typecase.code:
/**
 * Type case: a printer's cabinet of shallow drawers. The pointer picks a
 * drawer by its height: it slides out to show its grid of compartments for
 * the letters, and the drawers beside it ease out a little, staggered. At
 * rest one drawer stands half open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single stack (riffle).
 */
const {
  Cam, fit, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const N = 4, H = 15, D = 56, WY = 100, OUT = 58, FAV = 1, REST = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  const TOP = N * H + 6;
  fit(C, [[0, 0, 0], [D + OUT, WY, 0], [D + OUT, 0, 0], [0, WY, 0], [0, 0, TOP], [D + OUT, WY, TOP]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, -3, D, WY + 3, 4, 2);
  put(solid(g), prism(P, front, cr, ci, 0, TOP));
  const items = [];
  for (let k = 0; k < N; k++) {
    const zb = 3 + k * H, grp = mk("g", {}, g);
    const s = solid(grp), grid = mk("path", { class: "nf lo" }, grp), pull = mk("path", { class: "nf" }, grp);
    items.push({ k, zb, s, grid, pull, o: tween(k === FAV ? REST : 0), last: NaN });
  }
  function draw(it, off) {
    if (off === it.last) return;
    it.last = off;
    const z0 = it.zb + 1, z1 = it.zb + H - 1, xf = D + off;
    const [r, ri] = rings(D - 2, 3, xf + 2, WY - 3, 2, 1.5);
    put(it.s, prism(P, front, r, ri, z0, z1));
    let d = "";
    for (let gx = xf - 12; gx > D + 1; gx -= 13) d += seg(P(gx, 6, z1), P(gx, WY - 6, z1));
    for (let gy = 6 + 15; gy < WY - 6; gy += 15) if (xf - 2 > D + 1) d += seg(P(D + 1, gy, z1), P(xf - 2, gy, z1));
    it.grid.setAttribute("d", d || "M0 0");
    const m = (z0 + z1) / 2, hy = WY / 2;
    it.pull.setAttribute("d", poly([P(xf + 2, hy - 9, m - 2), P(xf + 2, hy + 9, m - 2), P(xf + 2, hy + 9, m + 2), P(xf + 2, hy - 9, m + 2)]));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);
  const mids = items.map((it) => P(D, WY / 2, it.zb + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < H * 1.75 && Math.abs(mids[best][0] - sx) < 110 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? REST : 0) : dd === 0 ? OUT : dd === 1 ? 10 : 0;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "case " + (N - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "typecase",
  means: "A printer's cabinet of type drawers: the drawer under the pointer slides out to show its letter compartments.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[199, 194], [199, 149], [199, 126], null],
  mount,
});

lightbox.code:
/**
 * Light table: a designer's tracing table, a cabinet with a glass top hinged
 * at its front edge, a sheet of tracing paper on the glass. The pointer's
 * place along the table sets how far the glass tilts up, a strut holding it.
 * At rest it leans a little, bright. The slider is the most it will tilt.
 *
 * The pattern: one part answering the pointer on a fixed plane.
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, unproj, clamp, lerp, rad, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, register, solid, put, facing,
} = HL;

const LX = 90, WY = 120, BZ = 34, TH = 3, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let most = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[0, 0, 0], [LX, WY, 0], [LX, 0, 0], [0, WY, 0], [10, 0, BZ + 74], [10, WY, BZ + 74]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, LX, WY, 5, 2.5);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const strut = mk("path", { class: "nf" }, g);
  const plate = mk("path", { class: "sil hi" }, g), face = mk("path", { class: "nf lo" }, g);
  const sheet = mk("path", { class: "nf" }, g), art = mk("path", { class: "nf lo" }, g);
  const a = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg), c = Math.cos(th), s = Math.sin(th);
    const W = (u, y, t) => P(LX - 2 - u * c + t * s, y, BZ + u * s + t * c);
    const pts = [];
    for (const u of [0, LX - 4]) for (const y of [2, WY - 2]) for (const t of [0, TH]) pts.push(W(u, y, t));
    plate.setAttribute("d", poly(hull(pts)));
    face.setAttribute("d", poly([W(0, 2, TH), W(LX - 4, 2, TH), W(LX - 4, WY - 2, TH), W(0, WY - 2, TH)]));
    sheet.setAttribute("d", poly([W(14, 22, TH), W(72, 18, TH), W(76, 92, TH), W(18, 96, TH)]));
    const ring = [];
    for (let i = 0; i < 24; i++) { const q = (i / 24) * 2 * Math.PI; ring.push(W(44 + 14 * Math.cos(q), 56 + 18 * Math.sin(q), TH)); }
    art.setAttribute("d", poly(ring) + seg(W(30, 40, TH), W(60, 76, TH)));
    const tip = W(LX - 6, WY / 2, 0);
    strut.setAttribute("d", seg(P(LX - 6 - (LX - 6) * 0.55, WY / 2, BZ), tip) + seg(P(LX - 6 - (LX - 6) * 0.55, WY / 2 - 6, BZ), P(LX - 6 - (LX - 6) * 0.55, WY / 2 + 6, BZ)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(a, now)); return !tdone(a, now); });
  bag.add(B.unregister);
  function aim(p) {
    const now = performance.now();
    let to = REST, lbl = "rest";
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      if (wx > -30 && wx < LX + 40 && wy > -20 && wy < WY + 20) { to = Math.round(lerp(4, 18 + 30 * most, clamp(wy / WY, 0, 1))); lbl = to + "°"; }
    }
    tset(a, to, now, 0);
    read.textContent = lbl;
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { most = v; }, destroy: bag.dispose };
}

hairline({
  name: "lightbox",
  means: "A light table with a tracing sheet on its glass: the pointer's place along the table tilts the glass top up toward you.",
  rules: [1, 3, 5, 6],
  range: [0, 0.7, 1],
  tour: [[138, 263], [200, 232], [262, 201], null],
  mount,
});

mooddboard.code:
/**
 * Pin board: a studio mood board standing on its feet, swatch cards pinned
 * across it, each card a colour chip over a label strip. The pointer picks
 * the card nearest it: the card swings on its pin and lifts off the board,
 * and the cards around it sway a little, staggered by distance. At rest the
 * cards hang at uneven leans and one is lifted, bright. The slider is the stagger.
 *
 * The pattern: one of many on a face plane (deposit boxes).
 */
const {
  Cam, fit, hull, poly, proj, rad, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const BY = 170, BZ0 = 16, BZ1 = 132, T = 5, CW = 30, CH = 38, FAV = 2;
const CARDS = [[28, 100, -5], [70, 108, 4], [113, 98, -3], [148, 106, 6], [44, 52, 3], [90, 46, -6], [134, 54, 2]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.55);
  fit(C, [[-14, 0, 0], [14, BY, 0], [0, 0, BZ1], [T + 14, BY, BZ1], [T + 14, 0, BZ0]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const corner = (x0, x1, y0, y1, z0, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push(P(x, y, z)); return o; };
  for (const fy of [16, BY - 16]) mk("path", { d: poly(hull(corner(-14, 14, fy - 3, fy + 3, 0, 3))) + seg(P(T / 2, fy, 3), P(T / 2, fy, BZ0)), class: "nf" }, g);
  mk("path", { d: poly(hull(corner(0, T, 0, BY, BZ0, BZ1))), class: "sil" }, g);
  mk("path", { d: poly([P(T, 4, BZ0 + 4), P(T, BY - 4, BZ0 + 4), P(T, BY - 4, BZ1 - 4), P(T, 4, BZ1 - 4)]), class: "nf lo" }, g);
  const items = CARDS.map(([y, z, lean], k) => {
    const grp = mk("g", {}, g);
    return { k, y, z, lean, card: mk("path", { class: "sil" }, grp), chip: mk("path", { class: "nf lo" }, grp), pin: mk("path", { class: "nf" }, grp),
      s: tween(k === FAV ? 1 : 0), last: NaN };
  }).sort((a, b) => a.y - b.y);
  items.forEach((it) => g.appendChild(it.card.parentNode));
  function draw(it, s) {
    if (s === it.last) return;
    it.last = s;
    const ang = rad(it.lean + s * (it.lean < 0 ? -24 : 24)), c = Math.cos(ang), sn = Math.sin(ang), x = T + 0.6 + s * 12;
    const W = (dy, dz) => P(x, it.y + dy * c - dz * sn, it.z + dy * sn + dz * c);
    it.card.setAttribute("d", poly([W(-CW / 2, 4), W(CW / 2, 4), W(CW / 2, 4 - CH), W(-CW / 2, 4 - CH)]));
    it.chip.setAttribute("d", poly([W(-CW / 2 + 4, -2), W(CW / 2 - 4, -2), W(CW / 2 - 4, -24), W(-CW / 2 + 4, -24)]) + seg(W(-CW / 2 + 4, -29), W(CW / 2 - 10, -29)));
    const ring = [];
    for (let i = 0; i < 12; i++) { const q = (i / 12) * 2 * Math.PI; ring.push(P(x + 0.4, it.y + 2.2 * Math.cos(q), it.z + 2.2 * Math.sin(q))); }
    it.pin.setAttribute("d", poly(ring));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.s, now)); if (!tdone(it.s, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);
  const mids = CARDS.map(([y, z]) => P(T, y, z - CH / 2 + 4));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.hypot(m[0] - sx, m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it) => {
      const d = a < 0 ? 0 : Math.hypot(it.y - CARDS[a][0], it.z - CARDS[a][1]);
      const s = a < 0 ? (it.k === FAV ? 1 : 0) : it.k === a ? 1 : d < 60 ? 0.3 : 0;
      const dd = from < 0 ? 0 : Math.hypot(it.y - CARDS[from][0], it.z - CARDS[from][1]) / 40;
      tset(it.s, s, now, dd * stag);
      it.card.classList.toggle("hi", it.k === (a < 0 ? FAV : a));
    });
    const top = items.find((it) => it.k === (a < 0 ? FAV : a));
    g.appendChild(top.card.parentNode);
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "mooddboard",
  means: "A studio pin board of swatch cards: the card nearest the pointer swings on its pin and lifts, its neighbours sway.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[250, 102], [182, 214], [118, 165], null],
  mount,
});

tillroll.code:
/**
 * Barcode scanner: a checkout counter with a scanner tower at its end, its
 * window facing the belt, and four packs of different sizes in a row, each
 * with a barcode on its near face. The pointer picks a pack by where it is
 * along the counter: that pack lifts high to be scanned, the others lift a
 * little after it, less the farther they stand. At rest one pack sits raised,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row, stepped heights; the hit is the
 * nearest rest centre along screen x.
 */
const {
  Cam, facing, fillet, fit, open, poly, prism, proj, rings, rrect, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 6, LIFT = 22, Y0 = 9, Y1 = 25;
const PK = [[4, 14, 16], [18, 29, 24], [33, 41, 12], [45, 56, 19]]; // x0, x1, height
const BAR = [0, 1, 1.6, 3, 3.6, 4.8, 6, 6.6];
const REST = [1, 6, 0, 2], FAV = 1, N = PK.length;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.15);
  fit(C, [[0, 0, 0], [84, 32, 0], [84, 0, 0], [0, 32, 0], [18, Y0, TOP + 24 + LIFT], [74, 4, 34]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the counter, with the belt's two seams on its top
  const counter = solid(g);
  put(counter, prism(P, front, ...rings(0, 0, 84, 32, 5, 1.2), 0, TOP));
  mk("path", { class: "nf lo", d: seg(P(2, Y0 - 2, TOP), P(60, Y0 - 2, TOP)) + seg(P(2, Y1 + 2, TOP), P(60, Y1 + 2, TOP)) }, counter.g);

  const packs = PK.map(([x0, x1, h], k) => {
    const s = solid(g);
    return { k, x0, x1, h, s, bars: mk("path", { class: "nf lo" }, s.g), z: tween(REST[k]), last: NaN };
  });

  // the scanner tower, nearest along x, so painted last; its window on its near face
  const tower = solid(g);
  put(tower, prism(P, front, ...rings(64, 4, 80, 26, 4, 1.2), TOP, 34));
  const win = [P(67, 26, 15), P(77, 26, 15), P(77, 26, 29), P(67, 26, 29)];
  mk("path", { class: "nf lo", d: poly(fillet(win, [1.5, 1.5, 1.5, 1.5], 3)) }, tower.g);

  function draw(p, lift) {
    if (lift === p.last) return;
    p.last = lift;
    const z0 = TOP + lift, z1 = z0 + p.h;
    put(p.s, prism(P, front, ...rings(p.x0, Y0, p.x1, Y1, 2, 0.9), z0, z1));
    // the barcode on the near (+y) face
    const w = p.x1 - p.x0 - 3, sc = w / 6.6;
    let d = "";
    BAR.forEach((b) => { const x = p.x0 + 1.5 + b * sc; d += seg(P(x, Y1, z0 + 2), P(x, Y1, z0 + 2 + Math.min(6, p.h * 0.4))); });
    p.bars.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    packs.forEach((p) => { draw(p, tval(p.z, now)); if (!tdone(p.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the pack whose rest centre is nearest the pointer along screen x, inside the counter's band
  const cx = packs.map((p) => P((p.x0 + p.x1) / 2, (Y0 + Y1) / 2, TOP + REST[p.k] + p.h / 2)[0]);
  const cy = packs.map((p) => P((p.x0 + p.x1) / 2, (Y0 + Y1) / 2, TOP + REST[p.k] + p.h / 2)[1]);
  function hit([sx, sy]) {
    let best = 0;
    cx.forEach((x, k) => { if (Math.abs(sx - x) < Math.abs(sx - cx[best])) best = k; });
    if (Math.abs(sx - cx[best]) > 30 || Math.abs(sy - cy[best]) > 50) return -1;
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    packs.forEach((p, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : Math.max(2, 10 - 4 * Math.abs(k - a));
      tset(p.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      p.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "item " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tillroll",
  means: "A checkout counter with a barcode scanner: the pack under the pointer lifts to be scanned, the others lift a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[124, 152], [157, 157], [217, 196], null],
  mount,
});

giftcards.code:
/**
 * Card rack: a low shop display tray with a row of gift cards standing in
 * it, each with a hang tab punched with a hole. The pointer picks a card by
 * where it is along the rack: that card rises out high, its neighbours rise
 * after it, less the farther they stand. At rest the cards sit unevenly, one
 * pulled up a little, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the cards' resting faces.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rrect, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 9, XS0 = 7, TOP = 8, Y0 = -2, Y1 = 34, SW = 1.6, VIS = 16, LIFT = 28;
const X1 = XS0 + (N - 1) * STEP + 7;
const REST = [2, 0, 7, 1, 3, 0], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.75);
  fit(C, [[0, Y0, 0], [X1, Y1, 0], [X1, Y0, 0], [0, Y1, 0], [XS0, 6, TOP + VIS + LIFT + 6], [X1, 28, TOP + VIS + LIFT + 6]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the tray: one rounded solid with its well along the top
  const tray = solid(g);
  put(tray, prism(P, front, rrect(0, Y0, X1, Y1, 6, 10), rrect(1, Y0 + 1, X1 - 1, Y1 - 1, 5, 10), 0, TOP));
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(3, 3, X1 - 3, 29, 3, 6), TOP)) }, tray.g);

  const cards = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    cards.push({ k, x: XS0 + k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }

  // a card: a rounded plate in the y–z plane with a hang tab on top, given a thickness along x
  function profile(x, h) {
    const zt = TOP + h, zb = zt - 6;
    const pts = [[5, TOP - 2], [27, TOP - 2], [27, zb], [21, zb], [19, zt], [13, zt], [11, zb], [5, zb]];
    return fillet(pts, [0, 0, 2, 1.5, 2, 2, 1.5, 2], 4).map(([y, z]) => [x, y, z]);
  }
  function hole(x, h) {
    const pts = [], zc = TOP + h - 2.6;
    for (let i = 0; i < 14; i++) { const a = (i / 14) * Math.PI * 2; pts.push(P(x, 16 + 1.6 * Math.cos(a), zc + 1.1 * Math.sin(a))); }
    return poly(pts);
  }
  function draw(s, lift) {
    if (lift === s.last) return;
    s.last = lift;
    const h = VIS + lift, near = profile(s.x + SW / 2, h), far = profile(s.x - SW / 2, h);
    s.sil.setAttribute("d", poly(hull(near.concat(far).map((p) => P(...p)))));
    s.cr.setAttribute("d", open(near.filter((p) => p[2] > TOP + 0.5).map((p) => P(...p))) + hole(s.x + SW / 2, h));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    cards.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the pointer on a fixed plane through the resting cards, nearest card along x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP + VIS * 0.6);
    if (x < -3 || x > X1 + 3 || y < Y0 - 4 || y > Y1 + 2) return -1;
    return clamp(Math.round((x - XS0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cards.forEach((s, k) => {
      const d = Math.abs(k - (a < 0 ? 0 : a));
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(LIFT * 0.6 - 5 * d, 3, LIFT);
      tset(s.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

