beecrates.code:
/**
 * Hive frames: a rack of honeycomb frames hanging by their lugs on two
 * rails, a stand under each end. The pointer picks a frame by where it is
 * along the rack: that frame lifts out high, its neighbours rise a little,
 * staggered from it. At rest the frames hang unevenly, one already half
 * drawn and bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), picked by rest centre.
 */
const {
  Cam, clamp, facing, fillet, fit, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 9, X0 = 6, ZB = 4, ZT = 32, HW = 12, LUG = 18, T = 2, LIFT = 24;
const X1 = X0 + (N - 1) * STEP + 6, REST = [1, 4, 0, 12, 2, 5], FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-4, -LUG - 3, 0], [X1 + 4, LUG + 3, 0], [X0, -LUG, ZT + 2 + LIFT], [X1, LUG, ZT + 2], [-4, LUG + 3, 0], [X1 + 4, -LUG - 3, ZT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the stand: a rail on each side, on two legs, the lugs resting on it
  function rail(parent, y) {
    for (const x of [0, X1 - 4]) { const [r, i] = rings(x, y - 1.5, x + 3, y + 1.5, 1.4, 0.5); put(solid(parent), prism(P, front, r, i, 0, ZT - 1)); }
    const [r, i] = rings(-4, y - 2, X1 + 4, y + 2, 1.6, 0.6);
    put(solid(parent), prism(P, front, r, i, ZT - 1, ZT + 1));
  }
  rail(mk("g", {}, g), -LUG + 2);
  const frames = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    frames.push({ k, x: X0 + k * STEP, far: mk("path", { class: "sil" }, grp), near: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), z: tween(REST[k]), last: NaN });
  }
  rail(mk("g", {}, g), LUG - 2);

  // a frame: a top bar with lugs over a comb panel, in the y–z plane
  const OUT = fillet([[-LUG, ZT + 2], [LUG, ZT + 2], [LUG, ZT], [HW, ZT], [HW, ZB], [-HW, ZB], [-HW, ZT], [-LUG, ZT]], [1, 1, 0.6, 0.6, 2, 2, 0.6, 0.6], 3);
  const HEX = [[-5, 20], [0, 17], [5, 20], [0, 23], [-5, 14], [5, 14], [0, 11]];
  function draw(f, lift) {
    if (lift === f.last) return;
    f.last = lift;
    const at = (x) => (p) => P(x, p[0], p[1] + lift);
    f.far.setAttribute("d", poly(OUT.map(at(f.x - T / 2))));
    f.near.setAttribute("d", poly(OUT.map(at(f.x + T / 2))));
    const xn = f.x + T / 2;
    let d = poly([[-HW + 2, ZB + 2], [HW - 2, ZB + 2], [HW - 2, ZT - 2], [-HW + 2, ZT - 2]].map(at(xn)));
    for (const [cy, cz] of HEX) {
      const h = [];
      for (let i = 0; i < 6; i++) { const a = (i / 6) * Math.PI * 2 + Math.PI / 6; h.push([cy + 2.6 * Math.cos(a), cz + 2.6 * Math.sin(a)]); }
      d += poly(h.map(at(xn)));
    }
    f.cr.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    frames.forEach((f) => { draw(f, tval(f.z, now)); if (!tdone(f.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the frame whose rest centre is nearest the pointer's screen x, inside the rack's band
  const centres = frames.map((f) => P(f.x, 0, (ZB + ZT) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = 1e9;
    centres.forEach((c, k) => { const dx = Math.abs(sx - c[0]); if (dx < bd) { bd = dx; best = k; } });
    const c = centres[best];
    return bd < STEP * 2.4 && Math.abs(sy - c[1]) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    frames.forEach((f, k) => {
      const z = a < 0 ? REST[k] : k === a ? LIFT : clamp(8 - 3 * Math.abs(k - a), 0, 8);
      tset(f.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      f.far.classList.toggle("hi", on);
      f.near.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "frame " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "beecrates",
  means: "A rack of honeycomb hive frames: the frame under the pointer lifts out high, its neighbours rise a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[151, 168], [190, 187], [249, 217], null],
  mount,
});

grainauger.code:
/**
 * Grain auger: a long tube on a wheeled strut, its intake hopper on the
 * ground and its spout over a round grain silo. The pointer on the ground
 * swings the auger about its foot to face it, on a spring, grain falling
 * from the spout wherever it points. At rest it leans over the silo's
 * roof, its tube bright. The slider is the tube's elevation.
 *
 * The pattern: a part turning to face the pointer (a rotated cylinder hull).
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, circ, seg, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const FX = 40, FY = -12, FZ = 4, LEN = 78, R = 3, SX = -2, SY = 30, SR = 16, SH = 34, ROOF = 46, SWING = 55;
const REST = Math.atan2(SY - FY, SX - FX) * 180 / Math.PI;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let elev = value;
  const C = Cam(45, 0.5, 2.5);
  const ends = [-SWING, 0, SWING].map((d) => [FX + Math.cos(rad(REST + d)) * LEN * 0.82, FY + Math.sin(rad(REST + d)) * LEN * 0.82, 56]);
  fit(C, [[SX - SR, SY - SR, 0], [SX + SR, SY + SR, ROOF], [FX + 8, FY + 8, 0], [FX - 6, FY - 6, 0]].concat(ends), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the silo: a round bin and its cone roof with a fill hole
  const sr = circ(SR, 32).map((s) => ({ ...s, u: s.u + SX, v: s.v + SY }));
  const si = circ(SR - 1.2, 32).map((s) => ({ ...s, u: s.u + SX, v: s.v + SY }));
  const silo = solid(g);
  put(silo, prism(P, front, sr, si, 0, SH));
  const roof = solid(g), hole = circ(3, 16).map((s) => ({ ...s, u: s.u + SX, v: s.v + SY }));
  roof.sil.setAttribute("d", poly(hull(ringAt(P, sr, SH).concat(ringAt(P, hole, ROOF)))));
  roof.cr.setAttribute("d", poly(ringAt(P, hole, ROOF)) + open(ringAt(P, sr.filter(front), SH + 0.8)));
  let bands = "";
  for (const z of [11, 22]) bands += open(ringAt(P, sr.filter(front), z));
  mk("path", { class: "nf lo", d: bands }, silo.g);

  const grain = [];
  for (let i = 0; i < 7; i++) grain.push(flatDot(g, C, 1.3, i % 2 ? "dot m" : "dot off"));
  const strut = mk("path", { class: "nf" }, g), wheels = solid(g);
  const hop = solid(g), [hr, hi] = rings(FX - 6, FY - 6, FX + 6, FY + 6, 6, 1);
  put(hop, prism(P, front, hr, hi, 0, 7));
  const tube = solid(g);
  tube.sil.classList.add("hi");

  let last = NaN, lastE = NaN;
  function draw(yawDeg) {
    if (yawDeg === last && elev === lastE) return;
    last = yawDeg; lastE = elev;
    const y = rad(yawDeg), e = rad(elev);
    const ax = [Math.cos(y) * Math.cos(e), Math.sin(y) * Math.cos(e), Math.sin(e)];
    const u = [-Math.sin(y), Math.cos(y), 0], v = [-Math.sin(e) * Math.cos(y), -Math.sin(e) * Math.sin(y), Math.cos(e)];
    const at = (t, a, b) => P(FX + ax[0] * t + u[0] * a + v[0] * b, FY + ax[1] * t + u[1] * a + v[1] * b, FZ + ax[2] * t + u[2] * a + v[2] * b);
    const ends = [];
    for (const t of [0, LEN]) for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; ends.push(at(t, R * Math.cos(a), R * Math.sin(a))); }
    tube.sil.setAttribute("d", poly(hull(ends)));
    let d = open([0, 0.25, 0.5, 0.75, 1].map((f) => at(LEN - 2, R * 0.8 * Math.cos(Math.PI * f), R * 0.8 * Math.sin(Math.PI * f))));
    for (let t = 8; t < LEN - 6; t += 7) d += seg(at(t, -R * 0.7, R * 0.7), at(t + 3, R * 0.7, R * 0.7));
    tube.cr.setAttribute("d", d);
    // the undercarriage: wheels under the tube's middle, a strut up to it
    const wt = LEN * 0.45 * Math.cos(e), wx = FX + Math.cos(y) * wt, wy = FY + Math.sin(y) * wt;
    const [wr, wi] = rings(wx - 3, wy - 3, wx + 3, wy + 3, 3, 0.8);
    put(wheels, prism(P, front, wr, wi, 0, 5));
    strut.setAttribute("d", seg(P(wx, wy, 5), at(LEN * 0.6, 0, -R)) + seg(P(wx, wy, 5), at(LEN * 0.3, 0, -R)));
    // the grain, falling from the spout to the ground
    const sx = FX + ax[0] * LEN, sy = FY + ax[1] * LEN, sz = FZ + ax[2] * LEN;
    grain.forEach((dot, i) => place(dot, P(sx + ((i * 5) % 3 - 1) * 1.2, sy + ((i * 3) % 3 - 1) * 1.2, sz - 4 - i * 1.6)));
  }

  const yaw = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(yaw.x); return m; });
  bag.add(B.unregister);

  function move([px, py]) {
    const [wx, wy] = unproj(C, px, py, 0);
    const dx = wx - FX, dy = wy - FY;
    if (Math.hypot(dx, dy) > 110) return leave();
    let a = Math.atan2(dy, dx) * 180 / Math.PI - REST;
    a = ((a + 540) % 360) - 180;
    yaw.t = REST + clamp(a, -SWING, SWING);
    read.textContent = (yaw.t - REST >= 0 ? "+" : "") + Math.round(yaw.t - REST) + "°";
    B.wake();
  }
  function leave() { yaw.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { elev = v; B.wake(); draw(yaw.x); }, destroy: bag.dispose };
}

hairline({
  name: "grainauger",
  means: "A grain auger beside a silo swings about its foot to face the pointer, grain falling from its spout where it points.",
  rules: [3, 5, 8, 9],
  range: [35, 45, 52],
  tour: [[206, 183], [117, 263], [312, 289], null],
  mount,
});

pallettruck.code:
/**
 * Pallet racking: a cantilever rack, three shelves on posts at the back,
 * three bays of loaded pallets on each shelf. The pointer picks a bay by
 * where it is along the rack: every pallet in that bay slides out to the
 * aisle, the other bays push back, staggered from it. At rest the loads sit
 * unevenly on the shelves, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; nearest rest centre by screen x.
 */
const {
  Cam, clamp, facing, fit, open, prism, proj, rings, ringAt, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BAYS = 3, BW = 22, D = 18, LV = [0, 22, 44], TH = 2.4, OUT = 20, W = BAYS * BW;
const H = [[12, 9, 14], [10, 15, 8], [13, 7, 11]];
const REST = [[1, 4, 0], [3, 0, 5], [0, 2, 1]];
const FAV = [1, 1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-2, -3, -TH], [W + 2, D + OUT, 0], [-2, -3, LV[2] + 20], [W + 2, D + OUT, LV[2] + 15], [-2, D + OUT, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the posts at the back, then each shelf with its pallets, bottom to top
  for (let b = 0; b <= BAYS; b++) {
    const [r, i] = rings(b * BW - 1.6, -3, b * BW + 1.6, 0, 0.8, 0.5);
    put(solid(g), prism(P, front, r, i, -TH, LV[2] + 20));
  }
  const pallets = [];
  LV.forEach((z, l) => {
    const [r, i] = rings(-2, -1, W + 2, D, 1.6, 0.8);
    put(solid(g), prism(P, front, r, i, z - TH, z));
    for (let b = 0; b < BAYS; b++) {
      const s = solid(g), board = mk("path", { class: "nf lo" }, s.g);
      pallets.push({ l, b, z, s, board, y: tween(REST[l][b]), last: NaN });
    }
  });

  function draw(p, y) {
    if (y === p.last) return;
    p.last = y;
    const [r, i] = rings(p.b * BW + 2, 1 + y, (p.b + 1) * BW - 2, D - 1 + y, 1.4, 0.8);
    put(p.s, prism(P, front, r, i, p.z, p.z + H[p.l][p.b]));
    p.board.setAttribute("d", open(ringAt(P, run(r, front), p.z + 2.2)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    pallets.forEach((p) => { draw(p, tval(p.y, now)); if (!tdone(p.y, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: inside the rack's box, the bay whose rest centre is nearest on screen x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, LV[1] + 6);
    if (x < -8 || x > W + 8 || y < -30 || y > D + OUT + 24) return -1;
    let best = -1, bd = 1e9;
    for (let b = 0; b < BAYS; b++) {
      const d = Math.abs(P((b + 0.5) * BW, D / 2, LV[1] + 6)[0] - sx);
      if (d < bd) { bd = d; best = b; }
    }
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    pallets.forEach((p) => {
      const y = a < 0 ? REST[p.l][p.b] : p.b === a ? OUT : 0;
      tset(p.y, y, now, from < 0 ? 0 : Math.abs(p.b - from) * stag + p.l * 40);
      p.s.sil.classList.toggle("hi", a < 0 ? p.l === FAV[0] && p.b === FAV[1] : p.b === a && p.l === 1);
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "pallettruck",
  means: "Pallet racking: every pallet in the bay under the pointer slides out to the aisle, the other bays push back after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[213, 147], [253, 167], [294, 187], null],
  mount,
});

strapping.code:
/**
 * Ratchet straps: a crate lashed to a flatbed with three straps, each with a
 * ratchet on the crate's near face. The pointer picks a strap by where it is
 * along the crate: that strap ratchets down tight against the crate, the
 * others throw slack, staggered from it. At rest the straps hang unevenly
 * slack, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; nearest rest centre by screen x.
 */
const {
  Cam, clamp, facing, fit, open, poly, prism, proj, rings, ringAt, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, seg,
} = HL;

const L = 60, D = 30, H = 26, SX = [12, 30, 48], SW = 4.5, MAX = 14, N = 24;
const REST = [7, 2, 11], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[-6, -6, -4], [L + 6, D + 6, -4], [-6, D + 6, -4], [L + 6, -6, -4], [0, D / 2, H + MAX], [L, D / 2, H + MAX], [L, D + MAX * 0.6, 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the flatbed, then the crate with its plank seams on the near faces
  let [r, i] = rings(-6, -6, L + 6, D + 6, 2, 1);
  put(solid(g), prism(P, front, r, i, -4, 0));
  [r, i] = rings(0, 0, L, D, 2.4, 1.2);
  const crate = solid(g);
  put(crate, prism(P, front, r, i, 0, H));
  mk("path", { class: "nf lo", d: open(ringAt(P, run(r, front), H / 3)) + open(ringAt(P, run(r, front), (2 * H) / 3)) }, crate.g);

  // a strap: over the top, down the near face, bulging out by its slack
  function path(x, s) {
    const pts = [];
    for (let k = 0; k <= N; k++) { const t = k / N; pts.push([x, t * D, H + s * Math.sin(Math.PI * t)]); }
    for (let k = 1; k <= N; k++) { const t = k / N; pts.push([x, D + s * 0.6 * Math.sin(Math.PI * t), H - t * (H - 1)]); }
    return pts;
  }
  const straps = SX.map((x) => {
    const grp = mk("g", {}, g);
    return { x, sil: mk("path", { class: "sil" }, grp), rat: solid(grp), s: tween(REST[SX.indexOf(x)]), last: NaN };
  });
  function draw(st, s) {
    if (s === st.last) return;
    st.last = s;
    const a = path(st.x - SW / 2, s).map((p) => P(...p)), b = path(st.x + SW / 2, s).map((p) => P(...p)).reverse();
    st.sil.setAttribute("d", poly(a.concat(b)));
    const yf = D + s * 0.6 * Math.sin(Math.PI * ((H - 12) / (H - 1)));
    const [rr, ri] = rings(st.x - 3.5, yf, st.x + 3.5, yf + 3, 1, 0.5);
    put(st.rat, prism(P, front, rr, ri, 8, 15));
    st.rat.cr.setAttribute("d", st.rat.cr.getAttribute("d") + seg(P(st.x, yf + 3, 15), P(st.x, yf + 3 + 3 + s * 0.4, 18 + s * 0.3)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    straps.forEach((st) => { draw(st, tval(st.s, now)); if (!tdone(st.s, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < -8 || x > L + 8 || y < -12 || y > D + 24) return -1;
    let best = -1, bd = 1e9;
    SX.forEach((xs, k) => { const d = Math.abs(P(xs, D / 2, H)[0] - sx); if (d < bd) { bd = d; best = k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    straps.forEach((st, k) => {
      tset(st.s, a < 0 ? REST[k] : k === a ? 0 : MAX, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      st.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "strap " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "strapping",
  means: "Ratchet straps over a crate: the strap under the pointer ratchets down tight, the others throw slack after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[164, 115], [200, 133], [236, 151], null],
  mount,
});

bubblewrap.code:
/**
 * Packing bench: a workbench on four legs with three cartons on it, each
 * with two top flaps. The pointer picks a carton by where it is along the
 * bench: its flaps fold shut, the other cartons throw their flaps wide,
 * staggered from it. At rest the flaps stand at uneven angles, one carton
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; nearest rest centre by screen x.
 */
const {
  Cam, clamp, facing, fillet, fit, poly, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, rad,
} = HL;

const W = 86, D = 34, TOP = 30, T = 3.5, ZB = TOP + T, OPEN = 165;
const BOX = [[4, 8, 24, 28, 14], [30, 6, 54, 28, 20], [60, 10, 80, 26, 12]];
const REST = [[12, 30], [22, 8], [35, 15]], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, 0, 0], [W, D, 0], [0, D, 0], [W, 0, 0], [4, 8, ZB + 34], [80, 26, ZB + 24], [30, 6, ZB + 46], [54, 28, ZB + 32]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the legs, back to front, then the bench top over them
  [[3, 3], [W - 7, 3], [3, D - 7], [W - 7, D - 7]].sort((a, b) => a[0] + a[1] - b[0] - b[1]).forEach(([x, y]) => {
    const [r, i] = rings(x, y, x + 4, y + 4, 1.2, 0.6);
    put(solid(g), prism(P, front, r, i, 0, TOP));
  });
  let [r, i] = rings(0, 0, W, D, 2.4, 1.1);
  put(solid(g), prism(P, front, r, i, TOP, ZB));

  // a carton, then its far flap (hinged at x0), then its near flap (hinged at x1)
  const boxes = BOX.map(([x0, y0, x1, y1, h], k) => {
    const s = solid(g);
    [r, i] = rings(x0, y0, x1, y1, 1.4, 0.8);
    const f0 = mk("path", { class: "" }, g), f1 = mk("path", { class: "" }, g);
    return { k, x0, y0, x1, y1, h, r, i, z: ZB + h, s, f: [f0, f1], a: [tween(REST[k][0]), tween(REST[k][1])], last: [NaN, NaN], lz: tween(0), lastz: NaN };
  });
  // a carton lifts off the bench when it is sealed
  function lift(b, z) {
    if (z === b.lastz) return;
    b.lastz = z;
    put(b.s, prism(P, front, b.r, b.i, ZB + z, ZB + b.h + z));
    b.z = ZB + b.h + z;
    b.last = [NaN, NaN];
  }

  function flap(b, side, deg) {
    if (deg === b.last[side]) return;
    b.last[side] = deg;
    const L = (b.x1 - b.x0) / 2 - 0.3, xh = side ? b.x1 : b.x0, dir = side ? -1 : 1;
    const xt = xh + dir * L * Math.cos(rad(deg)), zt = b.z + L * Math.sin(rad(deg));
    const pts = [P(xh, b.y0 + 0.5, b.z), P(xh, b.y1 - 0.5, b.z), P(xt, b.y1 - 0.5, zt), P(xt, b.y0 + 0.5, zt)];
    b.f[side].setAttribute("d", poly(fillet(pts, [0.5, 0.5, 1.5, 1.5], 3)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    boxes.forEach((b) => { lift(b, tval(b.lz, now)); if (!tdone(b.lz, now)) moving = true; });
    boxes.forEach((b) => [0, 1].forEach((sd) => { flap(b, sd, tval(b.a[sd], now)); if (!tdone(b.a[sd], now)) moving = true; }));
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, ZB + 14);
    if (x < -6 || x > W + 6 || y < -16 || y > D + 16) return -1;
    let best = -1, bd = 1e9;
    boxes.forEach((b) => { const d = Math.abs(P((b.x0 + b.x1) / 2, (b.y0 + b.y1) / 2, b.z)[0] - sx); if (d < bd) { bd = d; best = b.k; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    boxes.forEach((b) => {
      const d = from < 0 ? 0 : Math.abs(b.k - from) * stag;
      tset(b.lz, b.k === a ? 12 : 0, now, d + 180);
      [0, 1].forEach((sd) => tset(b.a[sd], a < 0 ? REST[b.k][sd] : b.k === a ? 0 : OPEN, now, d + sd * 90));
      b.s.sil.classList.toggle("hi", b.k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "bubblewrap",
  means: "A packing bench: the carton under the pointer folds its flaps shut, the other cartons throw theirs wide after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[149, 112], [198, 114], [244, 164], null],
  mount,
});

visa.code:
/**
 * Travel adapter: a rounded adapter body with a socket on its near face and
 * three plug heads along its top, each carrying its own pin pattern (two
 * flat blades, two round pins, three bars). The pointer picks a head by where
 * it is along the adapter: that head slides out tall with its pins, the
 * others sink back, staggered from it. At rest one head stands half out,
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle); the hit is each head's
 * rest centre, nearest along screen x.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, poly, ringAt, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 18, GAP = 3, X1 = N * (W + GAP) + GAP, Y1 = 34, BZ = 18, MH = 8, LIFT = 30;
const REST = [3, 12, 1], FAV = 1;
const PINS = [
  { h: 10, p: [[-5, -3.5, -3.4, 3.5], [3.4, -3.5, 5, 3.5]] },
  { h: 11, p: [[-6, -1.6, -2.8, 1.6], [2.8, -1.6, 6, 1.6]] },
  { h: 9, p: [[-6, 2, -2.4, 4], [2.4, 2, 6, 4], [-1, -6, 1, -1.8]] },
];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [GAP + W / 2, 17, BZ + MH + LIFT + 11]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [ring, inner] = rings(0, 0, X1, Y1, 7, 1.4);
  const body = solid(g);
  put(body, prism(P, front, ring, inner, 0, BZ));
  // the socket on the near face: a rounded rim and two slots
  const sx = X1 * 0.55, rim = [];
  for (let i = 0; i < 24; i++) { const a = (i / 24) * Math.PI * 2; rim.push(P(sx + 6 * Math.cos(a), Y1, 9 + 5.5 * Math.sin(a))); }
  mk("path", { class: "nf lo", d: poly(rim) + seg(P(sx - 2.5, Y1, 7.5), P(sx - 2.5, Y1, 10.5)) + seg(P(sx + 2.5, Y1, 7.5), P(sx + 2.5, Y1, 10.5)) }, body.g);

  const heads = [];
  for (let k = 0; k < N; k++) {
    const cx = GAP + k * (W + GAP) + W / 2, grp = mk("g", {}, g);
    const head = solid(grp), pins = PINS[k].p.map(() => solid(grp));
    heads.push({ k, cx, head, pins, z: tween(REST[k]), last: NaN });
  }
  function draw(s, h) {
    if (h === s.last) return;
    s.last = h;
    const z1 = BZ + MH + h, [r, i] = rings(s.cx - W / 2, 5, s.cx + W / 2, 29, 4, 1.2);
    put(s.head, prism(P, front, r, i, BZ, z1));
    PINS[s.k].p.forEach(([a, b, c, d], j) => {
      const [pr, pi] = rings(s.cx + a, 17 + b, s.cx + c, 17 + d, 0.8, 0.4);
      put(s.pins[j], prism(P, front, pr, pi, z1, z1 + PINS[s.k].h));
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    heads.forEach((s) => { draw(s, tval(s.z, now)); if (!tdone(s.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest head by its rest centre's screen x, inside the adapter's band
  const cxs = heads.map((s) => P(s.cx, 17, BZ + MH)[0]);
  const box = [P(0, Y1, 0)[0] - 6, P(X1, 0, 0)[0] + 6, P(0, 0, BZ + MH + LIFT + 12)[1], P(X1, Y1, 0)[1] + 6];
  function hit([sx, sy]) {
    if (sx < box[0] || sx > box[1] || sy < box[2] || sy > box[3]) return -1;
    let best = 0;
    cxs.forEach((c, k) => { if (Math.abs(c - sx) < Math.abs(cxs[best] - sx)) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    heads.forEach((s, k) => {
      tset(s.z, a < 0 ? REST[k] : k === a ? LIFT : 0, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      s.head.sil.classList.toggle("hi", on);
      s.pins.forEach((p) => p.sil.classList.toggle("hi", on));
    });
    read.textContent = a < 0 ? "rest" : ["type A", "type C", "type G"][a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "visa",
  means: "A travel adapter with three plug heads: the head under the pointer slides out tall with its pins, the others sink back.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[157, 148], [200, 170], [243, 192], null],
  mount,
});

neckpillow.code:
/**
 * Seat row: a gate's row of four seats on one long beam, two feet under it,
 * each seat a tall back and a pan hinged at its foot. Empty pans stand folded
 * up against their backs. The pointer picks a seat by where it is along the
 * row: its pan folds down flat, the others fold up, staggered from it. At rest
 * one pan is down, bright, and the rest stand at uneven angles.
 *
 * The pattern: one of many in a single row (riffle); the hit is each seat's
 * rest centre, nearest along screen x.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 14, GAP = 2.5, X1 = N * (W + GAP) - GAP, YB = 0, PZ = 17, D = 15, T = 2.2;
const REST = [86, 0, 72, 90], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.35);
  fit(C, [[-3, -2, 0], [X1 + 3, D + 6, 0], [X1 + 3, -2, 0], [-3, D + 6, 0], [0, YB, 44], [X1, YB, 44]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // two feet and the beam
  [[2, 10], [X1 - 10, X1 - 2]].forEach(([a, b]) => {
    const [r, i] = rings(a, 1, b, 13, 2.5, 0.8);
    put(solid(g), prism(P, front, r, i, 0, 2));
    const [r2, i2] = rings((a + b) / 2 - 1.5, 5, (a + b) / 2 + 1.5, 8, 1.4, 0.5);
    put(solid(g), prism(P, front, r2, i2, 2, 12));
  });
  const [br, bi] = rings(-2, 3, X1 + 2, 10, 3, 0.9);
  put(solid(g), prism(P, front, br, bi, 12, 15.5));

  const seats = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (W + GAP), grp = mk("g", {}, g);
    const back = solid(grp), [r, i] = rings(x0, YB, x0 + W, YB + 2.6, 1.2, 0.5);
    put(back, prism(P, front, r, i, PZ, 44));
    seats.push({ k, x0, back, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), a: tween(REST[k]), last: NaN });
  }
  // a pan: a rounded slab in the y–z plane, turned about its hinge by angle a, given its width along x
  function pan(x, a) {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a)), hy = YB + 3.4, hz = PZ;
    const pts = [[0, 0], [D, 0], [D, T], [0, T]].map(([u, v]) => [hy + u * c - v * s, hz + u * s + v * c]);
    return fillet(pts, [1, 1, 1, 1], 3).map(([y, z]) => [x, y, z]);
  }
  function draw(s, a) {
    if (a === s.last) return;
    s.last = a;
    const near = pan(s.x0 + W - 0.6, a), far = pan(s.x0 + 0.6, a);
    s.sil.setAttribute("d", poly(hull(near.concat(far).map((p) => P(...p)))));
    s.cr.setAttribute("d", open(near.map((p) => P(...p))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    seats.forEach((s) => { draw(s, tval(s.a, now)); if (!tdone(s.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: nearest seat by its rest centre's screen x, inside the row's band
  const cxs = seats.map((s) => P(s.x0 + W / 2, YB + 8, PZ)[0]);
  const box = [P(0, D + 6, 0)[0] - 6, P(X1, 0, 0)[0] + 6, P(0, 0, 46)[1], P(X1, D + 6, 0)[1] + 6];
  function hit([sx, sy]) {
    if (sx < box[0] || sx > box[1] || sy < box[2] || sy > box[3]) return -1;
    let best = 0;
    cxs.forEach((c, k) => { if (Math.abs(c - sx) < Math.abs(cxs[best] - sx)) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    seats.forEach((s, k) => {
      tset(s.a, a < 0 ? REST[k] : k === a ? 0 : 90, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      s.sil.classList.toggle("hi", on);
      s.back.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "seat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "neckpillow",
  means: "A gate's row of four seats on a beam: the seat under the pointer folds its pan down, the others fold up after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[140, 149], [197, 177], [256, 207], null],
  mount,
});

departures.code:
/**
 * Flip board: a departures board hung on two rods, three rows of four
 * split-flap cells, each cell a recess with a hinge across its middle and one
 * flap that turns over it, top half to bottom half. The pointer picks a cell:
 * its row turns its flaps over, the rest close up, staggered out from the
 * cell. At rest the board is mid-change, one flap standing out flat, bright.
 *
 * The pattern: a field of parts (pianokeys); the hit is each cell's rest
 * centre on the fixed board face, nearest in screen space.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const M = 4, R = 3, CW = 12, CG = 2.5, RH = 11, RG = 3, MX = 4, MZ = 4;
const BW = MX * 2 + M * CW + (M - 1) * CG, BH = MZ * 2 + R * RH + (R - 1) * RG, Z0 = 10, HY = 1.3, T = 0.8;
const REST = [0, 180, 0, 0, 180, 92, 0, 180, 0, 0, 180, 0], FAV = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.25);
  fit(C, [[0, -4, Z0], [BW, -4, Z0], [0, 7, Z0], [BW, 7, Z0], [0, -4, Z0 + BH + 12], [BW, -4, Z0 + BH + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // two hanging rods, then the board, then the cell recesses on its face
  [8, BW - 8].forEach((x) => {
    const [r, i] = rings(x - 1, -3, x + 1, -1, 1, 0.4);
    put(solid(g), prism(P, front, r, i, Z0 + BH, Z0 + BH + 12));
  });
  const [br, bi] = rings(0, -4, BW, 0, 1.6, 0.7);
  const board = solid(g);
  put(board, prism(P, front, br, bi, Z0, Z0 + BH));
  const cells = [];
  let recess = "";
  for (let r = 0; r < R; r++) for (let c = 0; c < M; c++) {
    const x0 = MX + c * (CW + CG), zb = Z0 + MZ + r * (RH + RG), zc = zb + RH / 2;
    const out = fillet([[x0, zb], [x0 + CW, zb], [x0 + CW, zb + RH], [x0, zb + RH]], [1.2, 1.2, 1.2, 1.2], 3);
    recess += poly(out.map(([x, z]) => P(x, 0, z))) + seg(P(x0 + 0.6, 0, zc), P(x0 + CW - 0.6, 0, zc));
    cells.push({ i: r * M + c, r, c, x0, zc });
  }
  mk("path", { class: "nf lo", d: recess }, board.g);
  // flaps paint bottom row first, so a flap turned out toward us covers the row below it
  cells.forEach((s) => {
    const grp = mk("g", {}, g);
    Object.assign(s, { sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), a: tween(REST[s.i]), last: NaN });
  });
  function flap(x, zc, a) {
    const dy = Math.sin(rad(a)), dz = Math.cos(rad(a)), L = RH / 2 - 0.4;
    const pts = [[0, 0], [L, 0], [L, T], [0, T]].map(([u, v]) => [HY + u * dy + v * dz, zc + u * dz - v * dy]);
    return fillet(pts, [0.3, 0.8, 0.8, 0.3], 3).map(([y, z]) => [x, y, z]);
  }
  function draw(s, a) {
    if (a === s.last) return;
    s.last = a;
    const near = flap(s.x0 + CW - 0.5, s.zc, a), far = flap(s.x0 + 0.5, s.zc, a);
    s.sil.setAttribute("d", poly(hull(near.concat(far).map((p) => P(...p)))));
    s.cr.setAttribute("d", open(far.map((p) => P(...p))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    cells.forEach((s) => { draw(s, tval(s.a, now)); if (!tdone(s.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the nearest cell by its rest centre on the board face, which never moves
  const ctr = cells.map((s) => P(s.x0 + CW / 2, 0, s.zc));
  const lim = Math.hypot(ctr[1][0] - ctr[0][0], ctr[1][1] - ctr[0][1]) * 0.9;
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    ctr.forEach(([cx, cy], k) => { const d = Math.hypot(cx - sx, cy - sy); if (d < bd) { bd = d; best = k; } });
    return bd < lim ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? cells[a] : act >= 0 ? cells[act] : null;
    act = a;
    cells.forEach((s) => {
      const to = a < 0 ? REST[s.i] : s.r === cells[a].r ? 180 : 0;
      tset(s.a, to, now, from ? (Math.abs(s.c - from.c) + Math.abs(s.r - from.r)) * stag : 0);
      s.sil.classList.toggle("hi", s.i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "row " + (cells[a].r + 1) + "·" + (cells[a].c + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "departures",
  means: "A split-flap departures board: the row under the pointer turns its flaps over, the rest close, rippling out from the cell.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[153, 132], [202, 193], [250, 254], null],
  mount,
});

carryon.code:
/**
 * Cabin bag sizer: the gate's open frame, a tray with a back and a side wall
 * and two posts carrying the top rails, and a cabin suitcase above it. The
 * pointer over the sizer lowers the bag right in, under the rails, and then
 * its handle runs up. At rest the bag stands half in, bright, handle down.
 * The slider is the handle's wait behind the bag.
 *
 * The pattern: one part, two poses (cloches); the hit is the sizer's fixed
 * screen box, which never moves.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 26, Y1 = 16, ZT = 40, BH = 34, UP = 20, IN = 2.5, HUP = 16, HDN = 1.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wait = value;
  const C = Cam(45, 0.5, 4.1);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [4, 4, UP + BH + 2], [20, 10, UP + BH + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b, parent) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent || g); put(s, prism(P, front, o, i, z0, z1)); return s; };

  // the far half of the sizer: tray, back wall, side wall
  box(-1, -1, X1 + 1, Y1 + 1, 0, 2.2, 2.5, 1);
  box(-1, -1, X1 + 1, 0.6, 2.2, ZT, 1.2, 0.5);
  box(-1, 0.6, 0.6, Y1 + 1, 2.2, ZT, 0.8, 0.4);

  // the bag: body, zip line on its near face, handle rods and grip
  const bg = mk("g", {}, g), body = solid(bg), zip = mk("path", { class: "nf lo" }, bg);
  const rods = [solid(bg), solid(bg)], grip = solid(bg);
  const bz = tween(UP), hz = tween(HDN);
  let last = "";
  function draw(z, h) {
    const key = z.toFixed(2) + h.toFixed(2);
    if (key === last) return;
    last = key;
    const [o, i] = rings(2, 2, X1 - 2, Y1 - 2, 4, 1.2), top = z + BH;
    put(body, prism(P, front, o, i, z, top));
    zip.setAttribute("d", seg(P(5, Y1 - 2, z + 4), P(5, Y1 - 2, top - 4)) + seg(P(5, Y1 - 2, top - 4), P(X1 - 5, Y1 - 2, top - 4)));
    [9, X1 - 9].forEach((x, k) => {
      const [ro, ri] = rings(x - 0.7, 7.3, x + 0.7, 8.7, 0.7, 0.3);
      put(rods[k], prism(P, front, ro, ri, top, top + h));
    });
    const [go, gi] = rings(8, 6.8, X1 - 8, 9.2, 1.2, 0.4);
    put(grip, prism(P, front, go, gi, top + h, top + h + 1.8));
  }

  // the near half: posts and top rails, painted over the bag
  box(X1 - 0.6, -1, X1 + 1, 0.6, 2.2, ZT, 0.8, 0.3);
  box(-1, Y1 - 0.6, 0.6, Y1 + 1, 2.2, ZT, 0.8, 0.3);
  box(X1 - 0.6, -1, X1 + 1, Y1 + 1, ZT - 1.6, ZT, 0.8, 0.3);
  box(-1, Y1 - 0.6, X1 + 1, Y1 + 1, ZT - 1.6, ZT, 0.8, 0.3);
  box(X1 - 0.6, Y1 - 0.6, X1 + 1, Y1 + 1, 2.2, ZT, 0.8, 0.3);

  const B = register(stage, (_dt, now) => {
    draw(tval(bz, now), tval(hz, now));
    return !tdone(bz, now) || !tdone(hz, now);
  });
  bag.add(B.unregister);

  // the hit: the sizer's own screen box at rest; nothing in it moves
  const pts = [[-1, -1, 0], [X1 + 1, Y1 + 1, 0], [X1 + 1, -1, 0], [-1, Y1 + 1, 0], [-1, -1, ZT], [X1 + 1, Y1 + 1, ZT], [X1 + 1, -1, ZT], [-1, Y1 + 1, ZT]].map((p) => P(...p));
  const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
  const hb = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  const hit = ([sx, sy]) => sx > hb[0] && sx < hb[1] && sy > hb[2] && sy < hb[3];

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now();
    tset(bz, a ? IN : UP, now, a ? 0 : wait);
    tset(hz, a ? HUP : HDN, now, a ? wait : 0);
    body.sil.classList.toggle("hi", true);
    read.textContent = a ? "fits" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wait = clamp(v, 0, 400); }, destroy: bag.dispose };
}

hairline({
  name: "carryon",
  means: "A cabin bag sizer at the gate: over the frame the suitcase lowers right in under the rails, then its handle runs up.",
  rules: [1, 3, 5, 6],
  range: [0, 200, 400],
  tour: [[200, 189], [214, 155], [186, 94], null],
  mount,
});

billboard2.code:
/**
 * Pop-up banner: a roll-up stand, the banner pulled out of its cassette and
 * held by a pole. The pointer's height sets how far the banner stands out of
 * the cassette, on a spring. At rest it stands most of the way up, its top
 * rail bright. The slider is the banner's width.
 *
 * The pattern: one continuous value, read from where the pointer is.
 */
const {
  Cam, clamp, fillet, fit, facing, hull, open, poly, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HB = 9, HMAX = 150, REST = 0.78, TH = 0.8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let half = value;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-58, -10, 0], [58, 10, 0], [58, -10, 0], [-58, 10, 0], [-48, 0, HB + HMAX + 4], [48, 0, HB + HMAX + 4]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const pole = mk("path", { class: "nf lo" }, g);
  const ban = solid(g), lines = mk("path", { class: "nf lo" }, g), rail = solid(g);
  const cas = solid(g);
  rail.sil.classList.add("hi");
  const h = spring(REST);
  let last = NaN, lastHalf = NaN;

  function draw() {
    if (h.x === last && half === lastHalf) return;
    last = h.x; lastHalf = half;
    const W = half, top = HB + 6 + (HMAX - 6) * clamp(h.x, 0.04, 1);
    const [cr, ci] = rings(-W - 6, -7, W + 6, 7, 4, 1.4);
    put(cas, prism(P, front, cr, ci, 0, HB));
    pole.setAttribute("d", open([P(0, -3, HB), P(0, -3, top)]));
    const face = (y) => fillet([P(-W, y, HB), P(W, y, HB), P(W, y, top), P(-W, y, top)], [0.5, 0.5, 1, 1], 3);
    const f = face(TH);
    put(ban, { sil: poly(hull(face(-TH).concat(f))), crease: open([f[f.length - 1]].concat(f.slice(0, 1))) });
    const d = [];
    for (const t of [0.82, 0.74, 0.3, 0.22]) { const z = HB + (top - HB) * t, w = t > 0.5 ? W * 0.7 : W * 0.45; d.push(open([P(-w, TH, z), P(w, TH, z)])); }
    lines.setAttribute("d", d.join(" "));
    const [rr, ri] = rings(-W - 2, -2.4, W + 2, 2.4, 2, 0.8);
    put(rail, prism(P, front, rr, ri, top, top + 3.5));
  }

  const loop = register(stage, (dt) => { const m = stepS(h, dt); draw(); return m; });
  bag.add(loop.unregister);

  const yBase = P(0, 0, HB)[1], yTop = P(0, 0, HB + HMAX)[1];
  function aim(p) {
    if (!p) { h.t = REST; read.textContent = "rest"; }
    else { h.t = clamp((yBase - p[1]) / (yBase - yTop), 0.04, 1); read.textContent = Math.round(h.t * 100) + "%"; }
    loop.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { half = v; last = NaN; loop.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "billboard2",
  means: "A roll-up banner stand: the pointer's height sets how far the banner stands out of its cassette, on a spring.",
  rules: [1, 3, 5, 8],
  range: [30, 40, 46],
  tour: [[200, 145], [200, 249], [200, 42], null],
  mount,
});

signspinner.code:
/**
 * Arrow sign: a signpost with two arrow boards. The upper board swings on
 * the post to point at where the pointer stands on the ground, and the lower
 * board follows half way. At rest the boards point apart, the upper one
 * bright. The slider is how far the lower board follows.
 *
 * The pattern: a part turning to face the pointer (spring on an angle).
 */
const {
  Cam, circ, fit, facing, fillet, hull, open, poly, prism, proj, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PH = 112, BL = 46, BT = 30, BH = 22, HD = 16, TH = 1.8;
const BOARDS = [{ z: 58, rest: 110, hi: false }, { z: 86, rest: -20, hi: true }];
const disc = (r, n = 20) => circ(r, n);
const ARROW = fillet([[-BT, 0], [BL - HD, 0], [BL, BH / 2], [BL - HD, BH], [-BT, BH]], [1.5, 1, 1.5, 1, 1.5], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let follow = value / 100;
  const C = Cam(45, 0.5, 2.0);
  const ext = [];
  for (let a = 0; a < 360; a += 30) { const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180); ext.push([BL * c, BL * s, 58], [BL * c, BL * s, 86 + BH]); }
  fit(C, ext.concat([[0, 0, PH + 2], [-14, -14, 0], [14, 14, 0]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(14, 32), disc(12, 32), 0, 4));
  put(solid(g), prism(P, front, disc(3.2), disc(2.2), 4, PH));
  put(solid(g), prism(P, front, disc(4.4), disc(3.4), PH, PH + 3));

  const boards = BOARDS.map((b) => ({ ...b, s: solid(g), a: spring(b.rest), last: NaN }));
  boards.forEach((b) => b.s.sil.classList.toggle("hi", b.hi));

  function draw(b) {
    const ang = b.a.x;
    if (ang === b.last) return;
    b.last = ang;
    const r = ang * Math.PI / 180, c = Math.cos(r), s = Math.sin(r), nx = -s * TH / 2, ny = c * TH / 2;
    const face = (k) => ARROW.map(([u, v]) => P(u * c + k * nx, u * s + k * ny, b.z + v));
    const A = face(1), Bf = face(-1);
    const near = (A[0][1] + A[1][1]) > (Bf[0][1] + Bf[1][1]) ? A : Bf;
    put(b.s, { sil: poly(hull(A.concat(Bf))), crease: open(near.concat([near[0]])) });
  }

  const loop = register(stage, (dt) => {
    let moving = false;
    for (const b of boards) { if (stepS(b.a, dt)) moving = true; draw(b); }
    return moving;
  });
  bag.add(loop.unregister);

  const near = (from, to) => from + ((((to - from) % 360) + 540) % 360) - 180;
  const NAMES = ["E", "SE", "S", "SW", "W", "NW", "N", "NE"];
  function aim(p) {
    if (!p) {
      boards.forEach((b) => { b.a.t = near(b.a.t, b.rest); });
      read.textContent = "rest";
    } else {
      const [x, y] = unproj(C, p[0], p[1], 0), deg = Math.atan2(y, x) * 180 / Math.PI;
      const up = boards[1], lo = boards[0];
      up.a.t = near(up.a.t, deg);
      lo.a.t = near(lo.a.t, lo.rest + follow * (((deg - lo.rest + 540) % 360) - 180));
      read.textContent = NAMES[((Math.round(deg / 45) % 8) + 8) % 8];
    }
    loop.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { follow = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "signspinner",
  means: "A signpost with two arrow boards: the upper board swings to point where the pointer stands, the lower follows half way.",
  rules: [1, 3, 5, 8],
  range: [0, 50, 100],
  tour: [[59, 272], [200, 300], [341, 272], null],
  mount,
});

flagbanner.code:
/**
 * Bunting: a string of pennants slung between two posts. The pointer picks a
 * pennant by where it stands: it swings out on the string toward the viewer,
 * and the pennants beside it swing a little, staggered from it. At rest the
 * pennants hang at uneven angles, one bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, fillet, poly, open, prism, proj, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, L = 210, H = 84, SAG = 16, W = 22, D = 34, FAV = 3;
const REST = [14, 26, 8, 30, 12, 24, 6];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const sz = (x) => { const t = x / L; return H - SAG * 4 * t * (1 - t); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[-10, -10, 0], [L + 10, 10, 0], [L / 2, D, H - SAG - 10], [0, 0, H + 6], [L, 0, H + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  function post(x) {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, 0, 9), disc(x, 0, 7), 0, 3));
    put(solid(grp), prism(P, front, disc(x, 0, 2.6, 16), disc(x, 0, 1.6, 16), 3, H + 4));
    return grp;
  }
  post(0);
  const sp = [];
  for (let i = 0; i <= 40; i++) { const x = (i / 40) * L; sp.push(P(x, 0, sz(x))); }
  mk("path", { d: open(sp), class: "nf" }, g);

  const gap = (L - N * W) / (N + 1), items = [];
  for (let k = 0; k < N; k++) {
    const xa = gap + k * (W + gap), xb = xa + W, path = mk("path", { class: "sil" }, g);
    items.push({ k, xa, xb, path, th: tween(REST[k]), last: NaN, mid: P((xa + xb) / 2, 0, sz(xa + W / 2) - D / 2)[0] });
  }
  post(L);

  function draw(it, th) {
    if (th === it.last) return;
    it.last = th;
    const a = rad(th), xm = (it.xa + it.xb) / 2, zm = (sz(it.xa) + sz(it.xb)) / 2;
    const pts = [P(it.xa, 0, sz(it.xa)), P(it.xb, 0, sz(it.xb)), P(xm, D * Math.sin(a), zm - D * Math.cos(a))];
    it.path.setAttribute("d", poly(fillet(pts, [1.2, 1.2, 1.6])));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.th, now)); if (!tdone(it.th, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const top = P(L / 2, 0, H)[1];
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const dd = Math.abs(it.mid - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && sy > top - 60 && sy < top + 120 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), th = a < 0 ? REST[k] : dd === 0 ? 78 : dd === 1 ? 46 : dd === 2 ? 30 : REST[k];
      tset(it.th, th, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.path.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "flag " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "flagbanner",
  means: "A string of pennants between two posts: the pennant under the pointer swings out on the string, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[110, 83], [200, 141], [290, 173], null],
  mount,
});

tapestand.code:
/**
 * Guitar stand: three guitars resting on a rack, their necks leaned back on a
 * padded rail. The guitar under the pointer stands up off the rail and turns
 * to face the reader; its neighbours swing a little out of its way, the
 * motion spreading from it. At rest they lean at slightly different angles,
 * the middle one bright.
 *
 * The pattern: a discrete choice (a tween per guitar, staggered by distance);
 * the hit is each guitar's rest centre on screen, which never moves.
 */
const {
  Cam, facing, fit, fillet, poly, prism, proj, rings, seg, tween, tset, tval, tdone, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, GAP = 34, LEAN = [17, 21, 15], TURN = [-8, 4, 12], FAV = 1, YB = 6, RAIL = -24;
const half = (w) => {
  if (w < 43) { const a = 169 - (w - 13) ** 2, b = 100 - (w - 33) ** 2; return Math.max(Math.sqrt(Math.max(a, 0)), Math.sqrt(Math.max(b, 0)), 0.8); }
  return w < 80 ? 1.7 : 3.2;
};
const PROF = (() => {
  const ws = [];
  for (let w = 0; w <= 43; w += 1.5) ws.push(w);
  ws.push(43.01, 80, 80.01, 90);
  const r = ws.map((w) => [half(w), w]), l = ws.slice().reverse().map((w) => [-half(w), w]);
  return r.concat(l);
})();

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  const ext = [[-20, YB + 16, 0], [GAP * (N - 1) + 20, YB + 16, 0], [-20, RAIL - 4, 0], [GAP * (N - 1) + 20, RAIL - 4, 92], [-14, YB, 94], [GAP * (N - 1) + 14, YB, 94]];
  fit(C, ext, 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const X1 = GAP * (N - 1);
  // the rack: two uprights, the back rail, the base bar the guitars stand in
  for (const x of [-16, X1 + 16]) put(solid(g), prism(P, front, rings(x - 2, RAIL - 2, x + 2, RAIL + 2, 1, 0.6)[0], null, 0, 72));
  put(solid(g), prism(P, front, rings(-18, RAIL - 3, X1 + 18, RAIL + 3, 2.5, 1)[0], rings(-18, RAIL - 3, X1 + 18, RAIL + 3, 2.5, 1)[1], 70, 75));
  for (const x of [-16, X1 + 16]) put(solid(g), prism(P, front, rings(x - 3, RAIL - 2, x + 3, YB + 12, 1.5, 0.8)[0], null, 0, 2.5));
  const [br, bi] = rings(-18, YB - 6, X1 + 18, YB + 8, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, 2.5, 7));

  const gs = [];
  for (let i = 0; i < N; i++) {
    const grp = mk("g", {}, g);
    gs.push({ i, x: i * GAP, back: mk("path", { class: "lo", d: "" }, grp), body: solid(grp), hole: mk("path", { class: "lo nf", d: "" }, grp), str: mk("path", { class: "lo nf", d: "" }, grp), th: tween(rad(LEAN[i])), tp: tween(rad(TURN[i])), drawn: "" });
  }
  function draw(gt, now) {
    const th = tval(gt.th, now), ph = tval(gt.tp, now), key = th.toFixed(4) + ph.toFixed(4);
    if (key === gt.drawn) return;
    gt.drawn = key;
    const U = [Math.cos(ph), Math.sin(ph), 0], n = [-Math.sin(ph), Math.cos(ph), 0];
    const Wd = [-n[0] * Math.sin(th), -n[1] * Math.sin(th), Math.cos(th)];
    const at = (u, w, o) => P(gt.x + U[0] * u + Wd[0] * w + n[0] * o, YB + U[1] * u + Wd[1] * w + n[1] * o, 5 + Wd[2] * w);
    const sm = (pts) => poly(fillet(pts, pts.map(() => 0.7), 2));
    gt.back.setAttribute("d", sm(PROF.map(([u, w]) => at(u, w, -2.2))));
    gt.body.sil.setAttribute("d", sm(PROF.map(([u, w]) => at(u, w, 2.2))));
    const hole = [];
    for (let k = 0; k < 20; k++) { const a = (k / 20) * Math.PI * 2; hole.push(at(4.2 * Math.cos(a), 26 + 4.2 * Math.sin(a), 2.2)); }
    gt.hole.setAttribute("d", poly(hole));
    gt.str.setAttribute("d", seg(at(-1, 8, 2.4), at(-1, 85, 2.4)) + seg(at(1, 8, 2.4), at(1, 85, 2.4)) + seg(at(-4, 8, 2.2), at(4, 8, 2.2)));
  }

  let amp = value;
  const B = register(stage, (dt, now) => {
    let m = false;
    for (const gt of gs) { draw(gt, now); if (!tdone(gt.th, now) || !tdone(gt.tp, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);
  const cx = gs.map((gt) => P(gt.x, YB - 14, 40)[0]);

  function choose(a) {
    const now = performance.now();
    for (const gt of gs) {
      const d = a < 0 ? 0 : Math.abs(gt.i - a), delay = d * 45;
      if (a < 0) { tset(gt.th, rad(LEAN[gt.i]), now, 0); tset(gt.tp, rad(TURN[gt.i]), now, 0); }
      else if (gt.i === a) { tset(gt.th, rad(1), now, 0); tset(gt.tp, rad(-40 * amp), now, 0); }
      else { tset(gt.th, rad(LEAN[gt.i] + 5), now, delay); tset(gt.tp, rad(TURN[gt.i] + (gt.i < a ? -16 : 16)), now, delay); }
      gt.body.sil.classList.toggle("hi", a < 0 ? gt.i === FAV : gt.i === a);
    }
    read.textContent = a < 0 ? "rest" : "guitar " + (a + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let a = -1, bd = 26;
      cx.forEach((x, i) => { const d = Math.abs(p[0] - x); if (d < bd) { bd = d; a = i; } });
      if (p[1] < 20 || p[1] > 300) a = -1;
      choose(a);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  choose(-1);
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

hairline({
  name: "tapestand",
  means: "Three guitars on a stand: the one under the pointer stands up and turns to face you, its neighbours swinging aside.",
  rules: [1, 2, 4, 5],
  range: [0.5, 1, 1.4],
  tour: [[162, 141], [210, 165], [258, 189], null],
  mount,
});

ovenmitt.code:
/**
 * Oven door: a countertop oven whose door is hinged along its foot. The pointer
 * on the floor in front of the oven is how far the door is pulled down: the
 * nearer the reader, the wider it swings, and once it lies open the baking tray
 * slides out over it. At rest the door stands a little ajar, its handle bright.
 *
 * The pattern: a continuous swing (a spring on one angle); the hit is on the
 * floor's plane, which never moves.
 */
const {
  Cam, facing, fit, fillet, hull, open, poly, prism, proj, rings, seg, unproj, spring, stepS, clamp, lerp, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 52, H = 52, HZ = 5, L = 40, X0 = 6, X1 = 58, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 0], [W, 0, H], [0, D + L + 4, 0], [W, D + L + 4, 0], [0, 0, H + 6], [W, D, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the body, its feet and the cavity on its door face
  const [ring, inner] = rings(0, 0, W, D, 5, 1.6);
  put(solid(g), prism(P, front, ring, inner, 2, H));
  for (const [x, y] of [[6, D - 4], [W - 6, D - 4], [W - 6, 6]]) put(solid(g), prism(P, front, rings(x - 2.5, y - 2.5, x + 2.5, y + 2.5, 1.2, 0.5)[0], null, 0, 2.2));
  const cav = fillet([P(X0 + 3, D, HZ + 3), P(X1 - 3, D, HZ + 3), P(X1 - 3, D, HZ + L - 3), P(X0 + 3, D, HZ + L - 3)], [2, 2, 2, 2]);
  mk("path", { class: "lo nf", d: poly(cav) }, g);
  const racks = [];
  for (const z of [16, 30]) racks.push(open([P(X0 + 4, D, z), P(X0 + 4, D - 14, z), P(X1 - 4, D - 14, z), P(X1 - 4, D, z)]));
  mk("path", { class: "lo nf", d: racks.join("") }, g);
  // knobs on the side face
  for (const z of [H - 10, H - 22]) mk("path", { class: "nf sil", d: poly(fillet([P(W, D - 6, z), P(W, D - 12, z), P(W, D - 12, z + 5), P(W, D - 6, z + 5)], [2, 2, 2, 2])) }, g);
  const tray = solid(g), door = solid(g);
  const handle = mk("path", { class: "nf sil hi", d: "" }, door.g);
  const sp = spring(rad(REST), { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, trayFirst = true;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a), t = 3;
    const at = (x, l, o) => P(x, D + l * s + o * c, HZ + l * c - o * s);
    const outer = [at(X0, 0, t), at(X1, 0, t), at(X1, L, t), at(X0, L, t)];
    const back = [at(X0, 0, 0), at(X1, 0, 0), at(X1, L, 0), at(X0, L, 0)];
    const h = hull(outer.concat(back));
    door.sil.setAttribute("d", poly(fillet(h, h.map(() => 1.6), 3)));
    door.cr.setAttribute("d", poly(fillet(outer, [1.4, 1.4, 1.4, 1.4], 3)));
    handle.setAttribute("d", seg(at(X0 + 8, L - 5, t + 3.5), at(X1 - 8, L - 5, t + 3.5)) + seg(at(X0 + 8, L - 5, t), at(X0 + 8, L - 5, t + 3.5)) + seg(at(X1 - 8, L - 5, t), at(X1 - 8, L - 5, t + 3.5)));
    const out = clamp((a - rad(55)) / rad(32), 0, 1) * 30;
    if (out < 0.5) put(tray, { sil: "", crease: "" });
    else {
      const [tr, ti] = rings(X0 + 5, D - 12 + out, X1 - 5, D + out, 2, 1.2);
      put(tray, prism(P, front, tr, ti, 28, 30));
    }
    const tf = a < rad(60);
    if (tf !== trayFirst) { trayFirst = tf; if (tf) door.g.after(tray.g); else tray.g.after(door.g); }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    let deg = REST, on = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x > -14 && x < W + 14 && y > -10 && y < D + L + 24) { on = true; deg = lerp(REST, 90, clamp((y - D * 0.4) / (L + 10), 0, 1)); }
    }
    sp.t = rad(deg);
    door.sil.classList.toggle("hi", on);
    read.textContent = on ? "door " + Math.round(deg) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "ovenmitt",
  means: "An oven whose door swings down as the pointer comes near; opened wide, the baking tray slides out over it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[205, 212], [179, 238], [127, 264], null],
  mount,
