bloodpressure.code:
/**
 * Pill organiser: a weekly tray of seven compartments, each with its own
 * hinged lid. The pointer picks a day by where it stands: that lid swings
 * open on its back hinge to show the pills, and the lids beside it crack
 * open a little, staggered from it. At rest one lid stands half open,
 * bright. The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, rings, ringAt, tdone, tset, tval, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, W = 22, D = 26, H = 12, T = 1.6, OPEN = 105, FAV = 2;
const X1 = N * W;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [X1, D, 0], [X1, 0, 0], [0, D, 0], [0, 0, H + D + 2], [X1, 0, H + D + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));

  // lid corner in world space: s along depth from the hinge, t through the thickness
  const lidPt = (x, s, t, a) => {
    const c = Math.cos(rad(a)), n = Math.sin(rad(a));
    return P(x, s * c - t * n, H + s * n + t * c);
  };
  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * W + 1.2, x1 = (k + 1) * W - 1.2, grp = mk("g", {}, g);
    // the pills: two capsules and a round tablet sitting in the well
    const pills = [[x0 + 6, D * 0.45, 2.6], [x0 + 13, D * 0.62, 2.2], [x0 + 9, D * 0.78, 2.4]].slice(0, 1 + (k % 3));
    for (const [px, py, r] of pills) mk("path", { d: poly(hull(ringAt(P, disc(px, py, r), H - 0.4).concat(ringAt(P, disc(px, py, r), H + 1.2)))), class: "lo" }, grp);
    const lid = mk("path", { class: "sil" }, grp), top = mk("path", { class: "nf lo" }, grp), tab = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, x1, lid, top, tab, a: tween(k === FAV ? 55 : 0), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const pts = [];
    for (const x of [it.x0, it.x1]) for (const s of [0, D]) for (const t of [0, T]) pts.push(lidPt(x, s, t, a));
    it.lid.setAttribute("d", poly(hull(pts)));
    it.top.setAttribute("d", open([lidPt(it.x0 + 1, D - 1, T, a), lidPt(it.x1 - 1, D - 1, T, a)]));
    const m = (it.x0 + it.x1) / 2;
    it.tab.setAttribute("d", poly([lidPt(m - 4, D, 0, a), lidPt(m - 3, D + 3, 0, a), lidPt(m + 3, D + 3, 0, a), lidPt(m + 4, D, 0, a)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D / 2, H));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  const DAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), to = a < 0 ? (k === FAV ? 55 : 0) : dd === 0 ? OPEN : dd === 1 ? 18 : 0;
      tset(it.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : DAYS[a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bloodpressure",
  means: "A weekly pill organiser: the day's lid under the pointer swings open on its hinge, and the lids beside it crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[102, 136], [265, 217], [298, 234], null],
  mount,
});

walkersticks.code:
/**
 * Cane stand: six walking canes standing in a round stand, crooks facing
 * different ways. The pointer picks a cane by where it stands: it rises out
 * of the stand and tips outward on its foot, and the other canes settle
 * upright, staggered from it. At rest one cane leans out, bright.
 * The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, R = 17, H = 30, L = 76, CR = 1.7, HK = 5.5, FAV = 4, TIP = 30, RISE = 12;
const REST = [5, 3, 7, 4, 16, 6];
const disc = (x, y, r, n = 12) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.45);
  const canes = [];
  for (let k = 0; k < N; k++) {
    const a = rad(k * 60 + 20), h = rad(k * 97 + 40);
    canes.push({ k, bx: 9 * Math.cos(a), by: 9 * Math.sin(a), dx: Math.cos(a), dy: Math.sin(a), hx: Math.cos(h), hy: Math.sin(h) });
  }
  // the pose: tilt t (deg) outward about the foot, rise z
  const pose = (c, t, z) => {
    const s = Math.sin(rad(t)), co = Math.cos(rad(t));
    return [c.bx + c.dx * L * s, c.by + c.dy * L * s, 2 + z + L * co];
  };
  const ext = [];
  for (const c of canes) { const [x, y, z] = pose(c, TIP, RISE); ext.push([x + c.hx * 12, y + c.hy * 12, z + 7], [x, y, z]); }
  fit(C, ext.concat([[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-R, -R, R, R, R, 2);
  put(solid(g), prism(P, front, sr, si, 0, H));
  mk("path", { d: poly(ringAt(P, si, H)), class: "nf lo" }, g);

  canes.sort((a, b) => a.bx + a.by - (b.bx + b.by));
  for (const c of canes) {
    c.grp = mk("g", {}, g);
    c.shaft = mk("path", { class: "sil" }, c.grp);
    c.hook = mk("path", { class: "sil" }, c.grp);
    c.tw = tween(REST[c.k]);
    c.last = NaN;
  }
  // the stand's near wall, over the canes' feet
  const fr = run(sr, front);
  mk("path", { d: poly(ringAt(P, fr, H).concat(ringAt(P, fr, 0).reverse())), class: "sil" }, g);

  function draw(c, v) {
    if (v === c.last) return;
    c.last = v;
    const t = v, z = (v > REST[c.k] ? (v - REST[c.k]) / (TIP - REST[c.k]) : 0) * RISE;
    const [tx, ty, tz] = pose(c, t, z);
    c.shaft.setAttribute("d", poly(hull(ringAt(P, disc(c.bx, c.by, CR), 2 + z).concat(ringAt(P, disc(tx, ty, CR), tz)))));
    const arc = (r) => {
      const out = [];
      for (let i = 0; i <= 10; i++) { const f = Math.PI * (1 - i / 10); out.push(P(tx + c.hx * (HK + r * Math.cos(f)), ty + c.hy * (HK + r * Math.cos(f)), tz + r * Math.sin(f))); }
      out.push(P(tx + c.hx * (HK + r), ty + c.hy * (HK + r), tz - 6));
      return out;
    };
    c.hook.setAttribute("d", poly(arc(HK + CR).concat(arc(HK - CR).reverse())));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of canes) { draw(c, tval(c.tw, now)); if (!tdone(c.tw, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = [];
  for (const c of canes) { const [x, y, z] = pose(c, REST[c.k], 0); mids[c.k] = P((c.bx + x) / 2 + c.hx * 3, (c.by + y) / 2 + c.hy * 3, z * 0.7); }
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx) + 0.25 * Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    for (const c of canes) {
      const to = a < 0 ? REST[c.k] : c.k === a ? TIP : 0;
      tset(c.tw, to, now, from < 0 ? 0 : Math.abs(c.k - from) * stag);
      const on = c.k === (a < 0 ? FAV : a);
      c.shaft.classList.toggle("hi", on); c.hook.classList.toggle("hi", on);
    }
    read.textContent = a < 0 ? "rest" : "cane " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "walkersticks",
  means: "Six walking canes in a round stand: the cane under the pointer rises and tips outward, and the others settle upright.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[188, 142], [213, 169], [167, 154], null],
  mount,
});

earthermometer.code:
/**
 * Thermometer case: a slim clinic case with a hinged half-shell lid and a
 * digital thermometer lying in its well. The pointer over the case swings
 * the lid back on its long hinge and the thermometer rises out of the well,
 * bright. At rest the lid sits cracked open, bright. The slider is how far
 * the lid swings.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, tdone, tset, tval, tween, rad, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 96, D = 26, H = 9, T = 7, REST = 22, RISE = 7;
const lidRing = rrect(0, 0, L, D, 9, 6);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [L, D, 0], [L, 0, 0], [0, D, 0], [0, -T, H + D + 2], [L, -T, H + D + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, D, 9, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const [wr] = rings(5, 5, L - 5, D - 5, 6, 1);
  mk("path", { d: poly(ringAt(P, wr, H)), class: "nf lo" }, g);

  const lidPt = (u, s, t, a) => {
    const c = Math.cos(rad(a)), n = Math.sin(rad(a));
    return P(u, s * c - t * n, H + s * n + t * c);
  };
  const therm = mk("g", {}, g), lid = mk("g", {}, g);
  const tSil = mk("path", { class: "sil" }, therm), tCr = mk("path", { class: "nf lo" }, therm);
  const tWin = mk("path", { class: "nf lo" }, therm), tTip = mk("path", { class: "sil" }, therm);
  const lSil = mk("path", { class: "sil" }, lid), lCr = mk("path", { class: "nf lo" }, lid), lCatch = mk("path", { class: "nf lo" }, lid);
  const ang = tween(REST);
  let lastA = NaN, back = false;
  const [thr, thi] = rings(10, 9, 74, 17, 4, 1.2), [tpr, tpi] = rings(72, 11.2, 88, 14.8, 1.8, 0.6), [wn] = rings(20, 10.5, 40, 15.5, 1.5, 0.5);

  function draw(a) {
    if (a === lastA) return;
    lastA = a;
    const lift = Math.max(0, (a - REST) / (110 - REST)) * RISE, z0 = H - 3 + lift;
    const t = prism(P, front, thr, thi, z0, z0 + 5), tp = prism(P, front, tpr, tpi, z0 + 1, z0 + 3.4);
    tSil.setAttribute("d", t.sil); tCr.setAttribute("d", t.crease);
    tTip.setAttribute("d", tp.sil);
    tWin.setAttribute("d", poly(ringAt(P, wn, z0 + 5)));
    const pts = [], top = [];
    for (const q of lidRing) { pts.push(lidPt(q.u, q.v, 0, a), lidPt(q.u, q.v, T, a)); }
    for (const q of rrect(2, 2, L - 2, D - 2, 7, 6)) top.push(lidPt(q.u, q.v, T, a));
    lSil.setAttribute("d", poly(hull(pts)));
    lCr.setAttribute("d", poly(top));
    lCatch.setAttribute("d", poly([lidPt(L / 2 - 7, D, 1, a), lidPt(L / 2 - 6, D + 2.4, 1, a), lidPt(L / 2 + 6, D + 2.4, 1, a), lidPt(L / 2 + 7, D, 1, a)]));
    const nb = a > 70;
    if (nb !== back) { back = nb; if (back) therm.before(lid); else lid.before(therm); }
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -6 && x < L + 6 && y > -14 && y < D + 6;
  }
  let on = null;
  function setActive(a) {
    if (a === on) return;
    on = a;
    tset(ang, a ? 70 + swing * 0.45 : REST, performance.now(), 0);
    lSil.classList.toggle("hi", !a);
    tSil.classList.toggle("hi", a); tTip.classList.toggle("hi", a);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (on) { tset(ang, 70 + v * 0.45, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "earthermometer",
  means: "A clinic thermometer case: the pointer swings its lid back on the hinge and the thermometer rises out of the well.",
  rules: [1, 5, 6, 8],
  range: [0, 70, 90],
  tour: [[99, 150], [193, 196], [271, 250], null],
  mount,
});

oscilloscope.code:
/**
 * Oscilloscope: a bench scope with a screen, a trace and two knobs. The
 * pointer is a probe on the bench: the scope turns on its spot to face it,
 * and the trace tightens or loosens with the turn. At rest it sits turned a
 * little away, the trace bright. The slider is the trace's amplitude.
 *
 * The pattern: one object turning to face the pointer.
 */
const {
  Cam, fit, facing, fillet, open, poly, prism, proj, rrect, unproj, clamp, rad,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const W = 64, D = 40, H = 40, LIM = 40, REST = -22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.95);
  const ext = [];
  for (const sx of [-34, 34]) for (const sy of [-34, 34]) ext.push([sx, sy, 0], [sx, sy, H + 2]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const body = solid(g), feet = mk("path", { class: "nf lo" }, g);
  const scr = mk("path", {}, g), grat = mk("path", { class: "dash" }, g);
  const trace = mk("path", { class: "nf hi" }, g);
  const k1 = mk("path", {}, g), k2 = mk("path", {}, g), k3 = mk("path", { class: "nf lo" }, g);
  const th = spring(REST);
  let last = NaN;

  function rot(ring, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
  }

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), c = Math.cos(a), s = Math.sin(a);
    // a point on the front face: u across, z up, standing out by o
    const F = (u, z, o = 0) => { const v = D / 2 + o; return P(u * c - v * s, u * s + v * c, z); };
    put(body, prism(P, front, rot(rrect(-W / 2, -D / 2, W / 2, D / 2, 5, 4), a), rot(rrect(-W / 2 + 1.8, -D / 2 + 1.8, W / 2 - 1.8, D / 2 - 1.8, 3.2, 4), a), 3, H));
    feet.setAttribute("d", open([F(-W / 2 + 6, 3), F(-W / 2 + 6, 0), F(-W / 2 + 12, 0), F(-W / 2 + 12, 3)]) + open([F(W / 2 - 12, 3), F(W / 2 - 12, 0), F(W / 2 - 6, 0), F(W / 2 - 6, 3)]));
    const u0 = -W / 2 + 5, u1 = 8, z0 = 9, z1 = H - 6;
    scr.setAttribute("d", poly(fillet([F(u0, z1), F(u1, z1), F(u1, z0), F(u0, z0)], [3, 3, 3, 3])));
    grat.setAttribute("d", open([F(u0 + 2, (z0 + z1) / 2), F(u1 - 2, (z0 + z1) / 2)]) + open([F((u0 + u1) / 2, z0 + 2), F((u0 + u1) / 2, z1 - 2)]));
    const cyc = 1.5 + (deg + LIM) / (2 * LIM) * 2.5, A = (z1 - z0) / 2 - 3, pts = [];
    for (let i = 0; i <= 48; i++) { const t = i / 48; pts.push(F(u0 + 3 + t * (u1 - u0 - 6), (z0 + z1) / 2 + A * amp * Math.sin(t * cyc * 2 * Math.PI), 0.2)); }
    trace.setAttribute("d", open(pts));
    const knob = (u, z, r) => { const q = []; for (let i = 0; i < 20; i++) { const t = (i / 20) * 2 * Math.PI; q.push(F(u + r * Math.cos(t), z + r * Math.sin(t), 0.3)); } return poly(q); };
    k1.setAttribute("d", knob(19, z1 - 5, 5.5));
    k2.setAttribute("d", knob(19, z0 + 6, 4.2));
    const kz = z1 - 5, ka = rad(deg * 3);
    k3.setAttribute("d", open([F(19, kz, 0.4), F(19 + 4.5 * Math.cos(ka), kz + 4.5 * Math.sin(ka), 0.4)]));
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(Math.round(th.x * 10) / 10); return m; });
  bag.add(B.unregister);

  function aim(p) {
    let deg = REST;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      deg = clamp(-Math.atan2(x, y) * 180 / Math.PI, -LIM, LIM);
    }
    th.t = deg;
    read.textContent = p ? (deg >= 0 ? "+" : "") + Math.round(deg) + "°" : "rest";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

