ssdbay.code:
/**
 * Drive bays: a storage chassis with six drive caddies in a row in its face.
 * The pointer picks a caddy by where it stands: that caddy slides out of its
 * bay on its rails, its latch swinging open, and the caddies beside it ease
 * out a little, staggered from it. At rest one caddy stands half out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), sliding.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 19, CW = 15, X0 = 5, W = X0 * 2 + (N - 1) * STEP + CW, DEP = 46, FY = DEP, H = 30;
const Z0 = 4, Z1 = 26, OUT = 30, FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, FY + OUT + 2, 0], [W, FY + OUT + 2, 0], [0, 0, H], [W, FY + OUT, Z1]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, DEP, 3, 1.6);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  // empty bays: a dim slot in the face behind each caddy
  let slots = "";
  for (let k = 0; k < N; k++) { const x = X0 + k * STEP; slots += poly([P(x, FY, Z0), P(x + CW, FY, Z0), P(x + CW, FY, Z1), P(x, FY, Z1)]); }
  mk("path", { d: slots, class: "lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g), s = solid(grp);
    const latch = mk("path", { class: "nf lo" }, grp), led = mk("path", { class: "nf" }, grp);
    items.push({ k, x, s, latch, led, o: tween(k === FAV ? OUT * 0.55 : 0), last: NaN });
  }

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const y1 = FY + 2 + o, [r, i] = rings(it.x + 0.4, FY, it.x + CW - 0.4, y1, 1.6, 0.7);
    put(it.s, prism(P, front, r, i, Z0 + 0.4, Z1 - 0.4));
    // the latch swings out from the caddy's face as it slides
    const a = Math.min(1, o / OUT) * 1.1, lx = it.x + 3, lz = Z0 + 3;
    it.latch.setAttribute("d", open([P(lx, y1, lz), P(lx + Math.sin(a) * 0, y1 + Math.sin(a) * 9, lz + Math.cos(a) * 14)]));
    it.led.setAttribute("d", poly([P(it.x + CW - 4, y1, Z1 - 5), P(it.x + CW - 2.5, y1, Z1 - 5), P(it.x + CW - 2.5, y1, Z1 - 3.5), P(it.x + CW - 4, y1, Z1 - 3.5)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + CW / 2, FY, (Z0 + Z1) / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 22 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? OUT * 0.55 : 0) : dd === 0 ? OUT : dd === 1 ? 7 : 0;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ssdbay",
  means: "A storage chassis with six drive caddies: the caddy under the pointer slides out on its rails and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[110, 131], [248, 200], [277, 215], null],
  mount,
});

vrstation.code:
/**
 * Charging dock: five tablets standing in the slots of a charging dock. The
 * pointer picks a tablet by where it stands: it tips forward out of its slot
 * toward the reader, pivoting on its foot, and the tablets beside it tip a
 * little, staggered from it. At rest the row leans back and one tablet stands
 * tipped forward, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), tilting.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, TW = 22, STEP = 28, X0 = 6, W = X0 * 2 + (N - 1) * STEP + TW, DD = 34, BH = 10, TH = 44, T = 2.4, SY = 13;
const BACK = -9, TIP = 34, FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  const ty = SY + TH * Math.sin(rad(TIP));
  fit(C, [[0, 0, 0], [W, 0, 0], [0, Math.max(DD, ty), 0], [W, Math.max(DD, ty), 0], [0, SY, BH + TH], [W, ty, BH + TH * Math.cos(rad(TIP))]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, DD, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  let slots = "";
  for (let k = 0; k < N; k++) { const x = X0 + k * STEP; slots += poly([P(x - 1, SY - 2.5, BH), P(x + TW + 1, SY - 2.5, BH), P(x + TW + 1, SY + 2.5, BH), P(x - 1, SY + 2.5, BH)]); }
  mk("path", { d: slots, class: "nf lo" }, g);

  const face = rrect(0, 0, TW, TH, 3.5, 4), scr = rrect(2.2, 3, TW - 2.2, TH - 3, 1.6, 4);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), s2 = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, sil, s2, a: tween(k === FAV ? TIP * 0.6 : BACK), last: NaN });
  }

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const a = rad(deg), s = Math.sin(a), c = Math.cos(a);
    const W3 = (q, d) => P(it.x + q.u, SY + q.v * s + d * c, BH - 1 + q.v * c - d * s);
    const fr = face.map((q) => W3(q, T / 2)), bk = face.map((q) => W3(q, -T / 2));
    it.sil.setAttribute("d", poly(hull(fr.concat(bk))));
    it.s2.setAttribute("d", poly(scr.map((q) => W3(q, T / 2))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + TW / 2, SY, BH + TH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? (k === FAV ? TIP * 0.6 : BACK) : dd === 0 ? TIP : dd === 1 ? 6 : BACK;
      tset(it.a, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tab " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "vrstation",
  means: "Tablets standing in a charging dock: the tablet under the pointer tips forward out of its slot, its neighbours tipping a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[136, 115], [214, 154], [293, 193], null],
  mount,
});

cablereel.code:
/**
 * Cable tray: a ladder rack, two rails joined by rungs, with three cables
 * laid along it. The pointer is a hand along the tray: the cables lift off
 * the rungs in a loop where it is, the middle one highest, and settle back
 * behind it. At rest the cables keep a small hump, the middle one bright.
 * The slider is the loop's height.
 *
 * The pattern: a field answering a continuous position (terrain), on a line.
 */
const {
  Cam, fit, facing, open, poly, prism, proj, rings, unproj, clamp,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const L = 176, DW = 36, RH = 9, RUNG = 16, LIFT = 30, CAB = [[10, 0.75, 3.2], [18, 1, 3.8], [26, 0.6, 2.8]];
const REST_X = L * 0.32, REST_A = 0.3, SIG = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let hgt = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [L, 0, 0], [0, DW, 0], [L, DW, 0], [L / 2, 0, LIFT + 12], [0, DW / 2, LIFT + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const bar = (x0, y0, x1, y1, z0, z1) => { const [r, i] = rings(x0, y0, x1, y1, 1, 0.5); put(solid(g), prism(P, front, r, i, z0, z1)); };
  bar(0, 0, L, 2.6, 0, RH);
  for (let x = 6; x < L; x += RUNG) bar(x, 2.6, x + 3, DW - 2.6, 1, 3.4);
  const cabs = CAB.map(([y, w, r], k) => ({ y, w, r, el: mk("path", { class: k === 1 ? "hi" : "" }, g) }));
  bar(0, DW - 2.6, L, DW, 0, RH);

  const cx = spring(REST_X), amp = spring(REST_A);
  let last = "";
  function draw() {
    const key = cx.x.toFixed(2) + amp.x.toFixed(3) + hgt;
    if (key === last) return;
    last = key;
    for (const cb of cabs) {
      const up = [], dn = [];
      for (let i = 0; i <= 60; i++) {
        const x = 1 + (i / 60) * (L - 2), b = Math.exp(-((x - cx.x) ** 2) / (2 * SIG * SIG)) * amp.x * hgt * LIFT * cb.w;
        const z = 3.4 + cb.r + b;
        up.push(P(x, cb.y, z + cb.r)); dn.push(P(x, cb.y, z - cb.r));
      }
      cb.el.setAttribute("d", poly(up.concat(dn.reverse())));
    }
  }

  const B = register(stage, (dt) => { const m = stepS(cx, dt) | stepS(amp, dt); draw(); return !!m; });
  bag.add(B.unregister);

  function aim(p) {
    let on = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x > -10 && x < L + 10 && y > -40 && y < DW + 40) { on = true; cx.t = clamp(x, 8, L - 8); amp.t = 1; }
    }
    if (!on) { cx.t = REST_X; amp.t = REST_A; }
    read.textContent = on ? "rung " + (1 + Math.round((cx.t - 7.5) / RUNG)) : "rest";
    B.wake();
  }
  draw();
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { hgt = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "cablereel",
  means: "A ladder cable tray: the cables lift off the rungs in a loop wherever the pointer runs along it, then settle back.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[103, 144], [252, 218], [301, 243], null],
  mount,
});

lunchcounter.code:
/**
 * Lunch counter: a diner counter with four swivel stools in front of it. The
 * pointer picks a stool by where it stands: it swivels round to face the
 * viewer, and the stools beside it turn a little after it, staggered by
 * distance. At rest one stool sits turned out, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row, answering with a turn.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 22, SY = 34, SZ = 17, FAV = 2, X0 = 14, L = X0 * 2 + (N - 1) * STEP;
const REST = [100, 80, -60, 95];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [L, 0, 0], [0, SY + 8, 0], [L, SY + 8, 0], [0, 0, 30], [L, 0, 30], [0, SY + 8, SZ + 20], [L, SY + 8, SZ + 20]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 2, L, 14, 2, 1.2);
  put(solid(g), prism(P, front, cr, ci, 0, 26));
  const [tr, ti] = rings(-3, -1, L + 3, 18, 3, 1.6);
  put(solid(g), prism(P, front, tr, ti, 26, 29));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, SY, 6), disc(x, SY, 5), 0, 1.5));
    put(solid(grp), prism(P, front, disc(x, SY, 1.4, 12), disc(x, SY, 0.8, 12), 1.5, SZ));
    const seat = solid(grp);
    put(seat, prism(P, front, disc(x, SY, 7.5, 32), disc(x, SY, 6.3, 32), SZ, SZ + 3));
    const back = mk("path", { class: "sil" }, grp);
    items.push({ k, x, seat, back, a: tween(REST[k]), last: NaN });
  }

  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const pts = [];
    for (let i = 0; i <= 10; i++) {
      const t = ((a - 75 + i * 15) * Math.PI) / 180;
      for (const r of [7.2, 6]) for (const z of [SZ + 3, SZ + 19]) pts.push(P(it.x + r * Math.cos(t), SY + r * Math.sin(t), z));
    }
    it.back.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, SY, SZ / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.a, a < 0 ? REST[k] : dd === 0 ? -90 : dd === 1 ? REST[k] + (k > a ? 80 : -80) : REST[k] + (k > a ? 40 : -40), now, d);
      const on = k === (a < 0 ? FAV : a);
      it.back.classList.toggle("hi", on);
      it.seat.sil.classList.toggle("hi", on);
    });
    read.textContent = a < 0 ? "rest" : "stool " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lunchcounter",
  means: "A diner counter with four swivel stools: the stool under the pointer swivels round to face you, its neighbours turn a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[119, 163], [158, 183], [235, 222], null],
  mount,
});

breadslicer.code:
/**
 * Bread slicer: a sliced loaf standing on a board. The pointer picks a slice
 * by where it stands: it slides out of the loaf toward the viewer and leans
 * away, and the slices beside it slide a little after it, staggered by
 * distance. At rest the end slice stands loose, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row, answering with a slide.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, T = 5, GAP = 1.2, BZ = 4, OUT = 24, FAV = N - 1;
const X0 = 10, Y = 22, L = X0 * 2 + N * (T + GAP);
// a slice's face, in (v, z): a flat foot and a domed crust
const FACE = [[11, 0], [12.5, 1.5], [-12.5, 1.5], [-11, 0]];
for (let i = 0; i <= 12; i++) { const t = (i / 12) * Math.PI; FACE.push([13 * Math.cos(t), 15 + 9 * Math.sin(t)]); }
const INNER = FACE.map(([v, z]) => [v * 0.8, 2.5 + (z - 1) * 0.8]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[0, 0, 0], [L, 2 * Y, 0], [L, 0, 0], [0, 2 * Y, 0], [X0, Y, BZ + 25], [L - X0, Y + OUT + 14, BZ + 20]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, 2 * Y, 6, 2);
  put(solid(g), prism(P, facing(C), br, bi, 0, BZ));

  const rest = (k) => (k === FAV ? [6, 10] : [0, 0]);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * (T + GAP), grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), cre = mk("path", { class: "nf lo" }, grp);
    const [s, a] = rest(k);
    items.push({ k, x, grp, sil, cre, s: tween(s), a: tween(a), last: "" });
  }

  function draw(it, s, a) {
    const key = s.toFixed(2) + "," + a.toFixed(2);
    if (key === it.last) return;
    it.last = key;
    const sn = Math.sin(a * Math.PI / 180), cs = Math.cos(a * Math.PI / 180);
    // leans away from the loaf, about its foot
    const t = (dx, v, z) => P(it.x + dx * cs + z * sn, Y + s + v, BZ + z * cs - dx * sn);
    const pts = [];
    for (const [v, z] of FACE) pts.push(t(0, v, z), t(T, v, z));
    it.sil.setAttribute("d", poly(hull(pts)));
    it.cre.setAttribute("d", open(INNER.slice(4).map(([v, z]) => t(T, v, z))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.s, now), tval(it.a, now)); if (!tdone(it.s, now) || !tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + T / 2, Y, BZ + 12));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const tg = items.map((it, k) => {
      const dd = Math.abs(k - a);
      return a < 0 ? rest(k) : dd === 0 ? [OUT, 14] : dd === 1 ? [5, 3] : [0, 0];
    });
    // nearer slices paint later: order by x + slide target
    items.slice().sort((p, q) => p.x + tg[p.k][0] - q.x - tg[q.k][0]).forEach((it) => g.appendChild(it.grp));
    items.forEach((it, k) => {
      const d = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.s, tg[k][0], now, d);
      tset(it.a, tg[k][1], now, d);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "slice " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "breadslicer",
  means: "A sliced loaf on a board: the slice under the pointer slides out toward you and leans away, its neighbours follow a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[152, 118], [183, 133], [245, 164], null],
  mount,
});

icecubes.code:
/**
 * Ice tray: a tray of eight cubes in two rows. The pointer picks a cube by
 * the cell under it on the tray: the cube jumps out and tumbles, and the
 * cubes beside it loosen and tip a little, staggered by distance. At rest
 * one cube sits loose, tipped, bright. The slider is the stagger.
 *
 * The pattern: a grid on a plane, answering with a tumble.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, run, unproj, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NX = 4, NY = 2, CELL = 17, H = 12, TZ = 5, FAV = 5, M = 4;
const W = NX * CELL + 2 * M, D = NY * CELL + 2 * M;
const sq = rrect(-6, -6, 6, 6, 2.2, 3), sqIn = rrect(-4.8, -4.8, 4.8, 4.8, 1.2, 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.25);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [M + 8, M + 8, TZ + H + 30], [W - 8, M + 8, TZ + H + 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(0, 0, W, D, 5, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  for (let i = 1; i < NX; i++) mk("path", { d: open([P(M + i * CELL, M, TZ), P(M + i * CELL, D - M, TZ)]), class: "nf lo" }, g);
  mk("path", { d: open([P(M, M + CELL, TZ), P(W - M, M + CELL, TZ)]), class: "nf lo" }, g);

  const cells = [];
  for (let j = 0; j < NY; j++) for (let i = 0; i < NX; i++) cells.push({ i, j, x: M + (i + 0.5) * CELL, y: M + (j + 0.5) * CELL });
  const order = cells.map((c, k) => k).sort((a, b) => cells[a].x + cells[a].y - cells[b].x - cells[b].y);
  const rest = (k) => (k === FAV ? [26, 6] : [((k * 7) % 5) - 2, 0]);
  const items = cells.map((c) => ({ ...c, a: tween(0), z: tween(0), last: "" }));
  for (const k of order) {
    const it = items[k], grp = mk("g", {}, g);
    it.sil = mk("path", { class: "sil" }, grp); it.cre = mk("path", { class: "nf lo" }, grp);
    const [a, z] = rest(k); it.a = tween(a); it.z = tween(z);
  }
  const frontIn = run(sqIn, front);

  function draw(it, a, lift) {
    const key = a.toFixed(2) + "," + lift.toFixed(2);
    if (key === it.last) return;
    it.last = key;
    const s = Math.sin(a * Math.PI / 180), c = Math.cos(a * Math.PI / 180), zc = TZ + lift + H / 2;
    // tumble about the cube's centre, around the tray's short axis
    const t = (u, v, z) => { const dz = z - H / 2; return P(it.x + u * c + dz * s, it.y + v, zc - u * s + dz * c); };
    const pts = [];
    for (const q of sq) pts.push(t(q.u, q.v, 0), t(q.u, q.v, H));
    it.sil.setAttribute("d", poly(hull(pts)));
    it.cre.setAttribute("d", open(frontIn.map((q) => t(q.u, q.v, H))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now), tval(it.z, now)); if (!tdone(it.a, now) || !tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TZ + H);
    const i = Math.floor((x - M) / CELL), j = Math.floor((y - M) / CELL);
    return i >= 0 && i < NX && j >= 0 && j < NY ? j * NX + i : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const ai = a % NX, aj = Math.floor(a / NX);
    items.forEach((it, k) => {
      const dd = Math.max(Math.abs(it.i - ai), Math.abs(it.j - aj)), d = from < 0 ? 0 : Math.abs(k - from) * stag * 0.6;
      const [ra, rz] = rest(k);
      tset(it.a, a < 0 ? ra : dd === 0 ? 72 : dd === 1 ? 12 : ra, now, d);
      tset(it.z, a < 0 ? rz : dd === 0 ? 22 : dd === 1 ? 3 : 0, now, d);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cube " + (ai + 1) + "·" + (aj + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "icecubes",
  means: "An ice tray of eight cubes: the cube under the pointer jumps out and tumbles, and the cubes beside it loosen and tip.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[161, 135], [200, 155], [239, 214], null],
  mount,
});

flashcards.code:
/**
 * Flash cards: a box of upright study cards. The pointer picks a card by
 * where it stands over the box: that card and every card in front of it
 * swing forward, the ones behind lean back, staggered out from it, opening
 * the file at the chosen card. At rest the file is open at one card, bright.
 * The slider is the stagger.
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, GAP = 6, X0 = 8, W = 58, H = 44, BZ = 10, FAV = 4, FWD = 38, BACK = -12;
const REST = [-14, -12, -10, -8, 22, 24, 27];
const XL = X0 + (N - 1) * GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-4, -4, 0], [XL + 6, W + 4, 0], [X0 - 12, 0, BZ + H], [XL + 30, W, BZ + H * 0.8], [XL + 6, -4, 0], [-4, W + 4, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, XL + 6, W + 4, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const cards = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * GAP, grp = mk("g", {}, g);
    const face = mk("path", { class: "sil" }, grp), edge = mk("path", { class: "nf lo" }, grp);
    const dots = [0, 1, 2].slice(0, (k % 3) + 1).map(() => mk("ellipse", { class: "dot off", rx: 1.6, ry: 1 }, grp));
    cards.push({ k, x, face, edge, dots, a: tween(REST[k]), last: NaN });
  }

  function draw(c, deg) {
    if (deg === c.last) return;
    c.last = deg;
    const s = Math.sin(deg * Math.PI / 180), co = Math.cos(deg * Math.PI / 180);
    const at = (y, h) => P(c.x + s * h, y, BZ - 2 + co * h);
    const pts = [at(0, 0), at(W, 0), at(W, H), at(0, H)];
    c.face.setAttribute("d", poly(fillet(pts, [1, 1, 4, 4], 4)));
    c.edge.setAttribute("d", seg(at(3, H - 3), at(W - 3, H - 3)));
    c.dots.forEach((d, i) => { const q = at(8 + i * 5, H - 9); d.setAttribute("cx", q[0]); d.setAttribute("cy", q[1]); });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cards) { draw(c, tval(c.a, now)); if (!tdone(c.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, BZ + H * 0.5);
    if (wy < -6 || wy > W + 6) return -1;
    const k = Math.round((wx - X0) / GAP);
    return k >= -2 && k <= N + 1 ? Math.max(0, Math.min(N - 1, k)) : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act >= 0 ? act : FAV;
    act = a;
    cards.forEach((c, k) => {
      const to = a < 0 ? REST[k] : k >= a ? FWD + (k - a) * 1.5 : BACK + (k - a) * 1.5;
      tset(c.a, to, now, Math.abs(k - from) * stag);
      c.face.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "card " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "flashcards",
  means: "A box of upright flash cards: the card under the pointer and those in front swing forward, opening the file at it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[173, 140], [205, 156], [237, 172], null],
  mount,
});

waterpump.code:
/**
 * Hand pump: a cast-iron pump on a stone slab, its long handle on a pivot at
 * the cap, a spout over a bucket. The pointer's height is the handle: up
 * high it lifts, low it presses, and pressing the handle draws water from
 * the spout into the bucket. At rest the handle hangs half raised, bright.
 *
 * The pattern: a continuous aim (one spring on the handle's angle); the hit is
 * the pointer's screen height, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, hull, poly, fillet, clamp, lerp, rad,
  spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const L = 50, AR = 9, PZ = 54, PX = -4, REST = 24, UP = 38, DN = -30;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  const ends = [];
  for (const d of [UP, DN]) ends.push([PX - L * Math.cos(rad(d)), 0, PZ + L * Math.sin(rad(d))]);
  fit(C, ends.concat([[-16, -16, 0], [16, 16, 0], [32, 8, 0], [32, -8, 0], [0, 0, 56]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const slab = rings(-16, -16, 16, 16, 3, 1.4);
  put(solid(g), prism(P, front, slab[0], slab[1], 0, 4));
  place(flatDot(g, C, 1.2, "dot off"), P(-11, 11, 4));
  const handle = solid(g);
  put(solid(g), prism(P, front, disc(0, 0, 6), null, 4, 46));
  put(solid(g), prism(P, front, disc(0, 0, 7.5), disc(0, 0, 6.3), 46, 50));
  const br = rings(-6, -1.6, -2, 1.6, 0.8, 0.4);
  put(solid(g), prism(P, front, br[0], null, 50, PZ + 1));
  const sp = rings(5.5, -2.6, 24, 2.6, 1.4, 0.6);
  put(solid(g), prism(P, front, sp[0], sp[1], 33, 37));
  const stream = mk("path", { class: "lo nf" }, g);
  const bk = mk("g", {}, g);
  put(solid(bk), prism(P, front, disc(25, 0, 7.5), disc(25, 0, 6.6), 0, 13));
  const water = mk("path", { class: "lo nf" }, bk);

  const a = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const d = a.x;
    if (Math.abs(d - drawn) < 1e-3) return;
    drawn = d;
    const c = Math.cos(rad(d)), s = Math.sin(rad(d)), pts = [];
    for (const t of [-L, AR]) for (const w of [-1.6, 1.6]) for (const h of [-1.8, 1.8]) {
      pts.push(P(PX + t * c, w, PZ - t * s + h));
    }
    const hp = hull(pts);
    handle.sil.setAttribute("d", poly(fillet(hp, hp.map(() => 1.2))));
    handle.cr.setAttribute("d", seg(P(PX, 0, PZ), P(PX + AR * c, 0, PZ - AR * s - 10)));
    const w = clamp((14 - d) / 44, 0, 1);
    stream.setAttribute("d", w > 0.02 ? seg(P(22.5, 0, 33), P(22.5, 0, 33 - w * 22)) + seg(P(23.6, 0, 33), P(23.6, 0, 33 - w * 18)) : "");
    water.setAttribute("d", w > 0.02 ? poly(disc(25, 0, 6.6 * Math.sqrt(w), 24).map((q) => P(q.u, q.v, 2 + w * 9))) : "");
  }
  handle.sil.classList.add("sil");

  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(t, on) {
    a.t = t;
    handle.sil.classList.toggle("hi", true);
    read.textContent = on ? (t < 14 ? "pump " : "lift ") + Math.round(Math.abs(t)) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => set(clamp(lerp(UP, DN, (p[1] - 70) / 190), DN, UP), true),
    leave: () => set(REST, false),
  }));
  bag.add(() => svg.replaceChildren());
  set(REST, false);
  draw();
  return {
    set: (v) => { a.k = 100 * v; a.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

