  name: "studybooth",
  means: "Four study carrels in a row: the stool at the pointer's carrel slides out and turns, the neighbours easing out less.",
  rules: [1, 2, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[257, 143], [214, 164], [129, 207], null],
  mount,
});

firewood.code:
/**
 * Log store: split logs stacked under a lean-to roof on four posts. The
 * pointer picks a log by its end face and that log slides out of the stack
 * toward you; its neighbours draw out less, by distance. At rest the ends sit
 * unevenly, one bright. The slider is how far the logs come out.
 */
const {
  Cam, fit, prism, proj, rings, facing, tween, tset, tval, tdone, hull, poly, ringAt, run,
  disposer, mk, pointer, put, register, solid, clamp, circ,
} = HL;

const COLS = [-24, -12, 0, 12, 24], ROWS = [6, 17.5, 29], R = 5.6, L = 20, FAV = 7;
const REST = [2, -1, 3, 0, -2, 1, 4, -1, 2, 0, -2, 3, 1, -1, 2];
const C0 = circ(R, 20), C1 = circ(R - 1.1, 20);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-26, -36, 0], [26, 36, 0], [-26, -36, 50], [26, 36, 44], [L + 40, 0, 0]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x, y, z1) => { const [a, b] = rings(x - 1.5, y - 1.5, x + 1.5, y + 1.5, 1, 0.5); put(solid(g), prism(P, front, a, b, 0, z1)); };
  post(-22, -32, 47); post(-22, 32, 47); post(22, -32, 41);
  const [FR, FI] = rings(-24, -34, 24, 34, 2, 1.2);
  put(solid(g), prism(P, front, FR, FI, 0, 1.5));
  const lg = mk("g", {}, g);
  const logs = [];
  ROWS.forEach((z, r) => COLS.forEach((y, c) => {
    const i = logs.length, s = solid(lg);
    logs.push({ i, r, c, y, z, s, tw: tween(REST[i]), drawn: NaN });
  }));
  post(22, 32, 41);
  // the lean-to roof: a plate falling from the back posts to the front
  const roof = mk("g", {}, g);
  const top = [[-27, -36, 49], [-27, 36, 49], [27, 36, 42], [27, -36, 42]];
  mk("path", { class: "sil", d: poly(hull(top.map((q) => P(...q)).concat(top.map((q) => P(q[0], q[1], q[2] - 1.6))))) }, roof);
  mk("path", { class: "lo nf", d: "M" + P(26, -35, 42.2) + "L" + P(26, 35, 42.2) }, roof);

  // a log lies along x: its rings stand in the y-z plane
  const at = (q, x, y, z) => P(x, y + q.u, z + q.v);
  function draw(o, now) {
    const dx = tval(o.tw, now);
    if (Math.abs(dx - o.drawn) < 1e-3) return;
    o.drawn = dx;
    const x0 = -L + dx, x1 = L + dx;
    const pts = C0.map((q) => at(q, x0, o.y, o.z)).concat(C0.map((q) => at(q, x1, o.y, o.z)));
    o.s.sil.setAttribute("d", poly(hull(pts)));
    o.s.cr.setAttribute("d", poly(C1.map((q) => at(q, x1, o.y, o.z))) + poly(C0.map((q) => at(q, x1, o.y, o.z))));
  }
  const B = register(stage, (dt, now) => {
    let m = false;
    for (const o of logs) { draw(o, now); if (!tdone(o.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let amp = value, sel = null;
  const FALL = [1, 0.34, 0.12, 0.05, 0.02, 0.01, 0];
  function retarget() {
    const now = performance.now(), a = logs[sel ?? FAV];
    for (const o of logs) {
      const d = Math.abs(o.r - a.r) + Math.abs(o.c - a.c);
      o.to = REST[o.i] + (sel === null ? 0 : clamp(amp * 30, 0, 42) * FALL[d]);
      tset(o.tw, o.to, now, d * 40);
      o.s.sil.classList.toggle("hi", o === a);
    }
    // nearer logs paint later: higher, further toward +y, further out
    [...logs].sort((p, q) => p.y + p.z + p.to * 0.6 - (q.y + q.z + q.to * 0.6)).forEach((o) => lg.appendChild(o.s.g));
    read.textContent = sel === null ? "rest" : "log " + (a.r + 1) + "·" + (a.c + 1);
    B.wake();
  }
  // hit: each log's rest end face, never its moving one
  const ends = logs.map((o) => P(L + REST[o.i], o.y, o.z));
  bag.add(pointer(stage, {
    move: (p) => {
      let best = null, bd = 16;
      ends.forEach((e, i) => { const d = Math.hypot(p[0] - e[0], p[1] - e[1]); if (d < bd) { bd = d; best = i; } });
      sel = best; retarget();
    },
    leave: () => { sel = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amp = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "firewood",
  means: "A log store under a lean-to roof: the log whose end the pointer touches slides out of the stack, its neighbours less.",
  rules: [1, 2, 3, 5, 6, 8],
  range: [0.5, 1, 1.4],
  tour: [[232, 159], [194, 198], [159, 238], null],
  mount,
});

coffeecups.code:
/**
 * Cup stack: three stacks of nested takeaway cups on a counter, the top cup
 * of each wearing its lid. The pointer picks a stack by where it stands: the
 * stack draws apart like an accordion, every cup lifting clear of the one
 * below, and the stacks beside it open a little, staggered from it. At rest
 * the middle stack stands half open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, hull, open, poly, proj, ringAt, run, facing, tdone, tset, tval, tween,
  disposer, mk, pointer, register, solid,
} = HL;

const COUNTS = [5, 7, 4], STEP = 34, RF = 7.5, RT = 11, H = 20, G0 = 3.4, G1 = 10, FAV = 1, CZ = 3;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const RESTG = [G0 + 0.6, G0 + 3.2, G0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  const X1 = 2 * STEP + 2 * RT;
  fit(C, [[-6, -6, 0], [X1 + 6, 2 * RT + 6, 0], [X1 + 6, -6, 0], [-6, 2 * RT + 6, 0], [RT + STEP, RT, CZ + H + 6 * G1 + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const cs = solid(g);
  const slab = [];
  for (const [x, y] of [[-6, -6], [X1 + 6, -6], [X1 + 6, 2 * RT + 6], [-6, 2 * RT + 6]]) slab.push(P(x, y, 0), P(x, y, CZ));
  cs.sil.setAttribute("d", poly(hull(slab)));

  const stacks = COUNTS.map((n, s) => {
    const x = RT + s * STEP, y = RT, grp = mk("g", {}, g), cups = [];
    for (let k = 0; k < n; k++) {
      const c = mk("g", {}, grp);
      cups.push({ sil: mk("path", { class: "sil" }, c), cr: mk("path", { class: "nf lo" }, c), band: mk("path", { class: "nf lo" }, c) });
    }
    const lid = mk("path", { class: "sil" }, grp), lidc = mk("path", { class: "nf lo" }, grp);
    return { s, n, x, y, cups, lid, lidc, gap: tween(RESTG[s]), last: NaN };
  });

  function draw(st, gap) {
    if (gap === st.last) return;
    st.last = gap;
    st.cups.forEach((c, k) => {
      const z0 = CZ + k * gap, z1 = z0 + H;
      const pts = ringAt(P, disc(st.x, st.y, RF), z0).concat(ringAt(P, disc(st.x, st.y, RT), z1));
      c.sil.setAttribute("d", poly(hull(pts)));
      c.cr.setAttribute("d", open(ringAt(P, run(disc(st.x, st.y, RT - 1.2), (q) => !front(q)), z1 - 0.4)));
      const rb = lerp3(RF, RT, 0.72);
      c.band.setAttribute("d", open(ringAt(P, run(disc(st.x, st.y, rb), front), z0 + H * 0.72)));
    });
    const zt = CZ + (st.n - 1) * gap + H;
    const lp = ringAt(P, disc(st.x, st.y, RT + 0.8), zt).concat(ringAt(P, disc(st.x, st.y, RT + 0.8), zt + 2.2), ringAt(P, disc(st.x, st.y, RT - 2.5), zt + 4.4));
    st.lid.setAttribute("d", poly(hull(lp)));
    st.lidc.setAttribute("d", poly(ringAt(P, disc(st.x - 3, st.y - 3, 1.6, 12), zt + 4.4)));
  }
  function lerp3(a, b, t) { return a + (b - a) * t; }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const st of stacks) { draw(st, tval(st.gap, now)); if (!tdone(st.gap, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = stacks.map((st) => P(st.x, st.y, CZ + H));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 34 && sy > mids[best][1] - 140 && sy < mids[best][1] + 50 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    stacks.forEach((st, k) => {
      const d = Math.abs(k - a), gp = a < 0 ? RESTG[k] : d === 0 ? G1 : G0 + 1.4;
      tset(st.gap, gp, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      st.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "stack " + (a + 1) + "·" + stacks[a].n;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "coffeecups",
  means: "Stacks of nested takeaway cups: the stack under the pointer draws apart like an accordion, cup by cup, under its lid.",
  rules: [1, 2, 5, 6],
