  tour: [[151, 160], [200, 114], [249, 209], null],
  mount,
});

cerealdispenser.code:
/**
 * Cereal dispenser: three tall canisters on a hotel breakfast stand, each on
 * a funnel neck with a three-spoke twist knob, a bowl waiting under each.
 * The pointer picks a canister by where it stands: its knob turns a third of
 * a turn and the canister tips forward on its pivot to pour, and the
 * canisters beside it tip a little, staggered from it. At rest the middle
 * canister leans half tipped, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), parts that tilt.
 */
const {
  Cam, circ, fit, hull, open, poly, prism, proj, rings, ringAt, facing, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 36, R = 13, Y = 20, PZ = 34, H = 50, TIP = 26, FAV = 1, L = 2 * 18 + 2 * STEP;
const REST = [3, 12, 0];
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [L, 46, 0], [L, 0, PZ + H + 8], [0, 0, PZ + H + 8], [0, 46, 0], [L, 46, 12], [L / 2, Y + 30, PZ + H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, 5, 2, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, PZ + H + 6));
  const [sr, si] = rings(0, 0, L, 46, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, 8));

  const cans = [0, 1, 2].map((k) => {
    const x = 18 + k * STEP, grp = mk("g", {}, g);
    const neck = mk("path", { class: "sil" }, grp), body = mk("path", { class: "sil" }, grp), top = mk("path", { class: "nf lo" }, grp);
    const level = mk("path", { class: "nf lo" }, grp), knob = mk("path", { class: "nf" }, grp);
    const bowl = mk("path", { class: "sil" }, grp), brim = mk("path", { class: "nf lo" }, grp);
    const bp = ringAt(P, disc(x, Y + 14, 8), 8).concat(ringAt(P, disc(x, Y + 14, 10), 15));
    bowl.setAttribute("d", poly(hull(bp)));
    brim.setAttribute("d", poly(ringAt(P, disc(x, Y + 14, 9), 15)));
    return { k, x, neck, body, top, level, knob, a: tween(REST[k]), last: NaN };
  });

  function draw(c, deg) {
    if (deg === c.last) return;
    c.last = deg;
    const t = (deg * Math.PI) / 180, cs = Math.cos(t), sn = Math.sin(t);
    const at = (ring, dz) => ring.map((q) => { const dy = q.v - Y; return P(q.u, Y + dy * cs + dz * sn, PZ - dy * sn + dz * cs); });
    c.neck.setAttribute("d", poly(hull(at(disc(c.x, Y, R - 1), 0).concat(at(disc(c.x, Y, 4), -12)))));
    c.body.setAttribute("d", poly(hull(at(disc(c.x, Y, R), 0).concat(at(disc(c.x, Y, R), H), at(disc(c.x, Y, R - 3), H + 3)))));
    c.top.setAttribute("d", poly(at(disc(c.x, Y, R - 1.5), H)));
    c.level.setAttribute("d", open(at(disc(c.x, Y, R - 0.6).filter(front), H * 0.62)));
    const turn = (deg / TIP) * (2 * Math.PI / 3), ky = Y + 7, kz = -7, spokes = [];
    for (let j = 0; j < 3; j++) {
      const u = turn + (j * 2 * Math.PI) / 3, dx = 7 * Math.cos(u), dz = 7 * Math.sin(u);
      const pt = (ddx, ddz) => { const dy = ky - Y; return P(c.x + ddx, Y + dy * cs + (kz + ddz) * sn, PZ - dy * sn + (kz + ddz) * cs); };
      spokes.push(seg(pt(0, 0), pt(dx, dz)));
    }
    c.knob.setAttribute("d", spokes.join(" "));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const c of cans) { draw(c, tval(c.a, now)); if (!tdone(c.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = cans.map((c) => P(c.x, Y, PZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 36 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    cans.forEach((c, k) => {
      const d = Math.abs(k - a), v = a < 0 ? REST[k] : d === 0 ? TIP : 5;
      tset(c.a, v, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      c.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bin " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "cerealdispenser",
  means: "Three cereal canisters on a breakfast stand: the one under the pointer twists its knob and tips forward to pour into its bowl.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[154, 117], [204, 142], [254, 167], null],
  mount,
});

beerkeg.code:
/**
 * Beer kegs: five kegs lying on their sides in a cellar, three on a pair of
 * timber rails and two nested on top. The pointer picks a keg by the rest
 * place of its front end: the keg slides out along its own length toward
 * the reader, and the kegs beside it ease out a little, staggered from it.
 * At rest one top keg sits half drawn, bright. The slider is the stagger.
 *
 * The pattern: stepped parts, picked on their rest pose, dynamic paint order.
 */
const {
  Cam, fit, hull, open, poly, prism, proj, rings, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 14, LEN = 46, OUT = 34, FAV = 3;
const KEGS = [[15, 0], [45, 0], [75, 0], [30, 1], [60, 1]].map(([x, t]) => ({ x, t, z: 3 + R + t * (R * 1.72) }));
const REST = [4, 0, 9, 16, 2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-2, 0, 0], [92, LEN + OUT, 0], [92, 0, 0], [-2, LEN + OUT, 0], [45, 0, 3 + 2 * R + R * 1.72 + R], [45, LEN + OUT, 3 + 2 * R + R * 1.72 + R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const y of [5, LEN - 11]) { const [r, i] = rings(-2, y, 92, y + 6, 1.5, 1); put(solid(g), prism(P, front, r, i, 0, 3)); }
  const hoop = (x, y, z, r, a0, a1, n = 24) => {
    const pts = [];
    for (let j = 0; j <= n; j++) { const a = a0 + ((a1 - a0) * j) / n; pts.push(P(x + r * Math.cos(a), y, z + r * Math.sin(a))); }
    return pts;
  };
  const kegs = KEGS.map((k, i) => {
    const grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp), ribs = mk("path", { class: "nf lo" }, grp);
    const end = mk("path", { class: "nf" }, grp), chime = mk("path", { class: "nf lo" }, grp);
    return { i, ...k, grp, body, ribs, end, chime, dy: tween(REST[i]), last: NaN, key: 0 };
  });

  function draw(k, dy) {
    if (dy === k.last) return;
    k.last = dy;
    const y0 = dy, y1 = dy + LEN, mid = (y0 + y1) / 2;
    const b = hoop(k.x, y0, k.z, R - 1.5, 0, 2 * Math.PI, 32).concat(hoop(k.x, y0 + 4, k.z, R, 0, 2 * Math.PI, 32), hoop(k.x, mid, k.z, R + 0.8, 0, 2 * Math.PI, 32), hoop(k.x, y1 - 4, k.z, R, 0, 2 * Math.PI, 32), hoop(k.x, y1, k.z, R - 1.5, 0, 2 * Math.PI, 32));
    k.body.setAttribute("d", poly(hull(b)));
    k.ribs.setAttribute("d", [y0 + 4, mid, y1 - 4].map((y, j) => open(hoop(k.x, y, k.z, j === 1 ? R + 0.8 : R, -0.6, Math.PI + 0.6))).join(" "));
    k.end.setAttribute("d", poly(hoop(k.x, y1, k.z, R - 1.5, 0, 2 * Math.PI, 32)));
    k.chime.setAttribute("d", poly(hoop(k.x, y1 + 0.1, k.z, 3, 0, 2 * Math.PI, 16)));
  }

  let order = "";
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const k of kegs) { const v = tval(k.dy, now); draw(k, v); k.key = v + (k.t ? 10 : 0) + k.x * 0.01; if (!tdone(k.dy, now)) moving = true; }
    const sorted = kegs.slice().sort((a, b) => a.key - b.key), o = sorted.map((k) => k.i).join();
    if (o !== order) { order = o; sorted.forEach((k) => g.appendChild(k.grp)); }
    return moving;
  });
  bag.add(B.unregister);

  const ends = kegs.map((k) => P(k.x, LEN, k.z));
  function hit([sx, sy]) {
    let best = -1, bd = R * 1.9 * 1.3;
    ends.forEach((m, i) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = i; } });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    kegs.forEach((k, i) => {
      const near = a >= 0 && Math.abs(k.x - kegs[a].x) <= 15 && i !== a;
      const v = a < 0 ? REST[i] : i === a ? OUT : near ? 6 : 0;
      tset(k.dy, v, now, from < 0 ? 0 : Math.abs(k.x - kegs[from].x) / 15 * stag);
      k.body.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "keg " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "beerkeg",
  means: "Five kegs lying stacked in a cellar: the keg under the pointer slides out along its length, its neighbours easing out after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[144, 162], [191, 186], [214, 152], null],
  mount,
});

fishnet.code:
/**
 * Fish net: a glass aquarium tank with water and two fish, and a hand net on
 * a long handle hinged above its right end. The pointer over the tank swings
 * the net down into the water, its hoop following the pointer along the
 * tank; leaving lifts it back out. At rest the net hangs poised above the
 * water, hoop bright. The slider is how deep it dips.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, clamp, lerp, rad, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 110, D = 50, H = 54, WZ = 42, HR = 22, L = 92;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let deep = value;
  const C = Cam(45, 0.5, 1.75);
  const PV = [W + 18, D / 2, H + 34];
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [0, 0, H], [PV[0] + 4, PV[1], PV[2] + 6], [10, D / 2, H + 60], [10, 0, H + 60], [10, D, H + 60]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // stand under the tank
  const [sr, si] = rings(-4, -4, W + 4, D + 4, 5, 1.5);
  put(solid(g), prism(P, front, sr, si, 0, 6));
  // glass tank: open, so the net reads through it
  const [tr] = rings(0, 0, W, D, 4, 1.5);
  const tank = prism(P, front, tr, tr, 6, 6 + H);
  mk("path", { d: tank.sil, class: "sil nf" }, g);
  mk("path", { d: poly(ringAt(P, tr, 6 + H)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, rings(1.5, 1.5, W - 1.5, D - 1.5, 3, 1)[0], 6 + WZ)), class: "nf lo" }, g);
  const fish = [[30, 30, 22], [70, 18, 30]].map(([x, y, z]) => {
    const body = [P(x - 7, y, 6 + z), P(x, y - 0.5, 6 + z + 3), P(x + 6, y, 6 + z), P(x, y + 0.5, 6 + z - 3)];
    const tail = [P(x + 6, y, 6 + z), P(x + 10, y, 6 + z + 3), P(x + 10, y, 6 + z - 3)];
    mk("path", { d: poly(body) + poly(tail), class: "nf lo" }, g);
    const e = P(x - 4, y, 6 + z + 0.6); return mk("circle", { cx: e[0], cy: e[1], r: 1.2, class: "dot off" }, g);
  });
  // the net
  const handle = mk("path", { class: "nf" }, g), pocket = mk("path", { class: "nf lo" }, g), hoop = mk("path", { class: "sil nf hi" }, g);
  const pv = P(...PV); const pin = mk("circle", { cx: pv[0], cy: pv[1], r: 2, class: "dot m" }, g);
  const th = spring(-8), hy = spring(D / 2);
  let lt = NaN, ly = NaN;
  function draw(t, y) {
    if (t === lt && y === ly) return; lt = t; ly = y;
    const a = rad(t), cx = PV[0] - L * Math.cos(a), cz = Math.max(24, PV[2] - L * Math.sin(a));
    const cy = lerp(PV[1], y, clamp((t + 8) / 50, 0, 1));
    const hp = ringAt(P, disc(cx, cy, HR), 6 + cz);
    const bag2 = ringAt(P, disc(cx + 2, cy, HR * 0.5, 16), 6 + cz - 22);
    pocket.setAttribute("d", poly(hull(hp.concat(bag2))) + open(hull(bag2)));
    hoop.setAttribute("d", poly(hp));
    const e = P(cx + HR, cy, 6 + cz);
    handle.setAttribute("d", open([e, pv]));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt) | stepS(hy, dt); draw(th.x, hy.x); return !!m; });
  bag.add(B.unregister);
  let on = null;
  function set(t, y, a) {
    th.t = t; hy.t = y;
    if (a !== on) { on = a; fish.forEach((f) => f.setAttribute("class", a ? "dot m" : "dot off")); }
    read.textContent = a ? "dip " + Math.round(t + 8) : "rest";
    B.wake();
  }
  draw(-8, D / 2); set(-8, D / 2, false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, 0);
      if (x < -30 || x > W + 30 || y < -30 || y > D + 30) return set(-8, D / 2, false);
      const k = clamp(1 - Math.abs(x - W * 0.4) / (W * 0.9), 0.2, 1);
      set(Math.round(-8 + (deep + 8) * k), clamp(y, 14, D - 14), true);
    },
    leave: () => set(-8, D / 2, false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { deep = v; }, destroy: bag.dispose };
}

hairline({
  name: "fishnet",
  means: "A hand net hinged over a glass fish tank: the pointer over the tank swings the net down into the water, following along.",
  rules: [1, 3, 5, 8],
  range: [20, 46, 50],
  tour: [[107, 200], [186, 240], [268, 281], null],
  mount,
});

litterbox.code:
/**
 * Litter tray: a low cat tray with a hooded cover and a door in its front.
 * The pointer's distance along the tray lifts the hood off its base on a
 * spring, tilting back as it rises, to show the litter heaped inside. At rest
 * the hood sits a little ajar, its rim bright. The slider is the lift.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, clamp, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 90, D = 60, TZ = 14, HZ = 46, REST = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxL = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [0, 0, TZ + HZ + 40], [W, 0, TZ + HZ + 40]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // tray base
  const [tr, ti] = rings(0, 0, W, D, 10, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  // litter heap inside the tray
  const heap = [];
  for (const [b, z] of [[5, 0], [14, 4], [26, 7]]) heap.push(...ringAt(P, rrect(b, b * 0.7, W - b, D - b * 0.7, 8, 4), TZ + z - 2));
  const lit = mk("path", { d: poly(hull(heap)), class: "nf lo" }, g);
  const grains = [[30, 26], [52, 34], [64, 22], [40, 40]].map(([x, y]) => { const p = P(x, y, TZ + 6); return mk("circle", { cx: p[0], cy: p[1], r: 1.4, class: "dot off" }, g); });
  // hood
  const hood = solid(g), door = mk("path", { class: "nf lo" }, g), vent = mk("path", { class: "nf lo" }, g);
  const foot = rrect(1, 1, W - 1, D - 1, 10, 4), top = rrect(12, 9, W - 12, D - 9, 12, 4), inner = rrect(14, 11, W - 14, D - 11, 10, 4);
  const lift = spring(REST);
  let last = NaN;
  function draw(l) {
    if (l === last) return; last = l;
    const tilt = l * 0.35; // back edge rises less: the hood hinges at the back (low y)
    const R = (ring, z) => ring.map((q) => { const zz = z + l - tilt * (1 - q.v / D); return P(q.u, q.v, zz); });
    const fp = R(foot, TZ), tp = R(top, TZ + HZ);
    hood.sil.setAttribute("d", poly(hull(fp.concat(tp))));
    hood.cr.setAttribute("d", open(R(run(inner, front), TZ + HZ)));
    // door: a rounded arch on the front face (+y)
    const dr = [];
    for (let i = 0; i <= 10; i++) { const a = Math.PI * i / 10; dr.push([W / 2 + 14 * Math.cos(a), D - 1 + 7 * (1 - Math.sin(a)) * 0, 4 + 22 * Math.sin(a)]); }
    const ty = (q) => P(q[0] - (q[2] / HZ) * 0, q[1] - (q[2] / HZ) * 7, TZ + q[2] + l - tilt);
    door.setAttribute("d", poly(dr.map(ty)));
    const vz = TZ + HZ + l - tilt * 0.5;
    vent.setAttribute("d", poly(ringAt(P, rrect(W / 2 - 12, D / 2 - 4, W / 2 + 12, D / 2 + 4, 4, 3), vz)));
  }
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);
  let on = false;
  function setT(t, a) {
    lift.t = t;
    if (a !== on) { on = a; hood.sil.classList.toggle("hi", true); grains.forEach((c) => c.setAttribute("class", a ? "dot m" : "dot off")); }
    read.textContent = a ? "lid " + Math.round((t / maxL) * 100) : "rest";
    B.wake();
  }
  hood.sil.classList.add("hi");
  draw(REST); setT(REST, false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, 0);
      const inside = x > -40 && x < W + 40 && y > -40 && y < D + 40;
      if (!inside) return setT(REST, false);
      const t = clamp(1 - Math.hypot(x - W / 2, y - D / 2) / 70, 0.15, 1);
      setT(Math.round(maxL * t), true);
    },
    leave: () => setT(REST, false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxL = v; }, destroy: bag.dispose };
}

hairline({
  name: "litterbox",
  means: "A hooded cat litter tray: the hood lifts and tips back off its base as the pointer nears the middle, showing the litter.",
  rules: [1, 3, 5, 8],
  range: [10, 34, 40],
  tour: [[94, 199], [200, 252], [285, 209], null],
  mount,
});

bowlingreturn.code:
/**
 * Ball return: the hood where balls come back from the pit, and two rails
 * running out of it with four balls resting on them, spread unevenly. The
 * pointer picks a ball by where it stands: the others roll along the rails to
 * close up against it, the nearest first, their finger holes turning as they
 * roll. At rest one ball stands apart, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), rolling to gather.
 */
const {
  Cam, fit, facing, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, R = 10, LEN = 150, D = 2 * R + 1, CZ = 19, FAV = 3;
const REST = [14, 44, 68, 128];
const HOLES = [[0.35, 0.25], [0.35, -0.25], [0.75, 0]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-26, -18, 0], [LEN + 10, 16, 0], [LEN + 10, -16, 0], [-26, 18, 0], [-26, -18, 34], [LEN, 0, CZ + R]], 200, 168);
  const P = proj(C), front = facing(C), S = 1.95;
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, par = g) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(par), prism(P, front, o, i, z0, z1)); };
  block(-26, -18, -2, 18, 9, 2, 0, 34);
  block(-8, -14, LEN + 10, 14, 6, 1.5, 0, 8);
  block(0, -9, LEN, -5, 2, 0.8, 8, 12);
  const balls = mk("g", {}, g);
  block(0, 5, LEN, 9, 2, 0.8, 8, 12);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, balls);
    const body = mk("ellipse", { class: "sil", rx: R * S, ry: R * S }, grp);
    const holes = HOLES.map(() => mk("ellipse", { class: "nf lo", rx: 1.6, ry: 1.6 }, grp));
    items.push({ k, grp, body, holes, x: tween(REST[k]), last: NaN });
  }

  function draw(it, x) {
    if (x === it.last) return;
    it.last = x;
    const c = P(x, 0, CZ);
    it.body.setAttribute("cx", c[0]); it.body.setAttribute("cy", c[1]);
    const a = x / R + it.k * 1.3;
    HOLES.forEach(([el, off], j) => {
      // a hole on the sphere: rolling about the y axis turns it in the x-z plane
      const t = a + off, e = Math.cos(el), hx = Math.cos(t) * e, hz = Math.sin(t) * e, hy = Math.sin(el) * (j === 2 ? 0.3 : 1) * 0.6;
      const q = P(x + hx * R, hy * R, CZ + hz * R), vis = hx + hy > -0.1;
      it.holes[j].setAttribute("cx", q[0]); it.holes[j].setAttribute("cy", q[1]);
      it.holes[j].setAttribute("rx", vis ? 1.6 : 0); it.holes[j].setAttribute("ry", vis ? 1.6 : 0);
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.x, now)); if (!tdone(it.x, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = REST.map((x) => P(x, 0, CZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 40 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const lo = a < 0 ? 0 : Math.min(Math.max(REST[a] - a * D, R), LEN - R - (N - 1) * D);
    items.forEach((it, k) => {
      tset(it.x, a < 0 ? REST[k] : lo + k * D, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "ball " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "bowlingreturn",
  means: "A ball return with four balls on its rails: the others roll along the rails to close up against the ball under the pointer.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[128, 112], [170, 133], [285, 190], null],
  mount,
});

curlingstones.code:
/**
 * Curling stones: four granite stones waiting at the near end of a short
 * sheet of ice, the house drawn as rings at the far end. The pointer picks a
 * stone by where it stands: it slides up the ice toward the house, its handle
 * turning as it goes, and the stones beside it creep a little after it,
 * staggered from it. At rest one stone is already part-way out, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), sliding.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 30, R = 12, Y0 = 46, SLIDE = 56, FAV = 2, IZ = 3;
const REST = [6, 0, 24, 3];
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, x, y, a) => ring.map((q) => {
  const c = Math.cos(a), s = Math.sin(a);
  return { ...q, u: x + q.u * c - q.v * s, v: y + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c };
});

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const X0 = -R - 6, X1 = (N - 1) * STEP + R + 6, YA = -42, YB = Y0 + R + 6;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[X0, YA, 0], [X1, YA, 0], [X0, YB, 0], [X1, YB, 0], [X1, YA, 20]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ir, ii] = rings(X0, YA, X1, YB, 6, 2);
  put(solid(g), prism(P, front, ir, ii, 0, IZ));
  // the house: rings on the ice at the far end, and the hog line across it
  const HX = (N - 1) * STEP / 2, HY = -14;
  for (const r of [22, 14, 6]) mk("path", { d: poly(ringAt(P, disc(HX, HY, r, 48), IZ)), class: "nf lo" }, g);
  mk("path", { d: poly([P(X0 + 4, 20, IZ), P(X1 - 4, 20, IZ)]), class: "nf dash" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const body = solid(grp), band = mk("path", { class: "nf lo" }, grp), handle = solid(grp);
    items.push({ k, x: k * STEP, grp, body, band, handle, s: tween(REST[k]), last: NaN });
  }
  const hbar = rrect(-7, -2, 7, 2, 2, 3), hin = rrect(-6, -1, 6, 1, 1, 3);

  function draw(it, s) {
    if (s === it.last) return;
    it.last = s;
    const y = Y0 - s, a = rad(-20 + s * 2.2);
    put(it.body, prism(P, front, disc(it.x, y, R), disc(it.x, y, R - 2), IZ, IZ + 9));
    it.band.setAttribute("d", poly(ringAt(P, disc(it.x, y, R - 0.2, 36), IZ + 5)));
    const ring = turn(hbar, it.x, y, a), inner = turn(hin, it.x, y, a);
    const pts = ringAt(P, disc(it.x, y, 3, 12), IZ + 9).concat(ringAt(P, ring, IZ + 13));
    it.handle.sil.setAttribute("d", poly(hull(pts)));
    it.handle.cr.setAttribute("d", poly(ringAt(P, inner, IZ + 13)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.s, now)); if (!tdone(it.s, now)) moving = true; }
    // paint order: farther (smaller x + y) first
    const order = items.slice().sort((p, q) => (p.x + Y0 - p.last) - (q.x + Y0 - q.last));
    for (const it of order) g.appendChild(it.grp);
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, Y0, IZ + 6));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && sy > mids[best][1] - 90 && sy < mids[best][1] + 30 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), s = a < 0 ? REST[k] : dd === 0 ? SLIDE : dd === 1 ? 14 : 4;
      tset(it.s, s, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "stone " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "curlingstones",
  means: "Four curling stones on the ice: the stone under the pointer slides toward the house, handle turning, and its neighbours creep after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[90, 143], [131, 164], [214, 205], null],
  mount,
});

feedbins.code:
/**
 * Feed bins: four lidded grain bins in a row against a barn wall. The
 * pointer picks a bin by where it stands: its lid swings up on the back
 * hinge to show the grain, and the lids beside it crack open, staggered
 * from it. At rest one lid is propped half open, bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row (riffle), answered by a hinge.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rad, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 34, GAP = 7, D = 34, H = 30, OPEN = 104, FAV = 2, REST = 72;
const X1 = N * W + (N - 1) * GAP;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-4, -4, 0], [X1 + 4, D + 4, 0], [X1 + 4, -4, 0], [-4, D + 4, 0], [0, -4, H + D + 4], [X1, -4, H + D + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-4, -4, X1 + 4, D + 4, 4, 1.6);
  put(solid(g), prism(P, front, fr, fi, 0, 2));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * (W + GAP), x1 = x0 + W, grp = mk("g", {}, g);
    const [br, bi] = rings(x0, 0, x1, D, 3, 2);
    put(solid(grp), prism(P, front, br, bi, 2, H));
    // the grain: a low heap inside the mouth
    const heap = [];
    for (const [u, v, z] of [[4, 6, 0], [W - 4, 6, 0], [W - 4, D - 5, 0], [4, D - 5, 0], [W / 2 - 4, D / 2, 4], [W / 2 + 4, D / 2 - 3, 4]]) heap.push(P(x0 + u, v, H - 3 + z));
    mk("path", { d: poly(hull(heap)), class: "nf lo" }, grp);
    const lid = mk("path", { class: "sil" }, grp), face = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, x1, lid, face, a: tween(k === FAV ? REST : 0), last: NaN });
  }

  // the lid: a thin plate hinged on the back edge, at angle a above the mouth
  function lidPt(x, l, t, a) {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return P(x, -1 + l * c - t * s, H + l * s + t * c);
  }
  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const xs = [it.x0 - 1, it.x1 + 1], ls = [0, D + 2], pts = [];
    for (const x of xs) for (const l of ls) for (const t of [0, 2]) pts.push(lidPt(x, l, t, a));
    it.lid.setAttribute("d", poly(hull(pts)));
    const top = [lidPt(xs[0] + 2, 1.5, 2, a), lidPt(xs[1] - 2, 1.5, 2, a), lidPt(xs[1] - 2, D, 2, a), lidPt(xs[0] + 2, D, 2, a)];
    it.face.setAttribute("d", poly(top));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, D / 2, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 34 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? (k === FAV ? REST : 0) : dd === 0 ? OPEN : dd === 1 ? 14 : 0;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bin " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "feedbins",
  means: "Four grain bins in a row: the lid of the bin under the pointer swings up on its hinge to show the feed, its neighbours crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[125, 162], [175, 187], [275, 236], null],
  mount,
});

egglamp.code:
/**
 * Egg candler: a round lamp housing with a cup collar on top, one big egg
 * standing in the cup with the lamp shining through it, so its air cell and
 * yolk show as dim lines. The pointer turns the egg in the cup, tilting it
 * toward its side on a spring. At rest the egg leans a little and the cup
 * collar is bright. The slider is how far the egg may tilt.
 *
 * The pattern: one part turning toward the pointer (officechairs).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HR = 32, HZ = 40, CR = 15, CZ = 6, EH = 74, ER = 25, REST = 18;
const disc = (r, n = 40) => circ(r, n);
const Q = Math.SQRT1_2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = 25 + value / 2;
  const C = Cam(45, 0.5, 2.15);
  const top = HZ + CZ;
  fit(C, [[-HR - 4, -HR - 4, 0], [HR + 4, HR + 4, 0], [HR + 4, -HR - 4, 0], [-HR - 4, HR + 4, 0], [0, 0, top + EH], [60 * Q, -60 * Q, top + 30], [-60 * Q, 60 * Q, top + 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-HR - 4, -HR - 4, HR + 4, HR + 4, HR + 4, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  put(solid(g), prism(P, front, disc(HR), disc(HR - 2.2), 3, HZ));
  const collar = solid(g);
  put(collar, prism(P, front, disc(CR + 3, 32), disc(CR, 32), HZ, top));
  collar.sil.classList.add("hi");

  const egg = mk("path", { class: "sil" }, g), cell = mk("path", { class: "nf lo" }, g), yolk = mk("path", { class: "nf lo" }, g);
  const tilt = spring(REST);
  let last = NaN;
  // a point at axial s (-1 low tip .. 1 blunt top) and ring angle w, for tilt t (deg) toward screen right
  function frame(t) {
    const a = (t * Math.PI) / 180, sn = Math.sin(a), cs = Math.cos(a);
    const ax = [sn * Q, -sn * Q, cs], e1 = [cs * Q, -cs * Q, -sn], e2 = [Q, Q, 0];
    const piv = [0, 0, top - 2], c0 = EH / 2 - 8;
    return (s, w, rr) => {
      const al = c0 + (s * EH) / 2, r = rr ?? ER * Math.sqrt(Math.max(0, 1 - s * s)) * (1 + 0.14 * s);
      const cw = Math.cos(w) * r, sw = Math.sin(w) * r;
      return P(piv[0] + ax[0] * al + e1[0] * cw + e2[0] * sw, piv[1] + ax[1] * al + e1[1] * cw + e2[1] * sw, piv[2] + ax[2] * al + e1[2] * cw + e2[2] * sw);
    };
  }
  function draw(t) {
    const tr = Math.round(t * 10) / 10;
    if (tr === last) return;
    last = tr;
    const F = frame(tr), pts = [];
    for (let i = 0; i <= 16; i++) { const s = -1 + (2 * i) / 16; for (let j = 0; j < 24; j++) pts.push(F(s, (j / 24) * 2 * Math.PI)); }
    egg.setAttribute("d", poly(hull(pts)));
    const ring = [];
    for (let j = 0; j < 28; j++) ring.push(F(0.66, (j / 28) * 2 * Math.PI));
    cell.setAttribute("d", poly(ring));
    const yp = [];
    for (let j = 0; j < 20; j++) { const w = (j / 20) * 2 * Math.PI; for (const s of [-0.12, -0.02, 0.08]) yp.push(F(s, w, 8 * Math.sqrt(1 - ((s + 0.02) / 0.14) ** 2 * 0.5))); }
    yolk.setAttribute("d", poly(hull(yp)));
  }

  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(tilt.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  const mid = P(0, 0, top + EH / 3);
  let on = false;
  function move([sx, sy]) {
    const inside = Math.abs(sx - mid[0]) < 120 && sy > mid[1] - 110 && sy < mid[1] + 130;
    if (inside) {
      const t = clamp((sx - mid[0]) / 90, -1, 1) * maxT;
      tilt.t = t;
      read.textContent = (t >= 0 ? "+" : "") + Math.round(t) + "°";
    }
    setOn(inside);
    B.wake();
  }
  function setOn(v) {
    if (!v) { tilt.t = REST; read.textContent = "rest"; }
    if (v === on) return;
    on = v;
    egg.classList.toggle("hi", v);
    collar.sil.classList.toggle("hi", !v);
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { setOn(false); B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = 25 + v / 2; }, destroy: bag.dispose };
}

hairline({
  name: "egglamp",
  means: "An egg on a candling lamp, its air cell and yolk lit through the shell: the pointer turns the egg in its cup toward its side.",
  rules: [1, 3, 5, 8],
  range: [0, 45, 90],
  tour: [[124, 109], [230, 83], [276, 109], null],
  mount,
});

fencepost.code:
/**
 * Gate latch: a farm gate hung between two posts, a latch bar on the far
 * post. The pointer stands on the ground behind the gate and the gate
 * swings back round its hinge into the paddock toward it, on a spring. At rest the gate
 * hangs a little ajar and the latch is bright. The slider is how wide the
 * gate may swing.
 *
 * The pattern: one part turning toward the pointer (officechairs).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 92, Z0 = 6, Z1 = 40, PH = 48, REST = 16;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = 40 + value / 2;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-30, -12, 0], [L + 14, -12, 0], [-12, -L - 8, 0], [L + 14, 14, 0], [0, 0, PH + 3], [L * 0.7, -L * 0.7, Z1], [-30, 0, 30]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-30, -12, L + 14, 16, 6, 2);
  put(solid(g), prism(P, front, gr, gi, 0, 2));
  const gate = mk("g", {}, g);
  const plate = mk("path", { class: "sil" }, gate), inner = mk("path", { class: "nf lo" }, gate);
  // a stub of fence running off behind the hinge post
  mk("path", { d: seg(P(-30, 0, 22), P(-3, 0, 22)) + seg(P(-30, 0, 34), P(-3, 0, 34)), class: "nf lo" }, g);
  put(solid(g), prism(P, front, disc(-24, 0, 3), disc(-24, 0, 1.6), 2, 38));
  put(solid(g), prism(P, front, disc(0, 0, 4.2), disc(0, 0, 2.4), 2, PH));
  put(solid(g), prism(P, front, disc(L + 6, 0, 4.2), disc(L + 6, 0, 2.4), 2, PH - 2));
  // the latch: a short bar on the far post, the rest mark
  const latch = solid(g);
  const [lr, li] = rings(L - 1, -1.4, L + 3, 1.4, 1, 0.5);
  put(latch, prism(P, front, lr, li, 27, 30));
  latch.sil.classList.add("hi");

  const ang = spring(REST);
  let last = NaN;
  function W(u, z, t, c, s) { return P(u * c + t * s, -u * s + t * c, z); }
  function draw(a) {
    const r2a = Math.round(a * 10) / 10;
    if (r2a === last) return;
    last = r2a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a)), pts = [];
    for (const u of [4.5, L - 1.5]) for (const z of [Z0, Z1]) for (const t of [-1, 1]) pts.push(W(u, z, t, c, s));
    plate.setAttribute("d", poly(hull(pts)));
    let d = poly([W(8, Z0 + 3, 0, c, s), W(L - 5, Z0 + 3, 0, c, s), W(L - 5, Z1 - 3, 0, c, s), W(8, Z1 - 3, 0, c, s)]);
    for (const z of [15, 23.5, 31.5]) d += seg(W(8, z, 0, c, s), W(L - 5, z, 0, c, s));
    d += seg(W(8, Z0 + 3, 0, c, s), W(L - 5, Z1 - 3, 0, c, s));
    inner.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  let on = false;
  function move([sx, sy]) {
    const [gx, gy] = unproj(C, sx, sy, 0), dist = Math.hypot(gx, gy);
    const inside = dist < L + 30 && gx > -10 && gy < 20;
    if (inside) {
      const a = clamp(Math.atan2(-gy, gx) * 180 / Math.PI, 0, maxA);
      ang.t = a;
      read.textContent = Math.round(a) + "°";
    }
    setOn(inside);
    B.wake();
  }
  function setOn(v) {
    if (!v) { ang.t = REST; read.textContent = "rest"; }
    if (v === on) return;
    on = v;
    plate.classList.toggle("hi", v);
    latch.sil.classList.toggle("hi", !v);
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { setOn(false); B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = 40 + v / 2; }, destroy: bag.dispose };
}

hairline({
  name: "fencepost",
  means: "A farm gate between two posts: it swings on its hinge to point at the pointer, and settles back ajar with the latch lit.",
  rules: [1, 3, 5, 8],
  range: [0, 45, 90],
  tour: [[265, 231], [260, 174], [248, 131], null],
  mount,
});

ballot2.code:
/**
 * Petition box: a boxed ballot with a hinged lid and a sign on a post. The
 * pointer's nearness swings the lid open on its back hinge (a spring), so the
 * box opens toward a hand reaching for it. At rest the lid sits ajar.
 */
const {
  Cam, facing, fit, prism, proj, rings, rrect, hull, poly, open, unproj, clamp, rad,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = -30, X1 = 30, Y0 = -22, Y1 = 22, H = 40, D = 46, TH = 3, REST = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  let MAX = 78 * value;
  fit(C, [[X0, Y0, 0], [X1, Y1, 0], [X1, Y0, H + D], [X0, Y0, H + D], [56, 20, 54], [X0, Y1, 0]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [ring, inner] = rings(X0, Y0, X1, Y1, 4, 1.6);
  put(solid(g), prism(P, front, ring, inner, 0, H));
  const slot = rings(-14, -2, 14, 2, 1.5, 0.5)[0];
  mk("path", { class: "lo nf", d: poly(slot.map((q) => P(q.u, q.v, H))) }, g);

  const lid = solid(g);
  const LR = rrect(X0 - 2, 0, X1 + 2, D, 4, 4), LI = rrect(X0 + 1, 3, X1 - 1, D - 3, 2.5, 4);
  const LS = rrect(-14, D / 2 - 2, 14, D / 2 + 2, 1.5, 3);
  const slotLid = mk("path", { class: "lo nf", d: "" }, g);
  const sp = spring(rad(REST));
  let drawn = NaN;
  const pt = (q, a, w) => {
    const c = Math.cos(a), s = Math.sin(a);
    return P(q.u, Y0 - 2 + q.v * c - w * s, H + q.v * s + w * c);
  };
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const pts = LR.map((q) => pt(q, a, 0)).concat(LR.map((q) => pt(q, a, TH)));
    put(lid, { sil: poly(hull(pts)), crease: poly(LI.map((q) => pt(q, a, TH))) });
    slotLid.setAttribute("d", poly(LS.map((q) => pt(q, a, TH))));
  }

  const sign = mk("g", {}, svg);
  const post = rings(45, 17.5, 47, 19.5, 0.8, 0.3), plate = rings(37, 17, 55, 20, 1.2, 0.6);
  put(solid(sign), prism(P, front, post[0], null, 0, 34));
  const pl = solid(sign);
  put(pl, prism(P, front, plate[0], plate[1], 32, 54));

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(open01) {
    sp.t = rad(open01 == null ? REST : REST + (MAX - REST) * open01);
    lid.sil.classList.toggle("hi", true);
    read.textContent = open01 == null ? "rest" : "lid " + Math.round((sp.t * 180) / Math.PI) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y);
      set(d > 95 ? null : clamp(1 - (d - 20) / 60, 0, 1));
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  draw();
  return { set: (v) => { MAX = 78 * v; }, destroy: bag.dispose };
}

hairline({
  name: "ballot2",
  means: "A petition box with a sign on a post: the hinged lid swings open as the pointer comes near.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.2],
  tour: [[113, 227], [200, 253], [183, 297], null],
  mount,
});

podium2.code:
/**
 * Lectern: a speaker's lectern on a low dais, a slanted reading desk on a
 * column, a gooseneck microphone at its front edge. The pointer is the
 * audience: the lectern swivels on its base, on one spring, to face it. At
 * rest it stands a little askew, its desk bright.
 */
const {
  Cam, facing, fit, prism, proj, rings, hull, poly, open, run, seg, unproj, rad,
  spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const BZ = 5, CZ = 8, DZ = 46, REST = rad(62);
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  const ext = [[-38, -30, 0], [38, 30, 0], [38, -30, 0], [-38, 30, 0], [0, 0, 70]];
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const dais = rings(-38, -30, 38, 30, 6, 1.8);
  put(solid(g), prism(P, front, dais[0], dais[1], 0, BZ));

  const BASE = rings(-13, -16, 13, 16, 3, 1.2), COL = rings(-8, -12, 8, 12, 2.5, 1);
  const DESK = rings(-13, -17, 13, 17, 2.5, 1.4);
  const base = solid(g), col = solid(g), desk = solid(g);
  const micG = mk("g", {}, g);
  const stalk = mk("path", { class: "nf sil", d: "" }, micG);
  const head = flatDot(micG, C, 1.8, "dot m");
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, micFirst = null;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a);
    const W = (u, v, z) => P(u * c - v * s, u * s + v * c, z);
    const T = (r) => r.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
    put(base, prism(P, front, T(BASE[0]), T(BASE[1]), BZ, CZ));
    put(col, prism(P, front, T(COL[0]), null, CZ, DZ));
    const top = (q) => DZ + 5 + 0.3 * q.u;
    const pts = DESK[0].map((q) => W(q.u, q.v, DZ)).concat(DESK[0].map((q) => W(q.u, q.v, top(q))));
    put(desk, { sil: poly(hull(pts)), crease: poly(DESK[1].map((q) => W(q.u, q.v, top(q)))) });
    const m0 = W(11, 0, top({ u: 11 })), m1 = W(9, 0, DZ + 13), m2 = W(4, 0, DZ + 18);
    stalk.setAttribute("d", seg(m0, m1) + seg(m1, m2));
    place(head, m2);
    const mf = c + s < 0;
    if (mf !== micFirst) { micFirst = mf; if (mf) desk.g.before(micG); else desk.g.after(micG); }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (p) sp.t = sp.t + wrap(Math.atan2(p[1], p[0]) - sp.t);
    else sp.t = sp.t + wrap(REST - sp.t);
    desk.sil.classList.add("hi");
    const deg = Math.round(((sp.t * 180) / Math.PI % 360 + 360) % 360);
    read.textContent = p ? "face " + deg + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y);
      aim(d < 8 || d > 120 ? null : [x, y]);
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "podium2",
  means: "A lectern on a dais: it swivels on its base to face the pointer, as a speaker turns to the audience.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[142, 148], [103, 245], [336, 226], null],
  mount,
});

passportbook.code:
/**
 * Stamp desk: an official's desk with an ink pad and an open document, and a
 * hand stamp. The stamp glides after the pointer across the desk on springs,
 * and presses down when it is over the document. At rest it waits lifted over
 * the ink pad, bright.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, clamp,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const TZ = 6, PAD = [-34, -18], DOC = [-8, -20, 34, 18];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const box = (x, y, w, d, r, b) => rings(x - w, y - d, x + w, y + d, r, b);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-52, -36, 0], [52, 36, 0], [52, -36, 0], [-52, 36, 0], [-34, -18, 40]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const desk = rings(-52, -36, 52, 36, 6, 2);
  put(solid(g), prism(P, front, desk[0], desk[1], 0, TZ));
  const pad = box(PAD[0], PAD[1], 9, 7, 2, 1.2);
  put(solid(g), prism(P, front, pad[0], pad[1], TZ, TZ + 3));
  const doc = rings(DOC[0], DOC[1], DOC[2], DOC[3], 1.5, 0.8);
  put(solid(g), prism(P, front, doc[0], null, TZ, TZ + 0.8));
  let lines = seg(P(DOC[0] + 21, DOC[1] + 1, TZ + 0.8), P(DOC[0] + 21, DOC[3] - 1, TZ + 0.8));
  for (let i = 0; i < 4; i++) { const y = DOC[1] + 7 + i * 7; lines += seg(P(DOC[0] + 4, y, TZ + 0.8), P(DOC[0] + 17, y, TZ + 0.8)); }
  mk("path", { class: "lo nf", d: lines }, g);

  const block = solid(g), stem = solid(g), knob = solid(g);
  const LIFT = 16;
  const sx = spring(PAD[0]), sy = spring(PAD[1]), sh = spring(TZ + 3 + 9);
  let drawn = "";
  function draw() {
    const x = sx.x, y = sy.x, h = sh.x, key = x.toFixed(3) + y.toFixed(3) + h.toFixed(3);
    if (key === drawn) return;
    drawn = key;
    const b = box(x, y, 9, 8, 2, 1);
    put(block, prism(P, front, b[0], b[1], h, h + 6));
    put(stem, prism(P, front, disc(x, y, 1.8), null, h + 6, h + 17));
    put(knob, prism(P, front, disc(x, y, 6, 32), disc(x, y, 4.8, 32), h + 17, h + 23));
  }
  const B = register(stage, (dt) => {
    const m = [sx, sy, sh].map((s) => stepS(s, dt)).some(Boolean);
    draw();
    return m;
  });
  bag.add(B.unregister);

  function go(p) {
    let tag = "rest";
    if (!p) { sx.t = PAD[0]; sy.t = PAD[1]; sh.t = TZ + 12; }
    else {
      const x = clamp(p[0], -44, 44), y = clamp(p[1], -29, 29);
      const on = x > DOC[0] + 4 && x < DOC[2] - 4 && y > DOC[1] + 3 && y < DOC[3] - 3;
      sx.t = x; sy.t = y; sh.t = on ? TZ + 0.8 : TZ + LIFT * value;
      tag = on ? "stamp" : "lift";
    }
    block.sil.classList.add("hi");
    read.textContent = tag;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TZ);
      go(Math.abs(x) > 70 || Math.abs(y) > 55 ? null : [x, y]);
    },
    leave: () => go(null),
  }));
  bag.add(() => svg.replaceChildren());
  go(null);
  draw();
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "passportbook",
  means: "A stamp desk: the hand stamp glides after the pointer and presses down on the document when it is over it.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.4],
  tour: [[80, 171], [226, 209], [222, 247], null],
  mount,
});

heatpump.code:
/**
 * Heat pump: an outdoor unit, a rounded cabinet on two feet with louvres on
 * its long side and two fans in round openings on its top. The pointer picks
 * a fan by where it is along the top: its four blades turn an eighth of a
 * revolution, the other fan turns a little after it. At rest the blades sit
 * at odd angles and the first fan's ring is bright. The slider is the stagger.
 *
 * The pattern: one of two, picked on a fixed plane through the cabinet's top.
 */
const {
  Cam, circ, facing, fillet, fit, poly, prism, proj, rad, rings, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 72, Y1 = 34, TOP = 30, FX = [18, 54], FY = 17, R = 14;
const REST = [10, 47], FAV = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [0, 0, TOP], [X1, Y1, TOP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // two feet, then the cabinet
  [6, X1 - 10].forEach((x) => { const [fr, fi] = rings(x, 2, x + 4, Y1 - 2, 1.2, 0.5); put(solid(g), prism(P, front, fr, fi, 0, 3)); });
  const [cr, ci] = rings(0, 0, X1, Y1, 6, 1.8);
  const cab = solid(g);
  put(cab, prism(P, front, cr, ci, 3, TOP));
  let lv = "";
  for (let z = 8; z <= TOP - 5; z += 3.4) lv += seg(P(8, Y1, z), P(X1 - 8, Y1, z));
  mk("path", { class: "nf lo", d: lv }, cab.g);

  const fans = FX.map((x, k) => {
    const fg = mk("g", {}, g);
    const ring = mk("path", { class: "nf sil", d: poly(circ(R, 32).map((s) => P(x + s.u, FY + s.v, TOP))) }, fg);
    mk("path", { class: "nf lo", d: poly(circ(R - 2.5, 32).map((s) => P(x + s.u, FY + s.v, TOP - 1))) }, fg);
    const blades = mk("path", { class: "" }, fg);
    mk("path", { class: "", d: poly(circ(2.4, 16).map((s) => P(x + s.u, FY + s.v, TOP - 0.5))) }, fg);
    return { x, ring, blades, a: tween(REST[k]), last: NaN };
  });

  // a blade: a swept paddle from the hub to the rim, in the plane just under the top
  const shape = fillet([[1.5, -3], [11.5, -7.5], [12.5, 2], [2, 3]], [1, 3.5, 3, 1], 3);
  function draw(f, deg) {
    if (deg === f.last) return;
    f.last = deg;
    let d = "";
    for (let b = 0; b < 4; b++) {
      const t = rad(deg + b * 90), c = Math.cos(t), s = Math.sin(t);
      d += poly(shape.map(([u, v]) => P(f.x + u * c - v * s, FY + u * s + v * c, TOP - 0.8)));
    }
    f.blades.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    fans.forEach((f) => { draw(f, tval(f.a, now)); if (!tdone(f.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP);
    if (x < -3 || x > X1 + 3 || y < -3 || y > Y1 + 3) return -1;
    return x < X1 / 2 ? 0 : 1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    fans.forEach((f, k) => {
      tset(f.a, a < 0 ? REST[k] : REST[k] + (k === a ? 45 : 30), now, from < 0 ? 0 : Math.abs(k - from) * stag);
      f.ring.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "fan " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "heatpump",
  means: "A heat pump's outdoor unit: the fan under the pointer turns its blades an eighth round, the other turns a little after.",
  rules: [1, 2, 5, 6],
  range: [0, 60, 120],
  tour: [[161, 107], [200, 126], [239, 146], null],
  mount,
});

gasbottles.code:
/**
 * Gas cylinders: four tall bottles standing on the plinth of a storage cage,
 * a meshed back wall behind them. The pointer picks a bottle by where it is
 * along the row: it tips forward on the front of its foot, as if drawn out
 * of the cage, and the bottles beside it rock after it, staggered from it.
 * At rest they lean a little this way and that, one bright. The slider is
 * the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * across the bottles' resting middles.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 14, X0 = 7, YC = 2, R = 6, H = 30, BZ = 2;
const REST = [2, -3, 5, 0], FAV = 1, TIP = 26;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.25);
  fit(C, [[-3, -9, 0], [57, 12, 0], [57, -9, 0], [-3, 12, 0], [-3, -9, 44], [57, -9, 44], [X0, 22, 34], [X0 + 42, 22, 34]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the cage: a meshed back wall, then the plinth
  const [wr, wi] = rings(-3, -9, 57, -7, 0.8, 0.4);
  const wall = solid(g);
  put(wall, prism(P, front, wr, wi, 0, 44));
  let mesh = "";
  for (let x = 4; x < 56; x += 6) mesh += seg(P(x, -7, 4), P(x, -7, 41));
  for (let z = 8; z < 42; z += 6) mesh += seg(P(0, -7, z), P(54, -7, z));
  mk("path", { class: "nf lo", d: mesh }, wall.g);
  const [pr, pi] = rings(-3, -7, 57, 12, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, 0, BZ));

  // a bottle's rings, foot to valve: [radius, height]
  const prof = [[R, 0], [R, H], [R * 0.96, H + 1.6], [R * 0.85, H + 3], [R * 0.62, H + 4.2], [R * 0.3, H + 4.8]];
const valve = [[1.7, H + 4], [1.7, H + 8.5]];
  const c32 = circ(1, 32);
  const bot = [];
  for (let k = 0; k < N; k++) {
    const bg = mk("g", {}, g);
    bot.push({ x: X0 + k * STEP, sil: mk("path", { class: "sil" }, bg), cr: mk("path", { class: "nf lo" }, bg), v: mk("path", {}, bg), a: tween(REST[k]), last: NaN });
  }
  function tilt(x, deg, u, v, z) {
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg)), w = v - R;
    return P(x + u, YC + R + w * c + z * s, BZ + z * c - w * s);
  }
  function draw(b, deg) {
    if (deg === b.last) return;
    b.last = deg;
    let pts = [];
    prof.forEach(([r, z]) => c32.forEach((s) => pts.push(tilt(b.x, deg, s.u * r, s.v * r, z))));
    b.sil.setAttribute("d", poly(hull(pts)));
    const vp = [];
    valve.forEach(([r, z]) => c32.forEach((s) => vp.push(tilt(b.x, deg, s.u * r, s.v * r, z))));
    b.v.setAttribute("d", poly(hull(vp)));
    const band = c32.filter((s) => s.v > 0 || s.u > 0.7 || s.u < -0.7).filter((s) => s.v > -0.2);
    b.cr.setAttribute("d", open(band.sort((p, q) => Math.atan2(p.v, p.u) - Math.atan2(q.v, q.u)).map((s) => tilt(b.x, deg, s.u * (R - 0.4), s.v * (R - 0.4), H - 2))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    bot.forEach((b) => { draw(b, tval(b.a, now)); if (!tdone(b.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H * 0.6);
    if (x < -5 || x > 59 || y < -10 || y > 14) return -1;
    return clamp(Math.round((x - X0) / STEP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    bot.forEach((b, k) => {
      const d = Math.abs(k - a);
      tset(b.a, a < 0 ? REST[k] : d === 0 ? TIP : REST[k] + Math.max(0, 10 - 4 * d), now, from < 0 ? 0 : d * stag);
      b.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "cyl " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "gasbottles",
  means: "Gas cylinders in a cage: the bottle under the pointer tips forward out of the row, the bottles beside it rock after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[153, 155], [185, 171], [249, 203], null],
  mount,
});

tentpoles.code:
/**
 * Camp chairs: a row of five folding camp chairs, each a canvas seat and back
 * on crossed legs. The pointer picks the chair under it by screen x: that one
 * swings open, its seat dropping level, and the rest fold shut, seat up flat
 * against the back, spreading out from it. At rest the row is mixed, some
 * open, some folded, one bright. The slider is how far the chosen chair opens.
 *
 * The pattern: a discrete choice (tween per chair, staggered by distance); the
 * hit is each chair's rest centre, which never moves.
 */
const { Cam, fit, proj, poly, fillet, seg, clamp, rad, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

const N = 5, GAP = 24, W = 8, HZ = 14, SL = 15, BZ = 34;
const REST = [0.2, 1, 0, 0.85, 0.1], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  const xs = Array.from({ length: N }, (_, i) => (i - (N - 1) / 2) * GAP);
  const ext = [];
  for (const x of [xs[0] - W, xs[N - 1] + W]) for (const y of [-15, 9]) for (const z of [0, BZ]) ext.push([x, y, z]);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  let amt = value;

  const chairs = xs.map((cx, i) => {
    const grp = mk("g", {}, g);
    const legsB = mk("path", { class: "nf lo" }, grp);
    const back = mk("path", { class: "sil" }, grp);
    const seat = mk("path", { class: "sil" }, grp);
    const legsF = mk("path", { class: "nf sil" }, grp);
    return { i, cx, grp, legsB, back, seat, legsF, tw: tween(REST[i]), drawn: NaN, sx: P(cx, 0, HZ)[0] };
  });

  const plate = (pts) => poly(fillet(pts.map((p) => P(...p)), [1.6, 1.6, 1.6, 1.6]));
  function draw(ch, f) {
    if (Math.abs(f - ch.drawn) < 1e-4) return;
    ch.drawn = f;
    const x0 = ch.cx - W, x1 = ch.cx + W, th = rad((1 - f) * 84);
    const hy = -7, fy = hy + SL * Math.cos(th), fz = HZ + SL * Math.sin(th);
    const ty = hy - 7 * f, gy = hy + 3 * f, ly = hy + 15 * f;
    ch.back.setAttribute("d", plate([[x0, ty, BZ], [x1, ty, BZ], [x1, hy, HZ - 1], [x0, hy, HZ - 1]]));
    ch.seat.setAttribute("d", plate([[x0, hy, HZ], [x1, hy, HZ], [x1, fy, fz], [x0, fy, fz]]));
    const L = (x) => seg(P(x, gy, 0), P(x, ty, BZ)) + seg(P(x, ly, 0), P(x, fy, fz)) + seg(P(x, gy, 0), P(x, fy, fz));
    ch.legsB.setAttribute("d", L(x0));
    ch.legsF.setAttribute("d", L(x1));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const ch of chairs) { draw(ch, tval(ch.tw, now)); if (!tdone(ch.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let sel = null;
  function retarget() {
    const now = performance.now();
    for (const ch of chairs) {
      const to = sel === null ? REST[ch.i] : ch.i === sel ? clamp(amt, 0.3, 1) : 0;
      tset(ch.tw, to, now, sel === null ? 0 : Math.abs(ch.i - sel) * 45);
      const on = sel === null ? ch.i === FAV : ch.i === sel;
      ch.seat.classList.toggle("hi", on);
      ch.back.classList.toggle("hi", on);
    }
    read.textContent = sel === null ? "rest" : "chair " + (sel + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      let best = null, bd = Infinity;
      for (const ch of chairs) { const d = Math.abs(p[0] - ch.sx); if (d < bd) { bd = d; best = ch.i; } }
      const next = bd > GAP * 2 || p[1] < 40 || p[1] > 290 ? null : best;
      if (next !== sel) { sel = next; retarget(); }
    },
    leave: () => { sel = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "tentpoles",
  means: "Five folding camp chairs in a row: the one under the pointer swings open and the others fold shut around it.",
  rules: [1, 2, 5, 8],
  range: [0.3, 1, 1],
  tour: [[101, 129], [241, 199], [194, 176], null],
  mount,
});

skateramp.code:
/**
 * Skate ramp: a quarter pipe built in five sections side by side, each a
 * curved transition rising to a steel coping. The pointer is where the ramp
 * swells: sections near it grow taller and steeper on their own springs, the
 * far ones settle low, and the coping nearest it is bright. At rest the ramp
 * rises gently toward one end, one coping bright. The slider is the swell.
 *
 * The pattern: a continuous falloff (terrain's spring per section); the hit
 * is each section's rest centre on screen, which never moves.
 */
const { Cam, fit, proj, poly, open, clamp, spring, stepS, disposer, mk, pointer, register } = HL;

const N = 5, SW = 18, R = 30, DECK = 8, STEPS = 12;
const REST = [20, 24, 28, 33, 26], FAV = 3, LOW = 16, HIGH = 46;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.85);
  const x0 = -(N * SW) / 2;
  const ext = [];
  for (const x of [x0, x0 + N * SW]) for (const y of [-R - DECK, 6]) for (const z of [0, HIGH]) ext.push([x, y, z]);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  let amt = value;

  const curve = (h) => {
    const pts = [];
    for (let k = 0; k <= STEPS; k++) { const t = (k / STEPS) * Math.PI / 2; pts.push([-R * Math.sin(t), h * (1 - Math.cos(t))]); }
    pts.push([-R - DECK, h]);
    return pts;
  };
  const secs = Array.from({ length: N }, (_, i) => {
    const a = x0 + i * SW, b = a + SW, grp = mk("g", {}, g);
    return {
      i, a, b, sp: spring(REST[i]), drawn: NaN, sx: P((a + b) / 2, -R / 2, REST[i] / 2)[0],
      face: mk("path", { class: "sil" }, grp), lines: mk("path", { class: "nf lo" }, grp),
      side: mk("path", { class: "sil" }, grp), cope: mk("path", { class: "nf sil" }, grp),
    };
  });

  function draw(s) {
    const h = s.sp.x;
    if (Math.abs(h - s.drawn) < 1e-3) return;
    s.drawn = h;
    const cv = curve(h);
    const A = cv.map(([y, z]) => P(s.a, y, z)), Bp = cv.map(([y, z]) => P(s.b, y, z));
    s.face.setAttribute("d", poly(A.concat(Bp.slice().reverse())));
    let d = "";
    for (const k of [4, 8]) d += open([A[k], Bp[k]]);
    s.lines.setAttribute("d", d);
    s.side.setAttribute("d", poly(Bp.concat([P(s.b, -R - DECK, 0), P(s.b, 0, 0)])));
    s.cope.setAttribute("d", open([P(s.a, -R, h + 1.2), P(s.b, -R, h + 1.2)]));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const s of secs) { if (stepS(s.sp, dt)) m = true; draw(s); }
    return m;
  });
  bag.add(B.unregister);

  let u = null;
  function retarget() {
    let near = null, bd = Infinity;
    for (const s of secs) {
      if (u === null) { s.sp.t = REST[s.i]; continue; }
      const d = Math.abs(u - s.i);
      if (d < bd) { bd = d; near = s.i; }
      const f = d < 0.5 ? 1 : d < 1.8 ? 0.42 : 0.1;
      s.sp.t = clamp(LOW + (HIGH - LOW) * f * amt, LOW, HIGH);
    }
    for (const s of secs) s.cope.classList.toggle("hi", u === null ? s.i === FAV : s.i === near);
    read.textContent = u === null ? "rest" : "bay " + (near + 1);
    B.wake();
  }

  const span = secs[N - 1].sx - secs[0].sx;
  bag.add(pointer(stage, {
    move: (p) => {
      const f = ((p[0] - secs[0].sx) / span) * (N - 1);
      u = f < -1 || f > N || p[1] < 30 || p[1] > 295 ? null : clamp(f, 0, N - 1);
      retarget();
    },
    leave: () => { u = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "skateramp",
  means: "A quarter pipe in five sections: the ramp swells tall and steep under the pointer and the far sections settle low.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[125, 163], [252, 226], [198, 199], null],
  mount,
});

returnsbin.code:
/**
 * Returns desk: a long counter with four returned parcels of different sizes
 * waiting on it. The pointer picks the parcel under it by screen x: that one
 * slides forward to the counter's front edge, turning square to the customer,
 * and the others slide back, spreading out from it. At rest the parcels sit
 * askew at mixed depths, one bright. The slider is how far the parcel comes.
 *
 * The pattern: a discrete choice (tween per parcel, staggered by distance);
 * the hit is each parcel's rest centre on screen, which never moves.
 */
const { Cam, fit, proj, facing, rings, prism, rrect, clamp, rad, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const L = 56, D = 16, H = 26;
const BOX = [[14, 12, 10], [10, 10, 14], [18, 13, 8], [12, 11, 11]];
const XS = [-38, -13, 13, 38], RY = [-4, 2, -6, 0], RA = [-14, 9, 5, -10], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-L, -D, 0], [L, D, 0], [-L, -D, H + 16], [L, D, H + 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-L, -D, L, D, 3, 1.4);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  const [tr, ti] = rings(-L - 2, -D - 2, L + 2, D + 2, 3, 1.2);
  put(solid(g), prism(P, front, tr, ti, H, H + 1.5));
  let amt = value;

  const parcels = BOX.map(([w, d, h], i) => {
    const s = solid(g);
    const base = rrect(-w / 2, -d / 2, w / 2, d / 2, 1.2, 4), inner = rrect(-w / 2 + 1, -d / 2 + 1, w / 2 - 1, d / 2 - 1, 0.6, 4);
    return { i, h, s, base, inner, tw: tween(0), drawn: NaN, sx: P(XS[i], RY[i], H + h / 2)[0] };
  });
  const turn = (ring, a, cx, cy) => {
    const c = Math.cos(a), s = Math.sin(a);
    return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
  };
  function draw(p, f) {
    if (Math.abs(f - p.drawn) < 1e-4) return;
    p.drawn = f;
    const y = f >= 0 ? RY[p.i] + (D - 7 - RY[p.i]) * f : RY[p.i] + (RY[p.i] + D - 7) * f * 0.5;
    const a = rad(RA[p.i] * (1 - clamp(f, 0, 1)));
    put(p.s, prism(P, front, turn(p.base, a, XS[p.i], y), turn(p.inner, a, XS[p.i], y), H + 1.5, H + 1.5 + p.h));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const p of parcels) { draw(p, tval(p.tw, now)); if (!tdone(p.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let sel = null;
  function retarget() {
    const now = performance.now();
    for (const p of parcels) {
      const to = sel === null ? 0 : p.i === sel ? clamp(amt, 0.3, 1) : -0.6;
      tset(p.tw, to, now, sel === null ? 0 : Math.abs(p.i - sel) * 45);
      p.s.sil.classList.toggle("hi", sel === null ? p.i === FAV : p.i === sel);
    }
    read.textContent = sel === null ? "rest" : "rtn " + (sel + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => {
      let best = null, bd = Infinity;
      for (const p of parcels) { const d = Math.abs(q[0] - p.sx); if (d < bd) { bd = d; best = p.i; } }
      const next = bd > 50 || q[1] < 40 || q[1] > 290 ? null : best;
      if (next !== sel) { sel = next; retarget(); }
    },
    leave: () => { sel = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "returnsbin",
  means: "A returns counter with four parcels: the one under the pointer slides forward squared up, the others slide back.",
  rules: [1, 2, 5, 8],
  range: [0.3, 1, 1],
  tour: [[137, 103], [235, 148], [270, 176], null],
  mount,
});

rebar.code:
/**
 * Rebar bundle: six steel bars stacked in a pyramid, their ends ragged from the
 * cut. The pointer chooses a bar: it slides out of the bundle along its length,
 * its neighbours drawn a little way with it, staggered by distance. At rest one
 * bar already stands proud, bright. The slider is how far a bar slides.
 *
 * The pattern: a discrete pick (the 700ms tween, staggered); the hit is each
 * bar's rest axis on screen, which never moves.
 */
const {
  Cam, fit, proj, circ, hull, poly, clamp, tween, tset, tval, tdone,
  disposer, mk, solid, put, pointer, register,
} = HL;

const R = 6, L = 52, OUT = 46;
const ROWS = [[-2, 0], [0, 0], [2, 0], [-1, 1], [1, 1], [0, 2]];
const REST = [3, -4, 6, -2, 2, 14], FAV = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  const bars = ROWS.map(([j, row], i) => ({ i, y: j * R, z: R + row * R * Math.sqrt(3), tw: tween(REST[i]), drawn: NaN }));
  const ext = [];
  for (const b of bars) ext.push([-L - 8, b.y - R, b.z - R], [L + OUT * 1.5, b.y + R, b.z + R], [-L, b.y + R, 0]);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const ring = circ(R, 24), capR = circ(R - 1.6, 24);
  const cyl = (x, b, rg) => rg.map((q) => P(x, b.y + q.u, b.z + q.v));

  bars.sort((p, q) => 0.61 * p.y + 0.5 * p.z - (0.61 * q.y + 0.5 * q.z));
  for (const b of bars) { b.s = solid(g); b.cap = mk("path", { class: "nf lo" }, b.s.g); }
  bars.sort((p, q) => p.i - q.i);
  for (const b of bars) {
    const a = P(-L, b.y, b.z), e = P(L, b.y, b.z);
    b.ax = [a, e];
  }

  function draw(b, now) {
    const x = tval(b.tw, now);
    if (Math.abs(x - b.drawn) < 1e-3) return;
    b.drawn = x;
    const x0 = -L + x, x1 = L + x;
    b.s.sil.setAttribute("d", poly(hull(cyl(x0, b, ring).concat(cyl(x1, b, ring)))));
    b.s.cr.setAttribute("d", poly(cyl(x1, b, ring)));
    b.cap.setAttribute("d", poly(cyl(x1, b, capR)));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const b of bars) { draw(b, now); if (!tdone(b.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let chosen = -1;
  function choose(a) {
    if (a === chosen) return;
    chosen = a;
    const now = performance.now(), out = clamp(OUT * value, 12, OUT * 1.5);
    for (const b of bars) {
      if (a < 0) { tset(b.tw, REST[b.i], now, 0); continue; }
      const d = Math.hypot(b.y - bars[a].y, b.z - bars[a].z) / (2 * R);
      tset(b.tw, b.i === a ? out : clamp(out * (0.42 - 0.2 * d), 0, out), now, d * 45);
    }
    for (const b of bars) b.s.sil.classList.toggle("hi", a < 0 ? b.i === FAV : b.i === a);
    read.textContent = a < 0 ? "rest" : "bar " + (a + 1);
    B.wake();
  }

  const dist = (p, [a, e]) => {
    const dx = e[0] - a[0], dy = e[1] - a[1];
    const t = clamp(((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / (dx * dx + dy * dy), 0, 1);
    return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy);
  };
  bag.add(pointer(stage, {
    move: (p) => {
      let best = -1, bd = R * 2.3 * 2.4;
      for (const b of bars) { const d = dist(p, b.ax); if (d < bd) { bd = d; best = b.i; } }
      choose(best);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  chosen = 0; choose(-1);
  for (const b of bars) draw(b, performance.now() + 1e4);
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "rebar",
  means: "A bundle of six rebar bars: the bar under the pointer slides out along its length, its neighbours drawn a little after it.",
  rules: [1, 2, 4, 5],
  range: [0.5, 1, 1.5],
  tour: [[124, 123], [134, 167], [154, 115], null],
  mount,
});

plumbline.code:
/**
 * Spirit level: a long aluminium level balanced on a block, a vial set in its
 * top with one bubble. The pointer is where the hand presses: the beam tilts on
 * its own spring toward that end, and the bubble runs up the vial to the high
 * end. At rest the level sits a little off true, the vial bright. The slider is
 * how far the beam can tip.
 *
 * The pattern: a continuous tilt (a spring on one angle); the hit is the
 * ground plane, which never moves.
 */
const {
  Cam, fit, proj, unproj, facing, rrect, rings, prism, ringAt, run, hull, poly, open,
  clamp, rad, spring, stepS, disposer, mk, solid, put, place, pointer, register,
} = HL;

const L = 66, W = 7, H = 9, PIV = 20, MAX = 11, REST = 2.6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.65);
  const ext = [];
  for (const s of [-1, 1]) for (const u of [-L, L]) for (const v of [-W, W]) {
    const z = PIV + u * Math.sin(rad(MAX * 1.5 * s));
    ext.push([u, v, z], [u, v, z + H], [u, v, 0]);
  }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  put(solid(g), prism(P, front, ...rings(-18, -14, 18, 14, 3, 1.4), 0, 2));
  put(solid(g), prism(P, front, ...rings(-5, -9, 5, 9, 2, 1), 2, PIV - 1));

  const foot = rrect(-L, -W, L, W, 2.4, 4), inner = rrect(-L + 1.2, -W + 1.2, L - 1.2, W - 1.2, 1.4, 4);
  const vial = rrect(-16, -2.6, 16, 2.6, 2.6, 6);
  const beam = solid(g);
  const win = mk("path", { class: "nf hi" }, g);
  const ticks = mk("path", { class: "nf lo" }, g);
  const bub = mk("ellipse", { class: "dot", rx: 3.2, ry: 1.7 }, g);

  const sp = spring(REST);
  let drawn = NaN;
  const at = (ring, z0, s) => ring.map((q) => { const p = P(q.u * Math.cos(Math.asin(s)), q.v, z0 + q.u * s); return p; });

  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const s = Math.sin(rad(sp.x)), c = Math.cos(rad(sp.x));
    const bot = at(foot, PIV, s), top = at(foot, PIV + H, s);
    const keep = run(inner, front);
    put(beam, { sil: poly(hull(bot.concat(top))), crease: open(at(keep, PIV + H, s)) });
    win.setAttribute("d", poly(at(vial, PIV + H + 0.01, s)));
    const tk = [-5, 5].map((u) => [P(u * c, -2.6, PIV + H + u * s), P(u * c, 2.6, PIV + H + u * s)]);
    ticks.setAttribute("d", tk.map(([a, b]) => "M" + a + "L" + b).join(""));
    const bu = clamp((sp.x / MAX) * 12, -12, 12);
    place(bub, P(bu * c, 0, PIV + H + bu * s + 0.3));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(over) {
    const lim = clamp(MAX * value, 3, MAX * 1.5);
    sp.t = over == null ? REST : clamp((over / L) * lim, -lim, lim);
    beam.sil.classList.toggle("hi", over != null);
    win.classList.toggle("hi", over == null);
    read.textContent = over == null ? "rest" : (sp.t >= 0 ? "+" : "") + sp.t.toFixed(1) + "°";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], PIV);
      set(Math.abs(x) > L + 18 || Math.abs(y) > 34 ? null : clamp(x, -L, L));
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  draw();
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "plumbline",
  means: "A spirit level balanced on a block: it tilts toward the end the pointer presses, and the bubble runs to the high end.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.5],
  tour: [[312, 231], [88, 119], [256, 203], null],
  mount,
});

buttonbox.code:
/**
 * Button tin: three round sewing tins along a shelf, each holding a few
 * buttons. The pointer picks a tin by where it stands: its lid rises and
 * swings back off the rim to show the buttons, and the tins beside it ease
 * their lids a little, staggered from it. At rest one lid sits ajar, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 58, R = 24, H = 16, LIFT = 26, BACK = 22, FAV = 1, SZ = 4;
const X1 = (N - 1) * STEP + 2 * R;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const BTN = [[-9, -6, 6], [7, -9, 5], [10, 7, 6.5], [-6, 10, 5], [1, 1, 4.5]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-8, -8 - BACK, 0], [X1 + 8, 2 * R + 8, 0], [X1 + 8, -8 - BACK, 0], [-8, 2 * R + 8, 0], [R, R - BACK, SZ + H + LIFT + 6], [X1 - R, R, SZ + H + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-8, -8, X1 + 8, 2 * R + 8, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = R + k * STEP, y = R, grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, y, R), disc(x, y, R - 1.6), SZ, SZ + H));
    mk("path", { d: poly(ringAt(P, disc(x, y, R - 2.5), SZ + H)), class: "nf lo" }, grp);
    for (const [bx, by, br] of BTN) {
      const b = mk("g", {}, grp);
      mk("path", { d: poly(ringAt(P, disc(x + bx, y + by, br, 20), SZ + H - 1)) }, b);
      mk("path", { d: poly(ringAt(P, disc(x + bx, y + by, br * 0.3, 8), SZ + H - 1)), class: "nf lo" }, b);
    }
    const lid = solid(grp);
    items.push({ k, x, y, lid, z: tween(k === FAV ? 0.4 : 0), last: NaN });
  }

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const z0 = SZ + H - 3 + LIFT * t, y = it.y - BACK * t, x = it.x;
    put(it.lid, prism(P, front, disc(x, y, R + 1.2), disc(x, y, R - 0.6), z0, z0 + 5));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, it.y, SZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 45 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 0.4 : 0) : dd === 0 ? 1 : dd === 1 ? 0.15 : 0;
      tset(it.z, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tin " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "buttonbox",
  means: "Three sewing tins on a shelf: the lid under the pointer rises and swings back to show the buttons; its neighbours ease open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[122, 130], [188, 162], [253, 195], null],
  mount,
});

tieclip.code:
/**
 * Cufflink box: three small velvet boxes on a dresser tray, each holding a
 * pair of cufflinks in a cushion slit. The pointer picks a box by where it
 * stands: its lid swings open on the back hinge, and the boxes beside it
 * crack their lids, staggered from it. At rest one lid stands ajar, bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), swinging on a hinge.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, seg,
} = HL;

const N = 3, STEP = 54, W = 40, D = 32, H = 14, LH = 7, TZ = 4, OPEN = 1.85, FAV = 2;
const X1 = (N - 1) * STEP + W;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-8, -8 - LH, 0], [X1 + 8, D + 8, 0], [X1 + 8, -8 - LH, 0], [-8, D + 8, 0], [0, 0, TZ + H + D + 4], [X1, 0, TZ + H + D + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-8, -8, X1 + 8, D + 8, 7, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const [r0, r1] = rings(x, 0, x + W, D, 4, 1.4);
    put(solid(grp), prism(P, front, r0, r1, TZ, TZ + H));
    const [c0] = rings(x + 3, 3, x + W - 3, D - 3, 3, 1);
    mk("path", { d: poly(ringAt(P, c0, TZ + H)), class: "nf lo" }, grp);
    mk("path", { d: seg(P(x + 7, D / 2, TZ + H), P(x + W - 7, D / 2, TZ + H)), class: "nf lo" }, grp);
    for (const cx of [x + W * 0.33, x + W * 0.67]) {
      const s = solid(grp);
      put(s, prism(P, front, disc(cx, D / 2, 4.2), disc(cx, D / 2, 3), TZ + H, TZ + H + 2.2));
    }
    const lid = solid(grp);
    items.push({ k, x, r0, r1, lid, t: tween(k === FAV ? 0.3 : 0), last: NaN });
  }

  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const a = OPEN * t, ca = Math.cos(a), sa = Math.sin(a), hz = TZ + H;
    // hinge along x at the back top edge (y = 0, z = hz); the lid turns up and back
    const R = (q, dz) => P(q.u, -(dz) * sa + q.v * ca, hz + q.v * sa + dz * ca);
    const pts = it.r0.map((q) => R(q, 0)).concat(it.r0.map((q) => R(q, LH)));
    put(it.lid, { sil: poly(hull(pts)), crease: a < 1.1 ? poly(it.r1.map((q) => R(q, LH))) : "" });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, D / 2, TZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 45 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), t = a < 0 ? (k === FAV ? 0.3 : 0) : dd === 0 ? 1 : dd === 1 ? 0.12 : 0;
      tset(it.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tieclip",
  means: "Three velvet cufflink boxes on a tray: the lid under the pointer swings open on its hinge; its neighbours crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[129, 141], [196, 175], [262, 208], null],
  mount,
