marsdome.code:
/**
 * Habitat dome: a round habitat on a landing pad, its shell over a low inner
 * module, an airlock tunnel on one side. The pointer over the pad opens it:
 * the shell rises off the module and the airlock reaches out, with the
 * nearness of the pointer setting how far. At rest the airlock is bright.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 38, CZ = 4, LIFT = 30, AL = 26, RIM = 52;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-RIM, -RIM, 0], [RIM, RIM, 0], [RIM + AL + 8, 0, 0], [0, 0, CZ + R * 0.85 + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-RIM, -RIM, RIM, RIM, 18, 2);
  put(solid(g), prism(P, front, pr, pi, 0, CZ));
  put(solid(g), prism(P, front, disc(26), disc(23.5), CZ, CZ + 16));
  const shell = mk("path", { class: "sil" }, g), seam = mk("path", { class: "nf lo" }, g), hatch = mk("path", { class: "nf" }, g);
  const tube = solid(g);
  const op = spring(0), ex = spring(0);
  let last = NaN;

  function draw(o, e) {
    const k = r2(o) + "," + r2(e);
    if (k === last) return;
    last = k;
    const base = CZ + o * LIFT, pts = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(R * Math.cos(t), 32), base + R * 0.85 * Math.sin(t))); }
    shell.setAttribute("d", poly(hull(pts)));
    seam.setAttribute("d", poly(ringAt(P, disc(R * 0.55, 32), base + R * 0.85 * 0.83)));
    const top = base + R * 0.85;
    hatch.setAttribute("d", poly(hull(ringAt(P, disc(5, 16), top).concat(ringAt(P, disc(5, 16), top + 2.5)))));
    const x1 = R - 6 + AL * (0.45 + 0.55 * e);
    const [tr, ti] = rings(R - 8, -9, x1, 9, 5, 1.6);
    put(tube, prism(P, front, tr, ti, CZ, CZ + 18));
  }
  const r2 = (n) => Math.round(n * 100) / 100;

  const B = register(stage, (dt) => {
    const a = stepS(op, dt), b = stepS(ex, dt);
    draw(op.x, ex.x);
    return a || b;
  });
  bag.add(B.unregister);

  function set(p) {
    let o = 0;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], 0); const d = Math.hypot(wx, wy); o = clamp(1.25 - d / (RIM * 1.6), 0, 1) * (0.4 + 0.6 * reach); }
    op.t = o; ex.t = p ? clamp(o * 1.4, 0, 1) : 0.15;
    shell.classList.toggle("hi", o > 0.05);
    tube.sil.classList.toggle("hi", o <= 0.05);
    read.textContent = o > 0.05 ? "open " + Math.round(o * 100) : "rest";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "marsdome",
  means: "A habitat dome on a pad: the pointer near it lifts the shell off the inner module and runs the airlock tunnel out.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[82, 157], [142, 188], [142, 241], null],
  mount,
});

dockingport.code:
/**
 * Docking port: a round docking collar on a hull plate, latches round its
 * rim, a hatch hinged at the far edge. The pointer swings the hatch open:
 * the nearer it comes to the port, the wider the hatch stands. At rest the
 * hatch is ajar and the collar is bright.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const R = 30, RIM = 50, CZ = 4, CH = 12, OPEN = 105, AJAR = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-RIM, -RIM, 0], [RIM, RIM, 0], [-R, 0, CZ + CH + 2 * R + 4], [-R - 10, -R, CZ + CH + 2 * R]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-RIM, -RIM, RIM, RIM, 14, 2);
  put(solid(g), prism(P, front, pr, pi, 0, CZ));
  const collar = solid(g);
  put(collar, prism(P, front, circ(R + 6, 40), circ(R + 3.5, 40), CZ, CZ + CH));
  mk("path", { d: poly(ringAt(P, circ(R, 40), CZ + CH)), class: "nf lo" }, g);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2 + 0.3, d = mk("circle", { r: 1.6, class: "dot off" }, g);
    place(d, P((R + 4.8) * Math.cos(a), (R + 4.8) * Math.sin(a), CZ + CH));
  }
  const hatch = mk("path", { class: "sil" }, g), wheel = mk("path", { class: "nf lo" }, g);
  const ang = spring(AJAR);
  let last = NaN;

  const tilt = (q, z, th) => { const s = q.u + R; return [-R + s * Math.cos(th), q.v, CZ + CH + 1 + s * Math.sin(th) + z * Math.cos(th)]; };
  function draw(deg) {
    const k = Math.round(deg * 10);
    if (k === last) return;
    last = k;
    const th = (deg * Math.PI) / 180, ring = circ(R - 1, 40), pts = [];
    for (const z of [0, 3]) for (const q of ring) pts.push(P(...tilt(q, z, th)));
    hatch.setAttribute("d", poly(hull(pts)));
    wheel.setAttribute("d", poly(circ(10, 24).map((q) => P(...tilt(q, 3.4, th)))));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function set(p) {
    let o = 0;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], 0); o = clamp(1.3 - Math.hypot(wx, wy) / (RIM * 1.4), 0, 1) * (0.4 + 0.6 * reach); }
    ang.t = o > 0 ? AJAR + (OPEN - AJAR) * o : AJAR;
    hatch.classList.toggle("hi", o > 0.05);
    collar.sil.classList.toggle("hi", o <= 0.05);
    read.textContent = o > 0.05 ? Math.round(ang.t) + "°" : "rest";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "dockingport",
  means: "A docking collar on a hull plate: the pointer near the port swings its hatch open on the far hinge.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[283, 191], [221, 222], [221, 270], null],
  mount,
});

petridish2.code:
/**
 * Sample rack: five capped sample tubes standing in a rack, each filled to a
 * different line. The pointer picks a tube by where it stands: it tips
 * forward out of the rack on its foot, and the tubes beside it lean a little,
 * staggered from it. At rest one tube leans, bright. The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 18, TR = 6, TL = 50, RZ = 12, TIP = 38, FAV = 3;
const FILL = [0.55, 0.35, 0.7, 0.45, 0.6];
const X1 = (N - 1) * STEP;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  const tipY = TL * Math.sin(rad(TIP)), tipZ = RZ + TL * Math.cos(rad(TIP));
  fit(C, [[-12, -12, 0], [X1 + 12, 12, 0], [-12, 12, 0], [X1 + 12, -12, 0], [0, 0, RZ + TL + 4], [X1, 0, RZ + TL + 4], [X1, tipY + 8, tipZ], [0, tipY + 8, tipZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-12, -12, X1 + 12, 12, 5, 1.8);
  put(solid(g), prism(P, front, rr, ri, 0, RZ));
  for (let k = 0; k < N; k++) mk("path", { d: poly(ringAt(P, disc(k * STEP, 0, TR + 1.2), RZ)), class: "nf lo" }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), s = solid(grp);
    const line = mk("path", { class: "nf lo" }, grp), cap = solid(grp);
    items.push({ k, x: k * STEP, grp, s, line, cap, t: tween(k === FAV ? 14 : 0), last: NaN });
  }

  const at = (it, sl, t) => [Math.sin(rad(t)) * sl, RZ + Math.cos(rad(t)) * sl];
  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const [y1, z1] = at(it, TL, t), [yc, zc] = at(it, TL - 6, t), [yf, zf] = at(it, TL * FILL[it.k], t);
    const foot = ringAt(P, disc(it.x, 0, TR), RZ), top = ringAt(P, disc(it.x, y1, TR), z1);
    it.s.sil.setAttribute("d", poly(hull(foot.concat(top))));
    it.s.cr.setAttribute("d", "");
    it.line.setAttribute("d", open(ringAt(P, run(disc(it.x, yf, TR - 1), front), zf)));
    const cb = ringAt(P, disc(it.x, yc, TR + 1.2), zc), ct = ringAt(P, disc(it.x, y1, TR + 1.2), z1 + 1);
    it.cap.sil.setAttribute("d", poly(hull(cb.concat(ct))));
    it.cap.cr.setAttribute("d", open(ringAt(P, run(disc(it.x, y1, TR - 0.2), front), z1 + 1)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, RZ + TL / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < STEP * 1.6 && Math.abs(mids[best][1] - sy) < TL * 1.6 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), t = a < 0 ? (k === FAV ? 14 : 0) : d === 0 ? TIP : d === 1 ? 8 : 0;
      tset(it.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    // the tipped tube comes nearest the viewer: paint it last
    for (const it of items) g.appendChild(it.grp);
    g.appendChild(items[a < 0 ? FAV : a].grp);
    read.textContent = a < 0 ? "rest" : "tube " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "petridish2",
  means: "Five capped sample tubes in a rack: the tube under the pointer tips forward on its foot, its neighbours lean a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[147, 113], [214, 146], [280, 179], null],
  mount,
});

sieve.code:
/**
 * Sieve: a stack of five round test sieves on a collecting pan, a lid on top.
 * The pointer picks a sieve by its rest height: it slides out of the stack
 * toward the viewer, and the sieves beside it shift a little, staggered from
 * it. At rest one sieve stands slightly out, bright. The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, R = 24, H = 9, PAN = 7, OUT = 34, FAV = 2;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const zOf = (k) => PAN + k * H;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  const top = zOf(N) + 6;
  fit(C, [[-R, -R, 0], [R + OUT, R + OUT, 0], [R + OUT, -R, 0], [-R, R, 0], [-R, -R, top], [R, R, top]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // collecting pan
  put(solid(g), prism(P, front, disc(0, 0, R + 1), disc(0, 0, R - 1.5), 0, PAN));

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const s = solid(grp);
    const mesh = mk("path", { class: "nf lo dash" }, grp);
    items.push({ k, grp, s, mesh, o: tween(k === FAV ? OUT * 0.3 : 0), last: NaN });
  }
  // lid with a low knob
  const lid = mk("g", {}, g);
  put(solid(lid), prism(P, front, disc(0, 0, R + 0.5), disc(0, 0, R - 2), zOf(N), zOf(N) + 3));
  put(solid(lid), prism(P, front, disc(0, 0, 5, 24), disc(0, 0, 3.5, 24), zOf(N) + 3, zOf(N) + 6));

  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const x = o, y = o * 0.15, z0 = zOf(it.k);
    put(it.s, prism(P, front, disc(x, y, R), disc(x, y, R - 2), z0, z0 + H));
    // the mesh: one line across the open top, seen past the rim
    const m = ringAt(P, disc(x, y, R - 6, 4), z0 + H - 3);
    it.mesh.setAttribute("d", "M" + m[0] + "L" + m[2] + "M" + m[1] + "L" + m[3]);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.o, now)); if (!tdone(it.o, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  // hit against the rest stack: band of each sieve's screen height
  const mids = items.map((it) => P(0, 0, zOf(it.k) + H / 2));
  const cx = P(0, 0, 0)[0];
  function hit([sx, sy]) {
    if (Math.abs(sx - cx) > R * 3.3 * 1.3) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < H * 3.3 * 1.2 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), o = a < 0 ? (k === FAV ? OUT * 0.3 : 0) : d === 0 ? OUT : d === 1 ? 6 : 0;
      tset(it.o, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tier " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "sieve",
  means: "A stack of test sieves on a pan: the sieve under the pointer slides out of the stack, its neighbours shift a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 189], [160, 126], [160, 61], null],
  mount,
});

openhouse.code:
/**
 * Open house: a yard sign on a lawn, a post with an arm and a panel hanging
 * from two hooks. The panel swings on its hooks toward the side the pointer
 * stands on, on a spring. At rest it hangs with a slight sway, bright.
 *
 * The pattern: one part swinging toward the pointer (swing).
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, seg, unproj, clamp, rad,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const AZ = 92, X0 = 14, X1 = 70, D0 = 6, D1 = 48, REST = 0.18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-24, -44, 0], [96, 44, 0], [96, -44, 0], [-24, 44, 0], [0, 0, AZ + 6], [X1, -40, AZ - 30], [X1, 40, AZ - 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [lr, li] = rings(-24, -44, 96, 44, 10, 2);
  put(solid(g), prism(P, front, lr, li, 0, 3));
  const [pr, pi] = rings(-3, -3, 3, 3, 1.5, 0.8);
  put(solid(g), prism(P, front, pr, pi, 3, AZ + 4));
  const panelG = mk("g", {}, g), arm = solid(g);
  const [ar, ai] = rings(-1, -2, X1 + 6, 2, 1, 0.6);
  put(arm, prism(P, front, ar, ai, AZ - 2, AZ + 2));
  const hooks = mk("path", { class: "nf lo" }, panelG), panel = mk("path", { class: "sil hi" }, panelG), face = mk("path", { class: "nf lo" }, panelG);

  function draw(a) {
    const c = Math.cos(a), s = Math.sin(a);
    const W = (x, d, t) => P(x, d * s + t * c, AZ - d * c + t * s);
    const pts = [];
    for (const x of [X0, X1]) for (const d of [D0, D1]) for (const t of [-1.2, 1.2]) pts.push(W(x, d, t));
    const h = hull(pts);
    panel.setAttribute("d", poly(fillet(h, h.map(() => 2.5), 3)));
    const n = s >= 0 ? 1.2 : -1.2;
    face.setAttribute("d", poly(fillet([W(X0 + 5, D0 + 5, n), W(X1 - 5, D0 + 5, n), W(X1 - 5, D1 - 5, n), W(X0 + 5, D1 - 5, n)], [2, 2, 2, 2], 3)));
    hooks.setAttribute("d", seg(W(X0 + 8, 0, 0), W(X0 + 8, D0, 0)) + seg(W(X1 - 8, 0, 0), W(X1 - 8, D0, 0)));
    if (s < -0.02) arm.g.after(panelG); else panelG.after(arm.g);
    if (s < -0.02) g.append(panelG);
  }

  const sw = spring(REST);
  let last = NaN;
  const B = register(stage, (dt) => {
    const m = stepS(sw, dt);
    if (sw.x !== last) { last = sw.x; draw(sw.x * rad(maxA)); }
    return m;
  });
  bag.add(B.unregister);

  function setSwing(t) {
    sw.t = t;
    read.textContent = t === REST ? "rest" : (t < 0 ? "back " : "front ") + Math.round(Math.abs(t) * maxA) + "°";
    B.wake();
  }
  setSwing(REST);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [, y] = unproj(C, sx, sy, 0); setSwing(clamp(y / 40, -1, 1)); },
    leave: () => setSwing(REST),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

