  tour: [[135, 123], [200, 156], [265, 189], null],
  mount,
});

vaultbars.code:
/**
 * Gold bar stack: six tapered bars in a pyramid, three, two, one, on a vault
 * shelf. The pointer picks a layer by height: that layer slides forward out of
 * the stack and carries the layers above it, staggered from the one chosen.
 * At rest the top bar sits skewed forward, bright. The slider is the stagger.
 *
 * The pattern: stepped parts picked on their own rest tops (slide).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BL = 40, BW = 17, BH = 11, TP = 2.6, GAP = 1.2, OUT = 26, REST = 9, SZ = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.85);
  const YW = 3 * BW + 2 * GAP;
  fit(C, [[-6, -6, 0], [BL + 6, YW + 6, 0], [BL + OUT + 4, -6, 0], [-6, YW + 6, 0], [BL + OUT, YW / 2, SZ + 3 * BH + 4], [0, YW / 2, SZ + 3 * BH + 4]], 200, 172);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const [sr, si] = rings(-6, -6, BL + 6, YW + 6, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const layers = [];
  for (let i = 0; i < 3; i++) {
    const z0 = SZ + i * BH, bars = [];
    for (let j = 0; j < 3 - i; j++) {
      const y0 = i * (BW + GAP) / 2 + j * (BW + GAP);
      const grp = mk("g", {}, g), s = solid(grp), mark = mk("path", { class: "nf lo" }, grp);
      bars.push({ y0, s, mark });
    }
    layers.push({ i, z0, bars, off: tween(i === 2 ? REST : 0), last: NaN });
  }

  function drawBar(b, x, z0) {
    const foot = rrect(x, b.y0, x + BL, b.y0 + BW, 2, 4), top = rrect(x + TP, b.y0 + TP, x + BL - TP, b.y0 + BW - TP, 1.6, 4);
    const inner = rrect(x + TP + 1, b.y0 + TP + 1, x + BL - TP - 1, b.y0 + BW - TP - 1, 1, 4), z1 = z0 + BH;
    b.s.sil.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, top, z1)))));
    b.s.cr.setAttribute("d", open(ringAt(P, run(inner, front), z1)));
    const m = [[x + 12, b.y0 + 5.5], [x + BL - 12, b.y0 + 5.5], [x + BL - 12, b.y0 + BW - 5.5], [x + 12, b.y0 + BW - 5.5]];
    b.mark.setAttribute("d", poly(m.map(([u, v]) => P(u, v, z1))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    // a layer rides on the ones below it: its x is the largest offset at or below it
    let carry = 0;
    for (const L of layers) {
      const x = Math.max(carry, tval(L.off, now));
      carry = x;
      const xr = Math.round(x * 10) / 10;
      if (xr !== L.last) { L.last = xr; L.bars.forEach((b) => drawBar(b, xr, L.z0)); }
      if (!tdone(L.off, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  // pick on each layer's rest top: the highest layer whose footprint holds the pointer
  function hit([sx, sy]) {
    for (let i = 2; i >= 0; i--) {
      const L = layers[i], z = L.z0 + BH, [wx, wy] = unproj(C, sx, sy, z);
      const y0 = L.bars[0].y0, y1 = L.bars[L.bars.length - 1].y0 + BW;
      if (wx > -4 && wx < BL + 4 && wy > y0 - 3 && wy < y1 + 3) return i;
    }
    const [wx, wy] = unproj(C, sx, sy, SZ);
    return wx > -6 && wx < BL + 10 && wy > -6 && wy < YW + 8 ? 0 : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    layers.forEach((L) => {
      const to = a < 0 ? (L.i === 2 ? REST : 0) : L.i === a ? OUT : 0;
      tset(L.off, to, now, from < 0 ? 0 : Math.abs(L.i - from) * stag);
      const lit = a < 0 ? L.i === 2 : L.i === a;
      L.bars.forEach((b) => b.s.sil.classList.toggle("hi", lit));
    });
    read.textContent = a < 0 ? "rest" : "tier " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "vaultbars",
  means: "A pyramid of gold bars: the tier under the pointer slides forward out of the stack, carrying the bars above it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[175, 112], [169, 142], [133, 188], null],
  mount,
});

passbook.code:
/**
 * Night safe: a thick bank wall with a deposit hopper set into it. The hopper's
 * front plate is hinged at its foot; the pointer's height tips it out and down
 * into an open chute, its two wedge cheeks folding out with it. At rest the
 * hopper stands just ajar and its pull bar is the bright mark. The slider is the widest tilt.
 *
 * The pattern: one plate tipping on a bottom hinge (tilt).
 */
const {
  Cam, clamp, fit, facing, lerp, poly, prism, proj, rad, rings, unproj,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const WX = 64, WY = 10, WZ = 74, X0 = 14, X1 = 50, Z0 = 32, HH = 22, PT = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-4, -4, 0], [WX + 4, WY + 4, 0], [WX + 4, -4, 0], [-4, WY + 4, 0], [0, 0, WZ], [WX, WY + HH, Z0], [X0, WY + HH, Z0]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const [fr, fi] = rings(-4, -4, WX + 4, WY + 18, 3, 1.5);
  put(solid(g), prism(P, front, fr, fi, 0, 3));
  const [wr, wi] = rings(0, 0, WX, WY, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 3, WZ));
  // the opening in the wall's near face, and the chute's dark throat behind it
  const F = (x, z) => P(x, WY, z);
  mk("path", { d: poly([F(X0 - 3, Z0 - 3), F(X1 + 3, Z0 - 3), F(X1 + 3, Z0 + HH + 3), F(X0 - 3, Z0 + HH + 3)]), class: "lo" }, g);
  mk("path", { d: poly([F(X0, Z0 + HH - 4), F(X1, Z0 + HH - 4), P(X1, WY - 6, Z0 + HH - 2), P(X0, WY - 6, Z0 + HH - 2)]), class: "lo nf" }, g);
  mk("path", { d: poly([F(X0 + 10, Z0 + HH + 14), F(X1 - 10, Z0 + HH + 14), F(X1 - 10, Z0 + HH + 18), F(X0 + 10, Z0 + HH + 18)]), class: "lo" }, g);

  const far = mk("path", {}, g), plate = mk("path", { class: "sil" }, g), edge = mk("path", { class: "nf lo" }, g);
  const bar = mk("path", { class: "nf" }, g), near = mk("path", {}, g);
  // a point on the plate: x across, h up it from the hinge, out from its face
  const at = (a, x, h, o = 0) => P(x, WY + h * Math.sin(a) + o * Math.cos(a), Z0 + h * Math.cos(a) - o * Math.sin(a));
  const ang = spring(10);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), cheek = (x) => poly([F(x, Z0), at(a, x, HH), F(x, Z0 + HH)]);
    far.setAttribute("d", cheek(X0));
    plate.setAttribute("d", poly([at(a, X0, 0, PT), at(a, X1, 0, PT), at(a, X1, HH, PT), at(a, X0, HH, PT), at(a, X0, HH), at(a, X0, 0)]));
    edge.setAttribute("d", "M" + at(a, X0, HH, PT).join(",") + " L" + at(a, X0, HH).join(",") + " L" + at(a, X1, HH).join(","));
    bar.setAttribute("d", poly([at(a, X0 + 9, HH - 6, PT), at(a, X1 - 9, HH - 6, PT), at(a, X1 - 9, HH - 6, PT + 3), at(a, X0 + 9, HH - 6, PT + 3)]));
    near.setAttribute("d", cheek(X1));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(Math.round(ang.x * 10) / 10); return m; });
  bag.add(B.unregister);

  const top = P(X0, WY, Z0 + HH + 10)[1], bot = P(X1, WY + 20, 0)[1];
  let on = null;
  function setOpen(p) {
    let hitIt = false;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], 0); hitIt = wx > -16 && wx < WX + 16 && wy > -60 && wy < WY + 40; }
    ang.t = hitIt ? lerp(0, maxA, clamp((p[1] - top) / (bot - top), 0, 1)) : 10;
    if (hitIt !== on) {
      on = hitIt;
      plate.classList.toggle("hi", hitIt);
      bar.classList.toggle("hi", !hitIt);
    }
    read.textContent = hitIt ? Math.round(ang.t) + "°" : "rest";
    B.wake();
  }
  setOpen(null);
  bag.add(pointer(stage, { move: (p) => setOpen(p), leave: () => setOpen(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "passbook",
  means: "A night safe in a bank wall: the pointer's height tips the hopper plate out and down into an open chute.",
  rules: [1, 3, 5, 8],
