  name: "seismograph",
  means: "A seismograph drum: the pointer rolls the drum to bring the tremor round and slides the pen to the trace it lands on.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[243, 160], [148, 112], [200, 140], null],
  mount,
});

crib.code:
/**
 * Crib: a baby cot on four posts, slatted sides front and back, a mattress
 * inside and a mobile hung over it from the back post. The pointer over the
 * cot lowers the front drop-side between its posts and turns the mobile; at
 * rest the drop-side sits a little low, its top rail bright. The slider is
 * how far the side drops.
 *
 * The pattern: one part answering (drop and turn).
 */
const {
  Cam, fit, facing, prism, proj, rings, rrect, ringAt, poly, hull, seg, clamp, unproj, rad,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 84, Y1 = 46, PH = 50, RT = 40, RB = 14, MZ = 74;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let dmax = 6 + value * 22;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-3, -3, 0], [X1 + 3, Y1 + 3, 0], [X1 + 3, -3, 0], [-3, Y1 + 3, 0], [X1, 0, MZ + 4], [X1 / 2, Y1 / 2, MZ + 4], [0, Y1, PH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x, y) => { const [r, i] = rings(x - 2.6, y - 2.6, x + 2.6, y + 2.6, 1.4, 0.7); put(solid(g), prism(P, front, r, i, 0, PH)); };
  const rail = (par, x0, x1, y, z0, z1) => { const [r, i] = rings(x0, y - 1.3, x1, y + 1.3, 1.2, 0.5); const s = solid(par); put(s, prism(P, front, r, i, z0, z1)); return s; };
  const slats = (y, d) => { let s = ""; for (let x = 8; x < X1 - 4; x += 6) s += seg(P(x, y, RB + 3 - d), P(x, y, RT - d)); return s; };

  // back: posts, side, mattress
  post(0, 0); post(X1, 0);
  rail(g, 2, X1 - 2, 0, RB, RB + 3); mk("path", { d: slats(0, 0), class: "lo nf" }, g); rail(g, 2, X1 - 2, 0, RT, RT + 3);
  const [mr, mi] = rings(3, 3, X1 - 3, Y1 - 3, 4, 1.6);
  put(solid(g), prism(P, front, mr, mi, RB - 2, RB + 6));
  post(0, Y1);

  // front drop-side, redrawn as it slides
  const fg = mk("g", {}, g);
  const fb = solid(fg), fs = mk("path", { class: "lo nf" }, fg), ft = solid(fg);
  post(X1, Y1);

  // the mobile: an arm from the back post, four toys on threads
  const ax = X1 / 2, ay = Y1 / 2;
  mk("path", { d: seg(P(X1, 0, PH), P(X1, 0, MZ)) + seg(P(X1, 0, MZ), P(ax, ay, MZ)), class: "nf" }, g);
  const mob = mk("g", {}, g);
  const thr = mk("path", { class: "lo nf" }, mob);
  const toys = [0, 1, 2, 3].map(() => mk("path", {}, mob));

  const sp = spring(0.25);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const d = p * dmax;
    const [br, bi] = rings(3, Y1 - 1.3, X1 - 3, Y1 + 1.3, 1.2, 0.5);
    put(fb, prism(P, front, br, bi, RB - d, RB + 3 - d));
    fs.setAttribute("d", slats(Y1, d));
    put(ft, prism(P, front, br, bi, RT - d, RT + 3 - d));
    const a0 = rad(20 + p * 120);
    let th = "";
    toys.forEach((t, k) => {
      const a = a0 + k * Math.PI / 2, x = ax + 14 * Math.cos(a), y = ay + 14 * Math.sin(a), z = MZ - 10 - (k % 2) * 5;
      th += seg(P(ax, ay, MZ), P(x, y, MZ - 3)) + seg(P(x, y, MZ - 3), P(x, y, z + 4));
      const ring = rrect(x - 3, y - 3, x + 3, y + 3, 3, 4);
      t.setAttribute("d", poly(hull(ringAt(P, ring, z - 3).concat(ringAt(P, ring, z + 3)))));
    });
    thr.setAttribute("d", th);
    // nearer toys paint last
    toys.map((t, k) => [t, Math.cos(a0 + k * Math.PI / 2) + Math.sin(a0 + k * Math.PI / 2)]).sort((u, v) => u[1] - v[1]).forEach(([t]) => mob.appendChild(t));
  }
  ft.sil.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(sp.x);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, RT * 0.6);
    const inside = x > -8 && x < X1 + 8 && y > -8 && y < Y1 + 8;
    sp.t = inside ? clamp(0.55 + (y / Y1) * 0.45, 0.55, 1) : 0.25;
    read.textContent = inside ? "drop " + Math.round(sp.t * dmax) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { sp.t = 0.25; read.textContent = "rest"; B.wake(); } }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { dmax = 6 + v * 22; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "crib",
  means: "A baby cot with slatted sides: over it, the front drop-side slides down between its posts and the mobile above turns.",
  rules: [1, 3, 5, 8],
  range: [0, 0.5, 1],
  tour: [[190, 144], [215, 190], [175, 176], null],
  mount,
});

highchair.code:
/**
 * High chair: a seat with a tall back and side panels on four splayed legs,
 * and a wide tray hinged at the front of the arms. The pointer over the chair
 * swings the tray up on its hinge to let the child in; at rest the tray sits
 * tipped a little, its edge bright. The slider is how far it swings.
 *
 * The pattern: one part answering (hinge).
 */
const {
  Cam, fit, facing, prism, proj, rings, rrect, ringAt, poly, hull, open, run, clamp, unproj, rad,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const SW = 32, SZ = 44, AZ = 56, HX = 34, TU = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = 45 + value * 40;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-12, -12, 0], [SW + 12, SW + 12, 0], [SW + 12, -12, 0], [-12, SW + 12, 0], [0, 0, 92], [HX, -6, AZ + TU + 2], [HX + TU, SW + 6, AZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 2, b = 1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  const leg = (fx, fy, tx, ty) => {
    const foot = rrect(fx - 2.4, fy - 2.4, fx + 2.4, fy + 2.4, 2.4, 3), top = rrect(tx - 2, ty - 2, tx + 2, ty + 2, 2, 3);
    put(solid(g), { sil: poly(hull(ringAt(P, foot, 0).concat(ringAt(P, top, SZ - 4)))), crease: "" });
  };

  // legs splay out, back to front; a footrest bar between the front pair
  leg(-10, -10, 3, 3);
  leg(SW + 10, -10, SW - 3, 3); leg(-10, SW + 10, 3, SW - 3);
  leg(SW + 10, SW + 10, SW - 3, SW - 3);
  box(SW + 2, 2, SW + 6, SW - 2, 16, 19, 1.5, 0.6);
  // back, seat, side panels
  box(0, 0, 4, SW, SZ, 92, 3, 1.2);
  box(0, 0, SW, SW, SZ - 6, SZ, 4, 1.6);
  box(4, -2, HX, 2, SZ, AZ, 2, 0.8);
  box(4, SW - 2, HX, SW + 2, SZ, AZ, 2, 0.8);

  // the tray: a thick plate hinged along x = HX at height AZ
  const tray = solid(g), lip = mk("path", { class: "lo nf" }, g);
  tray.sil.classList.add("hi");
  const ring = rrect(0, -8, TU, SW + 8, 5, 6), inner = rrect(2.5, -5.5, TU - 2.5, SW + 5.5, 3, 6);
  const at = (q, a, h) => {
    const c = Math.cos(a), s = Math.sin(a);
    return P(HX + q.u * c - h * s, q.v, AZ + q.u * s + h * c);
  };
  const sp = spring(0.15);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const a = rad(p * amax);
    const bot = ring.map((q) => at(q, a, 0)), top = ring.map((q) => at(q, a, 2.5));
    tray.sil.setAttribute("d", poly(hull(bot.concat(top))));
    tray.cr.setAttribute("d", poly(top));
    lip.setAttribute("d", poly(inner.map((q) => at(q, a, 3.6))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(sp.x);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, SZ);
    const inside = x > -10 && x < HX + TU + 4 && y > -12 && y < SW + 12;
    sp.t = inside ? clamp(0.6 + (x / (HX + TU)) * 0.4, 0.6, 1) : 0.15;
    read.textContent = inside ? "tray up" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { sp.t = 0.15; read.textContent = "rest"; B.wake(); } }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = 45 + v * 40; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "highchair",
  means: "A high chair on splayed legs: over it, the wide tray at the front of the arms swings up on its hinge to let the child in.",
  rules: [1, 3, 5, 8],
  range: [0, 0.5, 1],
  tour: [[243, 159], [224, 185], [205, 172], null],
  mount,
});

pushchair.code:
/**
 * Pushchair: a seat body on four wheels, a push handle at the back and a
 * folding hood of arched ribs hinged over the seat. The pointer over the
 * pushchair opens the hood forward, rib by rib; at rest it is half folded,
 * its front rib bright. The slider is how far the hood reaches.
 *
 * The pattern: one part answering (fold).
 */
const {
  Cam, fit, facing, prism, proj, rings, poly, hull, open, clamp, unproj, rad,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const L = 44, W = 26, BZ = 16, TZ = 34, HX = 10, NR = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = 60 + value * 35;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-18, -2, 0], [L + 8, W + 4, 0], [L + 8, -2, 0], [-18, W + 4, 0], [-18, W / 2, 72], [HX + 20, W / 2, TZ + 22]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => {
    const pts = [];
    for (let i = 0; i < 20; i++) { const t = (i / 20) * Math.PI * 2; for (const dy of [-1.6, 1.6]) pts.push(P(x + 8 * Math.cos(t), y + dy, 8 + 8 * Math.sin(t))); }
    put(solid(g), { sil: poly(hull(pts)), crease: "" });
  };
  // handle, far wheels, frame, body, near wheels
  mk("path", { d: open([P(2, 0, TZ), P(-16, 0, 70), P(-16, W, 70), P(2, W, TZ)]), class: "sil nf" }, g);
  wheel(4, -1); wheel(L - 4, -1);
  mk("path", { d: open([P(4, -1, 8), P(14, 0, BZ), P(L - 4, -1, 8)]) + open([P(4, W + 1, 8), P(14, W, BZ), P(L - 4, W + 1, 8)]), class: "lo nf" }, g);
  const [br, bi] = rings(0, 0, L, W, 7, 1.8);
  put(solid(g), prism(P, front, br, bi, BZ, TZ));
  wheel(4, W + 1); wheel(L - 4, W + 1);

  // the hood: arched ribs across the width, hinged on an axis along y at (HX, TZ)
  const hood = solid(g), ribs = mk("path", { class: "lo nf" }, g), lead = mk("path", { class: "sil hi nf" }, g);
  const rib = (phi) => {
    const pts = [];
    for (let i = 0; i <= 16; i++) { const s = (i / 16) * Math.PI, h = 20 * Math.sin(s), y = W / 2 - (W / 2 + 1) * Math.cos(s); pts.push(P(HX + h * Math.sin(phi), y, TZ + h * Math.cos(phi))); }
    return pts;
  };
  const sp = spring(0.08);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const a1 = rad(-35 + p * (amax + 35)), all = [];
    let rs = "";
    for (let k = 0; k < NR; k++) { const r = rib(rad(-35) + (a1 - rad(-35)) * (k / (NR - 1))); all.push(...r); if (k < NR - 1) rs += open(r); }
    hood.sil.setAttribute("d", poly(hull(all)));
    ribs.setAttribute("d", rs);
    lead.setAttribute("d", open(rib(a1)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(sp.x);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TZ);
    const inside = x > -18 && x < L + 8 && y > -4 && y < W + 4;
    sp.t = inside ? 1 : 0.08;
    read.textContent = inside ? "hood " + Math.round(sp.t * 100) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { sp.t = 0.08; read.textContent = "rest"; B.wake(); } }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = 60 + v * 35; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pushchair",
  means: "A pushchair on four wheels with a folding hood: over it, the hood opens forward over the seat, rib by rib.",
  rules: [1, 3, 5, 8],
  range: [0, 0.5, 1],
  tour: [[225, 174], [200, 160], [240, 195], null],
  mount,
});

cameraslider.code:
/**
 * Camera slider: a rail on two feet with a carriage and a camera on it. The
 * pointer's place along the rail is where the carriage dollies to, on a
 * spring, the lens turning out toward the viewer. At rest the carriage is
 * parked a third of the way along, the camera body bright. The slider is
 * the parking spot.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, clamp, lerp, unproj,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const L = 150, RY0 = 0, RY1 = 16, RZ0 = 18, RZ1 = 25, CW = 20, BZ0 = 31, BZ1 = 55;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let park = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-4, -6, 0], [L + 4, RY1 + 20, 0], [L + 4, -6, 0], [-4, RY1 + 20, 0], [CW, 8, BZ1 + 2], [L - CW, 8, BZ1 + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const x0 of [0, L - 14]) {
    const [fr, fi] = rings(x0 - 2, RY0 - 6, x0 + 16, RY1 + 6, 4, 1.2);
    put(solid(g), prism(P, front, fr, fi, 0, 4));
    const [lr, li] = rings(x0 + 3, RY0 + 3, x0 + 11, RY1 - 3, 3, 1);
    put(solid(g), prism(P, front, lr, li, 4, RZ0));
  }
  const [rr, ri] = rings(-4, RY0, L + 4, RY1, 3, 1.6);
  put(solid(g), prism(P, front, rr, ri, RZ0, RZ1));

  const cg = mk("g", {}, g);
  const plate = solid(cg), post = solid(cg), body = solid(cg), top = solid(cg);
  const lens = mk("path", { class: "sil" }, cg), glass = mk("path", { class: "nf lo" }, cg);
  body.sil.classList.add("hi");
  const sp = spring(lerp(CW, L - CW, park / 100));
  let last = NaN;

  function draw(x) {
    x = Math.round(x * 10) / 10;
    if (x === last) return;
    last = x;
    let a, b;
    [a, b] = rings(x - CW, RY0 - 5, x + CW, RY1 + 5, 4, 1.4); put(plate, prism(P, front, a, b, RZ1, RZ1 + 3));
    [a, b] = rings(x - 5, 3, x + 5, 13, 3, 1); put(post, prism(P, front, a, b, RZ1 + 3, BZ0));
    [a, b] = rings(x - CW + 2, RY0 - 2, x + CW - 2, RY1 - 2, 4, 1.6); put(body, prism(P, front, a, b, BZ0, BZ1));
    [a, b] = rings(x - 8, RY0 + 1, x + 6, RY1 - 6, 2.5, 1); put(top, prism(P, front, a, b, BZ1, BZ1 + 4));
    const zc = (BZ0 + BZ1) / 2, pts = [], ring = [];
    for (let i = 0; i < 24; i++) {
      const t = (i / 24) * Math.PI * 2, u = x + 3 + 9 * Math.cos(t), w = zc + 9 * Math.sin(t);
      pts.push(P(u, RY1 - 2, w), P(u, RY1 + 16, w));
      ring.push(P(x + 3 + 7 * Math.cos(t), RY1 + 16, zc + 7 * Math.sin(t)));
    }
    lens.setAttribute("d", poly(hull(pts)));
    glass.setAttribute("d", poly(ring));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(sp.x);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, RZ1);
    if (wy < -60 || wy > 80 || wx < -40 || wx > L + 40) return leave();
    sp.t = clamp(wx, CW, L - CW);
    read.textContent = "pos " + Math.round(((sp.t - CW) / (L - 2 * CW)) * 100);
    B.wake();
  }
  function leave() { sp.t = lerp(CW, L - CW, park / 100); read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { park = v; leave(); }, destroy: bag.dispose };
}

hairline({
  name: "cameraslider",
  means: "A camera on a slider rail: the carriage dollies along the rail to where the pointer is, on a spring.",
  rules: [1, 3, 5, 8],
  range: [0, 30, 100],
  tour: [[136, 125], [207, 160], [277, 195], null],
  mount,
});

vinylshelf.code:
/**
 * Record player: a plinth with a platter and record, a tonearm on its post,
 * and a dust lid hinged along the back. The pointer over the deck opens the
 * lid and swings the arm onto the record, staggered. At rest the lid is ajar,
 * bright. The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rad, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 110, D = 84, PZ = 14, LH = 16, AJ = 12;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, PZ + D], [W, 0, PZ + D]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let a, b;
  [a, b] = rings(0, 0, W, D, 6, 2); put(solid(g), prism(P, front, a, b, 0, PZ));
  put(solid(g), prism(P, front, disc(44, 44, 34), disc(44, 44, 32), PZ, PZ + 3));
  const rec = solid(g);
  put(rec, prism(P, front, disc(44, 44, 31), disc(44, 44, 12), PZ + 3, PZ + 4));
  mk("path", { d: poly(ringAt(P, disc(44, 44, 6, 20), PZ + 4)), class: "nf lo" }, g);
  [a, b] = rings(88, 12, 100, 24, 6, 1); put(solid(g), prism(P, front, a, b, PZ, PZ + 6));
  const arm = mk("path", { class: "nf" }, g), lid = mk("path", { class: "sil" }, g), lidc = mk("path", { class: "nf lo" }, g);
  const tA = tween(AJ), tR = tween(0);
  let lastA = NaN, lastR = NaN;

  function box(ang) {
    const c = Math.cos(rad(ang)), s = Math.sin(rad(ang)), pts = [];
    const q = (x, y, h) => P(x, y * c - h * s, PZ + y * s + h * c);
    for (const x of [0, W]) for (const y of [0, D]) for (const h of [0, LH]) pts.push(q(x, y, h));
    const cr = [q(2, D, LH), q(2, 2, LH), q(W - 2, 2, LH)];
    return [hull(pts), cr];
  }
  function draw(ang, r) {
    if (ang !== lastA) { lastA = ang; const [h, cr] = box(ang); lid.setAttribute("d", poly(h)); lidc.setAttribute("d", "M" + cr.map((p) => p.join(",")).join("L")); }
    if (r !== lastR) {
      lastR = r;
      const t = rad(100 + r * 42), ex = 94 + 58 * Math.cos(t), ey = 18 + 58 * Math.sin(t), z = PZ + 8;
      const pts = [];
      for (const [x, y] of [[94, 18], [ex, ey]]) for (const dz of [0, 2.4]) for (const [dx, dy] of [[-1.4, -1.4], [1.4, 1.4]]) pts.push(P(x + dx, y + dy, z + dz));
      arm.setAttribute("d", poly(hull(pts)));
    }
  }
  const B = register(stage, (_dt, now) => {
    draw(tval(tA, now), tval(tR, now));
    return !(tdone(tA, now) && tdone(tR, now));
  });
  bag.add(B.unregister);

  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    const now = performance.now();
    tset(tA, o ? 78 : AJ, now, o ? 0 : stag);
    tset(tR, o ? 1 : 0, now, o ? stag : 0);
    lid.classList.toggle("hi", !o);
    rec.sil.classList.toggle("hi", o);
    read.textContent = o ? "play" : "rest";
    B.wake();
  }
  set(false);
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, PZ);
    set(wx > -20 && wx < W + 20 && wy > -20 && wy < D + 20);
  }
  bag.add(pointer(stage, { move, leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "vinylshelf",
  means: "A record player: the pointer over the deck swings its dust lid open, then the tonearm onto the record.",
  rules: [1, 2, 5, 6],
  range: [0, 160, 400],
  tour: [[184, 165], [184, 213], [209, 270], null],
  mount,
});

bikelock.code:
/**
 * Bike lock: a hoop rack on a slab, a U-lock hung over its top bar. The
 * pointer's place along the rack slides the lock there, and its place across
 * swings the lock round the bar. At rest the lock hangs off centre, its body
 * bright. The slider is how far it swings.
 *
 * The pattern: continuous values read from the pointer (spring).
 */
const {
  Cam, fit, hull, poly, proj, rings, prism, facing, unproj, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BY = 40, BZ = 62, X0 = 12, X1 = 108;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-4, 18, 0], [124, 62, 0], [124, 18, 0], [-4, 62, 0], [X0, BY, BZ + 12], [X1, BY, BZ + 12], [60, BY + 40, 30], [60, BY - 40, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ra, ri] = rings(-4, 18, 124, 62, 6, 2); put(solid(g), prism(P, front, ra, ri, 0, 3));
  const cap = (a, b, r) => {
    const pts = [];
    for (const q of [P(...a), P(...b)]) for (let i = 0; i < 16; i++) pts.push([q[0] + Math.cos(i * Math.PI / 8) * r * 2.1, q[1] + Math.sin(i * Math.PI / 8) * r * 2.1]);
    return poly(hull(pts));
  };
  const tube = [[X0, BY, 3], [X0, BY, BZ - 10], [X0 + 10, BY, BZ], [X1 - 10, BY, BZ], [X1, BY, BZ - 10], [X1, BY, 3]];
  const rack = mk("g", {}, g);
  for (let i = 0; i < tube.length - 1; i++) mk("path", { d: cap(tube[i], tube[i + 1], 2.4) }, rack);
  const lk = mk("g", {}, g);
  const band = mk("path", { class: "sil" }, lk), body = mk("path", { class: "sil" }, lk), key = mk("circle", { r: 2.2, class: "dot off" }, lk);

  const xs = spring(78), ph = spring(22);
  let last = "";
  function draw(x, f) {
    const k = r2(x) + "," + r2(f);
    if (k === last) return;
    last = k;
    const c = Math.cos(rad(f)), s = Math.sin(rad(f));
    const W = (v, w) => [x, BY + v * c - w * s, BZ + v * s + w * c];
    const pts = [];
    for (let i = 0; i <= 12; i++) { const t = Math.PI - (i / 12) * Math.PI; pts.push(P(...W(8.6 * Math.cos(t), 8.6 * Math.sin(t) - 3))); }
    pts.push(P(...W(8.6, -36)), P(...W(5.2, -36)));
    for (let i = 0; i <= 12; i++) { const t = (i / 12) * Math.PI; pts.push(P(...W(5.2 * Math.cos(t), 5.2 * Math.sin(t) - 3))); }
    pts.push(P(...W(-5.2, -36)), P(...W(-8.6, -36)));
    band.setAttribute("d", poly(pts));
    body.setAttribute("d", cap(W(-13, -38), W(13, -38), 5.5));
    const q = P(...W(9, -38)); key.setAttribute("cx", q[0]); key.setAttribute("cy", q[1]);
  }
  const r2 = (n) => Math.round(n * 10) / 10;
  const B = register(stage, (dt) => { const a = stepS(xs, dt), b = stepS(ph, dt); draw(xs.x, ph.x); return a || b; });
  bag.add(B.unregister);

  // the ground never moves: read both values from the pointer on it
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x < -10 || x > 130 || y < -20 || y > 100 ? null : [clamp(x, 30, 92), clamp((y - BY) / 40, -1, 1)];
  }
  let act = null;
  function set(h) {
    act = h;
    xs.t = h ? h[0] : 78; ph.t = h ? h[1] * reach : 22;
    body.classList.toggle("hi", !h);
    band.classList.toggle("hi", !!h);
    read.textContent = h ? Math.round(ph.t) + "°" : "rest";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) set(act); }, destroy: bag.dispose };
}

hairline({
  name: "bikelock",
  means: "A U-lock hung on a hoop bike rack: it slides along the bar to the pointer and swings round it toward the pointer's side.",
  rules: [1, 3, 5, 8],
  range: [20, 60, 80],
  tour: [[304, 212], [200, 219], [103, 230], null],
  mount,
});

shutterdoor.code:
/**
 * Roller shutter: a shop front between two posts under a roll box, a
 * slatted shutter hanging in the opening, a counter inside. The pointer's
 * height on the front rolls the shutter up past it, so the shop shows
 * where you point. At rest the shutter hangs a third open, its lock bright.
 * The slider is how far the shutter may roll.
 *
 * The pattern: one continuous value read from the pointer (spring).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, seg, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, D = 16, H = 78, G = 3, PO = 7, REST = 0.34;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-10, -8, 0], [W + 10, D + 14, 0], [W + 10, -8, 0], [-10, D + 14, 0], [-3, -3, G + H + 14], [W + 3, D + 5, G + H + 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 2, b = 1.2, parent = g) => {
    const [ring, inner] = rings(x0, y0, x1, y1, r, b);
    const s = solid(parent); put(s, prism(P, front, ring, inner, z0, z1)); return s;
  };
  box(-10, -8, W + 10, D + 14, 0, G, 5, 2);
  box(0, 0, W, 3, G, G + H, 1.5, 0.8);
  // a door in the back wall, a shelf line
  mk("path", { class: "lo nf", d: poly([P(78, 3, G), P(102, 3, G), P(102, 3, G + 48), P(78, 3, G + 48)]) }, g);
  mk("path", { class: "lo nf", d: seg(P(PO + 4, 3, G + 52), P(70, 3, G + 52)) + seg(P(PO + 4, 3, G + 36), P(70, 3, G + 36)) }, g);
  box(18, 6, 62, 13, G, G + 24, 2, 1.2);
  box(0, 0, PO, D, G, G + H, 1.5, 0.8);
  const sh = mk("g", {}, g);
  const plate = mk("path", { class: "sil" }, sh), slats = mk("path", { class: "lo nf" }, sh), bar = mk("path", { class: "nf" }, sh);
  const lock = mk("circle", { r: 2.4, class: "dot" }, sh);
  box(W - PO, 0, W, D, G, G + H, 1.5, 0.8);
  box(-3, -3, W + 3, D + 5, G + H, G + H + 14, 3, 1.4);

  const zb = spring(H * REST);
  let last = NaN;
  function draw(z) {
    const r = Math.round(z * 10) / 10;
    if (r === last) return;
    last = r;
    const y = D - 1, x0 = PO, x1 = W - PO, b = G + r, t = G + H;
    plate.setAttribute("d", poly([P(x0, y, b), P(x1, y, b), P(x1, y, t), P(x0, y, t)]));
    let d = "";
    for (let s = t - 5; s > b + 4; s -= 5) d += seg(P(x0, y, s), P(x1, y, s));
    slats.setAttribute("d", d);
    bar.setAttribute("d", poly([P(x0, y + 0.6, b), P(x1, y + 0.6, b), P(x1, y + 0.6, b + 3), P(x0, y + 0.6, b + 3)]));
    const p = P(W / 2, y + 0.6, b + 1.5); lock.setAttribute("cx", p[0]); lock.setAttribute("cy", p[1]);
  }

  const B = register(stage, (dt) => { const m = stepS(zb, dt); draw(zb.x); return m; });
  bag.add(B.unregister);

  // the front face at rest never moves: read world x from screen x, then height
  const a0 = P(0, D, 0), a1 = P(W, D, 0), dz = P(0, D, 0)[1] - P(0, D, 1)[1];
  function hit([sx, sy]) {
    const u = (sx - a0[0]) / (a1[0] - a0[0]);
    if (u < 0.02 || u > 0.98) return null;
    const x = u * W, z = (P(x, D, G)[1] - sy) / dz;
    return z < -6 || z > H + 4 ? null : z;
  }
  let act = null;
  function set(z) {
    act = z;
    zb.t = z === null ? H * REST : clamp(z + 14, 6, H * reach);
    plate.classList.toggle("hi", z !== null);
    lock.setAttribute("class", z === null ? "dot" : "dot off");
    read.textContent = z === null ? "rest" : Math.round((zb.t / H) * 100) + "% up";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; if (act !== null) set(act); }, destroy: bag.dispose };
}

hairline({
  name: "shutterdoor",
  means: "A slatted roller shutter on a shop front: it rolls up past the pointer's height to show the counter inside.",
  rules: [1, 3, 5, 8],
  range: [40, 100, 100],
  tour: [[136, 193], [193, 144], [249, 155], null],
  mount,
});

servercool.code:
/**
 * Rack fans: a 2U rack chassis with a row of four cooling fans behind a
 * front tray door, hinged along its foot. The pointer is the hand on the
 * door: it swings down and out toward the pointer, opening on the fans, and
 * goes bright. At rest the door stands just ajar with its latch lit. The
 * slider is how stiff the hinge is.
 *
 * The pattern: a continuous swing on one spring; the hit is the floor's
 * plane, which never moves.
 */
const {
  Cam, facing, fit, hull, poly, prism, proj, rings, rrect, spring, stepS, unproj,
  disposer, mk, place, pointer, put, register, solid, clamp, rad,
} = HL;

const X = 48, Y0 = -34, Y1 = 8, ZH = 30, T = 2.4, A1 = 84, REST = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.15);
  const at = (a, u, w, d) => [u, Y1 + w * Math.sin(rad(a)) + d * Math.cos(rad(a)), w * Math.cos(rad(a)) - d * Math.sin(rad(a))];
  fit(C, [[-X, Y0, 0], [X, Y1, ZH], at(A1, -X, ZH - 2, T), at(A1, X, ZH - 2, T)], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [cR, cI] = rings(-X - 4, Y0, X + 4, Y1, 3, 1.4);
  put(solid(g), prism(P, front, cR, cI, 0, ZH + 2));
  // four fans on the chassis front, each a ring and a hub
  for (let i = 0; i < 4; i++) {
    const cx = -36 + i * 24, d = [];
    for (const r of [10, 3]) {
      const ring = [];
      for (let k = 0; k < 28; k++) { const t = (k / 28) * Math.PI * 2; ring.push(P(cx + r * Math.cos(t), Y1, 15 + r * Math.sin(t))); }
      d.push(poly(ring));
    }
    for (let k = 0; k < 5; k++) { const t = (k / 5) * Math.PI * 2 + i; d.push("M" + P(cx + 3 * Math.cos(t), Y1, 15 + 3 * Math.sin(t)) + "L" + P(cx + 9 * Math.cos(t + 0.5), Y1, 15 + 9 * Math.sin(t + 0.5))); }
    mk("path", { class: "nf lo", d: d.join("") }, g);
  }
  const door = solid(g);
  const grille = mk("path", { class: "nf lo" }, door.g);
  const latch = mk("circle", { class: "dot", r: 1.6 }, door.g);
  const outer = rrect(-X, 0, X, ZH - 2, 3, 4);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, over = false;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-3) return;
    drawn = a;
    const pts = outer.map((q) => P(...at(a, q.u, q.v, 0))).concat(outer.map((q) => P(...at(a, q.u, q.v, T))));
    door.sil.setAttribute("d", poly(hull(pts)));
    door.cr.setAttribute("d", poly(outer.map((q) => P(...at(a, q.u * 0.97, 0.8 + q.v * 0.94, T)))));
    let d = "";
    for (let k = 1; k < 8; k++) { const u = -X + k * 12; d += "M" + P(...at(a, u, 5, T)) + "L" + P(...at(a, u, ZH - 7, T)); }
    grille.setAttribute("d", d);
    place(latch, P(...at(a, 0, ZH - 4.5, T)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function show() {
    door.sil.classList.toggle("hi", over);
    latch.setAttribute("class", over ? "dot m" : "dot");
    read.textContent = over ? Math.round(sp.t) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(x) > X + 20 || y < Y0 || y > Y1 + 60) { over = false; sp.t = REST; show(); return; }
      over = true; sp.t = clamp(((y - Y1 + 6) / 38) * A1, 0, A1); show();
    },
    leave: () => { over = false; sp.t = REST; show(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); show();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "servercool",
  means: "A rack chassis with four cooling fans behind a tray door: the door swings down toward the pointer, opening on the fans.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[173, 151], [241, 208], [173, 196], null],
  mount,
});

tabletstand.code:
/**
 * Tablet stand: a tablet resting on a desk stand, its foot in a front lip,
 * leaning back on a hinged strut. The pointer is the tablet's top edge: the
 * tablet tilts on its hinge until its top sits under the pointer, from nearly
 * upright to laid far back. At rest it leans a little past upright and the
 * camera dot is bright. The slider is how stiff the hinge is.
 *
 * The pattern: a continuous tilt on one spring; the hit is a table of rest
 * poses (angle -> screen height of the top edge), which never moves.
 */
const {
  Cam, facing, fit, hull, poly, prism, proj, rings, rrect, seg, spring, stepS,
  disposer, mk, place, pointer, put, register, solid, clamp, rad,
} = HL;

const W = 46, H = 66, T = 2.4, HY = 20, HZ = 3.5, A0 = 8, A1 = 68, REST = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  // a tablet point: u across, w up the face, d into its back
  const at = (a, u, w, d) => {
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    return [u, HY - w * s - d * c, HZ + w * c - d * s];
  };
  const ext = [[-44, -36, 0], [44, 30, 0]];
  for (const a of [A0, A1]) for (const u of [-W, W]) for (const w of [0, H]) ext.push(at(a, u, w, 0));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // base plate, strut guide, tablet, then the lip in front of its foot
  const [bR, bI] = rings(-40, -32, 40, 26, 6, 1.6);
  put(solid(g), prism(P, front, bR, bI, 0, HZ));
  const strut = mk("path", { class: "nf sil" }, g);
  const tab = solid(g);
  const screen = mk("path", { class: "nf lo" }, tab.g);
  const cam = mk("circle", { class: "dot", r: 1.6 }, tab.g);
  const [lR, lI] = rings(-36, HY + 1, 36, HY + 6, 2, 0.8);
  put(solid(g), prism(P, front, lR, lI, HZ, HZ + 5));

  const outer = rrect(-W, 0, W, H, 5, 6), inner = rrect(-W + 4, 5, W - 4, H - 5, 2.5, 4);
  const table = [];
  for (let a = A0; a <= A1; a += 0.5) table.push([a, P(...at(a, 0, H, 0))[1]]);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, over = false;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-3) return;
    drawn = a;
    const pts = outer.map((q) => P(...at(a, q.u, q.v, 0))).concat(outer.map((q) => P(...at(a, q.u, q.v, T))));
    tab.sil.setAttribute("d", poly(hull(pts)));
    tab.cr.setAttribute("d", poly(outer.map((q) => P(...at(a, q.u * 0.97, 1.5 + q.v * 0.955, 0)))));
    screen.setAttribute("d", poly(inner.map((q) => P(...at(a, q.u, q.v, 0)))));
    place(cam, P(...at(a, 0, H - 2.6, 0)));
    // the strut runs from the back of the base up to the tablet's back
    let d = "";
    for (const u of [-22, 22]) d += seg(P(u, -28, HZ), P(...at(a, u, H * 0.55, T)));
    strut.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function show() {
    tab.sil.classList.toggle("hi", over);
    cam.setAttribute("class", over ? "dot m" : "dot");
    read.textContent = over ? Math.round(sp.t) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      if (p[0] < 60 || p[0] > 340) { over = false; sp.t = REST; show(); return; }
      let best = REST, bd = Infinity;
      for (const [a, y] of table) { const d = Math.abs(y - p[1]); if (d < bd) { bd = d; best = a; } }
      over = true; sp.t = clamp(best, A0, A1); show();
    },
    leave: () => { over = false; sp.t = REST; show(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); show();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "tabletstand",
  means: "A tablet on a hinged desk stand: it tilts back on its hinge until its top edge sits under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[185, 109], [130, 183], [213, 252], null],
  mount,
});

lockerroom.code:
/**
 * Locker bench: a row of tall lockers with a bench before them. The pointer
 * picks a locker by where it stands: its door swings open on its hinge, and
 * the doors beside it swing a little, staggered from it. At rest one door
 * stands ajar, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row, turned on a hinge.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, fillet, seg, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, W = 28, D = 22, H = 78, FAV = 2, OPEN = 82, NEAR = 34, AJAR = 38;
const X1 = N * W, BY = D + 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[0, 0, H], [X1, 0, H], [0, BY + 10, 0], [X1, BY + 10, 0], [0, D + W, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, D, 2, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const inner = mk("path", { class: "nf lo" }, g);
  let dIn = "";
  for (let k = 0; k < N; k++) {
    const x0 = k * W;
    dIn += seg(P(x0 + 3, D, H * 0.72), P(x0 + W - 3, D, H * 0.72)) + seg(P(x0 + W / 2, D, H * 0.66), P(x0 + W / 2, D, H * 0.6));
  }
  inner.setAttribute("d", dIn);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const plate = mk("path", { class: "sil" }, grp), marks = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0: k * W, plate, marks, a: tween(k === FAV ? AJAR : 0), last: NaN });
  }
  // the bench: two legs and a slatted top
  const bg = mk("g", {}, svg);
  for (const lx of [10, X1 - 16]) { const [lr, li] = rings(lx, BY + 1, lx + 6, BY + 9, 1, 0.8); put(solid(bg), prism(P, front, lr, li, 0, 16)); }
  const [tr, ti] = rings(4, BY, X1 - 4, BY + 10, 2, 1.2);
  put(solid(bg), prism(P, front, tr, ti, 16, 19.5));

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const a = rad(deg), w = W - 1.4, hx = it.x0 + 0.7, hy = D + 0.5;
    const at = (t, z) => P(hx + w * t * Math.cos(a), hy + w * t * Math.sin(a), z);
    it.plate.setAttribute("d", poly(fillet([at(0, 2), at(1, 2), at(1, H - 2), at(0, H - 2)], [1.5, 1.5, 1.5, 1.5])));
    let m = "";
    for (let v = 0; v < 3; v++) m += seg(at(0.25, H - 10 - v * 4), at(0.75, H - 10 - v * 4));
    m += seg(at(0.86, H * 0.5 - 5), at(0.86, H * 0.5 + 5));
    it.marks.setAttribute("d", m);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + W / 2, D, H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 30 && Math.abs(mids[best][1] - sy) < 95 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? (k === FAV ? AJAR : 0) : dd === 0 ? OPEN : dd === 1 ? NEAR : 10;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.plate.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "locker " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "lockerroom",
  means: "Tall lockers behind a bench: the door under the pointer swings open on its hinge, and the doors beside it swing ajar.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[160, 135], [194, 152], [262, 186], null],
  mount,
});

yogamats.code:
/**
 * Yoga mats: five rolled mats standing in a floor rack with a back rail.
 * The pointer picks a mat by where it stands: it tips forward out of the
 * rack, and the mats beside it lean a little, staggered from it. At rest
 * one mat leans, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row, tilted on its foot.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, R = 8.5, H = 62, STEP = 20, FAV = 3, TIP = 30, LEAN = 9, REST_T = 16, BZ = 4;
const X1 = (N - 1) * STEP + 2 * R + 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -R - 10, BZ + H + 8], [X1, -R - 10, 0], [-4, R + 6, 0], [X1, R + 6, 0], [0, H * 0.55, BZ + H * 0.85]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // back rail: two posts and a bar
  for (const px of [0, X1 - 6]) { const [pr, pi] = rings(px, -R - 8, px + 4, -R - 4, 1, 0.8); put(solid(g), prism(P, front, pr, pi, 0, H * 0.7)); }
  const [rr, ri] = rings(-2, -R - 8, X1 - 0, -R - 4, 1.5, 0.8);
  put(solid(g), prism(P, front, rr, ri, H * 0.7 - 5, H * 0.7));
  const [tr, ti] = rings(-4, -R - 4, X1, R + 6, 3, 1.4);
  put(solid(g), prism(P, front, tr, ti, 0, BZ));

  const circle = (x, a, z, r, n = 32) => {
    const o = [], s = Math.sin(a), c = Math.cos(a);
    for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI, cu = Math.cos(t) * r, cv = Math.sin(t) * r; o.push(P(x + cu, z * s + cv * c, BZ + z * c - cv * s)); }
    return o;
  };
  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    const body = mk("path", { class: "sil" }, grp), end = mk("path", { class: "nf lo" }, grp), band = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x: R + 3 + k * STEP, body, end, band, a: tween(k === FAV ? REST_T : 0), last: NaN });
  }

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const a = rad(deg), top = circle(it.x, a, H, R);
    it.body.setAttribute("d", poly(hull(circle(it.x, a, 0, R).concat(top))));
    it.end.setAttribute("d", poly(top) + poly(circle(it.x, a, H, R * 0.55, 24)) + poly(circle(it.x, a, H, R * 0.2, 12)));
    const s = Math.sin(a), c = Math.cos(a), bz = H * 0.3, at = (u, z) => P(it.x + u, z * s + R * c, BZ + z * c - R * s);
    it.band.setAttribute("d", seg(at(-R * 0.6, bz), at(R * 0.6, bz)) + seg(at(-R * 0.6, bz + 4), at(R * 0.6, bz + 4)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, BZ + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), deg = a < 0 ? (k === FAV ? REST_T : 0) : dd === 0 ? TIP : dd === 1 ? LEAN : 0;
      tset(it.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "mat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "yogamats",
  means: "Rolled yoga mats standing in a rack: the mat under the pointer tips forward out of it, and the mats beside it lean.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[154, 144], [183, 158], [268, 201], null],
  mount,
});

abwheel.code:
/**
 * Ab roller: a wheel on a long axle with two handles, standing on an
 * exercise mat whose far end is still rolled up. The pointer's place along
 * the mat is where the roller goes: it rolls out on a spring, its spokes
 * turning as it travels. At rest it waits near the roll. The slider is how
 * far down the mat it may reach.
 *
 * The pattern: one part following the pointer along a track (terrain).
 */
const {
  Cam, fit, poly, prism, proj, rings, facing, hull, seg, clamp, lerp, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 19, T = 12, HL_ = 18, HR = 3, MX0 = 0, MX1 = 190, MY = 30, X0 = 44, XM = 172, REST = 52;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[MX0, -MY, 0], [MX1, -MY, 0], [MX0, MY, 0], [MX1, MY, 0], [X0, 0, 2 * R + 2], [XM, 0, 2 * R + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(MX0 + 6, -MY, MX1, MY, 3, 1.4);
  put(solid(g), prism(P, front, mr, mi, 0, 1.4));
  const ring = (x, z, r, y, n = 32) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push(P(x + r * Math.cos(t), y, z + r * Math.sin(t))); } return o; };
  const cylY = (x, z, r, ya, yb) => poly(hull(ring(x, z, r, ya).concat(ring(x, z, r, yb))));
  // the rolled-up end of the mat
  mk("path", { d: cylY(10, 9, 9, -MY, MY), class: "sil" }, g);
  mk("path", { d: poly(ring(10, 9, 9, MY)) + poly(ring(10, 9, 4.5, MY)), class: "nf lo" }, g);
  mk("path", { d: seg(P(10, MY, 18), P(18, MY, 1.4)), class: "lo" }, g);

  const farH = mk("path", { class: "sil" }, g), farCap = mk("path", { class: "nf lo" }, g);
  const wheel = mk("path", { class: "sil hi" }, g), face = mk("path", { class: "nf lo" }, g), spokes = mk("path", { class: "nf" }, g);
  const nearH = mk("path", { class: "sil" }, g), nearCap = mk("path", { class: "nf lo" }, g);
  const pos = spring(REST);
  let last = NaN;

  function draw(x) {
    if (x === last) return;
    last = x;
    const z = R + 1.4, y0 = -T / 2, y1 = T / 2, th = -(x - X0) / R;
    farH.setAttribute("d", cylY(x, z, HR, y0 - HL_, y0));
    farCap.setAttribute("d", seg(...[-1, 1].map((s) => P(x, y0 - HL_ * 0.55, z + s * HR))));
    wheel.setAttribute("d", cylY(x, z, R, y0, y1));
    face.setAttribute("d", poly(ring(x, z, R - 4, y1, 40)) + poly(ring(x, z, 4, y1, 20)));
    let s = "";
    for (let k = 0; k < 3; k++) { const a = th + (k * 2 * Math.PI) / 3; s += seg(P(x + 5 * Math.cos(a), y1, z + 5 * Math.sin(a)), P(x + (R - 6) * Math.cos(a), y1, z + (R - 6) * Math.sin(a))); }
    spokes.setAttribute("d", s);
    nearH.setAttribute("d", cylY(x, z, HR, y1, y1 + HL_));
    nearCap.setAttribute("d", poly(ring(x, z, HR - 1, y1 + HL_, 16)) + seg(...[-1, 1].map((s2) => P(x, y1 + HL_ * 0.45, z + s2 * HR))));
  }

  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(B.unregister);

  function aim(t) {
    pos.t = t;
    read.textContent = t === REST ? "rest" : Math.round(((t - X0) / (XM - X0)) * 100) + "%";
    B.wake();
  }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (Math.abs(wy) > MY + 20 || wx < MX0 - 10 || wx > MX1 + 20) return aim(REST);
    aim(Math.round(clamp(wx, X0, lerp(X0 + 30, XM, reach))));
  }
  aim(REST);
  draw(REST);
  bag.add(pointer(stage, { move, leave: () => aim(REST) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "abwheel",
  means: "An ab roller on a mat with a rolled-up end: it rolls out along the mat to the pointer, its spokes turning as it goes.",
  rules: [1, 3, 5, 8],
  range: [0, 100, 100],
  tour: [[160, 157], [274, 214], [302, 228], null],
  mount,
});

ibeam.code:
/**
 * Steel beams: four I-beams laid side by side in a yard, ends staggered.
 * The pointer picks a beam by where it is across the row: the crane takes
 * it up and slews it round, the others shift a little, staggered from it.
 * At rest one beam lies slightly skewed, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row; the hit is on a fixed plane
 * through the beams' resting tops.
 */
const { Cam, clamp, facing, fit, prism, proj, rings, unproj, tdone, tset, tval, tween, disposer, put, register, solid, mk, pointer } = HL;

const N = 4, L = 34, W = 5, FT = 2, WT = 1.1, H = 11, GAP = 15, LIFT = 26, SWING = 34;
const RX = [0, 7, -4, 3], RROT = [0, 0, 7, 0], FAV = 2;

function rot(ring, cx, cy, a) {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((p) => ({ u: cx + c * p.u - s * p.v, v: cy + s * p.u + c * p.v, nu: c * p.nu - s * p.nv, nv: s * p.nu + c * p.nv }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.0);
  const Y1 = (N - 1) * GAP;
  fit(C, [[-L - 6, -W, 0], [L + 8, Y1 + W, 0], [L + 8, -W, 0], [-L - 6, Y1 + W, 0], [0, GAP, H + LIFT], [-L, GAP, H + LIFT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const beams = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    beams.push({ k, grp, parts: [solid(grp), solid(grp), solid(grp)], z: tween(0), a: tween(RROT[k]), dx: tween(RX[k]), last: "" });
  }
  // the three plates of an I: bottom flange, web, top flange, around the beam's centre
  const PLATES = [[W, 0, FT], [WT, FT, H - FT], [W, H - FT, H]];
  function draw(b, z, a, dx) {
    const key = z.toFixed(2) + a.toFixed(2) + dx.toFixed(2);
    if (key === b.last) return;
    b.last = key;
    PLATES.forEach(([hw, z0, z1], i) => {
      const [r, n] = rings(-L, -hw, L, hw, Math.min(1, hw * 0.6), Math.min(0.5, hw * 0.4));
      put(b.parts[i], prism(P, front, rot(r, dx, b.k * GAP, (a * Math.PI) / 180), rot(n, dx, b.k * GAP, (a * Math.PI) / 180), z + z0, z + z1));
    });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    beams.forEach((b) => {
      draw(b, tval(b.z, now), tval(b.a, now), tval(b.dx, now));
      if (!tdone(b.z, now) || !tdone(b.a, now) || !tdone(b.dx, now)) moving = true;
    });
    // the lifted beam is painted last; the rest far to near
    const order = beams.slice().sort((p, q) => (tval(p.z, now) > H * 0.5) - (tval(q.z, now) > H * 0.5) || p.k - q.k);
    order.forEach((b) => { if (g.lastChild !== b.grp) g.appendChild(b.grp); });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < -L - 8 || x > L + 10 || y < -W - 6 || y > Y1 + W + 6) return -1;
    return clamp(Math.round(y / GAP), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    beams.forEach((b, k) => {
      const d = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(b.z, a === k ? LIFT : 0, now, d);
      tset(b.a, a < 0 ? RROT[k] : a === k ? SWING : 0, now, d);
      tset(b.dx, a < 0 ? RX[k] : a === k ? 4 : RX[k] - 3 * Math.sign(k - a), now, d);
      b.parts.forEach((p) => p.sil.classList.toggle("hi", k === (a < 0 ? FAV : a)));
    });
    read.textContent = a < 0 ? "rest" : "beam " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ibeam",
  means: "Four steel I-beams in a row: the crane lifts the beam under the pointer and slews it round, the others shift after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[182, 119], [182, 183], [214, 230], null],
  mount,
});

pegboardkids.code:
/**
 * Peg board: a toy board with a five-by-five grid of holes and chunky pegs
 * standing in some of them, of different heights. The pegs lean away from
 * the pointer like grass under a hand, most near it, little beyond; the
 * peg nearest it goes bright. At rest they stand with a slight, uneven lean.
 *
 * The pattern: a field answering a continuous input (terrain); the hit is
 * the board's top plane, one spring per peg.
 */
const { Cam, circ, clamp, fit, hull, open, poly, prism, proj, rings, ringAt, unproj, spring, stepS, facing, disposer, mk, pointer, put, register, solid } = HL;

const G = 5, SP = 13, T = 5, PR = 3.4, MAXL = 9;
const PEGS = [[0, 1, 16], [1, 3, 22], [1, 0, 12], [2, 2, 26], [3, 1, 18], [3, 4, 14], [4, 2, 20], [2, 4, 10], [0, 3, 13], [4, 0, 9]];
const FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.8);
  const E = (G - 1) * SP;
  fit(C, [[-9, -9, 0], [E + 9, E + 9, 0], [E + 9, -9, 0], [-9, E + 9, 0], [2 * SP, 2 * SP, T + 26], [-4, -4, T + 22]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(-9, -9, E + 9, E + 9, 5, 1.6);
  const board = solid(g);
  put(board, prism(P, front, br, bi, 0, T));
  let holes = "";
  for (let i = 0; i < G; i++) for (let j = 0; j < G; j++) holes += poly(ringAt(P, circ(PR * 0.7, 12).map((s) => ({ ...s, u: s.u + i * SP, v: s.v + j * SP })), T));
  mk("path", { class: "nf lo", d: holes }, board.g);

  const ring = circ(PR, 16);
  const pegs = PEGS.map(([i, j, h], k) => ({ k, x: i * SP, y: j * SP, h, s: solid(g), lx: spring(((k * 7) % 5 - 2) * 0.7), ly: spring(((k * 3) % 5 - 2) * 0.6), last: "" }))
    .sort((a, b) => a.x + a.y - (b.x + b.y));
  pegs.forEach((p) => g.appendChild(p.s.g));
  const at = (r, x, y) => r.map((s) => ({ ...s, u: s.u + x, v: s.v + y }));
  function draw(p) {
    const key = p.lx.x.toFixed(2) + p.ly.x.toFixed(2);
    if (key === p.last) return;
    p.last = key;
    const base = ringAt(P, at(ring, p.x, p.y), T), top = ringAt(P, at(ring, p.x + p.lx.x, p.y + p.ly.x), T + p.h);
    p.s.sil.setAttribute("d", poly(hull(base.concat(top))));
    p.s.cr.setAttribute("d", poly(ringAt(P, at(circ(PR - 1, 16), p.x + p.lx.x, p.y + p.ly.x), T + p.h)));
  }
  pegs.forEach((p) => p.s.cr.setAttribute("class", "nf lo"));

  const B = register(stage, (dt) => {
    let m = false;
    pegs.forEach((p) => { if (stepS(p.lx, dt)) m = true; if (stepS(p.ly, dt)) m = true; draw(p); });
    return m;
  });
  bag.add(B.unregister);

  let lastNear = -2;
  function setPoint(pt) {
    let near = -1;
    if (pt) {
      const R = 14 + reach * 0.3;
      let best = 1e9;
      pegs.forEach((p) => {
        const dx = p.x - pt[0], dy = p.y - pt[1], d = Math.hypot(dx, dy) || 1e-3;
        const f = d < R ? 1 - 0.69 * (d / R) : 0.31 * Math.exp(-(d - R) / 8);
        const lean = clamp(MAXL * f, 0, MAXL);
        p.lx.t = (dx / d) * lean; p.ly.t = (dy / d) * lean;
        if (d < best) { best = d; near = p.k; }
      });
    } else pegs.forEach((p) => { p.lx.t = ((p.k * 7) % 5 - 2) * 0.7; p.ly.t = ((p.k * 3) % 5 - 2) * 0.6; });
    if (near !== lastNear) {
      lastNear = near;
      pegs.forEach((p) => p.s.sil.classList.toggle("hi", p.k === (near < 0 ? FAV : near)));
      const q = PEGS[near];
      read.textContent = near < 0 ? "rest" : "peg " + (q[0] + 1) + "·" + (q[1] + 1);
    }
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, T);
    if (x < -14 || x > E + 14 || y < -14 || y > E + 14) return setPoint(null);
    setPoint([x, y]);
  }
  setPoint(null);
  bag.add(pointer(stage, { move, leave: () => setPoint(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

