wallsafe.code:
/**
 * Floor safe: a hatch set into a floor slab, its heavy lid hinged on the far
 * edge with a dial on top. The nearer the pointer comes to the hatch, the
 * further the lid swings up on its hinge, showing the well beneath. At rest
 * the lid stands just ajar and the dial is bright. The slider is how far the
 * lid may open.
 *
 * The pattern: one part swinging on a hinge, following the pointer (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, rrect,
  disposer, mk, pointer, put, register, solid, spring, stepS, unproj,
} = HL;

const SZ = 8, LX0 = 26, LX1 = 84, LY0 = 22, LY1 = 74, TH = 3.5, REST = 14;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-2, -2, 0], [112, 98, 0], [112, -2, 0], [-2, 98, 0], [LX0, LY0, SZ + 58], [LX1, LY0, SZ + 58]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, 110, 96, 8, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  // the recessed frame and the opening
  mk("path", { d: poly(ringAt(P, rrect(LX0 - 4, LY0 - 4, LX1 + 4, LY1 + 4, 5, 4), SZ)), class: "nf lo" }, g);
  const hole = ringAt(P, rrect(LX0 + 2, LY0 + 2, LX1 - 2, LY1 - 2, 2, 4), SZ);
  mk("path", { d: poly(hole), class: "nf" }, g);
  // the well's far walls: their bottom edges, kept inside the opening
  const inside = (q) => {
    let s = 0;
    for (let i = 0; i < hole.length; i++) {
      const a = hole[i], b = hole[(i + 1) % hole.length];
      const c = (b[0] - a[0]) * (q[1] - a[1]) - (b[1] - a[1]) * (q[0] - a[0]);
      if (c !== 0) { if (s === 0) s = Math.sign(c); else if (Math.sign(c) !== s) return false; }
    }
    return true;
  };
  const D = SZ + 14, wx = LX0 + 2, wy = LY0 + 2;
  for (const [a, b] of [[[wx, wy], [LX1 - 2, wy]], [[wx, wy], [wx, LY1 - 2]]]) {
    const pts = [];
    for (let i = 0; i <= 40; i++) { const q = P(lerp(a[0], b[0], i / 40), lerp(a[1], b[1], i / 40), SZ - D); if (inside(q)) pts.push(q); }
    if (pts.length > 1) mk("path", { d: open(pts), class: "nf lo" }, g);
  }
  mk("path", { d: open([P(wx, wy, SZ), P(wx, wy, SZ - D)].filter(inside)), class: "nf lo" }, g);

  const lid = solid(g), top = mk("path", { class: "nf lo" }, g), dial = mk("path", { class: "nf" }, g), knob = mk("path", { class: "nf" }, g);
  const lring = rrect(LX0, LY0, LX1, LY1, 5, 4), linner = rrect(LX0 + 2, LY0 + 2, LX1 - 2, LY1 - 2, 3, 4);
  const cx = (LX0 + LX1) / 2, cy = (LY0 + LY1) / 2 + 4;
  const ang = spring(REST);
  let last = NaN;
  function W(u, v, h, a) {
    const d = v - LY0, ca = Math.cos(rad(a)), sa = Math.sin(rad(a));
    return P(u, LY0 + d * ca - h * sa, SZ + d * sa + h * ca);
  }
  const at = (ring, h, a) => ring.map((q) => W(q.u, q.v, h, a));
  function draw(a) {
    if (Math.abs(a - last) < 0.01) return;
    last = a;
    lid.sil.setAttribute("d", poly(hull(at(lring, 0, a).concat(at(lring, TH, a)))));
    const up = a < 62;
    top.setAttribute("d", up ? poly(at(linner, TH, a)) : "");
    dial.setAttribute("d", up ? poly(at(disc(cx, cy, 8), TH, a)) : "");
    knob.setAttribute("d", up ? poly(hull(at(disc(cx, cy, 3, 16), TH, a).concat(at(disc(cx, cy, 3, 16), TH + 3, a)))) : "");
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let on = null;
  function aim(p) {
    let t = REST, hot = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], SZ);
      const d = Math.hypot(x - cx, y - (LY0 + LY1) / 2);
      if (d < 95) { hot = true; t = lerp(maxA, REST + 6, clamp((d - 18) / 77, 0, 1)); }
    }
    ang.t = t;
    if (hot !== on) {
      on = hot;
      lid.sil.classList.toggle("hi", hot);
      dial.classList.toggle("hi", !hot);
    }
    read.textContent = hot ? Math.round(t) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "wallsafe",
  means: "A floor safe set in a slab: the nearer the pointer, the further the hinged lid swings open over the well.",
  rules: [3, 4, 5, 8],
  range: [60, 100, 112],
  tour: [[255, 170], [197, 192], [212, 264], null],
  mount,
});

bollardpost.code:
/**
 * Rising bollard: three steel posts set in sleeves across a road, a dashed
 * lane line running through them. As the pointer comes up the road toward
 * the barrier line, the posts rise out of their sleeves, the one in the
 * pointer's lane first and highest. At rest they stand at uneven heights,
 * the middle one bright. The slider is the full rise.
 *
 * The pattern: a barrier answering how near the pointer is (spring).
 */
const {
  Cam, circ, clamp, fit, facing, open, poly, prism, proj, rings, ringAt, run,
  disposer, mk, pointer, put, register, solid, spring, stepS, unproj,
} = HL;

const SZ = 6, BX = 70, YS = [14, 40, 66], R = 8, REST = [10, 24, 6], FAV = 1;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let H = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [140, 80, 0], [140, 0, 0], [0, 80, 0], [BX, YS[0], SZ + 52], [BX, YS[2], SZ + 52]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(0, 0, 140, 80, 8, 2);
  put(solid(g), prism(P, front, rr, ri, 0, SZ));
  for (let x = 8; x < 132; x += 16) mk("path", { d: open([P(x, 40, SZ), P(Math.min(x + 9, 132), 40, SZ)]), class: "nf lo" }, g);
  mk("path", { d: open([P(BX - 12, 4, SZ), P(BX - 12, 76, SZ)]), class: "dash" }, g);

  const posts = YS.map((y, k) => {
    const grp = mk("g", {}, g);
    mk("path", { d: poly(ringAt(P, disc(BX, y, R + 3), SZ)), class: "nf" }, grp);
    mk("path", { d: poly(ringAt(P, disc(BX, y, R + 1), SZ)), class: "nf lo" }, grp);
    const s = solid(grp), band = mk("path", { class: "nf lo" }, grp);
    return { y, k, s, band, h: spring(REST[k]), last: NaN };
  });
  function draw(p) {
    const h = Math.max(p.h.x, 0.5);
    if (Math.abs(h - p.last) < 0.01) return;
    p.last = h;
    put(p.s, prism(P, front, disc(BX, p.y, R), disc(BX, p.y, R - 1.6), SZ, SZ + h));
    p.band.setAttribute("d", h > 9 ? open(ringAt(P, run(disc(BX, p.y, R), front), SZ + h - 6)) : "");
  }
  posts.forEach(draw);

  const B = register(stage, (dt) => {
    let m = false;
    for (const p of posts) { if (stepS(p.h, dt)) m = true; draw(p); }
    return m;
  });
  bag.add(B.unregister);

  let lit = -2;
  function aim(pt) {
    let a = -1, f = 0;
    if (pt) {
      const [x, y] = unproj(C, pt[0], pt[1], SZ);
      if (x > -10 && x < 150 && y > -10 && y < 90) {
        f = 1 - clamp((Math.abs(x - BX) - 8) / 62, 0, 0.92);
        let bd = Infinity;
        YS.forEach((yy, k) => { const d = Math.abs(y - yy); if (d < bd) { bd = d; a = k; } });
      }
    }
    posts.forEach((p, k) => {
      p.h.t = a < 0 ? REST[k] : H * f * (k === a ? 1 : 0.62 + 0.1 * (2 - Math.abs(k - a))) + 4;
    });
    const hi = a < 0 ? FAV : a;
    if (hi !== lit) { lit = hi; posts.forEach((p, k) => p.s.sil.classList.toggle("hi", k === hi)); }
    read.textContent = a < 0 ? "rest" : "lane " + (a + 1) + " " + Math.round(f * 100) + "%";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { H = v; }, destroy: bag.dispose };
}

hairline({
  name: "bollardpost",
  means: "Three road bollards in their sleeves: as the pointer nears the barrier line they rise, the one in its lane highest.",
  rules: [1, 3, 4, 8],
  range: [24, 44, 48],
  tour: [[159, 114], [207, 179], [248, 241], null],
  mount,
});

containerdoor.code:
/**
 * Container doors: a shipping container with its two end doors. The pointer
 * picks a door by which half of the end it stands over: that door swings
 * wide on its hinge, and the other closes to a crack. At rest the right door
 * stands ajar, bright. The slider is the swing of the chosen door.
 *
 * The pattern: one of two, swinging on hinges.
 */
const {
  Cam, fit, facing, poly, fillet, prism, proj, rings, unproj, seg, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 96, W = 40, H = 40, DW = W / 2, REST = [6, 28];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[0, 0, 0], [L, W, 0], [L + DW, -4, H], [L + DW, W + 4, 0], [0, 0, H + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, L, W, 3, 1.6);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  // corrugation on the long side, the frame of the opening on the end
  let d = "";
  for (let x = 8; x < L - 4; x += 8) d += seg(P(x, W, 3), P(x, W, H - 3));
  mk("path", { d, class: "lo nf" }, g);
  mk("path", { d: poly(fillet([P(L, 3, 2), P(L, W - 3, 2), P(L, W - 3, H - 3), P(L, 3, H - 3)], [2, 2, 2, 2])), class: "lo nf" }, g);

  const doors = [0, 1].map((k) => {
    const grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), bars = mk("path", { class: "lo nf" }, grp);
    return { k, sil, bars, a: tween(REST[k]), last: NaN };
  });

  function draw(dr, ang) {
    if (ang === dr.last) return;
    dr.last = ang;
    const s = Math.sin(rad(ang)), c = Math.cos(rad(ang));
    const hy = dr.k === 0 ? 0 : W, dir = dr.k === 0 ? 1 : -1;
    const at = (t, z) => P(L + t * DW * s, hy + dir * t * DW * c, z);
    dr.sil.setAttribute("d", poly(fillet([at(0, 1), at(1, 1), at(1, H - 1), at(0, H - 1)], [1.5, 1.5, 1.5, 1.5])));
    dr.bars.setAttribute("d", seg(at(0.3, 3), at(0.3, H - 3)) + seg(at(0.75, 3), at(0.75, H - 3)) + seg(at(0.75, H * 0.45), at(0.95, H * 0.45)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const dr of doors) { draw(dr, tval(dr.a, now)); if (!tdone(dr.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < L - 50 || x > L + 40 || y < -30 || y > W + 30) return -1;
    return y < W / 2 ? 0 : 1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    doors.forEach((dr, k) => {
      tset(dr.a, a < 0 ? REST[k] : k === a ? open : 4, now, a < 0 ? 0 : Math.abs(k - a) * 40);
      dr.sil.classList.toggle("hi", k === (a < 0 ? 1 : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "door L" : "door R";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act >= 0) { tset(doors[act].a, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "containerdoor",
  means: "A shipping container's end doors: the door under the pointer swings wide on its hinge while the other closes to a crack.",
  rules: [1, 2, 5, 8],
  range: [40, 110, 160],
  tour: [[263, 248], [233, 263], [134, 196], null],
  mount,
});

gondola.code:
/**
 * Gondola: a long black-lacquer boat on a stretch of canal, its bow iron
 * standing up at the prow and the oar trailing from its forcola at the stern.
 * The pointer on the water steers it: the boat turns on the spot to point its
 * bow at the pointer, and the oar sweeps the other way, as a gondolier's
 * stroke would turn it. At rest it lies at an angle, its bow iron bright.
 *
 * The pattern: one thing turning to face the pointer (aim), picked on the
 * water plane, which never moves.
 */
const {
  Cam, clamp, fit, facing, hull, poly, open, proj, run, spring, stepS, unproj,
  disposer, mk, pointer, put, register, rings, prism, solid,
} = HL;

const L = 128, B = 24, WZ = 3, HZ = 12, REST = 18, MAXY = 48;
const CX0 = -96, CX1 = 96, CY0 = -56, CY1 = 56;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let sweep = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[CX0, CY0, 0], [CX1, CY1, 0], [CX1, CY0, 0], [CX0, CY1, 0], [0, 0, 44]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(CX0, CY0, CX1, CY1, 10, 2);
  put(solid(g), prism(P, front, wr, wi, 0, WZ));
  let rip = "";
  for (const [x, y, w] of [[-70, -30, 22], [-40, 34, 30], [30, -40, 26], [58, 30, 20], [-10, 44, 16], [70, -6, 14]])
    rip += "M" + P(x, y, WZ).join(",") + "L" + P(x + w, y, WZ).join(",");
  mk("path", { d: rip, class: "lo nf" }, g);

  const boat = mk("g", {}, g);
  const oarG = mk("g", {}, g);
  const shell = solid(boat);
  const seats = mk("path", { class: "lo nf" }, boat);
  const tail = mk("path", { class: "" }, boat);
  const ferro = mk("path", { class: "sil" }, boat);
  const comb = mk("path", { class: "lo nf" }, boat);
  const oar = mk("path", { class: "sil" }, oarG);

  // a lens-shaped deck ring in boat space: pointed at both ends
  const lens = (s, n = 36) => {
    const out = [];
    for (let i = 0; i < n; i++) {
      const t = (i / n) * Math.PI * 2, c = Math.cos(t), sn = Math.sin(t);
      const u = (L / 2) * s * c, v = (B / 2) * s * sn * Math.pow(Math.abs(sn), 0.15) * (1 - 0.25 * c * c);
      const nu = c / L, nv = sn / B, m = Math.hypot(nu, nv);
      out.push({ u, v, nu: nu / m, nv: nv / m });
    }
    return out;
  };
  const deck = lens(1), keel = lens(0.78), inner = lens(0.9);
  const yaw = spring(REST);
  const oarS = spring(-REST * 0.8);
  let lastY = NaN, lastO = NaN;

  function draw(a, o) {
    if (a === lastY && o === lastO) return;
    lastY = a; lastO = o;
    const r = (a * Math.PI) / 180, ca = Math.cos(r), sa = Math.sin(r);
    const W = (u, v) => [u * ca - v * sa, u * sa + v * ca];
    const at = (u, v, z) => { const [x, y] = W(u, v); return P(x, y, z); };
    const rot = (ring) => ring.map((q) => { const [x, y] = W(q.u, q.v); const [nx, ny] = W(q.nu, q.nv); return { u: x, v: y, nu: nx, nv: ny }; });
    const ringZ = (ring, z) => ring.map((q) => P(q.u, q.v, z));
    const rd = rot(deck), rk = rot(keel), ri = rot(inner);
    put(shell, { sil: poly(hull(ringZ(rk, WZ).concat(ringZ(rd, WZ + HZ)))), crease: open(ringZ(run(ri, front), WZ + HZ)) });
    let s = "";
    for (const u of [-22, 0, 22]) s += "M" + at(u, -B * 0.36, WZ + HZ).join(",") + "L" + at(u, B * 0.36, WZ + HZ).join(",");
    seats.setAttribute("d", s);
    // stern post: a short upturned plate
    const h = L / 2, Z = WZ + HZ;
    tail.setAttribute("d", poly([at(-h + 10, 0, Z), at(-h - 2, 0, Z + 9), at(-h - 4, 0, Z + 13), at(-h + 4, 0, Z + 4)]));
    // the bow iron: a tall blade with its comb
    ferro.setAttribute("d", poly([at(h - 12, 0, Z), at(h + 2, 0, Z + 6), at(h + 6, 0, Z + 26), at(h, 0, Z + 31), at(h - 4, 0, Z + 22), at(h - 6, 0, Z + 8)]));
    let cb = "";
    for (let i = 0; i < 4; i++) cb += "M" + at(h - 3 - i * 0.5, 0, Z + 10 + i * 4).join(",") + "L" + at(h - 9 - i * 0.5, 0, Z + 9 + i * 4).join(",");
    comb.setAttribute("d", cb);
    // the oar: from the forcola on the right of the stern into the water
    const ro = (o * Math.PI) / 180, lu = -h + 22, lv = B * 0.42;
    const bu = lu - 32 * Math.cos(ro), bv = lv + 32 * Math.sin(Math.abs(ro) * 0.5 + 0.5);
    const lock = at(lu, lv, Z + 10), blade = at(bu, bv, WZ + 1), mid = at((lu + bu) / 2, (lv + bv) / 2, Z + 4);
    const b2 = at(bu - 8 * Math.cos(ro), bv + 8 * Math.sin(Math.abs(ro) * 0.5 + 0.5), WZ);
    oar.setAttribute("d", "M" + lock.join(",") + "L" + mid.join(",") + "L" + blade.join(",") + poly([blade, at(bu - 2, bv + 3, WZ), b2, at(bu - 10 * Math.cos(ro) + 2, bv - 3, WZ)]) + poly([at(lu, lv, Z), at(lu, lv, Z + 10), at(lu + 2, lv, Z + 11), at(lu + 2, lv, Z)]));
    // paint order: the oar sits behind the boat when its blade is on the far side
    const [wx, wy] = W(bu, bv);
    if (wx + wy < 0) g.insertBefore(oarG, boat); else boat.after(oarG);
  }

  const R = register(stage, (dt) => {
    const m1 = stepS(yaw, dt), m2 = stepS(oarS, dt);
    draw(yaw.x, oarS.x);
    return m1 || m2;
  });
  bag.add(R.unregister);

  function aim(p) {
    if (!p) { yaw.t = REST; oarS.t = -REST * 0.8; ferro.classList.add("hi"); shell.sil.classList.remove("hi"); read.textContent = "rest"; R.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], WZ);
    if (x < CX0 || x > CX1 || y < CY0 || y > CY1 || Math.hypot(x, y) < 8) return aim(null);
    let a = (Math.atan2(y, x) * 180) / Math.PI;
    if (a > 90) a -= 180; else if (a < -90) a += 180; // the boat is the same either way round: point the nearer end
    a = clamp(a, -MAXY, MAXY);
    yaw.t = a; oarS.t = clamp(-a * (sweep / 45), -60, 60);
    ferro.classList.remove("hi"); shell.sil.classList.add("hi");
    read.textContent = (a >= 0 ? "+" : "") + Math.round(a) + "°";
    R.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sweep = v; }, destroy: bag.dispose };
}

hairline({
  name: "gondola",
  means: "A gondola on a canal: it turns on the spot to point its bow at the pointer, and its oar sweeps the other way.",
  rules: [1, 3, 5, 8],
  range: [0, 45, 90],
  tour: [[274, 150], [232, 207], [126, 144], null],
  mount,
});

tourbus.code:
/**
 * Tour bus: an open-top double-decker on a stretch of road, its upper deck a
 * railed tub of seat rows, its lower deck a band of windows over two wheel
 * arches. The pointer on the road calls it: the bus drives along to stand
 * level with the pointer, then settles. At rest it waits off-centre, its top
 * rail bright.
 *
 * The pattern: one thing sliding along a track, picked on the road plane.
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BL = 96, BW = 28, Z0 = 8, Z1 = 36, Z2 = 46, RX0 = -110, RX1 = 110, RY0 = -26, RY1 = 40, REST = -34;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.45);
  fit(C, [[RX0, RY0, 0], [RX1, RY1, 0], [RX1, RY0, 0], [RX0, RY1, 0], [RX1 - 50, 0, Z2 + 4], [RX0 + 50, 0, Z2 + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(RX0, RY0, RX1, RY1, 8, 2);
  put(solid(g), prism(P, front, rr, ri, 0, 3));
  mk("path", { d: "M" + P(RX0 + 8, 34, 3).join(",") + "L" + P(RX1 - 8, 34, 3).join(","), class: "dash nf" }, g);
  const busG = mk("g", {}, g);
  const lower = solid(busG), upper = solid(busG);
  const detail = mk("path", { class: "lo nf" }, busG);
  const pos = spring(REST);
  let last = NaN;

  function draw(cx) {
    if (cx === last) return;
    last = cx;
    const x0 = cx - BL / 2, x1 = cx + BL / 2, y0 = -BW / 2, y1 = BW / 2;
    const [lr, li] = rings(x0, y0, x1, y1, 7, 1.6);
    put(lower, prism(P, front, lr, li, Z0, Z1));
    const [ur, ui] = rings(x0 + 2, y0 + 1, x1 - 1, y1 - 1, 6, 2.2);
    put(upper, prism(P, front, ur, ui, Z1, Z2));
    let d = "";
    const L = (a, b) => { d += "M" + a.join(",") + "L" + b.join(","); };
    // seat rows inside the open top
    for (let x = x0 + 14; x < x1 - 8; x += 12) L(P(x, y0 + 4, Z2), P(x, y1 - 4, Z2));
    // window band and door on the near side
    L(P(x0 + 6, y1, Z1 - 6), P(x1 - 4, y1, Z1 - 6));
    L(P(x0 + 6, y1, Z1 - 16), P(x1 - 4, y1, Z1 - 16));
    for (let x = x0 + 18; x < x1 - 6; x += 14) L(P(x, y1, Z1 - 6), P(x, y1, Z1 - 16));
    L(P(x1 - 2, y1 - 6, Z1 - 6), P(x1 - 2, y1 - 6, Z0 + 2));
    // wheel arches on the near side
    for (const wx of [x0 + 20, x1 - 20]) {
      const arc = [];
      for (let i = 0; i <= 10; i++) { const t = (i / 10) * Math.PI; arc.push(P(wx - 8 * Math.cos(t), y1, Z0 - 6 + 9 * Math.sin(t))); }
      d += open(arc);
      const tyre = [];
      for (let i = 0; i <= 10; i++) { const t = (i / 10) * Math.PI; tyre.push(P(wx - 6 * Math.cos(t), y1 + 0.5, Z0 - 8 + 8 * Math.sin(t))); }
      d += open(tyre);
    }
    detail.setAttribute("d", d);
  }

  const R = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(R.unregister);

  const lim = RX1 - BL / 2 - 6;
  function call(p) {
    let on = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      on = x > RX0 && x < RX1 && y > RY0 - 30 && y < RY1 + 30;
      if (on) pos.t = clamp(x * (0.4 + reach / 150), -lim, lim);
    }
    if (!on) pos.t = REST;
    upper.sil.classList.toggle("hi", !on);
    lower.sil.classList.toggle("hi", on);
    read.textContent = on ? (pos.t >= 0 ? "+" : "") + Math.round(pos.t) + " m" : "rest";
    R.wake();
  }
  call(null);
  bag.add(pointer(stage, { move: call, leave: () => call(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

