dartboard2.code:
/**
 * Air hockey table: a long rimmed table on a plinth, a centre line and circle,
 * a goal slot at each end, a puck and a striker. The pointer is where the puck
 * slides to across the table, on a spring, and the striker follows it from
 * the near end, a little behind. At rest the puck waits off the centre spot,
 * bright, the striker parked by its goal. The slider is how loose the slide
 * is (a softer or stiffer spring).
 *
 * The pattern: a continuous position on two springs per part; the hit is the
 * table's top plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, poly, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X = 74, Y = 42, ZT = 12, PR = 8.5, MR = 10;
const REST = { px: -16, py: 9, mx: 50, my: -12 };
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-X, -Y, 0], [X, Y, 0], [X, -Y, ZT + 14], [-X, Y, ZT + 14], [-X, -Y, ZT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-X + 10, -Y + 10, X - 10, Y - 10, 8, 1.4), 0, 5));
  put(solid(g), prism(P, front, ...rings(-X, -Y, X, Y, 12, 2.2), 5, ZT));
  const at = (x, y) => P(x, y, ZT);
  const ring = (cx, r, a0, a1) => { const p = []; for (let k = 0; k <= 32; k++) { const a = a0 + (k / 32) * (a1 - a0); p.push(at(cx + r * Math.cos(a), r * Math.sin(a))); } return p; };
  mk("path", { class: "nf lo", d: seg(at(0, -Y + 3), at(0, Y - 3)) + poly(ring(0, 14, 0, Math.PI * 2)) }, g);
  mk("path", { class: "nf lo", d: poly(ring(-X + 2, 18, -Math.PI / 2, Math.PI / 2)).replace(/Z$/, "") + poly(ring(X - 2, 18, Math.PI / 2, Math.PI * 1.5)).replace(/Z$/, "") }, g);
  for (const s of [-1, 1]) mk("path", { class: "nf sil", d: poly([at(s * (X - 1), -11), at(s * (X - 1), 11), at(s * (X - 4), 11), at(s * (X - 4), -11)]) }, g);

  const puck = { x: spring(REST.px), y: spring(REST.py), g: mk("g", {}, g) };
  puck.s = solid(puck.g);
  const mal = { x: spring(REST.mx), y: spring(REST.my), g: mk("g", {}, g) };
  mal.base = solid(mal.g); mal.stem = solid(mal.g); mal.cap = solid(mal.g);
  puck.s.sil.classList.add("hi");
  let dp = "", dm = "", order = null;

  function draw() {
    const px = puck.x.x, py = puck.y.x, mx = mal.x.x, my = mal.y.x;
    const kp = px.toFixed(2) + py.toFixed(2), km = mx.toFixed(2) + my.toFixed(2);
    if (kp !== dp) { dp = kp; put(puck.s, prism(P, front, disc(px, py, PR, 40), disc(px, py, PR - 1.2, 40), ZT, ZT + 3)); }
    if (km !== dm) {
      dm = km;
      put(mal.base, prism(P, front, disc(mx, my, MR, 40), disc(mx, my, MR - 1.4, 40), ZT, ZT + 4));
      put(mal.stem, prism(P, front, disc(mx, my, 3.6, 24), null, ZT + 4, ZT + 10));
      put(mal.cap, prism(P, front, disc(mx, my, 5.4, 28), disc(mx, my, 4.4, 28), ZT + 10, ZT + 14));
    }
    const pf = px + py < mx + my;
    if (pf !== order) { order = pf; if (pf) puck.g.after(mal.g); else mal.g.after(puck.g); }
  }

  const sps = [puck.x, puck.y, mal.x, mal.y];
  const B = register(stage, (dt) => { let m = false; for (const s of sps) if (stepS(s, dt)) m = true; draw(); return m; });
  bag.add(B.unregister);
  const soft = (v) => { for (const s of sps) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } };
  soft(value);

  function go(on, x, y) {
    if (!on) { puck.x.t = REST.px; puck.y.t = REST.py; mal.x.t = REST.mx; mal.y.t = REST.my; read.textContent = "rest"; }
    else {
      const px = clamp(x, -X + 14, X - 38), py = clamp(y, -Y + 12, Y - 12);
      puck.x.t = px; puck.y.t = py;
      mal.x.t = px + 24; mal.y.t = clamp(py - 6, -Y + 13, Y - 13);
      read.textContent = (py < 0 ? "far " : "near ") + Math.round((px + X) / (2 * X) * 9 + 0.5);
    }
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZT);
      go(Math.abs(x) < X + 18 && Math.abs(y) < Y + 18, x, y);
    },
    leave: () => go(false),
  }));
  bag.add(() => svg.replaceChildren());
  go(false); draw();
  return { set: (v) => soft(v), destroy: bag.dispose };
}

hairline({
  name: "dartboard2",
  means: "An air hockey table: the puck slides across the table to the pointer, and the striker follows it from the near end.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[166, 104], [76, 135], [200, 197], null],
  mount,
});

pokerchips.code:
/**
 * Chip tray: a low rimmed tray holding five stacks of chips, each a different
 * height, every chip a seam round the stack's front. The pointer chooses a
 * stack and it slides out of the tray toward the player, the stacks beside it
 * edging out less, the motion spreading out from the one chosen. At rest the
 * stacks sit a little out of line, the second bright. The slider is how far
 * the chosen stack slides.
 *
 * The pattern: a single row picked by its rest centre's screen x; the slide is
 * a discrete choice on 700ms tweens, staggered by distance.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, run, ringAt, open, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, DX = 21, R = 8.6, T = 2.3, Z0 = 4, OUT = 24, FAV = 1;
const H = [6, 9, 4, 8, 6], JIT = [1.5, -1, 2.5, 0, -2];
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.0);
  const W = (N * DX) / 2 + 3;
  fit(C, [[-W, -16, 0], [W, 16 + OUT, 0], [-W, -16, Z0 + 9 * T + 2], [W, 16, Z0 + 9 * T]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-W, -15, W, 15, 7, 1.6), 0, Z0 + 3));
  for (let i = 0; i < N; i++) mk("path", { class: "nf lo", d: open(ringAt(P, run(disc(-W + 3 + (i + 0.5) * DX, 0, R + 1.2), front), Z0)) }, g);
  const stacks = [];
  for (let i = 0; i < N; i++) {
    const x = -W + 3 + (i + 0.5) * DX;
    const s = { i, x, h: H[i] * T, tw: tween(JIT[i]), drawn: NaN, g: mk("g", {}, g), cx: P(x, 0, Z0)[0] };
    s.body = solid(s.g);
    s.seams = mk("path", { class: "nf lo", d: "" }, s.g);
    stacks.push(s);
  }
  function draw(s, now) {
    const y = tval(s.tw, now);
    if (Math.abs(y - s.drawn) < 1e-3) return;
    s.drawn = y;
    const d = disc(s.x, y, R), fr = run(d, front);
    put(s.body, prism(P, front, d, disc(s.x, y, R - 1.3), Z0, Z0 + s.h));
    let p = "";
    for (let k = 1; k < H[s.i]; k++) p += open(ringAt(P, fr, Z0 + k * T));
    s.seams.setAttribute("d", p);
  }
  const B = register(stage, (dt, now) => { let m = false; for (const s of stacks) { draw(s, now); if (!tdone(s.tw, now)) m = true; } return m; });
  bag.add(B.unregister);

  let cur = -2;
  function choose(a) {
    if (a === cur) return;
    cur = a;
    const now = performance.now();
    for (const s of stacks) {
      const d = Math.abs(s.i - a), f = a < 0 ? 0 : d === 0 ? 1 : d === 1 ? 0.38 : 0.12;
      tset(s.tw, a < 0 ? JIT[s.i] : f * OUT * value + JIT[s.i] * (1 - f), now, a < 0 ? 0 : d * 40);
      s.body.sil.classList.toggle("hi", a < 0 ? s.i === FAV : s.i === a);
    }
    read.textContent = a < 0 ? "rest" : "stack " + (a + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const top = P(0, -24, Z0 + 10 * T)[1], bot = P(0, 24 + OUT, 0)[1];
      const xs = stacks.map((s) => s.cx), slope = (p[1] - P(0, 0, Z0)[1]);
      if (p[1] < top + slope * 0 - 30 || p[1] > bot + 40 || p[0] < xs[0] - 40 || p[0] > xs[N - 1] + 40) return choose(-1);
      let a = 0, bd = Infinity;
      stacks.forEach((s, i) => { const d = Math.abs(p[0] - s.cx); if (d < bd) { bd = d; a = i; } });
      choose(a);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  choose(-1);
  return { set: (v) => { value = v; const a = cur; cur = -2; choose(a); }, destroy: bag.dispose };
}

hairline({
  name: "pokerchips",
  means: "A chip tray of five stacks: the stack the pointer chooses slides out toward the player, its neighbours edging out less.",
  rules: [1, 2, 5, 8],
  range: [0.4, 1, 1],
  tour: [[94, 125], [158, 156], [295, 225], null],
  mount,
});

roulette.code:
/**
 * Spinner wheel: a flat game wheel on a round plinth, twelve wedges, a peg at
 * each wedge's edge and a fixed pawl at the front rim. The pointer is where the
 * wheel turns to: its angle round the hub becomes the wheel's turn, on a
 * spring, and the wedge that lands under the pawl is bright. At rest the wheel
 * is left a little past a wedge, that wedge lit. The slider is how far the
 * wheel follows (a fraction of the pointer's angle).
 *
 * The pattern: a continuous aim on one spring; the hit is the plinth's top
 * plane, which never moves, and the chosen wedge reads the spring's target.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, poly,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const N = 12, R = 60, ZT = 12, REST = 0.22;
const W = (Math.PI * 2) / N, FRONT = Math.PI / 4;
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  const ext = [];
  for (let k = 0; k < 16; k++) { const a = (k / 16) * Math.PI * 2; ext.push([(R + 6) * Math.cos(a), (R + 6) * Math.sin(a), 0], [R * Math.cos(a), R * Math.sin(a), ZT + 7]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(R + 6, 72), circ(R + 4.6, 72), 0, 6));
  put(solid(g), prism(P, front, circ(R, 72), circ(R - 2, 72), 6, ZT));
  const lines = mk("path", { class: "nf lo", d: "" }, g);
  const inner = mk("path", { class: "nf lo", d: "" }, g);
  const wedge = mk("path", { class: "nf hi", d: "" }, g);
  const pegs = [];
  for (let i = 0; i < N; i++) pegs.push(flatDot(g, C, 1.3, "dot off"));
  put(solid(g), prism(P, front, circ(7, 32), circ(5.8, 32), ZT, ZT + 5));
  const pc = (R - 1) / Math.SQRT2;
  put(solid(g), prism(P, front, ...rings(pc - 4, pc - 4, pc + 4, pc + 4, 1.6, 0.8), ZT, ZT + 7));

  const sp = spring(REST);
  let drawn = NaN;
  const at = (r, a) => P(r * Math.cos(a), r * Math.sin(a), ZT);
  function draw() {
    const a0 = sp.x;
    if (Math.abs(a0 - drawn) < 1e-4) return;
    drawn = a0;
    let d = "", d2 = [];
    for (let i = 0; i < N; i++) {
      const a = a0 + i * W;
      d += seg(at(9, a), at(R - 2, a));
      place(pegs[i], at(R - 4.5, a));
    }
    for (let k = 0; k <= 48; k++) d2.push(at(R * 0.62, (k / 48) * Math.PI * 2));
    lines.setAttribute("d", d);
    inner.setAttribute("d", poly(d2));
    // the wedge whose span holds the front, by the spring's target
    const i = pick(sp.t), s = sp.x + i * W, arc = [];
    for (let k = 0; k <= 8; k++) arc.push(at(R - 2, s + (k / 8) * W));
    for (let k = 8; k >= 0; k--) arc.push(at(R * 0.62, s + (k / 8) * W));
    wedge.setAttribute("d", poly(arc));
  }
  const pick = (t) => ((Math.floor(wrap(FRONT - t) / W) % N) + N) % N;

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(t, on) {
    sp.t = sp.t + wrap(t - sp.t);
    drawn = NaN;
    read.textContent = on ? "wedge " + (pick(sp.t) + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZT), r = Math.hypot(x, y);
      if (r > R + 30 || r < 6) return r > R + 30 ? aim(REST, false) : undefined;
      aim(value * wrap(Math.atan2(y, x) - FRONT) + REST, true);
    },
    leave: () => aim(REST, false),
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "roulette",
  means: "A spinner wheel: it turns with the pointer's angle round the hub, and the wedge under the front pawl is bright.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[151, 101], [102, 206], [298, 206], null],
  mount,
});

jigsaw.code:
/**
 * Jigsaw puzzle: twelve interlocking pieces on a board, each a thin plate with
 * knobs and sockets on its inner edges. The pointer loosens the puzzle: the
 * pieces near it turn out of the grid and rise a little, the turn falling
 * off with distance, and the piece nearest it is bright. At rest the puzzle
 * is assembled but for one piece left turned and lifted, bright. The slider
 * is how far the pieces turn.
 *
 * The pattern: a continuous falloff on a spring per piece (angle and lift);
 * the hit is the board's top plane, which never moves.
 */
const {
  Cam, fit, prism, proj, rings, facing, unproj, spring, stepS, poly, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NX = 4, NY = 3, S = 24, H = S / 2, Z0 = 5, TH = 2.4, FAV = 6, TURN = 0.62;
const sgn = (a, b) => (((a * 7 + b * 13) % 3) === 0 ? -1 : 1);

function outline(i, j) {
  const e = [j > 0 ? -sgn(i, j) : 0, i < NX - 1 ? sgn(i + 1, j + 9) : 0, j < NY - 1 ? sgn(i, j + 1) : 0, i > 0 ? -sgn(i, j + 9) : 0];
  const C4 = [[-H, -H], [H, -H], [H, H], [-H, H]], N4 = [[0, -1], [1, 0], [0, 1], [-1, 0]], pts = [];
  for (let k = 0; k < 4; k++) {
    const a = C4[k], b = C4[(k + 1) % 4], n = N4[k];
    for (let s = 0; s < 16; s++) {
      const t = s / 16, w = t > 0.3 && t < 0.7 ? Math.sqrt(Math.sin(Math.PI * (t - 0.3) / 0.4)) * 5.5 * e[k] : 0;
      const bulge = t > 0.3 && t < 0.7 ? Math.sin(Math.PI * (t - 0.3) / 0.4) * 0.12 * e[k] : 0;
      const tt = t + (t - 0.5) * -bulge;
      pts.push([a[0] + (b[0] - a[0]) * tt + n[0] * w, a[1] + (b[1] - a[1]) * tt + n[1] * w]);
    }
  }
  return pts;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  const BX = (NX * S) / 2 + 6, BY = (NY * S) / 2 + 6;
  fit(C, [[-BX, -BY, 0], [BX, BY, 0], [-BX, -BY, Z0 + 10], [BX, BY, Z0 + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-BX, -BY, BX, BY, 7, 1.8), 0, Z0));
  const pieces = [];
  for (let j = 0; j < NY; j++) for (let i = 0; i < NX; i++) {
    const k = j * NX + i, cx = -BX + 6 + (i + 0.5) * S, cy = -BY + 6 + (j + 0.5) * S;
    const ra = k === FAV ? 0.38 : ((k * 37) % 7 - 3) * 0.012, rz = k === FAV ? 4 : 0;
    pieces.push({ k, i, j, cx, cy, ra, rz, out: outline(i, j), a: spring(ra), z: spring(rz), drawn: "" });
  }
  pieces.sort((p, q) => p.cx + p.cy - (q.cx + q.cy));
  for (const p of pieces) { p.g = mk("g", {}, g); p.lo = mk("path", { class: "sil", d: "" }, p.g); p.hi = mk("path", { class: "sil", d: "" }, p.g); }

  function draw(p) {
    const a = p.a.x, z = p.z.x, key = a.toFixed(4) + z.toFixed(3);
    if (key === p.drawn) return;
    p.drawn = key;
    const c = Math.cos(a), s = Math.sin(a), at = (h) => p.out.map(([u, v]) => P(p.cx + u * c - v * s, p.cy + u * s + v * c, h));
    p.lo.setAttribute("d", poly(at(Z0 + z)));
    p.hi.setAttribute("d", poly(at(Z0 + z + TH)));
  }
  const B = register(stage, (dt) => { let m = false; for (const p of pieces) { if (stepS(p.a, dt)) m = true; if (stepS(p.z, dt)) m = true; draw(p); } return m; });
  bag.add(B.unregister);

  function go(w) {
    let near = null, bd = Infinity;
    for (const p of pieces) {
      if (!w) { p.a.t = p.ra; p.z.t = p.rz; continue; }
      const d = Math.hypot(w[0] - p.cx, w[1] - p.cy), f = d < S * 0.5 ? 1 : clamp(Math.exp(-((d - S * 0.5) ** 2) / (2 * 22 * 22)), 0.08, 1);
      if (d < bd) { bd = d; near = p; }
      p.a.t = p.ra * 0.3 + f * TURN * value * ((p.i + p.j) % 2 ? 1 : -1);
      p.z.t = f * 6;
    }
    for (const p of pieces) p.hi.classList.toggle("hi", w ? p === near : p.k === FAV);
    read.textContent = near ? "piece " + (near.i + 1) + "·" + (near.j + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (q) => {
      const [x, y] = unproj(C, q[0], q[1], Z0);
      go(Math.abs(x) < BX + 14 && Math.abs(y) < BY + 14 ? [clamp(x, -BX, BX), clamp(y, -BY, BY)] : null);
    },
    leave: () => go(null),
  }));
  bag.add(() => svg.replaceChildren());
  go(null);
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "jigsaw",
  means: "A jigsaw puzzle on its board: pieces near the pointer turn out of the grid and rise, and the nearest piece is bright.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.4],
  tour: [[178, 110], [178, 161], [222, 233], null],
  mount,
});

sentrybox.code:
/**
 * Sentry box: a guard hut with a flat overhanging roof, a slot window on its
 * side and a tall door on the front. The door swings on its hinge to follow
 * the pointer round the doorstep, from shut to wide open. At rest it stands
 * ajar, its window bright. The slider is how far the door may open.
 *
 * The pattern: a part swinging to face the pointer.
 */
const {
  Cam, clamp, fit, facing, poly, prism, proj, rad, rings, rrect, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 36, D = 36, H = 82, HX = 7, DW = 22, DZ = 64, REST = rad(28);
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxOpen = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-6, -6, 0], [W + 6, -6, 0], [-6, D + 30, 0], [HX + 2, D + DW + 2, 0], [W + 6, D + 6, 0], [-6, -6, H + 10], [W + 6, D + 6, H + 10]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-4, -4, W + 4, D + 8, 3, 1.4), 0, 3));
  put(solid(g), prism(P, front, ...rings(0, 0, W, D, 3, 1.4), 3, H));
  const face = (pts) => poly(pts.map(([x, y, z]) => P(x, y, z)));
  mk("path", { d: face([[HX, D, 4], [HX + DW, D, 4], [HX + DW, D, DZ], [HX, D, DZ]]), class: "nf lo" }, g);
  mk("path", { d: face([[W, 8, 50], [W, 28, 50], [W, 28, 62], [W, 8, 62]]), class: "nf lo" }, g);
  put(solid(g), prism(P, front, ...rings(-5, -5, W + 5, D + 5, 3, 1.6), H, H + 5));
  put(solid(g), prism(P, front, ...rings(4, 4, W - 4, D - 4, 3, 1.4), H + 5, H + 9));
  const door = solid(g), win = mk("path", { class: "nf hi" }, g), knob = mk("path", { class: "nf lo" }, g);
  const [dR, dI] = [rrect(0, -1.2, DW, 1.2, 1, 4), rrect(0.6, -0.6, DW - 0.6, 0.6, 0.5, 4)];
  const a = spring(REST);
  let last = NaN;

  function onDoor(ang, u, z) { return P(HX + u * Math.cos(ang) - 1.4 * Math.sin(ang), D + u * Math.sin(ang) + 1.4 * Math.cos(ang), z); }
  function draw() {
    if (a.x === last) return;
    last = a.x;
    const ang = a.x;
    put(door, prism(P, front, turn(dR, ang, HX, D + 1.2), turn(dI, ang, HX, D + 1.2), 4, DZ));
    win.setAttribute("d", poly([onDoor(ang, 5, 44), onDoor(ang, 17, 44), onDoor(ang, 17, 58), onDoor(ang, 5, 58)]));
    const k = onDoor(ang, 18.5, 32);
    knob.setAttribute("d", poly([[k[0] - 1.2, k[1] - 1.2], [k[0] + 1.2, k[1] - 1.2], [k[0] + 1.2, k[1] + 1.2], [k[0] - 1.2, k[1] + 1.2]]));
  }

  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [gx, gy] = unproj(C, sx, sy, 30);
    const t = Math.atan2(gy - D, gx - HX);
    a.t = clamp(t < -Math.PI / 2 ? Math.PI : t, 0, rad(maxOpen));
    read.textContent = "open " + Math.round((a.t * 180) / Math.PI) + "°";
    B.wake();
  }
  function leave() { a.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  draw();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxOpen = v; }, destroy: bag.dispose };
}

hairline({
  name: "sentrybox",
  means: "A guard hut with a flat roof and a tall front door: the door swings on its hinge to follow the pointer round the step.",
  rules: [1, 3, 5, 8],
  range: [60, 100, 120],
  tour: [[108, 227], [214, 236], [102, 190], null],
  mount,
});

pottery.code:
/**
 * Potter wheel: a round pedestal, a wheel head on it and a lump of clay on the
 * head. The pointer is the potter's hands: raise it over the wheel and the clay
 * is pulled up from a squat bowl into a tall vase with a neck, while the wheel
 * head turns its three marks. At rest the clay is a low, wide bowl and the wheel
 * head's edge is bright. The slider is how quickly the clay follows.
 *
 * The pattern: a continuous pull (one spring) read from the pointer's screen
 * height inside a fixed band, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, spring, stepS,
  disposer, mk, place, pointer, put, register, solid, poly, open, lerp, clamp,
} = HL;

const ZH = 19, LV = 7;
const REST = [21, 24, 25, 24.5, 23, 22, 22.5], PULL = [15, 19, 20, 17, 11, 9.5, 11];
const HR = 13, HP = 56;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.95);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([36 * Math.cos(a), 36 * Math.sin(a), 0], [20 * Math.cos(a), 20 * Math.sin(a), ZH + HP]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(30, 64), circ(28.4, 64), 0, 4));
  put(solid(g), prism(P, front, circ(12, 48), null, 4, ZH - 4));
  const pan = solid(g);
  put(pan, prism(P, front, circ(36, 72), circ(34.2, 72), ZH - 4, ZH - 1.5));
  const head = solid(g);
  put(head, prism(P, front, circ(27, 64), circ(25.6, 64), ZH - 1.5, ZH));
  const marks = [0, 1, 2].map(() => mk("circle", { class: "dot off", r: 1.6 }, g));
  const clay = solid(g);
  const sp = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  const ell = (r, z) => { const o = []; for (let i = 0; i < 48; i++) { const a = (i / 48) * Math.PI * 2; o.push(P(r * Math.cos(a), r * Math.sin(a), z)); } return o; };
  const ext2 = (pts) => { let l = 0, rr = 0; pts.forEach((p, i) => { if (p[0] < pts[l][0]) l = i; if (p[0] > pts[rr][0]) rr = i; }); return [l, rr]; };
  const arc = (pts, a, b, dir) => { const o = []; for (let i = a; ; i = (i + dir + 48) % 48) { o.push(pts[i]); if (i === b) break; } return o; };

  function draw() {
    const p = clamp(sp.x, 0, 1);
    if (Math.abs(p - drawn) < 1e-4) return;
    drawn = p;
    const H = lerp(HR, HP, p), L = [], R = [];
    let bot = null, top = null, bi = null, ti = null;
    for (let j = 0; j < LV; j++) {
      const pts = ell(lerp(REST[j], PULL[j], p), ZH + (H * j) / (LV - 1)), [l, r] = ext2(pts);
      L.push(pts[l]); R.push(pts[r]);
      if (j === 0) { bot = pts; bi = [l, r]; }
      if (j === LV - 1) { top = pts; ti = [l, r]; }
    }
    const nearSide = (pts, a, b) => { const m = arc(pts, a, b, 1); return m[m.length >> 1][1] > pts[a][1] ? 1 : -1; };
    const db = nearSide(bot, bi[1], bi[0]), dt = nearSide(top, ti[0], ti[1]);
    const sil = [...L.slice(0, -1), ...arc(top, ti[0], ti[1], -dt), ...R.slice(1).reverse().slice(0, -1), ...arc(bot, bi[1], bi[0], db)];
    clay.sil.setAttribute("d", poly(sil));
    clay.cr.setAttribute("d", open(arc(top, ti[0], ti[1], dt)));
    const turnA = p * Math.PI * 1.6;
    marks.forEach((m, i) => { const a = turnA + 0.4 + (i * Math.PI * 2) / 3; place(m, P(31.5 * Math.cos(a), 31.5 * Math.sin(a), ZH - 1.5)); });
  }

  const B = register(stage, (dts) => { const m = stepS(sp, dts); draw(); return m; });
  bag.add(B.unregister);
  const base = P(0, 0, ZH)[1];

  function set(on, t) {
    sp.t = t;
    clay.sil.classList.toggle("hi", on);
    head.sil.classList.toggle("hi", !on);
    read.textContent = on ? "h " + Math.round(lerp(HR, HP, t)) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (q) => {
      const dx = Math.abs(q[0] - 200);
      if (dx > 110 || q[1] > base + 40) return set(false, 0);
      set(true, clamp((base + 20 - q[1]) / 170, 0.15, 1));
    },
    leave: () => set(false, 0),
  }));
  bag.add(() => svg.replaceChildren());
  set(false, 0);
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "pottery",
  means: "A potter wheel: raise the pointer over it and the clay is pulled up from a squat bowl into a tall necked vase.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[200, 165], [200, 80], [200, 125], null],
  mount,
});

penholder.code:
/**
 * Brush jar: a round jar with a lip, seven paint brushes standing in it, each a
 * handle and a pointed tuft of bristles. The pointer is where the light comes
 * from: every brush tips over in the jar to lean toward it, on its own spring,
 * and the brush whose tip is nearest is bright. At rest the brushes fan out
 * unevenly and the jar's lip is bright. The slider is how far they lean.
 *
 * The pattern: a continuous aim (a spring pair per brush); the hit is on the
 * floor's plane, which never moves, and the nearest tip is read from rest.
 */
const {
  Cam, circ, facing, fit, prism, proj, hull, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid, poly, seg, clamp,
} = HL;

const JR = 17, JH = 30, N = 7;
const LEN = [58, 50, 62, 54, 47, 60, 52], FAN = [0.32, 0.22, 0.38, 0.18, 0.3, 0.26, 0.34], FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([JR * Math.cos(a), JR * Math.sin(a), 0], [44 * Math.cos(a), 44 * Math.sin(a), JH + 44]); }
  ext.push([0, 0, JH + 62]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const jar = solid(g);
  put(jar, prism(P, front, circ(JR, 48), circ(JR - 1.6, 48), 0, JH));
  const lip = solid(g);
  put(lip, prism(P, front, circ(JR + 1.6, 48), circ(JR - 1.2, 48), JH - 3, JH));

  const brushes = [];
  for (let i = 0; i < N; i++) {
    const a = 0.5 + (i / N) * Math.PI * 2, rr = i % 2 ? 9 : 5;
    const b = { i, x: Math.cos(a) * rr, y: Math.sin(a) * rr, L: LEN[i], rx: Math.cos(a) * FAN[i], ry: Math.sin(a) * FAN[i] };
    b.sx = spring(b.rx, { k: 100, c: 18 }); b.sy = spring(b.ry, { k: 100, c: 18 });
    b.restTip = P(b.x + b.rx * b.L, b.y + b.ry * b.L, JH + b.L * Math.sqrt(1 - b.rx * b.rx - b.ry * b.ry));
    brushes.push(b);
  }
  brushes.sort((p, q) => p.x + p.y - (q.x + q.y));
  for (const b of brushes) {
    b.g = mk("g", {}, g);
    b.handle = mk("path", { class: "nf sil" }, b.g);
    b.tuft = solid(b.g);
    b.drawn = "";
  }
  let gain = value;

  function draw(b) {
    const lx = b.sx.x, ly = b.sy.x, key = lx.toFixed(4) + ly.toFixed(4);
    if (key === b.drawn) return;
    b.drawn = key;
    const lz = Math.sqrt(Math.max(0.1, 1 - lx * lx - ly * ly));
    const at = (t) => [b.x + lx * b.L * t, b.y + ly * b.L * t, JH - 6 + lz * b.L * t];
    const f = at(0.7), tip = at(1), m = at(0.86), ring = circ(2.2, 12).map((q) => P(f[0] + q.u, f[1] + q.v, f[2])).concat(circ(3.4, 12).map((q) => P(m[0] + q.u, m[1] + q.v, m[2])));
    const a = at(7 / (lz * b.L));
    b.handle.setAttribute("d", seg(P(...a), P(...f)));
    b.tuft.sil.setAttribute("d", poly(hull(ring.concat([P(...tip)]))));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const b of brushes) { if (stepS(b.sx, dt)) m = true; if (stepS(b.sy, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function aim(w, scr) {
    let near = null, bd = Infinity;
    for (const b of brushes) {
      if (w) {
        const dx = w[0] - b.x, dy = w[1] - b.y, d = Math.hypot(dx, dy) || 1, m = clamp(d / 50, 0.25, 1) * 0.55 * gain;
        b.sx.t = (dx / d) * m; b.sy.t = (dy / d) * m;
        const sd = Math.hypot(scr[0] - b.restTip[0], scr[1] - b.restTip[1]);
        if (sd < bd) { bd = sd; near = b; }
      } else { b.sx.t = b.rx; b.sy.t = b.ry; }
    }
    for (const b of brushes) b.tuft.sil.classList.toggle("hi", w ? b === near : false);
    lip.sil.classList.toggle("hi", !w);
    read.textContent = near ? "brush " + (near.i + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const w = unproj(C, p[0], p[1], 0);
      if (Math.abs(p[0] - 200) > 150) return aim(null);
      aim(w, p);
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  for (const b of brushes) draw(b);
  return {
    set: (v) => { gain = clamp(v, 0.5, 1.2); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "penholder",
  means: "A jar of paint brushes: every brush tips in the jar to lean toward the pointer, and the brush whose tip is nearest is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[123, 84], [272, 150], [205, 250], null],
  mount,
});

wardrobe2.code:
/**
 * Sliding wardrobe: a tall carcass with two doors on two tracks. The pointer
 * picks a bay by where it stands, and the door covering that bay slides
 * across to open it, showing shelves or a hanging rail. At rest the front
 * door stands part-open, bright. The slider is the slide's reach.
 *
 * The pattern: one of two in a row, a sliding answer.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, D = 40, H = 112, HW = W / 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-2, -2, 0], [W + 2, D + 8, 0], [W + 2, -2, H + 2], [-2, D + 8, H + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, D, 3, 1.6);
  put(solid(g), prism(P, front, cr, ci, 0, H));

  // the inside, on the front plane: shelves in the left bay, a rail and hangers in the right
  const F = (x, z) => P(x, D, z);
  let inner = "";
  inner += seg(F(4, 6), F(W - 4, 6)) + seg(F(HW, 6), F(HW, H - 4));
  for (const z of [30, 54, 78]) inner += seg(F(6, z), F(HW - 3, z));
  inner += seg(F(HW + 4, 90), F(W - 6, 90));
  for (const x of [HW + 14, HW + 26, HW + 38, HW + 50]) inner += seg(F(x, 90), F(x - 8, 80)) + seg(F(x, 90), F(x + 8, 80)) + seg(F(x - 8, 80), F(x - 8, 46)) + seg(F(x + 8, 80), F(x + 8, 46)) + seg(F(x - 8, 46), F(x + 8, 46));
  mk("path", { d: inner, class: "nf lo" }, g);

  function door(y0, x0) {
    const s = solid(mk("g", {}, g));
    const pull = mk("path", { class: "nf lo" }, s.g);
    return { s, pull, y0, x: tween(x0), last: NaN };
  }
  const back = door(D + 0.6, 0), fr = door(D + 3.6, HW - 14);
  const doors = [back, fr];

  function draw(d, x) {
    if (x === d.last) return;
    d.last = x;
    const [r, i] = rings(x + 0.6, d.y0, x + HW - 0.6, d.y0 + 2.4, 0.8, 0.4);
    put(d.s, prism(P, front, r, i, 3, H - 2));
    const px = d === back ? x + HW - 6 : x + 6;
    d.pull.setAttribute("d", seg(P(px, d.y0 + 2.4, 46), P(px, d.y0 + 2.4, 70)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of doors) { draw(d, tval(d.x, now)); if (!tdone(d.x, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = [F(HW / 2, H / 2), F(HW * 1.5, H / 2)];
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 50 && Math.abs(mids[best][1] - sy) < 110 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    const k = reach / 100;
    tset(back.x, a === 0 ? HW * k : 0, now, 0);
    tset(fr.x, a < 0 ? HW - 14 : a === 1 ? HW - HW * k : HW, now, a === 0 ? 0 : 0);
    back.s.sil.classList.toggle("hi", a === 0);
    fr.s.sil.classList.toggle("hi", a !== 0);
    read.textContent = a < 0 ? "rest" : a === 0 ? "bay 1" : "bay 2";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; const a = act; act = -2; setActive(a); }, destroy: bag.dispose };
}

hairline({
  name: "wardrobe2",
  means: "A wardrobe with two sliding doors: the door over the bay under the pointer slides across to open it, showing shelves or a rail.",
  rules: [1, 4, 5, 6],
  range: [50, 100, 100],
  tour: [[146, 146], [215, 180], [226, 61], null],
  mount,
});

bedframe.code:
/**
 * Storage bed: a base, a headboard and a mattress platform hinged at the
 * head. The pointer's place along the bed sets the lift: nearer the foot,
 * the platform rises higher on its hinge and opens the storage well under
 * it. At rest the platform stands just ajar, bright. The slider is the
 * highest lift.
 *
 * The pattern: a single part following the pointer, a tilting answer.
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, run, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const LN = 100, WD = 66, BZ = 24, HX = 4, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 1.58);
  const up = rad(55);
  fit(C, [[-8, 0, 0], [LN, WD, 0], [LN, 0, 0], [-8, WD, 64], [HX + 100 * Math.cos(up), WD, BZ + 100 * Math.sin(up)], [HX + 100 * Math.cos(up), 0, BZ + 100 * Math.sin(up)]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [hr, hi] = rings(-8, -2, 0, WD + 2, 3, 1.4);
  put(solid(g), prism(P, front, hr, hi, 0, 64));
  const [br, bi] = rings(0, 0, LN, WD, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  // the storage well: its rim and a folded duvet inside
  mk("path", { d: poly(ringAt(P, rrect(5, 5, LN - 5, WD - 5, 2, 3), BZ)), class: "nf" }, g);
  mk("path", { d: poly(ringAt(P, rrect(40, 10, 80, 40, 3, 3), BZ - 0.1)) + poly(ringAt(P, rrect(44, 14, 76, 36, 2, 3), BZ - 0.1)), class: "nf lo" }, g);

  const lid = solid(mk("g", {}, g));
  const seam = mk("path", { class: "nf lo" }, lid.g);
  const pil = solid(lid.g);
  const ring = rrect(1, 1, LN - 1, WD - 1, 4, 4), inner = rrect(3, 3, LN - 3, WD - 3, 2.4, 4);
  const pr = rrect(8, 8, 26, WD - 8, 5, 4), pi = rrect(10, 10, 24, WD - 10, 3.4, 4);
  const a = spring(REST);
  let last = NaN;

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const t = rad(deg), c = Math.cos(t), s = Math.sin(t);
    const R = (q, z) => P(HX + (q.u - HX) * c - (z - BZ) * s, q.v, BZ + (q.u - HX) * s + (z - BZ) * c);
    const at = (rg, z) => rg.map((q) => R(q, z));
    put(lid, { sil: poly(hull(at(ring, BZ + 0.4).concat(at(ring, BZ + 15)))), crease: poly(at(inner, BZ + 15)) });
    seam.setAttribute("d", open(run(ring, front).map((q) => R(q, BZ + 4))));
    put(pil, { sil: poly(hull(at(pr, BZ + 15).concat(at(pr, BZ + 20)))), crease: poly(at(pi, BZ + 20)) });
  }

  const B = register(stage, (dt) => {
    const moving = stepS(a, dt);
    draw(a.x);
    return moving;
  });
  bag.add(B.unregister);
  lid.sil.classList.add("hi");

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -20 || x > LN + 30 || y < -20 || y > WD + 20) return leave();
    const f = clamp(x / LN, 0, 1);
    a.t = REST + (clamp(top, 20, 55) - REST) * f;
    read.textContent = Math.round(a.t) + "°";
    B.wake();
  }
  function leave() { a.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = v; }, destroy: bag.dispose };
}

hairline({
  name: "bedframe",
  means: "A storage bed: the platform lifts on its head hinge, higher the nearer the pointer stands to the foot, opening the well under it.",
  rules: [1, 3, 5, 8],
  range: [20, 45, 55],
  tour: [[260, 255], [204, 227], [160, 205], null],
  mount,
});

mailslot.code:
/**
 * Letterbox flap: a door with a brass-plate letterbox, its flap hinged along
 * the top of the slot. As the pointer nears the slot the flap swings up and
 * out, and a letter slides out through the opening under it. At rest the
 * flap hangs just ajar, bright. The slider is the widest swing.
 *
 * The pattern: a single part following the pointer, a swinging answer.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, H = 130, T = 6, FY = T + 1.6, X0 = 24, X1 = 96, ZB = 56, ZH = 76, REST = 8, LL = 44;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wide = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [W, T + 30, 0], [0, T, H], [W, T + 30, H]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const face = (rg, y) => rg.map((q) => P(q.u, y, q.v));

  const [dr, di] = rings(0, 0, W, T, 2, 1);
  put(solid(g), prism(P, front, dr, di, 0, H));
  // door panels below and above the letterbox
  mk("path", { d: poly(face(rrect(14, 12, W - 14, 42, 3, 3), T)) + poly(face(rrect(14, 92, W - 14, H - 12, 3, 3), T)), class: "nf lo" }, g);
  const [pr, pi] = rings(X0 - 10, T, X1 + 10, FY, 1, 0.5);
  put(solid(g), prism(P, front, pr, pi, ZB - 8, ZH + 6));
  mk("path", { d: poly(face(rrect(X0 - 10, ZB - 8, X1 + 10, ZH + 6, 3, 4), FY)), class: "nf" }, g);
  mk("path", { d: poly(face(rrect(X0, ZB, X1, ZH, 2, 4), FY)), class: "nf lo" }, g);

  const letter = solid(mk("g", {}, g));
  const vee = mk("path", { class: "nf lo" }, letter.g);
  const flap = solid(mk("g", {}, g));
  const fr = rrect(X0 - 2, 0, X1 + 2, ZH - ZB + 2, 2, 4);
  const a = spring(REST);
  let last = NaN;

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const t = rad(deg), c = Math.cos(t), s = Math.sin(t);
    const lay = (o) => fr.map((q) => P(q.u, FY + 0.3 + q.v * s + o * c, ZH + 1 - q.v * c + o * s));
    const outer = lay(1.6);
    put(flap, { sil: poly(hull(lay(0).concat(outer))), crease: seg(P(X0 + 6, FY + 1.9, ZH + 1), P(X1 - 6, FY + 1.9, ZH + 1)) });
    const f = clamp((deg - REST) / 50, 0, 1), y1 = FY + LL * f;
    if (f < 0.04) { put(letter, { sil: "", crease: "" }); vee.setAttribute("d", ""); return; }
    const [lr, li] = rings(X0 + 8, FY, X1 - 8, y1, 1, 0.5);
    put(letter, prism(P, front, lr, li, ZB + 1, ZB + 2));
    const m = Math.max(FY, y1 - 16);
    vee.setAttribute("d", seg(P(X0 + 9, y1, ZB + 2), P((X0 + X1) / 2, m, ZB + 2)) + seg(P((X0 + X1) / 2, m, ZB + 2), P(X1 - 9, y1, ZB + 2)));
  }

  const B = register(stage, (dt) => {
    const moving = stepS(a, dt);
    draw(a.x);
    return moving;
  });
  bag.add(B.unregister);
  flap.sil.classList.add("hi");

  const mid = P((X0 + X1) / 2, FY, (ZB + ZH) / 2);
  function move([sx, sy]) {
    const d = Math.hypot(sx - mid[0], sy - mid[1]);
    const f = clamp(1 - (d - 20) / 110, 0, 1);
    a.t = REST + (clamp(wide, 30, 80) - REST) * f;
    read.textContent = f > 0 ? Math.round(a.t) + "°" : "rest";
    B.wake();
  }
  function leave() { a.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wide = v; }, destroy: bag.dispose };
}

hairline({
  name: "mailslot",
  means: "A door letterbox: the flap swings up and out as the pointer nears the slot, and a letter slides through under it.",
  rules: [1, 3, 5, 8],
  range: [30, 70, 80],
  tour: [[216, 154], [157, 40], [280, 269], null],
  mount,
});

sheetrack.code:
/**
 * Sheet rack: a slotted floor rack of sheet metal, the sheets standing on
 * edge, cut to uneven heights and pushed in unevenly. The pointer picks a
 * sheet by its rest position and that sheet slides out of its slot toward
 * the reader, its neighbours easing out a little after it. At rest one sheet
 * stands proud and bright. The slider is how far the chosen sheet slides.
 *
 * The pattern: a single row picked by rest screen x (rule 01), a 700ms tween
 * per sheet staggered by distance (rule 02); sheets lie in planes of constant
 * x, so painting by x stays honest however far they slide.
 */
const {
  Cam, fit, prism, proj, rings, facing, seg, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 9, GAP = 8, X0 = -32, HT = [44, 52, 40, 48, 56, 42, 50, 38, 46], OUT = [2, 0, 4, 1, 6, 0, 3, 1, 2], FAV = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-42, -26, 0], [42, 26, 0], [-42, -26, 58], [42, 58, 58]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let reach = value;

  const [bo, bi] = rings(-42, -26, 42, 26, 4, 1.4);
  put(solid(g), prism(P, front, bo, bi, 0, 5));
  let d = "";
  for (let i = 0; i <= N; i++) { const x = X0 - GAP / 2 + i * GAP; d += seg(P(x, -24, 5), P(x, 24, 5)); }
  mk("path", { class: "nf lo", d }, g);
  const [po, pi] = rings(-41, -25, -37, -21, 1.5, 0.8);
  put(solid(g), prism(P, front, po, pi, 5, 30));

  const sheets = [];
  for (let i = 0; i < N; i++) {
    const s = solid(g);
    sheets.push({ i, x: X0 + i * GAP, s, tw: tween(OUT[i]), drawn: NaN, sx: P(X0 + i * GAP, 0, HT[i] / 2)[0] });
  }
  const [qo, qi] = rings(37, -25, 41, -21, 1.5, 0.8);
  put(solid(g), prism(P, front, qo, qi, 5, 30));

  function draw(sh, now) {
    const y = tval(sh.tw, now);
    if (Math.abs(y - sh.drawn) < 1e-3) return;
    sh.drawn = y;
    const [o, i] = rings(sh.x - 0.8, -22 + y, sh.x + 0.8, 22 + y, 0.6, 0.3);
    put(sh.s, prism(P, front, o, i, 5, 5 + HT[sh.i]));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const sh of sheets) { draw(sh, now); if (!tdone(sh.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let sel = -1;
  function choose(a) {
    if (a === sel && a !== -1) return;
    sel = a;
    const now = performance.now();
    for (const sh of sheets) {
      const k = Math.abs(sh.i - a);
      const to = a < 0 ? OUT[sh.i] : k === 0 ? 30 * reach : k === 1 ? 9 * reach : k === 2 ? 3 * reach : 0;
      tset(sh.tw, to, now, a < 0 ? 0 : k * 45);
      sh.s.sil.classList.toggle("hi", a < 0 ? sh.i === FAV : k === 0);
    }
    read.textContent = a < 0 ? "rest" : "sheet " + (a + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let best = -1, bd = Infinity;
      for (const sh of sheets) { const dd = Math.abs(p[0] - sh.sx); if (dd < bd) { bd = dd; best = sh.i; } }
      choose(bd < 30 ? best : -1);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  sel = 0; choose(-1);
  for (const sh of sheets) draw(sh, performance.now());
  return { set: (v) => { reach = v; const a = sel; sel = -2; choose(a); }, destroy: bag.dispose };
}

hairline({
  name: "sheetrack",
  means: "A slotted rack of sheet metal on edge: the sheet under the pointer slides out toward you, its neighbours easing after it.",
  rules: [1, 2, 3, 5, 6, 8],
  range: [0.5, 1, 1.3],
  tour: [[147, 148], [253, 201], [200, 164], null],
  mount,
});

robotgripper.code:
/**
 * Gripper: a robot wrist flange carrying a parallel gripper, two fingers
 * closed on a small cube on the palm. The pointer's screen x opens it: the
 * wrist turns and the fingers slide apart. At rest the fingers hold the cube,
 * the cube bright; while the pointer works it, the fingers take the bright.
 * The slider is how far the wrist turns over the full travel.
 *
 * The pattern: a continuous input (screen x, which never moves) on one spring;
 * fingers and cube re-sort far to near as the wrist turns.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, spring, stepS,
  clamp, disposer, mk, pointer, put, register, solid,
} = HL;

const ZB = 20, ZP = 33, REST = 0.04;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-30, -30, 0], [30, 30, 0], [-30, -30, 62], [30, 30, 62]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let sweep = value;

  put(solid(g), prism(P, front, circ(24, 64), circ(22.6, 64), 0, 5));
  put(solid(g), prism(P, front, circ(12, 48), circ(10.8, 48), 5, ZB));
  const body = solid(g), rail = solid(g);
  const top = mk("g", {}, g);
  const cube = solid(top);
  const fingers = [-1, 1].map((sd) => {
    const fg = mk("g", {}, top);
    return { sd, g: fg, base: solid(fg), tip: solid(fg) };
  });

  const B0 = rings(-22, -10, 22, 10, 4, 1.4), RL = rings(-19, -3, 19, 3, 1.5, 0.8), CU = rings(-6, -6, 6, 6, 1.5, 1);
  const sp = spring(REST);
  let drawn = NaN, active = false;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const a = -0.55 + t * 1.1 * sweep, x0 = 6 + t * 10;
    put(body, prism(P, front, turn(B0[0], a), turn(B0[1], a), ZB, ZP - 3));
    put(rail, prism(P, front, turn(RL[0], a), turn(RL[1], a), ZP - 3, ZP));
    put(cube, prism(P, front, turn(CU[0], a), turn(CU[1], a), ZP, ZP + 12));
    const keyed = [[0, cube.g]];
    for (const f of fingers) {
      const u0 = f.sd > 0 ? x0 : -x0 - 5, u1 = u0 + 5;
      const [o, i] = rings(u0, -8, u1, 8, 1.5, 1);
      const [o2, i2] = rings(f.sd > 0 ? u0 : u0 + 2, -5, f.sd > 0 ? u1 - 2 : u1, 5, 1.2, 0.8);
      put(f.base, prism(P, front, turn(o, a), turn(i, a), ZP - 4, ZP + 16));
      put(f.tip, prism(P, front, turn(o2, a), turn(i2, a), ZP + 16, ZP + 26));
      const um = f.sd * (x0 + 2.5);
      keyed.push([um * (Math.cos(a) + Math.sin(a)), f.g]);
    }
    keyed.sort((p, q) => p[0] - q[0]);
    for (const [, el] of keyed) top.appendChild(el);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function mark() {
    cube.sil.classList.toggle("hi", !active);
    for (const f of fingers) { f.base.sil.classList.toggle("hi", active); f.tip.sil.classList.toggle("hi", active); }
    read.textContent = active ? Math.round(12 + sp.t * 20) + "mm" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { active = true; sp.t = clamp((p[0] - 100) / 200, 0, 1); mark(); },
    leave: () => { active = false; sp.t = REST; mark(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); mark();
  return { set: (v) => { sweep = v; drawn = NaN; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "robotgripper",
  means: "A robot gripper holding a cube: the pointer's x turns the wrist and slides the two fingers open; the fingers are bright while they move.",
  rules: [1, 3, 5, 6, 8],
  range: [0.5, 1, 1.5],
  tour: [[136, 137], [264, 201], [249, 133], null],
  mount,
});

valvewheel.code:
/**
 * Valve wheel: a gate valve on a flanged pipe, its bonnet, the threaded stem
 * and the hand wheel on top. The pointer's screen x is how far the valve is
 * open: the wheel turns and climbs the stem as it opens. At rest it sits a
 * third open, the knob on the rim bright; when the pointer turns it, the rim
 * takes the bright. The slider is how many turns the full travel takes.
 *
 * The pattern: a continuous input (screen x, which never moves) on one spring.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, ringAt, run, open, seg, spring, stepS,
  clamp, disposer, mk, pointer, put, register, solid,
} = HL;

const WR = 24, Z0 = 50, LIFT = 22, REST = 0.3;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-46, -14, 0], [46, 14, 0], [-46, 14, 22], [46, -14, 22], [-WR, -WR, Z0 + LIFT + 9], [WR, WR, Z0 + LIFT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let turns = value;

  // pipe, flanges, body, bonnet: far to near
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  box(-46, -12, -40, 12, 3, 1, 0, 22);
  box(-40, -8, 40, 8, 4, 1.2, 3, 19);
  box(-14, -14, 14, 14, 5, 1.5, 0, 28);
  box(40, -12, 46, 12, 3, 1, 0, 22);
  box(-8, -8, 8, 8, 3, 1.2, 28, 40);
  for (const [x, y] of [[-43, -9], [-43, 9], [43, -9], [43, 9]]) mk("path", { class: "nf lo", d: seg(P(x, y, 22), P(x, y, 22.6)) + seg(P(x - 1, y, 22), P(x + 1, y, 22)) }, g);

  const stem = solid(g);
  const wg = mk("g", {}, g);
  const spokes = mk("path", { class: "nf sil", d: "" }, wg);
  const hub = solid(wg);
  const rim = solid(wg);
  rim.sil.classList.add("nf");
  const rimFront = mk("path", { class: "nf lo", d: "" }, wg);
  const knob = solid(wg);
  const O = circ(WR, 56), I = circ(WR - 3, 56);

  const sp = spring(REST, { k: 100, c: 18 });
  let drawn = NaN, active = false;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const z = Z0 + LIFT * t, a = t * Math.PI * 2 * turns;
    put(stem, prism(P, front, circ(1.8, 16), null, 40, z + 1));
    let d = "";
    for (let k = 0; k < 4; k++) {
      const b = a + (k * Math.PI) / 2, c = Math.cos(b), s = Math.sin(b);
      d += seg(P(4 * c, 4 * s, z + 1.5), P((WR - 2) * c, (WR - 2) * s, z + 1.5));
    }
    spokes.setAttribute("d", d);
    put(hub, prism(P, front, circ(4.5, 24), circ(3.3, 24), z, z + 4));
    put(rim, prism(P, front, O, I, z, z + 3));
    rimFront.setAttribute("d", open(ringAt(P, run(O, front), z + 3)));
    const kc = Math.cos(a + 0.4) * (WR - 1.5), ks = Math.sin(a + 0.4) * (WR - 1.5);
    put(knob, prism(P, front, disc(kc, ks, 2.2, 16), disc(kc, ks, 1.4, 16), z + 3, z + 10));
    // the knob is painted behind the rim when it stands on the far side
    if (kc + ks < 0) rim.g.before(knob.g); else rimFront.after(knob.g);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function mark() {
    rim.sil.classList.toggle("hi", active);
    knob.sil.classList.toggle("hi", !active);
    read.textContent = active ? Math.round(sp.t * 100) + "%" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { active = true; sp.t = clamp((p[0] - 90) / 220, 0, 1); mark(); },
    leave: () => { active = false; sp.t = REST; mark(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); mark();
  return { set: (v) => { turns = v; drawn = NaN; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "valvewheel",
  means: "A gate valve: the pointer's x opens it, and the hand wheel turns and climbs its stem; the rim is bright while it turns.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.5],
  tour: [[140, 180], [300, 150], [235, 118], null],
  mount,
});

stagelight.code:
/**
 * Stage lights: five PAR cans hung from a square truss between two towers.
 * The pointer picks a can: it tips down toward the front, and the wave runs
 * out to its neighbours, smaller each step. At rest the cans hang at uneven
 * angles with the second one bright. The slider is how far the picked can tips.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, seg, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const XS = [-44, -22, 0, 22, 44], Z = 92, TZ = 100, LEN = 22, RB = 7, RF = 10.5;
const RESTP = [18, 34, 8, 26, 14], REST = 1, FALL = [1, 0.5, 0.2, 0.08, 0.04];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-70, -6, 0], [70, 6, 0], [-70, -6, 112], [70, 6, 112], [-44, 30, 60], [44, 30, 60]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const tower = (x) => { const [r, i] = rings(x - 5, -5, x + 5, 5, 1.5, 0.8); const s = solid(g); put(s, prism(P, front, r, i, 0, 112)); return s; };
  tower(-64);
  const [tr, ti] = rings(-59, -5, 59, 5, 1.5, 0.8);
  put(solid(g), prism(P, front, tr, ti, TZ, TZ + 10));
  let lace = "";
  for (let x = -55; x < 55; x += 10) lace += seg(P(x, 5, TZ + 1), P(x + 5, 5, TZ + 9)) + seg(P(x + 5, 5, TZ + 9), P(x + 10, 5, TZ + 1));
  mk("path", { class: "nf lo", d: lace }, g);
  const cans = XS.map((x, i) => {
    const yoke = mk("path", { class: "nf sil" }, g), body = mk("path", { class: "sil" }, g), lens = mk("path", { class: "nf lo" }, g);
    return { i, x, yoke, body, lens, tw: tween(RESTP[i]), last: NaN };
  });
  const t2 = tower(64);
  let tip = value, sel = REST, over = false;

  function drawCan(c, deg) {
    if (deg === c.last) return;
    c.last = deg;
    const p = (deg * Math.PI) / 180, d = [0, Math.sin(p), -Math.cos(p)], u = [1, 0, 0], v = [0, Math.cos(p), Math.sin(p)];
    const ring = (off, r) => Array.from({ length: 24 }, (_, k) => {
      const t = (k / 24) * Math.PI * 2, q = (j) => [c.x, 0, Z][j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(-2, RB), lensRing = ring(LEN, RF);
    c.body.setAttribute("d", poly(hull(back.concat(lensRing))));
    c.lens.setAttribute("d", poly(ring(LEN, RF - 2)));
    c.yoke.setAttribute("d", seg(P(c.x - RB - 2, 0, Z), P(c.x - RB - 2, 0, TZ)) + seg(P(c.x + RB + 2, 0, Z), P(c.x + RB + 2, 0, TZ)) + seg(P(c.x - RB - 2, 0, Z), P(c.x + RB + 2, 0, Z)));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const c of cans) { drawCan(c, tval(c.tw, now)); if (!tdone(c.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  function choose(a) {
    sel = a;
    const now = performance.now(), top = 40 + 30 * tip;
    cans.forEach((c) => {
      const k = Math.abs(c.i - a), to = over ? RESTP[c.i] + (top - RESTP[c.i]) * FALL[k] : RESTP[c.i];
      tset(c.tw, Math.round(to * 10) / 10, now, k * 45);
      c.body.classList.toggle("hi", c.i === a);
    });
    read.textContent = over ? `can ${a + 1}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      let best = 0, bd = Infinity;
      cans.forEach((c) => { const d = Math.abs(P(c.x, 0, Z)[0] - p[0]); if (d < bd) { bd = d; best = c.i; } });
      over = bd < 40; choose(over ? best : REST);
    },
    leave: () => { over = false; choose(REST); },
  }));
  bag.add(() => svg.replaceChildren());
  choose(REST);
  return { set: (v) => { tip = v; if (over) choose(sel); }, destroy: bag.dispose };
}

hairline({
  name: "stagelight",
  means: "Five PAR cans on a truss: the one under the pointer tips down to the front and the tilt ripples out to its neighbours.",
  rules: [1, 2, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[182, 170], [129, 144], [235, 197], null],
  mount,
});

micstand2.code:
/**
 * Drum stool: a round throne on a threaded spindle over three splayed legs.
 * The pointer turns the seat to face it, and as it turns the thread winds the
 * seat up: nearer the stool, higher the seat. At rest the seat sits low with
 * its stitch dot bright. The slider is the pitch of the thread.
 */
const { Cam, circ, clamp, fit, facing, poly, prism, proj, ringAt, seg, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const R = 46, T = 13, FOOT = 50, COL = 4, LO = 30, HI = 66, REST = { a: 2.2, h: 38 };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-FOOT, -FOOT, 0], [FOOT, FOOT, 0], [FOOT, -FOOT, 0], [-FOOT, FOOT, 0], [-R, -R, HI + T], [R, R, HI + T]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const angs = [0.4, 0.4 + 2.094, 0.4 + 4.189];
  const foot = (a) => [Math.cos(a) * FOOT, Math.sin(a) * FOOT];
  const depth = (a) => Math.cos(a) + Math.sin(a);
  const legsBack = mk("path", { class: "nf sil" }, g);
  const feetBack = mk("g", {}, g);
  const tube = solid(g);
  put(tube, prism(P, front, circ(COL + 3, 24), circ(COL + 2, 24), 14, 22));
  const spindle = solid(g);
  const threads = mk("path", { class: "nf lo" }, g);
  const legsFront = mk("path", { class: "nf sil" }, g);
  const feetFront = mk("g", {}, g);
  const seat = solid(g);
  const stitch = mk("path", { class: "nf lo" }, g);
  const dot = mk("circle", { r: 3, class: "dot" }, g);
  // legs: from the collar at z 16 down to rubber feet on the ground, far to near
  let lb = "", lf = "";
  for (const a of angs) {
    const [fx, fy] = foot(a), s = seg(P(Math.cos(a) * COL, Math.sin(a) * COL, 16), P(fx, fy, 2));
    const brace = seg(P(fx * 0.55, fy * 0.55, 9), P(Math.cos(a + 2.094) * FOOT * 0.55, Math.sin(a + 2.094) * FOOT * 0.55, 9));
    const back = depth(a) < 0;
    if (back) lb += s; else lf += s;
    lb += brace;
    const f = solid(back ? feetBack : feetFront);
    const ring = circ(4, 16).map((q) => ({ ...q, u: q.u + fx, v: q.v + fy }));
    const inner = circ(3, 16).map((q) => ({ ...q, u: q.u + fx, v: q.v + fy }));
    put(f, prism(P, front, ring, inner, 0, 3));
  }
  legsBack.setAttribute("d", lb);
  legsFront.setAttribute("d", lf);

  const pitch = { v: value };
  const sa = spring(REST.a), sh = spring(REST.h);
  let last = "", over = false;

  function draw() {
    const key = sa.x.toFixed(3) + "," + sh.x.toFixed(2);
    if (key === last) return;
    last = key;
    const h = sh.x;
    put(spindle, prism(P, front, circ(COL, 20), circ(COL - 1, 20), 22, h));
    let th = "";
    for (let z = 26; z < h - 2; z += 5) {
      const ph = (z / 5 + sa.x * 3) % 1;
      th += seg(P(-COL * Math.SQRT1_2, COL * Math.SQRT1_2, z + ph), P(COL * Math.SQRT1_2, -COL * Math.SQRT1_2, z + 1.5 + ph));
    }
    threads.setAttribute("d", th);
    put(seat, prism(P, front, circ(R, 64), circ(R - 2.2, 64), h, h + T));
    const turn = sa.x;
    const st = circ(R - 8, 64).map((q) => {
      const c = Math.cos(turn), s = Math.sin(turn);
      return { ...q, u: q.u * c - q.v * s, v: q.u * s + q.v * c };
    });
    stitch.setAttribute("d", poly(ringAt(P, st, h + T)));
    const [dx, dy] = P(Math.cos(turn) * (R - 8), Math.sin(turn) * (R - 8), h + T);
    dot.setAttribute("cx", dx); dot.setAttribute("cy", dy);
  }

  const B = register(stage, (dt) => { const a = stepS(sa, dt), b = stepS(sh, dt); draw(); return a || b; });
  bag.add(B.unregister);

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      if (r > FOOT + 60) { leave(); return; }
      over = true;
      let a = Math.atan2(y, x);
      while (a - sa.t > Math.PI) a -= 2 * Math.PI;
      while (a - sa.t < -Math.PI) a += 2 * Math.PI;
      sa.t = a;
      const k = clamp(1 - r / (FOOT + 40), 0, 1);
      sh.t = clamp(LO + (HI - LO) * Math.pow(k, 0.8 / pitch.v), LO, HI);
      seat.sil.classList.add("hi");
      dot.setAttribute("class", "dot m");
      read.textContent = `${Math.round(sh.t)} cm`;
      B.wake();
    },
    leave: () => leave(),
  }));
  function leave() {
    over = false;
    sa.t = REST.a + Math.round((sa.t - REST.a) / (2 * Math.PI)) * 2 * Math.PI; sh.t = REST.h;
    seat.sil.classList.remove("hi");
    dot.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  bag.add(() => svg.replaceChildren());
  draw(); leave();
  return { set: (v) => { pitch.v = v; }, destroy: bag.dispose };
}

hairline({
  name: "micstand2",
  means: "A drum stool: the seat turns to face the pointer and winds up its spindle, higher the nearer you come.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.6],
  tour: [[200, 232], [285, 274], [73, 295], null],
  mount,
});

cdrack.code:
/**
 * Record crate: a wooden crate packed with record sleeves. The pointer digs:
 * the sleeve under it stands upright, the ones in front fall forward and the
 * ones behind lean back, so a gap opens on it. At rest the crate is parted a
 * little behind the middle. The slider is how far the sleeves fall.
 */
const { Cam, clamp, fit, fillet, poly, proj, seg, rings, prism, facing, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const N = 9, GAP = 8.5, X0 = -((N - 1) * GAP) / 2, HW = 21, H = 44, Z0 = 3;
const CX = 46, CY = 26, CH = 17, REST = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-CX - 22, -CY, 0], [CX + 22, CY, 0], [CX, -CY, 0], [-CX, CY, 0], [-CX, -CY, H + 4], [CX, CY, H + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-CX, -CY, CX, CY, 3, 1.2);
  put(solid(g), prism(P, front, cr, ci, 0, CH));
  const inner = mk("path", { class: "nf lo" }, g);
  const [ir] = rings(-CX + 3, -CY + 3, CX - 3, CY - 3, 1.5, 0.6);
  inner.setAttribute("d", poly(ir.map((q) => P(q.u, q.v, CH))));
  const sleeves = Array.from({ length: N }, (_, i) => {
    const el = mk("path", { class: "sil" }, g), disc = mk("path", { class: "nf lo" }, g);
    return { i, x: X0 + i * GAP, el, disc, tw: tween(0), last: NaN };
  });
  // the crate's near walls, painted over the sleeves' feet
  const lip = mk("path", { class: "sil" }, g);
  lip.setAttribute("d", poly(fillet([P(-CX, CY, CH), P(CX, CY, CH), P(CX, -CY, CH), P(CX, -CY, 0), P(CX, CY, 0), P(-CX, CY, 0)], [2, 2, 2, 2, 2, 2])));
  const slot = mk("path", { class: "nf lo" }, g);
  slot.setAttribute("d", seg(P(CX, -8, CH - 5), P(CX, 8, CH - 5)) + seg(P(-14, CY, CH - 5), P(14, CY, CH - 5)));
  let fall = value, sel = REST, over = false;

  const angleFor = (i, a) => (i === a ? 0 : i > a ? 26 : -16) * fall + (over ? 0 : (i > a ? 4 : 0));

  function drawSleeve(s, deg) {
    if (deg === s.last) return;
    s.last = deg;
    const t = (deg * Math.PI) / 180, sn = Math.sin(t), cs = Math.cos(t);
    const at = (y, h) => P(s.x + sn * h, y, Z0 + cs * h);
    s.el.setAttribute("d", poly(fillet([at(-HW, 0), at(HW, 0), at(HW, H), at(-HW, H)], [1, 1, 2, 2])));
    const ring = Array.from({ length: 28 }, (_, k) => { const a = (k / 28) * Math.PI * 2; return at(Math.cos(a) * 15, H / 2 + Math.sin(a) * 15); });
    s.disc.setAttribute("d", poly(ring));
  }

  const B = register(stage, (dt, now) => {
    let moving = false;
    for (const s of sleeves) { drawSleeve(s, tval(s.tw, now)); if (!tdone(s.tw, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function choose(a) {
    sel = a;
    const now = performance.now();
    sleeves.forEach((s) => {
      tset(s.tw, angleFor(s.i, a), now, Math.abs(s.i - a) * 40);
      s.el.classList.toggle("hi", s.i === a);
    });
    read.textContent = over ? `no ${String(a + 1).padStart(2, "0")}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      let best = -1, bd = Infinity;
      sleeves.forEach((s) => { const d = Math.abs(P(s.x, 0, Z0 + H / 2)[0] - p[0]); if (d < bd) { bd = d; best = s.i; } });
      const [ , cy] = P(0, 0, H / 2);
      if (bd > GAP * 3 || Math.abs(p[1] - cy) > 110) { if (over) { over = false; choose(REST); } return; }
      over = true; choose(best);
    },
    leave: () => { over = false; choose(REST); },
  }));
  bag.add(() => svg.replaceChildren());
  choose(REST);
  return { set: (v) => { fall = v; choose(sel); }, destroy: bag.dispose };
}

hairline({
  name: "cdrack",
  means: "A crate of record sleeves: the one under the pointer stands up as those in front fall forward and those behind lean back.",
  rules: [1, 2, 3, 5, 8],
  range: [0.5, 1, 1.3],
  tour: [[151, 134], [236, 176], [249, 183], null],
  mount,
});

pianolid.code:
/**
 * Upright piano: a tall case on two front posts, a keybed and a fallboard
 * over the keys, a top lid on a back hinge. The pointer opens it: the
 * fallboard swings up off the keys, the top lid tips open, and the key under
 * the pointer goes down. At rest the fallboard is ajar with its lock bright.
 * The slider is how far the lids open.
 */
const { Cam, clamp, fit, facing, fillet, poly, prism, proj, rings, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const W = 52, D = 16, TOP = 84, KY0 = D + 1, KY1 = 36, KZ = 44, NK = 14, KW = (2 * W - 10) / NK;
const REST = { f: 28, l: 5 };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-W, -D, 0], [W, KY1, 0], [W, -D, 0], [-W, KY1, 0], [-W, -D, TOP + 30], [W, D, TOP + 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-W, -D, W, D, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, TOP));
  for (const x of [-W + 5, W - 5]) {
    const [pr, pi] = rings(x - 3, KY1 - 6, x + 3, KY1, 1.5, 0.6);
    put(solid(g), prism(P, front, pr, pi, 0, KZ - 6));
  }
  const [kr, ki] = rings(-W + 1, D - 2, W - 1, KY1 + 1, 2, 0.8);
  put(solid(g), prism(P, front, kr, ki, KZ - 6, KZ));
  const plate = (x0, x1, y0, y1, z) => poly(fillet([P(x0, y0, z), P(x1, y0, z), P(x1, y1, z), P(x0, y1, z)], [0.8, 0.8, 0.8, 0.8]));
  const keys = Array.from({ length: NK }, (_, i) => {
    const x0 = -W + 5 + i * KW;
    return { i, x0, cx: x0 + KW / 2, el: mk("path", { class: "sil" }, g), last: NaN };
  });
  const blacks = mk("path", { class: "" }, g);
  let bd = "";
  keys.forEach((k, i) => { if (i < NK - 1 && [0, 1, 3, 4, 5].includes(i % 7)) bd += plate(k.x0 + KW * 0.68, k.x0 + KW * 1.32, KY0, KY0 + 9, KZ + 1.2); });
  const fall = mk("path", { class: "sil" }, g), fallEdge = mk("path", { class: "nf lo" }, g);
  const lock = mk("circle", { r: 2.6, class: "dot" }, g);
  const lid = mk("path", { class: "sil" }, g), lidEdge = mk("path", { class: "nf lo" }, g);
  let reach = value, sel = -1, last = "";
  const sf = spring(REST.f), sl = spring(REST.l), press = keys.map(() => spring(0));

  function draw() {
    const key = [sf.x, sl.x, ...press.map((s) => s.x)].map((v) => v.toFixed(2)).join();
    if (key === last) return;
    last = key;
    keys.forEach((k, i) => k.el.setAttribute("d", plate(k.x0 + 0.3, k.x0 + KW - 0.3, KY0, KY1, KZ + 0.4 - press[i].x)));
    blacks.setAttribute("d", bd);
    // fallboard: hinged at the back of the keybed, swings from flat over the keys up toward the case
    const t = (sf.x * Math.PI) / 180, L = KY1 - KY0 + 1, hz = KZ + 2.5;
    const fp = (x, s) => P(x, KY0 + Math.cos(t) * L * s, hz + Math.sin(t) * L * s);
    fall.setAttribute("d", poly(fillet([fp(-W + 3, 0), fp(W - 3, 0), fp(W - 3, 1), fp(-W + 3, 1)], [1, 1, 1.5, 1.5])));
    fallEdge.setAttribute("d", poly([fp(-W + 5, 0.86), fp(W - 5, 0.86)]));
    const [lx, ly] = fp(0, 0.93); lock.setAttribute("cx", lx); lock.setAttribute("cy", ly);
    // top lid: hinged along the back edge of the case
    const u = (sl.x * Math.PI) / 180, LD = 2 * D + 2;
    const lp = (x, s) => P(x, -D - 1 + Math.cos(u) * LD * s, TOP + 0.5 + Math.sin(u) * LD * s);
    lid.setAttribute("d", poly(fillet([lp(-W - 1, 0), lp(W + 1, 0), lp(W + 1, 1), lp(-W - 1, 1)], [1, 1, 2, 2])));
    lidEdge.setAttribute("d", poly([lp(-W + 2, 0.92), lp(W - 2, 0.92)]));
  }

  const B = register(stage, (dt) => {
    let m = stepS(sf, dt); m = stepS(sl, dt) || m;
    for (const s of press) m = stepS(s, dt) || m;
    draw(); return m;
  });
  bag.add(B.unregister);

  function update(over, p) {
    sel = -1;
    if (over) {
      let bd2 = Infinity;
      keys.forEach((k) => { const d = Math.abs(P(k.cx, (KY0 + KY1) / 2, KZ)[0] - p[0]); if (d < bd2) { bd2 = d; sel = k.i; } });
    }
    sf.t = over ? clamp(108 * reach, 40, 112) : REST.f;
    sl.t = over ? clamp(34 * reach, 10, 40) : REST.l;
    press.forEach((s, i) => { s.t = i === sel ? 1.6 : 0; });
    keys.forEach((k) => k.el.classList.toggle("hi", k.i === sel));
    lock.setAttribute("class", over ? "dot off" : "dot");
    read.textContent = over ? `key ${String(sel + 1).padStart(2, "0")}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); update(Math.abs(x) < W + 30 && y > -D - 40 && y < KY1 + 60, p); },
    leave: () => update(false),
  }));
  bag.add(() => svg.replaceChildren());
  update(false);
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "pianolid",
  means: "An upright piano: the pointer swings the fallboard up off the keys, tips the top lid open and presses the key beneath it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.05],
  tour: [[180, 262], [113, 234], [237, 296], null],
  mount,
});

scales2.code:
/**
 * Kitchen scale: a mixing bowl on a weighing platform over a rounded base
 * with a dial on its front face. The pointer's place across the frame is the
 * load: the bowl sinks on the platform and the needle swings round the dial.
 * At rest a little load sits in the bowl and the needle is bright.
 * The slider is the bowl's travel.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 60, Y1 = 60, BZ = 20, CX = 30, CY = 30, REST = 0.3;
const disc = (r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + CX, v: q.v + CY }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [CX - 30, CY, BZ + 42], [CX + 30, CY, BZ + 42], [CX, CY - 30, BZ + 42], [CX, CY + 30, BZ + 42]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, Y1, 12, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  // the dial on the front face (y = Y1), a ring of tick dots and a needle
  const DZ = 10, DR = 7.5, dial = [];
  for (let i = 0; i < 40; i++) { const a = (i / 40) * Math.PI * 2; dial.push(P(CX + DR * Math.sin(a), Y1, DZ + DR * Math.cos(a))); }
  mk("path", { d: poly(dial), class: "nf" }, g);
  for (let i = 0; i <= 6; i++) {
    const a = -2.2 + (i / 6) * 4.4, p = P(CX + (DR - 1.6) * Math.sin(a), Y1, DZ + (DR - 1.6) * Math.cos(a));
    mk("circle", { cx: p[0], cy: p[1], r: 0.9, class: "dot off" }, g);
  }
  const needle = mk("path", { class: "sil nf" }, g);
  const hubP = P(CX, Y1, DZ);
  mk("circle", { cx: hubP[0], cy: hubP[1], r: 1.4, class: "dot m" }, g);
  const plat = solid(g), bowl = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf lo" }, g);
  const load = mk("path", { class: "nf lo" }, g);

  const w = spring(REST);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const dz = -v * 10 * (travel / 50);
    const z0 = BZ + 6 + dz;
    put(plat, prism(P, front, disc(18), disc(16), BZ + 1 + dz, BZ + 3 + dz));
    const pts = [];
    for (let i = 0; i <= 6; i++) { const t = i / 6; pts.push(...ringAt(P, disc(12 + 17 * (1 - (1 - t) * (1 - t)), 40), z0 - 3 + 22 * t)); }
    bowl.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly(ringAt(P, disc(27.5, 48), z0 + 18.6)));
    load.setAttribute("d", poly(ringAt(P, disc(14 + 10 * v, 40), z0 + 4 + 12 * v)));
    const a = -2.2 + 4.4 * v;
    needle.setAttribute("d", open([hubP, P(CX + (DR - 1) * Math.sin(a), Y1, DZ + (DR - 1) * Math.cos(a))]));
  }

  const B = register(stage, (dt) => { const m = stepS(w, dt); draw(w.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function set(p) {
    act = p ? clamp((p[0] - 70) / 260, 0, 1) : null;
    w.t = act === null ? REST : act;
    bowl.classList.toggle("hi", act !== null);
    needle.classList.toggle("hi", act === null);
    read.textContent = act === null ? "rest" : Math.round(act * 2000) + " g";
    B.wake();
  }
  set(null);
  draw(REST);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = v; last = NaN; draw(w.x); }, destroy: bag.dispose };
}

hairline({
  name: "scales2",
  means: "A kitchen scale: the pointer across the frame is the load, so the bowl sinks on its platform and the dial's needle swings round.",
  rules: [3, 4, 5, 8],
  range: [20, 50, 80],
  tour: [[200, 113], [90, 203], [310, 226], null],
  mount,
});

cakestand2.code:
/**
 * Cake dome: a cake on a footed stand under a glass dome hinged at its left.
 * The nearer the pointer comes to the cake's middle, the further the dome
 * swings open on its hinge, up and back. At rest the dome sits a crack ajar,
 * bright. The slider is how far it can open.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PR = 34, PZ = 18, DR = 29, DH = 34, REST = 0.08;
const disc = (r, n = 40) => circ(r, n);
const E0 = Math.SQRT1_2, FMAX = 1.05;
function rotW(x, y, z, f) {
  const u = (y - x) * E0, v = (x + y) * E0, du = u - DR, dz = z - PZ;
  const u2 = DR + du * Math.cos(f) + dz * Math.sin(f), z2 = PZ + dz * Math.cos(f) - du * Math.sin(f);
  return [E0 * (v - u2), E0 * (u2 + v), z2];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let span = value;
  const C = Cam(45, 0.5, 2.85);
  const E = Math.SQRT1_2;
  const ext = [[-PR, -PR, 0], [PR, PR, 0], [PR, -PR, 0], [-PR, PR, 0], [0, 0, PZ + DH + 4]];
  for (const [x, y, z] of [[-DR, 0, PZ], [DR, 0, PZ], [0, DR, PZ], [0, -DR, PZ], [0, 0, PZ + DH + 4], [DR * E, DR * E, PZ], [DR * E, DR * E, PZ + DH * 0.7]]) ext.push(rotW(x, y, z, FMAX));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(16), disc(14), 0, 2.4));
  put(solid(g), prism(P, front, disc(4.5), disc(3.5), 2.4, PZ - 2));
  put(solid(g), prism(P, front, disc(PR, 48), disc(PR - 3, 48), PZ - 2, PZ));
  const cake = solid(g);
  put(cake, prism(P, front, disc(22), disc(20.5), PZ, PZ + 15));
  const ch = P(4, -3, PZ + 16.5);
  mk("circle", { cx: ch[0], cy: ch[1], r: 2.4, class: "dot m" }, g);
  const dome = mk("path", { class: "sil nf" }, g), rim = mk("path", { class: "nf lo" }, g), knob = mk("path", { class: "nf" }, g);
  // the dome, rotated about a hinge at its far edge (toward -x, -y)
  const rot = (x, y, z, f) => P(...rotW(x, y, z, f));
  const ringR = (r, z, f, n = 36) => circ(r, n).map((q) => rot(q.u, q.v, z, f));

  const o = spring(REST);
  let last = NaN;
  function draw() {
    if (o.x === last) return;
    last = o.x;
    const f = o.x * FMAX * (0.5 + span / 160), pts = [];
    for (let i = 0; i <= 7; i++) { const t = (i / 7) * (Math.PI / 2); pts.push(...ringR(DR * Math.cos(t) + 0.01, PZ + 0.3 + DH * Math.sin(t), f)); }
    dome.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly(ringR(DR, PZ + 2, f, 48)));
    knob.setAttribute("d", poly(hull(ringR(3, PZ + DH, f, 16).concat(ringR(3, PZ + DH + 4, f, 16)))));
  }

  const B = register(stage, (dt) => { const m = stepS(o, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(p) {
    const w = p ? unproj(C, p[0], p[1], PZ) : null;
    const dd = w ? Math.hypot(w[0], w[1]) : Infinity, act = dd < PR + 14;
    o.t = act ? clamp(1.15 - dd / (PR + 6), 0.2, 1) : REST;
    dome.classList.toggle("hi", !act);
    cake.sil.classList.toggle("hi", act);
    read.textContent = act ? Math.round(o.t * 100) + "%" : "rest";
    B.wake();
  }
  set(null);
  draw();
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { span = v; last = NaN; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "cakestand2",
  means: "A cake dome: the nearer the pointer comes to the cake, the further the glass dome swings open on its hinge at the left.",
  rules: [1, 3, 4, 8],
  range: [20, 50, 80],
  tour: [[200, 177], [99, 167], [200, 217], null],
  mount,
});

garageopener.code:
/**
 * Garage door: a garage block with an up-and-over door on its front face.
 * The pointer's height over the door tilts it up on its top hinge into a
 * canopy, on a spring. At rest the door hangs a little open and its handle
 * is bright. The slider is how far the door can swing.
 *
 * The pattern: one continuous value from the pointer's screen y, measured
 * against the closed door's fixed edges, so the moving panel never shifts it.
 */
const {
  Cam, clamp, facing, fit, lerp, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 10, X1 = 52, FY = 70, DH = 32, REST = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[0, 0, 0], [62, 0, 0], [0, 72, 0], [62, 72, 0], [0, 0, 50], [62, 72, 50], [X0, FY + DH, DH], [X1, FY + DH, DH]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 62, FY, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 44));
  const [rr, ri] = rings(-2, -2, 64, FY + 2, 3, 1.2);
  put(solid(g), prism(P, front, rr, ri, 44, 49));
  // the opening: its frame, and the far back wall line seen through it
  const hole = mk("path", { class: "nf lo" }, g);
  hole.setAttribute("d", poly([P(X0, FY, 0), P(X1, FY, 0), P(X1, FY, DH), P(X0, FY, DH)])
    + seg(P(X0 + 4, FY - 1, DH - 4), P(X1 - 4, FY - 1, DH - 4)) + seg(P(X1 - 4, FY - 1, 0), P(X1 - 4, FY - 1, DH - 4)));
  // a drive slab in front of the door
  const drive = mk("path", { class: "dash" }, g);
  drive.setAttribute("d", seg(P(X0, FY + 2, 0), P(X0, FY + 44, 0)) + seg(P(X1, FY + 2, 0), P(X1, FY + 44, 0)));

  const door = mk("path", { class: "sil" }, g);
  const ribs = mk("path", { class: "nf lo" }, g);
  const handle = mk("circle", { class: "dot", r: 3 }, g);

  // a point on the panel: s from its top hinge down (0..DH), swung by a degrees
  const at = (x, s, a) => P(x, FY + 0.6 + s * Math.sin(rad(a)), DH - s * Math.cos(rad(a)));
  let last = null;
  function draw(a) {
    const k = a.toFixed(2);
    if (k === last) return;
    last = k;
    door.setAttribute("d", poly([at(X0, 0, a), at(X1, 0, a), at(X1, DH, a), at(X0, DH, a)]));
    let d = "";
    for (let i = 1; i < 5; i++) d += seg(at(X0 + 1.5, (DH * i) / 5, a), at(X1 - 1.5, (DH * i) / 5, a));
    ribs.setAttribute("d", d);
    const h = at((X0 + X1) / 2, DH - 3.5, a);
    handle.setAttribute("cx", h[0]); handle.setAttribute("cy", h[1]);
  }

  const s = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(s.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  // hit: the closed door's fixed screen box; height within it sets the swing
  const bot = Math.max(P(X0, FY, 0)[1], P(X1, FY, 0)[1]), topY = Math.min(P(X0, FY, DH)[1], P(X1, FY, DH)[1]);
  const lx = P(X1, FY, 0)[0], rx = P(X0, FY, 0)[0];
  const xa = Math.min(lx, rx) - 20, xb = Math.max(lx, rx) + 20;
  function move([sx, sy]) {
    if (sx < xa || sx > xb || sy < topY - 60 || sy > bot + 30) return leave();
    const t = clamp((bot + 10 - sy) / (bot + 10 - (topY - 30)), 0, 1);
    s.t = lerp(0, reach, t);
    door.setAttribute("class", "sil hi");
    handle.setAttribute("class", "dot off");
    read.textContent = Math.round(s.t) + "°";
    B.wake();
  }
  function leave() {
    s.t = REST;
    door.setAttribute("class", "sil");
    handle.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "garageopener",
  means: "A garage with an up-and-over door: raise the pointer over it and the door tilts up into a canopy.",
  rules: [1, 3, 5, 8],
  range: [50, 88, 90],
  tour: [[164, 235], [164, 190], [164, 150], null],
  mount,
});

skylightwin.code:
/**
 * Roof window: a pitched roof slope with a window set into it. The pointer's
 * height over the window turns its sash on the centre pivot, top out, bottom
 * in, on a spring; the half that swings in shows only through the opening.
 * At rest the sash stands a little turned and its handle is bright.
 *
 * The pattern: one continuous value from the pointer's screen y against the
 * window's fixed rest box, so the turning sash never moves the hit.
 */
const {
  Cam, clamp, fit, lerp, poly, proj, rad, seg, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const PIT = rad(34), Y0 = 70, RL = 92, RU = 84;
const WX0 = 22, WX1 = 70, WU0 = 16, WU1 = 70, AX = (WU0 + WU1) / 2, HV = (WU1 - WU0) / 2 - 2.5, REST = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  // world point on the roof plane: x across, u up the slope, n out of it
  const W = (x, u, n = 0) => [x, Y0 - u * Math.cos(PIT) + n * Math.sin(PIT), u * Math.sin(PIT) + n * Math.cos(PIT)];
  fit(C, [W(0, 0, -6), W(RL, 0, -6), W(0, RU), W(RL, RU), W(WX0, AX, 22), W(WX1, AX, 22)], 200, 168);
  const P0 = proj(C), P = (x, u, n) => P0(...W(x, u, n));

  const g = mk("g", {}, svg);
  const ring = (i, n) => [P(WX0 - i, WU0 - i, n), P(WX1 + i, WU0 - i, n), P(WX1 + i, WU1 + i, n), P(WX0 - i, WU1 + i, n)];
  const hole = (i, n) => poly(ring(i, n).reverse());
  // the half that swings in goes first: the roof, cut by the opening, hides all but what shows through it
  const sashIn = mk("path", { class: "" }, g);
  mk("path", { class: "sil", d: poly([P(0, 0, -5), P(RL, 0, -5), P(RL, 0, 0), P(RL, RU, 0), P(0, RU, 0), P(0, 0, 0)]) + hole(0, 0) }, g);
  mk("path", { class: "nf lo", d: seg(P(0, 0, 0), P(RL, 0, 0)) + seg(P(1.5, RU - 6, 0), P(RL - 1.5, RU - 6, 0)) + seg(P(1.5, 6, 0), P(RL - 1.5, 6, 0)) }, g);
  // frame: a curb standing out of the slope round the opening
  mk("path", { class: "", d: poly(ring(3, 2.5)) + hole(0, 2.5) }, g);
  mk("path", { class: "nf lo", d: poly(ring(0, 2.5)) }, g);
  const sashOut = mk("path", { class: "sil" }, g);
  const glass = mk("path", { class: "nf lo" }, g);
  const handle = mk("circle", { class: "dot", r: 3 }, g);

  // sash point: v along the slope from the pivot, turned by a degrees, top out
  const S = (x, v, a) => P(x, AX + v * Math.cos(rad(a)), 2.5 + v * Math.sin(rad(a)));
  let last = null;
  function draw(a) {
    const k = a.toFixed(2);
    if (k === last) return;
    last = k;
    const x0 = WX0 + 1, x1 = WX1 - 1;
    sashIn.setAttribute("d", poly([S(x0, -HV, a), S(x1, -HV, a), S(x1, 0, a), S(x0, 0, a)]));
    sashOut.setAttribute("d", poly([S(x0, 0, a), S(x1, 0, a), S(x1, HV, a), S(x0, HV, a)]));
    glass.setAttribute("d", poly([S(x0 + 3, 2, a), S(x1 - 3, 2, a), S(x1 - 3, HV - 3, a), S(x0 + 3, HV - 3, a)]) + seg(S(x0 + 3, HV / 2, a), S(x1 - 3, HV / 2, a)) + seg(S((x0 + x1) / 2, 2, a), S((x0 + x1) / 2, HV - 3, a)));
    const h = S((x0 + x1) / 2, HV - 1.5, a);
    handle.setAttribute("cx", h[0]); handle.setAttribute("cy", h[1]);
  }

  const s = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(s.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  // hit: the opening's fixed screen box; height within it sets the turn
  const box = ring(3, 2.5), xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const xa = Math.min(...xs) - 20, xb = Math.max(...xs) + 20, ya = Math.min(...ys), yb = Math.max(...ys);
  function move([sx, sy]) {
    if (sx < xa || sx > xb || sy < ya - 60 || sy > yb + 30) return leave();
    const t = clamp((yb + 10 - sy) / (yb - 10 - ya), 0, 1);
    s.t = lerp(0, reach, t);
    sashOut.setAttribute("class", "sil hi");
    handle.setAttribute("class", "dot off");
    read.textContent = Math.round(s.t) + "°";
    B.wake();
  }
  function leave() {
    s.t = REST;
    sashOut.setAttribute("class", "sil");
    handle.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "skylightwin",
  means: "A roof window in a pitched slope: raise the pointer over it and the sash turns on its centre pivot, top out.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 85],
  tour: [[160, 218], [191, 171], [216, 113], null],
  mount,
});

gatepost.code:
/**
 * Driveway gate: a barred sliding gate on a ground track between two posts.
 * The pointer's place along the drive slides the gate open past the far
 * post, on a spring. At rest the gate stands a little ajar and the latch on
 * the near post is bright. The slider is how far the gate can travel.
 *
 * The pattern: one continuous value from the pointer's screen x, mapped
 * against fixed rest points, so the moving gate never shifts the hit.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 70, GY0 = -6, GY1 = -2.5, REST = 12, H = 50;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -10, 0], [154, -10, 0], [154, 8, 0], [-4, 8, 0], [0, 0, H + 6], [150, -6, H]], 200, 168);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const track = mk("path", { class: "dash" }, g);
  track.setAttribute("d", seg(P(-2, (GY0 + GY1) / 2, 0), P(152, (GY0 + GY1) / 2, 0)));
  const [tr, ti] = rings(-2, GY0 - 1, 152, GY1 + 1, 1, 0.5);
  put(solid(g), prism(P, front, tr, ti, 0, 1.2));

  // gate: two rails, two stiles and bars; redrawn when its offset changes
  const gg = mk("g", {}, g);
  const BARS = [];
  for (let x = 10; x < L - 4; x += 8) BARS.push(x);
  const parts = [];
  const add = (x0, x1, z0, z1) => { const el = solid(gg); parts.push({ el, x0, x1, z0, z1 }); return el; };
  const bottom = add(0, L, 3, 8);
  add(0, 4, 8, 46);
  BARS.forEach((x) => add(x, x + 1.8, 8, 44));
  add(L - 4, L, 8, 46);
  const top = add(0, L, 44, 49);
  const wheels = mk("path", { class: "nf lo" }, gg);

  let lastO = null;
  function drawGate(o) {
    const k = o.toFixed(2);
    if (k === lastO) return;
    lastO = k;
    const ox = 6 + o;
    for (const p of parts) {
      const w = Math.min(p.x1 - p.x0, GY1 - GY0);
      const [r, i] = rings(ox + p.x0, GY0, ox + p.x1, GY1, Math.min(1.2, w / 2), Math.min(0.6, w / 3));
      put(p.el, prism(P, front, r, i, p.z0, p.z1));
    }
    const wh = (x) => seg(P(ox + x - 3, GY1, 1.5), P(ox + x + 3, GY1, 1.5));
    wheels.setAttribute("d", wh(10) + wh(L - 10));
  }

  // posts stand in front of the gate's line
  const post = (x0) => { const [r, i] = rings(x0, -1, x0 + 7, 6, 1.6, 0.8); const el = solid(g); put(el, prism(P, front, r, i, 0, H + 4)); return el; };
  post(-1);
  const near = post(76);
  const latch = mk("circle", { class: "dot", r: 3 }, g);
  const lp = P(76, 2.5, 30); latch.setAttribute("cx", lp[0]); latch.setAttribute("cy", lp[1]);

  const s = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(s, dt); drawGate(s.x); return m; });
  bag.add(B.unregister);
  drawGate(REST);

  // hit: pointer's screen x against the fixed track ends
  const a = P(0, 0, 0)[0], b = P(150, 0, 0)[0];
  const A0 = P(0, 0, 0), A1 = P(150, 0, H);
  function move([sx, sy]) {
    const inside = sy > Math.min(A0[1], A1[1]) - 40 && sy < Math.max(A0[1], A1[1]) + 40 && sx > a - 20 && sx < b + 20;
    if (!inside) return leave();
    const t = clamp((sx - a) / (b - a - 40), 0, 1);
    s.t = t * travel;
    top.sil.classList.add("hi"); bottom.sil.classList.add("hi");
    latch.setAttribute("class", "dot off");
    read.textContent = "open " + Math.round((t * travel / L) * 100) + "%";
    B.wake();
  }
  function leave() {
    s.t = REST;
    top.sil.classList.remove("hi"); bottom.sil.classList.remove("hi");
    latch.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = v; }, destroy: bag.dispose };
}

hairline({
  name: "gatepost",
  means: "A sliding driveway gate between two posts: move along the drive and the gate rolls open past the far post.",
  rules: [1, 3, 5, 8],
  range: [30, 66, 70],
  tour: [[90, 115], [200, 168], [293, 216], null],
  mount,
});

busstop2.code:
/**
 * Bus shelter: a back wall, an end panel and a flat canopy on two posts,
 * with a row of four tip-up seats on a rail along the wall. The pointer
 * picks a seat by where it stands: it folds down, and the seats beside it
 * tip part way, staggered from it. At rest the seats stand folded at uneven
 * angles and one is down, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row, each turning on a hinge.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, X0 = 10, W = 22, GAP = 4, HY = 12, HZ = 22, D = 14, TOP = 64, SZ = 4, REST = [80, 66, 88, 6], FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-2, -2, 0], [122, 42, 0], [122, -2, 0], [-2, 42, 0], [0, 0, TOP + 3], [120, 34, TOP + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const slab = (x0, y0, x1, y1, z0, z1, r = 2, b = 1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, a, i, z0, z1)); return s; };
  slab(-2, -2, 122, 42, 0, SZ, 6, 2);
  slab(2, 4, 118, 7, SZ, TOP, 1.2, 0.6);
  slab(2, 7, 5, 32, SZ, TOP, 1.2, 0.6);
  slab(6, 7, 114, 10, HZ - 3, HZ, 1, 0.5);

  const box = (pts) => poly(hull(pts.map((p) => P(...p))));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = X0 + k * (W + GAP), x1 = x0 + W, grp = mk("g", {}, g);
    // the bracket under the hinge
    const br = mk("path", { d: box([[x0 + W / 2 - 1, 7, HZ - 9], [x0 + W / 2 + 1, 7, HZ - 9], [x0 + W / 2 - 1, HY, HZ - 3], [x0 + W / 2 + 1, HY, HZ - 3], [x0 + W / 2 - 1, 7, HZ - 3], [x0 + W / 2 + 1, 7, HZ - 3]]) }, grp);
    const seat = mk("path", { class: "sil" }, grp), lip = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, x1, grp, br, seat, lip, a: tween(REST[k]), last: NaN });
  }
  slab(115, 30, 119, 34, SZ, TOP, 1.4, 0.7);
  slab(-2, -2, 122, 36, TOP, TOP + 3, 3, 1.4);

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg));
    const at = (x, d, t) => [x, HY + d * c - t * s, HZ + d * s + t * c];
    const pts = [];
    for (const x of [it.x0, it.x1]) for (const d of [0, D]) for (const t of [0, 2]) pts.push(at(x, d, t));
    it.seat.setAttribute("d", box(pts));
    it.lip.setAttribute("d", "M" + P(...at(it.x0 + 1, D - 1.5, 2)).join(" ") + "L" + P(...at(it.x1 - 1, D - 1.5, 2)).join(" "));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, HY + D / 2, HZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), to = a < 0 ? REST[k] : d === 0 ? 0 : d === 1 ? 52 : 86;
      tset(it.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.seat.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "seat " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "busstop2",
  means: "A bus shelter with tip-up seats: the seat under the pointer folds down, and the seats beside it tip part way.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[134, 149], [169, 167], [239, 202], null],
  mount,
});

trainhorn.code:
/**
 * Level crossing: a road crossing a railway, a barrier post on each side
 * with a lamp box. The pointer picks a side of the track: that barrier arm
 * swings down across the road and its lamps light, the other swings up.
 * At rest one arm hangs half down, bright. The slider is the rest lean.
 *
 * The pattern: one of two, a hinged arm turning about its pivot.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rad, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 26, L = 52, SZ = 4, REST = [40, 58];
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const BAR = [{ x: 30, y: 12, dir: 1 }, { x: 92, y: 70, dir: -1 }];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lean = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -4, 0], [126, 86, 0], [126, -4, 0], [-4, 86, 0], [30, 12, PZ + L], [92, 70, PZ + L]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-4, -4, 126, 86, 8, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  // road edges along x
  mk("path", { d: seg(P(-4, 22, SZ), P(126, 22, SZ)) + seg(P(-4, 60, SZ), P(126, 60, SZ)), class: "nf lo" }, g);
  mk("path", { d: seg(P(4, 41, SZ), P(46, 41, SZ)) + seg(P(76, 41, SZ), P(118, 41, SZ)), class: "nf dash" }, g);

  function post(b, parent) {
    const grp = mk("g", {}, parent);
    put(solid(grp), prism(P, front, disc(b.x, b.y, 2.2), disc(b.x, b.y, 1.4), SZ, PZ + 6));
    const [lr, li] = rings(b.x - 3, b.y - 7 * b.dir - 3, b.x + 3, b.y - 7 * b.dir + 3, 1.5, 0.8);
    put(solid(grp), prism(P, front, lr, li, PZ - 8, PZ - 2));
    const lamps = [-1.6, 1.6].map((o) => mk("circle", { r: 1.6, class: "dot off" }, grp));
    lamps.forEach((d, i) => { const p = P(b.x + 3, b.y - 7 * b.dir + (i ? 1.6 : -1.6), PZ - 5); d.setAttribute("cx", p[0]); d.setAttribute("cy", p[1]); });
    const arm = mk("path", { class: "sil" }, grp);
    return { ...b, grp, arm, lamps, a: tween(BAR.indexOf(b) ? REST[1] : lean), last: NaN };
  }
  const items = [post(BAR[0], g)];
  // the track along y: sleepers then two rails
  const tg = mk("g", {}, g);
  for (let y = 2; y <= 80; y += 8) { const [r, i] = rings(52, y, 68, y + 3, 1, 0.6); put(solid(tg), prism(P, front, r, i, SZ, SZ + 1.2)); }
  for (const x of [55, 64]) { const [r, i] = rings(x, -2, x + 2, 84, 0.8, 0.4); put(solid(tg), prism(P, front, r, i, SZ + 1.2, SZ + 2.6)); }
  items.push(post(BAR[1], g));

  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg)), pts = [];
    for (const t of [-4, L]) pts.push(...ringAt(P, disc(it.x, it.y + it.dir * t * c, 2.4, 12), PZ + t * s - 1.2), ...ringAt(P, disc(it.x, it.y + it.dir * t * c, 2.4, 12), PZ + t * s + 1.2));
    it.arm.setAttribute("d", poly(hull(pts)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unprojG(sx, sy);
    if (x < -4 || x > 126 || y < -4 || y > 86) return -1;
    return x < 60 ? 0 : 1;
  }
  const unprojG = (sx, sy) => HL.unproj(C, sx, sy, SZ);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    items.forEach((it, k) => {
      tset(it.a, a < 0 ? (k ? REST[1] : lean) : k === a ? 0 : 90, now, 0);
      const on = k === (a < 0 ? 0 : a);
      it.arm.classList.toggle("hi", on);
      it.lamps.forEach((d) => d.setAttribute("class", a >= 0 && k === a ? "dot" : "dot off"));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "west" : "east";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lean = v; if (act < 0) { act = -2; setActive(-1); } }, destroy: bag.dispose };
}

