  name: "cablecar2",
  means: "A chairlift: the chair under the pointer swings out on its hanger from the cable, and its neighbours swing a little less.",
  rules: [1, 2, 5, 8],
  range: [0, 45, 90],
  tour: [[142, 140], [181, 144], [258, 176], null],
  mount,
