divingboard.code:
/**
 * Diving board: a long sprung board on its stand, out over the pool's rim.
 * The pointer is where a diver stands: the further out along the board, the
 * deeper the board flexes down about its fulcrum. At rest it holds a slight
 * bow and the pool's rim is bright. The slider is the board's give.
 */
const {
  Cam, facing, fit, hull, open, poly, prism, proj, rings, run, unproj, spring, stepS, clamp, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = -62, X1 = 70, HW = 9, Z = 30, PIV = -46, REST = 2, MAX = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  const zAt = (x, a) => Z - Math.max(0, x - PIV) * Math.tan(rad(a));
  fit(C, [[X0, -HW, 0], [X1, HW, Z + 3], [X1, HW, zAt(X1, MAX * 1.4)], [110, 44, 0], [20, -44, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // pool: a low rim with the water line inset
  const pool = solid(g);
  put(pool, prism(P, front, ...rings(22, -40, 112, 40, 10, 6), 0, 3));
  // stand at the back, fulcrum under the board
  put(solid(g), prism(P, front, ...rings(X0 - 4, -HW - 3, PIV + 4, HW + 3, 3, 1.4), 0, Z - 1));
  put(solid(g), prism(P, front, ...rings(-26, -HW + 2, -16, HW - 2, 2.5, 1), 0, Z - 0.8));
  const board = solid(g);
  const [ring, inner] = rings(X0, -HW, X1, HW, 4, 1.2);
  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-3) return;
    drawn = a;
    const at = (q, dz) => P(q.u, q.v, zAt(q.u, a) + dz);
    const pts = ring.map((q) => at(q, 0)).concat(ring.map((q) => at(q, 2.6)));
    board.sil.setAttribute("d", poly(hull(pts)));
    board.cr.setAttribute("d", open(run(inner, front).map((q) => at(q, 2.6))));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  let over = null;
  function retarget() {
    const t = over === null ? 0 : clamp((over - PIV) / (X1 - PIV), 0, 1);
    sp.t = over === null ? REST : REST + (MAX * value - REST) * t;
    board.sil.classList.toggle("hi", over !== null);
    pool.sil.classList.toggle("hi", over === null);
    read.textContent = over === null ? "rest" : "flex " + String(Math.round(t * 10)).padStart(2, "0");
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], Z);
      over = x > X0 - 6 && x < X1 + 12 && Math.abs(y) < 34 ? clamp(x, X0, X1) : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "divingboard",
  means: "A diving board over a pool: the further out the pointer stands along it, the deeper the board flexes down; the board goes bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[138, 62], [218, 102], [280, 133], null],
  mount,
});

microwave.code:
/**
 * Microwave: a countertop oven with a hinged door on its front face and a
 * turntable inside. The pointer's place across the figure swings the door
 * open, and the turntable turns with it. At rest the door stands ajar and
 * the start button is lit. The slider is how far the door can swing.
 *
 * The pattern: one part turning on a hinge (a continuous spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, poly, prism, proj, rad, rings, ringAt, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 112, D = 70, H = 62, DW = 80, DT = 3, REST = 22;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.72);
  const far = [DW * Math.cos(rad(110)), D + DW * Math.sin(rad(110))];
  fit(C, [[0, 0, 0], [W, 0, H], [W, D, 0], [0, D, H], [far[0], far[1], 4], [far[0], far[1], H - 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 7, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the cavity opening on the front face, and the turntable inside it
  const face = (x0, x1, z0, z1) => [P(x0, D, z0), P(x1, D, z0), P(x1, D, z1), P(x0, D, z1)];
  mk("path", { d: poly(face(6, DW - 4, 9, H - 8)), class: "lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(40, D - 20, 17), 10)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(40, D - 20, 5, 20), 10)), class: "nf lo" }, g);
  const roller = mk("circle", { r: 2.2, class: "dot m" }, g);
  // the control strip, its keypad dots, and the start button
  mk("path", { d: poly(face(DW + 6, W - 6, 8, H - 8)), class: "nf lo" }, g);
  for (let r = 0; r < 3; r++) for (let c = 0; c < 2; c++) {
    const [sx, sy] = P(DW + 13 + c * 10, D, H - 18 - r * 9);
    mk("circle", { cx: sx, cy: sy, r: 1.6, class: "dot off" }, g);
  }
  const [bx, by] = P(DW + 18, D, 16);
  const start = mk("circle", { cx: bx, cy: by, r: 3, class: "dot" }, g);
  // the door: a thin plate on a hinge at x 0, with its window and handle
  const door = mk("path", { class: "sil" }, g), win = mk("path", { class: "nf lo" }, g), handle = mk("path", { class: "nf" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (u, w, z) => P(u * c - w * s, D + u * s + w * c, z);
    const pts = [];
    for (const u of [0, DW]) for (const w of [0, DT]) for (const z of [4, H - 4]) pts.push(at(u, w, z));
    door.setAttribute("d", poly(hull(pts)));
    win.setAttribute("d", poly([at(8, DT, 11), at(DW - 16, DT, 11), at(DW - 16, DT, H - 11), at(8, DT, H - 11)]));
    handle.setAttribute("d", poly([at(DW - 9, DT, 14), at(DW - 5, DT, 14), at(DW - 5, DT, H - 14), at(DW - 9, DT, H - 14)]));
    const t = rad(a * 2.4);
    const [rx, ry] = P(40 + 13 * Math.cos(t), D - 20 + 13 * Math.sin(t), 10);
    roller.setAttribute("cx", rx); roller.setAttribute("cy", ry);
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const xL = P(0, D, 0)[0] - 40, xR = P(W, 0, 0)[0];
  function move([sx, sy]) {
    if (sy < 20 || sy > 300) return leave();
    const f = clamp((xR - sx) / (xR - xL), 0, 1);
    sp.t = lerp(4, maxA, f);
    door.classList.add("hi"); start.setAttribute("class", "dot m");
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() {
    sp.t = REST;
    door.classList.remove("hi"); start.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "microwave",
  means: "A microwave whose door swings open as the pointer moves across it, the turntable inside turning along with it.",
  rules: [1, 3, 5, 8],
  range: [60, 105, 110],
  tour: [[300, 160], [200, 158], [103, 146], null],
  mount,
});

bathmirror.code:
/**
 * Mirror cabinet: a bathroom wall cabinet whose front is a mirror door,
 * hinged on its right edge, over two shelves of bottles. The pointer's
 * place across the figure swings the mirror open. At rest the door stands
 * a little ajar and the lamp over it is lit. The slider is how far it swings.
 *
 * The pattern: one part turning on a hinge (a continuous spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 96, D = 30, H = 104, Z0 = 26, DT = 3, REST = 18;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const BOTTLES = [[16, 5, 22, 0], [30, 4, 16, 0], [44, 5, 26, 0], [22, 4, 18, 1], [40, 6, 14, 1], [64, 4, 20, 1]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.32);
  const far = [W - W * Math.cos(rad(110)), D + W * Math.sin(rad(110))];
  fit(C, [[-14, -6, 0], [-14, -6, Z0 + H + 22], [W + 14, -6, 0], [W + 14, -6, Z0 + H + 22], [W, D, Z0], [0, D, Z0], [W, D, Z0 + H], [far[0], far[1], Z0 + 2], [far[0], far[1], Z0 + H - 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the wall tile it hangs on, then the cabinet and its lamp
  const [wr, wi] = rings(-14, -6, W + 14, -2, 2, 0.8);
  put(solid(g), prism(P, front, wr, wi, 0, Z0 + H + 22));
  const [br, bi] = rings(0, -2, W, D, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, Z0, Z0 + H));
  const [lr, li] = rings(W / 2 - 22, 0, W / 2 + 22, 8, 3, 1);
  put(solid(g), prism(P, front, lr, li, Z0 + H + 6, Z0 + H + 12));
  const lp = P(W / 2 + 14, 8, Z0 + H + 9);
  const lamp = mk("circle", { cx: lp[0], cy: lp[1], r: 2.6, class: "dot" }, g);
  const face = (x0, x1, z0, z1) => [P(x0, D, z0), P(x1, D, z0), P(x1, D, z1), P(x0, D, z1)];
  mk("path", { d: poly(face(5, W - 5, Z0 + 5, Z0 + H - 5)), class: "lo" }, g);
  // two shelves with bottles standing near their front edge
  for (const s of [0, 1]) {
    const zs = Z0 + 6 + s * 48;
    mk("path", { d: open([P(5, D, zs), P(W - 5, D, zs)]), class: "nf lo" }, g);
    for (const [x, r, h, row] of BOTTLES) if (row === s) put(solid(g), prism(P, front, disc(x, D - 8, r), disc(x, D - 8, r - 1.4), zs, zs + h));
  }
  const door = mk("path", { class: "sil" }, g), glint = mk("path", { class: "nf lo" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (u, w, z) => P(W - u * c - w * s, D + u * s - w * c + DT, z);
    const pts = [];
    for (const u of [0, W]) for (const w of [0, DT]) for (const z of [Z0 + 1, Z0 + H - 1]) pts.push(at(u, w, z));
    door.setAttribute("d", poly(hull(pts)));
    const zm = Z0 + H / 2;
    glint.setAttribute("d", open([at(W - 26, 0, zm + 18), at(W - 10, 0, zm + 34)]) + " " + open([at(W - 34, 0, zm + 16), at(W - 14, 0, zm + 36)]));
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const xL = P(0, D, 0)[0] - 30, xR = P(W, 0, 0)[0] + 20;
  function move([sx, sy]) {
    if (sy < 10 || sy > 310) return leave();
    sp.t = lerp(4, maxA, clamp((xR - sx) / (xR - xL), 0, 1));
    door.classList.add("hi"); lamp.setAttribute("class", "dot m");
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() {
    sp.t = REST;
    door.classList.remove("hi"); lamp.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "bathmirror",
  means: "A bathroom mirror cabinet whose mirror door swings open on its hinge as the pointer moves across, showing the shelves of bottles.",
  rules: [1, 3, 5, 8],
  range: [60, 105, 110],
