dishwasher.code:
/**
 * Dishwasher: a tall cabinet whose front door hinges at its foot. The
 * pointer's height over the figure tips the door down, and once it lies
 * low the lower rack, with its standing plates, rolls out over it. At rest
 * the door stands ajar and the panel light is on. The slider is how far
 * the door can fall.
 *
 * The pattern: one part tilting on a hinge (a continuous spring).
 */
const {
  Cam, clamp, fit, hull, lerp, open, poly, prism, proj, rad, rings, spring, stepS, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 80, D = 72, H = 96, DH = 80, DT = 3, REST = 16, RZ = 26;
const PLATES = [[-26, 12], [-19, 11], [-12, 12], [-5, 10]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[0, 0, 0], [W, 0, H], [W, D, 0], [0, D, H], [0, D + DH + 4, 0], [W, D + DH + 4, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 6, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const face = (x0, x1, z0, z1) => [P(x0, D, z0), P(x1, D, z0), P(x1, D, z1), P(x0, D, z1)];
  mk("path", { d: poly(face(6, W - 6, 8, DH)), class: "lo" }, g);
  mk("path", { d: poly(face(6, W - 6, DH + 4, H - 4)), class: "nf lo" }, g);
  const lamp = P(W - 14, D, DH + 8);
  const dot = mk("circle", { cx: lamp[0], cy: lamp[1], r: 2.6, class: "dot" }, g);
  // the rack and its plates: only the part already out of the cavity is drawn
  const rack = mk("g", {}, g);
  const rb = mk("path", { class: "nf lo" }, rack), plates = PLATES.map(() => mk("path", {}, rack)), rt = mk("path", { class: "nf" }, rack);
  const door = mk("path", { class: "sil" }, g), handle = mk("path", { class: "nf lo" }, g);

  const sp = spring(REST);
  let last = NaN, layLast = null;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (x, v, w) => P(x, D + v * s + w * c, 4 + v * c - w * s);
    const pts = [];
    for (const x of [3, W - 3]) for (const v of [0, DH]) for (const w of [0, DT]) pts.push(at(x, v, w));
    door.setAttribute("d", poly(hull(pts)));
    handle.setAttribute("d", a > 51 ? "" : poly([at(20, DH - 8, DT), at(W - 20, DH - 8, DT), at(W - 20, DH - 4, DT), at(20, DH - 4, DT)]));
    const o = clamp((a - 48) / 40, 0, 1) * 46, y0 = Math.max(D, D - 34 + o), y1 = D - 2 + o;
    const show = y1 - y0 >= 2;
    const rect = (z) => [P(9, y0, z), P(W - 9, y0, z), P(W - 9, y1, z), P(9, y1, z)];
    rb.setAttribute("d", poly(rect(RZ)) + " " + PLATES.map(([dy]) => open([P(9, y1 + dy, RZ), P(W - 9, y1 + dy, RZ)])).join(" "));
    rt.setAttribute("d", poly(rect(RZ + 10)) + " " + [9, W - 9].map((x) => open([P(x, y0, RZ), P(x, y0, RZ + 10)]) + " " + open([P(x, y1, RZ), P(x, y1, RZ + 10)])).join(" "));
    PLATES.forEach(([dy, r], i) => {
      const ring = [];
      for (let k = 0; k < 28; k++) { const t = (k / 28) * Math.PI * 2; ring.push(P(W / 2 + r * Math.cos(t), y1 + dy, RZ + 1 + r + r * Math.sin(t))); }
      plates[i].setAttribute("d", show && y1 + dy >= y0 ? poly(ring) : "");
    });
    if (!show) { rb.setAttribute("d", ""); rt.setAttribute("d", ""); }
    // the rack sits in front of the door's plane once the door is past ~52°
    const lay = a > 52;
    if (lay !== layLast) { layLast = lay; if (lay) rack.before(door); else rack.after(door); door.after(handle); }
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const yT = P(W, 0, H)[1], yB = P(0, D + DH, 0)[1];
  function move([sx, sy]) {
    if (sx < 30 || sx > 370) return leave();
    sp.t = lerp(4, maxA, clamp((sy - yT) / (yB - yT), 0, 1));
    door.classList.add("hi"); dot.setAttribute("class", "dot m");
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() {
    sp.t = REST;
    door.classList.remove("hi"); dot.setAttribute("class", "dot");
    read.textContent = "rest";
    B.wake();
  }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "dishwasher",
  means: "A dishwasher whose door tips down as the pointer moves lower, the plate rack rolling out over it once it lies open.",
  rules: [1, 3, 5, 6],
  range: [60, 90, 90],
  tour: [[325, 64], [206, 154], [124, 247], null],
  mount,
});

globe2.code:
/**
 * Map roll: a wall map in its roller case, pulled down by its bottom rod. The
 * pointer's height on the sheet's plane is how far the map comes down; the
 * sheet slides on one spring and its fold lines appear as it unrolls. At rest
 * it hangs half down, the rod bright.
 *
 * The pattern: a continuous slide (one spring on a length); the hit is the
 * sheet's own plane, which never moves.
 */
const {
  Cam, fit, proj, poly, open, hull, fillet, clamp, spring, stepS,
  disposer, flatDot, mk, place, pointer, register,
} = HL;

const X0 = -46, X1 = 46, TOP = 96, R = 6, Y = 0, LMIN = 12, LMAX = 84, REST = 50;
const FOLDS = [16, 32, 48, 64, 80];
const COAST = [[-30, 20], [-14, 14], [-6, 26], [-18, 38], [-32, 34]];
const ISLE = [[8, 40], [26, 30], [34, 46], [20, 62], [10, 56]];

function mount({ stage, svg, read }) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[X0 - 4, Y, TOP + R + 3], [X1 + 4, Y, TOP + R + 3], [X0, Y, TOP - LMAX - 4], [X1, Y, TOP - LMAX - 4]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const Pw = (x, z) => P(x, Y + R - 1, z);
  const sheet = mk("path", { class: "sil", d: "" }, g);
  const art = mk("path", { class: "nf lo", d: "" }, g);
  const folds = mk("path", { class: "nf dash", d: "" }, g);
  const rod = mk("path", { class: "sil hi", d: "" }, g);
  const ring = flatDot(g, C, 1.8, "dot");
  // the roller case: a horizontal round bar, hull of its two end circles, then its end caps
  const end = (x, r) => Array.from({ length: 24 }, (_, i) => { const a = (i / 24) * Math.PI * 2; return P(x, Y + r * Math.cos(a), TOP + 2 + r * Math.sin(a)); });
  mk("path", { class: "sil", d: poly(hull(end(X0 - 3, R).concat(end(X1 + 3, R)))) }, g);
  mk("path", { class: "nf lo", d: poly(end(X1 + 3, R)) + poly(end(X1 + 3, R - 2.4)) }, g);
  mk("path", { class: "nf lo", d: open([P(X0 - 1, Y + R * 0.7, TOP + 2 - R * 0.7), P(X1 + 1, Y + R * 0.7, TOP + 2 - R * 0.7)]) }, g);

  const o = Pw(0, 0), ex = Pw(1, 0), ez = Pw(0, 1);
  const a = ex[0] - o[0], b = ez[0] - o[0], c = ex[1] - o[1], d = ez[1] - o[1], det = a * d - b * c;
  const onSheet = (sx, sy) => { const u = sx - o[0], v = sy - o[1]; return [(d * u - b * v) / det, (a * v - c * u) / det]; };

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const len = sp.x;
    if (Math.abs(len - drawn) < 1e-3) return;
    drawn = len;
    const zb = TOP - len;
    sheet.setAttribute("d", poly(fillet([[X0, TOP], [X1, TOP], [X1, zb], [X0, zb]], [0.5, 0.5, 2, 2]).map(([x, z]) => Pw(x, z))));
    const vis = (pts) => pts.every(([, z]) => z < len - 3) ? poly(fillet(pts, pts.map(() => 4)).map(([x, z]) => Pw(x, TOP - z))) : "";
    art.setAttribute("d", vis(COAST) + vis(ISLE));
    folds.setAttribute("d", FOLDS.filter((f) => f < len - 2).map((f) => open([Pw(X0 + 3, TOP - f), Pw(X1 - 3, TOP - f)])).join(""));
    rod.setAttribute("d", poly(fillet([[X0 - 3, zb + 1.6], [X1 + 3, zb + 1.6], [X1 + 3, zb - 1.6], [X0 - 3, zb - 1.6]], [1.2, 1.2, 1.2, 1.2]).map(([x, z]) => P(x, Y + R, z))));
    place(ring, P(0, Y + R, zb - 5));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function pull(z) {
    sp.t = z == null ? REST : clamp(TOP - z, LMIN, LMAX);
    read.textContent = z == null ? "rest" : Math.round((sp.t / LMAX) * 100) + "%";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (s) => {
      const [x, z] = onSheet(s[0], s[1]);
      pull(x < X0 - 16 || x > X1 + 16 || z > TOP + 12 || z < TOP - LMAX - 16 ? null : z);
    },
    leave: () => pull(null),
  }));
  bag.add(() => svg.replaceChildren());
  pull(null);
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "globe2",
  means: "A pull-down wall map in its roller case: the map unrolls to the pointer's height, its fold lines showing as it comes down.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[233, 259], [135, 62], [265, 227], null],
  mount,
});

lockerkey.code:
/**
 * Book stand: a reading stand on its base, an open book resting on the tilted
 * board against the front lip, a strut behind. The pointer's height sets the
 * board's tilt: up raises it toward upright, down lays it back. At rest it
 * stands at a reading angle, the book bright.
 *
 * The pattern: a continuous tilt (one spring on an angle); the hit is the
 * pointer's screen height over a stand that never moves its base.
 */
const {
  Cam, fit, proj, prism, rings, facing, poly, open, hull, fillet, clamp, lerp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HW = 30, YH = 10, ZH = 5, L = 52, TMIN = rad(18), TMAX = rad(80), REST = rad(52);

function mount({ stage, svg, read }) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  const ext = [[-HW - 6, -40, 0], [HW + 6, YH + 8, 0], [-HW, YH - L * Math.cos(TMAX), ZH + L], [HW, YH - L * Math.cos(TMIN), ZH + L * Math.sin(TMIN)]];
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ring, inner] = rings(-HW - 6, -36, HW + 6, YH + 6, 5, 1.6);
  put(solid(g), prism(P, front, ring, inner, 0, ZH));
  const strut = mk("path", { class: "nf sil", d: "" }, g);
  const board = mk("path", { class: "sil", d: "" }, g);
  const boardIn = mk("path", { class: "nf lo", d: "" }, g);
  const book = mk("path", { class: "sil hi", d: "" }, g);
  const lines = mk("path", { class: "nf lo", d: "" }, g);
  const lip = mk("path", { class: "sil", d: "" }, g);

  // a point on the board: x across, h up its face, n off its face
  const on = (t, x, h, n) => P(x, YH - h * Math.cos(t) + n * Math.sin(t), ZH + h * Math.sin(t) + n * Math.cos(t));
  const quad = (t, x0, h0, x1, h1, n, r) => fillet([[x0, h0], [x1, h0], [x1, h1], [x0, h1]], [r, r, r, r]).map(([x, h]) => on(t, x, h, n));
  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const top = on(t, 0, L * 0.7, -1.5), foot = P(0, YH - L * 0.9, 0.5);
    strut.setAttribute("d", open([P(-14, YH - L * 0.9, ZH), on(t, -14, L * 0.62, -1.5)]) + open([P(14, YH - L * 0.9, ZH), on(t, 14, L * 0.62, -1.5)]) + open([top, foot]));
    board.setAttribute("d", poly(hull(quad(t, -HW, 0, HW, L, -2, 3).concat(quad(t, -HW, 0, HW, L, 0, 3)))));
    boardIn.setAttribute("d", poly(quad(t, -HW + 2, 2, HW - 2, L - 2, 0, 2)));
    const lp = quad(t, -HW, -1, HW, 1, 0, 0.8).concat(quad(t, -HW, -1, HW, 1, 6, 0.8));
    lip.setAttribute("d", poly(hull(lp)));
    const pg = (x0, x1, lift) => [[x0, 2], [x1, 2], [x1, 40], [x0, 40]].map(([x, h]) => on(t, x, h, 0.6 + lift * (1 - Math.abs(x) / 24)));
    book.setAttribute("d", poly(hull(pg(-24, 0, 3).concat(pg(0, 24, 3)))));
    let d = open([on(t, 0, 2, 0.6), on(t, 0, 40, 0.6)]);
    for (let k = 0; k < 6; k++) {
      const h = 8 + k * 5.2;
      d += open([on(t, -21, h, 1.8), on(t, -4, h, 3.2)]) + open([on(t, 4, h, 3.2), on(t, k === 5 ? 12 : 21, h, k === 5 ? 2.2 : 1.8)]);
    }
    lines.setAttribute("d", d);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function tilt(sy) {
    sp.t = sy == null ? REST : clamp(lerp(TMAX, TMIN, (sy - 70) / 180), TMIN, TMAX);
    read.textContent = sy == null ? "rest" : Math.round((sp.t * 180) / Math.PI) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => tilt(p[0] < 60 || p[0] > 340 ? null : p[1]),
    leave: () => tilt(null),
  }));
  bag.add(() => svg.replaceChildren());
  tilt(null);
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "lockerkey",
  means: "A book stand holding an open book: the board tilts with the pointer's height, up toward upright, down laid back.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[148, 90], [95, 150], [272, 189], null],
  mount,
});

ventilator.code:
/**
 * Wheel stretcher: a trolley on four casters, a deck, a foot mattress and a
 * hinged back section. The pointer along the trolley is how far the back is
 * raised: toward the head end it tilts up on a spring, toward the foot it lies
 * flat. At rest the back sits a little raised and is the one bright part.
 * The slider is how quickly the back follows.
 *
 * The pattern: a continuous value on one angle; the hit is the floor plane.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, run, unproj,
  spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const ZD = 34, BL = 50, MAXT = 1.2, REST = 0.32;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-54, -22, 0], [54, 22, 0], [54, -22, 0], [-54, 22, 0], [-54, -20, ZD + 6], [-BL * Math.cos(MAXT) - 5, 20, ZD + 6 + BL * Math.sin(MAXT)], [-BL * Math.cos(MAXT) - 5, -20, ZD + 6 + BL * Math.sin(MAXT)]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  for (const [x, y] of [[-46, -14], [46, -14], [-46, 14], [46, 14]]) {
    place(flatDot(g, C, 1.6, "dot off"), P(x, y, 0));
    const [r, i] = rings(x - 3, y - 2.5, x + 3, y + 2.5, 2.4, 0.8);
    put(solid(g), prism(P, front, r, i, 0.8, 5));
    const [pr] = rings(x - 1.6, y - 1.6, x + 1.6, y + 1.6, 1.5, 0.5);
    put(solid(g), prism(P, front, pr, null, 5, ZD - 4));
  }
  const [dr, di] = rings(-52, -20, 52, 20, 5, 1.6);
  put(solid(g), prism(P, front, dr, di, ZD - 4, ZD));
  const back = solid(g);
  const [fr, fi] = rings(1, -18, 50, 18, 5, 1.6);
  put(solid(g), prism(P, front, fr, fi, ZD, ZD + 6));

  // the back section, in its own (u along the back from the hinge, v across) frame
  const RING = rrect(0, -18, BL, 18, 5, 4), INNER = rrect(1.6, -16.4, BL - 1.6, 16.4, 3.4, 4);
  const at = (q, w, th) => {
    const c = Math.cos(th), s = Math.sin(th);
    return P(-q.u * c + w * s, q.v, ZD + q.u * s + w * c);
  };
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const th = sp.x;
    if (Math.abs(th - drawn) < 1e-4) return;
    drawn = th;
    const pts = RING.map((q) => at(q, 0, th)).concat(RING.map((q) => at(q, 6, th)));
    back.sil.setAttribute("d", poly(hull(pts)));
    const face = (q) => ({ ...q, nu: -q.nu * Math.cos(th), nv: q.nv });
    const keep = INNER.map(face).filter(front).length ? run(INNER.map(face), front) : [];
    back.cr.setAttribute("d", keep.length ? open(keep.map((q) => at(q, 6, th))) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    sp.t = over === null ? REST : clamp((20 - over) / 70, 0, 1) * MAXT;
    back.sil.classList.add("hi");
    read.textContent = over === null ? "rest" : Math.round((sp.t * 180) / Math.PI) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = Math.abs(x) > 80 || Math.abs(y) > 60 ? null : x;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "ventilator",
  means: "A wheeled stretcher: the hinged back section tilts up as the pointer moves toward the head end, and lies flat at the foot.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[258, 260], [186, 224], [128, 195], null],
  mount,
});

dentalmirror.code:
/**
 * Dental lamp: a weighted foot, a tall column, and a long swing arm with the
 * lamp head hanging at its end. The pointer is where the patient sits: the arm
 * swings round the column on a spring and the head turns to face it, bright.
 * At rest the arm stands half out over the chair and the foot's rim is lit.
 * The slider is how quickly the arm follows.
 *
 * The pattern: a continuous aim on one angle; the hit is the floor plane.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZT = 92, AL = 64, REST = -0.35;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.2);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([(AL + 8) * Math.cos(a), (AL + 8) * Math.sin(a), ZT + 6], [(AL + 8) * Math.cos(a), (AL + 8) * Math.sin(a), ZT - 35], [22 * Math.cos(a), 22 * Math.sin(a), 0]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const foot = solid(g);
  put(foot, prism(P, front, circ(22, 48), circ(20.4, 48), 0, 5));
  put(solid(g), prism(P, front, circ(9, 32), circ(7.8, 32), 5, 9));
  const post = mk("g", {}, g);
  put(solid(post), prism(P, front, circ(3.6, 24), null, 9, ZT));
  put(solid(post), prism(P, front, circ(5.5, 24), circ(4.5, 24), ZT - 2, ZT + 5));

  // local footprints along +x: the arm, the drop neck, the yoke, the lamp head
  const ARM = rings(0, -3, AL, 3, 2.5, 1);
  const NECK = rings(AL - 3, -1.8, AL + 0.6, 1.8, 1.2, 0.5);
  const YOKE = rings(AL - 6, -15, AL + 4, 15, 4, 1.2);
  const HEAD = rings(AL - 14, -13, AL + 6, 13, 8, 1.6);
  const swing = mk("g", {}, g);
  const head = solid(swing), yoke = solid(swing), neck = solid(swing), arm = solid(swing);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, first = null;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const T = (r) => turn(r, a);
    put(head, prism(P, front, T(HEAD[0]), T(HEAD[1]), ZT - 34, ZT - 22));
    put(yoke, prism(P, front, T(YOKE[0]), T(YOKE[1]), ZT - 22, ZT - 19));
    put(neck, prism(P, front, T(NECK[0]), null, ZT - 19, ZT));
    put(arm, prism(P, front, T(ARM[0]), T(ARM[1]), ZT, ZT + 4));
    const behind = Math.cos(a) + Math.sin(a) < 0;
    if (behind !== first) {
      first = behind;
      if (behind) post.before(swing); else post.after(swing);
    }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    const aim = over ? Math.atan2(over[1], over[0]) : REST;
    sp.t = sp.t + wrap(aim - sp.t);
    head.sil.classList.toggle("hi", !!over);
    foot.sil.classList.toggle("hi", !over);
    read.textContent = over ? Math.round(((aim * 180) / Math.PI + 360) % 360) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r < 8 || r > AL + 60 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "dentalmirror",
  means: "A dental lamp on a column: the long arm swings round to the pointer and the lamp head turns to face it, bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[340, 309], [200, 224], [76, 270], null],
  mount,
});

wheelchair2.code:
/**
 * Commode chair: four legs, a seat with its pan opening, a backrest, two arm
 * rails, and a hinged lid over the seat. The pointer near the chair lifts the
 * lid on a spring, more the closer it comes; away it settles back. At rest the
 * lid stands slightly ajar and is the one bright part.
 * The slider is how quickly the lid follows.
 *
 * The pattern: a continuous value on one angle; the hit is the floor plane.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, run, unproj,
  spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const ZS = 26, LL = 31.5, MAXT = 1.5, REST = 0.1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-20, -20, 0], [20, 20, 0], [20, -20, 0], [-20, 20, 0], [-20, -20, 58], [-20, 20, 58], [18, -18, 48], [18, 18, 48]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  for (const [x, y] of [[-15, -15], [15, -15], [-15, 15], [15, 15]]) {
    place(flatDot(g, C, 1.2, "dot off"), P(x, y, 0));
    const [r] = rings(x - 1.6, y - 1.6, x + 1.6, y + 1.6, 1.5, 0.5);
    put(solid(g), prism(P, front, r, null, 0, ZS));
  }
  const [br, bi] = rings(-19, -17, -16, 17, 1.4, 0.6);
  put(solid(g), prism(P, front, br, bi, ZS, ZS + 30));
  const [sr, si] = rings(-17, -17, 17, 17, 4, 1.4);
  put(solid(g), prism(P, front, sr, si, ZS - 3, ZS));
  mk("path", { class: "nf lo", d: poly(circ(9, 32).map((q) => P(q.u + 1, q.v, ZS))) }, g);
  const arm = (y0, y1) => {
    const [pr] = rings(11, y0 + 0.5, 14, y1 - 0.5, 1.2, 0.5);
    put(solid(g), prism(P, front, pr, null, ZS, ZS + 16));
    const [ar, ai] = rings(-16, y0, 16, y1, 1.6, 0.7);
    put(solid(g), prism(P, front, ar, ai, ZS + 16, ZS + 19));
  };
  arm(-18, -14.5);
  const lid = solid(g);
  arm(14.5, 18);

  const RING = rrect(0, -14, LL, 14, 6, 4), INNER = rrect(1.4, -12.6, LL - 1.4, 12.6, 4.6, 4);
  const at = (q, w, th) => {
    const c = Math.cos(th), s = Math.sin(th);
    return P(-14 + q.u * c - w * s, q.v, ZS + q.u * s + w * c);
  };
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const th = sp.x;
    if (Math.abs(th - drawn) < 1e-4) return;
    drawn = th;
    lid.sil.setAttribute("d", poly(hull(RING.map((q) => at(q, 0, th)).concat(RING.map((q) => at(q, 4.2, th))))));
    const face = INNER.map((q) => ({ ...q, nu: q.nu * Math.cos(th) }));
    lid.cr.setAttribute("d", face.some(front) ? open(run(face, front).map((q) => at(q, 4.2, th))) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    sp.t = over === null ? REST : clamp(1.25 - over / 40, 0, 1) * MAXT;
    lid.sil.classList.add("hi");
    read.textContent = over === null ? "rest" : Math.round((sp.t * 180) / Math.PI) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r > 70 ? null : r;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "wheelchair2",
  means: "A bedside commode chair: its hinged lid swings up as the pointer comes near, and settles back ajar as it leaves.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[58, 249], [222, 277], [211, 249], null],
  mount,
});

cashbox.code:
/**
 * Cash box: a metal box with a hinged lid and a coin tray of four wells.
 * When the pointer is over the box the lid swings open on its back hinge and
 * the coin stack in the well under the pointer rises, bright. At rest the
 * lid stands a little ajar, bright. The slider is the delay before it opens.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rad, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 92, Y1 = 54, H = 26, T = 4, W = 3, FL = H - 17, REST = 16, OPEN = 104;
const HS = [5, 9, 4, 7];
const disc = (x, y, r, n = 22) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let delay = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [0, -14, H + Y1 + 2], [X1, -14, H + Y1 + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the well: tray floor, dividers and coin stacks, painted before the body that frames them
  const well = mk("g", {}, g);
  const fl = rrect(W, W, X1 - W, Y1 - W, 3, 4);
  mk("path", { class: "lo", d: poly(ringAt(P, fl, FL)) }, well);
  const cw = (X1 - 2 * W) / 4;
  let dv = "";
  for (let k = 1; k < 4; k++) { const x = W + k * cw; dv += seg(P(x, W, FL), P(x, Y1 - W, FL)) + seg(P(x, W, FL), P(x, W, FL + 12)); }
  mk("path", { class: "nf lo", d: dv }, well);
  const stacks = HS.map((h, k) => {
    const s = solid(well), x = W + (k + 0.5) * cw, y = Y1 / 2 + (k % 2 ? 4 : -3);
    return { s, x, y, h, z: tween(h), last: NaN };
  });

  // the body, with the opening cut through its top
  const [br, bi] = rings(0, 0, X1, Y1, 4, 1.4);
  const bp = prism(P, front, br, bi, 0, H);
  mk("path", { class: "sil", "fill-rule": "evenodd", d: bp.sil + " " + poly(ringAt(P, rrect(W, W, X1 - W, Y1 - W, 3, 4), H)) }, g);
  mk("path", { class: "nf lo", d: seg(P(X1 / 2 - 6, Y1, H - 6), P(X1 / 2 + 6, Y1, H - 6)) }, g);

  // the lid, turning about its back edge
  const lidG = mk("g", {}, g), lid = solid(lidG);
  const lo = rrect(0, 0, X1, Y1, 4, 4), li = rrect(2, 2, X1 - 2, Y1 - 2, 3, 4);
  const L = (q, d, a) => P(q.u, q.v * Math.cos(a) - d * Math.sin(a), H + 0.4 + q.v * Math.sin(a) + d * Math.cos(a));
  const ang = tween(REST);
  let lastA = NaN;

  function drawLid(deg) {
    if (deg === lastA) return;
    lastA = deg;
    const a = rad(deg), face = deg < 39 ? T : 0;
    lid.sil.setAttribute("d", poly(hull(lo.map((q) => L(q, 0, a)).concat(lo.map((q) => L(q, T, a))))));
    lid.cr.setAttribute("d", poly(li.map((q) => L(q, face, a))));
    lid.cr.setAttribute("class", "nf lo");
  }
  function drawStack(st, h) {
    if (h === st.last) return;
    st.last = h;
    put(st.s, prism(P, front, disc(st.x, st.y, 6.5), disc(st.x, st.y, 5), FL, FL + h));
  }

  const B = register(stage, (_dt, now) => {
    drawLid(tval(ang, now));
    let moving = !tdone(ang, now);
    for (const st of stacks) { drawStack(st, tval(st.z, now)); if (!tdone(st.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = stacks.map((st) => P(st.x, st.y, H)[0]);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < -10 || x > X1 + 10 || y < -40 || y > Y1 + 10) return -1;
    let best = 0;
    mids.forEach((m, k) => { if (Math.abs(m - sx) < Math.abs(mids[best] - sx)) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), was = act;
    act = a;
    tset(ang, a < 0 ? REST : OPEN, now, a >= 0 && was < 0 ? delay : 0);
    stacks.forEach((st, k) => {
      tset(st.z, k === a ? 15 : st.h, now, a >= 0 ? Math.abs(k - a) * 40 : 0);
      st.s.sil.classList.toggle("hi", k === a);
    });
    lid.sil.classList.toggle("hi", a < 0);
    read.textContent = a < 0 ? "rest" : "well " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { delay = v; }, destroy: bag.dispose };
}

hairline({
  name: "cashbox",
  means: "A cash box with a hinged lid: over it the lid swings open and the coin stack in the well under the pointer rises.",
  rules: [1, 4, 5, 6],
  range: [0, 60, 200],
  tour: [[150, 196], [190, 202], [236, 214], null],
  mount,
});

atmcard.code:
/**
 * Card reader: a flat payment terminal with a screen and a keypad, and a chip
 * card in front of its slot. When the pointer is over the reader the card
 * slides into the slot chip first and the screen takes the bright. At rest
 * the card waits just out of the slot, bright. The slider is how deep it goes.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 42, Y1 = 66, Z1 = 10, SZ = 4.5, CX0 = 7, CX1 = 35, CL = 46, REST = Y1 + 9;
const disc = (x, y, r, n = 14) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let depth = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [X1, 0, 0], [0, REST + CL, 0], [X1, REST + CL, 0], [0, 0, Z1], [X1, 0, Z1]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(0, 0, X1, Y1, 7, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, Z1));
  const screen = mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(6, 6, X1 - 6, 26, 2.5, 4), Z1)) }, g);
  for (let r = 0; r < 4; r++) for (let c = 0; c < 3; c++) {
    const x = 11 + c * 10, y = 33 + r * 7.5;
    mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(x - 3.2, y - 2.2, x + 3.2, y + 2.2, 1.2, 3), Z1)) }, g);
  }
  // the slot on the near end
  mk("path", { class: "nf", d: seg(P(CX0 - 1, Y1, SZ), P(CX1 + 1, Y1, SZ)) }, g);

  // the card: only the part outside the slot is drawn
  const card = solid(g), chip = mk("path", { class: "nf lo" }, g);
  const cy = tween(REST);
  let last = NaN;
  function draw(y0) {
    if (y0 === last) return;
    last = y0;
    const a = Math.max(y0, Y1), b = y0 + CL;
    const ring = rrect(CX0, a, CX1, b, a > y0 ? 0.3 : 2.5, 4), inner = rrect(CX0 + 2, a + (a > y0 ? 0 : 2), CX1 - 2, b - 2, 1.5, 4);
    put(card, { sil: poly(hull(ringAt(P, ring, SZ - 0.5).concat(ringAt(P, ring, SZ + 0.5)))), crease: poly(ringAt(P, inner, SZ + 0.5)) });
    const c0 = y0 + 6, c1 = y0 + 14;
    chip.setAttribute("d", c0 >= Y1 ? poly(ringAt(P, rrect(CX1 - 13, c0, CX1 - 5, c1, 1.4, 3), SZ + 0.5)) + seg(P(CX1 - 9, c0, SZ + 0.5), P(CX1 - 9, c1, SZ + 0.5)) : "");
  }

  const B = register(stage, (_dt, now) => { draw(tval(cy, now)); return !tdone(cy, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, Z1);
    return x > -10 && x < X1 + 10 && y > -10 && y < REST + CL;
  }

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(cy, on ? Y1 - CL * depth : REST, performance.now(), 0);
    card.sil.classList.toggle("hi", !on);
    screen.classList.toggle("hi", on);
    screen.classList.toggle("lo", !on);
    read.textContent = on ? "chip in" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { depth = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "atmcard",
  means: "A card reader with a chip card at its slot: over the reader the card slides in chip first and the screen lights.",
  rules: [1, 4, 5, 6],
  range: [0.3, 0.6, 0.75],
  tour: [[250, 133], [200, 160], [150, 190], null],
  mount,
});

hydrant.code:
/**
 * Fire hydrant: a flanged foot, a barrel, a collar, a domed bonnet with its
 * operating nut, and three outlet nozzles, each closed by a cap. The pointer
 * is the crew arriving: the upper barrel turns on a spring until the big
 * pumper cap faces it. At rest the pumper looks off down the kerb, its cap
 * bright. The slider is how quickly the barrel follows.
 *
 * The pattern: a continuous aim (one spring on an angle); the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 2.4;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
// nozzles: offset angle, half width, reach, z0, z1, cap length
const NOZ = [[0, 5, 18, 13, 24, 4], [Math.PI / 2, 3.4, 14, 15, 22, 3], [-Math.PI / 2, 3.4, 14, 15, 22, 3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 5.2);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([18 * Math.cos(a), 18 * Math.sin(a), 13], [11 * Math.cos(a), 11 * Math.sin(a), 0]); }
  ext.push([0, 0, 48]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const barrel = mk("g", {}, g);
  put(solid(barrel), prism(P, front, circ(10, 40), circ(8.6, 40), 0, 3));
  put(solid(barrel), prism(P, front, circ(7, 36), circ(6, 36), 3, 33));
  put(solid(barrel), prism(P, front, circ(9, 40), circ(7.8, 40), 33, 36));
  put(solid(barrel), prism(P, front, circ(7, 36), circ(5.4, 36), 36, 42));
  put(solid(barrel), prism(P, front, circ(2.6, 6), null, 42, 47));
  const noz = NOZ.map(([o, w, L, z0, z1, cl], i) => {
    const grp = mk("g", {}, g);
    return { o, w, L, z0, z1, cl, grp, body: solid(grp), cap: solid(grp), rb: rings(4, -w, L - cl, w, w * 0.6, 0.6), rc: rings(L - cl, -w - 1, L, w + 1, 1.5, 0.8), behind: null, i };
  });
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    for (const n of noz) {
      const T = (r) => turn(r, a + n.o);
      put(n.body, prism(P, front, T(n.rb[0]), null, n.z0 + 1, n.z1 - 1));
      put(n.cap, prism(P, front, T(n.rc[0]), T(n.rc[1]), n.z0, n.z1));
      const b = Math.cos(a + n.o) + Math.sin(a + n.o) < 0;
      if (b !== n.behind) { n.behind = b; if (b) barrel.before(n.grp); else barrel.after(n.grp); }
    }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    const aim = over ? Math.atan2(over[1], over[0]) : REST;
    sp.t = sp.t + wrap(aim - sp.t);
    noz[0].cap.sil.classList.toggle("hi", true);
    read.textContent = over ? Math.round(((aim * 180) / Math.PI + 360) % 360) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r < 3 || r > 70 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "hydrant",
  means: "A fire hydrant whose upper barrel turns on its post until the big pumper cap faces the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[163, 186], [347, 260], [274, 315], null],
  mount,
});

streetlamp.code:
/**
 * Street lamp: a cast base, a tall post, and a swing arm carrying a lantern.
 * The pointer is where the street needs light: the arm swivels round the post
 * on a spring to hang the lantern over it, and the pool of light on the
 * ground follows. At rest the arm stands askew over the kerb, lantern bright.
 * The slider is how quickly the arm follows.
 *
 * The pattern: a continuous aim (one spring on an angle); the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const TOP = 56, ARM = 30, REST = 2.2;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.5);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([(ARM + 8) * Math.cos(a), (ARM + 8) * Math.sin(a), TOP + 4], [(ARM + 7) * Math.cos(a), (ARM + 7) * Math.sin(a), 0]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const pool = flatDot(g, C, 7, "dot off");
  const arm = mk("g", {}, g);
  const post = mk("g", {}, g);
  put(solid(post), prism(P, front, circ(9, 40), circ(7.6, 40), 0, 3));
  put(solid(post), prism(P, front, circ(5.5, 32), circ(4.4, 32), 3, 12));
  put(solid(post), prism(P, front, circ(2.2, 20), null, 12, TOP));
  put(solid(post), prism(P, front, circ(3.6, 24), circ(2.8, 24), TOP, TOP + 3));
  // arm footprints, pointing +x from the post
  const BAR = rings(2, -1.4, ARM, 1.4, 0.7, 0.4);
  const STRUT = rings(2, -1, ARM * 0.55, 1, 0.5, 0.3);
  const CAP = rings(ARM - 8, -8, ARM + 8, 8, 3, 1.4);
  const LAMP = rings(ARM - 6, -6, ARM + 6, 6, 3.5, 1.4);
  const sBar = solid(arm), sStrut = solid(arm), sLamp = solid(arm), sCap = solid(arm);
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, behind = null;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const T = (r) => turn(r, a);
    put(sStrut, prism(P, front, T(STRUT[0]), null, TOP - 12, TOP - 10));
    put(sBar, prism(P, front, T(BAR[0]), T(BAR[1]), TOP - 1, TOP + 1.5));
    put(sLamp, prism(P, front, T(LAMP[0]), T(LAMP[1]), TOP - 16, TOP - 5));
    put(sCap, prism(P, front, T(CAP[0]), T(CAP[1]), TOP - 5, TOP - 2));
    place(pool, P(ARM * Math.cos(a), ARM * Math.sin(a), 0));
    const b = Math.cos(a) + Math.sin(a) < 0;
    if (b !== behind) { behind = b; if (b) post.before(arm); else post.after(arm); }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    const aim = over ? Math.atan2(over[1], over[0]) : REST;
    sp.t = sp.t + wrap(aim - sp.t);
    sCap.sil.classList.toggle("hi", true);
    pool.setAttribute("class", over ? "dot m" : "dot off");
    const deg = Math.round(((aim * 180) / Math.PI + 360) % 360);
    read.textContent = over ? deg + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r < 4 || r > ARM + 40 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

