vrheadset2.code:
/**
 * Laptop stand: a riser plate hinged at its front lip on a low base, held up
 * by a pair of struts, a closed laptop resting on it. The pointer over the
 * stand tilts the plate up on its hinge; the struts follow. At rest the plate
 * sits at a shallow working angle and its lip is bright. The slider is how
 * steeply it tilts.
 */
const { Cam, facing, fit, prism, proj, rings, rrect, hull, poly, seg, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const X = 30, Y = 22, Z0 = 4, REST = 10, UP = 40;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-X, -Y, 0], [X, Y, 0], [-X, -Y, Z0 + 2 * Y * Math.sin(rad(UP * 1.2)) + 6], [X, -Y, Z0 + 2 * Y * Math.sin(rad(UP * 1.2)) + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let amp = value;

  const BASE = rings(-X, -Y, X, Y, 6, 1.6);
  put(solid(g), prism(P, front, BASE[0], BASE[1], 0, Z0));
  const struts = mk("path", { class: "nf sil" }, g);
  const plate = solid(g), lap = solid(g), lip = mk("path", { class: "nf sil" }, g);
  const PL = rrect(-X, -Y, X, Y, 6, 4), PLI = rrect(-X + 2, -Y + 2, X - 2, Y - 2, 4, 4);
  const LP = rrect(-X + 4, -Y + 3, X - 4, Y - 6, 3, 4), LPI = rrect(-X + 6, -Y + 5, X - 6, Y - 8, 2, 4);
  const at = (u, v, a, t) => {
    const d = Y - v, c = Math.cos(a), s = Math.sin(a);
    return P(u, Y - d * c + t * s, Z0 + d * s + t * c);
  };
  const sp = spring(REST);
  let drawn = NaN;

  function slab(sd, ring, inner, a, t0, t1) {
    const pts = ring.map((q) => at(q.u, q.v, a, t0)).concat(ring.map((q) => at(q.u, q.v, a, t1)));
    sd.sil.setAttribute("d", poly(hull(pts)));
    sd.cr.setAttribute("d", poly(inner.map((q) => at(q.u, q.v, a, t1))));
  }

  function draw() {
    if (sp.x === drawn) return;
    drawn = sp.x;
    const a = rad(sp.x);
    slab(plate, PL, PLI, a, 0, 2);
    slab(lap, LP, LPI, a, 2, 6);
    // the lip that stops the laptop sliding, on the plate's front edge
    lip.setAttribute("d", seg(at(-X + 6, Y - 1, a, 2), at(X - 6, Y - 1, a, 2)) + seg(at(-X + 6, Y - 1, a, 5), at(X - 6, Y - 1, a, 5)));
    // two struts from the base's back to the plate's underside
    let d = "";
    for (const u of [-X + 8, X - 8]) d += seg(P(u, -Y + 10, Z0), at(u, -Y + 4, a, 0));
    struts.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let on = false;
  function apply() {
    sp.t = on ? UP * amp : REST;
    plate.sil.classList.toggle("hi", on);
    lip.classList.toggle("hi", !on);
    read.textContent = on ? Math.round(UP * amp) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      const n = Math.abs(x) < X + 14 && y > -Y - 70 && y < Y + 14;
      if (n !== on) { on = n; apply(); }
    },
    leave: () => { on = false; apply(); },
  }));
  bag.add(() => svg.replaceChildren());
  apply();
  draw();
  return { set: (v) => { amp = v; apply(); }, destroy: bag.dispose };
}

hairline({
  name: "vrheadset2",
  means: "A laptop stand: the pointer tilts the riser plate up on its front hinge, struts following, the laptop riding on it.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[149, 198], [137, 117], [160, 268], null],
  mount,
});

printer2.code:
/**
 * Label printer: a desk label printer, its lid hinged along the back edge
 * over a tape roll, a strip of label tape fed out of the front slot. The
 * pointer over the printer opens the lid on its hinge to show the roll and
 * feeds the tape further out. At rest the lid sits a little ajar and the
 * short tape end is the bright mark. The slider is how far the lid opens.
 */
const { Cam, facing, fit, prism, proj, rings, rrect, hull, poly, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const X = 26, Y = 20, ZT = 22, TH = 3, OPEN = 100, TAPE0 = 5, TAPE1 = 30;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-X, -Y, 0], [X, Y + TAPE1, 0], [-X, -Y - 4, ZT + 2 * Y + 2], [X, -Y - 4, ZT + 2 * Y + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let amp = value;

  const BODY = rings(-X, -Y, X, Y, 7, 1.8);
  put(solid(g), prism(P, front, BODY[0], BODY[1], 0, ZT));
  // the roll in its well, seen when the lid lifts
  const well = rings(-14, -14, 14, 10, 5, 1.2);
  mk("path", { class: "lo nf", d: prism(P, front, well[0], null, ZT, ZT).sil }, g);
  const roll = solid(g);
  const rc = HL.circ(8, 32).map((q) => ({ ...q, u: q.u, v: q.v - 2 }));
  put(roll, prism(P, front, rc, HL.circ(3, 24).map((q) => ({ ...q, v: q.v - 2 })), ZT - 6, ZT - 0.5));
  // the slot on the front face
  mk("path", { class: "lo nf", d: `M${P(-11, Y, 6)}L${P(11, Y, 6)}` }, g);

  const tape = solid(g), lid = solid(g);
  const LID = rrect(-X, -Y, X, Y, 7, 4), LIDI = rrect(-X + 2, -Y + 2, X - 2, Y - 2, 5, 4);
  const at = (q, a, t) => {
    const d = q.v + Y, c = Math.cos(a), s = Math.sin(a);
    return P(q.u, -Y + d * c - t * s, ZT + d * s + t * c);
  };
  const sp = { lid: spring(8), tape: spring(TAPE0) }, drawn = { lid: NaN, tape: NaN };

  function draw() {
    if (sp.lid.x !== drawn.lid) {
      drawn.lid = sp.lid.x;
      const a = rad(sp.lid.x), up = -0.5 * Math.sin(a) + 0.7 * Math.cos(a) > 0;
      const pts = LID.map((q) => at(q, a, 0)).concat(LID.map((q) => at(q, a, TH)));
      lid.sil.setAttribute("d", poly(hull(pts)));
      lid.cr.setAttribute("d", poly(LIDI.map((q) => at(q, a, up ? TH : 0))));
    }
    if (sp.tape.x !== drawn.tape) {
      drawn.tape = sp.tape.x;
      const r = rings(-10, Y - 1, 10, Y + sp.tape.x, 0.8, 0.3);
      put(tape, prism(P, front, r[0], null, 5.4, 6.2));
    }
  }

  const B = register(stage, (dt) => {
    const m = [stepS(sp.lid, dt), stepS(sp.tape, dt)].some(Boolean);
    draw();
    return m;
  });
  bag.add(B.unregister);

  let on = false;
  function apply() {
    sp.lid.t = on ? OPEN * amp : 8;
    sp.tape.t = on ? TAPE1 * Math.min(1, amp) : TAPE0;
    lid.sil.classList.toggle("hi", on);
    tape.sil.classList.toggle("hi", !on);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      const n = Math.abs(x) < X + 16 && y > -Y - 90 && y < Y + TAPE1 + 10;
      if (n !== on) { on = n; apply(); }
    },
    leave: () => { on = false; apply(); },
  }));
  bag.add(() => svg.replaceChildren());
  apply();
  draw();
  return { set: (v) => { amp = v; apply(); }, destroy: bag.dispose };
}

hairline({
  name: "printer2",
  means: "A label printer: the pointer opens its hinged lid over the tape roll and feeds the label tape out of the front slot.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.1],
  tour: [[171, 179], [171, 90], [95, 262], null],
  mount,
});

petfountain.code:
/**
 * Water fountain: a pet drinking fountain, a round bowl with a spout tower
 * in its middle. The spout turns to aim its arc of water at the pointer and
 * throws it as far as the pointer stands, splashing on the water's surface.
 * At rest it arcs toward the viewer, bright. The slider is the longest throw.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 52, ZB = 16, ZW = 12, TR = 11, ZT = 42, W = 3.6, PS = 2.1, RR = 24;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxR = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [0, 0, ZT + 14]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const outer = circ(R, 72);
  put(solid(g), prism(P, front, outer, circ(R - 2, 72), 0, ZB));
  mk("path", { class: "nf", d: poly(ringAt(P, circ(R - 4, 72), ZB)) }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, circ(R - 9, 72), ZW + 0.5)) }, g);
  const splash = mk("path", { class: "nf" }, g), splash2 = mk("path", { class: "nf lo" }, g);
  const tw = mk("g", {}, g);
  put(solid(tw), prism(P, front, circ(TR, 40), circ(TR - 1.5, 40), ZW, ZT));
  put(solid(tw), prism(P, front, circ(TR + 3, 40), circ(TR + 1, 40), ZT, ZT + 3));
  mk("path", { d: poly(hull(ringAt(P, circ(4, 20), ZT + 3).concat(ringAt(P, circ(3, 20), ZT + 8)))) }, tw);
  const sg = mk("g", {}, g);
  const stream = mk("path", { class: "sil hi" }, sg);
  const ang = spring(PS, { k: 80, c: 15 }), dist = spring(RR, { k: 80, c: 15 });
  let lastA = NaN, lastD = NaN, far = null;
  function draw(a, r) {
    if (Math.abs(a - lastA) < 1e-4 && Math.abs(r - lastD) < 1e-3) return;
    lastA = a; lastD = r;
    const cx = Math.cos(a), cy = Math.sin(a), H = ZT + 8 - ZW;
    const at = (t, o) => P((2 + r * t) * cx - o * cy, (2 + r * t) * cy + o * cx, ZT + 6 + 10 * t - (10 + H - 2) * t * t);
    const L = [], Rt = [];
    for (let i = 0; i <= 16; i++) { const t = i / 16; L.push(at(t, -W)); Rt.unshift(at(t, W)); }
    stream.setAttribute("d", poly(L.concat(Rt)));
    const lx = (2 + r) * cx, ly = (2 + r) * cy;
    splash.setAttribute("d", poly(ringAt(P, disc(lx, ly, 5, 24), ZW + 0.5)));
    splash2.setAttribute("d", poly(ringAt(P, disc(lx, ly, 10, 32), ZW + 0.5)));
    const f = cx + cy < 0;
    if (f !== far) { far = f; if (f) g.insertBefore(sg, tw); else tw.after(sg); }
  }
  const B = register(stage, (dt) => { const m1 = stepS(ang, dt), m2 = stepS(dist, dt); draw(ang.x, dist.x); return m1 || m2; });
  bag.add(B.unregister);
  function aim(p) {
    if (!p) { ang.t = PS; dist.t = RR; read.textContent = "rest"; B.wake(); return; }
    const [qx, qy] = unproj(C, p[0], p[1], ZW);
    let t = Math.atan2(qy, qx);
    while (t - ang.x > Math.PI) t -= 2 * Math.PI;
    while (t - ang.x < -Math.PI) t += 2 * Math.PI;
    ang.t = t;
    dist.t = clamp(Math.hypot(qx, qy), 14, maxR);
    read.textContent = Math.round(dist.t) + "cm";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxR = v; }, destroy: bag.dispose };
}

hairline({
  name: "petfountain",
  means: "A pet water fountain: the spout turns to aim its arc of water at the pointer and throws it as far as the pointer stands.",
  rules: [1, 3, 4, 5, 6],
  range: [24, 40, 40],
  tour: [[122, 178], [200, 186], [290, 178], null],
  mount,
});

catcarrier.code:
/**
 * Pet ramp: a low bed with a cleated ramp leaning against its edge. The ramp
 * slides out to put its foot under the pointer on the floor, so it runs from
 * steep to gentle; the cleats follow. At rest it leans steeply, bright. The
 * slider is how far it can reach.
 *
 * The pattern: one part following the pointer along a line (tilt and slide).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 56, BY = 64, BH = 42, Y0 = 16, Y1 = 48, TH = 3, REST = 34;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[0, 0, 0], [BX + 110, Y0, 0], [BX + 110, Y1, 0], [0, BY, 0], [0, 0, BH + 10], [BX, BY, BH + 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, BX, BY, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  const [cr, ci] = rings(5, 5, BX - 5, BY - 5, 10, 2);
  put(solid(g), prism(P, front, cr, ci, BH, BH + 8));
  const lip = mk("path", { class: "nf lo", d: open([P(BX, Y0 - 2, BH - 1), P(BX, Y1 + 2, BH - 1)]) }, g);
  const guide = mk("path", { class: "nf dash" }, g);
  const slab = mk("path", { class: "sil" }, g), top = mk("path", { class: "nf lo" }, g), cleats = mk("path", { class: "nf" }, g);
  const d = spring(REST, { k: 90, c: 16 });
  let last = NaN;
  function draw(r) {
    if (Math.abs(r - last) < 1e-3) return;
    last = r;
    const L = Math.hypot(r, BH), nx = BH / L, nz = r / L;
    const at = (t, y, o) => P(BX + r * t + nx * o, y, BH * (1 - t) + nz * o);
    const pts = [];
    for (const t of [0, 1]) for (const y of [Y0, Y1]) for (const o of [0, TH]) pts.push(at(t, y, o));
    slab.setAttribute("d", poly(hull(pts)));
    top.setAttribute("d", poly([at(0, Y0, TH), at(1, Y0, TH), at(1, Y1, TH), at(0, Y1, TH)]));
    let c = "";
    const n = Math.max(2, Math.round(L / 11));
    for (let i = 1; i < n; i++) { const t = i / n; c += seg(at(t, Y0 + 2, TH + 1.6), at(t, Y1 - 2, TH + 1.6)) + seg(at(t, Y0 + 2, TH), at(t, Y0 + 2, TH + 1.6)); }
    cleats.setAttribute("d", c);
    guide.setAttribute("d", open([P(BX, Y1, 0), P(BX + r, Y1, 0)]));
  }
  const B = register(stage, (dt) => { const m = stepS(d, dt); draw(d.x); return m; });
  bag.add(B.unregister);
  const deg = (r) => Math.round((Math.atan2(BH, r) * 180) / Math.PI) + "°";
  function aim(p) {
    if (!p) { d.t = REST; slab.classList.add("hi"); read.textContent = "rest"; B.wake(); return; }
    const [qx] = unproj(C, p[0], p[1], 0);
    d.t = clamp(qx - BX, 24, reach);
    read.textContent = deg(d.t);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

