  name: "camper",
  means: "A camper van with a pop-top roof: the pointer's place along the van tilts the roof open on its rear hinge, over a pleated canvas wall.",
  rules: [1, 3, 5, 8],
  range: [14, 20, 26],
  tour: [[264, 203], [199, 135], [120, 163], null],
  mount,
});

tentdome.code:
/**
 * Dome tent: a dome on a groundsheet, two poles crossing over its crown,
 * an arched door on the side facing us. The nearer the pointer comes to
 * the door, the further the door unzips: the flap rolls down from the top
 * of the arch to a roll at the sill. At rest it is barely unzipped, bright.
 * The slider is how far the flap may roll down.
 *
 * The pattern: one part opening with distance (continuous).
 */
const {
  Cam, clamp, fit, hull, open, poly, prism, proj, rad, rings, spring, stepS, unproj, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 52, H = 46, SPAN = 40, TOP = 66, REST = 0.12;
const V = [Math.cos(rad(30)) * Math.SQRT1_2, Math.cos(rad(30)) * Math.SQRT1_2, Math.sin(rad(30))];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxO = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-R - 8, -R - 8, 0], [R + 8, R + 8, 0], [R + 8, -R - 8, 0], [-R - 8, R + 8, 0], [0, 0, H + 2]], 200, 172);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const w = (ph, ps, dr = 0) => [(R + dr) * Math.cos(rad(ps)) * Math.cos(rad(ph)), (R + dr) * Math.cos(rad(ps)) * Math.sin(rad(ph)), (H + dr) * Math.sin(rad(ps))];
  const pt = (ph, ps, dr = 0) => P(...w(ph, ps, dr));
  const [gr, gi] = rings(-R - 8, -R - 8, R + 8, R + 8, 14, 2);
  put(solid(g), prism(P, front, gr, gi, 0, 1.5));
  const dome = [];
  for (let ps = 0; ps <= 90; ps += 10) for (let ph = 0; ph < 360; ph += 10) dome.push(pt(ph, ps));
  mk("path", { d: poly(hull(dome)), class: "sil" }, g);
  // poles: two arcs over the crown, only where the dome faces us
  let poles = "";
  for (const ph0 of [0, 90]) {
    let run = [];
    for (let s = -90; s <= 90; s += 3) {
      const ps = 90 - Math.abs(s), ph = s < 0 ? ph0 + 180 : ph0, q = w(ph, ps);
      const vis = (q[0] * V[0] + q[1] * V[1]) / (R * R) + (q[2] * V[2]) / (H * H) > 0;
      if (vis) run.push(P(...w(ph, ps, 0.6))); else if (run.length) { poles += open(run); run = []; }
    }
    if (run.length) poles += open(run);
  }
  mk("path", { d: poles, class: "nf lo" }, g);
  const arch = (ph) => TOP * Math.sqrt(Math.max(0, 1 - ((ph - 45) / SPAN) ** 2));
  const phs = []; for (let ph = 45 - SPAN; ph <= 45 + SPAN + 0.01; ph += 4) phs.push(ph);
  const door = phs.map((ph) => pt(ph, arch(ph), 0.4));
  mk("path", { d: poly(door), class: "nf lo" }, g);
  const flap = mk("path", { class: "sil" }, g), roll = mk("path", { class: "nf lo" }, g), zip = mk("path", { class: "nf lo" }, g);
  let last = NaN, on = false;
  function draw(o) {
    o = Math.round(o * 200) / 200;
    if (o === last) return;
    last = o;
    const cap = TOP * (1 - o), dr = 1 + o * 3;
    const topE = phs.map((ph) => pt(ph, Math.min(arch(ph), cap), dr));
    const base = phs.map((ph) => pt(ph, 0, dr)).reverse();
    flap.setAttribute("d", cap < 1 ? "" : poly(topE.concat(base)));
    roll.setAttribute("d", o > 0.04 && cap > 1 ? open(phs.map((ph) => pt(ph, Math.max(0, Math.min(arch(ph), cap) - 3), dr + 1.5))) : "");
    zip.setAttribute("d", cap > 4 ? open([pt(45, 0, dr), pt(45, Math.min(TOP, cap), dr)]) : "");
    read.textContent = on ? "zip " + Math.round(o * 100) + "%" : "rest";
  }
  const op = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(op, dt); draw(op.x); return m; });
  bag.add(B.unregister);
  const dx = R * Math.SQRT1_2, dy = R * Math.SQRT1_2;
  function aim(p) {
    on = !!p; last = NaN;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0), d = Math.hypot(wx - dx, wy - dy);
      if (d > 150) return aim(null);
      op.t = clamp(maxO * (1 - (d - 30) / 120), 0.04, maxO);
    } else op.t = REST;
    B.wake();
  }
  flap.classList.add("hi");
  draw(REST);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxO = v; }, destroy: bag.dispose };
}

hairline({
  name: "tentdome",
  means: "A dome tent on a groundsheet: the nearer the pointer comes to its arched door, the further the flap unzips and rolls down to the sill.",
  rules: [1, 3, 5, 8],
  range: [0.7, 0.95, 1],
  tour: [[341, 186], [200, 229], [200, 101], null],
  mount,
});

filmprojector.code:
/**
 * Film projector: a body on a turntable base, two reels standing on top and a
 * lens barrel at the front. The projector turns on its base to aim the lens at
 * the pointer, a dashed beam thrown ahead of it, the reels riding along. At
 * rest it faces left of the viewer, the lens bright.
 *
 * The pattern: a continuous aim (one spring on yaw); the hit is the floor
 * plane, which never moves. Depth order of reels and lens swaps as it turns.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, rrect, seg, unproj, spring, stepS, hull, poly,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 8, TZ = 32, R = 15, REST = 2.0, BEAM = 26;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([30 * Math.cos(a), 30 * Math.sin(a), 0], [28 * Math.cos(a), 28 * Math.sin(a), TZ + 2 * R + 2]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  put(solid(g), prism(P, front, circ(24, 64), circ(22.6, 64), 0, 3));
  put(solid(g), prism(P, front, circ(6, 24), null, 3, BZ));
  const beam = mk("path", { class: "nf dash", d: "" }, g);
  const body = solid(g);
  const slot = mk("path", { class: "nf lo", d: "" }, body.g);
  const lens = mk("g", {}, g), barrel = mk("path", { class: "sil", d: "" }, lens), glass = mk("path", { class: "lo", d: "" }, lens);
  const reels = [0, 1].map(() => { const gg = mk("g", {}, g); return { g: gg, rim: mk("path", { class: "sil", d: "" }, gg), sp: mk("path", { class: "nf lo", d: "" }, gg) }; });
  const [BR, BI] = rings(-20, -12, 20, 12, 4, 1.4);

  const yaw = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, order = "";

  // a vertical disc: centre c, spanned by horizontal unit h and z
  const vdisc = (cx, cy, cz, hx, hy, r, n = 36) => {
    const out = [];
    for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; out.push(P(cx + hx * r * Math.cos(t), cy + hy * r * Math.cos(t), cz + r * Math.sin(t))); }
    return out;
  };

  function draw() {
    const a = yaw.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const ca = Math.cos(a), sa = Math.sin(a);
    put(body, prism(P, front, turn(BR, a), turn(BI, a), BZ, TZ));
    slot.setAttribute("d", seg(P(-8 * ca - 13 * -sa, -8 * sa - 13 * ca, BZ + 6), P(-8 * ca - 13 * -sa, -8 * sa - 13 * ca, TZ - 6)));
    // lens barrel along +d from the front face, glass face at its tip
    const lx0 = 20 * ca, ly0 = 20 * sa, lx1 = 30 * ca, ly1 = 30 * sa, lz = 20;
    const back = vdisc(lx0, ly0, lz, -sa, ca, 6, 24), tip = vdisc(lx1, ly1, lz, -sa, ca, 6.5, 24);
    barrel.setAttribute("d", poly(hull(back.concat(tip))));
    glass.setAttribute("d", poly(tip) + poly(vdisc(lx1, ly1, lz, -sa, ca, 3.5, 20)));
    const bx = (30 + BEAM) * ca, by = (30 + BEAM) * sa;
    beam.setAttribute("d", seg(P(lx1, ly1, lz + 6), P(bx - 14 * sa, by + 14 * ca, lz + 14)) + seg(P(lx1, ly1, lz - 6), P(bx + 14 * sa, by - 14 * ca, lz - 10)));
    const cs = [[-10, 0], [11, 0]];
    reels.forEach((r, i) => {
      const cx = cs[i][0] * ca, cy = cs[i][0] * sa, cz = TZ + R + 1, rr = i ? R - 3 : R;
      r.rim.setAttribute("d", poly(vdisc(cx, cy, cz, ca, sa, rr)));
      let sp = poly(vdisc(cx, cy, cz, ca, sa, 2.5, 12));
      for (let k = 0; k < 3; k++) { const t = k * 2.094 + i; sp += seg(P(cx + ca * 3 * Math.cos(t), cy + sa * 3 * Math.cos(t), cz + 3 * Math.sin(t)), P(cx + ca * (rr - 2) * Math.cos(t), cy + sa * (rr - 2) * Math.cos(t), cz + (rr - 2) * Math.sin(t))); }
      r.sp.setAttribute("d", sp);
      r.depth = cx + cy;
    });
    // paint order: beam and lens behind the body when the lens faces away
    const lensFront = ca + sa > 0, rf = reels[0].depth < reels[1].depth;
    const key = (lensFront ? "f" : "b") + (rf ? "0" : "1");
    if (key !== order) {
      order = key;
      const [a0, a1] = rf ? [reels[0], reels[1]] : [reels[1], reels[0]];
      const seq = lensFront ? [body.g, a0.g, a1.g, beam, lens] : [beam, lens, body.g, a0.g, a1.g];
      for (const el of seq) g.appendChild(el);
    }
    barrel.classList.add("hi");
  }

  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(w) {
    const t = w ? Math.atan2(w[1], w[0]) : REST;
    yaw.t = yaw.t + wrap(t - yaw.t);
    read.textContent = w ? ((Math.round((t * 180) / Math.PI) + 360) % 360) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y); aim(d > 10 && d < 120 ? [x, y] : null); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { yaw.k = 100 * v; yaw.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "filmprojector",
  means: "A film projector on a turntable: it turns to aim its lens and beam at the pointer, both reels riding along on top.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[324, 243], [165, 181], [138, 283], null],
  mount,
});

windsock2.code:
/**
 * Wind vane: a weathervane on a mast over a plinth, four compass arms tipped
 * with balls, and a long arrow with a split tail fin on the pivot. The pointer
 * is where the wind comes from: the arrow swings on a spring to point at it,
 * and lights. At rest the arrow sits off the arms at an easy angle, and the
 * north tip is the bright mark. The slider is how briskly the vane swings.
 *
 * The pattern: a continuous aim (one spring on an angle); the hit is the
 * ground plane, which never moves.
 */
const {
  Cam, circ, facing, fit, fillet, poly, prism, proj, rings, seg, unproj, spring, stepS, rad,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const H = 64, HA = 50, ARM = 22, TH = 1.3, REST = rad(160);
const VANE = [[42, 0], [28, 8.5], [28, 1.8], [-24, 1.8], [-37, 13], [-46, 13], [-39, 0], [-46, -13], [-37, -13], [-24, -1.8], [28, -1.8], [28, -8.5]];
const RAD = [0.6, 1.2, 0.8, 0.8, 1.5, 1.5, 1.2, 1.5, 1.5, 0.8, 0.8, 1.2];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.8);
  const ext = [[-24, -24, 0], [24, 24, 0], [24, -24, 0], [-24, 24, 0]];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([46 * Math.cos(a), 46 * Math.sin(a), H + 13], [46 * Math.cos(a), 46 * Math.sin(a), H - 13]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [b0, b1] = rings(-20, -20, 20, 20, 6, 1.6);
  put(solid(g), prism(P, front, b0, b1, 0, 5));
  const [c0, c1] = rings(-8, -8, 8, 8, 4, 1.2);
  put(solid(g), prism(P, front, c0, c1, 5, 8));
  const tips = [[ARM, 0], [0, ARM], [-ARM, 0], [0, -ARM]];
  const far = tips.filter(([x, y]) => x + y < 0), near = tips.filter(([x, y]) => x + y > 0);
  mk("path", { class: "nf sil", d: far.map(([x, y]) => seg(P(0, 0, HA), P(x, y, HA))).join("") }, g);
  for (const [x, y] of far) place(flatDot(g, C, 1.8, "dot off"), P(x, y, HA));
  put(solid(g), prism(P, front, circ(2.2, 20), null, 8, H - 2));
  put(solid(g), prism(P, front, circ(3.6, 20), circ(2.8, 20), HA - 1.5, HA + 1.5));
  mk("path", { class: "nf sil", d: near.map(([x, y]) => seg(P(0, 0, HA), P(x, y, HA))).join("") }, g);
  for (const [x, y] of near) place(flatDot(g, C, 1.8, "dot off"), P(x, y, HA));
  const back = mk("path", { class: "sil" }, g);
  const vane = solid(g);
  put(solid(g), prism(P, front, circ(3, 20), circ(2.2, 20), H - 2.5, H + 2.5));
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  function plate(a, off) {
    const c = Math.cos(a), s = Math.sin(a), nx = -s * off, ny = c * off;
    return poly(fillet(VANE.map(([u, z]) => P(u * c + nx, u * s + ny, H + z)), RAD));
  }
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const side = Math.cos(a) - Math.sin(a) > 0 ? 1 : -1; // +n side faces the viewer
    back.setAttribute("d", plate(a, -side * TH));
    vane.sil.setAttribute("d", plate(a, 0));
    const c = Math.cos(a), s = Math.sin(a), Q = (u, z) => P(u * c, u * s, H + z);
    vane.cr.setAttribute("d", seg(Q(-24, 0), Q(26, 0)) + seg(Q(-36.5, 10), Q(-40, 1.5)) + seg(Q(-36.5, -10), Q(-40, -1.5)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const all = [...g.querySelectorAll("ellipse, circle")];
  let over = null;
  function retarget() {
    const aim = over ? Math.atan2(over[1], over[0]) : REST;
    sp.t = sp.t + wrap(aim - sp.t);
    vane.sil.classList.toggle("hi", !!over);
    all.forEach((d, i) => d.setAttribute("class", !over && i === all.length - 1 ? "dot" : "dot off"));
    const deg = Math.round(((aim * 180) / Math.PI + 405) % 360);
    read.textContent = over ? String(deg).padStart(3, "0") + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r < 6 || r > 140 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "windsock2",
  means: "A wind vane on a mast: the arrow swings round to point at the pointer, as if the wind came from there, and lights.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[91, 242], [358, 267], [200, 207], null],
  mount,
});

batterycart.code:
/**
 * Battery swap: a swap station, a plinth with a back wall and three tall
 * battery packs standing in their bays, each with a terminal on top and a
 * charge seam. The pointer picks a bay: that pack slides out toward you on
 * the 700ms ease, its neighbours ease out a little after it, and it is bright.
 * At rest the middle pack stands half drawn, bright. The slider is how far
 * a chosen pack slides.
 *
 * The pattern: a discrete pick by screen x (rest centres), staggered tweens.
 */
const {
  Cam, facing, fit, prism, proj, rings, seg, unproj, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const XS = [-24, 0, 24], REST = [3, 13, 0], FAV = 1, OUT = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-42, -24, 0], [42, -24, 44], [42, 18 + OUT * 1.4, 0], [-42, 18 + OUT * 1.4, 36], [-42, -24, 44]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [w0, w1] = rings(-40, -24, 40, -18, 2.5, 1);
  put(solid(g), prism(P, front, w0, w1, 0, 44));
  const [b0, b1] = rings(-40, -18, 40, 18, 4, 1.6);
  put(solid(g), prism(P, front, b0, b1, 0, 4));
  const packs = XS.map((cx, i) => {
    const grp = mk("g", {}, g);
    return { i, cx, s: solid(grp), cap: solid(grp), seam: mk("path", { class: "nf lo" }, grp), tw: tween(REST[i]), drawn: NaN };
  });

  function draw(p, now) {
    const y = tval(p.tw, now);
    if (Math.abs(y - p.drawn) < 1e-3) return;
    p.drawn = y;
    const [r0, r1] = rings(p.cx - 9, y - 12, p.cx + 9, y + 12, 3, 1.2);
    put(p.s, prism(P, front, r0, r1, 4, 36));
    const [t0, t1] = rings(p.cx - 3, y - 5, p.cx + 3, y + 5, 1.5, 0.6);
    put(p.cap, prism(P, front, t0, t1, 36, 38.5));
    p.seam.setAttribute("d", seg(P(p.cx + 9, y + 12, 12), P(p.cx - 9, y + 12, 12)) + seg(P(p.cx + 9, y + 12, 12), P(p.cx + 9, y - 12, 12)));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const p of packs) { draw(p, now); if (!tdone(p.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let pick = null;
  function retarget() {
    const now = performance.now();
    for (const p of packs) {
      const d = pick ? Math.abs(p.i - pick.i) : 0;
      const to = pick ? [OUT * value, 7, 2][d] : REST[p.i];
      tset(p.tw, to, now, pick ? d * 45 : 0);
      p.s.sil.classList.toggle("hi", pick ? p === pick : p.i === FAV);
    }
    read.textContent = pick ? "bay " + (pick.i + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => {
      let near = null, bd = Infinity;
      for (const p of packs) { const d = Math.abs(P(p.cx, 0, 20)[0] - q[0]); if (d < bd) { bd = d; near = p; } }
      const [x, y] = unproj(C, q[0], q[1], 20);
      const nxt = Math.abs(x) > 60 || Math.abs(y) > 70 ? null : near;
      if (nxt !== pick) { pick = nxt; retarget(); }
    },
    leave: () => { pick = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { value = v; retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "batterycart",
  means: "A battery swap station: the pack under the pointer slides out of its bay toward you, neighbours easing after it.",
  rules: [1, 2, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[187, 127], [289, 178], [238, 152], null],
  mount,
});

coathook2.code:
/**
 * Shoe rack spinner: three round tiers on a centre pole, five shoes on each,
 * toes out. The whole rack turns on one spring so that the middle tier's shoe
 * nearest the pointer comes round to face it, and that shoe is bright. At
 * rest the rack sits a little turned with one shoe bright on the middle tier.
 *
 * The pattern: a continuous aim (spring on one angle); the hit is on the
 * floor's plane, which never moves. Shoes move between the far and near group
 * of their tier as they pass behind the pole.
 */
const {
  Cam, circ, facing, fit, prism, proj, rrect, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, R = 31, TZ = [4, 28, 52], OFF = [0.62, 0, 0.31], REST = 0.35, FAV = 0;
const SHOE = [rrect(10, -3.8, 28, 3.8, 3.6, 4), rrect(11.2, -2.6, 26.8, 2.6, 2.4, 4)];
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([R * Math.cos(a), R * Math.sin(a), 0], [R * Math.cos(a), R * Math.sin(a), TZ[2] + 8]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(15, 40), circ(13.6, 40), 0, 3));
  const tiers = TZ.map((z, i) => {
    put(solid(g), prism(P, front, circ(R, 64), circ(R - 1.8, 64), z - 2, z));
    const far = mk("g", {}, g);
    put(solid(g), prism(P, front, circ(2.6, 20), null, z, i < 2 ? TZ[i + 1] - 2 : z + 12));
    const near = mk("g", {}, g);
    const shoes = [];
    for (let k = 0; k < N; k++) { const s = solid(far); shoes.push({ s, nearSide: false }); }
    return { z, i, far, near, shoes };
  });

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, pick = FAV;
  function draw() {
    const a0 = sp.x;
    if (Math.abs(a0 - drawn) < 1e-4) return;
    drawn = a0;
    for (const t of tiers) for (let k = 0; k < N; k++) {
      const a = a0 + OFF[t.i] + (k / N) * Math.PI * 2, sh = t.shoes[k];
      put(sh.s, prism(P, front, turn(SHOE[0], a), turn(SHOE[1], a), t.z, t.z + 5.5));
      const nearSide = Math.cos(a) + Math.sin(a) > 0;
      if (nearSide !== sh.nearSide) { sh.nearSide = nearSide; (nearSide ? t.near : t.far).appendChild(sh.s.g); }
    }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function light(k) {
    pick = k;
    tiers.forEach((t) => t.shoes.forEach((sh, j) => sh.s.sil.classList.toggle("hi", t.i === 1 && j === k)));
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y);
      if (d > R + 40) { sp.t = sp.t + wrap(REST - sp.t); light(FAV); read.textContent = "rest"; return B.wake(); }
      if (d < 4) return;
      const aim = Math.atan2(y, x);
      let bk = 0, bd = Infinity, bt = 0;
      for (let k = 0; k < N; k++) {
        const now = sp.t + (k / N) * Math.PI * 2, dd = wrap(aim - now);
        if (Math.abs(dd) < bd) { bd = Math.abs(dd); bk = k; bt = sp.t + dd; }
      }
      sp.t = bt; light(bk);
      read.textContent = "shoe " + (bk + 1);
      B.wake();
    },
    leave: () => { sp.t = sp.t + wrap(REST - sp.t); light(FAV); read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  light(FAV);
  read.textContent = "rest";
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "coathook2",
  means: "A spinning shoe rack: the rack turns so the middle tier's shoe nearest the pointer comes round to face it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[297, 208], [200, 296], [103, 208], null],
  mount,
});

blender2.code:
/**
 * Juice press: a lever citrus press. A base plate, a ribbed cone in its cup,
 * a post at the back and a long lever hinged on it, carrying the press bowl.
 * The pointer moving down across the press brings the lever down on a spring
 * until the bowl closes over the cone. At rest the lever stands raised and its
 * knob is bright; pressed home, the bowl takes the bright.
 *
 * The pattern: a continuous pull (spring) read from the ground plane, which
 * never moves; the arm and bowl turn about the hinge in the x–z plane.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS, clamp, hull, poly, open, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HX = 25, HZ = 42, ARM = 52, CUP = 25, UP = 60;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  const ue = rad => [HX - ARM * Math.cos(rad), 0, HZ + ARM * Math.sin(rad)];
  fit(C, [[-26, -16, 0], [32, 16, 0], [-14, 14, 0], ue(UP * Math.PI / 180), [HX - ARM - 4, 0, HZ], [HX - CUP + 14, 14, HZ + CUP * Math.sin(UP * Math.PI / 180) + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [bR, bI] = rings(-24, -16, 32, 16, 6, 1.6);
  put(solid(g), prism(P, front, bR, bI, 0, 3.5));
  put(solid(g), prism(P, front, disc(0, 0, 15, 40), disc(0, 0, 13.6, 40), 3.5, 13));
  // the ribbed cone
  const cone = solid(g), base = circ(9, 32).map((q) => P(q.u, q.v, 13)), apex = P(0, 0, 25);
  cone.sil.setAttribute("d", poly(hull(base.concat([apex]))));
  let ribs = ""; for (let i = 0; i < 6; i++) { const a = (i / 6) * Math.PI * 2 + 0.3; if (Math.cos(a) + Math.sin(a) > -0.3) ribs += seg(P(9 * Math.cos(a), 9 * Math.sin(a), 13), apex); }
  cone.cr.setAttribute("d", ribs);
  put(solid(g), prism(P, front, rings(HX - 4, -5, HX + 5, 5, 2.5, 0.8)[0], rings(HX - 4, -5, HX + 5, 5, 2.5, 0.8)[1], 3.5, HZ + 3));
  const lever = mk("g", {}, g);
  const bowl = solid(lever), arm = solid(lever), knob = solid(lever);

  // local shapes, in (along the arm from the hinge, y, height above the arm)
  const ringPts = (cx, r, h, n = 28) => circ(r, n).map((q) => [cx + q.u, q.v, h]);
  const box = (a0, a1, w, h0, h1) => { const o = []; for (const h of [h0, h1]) for (const [a, y] of [[a0, -w], [a1, -w], [a1, w], [a0, w]]) o.push([a, y, h]); return o; };
  const sp = spring(1, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const th = t * UP * Math.PI / 180, c = Math.cos(th), s = Math.sin(th);
    const W = ([a, y, h]) => P(HX - a * c + h * s, y, HZ + a * s + h * c);
    const S = (pts) => poly(hull(pts.map(W)));
    arm.sil.setAttribute("d", S(box(-3, ARM, 3, -1.5, 2.5)));
    arm.cr.setAttribute("d", open([[2, 0, 2.5], [ARM - 4, 0, 2.5]].map(W)));
    bowl.sil.setAttribute("d", S(ringPts(CUP, 13, -1.5).concat(ringPts(CUP, 10, -13))));
    bowl.cr.setAttribute("d", poly(ringPts(CUP, 10, -13).map(W)));
    knob.sil.setAttribute("d", S(ringPts(ARM, 4.5, -2, 16).concat(ringPts(ARM, 4.5, 4, 16))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function set(t) {
    sp.t = t;
    const home = t < 0.2;
    knob.sil.classList.toggle("hi", !home);
    bowl.sil.classList.toggle("hi", home);
    read.textContent = t < 1 ? "press " + Math.round((1 - t) * 100) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -60 || x > 50 || y < -60 || y > 40) return set(1);
      set(clamp(1 - (x + y + 40) / 60, 0, 1));
    },
    leave: () => set(1),
  }));
  bag.add(() => svg.replaceChildren());
  set(1);
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "blender2",
  means: "A lever citrus press: the pointer moving down across it pulls the lever down until the bowl closes over the cone.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[213, 169], [204, 226], [213, 275], null],
  mount,
});

toaster2.code:
/**
 * Toaster oven: a boxy oven on four feet, a glass door hinged along its
 * bottom edge, two dials beside it. The pointer coming round to the front
 * swings the door down on a spring and, once it is low enough, the rack tray
 * slides out over it. At rest the door hangs a little ajar and its handle is
 * the bright mark; open, the tray takes the bright.
 *
 * The pattern: a continuous pull (spring) read from the ground plane, which
 * never moves.
 */
const {
  Cam, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, clamp, fillet, poly,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const W = 64, D = 40, H = 36, X0 = 4, X1 = 46, Z0 = 6, DH = 25, REST = 0.12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, D + DH, 0], [W, D, 0], [0, 0, H], [W, D, H], [X0, D + DH, Z0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const [x, y] of [[5, 4], [W - 5, 4], [5, D - 4], [W - 5, D - 4]]) place(flatDot(g, C, 1.6, "dot off"), P(x, y, 0));
  const [ring, inner] = rings(0, 0, W, D, 5, 1.6);
  put(solid(g), prism(P, front, ring, inner, 2.5, H));
  // the oven's mouth on the front face, and the dials beside it
  const face = (x, z) => P(x, D, z);
  mk("path", { class: "lo nf", d: poly(fillet([face(X0, Z0), face(X1, Z0), face(X1, Z0 + DH), face(X0, Z0 + DH)], [2, 2, 2, 2])) }, g);
  mk("path", { class: "lo nf", d: seg(P(X0 + 2, D - 6, Z0 + 9), P(X1 - 2, D - 6, Z0 + 9)) + seg(P(X0 + 2, D - 30, Z0 + 9), P(X0 + 2, D - 6, Z0 + 9)) }, g);
  for (const z of [26, 15]) {
    const pts = []; for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push(P(55 + 4 * Math.cos(a), D + 0.4, z + 4 * Math.sin(a))); }
    mk("path", { d: poly(pts) }, g);
  }
  mk("path", { class: "lo nf", d: seg(P(51, D + 0.4, 8), P(59, D + 0.4, 8)) }, g);
  const door = mk("path", { class: "sil" }, g);
  const glass = mk("path", { class: "lo nf" }, g);
  const handle = mk("path", { class: "nf sil" }, g);
  const tray = mk("path", { class: "sil" }, g);
  const rack = mk("path", { class: "lo nf" }, g);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const o = sp.x;
    if (Math.abs(o - drawn) < 1e-4) return;
    drawn = o;
    const a = o * Math.PI / 2, s = Math.sin(a), c = Math.cos(a);
    const Q = (x, h, out = 0) => P(x, D + h * s + out * c, Z0 + h * c - out * s);
    door.setAttribute("d", poly(fillet([Q(X0, 0), Q(X1, 0), Q(X1, DH), Q(X0, DH)], [2, 2, 3, 3])));
    glass.setAttribute("d", poly(fillet([Q(X0 + 5, 4), Q(X1 - 5, 4), Q(X1 - 5, DH - 6), Q(X0 + 5, DH - 6)], [1.5, 1.5, 1.5, 1.5])));
    handle.setAttribute("d", seg(Q(X0 + 6, DH - 2.5, 0), Q(X0 + 6, DH - 2.5, 3)) + seg(Q(X0 + 6, DH - 2.5, 3), Q(X1 - 6, DH - 2.5, 3)) + seg(Q(X1 - 6, DH - 2.5, 3), Q(X1 - 6, DH - 2.5, 0)));
    const t = clamp((o - 0.55) / 0.45, 0, 1) * 22, z = Z0 + 9;
    if (t <= 0.3) { tray.setAttribute("d", ""); rack.setAttribute("d", ""); }
    if (t > 0.3) {
      const T = (x, y, zz = z) => P(x, D + y, zz);
      tray.setAttribute("d", poly(fillet([T(X0 + 2, 0), T(X1 - 2, 0), T(X1 - 2, t), T(X1 - 2, t, z - 1.6), T(X0 + 2, t, z - 1.6), T(X0 + 2, t)], [1, 1, 1, 1, 1, 1])));
      let d = "";
      for (let x = X0 + 7; x < X1 - 4; x += 5) d += seg(T(x, 0), T(x, t - 2));
      rack.setAttribute("d", d);
    }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(o, lit) {
    sp.t = o;
    handle.classList.toggle("hi", !lit);
    tray.classList.toggle("hi", lit);
    read.textContent = o > REST ? "door " + Math.round(o * 90) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -16 || x > W + 16 || y < -16 || y > D + DH + 18) return set(REST, false);
      const o = clamp((y - 6) / (D + 6), REST, 1);
      set(o, o > 0.6);
    },
    leave: () => set(REST, false),
  }));
  bag.add(() => svg.replaceChildren());
  set(REST, false);
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "toaster2",
  means: "A toaster oven: the pointer coming round to the front swings its door down, and the rack tray slides out over it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[141, 168], [241, 259], [126, 246], null],
  mount,
});

ricebin.code:
/**
 * Rice dispenser: a tall bin with a lid, a level window down its front and a
 * measuring drawer at its foot. The pointer coming round to the front pulls
 * the drawer out on a spring, a measure of rice in it. At rest the drawer sits
 * just proud of the face and its pull is bright; drawn out, the drawer takes
 * the bright.
 *
 * The pattern: a continuous pull (spring) read from the ground plane, which
 * never moves.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, unproj, spring, stepS, clamp, fillet, poly,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const W = 44, D = 36, H = 78, X0 = 7, X1 = 37, Z0 = 4, Z1 = 20, OUT = 30, REST = 0.08;
const GRAINS = [[0.3, 0.3], [0.5, 0.25], [0.7, 0.35], [0.4, 0.55], [0.6, 0.6], [0.25, 0.7], [0.75, 0.72], [0.5, 0.8]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, D + OUT, 0], [W, D + OUT, 0], [0, 0, H + 4], [W, D, H + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ring, inner] = rings(0, 0, W, D, 6, 1.8);
  put(solid(g), prism(P, front, ring, inner, 0, H));
  const [lr, li] = rings(-1, -1, W + 1, D + 1, 7, 1.6);
  put(solid(g), prism(P, front, lr, li, H, H + 4));
  const face = (x, z) => P(x, D, z);
  mk("path", { class: "lo nf", d: poly(fillet([face(18, 30), face(26, 30), face(26, H - 10), face(18, H - 10)], [3, 3, 3, 3])) + seg(face(18, 50), face(26, 50)) }, g);
  mk("path", { class: "lo nf", d: poly(fillet([face(X0 - 1, Z0 - 1), face(X1 + 1, Z0 - 1), face(X1 + 1, Z1 + 1), face(X0 - 1, Z1 + 1)], [2, 2, 2, 2])) }, g);
  const drawer = solid(g);
  const grains = GRAINS.map(() => flatDot(g, C, 1.3, "dot off"));
  const pull = mk("path", { class: "nf sil" }, g);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const o = sp.x;
    if (Math.abs(o - drawn) < 1e-4) return;
    drawn = o;
    const y1 = D + 1.5 + o * OUT;
    const [dr, di] = rings(X0, D - 0.2, X1, y1, 1.6, 1.2);
    put(drawer, prism(P, front, dr, o > 0.15 ? di : null, Z0, Z1));
    GRAINS.forEach(([u, v], i) => {
      const y = D + v * (y1 - D - 4);
      if (o > 0.25) { if (!grains[i].isConnected) pull.before(grains[i]); place(grains[i], P(X0 + 3 + u * (X1 - X0 - 6), y, Z1 - 1)); } else grains[i].remove();
    });
    const mid = (X0 + X1) / 2;
    pull.setAttribute("d", seg(P(mid - 6, y1, 13), P(mid - 6, y1 + 3, 13)) + seg(P(mid - 6, y1 + 3, 13), P(mid + 6, y1 + 3, 13)) + seg(P(mid + 6, y1 + 3, 13), P(mid + 6, y1, 13)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function set(o) {
    sp.t = o;
    const lit = o > 0.6;
    pull.classList.toggle("hi", !lit);
    drawer.sil.classList.toggle("hi", lit);
    read.textContent = o > REST ? "cup " + Math.round(o * 100) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -16 || x > W + 16 || y < -16 || y > D + OUT + 18) return set(REST);
      set(clamp((y - 4) / (D + 10), REST, 1));
    },
    leave: () => set(REST),
  }));
  bag.add(() => svg.replaceChildren());
  set(REST);
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "ricebin",
  means: "A rice dispenser bin: the pointer coming round to the front pulls out its measuring drawer, a measure of rice in it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[180, 206], [257, 281], [143, 287], null],
  mount,
});

tractor2.code:
/**
 * Hay baler: a square baler on two wheels, a pickup in front and a hitch bar,
 * with a bale chute hinged at its rear. The pointer is how far back the hand
 * is: the chute tips down and the bale slides out along it, on one spring.
 * At rest the bale sits just out of the chamber, the chute's lip bright.
 *
 * The pattern: a continuous reach (one spring) read from the ground plane,
 * which never moves.
 */
const {
  Cam, facing, fillet, fit, hull, poly, open, prism, proj, rings, seg, unproj, spring, stepS, clamp, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const lerpA = (p, q, f) => p + (q - p) * f;
const HX = 12, HZ = 15, CL = 46, CW = 13, BL = 17, BH = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-62, -16, 0], [-62, 16, 0], [HX + CL, -16, 0], [HX + CL, 16, 0], [-30, -16, 32], [HX, 16, 32]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const shape = (pts, r = 1.4) => { const h = hull(pts.map((q) => P(...q))); return poly(fillet(h, h.map(() => r), 3)); };
  const wheel = (parent, y0, y1) => {
    const ring = (y) => Array.from({ length: 28 }, (_, i) => { const a = (i / 28) * Math.PI * 2; return [-4 + 9 * Math.cos(a), y, 9 + 9 * Math.sin(a)]; });
    const s = solid(parent);
    s.sil.setAttribute("d", poly(hull(ring(y0).concat(ring(y1)).map((q) => P(...q)))));
    s.cr.setAttribute("d", poly(ring(y1).map((q) => P(...q))));
    const hubR = (y) => Array.from({ length: 16 }, (_, i) => { const a = (i / 16) * Math.PI * 2; return [-4 + 3 * Math.cos(a), y, 9 + 3 * Math.sin(a)]; });
    mk("path", { class: "nf lo", d: poly(hubR(y1).map((q) => P(...q))) }, s.g);
  };

  // far side first: far wheel, hitch, pickup, body, near wheel
  wheel(g, -18, -14);
  put(solid(g), prism(P, front, ...rings(-62, -8, -30, -4, 1.2, 0.6), 15, 18));
  put(solid(g), prism(P, front, ...rings(-42, -15, -30, 15, 3, 1.2), 2, 9));
  mk("path", { class: "nf lo", d: [0, 1, 2, 3, 4].map((i) => seg(P(-42, -12 + i * 6, 5), P(-45, -12 + i * 6, 3))).join("") }, g);
  put(solid(g), prism(P, front, ...rings(-30, -13, HX, 13, 3, 1.4), 7, 30));
  wheel(g, 14, 18);

  const chute = solid(g);
  const lip = mk("path", { class: "nf" }, chute.g);
  const bale = solid(g);
  const twine = mk("path", { class: "nf lo" }, bale.g);
  const sp = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  function draw() {
    const t = clamp(sp.x, 0, 1);
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const th = rad(10 + t * 26), c = Math.cos(th), s = Math.sin(th);
    // a point on the chute: along it by a, across by y, above its deck by h
    const at = (a, y, h) => [HX + a * c + h * s, y, HZ - a * s + h * c];
    const deck = [];
    for (const a of [0, CL]) for (const y of [-CW, CW]) for (const h of [0, -2]) deck.push(at(a, y, h));
    chute.sil.setAttribute("d", shape(deck, 1.6));
    chute.cr.setAttribute("d", open([at(CL - 1.5, -CW + 1, 0), at(CL - 1.5, CW - 1, 0)].map((q) => P(...q))));
    lip.setAttribute("d", seg(P(...at(CL, -CW, 0)), P(...at(CL, -CW, 2.5))) + seg(P(...at(CL, CW, 0)), P(...at(CL, CW, 2.5))) + open([at(CL, -CW, 2.5), at(CL, CW, 2.5)].map((q) => P(...q))));
    const a0 = 1 + t * (CL - BL - 2), a1 = a0 + BL, w = CW - 2, box = [];
    for (const a of [a0, a1]) for (const y of [-w, w]) for (const h of [0.3, BH]) box.push(at(a, y, h));
    bale.sil.setAttribute("d", shape(box, 1.6));
    bale.cr.setAttribute("d", open([at(a0 + 1, w - 1, BH), at(a1 - 1, w - 1, BH), at(a1 - 1, -w + 1, BH)].map((q) => P(...q))));
    let d = "";
    for (const f of [0.3, 0.7]) {
      const a = lerpA(a0, a1, f);
      d += open([at(a, -w, BH), at(a, w, BH), at(a, w, 0.3)].map((q) => P(...q)));
    }
    twine.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function mark(on) {
    lip.classList.toggle("hi", !on);
    bale.sil.classList.toggle("hi", on);
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -70 || x > HX + CL + 26 || Math.abs(y) > 46) { sp.t = 0; mark(false); read.textContent = "rest"; B.wake(); return; }
      sp.t = clamp((x + 20) / (CL + 26), 0, 1);
      mark(true);
      read.textContent = "out " + Math.round(sp.t * 100);
      B.wake();
    },
    leave: () => { sp.t = 0; mark(false); read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  mark(false);
  read.textContent = "rest";
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "tractor2",
  means: "A hay baler: the closer the pointer to its rear, the further the chute tips and the bale slides out.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[186, 180], [222, 234], [312, 243], null],
  mount,
});

sprinkler.code:
/**
 * Sprinkler: a rotary garden sprinkler on a sled base, a riser, a hub and two
 * long arms with nozzle caps at their tips. The pointer is where the water
 * goes: the rotor swings on a spring until one arm points at it, and that arm
 * is bright. At rest the rotor sits askew with its first arm bright. The
 * slider is how stiffly the rotor follows.
 *
 * The pattern: a continuous aim (one spring on an angle); the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 50, AZ = 21, REST = -0.55;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.1);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([(L + 2) * Math.cos(a), (L + 2) * Math.sin(a), 0], [(L + 2) * Math.cos(a), (L + 2) * Math.sin(a), AZ + 8]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // sled base: two runners and a cross plate, then the riser
  put(solid(g), prism(P, front, ...rings(-20, -16, 20, -10, 3, 1), 0, 3));
  put(solid(g), prism(P, front, ...rings(-20, 10, 20, 16, 3, 1), 0, 3));
  put(solid(g), prism(P, front, ...rings(-7, -14, 7, 14, 3, 1.2), 3, 6));
  put(solid(g), prism(P, front, circ(3, 24), null, 6, AZ - 3));

  const ARM = rings(2, -2.4, L - 6, 2.4, 1.2, 0.8), CAP = rings(L - 8, -4.5, L, 4.5, 2.2, 1);
  const rotor = mk("g", {}, g);
  const halves = [0, 1].map((i) => {
    const hg = mk("g", {}, rotor);
    return { i, g: hg, arm: solid(hg), cap: solid(hg) };
  });
  const hub = solid(rotor);
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, lit = 0;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    for (const h of halves) {
      const b = a + h.i * Math.PI;
      const T = (r) => turn(r, b);
      put(h.arm, prism(P, front, T(ARM[0]), T(ARM[1]), AZ, AZ + 3.4));
      put(h.cap, prism(P, front, T(CAP[0]), T(CAP[1]), AZ - 2, AZ + 7));
    }
    put(hub, prism(P, front, circ(6, 32), circ(4.8, 32), AZ - 3, AZ + 6));
    // the far arm goes behind the hub, the near one in front of it
    const far = Math.cos(a) + Math.sin(a) < 0 ? halves[0] : halves[1];
    const near = far === halves[0] ? halves[1] : halves[0];
    rotor.prepend(far.g);
    rotor.append(near.g);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function mark(i, label) {
    lit = i;
    for (const h of halves) { const on = h.i === i; h.arm.sil.classList.toggle("hi", on); h.cap.sil.classList.toggle("hi", on); }
    read.textContent = label;
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      if (r > L + 30) { sp.t = sp.t + wrap(REST - sp.t); mark(0, "rest"); return; }
      if (r < 5) return;
      const aim = Math.atan2(y, x);
      // swing whichever arm is closer to the aim
      const d0 = wrap(aim - sp.t), d1 = wrap(aim - Math.PI - sp.t);
      const use = Math.abs(d0) <= Math.abs(d1) ? 0 : 1;
      sp.t = sp.t + (use ? d1 : d0);
      const deg = Math.round(((aim * 180) / Math.PI + 360) % 360);
      mark(use, String(deg).padStart(3, "0") + "°");
    },
    leave: () => { sp.t = sp.t + wrap(REST - sp.t); mark(0, "rest"); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  mark(0, "rest");
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "sprinkler",
  means: "A rotary garden sprinkler: the rotor swings until one arm points at the pointer, and that arm is bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[353, 238], [112, 249], [25, 161], null],
  mount,
});

beehive2.code:
/**
 * Bee smoker: a tin canister with a cone lid and spout, and a pair of bellows
 * hinged at its foot. The pointer is the hand: the nearer it comes to the
 * bellows, the further their outer board swings shut and the more smoke rings
 * leave the spout, on one spring. At rest the bellows stand open and the
 * spout's rim is bright.
 *
 * The pattern: a continuous squeeze (one spring), read on the ground plane,
 * which never moves.
 */
const {
  Cam, circ, facing, fillet, fit, hull, poly, open, prism, proj, rings, ringAt, run, unproj, spring, stepS, clamp, rad, lerp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 11, H = 34, BX = 13.5, BW = 9, Z0 = 5, BH = 27;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 4.0);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R, R, 0], [R, -R, 0], [-R, -R, 66], [BX + 20, BW, 0], [BX + 20, -BW, Z0 + BH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const shape = (pts, r = 1.2) => { const h = hull(pts.map((q) => P(...q))); return poly(fillet(h, h.map(() => r), 3)); };
  const taper = (parent, foot, top, inner, z0, z1) => {
    const s = solid(parent);
    s.sil.setAttribute("d", poly(hull(ringAt(P, foot, z0).concat(ringAt(P, top, z1)))));
    s.cr.setAttribute("d", open(ringAt(P, run(inner, front), z1)));
    return s;
  };

  // canister, its rim band, the cone lid and the spout
  put(solid(g), prism(P, front, circ(R, 40), circ(R - 1.2, 40), 0, H));
  put(solid(g), prism(P, front, circ(R + 0.8, 40), circ(R - 0.4, 40), H - 1, H + 2));
  taper(g, circ(R + 0.4, 40), circ(4.6, 28), circ(3.6, 28), H + 2, H + 13);
  const spout = solid(g);
  put(spout, prism(P, front, circ(3, 24), circ(2, 24), H + 13, H + 17));

  // bellows: fixed inner board, leather, swinging outer board
  const innerB = [];
  for (const x of [BX, BX + 1.6]) for (const y of [-BW, BW]) for (const z of [Z0, Z0 + BH]) innerB.push([x, y, z]);
  mk("path", { class: "sil", d: shape(innerB) }, g);
  const leather = mk("path", { class: "sil" }, g);
  const pleats = mk("path", { class: "nf lo" }, g);
  const outer = solid(g);
  const smoke = [0, 1, 2].map(() => mk("ellipse", { class: "nf lo", rx: 0, ry: 0 }, g));

  const sp = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const t = clamp(sp.x, 0, 1);
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const ph = rad(lerp(34, 7, t)), c = Math.cos(ph), s = Math.sin(ph);
    const at = (h, y, d) => [BX + 3.2 + h * s + d * c, y, Z0 + h * c - d * s];
    const ob = [];
    for (const h of [0, BH]) for (const y of [-BW, BW]) for (const d of [0, 1.8]) ob.push(at(h, y, d));
    outer.sil.setAttribute("d", shape(ob));
    outer.cr.setAttribute("d", open([at(BH - 1.5, -BW + 1, 1.8), at(BH - 1.5, BW - 1, 1.8)].map((q) => P(...q))));
    const lb = [];
    for (const y of [-BW + 0.5, BW - 0.5]) { lb.push([BX + 1.6, y, Z0 + 1], [BX + 1.6, y, Z0 + BH - 1], at(1, y, 0), at(BH - 1, y, 0)); }
    leather.setAttribute("d", shape(lb, 0.8));
    let d = "";
    const zig = [];
    for (let i = 0; i <= 8; i++) {
      const f = i / 8, h = 1 + f * (BH - 2), k = i % 2 ? 0.75 : 0.25;
      const pin = [BX + 1.6, BW - 0.5, Z0 + h], pout = at(h, BW - 0.5, 0);
      zig.push(P(lerp(pin[0], pout[0], k), BW - 0.5, lerp(pin[2], pout[2], k)));
    }
    d += open(zig);
    pleats.setAttribute("d", d);
    smoke.forEach((e, i) => {
      const rise = t * (3 + i * 5), r = t * (2.5 + i * 1.6), [sx, sy] = P(0, 0, H + 18 + rise);
      e.setAttribute("cx", sx.toFixed(2)); e.setAttribute("cy", sy.toFixed(2));
      e.setAttribute("rx", (r * 4).toFixed(2)); e.setAttribute("ry", ((r * 4) * 0.5).toFixed(2));
    });
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function mark(on) {
    spout.sil.classList.toggle("hi", !on);
    outer.sil.classList.toggle("hi", on);
  }
  const rest = () => { sp.t = 0; mark(false); read.textContent = "rest"; B.wake(); };
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), dd = Math.hypot(x - (BX + 20), y);
      if (dd > 70) return rest();
      sp.t = clamp(1.15 - dd / 50, 0, 1);
      mark(true);
      read.textContent = "puff " + Math.round(sp.t * 100);
      B.wake();
    },
    leave: rest,
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  rest();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "beehive2",
  means: "A bee smoker: the nearer the pointer to the bellows, the further they squeeze shut and the more smoke leaves the spout.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[256, 252], [318, 305], [256, 308], null],
  mount,
});

chessclock.code:
/**
 * Chess clock: a long case with two round dials on its face and a rocker bar
 * on top carrying two plungers. The pointer picks a side: the rocker see-saws
 * down on that side, and that player's hand sweeps round its dial. At rest the
 * rocker leans to the left, its plunger bright.
 *
 * The pattern: a discrete choice between two sides (tween); the hit is the
 * plungers' rest screen x, which never moves.
 */
const {
  Cam, circ, facing, fit, hull, open, poly, prism, proj, rings, run, seg,
  tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid,
} = HL;

const H = 34, PZ = H + 4, A = 0.1, BX = 28;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-40, -16, 0], [40, 16, 0], [-40, -16, H], [40, 16, H], [-36, 0, PZ + 16], [36, 0, PZ + 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const T = (x, y, z, th) => {
    const dz = z - PZ, c = Math.cos(th), s = Math.sin(th);
    return P(x * c - dz * s, y, PZ + x * s + dz * c);
  };
  const tilted = (sd, ring, inner, z0, z1, ox, th) => {
    const pts = [];
    for (const q of ring) pts.push(T(q.u + ox, q.v, z0, th), T(q.u + ox, q.v, z1, th));
    put(sd, { sil: poly(hull(pts)), crease: inner ? open(run(inner, front).map((q) => T(q.u + ox, q.v, z1, th))) : "" });
  };

  const [body, bodyIn] = rings(-40, -16, 40, 16, 6, 1.6);
  put(solid(g), prism(P, front, body, bodyIn, 0, H));
  // dials on the front face, y = 16
  const dials = [-20, 20].map((cx, i) => {
    const ring = (R) => Array.from({ length: 40 }, (_, k) => { const t = (k / 40) * Math.PI * 2; return P(cx + R * Math.cos(t), 16, 17 + R * Math.sin(t)); });
    mk("path", { class: "sil", d: poly(ring(12)) }, g);
    mk("path", { class: "nf lo", d: poly(ring(10)) }, g);
    const ticks = [];
    for (let k = 0; k < 12; k++) { const t = (k / 12) * Math.PI * 2; ticks.push(seg(P(cx + 8.4 * Math.cos(t), 16, 17 + 8.4 * Math.sin(t)), P(cx + 9.6 * Math.cos(t), 16, 17 + 9.6 * Math.sin(t)))); }
    mk("path", { class: "nf lo", d: ticks.join("") }, g);
    const hand = mk("path", { class: "nf" }, g);
    const flag = mk("path", { class: "nf lo", d: open([P(cx + 2, 16, 27.5), P(cx + 4.5, 16, 31), P(cx, 16, 31.5)]) }, g);
    return { cx, hand, flag, tw: tween(i ? 0.6 : 0.25), drawn: NaN };
  });
  put(solid(g), prism(P, front, rings(-5, -6, 5, 6, 2, 0.8)[0], null, H, PZ));
  const rock = solid(g);
  const [rr, ri] = rings(-38, -6, 38, 6, 3, 1);
  const btns = [-BX, BX].map(() => solid(g));
  const bring = circ(7.5, 24), binner = circ(6.3, 24);
  const tilt = tween(A), state = { drawn: NaN }, sw = { v: value };

  function draw(now) {
    const th = tval(tilt, now);
    if (th !== state.drawn) {
      state.drawn = th;
      tilted(rock, rr, ri, PZ, PZ + 3, 0, th);
      tilted(btns[0], bring, binner, PZ + 3, PZ + 12, -BX, th);
      tilted(btns[1], bring, binner, PZ + 3, PZ + 12, BX, th);
    }
    for (const d of dials) {
      const a = tval(d.tw, now) * Math.PI * 2;
      if (a === d.drawn) continue;
      d.drawn = a;
      d.hand.setAttribute("d", seg(P(d.cx - 2 * Math.sin(a), 16, 17 - 2 * Math.cos(a)), P(d.cx + 9 * Math.sin(a), 16, 17 + 9 * Math.cos(a))));
    }
  }
  const B = register(stage, (dt, now) => { draw(now); return !tdone(tilt, now) || dials.some((d) => !tdone(d.tw, now)); });
  bag.add(B.unregister);

  let side = -1;
  const bx = [P(-BX, 0, PZ)[0], P(BX, 0, PZ)[0]];
  function choose(s) {
    if (s === side) return;
    side = s;
    const now = performance.now();
    tset(tilt, s === 1 ? -A : A, now, 0);
    dials.forEach((d, i) => tset(d.tw, s === i ? (i ? 0.6 : 0.25) + 0.42 * sw.v : i ? 0.6 : 0.25, now, 60));
    btns[0].sil.classList.toggle("hi", s !== 1);
    btns[1].sil.classList.toggle("hi", s === 1);
    read.textContent = s === 0 ? "white" : s === 1 ? "black" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      if (p[1] < 40 || p[1] > 300 || Math.abs(p[0] - 200) > 150) return choose(-1);
      choose(Math.abs(p[0] - bx[0]) < Math.abs(p[0] - bx[1]) ? 0 : 1);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  side = -2; choose(-1); draw(performance.now());
  return { set: (v) => { sw.v = v; const s = side; side = -2; choose(s); }, destroy: bag.dispose };
}

hairline({
  name: "chessclock",
  means: "A chess clock: the rocker see-saws down on the pointer's side and that player's hand sweeps round its dial.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[250, 140], [150, 90], [171, 193], null],
  mount,
});

pinballflip.code:
/**
 * Flipper: the foot of a pinball table seen from the player's end, two
 * flippers on their pivots, three round bumpers up the field and a ball. The
 * pointer picks a side: that flipper swings up and the ball is struck across
 * the field toward the bumpers. At rest both flippers hang down and the ball,
 * bright, waits between them.
 *
 * The pattern: a discrete choice between two sides (tween); the hit is on the
 * ground plane, read in the table's own axes, which never move.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, unproj,
  tween, tset, tval, tdone, disposer, mk, place, pointer, put, register, solid,
} = HL;

const Z = 4, ROT = -Math.PI / 4, c = Math.cos(ROT), s = Math.sin(ROT);
const W = (u, v) => [u * c - v * s, u * s + v * c];
const turn = (ring) => ring.map((q) => { const [x, y] = W(q.u, q.v); const [nx, ny] = W(q.nu, q.nv); return { u: x, v: y, nu: nx, nv: ny }; });
const shift = (ring, du, dv) => ring.map((q) => ({ ...q, u: q.u + du, v: q.v + dv }));
const FL = [{ pu: -28, pv: 34, down: 38, up: -30 }, { pu: 28, pv: 34, down: 142, up: 210 }];
const BALL = [[0, 18], [16, -12], [-16, -12]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  const ext = [];
  for (const [u, v] of [[-42, -62], [42, -62], [-42, 62], [42, 62]]) { const [x, y] = W(u, v); ext.push([x, y, 0], [x, y, 14]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-42, -62, 42, 62, 10, 1.8);
  put(solid(g), prism(P, front, turn(fr), turn(fi), 0, Z));
  for (const [u, v] of [[0, -48], [-17, -36], [17, -36]]) {
    put(solid(g), prism(P, front, turn(shift(circ(6.5, 24), u, v)), turn(shift(circ(5.3, 24), u, v)), Z, Z + 9));
  }
  const ball = mk("ellipse", { class: "sil hi", rx: 6 * C.S, ry: 6 * C.S }, g);
  const btw = [tween(BALL[0][0]), tween(BALL[0][1])];
  // flipper outline in its own frame: pivot round r 5.5, tip round r 3, 28 long
  const shape = (r0, r1) => {
    const pts = [];
    for (let k = 0; k < 24; k++) { const t = (k / 24) * Math.PI * 2; pts.push([r0 * Math.cos(t), r0 * Math.sin(t)], [32 + r1 * Math.cos(t), r1 * Math.sin(t)]); }
    return hull(pts);
  };
  const outer = shape(5.5, 3), inner = shape(4.3, 1.9);
  const fl = FL.map((f) => ({ ...f, sd: solid(g), tw: tween(f.down + (f.pu < 0 ? -4 : 4)), drawn: NaN }));
  const at = (f, pts, a, z) => pts.map(([px, py]) => { const u = f.pu + px * Math.cos(a) - py * Math.sin(a), v = f.pv + px * Math.sin(a) + py * Math.cos(a); const [x, y] = W(u, v); return P(x, y, z); });

  function draw(now) {
    for (const f of fl) {
      const a = (tval(f.tw, now) * Math.PI) / 180;
      if (a === f.drawn) continue;
      f.drawn = a;
      f.sd.sil.setAttribute("d", poly(hull(at(f, outer, a, Z).concat(at(f, outer, a, Z + 5)))));
      f.sd.cr.setAttribute("d", poly(at(f, inner, a, Z + 5)));
    }
    const [x, y] = W(tval(btw[0], now), tval(btw[1], now));
    place(ball, P(x, y, Z + 6));
  }
  const B = register(stage, (dt, now) => { draw(now); return fl.some((f) => !tdone(f.tw, now)) || !tdone(btw[0], now) || !tdone(btw[1], now); });
  bag.add(B.unregister);

  let side = -2;
  function choose(sd) {
    if (sd === side) return;
    side = sd;
    const now = performance.now();
    fl.forEach((f, i) => {
      tset(f.tw, sd === i ? f.down + (f.up - f.down) * clampV() : f.down + (sd === -1 && i === 0 ? -4 : i ? 4 : -4), now, 0);
      f.sd.sil.classList.toggle("hi", sd === i);
    });
    const b = BALL[sd + 1];
    tset(btw[0], b[0], now, 40); tset(btw[1], b[1], now, 40);
    ball.classList.toggle("hi", sd === -1);
    read.textContent = sd === 0 ? "left" : sd === 1 ? "right" : "rest";
    B.wake();
  }
  let reach = value;
  const clampV = () => Math.min(1.2, Math.max(0.4, reach));
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], Z), u = 0.7071 * (x - y), v = 0.7071 * (x + y);
      if (Math.abs(u) > 56 || v < -76 || v > 66) return choose(-1);
      choose(u < 0 ? 0 : 1);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  choose(-1); draw(performance.now());
  return { set: (v) => { reach = v; const sd = side; side = -2; choose(sd); }, destroy: bag.dispose };
}

hairline({
  name: "pinballflip",
  means: "Two pinball flippers: the one on the pointer's side swings up and strikes the ball across the field.",
  rules: [1, 4, 5, 8],
  range: [0.6, 1, 1.2],
  tour: [[277, 220], [123, 220], [200, 107], null],
  mount,
});

arcadestick.code:
/**
 * Arcade cabinet: a bartop cabinet, its screen standing behind a control
 * panel with a ball-top stick and two buttons. The stick leans toward the
 * pointer on its own spring and the sprite on the screen slides the same way.
 * At rest the stick leans to the left, its ball bright.
 *
 * The pattern: a continuous aim (spring per axis); the hit is the panel's
 * plane, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const PT = 40, SX = -6, SY = 8, L = 35, REST = [-0.4, 0.22];
const shift = (ring, du, dv) => ring.map((q) => ({ ...q, u: q.u + du, v: q.v + dv }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-26, -22, 0], [26, 22, 0], [-26, -22, 94], [26, -4, 94], [26, 22, PT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-26, -22, 26, 22, 5, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, PT));
  const [ur, ui] = rings(-26, -22, 26, -4, 5, 1.6);
  put(solid(g), prism(P, front, ur, ui, PT, 94));
  const sc = (x, z) => P(x, -4, z);
  mk("path", { class: "sil", d: poly([sc(-20, 48), sc(20, 48), sc(20, 86), sc(-20, 86)]) }, g);
  mk("path", { class: "nf lo", d: seg(sc(-17, 54), sc(17, 54)) }, g);
  const sprite = mk("path", { class: "nf" }, g);
  for (const [u, v] of [[10, 4], [16, 12]]) put(solid(g), prism(P, front, shift(circ(3.6, 20), u, v), shift(circ(2.6, 20), u, v), PT, PT + 2.2));
  put(solid(g), prism(P, front, shift(circ(4.5, 24), SX, SY), shift(circ(3.4, 24), SX, SY), PT, PT + 1.5));
  const shaft = mk("path", { class: "nf sil" }, g);
  const ball = mk("ellipse", { class: "sil hi", rx: 7.5 * C.S, ry: 7.5 * C.S }, g);
  const ax = spring(REST[0]), ay = spring(REST[1]);
  let drawn = "", gain = value;

  function draw() {
    const a = ax.x, b = ay.x, key = a.toFixed(4) + b.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const top = [SX + L * Math.sin(a), SY + L * Math.sin(b), PT + 1.5 + L * Math.cos(Math.hypot(a, b))];
    shaft.setAttribute("d", seg(P(SX, SY, PT + 1.5), P(top[0], top[1], top[2] - 6)));
    place(ball, P(...top));
    const px = clamp((a - b) * 30, -8, 8), pz = clamp(67 - (a + b) * 24, 59, 75);
    sprite.setAttribute("d", poly([sc(px - 11, pz - 10), sc(px + 11, pz - 10), sc(px + 11, pz + 10), sc(px - 11, pz + 10)]));
  }
  const B = register(stage, (dt) => { const m1 = stepS(ax, dt), m2 = stepS(ay, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { ax.t = REST[0]; ay.t = REST[1]; read.textContent = "rest"; return B.wake(); }
    const [x, y] = unproj(C, p[0], p[1], PT), dx = x - SX, dy = y - SY, d = Math.hypot(dx, dy) || 1;
    const m = clamp(d / 30, 0, 1) * 1.05 * gain;
    ax.t = (dx / d) * m; ay.t = (dy / d) * m;
    const dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? "R" : "L") : dy > 0 ? "D" : "U";
    read.textContent = m < 0.1 ? "mid" : "stick " + dir;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => aim(p[0] < 40 || p[0] > 360 || p[1] < 20 || p[1] > 305 ? null : p),
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null); draw();
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

hairline({
  name: "arcadestick",
  means: "A bartop arcade cabinet: its ball-top stick leans toward the pointer and the sprite on the screen slides along.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[214, 209], [108, 206], [164, 140], null],
  mount,
});

sewingdummy.code:
/**
 * Mannequin bust: a dress form on a pole and round foot, hips, waist, bust
 * and broad shoulders, with princess seams down its front. The pointer
 * turns it: move across and the bust swings round on its pole to face that
 * way, its seams sliding round the body and out of sight. At rest it stands
 * a quarter turned, its neck cap bright. The slider is how far it turns.
 *
 * The pattern: one part turning to face the pointer (turn).
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, ringAt, run, clamp, rad,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const LOW = [[56, 22, 16], [62, 24, 17], [74, 18, 13]];
const UP = [[74, 18, 13], [92, 25, 18], [104, 30, 15], [110, 24, 12]];
const REST = 35;
function ell(a, b, th, n = 32) {
  const c = Math.cos(th), s = Math.sin(th), out = [];
  for (let i = 0; i < n; i++) {
    const t = (i / n) * Math.PI * 2, u = a * Math.cos(t), v = b * Math.sin(t), nu = b * Math.cos(t), nv = a * Math.sin(t), l = Math.hypot(nu, nv);
    out.push({ u: u * c - v * s, v: u * s + v * c, nu: (nu * c - nv * s) / l, nv: (nu * s + nv * c) / l });
  }
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-34, -34, 0], [34, 34, 0], [-34, 34, 0], [34, -34, 0], [-30, 30, 106], [30, -30, 106], [0, 0, 126]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(32, 48), circ(29.5, 48), 0, 5));
  put(solid(g), prism(P, front, circ(3, 16), circ(2, 16), 5, 57));
  const lower = mk("path", { class: "sil" }, g), upper = mk("path", { class: "sil" }, g), seams = mk("path", { class: "nf lo" }, g);
  const neck = solid(g), cap = solid(g);
  put(neck, prism(P, front, circ(7, 24), circ(5.5, 24), 108, 121));
  put(cap, prism(P, front, circ(9, 24), circ(7.5, 24), 121, 124));
  const s = spring(REST);
  let last = NaN;

  const body = (secs, th) => poly(hull([].concat(...secs.map(([z, a, b]) => ringAt(P, ell(a, b, th), z)))));
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg), c = Math.cos(th), sn = Math.sin(th);
    lower.setAttribute("d", body(LOW, th));
    upper.setAttribute("d", body(UP, th));
    let d = "";
    for (const f of [-0.45, 0.45]) {
      const pts = [];
      for (const [z, a, b] of LOW.slice(1).concat(UP.slice(1, 3))) {
        const u = f * a, v = b * Math.sqrt(1 - f * f) * 0.98, nu = f, nv = 1;
        if (front({ u: 0, v: 0, nu: nu * c - nv * sn, nv: nu * sn + nv * c })) pts.push(P(u * c - v * sn, u * sn + v * c, z));
      }
      if (pts.length > 1) d += open(pts) + " ";
    }
    seams.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(s.x); return m; });
  bag.add(B.unregister);

  const cx = P(0, 0, 0)[0];
  let act = null;
  function setA(a) {
    s.t = a === null ? REST : a;
    read.textContent = a === null ? "rest" : Math.round(a) + "°";
    const on = a !== null;
    if (on !== act) { act = on; upper.classList.toggle("hi", on); cap.sil.classList.toggle("hi", !on); }
    B.wake();
  }
  function hit([sx, sy]) {
    if (sy < 20 || sy > 300 || Math.abs(sx - cx) > 150) return null;
    return clamp((sx - cx) / 110, -1, 1) * reach;
  }
  setA(null);
  bag.add(pointer(stage, { move: (p) => setA(hit(p)), leave: () => setA(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "sewingdummy",
  means: "A dress form on its pole: move across it and the bust turns to face that way, its front seams swinging round.",
  rules: [1, 3, 5, 8],
  range: [60, 110, 160],
  tour: [[200, 142], [322, 142], [78, 142], null],
  mount,
});

zipper.code:
/**
 * Zipper: a zip lying flat, two tapes meeting along a row of teeth, the
 * slider riding the row with its pull tab. The pointer slides the slider
 * along the zip: ahead of it the teeth stay meshed, behind it the tapes
 * part in a widening V. At rest the zip is a third open and the tab is
 * bright. The slider is how wide the tapes spread.
 *
 * The pattern: one continuous value along a track (slide).
 */
const {
  Cam, fit, facing, fillet, poly, open, prism, proj, rings, unproj, clamp,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const L = 170, W = 17, ZT = 1.5, REST = L * 0.4, DX = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let spread = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-26, -50, 0], [L + 4, -50, 0], [L + 4, 50, 0], [-26, 50, 0], [0, 0, 8]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const tapes = [-1, 1].map((sd) => ({ sd, edge: mk("path", { class: "nf lo" }, g), face: mk("path", { class: "sil" }, g) }));
  const teeth = mk("path", { class: "nf lo" }, g);
  const body = solid(g), tab = solid(g);
  const s = spring(REST);
  let last = NaN;

  const gap = (x, at) => clamp((x - at) * spread, 0, 24);
  function draw(at) {
    if (at === last) return;
    last = at;
    for (const t of tapes) {
      const inn = [], out = [];
      for (let x = 0; x <= L; x += DX) { const gp = gap(x, at); inn.push([x, t.sd * gp]); out.push([x, t.sd * (gp + W)]); }
      const pts = inn.concat(out.reverse()).map(([x, y]) => P(x, y, ZT)), n = inn.length;
      const rad = pts.map((_, i) => (i === 0 || i === n - 1 || i === n || i === 2 * n - 1 ? 5 : 0));
      t.face.setAttribute("d", poly(fillet(pts, rad)));
      const lo = (t.sd > 0 ? out.slice().reverse() : [[L, t.sd * (gap(L, at) + W)], [L, t.sd * gap(L, at)]]).map(([x, y]) => P(x, y, 0));
      t.edge.setAttribute("d", open(lo));
    }
    let d = "";
    for (let i = 0, x = 3; x < L - 2; i++, x += 6) {
      const sd = i % 2 ? 1 : -1, yi = sd * gap(x, at), a = yi - sd * 2.6, b = yi + sd * 3.2;
      d += poly([P(x - 2, a, ZT), P(x + 2, a, ZT), P(x + 2, b, ZT), P(x - 2, b, ZT)]) + " ";
    }
    teeth.setAttribute("d", d);
    const [br, bi] = rings(at - 10, -8, at + 10, 8, 5, 1.6);
    put(body, prism(P, front, br, bi, ZT, ZT + 6));
    const [tr, ti] = rings(at - 30, -5, at - 8, 5, 4, 1.4);
    put(tab, prism(P, front, tr, ti, ZT + 6, ZT + 7.6));
  }

  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(s.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setAt(x) {
    s.t = x === null ? REST : clamp(x, 32, L - 10);
    if (x === null) read.textContent = "rest"; else read.textContent = Math.round((1 - s.t / L) * 100) + "%";
    const on = x !== null;
    if (on !== act) { act = on; body.sil.classList.toggle("hi", on); tab.sil.classList.toggle("hi", !on); }
    B.wake();
  }
  setAt(null);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return Math.abs(y) < 52 && x > -30 && x < L + 14 ? x : null;
  }
  bag.add(pointer(stage, { move: (p) => setAt(hit(p)), leave: () => setAt(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { spread = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "zipper",
  means: "A zip lying flat: the pointer slides the pull along the teeth, and behind it the two tapes part in a widening V.",
  rules: [1, 3, 5, 8],
  range: [0.2, 0.45, 0.7],
  tour: [[154, 145], [287, 212], [253, 240], null],
  mount,
});

towelwarmer.code:
/**
 * Towel warmer: a spa cabinet on a low plinth, two doors hinged at its outer
 * edges, rolled towels stacked on the shelves behind them. The pointer picks
 * a door by where it stands: the door swings open on its hinge to show the
 * rolls, and the other door eases a little ajar after it. At rest the right
 * door stands ajar, bright. The slider is the stagger.
 *
 * The pattern: one of two, each swinging on a vertical hinge.
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 92, D = 46, Z0 = 8, Z1 = 92, HW = W / 2, OPEN = 112, FAV = 1, T = 2.4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-4, -4, 0], [W + 4, -4, Z1 + 4], [W + 18, D + HW, Z1], [-18, D + HW, 0], [W + 4, D + 4, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, W + 4, D + 4, 4, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, Z0));
  const [br, bi] = rings(0, 0, W, D, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  // the opening, a shelf, and the rolled towels on it
  const fr = (x0, z0, x1, z1) => [[x0, D, z0], [x1, D, z0], [x1, D, z1], [x0, D, z1]].map((p) => P(...p));
  mk("path", { d: poly(fillet(fr(5, Z0 + 5, W - 5, Z1 - 5), [3, 3, 3, 3])), class: "nf lo" }, g);
  const mid = (Z0 + Z1) / 2;
  mk("path", { d: poly(fr(5, mid - 1, W - 5, mid + 1)), class: "nf lo" }, g);
  const roll = (cx, cz, r) => { const pts = []; for (let i = 0; i < 24; i++) { const t = (i / 24) * 2 * Math.PI; pts.push(P(cx + r * Math.cos(t), D, cz + r * Math.sin(t))); } return poly(pts); };
  for (const cz of [Z0 + 5 + 10, mid + 1 + 10]) for (let c = 0; c < 4; c++) {
    const cx = 15 + c * 20.5;
    mk("path", { d: roll(cx, cz, 9.5), class: "nf" }, g);
    mk("path", { d: roll(cx + 1, cz, 4), class: "nf lo" }, g);
  }

  const doors = [0, 1].map((k) => {
    const grp = mk("g", {}, g);
    const rest = k === FAV ? 30 : 4;
    return { k, grp, sil: mk("path", { class: "sil" }, grp), face: mk("path", { class: "nf lo" }, grp), bar: mk("path", { class: "nf" }, grp), rest, a: tween(rest), last: NaN };
  });
  // a point on a door: w from its hinge, z up, o out along its normal
  const at = (k, a, w, z, o) => {
    const s = Math.sin(rad(a)), c = Math.cos(rad(a)), dir = k === 0 ? 1 : -1;
    return P((k === 0 ? 0.6 : W - 0.6) + dir * (w * c - o * s), D + 0.4 + w * s + o * c, z);
  };
  const DW = HW - 1.2;
  function draw(d, a) {
    if (a === d.last) return;
    d.last = a;
    const pts = [];
    for (const o of [0, T]) for (const [w, z] of [[0, Z0 + 1], [DW, Z0 + 1], [DW, Z1 - 1], [0, Z1 - 1]]) pts.push(at(d.k, a, w, z, o));
    const hl = hull(pts);
    d.sil.setAttribute("d", poly(fillet(hl, hl.map(() => 3))));
    const show = d.k === 0 ? a < 95 : true;
    d.face.setAttribute("d", show ? poly(fillet([[3, Z0 + 4], [DW - 3, Z0 + 4], [DW - 3, Z1 - 4], [3, Z1 - 4]].map(([w, z]) => at(d.k, a, w, z, T)), [3, 3, 3, 3])) : "");
    d.bar.setAttribute("d", show ? poly(fillet([[DW - 8, mid - 12], [DW - 5, mid - 12], [DW - 5, mid + 12], [DW - 8, mid + 12]].map(([w, z]) => at(d.k, a, w, z, T + 0.6)), [1.5, 1.5, 1.5, 1.5])) : "");
  }
  // the left door, swung out toward the viewer, is nearer than the right one
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of doors) { draw(d, tval(d.a, now)); if (!tdone(d.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);
  doors[1].grp.after(doors[0].grp);

  const mids = [P(HW / 2, D, mid), P(W - HW / 2, D, mid)];
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 50 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    doors.forEach((d, k) => {
      const to = a < 0 ? d.rest : k === a ? OPEN : 14;
      tset(d.a, to, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      d.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : a === 0 ? "door L" : "door R";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "towelwarmer",
  means: "A towel warmer cabinet: the door under the pointer swings open on its hinge to show the rolled towels, the other eases ajar.",
  rules: [1, 2, 5, 6],
  range: [0, 60, 120],
  tour: [[178, 132], [206, 101], [235, 160], null],
  mount,
});

traycart.code:
/**
 * Ice machine: a hotel corridor ice machine on short feet, a vent grille
 * up top and a bin below behind a door hinged along its foot, ice cubes
 * heaped inside with a scoop hooked on the wall of the bin. The pointer over
 * the machine tips the bin door down and out on its hinge; the further down
 * the pointer, the further it opens. At rest the door stands a crack ajar,
 * bright. The slider is how far it may open.
 *
 * The pattern: one part swinging on a hinge, following the pointer.
 */
const {
  Cam, clamp, fit, facing, fillet, hull, lerp, poly, prism, proj, rings, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 70, D = 56, Z0 = 6, Z1 = 128, BZ0 = 14, BZ1 = 70, REST = 12, T = 2.4;

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[0, 0, 0], [W, 0, Z1], [W, D + 60, BZ0], [0, D + 60, BZ0], [W, D, 0]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const [x, y] of [[6, 6], [W - 6, 6], [6, D - 6], [W - 6, D - 6]]) {
    const [fr, fi] = rings(x - 3, y - 3, x + 3, y + 3, 2, 0.8);
    put(solid(g), prism(P, front, fr, fi, 0, Z0));
  }
  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  const fp = (pts) => pts.map(([x, z]) => P(x, D, z));
  // the vent grille and the bin's opening
  for (let i = 0; i < 5; i++) mk("path", { d: poly(fillet(fp([[12, 92 + i * 6], [W - 12, 92 + i * 6], [W - 12, 94.5 + i * 6], [12, 94.5 + i * 6]]), [1, 1, 1, 1])), class: "nf lo" }, g);
  mk("path", { d: poly(fillet(fp([[6, BZ0], [W - 6, BZ0], [W - 6, BZ1], [6, BZ1]]), [3, 3, 3, 3])), class: "nf lo" }, g);
  // the heap of cubes and the scoop hooked on the bin's wall
  for (const [x, z, s] of [[12, 18, 11], [24, 18, 11], [36, 18, 11], [48, 18, 11], [18, 29, 10], [30, 29, 10], [42, 29, 10], [26, 39, 9], [37, 39, 9]])
    mk("path", { d: poly(fillet(fp([[x, z], [x + s, z], [x + s, z + s], [x, z + s]]), [2.5, 2.5, 2.5, 2.5])), class: "nf" }, g);
  mk("path", { d: poly(fillet(fp([[50, 36], [62, 36], [62, 52], [50, 52]]), [4, 4, 4, 4])), class: "nf" }, g);
  mk("path", { d: poly(fillet(fp([[54, 52], [58, 52], [58, 66], [54, 66]]), [1.5, 1.5, 1.5, 1.5])), class: "nf" }, g);

  const dg = mk("g", {}, g);
  const ds = mk("path", { class: "sil hi" }, dg), df = mk("path", { class: "nf lo" }, dg), dh = mk("path", { class: "nf" }, dg);
  const sp = spring(REST);
  let last = NaN;
  // a point on the door: u across, h up from the hinge, o out along its normal
  const at = (a, u, h, o) => {
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    return P(u, D + 0.4 + h * s + o * c, BZ0 - 4 + h * c - o * s);
  };
  const HD = BZ1 + 4 - (BZ0 - 4);
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const o of [0, T]) for (const [u, h] of [[2, 0], [W - 2, 0], [W - 2, HD], [2, HD]]) pts.push(at(a, u, h, o));
    const hl = hull(pts);
    ds.setAttribute("d", poly(fillet(hl, hl.map(() => 3))));
    const show = a < 88;
    df.setAttribute("d", show ? poly(fillet([[6, 4], [W - 6, 4], [W - 6, HD - 4], [6, HD - 4]].map(([u, h]) => at(a, u, h, T)), [3, 3, 3, 3])) : "");
    dh.setAttribute("d", show ? poly(fillet([[W / 2 - 14, HD - 12], [W / 2 + 14, HD - 12], [W / 2 + 14, HD - 8], [W / 2 - 14, HD - 8]].map(([u, h]) => at(a, u, h, T + 0.8)), [1.5, 1.5, 1.5, 1.5])) : "");
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const yTop = P(W / 2, D, Z1)[1], yLow = P(W / 2, D, BZ0)[1];
  function move([sx, sy]) {
    const t = clamp((sy - yTop) / (yLow - yTop), 0, 1);
    sp.t = lerp(REST, reach, t);
    read.textContent = "door " + Math.round(sp.t) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

