wineopener.code:
/**
 * Wine opener: a bottle standing on a coaster with a lever corkscrew clamped
 * on its neck. The pointer sweeps the long lever over the top on a spring:
 * the further left it goes, the higher the lever swings and the further the
 * cork draws out of the neck. At rest the lever lies forward, part raised,
 * bright. The slider is how far the lever may swing.
 *
 * The pattern: one part turning on a pivot, following the pointer.
 */
const {
  Cam, circ, clamp, fit, facing, fillet, hull, lerp, poly, prism, proj, ringAt, rings, rad, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 17, NZ = 96, OZ = 104, OH = 16, L = 70, REST = 22;
const disc = (r, n = 32) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.7);
  const top = OZ + OH;
  fit(C, [[-26, -26, 0], [26, 26, 0], [L + 4, 0, top + 34], [-L * 0.95, 0, top + L * 0.4], [0, 0, top + L + 6]], 200, 154);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-26, -26, 26, 26, 22, 2);
  put(solid(g), prism(P, front, cr, ci, 0, 4));
  // the bottle: body, then a shoulder that tapers into the neck
  put(solid(g), prism(P, front, disc(R), disc(R - 2), 4, 64));
  const sh = [];
  for (const [r, z] of [[R, 64], [R * 0.85, 74], [R * 0.55, 82], [6.5, 88], [6.5, NZ]]) sh.push(...ringAt(P, disc(r), z));
  mk("path", { d: poly(hull(sh)), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, disc(R - 1.5), 40)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(R - 1.5), 22)), class: "nf lo" }, g);
  // the cork, drawn out of the neck
  const cork = solid(g);
  // the opener's body clamped on the neck, with its pivot pin
  const og = mk("g", {}, g);
  const [orr, oi] = rings(-9, -9, 9, 9, 6, 1.6);
  put(solid(og), prism(P, front, orr, oi, OZ - 12, OZ + OH));
  const lev = mk("g", {}, g);
  const ls = mk("path", { class: "sil hi" }, lev), lc = mk("path", { class: "nf lo" }, lev);
  const sp = spring(REST);
  let last = NaN;

  // a point on the lever: s along it from the pivot, w across, h up from its face
  const at = (a, s, w, h) => {
    const c = Math.cos(rad(a)), n = Math.sin(rad(a));
    return P(s * c - h * n, w, top + s * n + h * c);
  };
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const w of [-6, 6]) for (const [s, h] of [[-6, -3], [L, -3], [L, 3], [-6, 3]]) pts.push(at(a, s, w, h));
    const hl = hull(pts);
    ls.setAttribute("d", poly(fillet(hl, hl.map(() => 3))));
    lc.setAttribute("d", poly(fillet([[2, -3.5, 3], [L - 6, -3.5, 3], [L - 6, 3.5, 3], [2, 3.5, 3]].map(([s, w, h]) => at(a, s, w, h)), [2, 2, 2, 2])));
    const lift = clamp((a - REST) / (150 - REST), 0, 1) * 30;
    put(cork, prism(P, front, disc(4.6, 20), disc(3.4, 20), OZ + OH - 14 + lift, OZ + OH + 2 + lift));
    // past upright the lever passes behind the opener's body
    if (a > 95) og.after(lev); else lev.after(og);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const mid = P(0, 0, 60)[0];
  function move([sx, sy]) {
    const t = clamp((mid + 70 - sx) / 140, 0, 1);
    sp.t = lerp(REST, reach, t);
    read.textContent = "lever " + Math.round(sp.t) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "wineopener",
  means: "A lever corkscrew on a wine bottle: the pointer sweeps the long lever up over the top and the cork draws out of the neck.",
  rules: [1, 3, 5, 8],
  range: [90, 150, 170],
  tour: [[292, 194], [195, 194], [99, 194], null],
  mount,
});

concretemix.code:
/**
 * Wheel mixer: a bellied mortar drum hung between two posts on a skid with a
 * wheel at each end. The pointer's place in front of or behind the mixer is
 * how far the drum tips on its trunnions: toward the reader to pour, back to
 * take a load, on a spring. The read-out gives the tilt. At rest the drum
 * leans a little forward, its mouth bright. The slider is the farthest pour.
 *
 * The pattern: a continuous lean read on the ground plane, which never moves.
 */
const {
  Cam, clamp, fit, proj, rings, prism, facing, spring, stepS, unproj, poly, open, hull, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZP = 38, PX = 29, REST = 16, BACK = -24;
const BANDS = [[-15, 15], [-6, 22], [4, 23.5], [13, 19], [21, 13]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let pour = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-44, -26, 0], [44, 26, 0], [-44, 30, 0], [0, 34, ZP + 10], [0, -34, ZP + 10], [0, 0, ZP + 28]], 200, 160);
  const P = proj(C), front = facing(C);
  const N = 28, ca = Math.cos(rad(45)) * Math.sqrt(0.75), cz = 0.5;

  const g = mk("g", {}, svg);
  const wheel = (x0) => {
    const pts = [];
    for (let k = 0; k < N; k++) { const t = (k / N) * 2 * Math.PI; for (const x of [x0, x0 + 3]) pts.push(P(x, 10 * Math.cos(t), 10 + 10 * Math.sin(t))); }
    const el = solid(g); el.sil.setAttribute("d", poly(hull(pts)));
    const hub = []; for (let k = 0; k <= N; k++) { const t = (k / N) * 2 * Math.PI; hub.push(P(x0 + 3, 3 * Math.cos(t), 10 + 3 * Math.sin(t))); }
    el.cr.setAttribute("d", open(hub));
  };
  const post = (x) => { const [r, i] = rings(x - 2.5, -3, x + 2.5, 3, 1.5, 0.8); put(solid(g), prism(P, front, r, i, 4, ZP + 4)); };
  wheel(-42);
  { const [r, i] = rings(-36, -9, 36, 9, 3, 1.2); put(solid(g), prism(P, front, r, i, 6, 10)); }
  post(-PX);
  const drum = solid(g), mouth = mk("path", { class: "sil hi" }, drum.g), lip = mk("path", { class: "nf lo" }, drum.g);
  post(PX);
  wheel(39);

  const tilt = spring(REST);
  let last = "";
  function at(th, h, r, t) { // a point of the drum: ring at local height h, radius r, angle t, tipped th toward +y
    const x = r * Math.cos(t), y = r * Math.sin(t), c = Math.cos(th), s = Math.sin(th);
    return P(x, y * c + h * s, ZP - y * s + h * c);
  }
  function draw(deg) {
    const key = deg.toFixed(2);
    if (key === last) return;
    last = key;
    const th = rad(deg), pts = [];
    for (const [h, r] of BANDS) for (let k = 0; k < N; k++) pts.push(at(th, h, r, (k / N) * 2 * Math.PI));
    drum.sil.setAttribute("d", poly(hull(pts)));
    const B = ca * Math.cos(th) - cz * Math.sin(th), t0 = Math.atan2(B, ca), band = [];
    for (let k = 0; k <= 16; k++) band.push(at(th, 4, 23.5, t0 - Math.PI / 2 + (k / 16) * Math.PI));
    drum.cr.setAttribute("d", open(band));
    const m = [], l = [];
    for (let k = 0; k < N; k++) { const t = (k / N) * 2 * Math.PI; m.push(at(th, 21, 13, t)); l.push(at(th, 21, 10.5, t)); }
    mouth.setAttribute("d", poly(m)); lip.setAttribute("d", poly(l));
  }
  draw(REST);

  const Bk = register(stage, (dt) => { const mv = stepS(tilt, dt); draw(tilt.x); return mv; });
  bag.add(Bk.unregister);

  function leave() { tilt.t = REST; read.textContent = "rest"; Bk.wake(); }
  function move(p) {
    const [wx, wy] = unproj(C, p[0], p[1], 0);
    if (Math.abs(wx) > 60 || Math.abs(wy) > 70) return leave();
    tilt.t = clamp(wy * 1.6, BACK, pour);
    read.textContent = Math.round(tilt.t) + "°";
    Bk.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { pour = v; }, destroy: bag.dispose };
}

hairline({
  name: "concretemix",
  means: "A wheel mixer's bellied drum hung on two posts: it tips toward the pointer to pour, or back to load, and settles leaning forward.",
  rules: [1, 3, 5, 8],
  range: [30, 45, 60],
  tour: [[271, 183], [200, 218], [165, 236], null],
  mount,
});

ladderext.code:
/**
 * Extension ladder: a two-section ladder lying on the ground, the fly section
 * riding on top of the base on its rails, a pair of hooked locks at its foot.
 * The pointer's place along the ladder is where the fly's head goes: the fly
 * slides out or back on a spring, and the read-out gives the overlap. At rest
 * the fly is half out, bright. The slider is the farthest it may run.
 *
 * The pattern: a continuous reach read on the ground plane, which never moves.
 */
const {
  Cam, clamp, fit, prism, proj, rings, seg, spring, stepS, unproj, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 100, Wd = 30, R = 3, REST = 34, MIN = 8, STEP = 11;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [L + 80, 0, 0], [0, Wd, 0], [L + 80, Wd, 0], [0, 0, 10]], 200, 168);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const rail = (par, x0, x1, y0, z0, z1) => { const [r, i] = rings(x0, y0, x1, y0 + R, 1.2, 0.5); put(solid(par), prism(P, front, r, i, z0, z1)); };
  rail(g, 0, L, 0, 0, 4);
  const rungs = mk("path", { class: "nf" }, g);
  { let d = ""; for (let x = 6; x < L; x += STEP) d += seg(P(x, R, 2), P(x, Wd - R, 2)); rungs.setAttribute("d", d); }
  rail(g, 0, L, Wd - R, 0, 4);

  const fly = mk("g", {}, g);
  const far = solid(fly), fr = mk("path", { class: "nf" }, fly), near = solid(fly), locks = mk("path", { class: "nf lo" }, fly);
  const ext = spring(REST);
  let last = "";
  function draw(e) {
    const key = e.toFixed(2);
    if (key === last) return;
    last = key;
    const x0 = e, x1 = e + L, z0 = 4.4, z1 = 8;
    let [r, i] = rings(x0, 1.5, x1, 1.5 + R, 1.2, 0.5); put(far, prism(P, front, r, i, z0, z1));
    [r, i] = rings(x0, Wd - 1.5 - R, x1, Wd - 1.5, 1.2, 0.5); put(near, prism(P, front, r, i, z0, z1));
    let d = ""; for (let x = x0 + 6; x < x1; x += STEP) d += seg(P(x, 1.5 + R, 6.2), P(x, Wd - 1.5 - R, 6.2));
    fr.setAttribute("d", d);
    let k = ""; for (const y of [1.5 + R / 2, Wd - 1.5 - R / 2]) k += seg(P(x0 + 3, y, z1), P(x0 + 3, y, z1 + 3)) + seg(P(x0 + 3, y, z1 + 3), P(x0 + 7, y, z1 + 3));
    locks.setAttribute("d", k);
    far.sil.classList.add("hi"); near.sil.classList.add("hi");
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(ext, dt); draw(ext.x); return m; });
  bag.add(B.unregister);

  function move(p) {
    const [wx, wy] = unproj(C, p[0], p[1], 0);
    if (wy < -40 || wy > Wd + 40 || wx < -20 || wx > L + 100) return leave();
    ext.t = clamp(wx - L, MIN, reach);
    read.textContent = "lap " + Math.round(L - ext.t);
    B.wake();
  }
  function leave() { ext.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "ladderext",
  means: "An extension ladder lying flat: the fly section slides out along the base to follow the pointer, and back again on leaving.",
  rules: [1, 3, 5, 8],
  range: [40, 60, 80],
  tour: [[233, 194], [343, 250], [298, 227], null],
  mount,
});

nailgun.code:
/**
 * Tool chest: a tall rolling chest on four casters, six drawers that grow
 * deeper toward the floor, a push handle on its side. The pointer picks a
 * drawer by its height on the front; it rolls out on its runners and the
 * drawers beside it follow a little, staggered from it. At rest the second
 * drawer stands open, bright. The slider is the stagger.
 *
 * The pattern: one of a stack of unequal parts; the pick is the drawer whose
 * resting front middle is nearest the pointer's y on screen.
 */
const {
  Cam, facing, fit, prism, proj, rings, seg, open, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 42, HS = [6, 6, 8, 9, 11, 13], Z0 = 11, OUT = 32, FAV = 1;
const ZS = []; { let z = Z0; for (let k = HS.length - 1; k >= 0; k--) { ZS[k] = z; z += HS[k]; } }
const ZT = ZS[0] + HS[0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, 0, 0], [W + 6, 0, 0], [0, D + OUT, 0], [W + 6, D + OUT, 0], [0, 0, ZT + 3], [W + 6, 0, ZT + 3]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const caster = (x, y) => { const [r, i] = rings(x - 3, y - 3, x + 3, y + 3, 3, 1); put(solid(g), prism(P, front, r, i, 0, Z0 - 1)); };
  caster(6, 6); caster(W - 6, 6); caster(6, D - 6);
  { const [r, i] = rings(0, 0, W, D, 2, 1.2); put(solid(g), prism(P, front, r, i, Z0 - 2, ZT)); }
  caster(W - 6, D - 6);
  mk("path", { class: "nf", d: open([P(W, 8, ZT - 6), P(W + 5, 8, ZT - 6), P(W + 5, D - 8, ZT - 6), P(W, D - 8, ZT - 6)]) }, g);
  const dg = mk("g", {}, g);
  const drawers = [];
  for (let k = HS.length - 1; k >= 0; k--) {
    const el = solid(dg), marks = mk("path", { class: "nf lo" }, el.g);
    drawers[k] = { k, z0: ZS[k], h: HS[k], el, marks, y: tween(k === FAV ? 20 : 0), last: "" };
  }
  { const [r, i] = rings(-1.5, -1.5, W + 1.5, D + 1.5, 2.4, 1.2); put(solid(g), prism(P, front, r, i, ZT, ZT + 3)); }

  function draw(d, y) {
    const key = y.toFixed(2);
    if (key === d.last) return;
    d.last = key;
    const z0 = d.z0 + 0.5, z1 = d.z0 + d.h - 0.5;
    const [r, i] = rings(2.5, 2 + y, W - 2.5, D + 0.6 + y, 1.2, 0.7);
    put(d.el, prism(P, front, r, i, z0, z1));
    const f = D + 0.6 + y, hz = z1 - 2;
    let m = seg(P(10, f, hz), P(W - 10, f, hz));
    if (y > 5) m += seg(P(W / 2, Math.max(D, 6 + y), z1), P(W / 2, f - 3, z1)); // a divider in the open tray
    d.marks.setAttribute("d", m);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const d of drawers) { draw(d, tval(d.y, now)); if (!tdone(d.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = drawers.map((d) => P(W / 2, D, d.z0 + d.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 18 && Math.abs(mids[best][0] - sx) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    drawers.forEach((d, k) => {
      const n = Math.abs(k - a);
      const y = a < 0 ? (k === FAV ? 20 : 0) : n === 0 ? OUT : n === 1 ? 6 : 0;
      tset(d.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      d.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "drw " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

