  name: "nailgun",
  means: "A rolling tool chest of six drawers on casters: the one under the pointer rolls out, its neighbours follow a little in turn.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[187, 110], [187, 142], [187, 199], null],
  mount,
});

rovercam.code:
/**
 * Rover mast: a six-wheeled rover with a tall mast and a wide camera head.
 * The pointer is what the rover should look at: the head pans on the mast to
 * face the point on the ground, on a spring. At rest it looks off to the left.
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, rings, rrect, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const MZ = 62, HW = 22, HD = 9, HH = 15, WR = 9, WX = [-30, 0, 30];
const REST = 1.15;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-42, -30, 0], [42, 30, 0], [42, -30, 0], [-42, 30, 0], [0, 0, MZ + HH + 2], [-HW, -HW, MZ + HH], [HW, HW, MZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => {
    const ring = (yy) => circ(WR, 28).map((q) => P(x + q.u, yy, WR + q.v));
    const s = solid(g);
    s.sil.setAttribute("d", poly(hull(ring(y - 3).concat(ring(y + 3)))));
    s.cr.setAttribute("d", poly(circ(WR - 4, 20).map((q) => P(x + q.u, y + 3.2, WR + q.v))));
    s.cr.setAttribute("class", "nf lo");
  };
  WX.forEach((x) => wheel(x, -24));
  const [dr, di] = rings(-38, -18, 38, 18, 6, 1.6);
  put(solid(g), prism(P, front, dr, di, 12, 24));
  WX.forEach((x) => wheel(x, 24));
  put(solid(g), prism(P, front, circ(4, 20), circ(3, 20), 24, MZ));
  const head = solid(g), lens = mk("path", { class: "nf" }, g), eye = mk("path", { class: "nf" }, g);
  const yaw = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "", over = false;

  function draw() {
    const key = yaw.x.toFixed(3);
    if (key === last) return; last = key;
    const a = yaw.x, ca = Math.cos(a), sa = Math.sin(a);
    const rot = (u, v) => [u * ca - v * sa, u * sa + v * ca];
    const at = (ring, z) => ring.map((q) => { const [x, y] = rot(q.u, q.v); return P(x, y, z); });
    const foot = rrect(-HD, -HW, HD, HW, 4, 4), inner = rrect(-HD + 1.5, -HW + 1.5, HD - 1.5, HW - 1.5, 2.5, 4);
    head.sil.setAttribute("d", poly(hull(at(foot, MZ).concat(at(foot, MZ + HH)))));
    head.cr.setAttribute("d", poly(at(inner, MZ + HH)));
    head.cr.setAttribute("class", "nf lo");
    const show = ca + sa > -0.2;
    const lensAt = (off, r) => circ(r, 24).map((q) => { const [x, y] = rot(HD + 0.3, off + q.u); return P(x, y, MZ + HH / 2 + q.v); });
    lens.setAttribute("d", show ? poly(lensAt(-10, 4.6)) : "");
    eye.setAttribute("d", show ? poly(lensAt(9, 3)) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (p) {
      let a = Math.atan2(p[1], p[0]);
      while (a - yaw.t > Math.PI) a -= 2 * Math.PI; while (a - yaw.t < -Math.PI) a += 2 * Math.PI;
      yaw.t = a;
    } else yaw.t = REST;
    over = !!p;
    head.sil.classList.toggle("hi", over);
    lens.setAttribute("class", over ? "nf" : "nf hi");
    read.textContent = over ? `pan ${((Math.round(yaw.t * 57.3) % 360) + 360) % 360}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); aim(Math.hypot(x, y) > 110 ? null : [x, y]); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { yaw.k = 100 * v; yaw.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "rovercam",
  means: "A six-wheeled rover's mast camera: the head pans on the mast to look at the point under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[269, 270], [48, 228], [365, 221], null],
  mount,
});

astronautseat.code:
/**
 * Launch couch: a capsule seat on a strut frame, with a backrest and a leg
 * rest hinged to the pan. The pointer sets the recline: toward the back of the
 * pad the couch lies down for launch, toward the front it sits up, on a spring.
 * At rest it is half back, harness buckle lit.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, seg, unproj, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 18, Z0 = 26, BL = 54, LL = 30, T = 5;
const REST = 0.75;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-62, -W, 0], [48, W, 0], [-10, W, Z0 + BL], [48, -W, 0], [-62, W, Z0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-26, -26, 30, 26, 8, 2);
  put(solid(g), prism(P, front, br, bi, -5, 0));
  const legs = mk("path", { class: "nf sil" }, g);
  legs.setAttribute("d", [[-6, -12], [16, -12], [-6, 12], [16, 12]].map(([x, y]) => seg(P(x, y, 0), P(x, y, Z0 - 1))).join(""));
  const back = solid(g);
  const [sr, si] = rings(-10, -W, 22, W, 6, 1.6);
  put(solid(g), prism(P, front, sr, si, Z0 - T, Z0));
  const buckle = mk("circle", { class: "dot", r: 2.8 }, g);
  const bp = P(8, 0, Z0 + 0.4); buckle.setAttribute("cx", bp[0]); buckle.setAttribute("cy", bp[1]);
  const leg = solid(g);
  const th = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "", over = false;

  /** A plate hinged at h, running len along a, with thickness along n. */
  function plate(s, h, a, n, len, w) {
    const ring = rrect(0, -w, len, w, 6, 4), inner = rrect(1.6, -w + 1.6, len - 1.6, w - 1.6, 4.4, 4);
    const at = (r, t) => r.map((q) => P(h[0] + a[0] * q.u + n[0] * t, h[1] + q.v, h[2] + a[2] * q.u + n[2] * t));
    s.sil.setAttribute("d", poly(hull(at(ring, 0).concat(at(ring, T)))));
    s.cr.setAttribute("d", poly(at(inner, T)));
    s.cr.setAttribute("class", "nf lo");
  }

  function draw() {
    const key = th.x.toFixed(3);
    if (key === last) return; last = key;
    const t = th.x;
    plate(back, [-10, 0, Z0 - T], [-Math.sin(t), 0, Math.cos(t)], [Math.cos(t), 0, Math.sin(t)], BL, W);
    const l = 0.35 + (1.4 - t) * 0.9;
    plate(leg, [22, 0, Z0 - T], [Math.cos(l), 0, -Math.sin(l)], [Math.sin(l), 0, Math.cos(l)], LL, W - 2);
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(p) {
    over = !!p;
    th.t = p ? clamp(0.75 - p[0] / 80, 0.12, 1.35) : REST;
    back.sil.classList.toggle("hi", over);
    buckle.setAttribute("class", over ? "dot off" : "dot");
    read.textContent = over ? `${Math.round(th.t * 57.3)}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); set(Math.abs(x) > 90 || Math.abs(y) > 70 ? null : [x, y]); },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { th.k = 100 * v; th.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "astronautseat",
  means: "A capsule launch couch on its frame: the pointer sets the recline, lying back toward the pad's rear and sitting up toward its front.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[139, 174], [295, 252], [54, 174], null],
  mount,
});

satdish2.code:
/**
 * Ground antenna: a big dish on a turret over a concrete pad. The pointer is
 * the satellite: the dish slews on its turret and tips its elevation to aim at
 * the point on the pad's plane, on a spring. At rest it looks up and left.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PAD = 56, HUB = 54, RIM = 40, BACK = 12, DEPTH = 16;
const REST = [-0.9, 0.75];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-PAD, -PAD, 0], [PAD, PAD, 0], [PAD, -PAD, 0], [-PAD, PAD, 0], [0, 0, HUB + RIM + 4], [-RIM, -RIM, HUB + 20]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-PAD, -PAD, PAD, PAD, 10, 2);
  put(solid(g), prism(P, front, pr, pi, -6, 0));
  const [br, bi] = rings(-16, -16, 16, 16, 5, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 10));
  put(solid(g), prism(P, front, circ(9, 32), circ(7.6, 32), 10, HUB - 8));
  const turret = solid(g);
  const dishG = mk("g", {}, g);
  const body = mk("path", { class: "sil" }, dishG), rim = mk("path", { class: "nf" }, dishG);
  const struts = mk("path", { class: "nf lo" }, dishG), feed = mk("circle", { class: "dot", r: 2.6 }, dishG);
  const az = spring(REST[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), el = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "", over = null;

  function draw() {
    const key = az.x.toFixed(3) + el.x.toFixed(3);
    if (key === last) return; last = key;
    const d = [Math.cos(el.x) * Math.cos(az.x), Math.cos(el.x) * Math.sin(az.x), Math.sin(el.x)];
    let u = [-Math.sin(az.x), Math.cos(az.x), 0];
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    const c = [0, 0, HUB];
    const ring = (off, r, n) => Array.from({ length: n }, (_, i) => {
      const t = (i / n) * Math.PI * 2, q = (j) => c[j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(-2, BACK, 24), lip = ring(DEPTH, RIM, 56), mid = ring(DEPTH - 1.4, RIM - 1.6, 56);
    const tring = circ(11, 24).map((q) => P(q.u, q.v, HUB - 8)).concat(circ(11, 24).map((q) => P(q.u, q.v, HUB - 2)));
    turret.sil.setAttribute("d", poly(hull(tring)));
    const toFront = d[0] + d[1] > 0;
    body.setAttribute("d", poly(hull(back.concat(lip))));
    rim.setAttribute("d", poly(toFront ? mid : lip));
    const tip = [0, 1, 2].map((j) => c[j] + d[j] * (DEPTH + 26)), tp = P(...tip);
    struts.setAttribute("d", [0, 14, 28, 42].map((i) => seg(lip[i], tp)).join(""));
    feed.setAttribute("cx", tp[0]); feed.setAttribute("cy", tp[1]);
  }

  const B = register(stage, (dt) => { const a = stepS(az, dt), b = stepS(el, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function retarget() {
    if (over) {
      const [x, y] = over, r = Math.hypot(x, y);
      let a = Math.atan2(y, x); while (a - az.t > Math.PI) a -= 2 * Math.PI; while (a - az.t < -Math.PI) a += 2 * Math.PI;
      az.t = a; el.t = Math.max(0.15, Math.min(1.25, 1.35 - r / 90));
    } else { az.t = REST[0]; el.t = REST[1]; }
    body.classList.toggle("hi", !!over);
    feed.setAttribute("class", over ? "dot off" : "dot");
    read.textContent = over ? `az ${((Math.round(az.t * 57.3) % 360) + 360) % 360}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) > 120 ? null : [x, y]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { az.k = el.k = 100 * v; az.c = el.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "satdish2",
  means: "A ground station dish on its turret: it slews and tips to aim where the pointer is, like tracking a pass overhead.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[212, 268], [52, 212], [336, 218], null],
  mount,
});

aquariumlid.code:
/**
 * Tank hood: an aquarium on a stand with its hood hinged along the back top
 * edge. The pointer over the tank lifts the hood, wider the nearer the front
 * the pointer comes. At rest the hood sits a little ajar, bright. The slider
 * is the widest opening.
 *
 * The pattern: one lid turning on a hinge (open).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const D = 66, Wd = 120, H = 64, HD = 68, HH = 9, REST = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[-4, -4, -6], [D + 4, Wd + 4, -6], [D + 4, -4, -6], [-4, Wd + 4, -6], [0, 0, H + HD + 6], [0, Wd, H + HD + 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, D + 4, Wd + 4, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, -6, 0));
  const [tr, ti] = rings(0, 0, D, Wd, 1.5, 1.2);
  put(solid(g), prism(P, front, tr, ti, 0, H));
  let d = seg(P(D, 0, H - 10), P(D, Wd, H - 10)) + seg(P(D, Wd, H - 10), P(0, Wd, H - 10));
  mk("path", { d, class: "nf dash" }, g);
  d = "";
  for (const [y, h] of [[18, 16], [30, 24], [42, 13], [92, 20], [102, 28]]) d += seg(P(D, y, 6), P(D, y + 2, 6 + h)) + seg(P(D, y + 2, 6 + h), P(D, y + 5, 6 + h * 0.6));
  d += seg(P(D, 0, 6), P(D, Wd, 6)) + seg(P(D, Wd, 6), P(0, Wd, 6));
  mk("path", { d, class: "nf lo" }, g);

  const hood = mk("g", {}, g);
  const sil = mk("path", { class: "sil hi" }, hood), faces = mk("path", { class: "nf lo" }, hood);
  const ang = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (x, y, dz) => P(x * c - dz * s, y, H + x * s + dz * c);
    const pts = [];
    for (const x of [-1, HD]) for (const y of [-1, Wd + 1]) for (const dz of [0, HH]) pts.push(at(x, y, dz));
    sil.setAttribute("d", poly(hull(pts)));
    const q = (a1, b1, c1, d1) => poly([a1, b1, c1, d1]);
    faces.setAttribute("d",
      q(at(-1, -1, HH), at(HD, -1, HH), at(HD, Wd + 1, HH), at(-1, Wd + 1, HH)) +
      q(at(HD, -1, 0), at(HD, Wd + 1, 0), at(HD, Wd + 1, HH), at(HD, -1, HH)) +
      seg(at(HD - 14, 10, HH), at(HD - 14, 34, HH)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let tgt = null, lastP = null;
  function lift(p) {
    lastP = p;
    let a = REST;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], H);
      if (wy > -30 && wy < Wd + 30 && wx > -40 && wx < D + 50) a = maxA * clamp((wx + 30) / (D + 40), 0.3, 1);
    }
    a = Math.round(a);
    if (a === tgt) return;
    tgt = a;
    ang.t = a;
    read.textContent = !p || a === REST ? "rest" : "open " + a + "°";
    B.wake();
  }
  lift(null);
  bag.add(pointer(stage, { move: lift, leave: () => lift(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; tgt = null; lift(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "aquariumlid",
  means: "An aquarium whose hood is hinged at the back: it lifts as the pointer comes over the tank, wider nearer the front.",
  rules: [1, 3, 5, 6],
  range: [30, 62, 80],
  tour: [[229, 175], [165, 143], [292, 143], null],
  mount,
});

hamsterball.code:
/**
 * Exercise ball: a clear hamster ball on a long runway. The pointer calls the
 * ball along the runway; it rolls to the point under the pointer, its seams
 * turning as it goes. At rest it waits a third of the way along, bright.
 * The slider is how briskly it rolls.
 *
 * The pattern: one part sliding to the pointer (follow).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 26, X0 = R, X1 = 175, REST = 70, W = R + 10;
const V = [Math.cos(Math.PI / 6) * Math.SQRT1_2, Math.cos(Math.PI / 6) * Math.SQRT1_2, 0.5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.55);
  fit(C, [[-6, -W, 0], [X1 + R + 6, W, 0], [X1 + R + 6, -W, 0], [-6, W, 0], [X0, 0, 2 * R + 4], [X1, 0, 2 * R + 4]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-6, -W, X1 + R + 6, W, 10, 2);
  put(solid(g), prism(P, front, pr, pi, -5, 0));
  const [lr, li] = rings(4, -3, X1 + R - 4, 3, 3, 0.8);
  mk("path", { d: prism(P, front, lr, li, 0, 0.01).sil, class: "nf dash" }, g);
  const [sr, si] = rings(X1 + R + 2, -W + 6, X1 + R + 6, W - 6, 1.5, 0.6);
  put(solid(g), prism(P, front, sr, si, 0, 14));

  const ball = mk("g", {}, g);
  const shadow = mk("path", { class: "nf lo" }, ball);
  const sil = mk("path", { class: "sil hi" }, ball);
  const seams = mk("path", { class: "nf lo" }, ball);
  const hatch = mk("path", { class: "nf" }, ball);
  let pos = spring(REST, { k: value }), last = NaN;

  function draw(x) {
    if (x === last) return;
    last = x;
    const c = [x, 0, R], th = -x / R, out = [];
    for (let i = 0; i <= 12; i++) for (let j = 0; j < 48; j++) {
      const a = (i / 12) * Math.PI, b = (j / 48) * 2 * Math.PI;
      out.push(P(c[0] + R * Math.sin(a) * Math.cos(b), c[1] + R * Math.sin(a) * Math.sin(b), c[2] + R * Math.cos(a)));
    }
    sil.setAttribute("d", poly(hull(out)));
    const sh = [];
    for (let j = 0; j < 32; j++) { const b = (j / 32) * 2 * Math.PI; sh.push(P(x + R * 0.7 * Math.cos(b), R * 0.7 * Math.sin(b), 0)); }
    shadow.setAttribute("d", poly(sh));
    let d = "";
    const circle = (u, w, r, off) => {
      let prev = null;
      for (let j = 0; j <= 48; j++) {
        const t = (j / 48) * 2 * Math.PI, q = [0, 1, 2].map((k) => off[k] + r * (Math.cos(t) * u[k] + Math.sin(t) * w[k]));
        const vis = (q[0] - c[0]) * V[0] + (q[1] - c[1]) * V[1] + (q[2] - c[2]) * V[2] > 0;
        const s = P(q[0], q[1], q[2]);
        if (vis && prev) d += seg(prev, s);
        prev = vis ? s : null;
      }
    };
    for (const k of [0, 1, 2]) { const a = th + (k * Math.PI) / 3; circle([Math.cos(a), 0, Math.sin(a)], [0, 1, 0], R, c); }
    circle([1, 0, 0], [0, 0, 1], R * 0.999, c);
    seams.setAttribute("d", d);
    // the hatch: a small disc on the near side, turning with the ball
    const n = [Math.cos(th + 0.9), 0, Math.sin(th + 0.9)], hc = c.map((v, k) => v + n[k] * R * 0.96);
    const hp = [];
    if ((hc[0] - c[0]) * V[0] + (hc[2] - c[2]) * V[2] > 0) for (let j = 0; j < 24; j++) {
      const t = (j / 24) * 2 * Math.PI, u = [-n[2], 0, n[0]];
      hp.push(P(hc[0] + 7 * (Math.cos(t) * u[0]), hc[1] + 7 * Math.sin(t), hc[2] + 7 * Math.cos(t) * u[2]));
    }
    hatch.setAttribute("d", hp.length ? poly(hp) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(B.unregister);

  let tgt = null;
  function call(p) {
    let x = REST;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], 0); if (Math.abs(wy) < W + 30) x = clamp(wx, X0, X1); }
    x = Math.round(x);
    if (x === tgt) return;
    tgt = x;
    pos.t = x;
    read.textContent = !p ? "rest" : Math.round(((x - X0) / (X1 - X0)) * 100) + "%";
    B.wake();
  }
  call(null);
  bag.add(pointer(stage, { move: call, leave: () => call(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { const x = pos.x, t = pos.t; pos = spring(x, { k: v }); pos.t = t; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "hamsterball",
  means: "A hamster ball on a runway: it rolls to the spot under the pointer, its seams turning as it goes.",
  rules: [1, 3, 5],
  range: [30, 90, 220],
  tour: [[271, 219], [123, 145], [210, 189], null],
  mount,
});

dogdoor.code:
/**
 * Dog door: a garden wall on a ground plate with a low opening and a flap
 * hung from its top edge. The flap swings toward whichever side of the wall
 * the pointer stands on, further the further out it is. At rest it hangs
 * pushed a little way in, bright. The slider is the widest swing.
 *
 * The pattern: one part turning toward the pointer (aim).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = -22, Y0 = 0, Y1 = 110, HY0 = 25, HY1 = 85, H = 88, SILL = 6, TOP = 68, L = 61, T = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-64, Y0 - 6, 0], [64, Y1 + 6, 0], [-64, Y1 + 6, 0], [64, Y0 - 6, 0], [0, Y0, H], [0, Y1, H]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-50, Y0 - 10, 50, Y1 + 10, 8, 2);
  put(solid(g), prism(P, front, gr, gi, -4, 0));

  const flapBack = mk("g", {}, g);
  const block = (y0, y1, z0, z1) => { const [r, i] = rings(-T, y0, T, y1, 1, 0.6); put(solid(g), prism(P, front, r, i, z0, z1)); };
  block(Y0, HY0, 0, H);
  block(HY0, HY1, 0, SILL);
  block(HY0, HY1, TOP, H);
  block(HY1, Y1, 0, H);
  const flapFront = mk("g", {}, g);

  const flap = mk("g", {}, flapBack);
  const sil = mk("path", { class: "sil" }, flap), face = mk("path", { class: "nf lo" }, flap);
  const pad = mk("path", { class: "nf" }, flap);
  const ang = spring(REST);
  let last = NaN, side = 0;

  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (y, d, n) => P(d * s + n * c, y, TOP - d * c + n * s);
    const ya = HY0 + 1.5, yb = HY1 - 1.5, pts = [];
    for (const y of [ya, yb]) for (const d of [0, L]) for (const n of [-1.2, 1.2]) pts.push(at(y, d, n));
    sil.setAttribute("d", poly(hull(pts)));
    const n = a >= 0 ? 1.2 : -1.2;
    face.setAttribute("d", poly([at(ya + 4, 6, n), at(yb - 4, 6, n), at(yb - 4, L - 6, n), at(ya + 4, L - 6, n)]));
    pad.setAttribute("d", poly([at(ya + 12, L - 14, n), at(yb - 12, L - 14, n), at(yb - 12, L - 9, n), at(ya + 12, L - 9, n)]));
    const s2 = a >= 0 ? 1 : -1;
    if (s2 !== side) { side = s2; (s2 > 0 ? flapFront : flapBack).appendChild(flap); }
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let tgt = null;
  function aim(p) {
    let a = REST;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      if (wy > Y0 - 30 && wy < Y1 + 30) a = clamp(wx / 34, -1, 1) * maxA;
    }
    a = Math.round(a);
    if (a === tgt) return;
    tgt = a;
    ang.t = a;
    sil.classList.add("hi");
    read.textContent = !p ? "rest" : a >= 0 ? "out " + a + "°" : "in " + -a + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (tgt !== null && tgt !== REST) { ang.t = clamp(ang.t, -v, v); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "dogdoor",
  means: "A flap hung in a garden wall: it swings toward the side the pointer stands on, further the further out.",
  rules: [1, 3, 5, 6],
  range: [30, 70, 85],
  tour: [[256, 238], [144, 182], [324, 204], null],
  mount,
});

xraylight.code:
/**
 * X-ray viewer: a desk light box on a hinged foot, two films clipped to its
 * face, each showing a spine and ribs. The pointer is the reader's eye: the
 * panel tilts on its hinge to face it, standing up as the pointer rises and
 * reclining as it comes near, and the panel goes bright. At rest it leans
 * back and the left film is the mark. The slider is how quickly it tilts.
 */
const {
  Cam, clamp, fillet, fit, mk, open, poly, proj, rings, prism, facing, unproj,
  spring, stepS, disposer, pointer, put, register, solid,
} = HL;

const W = 44, H = 62, TH = 3, T0 = 28, T1 = 86, REST = 60, d2r = Math.PI / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.25);
  const at = (t, u, w, o = 0) => [u, -w * Math.cos(t) + o * Math.sin(t), w * Math.sin(t) + o * Math.cos(t) + 4];
  const ext = [[-W - 4, -12, 0], [W + 4, 12, 0]];
  for (const t of [T0 * d2r, T1 * d2r]) for (const u of [-W, W]) ext.push(at(t, u, H), at(t, u, 0));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the foot and the hinge barrel
  const [FR, FI] = rings(-W - 3, -10, W + 3, 8, 4, 1.4);
  put(solid(g), prism(P, front, FR, FI, 0, 3));
  put(solid(g), prism(P, front, rings(-W, -2, W, 2, 1.8, 0.6)[0], null, 3, 6));

  // the panel: its back for the thickness, its face, then the films
  const back = mk("path", {}, g);
  const face = mk("path", { class: "sil" }, g);
  const films = [-1, 1].map(() => ({ sheet: mk("path", { class: "sil" }, g), bones: mk("path", { class: "nf lo" }, g) }));
  const clip = mk("path", { class: "nf sil" }, g);
  const sp = spring(REST * d2r, { k: 100 * value, c: 18 * Math.sqrt(value) });
  const rect = (t, u0, w0, u1, w1, o, r) => poly(fillet([[u0, w0], [u1, w0], [u1, w1], [u0, w1]].map(([u, w]) => P(...at(t, u, w, o))), [r, r, r, r]));
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    back.setAttribute("d", rect(t, -W, 0, W, H, -TH, 6));
    face.setAttribute("d", rect(t, -W, 0, W, H, 0, 6));
    films.forEach((f, i) => {
      const u0 = i ? 4 : -W + 5, u1 = i ? W - 5 : -4, cu = (u0 + u1) / 2;
      f.sheet.setAttribute("d", rect(t, u0, 7, u1, H - 8, 0.3, 2));
      let d = open([at(t, cu, 13, 0.4), at(t, cu, H - 15, 0.4)].map((q) => P(...q)));
      for (let k = 0; k < 5; k++) {
        const w = H - 20 - k * 6, rib = [];
        for (let j = -6; j <= 6; j++) { const u = cu + j * 1.9; rib.push(P(...at(t, u, w - 0.05 * j * j, 0.4))); }
        d += open(rib);
      }
      f.bones.setAttribute("d", d);
    });
    clip.setAttribute("d", open([at(t, -W + 3, H - 5, 0.6), at(t, W - 3, H - 5, 0.6)].map((q) => P(...q))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    sp.t = (over == null ? REST : over) * d2r;
    face.classList.toggle("hi", over != null);
    films[0].sheet.classList.toggle("hi", over == null);
    read.textContent = over == null ? "rest" : "tilt " + Math.round(over) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = Math.abs(x) > W + 40 || y > 120 || y < -120 ? null : clamp(T1 - (y + 60) * 0.55, T0, T1);
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "xraylight",
  means: "An x-ray light box with two films: the panel tilts on its hinge to face the pointer, upright when high, reclined when near.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[252, 178], [160, 220], [77, 265], null],
  mount,
});

robotarm2.code:
/**
 * Robot arm: a turntable base, a shoulder, an upper arm and a forearm on
 * round joints, a two-finger gripper at the wrist. The pointer is the part
 * to pick: the base turns to face it and the arm reaches out or folds in to
 * meet it, and the gripper goes bright. At rest the arm is half out and turned
 * aside, the shoulder joint the mark. The slider is how quickly it follows.
 */
const {
  Cam, circ, clamp, facing, fit, hull, mk, poly, prism, proj, rings, seg, unproj,
  spring, stepS, disposer, pointer, put, register, solid,
} = HL;

const ZS = 22, L1 = 42, L2 = 40, A0 = -12, A1 = 120, R0 = 26, R1 = 66, d2r = Math.PI / 180;
const REST = { yaw: 14, reach: 56 };
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.15);
  const ext = [[-20, -20, 0], [20, 20, 0]];
  for (let k = 0; k <= 6; k++) { const a = (A0 + (A1 - A0) * k / 6) * d2r; ext.push([R1 * Math.cos(a), R1 * Math.sin(a), 0], [30 * Math.cos(a), 30 * Math.sin(a), ZS + 44]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [BR, BI] = rings(-18, -18, 18, 18, 7, 1.6);
  put(solid(g), prism(P, front, BR, BI, 0, 4));
  put(solid(g), prism(P, front, circ(11, 40), circ(9.6, 40), 4, 9));
  const tower = solid(g), shoulder = solid(g), upper = solid(g), elbow = solid(g), fore = solid(g), wrist = solid(g);
  const fingers = mk("path", { class: "nf sil", d: "" }, g);
  const opt = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const yaw = spring(REST.yaw * d2r, opt), reach = spring(REST.reach, opt);
  const rod = (a, b, r) => poly(hull([...P_ring(a, r), ...P_ring(b, r)]));
  const P_ring = (p, r) => [-r, r].flatMap((dz) => circ(r, 16).map((q) => P(p[0] + q.u, p[1] + q.v, p[2] + dz)));
  let dy = NaN, dr = NaN;
  function draw() {
    if (Math.abs(yaw.x - dy) < 1e-4 && Math.abs(reach.x - dr) < 1e-3) return;
    dy = yaw.x; dr = reach.x;
    const c = Math.cos(dy), s = Math.sin(dy), R = clamp(dr, R0, R1);
    // two-link reach in the arm's plane: the wrist sits at R out, 8 above the floor
    const tx = R, tz = 10 - ZS, D = Math.min(L1 + L2 - 0.5, Math.hypot(tx, tz));
    const a1 = Math.atan2(tz, tx) + Math.acos((L1 * L1 + D * D - L2 * L2) / (2 * L1 * D));
    const ex = L1 * Math.cos(a1), ez = ZS + L1 * Math.sin(a1);
    const W = (r, z) => [r * c, r * s, z];
    const sh = W(0, ZS), el = W(ex, ez), wr = W(tx, 10);
    put(tower, prism(P, front, circ(6, 32), null, 9, ZS));
    put(shoulder, prism(P, front, circ(7.5, 32), circ(6.4, 32), ZS - 3, ZS + 3));
    upper.sil.setAttribute("d", rod(sh, el, 4)); upper.cr.setAttribute("d", "");
    put(elbow, prism(P, front, disc(el[0], el[1], 5.5), disc(el[0], el[1], 4.6), ez - 3, ez + 3));
    fore.sil.setAttribute("d", rod(el, wr, 3)); fore.cr.setAttribute("d", "");
    put(wrist, prism(P, front, disc(wr[0], wr[1], 4.2), null, 7, 12));
    const px = -s * 3.6, py = c * 3.6;
    fingers.setAttribute("d", seg(P(wr[0] + px, wr[1] + py, 7), P(wr[0] + px * 0.6, wr[1] + py * 0.6, 1)) + seg(P(wr[0] - px, wr[1] - py, 7), P(wr[0] - px * 0.6, wr[1] - py * 0.6, 1)));
  }
  const B = register(stage, (dt) => { const m = stepS(yaw, dt) | stepS(reach, dt); draw(); return !!m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    yaw.t = (over ? over.a : REST.yaw) * d2r;
    reach.t = over ? over.r : REST.reach;
    wrist.sil.classList.toggle("hi", !!over);
    shoulder.sil.classList.toggle("hi", !over);
    read.textContent = over ? "r " + Math.round(over.r) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r > R1 + 40 || r < 8 ? null : { a: clamp(Math.atan2(y, x) / d2r, A0, A1), r: clamp(r, R0, R1) };
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return { set: (v) => { for (const sp of [yaw, reach]) { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); } }, destroy: bag.dispose };
}

hairline({
  name: "robotarm2",
  means: "A robot arm on a turntable: it turns and reaches out or folds in to meet the pointer, and the gripper goes bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[146, 254], [383, 252], [35, 248], null],
  mount,
});

pitchingmachine.code:
/**
 * Batting cage: a netted tunnel on hoops, a pitching machine at the far end.
 * The pointer is where the ball is driven: the back net takes it, bellying
 * out round the ball, the mesh bending on a spring, and the ring of net round
 * the ball is bright. At rest one ball sits low in the net. The slider is how
 * hard the ball is hit.
 *
 * The pattern: a continuous press (springs on the ball's place and depth);
 * the hit is on the floor's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, open, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const X0 = -72, X1 = 72, YW = 24, H = 44, HOOPS = [-72, -36, 0, 36, 72];
const REST = [34, 12, 5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  let force = value;
  fit(C, [[X0, -YW - 40, 0], [X1, -YW - 40, H], [X0, YW, 0], [X1, YW, H], [X0, -YW, H], [X1, YW, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [fr, fi] = rings(X0 - 4, -YW - 4, X1 + 4, YW + 4, 4, 2);
  put(solid(g), prism(P, front, fr, fi, 0, 2));
  const net = mk("path", { class: "nf lo", d: "" }, g);
  const lip = mk("path", { class: "nf sil hi", d: "" }, g);
  const ball = flatDot(g, C, 1.6, "dot");
  // hoops: posts on both sides and a bar across the roof; the roof's netting between them
  const hoop = (x, y0, y1) => open([P(x, y0, 2), P(x, y0, H - 4), P(x, y0 + Math.sign(y1 - y0) * 4, H), P(x, y1 - Math.sign(y1 - y0) * 4, H), P(x, y1, H - 4), P(x, y1, 2)]);
  mk("path", { class: "nf sil", d: HOOPS.map((x) => hoop(x, -YW, YW)).join("") }, g);
  let roof = "";
  for (let y = -YW + 8; y <= YW - 8; y += 16) roof += seg(P(X0, y, H), P(X1, y, H));
  mk("path", { class: "nf lo", d: roof }, g);
  // the pitching machine: a base, a column and a throwing wheel facing down the tunnel
  put(solid(g), prism(P, front, ...rings(X0 + 6, -8, X0 + 22, 8, 2.5, 1), 2, 8));
  put(solid(g), prism(P, front, circ(2.2, 16).map((q) => ({ ...q, u: q.u + X0 + 14, v: q.v })), null, 8, 18));
  const wheel = [];
  for (let k = 0; k <= 32; k++) { const t = (k / 32) * Math.PI * 2; wheel.push(P(X0 + 14, 7 * Math.cos(t), 24 + 7 * Math.sin(t))); }
  mk("path", { class: "sil", d: open(wheel) }, g);
  mk("path", { class: "nf sil", d: seg(P(X0, YW, 2), P(X0, YW, H - 4)) + seg(P(X1, YW, 2), P(X1, YW, H - 4)) }, g);

  const bx = spring(REST[0]), bz = spring(REST[1]), bd = spring(REST[2]);
  let drawn = "";
  const yAt = (x, z) => {
    const edge = clamp(Math.sin(((x - X0) / (X1 - X0)) * Math.PI), 0, 1) * clamp(Math.sin((z / H) * Math.PI), 0, 1);
    return -YW - bd.x * Math.exp(-((x - bx.x) ** 2 + (z - bz.x) ** 2) / (2 * 24 * 24)) * edge;
  };
  function draw() {
    const key = bx.x.toFixed(2) + bz.x.toFixed(2) + bd.x.toFixed(2);
    if (key === drawn) return;
    drawn = key;
    let d = "";
    for (let z = 6; z < H; z += 6) { const pts = []; for (let x = X0; x <= X1; x += 3) pts.push(P(x, yAt(x, z), z)); d += open(pts); }
    for (let x = X0 + 8; x < X1; x += 8) { const pts = []; for (let z = 2; z <= H; z += 2) pts.push(P(x, yAt(x, z), z)); d += open(pts); }
    net.setAttribute("d", d);
    const lp = [], lr = 6 + bd.x * 0.2;
    for (let k = 0; k <= 36; k++) { const t = (k / 36) * Math.PI * 2, x = bx.x + lr * Math.cos(t), z = bz.x + lr * Math.sin(t); lp.push(P(x, yAt(x, z), z)); }
    lip.setAttribute("d", open(lp));
    place(ball, P(bx.x, yAt(bx.x, bz.x) + 1.5, bz.x));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const s of [bx, bz, bd]) if (stepS(s, dt)) m = true;
    draw();
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { bx.t = REST[0]; bz.t = REST[1]; bd.t = REST[2]; read.textContent = "rest"; B.wake(); return; }
    const x = clamp(p[0], X0 + 20, X1 - 14), z = clamp(14 + (p[1] + YW) * 0.5, 10, H - 12);
    bx.t = x; bz.t = z; bd.t = 34 * force;
    read.textContent = "bay " + clamp(Math.ceil((x - X0) / 36), 1, 4);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => { const p = unproj(C, q[0], q[1], 0); aim(p[0] < X0 - 10 || p[0] > X1 + 10 || Math.abs(p[1]) > YW + 30 ? null : p); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  draw();
  return {
    set: (v) => { force = v; if (bd.t !== REST[2]) { bd.t = 34 * v; B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "pitchingmachine",
  means: "A batting cage: the back net bellies out round the ball where the pointer drives it, the ring of net round it bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.25],
  tour: [[113, 181], [175, 199], [249, 224], null],
  mount,
});

trampoline.code:
/**
 * Trampoline: a round frame on six legs, a ring of springs and a woven mat.
 * The pointer is the jumper's foot: the mat sinks where it lands, its rings
 * and seams bending into a dip that follows on a spring, and the dip's lip is
 * bright. At rest the mat sags a little off centre. The slider is how deep
 * the mat gives.
 *
 * The pattern: a continuous press (a spring on the dip's centre and depth);
 * the hit is on the frame's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, seg, unproj, open, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const RF = 54, RM = 46, ZF = 22, NL = 6, NS = 32, RINGS = [8, 16, 24, 32, 40], SPOKES = 12;
const REST = [-9, 7, 5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([RF * Math.cos(a), RF * Math.sin(a), 0], [RF * Math.cos(a), RF * Math.sin(a), ZF + 1]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let depthK = value;

  // legs: a U of tube under each pair, drawn first so the mat covers the far ones
  const legs = [];
  for (let i = 0; i < NL; i++) {
    const a = (i / NL) * Math.PI * 2 + 0.3, x = RF * Math.cos(a), y = RF * Math.sin(a);
    legs.push(seg(P(x, y, ZF), P(x * 1.04, y * 1.04, 0)));
    place(flatDot(g, C, 1.2, "dot off"), P(x * 1.04, y * 1.04, 0));
  }
  mk("path", { class: "nf sil", d: legs.join("") }, g);
  // the frame tube and its skirt: an opaque plate the far legs hide behind
  put(solid(g), prism(P, front, circ(RF, 72), circ(RF - 1.6, 72), ZF - 2.5, ZF));
  // springs: short hooks from the frame to the mat's hem
  const spr = [];
  for (let i = 0; i < NS; i++) {
    const a = (i / NS) * Math.PI * 2;
    spr.push(seg(P((RF - 2) * Math.cos(a), (RF - 2) * Math.sin(a), ZF), P(RM * Math.cos(a), RM * Math.sin(a), ZF - 0.6)));
  }
  mk("path", { class: "nf lo", d: spr.join("") }, g);
  mk("path", { class: "nf sil", d: open(circ(RM, 72).concat(circ(RM, 72).slice(0, 1)).map((q) => P(q.u, q.v, ZF - 0.6))) }, g);
  const seams = mk("path", { class: "nf lo", d: "" }, g);
  const rings = mk("path", { class: "nf", d: "" }, g);
  const lip = mk("path", { class: "nf sil hi", d: "" }, g);

  const sx = spring(REST[0]), sy = spring(REST[1]), sd = spring(REST[2]);
  let drawn = "";
  const zAt = (x, y) => {
    const r = Math.hypot(x, y), d2 = (x - sx.x) ** 2 + (y - sy.x) ** 2;
    const edge = clamp(1 - (r / RM) ** 4, 0, 1);
    return ZF - 0.6 - sd.x * Math.exp(-d2 / (2 * 15 * 15)) * edge;
  };
  const loop = (pts) => open(pts.concat([pts[0]]));
  function draw() {
    const key = sx.x.toFixed(2) + sy.x.toFixed(2) + sd.x.toFixed(2);
    if (key === drawn) return;
    drawn = key;
    let rd = "", sd2 = "";
    for (const R of RINGS) {
      const pts = [];
      for (let k = 0; k < 64; k++) { const a = (k / 64) * Math.PI * 2, x = R * Math.cos(a), y = R * Math.sin(a); pts.push(P(x, y, zAt(x, y))); }
      rd += loop(pts);
    }
    for (let s = 0; s < SPOKES; s++) {
      const a = (s / SPOKES) * Math.PI * 2, pts = [];
      for (let k = 0; k <= 16; k++) { const r = (k / 16) * RM, x = r * Math.cos(a), y = r * Math.sin(a); pts.push(P(x, y, zAt(x, y))); }
      sd2 += open(pts);
    }
    rings.setAttribute("d", rd);
    seams.setAttribute("d", sd2);
    const lp = [], lr = 7 + sd.x * 0.25;
    for (let k = 0; k < 40; k++) {
      const a = (k / 40) * Math.PI * 2, x = sx.x + lr * Math.cos(a), y = sy.x + lr * Math.sin(a);
      lp.push(P(x, y, zAt(x, y)));
    }
    lip.setAttribute("d", loop(lp));
  }

  const B = register(stage, (dt) => {
    let m = false;
    for (const s of [sx, sy, sd]) if (stepS(s, dt)) m = true;
    draw();
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { sx.t = REST[0]; sy.t = REST[1]; sd.t = REST[2]; read.textContent = "rest"; B.wake(); return; }
    const r = Math.hypot(p[0], p[1]), k = Math.min(1, 30 / Math.max(r, 1e-6));
    sx.t = p[0] * k; sy.t = p[1] * k; sd.t = 16 * depthK;
    read.textContent = "ring " + clamp(Math.round(Math.min(r, 40) / 8), 0, 5);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => { const p = unproj(C, q[0], q[1], ZF); aim(Math.hypot(p[0], p[1]) > RF + 8 ? null : p); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  draw();
  return {
    set: (v) => { depthK = v; if (sd.t !== REST[2]) { sd.t = 16 * v; B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "trampoline",
  means: "A round trampoline: the mat sinks into a dip under the pointer, its rings and seams bending, the dip's lip bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[186, 111], [200, 147], [207, 173], null],
  mount,
});

skirack.code:
/**
 * Ski rack: five pairs of skis stand in a floor tray, their tips resting on a
 * rail along the wall. The pointer chooses a pair, and it tilts off the wall
 * toward the reader, its neighbours easing forward less the farther they
 * stand. At rest the pairs lean at slightly different angles, one bright.
 * The slider is how far the chosen pair tips out.
 *
 * The pattern: a single row picked by its rest centre's screen x; a tween per
 * pair, staggered by distance.
 */
const {
  Cam, facing, fit, prism, proj, rings, fillet, poly, rad, clamp,
  tween, tset, tval, tdone, disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const XS = [-48, -24, 0, 24, 48], YB = -12, L = 84, W = 4.2, FAV = 3;
const LEAN = [9, 7.5, 10, 8, 6.5], FALL = [1, 0.42, 0.14, 0.05, 0.02];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.85);
  let out = value;
  const tip = (x, th) => [x, YB - Math.sin(th) * L, 3 + Math.cos(th) * L];
  const ext = [[-74, -34, 0], [74, -34, 0], [-74, -34, 96], [74, -34, 96], [-70, -8, 0], [70, -8, 0]];
  for (const x of XS) { ext.push(tip(x, rad(-16)), [x, YB + 10, 0]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [wr, wi] = rings(-74, -34, 74, -31, 1.2, 0.6);
  put(solid(g), prism(P, front, wr, wi, 0, 96));
  const [rr, ri] = rings(-70, -31, 70, -25, 1.6, 0.8);
  put(solid(g), prism(P, front, rr, ri, 76, 80));
  const [tr, ti] = rings(-70, -31, 70, -6, 3, 1.4);
  put(solid(g), prism(P, front, tr, ti, 0, 3.5));

  const pairs = XS.map((x, i) => {
    const grp = mk("g", {}, g), skis = [];
    for (const dx of [-2.6, 2.6]) {
      const s = solid(grp);
      s.dot = flatDot(grp, C, 0.9, "dot off");
      skis.push({ x: x + dx, s });
    }
    return { i, x, grp, skis, tw: tween(LEAN[i]), drawn: NaN, cx: P(x, YB - 6, 42)[0] };
  });

  function shape(xc, th) {
    const b = (t, n = 0) => {
      const c = Math.cos(th), s = Math.sin(th);
      return [YB - s * t + c * n, 3.5 + c * t + s * n];
    };
    const pts = [];
    const path = [[0, 0], [L - 10, 0], [L - 4, 1.4], [L, 4.6]];
    for (const [t, n] of path) { const [y, z] = b(t, n); pts.push(P(xc - W / 2, y, z)); }
    for (const [t, n] of path.slice().reverse()) { const [y, z] = b(t, n); pts.push(P(xc + W / 2, y, z)); }
    return { d: poly(fillet(pts, pts.map(() => 1.2))), bind: (() => { const [y, z] = b(L * 0.42, 1.2); return P(xc, y, z); })() };
  }

  function draw(p, now) {
    const th = rad(tval(p.tw, now));
    if (Math.abs(th - p.drawn) < 1e-5) return;
    p.drawn = th;
    for (const k of p.skis) {
      const sh = shape(k.x, th);
      k.s.sil.setAttribute("d", sh.d);
      k.s.cr.setAttribute("d", "");
      place(k.s.dot, sh.bind);
    }
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const p of pairs) { draw(p, now); if (!tdone(p.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let cur = -2;
  function choose(a) {
    if (a === cur) return;
    cur = a;
    const now = performance.now();
    for (const p of pairs) {
      const to = a < 0 ? LEAN[p.i] : LEAN[p.i] - (8 + 16 * out) * FALL[Math.abs(p.i - a)];
      tset(p.tw, to, now, a < 0 ? 0 : Math.abs(p.i - a) * 40);
      const on = a < 0 ? p.i === FAV : p.i === a;
      for (const k of p.skis) k.s.sil.classList.toggle("hi", on);
    }
    read.textContent = a < 0 ? "rest" : "pair " + (a + 1);
    B.wake();
  }

  const top = P(0, -30, 96)[1], bot = P(0, 0, 0)[1];
  bag.add(pointer(stage, {
    move: (q) => {
      let a = -1, bd = Infinity;
      for (const p of pairs) { const d = Math.abs(q[0] - p.cx); if (d < bd) { bd = d; a = p.i; } }
      choose(bd > 30 || q[1] < top - 20 || q[1] > bot + 30 ? -1 : a);
    },
    leave: () => choose(-1),
  }));
  bag.add(() => svg.replaceChildren());
  choose(-1);
  for (const p of pairs) draw(p, performance.now());
  return {
    set: (v) => { out = clamp(v, 0, 1.2); const a = cur; cur = -2; choose(a); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "skirack",
  means: "Five pairs of skis against a wall rail: the pair under the pointer tilts off the wall, its neighbours easing out less.",
  rules: [1, 2, 4, 5],
  range: [0.4, 1, 1.2],
  tour: [[133, 149], [196, 181], [259, 212], null],
  mount,
});

playhouse.code:
/**
 * Playhouse: a small gabled play house on a mat, its door ajar. The pointer
 * turns the whole house to face it, and the door swings wide open while the
 * pointer is near. At rest the house stands turned a little, door ajar and
 * bright. The slider is how far the house may turn.
 *
 * The pattern: one object answering the pointer's position (aim).
 */
const {
  Cam, fit, facing, hull, poly, open, seg, prism, proj, rings, ringAt, rrect, rad, clamp, lerp,
  spring, stepS, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid,
} = HL;

const W = 50, D = 36, H = 30, RH = 20, OV = 4, DW = 7, DH = 21, REST = -14;

function rot(ring, t) {
  const c = Math.cos(t), s = Math.sin(t);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-44, -44, 0], [44, 44, 0], [44, -44, 0], [-44, 44, 0], [0, 0, H + RH + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-44, -44, 44, 44, 10, 2);
  put(solid(g), prism(P, front, mr, mi, 0, 2));
  const body = solid(g), roof = solid(g);
  const gable = mk("path", { class: "nf lo" }, g);
  const frame = mk("path", { class: "nf lo" }, g);
  const win = mk("path", { class: "nf lo" }, g);
  const leaf = mk("path", { class: "sil hi" }, g);

  const [br, bi] = rings(-W / 2, -D / 2, W / 2, D / 2, 3, 1.6);
  const eave = rrect(-W / 2 - OV, -D / 2 - OV, W / 2 + OV, D / 2 + OV, 2, 4);
  const turn = spring(REST), door = tween(25);
  let last = "";

  function draw(th, ph) {
    const key = th.toFixed(2) + ph.toFixed(1);
    if (key === last) return;
    last = key;
    const t = rad(th), c = Math.cos(t), s = Math.sin(t);
    const L = (x, y, z) => P(x * c - y * s, x * s + y * c, z);
    put(body, prism(P, front, rot(br, t), rot(bi, t), 2, 2 + H));
    const zE = 2 + H, zR = zE + RH, xe = W / 2 + OV, ye = D / 2 + OV;
    const pts = ringAt(P, rot(eave, t), zE).concat([L(-xe, 0, zR), L(xe, 0, zR)]);
    roof.sil.setAttribute("d", poly(hull(pts)));
    roof.cr.setAttribute("d", seg(L(-xe + 1, 0, zR - 0.6), L(xe - 1, 0, zR - 0.6)));
    const ex = c + s > 0 ? xe : -xe;
    gable.setAttribute("d", open([L(ex, -ye, zE), L(ex, 0, zR), L(ex, ye, zE)]) + seg(L(-xe, ye, zE), L(xe, ye, zE)));
    const fy = D / 2;
    frame.setAttribute("d", poly([L(-DW, fy, 2), L(DW, fy, 2), L(DW, fy, 2 + DH), L(-DW, fy, 2 + DH)]));
    const wx = W / 2 - 9, wz = 2 + H / 2 + 2;
    win.setAttribute("d", poly([L(wx - 5, fy, wz - 5), L(wx + 5, fy, wz - 5), L(wx + 5, fy, wz + 5), L(wx - 5, fy, wz + 5)]) + seg(L(wx, fy, wz - 5), L(wx, fy, wz + 5)));
    const p = rad(ph), fx = -DW + 2 * DW * Math.cos(p), fyy = fy + 2 * DW * Math.sin(p);
    leaf.setAttribute("d", poly([L(-DW, fy, 2), L(fx, fyy, 2), L(fx, fyy, 2 + DH), L(-DW, fy, 2 + DH)]));
  }

  let act = false;
  const B = register(stage, (dt, now) => {
    const m = stepS(turn, dt);
    draw(turn.x, tval(door, now));
    read.textContent = act ? "turn " + Math.round(turn.x) : "rest";
    return m || !tdone(door, now);
  });
  bag.add(B.unregister);

  function move([sx]) {
    act = true;
    turn.t = clamp(lerp(-reach, reach * 0.8, (sx - 60) / 280), -reach, reach * 0.8);
    tset(door, 80, performance.now(), 0);
    B.wake();
  }
  function leave() {
    act = false;
    turn.t = REST;
    tset(door, 25, performance.now(), 0);
    B.wake();
  }
  draw(REST, 25);
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "playhouse",
  means: "A gabled play house on a mat: it turns to face the pointer and its door swings wide open.",
  rules: [3, 5, 6, 8],
  range: [10, 35, 40],
  tour: [[136, 115], [171, 177], [264, 179], null],
  mount,
});

slide2.code:
/**
 * Spring rider: a playground rider on a coil spring, set in a round pad.
 * The pointer pulls the rider over towards it: the seat and head tilt and
 * the coil leans with them, more towards its top. At rest the rider leans
 * forward a little, its seat bright. The slider is the most it may tilt.
 *
 * The pattern: one object answering the pointer's position (aim).
 */
const {
  Cam, fit, hull, poly, open, prism, proj, facing, rings, rrect, circ, unproj, rad, clamp,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const Z0 = 22, RA = 9, RB = -5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-32, -32, 0], [32, 32, 0], [32, -32, 0], [-32, 32, 0], [0, 0, Z0 + 32], [30, 0, Z0 + 26], [-30, 0, Z0 + 14]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const pad = circ(30, 48).map((q) => ({ ...q }));
  const padIn = circ(28, 48).map((q) => ({ ...q }));
  put(solid(g), prism(P, front, pad, padIn, 0, 3));
  const coil = mk("path", { class: "sil nf" }, g);
  const parts = [
    { ring: rrect(-18, -8, 14, 8, 4, 4), inner: rrect(-16.5, -6.5, 12.5, 6.5, 2.5, 4), z0: Z0, z1: Z0 + 9 },
    { ring: rrect(-20, -7, -13, 7, 3, 4), inner: rrect(-19, -6, -14, 6, 2, 4), z0: Z0 + 9, z1: Z0 + 15 },
    { ring: rrect(8, -6, 20, 6, 4, 4), inner: rrect(9.5, -4.5, 18.5, 4.5, 2.5, 4), z0: Z0 + 9, z1: Z0 + 26 },
    { ring: rrect(12, -13, 16, 13, 2, 4), inner: rrect(12.8, -12.2, 15.2, 12.2, 1.2, 4), z0: Z0 + 21, z1: Z0 + 24 },
  ].map((p) => ({ ...p, s: solid(g) }));
  parts[0].s.sil.classList.add("hi");

  const ta = spring(RA), tb = spring(RB);
  let last = "";
  function T(x, y, z, a, b) {
    const ca = Math.cos(a), sa = Math.sin(a), cb = Math.cos(b), sb = Math.sin(b);
    const dz = z - Z0, x1 = x * ca + dz * sa, z1 = -x * sa + dz * ca;
    return P(x1, y * cb + z1 * sb, Z0 - y * sb + z1 * cb);
  }
  function draw(A, Bd) {
    const key = A.toFixed(2) + "," + Bd.toFixed(2);
    if (key === last) return;
    last = key;
    const a = rad(A), b = rad(Bd), pts = [];
    for (let i = 0; i <= 90; i++) {
      const f = i / 90, t = f * Math.PI * 2 * 6, z = 3 + f * (Z0 - 3);
      const lean = f * f;
      pts.push(T(7 * Math.cos(t), 7 * Math.sin(t), Z0 - (1 - f) * (Z0 - 3) + 0 * z, a * lean, b * lean));
    }
    coil.setAttribute("d", open(pts));
    for (const p of parts) {
      const lo = p.ring.map((q) => T(q.u, q.v, p.z0, a, b)), hiR = p.ring.map((q) => T(q.u, q.v, p.z1, a, b));
      p.s.sil.setAttribute("d", poly(hull(lo.concat(hiR))));
      p.s.cr.setAttribute("d", poly(p.inner.map((q) => T(q.u, q.v, p.z1, a, b))));
    }
  }

  let act = false;
  const B = register(stage, (dt) => {
    const m = stepS(ta, dt) | stepS(tb, dt);
    draw(ta.x, tb.x);
    read.textContent = act ? "tilt " + Math.round(Math.hypot(ta.x, tb.x)) : "rest";
    return !!m;
  });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    act = true;
    ta.t = clamp(wx / 45, -1, 1) * maxT;
    tb.t = clamp(-wy / 45, -1, 1) * maxT;
    B.wake();
  }
  function leave() { act = false; ta.t = RA; tb.t = RB; B.wake(); }
  draw(RA, RB);
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; }, destroy: bag.dispose };
}

