  name: "cardtower",
  means: "A sand timer hung on pins in a stand: the glass tilts toward the pointer on a spring, its sand bright in the lower bulb.",
  rules: [1, 3, 5, 8],
  range: [10, 40, 45],
  tour: [[78, 236], [322, 236], [200, 255], null],
  mount,
});

bowlingpinset.code:
/**
 * Golf flag: a round green with its cup, a ball lying near it and a pin
 * standing in the cup with its flag. The pointer is the wind: the flag
 * swings round the pole to stream toward it and the pin leans its way.
 * At rest the flag streams a little to the right, bright. The slider is the lean.
 *
 * The pattern: one part turning to the pointer (aim).
 */
const { Cam, circ, fit, hull, poly, proj, unproj, clamp, rad, spring, stepS, disposer, mk, pointer, register } = HL;

const GR = 72, GZ = 4, PH = 118, FL = 50, FH = 30;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lean = value;
  const C = Cam(45, 0.5, 1.75);
  const ring = (cx, cy, r, z, n = 16) => circ(r, n).map((q) => [cx + q.u, cy + q.v, z]);
  const ext = ring(0, 0, GR, 0, 24).concat(ring(0, 0, GR, GZ, 24));
  for (const [a, b] of [[1, 0], [0, 1], [-1, 0], [0, -1]]) { const t = rad(16); ext.push([a * PH * Math.sin(t), b * PH * Math.sin(t), GZ + PH], [a * (PH * Math.sin(t) + FL), b * (PH * Math.sin(t) + FL), GZ + PH]); }
  fit(C, ext, 200, 170);
  const P = proj(C), S = (pts) => pts.map((p) => P(...p));
  const g = mk("g", {}, svg);

  // the green, its fringe crease and the cup
  mk("path", { class: "sil", d: poly(hull(S(ext.slice(0, 48)))) }, g);
  mk("path", { class: "nf lo", d: poly(S(ring(0, 0, GR - 3, GZ, 48))) }, g);
  mk("path", { class: "nf", d: poly(S(ring(0, 0, 7, GZ, 24))) }, g);
  mk("path", { class: "nf lo", d: poly(S(ring(0, 0, 5.5, GZ - 1.5, 24))) }, g);
  // the ball, a few lengths short of the cup
  const ball = [];
  for (let i = 0; i <= 6; i++) { const t = (i / 6) * Math.PI; ball.push(...ring(26, 20, 4.4 * Math.sin(t), GZ + 4.4 - 4.4 * Math.cos(t), 14)); }
  mk("path", { class: "sil", d: poly(hull(S(ball))) }, g);

  const pole = mk("path", { class: "sil" }, g), flag = mk("path", { class: "sil hi" }, g), seam = mk("path", { class: "nf lo" }, g);
  const dx = spring(0.7), dy = spring(-0.7), ln = spring(4);
  let last = "";
  function draw() {
    let ax = dx.x, ay = dy.x;
    const m = Math.hypot(ax, ay) || 1; ax /= m; ay /= m;
    const key = ax.toFixed(3) + ay.toFixed(3) + ln.x.toFixed(2);
    if (key === last) return;
    last = key;
    const t = rad(ln.x), at = (h) => [ax * h * Math.sin(t), ay * h * Math.sin(t), GZ - 6 + h * Math.cos(t)];
    const top = at(PH + 6);
    pole.setAttribute("d", poly(hull(S(ring(0, 0, 1.8, GZ - 6, 10).concat(ring(top[0], top[1], 1.8, top[2], 10), ring(top[0], top[1], 1.4, top[2] + 2.5, 10))))));
    // the flag: hung from the pole's top, streaming along (ax, ay) with a soft wave
    const nx = -ay, ny = ax, edge = (h0) => {
      const base = at(h0), out = [];
      for (let i = 0; i <= 8; i++) { const s = i / 8, w = 4 * Math.sin(Math.PI * s * 1.6); out.push([base[0] + ax * FL * s + nx * w, base[1] + ay * FL * s + ny * w, base[2] - 2 * s]); }
      return out;
    };
    const hiE = edge(PH), loE = edge(PH - FH);
    flag.setAttribute("d", poly(S(hiE.concat(loE.reverse()))));
    const mid = edge(PH - FH / 2);
    seam.setAttribute("d", poly(S(mid.slice(0, 3).concat(mid.slice(0, 3).reverse()))));
    // paint the flag behind the pole when it streams away from the viewer
    if (ax + ay < 0) { g.insertBefore(flag, pole); flag.after(seam); } else { pole.after(flag); flag.after(seam); }
  }
  draw();

  const B = register(stage, (dt) => { const a = stepS(dx, dt), b = stepS(dy, dt), c = stepS(ln, dt); draw(); return a || b || c; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { dx.t = 0.7; dy.t = -0.7; ln.t = 4; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], GZ), d = Math.hypot(x, y);
    if (d > 4) { dx.t = x / d; dy.t = y / d; }
    ln.t = clamp(d / 80, 0, 1) * lean;
    const deg = (Math.round((Math.atan2(y, x) * 180) / Math.PI) + 360) % 360;
    read.textContent = deg + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lean = v; }, destroy: bag.dispose };
}

hairline({
  name: "bowlingpinset",
  means: "A golf flag in the cup on a round green: the flag swings round its pole toward the pointer and the pin leans its way.",
  rules: [1, 3, 5, 8],
  range: [0, 12, 16],
  tour: [[52, 250], [348, 250], [200, 300], null],
  mount,
});

hairdryer.code:
/**
 * Salon dryer: a salon chair with a hood dryer on a stand behind it. The
 * pointer's height swings the hood on its pivot: low brings it down over
 * the seat, high tilts it back and up. At rest it hangs half raised, its
 * shell bright. The slider is how far back it tilts.
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, rings, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PV = [0, -26, 60], HR = 17, ARM = 24, REST = 30;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[-20, -34, 0], [20, 20, 0], [20, -34, 0], [-20, 20, 0], [0, -26, 90], [0, 10, 60]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // stand, behind the chair
  put(solid(g), prism(P, front, disc(PV[0], PV[1], 12), disc(PV[0], PV[1], 10.5), 0, 2));
  put(solid(g), prism(P, front, disc(PV[0], PV[1], 2.2, 16), disc(PV[0], PV[1], 1.4, 16), 2, PV[2]));
  // the chair
  put(solid(g), prism(P, front, disc(0, 0, 16), disc(0, 0, 14.5), 0, 2));
  put(solid(g), prism(P, front, disc(0, 0, 4, 16), disc(0, 0, 3, 16), 2, 14));
  const [br, bi] = rings(-15, -18, 15, -13, 2.5, 1.2);
  put(solid(g), prism(P, front, br, bi, 14, 46));
  const [sr, si] = rings(-15, -15, 15, 15, 5, 1.6);
  put(solid(g), prism(P, front, sr, si, 14, 21));
  const hood = mk("g", {}, g);
  const arm = mk("path", { class: "nf" }, hood), shell = mk("path", { class: "sil" }, hood), lip = mk("path", { class: "nf lo" }, hood);

  // a hood point in local space (pivot at origin, hood centre at y = ARM), turned by a about the x axis
  const W = (x, y, z, a) => {
    const c = Math.cos(a), s = Math.sin(a);
    return P(PV[0] + x, PV[1] + y * c - z * s, PV[2] + y * s + z * c);
  };
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [], rim = [];
    for (let i = 0; i <= 5; i++) {
      const t = (i / 5) * (Math.PI / 2), r = HR * Math.cos(t), z = -8 + HR * 0.85 * Math.sin(t);
      for (const q of circ(r, 32)) pts.push(W(q.u, ARM + q.v, z, a));
    }
    for (const q of circ(HR, 40)) rim.push(W(q.u, ARM + q.v, -8, a));
    shell.setAttribute("d", poly(hull(pts.concat(rim))));
    lip.setAttribute("d", poly(rim));
    arm.setAttribute("d", open([W(0, 0, -1, a), W(0, ARM - HR, 4, a)]) + open([W(0, 0, 1, a), W(0, ARM - HR, 6, a)]));
  }

  const sp = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const seat = P(0, 0, 21)[1];
  function aim(p) {
    sp.t = p ? clamp((seat + 20 - p[1]) / 150, 0, 1) * maxA : REST;
    shell.classList.add("hi");
    read.textContent = p ? Math.round(sp.t) + "°" : "rest";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "hairdryer",
  means: "A salon chair under a hood dryer: the pointer's height swings the hood down over the seat or tilts it back up.",
  rules: [3, 5, 6, 8],
  range: [40, 70, 80],
  tour: [[186, 73], [186, 218], [238, 145], null],
  mount,
});

nailpolish.code:
/**
 * Nail polish rack: five square bottles with tall caps on a shelf. The
 * pointer picks a bottle by where it stands: it slides forward off the row,
 * its neighbours follow a little, staggered from it. At rest one bottle
 * stands pulled out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), sliding.
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 5, STEP = 24, W = 9, BODY = 20, NECK = 3.5, CAP = 18, OUT = 30, FAV = 3;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  const X1 = (N - 1) * STEP + 2 * W + 4;
  fit(C, [[-4, -4, 0], [X1, -4, 0], [X1, OUT + 2 * W + 4, 0], [-4, OUT + 2 * W + 4, 0], [W, W, 4 + BODY + NECK + CAP + 2], [X1 - W, W, 4 + BODY + NECK + CAP + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-4, -4, X1, OUT + 2 * W + 4, 4, 1.8);
  put(solid(g), prism(P, front, sr, si, 0, 4));
  const row = mk("g", {}, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, row);
    const body = solid(grp), neck = solid(grp), cap = solid(grp), lvl = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x: 2 + W + k * STEP, grp, body, neck, cap, lvl, d: tween(k === FAV ? OUT * 0.7 : 0), last: NaN, lv: 0.45 + 0.4 * ((k * 7) % 5) / 4 });
  }

  function draw(it, d) {
    if (d === it.last) return false;
    it.last = d;
    const x = it.x, y = 2 + W + d, z0 = 4;
    const [br, bi] = rings(x - W, y - W, x + W, y + W, 3, 1.4);
    put(it.body, prism(P, front, br, bi, z0, z0 + BODY));
    put(it.neck, prism(P, front, disc(x, y, 4), disc(x, y, 3), z0 + BODY, z0 + BODY + NECK));
    put(it.cap, prism(P, front, disc(x, y, 5.5), disc(x, y, 4.3), z0 + BODY + NECK, z0 + BODY + NECK + CAP));
    const h = z0 + 2 + (BODY - 5) * it.lv;
    it.lvl.setAttribute("d", open([P(x + W - 0.4, y - W + 2, h), P(x + W - 0.4, y + W - 0.4, h), P(x - W + 2, y + W - 0.4, h)]));
    return true;
  }

  const B = register(stage, (_dt, now) => {
    let moving = false, changed = false;
    for (const it of items) { if (draw(it, tval(it.d, now))) changed = true; if (!tdone(it.d, now)) moving = true; }
    if (changed) items.slice().sort((a, b) => a.x + a.last - (b.x + b.last)).forEach((it) => row.appendChild(it.grp));
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 2 + W, 4 + BODY / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 26 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), d = a < 0 ? (k === FAV ? OUT * 0.7 : 0) : dd === 0 ? OUT : dd === 1 ? 6 : 0;
      tset(it.d, d, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.body.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "no. " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "nailpolish",
  means: "Five polish bottles on a shelf: the bottle under the pointer slides forward off the row, its neighbours a little after.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[149, 129], [223, 166], [298, 203], null],
  mount,
});

lipstick.code:
/**
 * Lipstick: an open lipstick case with its cap standing beside it. The
 * pointer's height twists the case: up winds the slanted bullet out of its
 * sleeve, down winds it back in, and a seam on the sleeve turns as it goes.
 * At rest the bullet stands half out, bright. The slider is the reach.
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, ringAt, run, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 13, CASE = 26, SR = 10.5, BR = 8.5, BL = 22, REST = 0.45;
const at = (r, x, y, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  const CX = 0, CY = 0, KX = 34, KY = -30;
  fit(C, [[CX - R, CY - R, 0], [CX + R, CY + R, 0], [KX + R, KY - R, 0], [KX - R, KY + R, 0], [CX, CY, CASE + 40 + BL + 4], [KX, KY, 46]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the cap, farther back, painted first
  const cap = solid(g);
  put(cap, prism(P, front, at(R + 0.5, KX, KY), at(R - 1.5, KX, KY), 0, 44));
  mk("path", { d: poly(ringAt(P, at(R - 3, KX, KY), 44)), class: "nf lo" }, g);
  // the case
  const body = mk("g", {}, g);
  put(solid(body), prism(P, front, at(R, CX, CY), at(R - 1.6, CX, CY), 0, CASE));
  mk("path", { d: open(ringAt(P, run(at(R, CX, CY), front), 8)), class: "nf lo" }, body);
  const sleeveG = mk("g", {}, g);
  const sleeve = solid(sleeveG), seam = mk("path", { class: "nf lo" }, sleeveG);
  const bullet = mk("path", { class: "sil" }, sleeveG), tip = mk("path", { class: "nf lo" }, sleeveG);

  let last = NaN;
  function draw(f) {
    if (f === last) return;
    last = f;
    const top = CASE + 4 + f * reach;
    put(sleeve, prism(P, front, at(SR, CX, CY), at(SR - 1.4, CX, CY), CASE, top));
    const ang = f * 5;
    const sx = Math.cos(ang), sy = Math.sin(ang);
    seam.setAttribute("d", sx + sy > -0.3 ? open([P(CX + SR * sx, CY + SR * sy, CASE + 1), P(CX + SR * sx, CY + SR * sy, top - 1)]) : "");
    const b0 = top, pts = [], face = [];
    for (const q of at(BR, CX, CY, 36)) {
      const z1 = b0 + BL * (0.55 + 0.45 * ((q.u - CX) - (q.v - CY)) / (2 * BR));
      pts.push(P(q.u, q.v, b0), P(q.u, q.v, z1));
      face.push(P(q.u, q.v, z1));
    }
    bullet.setAttribute("d", poly(hull(pts)));
    tip.setAttribute("d", poly(face));
  }

  const sp = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const base = P(CX, CY, CASE)[1];
  function aim(p) {
    sp.t = p ? clamp((base + 10 - p[1]) / 140, 0, 1) : REST;
    bullet.classList.add("hi");
    read.textContent = p ? Math.round(sp.t * 100) + "%" : "rest";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "lipstick",
  means: "An open lipstick beside its cap: the pointer's height twists the case and winds the slanted bullet out or back in.",
  rules: [3, 5, 6, 8],
  range: [24, 40, 40],
  tour: [[117, 77], [117, 235], [235, 194], null],
  mount,
});

compact.code:
/**
 * Compact: a round powder compact, its lid hinged at the back. The pointer's
 * height over the figure opens the lid on a spring: up swings it upright to
 * show the mirror, down closes it on the powder pan. At rest it stands ajar,
 * the lid's edge bright. The slider is the widest opening.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 34, H = 9, T = 3, REST = 32;
const disc = (r, n = 48) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [0, -R, H + 2 * R + 4], [R, -R, H + 2 * R]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g), baseG = mk("g", {}, g);
  put(solid(baseG), prism(P, front, disc(R), disc(R - 2), 0, H));
  mk("path", { d: poly(ringAt(P, disc(R - 5), H)), class: "nf lo" }, baseG);
  const pan = mk("path", { d: poly(ringAt(P, disc(R - 9), H - 1)), class: "nf" }, baseG);
  const puff = mk("path", { d: poly(hull(ringAt(P, circ(11, 24).map((q) => ({ ...q, u: q.u + 4, v: q.v + 6 })), H - 1).concat(ringAt(P, circ(10, 24).map((q) => ({ ...q, u: q.u + 4, v: q.v + 6 })), H + 2)))), class: "nf lo" }, baseG);
  const lid = mk("path", { class: "sil" }, lidG), face = mk("path", { class: "nf lo" }, lidG), clasp = mk("path", { class: "nf" }, lidG);

  // a lid point: ring sample (u, v) rotated by a about the hinge at y = -R, z = H
  const L = (u, v, w, a) => {
    const d = v + R, s = Math.sin(a), c = Math.cos(a);
    return P(u, -R + d * c - w * s, H + d * s + w * c);
  };
  const ring = disc(R), inner = disc(R - 5);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const q of ring) { pts.push(L(q.u, q.v, 0, a), L(q.u, q.v, T, a)); }
    lid.setAttribute("d", poly(hull(pts)));
    const showInner = 0.61 * Math.sin(a) - 0.5 * Math.cos(a) > 0;
    face.setAttribute("d", poly(inner.map((q) => L(q.u, q.v, showInner ? 0 : T, a))));
    clasp.setAttribute("d", poly(hull([[-4, R - 1], [4, R - 1], [4, R + 2], [-4, R + 2]].flatMap(([u, v]) => [L(u, v, 0, a), L(u, v, T, a)]))));
    if (deg > 48) g.insertBefore(lidG, baseG); else g.insertBefore(baseG, lidG);
  }

  const sp = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const top = P(0, 0, H)[1];
  function aim(p) {
    if (!p) { sp.t = REST; lid.classList.add("hi"); read.textContent = "rest"; B.wake(); return; }
    const f = clamp((top + 20 - p[1]) / 150, 0, 1);
    sp.t = f * maxA;
    lid.classList.add("hi");
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

