tongs.code:
/**
 * Bunsen tripod: a three-legged ring stand with a square of wire gauze on
 * top and a burner standing under it. The pointer's bearing round the stand
 * turns the tripod and its gauze to face it; leaving turns them back to a
 * slight angle. The gauze is the bright mark. The slider is the rest angle.
 *
 * The pattern: a part turning to face the pointer (turn).
 */
const {
  Cam, fit, facing, circ, fillet, hull, open, poly, prism, proj, rad, ringAt, rings, unproj, spring, stepS, r2,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RT = 24, RF = 34, ZT = 62, G = 30;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restA = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-42, -42, 0], [42, 42, 0], [42, -42, 0], [-42, 42, 0], [0, 0, ZT + 4]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g);
  // the burner: a foot, a barrel, an air collar and a cone of flame
  const bg = mk("g", {}, g);
  put(solid(bg), prism(P, front, disc(0, 0, 11), disc(0, 0, 9), 0, 4));
  put(solid(bg), prism(P, front, disc(0, 0, 3.6, 16), disc(0, 0, 2.6, 16), 4, 40));
  put(solid(bg), prism(P, front, disc(0, 0, 4.8, 16), disc(0, 0, 4, 16), 12, 19));
  mk("path", { d: poly(hull(ringAt(P, disc(0, 0, 3, 12), 41).concat([P(0, 0, 55)]))), class: "nf lo" }, bg);
  const fr = mk("g", {}, g);
  const legs = [0, 1, 2].map(() => { const lg = mk("g", {}, back); return { lg, path: mk("path", { class: "sil" }, lg) }; });
  const ring = solid(fr), gauze = solid(fr), disk = mk("path", { class: "nf lo" }, fr), mesh = mk("path", { class: "nf lo" }, fr);
  const sp = spring(rad(restA));
  let last = NaN;
  function draw(a) {
    const v = r2(a * 100);
    if (v === last) return;
    last = v;
    legs.forEach((L, k) => {
      const t = a + rad(30 + k * 120), c = Math.cos(t), s = Math.sin(t);
      const top = ringAt(P, disc(RT * c, RT * s, 1.6, 10), ZT), foot = ringAt(P, disc(RF * c, RF * s, 1.6, 10), 0);
      L.path.setAttribute("d", poly(hull(top.concat(foot))));
      (RF * (c + s) > 0 ? fr : back).prepend(L.lg);
    });
    const [ra, ri] = [disc(0, 0, RT + 2, 40), disc(0, 0, RT - 1.5, 40)];
    put(ring, prism(P, front, ra, ri, ZT - 2, ZT));
    const sq = (h) => fillet([0, 1, 2, 3].map((k) => { const t = a + rad(45 + k * 90); return [h * Math.SQRT2 * Math.cos(t), h * Math.SQRT2 * Math.sin(t)]; }), [3, 3, 3, 3], 3);
    const ring2 = (h) => sq(h).map(([u, v]) => ({ u, v, nu: u, nv: v }));
    const o = ring2(G), inn = ring2(G - 2);
    put(gauze, { sil: poly(hull(ringAt(P, o, ZT).concat(ringAt(P, o, ZT + 1.6)))), crease: open(ringAt(P, inn, ZT + 1.6).concat([P(inn[0].u, inn[0].v, ZT + 1.6)])) });
    disk.setAttribute("d", poly(ringAt(P, disc(0, 0, 13, 32), ZT + 1.7)));
    const ca = Math.cos(a), sa = Math.sin(a);
    let d = "";
    for (const off of [-22, -17, 17, 22]) for (const [ux, uy, vx, vy] of [[ca, sa, -sa, ca], [-sa, ca, ca, sa]]) {
      const p0 = [off * ux - 26 * vx, off * uy - 26 * vy], p1 = [off * ux + 26 * vx, off * uy + 26 * vy];
      d += "M" + P(p0[0], p0[1], ZT + 1.7).join(",") + "L" + P(p1[0], p1[1], ZT + 1.7).join(",");
    }
    mesh.setAttribute("d", d);
  }
  gauze.sil.classList.add("hi");
  draw(sp.x);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const toward = (t) => { let d = t - sp.t; d -= Math.round(d / (2 * Math.PI)) * 2 * Math.PI; return sp.t + d; };
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, ZT / 2), r = Math.hypot(x, y);
    if (r > 95) return leave();
    sp.t = toward(Math.atan2(y, x) - rad(45));
    read.textContent = "turn " + (((Math.round(sp.t * 180 / Math.PI) % 360) + 360) % 360) + "°";
    B.wake();
  }
  function leave() { sp.t = toward(rad(restA)); read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restA = v; if (read.textContent === "rest") leave(); }, destroy: bag.dispose };
}

hairline({
  name: "tongs",
  means: "A Bunsen tripod with wire gauze over a burner: the tripod and its gauze turn to face the pointer, then settle back at an angle.",
  rules: [3, 5, 6, 8],
  range: [0, 15, 45],
  tour: [[57, 117], [295, 188], [295, 93], null],
  mount,
});

funnelrack.code:
/**
 * Separating funnel: a pear-shaped funnel with a stopper, a tap on its stem
 * and two layers inside, held by a clamp on a retort stand over a beaker.
 * The pointer's height slides the clamp, and the funnel with it, up or down
 * the rod; leaving brings it back over the beaker. The funnel is the bright
 * mark. The slider is how far the clamp can travel.
 *
 * The pattern: one part following the pointer (slide).
 */
const {
  Cam, fit, facing, circ, clamp, hull, lerp, poly, prism, proj, ringAt, rings, spring, stepS, r2,
  disposer, mk, pointer, put, register, solid,
} = HL;

const FX = 28, RX = -14, H0 = 70, H1 = 112, TOPZ = 160;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const PEAR = [[38, 4], [32, 5], [27, 9], [20, 14], [12, 16.5], [4, 14], [-4, 9], [-12, 4], [-17, 2.4]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = value;
  const C = Cam(45, 0.5, 1.45);
  fit(C, [[-30, -28, 0], [64, 28, 0], [64, -28, 0], [-30, 28, 0], [RX, 0, TOPZ], [FX, 0, H1 + 44]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ba, bi] = rings(-30, -28, 64, 28, 6, 2);
  put(solid(g), prism(P, front, ba, bi, 0, 4));
  put(solid(g), prism(P, front, disc(RX, 0, 2.4, 16), disc(RX, 0, 1.6, 16), 4, TOPZ));
  const mv = mk("g", {}, g);
  const arm = solid(mv), boss = solid(mv), stem = solid(mv), tap = solid(mv), handle = solid(mv), body = solid(mv), plug = solid(mv);
  const layer = mk("path", { class: "nf lo" }, mv);
  // the beaker the funnel drains into, nearest the viewer
  const bk = solid(g);
  put(bk, prism(P, front, disc(FX, 0, 13, 32), disc(FX, 0, 12, 32), 4, 34));
  mk("path", { d: poly(ringAt(P, disc(FX, 0, 11.6, 32), 14)), class: "nf lo" }, g);
  const REST = 0.4, sp = spring(REST);
  let last = NaN;
  function draw(t) {
    const v = r2(t);
    if (v === last) return;
    last = v;
    const H = lerp(H0, lerp(H0, H1, travel), t);
    let [a, i] = rings(RX - 4, -4, RX + 5, 4, 2, 1);
    put(boss, prism(P, front, a, i, H + 20, H + 28));
    [a, i] = rings(RX + 4, -1.5, FX, 1.5, 1.4, 0.6);
    put(arm, prism(P, front, a, i, H + 22.5, H + 25.5));
    put(stem, prism(P, front, disc(FX, 0, 1.8, 12), disc(FX, 0, 1.1, 12), H - 46, H - 15));
    put(tap, prism(P, front, disc(FX, 0, 3.4, 16), disc(FX, 0, 2.4, 16), H - 30, H - 24));
    [a, i] = rings(FX - 1.5, -10, FX + 1.5, 10, 1.4, 0.6);
    put(handle, prism(P, front, a, i, H - 28, H - 26));
    const pts = [];
    for (const [z, r] of PEAR) pts.push(...ringAt(P, disc(FX, 0, r, 28), H + z));
    body.sil.setAttribute("d", poly(hull(pts)));
    body.cr.setAttribute("d", poly(ringAt(P, disc(FX, 0, 4, 20), H + 38)));
    put(plug, prism(P, front, disc(FX, 0, 3.2, 16), disc(FX, 0, 2.2, 16), H + 38, H + 44));
    layer.setAttribute("d", poly(ringAt(P, disc(FX, 0, 15.8, 32), H + 8)));
  }
  body.sil.classList.add("hi");
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const yLo = P(FX, 0, H0)[1], yHi = P(FX, 0, H1)[1], xL = P(-30, 28, 0)[0], xR = P(64, -28, 0)[0];
  function move([sx, sy]) {
    if (sx < xL - 10 || sx > xR + 10) return leave();
    sp.t = clamp((yLo - sy) / (yLo - yHi), 0, 1);
    read.textContent = "clamp " + Math.round(sp.t * 100);
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = v; last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "funnelrack",
  means: "A separating funnel clamped to a retort stand over a beaker: the pointer's height slides the clamp and funnel along the rod.",
  rules: [3, 5, 6, 8],
  range: [0.4, 1, 1],
  tour: [[211, 110], [211, 185], [211, 72], null],
  mount,
});

microtome.code:
/**
 * Spectroscope: a round stand with a prism on its centre table, a fixed
 * collimator tube with its slit at the back, and a telescope arm with an
 * eyepiece that swings round the table. The pointer's bearing swings the
 * telescope to face it; leaving swings it back. The telescope is the bright
 * mark. The slider is its rest bearing.
 *
 * The pattern: a part turning to face the pointer (swing).
 */
const {
  Cam, fit, facing, circ, clamp, fillet, hull, poly, prism, proj, rad, ringAt, unproj, spring, stepS, r2,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZT = 40, AC = rad(215), LO = rad(60), HI = rad(300);
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restB = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-62, -62, 0], [62, 62, 0], [62, -62, 0], [-62, 62, 0], [0, 0, ZT + 12]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 30, 48), disc(0, 0, 28, 48), 0, 5));
  const layer = mk("g", {}, g);
  // a tube lying level at height z, along bearing a, from radius r0 to r1
  function tube(a, r0, r1, R, z) {
    const c = Math.cos(a), s = Math.sin(a), end = (d) => {
      const out = [];
      for (let k = 0; k < 16; k++) { const f = (k / 16) * 2 * Math.PI; out.push(P(d * c - R * Math.cos(f) * s, d * s + R * Math.cos(f) * c, z + R * Math.sin(f))); }
      return out;
    };
    return { sil: poly(hull(end(r0).concat(end(r1)))), rim: poly(end(r1)) };
  }
  function arm(a, len, R) {
    const grp = mk("g", {}, layer), post = solid(grp), t = solid(grp), eye = solid(grp);
    return { grp, post, t, eye, a, len, R };
  }
  function drawArm(m, a) {
    const c = Math.cos(a), s = Math.sin(a);
    put(m.post, prism(P, front, disc(25 * c, 25 * s, 2.4, 12), disc(25 * c, 25 * s, 1.6, 12), 5, ZT));
    const T = tube(a, 15, m.len, m.R, ZT), E = tube(a, m.len, m.len + 9, m.R * 0.6, ZT);
    m.t.sil.setAttribute("d", T.sil); m.t.cr.setAttribute("d", T.rim);
    m.eye.sil.setAttribute("d", E.sil); m.eye.cr.setAttribute("d", E.rim);
    m.depth = (m.len / 2) * (c + s);
  }
  const col = arm(AC, 48, 4.5), tel = arm(0, 54, 5);
  const tg = mk("g", {}, layer);
  put(solid(tg), prism(P, front, disc(0, 0, 4, 16), disc(0, 0, 3, 16), 5, ZT - 8));
  put(solid(tg), prism(P, front, disc(0, 0, 14, 32), disc(0, 0, 12.5, 32), ZT - 8, ZT - 5));
  const tri = fillet([0, 1, 2].map((k) => { const t = rad(20 + k * 120); return [9 * Math.cos(t), 9 * Math.sin(t)]; }), [1.5, 1.5, 1.5], 3).map(([u, v]) => ({ u, v, nu: u, nv: v }));
  const triIn = tri.map((q) => ({ ...q, u: q.u * 0.8, v: q.v * 0.8 }));
  put(solid(tg), prism(P, front, tri, triIn, ZT - 5, ZT + 8));
  drawArm(col, AC);
  tel.t.sil.classList.add("hi");
  const sp = spring(rad(restB));
  let last = NaN;
  function draw(a) {
    const v = r2(a * 100);
    if (v === last) return;
    last = v;
    drawArm(tel, a);
    [col, { grp: tg, depth: 0 }, tel].sort((p, q) => p.depth - q.depth).forEach((m) => layer.appendChild(m.grp));
  }
  draw(sp.x);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, ZT);
    if (Math.hypot(x, y) > 110) return leave();
    let rel = Math.atan2(y, x) - AC;
    rel = ((rel % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
    sp.t = AC + clamp(rel, LO, HI);
    read.textContent = "arm " + Math.round(((sp.t - AC) * 180) / Math.PI) + "°";
    B.wake();
  }
  function leave() {
    let rel = rad(restB) - AC;
    rel = ((rel % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
    sp.t = AC + clamp(rel, LO, HI); read.textContent = "rest"; B.wake();
  }
  read.textContent = "rest";
  leave(); sp.x = sp.t; draw(sp.x);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restB = v; if (read.textContent === "rest") leave(); }, destroy: bag.dispose };
}

hairline({
  name: "microtome",
  means: "A spectroscope: a prism on a round table, a fixed collimator, and a telescope arm that swings round the table to face the pointer.",
  rules: [3, 5, 6, 8],
  range: [-30, 20, 80],
  tour: [[35, 129], [365, 129], [16, 65], null],
  mount,
});

parkingticket.code:
/**
 * Ticket barrier: a pay housing on a kerb island, a striped boom arm and the
 * post its tip rests on. Point at the lane and the boom swings up; leave and
 * it settles back on its post. At rest the boom is bright, a touch raised.
 * The slider is how far the boom opens.
 *
 * The pattern: one part swinging about a pivot.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, unproj, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 108, PZ = 36, PY = 18, REST = 4, W = 2.4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 1.88);
  const tipAt = (a) => [8, PY + L * Math.cos(rad(a)), PZ + L * Math.sin(rad(a))];
  fit(C, [[-6, -6, 0], [22, -6, 0], [-6, PY + L + 6, 0], [22, PY + L + 6, 0], tipAt(80), [8, PY, PZ + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ir, ii] = rings(-6, -6, 22, 26, 4, 1.5);
  put(solid(g), prism(P, front, ir, ii, 0, 3));
  const [hr, hi] = rings(0, 0, 16, 16, 3, 1.5);
  put(solid(g), prism(P, front, hr, hi, 3, 46));
  const [cr, ci] = rings(2, 2, 14, 14, 2.5, 1);
  put(solid(g), prism(P, front, cr, ci, 46, 49));
  // ticket slot on the near face
  mk("path", { d: seg(P(16, 4, 30), P(16, 12, 30)), class: "lo nf" }, g);
  const tip = tipAt(REST), py = tip[1];
  const [pr, pi] = rings(4, py - 4, 12, py + 4, 2.5, 1);
  put(solid(g), prism(P, front, pr, pi, 0, tip[2] - W - 0.4));
  // the pivot hub
  const hub = solid(g);
  const [ur, ui] = rings(3, PY - 2, 13, PY + 4, 3, 1);
  put(hub, prism(P, front, ur, ui, PZ - 6, PZ + 6));
  const arm = mk("path", { class: "sil" }, g), stripes = mk("path", { class: "lo nf" }, g);

  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const pt = (t, dx, dz) => P(8 + dx, PY + t * c - dz * s, PZ + t * s + dz * c);
    const pts = [];
    for (const t of [0, L]) for (const dx of [-W, W]) for (const dz of [-W, W]) pts.push(pt(t, dx, dz));
    arm.setAttribute("d", poly(hull(pts)));
    let d = "";
    for (let t = 22; t < L; t += 20) d += seg(pt(t, W, W), pt(t + 8, -W, W)) + seg(pt(t, W, W), pt(t + 8, W, -W));
    stripes.setAttribute("d", d);
  }

  const ang = tween(REST);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? open : REST, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  arm.classList.add("hi");
  setActive(false);
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 0); return x > -30 && x < 50 && y > -10 && y < PY + L + 10; };
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "parkingticket",
  means: "A car park ticket barrier: point at the lane and the striped boom swings up off its post; leave and it settles back.",
  rules: [1, 3, 5, 8],
  range: [40, 65, 80],
  tour: [[270, 228], [177, 274], [118, 304], null],
  mount,
});

meterbox.code:
/**
 * Meter cabinet: a tall utility cabinet with three meters standing on its
 * front panel, closed by one hinged door. The pointer is where the door
 * swings to: it turns on its hinge to face the pointer, uncovering the meters.
 * At rest the door stands a little ajar and its handle is bright.
 */
const { Cam, fit, prism, proj, rings, unproj, spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid, clamp } = HL;

const W = 40, D = 14, H = 62, HX = 0, HY = 18, REST = 0.26, AMIN = 0.06, AMAX = 1.75;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: HX + q.u * c - q.v * s, v: HY + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[0, 0, 0], [W, 0, 0], [W, HY, 0], [0, 0, H + 2], [W, HY, H + 2], [0, HY + W, 0], [0, HY + W, H], [-4, HY + W * 0.6, 0]], 200, 160);
  const P = proj(C);
  const fr = HL.facing(C);
  const g = mk("g", {}, svg);
  // plinth, body, cap
  put(solid(g), prism(P, fr, ...rings(-1, -1, W + 1, D + 1, 2, 1), 0, 4));
  put(solid(g), prism(P, fr, ...rings(0, 0, W, D, 2.5, 1.2), 4, H));
  put(solid(g), prism(P, fr, ...rings(-1.5, -1.5, W + 1.5, D + 1.5, 2.5, 1.2), H, H + 2));
  // three meters on the front panel, at uneven heights
  const M = [[5, 17, 40, 52], [22, 35, 44, 54], [8, 32, 14, 24]];
  for (const [x0, x1, z0, z1] of M) {
    put(solid(g), prism(P, fr, ...rings(x0, D, x1, D + 3, 1.2, 0.6), z0, z1));
    place(flatDot(g, C, 1.6, "dot off"), P((x0 + x1) / 2, D + 1.5, z1));
  }
  // the door and its handle
  const DOOR = rings(0, -1, W, 1, 0.8, 0.4), HAND = rings(33, 1, 36, 3.2, 0.8, 0.4);
  const door = solid(g), hand = solid(g);
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, handFirst = null, active = false;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    put(door, prism(P, fr, turn(DOOR[0], a), turn(DOOR[1], a), 4.5, H - 0.5));
    put(hand, prism(P, fr, turn(HAND[0], a), turn(HAND[1], a), 26, 38));
    const hf = Math.cos(a) - Math.sin(a) < 0;
    if (hf !== handFirst) { handFirst = hf; if (hf) door.g.before(hand.g); else hand.g.before(door.g); }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function paint() {
    door.sil.classList.toggle("hi", active);
    hand.sil.classList.toggle("hi", !active);
    read.textContent = active ? "open " + Math.round((sp.t * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), dx = x - HX, dy = y - HY;
      if (Math.hypot(dx, dy) > 95 || (dx < -30 && dy < 0)) { active = false; sp.t = REST; }
      else { active = true; sp.t = clamp(Math.atan2(dy, dx), AMIN, AMAX); }
      paint();
    },
    leave: () => { active = false; sp.t = REST; paint(); },
  }));
  bag.add(() => svg.replaceChildren());
  paint();
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

