  tour: [[244, 299], [111, 291], [93, 258], null],
  mount,
});

windup.code:
/**
 * Water wheel: a paddle wheel on its axle between two posts, over a wooden
 * flume. The pointer is the current: moving along the flume turns the wheel
 * on a spring, and the top paddle is bright. At rest the
 * wheel sits a little turned, its top paddle bright.
 */
const { Cam, fit, prism, proj, rings, unproj, spring, stepS, disposer, mk, pointer, put, register, solid, clamp, poly } = HL;

const R = 34, IN = 22, ZC = 48, YW = 8, N = 10, REST = 0.18;
const ang = (k, a) => a + (k / N) * Math.PI * 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-60, -16, 0], [60, 16, 0], [-R - 5, 0, ZC], [R + 5, 0, ZC], [0, -YW, ZC + R + 5], [0, YW, ZC - R - 5]], 200, 160);
  const P = proj(C), fr = HL.facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, fr, ...rings(-58, -14, 58, 14, 3, 1.2), 0, 7));
  const post = (y0, y1) => put(solid(g), prism(P, fr, ...rings(-2.5, y0, 2.5, y1, 1, 0.5), 7, ZC + 1));
  post(-15, -11);
  const rim = (y, r) => { const pts = []; for (let i = 0; i < 48; i++) { const t = (i / 48) * Math.PI * 2; pts.push(P(r * Math.cos(t), y, ZC + r * Math.sin(t))); } return poly(pts); };
  mk("path", { class: "nf sil", d: rim(-YW, R) + rim(-YW, IN) }, g);
  const wheel = mk("g", {}, g);
  const paddles = [];
  for (let k = 0; k < N; k++) paddles.push({ k, el: mk("polygon", { class: "sil" }, wheel) });
  const spokes = mk("path", { class: "nf lo" }, g);
  mk("path", { class: "nf sil", d: rim(YW, R) + rim(YW, IN) }, g);
  mk("path", { class: "sil", d: rim(YW + 1, 5) }, g);
  post(11, 15);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, active = false, hiK = -1;

  function quad(t) {
    const c = Math.cos(t), s = Math.sin(t), a = IN - 2, b = R + 6;
    return [P(a * c, -YW, ZC + a * s), P(b * c, -YW, ZC + b * s), P(b * c, YW, ZC + b * s), P(a * c, YW, ZC + a * s)];
  }
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    let d = "";
    for (const p of paddles) {
      const t = ang(p.k, a);
      p.el.setAttribute("points", quad(t).map((q) => q.join(",")).join(" "));
      p.depth = 0.61 * Math.cos(t) + 0.5 * Math.sin(t);
      d += "M" + P(0, YW, ZC).join(",") + "L" + P(IN * Math.cos(t), YW, ZC + IN * Math.sin(t)).join(",");
    }
    spokes.setAttribute("d", d);
    [...paddles].sort((p, q) => p.depth - q.depth).forEach((p) => wheel.appendChild(p.el));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function paint() {
    // bright: the paddle that will stand nearest the top once the wheel lands
    let best = 0, bv = -Infinity;
    for (const p of paddles) { const v = Math.sin(ang(p.k, sp.t)); if (v > bv) { bv = v; best = p.k; } }
    const k = best;
    if (k !== hiK) { hiK = k; for (const p of paddles) p.el.classList.toggle("hi", p.k === k); }
    read.textContent = active ? "turn " + Math.round(((sp.t - REST) * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(x) > 80 || Math.abs(y) > 70) { active = false; sp.t = REST; }
      else { active = true; sp.t = REST + clamp(x, -60, 60) * 0.045; }
      paint();
    },
    leave: () => { active = false; sp.t = REST; paint(); },
  }));
  bag.add(() => svg.replaceChildren());
  paint();
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "windup",
  means: "A water wheel over its flume: running the pointer along the flume turns the wheel, and its top paddle is bright.",
  rules: [3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[287, 266], [131, 257], [105, 175], null],
  mount,
});

bankvault2.code:
/**
 * Bank teller window: a counter with a glazed partition, and the pass-through
 * drawer under the glass. The pointer's distance in front of the window sets
 * how far the drawer slides out toward it; a coin rides in the tray. At rest
 * the drawer sits a little open, bright.
 *
 * The pattern: one part following the pointer (spring).
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, clamp, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const W = 120, D = 80, CZ = 10, WY = 26, WT = 5, WH = 92, DX0 = 28, DX1 = 92, DH = 12, REST = 9, MAX = 56;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [0, WY, WH], [W, WY, WH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-4, -4, W + 4, D + 4, 5, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));
  // the partition, glass window and drawer slot on its near face
  const [wr, wi] = rings(-2, WY - WT, W + 2, WY, 2, 1.2);
  put(solid(g), prism(P, front, wr, wi, CZ, WH));
  const face = (x0, x1, z0, z1, r) => poly(fillet([P(x0, WY, z0), P(x1, WY, z0), P(x1, WY, z1), P(x0, WY, z1)], [r, r, r, r]));
  mk("path", { d: face(16, W - 16, 40, WH - 10, 4), class: "nf lo" }, g);
  mk("path", { d: face(20, W - 20, 44, WH - 14, 3), class: "nf lo" }, g);
  for (let i = 0; i < 5; i++) { const d = mk("circle", { r: 1.3, class: "dot off" }, g); place(d, P(W / 2 - 8 + i * 4, WY, 34)); }
  mk("path", { d: face(DX0 - 3, DX1 + 3, CZ + 1, CZ + DH + 3, 2), class: "nf lo" }, g);

  const dg = mk("g", {}, g);
  const tray = solid(dg), floor = mk("path", { class: "nf lo" }, dg), lip = mk("path", { class: "nf" }, dg);
  const coin = mk("ellipse", { class: "dot m" }, dg);
  const ext = spring(REST);
  let last = NaN;
  function draw(e) {
    if (e === last) return;
    last = e;
    const y0 = WY, y1 = WY + e;
    const [r1, i1] = rings(DX0, y0, DX1, y1, 3, 1.4);
    put(tray, prism(P, front, r1, i1, CZ, CZ + DH));
    floor.setAttribute("d", poly(fillet([P(DX0 + 3, y0, CZ + 3), P(DX1 - 3, y0, CZ + 3), P(DX1 - 3, y1 - 3, CZ + 3), P(DX0 + 3, y1 - 3, CZ + 3)], [1, 2, 2, 2])));
    // the pull: a low bar on the near face
    lip.setAttribute("d", poly(fillet([P(DX0 + 14, y1 + 2.5, CZ + 5), P(DX1 - 14, y1 + 2.5, CZ + 5), P(DX1 - 14, y1 + 2.5, CZ + 8), P(DX0 + 14, y1 + 2.5, CZ + 8)], [1.5, 1.5, 1.5, 1.5])));
    const c = P(DX0 + 16, y0 + Math.max(4, e - 8), CZ + 3);
    coin.setAttribute("cx", c[0]); coin.setAttribute("cy", c[1]);
    coin.setAttribute("rx", 7); coin.setAttribute("ry", 3.5);
  }
  draw(REST);
  tray.sil.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(ext, dt); draw(ext.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, CZ);
    const inside = x > -10 && x < W + 10 && y > WY && y < D + 30;
    if (!inside) return leave();
    const t = clamp((y - WY) / (D - WY), 0, 1);
    ext.t = clamp(REST + (MAX - REST) * t * (reach / 100), 6, MAX);
    read.textContent = "out " + Math.round(ext.t);
    B.wake();
  }
  function leave() { ext.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "bankvault2",
  means: "A teller window: the drawer under the glass slides out toward the pointer as it comes to the counter's front.",
  rules: [1, 3, 5, 8],
  range: [40, 100, 100],
  tour: [[128, 181], [148, 244], [222, 279], null],
  mount,
});

ledgerlamp.code:
/**
 * Banker lamp: a desk with a footed brass stem and a long half-round shade.
 * The pointer on the desk tilts the shade toward it, and the dashed pool of
 * light slides across the desk to meet it. At rest the shade tips a little
 * forward, bright.
 *
 * The pattern: one part following the pointer (spring).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, ringAt, clamp, rad, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 150, D = 110, DZ = 8, LX = 75, LY = 34, PZ = 66, L = 84, R = 15, REST = -16, MAXT = 80;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.78);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [LX - L / 2, LY - R, PZ + R + 2], [LX + L / 2, LY - R, PZ + R + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-4, -4, W + 4, D + 4, 6, 2);
  put(solid(g), prism(P, front, dr, di, 0, DZ));
  const pool = mk("path", { class: "nf dash" }, g);
  // foot, stem, and the arm that holds the shade
  const foot = rrect(LX - 22, LY - 12, LX + 22, LY + 12, 11, 8), footIn = rrect(LX - 20, LY - 10, LX + 20, LY + 10, 9, 8);
  put(solid(g), prism(P, front, foot, footIn, DZ, DZ + 5));
  const [sr, si] = rings(LX - 2, LY - 2, LX + 2, LY + 2, 2, 0.6);
  put(solid(g), prism(P, front, sr, si, DZ + 5, PZ - 4));
  const [ar, ai] = rings(LX - 14, LY - 1.5, LX + 14, LY + 1.5, 1.5, 0.5);
  put(solid(g), prism(P, front, ar, ai, PZ - 6, PZ - 3));

  const sh = solid(g), rim = mk("path", { class: "nf lo" }, g), chain = mk("path", { class: "nf lo" }, g), bead = mk("circle", { r: 2, class: "dot m" }, g);
  const tilt = spring(REST);
  const W3 = (x, y, z, a) => P(x, LY + y * Math.cos(a) - z * Math.sin(a), PZ + y * Math.sin(a) + z * Math.cos(a));
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [], near = [];
    for (let i = 0; i <= 16; i++) {
      const t = (i / 16) * Math.PI, y = R * Math.cos(t), z = R * Math.sin(t);
      pts.push(W3(LX - L / 2, y, z, a), W3(LX + L / 2, y, z, a));
      near.push(W3(LX + L / 2, y, z, a));
    }
    put(sh, { sil: poly(hull(pts)), crease: open([W3(LX - L / 2 + 2, R, 0, a), W3(LX + L / 2 - 2, R, 0, a)]) });
    rim.setAttribute("d", open(near));
    const tip = W3(LX + L / 2 - 8, R, 0, a), lo = [tip[0], tip[1] + 16];
    chain.setAttribute("d", open([tip, lo]));
    bead.setAttribute("cx", lo[0]); bead.setAttribute("cy", lo[1] + 2);
    const py = clamp(LY + 4 + 72 * Math.sin(a), 12, D - 14);
    pool.setAttribute("d", poly(ringAt(P, rrect(LX - 46, py - 13, LX + 46, py + 13, 13, 8), DZ)));
  }
  draw(REST);
  sh.sil.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(tilt, dt); draw(tilt.x); return m; });
  bag.add(B.unregister);

  function leave() { tilt.t = REST; read.textContent = "rest"; B.wake(); }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, DZ);
    if (x < -10 || x > W + 10 || y < -10 || y > D + 20) return leave();
    const t = clamp((y - LY) / (D - LY), 0, 1);
    tilt.t = clamp(10 + (MAXT - 10) * t * (reach / 100), 0, MAXT);
    read.textContent = Math.round(tilt.t) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "ledgerlamp",
  means: "A banker lamp on a desk: its long shade tilts toward the pointer and the pool of light slides across the desk to it.",
  rules: [1, 3, 5, 8],
  range: [40, 100, 100],
  tour: [[162, 140], [138, 234], [250, 259], null],
  mount,
});

moneyclip2.code:
/**
 * Card wallet: a bifold lying open, three cards stepped in the slots of its
 * left leaf. The pointer swings the right leaf about the spine: toward the
 * right it lays the wallet flat open, toward the cards it folds shut over
 * them. At rest the leaf stands half open, bright.
 *
 * The pattern: one part following the pointer (spring), a hinge.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, rad, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, place,
} = HL;

const LW = 72, D = 64, T = 3.5, REST = 62;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-LW, 0, 0], [LW, D, 0], [LW, 0, 0], [-LW, D, 0], [0, 0, LW + 4], [0, D, LW + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [lr, li] = rings(-LW, 0, 0, D, 5, 1.6);
  put(solid(g), prism(P, front, lr, li, 0, T));
  // three cards in stepped slots, far to near
  for (let k = 0; k < 3; k++) {
    const [cr, ci] = rings(-LW + 7, 7 + k * 11, -7, D - 6, 3, 1);
    put(solid(g), prism(P, front, cr, ci, T + k * 0.7, T + k * 0.7 + 0.8));
  }
  const leaf = solid(g), face = mk("path", { class: "nf lo" }, g), snap = mk("circle", { r: 2.4, class: "dot m" }, g);
  const outer = rrect(0, 0, LW, D, 5, 4), inner = rrect(6, 6, LW - 6, D - 6, 3, 4);
  const ang = spring(REST);
  let last = NaN;
  const at = (u, y, off, a) => P(u * Math.cos(a) - off * Math.sin(a), y, T * 0.5 + u * Math.sin(a) + off * Math.cos(a));
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const s of outer) pts.push(at(s.u, s.v, 0, a), at(s.u, s.v, T, a));
    const off = deg < 100 ? T : 0;
    put(leaf, { sil: poly(hull(pts)), crease: "" });
    face.setAttribute("d", poly(inner.map((s) => at(s.u, s.v, off, a))));
    place(snap, at(LW - 10, D / 2, off, a));
  }
  draw(REST);
  leaf.sil.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -LW - 12 || x > LW + 12 || y < -12 || y > D + 12) return leave();
    const t = clamp((x + LW) / (2 * LW), 0, 1);
    ang.t = clamp(REST + (lerp2(166, 4, t) - REST) * (reach / 100), 4, 166);
    read.textContent = Math.round(180 - ang.t) + "°";
    B.wake();
  }
  const lerp2 = (a, b, t) => a + (b - a) * t;
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "moneyclip2",
  means: "A bifold card wallet: its free leaf swings about the spine, flat open toward the right, folding shut over the cards toward the left.",
  rules: [1, 3, 5, 8],
  range: [40, 100, 100],
  tour: [[86, 164], [151, 246], [314, 279], null],
  mount,
});

abacus2.code:
/**
 * Check stamp: an endorsement stamp over a paper check on the desk. The
 * stamp slides to the spot under the pointer and presses down onto the
 * check; leaving lifts it back to its corner. At rest it hangs raised over
 * the check's right end, bright. The slider is how hard it presses.
 */
const {
  Cam, circ, clamp, fit, facing, poly, prism, proj, rings, unproj, spring, stepS, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 120, D = 56, PZ = 1.6, REST = [96, 30, 22];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let press = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [REST[0], REST[1], REST[2] + 34], [16, 12, 40]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(0, 0, W, D, 3, 1.2);
  put(solid(g), prism(P, front, cr, ci, 0, PZ));
  // the check's own marks: payee line, amount box, signature line, perforation
  mk("path", { class: "lo nf", d: seg(P(12, 22, PZ), P(78, 22, PZ)) + seg(P(12, 44, PZ), P(60, 44, PZ)) }, g);
  mk("path", { class: "lo nf", d: poly([P(86, 14, PZ), P(110, 14, PZ), P(110, 26, PZ), P(86, 26, PZ)]) }, g);
  mk("path", { class: "dash", d: seg(P(6, 4, PZ), P(6, D - 4, PZ)) }, g);

  const sg = mk("g", {}, g), pad = solid(sg), neck = solid(sg), knob = solid(sg);
  const sx = spring(REST[0]), sy = spring(REST[1]), sz = spring(REST[2]);
  let last = "";
  function draw() {
    const x = sx.x, y = sy.x, z = sz.x, key = [x, y, z].map((v) => v.toFixed(2)).join();
    if (key === last) return;
    last = key;
    const [pr, pi] = rings(x - 17, y - 10, x + 17, y + 10, 3, 1.4);
    put(pad, prism(P, front, pr, pi, z, z + 9));
    put(neck, prism(P, front, disc(x, y, 4), disc(x, y, 3), z + 9, z + 22));
    put(knob, prism(P, front, disc(x, y, 9), disc(x, y, 7.4), z + 22, z + 31));
  }

  const B = register(stage, (dt) => {
    const m = [stepS(sx, dt), stepS(sy, dt), stepS(sz, dt)].some(Boolean);
    draw();
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      const on = wx > -10 && wx < W + 10 && wy > -10 && wy < D + 10;
      sx.t = clamp(wx, 17, W - 17); sy.t = clamp(wy, 10, D - 10); sz.t = on ? PZ + 14 * (1 - press) : REST[2];
      read.textContent = on ? "press " + Math.round(sx.t / 20) + "·" + Math.round(sy.t / 20) : "rest";
      pad.sil.classList.toggle("hi", true);
    } else {
      sx.t = REST[0]; sy.t = REST[1]; sz.t = REST[2];
      read.textContent = "rest";
      pad.sil.classList.toggle("hi", true);
    }
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { press = v; }, destroy: bag.dispose };
}

hairline({
  name: "abacus2",
  means: "An endorsement stamp over a paper check: it slides to the spot under the pointer and presses down onto the check.",
  rules: [1, 3, 5, 8],
  range: [0, 0.8, 1],
  tour: [[150, 135], [139, 172], [245, 250], null],
