petbath2.code:
/**
 * Pet stairs: four carpeted steps set against the side of a sofa. The
 * pointer picks a step by where it stands on it, and the stair parts there:
 * that step and the ones below it slide out from the sofa, staggered from
 * the touched step, opening gaps a paw could fit. At rest the stair is
 * slightly loose with one step bright. The slider is the stagger.
 */
const {
  Cam, fit, facing, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, SX = 42, STEP = 17, RISE = 11, Y0 = 22, Y1 = 70, FAV = 1, REST = [0, 3, 7, 12];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [SX + N * STEP + 46, 92, 0], [SX + N * STEP + 46, 0, 0], [0, 92, 0], [0, 0, 74]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, z0, z1, r = 4, b = 1.6) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(parent); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(g, 0, 0, 14, 92, 6, 74, 6, 2);
  box(g, 0, 0, 42, 12, 6, 58, 5, 2);
  box(g, 2, 2, 42, 90, 6, 42, 5, 2);
  box(g, 10, 10, 42, 82, 42, 48, 4, 1.6);
  box(g, 0, 80, 42, 92, 6, 58, 5, 2);
  for (const [x, y] of [[4, 4], [38, 4], [4, 88], [38, 88]]) box(g, x - 2, y - 2, x + 2, y + 2, 0, 6, 1.5, 0.6);

  const steps = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    steps.push({ k, grp, s: solid(grp), off: tween(REST[k]), last: NaN, h: (N - k) * RISE });
  }
  function draw(st, o) {
    if (o === st.last) return;
    st.last = o;
    const x0 = SX + st.k * STEP + o;
    const [r, i] = rings(x0, Y0, x0 + STEP, Y1, 3, 1.4);
    put(st.s, prism(P, front, r, i, 0, st.h));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const st of steps) { draw(st, tval(st.off, now)); if (!tdone(st.off, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    for (const st of steps) {
      const [wx, wy] = unproj(C, sx, sy, st.h), cx = SX + st.k * STEP + REST[st.k] + STEP / 2;
      const dd = Math.max(Math.abs(wx - cx) - STEP / 2, 0) + Math.max(Math.abs(wy - (Y0 + Y1) / 2) - (Y1 - Y0) / 2, 0);
      if (dd < bd || (dd === bd && st.k > best)) { bd = dd; best = st.k; }
    }
    return bd < 12 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : Math.max(act, 0);
    act = a;
    steps.forEach((st, k) => {
      const o = a < 0 ? REST[k] : k < a ? 0 : 14 + (k - a) * 10;
      tset(st.off, o, now, Math.abs(k - from) * stag);
      st.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "step " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "petbath2",
  means: "Pet stairs against a sofa: the stair parts at the step under the pointer, that step and those below sliding out.",
  rules: [1, 2, 5, 6, 8],
  range: [0, 45, 90],
  tour: [[176, 162], [198, 189], [240, 227], null],
  mount,
});

waffleiron2.code:
/**
 * Panini press: a ridged base plate with a sandwich on it and a heavy lid
 * hinged along the back edge. The pointer lifts the lid: the higher it is on
 * the stage, the wider the lid swings open on a spring, showing the ridges
 * under it. At rest the lid sits ajar over the sandwich, bright.
 */
const {
  Cam, facing, fit, prism, proj, rrect, rings, hull, poly, open, seg, spring, stepS, clamp, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 38, D = 28, HB = 14, T = 9, REST = 14, MAX = 108;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.4);
  const L = (u, v, w, th) => [u, -D + v * Math.cos(th) - w * Math.sin(th), HB + v * Math.sin(th) + w * Math.cos(th)];
  const ext = [[-W - 2, -D - 12, 0], [W + 2, D + 4, 0], [-W, D, 0], [W, -D - 12, 0]];
  [REST, 60, MAX].forEach((d) => [[-W, 62, T], [W, 62, T], [W, 0, T], [-W, 62, 0]].forEach(([u, v, w]) => ext.push(L(u, v, w, rad(d)))));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // base and its ridges, then the sandwich
  const BR = rings(-W, -D, W, D, 6, 1.6);
  put(solid(g), prism(P, front, BR[0], BR[1], 0, HB));
  let rid = "";
  for (let i = 0; i < 7; i++) { const y = -D + 6 + i * 7.3; rid += seg(P(-W + 6, y, HB), P(W - 6, y, HB)); }
  mk("path", { class: "nf lo", d: rid }, g);
  const SR = rings(-24, -16, 22, 18, 5, 1.2);
  put(solid(g), prism(P, front, SR[0], SR[1], HB, HB + 4.5));
  // the lid
  const lid = solid(g), under = mk("path", { class: "nf lo", d: "" }, g);
  lid.sil.classList.add("hi");
  const LR = rrect(-W, 0, W, 62, 6, 6), LI = rrect(-W + 1.8, 1.8, W - 1.8, 60.2, 4.2, 6);
  const sp = spring(rad(REST), { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const th = sp.x;
    if (Math.abs(th - drawn) < 1e-4) return;
    drawn = th;
    const bot = LR.map((q) => P(...L(q.u, q.v, 0, th))), top = LR.map((q) => P(...L(q.u, q.v, T, th)));
    lid.sil.setAttribute("d", poly(hull(bot.concat(top))));
    const showTop = 0.5 * Math.cos(th) - 0.61 * Math.sin(th) > 0;
    if (showTop) {
      lid.cr.setAttribute("d", poly(LI.map((q) => P(...L(q.u, q.v, T, th)))));
      under.setAttribute("d", "");
      lid.g.after(under);
    } else {
      lid.cr.setAttribute("d", poly(LI.map((q) => P(...L(q.u, q.v, 0, th)))));
      let d = "";
      for (let i = 0; i < 7; i++) { const v = 8 + i * 7.6; d += seg(P(...L(-W + 6, v, 0, th)), P(...L(W - 6, v, 0, th))); }
      under.setAttribute("d", d);
      lid.g.after(under);
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const t = clamp((250 - p[1]) / 170, 0, 1), deg = REST + t * (MAX - REST);
      sp.t = rad(deg);
      read.textContent = "open " + Math.round(deg) + "°";
      B.wake();
    },
    leave: () => { sp.t = rad(REST); read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "waffleiron2",
  means: "A panini press: the lid swings open on its back hinge as the pointer rises, showing the ridged plates and the sandwich.",
  rules: [3, 5, 6, 8],
  range: [0.5, 1, 1.6],
  tour: [[248, 48], [180, 219], [200, 306], null],
  mount,
});

spicegrinder.code:
/**
 * Pepper mill: a tall mill on a round dish, a square-cornered body and a
 * square-cornered head with a knob on top. The pointer twists the head: its
 * screen x is the turn, on a spring, and the head rises a little as it
 * unscrews. At rest the head sits a quarter-turn askew, bright.
 */
const {
  Cam, circ, facing, fit, prism, proj, rrect, rings, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const REST = 0.42, H0 = 54, H1 = 86;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([34 * Math.cos(a), 34 * Math.sin(a), 0]); }
  ext.push([0, 0, H1 + 18], [16, 16, H1 + 14], [-16, -16, H1 + 14]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // dish with a few grains of pepper
  put(solid(g), prism(P, front, circ(32, 64), circ(29.5, 64), 0, 3));
  const GR = [[-22, 6], [-18, 14], [8, 22], [14, 18], [-6, 24], [22, -4], [19, 9], [-24, -6]];
  GR.forEach(([x, y], i) => place(flatDot(g, C, 1, i % 3 ? "dot off" : "dot m"), P(x, y, 3)));
  // body: foot, waist and shoulder
  const BODY = rings(-11, -11, 11, 11, 4, 1.4), FOOT = rings(-13, -13, 13, 13, 5, 1.6);
  put(solid(g), prism(P, front, turn(FOOT[0], 0.2), turn(FOOT[1], 0.2), 3, 9));
  put(solid(g), prism(P, front, turn(BODY[0], 0.2), turn(BODY[1], 0.2), 9, H0));
  const collar = solid(g);
  put(collar, prism(P, front, circ(8, 32), circ(7, 32), H0, H0 + 3));
  const HEAD = [rrect(-13, -13, 13, 13, 5, 6), rrect(-11.6, -11.6, 11.6, 11.6, 3.6, 6)];
  const head = solid(g), neck = solid(g), knob = solid(g);
  head.sil.classList.add("hi");
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  const lift = spring(0);
  let drawn = NaN;
  function draw() {
    const a = sp.x, z = H0 + 2 + lift.x;
    if (Math.abs(a - drawn) < 1e-4 && Math.abs(lift.x - draw.l) < 1e-3) return;
    drawn = a; draw.l = lift.x;
    put(collar, prism(P, front, circ(8, 32), circ(7, 32), H0, z + 1));
    put(head, prism(P, front, turn(HEAD[0], a), turn(HEAD[1], a), z, z + (H1 - H0)));
    const top = z + (H1 - H0);
    put(neck, prism(P, front, turn(rrect(-3, -3, 3, 3, 1.2, 3), a), null, top, top + 5));
    put(knob, prism(P, front, turn(rrect(-6, -6, 6, 6, 2.6, 4), a), turn(rrect(-5, -5, 5, 5, 1.8, 4), a), top + 5, top + 10));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt) | stepS(lift, dt); draw(); return !!m; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const t = clamp((p[0] - 200) / 120, -1, 1);
      sp.t = REST + t * Math.PI * 0.75;
      lift.t = 9 * Math.abs(t);
      read.textContent = "turn " + Math.round(t * 135) + "°";
      B.wake();
    },
    leave: () => { sp.t = REST; lift.t = 0; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  draw();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "spicegrinder",
  means: "A tall pepper mill on a dish: the head twists with the pointer and rises a little as it unscrews.",
  rules: [3, 5, 8, 9],
  range: [0.5, 1, 1.6],
  tour: [[330, 259], [70, 259], [200, 60], null],
  mount,
});

saladspinner.code:
/**
 * Salad spinner: a round bowl on a foot ring, a lid with a pump plunger on a
 * tall rod. The pointer pumps it: the lower the pointer, the further the
 * knob is pressed down, and the vented lid turns with each stroke. At rest
 * the plunger stands up, its knob bright.
 */
const {
  Cam, circ, facing, fit, prism, proj, seg, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const R = 34, HB = 30, ROD = 34, LO = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([(R + 2) * Math.cos(a), (R + 2) * Math.sin(a), 0]); }
  ext.push([0, 0, HB + 3 + ROD + 8]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(R - 8, 48), circ(R - 9.4, 48), 0, 3));
  put(solid(g), prism(P, front, circ(R, 64), circ(R - 1.6, 64), 3, HB));
  put(solid(g), prism(P, front, circ(R + 2, 64), circ(R - 4, 64), HB, HB + 3));
  const vents = mk("path", { class: "nf lo", d: "" }, g);
  place(flatDot(g, C, 1.6, "dot m"), P(R * 0.62, R * 0.62, HB + 3));
  const rod = solid(g), knob = solid(g);
  knob.sil.classList.add("hi");
  const dp = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let spin = 0.3, drawn = NaN, prev = 0;
  function draw() {
    const d = dp.x;
    spin += Math.abs(d - prev) * 2.4; prev = d;
    if (Math.abs(d - drawn) < 1e-4) return;
    drawn = d;
    const zt = HB + 3 + LO + (ROD - LO) * (1 - d);
    let v = "";
    for (let i = 0; i < 8; i++) {
      const a = spin + (i / 8) * Math.PI * 2, c = Math.cos(a), s = Math.sin(a);
      v += seg(P(c * 11, s * 11, HB + 3), P(c * (R - 7), s * (R - 7), HB + 3));
    }
    vents.setAttribute("d", v);
    put(rod, prism(P, front, circ(3, 24), null, HB + 3, zt));
    put(knob, prism(P, front, circ(10, 40), circ(8.8, 40), zt, zt + 6));
  }
  const B = register(stage, (dt) => { const m = stepS(dp, dt); draw(); return m; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const t = clamp((p[1] - 70) / 160, 0, 1);
      dp.t = t;
      read.textContent = "pump " + Math.round(t * 100) + "%";
      B.wake();
    },
    leave: () => { dp.t = 0; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  draw();
  return {
    set: (v) => { dp.k = 100 * v; dp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "saladspinner",
  means: "A salad spinner: the pointer presses the pump knob down its rod, and the vented lid turns with every stroke.",
  rules: [3, 5, 8, 9],
  range: [0.5, 1, 1.6],
  tour: [[200, 275], [200, 75], [96, 224], null],
  mount,
});

podium3.code:
/**
 * Voting booth curtain: a booth with a back wall, a side wall and a writing
 * shelf, a rail across its open front and a pleated curtain hung from it.
 * The pointer's place along the rail is where the curtain's edge goes: the
 * pleats fold up like an accordion as it opens and flatten as it closes.
 * At rest it is part drawn, its leading pleat bright. The slider is the rest opening.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, clamp, lerp, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 90, D = 40, H = 70, N = 9, PW = W / N, MINE = 3.6 * N;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restE = lerp(MINE, W, value / 100);
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-4, -4, 0], [W + 4, D + 14, 0], [W + 4, -4, 0], [-4, D + 14, 0], [0, 0, H + 6], [W, D, H + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const add = (x0, y0, x1, y1, z0, z1, r, b) => { const [a, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, a, i, z0, z1)); };
  add(-4, -4, W + 4, D + 4, 0, 3, 4, 1.4);
  add(0, 0, W, 3, 3, H, 1.2, 0.6);
  add(0, 3, 3, D, 3, H, 1.2, 0.6);
  add(22, 3, 66, 18, 36, 39, 1.5, 0.8);
  add(28, 6, 46, 15, 39, 40, 1, 0.4);
  // the rail: two posts and a bar along the front
  add(W - 2, D - 2, W + 2, D + 2, 3, H + 4, 2, 0.6);
  const rail = mk("path", { class: "nf" }, g);
  const ra = P(0, D, H + 2), rb = P(W, D, H + 2);
  rail.setAttribute("d", seg(ra, rb) + seg(P(0, D, H + 3.6), P(W, D, H + 3.6)));
  const cg = mk("g", {}, g);
  const pleats = [];
  for (let i = 0; i < N; i++) pleats.push(mk("path", { class: "sil" }, cg));
  const rings2 = mk("path", { class: "nf lo" }, cg);
  add(-2, D - 2, 2, D + 2, 3, H + 4, 2, 0.6);

  const E = spring(restE);
  let last = NaN;
  function draw(e) {
    if (e === last) return;
    last = e;
    const w = e / N, dep = Math.sqrt(Math.max(0, PW * PW - w * w)) * 0.9;
    let hooks = "";
    for (let i = 0; i < N; i++) {
      const xa = i * w, xb = xa + w, ya = D + (i % 2 ? dep : 0), yb = D + (i % 2 ? 0 : dep);
      pleats[i].setAttribute("d", poly([P(xa, ya, H), P(xb, yb, H), P(xb, yb, 6), P(xa, ya, 6)]));
      hooks += seg(P(xa, D, H + 2), P(xa, ya, H));
    }
    rings2.setAttribute("d", hooks);
  }
  draw(restE);
  const B = register(stage, (dt) => { const m = stepS(E, dt); draw(E.x); return m; });
  bag.add(B.unregister);
  pleats[N - 1].classList.add("hi");

  const top = P(0, D, H + 4)[1], bot = P(W, D, 0)[1];
  function hit([sx, sy]) {
    if (sy < top - 20 || sy > bot + 30) return -1;
    return clamp((sx - ra[0]) / (rb[0] - ra[0]), 0, 1);
  }
  function move(p) {
    const t = hit(p);
    E.t = t < 0 ? restE : clamp(t * W, MINE, W);
    read.textContent = t < 0 ? "rest" : Math.round((1 - (E.t - MINE) / (W - MINE)) * 100) + "% open";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { E.t = restE; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restE = lerp(MINE, W, v / 100); E.t = restE; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "podium3",
  means: "A voting booth with a pleated curtain on a rail: the curtain's edge follows the pointer, folding open and flattening shut.",
  rules: [1, 3, 5, 8],
  range: [20, 50, 80],
  tour: [[248, 207], [136, 151], [105, 135], null],
  mount,
});

flagstand.code:
/**
 * Flag stand: a weighted round base, a tall pole with a ball finial and a
 * flag hung from it. The flag swings round the pole to stream toward the
 * pointer, rippling along its length. At rest it hangs out to one side,
 * bright. The slider is the rest heading.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PH = 90, FT = 86, FB = 54, L = 80, K = 12;
const disc = (r, n = 32) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let rest = rad(value);
  const C = Cam(45, 0.5, 2.0);
  const box = [];
  for (let a = 0; a < 8; a++) box.push([Math.cos(a * Math.PI / 4) * L, Math.sin(a * Math.PI / 4) * L, FB - 4]);
  fit(C, box.concat([[0, 0, PH + 6], [-20, -20, 0], [20, 20, 0]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(18, 40), disc(16, 40), 0, 3));
  put(solid(g), prism(P, front, disc(11, 32), disc(9.5, 32), 3, 7));
  const fg = mk("g", {}, g);
  const flag = mk("path", { class: "sil hi" }, fg), hem = mk("path", { class: "nf lo" }, fg);
  const pg = mk("g", {}, g);
  put(solid(pg), prism(P, front, disc(1.6, 16), disc(1, 16), 7, PH));
  const ball = ringAt(P, disc(3.4, 16), PH + 3.4).concat(ringAt(P, disc(2.2, 16), PH + 6), ringAt(P, disc(2.2, 16), PH + 0.8));
  mk("path", { d: poly(hull(ball)) }, pg);

  const A = spring(rest), W = spring(0);
  let last = "";
  function draw(th, wv) {
    const key = th.toFixed(4) + wv.toFixed(3);
    if (key === last) return;
    last = key;
    const c = Math.cos(th), s = Math.sin(th), top = [], bot = [], mid = [];
    for (let i = 0; i <= K; i++) {
      const d = (i / K) * L, off = Math.sin(i / K * 5 + wv) * 4.5 * (i / K);
      const x = c * d - s * off, y = s * d + c * off, sag = (i / K) * 3;
      top.push(P(x, y, FT - sag * 0.4)); bot.push(P(x, y, FB - sag)); mid.push(P(x, y, (FT + FB) / 2 - sag * 0.7));
    }
    flag.setAttribute("d", poly(top.concat(bot.reverse())));
    hem.setAttribute("d", "M" + mid.map((q) => q.join(",")).join("L"));
    fg.parentNode.insertBefore(pg, c + s > 0 ? fg : fg.nextSibling);
  }
  draw(rest, 0);
  const B = register(stage, (dt) => {
    const m1 = stepS(A, dt), m2 = stepS(W, dt);
    draw(A.x, W.x);
    return m1 || m2;
  });
  bag.add(B.unregister);

  function aim(th) {
    let t = th;
    while (t - A.t > Math.PI) t -= 2 * Math.PI;
    while (t - A.t < -Math.PI) t += 2 * Math.PI;
    W.t += (t - A.t) * 0.8;
    A.t = t;
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, (FT + FB) / 2);
    if (Math.hypot(x, y) < 4) return;
    aim(Math.atan2(y, x));
    read.textContent = String(((Math.round(A.t * 180 / Math.PI) % 360) + 360) % 360).padStart(3, "0") + "°";
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { aim(rest); read.textContent = "rest"; } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { rest = rad(v); aim(rest); }, destroy: bag.dispose };
}

