vise.code:
/**
 * Bench vise: a fixed jaw on its rail and a sliding jaw driven by the screw,
 * with the tommy bar at the end. The pointer is where the jaw slides to: its
 * x along the rail opens or closes the jaws on a spring. At rest the jaws stand
 * a little open, the sliding jaw bright.
 */
const {
  Cam, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const J0 = 14, JMIN = 3, JMAX = 40;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-44, -20, 0], [-44, 20, 0], [88, -22, 30], [88, 22, 30], [-44, -18, 36], [0, 18, 36], [88, 0, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  put(solid(g), prism(P, front, ...rings(-44, -14, 12, 14, 3, 1.2), 0, 4));
  put(solid(g), prism(P, front, ...rings(-36, -9, 8, 9, 2.5, 1), 4, 10));
  put(solid(g), prism(P, front, ...rings(-42, -18, -30, 18, 2.5, 1), 10, 36));
  const mv = mk("g", {}, g);
  const slide = solid(mv), jaw = solid(mv), boss = solid(mv);
  const rod = mk("path", { class: "nf sil" }, mv);
  const bar = mk("path", { class: "nf sil" }, mv);
  const k1 = flatDot(mv, C, 1.6, "dot m"), k2 = flatDot(mv, C, 1.6, "dot m");
  jaw.sil.classList.add("hi");

  const sp = spring(J0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const j = sp.x;
    if (Math.abs(j - drawn) < 1e-3) return;
    drawn = j;
    const x0 = -30 + j;
    put(slide, prism(P, front, ...rings(x0, -7, x0 + 34, 7, 2, 0.8), 10, 18));
    put(jaw, prism(P, front, ...rings(x0, -18, x0 + 12, 18, 2.5, 1), 10, 36));
    put(boss, prism(P, front, ...rings(x0 + 34, -5, x0 + 40, 5, 2, 0.8), 14, 26));
    rod.setAttribute("d", seg(P(x0 + 40, -1.4, 20), P(x0 + 56, -1.4, 20)) + seg(P(x0 + 40, 1.4, 20), P(x0 + 56, 1.4, 20)));
    const hx = x0 + 56;
    bar.setAttribute("d", seg(P(hx, -20, 21), P(hx, 20, 21)) + seg(P(hx, -20, 19), P(hx, 20, 19)));
    place(k1, P(hx, -21, 20)); place(k2, P(hx, 21, 20));
  }
  draw();

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(t) {
    sp.t = t;
    read.textContent = t === J0 && !live ? "rest" : Math.round(t) + " mm";
    B.wake();
  }
  let live = false;
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(y) > 50 || x < -70 || x > 110) { live = false; aim(J0); return; }
      live = true; aim(clamp(Math.round(x - 4), JMIN, JMAX));
    },
    leave: () => { live = false; aim(J0); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "vise",
  means: "A bench vise: the sliding jaw follows the pointer along the rail, opening and closing on its screw.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[121, 176], [231, 231], [268, 250], null],
  mount,
});

sawhorse.code:
/**
 * Folding sawhorse: a beam on two pairs of hinged legs. The pointer's distance
 * from the beam, across it on the floor, is how far the legs splay: spread them
 * and the beam drops, fold them and it rises. At rest it stands half open, the
 * beam bright.
 */
const {
  Cam, facing, fit, prism, proj, rings, unproj, spring, stepS, clamp, fillet, poly, seg,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const L = 50, S0 = 17, SMIN = 5, SMAX = 32, XL = [-30, 30], BW = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-44, -SMAX, 0], [44, SMAX, 0], [-44, -SMAX, 0], [44, -4, 56], [-44, 4, 56], [44, SMAX, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g), beam = solid(g), fore = mk("g", {}, g);
  const legs = [];
  for (const side of [-1, 1]) for (const x of XL) {
    const par = side < 0 ? back : fore;
    legs.push({ side, x, el: mk("path", { class: "sil" }, par), lo: mk("path", { class: "lo nf" }, par), dot: flatDot(par, C, 1.3, "dot off") });
  }
  const brace = mk("path", { class: "lo nf" }, back);
  beam.sil.classList.add("hi");

  const sp = spring(S0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const s = sp.x;
    if (Math.abs(s - drawn) < 1e-3) return;
    drawn = s;
    const h = Math.sqrt(L * L - s * s);
    for (const l of legs) {
      const y0 = l.side * BW, y1 = l.side * s, a = l.x - 2.6 * Math.sign(l.x) - 2.4, b = a + 4.8;
      const q = [P(a, y0, h), P(b, y0, h), P(b + Math.sign(l.x) * 3, y1, 0), P(a + Math.sign(l.x) * 3, y1, 0)];
      l.el.setAttribute("d", poly(fillet(q, [1, 1, 1, 1])));
      l.lo.setAttribute("d", seg(P(a + 1.2, y0, h - 1), P(a + 1.2 + Math.sign(l.x) * 3, y1, 1)));
      place(l.dot, P(l.x + Math.sign(l.x) * 3, y1, 0));
    }
    const m = 0.45;
    brace.setAttribute("d", seg(P(XL[0] + 1, -BW - (s - BW) * m, h * (1 - m)), P(XL[1] - 1, -BW - (s - BW) * m, h * (1 - m))));
    put(beam, prism(P, front, ...rings(-44, -BW - 1, 44, BW + 1, 2, 1), h, h + 6));
  }
  draw();

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(t, live) {
    sp.t = t;
    read.textContent = live ? Math.round((2 * Math.atan(t / Math.sqrt(L * L - t * t)) * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(x) > 70 || Math.abs(y) > 60) { aim(S0, false); return; }
      aim(clamp(Math.round(Math.abs(y)), SMIN, SMAX), true);
    },
    leave: () => aim(S0, false),
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "sawhorse",
  means: "A folding sawhorse: the legs splay as far as the pointer is from the beam, and the beam drops as they spread.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[192, 212], [147, 235], [283, 200], null],
  mount,
});

wagon2.code:
/**
 * Pull wagon: a child's wagon, a rounded tub on four spoked wheels with a
 * long pull handle on a pivot at its nose. The pointer is where the child
 * pulls from: the handle swings round its pivot to point at it, on a spring,
 * clamped to the reach of a real pivot. At rest the handle lies off to one
 * side and the tub's rim is bright.
 *
 * The pattern: a continuous aim (one spring on the handle's angle); the hit
 * is on the floor's plane, which never moves.
 */
const {
  Cam, fit, poly, prism, proj, rings, seg, unproj, spring, stepS, clamp, rad, facing,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const L = 50, PX = 36, PZ = 9, REST = rad(-26), MAXA = rad(78), WR = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-36, -24, 0], [PX + L, -L, 0], [PX + L, L, 0], [-36, 24, 30], [PX, 0, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  mk("path", { class: "dash", d: seg(P(-40, 0, 0), P(PX, 0, 0)) }, g);

  const wheel = (x, y) => {
    const pts = [], sp = [];
    for (let i = 0; i < 28; i++) { const a = (i / 28) * Math.PI * 2; pts.push(P(x + WR * Math.cos(a), y, WR + WR * Math.sin(a))); }
    for (let i = 0; i < 5; i++) { const a = (i / 5) * Math.PI * 2 + 0.3; sp.push(seg(P(x, y, WR), P(x + (WR - 2) * Math.cos(a), y, WR + (WR - 2) * Math.sin(a)))); }
    const w = mk("g", {}, g);
    mk("path", { class: "sil", d: poly(pts) }, w);
    mk("path", { class: "nf lo", d: sp.join("") }, w);
    place(flatDot(w, C, 0.9, "dot off"), P(x, y, 0));
  };
  // far wheels, the axles, the tub, the near wheels
  wheel(-22, -21); wheel(22, -21);
  mk("path", { class: "nf lo", d: seg(P(-22, -21, WR), P(-22, 21, WR)) + seg(P(22, -21, WR), P(22, 21, WR)) }, g);
  const [ring, inner] = rings(-32, -17, 32, 17, 6, 1.6);
  const tub = solid(g);
  put(tub, prism(P, front, ring, inner, 12, 30));
  mk("path", { class: "nf lo", d: seg(P(-26, 17, 16), P(26, 17, 16)) }, g);
  wheel(-22, 21); wheel(22, 21);
  mk("path", { class: "nf sil", d: seg(P(30, 0, 12), P(PX, 0, PZ)) }, g);
  const pivot = flatDot(g, C, 1.4, "dot m");
  place(pivot, P(PX, 0, 0));
  const handle = mk("path", { class: "nf sil" }, g);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a), h = L * 0.92, tz = PZ + L * 0.39;
    const tx = PX + h * c, ty = h * s;
    handle.setAttribute("d",
      seg(P(PX - s, c, PZ), P(tx - s, ty + c, tz)) + seg(P(PX + s, -c, PZ), P(tx + s, ty - c, tz)) +
      seg(P(tx - 8 * s, ty + 8 * c, tz), P(tx + 8 * s, ty - 8 * c, tz)) +
      seg(P(tx - 8 * s, ty + 8 * c, tz + 2.4), P(tx + 8 * s, ty - 8 * c, tz + 2.4)) +
      seg(P(PX + 4 * c - 2 * s, 4 * s + 2 * c, PZ + 1.7), P(PX + 4 * c + 2 * s, 4 * s - 2 * c, PZ + 1.7)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function show(on) {
    tub.sil.classList.toggle("hi", !on);
    handle.classList.toggle("hi", on);
    read.textContent = on ? Math.round((sp.t * 180) / Math.PI) + "°" : "rest";
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), dx = x - PX, d = Math.hypot(dx, y);
      if (d > L + 40 || x < -50) { sp.t = REST; show(false); }
      else if (d > 6) { sp.t = clamp(Math.atan2(y, dx), -MAXA, MAXA); show(true); }
      B.wake();
    },
    leave: () => { sp.t = REST; show(false); B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  show(false);
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "wagon2",
  means: "A child's pull wagon whose long handle swings round its pivot to point at the pointer, the way a child would pull it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[293, 245], [118, 254], [359, 103], null],
  mount,
});

gpsunit.code:
/**
 * Car GPS: a navigation screen on a suction-cup arm, stuck to a slab of
 * dashboard. The screen carries a dim route and a bright position dot. The
 * pointer is the driver: the screen swivels on its ball joint to face it,
 * on a spring, clamped so its face never turns away. At rest it sits a little
 * askew toward the passenger. The slider is how stiff the joint is.
 *
 * The pattern: a continuous aim on one angle; the hit is the dashboard's
 * plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, hull, fillet, poly, open, seg,
  spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid, clamp,
} = HL;

const W = 25, H = 15, TH = 5, ZC = 32, VIEW = Math.PI / 4, SPAN = 1.25;
const REST = VIEW - 0.5, CUP = [-12, -12];
const ROUTE = [[-18, -9], [-8, -9], [-3, -2], [8, -2], [12, 6]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.0);
  const frame = (a, u, d, v) => {
    const nx = Math.cos(a), ny = Math.sin(a);
    return [-ny * u + nx * d, nx * u + ny * d, ZC + v];
  };
  const ext = [[-36, -30, 0], [36, 30, 0]];
  for (const a of [VIEW - SPAN, VIEW, VIEW + SPAN]) for (const u of [-W, W]) for (const v of [-H, H]) ext.push(frame(a, u, -TH, v), frame(a, u, 0, v));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-34, -28, 34, 28, 7, 1.6), 0, 4));
  const at = (r) => r.map((q) => ({ ...q, u: q.u + CUP[0], v: q.v + CUP[1] }));
  put(solid(g), prism(P, front, at(circ(8, 40)), at(circ(6.8, 40)), 4, 6.5));
  put(solid(g), prism(P, front, at(circ(2.4, 20)), null, 6.5, 14));
  const arm = mk("path", { class: "nf sil" }, g);
  const scr = solid(g);
  const disp = mk("path", { class: "nf lo" }, g);
  const route = mk("path", { class: "nf lo" }, g);
  const pos = mk("circle", { class: "dot", r: 2.2 }, g);

  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const Q = (u, d, v) => P(...frame(a, u, d, v));
    const pts = [];
    for (const u of [-W, W]) for (const d of [-TH, 0]) for (const v of [-H, H]) pts.push(Q(u, d, v));
    const h = hull(pts);
    scr.sil.setAttribute("d", poly(fillet(h, h.map(() => 3))));
    scr.cr.setAttribute("d", open([Q(-W + 1, 0, H - 1), Q(W - 1, 0, H - 1)]));
    const box = [[-W + 3, -H + 3], [W - 3, -H + 3], [W - 3, H - 3], [-W + 3, H - 3]].map(([u, v]) => Q(u, 0.2, v));
    disp.setAttribute("d", poly(fillet(box, [1.5, 1.5, 1.5, 1.5])));
    route.setAttribute("d", open(ROUTE.map(([u, v]) => Q(u, 0.2, v))));
    place(pos, Q(12, 0.2, 6));
    const b = frame(a, 0, -TH, 0);
    arm.setAttribute("d", seg(P(CUP[0], CUP[1], 14), P(CUP[0], CUP[1], 22)) + seg(P(CUP[0], CUP[1], 22), P(...b)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const t = clamp(Math.atan2(p[1], p[0]), VIEW - SPAN, VIEW + SPAN);
    sp.t = t;
    read.textContent = Math.round(((t - VIEW) * 180) / Math.PI) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZC);
      if (Math.hypot(x, y) < 6 || Math.hypot(x, y) > 90) return aim(null);
      aim([x, y]);
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  draw();
  scr.sil.classList.add("hi");
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "gpsunit",
  means: "A car GPS on a suction-cup arm: the screen swivels on its ball joint to face the pointer, and springs back askew.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[338, 144], [200, 213], [62, 144], null],
  mount,
});

luggagetag.code:
/**
 * Luggage lock: a combination padlock, a body with three number wheels in a
 * window on its face and a tall shackle. Over the lock, the shackle lifts out
 * of its hole and swings round its left leg toward the pointer, open, and goes
 * bright. At rest it sits shut, a touch askew, the middle wheel bright. The
 * slider is how far the shackle swings.
 */
const {
  Cam, facing, fit, prism, proj, rings, unproj, poly, seg,
  tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 17, BY = 7, BZ = 26, LEG = 9.5, RAD = 9.5, TUBE = 1.8, LIFT = 9;
const OPEN = 1.35, REST = 0.12;

function uRing(h) {
  const out = [], inn = [];
  for (const [r, arr] of [[RAD + TUBE, out], [RAD - TUBE, inn]]) {
    arr.push([RAD - r, 0]);
    for (let i = 0; i <= 16; i++) { const t = Math.PI - (i / 16) * Math.PI; arr.push([RAD + r * Math.cos(t), h + r * Math.sin(t)]); }
    arr.push([RAD + r, 0]);
  }
  return out.concat(inn.reverse());
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 4.6);
  const shPts = (phi, lift) => uRing(18).map(([u, z]) => [-LEG + u * Math.cos(phi), u * Math.sin(phi), BZ + lift + z]);
  const ext = [[-BX, -BY, 0], [BX, BY, 0], ...shPts(REST, 0), ...shPts(OPEN * 1.2, LIFT)];
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const shack = mk("path", { class: "sil" }, g);
  put(solid(g), prism(P, front, ...rings(-BX, -BY, BX, BY, 5, 1.6), 0, BZ));
  // the window on the near long face, and its three wheels
  const F = (x, z) => P(x, BY + 0.1, z);
  const win = [F(-12, 6), F(12, 6), F(12, 17), F(-12, 17)];
  mk("path", { class: "nf lo", d: poly(win) }, g);
  const wheels = [-8, 0, 8].map((x, i) => {
    const w = mk("path", { class: "nf" + (i === 1 ? "" : " lo") }, g);
    w.setAttribute("d", seg(F(x - 3, 8), F(x - 3, 15)) + seg(F(x + 3, 8), F(x + 3, 15)) + seg(F(x - 1, 8.5), F(x + 1, 8.5)) + seg(F(x - 1, 14.5), F(x + 1, 14.5)));
    return w;
  });
  const hole = mk("path", { class: "nf lo" }, g);
  hole.setAttribute("d", seg(P(-LEG + 2 * RAD - 2, -1.5, BZ), P(-LEG + 2 * RAD + 2, 1.5, BZ)));

  const tw = tween(0);
  let drawn = NaN, swing = value;
  function draw(now) {
    const k = tval(tw, now);
    if (Math.abs(k - drawn) < 1e-4) return;
    drawn = k;
    const lift = LIFT * Math.min(1, k * 1.6), phi = REST + (OPEN * swing - REST) * k;
    shack.setAttribute("d", poly(shPts(phi, lift).map((q) => P(...q))));
  }
  const B = register(stage, (dt, now) => { draw(now); return !tdone(tw, now); });
  bag.add(B.unregister);

  let cur = null;
  function set(open) {
    if (open === cur) return;
    cur = open;
    tset(tw, open ? 1 : 0, performance.now(), 0);
    shack.classList.toggle("hi", open);
    wheels[1].classList.toggle("sil", !open);
    wheels[1].classList.toggle("hi", !open);
    read.textContent = open ? "open" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const hit = (z) => { const [x, y] = unproj(C, p[0], p[1], z); return Math.abs(x) < BX + 16 && Math.abs(y) < BY + 22; };
      set(hit(0) || hit(BZ + 20));
    },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  set(false);
  draw(performance.now());
  return {
    set: (v) => { swing = v; drawn = NaN; draw(performance.now()); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "luggagetag",
  means: "A luggage combination lock: over it, the shackle lifts out of its hole and swings open, bright.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[137, 260], [235, 277], [332, 293], null],
  mount,
});

travelpillow.code:
/**
 * Seat recline: a row of three airplane seats on one rail, each a cushion on a
 * pedestal with a tall backrest and headrest hinged at its rear edge. The
 * pointer picks a seat by its rest centre: that seat tips its back all the way
 * down and goes bright, its neighbours straighten up for it, nearest first.
 * At rest the backs sit at uneven angles, the middle one bright. The slider is
 * how far the chosen back reclines.
 */
const {
  Cam, facing, fit, prism, proj, rings, unproj, hull, fillet, poly, open, seg,
  tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid, clamp,
} = HL;

const XS = [-27, 0, 27], HW = 11, Z0 = 15, PY = -10, BH = 34, TH = 4.5;
const REST = [14, 6, 24], FAV = 1;
const deg = Math.PI / 180;

function backPts(cx, a, h0, h1, w) {
  const out = [], s = Math.sin(a), c = Math.cos(a);
  for (const u of [cx - w, cx + w]) for (const t of [0, TH]) for (const h of [h0, h1]) {
    out.push([u, PY - t * c - h * s, Z0 - t * s + h * c]);
  }
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  const ext = [];
  for (const x of XS) ext.push(...backPts(x, 46 * deg, 0, BH + 8, HW), [x - HW, 12, 0], [x + HW, 12, 0]);
  fit(C, ext, 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rail the row stands on
  put(solid(g), prism(P, front, ...rings(-42, -6, 42, 2, 2, 0.8), 0, 2));
  const seats = XS.map((cx, k) => {
    const grp = mk("g", {}, g);
    const back = solid(grp), head = solid(grp);
    put(solid(grp), prism(P, front, ...rings(cx - 3, -5, cx + 3, 1, 1.5, 0.6), 2, Z0 - 3));
    put(solid(grp), prism(P, front, ...rings(cx - HW, PY, cx + HW, 10, 4, 1.4), Z0 - 3, Z0));
    const arm = mk("path", { class: "nf lo" }, grp);
    arm.setAttribute("d", seg(P(cx + HW, PY, Z0 + 6), P(cx + HW, 6, Z0 + 6)) + seg(P(cx + HW, 6, Z0 + 6), P(cx + HW, 6, Z0)));
    return { k, cx, back, head, tw: tween(REST[k] * deg), drawn: NaN };
  });

  function plate(sol, pts) {
    const sp = pts.map((q) => P(...q)), h = hull(sp);
    sol.sil.setAttribute("d", poly(fillet(h, h.map(() => 2.5))));
    sol.cr.setAttribute("d", open([sp[1], sp[3], sp[7], sp[5]].map((q, i) => q)));
  }

  function draw(s, now) {
    const a = tval(s.tw, now);
    if (Math.abs(a - s.drawn) < 1e-4) return;
    s.drawn = a;
    plate(s.back, backPts(s.cx, a, 0, BH, HW));
    plate(s.head, backPts(s.cx, a, BH + 1, BH + 8, HW - 3));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const s of seats) { draw(s, now); if (!tdone(s.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let amt = value, cur = undefined;
  function choose(i) {
    if (i === cur) return;
    cur = i;
    const now = performance.now();
    for (const s of seats) {
      const t = i == null ? REST[s.k] : s.k === i ? 18 + 28 * amt : 2;
      tset(s.tw, t * deg, now, i == null ? 0 : Math.abs(s.k - i) * 45);
      const on = i == null ? s.k === FAV : s.k === i;
      s.back.sil.classList.toggle("hi", on);
      s.head.sil.classList.toggle("hi", on);
    }
    read.textContent = i == null ? "rest" : "seat " + (i + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], Z0);
      if (Math.abs(x) > 48 || y < -48 || y > 22) return choose(null);
      let bi = 0, bd = Infinity;
      for (const s of seats) { const d = Math.abs(P(s.cx, 0, Z0)[0] - p[0]); if (d < bd) { bd = d; bi = s.k; } }
      choose(bi);
    },
    leave: () => choose(null),
  }));
  bag.add(() => svg.replaceChildren());
  choose(null);
  return {
    set: (v) => { amt = v; const i = cur; cur = undefined; choose(i); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "travelpillow",
  means: "Three airplane seats in a row: the one under the pointer reclines its back and goes bright, the others straighten up.",
  rules: [1, 2, 5, 8],
  range: [0.3, 1, 1],
  tour: [[123, 176], [172, 200], [220, 225], null],
  mount,
});

jukebox.code:
/**
 * Jukebox: the record rack of a jukebox, discs standing on edge in a
 * cradle. The pointer picks a disc by where it stands: discs before it lean
 * back, discs after it lean forward, staggered from it, and it stands alone
 * in the gap. At rest the gap is at disc 4, bright. The slider is the
 * stagger.
 *
 * The pattern: one of many in a single row (riffle), flipped open like a crate.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, seg, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, STEP = 13, R = 22, TH = 2, BZ = 8, YC = 22, FAV = 3;
const X1 = (N - 1) * STEP + 16;
const lean = (k, a, b, f) => (k < a ? -b - (a - k) * 2 : k > a ? f + (k - a) * 2 : 0);
const restA = (k) => lean(k, FAV, 14, 10);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-6, -10, 0], [X1 + 6, 50, 0], [X1 + 6, -10, 0], [-6, 50, 0], [-24, YC, BZ + 2 * R], [X1 + 24, YC, BZ + 2 * R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, 2, X1 + 6, 42, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, BZ));
  mk("path", { d: seg(P(0, YC - 3, BZ), P(X1, YC - 3, BZ)) + seg(P(0, YC + 3, BZ), P(X1, YC + 3, BZ)), class: "nf lo" }, g);
  const ring = circ(R, 36), lab = circ(R * 0.36, 20);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 8 + k * STEP, grp = mk("g", {}, g);
    items.push({ k, x, disc: mk("path", { class: "sil" }, grp), label: mk("path", { class: "nf lo" }, grp), a: tween(restA(k)), last: NaN });
  }

  // a disc point: v along y, w up from the cradle, leaned by phi about its lower edge
  const DP = (x, v, w, phi) => P(x + w * Math.sin(phi), YC + v, BZ + w * Math.cos(phi));
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const phi = rad(deg), pts = [];
    for (const q of ring) { pts.push(DP(it.x, q.u, R + q.v, phi), DP(it.x + TH, q.u, R + q.v, phi)); }
    it.disc.setAttribute("d", poly(hull(pts)));
    it.label.setAttribute("d", poly(lab.map((q) => DP(it.x + TH, q.u, R + q.v, phi))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, YC, BZ + R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? restA(k) : lean(k, a, 26, 20);
      tset(it.a, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.disc.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "disc " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "jukebox",
  means: "A jukebox record rack: discs before the pointer lean back, discs after it lean forward, and the picked one stands alone.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[139, 86], [177, 105], [255, 144], null],
  mount,
});

metronome2.code:
/**
 * Music box: a wooden box with a hinged lid, a pinned drum inside and a
 * crank on its side. The pointer's place along the box sets how far the lid
 * swings open, and the crank turns with it. At rest the lid stands ajar,
 * bright. The slider is how far the lid may open.
 *
 * The pattern: one part following the pointer (hinge).
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, ringAt, open, seg, clamp, rad, spring, stepS, unproj, circ,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 44, H = 26, T = 5, REST = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, 0, 0], [W + 12, D, 0], [W, -18, H + D], [0, -18, H + D], [0, D, 0]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the open well: an inner rim on the top
  const [wr] = rings(3, 3, W - 3, D - 3, 2, 0.8);
  mk("path", { d: poly(ringAt(P, wr, H)), class: "lo" }, g);
  // the drum, lying along x inside the well, and its comb
  const drum = [];
  for (const x of [12, W - 22]) for (let i = 0; i < 20; i++) { const t = (i / 20) * Math.PI * 2; drum.push(P(x, D * 0.55 + 6 * Math.cos(t), H - 7 + 6 * Math.sin(t))); }
  mk("path", { d: poly(hull(drum)), class: "nf" }, g);
  let comb = "";
  for (let i = 0; i < 9; i++) { const x = 13 + i * 3.6; comb += seg(P(x, D * 0.55 + 7, H - 1), P(x, D - 6, H - 1)); }
  mk("path", { d: comb, class: "nf lo" }, g);

  const lid = mk("path", { class: "sil hi" }, g), lidIn = mk("path", { class: "nf lo" }, g);
  const crank = mk("path", { class: "nf sil" }, g), knob = mk("path", { class: "" }, g);
  const LP = (x, yl, hl, a) => P(x, yl * Math.cos(a) - hl * Math.sin(a), H + yl * Math.sin(a) + hl * Math.cos(a));
  const knobRing = circ(2.2, 14);

  const A = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const x of [0, W]) for (const yl of [0, D]) for (const hl of [0, T]) pts.push(LP(x, yl, hl, a));
    const hp = hull(pts);
    lid.setAttribute("d", poly(fillet(hp, hp.map(() => 3), 3)));
    lidIn.setAttribute("d", open([LP(3, D - 3, T, a), LP(W - 3, D - 3, T, a), LP(W - 3, 3, T, a)]));
    // crank on the +x face: shaft, arm, handle
    const cy = D * 0.55, cz = H * 0.5, ph = a * 3, ay = cy + 9 * Math.cos(ph), az = cz + 9 * Math.sin(ph);
    crank.setAttribute("d", seg(P(W, cy, cz), P(W + 5, cy, cz)) + seg(P(W + 5, cy, cz), P(W + 5, ay, az)));
    knob.setAttribute("d", poly(hull(knobRing.map((q) => P(W + 5, ay + q.u, az + q.v)).concat(knobRing.map((q) => P(W + 11, ay + q.u, az + q.v))))));
  }

  const B = register(stage, (dt) => { const m = stepS(A, dt); draw(A.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (wx < -14 || wx > W + 14 || wy < -30 || wy > D + 20) return leave();
    const t = clamp(wx / W, 0, 1);
    A.t = REST + 6 + t * (maxA - REST - 6);
    read.textContent = "lid " + Math.round(A.t) + "°";
    B.wake();
  }
  function leave() { A.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  draw(REST);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "metronome2",
  means: "A music box with a hinged lid: the pointer's place along the box swings the lid open and turns the crank on its side.",
  rules: [1, 3, 5, 8],
  range: [60, 95, 110],
  tour: [[131, 228], [182, 254], [240, 283], null],
  mount,
});

guitarpedal.code:
/**
 * Effects pedal: a rocker pedal, a low housing with a treadle on a centre
 * pivot. The pointer's place along the pedal rocks the treadle, heel down
 * at the back, toe down at the front. At rest it leans a little toe-up,
 * bright. The slider is how far the treadle may rock.
 *
 * The pattern: one part following the pointer (rocker).
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, seg, clamp, rad, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 40, L = 72, BZ = 6, PZ = 18, T = 4, M = L / 2, REST = 7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[0, 0, 0], [W, L, 0], [W, 0, 0], [0, L, 0], [W / 2, 0, PZ + 16], [W / 2, L, PZ + 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, L, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [kr, ki] = rings(6, M - 6, W - 6, M + 6, 3, 1.2);
  put(solid(g), prism(P, front, kr, ki, BZ, PZ - 1));
  const tre = mk("path", { class: "sil hi" }, g), top = mk("path", { class: "nf lo" }, g), tread = mk("path", { class: "nf lo" }, g);
  const TP = (x, yl, hl, a) => P(x, M + yl * Math.cos(a) - hl * Math.sin(a), PZ + yl * Math.sin(a) + hl * Math.cos(a));

  const A = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const x of [2, W - 2]) for (const yl of [-M + 2, M - 2]) for (const hl of [0, T]) pts.push(TP(x, yl, hl, a));
    const hp = hull(pts);
    tre.setAttribute("d", poly(fillet(hp, hp.map(() => 4), 3)));
    const inn = [TP(5, -M + 5, T, a), TP(W - 5, -M + 5, T, a), TP(W - 5, M - 5, T, a), TP(5, M - 5, T, a)];
    top.setAttribute("d", poly(fillet(inn, [3, 3, 3, 3], 3)));
    let d = "";
    for (let i = 0; i < 7; i++) { const yl = -M + 12 + i * 8; d += seg(TP(9, yl, T, a), TP(W - 9, yl, T, a)); }
    tread.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(A, dt); draw(A.x); return m; });
  bag.add(B.unregister);

  function leave() { A.t = REST; read.textContent = "rest"; B.wake(); }
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    if (wx < -20 || wx > W + 30 || wy < -20 || wy > L + 30) return leave();
    A.t = clamp((M - wy) / M, -1, 1) * maxA;
    read.textContent = (A.t < 0 ? "toe " : "heel ") + Math.abs(Math.round(A.t)) + "°";
    B.wake();
  }
  leave();
  draw(REST);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "guitarpedal",
  means: "A rocker effects pedal: the pointer's place along it rocks the treadle on its pivot, heel down at the back, toe down at the front.",
  rules: [1, 3, 5, 8],
  range: [8, 16, 20],
  tour: [[266, 168], [200, 201], [130, 236], null],
  mount,
});

lunchbag.code:
/**
 * School locker: a bank of three lockers, each door hung on a hinge with
 * vent slots and a latch. The pointer picks a locker and its door swings
 * open on a 700ms ease; the neighbours settle back, staggered by distance.
 * At rest one door stands ajar and is bright. The slider is how far a door
 * swings.
 */
const {
  Cam, fit, prism, proj, rings, seg, facing, tween, tset, tval, tdone, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, W = 26, D = 22, H = 80, T = 1.8, OPEN = 100;
const REST = [5, 30, 0], FAV = 1;
const R = Math.PI / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  const ext = [[0, 0, 0], [N * W, D, 0], [0, 0, H], [N * W, D, H]];
  for (let i = 0; i < N; i++) ext.push([i * W, D + W, 0], [i * W, D + W, H], [i * W + W, D, H]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [ring, inner] = rings(0, 0, N * W, D, 3, 1.4);
  put(solid(g), prism(P, front, ring, inner, 0, H));
  // door frames, a shelf and a hook inside each locker, on the front face
  let frames = "";
  for (let i = 0; i < N; i++) {
    const x0 = i * W + 1.2, x1 = i * W + W - 1.2, z0 = 2.5, z1 = H - 2.5;
    const q = [[x0, z0], [x1, z0], [x1, z1], [x0, z1]].map(([x, z]) => P(x, D, z));
    frames += seg(q[0], q[1]) + seg(q[1], q[2]) + seg(q[2], q[3]) + seg(q[3], q[0]);
    frames += seg(P(x0, D, H - 16), P(x1, D, H - 16));
    frames += seg(P(i * W + W / 2, D, H - 22), P(i * W + W / 2, D, H - 26));
  }
  mk("path", { class: "nf lo", d: frames }, g);

  const DOOR = rings(0.4, 0, W - 0.4, T, 0.7, 0.3)[0];
  const doors = [];
  for (let i = 0; i < N; i++) {
    const grp = mk("g", {}, g);
    const s = solid(grp);
    const marks = mk("path", { class: "nf lo", d: "" }, grp);
    doors.push({ i, hx: i * W, s, marks, tw: tween(REST[i]), drawn: NaN, cx: P(i * W + W / 2, D, H / 2)[0] });
  }

  function draw(d, now) {
    const a = tval(d.tw, now);
    if (Math.abs(a - d.drawn) < 1e-3) return;
    d.drawn = a;
    const c = Math.cos(a * R), sn = Math.sin(a * R);
    const L = (u, v) => [d.hx + u * c - v * sn, D + u * sn + v * c];
    const rr = DOOR.map((q) => { const [x, y] = L(q.u, q.v); return { u: x, v: y, nu: q.nu * c - q.nv * sn, nv: q.nu * sn + q.nv * c }; });
    put(d.s, prism(P, front, rr, null, 1.5, H - 1.5));
    let m = "";
    if (c - sn > 0.05) {
      for (let k = 0; k < 4; k++) {
        const z = H - 9 - k * 3.2, a0 = L(W * 0.28, T), a1 = L(W * 0.72, T);
        m += seg(P(a0[0], a0[1], z), P(a1[0], a1[1], z));
      }
      const h = L(W - 4.5, T);
      m += seg(P(h[0], h[1], H / 2 - 5), P(h[0], h[1], H / 2 + 5));
    }
    d.marks.setAttribute("d", m);
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const d of doors) { draw(d, now); if (!tdone(d.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  let cur = null;
  function choose(a, now) {
    cur = a;
    for (const d of doors) {
      const to = a === null ? REST[d.i] : d.i === a ? clamp(OPEN * value, 20, 125) : REST[d.i] * 0.4;
      tset(d.tw, to, now, a === null ? Math.abs(d.i - FAV) * 40 : Math.abs(d.i - a) * 40);
      d.s.sil.classList.toggle("hi", a === null ? d.i === FAV : d.i === a);
    }
    read.textContent = a === null ? "rest" : "locker " + (a + 1);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      let a = null, bd = Infinity;
      for (const d of doors) { const dd = Math.abs(p[0] - d.cx); if (dd < bd) { bd = dd; a = d.i; } }
      if (bd > 70 || p[1] < 20 || p[1] > 305) a = null;
      if (a !== cur) choose(a, performance.now());
    },
    leave: () => choose(null, performance.now()),
  }));
  bag.add(() => svg.replaceChildren());
  choose(null, performance.now());
  return {
    set: (v) => { value = v; if (cur !== null) { const c = cur; cur = -1; choose(c, performance.now()); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "lunchbag",
  means: "A bank of school lockers: the door under the pointer swings open on its hinge, and the open one is bright.",
  rules: [1, 2, 4, 5],
  range: [0.5, 1, 1.25],
  tour: [[150, 160], [200, 160], [250, 160], null],
  mount,
});

scissors.code:
/**
 * Scissors: a pair of safety scissors lying on the desk, two halves on one
 * pivot screw, each a blade with a round-nosed tip and a finger loop. The
 * pointer is what they reach for: the pair swivels on a spring to aim at it
 * and the blades open around it. At rest they lie a little open, the screw
 * bright. The slider is how wide the blades open.
 */
const {
  Cam, fit, prism, proj, facing, fillet, circ, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid, flatDot, place, unproj,
} = HL;

const R = Math.PI / 180, BASE = -24, SW = 22, REST_W = 16, OPEN = 26;
const BLADE = [[54, 0], [40, 3], [6, 4.5], [-6, 5], [-14, 9], [-17, 4], [-7, -2.5], [6, -4], [44, -2.5]];
const BR = [2.6, 3, 4, 3, 2, 2, 3, 3, 3];
const LOOP = [-25, 11], LR = 9.5;
function ringOf(pts) {
  let a = 0;
  for (let i = 0; i < pts.length; i++) { const p = pts[i], q = pts[(i + 1) % pts.length]; a += p[0] * q[1] - q[0] * p[1]; }
  const sg = a > 0 ? 1 : -1;
  return pts.map((p, i) => {
    const pr = pts[(i - 1 + pts.length) % pts.length], nx = pts[(i + 1) % pts.length];
    const dx = nx[0] - pr[0], dy = nx[1] - pr[1], l = Math.hypot(dx, dy) || 1;
    return { u: p[0], v: p[1], nu: (sg * dy) / l, nv: (-sg * dx) / l };
  });
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.6);
  const ext = [];
  for (let k = 0; k < 24; k++) { const a = (BASE + (k / 23 - 0.5) * 2 * (SW + 40)) * R; ext.push([56 * Math.cos(a), 56 * Math.sin(a), 0]); }
  for (let k = 0; k < 24; k++) { const a = (180 + BASE + (k / 23 - 0.5) * 2 * (SW + 40)) * R; ext.push([38 * Math.cos(a), 38 * Math.sin(a), 6]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const flip = (pts, s) => pts.map(([u, v]) => [u, v * s]);
  const halves = [-1, 1].map((s, k) => {
    const blade = ringOf(fillet(flip(BLADE, s), BR, 3));
    const loop = circ(LR, 32).map((q) => ({ ...q, u: q.u + LOOP[0], v: q.v + LOOP[1] * s }));
    const hole = circ(LR - 3.5, 32).map((q) => ({ ...q, u: q.u + LOOP[0], v: q.v + LOOP[1] * s }));
    const grp = mk("g", {}, g);
    return { s, z: 1 + k * 2, blade, loop, hole, grp, L: solid(grp), B: solid(grp), H: solid(grp) };
  });
  const screw = flatDot(g, C, 2.2, "dot");
  const aim = spring(BASE), open = spring(REST_W);
  let drawn = "";

  function turn(ring, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
  }
  function draw() {
    const key = aim.x.toFixed(3) + open.x.toFixed(3);
    if (key === drawn) return;
    drawn = key;
    for (const h of halves) {
      const a = (aim.x - h.s * open.x) * R;
      put(h.L, prism(P, front, turn(h.loop, a), null, h.z, h.z + 2));
      put(h.B, prism(P, front, turn(h.blade, a), null, h.z, h.z + 2));
      put(h.H, prism(P, front, turn(h.hole, a), null, h.z + 1.9, h.z + 2));
    }
    place(screw, P(0, 0, 5.2));
  }

  const Bk = register(stage, (dt) => {
    const m1 = stepS(aim, dt), m2 = stepS(open, dt);
    draw();
    return m1 || m2;
  });
  bag.add(Bk.unregister);

  function hi(on) {
    for (const h of halves) { h.B.sil.classList.toggle("hi", on); h.L.sil.classList.toggle("hi", on); }
    screw.setAttribute("class", on ? "dot m" : "dot");
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y);
      const ang = Math.atan2(y, x) / R, rel = ((ang - BASE + 540) % 360) - 180;
      if (d < 10 || d > 90 || Math.abs(rel) > 90) { aim.t = BASE; open.t = REST_W; hi(false); read.textContent = "rest"; }
      else {
        aim.t = BASE + clamp(rel, -SW, SW);
        open.t = clamp(REST_W + OPEN * value * (1 - clamp((d - 20) / 60, 0, 0.8)), REST_W, 40);
        hi(true);
        read.textContent = Math.round(open.t * 2) + "°";
      }
      Bk.wake();
    },
    leave: () => { aim.t = BASE; open.t = REST_W; hi(false); read.textContent = "rest"; Bk.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  hi(false);
  read.textContent = "rest";
  draw();
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

