  tour: [[241, 195], [297, 223], [135, 142], null],
  mount,
});

puzzlecube.code:
/**
 * Shape cube: an activity cube with shaped holes in its lid, a round, a
 * triangle, a square and a star. Near the pointer the cube turns on the floor
 * to bring its holes round to face it. At rest it sits a little askew, the
 * round hole bright. The slider is how far it turns.
 */
const { Cam, fit, proj, facing, rings, prism, poly, unproj, spring, stepS, disposer, mk, solid, put, pointer, register } = HL;

const H = 40, S2 = 26;
const turn = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };
const shape = (k, cx, cy) => {
  const pts = [], n = [24, 3, 4, 10][k];
  for (let i = 0; i < n; i++) {
    const t = (i / n) * Math.PI * 2 + (k === 2 ? Math.PI / 4 : -Math.PI / 2), r = k === 3 ? (i % 2 ? 3.4 : 7.5) : k === 2 ? 8 : 7;
    pts.push([cx + r * Math.cos(t), cy + r * Math.sin(t)]);
  }
  return pts;
};
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.8);
  const ext = [];
  for (let k = 0; k < 8; k++) { const t = (k / 8) * Math.PI * 2; ext.push([37 * Math.cos(t), 37 * Math.sin(t), 0], [37 * Math.cos(t), 37 * Math.sin(t), H]); }
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const R = rings(-S2, -S2, S2, S2, 4, 1.8);
  const body = solid(g);
  const holes = [0, 1, 2, 3].map(() => mk("path", { class: "sil" }, g));
  const POS = [[-12, -12], [12, -12], [-12, 12], [12, 12]];
  const sp = spring(0.22);
  let drawn = NaN, reach = 1, on = false;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    put(body, prism(P, front, turn(R[0], a), turn(R[1], a), 0, H));
    const c = Math.cos(a), s = Math.sin(a);
    holes.forEach((h, k) => h.setAttribute("d", poly(shape(k, POS[k][0], POS[k][1]).map(([u, v]) => P(u * c - v * s, u * s + v * c, H)))));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function set(o) {
    on = o;
    sp.t = on ? 0.22 + 1.35 * reach : 0.22;
    holes[0].classList.toggle("hi", !on); holes[3].classList.toggle("hi", on);
    read.textContent = on ? "turn" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], H); set(Math.hypot(x, y) < 44); },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  draw(); set(false);
  return { set: (v) => { reach = v; set(on); }, destroy: bag.dispose };
}

hairline({
  name: "puzzlecube",
  means: "A shape-sorter activity cube: near the pointer it turns on the floor, swinging its shaped holes round.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[200, 135], [200, 163], [200, 60], null],
  mount,
});

nightlight2.code:
/**
 * Projector lamp: a star projector night light, a squat base and a drum
 * pierced with stars. Near the pointer the drum rises out of the base and
 * turns, the stars wheeling round it. At rest the drum sits down, one star
 * bright. The slider is how high it rises.
 */
const { Cam, fit, proj, facing, circ, prism, poly, unproj, spring, stepS, disposer, mk, solid, put, pointer, register } = HL;

const RB = 24, HB = 12, RD = 20, HD = 30, NS = 9;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-RB, -RB, 0], [RB, RB, 0], [-RB, -RB, HB + HD + 22], [RB, RB, HB + HD + 22]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const head = solid(g), cap = solid(g);
  const stars = [];
  for (let i = 0; i < NS; i++) stars.push(mk("path", { class: "sil" }, g));
  const base = solid(g);
  put(base, prism(P, front, circ(RB, 64), circ(RB - 2, 64), 0, HB));
  const lift = spring(10), spin = spring(0.4);
  let drawn = "", reach = 1, on = false;
  function draw() {
    const z0 = HB - 4 + lift.x, a = spin.x, key = z0.toFixed(3) + a.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    put(head, prism(P, front, circ(RD, 64), circ(RD - 1.6, 64), z0, z0 + HD));
    put(cap, prism(P, front, circ(7, 32), null, z0 + HD, z0 + HD + 3));
    stars.forEach((st, i) => {
      const t = a + (i / NS) * Math.PI * 2, nx = Math.cos(t), ny = Math.sin(t), zc = z0 + HD * (i % 2 ? 0.4 : 0.68);
      if (nx + ny < 0.35) { st.setAttribute("d", ""); return; }
      const pts = [];
      for (let k = 0; k < 10; k++) {
        const b = (k / 10) * Math.PI * 2 - Math.PI / 2, r = k % 2 ? 1.6 : 4;
        pts.push(P(RD * nx - ny * r * Math.cos(b), RD * ny + nx * r * Math.cos(b), zc - r * Math.sin(b)));
      }
      st.setAttribute("d", poly(pts));
    });
  }
  const B = register(stage, (dt) => { const m1 = stepS(lift, dt), m2 = stepS(spin, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);
  function set(o) {
    on = o;
    lift.t = on ? 12 + 12 * reach : 10;
    spin.t = on ? 0.4 + 2.4 * reach : 0.4;
    head.sil.classList.toggle("hi", on);
    stars[0].classList.toggle("hi", !on);
    read.textContent = on ? "glow" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], HB); set(Math.hypot(x, y) < 40); },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  draw(); set(false);
  return { set: (v) => { reach = v; set(on); }, destroy: bag.dispose };
}

hairline({
  name: "nightlight2",
  means: "A star projector lamp: near the pointer its starry drum rises from the base and turns, the stars wheeling round.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[200, 171], [200, 186], [200, 84], null],
  mount,
});

hotelsafe.code:
/**
 * Luggage rack: a folding hotel rack, two scissor legs at each end under two
 * rails joined by webbing straps. At rest it stands half folded, tall and
 * narrow, its middle strap bright. The pointer over it opens the rack: the
 * legs scissor out, the rails spread and drop, the straps pull taut.
 * The slider is how far it opens.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, clamp, unproj, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 74, LEG = 46, REST = 16, CZ = 0;
const hOf = (s) => Math.sqrt(LEG * LEG - s * s);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-4, -22, 0], [L + 4, 22, 0], [L + 4, -22, 0], [-4, 22, 0], [0, 0, LEG + 2], [L, 0, LEG + 2]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const legsFar = mk("path", { class: "nf" }, g);
  const railA = solid(g);
  const straps = [0, 1, 2, 3].map(() => mk("path", { class: "nf" }, g));
  const railB = solid(g);
  const legsNear = mk("path", { class: "nf" }, g);
  const sp = tween(REST);
  let last = NaN;

  function draw(s) {
    if (s === last) return;
    last = s;
    const h = hOf(s), y = s / 2;
    const leg = (x) => seg(P(x, -y, 0), P(x, y, h)) + seg(P(x, y, 0), P(x, -y, h));
    legsFar.setAttribute("d", leg(4));
    legsNear.setAttribute("d", leg(L - 4));
    const [ra, ia] = rings(0, -y - 1.6, L, -y + 1.6, 1.6, 0.6);
    put(railA, prism(P, front, ra, ia, h - 2.4, h));
    const [rb, ib] = rings(0, y - 1.6, L, y + 1.6, 1.6, 0.6);
    put(railB, prism(P, front, rb, ib, h - 2.4, h));
    straps.forEach((st, i) => {
      const x = 14 + i * 15.3, sag = clamp(6 - s * 0.16, 0.5, 6);
      const pts = [], n = 8;
      for (let j = 0; j <= n; j++) { const t = j / n; pts.push(P(x, lerpY(-y, y, t), h - 1 - sag * 4 * t * (1 - t))); }
      const pts2 = pts.map((p, j) => P(x + 4, lerpY(-y, y, j / n), h - 1 - sag * 4 * (j / n) * (1 - j / n)));
      st.setAttribute("d", "M" + pts.map((p) => p.join(",")).join("L") + "L" + pts2.reverse().map((p) => p.join(",")).join("L") + "Z");
    });
  }
  const lerpY = (a, b, t) => a + (b - a) * t;

  const B = register(stage, (_dt, now) => { draw(tval(sp, now)); return !tdone(sp, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(sp, a ? 18 + 18 * open : REST, performance.now(), 0);
    straps.forEach((st, i) => st.classList.toggle("hi", a ? i === 0 || i === 3 : i === 1));
    railB.sil.classList.toggle("hi", !!a);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    const [x2, y2] = unproj(C, sx, sy, 30);
    return (x > -8 && x < L + 8 && Math.abs(y) < 26) || (x2 > -8 && x2 < L + 8 && Math.abs(y2) < 20);
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

