  name: "fuelpump2",
  means: "A jerry can with its handle and spout cap turns to face the pointer, and the part under it brightens.",
  rules: [1, 3, 5, 6],
  range: [20, 34, 48],
  tour: [[247, 20], [112, 229], [180, 140], null],
  mount,
});

