kettlebell2.code:
/**
 * Kettlebell rack: a long shelf on four legs holding five kettlebells of
 * different sizes, each a round body under a loop handle. The pointer picks
 * the bell nearest it along the row; that bell slides forward to the shelf's
 * front edge and its neighbours follow less, staggered by distance. At rest
 * the bells sit unevenly, the middle one bright.
 */
const { Cam, fit, proj, facing, rings, circ, prism, poly, unproj, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const XS = [-40, -20, 0, 20, 40], RS = [5, 6, 7.5, 6.5, 5.5], YR = [-4, -1, 1, -3, 0], TOP = 19, FAV = 2, OUT = 9;
const FALL = [1, 0.45, 0.18, 0.08, 0.04];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-54, -12, 0], [54, 14, 0], [-46, -10, TOP + 20], [46, 14, TOP + 18]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1) => {
    const s = solid(g), r = rings(x0, y0, x1, y1, 0.8, Math.min(1, 0.25 * Math.min(x1 - x0, y1 - y0)));
    put(s, prism(P, front, r[0], r[1], z0, z1));
  };
  box(-50, -10, -46, -6, 0, 16); box(46, -10, 50, -6, 0, 16);
  box(-50, 8, -46, 12, 0, 16); box(46, 8, 50, 12, 0, 16);
  box(-54, -12, 54, 14, 16, TOP);
  const bells = XS.map((x, i) => {
    const bg = mk("g", {}, g);
    return { i, x, R: RS[i], body: solid(bg), handle: mk("path", { class: "sil" }, bg), tw: tween(YR[i]), drawn: NaN };
  });

  function draw(b, now) {
    const y = tval(b.tw, now);
    if (Math.abs(y - b.drawn) < 1e-3) return;
    b.drawn = y;
    const R = b.R, h = TOP + 1.5 * R, mv = (r) => r.map((q) => ({ ...q, u: q.u + b.x, v: q.v + y }));
    put(b.body, prism(P, front, mv(circ(R, 32)), mv(circ(R - 1, 32)), TOP, h));
    const out = [], inn = [];
    for (let k = 0; k <= 12; k++) {
      const t = (k / 12) * Math.PI, c = Math.cos(t), s = Math.sin(t);
      out.push(P(b.x - 0.7 * R * c, y, h - 0.4 + 0.95 * R * s));
      inn.unshift(P(b.x - 0.42 * R * c, y, h - 0.4 + 0.62 * R * s));
    }
    b.handle.setAttribute("d", poly(out.concat(inn)));
  }

  const B = register(stage, (dt, now) => {
    let m = false;
    for (const b of bells) { draw(b, now); if (!tdone(b.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);

  function pick(a) {
    const now = performance.now();
    bells.forEach((b) => {
      tset(b.tw, a == null ? YR[b.i] : YR[b.i] + OUT * value * FALL[Math.abs(b.i - a)], now, a == null ? 0 : Math.abs(b.i - a) * 45);
      b.body.sil.classList.toggle("hi", b.i === (a == null ? FAV : a));
    });
    read.textContent = a == null ? "rest" : RS[a] * 2 + " kg";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (q) => {
      const [x, y] = unproj(C, q[0], q[1], TOP);
      if (Math.abs(x) > 62 || Math.abs(y) > 30) return pick(null);
      let a = 0, bd = Infinity;
      bells.forEach((b) => { const d = Math.abs(P(b.x, YR[b.i], TOP)[0] - q[0]); if (d < bd) { bd = d; a = b.i; } });
      pick(a);
    },
    leave: () => pick(null),
  }));
  bag.add(() => svg.replaceChildren());
  pick(null);
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "kettlebell2",
  means: "A kettlebell rack: the bell nearest the pointer slides to the shelf's edge, its neighbours follow less, and it is bright.",
  rules: [1, 2, 3, 4, 5],
  range: [0.5, 1, 1.3],
  tour: [[241, 180], [124, 121], [280, 199], null],
  mount,
});

cutmat.code:
/**
 * Paper trimmer: a guillotine trimmer, a gridded base with a sheet on it and
 * a long blade arm hinged at the back corner with a handle at its far end.
 * The pointer along the base swings the arm open: further toward the front,
 * the wider it opens. At rest the arm is just lifted, bright.
 */
const { Cam, clamp, fit, hull, poly, proj, seg, unproj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const W = 40, D = 50, BH = 3, AX = W, AW = 8, AH = 5, AL = 56, REST = 14, MAXA = 72;

function box(P, f, x0, x1, y0, y1, z0, z1) {
  const c = [];
  for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) c.push(P(...f([x, y, z])));
  return { sil: poly(hull(c)), cr: seg(c[7], c[3]) + seg(c[7], c[5]) + seg(c[7], c[6]) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.5);
  const r = (MAXA * Math.PI) / 180;
  fit(C, [[0, 0, 0], [AX + AW + 2, D + 4, 0], [0, D, 0], [AX + AW, 0, 0], [AX, AL * Math.cos(r), BH + AL * Math.sin(r) + 8], [AX + AW, -6, BH + 6]], 200, 165);
  const P = proj(C), id = (p) => p;
  const g = mk("g", {}, svg);

  const base = box(P, id, 0, AX + AW, -4, D, 0, BH);
  mk("path", { class: "sil", d: base.sil }, g);
  mk("path", { class: "nf lo", d: base.cr }, g);
  let grid = "";
  for (const x of [10, 20, 30]) grid += seg(P(x, 0, BH), P(x, D - 4, BH));
  for (const y of [12, 24, 36]) grid += seg(P(2, y, BH), P(AX - 2, y, BH));
  grid += poly([P(6, 8, BH), P(AX - 1, 8, BH), P(AX - 1, 40, BH), P(6, 40, BH)]);
  mk("path", { class: "nf lo", d: grid }, g);

  const arm = mk("g", {}, g);
  const aSil = mk("path", { class: "sil" }, arm), aCr = mk("path", { class: "nf lo" }, arm);
  const hSil = mk("path", { class: "sil" }, arm), hCr = mk("path", { class: "nf lo" }, arm);
  const ang = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    const f = ([x, y, z]) => [x, y * c - (z - BH) * s, BH + y * s + (z - BH) * c];
    const b = box(P, f, AX, AX + AW, -4, AL, BH, BH + AH), h = box(P, f, AX - 1, AX + AW + 1, AL - 10, AL - 2, BH + AH, BH + AH + 6);
    aSil.setAttribute("d", b.sil);
    aCr.setAttribute("d", b.cr + seg(P(...f([AX + 1, 0, BH])), P(...f([AX + 1, AL - 2, BH]))));
    hSil.setAttribute("d", h.sil);
    hCr.setAttribute("d", h.cr);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BH);
    if (x < -4 || x > AX + AW + 6 || y < -8 || y > D + 6) return -1;
    return clamp((y + 4) / (D + 6), 0, 1);
  }
  let cur = -2;
  function setT(t) {
    const deg = t < 0 ? REST : Math.round(REST + 10 + (MAXA - REST - 10) * Math.pow(t, 1 / (0.5 + reach)));
    if (deg === cur) return;
    cur = deg;
    tset(ang, deg, performance.now(), 0);
    aSil.classList.add("hi");
    read.textContent = t < 0 ? "rest" : deg + "°";
    B.wake();
  }
  setT(-1);
  bag.add(pointer(stage, { move: (p) => setT(hit(p)), leave: () => setT(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

