  name: "conveyor3",
  means: "A roller conveyor: the taped carton slides along the rollers to the spot under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.2, 1, 1],
  tour: [[138, 113], [274, 181], [120, 104], null],
  mount,
