ribbonspool.code:
/**
 * Ribbon rack: a rail on two posts over a base, with five ribbon spools on
 * it. The pointer picks a spool by where it is along the rail: its ribbon
 * unrolls down to the base and the other spools slide away along the rail,
 * staggered from it. At rest one spool is bright. The slider is the stagger.
 */
const { Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 5, STEP = 14, R = 9, W = 8, RAIL = 26, FAV = 2, SPREAD = 4, L0 = 3, L1 = 24;
const XL = -12, XR = (N - 1) * STEP + 12;

function circX(P, x, y, z, r) { const o = []; for (let i = 0; i < 28; i++) { const a = (i / 28) * Math.PI * 2; o.push(P(x, y + r * Math.cos(a), z + r * Math.sin(a))); } return o; }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[XL - 4, -12, 0], [XR + 4, 14, 0], [XL - 4, 14, 0], [XR + 4, -12, 0], [XL, 0, RAIL + R + 2], [XR, 0, RAIL + R + 2]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const base = solid(g);
  const [br, bi] = rings(XL - 4, -12, XR + 4, 14, 4, 1.2);
  put(base, prism(P, front, br, bi, 0, 4));
  const postL = solid(g);
  const [pr, pi] = rings(XL - 2, -2, XL + 2, 2, 1.5, 0.6);
  put(postL, prism(P, front, pr, pi, 4, RAIL + 2));
  mk("path", { class: "nf lo", d: open([P(XL, 0, RAIL), P(XR, 0, RAIL)]) }, g);

  const spools = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    spools.push({ k, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), tail: mk("path", { class: "sil" }, grp), dx: tween(0), len: tween(L0), last: "" });
  }
  const postR = solid(g);
  const [qr, qi] = rings(XR - 2, -2, XR + 2, 2, 1.5, 0.6);
  put(postR, prism(P, front, qr, qi, 4, RAIL + 2));

  function draw(s, dx, len) {
    const key = dx.toFixed(2) + "/" + len.toFixed(2);
    if (key === s.last) return;
    s.last = key;
    const x = s.k * STEP + dx, a = x - W / 2, b = x + W / 2;
    s.sil.setAttribute("d", poly(hull(circX(P, a, 0, RAIL, R).concat(circX(P, b, 0, RAIL, R)))));
    s.cr.setAttribute("d", poly(circX(P, b, 0, RAIL, R)) + poly(circX(P, b, 0, RAIL, 3.2)) + poly(circX(P, b, 0, RAIL, 1.2)));
    const w = W / 2 - 1, y = R, zt = RAIL, zb = RAIL - len;
    s.tail.setAttribute("d", poly([P(x - w, y, zt), P(x + w, y, zt), P(x + w, y + 0.2, zb), P(x, y + 0.2, zb + 2.5), P(x - w, y + 0.2, zb)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    spools.forEach((s) => { draw(s, tval(s.dx, now), tval(s.len, now)); if (!tdone(s.dx, now) || !tdone(s.len, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the spool whose rest centre is nearest the pointer's screen x
  const cx = spools.map((s) => P(s.k * STEP, 0, RAIL)[0]);
  const yTop = P(XL, 0, RAIL + R + 4)[1], yBot = P(XR, 14, 0)[1];
  function hit([sx, sy]) {
    if (sy < yTop - 30 || sy > yBot + 10 || sx < cx[0] - 30 || sx > cx[N - 1] + 30) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    spools.forEach((s, k) => {
      const dx = a < 0 || k === a ? 0 : Math.sign(k - a) * clamp(SPREAD + 2 - Math.abs(k - a), 2, SPREAD);
      const d = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(s.dx, dx, now, d);
      tset(s.len, k === a ? L1 : L0, now, d);
      s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "reel " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "ribbonspool",
  means: "A ribbon rack: the spool under the pointer unrolls its ribbon and the others slide away along the rail.",
  rules: [1, 2, 4, 5],
  range: [0, 40, 90],
  tour: [[120, 86], [202, 109], [284, 168], null],
  mount,
});

bagsealer.code:
/**
 * Bag sealer: a long base with a hinged jaw along its back edge and a bag
 * lying with its mouth across the heat strip. The pointer over the sealer
 * swings the jaw open on its hinge; along the jaw, the nearer the pointer is
 * to the front the wider it opens. At rest the heat strip is bright. The
 * slider is how far the jaw can open.
 */
const { Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rings, unproj, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const L = 70, Y0 = 0, Y1 = 16, TOP = 9, JH = 6, YM = 11;
const PROF = fillet([[0, 0], [Y1, 0], [Y1, JH], [0, JH]], [0.8, 2, 2.5, 1.5], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[0, Y0, 0], [L, Y1 + 30, 0], [L, Y0, 0], [0, Y1 + 30, 0], [0, Y0, TOP + 20], [L, Y0, TOP + 20]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const base = solid(g), [br, bi] = rings(0, Y0, L, Y1, 3, 1);
  put(base, prism(P, front, br, bi, 0, TOP));
  const strip = mk("path", { class: "sil", d: poly([P(4, YM - 1, TOP), P(L - 4, YM - 1, TOP), P(L - 4, YM + 1, TOP), P(4, YM + 1, TOP)]) }, g);
  const x0 = 14, x1 = L - 14, yf = Y1 + 12, ye = Y1 + 30;
  mk("path", { class: "sil", d: poly([P(x0, YM + 1.6, TOP), P(x1, YM + 1.6, TOP), P(x1, Y1 + 0.5, TOP), P(x1 + 2, yf, 0), P(x1 + 2, ye, 0), P(x0 - 2, ye, 0), P(x0 - 2, yf, 0), P(x0, Y1 + 0.5, TOP)]) }, g);
  mk("path", { class: "nf lo", d: open([P(x0 - 2, yf, 0), P(x1 + 2, yf, 0)]) + open([P(x0, Y1 + 0.5, TOP), P(x1, Y1 + 0.5, TOP)]) }, g);

  const jaw = mk("g", {}, g), sil = mk("path", { class: "sil" }, jaw), cr = mk("path", { class: "nf lo" }, jaw);
  const ang = tween(16);
  let last = NaN;
  function pt(x, y, z, a) { const c = Math.cos(a), s = Math.sin(a); return P(x, Y0 + y * c - z * s, TOP + y * s + z * c); }
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180, near = PROF.map(([y, z]) => pt(L - 1, y, z, a)), far = PROF.map(([y, z]) => pt(1, y, z, a));
    sil.setAttribute("d", poly(hull(near.concat(far))));
    cr.setAttribute("d", poly(near) + open([pt(4, YM, 0, a), pt(L - 4, YM, 0, a)]) + open([pt(1, Y1 - 1, JH, a), pt(L - 1, Y1 - 1, JH, a)]));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  // the hit: the pointer on the ground, which never moves; how far forward it is sets the opening
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP);
    if (x < -6 || x > L + 6 || y < Y0 - 30 || y > Y1 + 30) return -1;
    return clamp((y - Y0 + 30) / (Y1 + 30), 0.4, 1);
  }

  let act = -2;
  function setActive(f) {
    const q = f < 0 ? -1 : Math.round(f * 4) / 4;
    if (q === act) return;
    act = q;
    const deg = q < 0 ? 16 : max * q;
    tset(ang, deg, performance.now(), 0);
    sil.classList.toggle("hi", q >= 0);
    strip.classList.toggle("hi", q < 0);
    read.textContent = q < 0 ? "rest" : Math.round(deg) + "°";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; const f = act; act = -2; setActive(f); }, destroy: bag.dispose };
}

hairline({
  name: "bagsealer",
  means: "A heat bag sealer: the pointer over it swings the hinged jaw open off the heat strip, wider the nearer the front.",
  rules: [1, 3, 4, 5],
  range: [30, 60, 80],
  tour: [[249, 139], [221, 153], [216, 155], null],
  mount,
});

hangerrack.code:
/**
 * Clothes rail: a rail on two uprights with feet, six garments hanging on
 * it. The pointer picks a garment by where it is along the rail: it swings
 * out towards the viewer on its hanger, its neighbours swing less, staggered
 * from it. At rest one garment is bright. The slider is the stagger.
 */
const { Cam, clamp, facing, fillet, fit, hull, open, poly, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 6, STEP = 11, TOP = 52, TH = 1.6, FAV = 3, SWING = 48;
const XL = -9, XR = (N - 1) * STEP + 9;
const SHAPE = fillet([[-3.5, -3], [3.5, -3], [11, -8], [9.5, -15], [8, -14], [8.5, -38], [-8.5, -38], [-8, -14], [-9.5, -15], [-11, -8]], [1, 1, 2, 1, 1, 1.5, 1.5, 1, 1, 2], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[XL - 3, -12, 0], [XR + 3, 12, 0], [XL - 3, 12, 0], [XR + 3, -12, 0], [XL, 0, TOP + 4], [XR, 0, TOP + 4], [XR, 30, TOP - 20]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  function upright(x) {
    const foot = solid(g), [fr, fi] = rings(x - 2, -12, x + 2, 12, 1.8, 0.6);
    put(foot, prism(P, front, fr, fi, 0, 2.5));
    const post = solid(g), [pr, pi] = rings(x - 1.4, -1.4, x + 1.4, 1.4, 1.2, 0.5);
    put(post, prism(P, front, pr, pi, 2.5, TOP + 1.5));
  }
  upright(XL);
  mk("path", { class: "nf lo", d: open([P(XL, 0, TOP), P(XR, 0, TOP)]) }, g);

  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    items.push({ k, x: k * STEP, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp), a: tween(0), last: NaN });
  }
  upright(XR);

  function pt(x, y, z, a) { const c = Math.cos(a), s = Math.sin(a); return P(x, y * c - z * s, TOP + y * s + z * c); }
  function draw(s, deg) {
    if (deg === s.last) return;
    s.last = deg;
    const a = (deg * Math.PI) / 180, near = SHAPE.map(([y, z]) => pt(s.x + TH / 2, y, z, a)), far = SHAPE.map(([y, z]) => pt(s.x - TH / 2, y, z, a));
    s.sil.setAttribute("d", poly(hull(near.concat(far))));
    const xn = s.x + TH / 2;
    s.cr.setAttribute("d", poly(near) + open([pt(xn, 0, 2.5, a), pt(xn, 1.2, 1.2, a), pt(xn, 0, 0, a), pt(xn, -1.2, 1.2, a), pt(xn, 0, -3, a)]) + open([pt(xn, -3.5, -3, a), pt(xn, 0, -9, a), pt(xn, 3.5, -3, a)]) + open([pt(xn, 0, -9, a), pt(xn, 0, -38, a)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    items.forEach((s) => { draw(s, tval(s.a, now)); if (!tdone(s.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: the garment whose rest centre is nearest the pointer's screen x
  const cx = items.map((s) => P(s.x, 0, TOP - 18)[0]);
  const yTop = P(XL, 0, TOP + 4)[1], yBot = P(XR, 12, 0)[1];
  function hit([sx, sy]) {
    if (sy < yTop - 20 || sy > yBot + 10 || sx < cx[0] - 25 || sx > cx[N - 1] + 25) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(sx - c) < Math.abs(sx - cx[best])) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((s, k) => {
      const deg = a < 0 ? 0 : SWING * clamp(1 - Math.abs(k - a) * 0.3, 0.2, 1);
      tset(s.a, deg, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "no. " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "hangerrack",
  means: "A clothes rail: the garment under the pointer swings out on its hanger, its neighbours swing a little after it.",
  rules: [1, 2, 4, 5],
  range: [0, 40, 90],
  tour: [[149, 101], [210, 131], [251, 151], null],
  mount,
