  name: "vendlocker",
  means: "A key cutting machine: the pointer's place along the bench slides the carriage there, running the key's blade past the wheel.",
  rules: [1, 3, 4, 5],
  range: [6, 14, 20],
  tour: [[151, 123], [216, 156], [240, 167], null],
  mount,
});

transformer2.code:
/**
 * Pole transformer: a wooden pole with a cross arm and three insulators, and a
 * round transformer can hung on its bracket, two bushings on its lid wired up
 * to the arm. The pointer swings the can out from the pole on its bracket
 * hinge. At rest it hangs slightly out, its lid bright.
 */
const { Cam, circ, facing, fit, prism, proj, rings, unproj, hull, poly, seg, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const HZ = 66, RC = 13, DX = 18, H = 30, REST = 5, YS = [-34, 0, 34];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-6, -40, 0], [6, 40, 0], [0, -40, 96], [0, 40, 96], [4 + DX + RC + 30, 0, 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(9, 32), circ(8, 32), 0, 1.5));
  put(solid(g), prism(P, front, circ(4, 24), null, 1.5, 94));
  const A = rings(-2.5, -40, 2.5, 40, 1.5, 0.8);
  put(solid(g), prism(P, front, A[0], A[1], 84, 88));
  for (const y of YS) put(solid(g), prism(P, front, circ(2, 16).map((q) => ({ ...q, v: q.v + y })), null, 88, 95));
  const wires = mk("path", { class: "nf lo", d: "" }, g);
  const can = solid(g), b1 = solid(g), b2 = solid(g);
  const ring = circ(RC, 48), inner = circ(RC - 1.5, 48);
  const at = (a, u, v, z) => { const c = Math.cos(a), s = Math.sin(a), x = u + DX; return P(4 + x * c + z * s, v, HZ - x * s + z * c); };
  const cyl = (a, cu, cv, r, z0, z1) => { const pts = []; for (const q of circ(r, 16)) pts.push(at(a, cu + q.u, cv + q.v, z0), at(a, cu + q.u, cv + q.v, z1)); return poly(hull(pts)); };
  const tw = tween(REST);
  let drawn = NaN;
  function draw(now) {
    const a = tval(tw, now) * Math.PI / 180;
    if (a !== drawn) {
      drawn = a;
      const pts = [];
      for (const q of ring) pts.push(at(a, q.u, q.v, 0), at(a, q.u, q.v, -H));
      can.sil.setAttribute("d", poly(hull(pts)));
      can.cr.setAttribute("d", poly(inner.map((q) => at(a, q.u, q.v, 0))));
      b1.sil.setAttribute("d", cyl(a, 2, -6, 2, 0, 7));
      b2.sil.setAttribute("d", cyl(a, 2, 6, 2, 0, 7));
      wires.setAttribute("d", seg(at(a, 2, -6, 7), P(0, -34, 95)) + seg(at(a, 2, 6, 7), P(0, 34, 95)));
    }
    return !tdone(tw, now);
  }
  const B = register(stage, (dt, now) => draw(now));
  bag.add(B.unregister);
  let on = false, amt = 32 * value;
  function retarget() {
    tset(tw, on ? amt : REST, performance.now(), 0);
    can.sil.classList.toggle("hi", on);
    can.cr.classList.toggle("hi", !on);
    read.textContent = on ? "can" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (q) => { const [x, y] = unproj(C, q[0], q[1], HZ - H / 2); on = x > -10 && x < 60 && Math.abs(y) < 30; retarget(); },
    leave: () => { on = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = 32 * v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "transformer2",
  means: "A pole-mounted transformer: the pointer swings the round can out from the pole on its bracket hinge, wires following.",
  rules: [1, 4, 5, 8],
  range: [0.6, 1, 1.3],
  tour: [[230, 138], [185, 160], [250, 193], null],
  mount,
});

switchgear.code:
/**
 * Knife switch: a three-pole knife switch on a slate base, each copper blade
 * hinged on its post and closing into its jaw, the three joined by a cross bar
 * with a handle. The pointer picks a pole and the blades swing open, nearest
 * first. At rest the switch stands a little open, the middle blade bright.
 */
const { Cam, facing, fit, prism, proj, rings, unproj, hull, poly, seg, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const YS = [-18, 0, 18], HX = -30, HZ = 12, L = 58, REST = [14, 18, 22];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-44, -32, 0], [44, 32, 0], [HX, 0, HZ + L], [44, 32, 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const R = rings(-44, -32, 44, 32, 4, 1.6);
  put(solid(g), prism(P, front, R[0], R[1], 0, 5));
  const at = (a, l, y, dz) => { const c = Math.cos(a), s = Math.sin(a); return P(HX + l * c - dz * s, y, HZ + l * s + dz * c); };
  const box = (a, l0, l1, y0, y1, d0, d1) => {
    const pts = [];
    for (const l of [l0, l1]) for (const y of [y0, y1]) for (const d of [d0, d1]) pts.push(at(a, l, y, d));
    return pts;
  };
  const poles = YS.map((y, i) => {
    const gg = mk("g", {}, g);
    const pr = rings(HX - 3, y - 4, HX + 3, y + 4, 1.5, 0.8), jr = rings(28, y - 4, 34, y + 4, 1.5, 0.8);
    put(solid(gg), prism(P, front, pr[0], pr[1], 5, HZ + 2));
    put(solid(gg), prism(P, front, jr[0], jr[1], 5, HZ + 3));
    const blade = solid(gg);
    return { i, y, blade, tw: tween(REST[i]), drawn: NaN };
  });
  const bar = solid(g), knob = solid(g);
  let last = NaN;
  function draw(now) {
    let m = false;
    for (const p of poles) {
      const a = tval(p.tw, now) * Math.PI / 180;
      if (!tdone(p.tw, now)) m = true;
      if (a !== p.drawn) {
        p.drawn = a;
        const pts = box(a, -2, L, p.y - 1.4, p.y + 1.4, -2.2, 2.2);
        p.blade.sil.setAttribute("d", poly(hull(pts)));
        p.blade.cr.setAttribute("d", seg(at(a, 0, p.y, 2.2), at(a, L - 2, p.y, 2.2)));
      }
    }
    const a = poles[1].drawn;
    if (a !== last) {
      last = a;
      bar.sil.setAttribute("d", poly(hull(box(a, L - 8, L - 3, -22, 22, 2, 5))));
      knob.sil.setAttribute("d", poly(hull(box(a, L - 7.5, L - 3.5, -3, 3, 5, 16))));
      knob.cr.setAttribute("d", seg(at(a, L - 5.5, 0, 6), at(a, L - 5.5, 0, 15)));
    }
    return m;
  }
  const B = register(stage, (dt, now) => draw(now));
  bag.add(B.unregister);
  let open = 70 * value, pick = null;
  function retarget() {
    const now = performance.now();
    for (const p of poles) {
      const to = pick === null ? REST[p.i] : open;
      tset(p.tw, to, now, pick === null ? 0 : Math.abs(p.i - pick) * 45);
      p.blade.sil.classList.toggle("hi", pick === null ? p.i === 1 : p.i === pick);
    }
    read.textContent = pick === null ? "rest" : "pole " + (pick + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (q) => {
      const [x, y] = unproj(C, q[0], q[1], 0);
      if (Math.abs(x) > 50 || Math.abs(y) > 38) pick = null;
      else { let b = 0; YS.forEach((v, i) => { if (Math.abs(y - v) < Math.abs(y - YS[b])) b = i; }); pick = b; }
      retarget();
    },
    leave: () => { pick = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { open = 70 * v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "switchgear",
  means: "A three-pole knife switch: the pointer picks a pole and the blades swing open from their jaws, nearest first.",
  rules: [1, 2, 4, 8],
  range: [0.6, 1, 1.25],
  tour: [[249, 195], [216, 212], [184, 228], null],
  mount,
});

pushsled.code:
/**
 * Push sled: a weight sled on two runners, plates stacked on its post and a
 * pair of tall push handles, standing on a dashed turf lane. The pointer is
 * where the sled is pushed to: it slides down the lane on a spring and its
 * handle is bright. At rest it waits a little way up the lane.
 */
const { Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid } = HL;

const REST = -22, LO = -42, HI = 42;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-64, -18, 0], [64, 18, 0], [-64, 18, 0], [64, -18, 0], [HI - 18, 0, 40], [LO - 18, 0, 40]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  mk("path", { class: "dash nf", d: "M" + P(-64, -18, 0) + "L" + P(64, -18, 0) + "M" + P(-64, 18, 0) + "L" + P(64, 18, 0) }, g);
  place(flatDot(g, C, 1.6, "dot off"), P(60, 0, 0));
  const S = Array.from({ length: 9 }, () => solid(g));
  const box = (s, x0, y0, x1, y1, z0, z1, r = 1.5) => {
    const [a, b] = rings(x0, y0, x1, y1, r, Math.min(1, Math.min(x1 - x0, y1 - y0) / 4));
    put(s, prism(P, front, a, b, z0, z1));
  };
  const disc = (s, x, R, z0, z1) => {
    const m = (q) => ({ ...q, u: q.u + x, v: q.v });
    put(s, prism(P, front, circ(R, 40).map(m), circ(R - 1.4, 40).map(m), z0, z1));
  };
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const X = sp.x;
    if (Math.abs(X - drawn) < 1e-3) return;
    drawn = X;
    box(S[0], X - 20, -15, X + 20, -10, 0, 3, 1.5);
    box(S[1], X - 18, -16, X - 14, -8, 3, 38, 1);
    box(S[2], X - 20, -12, X - 12, 12, 36, 40, 1.5);
    box(S[3], X - 22, -13, X + 22, 13, 3, 7, 2.5);
    box(S[4], X - 18, 8, X - 14, 16, 3, 38, 1);
    disc(S[5], X + 4, 12, 7, 11);
    disc(S[6], X + 4, 11, 11, 15);
    disc(S[7], X + 4, 3, 15, 24);
    box(S[8], X - 20, 10, X + 20, 15, 0, 3, 1.5);
    // the far runner first, the near one last
    S[8].g.parentNode.insertBefore(S[0].g, S[1].g);
    S[2].sil.classList.add("hi");
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(y) > 40 || Math.abs(x) > 80) { sp.t = REST; read.textContent = "rest"; }
      else { sp.t = Math.max(LO, Math.min(HI, x)); read.textContent = Math.round(sp.t - LO) + "m"; }
      B.wake();
    },
    leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  draw();
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "pushsled",
  means: "A weight push sled on a turf lane: it slides down the lane to wherever the pointer pushes it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[249, 209], [132, 151], [268, 219], null],
  mount,
});

gymrings.code:
/**
 * Gym rings: a tall frame with a crossbar, and two rings hanging on long
 * straps. The pointer is where the rings swing to: both straps swing on a
 * spring about the bar, and the near ring is bright. At rest they hang with a
 * slight swing.
 */
const { Cam, facing, fit, prism, proj, rings, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const REST = 0.2, L = 52, TOP = 94, R = 10, YS = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-16, -46, 0], [16, 46, 0], [-16, 46, 0], [16, -46, 0], [0, -46, 98], [0, 46, 98], [40, 0, 40], [-40, 0, 40]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r = 1.5) => {
    const [a, b] = rings(x0, y0, x1, y1, r, Math.min(1, Math.min(x1 - x0, y1 - y0) / 4));
    put(s, prism(P, front, a, b, z0, z1));
  };
  box(solid(g), -16, -48, 16, -40, 0, 3, 2);
  box(solid(g), -2, -46, 2, -42, 3, 94, 1);
  box(solid(g), -2.5, -47, 2.5, 47, 94, 98, 1.5);
  const hang = [-YS, YS].map((y) => ({ y, strap: mk("path", { class: "nf sil", d: "" }, g), outer: mk("path", { class: "nf sil", d: "" }, g), inner: mk("path", { class: "nf lo", d: "" }, g) }));
  box(solid(g), -2, 42, 2, 46, 3, 94, 1);
  box(solid(g), -16, 40, 16, 48, 0, 3, 2);
  hang[1].outer.classList.add("hi");
  const sp = spring(REST, { k: 60 * value, c: 9 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const dx = Math.sin(a), dz = -Math.cos(a);
    for (const h of hang) {
      const ex = L * dx, ez = TOP + L * dz, cx = ex + R * dx, cz = ez + R * dz;
      h.strap.setAttribute("d", "M" + P(0, h.y - 2, TOP) + "L" + P(ex, h.y, ez) + "L" + P(0, h.y + 2, TOP));
      const ring = (r) => {
        const pts = [];
        for (let k = 0; k < 40; k++) { const b = (k / 40) * Math.PI * 2, u = Math.cos(b) * r, v = Math.sin(b) * r; pts.push(P(cx - v * dx, h.y + u, cz - v * dz)); }
        return "M" + pts.join("L") + "Z";
      };
      h.outer.setAttribute("d", ring(R));
      h.inner.setAttribute("d", ring(R - 2.2));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const say = () => { read.textContent = Math.round(sp.t * 57.3) + "deg"; };
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 40);
      sp.t = Math.abs(y) > 70 ? REST : Math.max(-0.7, Math.min(0.7, x / 45));
      say(); B.wake();
    },
    leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest"; draw();
  return { set: (v) => { sp.k = 60 * v; sp.c = 9 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "gymrings",
  means: "Gym rings on a tall frame: both rings swing on their straps toward the pointer, the near ring bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[221, 199], [141, 159], [190, 185], null],
  mount,
});

foamroller.code:
/**
 * Squat rack: two uprights on feet with J-hooks, and a loaded barbell racked
 * on the hooks. The pointer is how high the bar is lifted: it slides up and
 * down the uprights on a spring, its plates bright. At rest it sits on the
 * hooks.
 */
const { Cam, fit, prism, proj, rings, facing, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const REST = 50, LO = 20, HI = 76, BX = 7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-18, -56, 0], [18, 56, 0], [-18, 56, 0], [18, -56, 0], [0, -32, 86], [0, 32, 86], [BX, -56, HI + 18], [BX, 56, HI + 18]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r = 1.5) => {
    const [a, b] = rings(x0, y0, x1, y1, r, Math.min(1, Math.min(x1 - x0, y1 - y0) / 4));
    put(s, prism(P, front, a, b, z0, z1));
  };
  const path = (cls) => mk("path", { class: cls, d: "" }, g);
  const lsl = path("nf sil"), lpl = [path("sil"), path("sil"), path("sil"), path("sil")];
  for (const y of [-30, 30]) {
    box(solid(g), -18, y - 4, 18, y + 4, 0, 3, 2);
    box(solid(g), -3, y - 3, 3, y + 3, 3, 86, 1);
    box(solid(g), 3, y - 2, BX + 3, y + 2, REST - 5, REST - 2, 0.8);
  }
  const bar = path("nf sil"), rpl = [path("sil"), path("sil"), path("sil"), path("sil")], rsl = path("nf sil");
  for (const q of [...lpl, ...rpl]) q.classList.add("hi");
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  const disc = (y, z, r) => {
    const pts = [];
    for (let k = 0; k < 44; k++) { const b = (k / 44) * Math.PI * 2; pts.push(P(BX + r * Math.cos(b), y, z + r * Math.sin(b))); }
    return "M" + pts.join("L") + "Z";
  };
  const rod = (y0, y1, z) => "M" + P(BX, y0, z + 1.2) + "L" + P(BX, y1, z + 1.2) + "M" + P(BX, y0, z - 1.2) + "L" + P(BX, y1, z - 1.2);
  function draw() {
    const z = sp.x;
    if (Math.abs(z - drawn) < 1e-3) return;
    drawn = z;
    lsl.setAttribute("d", rod(-56, -46, z));
    [-46, -43, -40, -37].forEach((y, i) => lpl[i].setAttribute("d", disc(y, z, i < 2 ? 17 : 14)));
    bar.setAttribute("d", rod(-37, 37, z));
    [37, 40, 43, 46].forEach((y, i) => rpl[i].setAttribute("d", disc(y, z, i < 2 ? 14 : 17)));
    rsl.setAttribute("d", rod(46, 56, z));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const y0 = P(BX, 0, 0)[1], dz = y0 - P(BX, 0, 1)[1];
  const say = () => { read.textContent = Math.round(sp.t) + "cm"; };
  bag.add(pointer(stage, {
    move: (p) => { sp.t = Math.max(LO, Math.min(HI, (y0 - p[1]) / dz)); say(); B.wake(); },
