  name: "phrasebook",
  means: "A ticket barrier gate: its two glass paddles swing open as the pointer comes up the lane, wider the nearer it is.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[78, 155], [163, 197], [203, 218], null],
  mount,
