  name: "visastamp",
  means: "A rubber passport stamp: it slides over the open passport to the pointer and drops toward the page, its landing traced under it.",
  rules: [1, 3, 5, 8],
  range: [0.3, 0.85, 1],
  tour: [[183, 201], [133, 226], [263, 237], null],
  mount,
