  name: "fittingroom",
  means: "A fitting room booth: the pointer over it draws the pleated curtain open along the rail, bunching at the post.",
  rules: [1, 2, 4, 5],
  range: [0, 40, 80],
  tour: [[170, 180], [200, 172], [230, 165], null],
  mount,
});

mannequin3.code:
/**
 * Shelf talker: a store shelf plank on two brackets, with a price flag
 * clipped to its front edge and standing out into the aisle. The pointer
 * swings the flag on its clip toward the side it comes from, like a
 * shopper brushing past. At rest the flag stands out at a slant, bright.
 * The slider is how far it swings.
 *
 * The pattern: one part turning about a fixed axis; the hit is on a plane
 * through the shelf.
 */
const { Cam, facing, fit, hull, poly, open, prism, proj, rings, unproj, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 40, D = 16, SZ = 22, AX = 20, AY = D + 1, FL = 26, FZ0 = 8, FZ1 = 32, T = 1.2, REST = 70;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 4.6);
  fit(C, [[0, 0, 0], [W, D, SZ + 4], [AX - FL, AY, FZ0], [AX + FL, AY, FZ0], [AX, AY + FL, FZ0], [AX, AY + FL, FZ1]], 200, 168);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r) => { const [o, i] = rings(x0, y0, x1, y1, r, 0.5); put(s, prism(P, front, o, i, z0, z1)); };

  const b1 = solid(g); box(b1, 6, 0, 9, D - 3, 6, SZ, 0.5);
  const b2 = solid(g); box(b2, W - 9, 0, W - 6, D - 3, 6, SZ, 0.5);
  const plank = solid(g); box(plank, 0, 0, W, D, SZ, SZ + 3, 1);
  const clip = solid(g); box(clip, AX - 2, D - 1, AX + 2, D + 2, SZ - 2, SZ + 4, 0.5);
  const flag = solid(g);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const r = (a * Math.PI) / 180, ux = Math.cos(r), uy = Math.sin(r), nx = -uy * T / 2, ny = ux * T / 2;
    const pt = (u, z, s) => P(AX + ux * u + nx * s, AY + uy * u + ny * s, z);
    const pts = [];
    for (const s of [-1, 1]) for (const u of [2, FL]) for (const z of [FZ0, FZ1]) pts.push(pt(u, z, s));
    flag.sil.setAttribute("d", poly(hull(pts)));
    const m = (u, z) => pt(u, z, 1);
    flag.cr.setAttribute("d", open([m(6, FZ0 + 5), m(FL - 4, FZ0 + 5), m(FL - 4, FZ1 - 5), m(6, FZ1 - 5), m(6, FZ0 + 5)]) + open([m(2, SZ + 1.5), m(2, SZ - 1.5)]));
  }
  const R = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(R.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, SZ);
    if (x < -10 || x > W + 10 || y < -14 || y > AY + FL + 6) return -1;
    return x < AX ? 0 : 1;
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(ang, a < 0 ? REST : a === 0 ? REST + swing : REST - swing, performance.now(), 0);
    flag.sil.classList.add("hi");
    read.textContent = a < 0 ? "rest" : a === 0 ? "swing <" : "swing >";
    R.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (act >= 0) setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "mannequin3",
  means: "A price flag clipped to a shelf edge: the pointer swings the flag on its clip toward the side it comes from.",
  rules: [1, 3, 4, 5],
  range: [30, 60, 75],
  tour: [[167, 114], [205, 118], [240, 130], null],
  mount,
});

sleepingpod.code:
/**
 * Sleeping pod: a low bed plinth with a long shell hood hinged at its head.
 * The pointer along the pod swings the hood open about the hinge; nearer the
 * foot opens it wider. At rest the hood stands ajar, bright.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, clamp, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid, unproj } = HL;

const L = 64, W = 28, BZ = 10, R = 14, REST = 0.35, MAX = 1.15;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [0, W / 2, BZ + R + L * 0.6], [L * 0.5, W / 2, BZ + R + 6]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, W, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [mr, mi] = rings(3, 3, L - 3, W - 3, 4, 1.2);
  put(solid(g), prism(P, front, mr, mi, BZ, BZ + 3));
  const hood = mk("path", { class: "sil hi" }, g), lip = mk("path", { class: "nf" }, g), win = mk("path", { class: "nf lo" }, g);
  const ang = tween(REST);
  const arc = (x) => { const a = []; for (let i = 0; i <= 12; i++) { const t = (i / 12) * Math.PI; a.push([x, W / 2 - R * Math.cos(t), BZ + R * Math.sin(t)]); } return a; };
  const rot = ([x, y, z], a) => { const dz = z - BZ; return P(x * Math.cos(a) - dz * Math.sin(a), y, BZ + x * Math.sin(a) + dz * Math.cos(a)); };
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const head = arc(0).map((p) => rot(p, a)), foot = arc(L).map((p) => rot(p, a));
    hood.setAttribute("d", poly(hull(head.concat(foot))));
    lip.setAttribute("d", poly(foot));
    const w = []; for (const x of [L * 0.35, L * 0.75]) for (const t of [0.35, 0.65]) { const th = t * Math.PI; w.push([x, W / 2 - R * Math.cos(th), BZ + R * Math.sin(th)]); }
    win.setAttribute("d", poly([w[0], w[1], w[3], w[2]].map((p) => rot(p, a))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  function set(p) {
    const now = performance.now();
    if (!p) { tset(ang, REST, now, 0); read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    if (x < -20 || x > L + 30 || y < -30 || y > W + 30) return set(null);
    const t = clamp(x / L, 0, 1), a = clamp(0.2 + t * MAX * (0.4 + reach / 100), 0.2, MAX);
    tset(ang, a, now, 0);
    read.textContent = Math.round((a / MAX) * 100) + "% open";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

