coalcart.code:
/**
 * Mine cart: a tapered ore cart heaped with coal, standing on a short run of
 * track, rails on sleepers. The pointer picks a spot along the track and the
 * cart rolls there, wheels and all. At rest it waits near the far end of the
 * track, bright. The slider is how stiffly it rolls.
 */
const { Cam, clamp, facing, fit, hull, poly, prism, proj, rings, spring, stepS, unproj, disposer, mk, pointer, put, register, solid } = HL;

const LX = 96, Y0 = 0, Y1 = 20, REST = 18, XMIN = 14, XMAX = 82;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, -2, 0], [LX, Y1 + 2, 0], [LX, -2, 0], [0, Y1 + 2, 0], [XMIN, 10, 28], [XMAX, 10, 28]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  function box(s, x0, y0, x1, y1, z0, z1, r, b) { const [a, i] = rings(x0, y0, x1, y1, r || 0.6, b || 0.3); put(s, prism(P, front, a, i, z0, z1)); }

  for (let x = 4; x < LX; x += 11) { const s = solid(g); box(s, x - 2.5, -2, x + 2.5, Y1 + 2, 0, 1.5); }
  [4, 16].forEach((y) => { const s = solid(g); box(s, 0, y - 0.8, LX, y + 0.8, 1.5, 3); });
  const farW = [0, 1].map(() => mk("path", { class: "sil" }, g));
  const heap = mk("path", { class: "sil" }, g);
  const body = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf lo" }, g);
  const nearW = [0, 1].map(() => mk("path", { class: "sil" }, g));
  const hubs = mk("path", { class: "nf lo" }, g);

  const pos = spring(REST, { k: value, c: 2 * Math.sqrt(value) * 0.9 });
  let last = NaN;
  function wheel(cx, y) { const r = []; for (let i = 0; i < 18; i++) { const a = (i / 18) * Math.PI * 2; r.push(P(cx + 4 * Math.cos(a), y, 7 + 4 * Math.sin(a))); } return poly(r); }
  function draw(c) {
    if (c === last) return; last = c;
    farW.forEach((w, k) => w.setAttribute("d", wheel(c + (k ? 7 : -7), 3)));
    const pts = [];
    [[-9, 3, 17, 6], [-13, 0, 20, 20]].forEach(([dx, y0, y1, z]) => { pts.push(P(c + dx, y0, z), P(c - dx, y0, z), P(c + dx, y1, z), P(c - dx, y1, z)); });
    body.setAttribute("d", poly(hull(pts)));
    const top = [P(c - 13, 0, 20), P(c + 13, 0, 20), P(c + 13, 20, 20), P(c - 13, 20, 20)];
    rim.setAttribute("d", poly(top));
    const hp = [];
    for (let i = 0; i <= 12; i++) { const u = i / 12; hp.push(P(c - 11 + 22 * u, 10, 20 + 7 * Math.sin(Math.PI * u) + (i % 3 === 1 ? 1.5 : 0))); }
    hp.push(P(c + 12, 18, 20), P(c - 12, 18, 20), P(c - 12, 2, 20), P(c + 12, 2, 20));
    heap.setAttribute("d", poly(hull(hp)));
    nearW.forEach((w, k) => w.setAttribute("d", wheel(c + (k ? 7 : -7), 17)));
    const a = -(c - REST) / 4;
    hubs.setAttribute("d", [-7, 7].map((dx) => { const p = P(c + dx, 17, 7), q = P(c + dx + 3.5 * Math.cos(a), 17, 7 + 3.5 * Math.sin(a)); return "M" + p + "L" + q; }).join(""));
  }
  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(pos.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function set(x) {
    if (x === act) return; act = x;
    pos.t = x === null ? REST : x;
    body.classList.toggle("hi", true);
    read.textContent = x === null ? "rest" : "m " + Math.round(x);
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 12);
    if (x < -6 || x > LX + 6 || y < -14 || y > Y1 + 12) return null;
    return Math.round(clamp(x, XMIN, XMAX));
  }
  set(null); draw(REST);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { pos.k = v; pos.c = 2 * Math.sqrt(v) * 0.9; }, destroy: bag.dispose };
}

hairline({
  name: "coalcart",
  means: "A coal-heaped mine cart on a run of track: it rolls along the rails to the spot the pointer picks.",
  rules: [1, 3, 5, 6],
  range: [30, 80, 160],
  tour: [[243, 174], [150, 128], [200, 152], null],
  mount,
});

drumcart.code:
/**
 * Drum trolley: a two-wheeled hand truck carrying an upright barrel drum,
 * the nose plate under it and the handle bar up top. The pointer over the
 * trolley tilts it back on its axle, drum and all, ready to roll. At rest
 * it stands nearly upright, the near wheel bright. The slider is the tilt.
 */
const { Cam, clamp, fit, hull, open, poly, proj, seg, rad, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const AZ = 4, RW = 4.5, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tilt = value;
  const C = Cam(45, 0.5, 5.4);
  fit(C, [[-30, -12, 0], [16, 12, 0], [-30, 12, 44], [16, -12, 44], [16, 12, 30]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const T = (t) => (lx, y, lz) => P(-lz * Math.sin(t) + lx * Math.cos(t), y, AZ + lx * Math.sin(t) + lz * Math.cos(t));
  const wheel = (y) => { const pts = []; for (let i = 0; i < 28; i++) { const a = (i / 28) * Math.PI * 2; pts.push(P(RW * Math.cos(a), y, AZ + RW * Math.sin(a))); } return pts; };
  const farW = mk("path", { class: "sil" }, g); farW.setAttribute("d", poly(wheel(-10)));
  const frame = solid(g), plate = solid(g), drum = solid(g);
  const nearW = solid(g);
  const nw = wheel(10), hub = []; for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2; hub.push(P(1.4 * Math.cos(a), 10, AZ + 1.4 * Math.sin(a))); }
  put(nearW, { sil: poly(nw), crease: poly(hub) });
  const tw = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const F = T(rad(deg));
    let d = "", c = "";
    for (const y of [-6, 6]) d += poly(hull([F(-1.5, y - 1, -3), F(-0.5, y + 1, -3), F(-1.5, y - 1, 38), F(-0.5, y + 1, 38)]));
    d += poly(hull([F(-1.5, -7, 36), F(-0.5, 7, 36), F(-1.5, -7, 38), F(-0.5, 7, 38)]));
    frame.sil.setAttribute("d", d);
    plate.sil.setAttribute("d", poly(hull([F(-1, -8, -4), F(13, -8, -4), F(-1, 8, -4), F(13, 8, -4), F(-1, -8, -3), F(13, 8, -3), F(13, -8, -3), F(-1, 8, -3)])));
    const ring = (lz) => { const r = []; for (let i = 0; i < 32; i++) { const a = (i / 32) * Math.PI * 2; r.push(F(5.5 + 9 * Math.cos(a), 9 * Math.sin(a), lz)); } return r; };
    const fr = (lz) => { const r = []; for (let i = -12; i <= 4; i++) { const a = (i / 32) * Math.PI * 2; r.push(F(5.5 + 9 * Math.cos(a), 9 * Math.sin(a), lz)); } return r; };
    drum.sil.setAttribute("d", poly(hull(ring(-2).concat(ring(26)))));
    c = poly(ring(26)) + open(fr(8)) + open(fr(16)) + seg(F(8, 2, 26), F(10, 2, 26));
    drum.cr.setAttribute("d", c);
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? tilt : REST, performance.now(), 0);
    drum.sil.classList.toggle("hi", !!a);
    nearW.sil.classList.toggle("hi", !a);
    read.textContent = a ? "tilt " + tilt + "°" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(sx > 90 && sx < 310 && sy > 30 && sy < 300 ? 1 : 0), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tilt = v; if (act === 1) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "drumcart",
  means: "A drum trolley: the pointer over it tilts the hand truck back on its axle, barrel and all, ready to roll.",
  rules: [3, 4, 5, 8],
  range: [20, 34, 45],
  tour: [[246, 123], [200, 180], [234, 250], null],
  mount,
});

ibctank.code:
/**
 * IBC tote: a caged square tank on its pallet, the filler cap on top and the
 * drain valve low on the front, standing on a tilt frame. The pointer over
 * it tips the tote forward on the frame's front edge, toward the valve, to
 * drain it. At rest it leans a little, the valve bright. The slider is the tip.
 */
const { Cam, fit, hull, poly, proj, seg, rad, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const X1 = 24, Y1 = 20, H = 24, REST = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 4.8);
  fit(C, [[-2, -2, -4], [X1 + 14, Y1 + 2, -4], [-2, Y1, H + 4], [X1, -2, H + 4]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const base = solid(g);
  const bx = (F, x0, y0, z0, x1, y1, z1) => { const c = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) c.push(F(x, y, z)); return poly(hull(c)); };
  put(base, { sil: bx(P, -2, -2, -4, X1 + 2, Y1 + 2, 0), crease: seg(P(X1 + 2, Y1 + 2, 0), P(-2, Y1 + 2, 0)) + seg(P(X1 + 2, Y1 + 2, 0), P(X1 + 2, -2, 0)) + seg(P(X1 + 2, Y1 + 2, 0), P(X1 + 2, Y1 + 2, -4)) });
  const tank = solid(g), valve = solid(g);
  const tw = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const t = rad(deg), F = (x, y, z) => P(X1 + 2 + (x - X1 - 2) * Math.cos(t) + z * Math.sin(t), y, -(x - X1 - 2) * Math.sin(t) + z * Math.cos(t));
    let sil = bx(F, 0, 0, 0, X1, Y1, 3) + bx(F, 0.5, 0.5, 3, X1 - 0.5, Y1 - 0.5, H);
    let c = seg(F(X1, Y1, 3), F(0, Y1, 3)) + seg(F(X1, Y1, 3), F(X1, 0, 3));
    for (let i = 1; i < 4; i++) { const x = (X1 * i) / 4, y = (Y1 * i) / 4; c += seg(F(x, Y1 - 0.5, 3), F(x, Y1 - 0.5, H)) + seg(F(X1 - 0.5, y, 3), F(X1 - 0.5, y, H)); }
    for (const z of [10, 17]) c += seg(F(0.5, Y1 - 0.5, z), F(X1 - 0.5, Y1 - 0.5, z)) + seg(F(X1 - 0.5, Y1 - 0.5, z), F(X1 - 0.5, 0.5, z));
    c += seg(F(X1 - 0.5, Y1 - 0.5, H), F(0.5, Y1 - 0.5, H)) + seg(F(X1 - 0.5, Y1 - 0.5, H), F(X1 - 0.5, 0.5, H)) + seg(F(X1 - 0.5, Y1 - 0.5, H), F(X1 - 0.5, Y1 - 0.5, 3));
    const cap = []; for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; cap.push(F(X1 / 2 + 4 * Math.cos(a), Y1 / 2 + 4 * Math.sin(a), H)); }
    c += poly(cap);
    tank.sil.setAttribute("d", sil);
    tank.cr.setAttribute("d", c);
    valve.sil.setAttribute("d", bx(F, X1 - 0.5, Y1 / 2 - 2, 4, X1 + 4, Y1 / 2 + 2, 7.5));
    valve.cr.setAttribute("d", seg(F(X1 + 4, Y1 / 2, 7.5), F(X1 + 4, Y1 / 2 + 6, 9)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? tip : REST, performance.now(), 0);
    tank.sil.classList.toggle("hi", !!a);
    valve.sil.classList.toggle("hi", !a);
    read.textContent = a ? "tip " + tip + "°" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(sx > 70 && sx < 330 && sy > 30 && sy < 290 ? 1 : 0), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; if (act === 1) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

