mailsorter.code:
/**
 * Mail sorter: a pigeonhole cabinet, four columns by three rows, a letter in
 * every hole. The pointer picks a hole by its rest position on the face: that
 * letter slides far out, the others ease out after it, staggered by distance.
 * At rest the letters sit at uneven depths, one bright. The slider is the stagger.
 */
const { Cam, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const NC = 4, NR = 3, CW = 11, RH = 10, D = 16, X1 = NC * CW, Z1 = NR * RH + 2, OUT = 15;
const REST = [3, 1, 5, 2, 1, 4, 2, 6, 4, 2, 3, 1], FAV = 7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.9);
  fit(C, [[0, 0, 0], [X1, D + OUT + 2, 0], [0, D + OUT, Z1], [X1, 0, Z1 + 4]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const bx = (x0, y0, z0, x1, y1, z1) => { const c = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) c.push(P(x, y, z)); return poly(hull(c)); };
  const cab = solid(g);
  let c = seg(P(X1, D, Z1), P(0, D, Z1)) + seg(P(X1, D, Z1), P(X1, 0, Z1)) + seg(P(X1, D, Z1), P(X1, D, 0));
  for (let i = 1; i < NC; i++) c += seg(P(i * CW, D, 1), P(i * CW, D, Z1 - 1));
  for (let r = 0; r <= NR; r++) c += seg(P(1, D, 1 + r * RH), P(X1 - 1, D, 1 + r * RH));
  c += seg(P(1, D, 1), P(1, D, Z1 - 1)) + seg(P(X1 - 1, D, 1), P(X1 - 1, D, Z1 - 1));
  put(cab, { sil: bx(0, 0, 0, X1, D, Z1), crease: c });
  const L = [];
  for (let r = 0; r < NR; r++) for (let k = 0; k < NC; k++) {
    const i = r * NC + k;
    L.push({ i, r, k, s: solid(g), y: tween(REST[i]), last: NaN, at: P(k * CW + CW / 2, D, 1 + r * RH + 3) });
  }
  function draw(l, o) {
    if (o === l.last) return;
    l.last = o;
    const x0 = l.k * CW + 2, x1 = x0 + CW - 4, z0 = 1 + l.r * RH + 1, z1 = z0 + 2.2, y1 = D + o, xm = (x0 + x1) / 2;
    l.s.sil.setAttribute("d", bx(x0, D - 0.2, z0, x1, y1, z1));
    l.s.cr.setAttribute("d", seg(P(x1, y1, z1), P(x0, y1, z1)) + seg(P(x1, y1, z1), P(x1, D, z1)) + seg(P(x0 + 1, y1 - 3, z1), P(xm, y1 - 1.2, z1)) + seg(P(xm, y1 - 1.2, z1), P(x1 - 1, y1 - 3, z1)));
  }
  const B = register(stage, (_dt, now) => { let m = false; L.forEach((l) => { draw(l, tval(l.y, now)); if (!tdone(l.y, now)) m = true; }); return m; });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    let best = -1, bd = 22 * 22;
    L.forEach((l) => { const d = (l.at[0] - sx) ** 2 + (l.at[1] - sy) ** 2; if (d < bd) { bd = d; best = l.i; } });
    return best;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const fr = from >= 0 ? L[from] : null;
    L.forEach((l) => {
      const dist = fr ? Math.abs(l.k - fr.k) + Math.abs(l.r - fr.r) : 0;
      const o = a < 0 ? REST[l.i] : l.i === a ? OUT : Math.max(2, 9 - dist * 2.2);
      tset(l.y, o, now, fr ? dist * stag : 0);
      l.s.sil.classList.toggle("hi", l.i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + String.fromCharCode(65 + L[a].r) + (L[a].k + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "mailsorter",
  means: "A pigeonhole mail sorter: the letter in the hole under the pointer slides far out, the rest ease out after it.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[203, 124], [182, 140], [218, 243], null],
  mount,
});

dockdoor.code:
/**
 * Dock door: a loading-dock wall with a roll-up sectional door, the coil
 * hood above it, rubber bumpers either side and the dock plate below. The
 * pointer over the opening rolls the door up into its hood, slat by slat.
 * At rest it stands just cracked open, its bottom bar bright. The slider is how far it opens.
 */
const { Cam, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 56, T = 4, HW = 46, DX0 = 10, DX1 = 46, DH = 32, REST = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[0, 0, -6], [W, T + 10, -6], [0, T + 10, HW], [W, 0, HW]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const bx = (x0, y0, z0, x1, y1, z1) => { const c = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) c.push(P(x, y, z)); return poly(hull(c)); };
  const ed = (x0, y0, z0, x1, y1, z1) => seg(P(x1, y1, z1), P(x0, y1, z1)) + seg(P(x1, y1, z1), P(x1, y0, z1)) + seg(P(x1, y1, z1), P(x1, y1, z0));
  const plat = solid(g);
  put(plat, { sil: bx(0, 0, -6, W, T + 10, 0), crease: ed(0, 0, -6, W, T + 10, 0) + poly([P(DX0, T, 0), P(DX1, T, 0), P(DX1, T + 7, 0), P(DX0, T + 7, 0)]) });
  const wall = solid(g);
  const ins = seg(P(DX0, T, DH), P(DX0 + 3, T - 3, DH - 3)) + seg(P(DX0 + 3, T - 3, DH - 3), P(DX0 + 3, T - 3, 0)) + seg(P(DX0 + 3, T - 3, DH - 3), P(DX1, T - 3, DH - 3));
  put(wall, { sil: bx(0, 0, 0, W, T, HW), crease: ed(0, 0, 0, W, T, HW) + poly([P(DX0, T, 0), P(DX1, T, 0), P(DX1, T, DH), P(DX0, T, DH)]) + ins });
  for (const [x0, z0, x1, z1] of [[14, 0, 26, 11], [27, 0, 40, 13], [16, 11, 25, 20], [29, 13, 38, 22]]) { const b = solid(g); put(b, { sil: bx(x0, 0.4, z0, x1, T, z1), crease: ed(x0, 0.4, z0, x1, T, z1) + seg(P((x0 + x1) / 2, T, z0 + 1), P((x0 + x1) / 2, T, z1 - 1)) }); }
  const door = solid(g), bar = solid(g);
  const hood = solid(g);
  put(hood, { sil: bx(DX0 - 2, T, DH, DX1 + 2, T + 4, DH + 6), crease: ed(DX0 - 2, T, DH, DX1 + 2, T + 4, DH + 6) });
  for (const x of [DX0 - 5, DX1 + 1]) { const b = solid(g); put(b, { sil: bx(x, T, 3, x + 4, T + 3, 9), crease: ed(x, T, 3, x + 4, T + 3, 9) }); }
  const tw = tween(REST);
  let last = NaN;
  function draw(h) {
    if (h === last) return;
    last = h;
    const y = T + 0.6, xm = (DX0 + DX1) / 2;
    door.sil.setAttribute("d", poly([P(DX0, y, h), P(DX1, y, h), P(DX1, y, DH), P(DX0, y, DH)]));
    let c = "";
    for (let z = DH - 3; z > h + 0.5; z -= 3) c += seg(P(DX0, y, z), P(DX1, y, z));
    door.cr.setAttribute("d", c);
    bar.sil.setAttribute("d", bx(DX0, y, h, DX1, y + 1.2, h + 1.6));
    bar.cr.setAttribute("d", seg(P(xm - 3, y + 1.2, h + 0.8), P(xm + 3, y + 1.2, h + 0.8)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? ((DH - 2) * open) / 100 : REST, performance.now(), 0);
    door.sil.classList.toggle("hi", !!a);
    bar.sil.classList.toggle("hi", !a);
    read.textContent = a ? "open " + open + "%" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(sx > 60 && sx < 340 && sy > 30 && sy < 300 ? 1 : 0), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act === 1) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "dockdoor",
  means: "A loading-dock door: the pointer over the opening rolls the sectional door up into its hood, slat by slat.",
  rules: [3, 4, 5, 8],
  range: [60, 100, 100],
  tour: [[205, 149], [150, 168], [250, 253], null],
  mount,
});

axlestand.code:
/**
 * Axle stand: a four-legged stand on a square foot, a collar with its pawl
 * lever, and a toothed ratchet column carrying a saddle. The pointer is how
 * high the axle sits: the nearer it comes to the stand, the further the column
 * slides up out of the collar, notch by notch. At rest the column stands a few
 * notches up, saddle bright. The slider is the column's reach.
 *
 * The pattern: one continuous lift on a spring; the hit is on the floor plane.
 */
const {
  Cam, fit, prism, proj, rings, seg, unproj, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const FT = 20, CL = 6, CO = 4, CZ = 34, NOTCH = 4, REST = 10, MAX = 30;
const box = (P, front, x0, y0, x1, y1, z0, z1, r = 1.2, b = 0.7) => {
  const [o, i] = rings(x0, y0, x1, y1, r, b);
  return prism(P, front, o, i, z0, z1);
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[-FT, -FT, 0], [FT, FT, 0], [-FT, FT, 0], [FT, -FT, 0], [0, 0, CZ + 20 + MAX + 8]], 200, 160);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), box(P, front, -FT, -FT, FT, FT, 0, 2.5, 3, 1.4));
  const legs = [];
  for (const [sx, sy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    legs.push(seg(P(sx * (FT - 3), sy * (FT - 3), 2.5), P(sx * CL, sy * CL, CZ - 4)));
    legs.push(seg(P(sx * (FT - 7), sy * (FT - 3), 2.5), P(sx * (CL - 1), sy * CL, CZ - 6)));
  }
  mk("path", { class: "nf sil", d: legs.join("") }, g);
  put(solid(g), box(P, front, -CL, -CL, CL, CL, CZ - 6, CZ, 1.5, 0.8));
  // pawl lever on the collar's near face
  mk("path", { class: "nf sil", d: seg(P(CL, 0, CZ - 3), P(CL + 12, 4, CZ + 4)) }, g);
  const col = solid(g), sad = solid(g), ears = solid(g);
  const lift = spring(REST, { k: 120, c: 20 });
  let drawn = NaN, max = MAX * value;

  function draw() {
    const h = lift.x;
    if (Math.abs(h - drawn) < 1e-3) return;
    drawn = h;
    const top = CZ + 14 + h;
    const c = box(P, front, -CO, -CO, CO, CO, CZ, top, 0.6, 0.4);
    let teeth = "";
    for (let z = top - 3; z > CZ + 1; z -= NOTCH) {
      teeth += seg(P(CO, -CO, z), P(CO, CO, z - 1.5)) + seg(P(-CO, CO, z), P(CO, CO, z - 1.5));
    }
    put(col, { sil: c.sil, crease: c.crease + teeth });
    put(sad, box(P, front, -10, -5, 10, 5, top, top + 3, 1.5, 0.8));
    const e1 = box(P, front, -10, -5, -7, 5, top + 3, top + 8, 0.8, 0.4), e2 = box(P, front, 7, -5, 10, 5, top + 3, top + 8, 0.8, 0.4);
    put(ears, { sil: e1.sil + e2.sil, crease: e1.crease + e2.crease });
  }
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(d) {
    lift.t = d == null ? REST : clamp(REST + (max - REST) * (1 - d / 46), REST, max);
    sad.sil.classList.toggle("hi", true);
    ears.sil.classList.toggle("hi", true);
    read.textContent = d == null ? "rest" : "notch " + Math.round(lift.t / NOTCH);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      // fixed screen band of the stand at rest: the higher the pointer, the higher the column
      const [cx, fy] = P(0, 0, 0), ty = P(0, 0, CZ + 22 + MAX)[1];
      if (Math.abs(p[0] - cx) > 80 || p[1] > fy + 30 || p[1] < ty - 20) return aim(null);
      aim(46 * (1 - clamp((fy - p[1]) / ((fy - ty) * 0.6), 0, 1)));
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { max = MAX * v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "axlestand",
  means: "An axle stand: the ratchet column slides up out of its collar, notch by notch, as the pointer nears.",
  rules: [1, 3, 5],
  range: [0.6, 1, 1],
  tour: [[200, 99], [222, 33], [200, 140], null],
  mount,
});

transjack.code:
/**
 * Transmission jack: a low cross base on four casters, a two-stage ram and a
 * wide saddle with corner jaws on top. The pointer is the gearbox coming down:
 * the higher it sits over the jack, the further the ram telescopes and the
 * saddle tilts to meet it. At rest the ram is half up, the saddle bright. The
 * slider is the ram's reach.
 *
 * The pattern: one lift and one tilt on springs; the hit is a fixed screen band.
 */
const {
  Cam, fit, prism, proj, rings, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const BL = 26, BZ = 6, REST = 10, MAX = 28, SW = 18;
const box = (P, front, x0, y0, x1, y1, z0, z1, r = 1.5, b = 0.7) => {
  const [o, i] = rings(x0, y0, x1, y1, r, b);
  return prism(P, front, o, i, z0, z1);
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.35);
  fit(C, [[-BL, -BL, 0], [BL, BL, 0], [-BL, BL, 0], [BL, -BL, 0], [-SW, -SW, BZ + 30 + MAX + 14], [SW, SW, BZ + 30], [-SW, SW, BZ + 30], [SW, -SW, BZ + 30]], 200, 160);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  for (const [x, y] of [[-BL + 3, 0], [0, -BL + 3], [0, BL - 3], [BL - 3, 0]]) place(flatDot(g, C, 2.4, "dot off"), P(x, y, 0));
  put(solid(g), box(P, front, -BL, -4, BL, 4, 2, BZ));
  put(solid(g), box(P, front, -4, -BL, 4, BL, 2, BZ));
  put(solid(g), box(P, front, -7, -7, 7, 7, BZ, BZ + 18, 2.5, 1));
  const st1 = solid(g), st2 = solid(g), sad = solid(g), jaws = solid(g);
  const lift = spring(REST, { k: 110, c: 19 });
  let drawn = NaN, max = MAX * value;

  function draw() {
    const h = lift.x;
    if (Math.abs(h - drawn) < 1e-3) return;
    drawn = h;
    const z1 = BZ + 18 + h * 0.5, z2 = z1 + 12 + h * 0.5;
    put(st1, box(P, front, -5, -5, 5, 5, BZ + 18, z1 + 6, 2, 0.8));
    put(st2, box(P, front, -3, -3, 3, 3, z1 + 6, z2, 1.2, 0.5));
    // the saddle tilts toward +x as it rises: a sheared slab
    const t = (h / MAX) * 5, zs = z2;
    const T = (pts) => pts;
    const s = box(P, front, -SW, -SW + 4, SW, SW - 4, zs, zs + 3, 3, 1.2);
    put(sad, s);
    let js = "", jc = "";
    for (const [x, y] of [[-SW, -SW + 4], [SW - 4, -SW + 4], [-SW, SW - 8], [SW - 4, SW - 8]]) {
      const j = box(P, front, x, y, x + 4, y + 4, zs + 3, zs + 8 + (x > 0 ? t : 0), 1, 0.4);
      js += j.sil; jc += j.crease;
    }
    put(jaws, T({ sil: js, crease: jc }));
  }
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(u) {
    lift.t = u == null ? REST : clamp(REST + (max - REST) * u, REST, max);
    sad.sil.classList.toggle("hi", true);
    read.textContent = u == null ? "rest" : Math.round(lift.t) + " cm";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [cx, fy] = P(0, 0, 0), ty = P(0, 0, BZ + 30 + MAX)[1];
      if (Math.abs(p[0] - cx) > 90 || p[1] > fy + 40 || p[1] < ty - 20) return aim(null);
      aim(clamp((fy - p[1]) / ((fy - ty) * 0.6), 0, 1));
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { max = MAX * v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "transjack",
  means: "A transmission jack: the two-stage ram telescopes up and lifts its jawed saddle as the pointer rises over it.",
  rules: [1, 3, 5],
  range: [0.6, 1, 1],
  tour: [[200, 136], [200, 90], [200, 190], null],
  mount,
});

brakebleeder.code:
/**
 * Brake caliper: a drilled disc on its hub, with the caliper straddling its
 * edge and two pads inside. The pointer is the service: the nearer it comes,
 * the further the caliper slides off the disc's edge and its pads open. At rest
 * the caliper sits just clear of the rim, its body bright. The slider is how
 * far the caliper may slide.
 *
 * The pattern: one slide on a spring; the hit is on the floor plane.
 */
const {
  Cam, circ, fit, prism, proj, rings, unproj, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const R = 32, DZ = 4, CX = 26, REST = 3, MAX = 24;
const box = (P, front, x0, y0, x1, y1, z0, z1, r = 2, b = 0.8) => {
  const [o, i] = rings(x0, y0, x1, y1, r, b);
  return prism(P, front, o, i, z0, z1);
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R, R, 0], [R + MAX + 10, -R, 0], [CX + MAX + 12, 0, 20]], 200, 165);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(R, 96), circ(R - 9, 96), 0, DZ));
  put(solid(g), prism(P, front, circ(12, 48), circ(10, 48), DZ, DZ + 5));
  for (let k = 0; k < 5; k++) { const a = k * 1.2566; place(flatDot(g, C, 1.6, "dot off"), P(6 * Math.cos(a), 6 * Math.sin(a), DZ + 5)); }
  for (let k = 0; k < 18; k++) { const a = k * 0.349 + (k % 2) * 0.12, r = k % 2 ? 26 : 20; place(flatDot(g, C, 1, "dot off"), P(r * Math.cos(a), r * Math.sin(a), DZ)); }
  const grp = mk("g", {}, g), padA = solid(grp), body = solid(grp), padB = solid(grp);
  const slide = spring(REST, { k: 110, c: 19 });
  let drawn = NaN, max = MAX * value;

  function draw() {
    const s = slide.x;
    if (Math.abs(s - drawn) < 1e-3) return;
    drawn = s;
    const x = CX + s, open = s * 0.12;
    put(padA, box(P, front, x - 4, -9, x + 4, 9, DZ - 3 - open, DZ - 1 - open, 1.5, 0.6));
    put(body, box(P, front, x - 2, -13, x + 12, 13, -3 - open, 13 + open, 4, 1.4));
    put(padB, box(P, front, x - 5, -10, x + 5, 10, 13 + open, 16 + open, 2, 0.8));
  }
  const B = register(stage, (dt) => { const m = stepS(slide, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(d) {
    slide.t = d == null ? REST : clamp(REST + (max - REST) * (1 - d / 60), REST, max);
    body.sil.classList.toggle("hi", true);
    read.textContent = d == null ? "rest" : Math.round(slide.t) + " mm";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], DZ), d = Math.hypot(x - CX - REST - 5, y);
      aim(Math.hypot(x, y) > R + 50 && d > 40 ? null : d);
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { max = MAX * v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "brakebleeder",
  means: "A disc brake caliper: the caliper slides off the drilled disc and its pads open as the pointer nears.",
  rules: [1, 3, 5],
  range: [0.5, 1, 1],
  tour: [[243, 196], [80, 127], [200, 165], null],
  mount,
});

cuttingplotter.code:
/**
 * Vinyl cutter: a long plotter body with a vinyl roll behind it, a sheet fed
 * out in front, a hinged cover on top and the blade carriage on its front rail.
 * The pointer over the cutter swings the cover open, the carriage slides to the
 * pointer and the sheet feeds further out. At rest the cover is ajar and the
 * carriage is bright. The slider is how far the cover opens.
 */
const { Cam, clamp, facing, fit, hull, poly, prism, proj, rrect, seg, unproj, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const X1 = 64, Y1 = 16, H = 14, T = 2, AMAX = 100;

function rx(p, cy, cz, a) {
  const dy = p[1] - cy, dz = p[2] - cz, c = Math.cos(a), s = Math.sin(a);
  return [p[0], cy + dy * c - dz * s, cz + dy * s + dz * c];
}
function box(x0, y0, z0, x1, y1, z1) {
  return [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = value;
  const C = Cam(45, 0.5, 3.6);
  const lidOpen = box(0, 0, H, X1, Y1, H + T).map((p) => rx(p, 0, H, -(AMAX * Math.PI) / 180));
  fit(C, [[0, -10, 0], [X1, Y1 + 30, 0], [X1, -10, 0], [0, Y1 + 30, 0]].concat(lidOpen.map((p) => [p[0], p[1], p[2]])), 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const pp = (p) => P(...p);

  // the roll behind: a cylinder along x
  const circ = (x) => { const o = []; for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; o.push([x, -6 + 4.5 * Math.cos(a), 5 + 4.5 * Math.sin(a)]); } return o; };
  mk("path", { class: "sil", d: poly(hull(circ(3).concat(circ(X1 - 3)).map(pp))) }, g);
  mk("path", { class: "nf lo", d: poly(circ(X1 - 3).map(pp)) }, g);

  // the sheet on the ground in front
  const sheet = mk("path", { class: "sil" }, g);
  // the body
  const body = solid(g);
  put(body, prism(P, front, rrect(0, 0, X1, Y1, 4, 8), rrect(1.2, 1.2, X1 - 1.2, Y1 - 1.2, 2.8, 8), 0, H));
  mk("path", { class: "nf lo", d: seg(P(4, Y1, 9), P(X1 - 4, Y1, 9)) + seg(P(4, Y1, 6), P(X1 - 4, Y1, 6)) }, body.g);
  // the cover
  const lid = { g: mk("g", {}, g) };
  lid.sil = mk("path", { class: "sil" }, lid.g);
  lid.ln = mk("path", { class: "nf lo" }, lid.g);
  // the carriage on the front rail
  const car = solid(g);

  const o = tween(0.14), cx = tween(20);
  let last = "";
  function draw(ov, x) {
    const key = ov.toFixed(4) + "," + x.toFixed(3) + "," + amax;
    if (key === last) return;
    last = key;
    const sl = 12 + ov * 16;
    sheet.setAttribute("d", poly([[6, Y1, 6], [X1 - 6, Y1, 6], [X1 - 6, Y1 + sl, 0.3], [6, Y1 + sl, 0.3]].map(pp)));
    const a = -(ov * amax * Math.PI) / 180;
    const pts = box(0.5, 0, H, X1 - 0.5, Y1, H + T).map((p) => rx(p, 0, H, a));
    lid.sil.setAttribute("d", poly(hull(pts.map(pp))));
    lid.ln.setAttribute("d", poly([pts[4], pts[5], pts[6], pts[7]].map(pp)));
    put(car, prism(P, front, rrect(x - 4, Y1 - 2, x + 4, Y1 + 4, 1.6, 4), rrect(x - 3.2, Y1 - 1.2, x + 3.2, Y1 + 3.2, 0.8, 4), 7, 15));
  }

  const B = register(stage, (_dt, now) => { draw(tval(o, now), tval(cx, now)); return !tdone(o, now) || !tdone(cx, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < -4 || x > X1 + 4 || y < -12 || y > Y1 + 14) return null;
    return clamp(x, 6, X1 - 6);
  }
  let act = null;
  function setActive(x) {
    if (x === act) return;
    const now = performance.now();
    act = x;
    tset(o, x === null ? 0.14 : 1, now, 0);
    tset(cx, x === null ? 20 : x, now, 0);
    car.sil.classList.toggle("hi", true);
    read.textContent = x === null ? "rest" : "x " + Math.round(x);
    B.wake();
  }
  setActive(null);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = v; last = ""; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "cuttingplotter",
  means: "A vinyl cutter: the pointer swings its cover open, slides the blade carriage to it and feeds the sheet out.",
  rules: [1, 3, 5, 6],
  range: [40, 80, 100],
  tour: [[236, 138], [190, 125], [281, 137], null],
  mount,
});

inkjar.code:
/**
 * Screen print press: a base board with a sheet on it, a hinge clamp at the
 * back and the mesh frame held up in it, a squeegee resting on the frame. The
 * pointer over the press swings the frame down onto the sheet and draws the
 * squeegee across the mesh. At rest the frame is raised and the squeegee is
 * bright. The slider is how high the frame rests.
 */
const { Cam, facing, fit, hull, poly, prism, proj, rrect, seg, unproj, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;
const D = Math.PI / 180;
function rx(p, cy, cz, a) {
  const dy = p[1] - cy, dz = p[2] - cz, c = Math.cos(a), s = Math.sin(a);
  return [p[0], cy + dy * c - dz * s, cz + dy * s + dz * c];
}
function box(x0, y0, z0, x1, y1, z1) {
  return [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
}
function plate(parent) { const g = mk("g", {}, parent); return { g, sil: mk("path", { class: "sil" }, g), ln: mk("path", { class: "nf lo" }, g) }; }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 3.7);
  const up = box(6, 4, 2, 44, 34, 12).map((p) => rx(p, 4, 4, 60 * D));
  fit(C, [[0, 0, 0], [50, 0, 0], [50, 40, 0], [0, 40, 0]].concat(up), 200, 165);
  const P = proj(C), front = facing(C), pp = (p) => P(...p);
  const g = mk("g", {}, svg);
  const base = solid(g);
  put(base, prism(P, front, rrect(0, 0, 50, 40, 2, 4), rrect(1, 1, 49, 39, 1, 4), 0, 2));
  mk("path", { class: "nf lo", d: poly([[12, 10, 2], [38, 10, 2], [38, 30, 2], [12, 30, 2]].map(pp)) }, base.g);
  const clampS = solid(g);
  put(clampS, prism(P, front, rrect(14, 0, 36, 4, 1, 3), rrect(15, 1, 35, 3, 0.5, 3), 2, 8));
  const frame = plate(g), sq = plate(g);
  const o = tween(1), s = tween(0);
  let last = "";
  function draw(v, sv) {
    const key = v.toFixed(4) + "," + sv.toFixed(4) + "," + lift;
    if (key === last) return;
    last = key;
    const a = v * lift * D;
    const T = (p) => rx(p, 4, 4, a);
    const pts = box(6, 4, 2, 44, 34, 5).map(T);
    frame.sil.setAttribute("d", poly(hull(pts.map(pp))));
    frame.ln.setAttribute("d", poly([[10, 8, 5], [40, 8, 5], [40, 30, 5], [10, 30, 5]].map(T).map(pp)));
    const y = 10 + sv * 16;
    const q = box(9, y, 5, 41, y + 2, 9).map(T).concat(box(23, y + 0.2, 9, 27, y + 1.8, 13).map(T));
    sq.sil.setAttribute("d", poly(hull(q.map(pp))));
    sq.ln.setAttribute("d", seg(pp(T([9, y + 2, 9])), pp(T([41, y + 2, 9]))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(o, now), tval(s, now)); return !tdone(o, now) || !tdone(s, now); });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 4);
    return x > -4 && x < 54 && y > -10 && y < 44;
  }
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    const now = performance.now();
    tset(o, on ? 0 : 1, now, 0);
    tset(s, on ? 1 : 0, now, on ? 260 : 0);
    sq.sil.classList.toggle("hi", true);
    read.textContent = on ? "pull" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; last = ""; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "inkjar",
  means: "A screen print press: the pointer swings the mesh frame down onto the sheet and the squeegee is drawn across it.",
  rules: [1, 3, 5, 6],
  range: [25, 45, 60],
  tour: [[200, 176], [187, 149], [213, 244], null],
  mount,
});

laserlevel.code:
/**
 * Laser level: a self-levelling laser head on a three-legged tripod. The head
 * turns on its mount to face the pointer and its beam sweeps round with it.
 * At rest it faces a little to the left, its lens bright. The slider is how
 * far the head may turn from its rest.
 */
const { Cam, clamp, fit, hull, poly, proj, unproj, seg, spring, stepS, disposer, mk, pointer, register, rad } = HL;

// T: local box points through a pivot, rotated about x (rx), then y (ry), then z (az)
function xf(pv, az, ry, rx) {
  const ca = Math.cos(az), sa = Math.sin(az), cy = Math.cos(ry), sy = Math.sin(ry), cx = Math.cos(rx), sx = Math.sin(rx);
  return ([x, y, z]) => {
    const y1 = y * cx - z * sx, z1 = y * sx + z * cx, x2 = x * cy + z1 * sy, z2 = -x * sy + z1 * cy;
    return [pv[0] + x2 * ca - y1 * sa, pv[1] + x2 * sa + y1 * ca, pv[2] + z2];
  };
}
const ID = xf([0, 0, 0], 0, 0, 0);
function box(g) { const grp = mk("g", {}, g); return { g: grp, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp) }; }
function drawBox(P, el, b, T) {
  const [x0, x1, y0, y1, z0, z1] = b, pts = [];
  for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) pts.push(P(...T([x, y, z])));
  el.sil.setAttribute("d", poly(hull(pts)));
  el.cr.setAttribute("d", poly([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]].map((p) => P(...T(p)))));
}
const H = 46, REST = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, on = false;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[-30, -30, 0], [30, 30, 0], [0, 0, H + 18], [62, 0, H + 6], [0, 62, H + 6], [-62, 0, H + 6]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const feet = [90, 210, 330].map((d) => [26 * Math.cos(rad(d + 45)), 26 * Math.sin(rad(d + 45)), 0]);
  mk("path", { d: feet.map((f) => seg(P(...f), P(f[0] * 0.15, f[1] * 0.15, H - 6))).join("") }, g);
  const hub = box(g);
  drawBox(P, hub, [-6, 6, -6, 6, H - 6, H], ID);
  const beam = mk("path", { class: "dash" }, g), body = box(g), lens = box(g);
  lens.sil.classList.add("hi");
  const az = spring(REST);
  function draw() {
    const T = xf([0, 0, H], rad(az.x), 0, 0);
    beam.setAttribute("d", seg(P(...T([14, 0, 8])), P(...T([60, 0, 8]))));
    const away = Math.cos(rad(az.x)) + Math.sin(rad(az.x)) < 0;
    if (away) { g.insertBefore(lens.g, body.g); g.insertBefore(beam, lens.g); } else { body.g.after(lens.g); lens.g.after(beam); }
    drawBox(P, body, [-10, 10, -8, 8, 0, 16], T);
    drawBox(P, lens, [10, 14, -4, 4, 4, 12], T);
    read.textContent = !on ? "rest" : Math.round(((az.t % 360) + 360) % 360) + "°";
  }
  draw();
  const B = register(stage, (dt) => { const m = stepS(az, dt); draw(); return m; });
  bag.add(B.unregister);
  function move([sx, sy]) {
    on = true;
    const [x, y] = unproj(C, sx, sy, 0);
    const a = Math.atan2(y, x) * 180 / Math.PI, d = ((a - REST + 540) % 360) - 180;
    az.t = REST + clamp(d, -180 * reach, 180 * reach);
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { on = false; az.t = REST; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "laserlevel",
  means: "A laser level on a tripod: the head turns on its mount to face the pointer and its beam sweeps round with it.",
  rules: [1, 3, 5],
  range: [0.2, 1, 1],
  tour: [[128, 178], [80, 202], [290, 190], null],
  mount,
});

tilecutter.code:
/**
 * Tile cutter: a manual tile cutter, a long bed with end blocks and twin
 * rails, a tile laid on it and a scoring carriage with a tall handle. The
 * carriage slides along the rails to the pointer, the handle leaning into
 * the cut. At rest it waits near the start, handle bright. The slider is how
 * far it may travel.
 */
const { Cam, clamp, fit, hull, poly, proj, unproj, seg, spring, stepS, disposer, mk, pointer, register, rad } = HL;

// T: local box points through a pivot, rotated about x (rx), then y (ry), then z (az)
function xf(pv, az, ry, rx) {
  const ca = Math.cos(az), sa = Math.sin(az), cy = Math.cos(ry), sy = Math.sin(ry), cx = Math.cos(rx), sx = Math.sin(rx);
  return ([x, y, z]) => {
    const y1 = y * cx - z * sx, z1 = y * sx + z * cx, x2 = x * cy + z1 * sy, z2 = -x * sy + z1 * cy;
    return [pv[0] + x2 * ca - y1 * sa, pv[1] + x2 * sa + y1 * ca, pv[2] + z2];
  };
}
const ID = xf([0, 0, 0], 0, 0, 0);
function box(g) { const grp = mk("g", {}, g); return { g: grp, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp) }; }
function drawBox(P, el, b, T) {
  const [x0, x1, y0, y1, z0, z1] = b, pts = [];
  for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) pts.push(P(...T([x, y, z])));
  el.sil.setAttribute("d", poly(hull(pts)));
  el.cr.setAttribute("d", poly([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]].map((p) => P(...T(p)))));
}
const REST = -20;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, on = false;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-46, -16, 0], [46, 16, 0], [-30, 0, 52], [34, 0, 52]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const bed = box(g), back = box(g), tile = box(g);
  drawBox(P, bed, [-46, 46, -16, 16, 0, 5], ID);
  drawBox(P, back, [-46, -38, -16, 16, 5, 16], ID);
  drawBox(P, tile, [-32, 32, -13, 13, 5, 7], ID);
  mk("path", { class: "dash", d: seg(P(-32, 0, 7), P(32, 0, 7)) }, g);
  const rails = [box(g), box(g)];
  rails.forEach((r, i) => drawBox(P, r, [-38, 38, (i ? 7 : -9), (i ? 9 : -7), 12, 14], ID));
  const car = box(g), handle = box(g), knob = box(g), front = box(g);
  drawBox(P, front, [38, 46, -16, 16, 5, 16], ID);
  handle.sil.classList.add("hi");
  const cx = spring(REST);
  function draw() {
    const lean = clamp((cx.x - REST) / 50, -1, 1) * 18;
    drawBox(P, car, [-6, 6, -12, 12, 0, 6], xf([cx.x, 0, 10], 0, 0, 0));
    const T = xf([cx.x, 0, 16], 0, rad(-20 - lean), 0);
    drawBox(P, handle, [-2.2, 2.2, -2.2, 2.2, 0, 30], T);
    drawBox(P, knob, [-4, 4, -4, 4, 30, 38], T);
    read.textContent = !on ? "rest" : Math.round(cx.t + 32) + "mm";
  }
  draw();
  const B = register(stage, (dt) => { const m = stepS(cx, dt); draw(); return m; });
  bag.add(B.unregister);
  function move([sx, sy]) {
    on = true;
    const [x] = unproj(C, sx, sy, 10);
    cx.t = clamp(x, REST - 10 * reach, REST + 52 * reach);
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { on = false; cx.t = REST; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "tilecutter",
  means: "A manual tile cutter: the scoring carriage slides along its rails to the pointer, the tall handle leaning into the cut.",
  rules: [1, 3, 5],
  range: [0.2, 1, 1],
  tour: [[180, 172], [237, 199], [246, 203], null],
  mount,
});

lockbox.code:
/**
 * Lockbox: a realtor's key safe, a squat body with a keypad on its face and
 * a steel shackle on top. The pointer on it opens it: the shackle lifts and
 * swings round on its left leg, and the key vault under the keypad drops
 * open. At rest the shackle sits a little proud, bright. The slider is how
 * far the shackle swings.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 44, D = 28, H = 56, VZ = 18, DROP = 9, LX0 = 11, LX1 = 33, SH = 26, RI = 11;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[0, 0, -DROP], [W, D, -DROP], [W, 0, 0], [0, D, H + SH + 28], [W, D, H], [-24, D / 2, H + SH + 28], [LX0, D / 2 + 30, H + SH + 28], [0, 0, H]], 200, 150);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  const shk = mk("path", { class: "nf" }, g);
  const body = solid(g);
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(body, prism(P, front, br, bi, VZ, H));
  const pad = mk("path", { class: "nf lo" }, body.g);
  let k = poly(rrect(9, VZ + 8, W - 9, H - 8, 2, 3).map(onFace(D)));
  for (let c = 0; c < 3; c++) for (let r = 0; r < 4; r++) {
    const x = 15 + c * 7, z = VZ + 13 + r * 7.5;
    k += poly(rrect(x - 2, z - 2, x + 2, z + 2, 0.8, 2).map(onFace(D)));
  }
  pad.setAttribute("d", k);
  const vault = solid(g);
  const lip = mk("path", { class: "nf lo" }, vault.g);
  g.insertBefore(vault.g, body.g);

  // the shackle: a U in the x-z plane, two lines for its thickness
  const U = (r) => {
    const pts = [];
    pts.push([LX0 + 11 - r, -8]);
    for (let i = 0; i <= 12; i++) { const a = Math.PI - (i / 12) * Math.PI; pts.push([LX0 + 11 + r * Math.cos(a), SH + r * Math.sin(a) * 0.9]); }
    pts.push([LX0 + 11 + r, -8]);
    return pts;
  };
  const u0 = U(RI + 2.2), u1 = U(RI - 2.2);
  const st = tween(0), last = [NaN];
  function draw(s) {
    const lift = 3 + s * 6, a = s * swing * Math.PI / 180;
    const pt = ([x, z]) => P(LX0 + (x - LX0) * Math.cos(a), D / 2 + (x - LX0) * Math.sin(a), H + lift + z);
    shk.setAttribute("d", "M" + u0.map((q) => pt(q).join(",")).join("L") + "M" + u1.map((q) => pt(q).join(",")).join("L"));
    const z1 = VZ - s * DROP, z0 = z1 - VZ + 1;
    const [r, i] = rings(1, 1, W - 1, D - 1, 3.4, 1.2);
    put(vault, prism(P, front, r, i, z0, z1));
    lip.setAttribute("d", poly(rrect(W / 2 - 8, z1 - 5, W / 2 + 8, z1 - 3, 0.8, 2).map(onFace(D - 1))));
  }

  const B = register(stage, (_dt, now) => {
    const s = tval(st, now);
    if (s !== last[0]) { draw(s); last[0] = s; }
    return !tdone(st, now);
  });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(st, a ? 1 : 0, performance.now(), 0);
    shk.classList.toggle("hi", !a);
    vault.sil.classList.toggle("hi", !!a);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: () => setActive(1), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; last[0] = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "lockbox",
  means: "A realtor's key lockbox: under the pointer its shackle lifts and swings round, and the key vault drops open below the keypad.",
