blueprintrack.code:
/**
 * Plan chest: a low architect's cabinet of five wide, shallow drawers for
 * flat drawings, standing on a plinth. The pointer picks a drawer on the
 * chest's face: it slides out, and its neighbours come out a little,
 * staggered from it. At rest one drawer stands half open, bright. The
 * slider is the stagger.
 */
const {
  Cam, clamp, facing, fit, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const NR = 5, CW = 96, CH = 10, M = 5, BASE = 9, D = 56, IN = 0.9, OUT = 40;
const W = 2 * M + CW, H = BASE + NR * CH + M, FAV = 2;
const PROUD = [1.2, 3, 22, 1.6, 1.2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D + OUT, BASE], [0, 0, H], [W, 0, H], [W, D + OUT, H - M]], 200, 166);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, W, D, 3, 1.4);
  put(solid(g), prism(P, front, wr, wi, 0, H));
  mk("path", { d: seg(P(1.5, D, BASE - 3), P(W - 1.5, D, BASE - 3)), class: "nf lo" }, g);

  const boxes = [];
  for (let r = 0; r < NR; r++) {
    const x0 = M + IN, x1 = M + CW - IN, z0 = BASE + r * CH + IN, z1 = BASE + (r + 1) * CH - IN;
    mk("path", { d: poly(rrect(x0 - 0.5, z0 - 0.5, x1 + 0.5, z1 + 0.5, 0.8, 2).map(onFace(D))), class: "nf lo" }, g);
    boxes.push({ r, x0, x1, z0, z1, rest: PROUD[r] });
  }
  for (const b of boxes) {
    b.el = solid(g);
    b.plate = mk("path", { class: "nf lo" }, b.el.g);
    b.pull = mk("path", { class: "nf" }, b.el.g);
    b.s = tween(b.rest);
    b.last = NaN;
  }

  function draw(b, s) {
    const y = D + s, xm = (b.x0 + b.x1) / 2, zm = (b.z0 + b.z1) / 2;
    const [r, i] = rings(b.x0, D, b.x1, y, 1.2, Math.min(0.9, s * 0.4));
    put(b.el, prism(P, front, r, i, b.z0, b.z1));
    b.plate.setAttribute("d", poly(rrect(b.x0 + 6, zm - 1.6, b.x0 + 18, zm + 1.6, 0.5, 2).map(onFace(y))));
    b.pull.setAttribute("d", poly(rrect(xm - 9, zm - 1.1, xm + 9, zm + 1.1, 1, 3).map(onFace(y))));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const b of boxes) {
      const s = tval(b.s, now);
      if (s !== b.last) { draw(b, s); b.last = s; }
      if (!tdone(b.s, now)) moving = true;
    }
    return moving;
  });
  bag.add(B.unregister);

  /** The drawer under the point, read on the chest's face plane (y = D), which never moves. */
  function hit([sx, sy]) {
    const c = Math.cos(C.az), s = Math.sin(C.az), zf = Math.sqrt(1 - C.k * C.k);
    const x = ((sx - C.ox) / C.S + D * s) / c, Y = x * s + D * c, z = (Y * C.k - (sy - C.oy) / C.S) / zf;
    if (x < M || x > W - M || z < BASE || z > BASE + NR * CH) return -1;
    return clamp(Math.floor((z - BASE) / CH), 0, NR - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    boxes.forEach((b, i) => {
      const dist = a >= 0 ? Math.abs(i - a) : 0;
      const s = a < 0 ? b.rest : dist === 0 ? OUT : dist === 1 ? 5 : 1.2;
      tset(b.s, s, now, from >= 0 ? Math.abs(i - from) * stag : 0);
      b.el.sil.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : `drw ${NR - a}`;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "blueprintrack",
  means: "A plan chest of five wide flat drawers: the drawer under the pointer slides out, and its neighbours open a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[186, 143], [186, 186], [186, 230], null],
  mount,
});

doorbell2.code:
/**
 * Video doorbell: a slim unit on a wall plate, a camera eye at the top and a
 * ring button below. The pointer on it presses the button: the button sinks
 * into the face and three chime rings spread out round the unit, behind it.
 * At rest the button ring is bright. The slider is how far the rings reach.
 */
const {
  Cam, circ, facing, fit, poly, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 26, T = 9, H = 66, BZ = 17, LZ = 52, BR = 7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.7);
  fit(C, [[-26, T, BZ - 24], [W + 26, T, BZ + 50], [-26, T, BZ + 50], [W + 26, T, BZ - 24], [-6, -5, -6], [W + 6, T, -6]], 200, 180);
  const P = proj(C), front = facing(C);
  const onFace = (y) => (q) => P(q.u, y, q.v);

  const g = mk("g", {}, svg);
  const waves = mk("path", { class: "nf" }, g);
  const plate = solid(g);
  const [pr, pi] = rings(-5, -5, W + 5, 0, 2, 1);
  put(plate, prism(P, front, pr, pi, -5, H + 5));
  const unit = solid(g);
  const [ur, ui] = rings(0, 0, W, T, 4, 1.4);
  put(unit, prism(P, front, ur, ui, 0, H));
  const eye = mk("path", { class: "nf" }, unit.g);
  const ring = (cx, cz, r, y) => poly(circ(r, 24).map((q) => P(cx + q.u, y, cz + q.v)));
  eye.setAttribute("d", ring(W / 2, LZ, 7, T) + ring(W / 2, LZ, 3.6, T) + poly(rrect(4, H - 6, W - 4, H - 4, 1, 2).map(onFace(T))));
  const btn = mk("path", { class: "nf" }, unit.g);

  const st = tween(0), last = [NaN];
  function draw(s) {
    const y = T - s * 1.6;
    btn.setAttribute("d", ring(W / 2, BZ, BR, T) + ring(W / 2, BZ, BR - 2.2, y) + ring(W / 2, BZ, 1.2, y));
    let d = "";
    if (s > 0.02) for (let i = 0; i < 5; i++) {
      const r = (10 + i * 6.5) * s * (0.5 + reach / 200);
      d += ring(W / 2, BZ + 14, r, T);
    }
    waves.setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    const s = tval(st, now);
    if (s !== last[0]) { draw(s); last[0] = s; }
    return !tdone(st, now);
  });
  bag.add(B.unregister);
  btn.classList.add("hi");

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(st, a ? 1 : 0, performance.now(), 0);
    read.textContent = a ? "ding" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: () => setActive(1), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last[0] = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "doorbell2",
  means: "A video doorbell on its wall plate: under the pointer the button sinks in and chime rings spread out round the unit.",
  rules: [3, 4, 5, 6],
  range: [20, 60, 100],
  tour: [[200, 222], [200, 110], [190, 247], null],
  mount,
});

keypad2.code:
/**
 * Door keypad: a lock plate on the door with a lever handle and a keypad
 * under a hinged cover. The cover tilts up as the pointer nears the plate,
 * baring the keys. At rest it is shut and the status lamp is bright.
 */
const { Cam, clamp, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const W = 40, H = 70, HZ = 52, BZ = 18, OPEN = 2.0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lag = value;
  const C = Cam(45, 0.5, 3.9);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, 0, H], [W, 0, H], [0, 40, HZ], [W, 40, HZ]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const hb = (pts) => poly(hull(pts.map((p) => P(...p))));
  const box = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
  mk("path", { class: "sil", d: hb(box(0, 0, 0, W, 4, H)) }, g);
  let keys = "";
  for (let r = 0; r < 4; r++) for (let c = 0; c < 3; c++) {
    const x = 8 + c * 9, z = HZ - 8 - r * 8;
    keys += hb([[x, 4, z], [x + 6, 4, z], [x + 6, 4, z + 5], [x, 4, z + 5]]);
  }
  mk("path", { class: "nf lo", d: keys }, g);
  mk("path", { class: "sil hi", d: hb(box(W / 2 - 2, 4, H - 9, W / 2 + 2, 6, H - 5)) }, g);
  mk("path", { class: "sil", d: hb(box(6, 4, 7, 10, 10, 11)) + hb(box(6, 8, 7, 44, 11, 10)) }, g);
  const cover = mk("path", { class: "sil" }, g);
  const ca = tween(0);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const T = ([x, y, z]) => { const dy = y - 4, dz = z - HZ; return [x, 4 + dy * c - dz * s, HZ + dy * s + dz * c]; };
    cover.setAttribute("d", hb(box(2, 4, BZ, W - 2, 7, HZ).map(T)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ca, now)); return !tdone(ca, now); });
  bag.add(B.unregister);
  const mid = P(W / 2, 4, 35);
  function near(p) {
    const now = performance.now();
    const f = p ? clamp(1.4 - Math.hypot(p[0] - mid[0], p[1] - mid[1]) / 90, 0, 1) : 0;
    tset(ca, f * OPEN, now, lag);
    read.textContent = p && f > 0 ? Math.round(f * 100) + "%" : "rest";
    B.wake();
  }
  near(null);
  bag.add(pointer(stage, { move: (p) => near(p), leave: () => near(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lag = v; }, destroy: bag.dispose };
}

hairline({
  name: "keypad2",
  means: "A door keypad lock: the hinged cover tilts up off the keys as the pointer comes near the plate.",
  rules: [1, 2, 5, 6],
  range: [0, 0, 200],
  tour: [[244, 166], [228, 145], [117, 258], null],
  mount,
