  name: "hammockstand",
  means: "A hammock on a steel stand: the pointer's place along the stand sways the hammock about the line through the post tops.",
  rules: [1, 3, 5, 6],
  range: [20, 45, 60],
  tour: [[93, 142], [200, 196], [307, 250], null],
  mount,
});

roverarm.code:
/**
 * Rover arm: a six-wheeled rover deck with a jointed arm on a turret at
 * its front corner. The arm swings on the turret to follow the pointer and
 * its elbow reaches out; the tool at its tip is bright at rest.
 *
 * The pattern: one part aims at the pointer (aim).
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const PIV = [14, 0, 14];
const pts3 = (P, list) => list.map((q) => P(q[0], q[1], q[2]));
const blob = (a, b, w) => { const o = []; for (const p of [a, b]) for (const dx of [-w, w]) for (const dy of [-w, w]) for (const dz of [-w, w]) o.push([p[0] + dx, p[1] + dy, p[2] + dz]); return o; };
const wheel = (x, y, r, w) => { const o = []; for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; for (const dy of [-w, w]) o.push([x + r * Math.cos(t), y + dy, r + r * Math.sin(t)]); } return o; };
const box = (x0, y0, z0, x1, y1, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x, y, z]); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[-30, -24, 0], [30, 24, 0], [-30, 24, 0], [30, -24, 0], [50, 30, 40], [50, -30, 40], [-30, 0, 30]], 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const shape = (cls, list) => mk("path", { class: cls, d: poly(hull(pts3(P, list))) }, g);
  for (const x of [-20, 0, 20]) shape("sil", wheel(x, 20, 6, 2.5));
  shape("sil", box(-26, -16, 9, 26, 16, 17));
  shape("sil", box(-14, -8, 17, -2, 8, 22));
  shape("sil", blob([-22, -6, 18], [-22, 6, 30], 1.5));
  for (const x of [-20, 0, 20]) shape("sil", wheel(x, -20, 6, 2.5));
  const turret = mk("path", { class: "sil" }, g), upper = mk("path", { class: "sil" }, g),
    fore = mk("path", { class: "sil" }, g), tool = mk("path", { class: "sil" }, g);
  const yaw = tween(-0.5), ext = tween(0.6);
  let last = "";

  function draw(a, e) {
    const key = a.toFixed(4) + e.toFixed(4);
    if (key === last) return; last = key;
    const c = Math.cos(a), s = Math.sin(a);
    const W = (r, z) => [PIV[0] + r * c, PIV[1] + r * s, z];
    const el = W(22 * (0.5 + 0.5 * e), PIV[2] + 22 - 10 * e), tip = W(22 * (0.5 + 0.5 * e) + 18 + 12 * e, PIV[2] + 6 + 6 * e);
    const set = (el2, list) => el2.setAttribute("d", poly(hull(pts3(P, list))));
    set(turret, blob([PIV[0], PIV[1], 17], [PIV[0], PIV[1], 21], 5));
    set(upper, blob([PIV[0], PIV[1], 21], el, 2));
    set(fore, blob(el, tip, 1.6));
    set(tool, blob([tip[0], tip[1], tip[2] - 3], [tip[0], tip[1], tip[2] - 9], 3.5));
  }
  const B = register(stage, (_dt, now) => { draw(tval(yaw, now), tval(ext, now)); return !(tdone(yaw, now) && tdone(ext, now)); });
  bag.add(B.unregister);
  const pv = P(PIV[0], PIV[1], PIV[2]);
  function aim(p) {
    const now = performance.now();
    if (!p) { tset(yaw, -0.5, now, 0); tset(ext, 0.6, now, 0); tool.classList.add("hi"); read.textContent = "rest"; B.wake(); return; }
    const dx = (p[0] - pv[0]) / 90, dy = (p[1] - pv[1]) / 90;
    const a = Math.max(-1.6, Math.min(1.6, Math.atan2(dy + dx, dx - dy)));
    const e = Math.max(0, Math.min(1, Math.hypot(dx, dy) * (0.6 + reach)));
    tset(yaw, a, now, 0); tset(ext, e, now, 0);
    tool.classList.add("hi");
    read.textContent = Math.round((a * 180) / Math.PI) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "roverarm",
  means: "A rover with a jointed arm on a turret: the arm swings round to follow the pointer and reaches out, tool tip bright.",
  rules: [1, 2, 5, 6],
  range: [0, 0.5, 1],
  tour: [[193, 298], [57, 185], [352, 168], null],
  mount,
});

spacesuit2.code:
/**
 * Airlock: a thick airlock door set in a bulkhead, with a locking wheel on
 * its face. The pointer turns the wheel and swings the door open on its
 * hinge, further the further right it goes. At rest the door is shut and
 * the wheel is bright.
 *
 * The pattern: one part swings on a hinge (swing).
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const HX = -16, DW = 32, DH = 44, Z0 = 6, TH = 4, WR = 9;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let spin = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[-30, 0, 0], [30, 6, 0], [-30, 0, 58], [30, 6, 58], [-16, -34, 50], [-16, -34, 0]], 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const H = (list) => poly(hull(list.map((q) => P(q[0], q[1], q[2]))));
  const box = (x0, y0, z0, x1, y1, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x, y, z]); return o; };
  mk("path", { class: "sil", d: H(box(-30, 0, 0, 30, 6, 58)) }, g);
  mk("path", { class: "nf", d: H(box(-20, -1, Z0 - 2, 20, -1, Z0 + DH + 2)) }, g);
  mk("path", { class: "nf lo", d: H(box(-17, -1.2, Z0, 17, -1.2, Z0 + DH)) }, g);
  const door = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g);
  const rim = mk("path", { class: "nf hi" }, g), spokes = mk("path", { class: "nf hi" }, g), hub = mk("path", { class: "nf hi" }, g);
  const ang = tween(0), wh = tween(0);
  let last = "";
  function draw(a, w) {
    const key = a.toFixed(4) + w.toFixed(4);
    if (key === last) return; last = key;
    const c = Math.cos(a), s = Math.sin(a);
    const W = (u, t, z) => [HX + u * c - t * s, -1.5 + u * s + t * c, z];
    const dp = []; for (const u of [0, DW]) for (const t of [0, -TH]) for (const z of [Z0, Z0 + DH]) dp.push(W(u, t, z));
    door.setAttribute("d", H(dp));
    face.setAttribute("d", poly([W(3, -TH - 0.1, Z0 + 3), W(DW - 3, -TH - 0.1, Z0 + 3), W(DW - 3, -TH - 0.1, Z0 + DH - 3), W(3, -TH - 0.1, Z0 + DH - 3)].map((q) => P(q[0], q[1], q[2]))) + "Z");
    const ring = (r) => { const o = []; for (let i = 0; i <= 32; i++) { const t = (i / 32) * Math.PI * 2; const q = W(DW / 2 + r * Math.cos(t), -TH - 3, Z0 + DH / 2 + r * Math.sin(t)); o.push(P(q[0], q[1], q[2])); } return o; };
    rim.setAttribute("d", poly(ring(WR)));
    hub.setAttribute("d", poly(ring(2)));
    let d = "";
    for (let k = 0; k < 3; k++) {
      const t = w + (k * Math.PI) / 3, A = W(DW / 2 + WR * Math.cos(t), -TH - 3, Z0 + DH / 2 + WR * Math.sin(t)), Bq = W(DW / 2 - WR * Math.cos(t), -TH - 3, Z0 + DH / 2 - WR * Math.sin(t));
      const pa = P(A[0], A[1], A[2]), pb = P(Bq[0], Bq[1], Bq[2]);
      d += "M" + pa[0].toFixed(1) + " " + pa[1].toFixed(1) + "L" + pb[0].toFixed(1) + " " + pb[1].toFixed(1);
    }
    spokes.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now), tval(wh, now)); return !(tdone(ang, now) && tdone(wh, now)); });
  bag.add(B.unregister);
  const L = P(-30, 0, 30)[0], R = P(30, 0, 30)[0];
  function act(p) {
    const now = performance.now();
    const f = p ? Math.max(0, Math.min(1, (p[0] - L) / (R - L))) : 0;
    tset(wh, f * Math.PI * (1 + spin), now, 0);
    tset(ang, -f * 1.9, now, f > 0 ? 250 : 0);
    read.textContent = p ? Math.round(f * 100) + "%" : "rest";
    B.wake();
  }
  act(null);
  bag.add(pointer(stage, { move: act, leave: () => act(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { spin = v; }, destroy: bag.dispose };
}

hairline({
  name: "spacesuit2",
  means: "An airlock door in a bulkhead: the pointer spins its locking wheel and swings the heavy door open on its hinge.",
  rules: [1, 2, 5, 6],
  range: [0, 1, 2],
  tour: [[139, 128], [207, 162], [275, 196], null],
  mount,
});

capsulehatch.code:
/**
 * Capsule hatch: a conical space capsule with a round hatch on its top,
 * a handwheel on the hatch. The pointer swings the hatch up on its hinge,
 * further the further right it goes, and turns the handwheel as it opens.
 * At rest the hatch is shut and its handwheel is bright.
 *
 * The pattern: one part tilts open on a hinge (tilt).
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const RB = 24, RT = 15, ZT = 26, HR = 13, HT = 4, HX = -HR;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let spin = value;
  const C = Cam(45, 0.5, 4.4);
  fit(C, [[-RB, -RB, 0], [RB, RB, 0], [-RB, RB, 0], [RB, -RB, 0], [-2 * HR - 4, 0, ZT + 2 * HR], [HR, 0, ZT + 8]], 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const ring = (cx, cy, r, z, n = 36) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push([cx + r * Math.cos(t), cy + r * Math.sin(t), z]); } return o; };
  const pp = (list) => list.map((q) => P(q[0], q[1], q[2]));
  const H = (list) => poly(hull(pp(list)));
  mk("path", { class: "sil", d: H(ring(0, 0, RB, 0).concat(ring(0, 0, RB, 5), ring(0, 0, RT, ZT))) }, g);
  mk("path", { class: "nf", d: poly(pp(ring(0, 0, HR - 1, ZT + 0.1))) }, g);
  const lid = mk("path", { class: "sil" }, g), top = mk("path", { class: "nf lo" }, g);
  const wheel = mk("path", { class: "nf hi" }, g), spokes = mk("path", { class: "nf hi" }, g);
  const ang = tween(0), wh = tween(0);
  let last = "";
  function draw(a, w) {
    const key = a.toFixed(4) + w.toFixed(4);
    if (key === last) return; last = key;
    const c = Math.cos(a), s = Math.sin(a);
    const W = (u, v, t) => [HX + u * c - t * s, v, ZT + u * s + t * c];
    const disc = (r, t, n = 36) => { const o = []; for (let i = 0; i < n; i++) { const q = (i / n) * Math.PI * 2; o.push(W(HR + r * Math.cos(q), r * Math.sin(q), t)); } return o; };
    lid.setAttribute("d", H(disc(HR, 0).concat(disc(HR, HT))));
    top.setAttribute("d", poly(pp(disc(HR - 2, HT + 0.1))));
    wheel.setAttribute("d", poly(pp(disc(7, HT + 4))));
    let d = "";
    const hub = P(...W(HR, 0, HT + 0.1));
    for (let k = 0; k < 3; k++) {
      const q = w + (k * 2 * Math.PI) / 3, e = P(...W(HR + 7 * Math.cos(q), 7 * Math.sin(q), HT + 4));
      d += "M" + hub[0].toFixed(1) + " " + hub[1].toFixed(1) + "L" + e[0].toFixed(1) + " " + e[1].toFixed(1);
    }
    spokes.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now), tval(wh, now)); return !(tdone(ang, now) && tdone(wh, now)); });
  bag.add(B.unregister);
  const L = P(0, -RB, 10)[0], R = P(0, RB, 10)[0], lo = Math.min(L, R), hi = Math.max(L, R);
  function act(p) {
    const now = performance.now();
    const f = p ? Math.max(0, Math.min(1, (p[0] - lo) / (hi - lo))) : 0;
    tset(wh, f * Math.PI * (1 + spin), now, 0);
    tset(ang, f * 1.95, now, f > 0 ? 200 : 0);
    read.textContent = p ? Math.round(f * 100) + "%" : "rest";
    B.wake();
  }
  act(null);
  bag.add(pointer(stage, { move: act, leave: () => act(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { spin = v; }, destroy: bag.dispose };
}

hairline({
  name: "capsulehatch",
  means: "A space capsule with a round hatch on top: the pointer turns the handwheel and swings the hatch up open on its hinge.",
  rules: [1, 2, 5, 6],
