  name: "hamsterwheel2",
  means: "A pet stroller on four wheels: its folding canopy swings forward over the carriage as the pointer moves to the front.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1],
  tour: [[145, 201], [210, 235], [276, 267], null],
  mount,
