  name: "treatjar",
  means: "A treat dispenser jar: its long lever tips down as the pointer nears the paddle, and a treat slides out of the chute.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1],
  tour: [[200, 200], [230, 150], [255, 121], null],
  mount,
