    sp.t = a ? amt : REST;
    read.textContent = a ? "pour" : "rest";
    B.wake();
  }
  draw(REST); setOn(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setOn(sx > box[0] && sx < box[2] && sy > box[1] && sy < box[3]), leave: () => setOn(false) }));
