samplebag.code:
/**
 * Tote bag: a branded tote standing on a low step, its two handles flopped
 * over at rest. The pointer turns the bag to face it and the handles swing
 * up to stand. The front handle is the bright mark.
 * The slider is how far the bag turns.
 *
 * The pattern: one part turning to face the pointer (officechairs).
 */
const { Cam, facing, fit, hull, open, poly, prism, proj, rings, spring, stepS, clamp, rad, disposer, mk, pointer, put, register, solid } = HL;

const BW = 22, BD = 6, BH = 46, SZ = 6, HR = 10, HH = 22, REST = -28;
const FACES = [[4, 5, 7, 6], [0, 2, 3, 1], [1, 3, 7, 5], [0, 4, 6, 2], [2, 6, 7, 3], [0, 1, 5, 4]];
const area = (q) => { let s = 0; for (let i = 0; i < q.length; i++) { const a = q[i], b = q[(i + 1) % q.length]; s += a[0] * b[1] - b[0] * a[1]; } return s; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[-34, -34, 0], [34, 34, 0], [34, -34, 0], [-34, 34, 0], [0, 0, SZ + BH + HH + 4]], 200, 165);
  const P = proj(C), front = facing(C);
  const SG = Math.sign(area([P(0, 0, 1), P(1, 0, 1), P(1, 1, 1), P(0, 1, 1)]));
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-34, -24, 34, 24, 8, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  const back = mk("path", { class: "nf" }, g);
  const sil = mk("path", { class: "sil" }, g), faces = mk("path", { class: "nf" }, g), logo = mk("path", { class: "nf lo" }, g);
  const fore = mk("path", { class: "nf" }, g);
  const yaw = spring(REST), lift = spring(0);

  function draw() {
    const c = Math.cos(rad(yaw.x)), s = Math.sin(rad(yaw.x));
    const W = (x, y, z) => P(x * c - y * s, x * s + y * c, SZ + z);
    const pts = [];
    for (let i = 0; i < 8; i++) pts.push(W(i & 1 ? BW : -BW, i & 2 ? BD : -BD, i & 4 ? BH : 0));
    sil.setAttribute("d", poly(hull(pts)));
    let fd = "", ld = "";
    FACES.forEach((f, k) => {
      const q = f.map((i) => pts[i]);
      if (area(q) * SG <= 0) return;
      fd += poly(q);
      if (k >= 4) {
        const m = [0, 1].map((j) => q.reduce((a, p) => a + p[j], 0) / 4);
        ld += poly(q.map((p) => [m[0] + (p[0] - m[0]) * 0.45, m[1] + (p[1] - m[1]) * 0.35]));
      }
    });
    faces.setAttribute("d", fd);
    logo.setAttribute("d", ld);
    const handle = (side, phi) => {
      const out = [], sp = Math.sin(rad(phi)), cp = Math.cos(rad(phi));
      for (let i = 0; i <= 16; i++) {
        const a = Math.PI * (i / 16), u = -HR * Math.cos(a), h = HH * Math.sin(a);
        out.push(W(u, side * (BD + h * sp), BH + h * cp));
      }
      return open(out);
    };
    const t = lift.x;
    back.setAttribute("d", handle(-1, 75 - 70 * t));
    fore.setAttribute("d", handle(1, 80 - 72 * t));
  }

  const B = register(stage, (dt) => {
    const a = stepS(yaw, dt), b = stepS(lift, dt);
    draw();
    return a || b;
  });
  bag.add(B.unregister);

  const cx = P(0, 0, 0)[0];
  function aim(p) {
    if (!p) { yaw.t = REST; lift.t = 0; read.textContent = "rest"; }
    else {
      const t = clamp((p[0] - cx) / 110, -1, 1);
      yaw.t = -45 + t * reach; lift.t = 1;
      read.textContent = Math.round(yaw.t) + "°";
    }
    fore.classList.add("hi");
    B.wake();
  }
  aim(null);
  draw();
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "samplebag",
  means: "A branded tote bag on a step: it turns to face the pointer and its flopped handles swing up to stand.",
  rules: [1, 3, 4, 5],
  range: [20, 50, 80],
  tour: [[120, 150], [290, 150], [200, 110], null],
  mount,
});

shelftruck.code:
/**
 * Shelf truck: a two-deck shelf trolley on four casters with a push handle
 * at one end. The pointer on the floor turns the whole truck on its casters
 * to face it, clamped to a quarter turn. At rest it stands square, the push
 * handle bright. The slider is the spring's stiffness.
 */
const { Cam, clamp, fit, hull, poly, proj, seg, unproj, spring, stepS, disposer, mk, pointer, register } = HL;

function boxD(P, T, a, b) {
  const c = [];
  for (const x of [a[0], b[0]]) for (const y of [a[1], b[1]]) for (const z of [a[2], b[2]]) c.push(T([x, y, z]));
  const s = c.map((p) => P(...p));
  let n = 0, best = -1e9;
  c.forEach((p, i) => { const v = p[0] + p[1] + p[2] * 0.8; if (v > best) { best = v; n = i; } });
  return { sil: poly(hull(s)), cr: seg(s[n], s[n ^ 4]) + seg(s[n], s[n ^ 2]) + seg(s[n], s[n ^ 1]), d: c.reduce((m, p) => m + p[0] + p[1] + p[2] * 0.3, 0) / 8 };
}
const PARTS = [];
for (const x of [-17, 17]) for (const y of [-10, 10]) PARTS.push([[x - 2, y - 2, 0], [x + 2, y + 2, 5]]);
PARTS.push([[-20, -12, 5], [20, 12, 8]]);
for (const x of [-18, 18]) for (const y of [-10.5, 10.5]) PARTS.push([[x - 0.9, y - 0.9, 8], [x + 0.9, y + 0.9, 22]]);
PARTS.push([[-20, -12, 22], [20, 12, 24.5]]);
PARTS.push([[-6, -8, 24.5], [8, 6, 33]]);
const HI0 = PARTS.length;
for (const y of [-10.5, 10.5]) PARTS.push([[-22.5, y - 0.9, 8], [-20.7, y + 0.9, 42]]);
PARTS.push([[-22.5, -11.4, 40], [-20.7, 11.4, 42]]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 4.2);
  fit(C, [[-26, -26, 0], [26, 26, 0], [26, -26, 0], [-26, 26, 0], [-26, 0, 42], [0, 26, 42], [26, 0, 42], [0, -26, 42]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const pool = PARTS.map(() => { const sg = mk("g", {}, g); return { g: sg, sil: mk("path", { class: "sil" }, sg), cr: mk("path", { class: "nf lo" }, sg) }; });
  const sp = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;
  function draw(th) {
    if (th === last) return;
    last = th;
    const c = Math.cos(th), s = Math.sin(th);
    const T = ([x, y, z]) => [x * c - y * s, x * s + y * c, z];
    const ds = PARTS.map((p, i) => ({ i, ...boxD(P, T, p[0], p[1]) })).sort((a, b) => a.d - b.d);
    ds.forEach((d, k) => {
      const o = pool[k];
      o.sil.setAttribute("d", d.sil); o.cr.setAttribute("d", d.cr);
      o.sil.classList.toggle("hi", d.i >= HI0);
    });
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function aim(p) {
    if (!p) { sp.t = 0; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    const r = Math.hypot(x, y);
    if (r < 8 || r > 90) return;
    const a = clamp(Math.atan2(y, x), -1.2, 1.2);
    sp.t = a;
    read.textContent = Math.round((a * 180) / Math.PI) + "\u00b0";
    B.wake();
  }
  draw(0); read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "shelftruck",
  means: "A two-deck shelf trolley: it turns on its casters to face the pointer on the floor, push handle trailing behind.",
  rules: [1, 3, 5],
  range: [0.5, 1, 2],
  tour: [[111, 291], [390, 232], [20, 202], null],
  mount,
});

drumpump.code:
/**
 * Drum pump: a steel drum with a hand pump screwed into its bung, a tall
 * tube, a pump head with a spout and a long lever. The pointer on the floor
 * turns the pump round the bung to point its spout at it, and the lever
 * swings down as it does. At rest the spout points ahead, the lever bright.
 */
const { Cam, clamp, fit, hull, poly, open, proj, seg, unproj, spring, stepS, disposer, mk, pointer, register } = HL;
function boxD(P, T, a, b) {
  const c = [];
  for (const x of [a[0], b[0]]) for (const y of [a[1], b[1]]) for (const z of [a[2], b[2]]) c.push(T([x, y, z]));
  const s = c.map((p) => P(...p));
  let n = 0, best = -1e9;
  c.forEach((p, i) => { const v = p[0] + p[1] + p[2] * 0.8; if (v > best) { best = v; n = i; } });
  return { sil: poly(hull(s)), cr: seg(s[n], s[n ^ 4]) + seg(s[n], s[n ^ 2]) + seg(s[n], s[n ^ 1]), d: c.reduce((m, p) => m + p[0] + p[1] + p[2] * 0.3, 0) / 8 };
}
function paint(pool, ds, hiTest) {
  ds.sort((a, b) => a.d - b.d).forEach((d, k) => {
    const o = pool[k];
    o.sil.setAttribute("d", d.sil); o.cr.setAttribute("d", d.cr);
    o.sil.classList.toggle("hi", hiTest(d.i));
  });
}
const mkPool = (g, n) => Array.from({ length: n }, () => { const sg = mk("g", {}, g); return { sil: mk("path", { class: "sil" }, sg), cr: mk("path", { class: "nf lo" }, sg) }; });
const R = 14, DH = 30, BX = 5;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-24, -24, 0], [24, 24, 0], [24, -24, 0], [-24, 24, 0], [BX, 0, 76], [-24, 0, 76], [24, 0, 76]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const drum = mk("g", {}, g), dsil = mk("path", { class: "sil" }, drum), dcr = mk("path", { class: "nf lo" }, drum);
  const ring = (z, a0 = 0, a1 = Math.PI * 2) => Array.from({ length: 33 }, (_, i) => { const a = a0 + ((a1 - a0) * i) / 32; return P(R * Math.cos(a), R * Math.sin(a), z); });
  dsil.setAttribute("d", poly(hull(ring(0).concat(ring(DH)))));
  dcr.setAttribute("d", poly(ring(DH)) + open(ring(10, -Math.PI / 4, (3 * Math.PI) / 4)) + open(ring(20, -Math.PI / 4, (3 * Math.PI) / 4)) + poly(Array.from({ length: 13 }, (_, i) => P(BX + 2.5 * Math.cos(i / 2), 2.5 * Math.sin(i / 2), DH))));
  const pool = mkPool(g, 5);
  const sp = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;
  function draw(th) {
    if (th === last) return;
    last = th;
    const c = Math.cos(th), s = Math.sin(th), down = Math.min(1, Math.abs(th) / 0.8);
    const T = ([x, y, z]) => [BX + x * c - y * s, x * s + y * c, z];
    const la = 0.45 - down * 0.75, lc = Math.cos(la), ls = Math.sin(la);
    const L = ([x, y, z]) => T([-4 + x * lc, y, 64 - x * ls + z]);
    const ds = [
      { i: 0, ...boxD(P, T, [-1.5, -1.5, DH], [1.5, 1.5, 56]) },
      { i: 1, ...boxD(P, T, [-4, -4, 56], [4, 4, 64]) },
      { i: 2, ...boxD(P, T, [4, -1.2, 58], [16, 1.2, 60.4]) },
      { i: 3, ...boxD(P, T, [-5.5, -2, DH], [5.5, 2, DH + 2.5]) },
      { i: 4, ...boxD(P, L, [-24, -1, -1], [0, 1, 1]) },
    ];
    ds.forEach((d) => { d.d += 200; });
    paint(pool, ds, (i) => i === 4);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function aim(p) {
    if (!p) { sp.t = 0; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    const r = Math.hypot(x - BX, y);
    if (r < 6 || r > 90) return;
    const a = clamp(Math.atan2(y, x - BX), -1.6, 1.6);
    sp.t = a;
    read.textContent = Math.round((a * 180) / Math.PI) + "\u00b0";
    B.wake();
  }
  draw(0); read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "drumpump",
  means: "A hand pump on a steel drum: it turns round the bung to aim its spout at the pointer, the lever swinging down.",
  rules: [1, 3, 5],
  range: [0.5, 1, 2],
  tour: [[111, 300], [315, 219], [98, 212], null],
  mount,
});

toteboxes.code:
/**
 * Tote crates: three plastic totes stacked under a lid. The pointer picks a
 * crate by its height in the stack; that crate and every one above it slide
 * out to the side together, staggered outward from the picked one, so the
 * stack splits there. At rest the stack stands square, the lid bright.
 */
const { Cam, clamp, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;
function boxD(P, T, a, b) {
  const c = [];
  for (const x of [a[0], b[0]]) for (const y of [a[1], b[1]]) for (const z of [a[2], b[2]]) c.push(T([x, y, z]));
  const s = c.map((p) => P(...p));
  let n = 0, best = -1e9;
  c.forEach((p, i) => { const v = p[0] + p[1] + p[2] * 0.8; if (v > best) { best = v; n = i; } });
  return { sil: poly(hull(s)), cr: seg(s[n], s[n ^ 4]) + seg(s[n], s[n ^ 2]) + seg(s[n], s[n ^ 1]), d: c.reduce((m, p) => m + p[0] + p[1] + p[2] * 0.3, 0) / 8 };
}
function paint(pool, ds, hiTest) {
  ds.sort((a, b) => a.d - b.d).forEach((d, k) => {
    const o = pool[k];
    o.sil.setAttribute("d", d.sil); o.cr.setAttribute("d", d.cr);
    o.sil.classList.toggle("hi", hiTest(d.i));
  });
}
const mkPool = (g, n) => Array.from({ length: n }, () => { const sg = mk("g", {}, g); return { sil: mk("path", { class: "sil" }, sg), cr: mk("path", { class: "nf lo" }, sg) }; });
const N = 3, H = 11, OUT = 22;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 4.7);
  fit(C, [[-15, -11, 0], [15 + OUT, 11, 0], [-15, 11, 0], [15 + OUT, -11, 0], [-15, -11, N * H + 2], [15 + OUT, 11, N * H + 2]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const pool = mkPool(g, N * 2 + 1);
  const tw = Array.from({ length: N + 1 }, () => tween(0));
  const I = ([x, y, z]) => [x, y, z];
  let act = -2;
  function draw(now) {
    const ds = [];
    for (let k = 0; k <= N; k++) {
      const dx = tval(tw[k], now), T = ([x, y, z]) => [x + dx, y, z], z0 = k * H;
      if (k < N) {
        ds.push({ i: 2 * k, ...boxD(P, T, [-13.5, -9.5, z0], [13.5, 9.5, z0 + H - 2]) });
        ds.push({ i: 2 * k + 1, ...boxD(P, T, [-15, -11, z0 + H - 2], [15, 11, z0 + H]) });
      } else ds.push({ i: 2 * N, ...boxD(P, T, [-15.5, -11.5, z0], [15.5, 11.5, z0 + 2]) });
    }
    paint(pool, ds, (i) => (act < 0 ? i === 2 * N : Math.floor(i / 2) === act));
  }
  const B = register(stage, (_dt, now) => { draw(now); return tw.some((t) => !tdone(t, now)); });
  bag.add(B.unregister);
  const ys = Array.from({ length: N }, (_, k) => P(0, 0, k * H + H / 2));
  const top = P(0, 0, N * H + 4), bot = P(0, 0, -6);
  function hit([sx, sy]) {
    if (sy < top[1] - 20 || sy > bot[1] + 20 || Math.abs(sx - ys[0][0]) > 90) return -1;
    let b = 0;
    ys.forEach((p, k) => { if (Math.abs(p[1] - sy) < Math.abs(ys[b][1] - sy)) b = k; });
    return b;
  }
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    tw.forEach((t, k) => tset(t, a >= 0 && k >= a ? OUT : 0, now, a >= 0 ? Math.abs(k - a) * 45 * stag : 0));
    read.textContent = a < 0 ? "rest" : "crate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "toteboxes",
  means: "Three stacked tote crates under a lid: the crate under the pointer and all above it slide out sideways, splitting the stack.",
  rules: [1, 2, 3, 5],
  range: [0, 1, 2],
  tour: [[169, 188], [169, 150], [169, 84], null],
  mount,
});

gavelblock.code:
/**
 * Ballot scanner: a ballot bin with a scanner head on top and a feed slot
 * across it, a marked ballot standing half out of the slot. The pointer over
 * the scanner feeds the ballot down into the slot; the slider is how far it
 * goes in. At rest the waiting ballot is the bright mark.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 40, X0 = 5, X1 = 31, YB = 11, HR = 32, HIN = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-2, -2, 0], [38, 26, 0], [38, -2, 0], [-2, 26, 0], [X0, YB, TOP + HR], [X1, YB, TOP + HR]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const s = solid(g), [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };
  const H3 = (pts) => poly(hull(pts.map((p) => P(...p))));
  const L3 = (pts) => pts.map((p, k) => (k ? "L" : "M") + P(...p).map((n) => n.toFixed(1)).join(" ")).join("");

  box(0, 0, 36, 24, 3, 1, 0, 30);
  const head = box(-2, -2, 38, 26, 4, 1.2, 30, TOP);
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(X0 - 1, YB - 1, X1 + 1, YB + 2, 1, 3), TOP))
    + L3([[26, 26, 32], [35, 26, 32], [35, 26, 38], [26, 26, 38], [26, 26, 32]])
    + L3([[4, 24, 4], [24, 24, 4], [24, 24, 26], [4, 24, 26], [4, 24, 4]]) + seg(P(20, 24, 15), P(22, 24, 15)) }, head.g);
  const bg = mk("g", {}, g), sil = mk("path", { class: "sil" }, bg), lines = mk("path", { class: "nf lo" }, bg);
  const t = tween(0);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const h = HR - (HR - HIN) * v, zt = TOP + h;
    sil.setAttribute("d", H3([[X0, YB, TOP], [X1, YB, TOP], [X0, YB + 1, TOP], [X1, YB + 1, TOP], [X0, YB, zt], [X1, YB, zt], [X0, YB + 1, zt], [X1, YB + 1, zt]]));
    let d = "";
    for (let k = 0; k < 4; k++) {
      const z = zt - 6 - k * 6;
      if (z > TOP + 1) d += L3([[X0 + 3, YB + 1, z], [X0 + 6, YB + 1, z - 2], [X0 + 10, YB + 1, z + 2]]) + seg(P(X0 + 13, YB + 1, z), P(X1 - 3, YB + 1, z));
    }
    lines.setAttribute("d", d);
  }
  const zone = hull([[-2, -2, 0], [38, 26, 0], [38, -2, 0], [-2, 26, 0], [-2, -2, TOP + HR], [38, 26, TOP], [38, -2, TOP + HR], [-2, 26, TOP]].map((p) => P(...p)));
  const side = (q, k) => { const a = zone[k], b = zone[(k + 1) % zone.length]; return (b[0] - a[0]) * (q[1] - a[1]) - (b[1] - a[1]) * (q[0] - a[0]); };
  function hit(q) { const s = zone.map((_, k) => side(q, k)); return s.every((v) => v >= 0) || s.every((v) => v <= 0); }
  function mark(a) { sil.classList.add("hi"); read.textContent = a ? "cast" : "rest"; }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a ? amt : 0, performance.now(), 0);
    mark(a);
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { tset(t, amt, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

