shopcounter.code:
/**
 * Shop counter: a counter with a lift-up flap and a swing gate under it.
 * The pointer over the counter swings the flap up on its hinge and the gate
 * open. At rest the flap sits cracked open, bright. The slider is the reach.
 */
const { Cam, fit, hull, poly, proj, seg, unproj, tdone, tset, tval, tween, disposer, mk, pointer, register, solid } = HL;

const HX = 34, L = 60, D = 16, H = 30, T = 2.5;
function bx(x0, y0, z0, x1, y1, z1) {
  return [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.7);
  fit(C, [[0, 0, 0], [L, D, 0], [0, D, 0], [L, 0, 0], [HX - 4, 0, H + 30], [HX - 4, D, H + 30], [HX + 1, D + 25, 0], [HX + 1, D + 25, H]], 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const draw = (s, pts) => {
    const q = pts.map((p) => P(...p));
    s.sil.setAttribute("d", poly(hull(q)));
    let k = 0;
    for (let i = 1; i < 4; i++) if (pts[i][0] + pts[i][1] > pts[k][0] + pts[k][1]) k = i;
    s.cr.setAttribute("d", poly(q.slice(4)) + seg(q[k], q[k + 4]));
    s.cr.setAttribute("class", "nf lo");
  };
  mk("path", { class: "nf lo dash", d: poly([P(HX, 0, 0), P(L, 0, 0), P(L, D, 0), P(HX, D, 0)]) }, g);
  const back = solid(g), body = solid(g), top = solid(g), end = solid(g), gate = solid(g), flap = solid(g);
  draw(back, bx(HX, 0, 0, L, 2, H));
  draw(body, bx(0, 0, 0, HX, D, H));
  draw(top, bx(-2, -1, H, HX, D + 1, H + T));
  draw(end, bx(L - 2, 0, 0, L, D, H));
  const t = tween(0.12);

  function pose(o) {
    const a = o * reach * Math.PI / 180, b = o * 1.1 * Math.PI / 2 * Math.min(1, reach / 90);
    const ca = Math.cos(a), sa = Math.sin(a), cb = Math.cos(b), sb = Math.sin(b);
    draw(flap, bx(HX, -1, H, L, D + 1, H + T).map(([x, y, z]) => {
      const dx = x - HX, dz = z - H;
      return [HX + dx * ca - dz * sa, y, H + dx * sa + dz * ca];
    }));
    draw(gate, bx(HX + 1, D - 1.5, 2, L - 3, D, H - 3).map(([x, y, z]) => {
      const dx = x - HX - 1, dy = y - D;
      return [HX + 1 + dx * cb - dy * sb, D + dx * sb + dy * cb, z];
    }));
  }
  let last = NaN;
  const B = register(stage, (_dt, now) => {
    const o = tval(t, now);
    if (o !== last) { last = o; pose(o); }
    return !tdone(t, now);
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -4 && x < L + 4 && y > -4 && y < D + 30 ? 1 : 0;
  }
  let act = -1;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a ? 1 : 0.12, performance.now(), 0);
    flap.sil.classList.toggle("hi", true);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "shopcounter",
  means: "A shop counter: the pointer swings its flap up on the hinge and the gate beneath it open.",
  rules: [1, 3, 5, 6],
  range: [40, 95, 100],
  tour: [[244, 161], [230, 150], [142, 96], null],
  mount,
});

slatwall.code:
/**
 * Slatwall hooks: a slatted wall panel with three hooks, a boxed package
 * hanging on each. The pointer picks a hook by where it is along the wall:
 * that package slides out along its hook, its neighbours a little after it.
 * At rest the packages sit unevenly, the middle one pulled out, bright.
 */
const { Cam, clamp, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, register, solid } = HL;

const N = 3, WX = 66, WZ = 60, PW = 16, PH = 24, PD = 6, HZ = 44, REST = [3, 9, 1], FAV = 1, OUT = 20;
const XS = [5, 25, 45];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[0, 0, 0], [WX, 0, 0], [0, 0, WZ], [WX, 0, WZ], [0, OUT + PD + 4, HZ - PH], [WX, OUT + PD + 4, HZ]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const wall = solid(g);
  wall.sil.setAttribute("d", poly([P(0, -3, 0), P(WX, -3, 0), P(WX, 0, 0), P(WX, 0, WZ), P(0, 0, WZ), P(0, -3, WZ)]));
  let d = "";
  for (let z = 8; z < WZ; z += 9) d += seg(P(1, 0, z), P(WX - 1, 0, z));
  wall.cr.setAttribute("d", d + seg(P(0, 0, 0), P(0, 0, WZ)) + seg(P(0, 0, WZ), P(0, -3, WZ)));
  wall.cr.setAttribute("class", "nf lo");
  const items = XS.map((x, k) => {
    const s = solid(g);
    s.cr.setAttribute("class", "nf lo");
    return { k, x, s, y: tween(REST[k]), last: NaN };
  });
  function draw(it, y) {
    if (y === it.last) return;
    it.last = y;
    const x0 = it.x, x1 = it.x + PW, xm = it.x + PW / 2, z1 = HZ - 2, z0 = z1 - PH;
    const pts = [];
    for (const [x, yy, z] of [[x0, y, z0], [x1, y, z0], [x0, y + PD, z0], [x1, y + PD, z0], [x0, y, z1], [x1, y, z1], [x0, y + PD, z1], [x1, y + PD, z1]]) pts.push(P(x, yy, z));
    it.s.sil.setAttribute("d", poly(hull(pts)));
    it.s.cr.setAttribute("d", seg(P(x0, y + PD, z1), P(x1, y + PD, z1)) + seg(P(x1, y + PD, z0), P(x1, y + PD, z1)) +
      seg(P(xm, y + PD, HZ), P(xm, OUT + PD + 3, HZ)) + seg(P(xm, OUT + PD + 3, HZ), P(xm, OUT + PD + 3, HZ + 3)) +
      poly([P(xm - 2, y + PD, z1 - 2), P(xm + 2, y + PD, z1 - 2), P(xm + 2, y + PD, z1 - 5), P(xm - 2, y + PD, z1 - 5)]));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    items.forEach((it) => { draw(it, tval(it.y, now)); if (!tdone(it.y, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: one row, the package whose rest centre is nearest the pointer's screen x
  const cx = items.map((it) => P(it.x + PW / 2, REST[it.k], HZ - PH / 2)[0]);
  function hit([sx, sy]) {
    if (sy < 20 || sy > 300) return -1;
    let k = -1, best = 1e9;
    cx.forEach((c, i) => { const dd = Math.abs(sx - c); if (dd < best) { best = dd; k = i; } });
    return best < 45 ? k : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      tset(it.y, a < 0 ? REST[k] : k === a ? OUT : clamp(6 - 3 * Math.abs(k - a), 0, 6), now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hook " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

