walkthrough.code:
/**
 * Metal detector: a walk-through arch of two sensor pillars under a
 * crossbeam, with a traveller waiting at its mouth. The pointer over the
 * arch walks the traveller into it, through the sensor field. At rest the
 * traveller stands a step short of the arch, bright. The slider is how far
 * into the arch they walk.
 */
const { Cam, clamp, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, register, solid } = HL;

const W = 40, PW = 6, PD = 12, H = 74, BH = 9, REST = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let goal = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[0, 0, 0], [W, 0, 0], [W, PD, 0], [0, PD, 0], [0, 0, H], [W, PD, H], [14, REST + 8, 0], [26, REST + 8, 0]], 200, 160);
  const P = proj(C), c = Math.cos(C.az), s = Math.sin(C.az);
  const near = (q) => q[0] * s + q[1] * c;
  function blk(el, x0, y0, x1, y1, z0, z1) {
    const pl = [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
    const top = pl.map((q) => P(q[0], q[1], z1)), bot = pl.map((q) => P(q[0], q[1], z0));
    el.sil.setAttribute("d", poly(hull(top.concat(bot))));
    el.cr.setAttribute("d", poly(top) + seg(top[2], bot[2]));
  }
  const g = mk("g", {}, svg);
  // floor mat under the arch
  mk("path", { d: poly([P(-6, -6, 0), P(W + 6, -6, 0), P(W + 6, PD + 6, 0), P(-6, PD + 6, 0)]), class: "nf lo" }, g);
  const left = solid(g);
  blk(left, 0, 0, PW, PD, 0, H - BH);
  // the sensor zones on the inner face of the left pillar
  let z = "";
  for (let k = 1; k < 6; k++) z += seg(P(PW, 2, k * 10), P(PW, PD - 2, k * 10));
  mk("path", { d: z, class: "nf lo" }, g);

  const parts = [[15, 19, 0, 24], [21, 25, 0, 24], [13.5, 26.5, 22, 46], [17, 23, 47.5, 56]].map((p) => ({ p, el: solid(g) }));
  const right = solid(g);
  blk(right, W - PW, 0, W, PD, 0, H - BH);
  const beam = solid(g);
  blk(beam, 0, 0, W, PD, H - BH, H);
  mk("path", { d: poly([P(14, PD, H - 3), P(26, PD, H - 3), P(26, PD, H - 6), P(14, PD, H - 6)]), class: "nf lo" }, g);

  const walk = tween(REST);
  let last = NaN;
  function draw(y) {
    for (const { p, el } of parts) blk(el, p[0], y, p[1], y + (p[2] > 40 ? 5 : 6), p[2], p[3]);
  }
  const B = register(stage, (_dt, now) => {
    const y = tval(walk, now);
    if (y !== last) { draw(y); last = y; }
    return !tdone(walk, now);
  });
  bag.add(B.unregister);

  const restHull = hull([[0, 0, 0], [W, 0, 0], [W, PD, 0], [0, PD, 0], [0, 0, H], [W, 0, H], [W, PD, H], [0, PD, H], [14, REST + 6, 0], [26, REST + 6, 0], [14, REST + 6, 56], [26, REST + 6, 56]].map((q) => P(q[0], q[1], q[2])));
  function inside([x, y]) {
    let o = false;
    for (let i = 0, j = restHull.length - 1; i < restHull.length; j = i++) {
      const [xi, yi] = restHull[i], [xj, yj] = restHull[j];
      if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) o = !o;
    }
    return o;
  }
  let act = null;
  const tgt = () => clamp(REST - goal, 3, REST - 8);
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(walk, on ? tgt() : REST, performance.now(), 0);
    for (const { el } of parts) el.sil.classList.toggle("hi", true);
    read.textContent = on ? "scan" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { goal = v; if (act) { tset(walk, tgt(), performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "walkthrough",
  means: "A walk-through metal detector arch: the pointer walks the waiting traveller into the arch, through the sensor pillars.",
  rules: [1, 3, 5, 6],
  range: [10, 20, 27],
  tour: [[160, 136], [185, 216], [238, 93], null],
  mount,
});

vaultdoor2.code:
/**
 * Gun safe: a tall steel cabinet with a thick door hinged on its left, a
 * three-spoke handle wheel and a dial on the door. The pointer over the safe
 * swings the door open about its hinge, showing the rack of barrels inside.
 * At rest the door stands just ajar, bright. The slider is how far it opens.
 */
const { Cam, circ, clamp, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, register, solid } = HL;

const W = 40, D = 34, H = 66, T = 5, HX = 1, DW = 38, AJAR = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, D, 0], [W, D, H], [0, 0, H], [HX - 4, D + DW, 0], [HX - 4, D + DW, H]], 200, 160);
  const P = proj(C), c = Math.cos(C.az), s = Math.sin(C.az);
  const near = (q) => q[0] * s + q[1] * c;

  // a box from its 4 plan corners and two heights: silhouette, top outline, nearest vertical edge
  function blk(el, pl, z0, z1) {
    const top = pl.map((q) => P(q[0], q[1], z1)), bot = pl.map((q) => P(q[0], q[1], z0));
    el.sil.setAttribute("d", poly(hull(top.concat(bot))));
    let n = 0;
    pl.forEach((q, i) => { if (near(q) > near(pl[n])) n = i; });
    el.cr.setAttribute("d", poly(top) + seg(top[n], bot[n]));
  }

  const g = mk("g", {}, svg);
  const body = solid(g);
  blk(body, [[0, 0], [W, 0], [W, D], [0, D]], 0, H);
  // plinth and the mouth of the cabinet on its front face, with the rack inside
  const F = (x, z) => P(x, D, z);
  mk("path", { d: seg(P(0, D, 4), P(W, D, 4)) + seg(P(W, 1.5, 4), P(W, D, 4)), class: "nf lo" }, g);
  let rack = poly([F(3, 7), F(W - 3, 7), F(W - 3, H - 3), F(3, H - 3)]) + seg(F(3, H - 18), F(W - 3, H - 18));
  for (let i = 0; i < 6; i++) { const x = 8 + i * 4.8; rack += seg(F(x, 8), F(x, H - 22)) + poly(circ(1.1, 10).map((q) => F(x + q.u, H - 22 + q.v * 0.6))); }
  mk("path", { d: rack, class: "nf lo" }, g);

  const door = solid(g);
  const wheel = mk("path", { class: "nf" }, door.g);
  const dial = mk("path", { class: "nf lo" }, door.g);
  const ang = tween(AJAR);
  let last = NaN;
  function draw(a) {
    const r = a * Math.PI / 180, ca = Math.cos(r), sa = Math.sin(r);
    const at = (u, v) => [HX + u * ca - v * sa, D + u * sa + v * ca];
    blk(door, [at(0, 0), at(DW, 0), at(DW, T), at(0, T)], 1, H - 1);
    // the outer face of the door, in the door's own frame
    const O = (u, z) => { const q = at(u, T); return P(q[0], q[1], z); };
    const cu = DW * 0.62, cz = H * 0.52;
    let w = poly(circ(2, 16).map((q) => O(cu + q.u, cz + q.v)));
    for (let k = 0; k < 3; k++) { const t = k * 2.094 + 0.5; w += seg(O(cu, cz), O(cu + 7 * Math.cos(t), cz + 7 * Math.sin(t))); }
    wheel.setAttribute("d", w);
    dial.setAttribute("d", poly(circ(3.4, 20).map((q) => O(cu + q.u, cz + 13 + q.v))) + seg(O(cu, cz + 13), O(cu, cz + 16.4)) + poly([O(5, 4), O(DW - 4, 4), O(DW - 4, H - 4), O(5, H - 4)]));
  }

  const B = register(stage, (_dt, now) => {
    const a = tval(ang, now);
    if (a !== last) { draw(a); last = a; }
    return !tdone(ang, now);
  });
  bag.add(B.unregister);

  // hit against the rest pose: the cabinet's silhouette plus the door's swing, which never move
  const restHull = hull([[0, 0, 0], [W, 0, 0], [W, D, 0], [0, D, 0], [0, 0, H], [W, 0, H], [W, D, H], [0, D, H], [HX, D + 12, 0], [HX, D + 12, H]].map((q) => P(q[0], q[1], q[2])));
  function inside([x, y]) {
    let o = false;
    for (let i = 0, j = restHull.length - 1; i < restHull.length; j = i++) {
      const [xi, yi] = restHull[i], [xj, yj] = restHull[j];
      if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) o = !o;
    }
    return o;
  }
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? clamp(maxA, 20, 110) : AJAR, performance.now(), 0);
    door.sil.classList.toggle("hi", true);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (act) { tset(ang, clamp(v, 20, 110), performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "vaultdoor2",
  means: "A gun safe: the pointer swings its heavy door open on the hinge, showing the rack of barrels inside; at rest it stands ajar.",
  rules: [1, 3, 5, 6],
  range: [20, 70, 110],
  tour: [[197, 103], [150, 180], [234, 205], null],
  mount,
});

reactionwheel.code:
/**
 * Reaction wheel: a heavy flywheel on a short column over its housing. The
 * pointer is where the wheel leans: the flywheel tilts its axis toward it on a
 * spring and its spokes turn round with it. At rest the wheel leans a little,
 * its hub bright. The slider is how far the wheel may lean.
 *
 * The pattern: a continuous aim (a spring on a tilt vector); the hit is on the
 * floor's plane, which never moves.
 */
const { Cam, fit, hull, poly, proj, spring, stepS, disposer, mk, pointer, register, unproj } = HL;

const D = Math.PI / 180, RW = 34, ZW = 26, TW = 7, MAX = 34 * D, REST = [0.16, -0.08];
const frame = (t, p) => { const ct = Math.cos(t), st = Math.sin(t), cp = Math.cos(p), sp = Math.sin(p); return [[ct * cp, ct * sp, -st], [-sp, cp, 0], [st * cp, st * sp, ct]]; };
const at = (o, F, u, v, w) => [0, 1, 2].map((i) => o[i] + u * F[0][i] + v * F[1][i] + w * F[2][i]);
const ID = frame(0, 0);
function ring(P, o, F, r, w, n = 44, a0 = 0) { const out = []; for (let i = 0; i < n; i++) { const a = a0 + (i / n) * Math.PI * 2; out.push(P(...at(o, F, r * Math.cos(a), r * Math.sin(a), w))); } return out; }
const cyl = (P, o, F, r0, w0, r1, w1) => poly(hull(ring(P, o, F, r0, w0).concat(ring(P, o, F, r1, w1))));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lim = MAX * value;
  const C = Cam(45, 0.5, 3.1);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([(RW + 10) * Math.cos(a), (RW + 10) * Math.sin(a), 0], [(RW + 4) * Math.cos(a), (RW + 4) * Math.sin(a), ZW + 26]); }
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const O = [0, 0, 0];
  mk("path", { class: "sil", d: cyl(P, O, ID, 30, 0, 30, 8) }, g);
  mk("path", { class: "nf lo", d: poly(ring(P, O, ID, 28, 8)) }, g);
  mk("path", { class: "sil", d: cyl(P, O, ID, 5, 8, 5, ZW) }, g);
  const wheel = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), spokes = mk("path", { class: "nf" }, g), hub = mk("path", { class: "sil" }, g);
  const tx = spring(REST[0]), ty = spring(REST[1]), sp = spring(0);
  let last = "";

  function draw() {
    const vx = tx.x, vy = ty.x, key = vx.toFixed(4) + vy.toFixed(4) + sp.x.toFixed(4);
    if (key === last) return;
    last = key;
    const t = Math.min(lim, Math.hypot(vx, vy)), F = frame(t, Math.atan2(vy, vx)), c = [0, 0, ZW];
    wheel.setAttribute("d", cyl(P, c, F, RW, 0, RW, TW));
    face.setAttribute("d", poly(ring(P, c, F, RW - 3, TW)));
    let d = "";
    for (let k = 0; k < 5; k++) { const a = sp.x + (k / 5) * Math.PI * 2, p0 = P(...at(c, F, 6 * Math.cos(a), 6 * Math.sin(a), TW)), p1 = P(...at(c, F, (RW - 3) * Math.cos(a), (RW - 3) * Math.sin(a), TW)); d += `M${p0[0].toFixed(1)} ${p0[1].toFixed(1)}L${p1[0].toFixed(1)} ${p1[1].toFixed(1)}`; }
    spokes.setAttribute("d", d);
    hub.setAttribute("d", cyl(P, c, F, 6, TW, 5, TW + 4));
  }

  const B = register(stage, (dt) => { const m = [stepS(tx, dt), stepS(ty, dt), stepS(sp, dt)].some(Boolean); draw(); return m; });
  bag.add(B.unregister);

  function aim(over) {
    if (over) {
      const r = Math.hypot(over[0], over[1]), k = Math.min(1, r / RW) * lim / Math.max(r, 1e-6);
      tx.t = over[0] * k; ty.t = over[1] * k; sp.t = Math.atan2(over[1], over[0]) * 1.5;
      read.textContent = Math.round(Math.min(1, r / RW) * lim / D) + "°";
    } else { tx.t = REST[0]; ty.t = REST[1]; sp.t = 0; read.textContent = "rest"; }
    wheel.classList.toggle("hi", !!over);
    hub.classList.toggle("hi", !over);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); aim(Math.hypot(x, y) > RW + 30 ? null : [x, y]); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { lim = MAX * v; aim(null); }, destroy: bag.dispose };
}

