sampledrill.code:
/**
 * Core drill: a planetary core drill on its landing pad, the drill head riding
 * a mast with the bit beneath it. The pointer is how deep it bores: nearer the
 * mast foot, further the head slides down and the bit sinks into the ground, on
 * a spring. At rest the head is raised, the bit bright. The slider is depth.
 *
 * The pattern: a continuous value (a spring on one height); the hit is on the
 * floor's plane, which never moves.
 */
const { Cam, fit, hull, poly, proj, spring, stepS, disposer, mk, pointer, register, unproj } = HL;

const ZT = 74, DEEP = 40, REST = 4, RH = 15, HH = 16, LB = 26;
const ring = (P, c, r, z, n = 40) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; o.push(P(c[0] + r * Math.cos(a), c[1] + r * Math.sin(a), z)); } return o; };
const cyl = (P, c, r0, z0, r1, z1) => poly(hull(ring(P, c, r0, z0).concat(ring(P, c, r1, z1))));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let deep = DEEP * value;
  const C = Cam(45, 0.5, 2.6);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([36 * Math.cos(a), 36 * Math.sin(a), 0], [20 * Math.cos(a), 20 * Math.sin(a), ZT + HH + 12]); }
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const O = [0, 0], M = [-14, -14];
  mk("path", { class: "sil", d: cyl(P, O, 32, 0, 32, 5) }, g);
  mk("path", { class: "nf lo", d: poly(ring(P, O, 29, 5)) }, g);
  mk("path", { class: "sil", d: cyl(P, M, 3.5, 5, 3.5, ZT + HH + 10) }, g);
  mk("path", { class: "nf lo", d: poly(ring(P, O, 5, 5, 24)) }, g);
  const bit = mk("path", { class: "sil" }, g), flutes = mk("path", { class: "nf lo" }, g), head = mk("path", { class: "sil" }, g), cap = mk("path", { class: "nf lo" }, g), motor = mk("path", { class: "sil" }, g);
  const dz = spring(REST);
  let last = NaN;

  function draw() {
    const d = Math.min(deep, dz.x);
    if (Math.abs(d - last) < 1e-3) return;
    last = d;
    const z0 = ZT - d, zb = Math.max(5, z0 - LB);
    bit.setAttribute("d", cyl(P, O, 2.6, zb, 3.4, z0));
    let f = "";
    for (let z = z0 - 4; z > zb + 1; z -= 5) { const p0 = P(-2.4, 2.4, z), p1 = P(2.4, -2.4, z - 3); f += `M${p0[0].toFixed(1)} ${p0[1].toFixed(1)}L${p1[0].toFixed(1)} ${p1[1].toFixed(1)}`; }
    flutes.setAttribute("d", f);
    head.setAttribute("d", cyl(P, O, RH, z0, RH, z0 + HH));
    cap.setAttribute("d", poly(ring(P, O, RH - 2.5, z0 + HH)));
    motor.setAttribute("d", cyl(P, O, 6, z0 + HH, 5, z0 + HH + 7));
  }

  const B = register(stage, (dt) => { const m = stepS(dz, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(over) {
    if (over) {
      const f = Math.max(0, Math.min(1, 1 - (Math.hypot(over[0], over[1]) - 6) / 40));
      dz.t = REST + f * (deep - REST);
      read.textContent = "d " + Math.round(dz.t);
    } else { dz.t = REST; read.textContent = "rest"; }
    head.classList.toggle("hi", !!over);
    bit.classList.toggle("hi", !over);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); aim(Math.hypot(x, y) > 70 ? null : [x, y]); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { deep = DEEP * v; aim(null); }, destroy: bag.dispose };
}

hairline({
  name: "sampledrill",
  means: "A planetary core drill: the drill head slides down its mast and the bit bores in as the pointer nears.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[200, 278], [230, 250], [200, 197], null],
  mount,
});

moneytray.code:
/**
 * Money counter: a note counting machine with a fan of banknotes standing in its hopper. The pointer picks a note by where it stands and it leans over to be fed; the notes beside it lean less, staggered. At rest one note leans, bright. The slider is the stagger.
 */
const { Cam, circ, rrect, fit, hull, poly, proj, rad, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const box = (x0, y0, z0, x1, y1, z1, r = 2) => { const g = rrect(x0, y0, x1, y1, r, 4), o = []; for (const q of g) o.push([q.u, q.v, z0], [q.u, q.v, z1]); return o; };
const taper = (a, z0, b, z1, r = 3) => { const o = []; for (const q of rrect(...a, r, 4)) o.push([q.u, q.v, z0]); for (const q of rrect(...b, r, 4)) o.push([q.u, q.v, z1]); return o; };
const ell = (cx, cy, cz, rx, ry, rz) => { const o = []; for (let i = 0; i <= 8; i++) { const t = (i / 8) * Math.PI; for (let j = 0; j < 16; j++) { const f = (j / 16) * 2 * Math.PI; o.push([cx + rx * Math.sin(t) * Math.cos(f), cy + ry * Math.sin(t) * Math.sin(f), cz + rz * Math.cos(t)]); } } return o; };
const cyl = (cx, cy, R, z0, z1) => { const o = []; for (const q of circ(R, 16)) o.push([cx + q.u, cy + q.v, z0], [cx + q.u, cy + q.v, z1]); return o; };
const shift = (pts, dx) => pts.map(([x, y, z]) => [x + dx, y, z]);
function turn(pts, ax, h1, h2, a) {
  const c = Math.cos(a), s = Math.sin(a);
  return pts.map(([x, y, z]) => {
    if (ax === "x") { const dy = y - h1, dz = z - h2; return [x, h1 + dy * c - dz * s, h2 + dy * s + dz * c]; }
    const dx = x - h1, dz = z - h2; return [h1 + dx * c + dz * s, y, h2 - dx * s + dz * c];
  });
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const items = [];
  for (let k = 0; k < SPEC.n; k++) items.push({ k, ...SPEC.build(k) });
  const C = Cam(45, 0.5, SPEC.S);
  const ext = [];
  for (const it of items) { for (const p of it.fixed.flat()) ext.push(p); for (const p of it.moving.flat()) ext.push(p); for (const p of turn(it.moving.flat(), it.ax, it.h1, it.h2, rad(SPEC.open))) ext.push(p); }
  for (const p of (SPEC.base || []).flat()) ext.push(p);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const shape = (pts) => poly(hull(pts.map((p) => P(...p))));
  for (const b of SPEC.base || []) mk("path", { d: shape(b), class: "sil" }, g);
  for (const it of items) {
    it.grp = mk("g", {}, g);
    for (const f of it.fixed) mk("path", { d: shape(f), class: "sil" }, it.grp);
    it.paths = it.moving.map((m, i) => mk("path", { class: i === 0 ? "sil" : "lo" }, it.grp));
    it.a = tween(it.k === SPEC.fav ? SPEC.restA : 0);
    it.last = NaN;
    it.mid = P(...it.hit);
  }
  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    it.moving.forEach((m, i) => it.paths[i].setAttribute("d", shape(turn(m, it.ax, it.h1, it.h2, rad(a)))));
  }
  const B = register(stage, (_dt, now) => {
    let mv = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) mv = true; }
    return mv;
  });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < SPEC.hx && Math.abs(items[best].mid[1] - sy) < SPEC.hy ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), t = a < 0 ? (k === SPEC.fav ? SPEC.restA : 0) : d === 0 ? SPEC.open : d === 1 ? SPEC.near : d === 2 ? SPEC.near * 0.4 : 0;
      tset(it.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.paths[0].classList.toggle("hi", k === (a < 0 ? SPEC.fav : a));
    });
    read.textContent = a < 0 ? "rest" : SPEC.label + " " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

const SPEC = {
  n: 7, S: 2.5, fav: 2, restA: 18, open: 42, near: 20, hx: 8, hy: 90, label: "note",
  base: [box(-12, -24, 0, 54, 24, 18, 5), box(-4, -20, 18, 46, 20, 20, 3)],
  build: (k) => {
    const x = k * 7;
    return {
      fixed: [],
      moving: [box(x - 0.6, -17, 20, x + 0.6, 17, 52, 1), box(x - 0.8, -5, 32, x + 0.8, 5, 40, 1)],
      ax: "y", h1: x, h2: 20, hit: [x, 0, 46],
    };
  },
};
hairline({
  name: "moneytray",
  means: "A note counting machine with banknotes in its hopper: the note under the pointer leans over to feed, and its neighbours lean less.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[171, 104], [195, 116], [219, 128], null],
  mount,
});

