  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < SPEC.hx && Math.abs(items[best].mid[1] - sy) < SPEC.hy ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), t = a < 0 ? (k === SPEC.fav ? SPEC.restA : 0) : d === 0 ? SPEC.open : d === 1 ? SPEC.near : d === 2 ? SPEC.near * 0.4 : 0;
      tset(it.a, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.paths[0].classList.toggle("hi", k === (a < 0 ? SPEC.fav : a));
    });
    read.textContent = a < 0 ? "rest" : SPEC.label + " " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

const SPEC = {
  n: 3, S: 2.5, fav: 1, restA: 38, open: 105, near: 30, hx: 24, hy: 70, label: "box",
  build: (k) => {
    const x = k * 30;
    return {
      fixed: [box(x - 11, -26, 0, x + 11, 26, 12, 3), box(x - 4, 26, 4, x + 4, 29, 7, 1)],
      moving: [box(x - 11.5, -26.5, 12, x + 11.5, 26.5, 15, 3), box(x - 3, 18, 15, x + 3, 21, 16.5, 1)],
      ax: "x", h1: -26.5, h2: 12, hit: [x, 0, 12],
    };
  },
};
hairline({
  name: "safedeposit",
  means: "Three long safe deposit boxes: the lid under the pointer swings open on its hinge, and the boxes beside it crack open.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[131, 182], [184, 209], [237, 236], null],
  mount,
});

netpost.code:
/**
 * Net post: two volleyball posts on base plates with a meshed net strung
 * between them, a bright tape along its top. The pointer slides the net up
 * and down the posts, higher the nearer the pointer to the top of the frame.
 * At rest it hangs at a middle height. The slider is the net's travel.
 *
 * The pattern: one part sliding along a fixed guide.
 */
const { Cam, fit, hull, poly, proj, clamp, lerp, spring, stepS, disposer, mk, pointer, register, seg, circ, ringAt } = HL;

const X = 110, PH = 100, NH = 26, REST = 0.5;
function cyl(P, x, y, z0, z1, r) {
  const c = circ(r, 24).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
  return poly(hull(ringAt(P, c, z0).concat(ringAt(P, c, z1))));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-12, -12, 0], [X + 12, 12, 0], [X + 12, -12, 0], [-12, 12, 0], [0, 0, PH + 4], [X, 0, PH + 4]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  for (const x of [0, X]) mk("path", { class: "sil", d: poly(hull(ringAt(P, circ(10, 24).map((q) => ({ ...q, u: q.u + x })), 0).concat(ringAt(P, circ(10, 24).map((q) => ({ ...q, u: q.u + x })), 3)))) }, g);
  mk("path", { class: "sil", d: cyl(P, 0, 0, 3, PH, 3) }, g);
  const mesh = mk("path", { class: "nf lo" }, g), frame = mk("path", { class: "nf sil" }, g), tape = mk("path", { class: "sil hi" }, g);
  mk("path", { class: "sil", d: cyl(P, X, 0, 3, PH, 3) }, g);
  const z = spring(0);
  let last = NaN;
  const lo = () => 12, hi = () => 12 + travel;

  function draw(h) {
    if (h === last) return;
    last = h;
    let d = "";
    for (let x = 3 + 6; x < X - 3; x += 6) d += seg(P(x, 0, h), P(x, 0, h + NH));
    for (let k = 1; k < 5; k++) d += seg(P(3, 0, h + (k * NH) / 5), P(X - 3, 0, h + (k * NH) / 5));
    mesh.setAttribute("d", d);
    frame.setAttribute("d", poly([P(3, 0, h), P(X - 3, 0, h), P(X - 3, 0, h + NH), P(3, 0, h + NH)]));
    tape.setAttribute("d", poly([P(3, 0, h + NH), P(X - 3, 0, h + NH), P(X - 3, 0, h + NH + 4), P(3, 0, h + NH + 4)]));
  }

  const B = register(stage, (dt) => { const m = stepS(z, dt); draw(z.x); return m; });
  bag.add(B.unregister);

  function aim(t, rest) {
    z.t = lerp(lo(), hi(), t);
    read.textContent = rest ? "rest" : Math.round(t * 100) + "%";
    B.wake();
  }
  z.x = lerp(lo(), hi(), REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([, sy]) => aim(clamp((260 - sy) / 200, 0, 1)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = v; aim(REST, true); }, destroy: bag.dispose };
}

hairline({
  name: "netpost",
  means: "Two volleyball posts with a net between them: the net slides up and down the posts with the pointer's height.",
  rules: [1, 3, 5],
  range: [40, 55, 66],
  tour: [[200, 79], [200, 172], [200, 104], null],
  mount,
});

golfcart2.code:
/**
 * Golf bag: a stand bag with clubs in its mouth and two stand legs folded
 * along its back. The pointer swings the legs open, and the bag tilts back
 * onto them. At rest the legs stand half open, bright. The slider is the
 * widest the legs open.
 *
 * The pattern: one part swinging open to the pointer.
 */
const { Cam, fit, hull, poly, proj, clamp, lerp, rad, spring, stepS, disposer, mk, pointer, register } = HL;

const H = 86, R = 12, REST = 0.5;
const ry = (p, a) => [p[0] * Math.cos(a) + p[2] * Math.sin(a), p[1], -p[0] * Math.sin(a) + p[2] * Math.cos(a)];
function cyl(P, a, b, r, n = 20) {
  const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], L = Math.hypot(...d), w = d.map((v) => v / L);
  const t = Math.abs(w[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  let u = [w[1] * t[2] - w[2] * t[1], w[2] * t[0] - w[0] * t[2], w[0] * t[1] - w[1] * t[0]];
  const ul = Math.hypot(...u); u = u.map((v) => v / ul);
  const v = [w[1] * u[2] - w[2] * u[1], w[2] * u[0] - w[0] * u[2], w[0] * u[1] - w[1] * u[0]];
  const pts = [];
  for (let i = 0; i < n; i++) {
    const c = Math.cos((i / n) * 2 * Math.PI) * r, s = Math.sin((i / n) * 2 * Math.PI) * r;
    for (const e of [a, b]) pts.push(P(e[0] + u[0] * c + v[0] * s, e[1] + u[1] * c + v[1] * s, e[2] + u[2] * c + v[2] * s));
  }
  return poly(hull(pts));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-70, -30, 0], [20, 30, 0], [-70, 30, 0], [20, -30, 0], [0, 0, H + 26], [-40, 0, H + 20]], 200, 162);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const names = ["legL", "legR", "body", "club1", "club2", "club3", "pocket", "collar"];
  const el = {};
  for (const k of names) el[k] = mk("path", { class: k.startsWith("leg") ? "sil hi" : "sil" }, g);
  const open = spring(REST);
  let last = NaN;

  function draw(s) {
    if (s === last) return;
    last = s;
    const tilt = -rad(max) * 0.45 * s, B = (x, y, z) => ry([x, y, z], tilt);
    const top = B(0, 0, H), hinge = B(-R, 0, H - 18);
    const items = [];
    for (const sy of [-1, 1]) {
      const foot = [-R - 4 - 60 * Math.sin(rad(max) * s), sy * (5 + 16 * s), 0];
      items.push([sy < 0 ? "legL" : "legR", cyl(P, [hinge[0], hinge[1] + sy * 5, hinge[2]], foot, 1.6, 10), [foot[0] + 30, foot[1]]]);
    }
    items.push(["body", cyl(P, B(0, 0, 2), top, R, 32), [0, 0]]);
    items.push(["pocket", cyl(P, B(R - 1, 0, 22), B(R - 1, 0, 50), 6, 16), [R + 2, 0.5]]);
    items.push(["collar", cyl(P, B(0, 0, H - 3), B(0, 0, H + 2), R + 2, 32), [0.1, 0.1]]);
    [[-4, -4, 22], [3, 3, 18], [-3, 5, 26]].forEach(([x, y, h], i) => {
      items.push(["club" + (i + 1), cyl(P, B(x, y, H), B(x * 1.4 - 6, y * 1.4, H + h), 4.5, 12), [x - 2, y + 0.2]]);
    });
    items.sort((p, q) => p[2][0] + p[2][1] - (q[2][0] + q[2][1]));
    for (const [k, path] of items) { el[k].setAttribute("d", path); g.appendChild(el[k]); }
  }

  const Bk = register(stage, (dt) => { const m = stepS(open, dt); draw(open.x); return m; });
  bag.add(Bk.unregister);

  function aim(t, rest) {
    open.t = t;
    read.textContent = rest ? "rest" : Math.round(t * max) + "°";
    Bk.wake();
  }
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(clamp((340 - sx) / 260, 0, 1)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; last = NaN; aim(REST, true); }, destroy: bag.dispose };
}

hairline({
  name: "golfcart2",
  means: "A golf stand bag: its two legs swing open toward the pointer and the bag tilts back onto them.",
  rules: [1, 3, 5],
  range: [20, 35, 50],
  tour: [[300, 150], [100, 150], [172, 172], null],
  mount,
});

letterscale.code:
/**
 * Letter scale: a desk letter scale, a base with a round dial on its front,
 * a post, and a tray with a letter on it. The pointer over the scale weighs
 * the letter: the tray tilts and sinks, the needle swings round the dial.
 * At rest the letter lies on the tray, bright. The slider is the weight.
 *
 * The pattern: one sprung part (tilt and sink); the hit is a fixed plane through the scale.
 */
const { Cam, fit, hull, open, poly, proj, unproj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

// a box as its eight corners (x outer, y, z inner), and a turn about an x-parallel axis through (y, z)
function box(a, b) { const o = []; for (const x of [a[0], b[0]]) for (const y of [a[1], b[1]]) for (const z of [a[2], b[2]]) o.push([x, y, z]); return o; }
const rx = (c, a) => ([x, y, z]) => { const s = Math.sin(a), k = Math.cos(a), dy = y - c[0], dz = z - c[1]; return [x, c[0] + dy * k - dz * s, c[1] + dy * s + dz * k]; };
const TOP = [1, 3, 7, 5], FRONT = [2, 3, 7, 6];
function part(g, cls) { const grp = mk("g", {}, g); return { sil: mk("path", { class: "sil" + (cls ? " " + cls : "") }, grp), det: mk("path", { class: "nf lo" }, grp) }; }
function show(P, p, pts, faces, extra) { p.sil.setAttribute("d", poly(hull(pts.map((q) => P(...q))))); p.det.setAttribute("d", faces.map((f) => poly(f.map((i) => P(...pts[i])))).join("") + (extra || "")); }

const L = 44, WORD = "weigh";
const EXT = [[-6, -6, 0], [L + 6, -6, 0], [-6, 40, 0], [L + 6, 40, 0], [-6, -6, 34], [L + 6, 40, 34]];
const HIT = [-8, L + 8, -8, 42, 20];
const tray = box([-6, -4, 26], [L + 6, 38, 28]), letter = box([4, 4, 28], [L - 4, 28, 29]);
const ring = (r, a0, n) => { const o = []; for (let i = 0; i <= n; i++) { const a = a0 + (i / n) * Math.PI * 2; o.push([L / 2 + r * Math.cos(a), 34, 10 + r * Math.sin(a)]); } return o; };

function build(g, P) {
  const post = part(g), base = part(g), tr = part(g), let_ = part(g, "hi"), needle = mk("path", { class: "nf hi" }, g);
  show(P, post, box([L / 2 - 3, 14, 12], [L / 2 + 3, 20, 27]), [FRONT]);
  show(P, base, box([0, 0, 0], [L, 34, 14]), [TOP], open(ring(8, 0, 24).map((p) => P(...p))));
  return (w) => {
    const sink = w * 0.12, f = (p) => rx([17, 27], w * 0.004)([p[0], p[1], p[2] - sink]);
    show(P, tr, tray.map(f), [TOP]);
    show(P, let_, letter.map(f), [TOP], seg2(P, letter.map(f)));
    const a = Math.PI / 2 - w * 0.05;
    needle.setAttribute("d", open([[L / 2, 34, 10], [L / 2 + 7 * Math.cos(a), 34, 10 + 7 * Math.sin(a)]].map((p) => P(...p))));
  };
}
const seg2 = (P, b) => open([b[1], [(b[3][0] + b[7][0]) / 2, (b[3][1] + b[7][1]) / 2 - 10, b[3][2]], b[5]].map((p) => P(...p)));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value, last = NaN;
  const C = Cam(45, 0.5, 3.6);
  fit(C, EXT, 200, 168);
  const P = proj(C), g = mk("g", {}, svg);
  const draw = build(g, P);
  const t = tween(0);
  const B = register(stage, (_dt, now) => {
    const v = tval(t, now) * amt;
    if (v !== last) { last = v; draw(v); }
    return !tdone(t, now);
  });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, HIT[4]);
    return x > HIT[0] && x < HIT[1] && y > HIT[2] && y < HIT[3] ? 1 : 0;
  }
  let act = -1;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a, performance.now(), 0);
    read.textContent = a ? WORD : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "letterscale",
  means: "A desk letter scale: the pointer weighs the letter, the tray tilts and sinks and the needle swings round its dial.",
  rules: [1, 3, 5],
  range: [20, 50, 60],
  tour: [[203, 129], [220, 150], [185, 110], null],
  mount,
});

inkpad.code:
/**
 * Ink pad: a flat stamp pad tin, a shallow base holding the inked pad and a
 * lid hinged along the back. The pointer over the tin swings the lid open
 * on its hinge to show the pad. At rest the tin is shut, its lid bright. The
 * slider is how far the lid swings.
 *
 * The pattern: one hinged part (swing); the hit is a fixed plane through the tin.
 */
const { Cam, fit, hull, open, poly, proj, unproj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

// a box as its eight corners (x outer, y, z inner), and a turn about an x-parallel axis through (y, z)
function box(a, b) { const o = []; for (const x of [a[0], b[0]]) for (const y of [a[1], b[1]]) for (const z of [a[2], b[2]]) o.push([x, y, z]); return o; }
const rx = (c, a) => ([x, y, z]) => { const s = Math.sin(a), k = Math.cos(a), dy = y - c[0], dz = z - c[1]; return [x, c[0] + dy * k - dz * s, c[1] + dy * s + dz * k]; };
const TOP = [1, 3, 7, 5], FRONT = [2, 3, 7, 6];
function part(g, cls) { const grp = mk("g", {}, g); return { sil: mk("path", { class: "sil" + (cls ? " " + cls : "") }, grp), det: mk("path", { class: "nf lo" }, grp) }; }
function show(P, p, pts, faces, extra) { p.sil.setAttribute("d", poly(hull(pts.map((q) => P(...q))))); p.det.setAttribute("d", faces.map((f) => poly(f.map((i) => P(...pts[i])))).join("") + (extra || "")); }

const L = 56, D = 38, PIV = [0, 9], WORD = "open";
const EXT = [[0, 0, 0], [L, 0, 0], [0, D, 0], [L, D, 0], [0, -20, 46], [L, -20, 46]];
const HIT = [-4, L + 4, -8, D + 4, 8];
const lid = box([-1, 0, 7], [L + 1, D + 1, 11]);

function build(g, P) {
  const base = part(g), lidp = part(g, "hi");
  const pad = box([4, 4, 5], [L - 4, D - 4, 7]);
  show(P, base, box([0, 1, 0], [L, D, 7]), [TOP, FRONT], poly(TOP.map((i) => P(...pad[i]))));
  return (deg) => {
    const pts = lid.map(rx(PIV, deg * Math.PI / 180));
    show(P, lidp, pts, [TOP, FRONT]);
  };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value, last = NaN;
  const C = Cam(45, 0.5, 3.6);
  fit(C, EXT, 200, 168);
  const P = proj(C), g = mk("g", {}, svg);
  const draw = build(g, P);
  const t = tween(0);
  const B = register(stage, (_dt, now) => {
    const v = tval(t, now) * amt;
    if (v !== last) { last = v; draw(v); }
    return !tdone(t, now);
  });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, HIT[4]);
    return x > HIT[0] && x < HIT[1] && y > HIT[2] && y < HIT[3] ? 1 : 0;
  }
  let act = -1;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a, performance.now(), 0);
    read.textContent = a ? WORD : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "inkpad",
  means: "A stamp pad tin: the pointer swings its lid open on the back hinge to show the inked pad inside.",
  rules: [1, 3, 5],
  range: [60, 100, 115],
  tour: [[172, 219], [190, 200], [150, 230], null],
  mount,
