hurdle.code:
/**
 * Track hurdle: two L feet on the track, two uprights and a top bar. The
 * pointer clips the bar: the whole frame tips forward on its feet, further
 * the further right the pointer sits. At rest it leans a little, bar bright.
 * The slider is how far it can tip.
 */
const { Cam, fit, hull, poly, proj, clamp, lerp, rad, spring, stepS, disposer, mk, pointer, register } = HL;

const W = 100, H = 54, FZ = 3, REST = 8;
const corners = (x0, y0, z0, x1, y1, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x, y, z]); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -40, 0], [W + 4, 40, 0], [-4, -40, H + 6], [W + 4, 40, H + 6]], 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const track = mk("path", { class: "dash nf" }, g);
  track.setAttribute("d", poly([P(-30, -44, 0), P(W + 30, -44, 0), P(W + 30, 44, 0), P(-30, 44, 0)]));
  const feet = [0, W].map(() => mk("path", { class: "sil" }, g));
  const posts = [0, W].map(() => mk("path", { class: "sil" }, g));
  const bar = mk("path", { class: "sil hi" }, g);
  const bline = mk("path", { class: "nf lo" }, g);
  for (const [k, x] of [0, W].entries()) feet[k].setAttribute("d", poly(hull(corners(x - 3, -30, 0, x + 3, 4, FZ).map((p) => P(...p)))));
  const tip = spring(REST);
  // tip about the line y = 0, z = FZ: the frame falls toward +y (down-left on screen)
  const T = ([x, y, z], a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return [x, y * c + (z - FZ) * s, FZ - y * s + (z - FZ) * c]; };
  const hp = (pts, a) => poly(hull(pts.map((p) => P(...T(p, a)))));
  let last = NaN;
  function draw(a) {
    if (a === last) return; last = a;
    for (const [k, x] of [0, W].entries()) posts[k].setAttribute("d", hp(corners(x - 2.5, -2.5, FZ, x + 2.5, 2.5, H - 2), a));
    bar.setAttribute("d", hp(corners(-6, -1.5, H - 12, W + 6, 1.5, H), a));
    const m = [[-6, 1.5, H - 6], [W + 6, 1.5, H - 6]].map((p) => P(...T(p, a)));
    bline.setAttribute("d", "M" + m[0].join(",") + "L" + m[1].join(","));
  }
  const B = register(stage, (dt) => { const mv = stepS(tip, dt); draw(tip.x); return mv; });
  bag.add(B.unregister);
  const L = P(-6, 0, 0)[0], R = P(W + 6, 0, 0)[0], top = P(0, -40, H + 6)[1], bot = P(W, 40, 0)[1];
  function move([sx, sy]) {
    if (sx < L - 20 || sx > R + 20 || sy < top - 20 || sy > bot + 20) return leave();
    const t = clamp((sx - L) / (R - L), 0, 1);
    tip.t = lerp(20, 20 + 60 * reach, t);
    read.textContent = Math.round(tip.t) + "°";
    B.wake();
  }
  function leave() { tip.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "hurdle",
  means: "A track hurdle on its feet: the pointer clips the bar and the frame tips forward, further toward the right.",
  rules: [1, 3, 5],
  range: [0.4, 1, 1],
  tour: [[129, 91], [200, 126], [271, 162], null],
  mount,
});

bowlingball.code:
/**
 * Bowling return: a hood at the head of two rails, three balls resting on
 * the rails against it. The pointer rolls the balls down the rack, the one
 * nearest the hood first, spreading out further the further right it sits.
 * At rest the front ball is bright. The slider is how far they roll.
 */
const { Cam, fit, hull, poly, proj, rings, prism, facing, put, solid, clamp, lerp, spring, stepS, disposer, mk, pointer, register } = HL;

const RL = 180, BR = 14, RZ = 10, HX = 36;
const corners = (x0, y0, z0, x1, y1, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x, y, z]); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[0, -22, 0], [RL, 22, 0], [0, -22, 46], [RL, 22, 46]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [hr, hi] = rings(0, -22, HX, 22, 8, 2);
  put(solid(g), prism(P, front, hr, hi, 0, 44));
  mk("path", { class: "nf lo", d: poly([P(HX, -14, 30), P(HX, 14, 30), P(HX, 14, 14), P(HX, -14, 14)]) }, g);
  for (const y of [-7, 7]) mk("path", { class: "sil", d: poly(hull(corners(HX, y - 1.5, 0, RL, y + 1.5, RZ).map((p) => P(...p)))) }, g);
  const rests = [HX + BR, HX + 3 * BR, HX + 5 * BR];
  const balls = rests.map((x, i) => ({ x0: x, s: spring(x), el: mk("ellipse", { class: "sil" + (i === 2 ? " hi" : ""), rx: BR * C.S || 0, ry: 0 }, g), holes: mk("path", { class: "nf lo" }, g) }));
  const r = Math.hypot(P(0, 0, BR)[0] - P(0, 0, 0)[0], P(0, 0, BR)[1] - P(0, 0, 0)[1]);
  for (const b of balls) { b.el.setAttribute("rx", r.toFixed(2)); b.el.setAttribute("ry", r.toFixed(2)); }
  function draw() {
    for (const b of balls) {
      const c = P(b.s.x, 0, RZ + BR * 0.6);
      b.el.setAttribute("cx", c[0].toFixed(2)); b.el.setAttribute("cy", c[1].toFixed(2));
      const ang = (b.s.x - b.x0) / BR;
      const h = [0, 1, 2].map((k) => { const t = ang + k * 0.5; return [c[0] + Math.cos(t) * r * 0.45, c[1] - r * 0.35 + Math.sin(t) * r * 0.2]; });
      b.holes.setAttribute("d", h.map(([x, y]) => `M${(x - 1.6).toFixed(2)},${y.toFixed(2)}a1.6,1.6 0 1,0 3.2,0a1.6,1.6 0 1,0 -3.2,0`).join(""));
    }
  }
  const B = register(stage, (dt) => { let mv = false; for (const b of balls) if (stepS(b.s, dt)) mv = true; draw(); return mv; });
  bag.add(B.unregister);
  const L = P(0, 0, 0)[0], R = P(RL, 0, 0)[0], top = P(0, -22, 50)[1], bot = P(RL, 22, 0)[1];
  function move([sx, sy]) {
    if (sx < L - 20 || sx > R + 20 || sy < top - 20 || sy > bot + 20) return leave();
    const t = clamp((sx - L) / (R - L), 0, 1);
    balls.forEach((b, i) => { b.s.t = b.x0 + t * reach * (RL - BR - rests[2]) * (0.4 + 0.3 * i); });
    read.textContent = Math.round(t * 100) + "%";
    B.wake();
  }
  function leave() { balls.forEach((b) => { b.s.t = b.x0; }); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "bowlingball",
  means: "A bowling ball return: three balls rest against the hood, and the pointer rolls them apart down the rails.",
  rules: [1, 3, 5],
  range: [0.4, 1, 1],
  tour: [[82, 130], [200, 189], [318, 248], null],
  mount,
});

jewelbox.code:
/** Jewelry box: the lid swings open on its back hinge and the ballerina rises out, turning. */
const { Cam, circ, fit, hull, poly, open, proj, rrect, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;
const R3 = (ring, z) => ring.map((q) => [q.u, q.v, z]);
const box = (x0, y0, x1, y1, r, z0, z1, b = 2) => { const a = rrect(x0, y0, x1, y1, r, 4); return { pts: R3(a, z0).concat(R3(a, z1)), cr: R3(rrect(x0 + b, y0 + b, x1 - b, y1 - b, Math.max(r - b, 0.5), 4), z1 - 0.5) }; };
const disc = (cx, cy, R, n = 36) => circ(R, n).map((q) => ({ u: q.u + cx, v: q.v + cy }));
const cyl = (cx, cy, R, z0, z1, b = 2) => ({ pts: R3(disc(cx, cy, R), z0).concat(R3(disc(cx, cy, R), z1)), cr: b ? R3(disc(cx, cy, R - b), z1 - 0.5) : null });
const part = (parent) => { const g = mk("g", {}, parent); return { g, s: mk("path", { class: "sil" }, g), c: mk("path", { class: "nf lo" }, g) }; };
const rotX = (yh, zh, a) => ([x, y, z]) => [x, yh + (y - yh) * Math.cos(a) - (z - zh) * Math.sin(a), zh + (y - yh) * Math.sin(a) + (z - zh) * Math.cos(a)];
const shift = (dx, dy, dz) => ([x, y, z]) => [x + dx, y + dy, z + dz];

function mount({ stage, svg, read }) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [70, 46, 0], [0, 0, 70], [70, 46, 70]], 200, 166);
  const P = proj(C), pr = (f) => (p) => P(...f(p)), id = (p) => p;
  const draw = (el, sh, f) => { el.s.setAttribute("d", poly(hull(sh.pts.map(pr(f))))); if (sh.cr) el.c.setAttribute("d", poly(sh.cr.map(pr(f)))); };
  const back = P(35, 0, 0)[1] < P(35, 46, 0)[1] ? 0 : 46, sgn = back ? 1 : -1;
  const g = mk("g", {}, svg), lid = part(g), body = part(g), dancer = mk("g", {}, g);
  draw(body, box(0, 0, 70, 46, 6, 0, 24, 3), id);
  const post = part(dancer), tutu = part(dancer), torso = part(dancer), head = part(dancer), arms = mk("path", { class: "nf" }, dancer);
  const lidSh = box(0, 0, 70, 46, 6, 24, 31);
  const t = tween(0), REST = 0.2; let last = NaN;
  function render(v) {
    const a = -sgn * v * 1.9;
    draw(lid, lidSh, rotX(back, 24, a));
    if (a * -sgn > 1.0) g.insertBefore(lid.g, body.g); else g.append(lid.g);
    const h = 26 * v, up = shift(0, 0, h), sp = v * Math.PI * 1.5;
    draw(post, cyl(35, 23, 1.2, 22, 18 + h, 0), id);
    draw(tutu, cyl(35, 23, 9, 17 + h, 19.5 + h, 0), id);
    draw(torso, cyl(35, 23, 2.4, 19.5 + h, 30 + h, 0), id);
    draw(head, cyl(35, 23, 2.8, 31 + h, 36 + h, 0), id);
    arms.setAttribute("d", open([P(35 + 8 * Math.cos(sp), 23 + 8 * Math.sin(sp), 31 + h), P(35, 23, 28 + h), P(35 - 8 * Math.cos(sp), 23 - 8 * Math.sin(sp), 31 + h)]));
  }
  const mark = (a) => { lid.s.classList.toggle("hi", a < 0); tutu.s.classList.toggle("hi", a >= 0); };
  const mid = P(35, 23, 20), HW = 120, HH = 100;
  const B = register(stage, (_dt, now) => { const v = tval(t, now); if (v !== last) { last = v; render(v); } return !tdone(t, now); });
  bag.add(B.unregister);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a < 0 ? REST : 1, performance.now(), 0);
    mark(a);
    read.textContent = a < 0 ? "rest" : "open";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.abs(sx - mid[0]) < HW && Math.abs(sy - mid[1]) < HH ? 1 : -1), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: () => {}, destroy: bag.dispose };
}

hairline({
  name: "jewelbox",
  means: "A jewelry box: the lid swings back on its hinge and the little ballerina rises from inside, turning her arms.",
  rules: [1, 4, 5, 6],
  range: [0, 1, 1],
  tour: [[200, 192], [132, 215], [268, 283], null],
  mount,
});

hatbox.code:
/** Hat box: a round box whose lid tips back on its hinge as the hat inside rises. */
const { Cam, circ, fit, hull, poly, open, proj, rrect, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;
const R3 = (ring, z) => ring.map((q) => [q.u, q.v, z]);
const box = (x0, y0, x1, y1, r, z0, z1, b = 2) => { const a = rrect(x0, y0, x1, y1, r, 4); return { pts: R3(a, z0).concat(R3(a, z1)), cr: R3(rrect(x0 + b, y0 + b, x1 - b, y1 - b, Math.max(r - b, 0.5), 4), z1 - 0.5) }; };
const disc = (cx, cy, R, n = 36) => circ(R, n).map((q) => ({ u: q.u + cx, v: q.v + cy }));
const cyl = (cx, cy, R, z0, z1, b = 2) => ({ pts: R3(disc(cx, cy, R), z0).concat(R3(disc(cx, cy, R), z1)), cr: b ? R3(disc(cx, cy, R - b), z1 - 0.5) : null });
const part = (parent) => { const g = mk("g", {}, parent); return { g, s: mk("path", { class: "sil" }, g), c: mk("path", { class: "nf lo" }, g) }; };
const rotX = (yh, zh, a) => ([x, y, z]) => [x, yh + (y - yh) * Math.cos(a) - (z - zh) * Math.sin(a), zh + (y - yh) * Math.sin(a) + (z - zh) * Math.cos(a)];
const shift = (dx, dy, dz) => ([x, y, z]) => [x + dx, y + dy, z + dz];

function mount({ stage, svg, read }) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.42);
  fit(C, [[0, 0, 0], [80, 80, 0], [0, 0, 104], [80, 80, 104]], 200, 166);
  const P = proj(C), pr = (f) => (p) => P(...f(p)), id = (p) => p;
  const draw = (el, sh, f) => { el.s.setAttribute("d", poly(hull(sh.pts.map(pr(f))))); if (sh.cr) el.c.setAttribute("d", poly(sh.cr.map(pr(f)))); };
  const back = P(40, 0, 0)[1] < P(40, 80, 0)[1] ? 4 : 76, sgn = back > 40 ? 1 : -1;
  const g = mk("g", {}, svg), lid = part(g), body = part(g), brim = part(g), crown = part(g);
  draw(body, cyl(40, 40, 34, 0, 38, 3), id);
  const lidSh = cyl(40, 40, 36, 38, 48, 3);
  const t = tween(0), REST = 0.18; let last = NaN;
  function render(v) {
    const a = -sgn * v * 1.5;
    draw(lid, lidSh, rotX(back, 38, a));
    if (a * -sgn > 0.9) g.insertBefore(lid.g, body.g); else g.append(lid.g);
    const h = 20 * v;
    draw(brim, cyl(40, 40, 29, 30 + h, 32 + h, 0), id);
    draw(crown, cyl(40, 40, 15, 32 + h, 47 + h, 2), id);
  }
  const mark = (a) => { lid.s.classList.toggle("hi", a < 0); crown.s.classList.toggle("hi", a >= 0); };
  const mid = P(40, 40, 24), HW = 120, HH = 100;
  const B = register(stage, (_dt, now) => { const v = tval(t, now); if (v !== last) { last = v; render(v); } return !tdone(t, now); });
  bag.add(B.unregister);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a < 0 ? REST : 1, performance.now(), 0);
    mark(a);
    read.textContent = a < 0 ? "rest" : "hat";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.abs(sx - mid[0]) < HW && Math.abs(sy - mid[1]) < HH ? 1 : -1), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: () => {}, destroy: bag.dispose };
}

hairline({
  name: "hatbox",
  means: "A round hat box: its lid tips back on the hinge and the hat inside rises up to be taken out.",
  rules: [1, 4, 5, 6],
  range: [0, 1, 1],
  tour: [[200, 212], [132, 241], [268, 309], null],
  mount,
});

sandpit.code:
/**
 * Sandpit: a square wooden sandpit with a hinged lid along its far edge and a
 * mound of sand inside. The pointer over the pit swings the lid open to show
 * the sand. At rest the lid sits ajar, bright. The slider is how far it opens.
 *
 * The pattern: one part swinging on a hinge.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, ringAt, circ, tdone, tset, tval, tween, clamp, unproj, disposer, mk, pointer, put, register, solid } = HL;

const W = 90, H = 14, T = 4, LT = 3, REST = 14;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-4, -4, 0], [W + 4, W + 4, 0], [W + 4, -4, 0], [-4, W + 4, 0], [0, -6, H + W], [W, -6, H + W]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [or, ir] = rings(0, 0, W, W, 5, 1.6);
  put(solid(g), prism(P, front, or, ir, 0, H));
  // the inside: the inner well and the sand mound
  const [wr] = rings(T, T, W - T, W - T, 3, 1);
  mk("path", { d: poly(ringAt(P, wr, H)), class: "nf" }, g);
  const mound = [];
  for (const [r, z] of [[30, 0], [24, 4], [15, 7], [6, 9]]) mound.push(...ringAt(P, disc(W / 2 + 4, W / 2 + 2, r), H - 3 + z));
  mk("path", { d: poly(hull(mound)), class: "nf lo" }, g);
  for (const [x, y, r] of [[26, 30, 6], [62, 64, 5]]) mk("path", { d: poly(ringAt(P, disc(x, y, r, 16), H)), class: "nf lo" }, g);
  const lid = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), slat = mk("path", { class: "nf lo" }, g);
  const ang = tween(REST);
  let last = NaN;
  // a lid point at (x, along y from the hinge, up from the lid's underside), swung by a degrees about the far edge
  const L = (x, y, z, a) => { const r = (a * Math.PI) / 180, c = Math.cos(r), s = Math.sin(r); return P(x, y * c - z * s, H + y * s + z * c); };
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const x of [-1, W + 1]) for (const y of [-1, W + 1]) for (const z of [0, LT]) pts.push(L(x, y, z, a));
    lid.setAttribute("d", poly(hull(pts)));
    face.setAttribute("d", poly([L(-1, -1, LT, a), L(W + 1, -1, LT, a), L(W + 1, W + 1, LT, a), L(-1, W + 1, LT, a)]));
    let d = "";
    for (const y of [W / 3, (2 * W) / 3]) d += "M" + L(-1, y, LT, a).join(",") + "L" + L(W + 1, y, LT, a).join(",");
    slat.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? maxA : REST, performance.now(), 0);
    lid.classList.add("hi");
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, H); return x > -8 && x < W + 8 && y > -8 && y < W + 8; };
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = clamp(v, 40, 100); if (act) { tset(ang, maxA, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "sandpit",
  means: "A sandpit with a hinged lid: the pointer over the pit swings the lid open on its far edge to show the sand inside.",
  rules: [1, 3, 5, 6],
  range: [40, 95, 100],
  tour: [[200, 230], [170, 220], [230, 240], null],
  mount,
});

kidsmailbox.code:
/**
 * Kidsmailbox: a toy cash register, a chunky body with a key pad, a display
 * flag on its back and a coin drawer below. The pointer over the till slides
 * the drawer out toward the reader, showing its coin trays. At rest the drawer
 * stands open a little, bright. The slider is how far it slides.
 *
 * The pattern: one part sliding on a track.
 */
const { Cam, fit, facing, poly, prism, proj, rings, ringAt, circ, tdone, tset, tval, tween, clamp, unproj, seg, disposer, mk, pointer, put, register, solid } = HL;

const W = 70, D = 56, DZ = 18, BZ = 44, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let out = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [W, D + 40, 0], [W, 0, 0], [0, D + 40, 0], [0, 0, BZ + 26], [W, 0, BZ + 26]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // display flag on the back, then the body and its key pad
  const [fr, fi] = rings(16, 4, 54, 12, 2, 1);
  put(solid(g), prism(P, front, fr, fi, BZ, BZ + 24));
  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, DZ, BZ));
  let keys = "";
  for (let i = 0; i < 4; i++) for (let j = 0; j < 3; j++) {
    const [kr] = rings(10 + i * 14, 22 + j * 11, 18 + i * 14, 29 + j * 11, 2, 0.6);
    keys += poly(ringAt(P, kr, BZ));
  }
  mk("path", { d: keys, class: "nf lo" }, g);
  const [hr, hi2] = rings(-2, -2, W + 2, D + 2, 6, 1);
  const base = solid(g);
  const drawer = mk("g", {}, g), ds = solid(drawer), trays = mk("path", { class: "nf lo" }, drawer), knob = mk("path", { class: "nf" }, drawer);
  const tw = tween(REST);
  let last = NaN;
  function draw(y) {
    if (y === last) return;
    last = y;
    const [dr, di] = rings(3, 2 + y, W - 3, D + y, 4, 1.4);
    put(ds, prism(P, front, dr, di, 2, DZ - 1));
    let d = "";
    for (let i = 0; i < 4; i++) { const [tr] = rings(7 + i * 15.5, D + y - 26, 19 + i * 15.5, D + y - 5, 3, 1); d += poly(ringAt(P, tr, DZ - 1)); }
    trays.setAttribute("d", y > 8 ? d : "");
    knob.setAttribute("d", poly(ringAt(P, circ(3, 16).map((q) => ({ ...q, u: q.u + W / 2, v: q.v + D + y })), 9)) + seg(P(W / 2 - 8, D + y, 13), P(W / 2 + 8, D + y, 13)));
  }
  put(base, prism(P, front, hr, hi2, 0, 2));
  g.prepend(drawer);
  g.prepend(base.g);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  ds.sil.classList.add("hi");
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? out : REST, performance.now(), 0);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, DZ); return x > -10 && x < W + 10 && y > -10 && y < D + 40; };
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { out = clamp(v, 16, 40); if (act) { tset(tw, out, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "kidsmailbox",
  means: "A toy cash register: the pointer over the till slides its coin drawer out toward the reader to show the trays.",
  rules: [1, 3, 5, 6],
  range: [16, 34, 40],
  tour: [[228, 129], [133, 206], [242, 260], null],
  mount,
});

stackrings.code:
/**
 * Stackrings: a ring stacker, five rings of shrinking size on a cone peg on a
 * round base. The pointer picks a ring by its height: it and every ring above
 * it slide up the peg together, staggered from it. At rest the top ring sits
 * raised, bright. The slider is the stagger.
 *
 * The pattern: a stack, picked by rest height.
 */
const { Cam, fit, facing, hull, poly, prism, proj, ringAt, circ, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 5, TH = 8, BZ = 6, LIFT = 22, PH = BZ + N * TH + LIFT + 4;
const RS = [30, 26, 22, 18, 14];
const disc = (r, n = 40) => circ(r, n);
const pr = (z) => 8 - (4 * (z - BZ)) / (PH - BZ);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-36, -36, 0], [36, 36, 0], [36, -36, 0], [-36, 36, 0], [0, 0, PH + LIFT + 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(36), disc(34), 0, BZ));
  const items = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g), s = solid(grp), hole = mk("path", { class: "nf lo" }, grp), peg = mk("path", { class: "sil" }, grp);
    items.push({ k, s, hole, peg, z: tween(0), last: NaN });
  }
  const tipEl = mk("path", { class: "sil" }, g);
  const pegPath = (z0) => poly(hull(ringAt(P, disc(pr(z0), 20), z0).concat(ringAt(P, disc(pr(PH), 20), PH))));
  function drawAll(now) {
    let moving = false;
    for (const it of items) {
      const lift = tval(it.z, now); if (!tdone(it.z, now)) moving = true;
      if (lift === it.last) continue;
      it.last = lift;
      const z0 = BZ + it.k * TH + lift, r = RS[it.k];
      put(it.s, prism(P, front, disc(r), disc(r - 2), z0, z0 + TH));
      it.hole.setAttribute("d", poly(ringAt(P, disc(pr(z0 + TH) + 1.5, 24), z0 + TH)));
      it.peg.setAttribute("d", pegPath(z0 + TH));
    }
    return moving;
  }
  tipEl.setAttribute("d", poly(ringAt(P, disc(pr(PH), 16), PH)));
  const B = register(stage, (_dt, now) => drawAll(now));
  bag.add(B.unregister);

  const mids = items.map((it) => P(0, 0, BZ + it.k * TH + TH / 2));
  function hit([sx, sy]) {
    if (Math.abs(sx - mids[0][0]) > 90) return -1;
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 40 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    items.forEach((it, k) => {
      const z = a < 0 ? (k === N - 1 ? LIFT * 0.6 : 0) : k >= a ? LIFT : 0;
      tset(it.z, z, now, a < 0 ? 0 : (k - a >= 0 ? k - a : 0) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? N - 1 : a));
    });
    read.textContent = a < 0 ? "rest" : "ring " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "stackrings",
  means: "A ring stacker: the ring under the pointer and every ring above it slide up the cone peg together.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 90],
  tour: [[149, 238], [156, 193], [176, 162], null],
  mount,
});

cribmobile.code:
/**
 * Cribmobile: a cot with a mobile on a bent pole, four toys hanging from a
 * cross of arms. The pointer turns the mobile so the bright toy swings round
 * to face it; the other three follow on their arms. At rest the cross sits
 * a little turned. The slider is how far out the arms reach.
 *
 * The pattern: one part turning to face the pointer.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, rrect, circ, tdone, tset, tval, tween, clamp, unproj, seg, disposer, mk, pointer, put, register, solid } = HL;

const HZ = 92, DROP = 22, CW = 56, CD = 36, REST = 30;
const sh = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const SHAPES = [() => circ(8, 32), () => rrect(-6, -6, 6, 6, 2, 3), () => circ(5, 24), () => rrect(-8, -4, 8, 4, 3, 3)];
const HS = [6, 10, 12, 6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-CW, -CD, 0], [CW, CD, 0], [CW, -CD, 0], [-CW, CD, 0], [-CW, -CD, HZ + 12], [44, 44, HZ - 40], [-44, -44, HZ]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-CW, -CD, CW, CD, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, 30));
  let bars = "";
  for (let i = 1; i < 8; i++) { const x = -CW + (i * 2 * CW) / 8; bars += seg(P(x, CD, 6), P(x, CD, 28)); }
  for (let i = 1; i < 5; i++) { const y = -CD + (i * 2 * CD) / 5; bars += seg(P(CW, y, 6), P(CW, y, 28)); }
  mk("path", { d: bars, class: "nf lo" }, g);
  mk("path", { d: seg(P(-CW + 3, -CD + 3, 30), P(-CW + 3, -CD + 3, HZ + 10)) + seg(P(-CW + 3, -CD + 3, HZ + 10), P(0, 0, HZ + 10)) + seg(P(0, 0, HZ + 10), P(0, 0, HZ)), class: "nf" }, g);
  const arms = mk("path", { class: "nf lo" }, g);
  const toys = SHAPES.map((f, k) => { const grp = mk("g", {}, g), str = mk("path", { class: "nf lo" }, grp), s = solid(grp); return { k, ring: f(), grp, str, s }; });
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    let d = "";
    const pos = toys.map((t) => { const r = ((a + t.k * 90) * Math.PI) / 180; return [reach * Math.cos(r), reach * Math.sin(r)]; });
    pos.forEach(([x, y]) => { d += seg(P(0, 0, HZ), P(x, y, HZ)); });
    arms.setAttribute("d", d);
    toys.map((t, k) => ({ t, x: pos[k][0], y: pos[k][1] })).sort((p, q) => p.x + p.y - (q.x + q.y)).forEach(({ t, x, y }) => {
      const z1 = HZ - DROP - t.k * 5, z0 = z1 - HS[t.k];
      t.str.setAttribute("d", seg(P(x, y, HZ), P(x, y, z1)));
      put(t.s, prism(P, front, sh(t.ring, x, y), sh(t.ring, x, y), z0, z1));
      g.appendChild(t.grp);
    });
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  toys[0].s.sil.classList.add("hi");

  let cur = REST;
  function aim(p) {
    let tgt = REST;
    if (p) { const [x, y] = unproj(C, p[0], p[1], 0); tgt = (Math.atan2(y, x) * 180) / Math.PI; }
    let d = ((tgt - cur) % 360 + 540) % 360 - 180;
    if (Math.abs(d) < 1) return;
    cur += d;
    tset(ang, cur, performance.now(), 0);
    read.textContent = p ? Math.round(((cur % 360) + 360) % 360) + "°" : "rest";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 24, 40); last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "cribmobile",
  means: "A cot mobile: the pointer turns the cross of arms so the bright toy swings round to face it, the other toys following.",
  rules: [1, 3, 4, 5],
  range: [24, 34, 40],
  tour: [[119, 286], [281, 286], [79, 266], null],
  mount,
});

guitarcase.code:
/**
 * Guitar case: a hard case lying flat, body and neck, its lid hinged along
 * the far side. At rest the lid sits ajar and the front handle is bright;
 * the pointer over the case swings the lid open. The slider is how far.
 *
 * The pattern: one part that swings on a hinge.
 */
const { Cam, circ, fit, hull, poly, open, proj, rad, tween, tset, tval, tdone, mk, pointer, register, disposer } = HL;

const H = 16, T = 6, HY = 4, REST = 14;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => [q.u + x, q.v + y]);
const BODY = disc(40, 30, 27).concat(disc(96, 30, 21));
const NECK = [[112, 21], [176, 23], [176, 37], [112, 39]];
const rot = (a) => ([x, y, z]) => { const c = Math.cos(a), s = Math.sin(a), dy = y - HY, dz = z - H; return [x, HY + dy * c - dz * s, H + dy * s + dz * c]; };
const slab = (fp, z0, z1) => fp.map(([x, y]) => [x, y, z0]).concat(fp.map(([x, y]) => [x, y, z1]));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 1.9);
  const ext = slab(BODY.concat(NECK), 0, H + T).concat(slab(BODY.concat(NECK), H, H + T).map(rot(rad(110))));
  fit(C, ext, 200, 170);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const shape = (pts) => poly(hull(pts.map((p) => P(...p))));
  const ring = (fp, z, f = (p) => p) => poly(hull(fp.map(([x, y]) => P(...f([x, y, z])))));
  for (const fp of [BODY, NECK]) {
    mk("path", { d: shape(slab(fp, 0, H)), class: "sil" }, g);
    mk("path", { d: ring(fp, H), class: "nf lo" }, g);
  }
  mk("path", { d: shape([[50, 57, 5], [74, 57, 5], [74, 62, 5], [50, 62, 5], [50, 57, 10], [74, 57, 10], [74, 62, 10], [50, 62, 10]]), class: "sil" }, g);
  const handle = g.lastChild;
  const lid = [BODY, NECK].map(() => ({ sil: mk("path", { class: "sil" }, g), face: mk("path", { class: "nf lo" }, g) }));
  const tw = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const f = rot(rad(deg));
    [BODY, NECK].forEach((fp, i) => {
      lid[i].sil.setAttribute("d", shape(slab(fp, H, H + T).map(f)));
      lid[i].face.setAttribute("d", ring(fp, deg < 75 ? H + T : H, f));
    });
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
