claw2.code:
/**
 * Coin pusher: a shelf of coins with a heavy pusher block at the back. The
 * pointer is where the stroke reaches: the pusher slides out toward it and
 * shoves the coins in its way toward the lip. At rest the pusher sits back,
 * bright, the coins scattered unevenly. The slider is how far the stroke goes.
 */
const { Cam, fit, proj, facing, rings, prism, circ, unproj, spring, stepS, clamp, disposer, mk, solid, put, register, pointer } = HL;
const W = 46, D = 34, SH = 6, PH = 18, L = 16, REST = 3;
const COINS = [[-30, 2], [-12, 12], [6, -2], [26, 8], [-22, 24], [14, 25], [34, 26]];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-W, -D, 0], [W, D, 0], [-W, -D, SH + PH], [W, -D, SH + PH], [-W, D, 0], [W, D, 0]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-W, -D, W, D, 4, 1.6), 0, SH));
  const pu = solid(g);
  const coins = COINS.map(([x, y]) => ({ x, y0: y, s: null })).sort((a, b) => a.x + a.y0 - (b.x + b.y0));
  for (const c of coins) c.s = solid(g);
  let reach = 22 * value;
  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-3) return;
    drawn = sp.x;
    const f = -D + L + sp.x;
    put(pu, prism(P, front, ...rings(-W + 3, -D + 2, W - 3, f, 3, 1.4), SH, SH + PH));
    for (const c of coins) {
      const y = clamp(Math.max(c.y0, f + 5.5), -D, D - 4);
      put(c.s, prism(P, front, disc(c.x, y, 5.2), disc(c.x, y, 4.2), SH, SH + 2.2));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function set(over) {
    let near = null;
    if (over) {
      const f = Math.max(over[1], -D + L + REST + reach);
      sp.t = clamp(f + D - L, REST, REST + reach);
      let bd = Infinity;
      for (const c of coins) { const d = Math.abs(c.x - over[0]); if (d < bd) { bd = d; near = c; } }
    } else sp.t = REST;
    pu.sil.classList.toggle("hi", !over);
    for (const c of coins) c.s.sil.classList.toggle("hi", c === near);
    read.textContent = over ? "lane " + (1 + Math.round(clamp((over[0] + W) / (2 * W), 0, 1) * 3)) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], SH); set(Math.abs(x) < W + 8 && Math.abs(y) < D + 8 ? [x, y] : null); },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null); draw();
  return { set: (v) => { reach = 22 * v; }, destroy: bag.dispose };
}

hairline({
  name: "claw2",
  means: "A coin pusher shelf: the pusher block slides out toward the pointer and shoves the coins in its path to the lip.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[215, 136], [170, 160], [250, 190], null],
  mount,
});

gamespinner.code:
/**
 * Game spinner: a square board-game card split in four, with a kite-shaped
 * arrow on a hub. The pointer is the quadrant you call: the arrow turns to
 * point at it and the card tips toward it on its own spring. At rest the
 * arrow points between two quadrants, bright, the card a little tipped.
 */
const { Cam, fit, proj, facing, rings, prism, circ, fillet, poly, seg, unproj, spring, stepS, clamp, disposer, mk, solid, put, register, pointer, flatDot, place } = HL;
const H = 40, T = 3, REST = 0.5;
const KITE = fillet([[-11, 0], [0, -5.5], [36, 0], [0, 5.5]], [2, 2, 1.2, 2], 3);
const ringOf = (pts) => pts.map((p, i) => {
  const a = pts[(i + pts.length - 1) % pts.length], b = pts[(i + 1) % pts.length];
  const tx = b[0] - a[0], ty = b[1] - a[1], l = Math.hypot(tx, ty) || 1;
  return { u: p[0], v: p[1], nu: ty / l, nv: -tx / l };
});
const turn = (pts, a) => { const c = Math.cos(a), s = Math.sin(a); return pts.map(([x, y]) => [x * c - y * s, x * s + y * c]); };
const DOTS = [[20, 20], [-20, 20], [-20, -20], [20, -20]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-H, -H, -8], [H, H, -8], [-H, H, 12], [H, -H, 12], [-H, -H, 14], [H, H, 14]], 200, 166);
  const P0 = proj(C), front = facing(C), g = mk("g", {}, svg);
  const card = solid(g), lines = mk("path", { class: "lo nf" }, g);
  const dots = DOTS.map(() => flatDot(g, C, 1.6, "dot off"));
  const arrow = solid(g), hub = solid(g);
  const a = spring(REST * Math.PI), sx = spring(0.06), sy = spring(-0.04);
  let tip = 0.14 * value, drawn = "";
  function draw() {
    const key = [a.x, sx.x, sy.x].map((v) => v.toFixed(4)).join();
    if (key === drawn) return;
    drawn = key;
    const P = (x, y, z) => P0(x, y, z - x * sx.x - y * sy.x);
    put(card, prism(P, front, ...rings(-H, -H, H, H, 5, 1.6), 0, T));
    lines.setAttribute("d", seg(P(-H + 2, 0, T), P(H - 2, 0, T)) + seg(P(0, -H + 2, T), P(0, H - 2, T)));
    DOTS.forEach(([x, y], i) => place(dots[i], P(x, y, T)));
    const k = turn(KITE, a.x);
    put(arrow, prism(P, front, ringOf(k), ringOf(turn(fillet([[-9.5, 0], [0, -4.2], [33, 0], [0, 4.2]], [2, 2, 1, 2], 3), a.x)), T + 2, T + 4.5));
    put(hub, prism(P, front, circ(3.2, 20), circ(2.2, 20), T, T + 6));
  }
  const B = register(stage, (dt) => { let m = stepS(a, dt); if (stepS(sx, dt)) m = true; if (stepS(sy, dt)) m = true; draw(); return m; });
  bag.add(B.unregister);
  const wrap = (v) => v - Math.PI * 2 * Math.round(v / (Math.PI * 2));
  function set(over) {
    let q = -1;
    if (over) {
      const ang = Math.atan2(over[1], over[0]), r = Math.hypot(over[0], over[1]) || 1;
      a.t = a.t + wrap(ang - a.t);
      const m = clamp(r / H, 0.4, 1) * tip;
      sx.t = (over[0] / r) * m; sy.t = (over[1] / r) * m;
      q = ((Math.floor((ang + Math.PI * 2) / (Math.PI / 2)) % 4) + 4) % 4;
    } else { a.t = a.t + wrap(REST * Math.PI - a.t); sx.t = 0.06; sy.t = -0.04; }
    arrow.sil.classList.toggle("hi", !over);
    dots.forEach((d, i) => d.setAttribute("class", i === q ? "dot" : "dot off"));
    read.textContent = over ? "q " + (q + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], T); set(Math.abs(x) < H + 10 && Math.abs(y) < H + 10 && Math.hypot(x, y) > 4 ? [x, y] : null); },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null); draw();
  return { set: (v) => { tip = 0.14 * v; }, destroy: bag.dispose };
}

hairline({
  name: "gamespinner",
  means: "A board game spinner: the arrow turns to point at the quadrant under the pointer and the card tips toward it.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.5],
  tour: [[200, 205], [140, 165], [262, 162], null],
  mount,
});

bagatelle.code:
/**
 * Bagatelle board: a round-topped board of pins with a plunger lane down one
 * side and a ball. The pointer is where you lean on it: the board tilts toward
 * it and the ball rolls downhill. At rest the board lies a little tipped, the
 * plunger bright.
 */
const { Cam, fit, proj, facing, rings, rrect, prism, circ, unproj, spring, stepS, clamp, disposer, mk, solid, put, register, pointer, flatDot, place } = HL;
const X = 32, Y = 52, T = 3;
const PINS = [[-16, -26], [0, -32], [16, -26], [-8, -12], [8, -12], [-18, 2], [0, 4], [18, 2], [-8, 18], [8, 18]];
const disc = (x, y, r, n = 14) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-X, -Y, -8], [X, Y, -8], [X, -Y, 10], [-X, Y, 10], [-X, -Y, 12], [X, Y, 12]], 200, 166);
  const P0 = proj(C), front = facing(C), g = mk("g", {}, svg);
  const board = solid(g), rail = mk("path", { class: "lo nf" }, g);
  const pins = PINS.map(([x, y]) => ({ x, y, s: null })).sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const p of pins) p.s = solid(g);
  const plunger = solid(g), ball = flatDot(g, C, 2.6, "dot");
  const sx = spring(0.05), sy = spring(0.07);
  let tip = 0.16 * value, drawn = "";
  function draw() {
    const key = sx.x.toFixed(4) + sy.x.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const P = (x, y, z) => P0(x, y, z - x * sx.x - y * sy.x);
    const ring = rrect(-X, -Y, X, Y, 26, 10), inner = rrect(-X + 1.6, -Y + 1.6, X - 1.6, Y - 1.6, 24.4, 10);
    put(board, prism(P, front, ring, inner, 0, T));
    rail.setAttribute("d", "M" + P(X - 8, Y - 3, T) + "L" + P(X - 8, -8, T));
    for (const p of pins) put(p.s, prism(P, front, disc(p.x, p.y, 1.3), null, T, T + 4));
    const py = Y - 24 + clamp(sy.x, -0.2, 0.2) * 40;
    put(plunger, prism(P, front, ...rings(X - 6.5, py - 4, X - 2.5, py + 14, 1.8, 0.6), T + 1, T + 4));
    const bx = clamp(-4 + sx.x * 160, -X + 6, X - 12), by = clamp(10 + sy.x * 220, -Y + 14, Y - 6);
    place(ball, P(bx, by, T + 2.6));
  }
  const B = register(stage, (dt) => { let m = stepS(sx, dt); if (stepS(sy, dt)) m = true; draw(); return m; });
  bag.add(B.unregister);
  function set(over) {
    let near = null;
    if (over) {
      const r = Math.hypot(over[0], over[1]) || 1, m = clamp(r / Y, 0.4, 1) * tip;
      sx.t = (over[0] / r) * m; sy.t = (over[1] / r) * m;
      let bd = Infinity;
      for (const p of pins) { const d = Math.hypot(p.x - over[0], p.y - over[1]); if (d < bd) { bd = d; near = p; } }
    } else { sx.t = 0.05; sy.t = 0.07; }
    plunger.sil.classList.toggle("hi", !over);
    for (const p of pins) p.s.sil.classList.toggle("hi", p === near);
    read.textContent = near ? "pin " + (pins.indexOf(near) + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], T); set(Math.abs(x) < X + 8 && Math.abs(y) < Y + 8 ? [x, y] : null); },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null); draw();
  return { set: (v) => { tip = 0.16 * v; }, destroy: bag.dispose };
}

hairline({
  name: "bagatelle",
  means: "A bagatelle board of pins and a plunger: the board tilts toward the pointer and the ball rolls downhill.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.5],
  tour: [[220, 125], [175, 205], [245, 170], null],
  mount,
});

railswitch.code:
/**
 * Rail switch: a ground lever on its stand beside a stock rail, linked to a
 * switch blade. The pointer throws the lever: across the figure it swings
 * from one side to the other on a spring, and the blade swings with it,
 * closing on the rail. At rest the lever leans back and the blade stands open.
 * The slider is how far the lever throws.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PIV = [0, 34, 22], LEN = 78, REST = -0.8, BL = [-62, -16, 7];

function rot(p, o, ax, a) {
  const c = Math.cos(a), s = Math.sin(a), [x, y, z] = [p[0] - o[0], p[1] - o[1], p[2] - o[2]], [u, v, w] = ax;
  const d = u * x + v * y + w * z;
  return [o[0] + x * c + (v * z - w * y) * s + u * d * (1 - c), o[1] + y * c + (w * x - u * z) * s + v * d * (1 - c), o[2] + z * c + (u * y - v * x) * s + w * d * (1 - c)];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-66, -40, 0], [66, 50, 0], [-50, 34, 90], [50, 34, 90]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const slab = (x0, y0, x1, y1, z0, z1, r, b) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  slab(-14, -44, 14, 46, 0, 6, 3, 1.2);
  slab(-66, -32, 66, -26, 6, 12, 2, 1);
  const blade = solid(g);
  slab(-12, 26, 12, 42, 6, 20, 3, 1.2);
  const lever = solid(g), knob = solid(g);
  lever.sil.classList.add("hi"); knob.sil.classList.add("hi");

  function bar(s, A, B, ra, rb) {
    const d = [B[0] - A[0], B[1] - A[1], B[2] - A[2]], n = Math.hypot(...d), e = d.map((q) => q / n);
    let u = [e[1], -e[0], 0]; if (Math.hypot(...u) < 0.1) u = [1, 0, 0];
    const un = Math.hypot(...u); u = u.map((q) => q / un);
    const v = [u[1] * e[2] - u[2] * e[1], u[2] * e[0] - u[0] * e[2], u[0] * e[1] - u[1] * e[0]];
    const ring = (c, r) => circ(r, 20).map((q) => P(...[0, 1, 2].map((j) => c[j] + r * 0 + q.u * u[j] + q.v * v[j])));
    const rA = ring(A, ra), rB = ring(B, rb);
    s.sil.setAttribute("d", poly(hull(rA.concat(rB))));
    s.cr.setAttribute("d", poly(ring(B, rb * 0.6)));
  }
  function ball(s, c, r) {
    const pts = [];
    for (const q of circ(r, 24)) pts.push(P(c[0] + q.u, c[1] + q.v, c[2]), P(c[0] + q.u, c[1], c[2] + q.v), P(c[0], c[1] + q.u, c[2] + q.v));
    s.sil.setAttribute("d", poly(hull(pts)));
  }

  const t = spring(REST);
  let last = "", over = null;
  function draw() {
    const key = t.x.toFixed(3);
    if (key === last) return;
    last = key;
    const a = rad(32) * t.x, top = rot([PIV[0], PIV[1], PIV[2] + LEN], PIV, [0, 1, 0], a);
    bar(lever, PIV, top, 4, 3.4);
    ball(knob, top, 7);
    const ba = rad(5) * (t.x + 1) / 2 - rad(5);
    bar(blade, BL, rot([54, -16, 7], BL, [0, 0, 1], -ba), 3, 2.4);
  }
  const B = register(stage, (dt) => { const m = stepS(t, dt); draw(); return m; });
  bag.add(B.unregister);
  let gain = value;
  function retarget() {
    t.t = over === null ? REST : clamp(over * gain, -1, 1);
    read.textContent = over === null ? "rest" : `${Math.round(32 * t.t)}°`;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = Math.abs(x) < 80 && Math.abs(y) < 70 ? clamp(x / 50, -1, 1) : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget(); draw();
  return { set: (v) => { gain = v; retarget(); }, destroy: bag.dispose };
}

