nasdrive.code:
/**
 * NAS drive: a squat rounded box with four drive sleds side by side in its
 * front face. The pointer picks a bay by where it is along the box: that sled
 * slides out on its rails, the neighbours ease out a little after it. At rest
 * the sleds sit unevenly, one half-drawn and bright. The slider is the stagger.
 */
const { Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 4, W = 9, GAP = 2.4, X0 = 3, Y0 = 0, Y1 = 34, H = 40, OUT = 18;
const X1 = X0 + N * W + (N - 1) * GAP + 3;
const REST = [1, 4, 0.5, 2], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[0, Y0, 0], [X1, Y0, H], [X1, Y1 + OUT, 0], [0, Y1 + OUT, H], [0, Y0, H], [X1, Y1 + OUT, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const body = solid(g);
  const [br, bi] = rings(0, Y0, X1, Y1, 5, 1.6);
  put(body, prism(P, front, br, bi, 0, H));
  // the bays: dim openings on the front face
  let bays = "";
  for (let k = 0; k < N; k++) {
    const x = X0 + k * (W + GAP);
    bays += seg(P(x - 0.6, Y1, 3), P(x + W + 0.6, Y1, 3)) + seg(P(x - 0.6, Y1, H - 4), P(x + W + 0.6, Y1, H - 4));
  }
  mk("path", { class: "nf lo", d: bays }, body.g);

  const sleds = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    const h = mk("path", { class: "nf lo" }, s.g);
    sleds.push({ k, x: X0 + k * (W + GAP), s, h, y: tween(REST[k]), last: NaN });
  }
  function draw(d, out) {
    if (out === d.last) return;
    d.last = out;
    const [r, i] = rings(d.x, Y1 - 6, d.x + W, Y1 + 1 + out, 1.6, 0.9);
    put(d.s, prism(P, front, r, i, 4, H - 5));
    const yf = Y1 + 1 + out, xc = d.x + W / 2;
    d.h.setAttribute("d", seg(P(xc - 2.5, yf, H - 10), P(xc + 2.5, yf, H - 10)) + seg(P(xc, yf, 9), P(xc, yf, 11)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    sleds.forEach((d) => { draw(d, tval(d.y, now)); if (!tdone(d.y, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  const cx = sleds.map((d) => P(d.x + W / 2, Y1, H / 2)[0]);
  const top = P(0, Y0, H)[1] - 10, bot = P(X1, Y1 + OUT, 0)[1] + 10;
  function hit([sx, sy]) {
    if (sy < top || sy > bot || sx < cx[0] - 40 || sx > cx[N - 1] + 40) return -1;
    let best = 0;
    cx.forEach((c, k) => { if (Math.abs(c - sx) < Math.abs(cx[best] - sx)) best = k; });
    return best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    sleds.forEach((d, k) => {
      const o = a < 0 ? REST[k] : k === a ? OUT : clamp(6 - 2.5 * Math.abs(k - a), 1, 6);
      tset(d.y, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      d.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "bay " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "nasdrive",
  means: "A four-bay NAS box: the drive sled under the pointer slides out on its rails, its neighbours ease out a little after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[138, 108], [194, 136], [236, 157], null],
  mount,
});

serverblade.code:
/**
 * Server blade: a short rack chassis with five blades stacked in its front.
 * The pointer picks a blade by its height on the face: that blade slides out
 * on its rails, the ones around it ease out a little after it. At rest the
 * blades sit unevenly, one drawn half out and bright. The slider is the stagger.
 */
const { Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 5, BH = 6, GAP = 1.8, Z0 = 4, X1 = 50, Y1 = 30, OUT = 20;
const H = Z0 + N * BH + (N - 1) * GAP + 4;
const REST = [0.5, 2, 0, 6, 1], FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [X1, 0, H], [X1, Y1 + OUT, 0], [0, Y1 + OUT, H], [0, 0, H], [X1, Y1 + OUT, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const body = solid(g);
  const [br, bi] = rings(0, 0, X1, Y1, 4, 1.4);
  put(body, prism(P, front, br, bi, 0, H));
  // the rack ears on the front face
  mk("path", { class: "nf lo", d: seg(P(2, Y1, 3), P(2, Y1, H - 3)) + seg(P(X1 - 2, Y1, 3), P(X1 - 2, Y1, H - 3)) }, body.g);

  const blades = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g);
    const h = mk("path", { class: "nf lo" }, s.g);
    blades.push({ k, z: Z0 + k * (BH + GAP), s, h, y: tween(REST[k]), last: NaN });
  }
  function draw(d, out) {
    if (out === d.last) return;
    d.last = out;
    const [r, i] = rings(4, Y1 - 8, X1 - 4, Y1 + 1 + out, 1.4, 0.8);
    put(d.s, prism(P, front, r, i, d.z, d.z + BH));
    const yf = Y1 + 1 + out, zm = d.z + BH / 2;
    d.h.setAttribute("d", seg(P(8, yf, zm), P(14, yf, zm)) + seg(P(X1 - 12, yf, zm), P(X1 - 10, yf, zm)));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    blades.forEach((d) => { draw(d, tval(d.y, now)); if (!tdone(d.y, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: on the front face at rest, nearest blade by screen height, along the face's slope
  const cy = blades.map((d) => P(X1 / 2, Y1, d.z + BH / 2));
  const dy = (P(X1, Y1, 0)[1] - P(0, Y1, 0)[1]) / (P(X1, Y1, 0)[0] - P(0, Y1, 0)[0]);
  const xl = P(0, Y1 + OUT, 0)[0] - 10, xr = P(X1, 0, 0)[0] + 10;
  function hit([sx, sy]) {
    if (sx < xl || sx > xr) return -1;
    const off = (d) => sy - (d[1] + (sx - d[0]) * dy);
    let best = 0;
    cy.forEach((c, k) => { if (Math.abs(off(c)) < Math.abs(off(cy[best]))) best = k; });
    return Math.abs(off(cy[best])) > 30 ? -1 : best;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    blades.forEach((d, k) => {
      const o = a < 0 ? REST[k] : k === a ? OUT : clamp(7 - 3 * Math.abs(k - a), 0.5, 7);
      tset(d.y, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      d.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "blade " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "serverblade",
  means: "A rack chassis of five blades: the blade under the pointer slides out on its rails, the ones beside it ease out after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[187, 140], [187, 182], [187, 213], null],
  mount,
});

dockstation.code:
/**
 * Laptop dock: a low docking slab with a laptop seated on it. The pointer's
 * place across the figure swings the lid on its hinge, shut on the left, wide
 * open on the right, on a spring. At rest the lid stands half open and bright.
 * The slider is how far the lid may open.
 */
const { Cam, clamp, facing, fit, hull, lerp, open, poly, prism, proj, rad, rings, rrect, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const W = 52, D = 36, DZ = 5, BZ = 4, T = 1.6, L = 34, REST = 108;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-4, -4, 0], [W + 4, D + 4, 0], [W + 4, -4, 0], [-4, D + 4, 0], [0, 2, DZ + BZ + L], [W, 2, DZ + BZ + L]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the dock: a low slab, wider than the laptop, with a port lip at the back
  const dock = solid(g);
  const [dr, di] = rings(-4, -4, W + 4, D + 4, 5, 1.6);
  put(dock, prism(P, front, dr, di, 0, DZ));
  mk("path", { class: "nf lo", d: seg(P(W + 4, 6, 2.5), P(W + 4, 14, 2.5)) + seg(P(8, D + 4, 2.5), P(12, D + 4, 2.5)) }, dock.g);
  // the laptop base, its keyboard well and trackpad
  const base = solid(g);
  const [br, bi] = rings(0, 0, W, D, 3, 1);
  put(base, prism(P, front, br, bi, DZ, DZ + BZ));
  const z = DZ + BZ;
  mk("path", { class: "nf lo", d: poly([P(5, 4, z), P(W - 5, 4, z), P(W - 5, 20, z), P(5, 20, z)]) + poly([P(W / 2 - 8, 24, z), P(W / 2 + 8, 24, z), P(W / 2 + 8, 32, z), P(W / 2 - 8, 32, z)]) }, base.g);

  // the lid: a thin plate hinged on the base's back edge
  const lid = solid(g);
  const scr = mk("path", { class: "nf lo" }, lid.g);
  const ring = rrect(0, 0, W, L, 3, 4), inner = rrect(3, 3, W - 3, L - 3, 1.5, 4);
  const at = (th, t) => (s) => { const c = Math.cos(th), si = Math.sin(th); return P(s.u, s.v * c - t * si, z + s.v * si + t * c); };
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg);
    // the lid's hinge sits on y = 0; v runs from the hinge out along the lid
    const a = ring.map(at(th, 0)), b = ring.map(at(th, T));
    lid.sil.setAttribute("d", poly(hull(a.concat(b))));
    lid.cr.setAttribute("d", "");
    scr.setAttribute("d", poly(inner.map(at(th, deg > 75 ? 0 : T))));
  }
  const sp = spring(REST);
  lid.sil.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const xl = P(0, D, 0)[0] - 10, xr = P(W, 0, 0)[0] + 10;
  function move([sx, sy]) {
    if (sx < xl - 20 || sx > xr + 20 || sy < 20 || sy > 300) return leave();
    const f = clamp((sx - xl) / (xr - xl), 0, 1);
    sp.t = lerp(12, 85 + 40 * maxA, f);
    read.textContent = "lid " + Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "dockstation",
  means: "A laptop seated on a dock: the pointer's place across it swings the lid on its hinge, from shut to wide open.",
  rules: [1, 3, 4, 5],
  range: [0, 0.5, 1],
  tour: [[126, 186], [200, 196], [282, 206], null],
  mount,
});

chalkeraser.code:
/**
 * Overhead projector: a low box with a glass stage, a post rising at its back
 * and a projector head on the arm above the stage. The pointer's x tilts the
 * arm forward and back about its foot, on a spring. At rest the arm leans a
 * little forward, bright. The slider is the reach of the tilt.
 */
const {
  Cam, fit, proj, facing, rings, prism, rrect, hull, poly, clamp, lerp, rad,
  spring, stepS, mk, solid, put, register, pointer, disposer,
} = HL;

const REST = 8, PY = -3, PZ = 20;
const box = (x0, y0, z0, x1, y1, z1, r) => { const q = rrect(x0, y0, x1, y1, r, 3); return [z0, z1].flatMap((z) => q.map((s) => [s.u, s.v, z])); };
const POST = box(25, -7, 12, 35, 1, 84, 3), HEAD = box(10, -10, 76, 50, 30, 94, 5), LENS = box(22, 2, 66, 38, 18, 77, 6);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, -34, 0], [60, 70, 0], [0, -34, 96], [60, 70, 96]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = mk("path", { class: "sil hi" }, g);
  const [br, bi] = rings(0, 0, 60, 58, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 20));
  const [gr] = rings(10, 10, 50, 50, 3, 1);
  mk("path", { d: poly(gr.map((s) => P(s.u, s.v, 20))), class: "nf lo" }, g);
  const lens = mk("path", { class: "sil hi" }, g), head = mk("path", { class: "sil hi" }, g);

  const tilt = (pts, a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return pts.map(([x, y, z]) => { const dy = y - PY, dz = z - PZ; return P(x, PY + dy * c + dz * s, PZ - dy * s + dz * c); }); };
  function draw(a) {
    post.setAttribute("d", poly(hull(tilt(POST, a))));
    lens.setAttribute("d", poly(hull(tilt(LENS, a))));
    head.setAttribute("d", poly(hull(tilt(HEAD, a))));
  }
  const sp = spring(REST);
  let last = NaN;
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); if (sp.x !== last) { last = sp.x; draw(sp.x); } return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    if (sx < 50 || sx > 350 || sy < 20 || sy > 300) return leave();
    const t = clamp((sx - 110) / 180, 0, 1), a = lerp(-amp * 0.6, amp, t);
    sp.t = a;
    read.textContent = "tilt " + Math.round(a);
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
