  tour: [[262, 218], [200, 175], [150, 140], null],
  mount,
});

icecreamscoop.code:
/**
 * Gelato cabinet: a low display cabinet with three tubs of gelato, each under
 * its own lid hinged along the back. The pointer picks a tub by where it
 * stands: its lid tilts up to show the mound of gelato, and the lids beside it
 * lift a crack, staggered from it. At rest one lid is half open, bright. The
 * slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), a hinge across the back.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, SW = 44, D = 40, HC = 26, T = 2.5, FAV = 1, OPEN = 1.35;
const REST = [0.1, 0.62, 0.22];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  const X1 = N * SW;
  fit(C, [[0, 0, 0], [X1, D, 0], [X1, 0, 0], [0, D, 0], [0, 0, HC + D], [X1, 0, HC + D]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-2, -2, X1 + 2, D + 2, 4, 2);
  put(solid(g), prism(P, front, cr, ci, 0, HC));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * SW, grp = mk("g", {}, g), cx = x0 + SW / 2, cy = D / 2;
    mk("path", { d: poly(ringAt(P, rings(x0 + 4, 4, x0 + SW - 4, D - 4, 3, 1)[0], HC)), class: "nf lo" }, grp);
    const mound = [];
    for (const [r, z] of [[13, 0], [11, 4], [7, 7], [3, 8.5]]) mound.push(...ringAt(P, disc(cx + 1, cy, r), HC + z));
    mk("path", { d: poly(hull(mound)), class: "nf" }, grp);
    const lid = mk("path", { class: "sil" }, grp), face = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x0, lid, face, th: tween(REST[k]), last: NaN });
  }

  function draw(it, th) {
    if (th === it.last) return;
    it.last = th;
    const c = Math.cos(th), s = Math.sin(th);
    const L = (u, v, w) => P(it.x0 + u, v * c - w * s, HC + v * s + w * c);
    const pts = [];
    for (const u of [0.5, SW - 0.5]) for (const v of [0, D]) for (const w of [0, T]) pts.push(L(u, v, w));
    it.lid.setAttribute("d", poly(hull(pts)));
    it.face.setAttribute("d", poly([L(4, 4, T), L(SW - 4, 4, T), L(SW - 4, D - 4, T), L(4, D - 4, T)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.th, now)); if (!tdone(it.th, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0 + SW / 2, D / 2, HC));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 45 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), th = a < 0 ? REST[k] : dd === 0 ? OPEN : dd === 1 ? 0.2 : 0;
      tset(it.th, th, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.lid.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tub " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "icecreamscoop",
  means: "A gelato cabinet with three tubs: the lid under the pointer tilts up on its hinge to show the gelato.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[139, 141], [200, 171], [261, 201], null],
  mount,
});

citruspress.code:
/**
 * Citrus press: a lever juicer on a base plate, a post at the back carrying a
 * long lever on a pivot, the pressing cone hung from the lever over a juice
 * cup with its reamer. The pointer is how hard it presses: the further along
 * the base it stands, the further the lever swings down on a spring, bringing
 * the cone onto the cup. At rest the lever is raised, bright. The slider is
 * how quickly it follows.
 *
 * The pattern: a continuous swing (terrain's spring, on one angle); the hit is
 * on the base's plane, which never moves.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 92, BY = 46, PZ = 50, PX = 10, CY = 23, CUPX = 40, ARM = 96, HEAD = 30, UP = -0.5, DOWN = 0.42;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[0, 0, 0], [BX, BY, 0], [BX, 0, 0], [0, BY, 0], [PX, CY, PZ + 6], [PX + ARM * Math.cos(UP), CY, PZ - ARM * Math.sin(UP)]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, BX, BY, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  put(solid(g), prism(P, front, rings(PX - 5, CY - 5, PX + 5, CY + 5, 2, 1)[0], null, 5, PZ + 3));
  put(solid(g), prism(P, front, disc(CUPX, CY, 17), disc(CUPX, CY, 15.5), 5, 15));
  const ream = [];
  for (const [r, z] of [[8, 0], [5, 5], [2, 8], [0.5, 9]]) ream.push(...ringAt(P, disc(CUPX, CY, r, 20), 15 + z));
  mk("path", { d: poly(hull(ream)), class: "nf" }, g);
  const head = mk("path", { class: "sil" }, g);
  const lever = mk("path", { class: "sil hi" }, g);
  const sp = spring(UP, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, over = false;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a);
    const Lv = (u, v, w) => P(PX + u * c + w * s, CY + v, PZ - u * s + w * c);
    const pts = [];
    for (const u of [-6, ARM]) for (const v of [-3.5, 3.5]) for (const w of [0, 5]) pts.push(Lv(u, v, w));
    lever.setAttribute("d", poly(hull(pts)));
    const hx = PX + HEAD * c, hz = PZ - HEAD * s;
    const hp = [];
    for (const [r, z] of [[4, 0], [16, -8], [16, -13]]) hp.push(...ringAt(P, disc(hx, CY, r), hz + z));
    head.setAttribute("d", poly(hull(hp)));
    read.textContent = over ? Math.round((100 * (a - UP)) / (DOWN - UP)) + "%" : "rest";
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 5);
      over = y > -25 && y < BY + 25 && x > -25 && x < BX + 40;
      sp.t = over ? UP + (DOWN - UP) * clamp(x / BX, 0, 1) : UP;
      drawn = NaN; B.wake();
    },
    leave: () => { over = false; drawn = NaN; sp.t = UP; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "citruspress",
  means: "A lever citrus press: the lever swings down as the pointer moves along the base, bringing the cone onto the cup.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[262, 226], [200, 190], [166, 153], null],
  mount,
});

waxmelter.code:
/**
 * Seed drill hopper: a long seed box on a two-wheeled frame with a hinged lid. The pointer over the drill swings the lid open; at rest it sits ajar, bright.
 *
 * The pattern: one part answers by opening about a fixed pivot.
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const S0 = [["c",-6,16,14,-2,16,14,14],["c",82,16,14,86,16,14,14],["c",-2,16,14,82,16,14,2],["b",0,0,24,80,32,52],["b",10,30,4,13,33,24],["b",40,30,4,43,33,24],["b",67,30,4,70,33,24]];
const S1 = [["b",-1,0,52,81,34,55],["b",-1,32,46,81,34,55,0,1],["b",36,24,55,44,34,58]];
const PIV = [0,0,52], AX = "x", REST = 0.22, K = 1.6, SC = 2.5;

function rot(p, a) {
  const q = [p[0] - PIV[0], p[1] - PIV[1], p[2] - PIV[2]], c = Math.cos(a), s = Math.sin(a);
  let r;
  if (AX === "x") r = [q[0], q[1] * c - q[2] * s, q[1] * s + q[2] * c];
  else if (AX === "y") r = [q[0] * c + q[2] * s, q[1], -q[0] * s + q[2] * c];
  else r = [q[0] * c - q[1] * s, q[0] * s + q[1] * c, q[2]];
  return [r[0] + PIV[0], r[1] + PIV[1], r[2] + PIV[2]];
}
function pts(s) {
  if (s[0] === "b") { const [, a, b, c, d, e, f] = s, o = []; for (const x of [a, d]) for (const y of [b, e]) for (const z of [c, f]) o.push([x, y, z]); return o; }
  const [, ax, ay, az, bx, by, bz, r] = s, v = [bx - ax, by - ay, bz - az], L = Math.hypot(...v), w = v.map((t) => t / L);
  let u = Math.abs(w[2]) < 0.9 ? [w[1], -w[0], 0] : [1, 0, 0];
  const ul = Math.hypot(...u); u = u.map((t) => t / ul);
  const n = [w[1] * u[2] - w[2] * u[1], w[2] * u[0] - w[0] * u[2], w[0] * u[1] - w[1] * u[0]], o = [];
  for (let i = 0; i < 20; i++) { const t = (i / 20) * Math.PI * 2, cc = Math.cos(t) * r, ss = Math.sin(t) * r;
    for (const [px, py, pz] of [[ax, ay, az], [bx, by, bz]]) o.push([px + u[0] * cc + n[0] * ss, py + u[1] * cc + n[1] * ss, pz + u[2] * cc + n[2] * ss]); }
  return o;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = value;
  const C = Cam(45, 0.5, SC), all = [];
  S0.forEach((s) => all.push(...pts(s)));
  for (const a of [REST, 1]) S1.forEach((s) => all.push(...pts(s).map((p) => rot(p, a * K))));
  fit(C, all, 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const shp = (ps) => poly(hull(ps.map((p) => P(...p))));
  const back = mk("g", {}, g), front = mk("g", {}, g);
  S0.forEach((s, i) => mk("path", { d: shp(pts(s)), class: s[8] ? "nf lo" : "" }, s[9] ? front : back));
  const mg = mk("g", {}, g);
  front.before(mg);
  const mp = S1.map((s, i) => mk("path", { class: i === 0 ? "sil" : s[8] ? "nf" : "" }, mg));
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    S1.forEach((s, i) => mp[i].setAttribute("d", shp(pts(s).map((p) => rot(p, a * amax / 100 * K)))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const sp = []; S0.forEach((s) => sp.push(...pts(s).map((p) => P(...p)))); S1.forEach((s) => sp.push(...pts(s).map((p) => P(...rot(p, REST * K)))));
  const bx = [Math.min(...sp.map((q) => q[0])) - 8, Math.max(...sp.map((q) => q[0])) + 8, Math.min(...sp.map((q) => q[1])) - 30, Math.max(...sp.map((q) => q[1])) + 8];
  let act = null;
  function set(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? 1 : REST, performance.now(), 0);
    mp[0].classList.add("hi");
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > bx[0] && x < bx[1] && y > bx[2] + 22 && y < bx[3]), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "waxmelter",
  means: "A seed drill hopper on its wheels: the pointer over it swings the long hinged lid open to show the seed box.",
  rules: [1, 3, 4, 5],
  range: [40, 70, 100],
  tour: [[171,154],[157,209],[242,189],null],
  mount,
});

