  front.before(mg);
  const mp = S1.map((s, i) => mk("path", { class: i === 0 ? "sil" : s[8] ? "nf" : "" }, mg));
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
