  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-W - 4, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, W * 0.7], [0, D, W * 0.7]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
