    pt.sil = mk("path", { class: "sil" }, pt.grp);
    pt.cr = mk("path", { class: "nf lo" }, pt.grp);
    pt.mk = (pt.marks || []).map(() => mk("path", { class: "nf lo" }, pt.grp));
