const box = (x0, y0, x1, y1, z0, z1, r = 2) => { const q = rrect(x0, y0, x1, y1, r, 4); return [q.map((p) => [p.u, p.v, z0]), q.map((p) => [p.u, p.v, z1])]; };
const cyl = (a, b, R, n = 28) => { const c = circ(R, n); return [c.map((p) => [a[0] + p.u, a[1] + p.v, a[2]]), c.map((p) => [b[0] + p.u, b[1] + p.v, b[2]])]; };
const cone = (x, y, R0_, z0, R1, z1, n = 40) => [circ(R0_, n).map((p) => [x + p.u, y + p.v, z0]), circ(R1, n).map((p) => [x + p.u, y + p.v, z1])];
const xbar = (x0, x1, y, z, R, n = 20) => { const c = circ(R, n); return [c.map((p) => [x0, y + p.u, z + p.v]), c.map((p) => [x1, y + p.u, z + p.v])]; };
const ydisc = (x, z, R, y0, y1, n = 44) => { const c = circ(R, n); return [c.map((p) => [x + p.u, y0, z + p.v]), c.map((p) => [x + p.u, y1, z + p.v])]; };
function PARTS() {
  return [
    { rings: box(-60, -16, 60, 16, 0, 0.8, 6), layer: 0, name: "ice" },
    { rings: cone(0, 0, 15, 0.8, 22, 7), layer: 1, name: "stone" },
    { rings: cone(0, 0, 22, 7, 18, 15), layer: 2, name: "stone" },
    { rings: cyl([-7, 0, 15], [-7, 0, 21], 2.6), layer: 3, name: "handle" },
    { rings: box(-10, -2.6, 14, 2.6, 20, 24.5, 2.4), layer: 4, name: "handle" },
  ];
}


function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const parts = PARTS();
  const rot = (p, a, s) => { const c = Math.cos(a), si = Math.sin(a); return [p[0] * c - p[1] * si + s, p[0] * si + p[1] * c, p[2]]; };
  const ext = [];
  for (let d = -90; d <= 90; d += 15) for (const pt of parts) for (const r of pt.rings) for (const p of r) ext.push(rot(p, ((R0 + d) * Math.PI) / 180, (d / 90) * SLIDE));
  const C1 = Cam(45, 0.5, 1); fit(C1, ext, 200, 166);
  const P1 = proj(C1), sp = ext.map((p) => P1(...p));
  const w = Math.max(...sp.map((p) => p[0])) - Math.min(...sp.map((p) => p[0])), h = Math.max(...sp.map((p) => p[1])) - Math.min(...sp.map((p) => p[1]));
  const C = Cam(45, 0.5, Math.min(372 / w, 292 / h)); fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  for (const pt of parts) {
    pt.grp = mk("g", {}, g);
    pt.sil = mk("path", { class: "sil" }, pt.grp);
    pt.cr = mk("path", { class: "nf lo" }, pt.grp);
    pt.mk = (pt.marks || []).map(() => mk("path", { class: "nf lo" }, pt.grp));
  }
  const ang = spring(0);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const a = ((R0 + d) * Math.PI) / 180, s = (d / 90) * SLIDE, pr = (p) => P(...rot(p, a, s));
    for (const pt of parts) {
      const [ra, rb] = pt.rings;
      pt.sil.setAttribute("d", poly(hull(ra.concat(rb).map(pr))));
      const rf = pt.face ? (pr(rb[0])[1] + pr(rb[rb.length >> 1])[1] > pr(ra[0])[1] + pr(ra[ra.length >> 1])[1] ? rb : ra) : rb;
      pt.cr.setAttribute("d", poly(rf.map(pr)));
      (pt.marks || []).forEach((m, i) => { const mm = pt.face && rf === ra ? m.map((p) => [p[0], 2 * pt.mid - p[1], p[2]]) : m; pt.mk[i].setAttribute("d", poly(mm.map(pr))); });
      const c = pt.rings[0].concat(pt.rings[1]).reduce((acc, p) => [acc[0] + p[0], acc[1] + p[1]], [0, 0]).map((v) => v / (pt.rings[0].length * 2));
      pt.key = pt.layer * 1000 + pr([c[0], c[1], 0])[1];
    }
    [...parts].sort((x, y) => x.key - y.key).forEach((pt) => g.appendChild(pt.grp));
  }
  draw(0);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(Math.round(ang.x * 100) / 100); return m; });
  bag.add(B.unregister);

  const mids = parts.filter((pt) => pt.name).map((pt) => { const all = pt.rings[0].concat(pt.rings[1]).map((p) => P(...rot(p, (R0 * Math.PI) / 180, 0))); return { pt, m: [all.reduce((s, p) => s + p[0], 0) / all.length, all.reduce((s, p) => s + p[1], 0) / all.length] }; });
  let cur = null;
  function choose(name, sx) {
    ang.t = name ? clamp((sx - 200) / 150, -1, 1) * reach : 0;
    for (const pt of parts) pt.sil.classList.toggle("hi", pt.name === (name || HI));
    if (name !== cur) { cur = name; read.textContent = name || "rest"; }
    B.wake();
  }
  function hit([sx, sy]) {
    let best = null, bd = Infinity;
    for (const { pt, m } of mids) { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = pt.name; } }
    choose(bd < 90 ? best : null, sx);
  }
  choose(null, 200);
  bag.add(pointer(stage, { move: hit, leave: () => choose(null, 200) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "curlingstone",
  means: "A curling stone with its handle on the ice: it turns to follow the pointer, and the part under it lights.",
  rules: [1, 3, 5, 8],
  range: [0, 60, 90],
  tour: [[280, 120], [130, 180], [250, 210], null],
  mount,
});

jackbox.code:
/**
 * Jack in the box: a square box with a crank on its side and a hinged lid.
 * The pointer over the box turns the crank: the lid swings open on its back
 * hinge and the jack springs up on its coil, head first. At rest the lid sits
 * ajar on the jack's head, bright. The slider is how far the jack springs.
 *
 * The pattern: one part answering a continuous value (a spring per figure);
 * the hit is on the ground plane under the box, which never moves.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, seg, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 44, H = 30, HEAD = 18, REST = 0.22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.79);
  fit(C, [[-4, -4, 0], [W + 14, W + 4, 0], [W, -4, 0], [-4, W, 0], [W / 2, W / 2, H + 1.3 * 46 + HEAD]], 200, 173);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, W, 3, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the crank: an axle out of the +y face, an arm that turns, a knob
  const crank = mk("path", { class: "nf sil" }, g);
  const lid = mk("path", { class: "sil" }, g);
  const coil = mk("path", { class: "nf lo" }, g);
  const head = solid(g);
  const sp = spring(REST, { k: 120, c: 16 });
  let last = NaN;

  function draw(t) {
    if (Math.abs(t - last) < 1e-4) return;
    last = t;
    const a = clamp(t, 0, 1) * 1.95, jz = t * 46 * reach, top = H + jz;
    const ca = Math.cos(a), sa = Math.sin(a);
    // the lid, hinged on the far edge x = 0, swinging up and back
    const L = (x, y) => P(-x * (1 - ca) * 0 + x * ca, y, H + x * sa);
    lid.setAttribute("d", poly([L(0, 0), L(W, 0), L(W, W), L(0, W)]));
    // the coil, a zigzag from the box floor to the head
    const pts = [], cx = W / 2, cy = W / 2;
    for (let i = 0; i <= 8; i++) { const z = H - 4 + ((top - H + 4) * i) / 8, s = i % 2 ? 6 : -6; pts.push(P(cx + s, cy - s, z)); }
    coil.setAttribute("d", pts.length && top > H + 1 ? "M" + pts.map((p) => p.join(",")).join("L") : "");
    const hz = Math.max(H - HEAD + 6, top - 2);
    const [hr, hi] = rings(cx - 10, cy - 10, cx + 10, cy + 10, 9, 2);
    put(head, prism(P, front, hr, hi, hz, hz + HEAD));
    // paint order: once the lid stands past upright it is behind the head
    if (a > 0.9) lid.before(coil); else head.g.after(lid);
    const k = t * Math.PI * 4, ax = W * 0.55, ay = W, az = H * 0.55;
    const arm = [ax + 9 * Math.cos(k), ay + 7, az + 9 * Math.sin(k)];
    crank.setAttribute("d", seg(P(ax, ay, az), P(ax, ay + 7, az)) + seg(P(ax, ay + 7, az), P(...arm)) + seg(P(...arm), P(arm[0], arm[1] + 5, arm[2])));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    sp.t = on ? 1 : REST;
    lid.classList.toggle("hi", !on);
    head.sil.classList.toggle("hi", on);
    read.textContent = on ? "pop" : "rest";
    B.wake();
  }
  setActive(false);
  function hit([sx, sy]) {
    const mid = P(W / 2, W / 2, H);
    return Math.abs(sx - mid[0]) < 70 && sy > P(W / 2, W / 2, H + 60 + HEAD)[1] - 10 && sy < P(W, W, 0)[1] + 10;
  }
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "jackbox",
  means: "A jack in the box: the pointer over the box turns the crank, the lid swings open and the jack springs up on its coil.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1.3],
  tour: [[200, 137], [200, 243], [200, 93], null],
  mount,
});

tabletennis2.code:
/**
 * Ball launcher: a tennis ball machine on a round base, its turret a body,
 * a hopper of balls on top and a barrel out the front. The pointer is where
 * it aims: the turret turns on its column on a spring to face it. At rest it
 * points off to one side, the barrel bright. The slider is how quickly it
 * follows.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = rad(28);
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.15);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([50 * Math.cos(a), 50 * Math.sin(a), 22], [24 * Math.cos(a), 24 * Math.sin(a), 0], [16 * Math.cos(a), 16 * Math.sin(a), 52]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-22, -22, 22, 22, 9, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  put(solid(g), prism(P, front, circ(4, 20), null, 5, 18));
  const tur = mk("g", {}, g), barG = mk("g", {}, tur);
  const BODY = rings(-15, -13, 13, 13, 6, 2), BAR = rings(4, -5, 46, 5, 5, 1.4), MOUTH = rings(42, -6.5, 47, 6.5, 2, 1);
  const HOP = rings(-16, -14, 8, 14, 5, 2);
  const barrel = solid(barG), mouth = solid(barG), body = solid(tur), hop = solid(tur), balls = [0, 1, 2].map(() => solid(tur));
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN, barFirst = null;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const T = (r) => turn(r, a);
    put(body, prism(P, front, T(BODY[0]), T(BODY[1]), 18, 32));
    put(barrel, prism(P, front, T(BAR[0]), T(BAR[1]), 22, 31));
    put(mouth, prism(P, front, T(MOUTH[0]), T(MOUTH[1]), 20.5, 32.5));
    put(hop, prism(P, front, T(HOP[0]), T(HOP[1]), 32, 46));
    [[-8, -5], [-1, 5], [-10, 6]].forEach(([u, v], i) => put(balls[i], prism(P, front, T(disc(u, v, 4.2)), null, 46, 49)));
    const first = Math.cos(a) + Math.sin(a) < 0;
    if (first !== barFirst) { barFirst = first; if (first) tur.prepend(barG); else tur.append(barG); }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(over) {
    const t = over ? Math.atan2(over[1], over[0]) : REST;
    sp.t = sp.t + wrap(t - sp.t);
    barrel.sil.classList.add("hi");
    mouth.sil.classList.add("hi");
    read.textContent = over ? "aim " + Math.round(((t * 180) / Math.PI + 360) % 360) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y); aim(r < 14 || r > 90 ? null : [x, y]); },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "tabletennis2",
  means: "A tennis ball launcher: its turret, hopper and barrel turn on the column to aim at the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[133, 175], [66, 231], [122, 285], null],
  mount,
});

smoker.code:
/**
 * Smoker box: a barbecue smoker on its firebox with a chimney. The pointer swings its big front door open on the right hinge to show the grates. At rest the door stands ajar, bright.
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;
const TAU = Math.PI * 2;
const cyl = (cx, cy, r, z0, z1, n = 24) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * TAU, x = cx + r * Math.cos(a), y = cy + r * Math.sin(a); o.push([x, y, z0], [x, y, z1]); } return o; };
const ring = (cx, cy, r, z, n = 32) => Array.from({ length: n }, (_, i) => [cx + r * Math.cos((i / n) * TAU), cy + r * Math.sin((i / n) * TAU), z]);
const arc = (cx, cy, r, z, n = 16) => Array.from({ length: n + 1 }, (_, i) => { const a = (-0.25 + 0.5 * i / n) * Math.PI * 2 * 0.5 + Math.PI / 4 - Math.PI / 4; const b = -Math.PI / 4 + (i / n) * Math.PI; return [cx + r * Math.cos(b), cy + r * Math.sin(b), z]; });
const blk = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x0, y1, z0], [x1, y1, z0], [x0, y0, z1], [x1, y0, z1], [x0, y1, z1], [x1, y1, z1]];
const rotZ = (p, ox, oy, a) => { const dx = p[0] - ox, dy = p[1] - oy; return [ox + dx * Math.cos(a) - dy * Math.sin(a), oy + dx * Math.sin(a) + dy * Math.cos(a), p[2]]; };
const rotX = (p, oy, oz, a) => { const dy = p[1] - oy, dz = p[2] - oz; return [p[0], oy + dy * Math.cos(a) - dz * Math.sin(a), oz + dy * Math.sin(a) + dz * Math.cos(a)]; };

const D = (p, t) => rotZ(p, 46, 32, -t * 1.9);
const parts = [
  { k: 'h', p: blk(-14, 6, 0, 0, 28, 24) },
  { k: 'h', p: cyl(6, 8, 3.5, 50, 72, 16) },
  { k: 'h', p: blk(0, 0, 0, 46, 32, 50) },
  ...[16, 24, 32, 40].map((z) => ({ k: 'l', c: 'nf lo', p: [[4, 32, z], [42, 32, z]] })),
  { k: 'r', c: 'nf lo', p: [[3, 32, 6], [43, 32, 6], [43, 32, 46], [3, 32, 46]] },
  { k: 'h', c: 'sil', p: (t) => blk(2, 32, 5, 46, 34, 47).map((q) => D(q, t)) },
  { k: 'h', p: (t) => blk(6, 34, 22, 9, 38, 30).map((q) => D(q, t)) }
];
const READ = ["rest","open"];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value / 100;
  const C = Cam(45, 0.5, 3);
  const ext = [];
  for (const pt of parts) for (const t of [0, 1]) ext.push(...(typeof pt.p === "function" ? pt.p(t) : pt.p));
  fit(C, ext, 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const dOf = (pt, t) => {
    const q = (typeof pt.p === "function" ? pt.p(t) : pt.p).map((v) => P(v[0], v[1], v[2]));
    if (pt.k === "h") return poly(hull(q));
    if (pt.k === "r") return poly(q);
    return "M" + q.map((v) => v[0].toFixed(1) + "," + v[1].toFixed(1)).join("L");
  };
  const els = parts.map((pt) => { const e = mk("path", { class: pt.c || "", d: dOf(pt, 0.18) }, g); return e; });
  const live = parts.map((pt, i) => [pt, els[i]]).filter(([pt]) => typeof pt.p === "function");
  const late = parts.map((pt, i) => [pt, els[i]]).filter(([pt]) => pt.late);
  const T = tween(0.18);
  let last = NaN, front = false;
  const B = register(stage, (_dt, now) => {
    const t = tval(T, now);
    if (t !== last) {
      last = t;
      for (const [pt, e] of live) e.setAttribute("d", dOf(pt, t));
      const f = t > 0.45;
      if (f !== front) { front = f; for (const [pt, e] of late) (f ? g.append(e) : els[pt.late].before(e)); }
    }
    return !tdone(T, now);
  });
  bag.add(B.unregister);
  for (const [pt, e] of parts.map((pt, i) => [pt, els[i]])) if (pt.c === "sil") e.classList.add("hi");
  let on = null;
  function go(o) {
    if (o === on) return;
    on = o;
    tset(T, o ? Math.max(0.18 + 0.1, amp) : 0.18, performance.now(), 0);
    read.textContent = o ? READ[1] : READ[0];
    B.wake();
  }
  go(false);
  bag.add(pointer(stage, { move: () => go(true), leave: () => go(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v / 100; if (on) { on = null; go(true); } }, destroy: bag.dispose };
}

hairline({
  name: "smoker",
  means: "A barbecue smoker: the pointer swings its front door open on its hinge to show the grates inside; the slider sets how far.",
  rules: [1, 3, 4, 5],
  range: [50, 75, 100],
  tour: [[177,140],[200,180],[160,215], null],
  mount,
});

tortillapress.code:
/**
 * Tortilla press: two round plates hinged at the back with a long lever. The pointer swings the top plate and lever up to show the dough ball. At rest the plate sits just open, bright.
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;
const TAU = Math.PI * 2;
const cyl = (cx, cy, r, z0, z1, n = 24) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * TAU, x = cx + r * Math.cos(a), y = cy + r * Math.sin(a); o.push([x, y, z0], [x, y, z1]); } return o; };
const ring = (cx, cy, r, z, n = 32) => Array.from({ length: n }, (_, i) => [cx + r * Math.cos((i / n) * TAU), cy + r * Math.sin((i / n) * TAU), z]);
const arc = (cx, cy, r, z, n = 16) => Array.from({ length: n + 1 }, (_, i) => { const a = (-0.25 + 0.5 * i / n) * Math.PI * 2 * 0.5 + Math.PI / 4 - Math.PI / 4; const b = -Math.PI / 4 + (i / n) * Math.PI; return [cx + r * Math.cos(b), cy + r * Math.sin(b), z]; });
const blk = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x0, y1, z0], [x1, y1, z0], [x0, y0, z1], [x1, y0, z1], [x0, y1, z1], [x1, y1, z1]];
const rotZ = (p, ox, oy, a) => { const dx = p[0] - ox, dy = p[1] - oy; return [ox + dx * Math.cos(a) - dy * Math.sin(a), oy + dx * Math.sin(a) + dy * Math.cos(a), p[2]]; };
const rotX = (p, oy, oz, a) => { const dy = p[1] - oy, dz = p[2] - oz; return [p[0], oy + dy * Math.cos(a) - dz * Math.sin(a), oz + dy * Math.sin(a) + dz * Math.cos(a)]; };

const H = (p, t) => rotX(p, 2, 7, t * 1.15);
const parts = [
  { k: 'h', p: cyl(25, 26, 24, 0, 5, 36) },
  { k: 'h', p: blk(20, -4, 0, 30, 4, 12) },
  { k: 'h', c: 'nf', p: [...ring(25, 30, 7, 5, 18), ...ring(25, 30, 4, 8.5, 14)] },
  { k: 'h', c: 'sil', p: (t) => cyl(25, 26, 23, 7, 11, 36).map((q) => H(q, t)) },
  { k: 'h', p: (t) => blk(22, -2, 11, 28, 56, 14).map((q) => H(q, t)) },
  { k: 'h', p: (t) => blk(21, 48, 10, 29, 58, 15).map((q) => H(q, t)) }
];
const READ = ["rest","open"];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
