  name: "micstand",
  means: "A microphone stand with a boom arm: the boom swings round to point the mic wherever the pointer is.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[222, 304], [70, 250], [200, 163], null],
  mount,
