handpan.code:
/**
 * Handpan: a steel lens with a raised centre note and a ring of tone fields,
 * resting on a low three-legged stand. The pan tilts its face toward the
 * pointer, steeper the farther out. At rest it tips slightly forward with the
 * centre note bright. The slider is how far it can tilt.
 */
const { Cam, circ, clamp, fit, hull, poly, proj, seg, unproj, spring, stepS, disposer, mk, pointer, register } = HL;

const R = 58, Z0 = 40, MAX = 0.5, REST = [0.12, 0.1];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R, R, Z0 + 40], [R, -R, Z0 + 40], [0, 0, Z0 + 46]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const legs = mk("path", { class: "nf sil" }, g);
  let ld = "";
  for (let k = 0; k < 3; k++) { const a = 0.7 + k * 2.094; ld += seg(P(Math.cos(a) * 44, Math.sin(a) * 44, 0), P(Math.cos(a) * 16, Math.sin(a) * 16, Z0 - 12)); }
  legs.setAttribute("d", ld);
  const body = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf lo" }, g);
  const fields = Array.from({ length: 8 }, () => mk("path", { class: "nf lo" }, g));
  const ding = mk("path", { class: "nf hi" }, g);
  const tx = spring(REST[0], { k: 110, c: 15 }), ty = spring(REST[1], { k: 110, c: 15 });
  let lim = MAX * value, last = "";
  function draw() {
    const key = tx.x.toFixed(3) + ty.x.toFixed(3);
    if (key === last) return;
    last = key;
    const a = tx.x, b = ty.x;
    // tilt: rotate about y by a, about x by b, around (0,0,Z0)
    const T = (x, y, z) => {
      const x1 = x * Math.cos(a) + z * Math.sin(a), z1 = -x * Math.sin(a) + z * Math.cos(a);
      const y2 = y * Math.cos(b) - z1 * Math.sin(b), z2 = y * Math.sin(b) + z1 * Math.cos(b);
      return P(x1, y2, Z0 + z2);
    };
    const ring = (r, z, cx = 0, cy = 0) => circ(r, 40).map((q) => T(cx + q.u, cy + q.v, z));
    const prof = [[R, 0], [R * 0.92, 8], [R * 0.7, 15], [R * 0.4, 19], [R * 0.92, -8], [R * 0.6, -15], [R * 0.25, -18]];
    body.setAttribute("d", poly(hull(prof.flatMap(([r, z]) => ring(r, z)))));
    rim.setAttribute("d", poly(ring(R, 0)));
    fields.forEach((f, i) => { const t = (i / 8) * Math.PI * 2 + 0.3; f.setAttribute("d", poly(circ(7, 20).map((q) => T(Math.cos(t) * 36 + q.u, Math.sin(t) * 36 + q.v * 0.8, 15)))); });
    ding.setAttribute("d", poly(hull(ring(10, 19).concat(ring(7, 24)))));
  }
  const B = register(stage, (dt) => { const m1 = stepS(tx, dt), m2 = stepS(ty, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);
  function tilt(t) {
    tx.t = t[0]; ty.t = t[1];
    read.textContent = t === REST ? "rest" : `${Math.round((Math.hypot(t[0], t[1]) * 180) / Math.PI)}°`;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], Z0), r = Math.hypot(x, y);
      if (r < 6) return tilt(REST);
      const m = clamp(r / 120, 0, 1) * lim;
      tilt([(x / r) * m, -(y / r) * m]);
    },
    leave: () => tilt(REST),
  }));
  bag.add(() => svg.replaceChildren());
  draw(); tilt(REST);
  return { set: (v) => { lim = MAX * v; }, destroy: bag.dispose };
}

hairline({
  name: "handpan",
  means: "A handpan on its stand: the steel lens tilts its face toward the pointer, steeper the farther out you go.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[122, 171], [200, 172], [200, 54], null],
  mount,
});

microscope3.code:
/**
 * Stereo microscope: a heavy foot with a round stage, a pillar at the back
 * and a binocular head on an arm. The pointer brings the head sliding down
 * the pillar to focus on the stage. At rest the stage plate is bright.
 * The slider is how far the head travels.
 */
const { Cam, circ, fit, facing, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value / 100, act = false;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[0, 0, 0], [40, 50, 0], [40, 0, 0], [0, 50, 0], [6, 10, 78], [34, 46, 78], [6, 10, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const box = (g, x0, y0, x1, y1, z0, z1, r = 3) => { const s = solid(g); put(s, prism(P, front, ...rings(x0, y0, x1, y1, r, 1.5), z0, z1)); return s; };
  const cyl = (g, x, y, r, z0, z1) => { const s = solid(g); put(s, prism(P, front, disc(x, y, r), disc(x, y, r - 1.2), z0, z1)); return s; };
  const g = mk("g", {}, svg);
  box(g, 0, 0, 40, 50, 0, 7, 6);
  const plate = cyl(g, 20, 20, 13, 7, 9.5);
  cyl(g, 20, 44, 4, 7, 76);
  const mv = mk("g", {}, g);
  const t = tween(0);
  let last = NaN;
  function draw(k) {
    if (k === last) return;
    last = k;
    mv.replaceChildren();
    const h = 12 - 16 * amt * k;
    cyl(mv, 13, 20, 3.5, 34 + h, 42 + h);
    cyl(mv, 27, 20, 3.5, 34 + h, 42 + h);
    box(mv, 14, 30, 26, 47, 46 + h, 54 + h, 3);
    const head = box(mv, 4, 9, 36, 32, 40 + h, 54 + h, 6);
    cyl(mv, 12, 18, 4, 54 + h, 64 + h);
    cyl(mv, 28, 18, 4, 54 + h, 64 + h);
    head.sil.classList.toggle("hi", act);
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);
  const A = P(20, 20, 50);
  function setActive(a) {
    if (a === act) return;
    act = a;
    last = NaN;
    tset(t, a ? 1 : 0, performance.now(), 0);
    plate.sil.classList.toggle("hi", !a);
    read.textContent = a ? "focus" : "rest";
    B.wake();
  }
  plate.sil.classList.add("hi");
  read.textContent = "rest";
  bag.add(pointer(stage, { move: ([x, y]) => setActive(Math.hypot(x - A[0], y - A[1]) < 120), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v / 100; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "microscope3",
  means: "A stereo microscope: the binocular head slides down its pillar to focus on the round stage under the pointer.",
  rules: [1, 4, 5, 8],
  range: [40, 70, 100],
  tour: [[209, 129], [200, 104], [217, 178], null],
