  name: "periodic",
  means: "A science kit: the hinged lid swings open on its back hinge to show the rack of stoppered test tubes inside.",
  rules: [1, 4, 5, 6],
  range: [40, 70, 100],
  tour: [[200, 171], [91, 179], [317, 134], null],
