soldering2.code:
/**
 * Soldering station: a control box with a dial on its face and, beside it, a
 * stand holding the iron upright in its sleeve. The pointer over the station
 * draws the iron up out of the sleeve, eased; leaving drops it back.
 * At rest the iron sits in the sleeve, its grip bright.
 * The slider is how far it rises.
 */
const { Cam, facing, fit, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween, unproj, disposer, mk, pointer, put, register, solid } = HL;

const S = 4.5, BX = 26, BY = 24, BH = 15, SX = 38, SY = 8, IL = 34, UP = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 90;
  const C = Cam(45, 0.5, S);
  fit(C, [[0, 0, 0], [BX, BY, 0], [SX + 12, SY + 12, 0], [SX, SY, 8 + IL + UP], [0, BY, BH], [SX + 12, SY - 4, 0]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const base = solid(g);
  const [bo, bi] = rings(0, 0, BX, BY, 4, 1.3);
  put(base, prism(P, front, bo, bi, 0, BH));
  const dial = []; for (let n = 0; n < 24; n++) { const q = (n / 24) * Math.PI * 2; dial.push(P(BX / 2 + 4.5 * Math.cos(q), BY, 7.5 + 4.5 * Math.sin(q))); }
  mk("path", { class: "nf lo", d: poly(dial) + seg(P(BX / 2, BY, 7.5), P(BX / 2 + 2.5, BY, 10)) }, base.g);

  const foot = solid(g);
  put(foot, prism(P, front, rrect(SX - 7, SY - 7, SX + 7, SY + 7, 7, 10), rrect(SX - 6, SY - 6, SX + 6, SY + 6, 6, 10), 0, 3));
  const iron = solid(g), tip = mk("path", { class: "sil" }, iron.g);
  const sleeve = solid(g);
  put(sleeve, prism(P, front, rrect(SX - 4.5, SY - 4.5, SX + 4.5, SY + 4.5, 4.5, 10), rrect(SX - 3.6, SY - 3.6, SX + 3.6, SY + 3.6, 3.6, 10), 3, 22));
  const z = tween(0);
  let last = NaN;

  function draw(h) {
    if (h === last) return;
    last = h;
    const z0 = 6 + h;
    put(iron, prism(P, front, rrect(SX - 2.6, SY - 2.6, SX + 2.6, SY + 2.6, 2.6, 10), rrect(SX - 1.8, SY - 1.8, SX + 1.8, SY + 1.8, 1.8, 10), z0 + 10, z0 + IL));
    // the tip: a thin taper below the grip, hidden in the sleeve at rest
    tip.setAttribute("d", poly([P(SX - 1.2, SY, z0 + 10), P(SX + 1.2, SY, z0 + 10), P(SX, SY, z0)]));
  }

  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -12 && x < SX + 20 && y > -12 && y < BY + 14;
  }

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(z, a ? UP * (0.4 + 0.6 * reach) : 0, performance.now(), 0);
    tip.classList.toggle("hi", a);
    iron.sil.classList.toggle("hi", true);
    read.textContent = a ? "iron" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 90; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "soldering2",
  means: "A soldering station: the pointer over it draws the iron up out of its sleeve on the stand.",
  rules: [1, 3, 5],
  range: [30, 90, 90],
  tour: [[190, 243], [108, 227], [260, 272], null],
  mount,
});

keyboard3.code:
/**
 * Macro pad: a small slab with a cable stub and a three-by-three grid of
 * keys. The pointer picks a key on the plane of the resting key tops: it
 * pops up high, the keys round it rise less with distance, staggered out
 * from it. At rest the keys sit at uneven heights, the centre one bright.
 * The slider is the stagger.
 */
const { Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween, unproj, disposer, mk, pointer, put, register, solid } = HL;

const G = 3, PITCH = 13, KS = 11, BZ = 5, KH = 5, LIFT = 16, M = 3;
const SIZE = M * 2 + (G - 1) * PITCH + KS;
const REST = [1, 0, 2, 0, 4, 1, 2, 1, 0], FAV = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 4.15);
  fit(C, [[0, 0, 0], [SIZE, SIZE, 0], [0, SIZE, 0], [SIZE, 0, 0], [M, M, BZ + KH + LIFT], [SIZE - M, M, BZ + KH + LIFT]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const base = solid(g);
  const [bo, bi] = rings(0, 0, SIZE, SIZE, 5, 1.4);
  put(base, prism(P, front, bo, bi, 0, BZ));
  mk("path", { class: "nf lo", d: seg(P(SIZE / 2, -0.2, 2.5), P(SIZE / 2, -6, 2.5)) }, g);

  const keys = [];
  for (let j = 0; j < G; j++) for (let i = 0; i < G; i++) keys.push({ i, j, x: M + i * PITCH, y: M + j * PITCH });
  // paint far to near
  keys.slice().sort((a, b) => a.x + a.y - (b.x + b.y)).forEach((k) => { k.s = solid(g); });
  keys.forEach((k, n) => { k.n = n; k.z = tween(REST[n]); k.last = NaN; });

  function draw(k, lift) {
    if (lift === k.last) return;
    k.last = lift;
    const [o, i] = rings(k.x, k.y, k.x + KS, k.y + KS, 2.4, 1.2);
    put(k.s, prism(P, front, o, i, BZ, BZ + KH + lift));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    keys.forEach((k) => { draw(k, tval(k.z, now)); if (!tdone(k.z, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BZ + KH + 1);
    if (x < 0 || y < 0 || x > SIZE || y > SIZE) return -1;
    const i = clamp(Math.floor((x - M + 1) / PITCH), 0, G - 1), j = clamp(Math.floor((y - M + 1) / PITCH), 0, G - 1);
    return j * G + i;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    const fi = from % G, fj = Math.floor(from / G);
    keys.forEach((k) => {
      const d = a < 0 ? 0 : Math.hypot(k.i - (a % G), k.j - Math.floor(a / G));
      const z = a < 0 ? REST[k.n] : k.n === a ? LIFT : clamp(8 - 4 * d, 1, 8);
      tset(k.z, z, now, from < 0 ? 0 : Math.hypot(k.i - fi, k.j - fj) * stag);
      k.s.sil.classList.toggle("hi", k.n === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "key " + (a % G + 1) + "·" + (Math.floor(a / G) + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
