  means: "A comb binding machine: the pointer over it tips the punch lid open and swings the long handle down.",
  rules: [3, 4, 5, 6],
  range: [40, 70, 85],
  tour: [[173, 178], [145, 160], [205, 250], null],
  mount: make(F),
});

birdcage2.code:
/**
 * Bird cage: a round cage of bars on a stand, with a hinged door. The
 * pointer over the cage swings the door wide and turns the cage on its
 * hook to face it. At rest the door stands ajar, bright. The slider is
 * how far the cage turns.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const R = 30, H = 62, Z0 = 6, NB = 14, DW = 2;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-R - 18, -R - 18, 0], [R + 18, R + 18, 0], [R + 18, -R - 18, 0], [-R - 18, R + 18, 0], [0, 0, Z0 + H + 22], [R + 30, 0, Z0 + H / 2]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-R - 6, -R - 6, R + 6, R + 6, R + 6, 3);
  put(solid(g), prism(P, front, br, bi, 0, Z0));
  const bars = mk("path", { class: "nf" }, g), top = mk("path", { class: "nf" }, g), door = mk("path", { class: "sil" }, g), hook = mk("path", { class: "nf lo" }, g);
  const turn = tween(0.15), open = tween(0.3);
  let last = "";
  function at(a, r, z) { return P(r * Math.cos(a), r * Math.sin(a), z); }
  function draw(t, o) {
    const k = t + "," + o; if (k === last) return; last = k;
    const rot = t * Math.PI * 0.8;
    let d = "";
    for (let i = 0; i < NB; i++) { if (i > 0 && i < DW) continue; const a = rot + (i / NB) * 2 * Math.PI; d += seg(at(a, R, Z0), at(a, R, Z0 + H)); }
    d += poly(ringAt(P, disc(R), Z0 + 1)) + poly(ringAt(P, disc(R), Z0 + H * 0.5)) ;
    bars.setAttribute("d", d);
    const dome = [];
    for (let i = 0; i <= 5; i++) { const s = (i / 5) * Math.PI / 2; dome.push(...ringAt(P, disc(R * Math.cos(s), 28), Z0 + H + R * 0.6 * Math.sin(s))); }
    top.setAttribute("d", poly(hull(dome)) + poly(ringAt(P, disc(R), Z0 + H)));
    hook.setAttribute("d", poly(hull(ringAt(P, disc(3, 12), Z0 + H + R * 0.6).concat(ringAt(P, disc(3, 12), Z0 + H + R * 0.6 + 10)))));
    // door: hinged at bar 0, spans to bar DW
    const a0 = rot, a1 = rot + (DW / NB) * 2 * Math.PI, w = 2 * R * Math.sin((a1 - a0) / 2);
    const hx = R * Math.cos(a0), hy = R * Math.sin(a0);
    const dir = Math.atan2(R * Math.sin(a1) - hy, R * Math.cos(a1) - hx) - o * Math.PI * 0.7;
    const fx = hx + w * Math.cos(dir), fy = hy + w * Math.sin(dir), zl = Z0 + 6, zh = Z0 + H * 0.5 - 2;
    let dd = poly([P(hx, hy, zl), P(fx, fy, zl), P(fx, fy, zh), P(hx, hy, zh)]);
    for (const f of [0.33, 0.66]) dd += seg(P(hx + (fx - hx) * f, hy + (fy - hy) * f, zl), P(hx + (fx - hx) * f, hy + (fy - hy) * f, zh));
    door.setAttribute("d", dd);
  }
  const B = register(stage, (_dt, now) => { draw(tval(turn, now), tval(open, now)); return !(tdone(turn, now) && tdone(open, now)); });
  bag.add(B.unregister);
  const mid = P(0, 0, Z0 + H / 2);
  let act = null;
  function setActive(a) {
    if (a === act) return; act = a;
    const now = performance.now();
    tset(turn, a ? 0.15 + amp / 90 : 0.15, now, 0);
    tset(open, a ? 1 : 0.3, now, a ? 80 : 0);
    door.classList.add("hi");
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.abs(sx - mid[0]) < 70 && Math.abs(sy - mid[1]) < 90), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

hairline({
  name: "birdcage2",
  means: "A round bird cage on a stand: the pointer swings its door wide and turns the cage on its hook to face you.",
  rules: [1, 4, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 133], [215, 160], [185, 110], null],
  mount,
});

dogwasher.code:
/**
 * Dog bath: a raised tub on legs with a slatted ramp hinged at its rim.
 * The pointer over the bath swings the ramp down to the floor for the
 * dog to climb. At rest the ramp is folded up against the tub, bright.
 * The slider is how far the ramp swings.
 */
const { Cam, fit, ringAt, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const TL = 64, TW = 40, ZL = 16, TH = 24, RL = 62, NS = 7;
const UP = 1.15, DOWN = -Math.asin((ZL + TH) / RL);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-6, -6, 0], [TL + RL + 4, TW + 6, 0], [TL + RL + 4, -6, 0], [-6, TW + 6, 0], [0, 0, ZL + TH + 6], [TL + 26, 6, ZL + TH + 58]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const legs = mk("path", { class: "nf" }, g);
  let ld = "";
  for (const [x, y] of [[6, 6], [TL - 6, 6], [6, TW - 6], [TL - 6, TW - 6]]) ld += seg(P(x, y, 0), P(x, y, ZL));
  legs.setAttribute("d", ld);
  const [tr, ti] = rings(0, 0, TL, TW, 8, 3);
  put(solid(g), prism(P, front, tr, ti, ZL, ZL + TH));
  const [hr] = rings(5, 5, TL - 5, TW - 5, 6, 2);
  mk("path", { d: poly(ringAt(P, hr, ZL + TH)), class: "nf" }, g);
  const ramp = mk("path", { class: "sil" }, g), slats = mk("path", { class: "nf lo" }, g);
  const ang = tween(UP);
  let last = NaN;
  const pt = (s, y, a, dz = 0) => P(TL + s * Math.cos(a) - dz * Math.sin(a), y, ZL + TH + s * Math.sin(a) + dz * Math.cos(a));
  function draw(a) {
    if (a === last) return; last = a;
    const y0 = 6, y1 = TW - 6, c = [];
    for (const s of [0, RL]) for (const y of [y0, y1]) for (const dz of [0, -3]) c.push(pt(s, y, a, dz));
    ramp.setAttribute("d", poly(hull(c)));
    let d = "";
    for (let i = 1; i <= NS; i++) { const s = (i / (NS + 1)) * RL; d += seg(pt(s, y0 + 2, a), pt(s, y1 - 2, a)); }
    slats.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const mid = P(TL / 2 + 20, TW / 2, ZL);
  let act = null;
  function setActive(a) {
    if (a === act) return; act = a;
    const now = performance.now();
    tset(ang, a ? UP + (DOWN - UP) * (0.4 + 0.6 * amp / 90) : UP, now, 0);
    ramp.classList.add("hi");
    read.textContent = a ? "ramp" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.abs(sx - mid[0]) < 150 && Math.abs(sy - mid[1]) < 130), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

hairline({
  name: "dogwasher",
  means: "A raised dog bath on legs: the pointer swings its slatted ramp down from the rim to the floor for the dog to climb.",
  rules: [1, 4, 5, 6],
  range: [0, 45, 90],
  tour: [[152, 111], [220, 190], [133, 147], null],
  mount,
});

agilityhoop.code:
/**
 * Agility tire jump: a tyre hung on chains inside a frame of two posts
 * and a crossbar, on two feet. The pointer over the frame swings the
 * tyre on its chains toward the reader, as a dog brushing through would.
 * At rest the tyre hangs still, bright. The slider is the swing.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 96, HZ = 104, CX = W / 2, CZ = 56, RO = 26, RI = 15, T = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-8, -26, 0], [W + 8, 26, 0], [W + 8, -26, 0], [-8, 26, 0], [0, 0, HZ + 4], [W, 0, HZ + 4], [CX, 60, 70]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const x of [0, W]) { const [fr, fi] = rings(x - 7, -24, x + 7, 24, 5, 2); put(solid(g), prism(P, front, fr, fi, 0, 5)); }
  for (const x of [0, W]) { const [pr, pi] = rings(x - 3, -3, x + 3, 3, 2, 1); put(solid(g), prism(P, front, pr, pi, 5, HZ)); }
  const [br, bi] = rings(-4, -3, W + 4, 3, 2, 1);
  put(solid(g), prism(P, front, br, bi, HZ, HZ + 5));
  const chains = mk("path", { class: "nf lo" }, g), tyre = mk("path", { class: "sil" }, g), tread = mk("path", { class: "nf lo" }, g);
  const sw = tween(0);
  let last = NaN;
  const at = (x, y, z, th) => { const dz = z - HZ, dy = y; return P(x, dy * Math.cos(th) - dz * Math.sin(th), HZ + dy * Math.sin(th) + dz * Math.cos(th)); };
  const ring = (r, y, th, n = 36) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * 2 * Math.PI; o.push(at(CX + r * Math.cos(a), y, CZ + r * Math.sin(a), th)); } return o; };
  function draw(th) {
    if (th === last) return; last = th;
    tyre.setAttribute("d", poly(hull(ring(RO, -T, th).concat(ring(RO, T, th)))) + poly(ring(RI, 0, th).reverse()));
    tread.setAttribute("d", poly(ring((RO + RI) / 2, 0, th)));
    let d = "";
    for (const s of [-1, 1]) { const a = Math.PI / 2 + s * 0.55; d += seg(at(CX + s * 30, 0, HZ, th), at(CX + RO * Math.cos(a), 0, CZ + RO * Math.sin(a), th)); }
    chains.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(sw, now)); return !tdone(sw, now); });
  bag.add(B.unregister);
  const mid = P(CX, 0, CZ);
  let act = null;
  function setActive(a) {
    if (a === act) return; act = a;
    const now = performance.now();
    tset(sw, a ? -(0.25 + 0.5 * amp / 90) : 0, now, 0);
    tyre.classList.add("hi");
    read.textContent = a ? "swing" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.abs(sx - mid[0]) < 140 && Math.abs(sy - mid[1]) < 150), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

