  name: "signalgen",
  means: "A logic analyser's probe clip box: the lid swings open on its hinge over the pointer, and the clip under it goes bright.",
  rules: [1, 3, 5, 6],
  range: [0, 60, 100],
  tour: [[119, 184], [198, 223], [238, 243], null],
  mount,
