  name: "kvm",
  means: "A four-port KVM switch: the select key under the pointer presses down flush, the keys beside it rock up after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[136, 132], [217, 173], [257, 193], null],
  mount,
