darts2.code:
/**
 * Dart cabinet: a wall cabinet holding a dartboard, its two doors on hinges
 * at the sides. The pointer swings the doors: the door nearer it opens wide,
 * the other follows less, each on its own spring. At rest both stand ajar
 * and the board's rim is bright. The slider is the spring's stiffness.
 *
 * The pattern: a continuous aim per door (terrain's spring on an angle); the
 * hit is on a fixed plane through the cabinet's middle, which never moves.
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, unproj, spring, stepS, clamp, lerp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WD = 64, DP = 10, HT = 72, DW = WD / 2, REST = [0.55, 0.85], WIDE = 1.65;
const turn = (ring, a, hx, hy, s) => {
  const c = Math.cos(a), n = Math.sin(a);
  return ring.map((q) => ({ u: hx + s * (q.u * c - q.v * n), v: hy + q.u * n + q.v * c, nu: s * (q.nu * c - q.nv * n), nv: q.nu * n + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[-DW, 0, 0], [WD + DW, DP + DW, HT], [0, DP + DW, 0], [WD, 0, HT], [WD, DP + DW, 0], [0, 0, HT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ba, bb] = rings(0, 0, WD, DP, 3, 1.4);
  put(solid(g), prism(P, front, ba, bb, 0, HT));
  // the board, on the cabinet's front face
  const ring = (r) => circ(r, 40).map((q) => P(WD / 2 + q.u, DP + 0.2, HT / 2 + q.v));
  const rim = mk("path", { d: poly(ring(24)) }, g);
  mk("path", { class: "nf lo", d: poly(ring(17)) + poly(ring(10)) + poly(ring(2.5)) }, g);
  const wires = [];
  for (let k = 0; k < 10; k++) { const a = (k / 10) * Math.PI * 2; wires.push(open([P(WD / 2 + 2.5 * Math.cos(a), DP + 0.2, HT / 2 + 2.5 * Math.sin(a)), P(WD / 2 + 17 * Math.cos(a), DP + 0.2, HT / 2 + 17 * Math.sin(a))])); }
  mk("path", { class: "nf lo", d: wires.join("") }, g);
  const [da, db] = rings(0, -2, DW, 0, 0.9, 0.4);
  const doors = [[0, 1], [WD, -1]].map(([hx, s], i) => ({ i, hx, s, sol: solid(g), sp: spring(REST[i], { k: 100 * value, c: 18 * Math.sqrt(value) }), drawn: NaN }));
  function draw(d) {
    const a = d.sp.x;
    if (Math.abs(a - d.drawn) < 1e-4) return;
    d.drawn = a;
    put(d.sol, prism(P, front, turn(da, d.s * a, d.hx, DP + 2, d.s), turn(db, d.s * a, d.hx, DP + 2, d.s), 0, HT));
  }
  const B = register(stage, (dt) => { let m = false; for (const d of doors) { if (stepS(d.sp, dt)) m = true; draw(d); } return m; });
  bag.add(B.unregister);
  function set(x) {
    let near = null;
    if (x == null) doors.forEach((d) => { d.sp.t = REST[d.i]; });
    else {
      const f = clamp(x / WD, 0, 1);
      doors[0].sp.t = lerp(WIDE, 0.5, f); doors[1].sp.t = lerp(0.5, WIDE, f);
      near = f < 0.5 ? doors[0] : doors[1];
    }
    rim.classList.toggle("hi", !near);
    doors.forEach((d) => d.sol.sil.classList.toggle("hi", d === near));
    read.textContent = near ? (near.i ? "right" : "left") : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], HT / 2); set(Math.abs(y - DP) > 70 || x < -50 || x > WD + 50 ? null : x); },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => doors.forEach((d) => { d.sp.k = 100 * v; d.sp.c = 18 * Math.sqrt(v); }), destroy: bag.dispose };
}

hairline({
  name: "darts2",
  means: "A dart cabinet on the wall: its two doors swing open toward the pointer, the nearer one wide, to show the board.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[154, 141], [249, 188], [202, 165], null],
  mount,
});

dogstairs.code:
/**
 * Pet steps: four carpeted steps that climb toward the back, each a drawer. The step under the pointer slides out toward the reader and the steps beside it follow a little, staggered. At rest the third step is half out, bright.
 *
 * The pattern: each moving part has a rest pose and an answer pose; the pick
 * is the part whose resting middle is nearest the pointer on screen, and the
 * others follow by distance, staggered. The slider is the stagger.
 */
const {
  Cam, facing, fit, hull, open, poly, proj, rad, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, register, solid,
} = HL;

// [x0, y0, x1, y1, z0, z1, radius, motion|null, name]; motion {ax, p, ang} turns about an axis through p, {d} slides
const PARTS = [[0,0,16,32,0,52,2,{"d":[0,16,0]},"step 4"],[16,0,32,32,0,39,2,{"d":[0,16,0]},"step 3"],[32,0,48,32,0,26,2,{"d":[0,16,0]},"step 2"],[48,0,64,32,0,13,2,{"d":[0,16,0]},"step 1"]];
const REST = [0.06,0,0.4,0.12], FAV = 2, FALL = [1, 0.62, 0.42, 0.3];

function xf(pt, m, t) {
  if (!m || !t) return pt;
  if (m.d) return [pt[0] + m.d[0] * t, pt[1] + m.d[1] * t, pt[2] + m.d[2] * t];
  const a = rad(m.ang * t), c = Math.cos(a), s = Math.sin(a);
  let x = pt[0] - m.p[0], y = pt[1] - m.p[1], z = pt[2] - m.p[2];
  if (m.ax === "x") [y, z] = [y * c - z * s, y * s + z * c];
  else if (m.ax === "y") [x, z] = [x * c - z * s, x * s + z * c];
  else [x, y] = [x * c - y * s, x * s + y * c];
  return [x + m.p[0], y + m.p[1], z + m.p[2]];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.75);
  const ext = [];
  for (const b of PARTS) for (const t of [0, 1]) for (const x of [b[0], b[2]]) for (const y of [b[1], b[3]]) for (const z of [b[4], b[5]]) ext.push(xf([x, y, z], b[7], t));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const parts = PARTS.map((b, k) => {
    const r = Math.min(b[6], (b[2] - b[0]) / 2 - 0.05, (b[3] - b[1]) / 2 - 0.05);
    const bi = Math.min(1.2, (b[2] - b[0]) / 2 - 0.1, (b[3] - b[1]) / 2 - 0.1);
    const ring = rrect(b[0], b[1], b[2], b[3], r, 4), inner = rrect(b[0] + bi, b[1] + bi, b[2] - bi, b[3] - bi, Math.max(0.05, r - bi), 4);
    return { b, k, el: solid(g), ring, inner: run(inner, front), mv: b[7] ? 1 : 0, tw: tween(0), last: "" };
  });
  const movers = parts.filter((p) => p.mv);
  movers.forEach((p, i) => { p.i = i; p.tw = tween(REST[i]); });

  function draw(p, t) {
    const key = t.toFixed(3);
    if (key === p.last) return;
    p.last = key;
    const b = p.b, pts = [];
    for (const s of p.ring) { pts.push(P(...xf([s.u, s.v, b[4]], b[7], t))); pts.push(P(...xf([s.u, s.v, b[5]], b[7], t))); }
    p.el.sil.setAttribute("d", poly(hull(pts)));
    p.el.cr.setAttribute("d", open(p.inner.map((s) => P(...xf([s.u, s.v, b[5]], b[7], t)))));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of parts) { draw(p, tval(p.tw, now)); if (!tdone(p.tw, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = movers.map((p) => { const b = p.b; return P((b[0] + b[2]) / 2, (b[1] + b[3]) / 2, (b[4] + b[5]) / 2); });
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, i) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = i; } });
    return bd < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    movers.forEach((p, i) => {
      const t = a < 0 ? REST[i] : FALL[Math.min(3, Math.abs(i - a))];
      tset(p.tw, t, now, from < 0 ? 0 : Math.abs(i - from) * stag);
      p.el.sil.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : movers[a].b[8];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "dogstairs",
  means: "Four pet steps: the step under the pointer slides out toward you, and its neighbours follow a little in turn.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[205,110],[231,166],[250,215],null],
  mount,
});

kittyshelf.code:
/**
 * Cat shelf: a wall board with three perches at different heights. The perch under the pointer swings out from the wall on its pivot and the others follow a little, staggered. At rest the middle perch is half out, bright.
 *
 * The pattern: each moving part has a rest pose and an answer pose; the pick
 * is the part whose resting middle is nearest the pointer on screen, and the
 * others follow by distance, staggered. The slider is the stagger.
 */
const {
  Cam, facing, fit, hull, open, poly, proj, rad, rrect, run, tdone, tset, tval, tween,
  disposer, mk, pointer, register, solid,
} = HL;

// [x0, y0, x1, y1, z0, z1, radius, motion|null, name]; motion {ax, p, ang} turns about an axis through p, {d} slides
const PARTS = [[0,0,96,4,0,84,1.5,null,"wall"],[6,4,36,30,60,64,3,{"ax":"z","p":[6,4,0],"ang":40},"perch 1"],[58,4,90,30,38,42,3,{"ax":"z","p":[58,4,0],"ang":40},"perch 2"],[26,4,56,30,12,16,3,{"ax":"z","p":[26,4,0],"ang":40},"perch 3"]];
const REST = [0.05,0.35,0], FAV = 1, FALL = [1, 0.62, 0.42, 0.3];

function xf(pt, m, t) {
  if (!m || !t) return pt;
  if (m.d) return [pt[0] + m.d[0] * t, pt[1] + m.d[1] * t, pt[2] + m.d[2] * t];
  const a = rad(m.ang * t), c = Math.cos(a), s = Math.sin(a);
  let x = pt[0] - m.p[0], y = pt[1] - m.p[1], z = pt[2] - m.p[2];
  if (m.ax === "x") [y, z] = [y * c - z * s, y * s + z * c];
  else if (m.ax === "y") [x, z] = [x * c - z * s, x * s + z * c];
  else [x, y] = [x * c - y * s, x * s + y * c];
  return [x + m.p[0], y + m.p[1], z + m.p[2]];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  const ext = [];
  for (const b of PARTS) for (const t of [0, 1]) for (const x of [b[0], b[2]]) for (const y of [b[1], b[3]]) for (const z of [b[4], b[5]]) ext.push(xf([x, y, z], b[7], t));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const parts = PARTS.map((b, k) => {
    const r = Math.min(b[6], (b[2] - b[0]) / 2 - 0.05, (b[3] - b[1]) / 2 - 0.05);
    const bi = Math.min(1.2, (b[2] - b[0]) / 2 - 0.1, (b[3] - b[1]) / 2 - 0.1);
    const ring = rrect(b[0], b[1], b[2], b[3], r, 4), inner = rrect(b[0] + bi, b[1] + bi, b[2] - bi, b[3] - bi, Math.max(0.05, r - bi), 4);
    return { b, k, el: solid(g), ring, inner: run(inner, front), mv: b[7] ? 1 : 0, tw: tween(0), last: "" };
  });
  const movers = parts.filter((p) => p.mv);
  movers.forEach((p, i) => { p.i = i; p.tw = tween(REST[i]); });

  function draw(p, t) {
    const key = t.toFixed(3);
    if (key === p.last) return;
    p.last = key;
    const b = p.b, pts = [];
    for (const s of p.ring) { pts.push(P(...xf([s.u, s.v, b[4]], b[7], t))); pts.push(P(...xf([s.u, s.v, b[5]], b[7], t))); }
    p.el.sil.setAttribute("d", poly(hull(pts)));
    p.el.cr.setAttribute("d", open(p.inner.map((s) => P(...xf([s.u, s.v, b[5]], b[7], t)))));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of parts) { draw(p, tval(p.tw, now)); if (!tdone(p.tw, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = movers.map((p) => { const b = p.b; return P((b[0] + b[2]) / 2, (b[1] + b[3]) / 2, (b[4] + b[5]) / 2); });
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, i) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = i; } });
    return bd < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    movers.forEach((p, i) => {
      const t = a < 0 ? REST[i] : FALL[Math.min(3, Math.abs(i - a))];
      tset(p.tw, t, now, from < 0 ? 0 : Math.abs(i - from) * stag);
      p.el.sil.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : movers[a].b[8];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

