sinkcaddy.code:
/**
 * Sinkcaddy: a dish drying rack, a low tray with six plates standing in its
 * slots. The pointer picks a plate by where it stands: the plates before it
 * tilt back and the plates from it tilt forward, opening a gap at the chosen
 * plate, staggered from it. At rest the row leans in a loose fan, one plate
 * bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, STEP = 15, R = 24, Z0 = 5, YC = R + 4, FAV = 2, LEAN = 24;
const X1 = (N - 1) * STEP;
const D = Math.PI / 180;
const restA = (j) => (j < FAV ? -8 - 3 * (FAV - 1 - j) : 5 + 3 * (j - FAV));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-26, -2, 0], [X1 + 26, 2 * YC + 2, 0], [X1 + 26, -2, 0], [-26, 2 * YC + 2, 0], [-22, YC, 2 * R + Z0 + 4], [X1 + 22, YC, 2 * R + Z0 + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-24, 0, X1 + 24, 2 * YC, 6, 2);
  put(solid(g), prism(P, front, tr, ti, 0, Z0 - 1));
  // the drain lip at the tray's front
  mk("path", { d: poly([P(X1 + 24, 8, 0), P(X1 + 30, 10, -1), P(X1 + 30, 2 * YC - 10, -1), P(X1 + 24, 2 * YC - 8, 0)]), class: "nf lo" }, g);

  const items = [];
  for (let j = 0; j < N; j++) {
    const grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), cr = mk("path", { class: "nf lo" }, grp);
    items.push({ j, x0: j * STEP, sil, cr, a: tween(restA(j)), last: NaN });
  }

  function pt(it, th, t, r, off) {
    const y = YC + r * Math.cos(t), h = R + r * Math.sin(t);
    return P(it.x0 + h * Math.sin(th) + off * Math.cos(th), y, Z0 + h * Math.cos(th) - off * Math.sin(th));
  }
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const th = deg * D, out = [], inn = [];
    for (let i = 0; i < 40; i++) {
      const t = (i / 40) * 2 * Math.PI;
      out.push(pt(it, th, t, R, 0), pt(it, th, t, R, 1.8));
      inn.push(pt(it, th, t, R - 5, 1.8));
    }
    it.sil.setAttribute("d", poly(hull(out)));
    it.cr.setAttribute("d", poly(inn));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x0, YC, Z0 + R));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 24 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? restA(k) : k < a ? -LEAN + dd * 2 : LEAN - dd * 2;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "plate " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "sinkcaddy",
  means: "A dish rack of standing plates: the plates part at the one under the pointer, tilting back and forward from it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[142, 125], [188, 148], [258, 183], null],
  mount,
});

firescreen.code:
/**
 * Firescreen: a folding three-panel fire screen with arched tops, standing
 * on short feet. The pointer picks a panel by where it stands: a wing swings
 * open flat and the other wing folds in; the middle panel opens both wings
 * part way. At rest the wings stand at uneven folds, the left one bright.
 * The slider is how far the other wing folds in.
 *
 * The pattern: a few hinged parts, one chosen (swing).
 */
const {
  Cam, fit, facing, hull, open, poly, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const W = 42, HM = 60, HS = 50, A = 9, Z0 = 5, D = Math.PI / 180;
const REST = [52, 28];

function outline(w, h, inset) {
  const pts = [[inset, Z0 + inset], [w - inset, Z0 + inset]];
  for (let i = 0; i <= 16; i++) { const s = w - inset - ((w - 2 * inset) * i) / 16; pts.push([s, Z0 + h - inset + A * Math.sin((Math.PI * s) / w)]); }
  return pts;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let fold = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-W, 0, 0], [2 * W, 0, 0], [0, W, 0], [W, W, 0], [-W, 0, HS + A + 6], [2 * W, 0, HS + A + 6], [W / 2, 0, HM + A + 8], [0, W, HS + A + 6], [W, W, HS + A + 6]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  // where a panel's local (s, z) lands: mid stands at y = 0, wings swing toward the viewer
  const map = [
    (s, z, o) => P(s, o, z),
    (s, z, o, f) => P(-s * Math.cos(f) + o * Math.sin(f), s * Math.sin(f) + o * Math.cos(f), z),
    (s, z, o, f) => P(W + s * Math.cos(f) - o * Math.sin(f), s * Math.sin(f) + o * Math.cos(f), z),
  ];
  const panels = [0, 1, 2].map((k) => {
    const grp = mk("g", {}, g), h = k === 0 ? HM : HS;
    const feet = mk("path", { class: "nf" }, grp), sil = mk("path", { class: "sil" }, grp), cr = mk("path", { class: "nf lo" }, grp);
    return { k, h, feet, sil, cr, out: outline(W, h, 0), inn: outline(W, h, 5), a: tween(k === 0 ? 0 : REST[k - 1]), last: NaN };
  });

  function draw(p, deg) {
    if (deg === p.last) return;
    p.last = deg;
    const f = deg * D, m = map[p.k], pts = [];
    for (const [s, z] of p.out) pts.push(m(s, z, 0, f), m(s, z, 2.4, f));
    p.sil.setAttribute("d", poly(hull(pts)));
    p.cr.setAttribute("d", poly(p.inn.map(([s, z]) => m(s, z, 2.4, f))));
    p.feet.setAttribute("d", open([m(4, Z0, 1.2, f), m(4, 0, 1.2, f)]) + open([m(W - 4, Z0, 1.2, f), m(W - 4, 0, 1.2, f)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of panels) { draw(p, tval(p.a, now)); if (!tdone(p.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = panels.map((p) => map[p.k](W / 2, Z0 + p.h / 2, 0, (p.k === 0 ? 0 : REST[p.k - 1]) * D));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 50 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now();
    act = a;
    const t = a < 0 ? REST : a === 0 ? [14, 14] : a === 1 ? [0, fold] : [fold, 0];
    tset(panels[1].a, t[0], now, 0);
    tset(panels[2].a, t[1], now, a === 1 ? 60 : 0);
    panels.forEach((p, k) => p.sil.classList.toggle("hi", k === (a < 0 ? 1 : a)));
    read.textContent = a < 0 ? "rest" : ["mid", "left", "right"][a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { fold = v; if (act > 0) setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "firescreen",
  means: "A folding three-panel fire screen: the wing under the pointer swings open flat while the other wing folds in.",
  rules: [1, 3, 5, 6],
  range: [40, 62, 84],
  tour: [[112, 158], [200, 165], [236, 197], null],
  mount,
});

picturehook.code:
/**
 * Picturehook: a picture rail along a wall, with three framed pictures
 * hanging from hooks on cords. The pointer picks a frame by where it hangs:
 * it swings on its hook, and the frames beside it swing a little the other
 * way, staggered from it. At rest the frames hang a touch crooked, one bright.
 * The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZR = 80, DROP = 14, FAV = 1, SW = 14;
const F = [{ x: 24, w: 34, h: 44, r: 3 }, { x: 76, w: 40, h: 30, r: -4 }, { x: 128, w: 28, h: 36, r: 2 }];
const X1 = 152, D = Math.PI / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -3, ZR + 6], [X1 + 4, 3, ZR + 6], [-4, 3, 10], [X1 + 4, 3, 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [rr, ri] = rings(-2, -4, X1 + 2, 0, 1.5, 0.8);
  put(solid(g), prism(P, front, rr, ri, ZR, ZR + 4));

  const items = F.map((f, k) => {
    const grp = mk("g", {}, g);
    mk("path", { d: open([P(f.x, -2, ZR + 4.5), P(f.x, 1.5, ZR + 4.5), P(f.x, 1.5, ZR + 1), P(f.x, 0.5, ZR - 2)]), class: "nf" }, grp);
    const cord = mk("path", { class: "nf lo" }, grp), sil = mk("path", { class: "sil" }, grp), cr = mk("path", { class: "nf lo" }, grp);
    const out = rrect(-f.w / 2, DROP, f.w / 2, DROP + f.h, 2, 3), inn = rrect(-f.w / 2 + 5, DROP + 5, f.w / 2 - 5, DROP + f.h - 5, 1, 2);
    return { k, f, cord, sil, cr, out, inn, a: tween(f.r), last: NaN };
  });

  function at(it, th, u, w, y) {
    return P(it.f.x + u * Math.cos(th) + w * Math.sin(th), y, ZR - 2 + u * Math.sin(th) - w * Math.cos(th));
  }
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const th = deg * D, pts = [];
    for (const q of it.out) pts.push(at(it, th, q.u, q.v, 0), at(it, th, q.u, q.v, 2.6));
    it.sil.setAttribute("d", poly(hull(pts)));
    it.cr.setAttribute("d", poly(it.inn.map((q) => at(it, th, q.u, q.v, 2.6))));
    const c = it.f.w / 2 - 4;
    it.cord.setAttribute("d", open([at(it, th, -c, DROP + 2, 1.5), at(it, th, 0, 0, 1.5), at(it, th, c, DROP + 2, 1.5)]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.f.x, 1, ZR - DROP - it.f.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 50 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), ang = a < 0 ? it.f.r : dd === 0 ? SW : dd === 1 ? 8 : 3;
      tset(it.a, ang, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "frame " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "picturehook",
  means: "Framed pictures hung on cords from a picture rail: the frame under the pointer swings on its hook, its neighbours sway after it.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[129, 120], [203, 157], [276, 194], null],
  mount,
