beakerstand.code:
/**
 * Retort stand: a heavy base, a tall rod, and a boss clamp holding a round
 * flask by its neck. The pointer slides the clamp up or down the rod to the
 * height it points at, read beside the rod; the flask rides with it and
 * leans a little as it goes. At rest the flask hangs at mid height, bright.
 * The slider is how far the flask leans.
 *
 * The pattern: one part slid along a guide (slide).
 */
const { Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const H = 124, LO = 48, HI = 112, REST = 76, AX = 34, FR = 17;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lean = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-14, -20, 0], [56, 20, 0], [56, -20, 0], [-14, 20, 0], [0, 0, H], [AX, 0, HI + 12], [AX, 0, LO - 40]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-14, -20, 56, 20, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  put(solid(g), prism(P, front, disc(0, 0, 2.4, 16), disc(0, 0, 1.6, 16), 5, H));
  const cg = mk("g", {}, g);
  const boss = solid(cg), arm = mk("path", { class: "nf" }, cg), jaw = solid(cg);
  const neck = mk("path", { class: "sil" }, cg), bulb = mk("path", { class: "sil" }, cg), lip = mk("path", { class: "nf lo" }, cg);
  const h = spring(REST, { k: 80, c: 16 });
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    const tilt = ((z - REST) / (HI - LO)) * lean * 0.5;
    put(boss, prism(P, front, ...rings(-5, -5, 5, 5, 1.5, 1), z - 5, z + 5));
    arm.setAttribute("d", seg(P(5, 0, z + 1.5), P(AX - 4, 0, z + 1.5)) + seg(P(5, 0, z - 1.5), P(AX - 4, 0, z - 1.5)));
    put(jaw, prism(P, front, ...rings(AX - 7, -7, AX + 7, 7, 3, 1), z - 3, z + 3));
    const nb = z - 8, cx = AX + Math.sin(tilt) * 26, cz = nb - FR * 0.85;
    neck.setAttribute("d", poly(hull(ringAt(P, disc(AX, 0, 4.5, 20), z + 10).concat(ringAt(P, disc(AX + Math.sin(tilt) * 8, 0, 4.5, 20), nb)))));
    const pts = [];
    for (let i = -4; i <= 4; i++) { const t = i / 4.2; pts.push(...ringAt(P, disc(cx, 0, FR * Math.sqrt(1 - t * t)), cz + FR * t)); }
    bulb.setAttribute("d", poly(hull(pts)));
    lip.setAttribute("d", poly(ringAt(P, disc(cx, 0, FR * 0.8, 32), cz - 6)));
    neck.parentNode.appendChild(bulb); neck.parentNode.appendChild(lip); neck.parentNode.appendChild(jaw.g); 
  }
  const B = register(stage, (dt) => { const m = stepS(h, dt); draw(h.x); return m; });
  bag.add(B.unregister);

  const rod = P(0, 0, 0)[0];
  function aim(p) {
    let t = REST;
    if (p && Math.abs(p[0] - rod) < 110) {
      let best = REST, bd = Infinity;
      for (let z = LO - 30; z <= HI + 30; z += 1) { const d = Math.abs(P(AX / 2, 0, z)[1] - p[1]); if (d < bd) { bd = d; best = z; } }
      if (bd < 4) t = clamp(best, LO, HI);
    }
    h.t = t;
    bulb.classList.toggle("hi", true);
    read.textContent = p && t !== REST ? "h" + Math.round(t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lean = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "beakerstand",
  means: "A retort stand: the clamp slides up or down the rod to the height of the pointer, carrying its round flask.",
  rules: [1, 3, 5, 6],
  range: [0, 0.5, 1],
  tour: [[194, 166], [194, 60], [194, 56], null],
  mount,
});

mapstand.code:
/**
 * Wall map: a rolled map on a stand, its roller case on two posts, the sheet
 * hanging below with a pull ring at its foot. The pointer pulls the sheet
 * down, or lets it roll up, to the height it points at. At rest the map
 * hangs half down, bright. The slider is how much graticule the map shows.
 *
 * The pattern: one part slid along a guide (slide).
 */
const { Cam, clamp, fit, facing, poly, prism, proj, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const W = 96, TOP = 120, LO = 14, HI = 100, REST = 34;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let grid = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-14, -14, 0], [W + 14, 14, 0], [W + 14, -14, 0], [-14, 14, 0], [-10, 0, TOP + 8], [W + 10, 0, TOP + 8]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const x of [-8, W + 8]) {
    put(solid(g), prism(P, front, ...rings(x - 7, -12, x + 7, 12, 4, 1.5), 0, 4));
  }
  put(solid(g), prism(P, front, ...rings(-10, -2, -6, 2, 1, 0.6), 4, TOP));
  const sheet = solid(g), lines = mk("path", { class: "nf lo" }, g), ring = mk("path", { class: "nf" }, g);
  put(solid(g), prism(P, front, ...rings(-6, -5, W + 6, 5, 5, 1.5), TOP - 4, TOP + 6));
  put(solid(g), prism(P, front, ...rings(W + 6, -2, W + 10, 2, 1, 0.6), 4, TOP));
  const h = spring(REST, { k: 70, c: 15 });
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const zb = TOP - 4 - d;
    put(sheet, prism(P, front, ...rings(2, -1, W - 2, 1, 0.8, 0.4), zb, TOP - 4));
    let s = "";
    const n = Math.round(3 + grid * 5);
    for (let i = 1; i < n; i++) { const x = 2 + ((W - 4) * i) / n; s += seg(P(x, 1.2, zb + 3), P(x, 1.2, TOP - 6)); }
    for (let z = TOP - 16; z > zb + 4; z -= 14) s += seg(P(5, 1.2, z), P(W - 5, 1.2, z));
    lines.setAttribute("d", s);
    const c = W / 2;
    ring.setAttribute("d", seg(P(c, 1, zb), P(c, 1, zb - 4)) + poly([[0, 0], [1, 0], [1, 1]].map(() => P(c, 1, zb - 7)).concat([P(c - 4, 1, zb - 4), P(c - 4, 1, zb - 10), P(c + 4, 1, zb - 10), P(c + 4, 1, zb - 4)]).slice(3)));
  }
  const B = register(stage, (dt) => { const m = stepS(h, dt); draw(h.x); return m; });
  bag.add(B.unregister);

  const xl = P(0, 0, 0)[0], xr = P(W, 0, 0)[0];
  function aim(p) {
    let t = REST;
    if (p) {
      const u = clamp((p[0] - xl) / (xr - xl), 0, 1);
      if (p[0] > xl - 20 && p[0] < xr + 20) {
        let best = REST, bd = Infinity;
        for (let d = 0; d <= TOP; d++) { const e = Math.abs(P(u * W, 0, TOP - 4 - d)[1] - p[1]); if (e < bd) { bd = e; best = d; } }
        if (bd < 4) t = clamp(best, LO, HI);
      }
    }
    h.t = t;
    sheet.sil.classList.toggle("hi", true);
    read.textContent = p && t !== REST ? Math.round((t / HI) * 100) + "%" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { grid = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "mapstand",
  means: "A pull-down wall map on a stand: the sheet rolls down or up to the height of the pointer, its pull ring leading.",
  rules: [1, 3, 5, 6],
  range: [0, 0.5, 1],
  tour: [[200, 95], [200, 236], [200, 233], null],
  mount,
});

tennisnet.code:
/**
 * Tennis net crank: a net strung between two posts, a winder crank on the
 * near post. The pointer over the net turns the crank and the net draws taut,
 * the cord rising from the crank outward, staggered by distance. At rest the
 * net sags and the crank is bright. The slider is the stagger.
 */
const {
  Cam, circ, fit, facing, open, prism, proj, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 130, H = 34, M = 12, SAG = 14, TIGHT = 1, AR = 8;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [L + 12, 4, 0], [0, 0, H + 4], [L, 0, H + 4], [L + 6, 0, H + AR], [L + 6, 0, H - 2 * AR]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 4, 24), disc(0, 0, 3, 24), 0, 1.5));
  put(solid(g), prism(P, front, disc(0, 0, 2, 16), null, 1.5, H + 2));
  const mesh = mk("path", { class: "nf lo" }, g), band = mk("path", { class: "nf sil" }, g);
  put(solid(g), prism(P, front, disc(L, 0, 4, 24), disc(L, 0, 3, 24), 0, 1.5));
  put(solid(g), prism(P, front, disc(L, 0, 2, 16), null, 1.5, H + 2));
  const drum = solid(g);
  put(drum, prism(P, front, disc(L + 3.5, 0, 3, 20), disc(L + 3.5, 0, 2, 20), H - 9, H - 3));
  const crank = mk("path", { class: "nf sil" }, g);
  const knob = mk("ellipse", { class: "dot m", rx: 2.2, ry: 1.6 }, g);

  const tw = [];
  for (let i = 0; i <= M; i++) tw.push(tween(SAG));
  let last = "";
  function top(i, s) { const f = (2 * i) / M - 1; return H - s * (1 - f * f); }
  function draw(now) {
    const s = tw.map((t) => tval(t, now)), key = s.map((v) => v.toFixed(2)).join();
    if (key === last) return;
    last = key;
    const xs = s.map((_, i) => (i * L) / M), hs = s.map((v, i) => top(i, v));
    let d = "";
    for (let i = 1; i < M; i++) d += seg(P(xs[i], 0, 2), P(xs[i], 0, hs[i]));
    for (const f of [0.06, 0.3, 0.55, 0.78]) d += open(xs.map((x, i) => P(x, 0, Math.max(2, f * hs[i]))));
    mesh.setAttribute("d", d);
    band.setAttribute("d", open(xs.map((x, i) => P(x, 0, hs[i]))) + open(xs.map((x, i) => P(x, 0, hs[i] - 2.5))));
    const a = ((SAG - s[M]) / (SAG - TIGHT)) * Math.PI * 2.4 + 0.6, cz = H - 6;
    const tip = [L + 8, AR * Math.cos(a), cz + AR * Math.sin(a)];
    crank.setAttribute("d", seg(P(L + 3.5, 0, cz), P(L + 8, 0, cz)) + seg(P(L + 8, 0, cz), P(...tip)) + seg(P(...tip), P(tip[0] + 5, tip[1], tip[2])));
    const k = P(tip[0] + 5, tip[1], tip[2]);
    knob.setAttribute("cx", k[0]); knob.setAttribute("cy", k[1]);
  }

  const B = register(stage, (_dt, now) => { draw(now); return tw.some((t) => !tdone(t, now)); });
  bag.add(B.unregister);

  const pts = [P(0, 0, 0), P(L, 0, 0), P(0, 0, H), P(L, 0, H)];
  const x0 = Math.min(...pts.map((p) => p[0])) - 8, x1 = Math.max(...pts.map((p) => p[0])) + 14;
  const y0 = Math.min(...pts.map((p) => p[1])) - 10, y1 = Math.max(...pts.map((p) => p[1])) + 8;
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    const now = performance.now();
    tw.forEach((t, i) => tset(t, v ? TIGHT : SAG, now, (M - i) * stag));
    crank.classList.toggle("hi", !v);
    band.classList.toggle("hi", v);
    read.textContent = v ? "taut" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => set(sx > x0 && sx < x1 && sy > y0 && sy < y1),
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "tennisnet",
  means: "A tennis net between two posts: the pointer turns the winder crank and the sagging net draws taut, cord rising from the crank out.",
  rules: [1, 2, 5, 8],
  range: [0, 30, 60],
  tour: [[194, 141], [140, 116], [250, 186], null],
  mount,
});

squashracket.code:
/**
 * Racket press: a racket lying in a wooden press, the press's top board
 * hinged at the throat. The pointer over the press swings the board open to
 * show the strung head; at rest the board lies nearly shut and is bright.
 * The slider is how far it opens.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const A = 26, Bh = 20, X0 = -32, X1 = 32, Y = 26, Z = 6, T = 3;
const ell = (a, b, n = 40) => { const r = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; r.push([a * Math.cos(t), b * Math.sin(t)]); } return r; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wide = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-74, 0, 0], [X1, -Y, 0], [X1, Y, 0], [X0, -Y, 0], [X0 + 4, Y, 70], [X0 + 4, -Y, 70]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(X0, -Y, X1, Y, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, Z - 2));
  put(solid(g), prism(P, front, rings(-76, -2.6, -A + 1, 2.6, 2.4, 0.8)[0], rings(-76, -2.6, -A + 1, 2.6, 2.4, 0.8)[1], Z - 2, Z));
  const head = mk("path", { class: "sil" }, g);
  head.setAttribute("d", poly(ell(A, Bh).map(([x, y]) => P(x, y, Z))));
  let s = "";
  for (let i = -3; i <= 3; i++) { const y = i * 5, x = A * Math.sqrt(1 - (y / Bh) ** 2) - 2; s += seg(P(-x, y, Z), P(x, y, Z)); }
  for (let i = -4; i <= 4; i++) { const x = i * 5, y = Bh * Math.sqrt(1 - (x / A) ** 2) - 2; s += seg(P(x, -y, Z), P(x, y, Z)); }
  mk("path", { class: "nf lo", d: s }, g);
  const board = solid(g);
  const face = rrect(0, -Y, X1 - X0, Y, 6, 4), inner = rrect(2, -Y + 2, X1 - X0 - 2, Y - 2, 4, 4);
  const tw = tween(0.12);
  let last = NaN;
  function draw(f) {
    if (f === last) return;
    last = f;
    const a = f * (Math.PI / 2) * 0.95, c = Math.cos(a), sn = Math.sin(a);
    const W = (u, v, w) => P(X0 + u * c - w * sn, v, Z + u * sn + w * c);
    const pts = [];
    for (const q of face) pts.push(W(q.u, q.v, 0), W(q.u, q.v, T));
    board.sil.setAttribute("d", poly(hull(pts)));
    board.cr.setAttribute("d", poly(inner.map((q) => W(q.u, q.v, T))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const box = [P(-76, 0, 0), P(X1, -Y, 0), P(X1, Y, 0), P(X0, 0, 40)];
  const x0 = Math.min(...box.map((p) => p[0])), x1 = Math.max(...box.map((p) => p[0]));
  const y0 = Math.min(...box.map((p) => p[1])), y1 = Math.max(...box.map((p) => p[1]));
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? wide : 0.12, performance.now(), 0);
    board.sil.classList.toggle("hi", !v);
    head.classList.toggle("hi", v);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(sx > x0 && sx < x1 && sy > y0 && sy < y1), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wide = v; if (on) { on = null; set(true); } }, destroy: bag.dispose };
}

hairline({
  name: "squashracket",
  means: "A squash racket in a wooden press: the pointer swings the top board open on its hinge to show the strung head.",
  rules: [1, 3, 5, 8],
  range: [0.6, 1, 1],
  tour: [[215, 226], [250, 210], [150, 200], null],
  mount,
});

lacrosse.code:
/**
 * Lacrosse goal: a square pipe frame, base pipes running back to a point, a
 * deep net hung between them and a ball in front. The pointer along the mouth
 * swings the net back into a pocket where it points, falling off with
 * distance. At rest the net hangs slack and the ball is bright. The slider is
 * how deep the pocket goes.
 */
const {
  Cam, circ, fit, facing, open, prism, proj, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 30, H = 34, D = 40, K = 12;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let depth = value;
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-D - 26, 0, 0], [0, -W, 0], [0, W, 0], [0, -W, H + 2], [0, W, H + 2], [22, 0, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const net = mk("path", { class: "nf lo" }, g);
  const pipes = mk("path", { class: "nf sil" }, g);
  pipes.setAttribute("d", seg(P(0, -W, 0), P(-D, 0, 0)) + seg(P(-D, 0, 0), P(0, W, 0)) + seg(P(0, -W, H), P(0, W, H)) + seg(P(0, -W, H - 1.6), P(0, W, H - 1.6)));
  put(solid(g), prism(P, front, disc(0, -W, 1.6), null, 0, H));
  put(solid(g), prism(P, front, disc(0, W, 1.6), null, 0, H));
  const ball = mk("path", { class: "sil" }, g);

  const sp = spring(0), dp = spring(0.25);
  let aim = 0, last = "";
  function draw() {
    const key = sp.x.toFixed(3) + dp.x.toFixed(3);
    if (key === last) return;
    last = key;
    const pull = (y) => 6 + dp.x * 26 * Math.exp(-((y - sp.x) ** 2) / 260);
    let d = "";
    const rows = [];
    for (let i = 0; i <= K; i++) {
      const y = -W + (2 * W * i) / K, ry = 1 - Math.abs(y) / W, pts = [];
      for (let j = 0; j <= 6; j++) {
        const t = j / 6, s = Math.sin(t * Math.PI);
        pts.push(P(-D * ry * t - pull(y) * s * ry - 2 * s, y * (1 - 0.2 * s), H * (1 - t) * (1 - 0.15 * s)));
      }
      rows.push(pts);
      d += open(pts);
    }
    for (let j = 1; j < 6; j++) d += open(rows.map((r) => r[j]));
    net.setAttribute("d", d);
    const bx = 12 - dp.x * 6, by = sp.x * 0.6, R = 4, pts = [];
    for (let a = 0; a < 24; a++) { const t = (a / 24) * Math.PI * 2; pts.push(P(bx, by + R * Math.cos(t) * 0.7071, R + R * Math.sin(t)), P(bx + R * Math.cos(t) * 0.7071, by, R + R * Math.sin(t))); }
    const c = P(bx, by, R), rr = Math.max(...pts.map((p) => Math.hypot(p[0] - c[0], p[1] - c[1])));
    ball.setAttribute("d", `M${c[0] - rr},${c[1]}a${rr},${rr} 0 1,0 ${2 * rr},0a${rr},${rr} 0 1,0 ${-2 * rr},0Z`);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt) | stepS(dp, dt); draw(); return !!m; });
  bag.add(B.unregister);

  function set(y) {
    const on = y !== null;
    sp.t = on ? y : 0;
    dp.t = on ? depth : 0.25;
    ball.classList.toggle("hi", !on);
    net.classList.toggle("hi", on);
    net.classList.toggle("lo", !on);
    read.textContent = on ? "pocket " + (Math.round(((y + W) / (2 * W)) * 4) + 1) : "rest";
    aim = y;
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], H / 2);
      set(x > -D - 20 && x < 24 && Math.abs(y) < W + 10 ? Math.max(-W, Math.min(W, y)) : null);
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { depth = v; if (aim !== null) set(aim); }, destroy: bag.dispose };
}

