  name: "raclette",
  means: "A raclette grill: the pan under the pointer slides out from beneath the hot plate, and its neighbours ease out a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[135, 137], [200, 170], [265, 203], null],
  mount,
