  mount,
});

mistnozzle.code:
/**
 * Mist sprinkler: a riser pipe on a ground flange carrying a spinning head of three arms, each ending in a nozzle that sheds a dashed mist. The pointer's x turns the head; at rest it sits part-turned, arms bright. The slider is how far it turns.
 *
 * The pattern: one part turning on a hinge, driven by the pointer's x (a continuous spring).
 */
const B = (x0, y0, z0, x1, y1, z1) => [x0, y0, z0, x1, y1, z1];
const S = 2.0, AX = "z", O = [0, 0, 0], LO = 0, REST = 25, RANGE = [60, 120, 180], SORT = true, UNIT = "°";
const arm = (off) => ({ mv: 1, hi: 1, off, c: [30, 0, 0], lcls: "dash nf",
  lines: [[[42, 0, 52], [50, -8, 4]], [[42, 0, 52], [54, 6, 4]]],
  boxes: [B(5, -2, 60, 44, 2, 64), B(38, -3.5, 52, 46, 3.5, 60)] });
