function turn(p, ax, o, a) {
  const c = Math.cos(a), s = Math.sin(a), [i, j] = ax === "x" ? [1, 2] : ax === "y" ? [0, 2] : [0, 1];
  const q = p.slice(), di = p[i] - o[i], dj = p[j] - o[j];
  q[i] = o[i] + di * c - dj * s; q[j] = o[j] + di * s + dj * c;
