      const q = corners(b).map((c) => P(...pose(c, part, a)));
      el.sils[k].setAttribute("d", poly(hull(q)));
      el.faces[k].setAttribute("d", FACES.map((f) => f.map((i) => q[i])).filter((f) => Math.sign(area(f)) === vis).map(poly).join(""));
    });
  }
