    { c: box(3, 0, 26, 7, 30, 34) },
    { c: r(box(7, 3, 28, 48, 7, 32)) },
    { c: r(box(7, 23, 28, 48, 27, 32)) },
    { c: r(box(48, 3, 28, 53, 27, 32)), hi: 1 },
  ];
