  const SG = Math.sign(area(FACES[1].map((i) => P(...box(0, 0, 0, 1, 1, 1)[i]))));
  const g = mk("g", {}, svg);
  const els = parts(0).map(() => { const grp = mk("g", {}, g); return { grp, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp) }; });
