tiddly.code:
/**
 * Tiddlywinks cup: a flared cup on the mat, five winks scattered round it
 * and a squidger lying by. The pointer picks the wink nearest it on the mat:
 * that wink lights and the cup tips toward it, as if to take the shot. At
 * rest the cup leans a little toward one wink, bright. The slider is the tip.
 *
 * The pattern: one of many on the ground (terrain pick), one part turning
 * to answer.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 15, RT = 19, CH = 26, FAV = 0, REST = 8;
const WINKS = [[30, 30], [-34, 16], [38, -10], [8, -40], [-12, 42]];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-46, -46, 0], [46, 46, 0], [46, -46, 0], [-46, 46, 0], [0, 0, CH + 4]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g), cupg = mk("g", {}, g), fore = mk("g", {}, g);
  const sq = disc(-30, -26, 9), sqi = disc(-30, -26, 7.4);
  put(solid(back), prism(P, front, sq, sqi, 0, 2.4));
  mk("path", { class: "nf lo", d: poly(ringAt(P, disc(-30, -26, 2.5, 16), 2.4)) }, back);
  const winks = WINKS.map(([x, y], k) => {
    const s = solid(x + y < 0 ? back : fore);
    put(s, prism(P, front, disc(x, y, 5), disc(x, y, 4), 0, 1.4));
    return s;
  });
  const sil = mk("path", { class: "sil" }, cupg), rim = mk("path", { class: "nf" }, cupg), lip = mk("path", { class: "nf lo" }, cupg);
  const base = circ(R, 32), top = circ(RT, 40), topIn = circ(RT - 1.8, 40);
  const ph = tween(Math.atan2(WINKS[FAV][1], WINKS[FAV][0])), th = tween(REST);
  let last = "";
  function W(q, z, d, e, c, s) {
    const sd = q.u * d[0] + q.v * d[1], te = q.u * e[0] + q.v * e[1];
    const s2 = R + (sd - R) * c + z * s, z2 = -(sd - R) * s + z * c;
    return P(s2 * d[0] + te * e[0], s2 * d[1] + te * e[1], z2);
  }
  function draw(phi, deg) {
    const key = phi.toFixed(4) + deg.toFixed(3);
    if (key === last) return;
    last = key;
    const d = [Math.cos(phi), Math.sin(phi)], e = [-d[1], d[0]], t = (deg * Math.PI) / 180, c = Math.cos(t), s = Math.sin(t);
    const b = base.map((q) => W(q, 0, d, e, c, s)), tp = top.map((q) => W(q, CH, d, e, c, s));
    sil.setAttribute("d", poly(hull(b.concat(tp))));
    rim.setAttribute("d", poly(tp));
    lip.setAttribute("d", poly(topIn.map((q) => W(q, CH, d, e, c, s))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ph, now), tval(th, now)); return !tdone(ph, now) || !tdone(th, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    let best = -1, bd = 22;
    WINKS.forEach(([wx, wy], k) => { const dd = Math.hypot(wx - x, wy - y); if (dd < bd) { bd = dd; best = k; } });
    return best;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), k = a < 0 ? FAV : a;
    act = a;
    let to = Math.atan2(WINKS[k][1], WINKS[k][0]);
    const cur = ph.t !== undefined ? ph.t : tval(ph, now);
    while (to - cur > Math.PI) to -= 2 * Math.PI;
    while (to - cur < -Math.PI) to += 2 * Math.PI;
    tset(ph, to, now, 0);
    tset(th, a < 0 ? REST : tip, now, 0);
    winks.forEach((w, i) => w.sil.classList.toggle("hi", i === k));
    read.textContent = a < 0 ? "rest" : "wink " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; if (act >= 0) tset(th, v, performance.now(), 0); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "tiddly",
  means: "A tiddlywinks cup among scattered winks: the wink under the pointer lights and the cup tips toward it.",
  rules: [1, 3, 4, 5],
  range: [12, 30, 40],
  tour: [[108, 149], [288, 136], [101, 193], null],
  mount,
});

capsuletoy.code:
/**
 * Capsule toy: a gacha machine, a square base with a chute and a crank, a
 * glass globe full of two-part capsules on a collar. The pointer over the
 * machine turns the crank: the capsules churn round inside the globe and one
 * rolls out into the chute. At rest the crank handle is bright. The slider
 * is how far the capsules turn.
 *
 * The pattern: one thing that turns (a tween), its contents re-sorted by
 * depth every frame into fixed slots.
 */
const {
  Cam, circ, fillet, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BH = 34, GZ = 58, GR = 24, CR = 6.2;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const SEEDS = [];
for (let k = 0; k < 5; k++) SEEDS.push({ r: 13, a: k * 72 + 10, z: 46, w: 1 });
for (let k = 0; k < 4; k++) SEEDS.push({ r: 11, a: k * 90 + 50, z: 59, w: -0.8 });
SEEDS.push({ r: 3, a: 0, z: 70, w: 0.5 });

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let turn = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-26, -26, 0], [26, 36, 0], [26, -26, 0], [-26, 36, 0], [0, 0, GZ + GR + 7]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-24, -24, 24, 24, 8, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  const chute = fillet([[-9, 5], [9, 5], [9, 18], [-9, 18]], [2, 2, 5, 5], 4).map(([x, z]) => P(x, 24, z));
  mk("path", { class: "nf lo", d: poly(chute) }, g);
  const dialPts = circ(7.5, 28).map((q) => P(24, q.u, 22 + q.v));
  mk("path", { class: "nf lo", d: poly(dialPts) }, g);
  const bar = mk("path", { class: "nf" }, g);
  put(solid(g), prism(P, front, disc(0, 0, 19), disc(0, 0, 17.4), BH, BH + 5));
  // the globe: a sphere above the collar, glass, so the capsules show
  const lat = [];
  for (let z = BH + 5; z <= GZ + GR; z += 2) { const rr = Math.sqrt(Math.max(0, GR * GR - (z - GZ) ** 2)); if (rr > 0.5) lat.push(...ringAt(P, disc(0, 0, rr, 36), z)); }
  lat.push(P(0, 0, GZ + GR));
  mk("path", { class: "sil nf", d: poly(hull(lat)) }, g);
  const slots = SEEDS.map(() => ({ s: mk("path", { class: "nf" }, g), m: mk("path", { class: "nf lo" }, g) }));
  put(solid(g), prism(P, front, disc(0, 0, 6), disc(0, 0, 4.6), GZ + GR - 1.5, GZ + GR + 4));
  const out = { s: mk("path", { class: "nf" }, g), m: mk("path", { class: "nf lo" }, g) };

  function capsule(el, x, y, z) {
    const pts = [];
    for (const dz of [-CR, -CR * 0.7, 0, CR * 0.7, CR]) { const rr = Math.sqrt(Math.max(0, CR * CR - dz * dz)); pts.push(...ringAt(P, disc(x, y, Math.max(rr, 0.3), 20), z + dz)); }
    el.s.setAttribute("d", poly(hull(pts)));
    el.m.setAttribute("d", open(ringAt(P, run(disc(x, y, CR, 24), front), z)));
  }
  const rot = tween(0), crank = tween(0), roll = tween(0);
  let last = "";
  function draw(a, c, o) {
    const key = a.toFixed(3) + c.toFixed(3) + o.toFixed(4);
    if (key === last) return;
    last = key;
    const cs = SEEDS.map((q) => { const t = ((q.a + a * q.w) * Math.PI) / 180; return [q.r * Math.cos(t), q.r * Math.sin(t), q.z]; });
    cs.sort((p, q) => 0.612 * (p[0] + p[1]) + 0.5 * p[2] - (0.612 * (q[0] + q[1]) + 0.5 * q[2]));
    cs.forEach((p, i) => capsule(slots[i], ...p));
    const t = (c * Math.PI) / 180, ct = Math.cos(t), st = Math.sin(t);
    const shape = fillet([[-11, -2.4], [11, -2.4], [11, 2.4], [-11, 2.4]], [2.2, 2.2, 2.2, 2.2], 3);
    bar.setAttribute("d", poly(shape.map(([u, v]) => P(24.6, u * ct - v * st, 22 + u * st + v * ct))));
    if (o < 0.02) { out.s.setAttribute("d", ""); out.m.setAttribute("d", ""); }
    if (o >= 0.02) capsule(out, 0, 22 + 12 * o, CR + 0.2);
  }
  const B = register(stage, (_dt, now) => {
    draw(tval(rot, now), tval(crank, now), tval(roll, now));
    return !tdone(rot, now) || !tdone(crank, now) || !tdone(roll, now);
  });
  bag.add(B.unregister);

  const gc = P(0, 0, GZ);
  function hit([sx, sy]) {
    if (Math.hypot(sx - gc[0], sy - gc[1]) < GR * C.S * 1.05) return 1;
    for (const z of [0, BH]) { const [x, y] = unproj(C, sx, sy, z); if (Math.abs(x) < 28 && Math.abs(y) < 28) return 1; }
    return -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    tset(rot, a < 0 ? 0 : turn, now, 0);
    tset(crank, a < 0 ? 0 : 300, now, 0);
    tset(roll, a < 0 ? 0 : 1, now, a < 0 ? 0 : 200);
    bar.classList.toggle("hi", a < 0);
    out.s.classList.toggle("hi", a >= 0);
    read.textContent = a < 0 ? "rest" : "turn";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { turn = v; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "capsuletoy",
  means: "A gacha capsule machine: the pointer turns its crank, the capsules churn in the globe and one rolls out the chute.",
  rules: [1, 4, 5, 6],
  range: [50, 110, 160],
  tour: [[208, 112], [249, 207], [168, 232], null],
  mount,
});

tokentray.code:
/**
 * Token box: a game's token box, three compartments holding round tokens,
 * cubes and a stack of chips, under a hinged lid. The pointer over the box
 * swings the lid open on its back hinge. At rest the lid sits ajar, bright.
 * The slider is how far the lid opens.
 *
 * The pattern: one thing that opens (a hinge turned by a tween).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 84, Y1 = 50, H = 20, T = 5, REST = 12;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, -16, 0], [0, Y1, 0], [0, -16, H + Y1 + 8], [X1, -16, H + Y1 + 8]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, X1, Y1, 8, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // the tray: a rim inset on the top, two walls, and what each cell holds
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(3, 3, X1 - 3, Y1 - 3, 6, 8), H)) + seg(P(30, 3, H), P(30, Y1 - 3, H)) + seg(P(57, 3, H), P(57, Y1 - 3, H)) }, g);
  for (const [x, y] of [[10, 11], [20, 13], [12, 26], [22, 30], [14, 40]]) put(solid(g), prism(P, front, disc(x, y, 4.2), disc(x, y, 3.2), H, H + 1.6));
  for (const [x, y] of [[36, 10], [46, 18], [37, 30], [47, 38]]) { const [r, i] = rings(x - 3.5, y - 3.5, x + 3.5, y + 3.5, 1.4, 0.7); put(solid(g), prism(P, front, r, i, H, H + 6)); }
  for (const [x, y, n] of [[70, 14, 4], [68, 34, 2]]) put(solid(g), prism(P, front, disc(x, y, 7, 28), disc(x, y, 5.8, 28), H, H + 1.4 * n));

  const lid = mk("path", { class: "sil hi" }, g), lcr = mk("path", { class: "nf lo" }, g);
  const outer = rrect(-1, -1, X1 + 1, Y1 + 1, 9, 8), inner = rrect(2, 2, X1 - 2, Y1 - 2, 7, 8);
  const ang = tween(REST);
  let last = NaN;
  function L(q, dz, c, s) { const yy = q.v + 1; return P(q.u, -1 + yy * c - dz * s, H + 0.4 + yy * s + dz * c); }
  function draw(a) {
    if (a === last) return;
    last = a;
    const t = (a * Math.PI) / 180, c = Math.cos(t), s = Math.sin(t);
    const pts = outer.map((q) => L(q, 0, c, s)).concat(outer.map((q) => L(q, T, c, s)));
    lid.setAttribute("d", poly(hull(pts)));
    const up = -0.612 * s + 0.5 * c > 0;
    lcr.setAttribute("d", poly(inner.map((q) => L(q, up ? T : 0, c, s))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    for (const z of [0, H]) { const [x, y] = unproj(C, sx, sy, z); if (x > -6 && x < X1 + 6 && y > -6 && y < Y1 + 6) return 1; }
    return -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a < 0 ? REST : reach, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "open";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

