  read.textContent = "rest";
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 0); aim(clamp(x - y, -reach, reach)); },
    leave: () => aim(REST),
  }));
