ducklingbox.code:
/**
 * Brooder: a low chick crate whose hinged lid carries a heat lamp. The lid tips up off the crate at the pointer; at rest it stands ajar, bright.
 *
 * The pattern: one part answers (open).
 */
const { Cam, fit, proj, rrect, hull, poly, open, lerp, rad, tween, tset, tval, tdone, mk, pointer, register, disposer, solid } = HL;

