  name: "speakerbox",
  means: "A smart speaker: the pointer lifts its light ring cap clear of the grille body.",
  rules: [1, 3, 5, 6],
  range: [0, 0.6, 1],
  tour: [[200, 121], [200, 180], [170, 150], null],
  mount,
