    put(top, prism(P, front, disc(dx, 0, R + 1), disc(dx, 0, R - 1), b - 4, b + 12));
    put(neck, prism(P, front, disc(dx, 0, R * 0.62), disc(dx, 0, R * 0.5), b + 12, b + 20));
