  rules: [1, 5, 6, 8],
  range: [45, 70, 80],
  tour: [[200, 217], [168, 200], [234, 236], null],
  mount,
});

tapedrive.code:
/**
 * Tape drive: a desktop drive, a rounded box with a slot and an activity light
 * on its front, and a tape cartridge in the slot. The pointer over the drive
 * slides the cartridge out toward the hand; at rest it sticks out a little,
 * bright. The slider is how far it ejects.
 */
const {
  Cam, fillet, fit, flatDot, place, poly, prism, proj, rings, rrect, seg, unproj, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 50, H = 26, CX0 = 9, CX1 = 55, CZ0 = 7, CZ1 = 19, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxO = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [W, D + 60, 0], [W, 0, 0], [0, D + 60, 0], [0, 0, H], [W, 0, H]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [r0, i0] = rings(0, 0, W, D, 6, 1.6);
  const body = solid(g);
  put(body, prism(P, front, r0, i0, 0, H));
  const slot = fillet([[CX0 - 2, CZ0 - 1.5], [CX1 + 2, CZ0 - 1.5], [CX1 + 2, CZ1 + 1.5], [CX0 - 2, CZ1 + 1.5]], [2, 2, 2, 2], 4).map(([x, z]) => P(x, D, z));
  mk("path", { class: "nf lo", d: poly(slot) + seg(P(10, 0, H), P(10, D, H)) }, body.g);
  place(flatDot(body.g, C, 1.6, "dot m"), P(W - 5, D, H - 4));

  const cart = solid(g);
  cart.sil.classList.add("hi");
  const out = tween(REST);
  let last = NaN;
  function draw(o) {
    if (o === last) return;
    last = o;
    const [r, i] = rings(CX0, D - 1, CX1, D + o, 2.5, 1.4);
    put(cart, prism(P, front, r, i, CZ0, CZ1));
  }
  const notch = mk("path", { class: "nf lo" }, cart.g);
  function drawNotch(o) {
    notch.setAttribute("d", o > 10 ? poly(rrect(CX0 + 8, D + o - 9, CX1 - 8, D + o - 4, 1.5, 3).map((q) => P(q.u, q.v, CZ1))) : "");
  }

  const B = register(stage, (_dt, now) => { const o = tval(out, now); draw(o); drawNotch(o); return !tdone(out, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -6 && x < W + 6 && y > -6 && y < D + 6 ? 1 : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(out, a < 0 ? REST : maxO, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "eject";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxO = v; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "tapedrive",
  means: "A desktop tape drive: the pointer over it slides the tape cartridge out of the front slot toward the hand.",
  rules: [1, 5, 6, 8],
  range: [30, 46, 60],
  tour: [[258, 108], [236, 84], [272, 150], null],
  mount,
});

kalimba.code:
/**
 * Kalimba: a wooden board with a fan of metal tines, long in the middle and
 * shorter to each side. The pointer picks a tine by where it stands: it
 * springs up off the bridge and its neighbours rise a little, staggered.
 * At rest one tine is raised, bright. The slider is the stagger.
 */
const { Cam, fit, facing, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 7, STEP = 14, W = 8, BX = N * STEP + 16, BY = 90, BZ = 14, LIFT = 26, FAV = 2;
const LEN = [44, 54, 64, 72, 62, 52, 42];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [BX, BY, 0], [BX, 0, 0], [0, BY, 0], [BX / 2, BY, BZ + LIFT + 8], [0, 0, BZ + LIFT + 8]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, BX, BY, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [hr, hi] = rings(BX / 2 - 14, 10, BX / 2 + 14, 38, 14, 4);
  put(solid(g), prism(P, front, hr, hi, BZ, BZ + 0.6));
  const [gr, gi] = rings(6, BY - 22, BX - 6, BY - 16, 1, 1);
  put(solid(g), prism(P, front, gr, gi, BZ, BZ + 4));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 8 + k * STEP + (STEP - W) / 2, grp = mk("g", {}, g);
    items.push({ k, x, grp, z: tween(k === FAV ? LIFT * 0.7 : 0), last: NaN });
  }

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    it.grp.replaceChildren();
    const y1 = BY - 10, y0 = y1 - LEN[it.k], z = BZ + 4;
    const tilt = (y) => z + lift * (y1 - y) / LEN[it.k];
    const corners = [[it.x, y0], [it.x + W, y0], [it.x + W, y1], [it.x, y1]];
    const top = corners.map(([x, y]) => P(x, y, tilt(y) + 2.5)), bot = corners.map(([x, y]) => P(x, y, tilt(y)));
    const pts = top.concat(bot);
    const hullp = HL.hull(pts);
    const s = mk("path", { d: HL.poly(hullp), class: "sil" + (it.hi ? " hi" : "") }, it.grp);
    it.sil = s;
    mk("path", { d: HL.poly(top), class: "nf lo" }, it.grp);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x + W / 2, BY - 10 - LEN[it.k] / 2, BZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 20 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? LIFT * 0.7 : 0) : dd === 0 ? LIFT : dd === 1 ? 8 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.hi = k === (a < 0 ? FAV : a); it.last = NaN;
    });
    read.textContent = a < 0 ? "rest" : "tine " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "kalimba",
  means: "A kalimba's fan of tines: the tine under the pointer springs up off the bridge and its neighbours rise a little.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[192, 191], [135, 147], [290, 224], null],
  mount,
});

shaker.code:
/**
 * Egg shakers: three eggs standing on pegs along a wooden stand. The pointer
 * picks an egg by where it stands: it rocks over on its peg as if shaken, and
 * the eggs beside it rock less, staggered. At rest the eggs lean unevenly and
 * one is bright. The slider is the stagger.
 */
const { Cam, fit, facing, prism, proj, rings, hull, poly, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 3, STEP = 36, SX = N * STEP + 8, SY = 30, SZ = 8, PEG = 6, ER = 12, EH = 30, TIP = 0.75, FAV = 1;
const REST = [0.12, -0.28, 0.06];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [SX, SY, 0], [SX, 0, 0], [0, SY, 0], [4, SY / 2, SZ + PEG + EH + 6], [SX - 4, SY / 2, SZ + PEG + EH + 6], [SX / 2, SY / 2 + 30, SZ + 30], [SX / 2, SY / 2 - 30, SZ + 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, SX, SY, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SZ));

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 4 + STEP / 2 + k * STEP, y = SY / 2, grp = mk("g", {}, g);
    const [pr, pi] = rings(x - 2.5, y - 2.5, x + 2.5, y + 2.5, 2.4, 1);
    put(solid(grp), prism(P, front, pr, pi, SZ, SZ + PEG));
    const sil = mk("path", { class: "sil" }, grp), seam = mk("path", { class: "nf lo" }, grp);
    items.push({ k, x, y, grp, sil, seam, a: tween(REST[k]), last: NaN });
  }

  function draw(it, ang) {
    if (ang === it.last) return;
    it.last = ang;
    const c = Math.cos(ang), s = Math.sin(ang), z0 = SZ + PEG;
    const W = (u, v, h) => P(it.x + u, it.y + v * c - h * s, z0 + v * s + h * c);
    const pts = [];
    let seam = [];
    for (let j = 0; j <= 10; j++) {
      const t = j / 10, h = t * EH, r = ER * Math.sqrt(Math.max(0, 1 - Math.pow(2 * t - 1, 2))) * (t < 0.5 ? 1 : 0.85);
      for (let i = 0; i < 20; i++) { const q = (i / 20) * Math.PI * 2; pts.push(W(Math.cos(q) * r, Math.sin(q) * r, h)); }
    }
    for (let i = 0; i <= 20; i++) { const q = (i / 20) * Math.PI * 2; seam.push(W(Math.cos(q) * ER * 0.97, Math.sin(q) * ER * 0.97, EH * 0.48)); }
    it.sil.setAttribute("d", poly(hull(pts)));
    it.seam.setAttribute("d", poly(seam));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

