  name: "corset",
  means: "An adjustable dress form with a dial at its waist: the pointer turns the dial and the torso widens.",
  rules: [1, 3, 5, 6],
  range: [0.5, 1, 1],
  tour: [[200, 300], [200, 264], [200, 228], null],
  mount,
