    { p: [bot, tip], line: true, c: "nf" },
  ];
}
const LABEL = (a, d) => (a < 0 ? "rest" : "bag " + (a + 1)) + " " + Math.abs(d) + "°";

function mount({ stage, svg, read }, value) {
  const bag = disposer();
