dissecttray.code:
/**
 * Dissection tray: a shallow wax-lined pan with a specimen pinned out on its
 * floor. The pointer tips the tray toward itself on a spring, and the pin
 * nearest it is bright. At rest the tray sits a little askew, one pin bright.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, ringAt, seg, unproj, spring, stepS, clamp,
  disposer, flatDot, mk, place, poly, pointer, put, register, solid,
} = HL;

const PINS = [[-17, -22], [17, -22], [-22, 10], [22, 10], [-12, 26], [12, 26], [0, -34]];
const FAV = 6, REST = [0.05, -0.06];
const oval = (cx, cy, a, b) => circ(1, 32).map((q) => ({ ...q, u: cx + q.u * a, v: cy + q.v * b }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  const ext = [];
  for (const x of [-62, 62]) for (const y of [-46, 46]) for (const z of [-16, 26]) ext.push([x, y, z]);
  fit(C, ext, 200, 162);
  const P = proj(C), front = facing(C);
  const TR = rings(-60, -44, 60, 44, 7, 1.8), FL = rings(-53, -37, 53, 37, 5, 1)[0];
  const BODY = oval(0, -2, 9, 15), HEAD = oval(0, -21, 6.5, 5.5);
  const g = mk("g", {}, svg);
  const tray = solid(g);
  const floor = mk("path", { class: "lo nf" }, g);
  const frog = mk("path", { class: "nf" }, g);
  const pins = PINS.map(([x, y], k) => ({ k, x, y })).sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const p of pins) { p.sh = mk("path", { class: "nf sil" }, g); p.hd = flatDot(g, C, 1.9, "dot m"); }
  const tx = spring(REST[0]), ty = spring(REST[1]);
  let drawn = "";

  function draw() {
    const key = tx.x.toFixed(4) + "," + ty.x.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const Q = (x, y, z) => P(x, y, z + tx.x * x + ty.x * y);
    put(tray, prism(Q, front, TR[0], TR[1], 0, 9));
    floor.setAttribute("d", poly(ringAt(Q, FL, 4)));
    let d = poly(ringAt(Q, BODY, 4)) + poly(ringAt(Q, HEAD, 4));
    for (const p of pins) if (p.k !== FAV) d += seg(Q(Math.sign(p.x) * 6, p.y * 0.4, 4), Q(p.x, p.y, 4));
    frog.setAttribute("d", d);
    for (const p of pins) { p.sh.setAttribute("d", seg(Q(p.x, p.y, 4), Q(p.x, p.y, 16))); place(p.hd, Q(p.x, p.y, 16)); }
  }

  const B = register(stage, (dt) => {
    const m = stepS(tx, dt) | stepS(ty, dt);
    draw();
    return !!m;
  });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null;
    if (over) {
      let bd = Infinity;
      for (const p of pins) { const d = Math.hypot(over[0] - p.x, over[1] - p.y); if (d < bd) { bd = d; near = p; } }
      tx.t = -0.2 * value * clamp(over[0] / 60, -1, 1);
      ty.t = -0.2 * value * clamp(over[1] / 44, -1, 1);
    } else { tx.t = REST[0]; ty.t = REST[1]; }
    for (const p of pins) {
      const on = near ? p === near : p.k === FAV;
      p.sh.classList.toggle("hi", on);
      p.hd.setAttribute("class", on ? "dot" : "dot m");
    }
    read.textContent = near ? "pin " + (near.k + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 9);
      over = Math.abs(x) > 72 || Math.abs(y) > 56 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "dissecttray",
  means: "A wax dissection tray with a pinned specimen: the tray tips toward the pointer, and the nearest pin is bright.",
  rules: [1, 3, 4, 5, 8],
  range: [0.4, 1, 1.6],
  tour: [[218, 166], [180, 95], [224, 220], null],
  mount,
});

periscope2.code:
/**
 * Periscope: a toy periscope, a tall square tube with a head at each end
 * facing opposite ways. The pointer is what it looks at: the whole tube turns
 * on a spring until its top window faces the pointer. At rest it looks off to
 * one side, its top window bright.
 */
const {
  Cam, facing, fit, prism, proj, rings, unproj, spring, stepS, fillet,
  disposer, mk, poly, pointer, put, register, solid,
} = HL;

const H = 96, REST = -0.35;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([30 * Math.cos(a), 30 * Math.sin(a), 0], [30 * Math.cos(a), 30 * Math.sin(a), H + 20]); }
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const TUBE = rings(-8, -8, 8, 8, 2.5, 1.2), LOW = rings(-28, -10, 8, 10, 3, 1.4), TOP = rings(-8, -10, 28, 10, 3, 1.4);
  const g = mk("g", {}, svg);
  const foot = solid(g), low = solid(g), lowWin = mk("path", { class: "nf sil" }, g);
  const tube = solid(g), top = solid(g), win = mk("path", { class: "nf sil hi" }, g);
  const sp = spring(REST);
  let drawn = NaN;

  const window = (a, u, z0, z1) => {
    const c = Math.cos(a), s = Math.sin(a);
    const pts = [[-7, z0], [7, z0], [7, z1], [-7, z1]].map(([v, z]) => P(u * c - v * s, u * s + v * c, z));
    return poly(fillet(pts, [1.5, 1.5, 1.5, 1.5]));
  };

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const T = (r) => turn(r, a);
    const fwd = Math.cos(a) + Math.sin(a) > 0;
    put(foot, prism(P, front, T(rings(-30, -14, 10, 14, 4, 1.6)[0]), T(rings(-30, -14, 10, 14, 4, 1.6)[1]), 0, 3));
    put(low, prism(P, front, T(LOW[0]), T(LOW[1]), 3, 24));
    put(tube, prism(P, front, T(TUBE[0]), T(TUBE[1]), 24, H));
    put(top, prism(P, front, T(TOP[0]), T(TOP[1]), H, H + 20));
    win.setAttribute("d", fwd ? window(a, 28, H + 5, H + 15) : "");
    lowWin.setAttribute("d", fwd ? "" : window(a, -28, 8, 19));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    const aim = over ? Math.atan2(over[1], over[0]) : REST;
    const want = over ? REST + wrap(aim - REST) * Math.min(1, value) : REST;
    sp.t = sp.t + wrap(want - sp.t);
    read.textContent = over ? Math.round(((aim * 180) / Math.PI + 360) % 360) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r < 6 || r > 140 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "periscope2",
  means: "A toy periscope with a head at each end: the tube turns until its top window faces the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[86, 300], [135, 210], [300, 260], null],
  mount,
});

geoboard.code:
/**
 * Geoboard: a square board with a grid of pegs and a rubber band stretched
 * round four of them. The pointer tips the board toward itself on a spring,
 * and the band's free corner hooks onto the peg nearest it. At rest the band
 * is a lopsided quad, bright, the board a little askew.
 */
const {
  Cam, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, clamp,
  disposer, flatDot, mk, place, poly, pointer, put, register, solid,
} = HL;

const FIX = [[-40, -20], [20, -40], [40, 20]], FREE = [-20, 40], REST = [0.06, -0.05];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  const ext = [];
  for (const x of [-52, 52]) for (const y of [-52, 52]) for (const z of [-14, 30]) ext.push([x, y, z]);
  fit(C, ext, 200, 162);
  const P = proj(C), front = facing(C);
  const BR = rings(-50, -50, 50, 50, 7, 1.8);
  const g = mk("g", {}, svg);
  const board = solid(g);
  const pegs = [];
  for (let i = 0; i < 5; i++) for (let j = 0; j < 5; j++) pegs.push({ x: -40 + i * 20, y: -40 + j * 20, i, j });
  pegs.sort((a, b) => a.x + a.y - (b.x + b.y));
  for (const p of pegs) { p.sh = mk("path", { class: "nf lo" }, g); p.hd = flatDot(g, C, 1.6, "dot off"); }
  const band = mk("path", { class: "nf sil hi" }, g);
  const tx = spring(REST[0]), ty = spring(REST[1]);
  let free = FREE, drawn = "";

  function draw() {
    const key = tx.x.toFixed(4) + "," + ty.x.toFixed(4) + "," + free;
    if (key === drawn) return;
    drawn = key;
    const Q = (x, y, z) => P(x, y, z + tx.x * x + ty.x * y);
    put(board, prism(Q, front, BR[0], BR[1], 0, 8));
    for (const p of pegs) { p.sh.setAttribute("d", seg(Q(p.x, p.y, 8), Q(p.x, p.y, 15))); place(p.hd, Q(p.x, p.y, 15)); }
    const quad = [FIX[0], FIX[1], FIX[2], free];
    const hull = quad.map(([x, y]) => [x, y, Math.atan2(y, x)]).sort((a, b) => a[2] - b[2]);
    band.setAttribute("d", poly(hull.map(([x, y]) => Q(x, y, 12))));
  }

  const B = register(stage, (dt) => { const m = stepS(tx, dt) | stepS(ty, dt); draw(); return !!m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let near = null;
    if (over) {
      let bd = Infinity;
      for (const p of pegs) {
        if (FIX.some(([x, y]) => x === p.x && y === p.y) || (Math.abs(p.x) < 5 && Math.abs(p.y) < 5)) continue;
        const d = Math.hypot(over[0] - p.x, over[1] - p.y);
        if (d < bd) { bd = d; near = p; }
      }
      tx.t = -0.2 * value * clamp(over[0] / 50, -1, 1);
      ty.t = -0.2 * value * clamp(over[1] / 50, -1, 1);
    } else { tx.t = REST[0]; ty.t = REST[1]; }
    free = near ? [near.x, near.y] : FREE;
    for (const p of pegs) p.hd.setAttribute("class", p === near ? "dot" : "dot off");
    read.textContent = near ? "peg " + (near.i + 1) + "·" + (near.j + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 8);
      over = Math.abs(x) > 62 || Math.abs(y) > 62 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "geoboard",
  means: "A geoboard with a rubber band on its pegs: the board tips toward the pointer and the band hooks the nearest peg.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.6],
  tour: [[200, 206], [200, 93], [313, 150], null],
  mount,
});

pulleykit.code:
/**
 * Pulley kit: a stand with a crossbar, a pulley block hanging from it and a
 * weight on the rope. The pointer pulls the weight toward itself: rope and
 * weight swing on a spring, and the weight is bright. At rest it hangs a
 * little off plumb.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, clamp,
  disposer, mk, open, pointer, put, register, solid,
} = HL;

const H = 110, L = 62, REST = -0.14, UX = Math.SQRT1_2, UY = -Math.SQRT1_2;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  const ext = [[-50, 50, 0], [50, -50, 0], [-30, -30, 0], [30, 30, 0], [-50, 50, H + 6], [50, -50, H + 6]];
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-46, 34, -34, 46, 3, 1.2), 0, 4));
  put(solid(g), prism(P, front, ...rings(34, -46, 46, -34, 3, 1.2), 0, 4));
  put(solid(g), prism(P, front, disc(-40, 40, 2.4, 16), null, 4, H));
  put(solid(g), prism(P, front, disc(40, -40, 2.4, 16), null, 4, H));
  const beam = [];
  for (let k = 0; k <= 8; k++) beam.push(P(-40 + k * 10, 40 - k * 10, H + 2));
  mk("path", { class: "nf sil", d: open(beam) }, g);
  const wheel = [];
  for (let k = 0; k <= 32; k++) { const a = (k / 32) * Math.PI * 2; wheel.push(P(7 * Math.cos(a) * UX, 7 * Math.cos(a) * UY, H - 10 + 7 * Math.sin(a))); }
  mk("path", { d: open(wheel) }, g);
  mk("path", { class: "nf sil", d: seg(P(0, 0, H + 2), P(0, 0, H - 10)) + seg(P(-7 * UX, -7 * UY, H - 10), P(-7 * UX, -7 * UY, 8)) }, g);
  const rope = mk("path", { class: "nf sil" }, g);
  const wt = solid(g);
  const sp = spring(REST);
  let drawn = NaN;

  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const ox = 7 * UX, oy = 7 * UY, top = H - 10;
    const dx = L * Math.sin(a), dz = L * Math.cos(a);
    const cx = ox + dx * UX, cy = oy + dx * UY, cz = top - dz;
    rope.setAttribute("d", seg(P(ox, oy, top), P(cx, cy, cz)));
    put(wt, prism(P, front, ...rings(cx - 9, cy - 9, cx + 9, cy + 9, 9, 1.4), cz - 22, cz));
    wt.sil.classList.add("hi");
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    sp.t = over === null ? REST : clamp(over / 60, -1, 1) * 0.9 * value;
    read.textContent = over === null ? "rest" : Math.round((sp.t * 180) / Math.PI) + "°";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), s = x * UX + y * UY;
      over = Math.abs(s) > 90 ? null : s;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "pulleykit",
  means: "A pulley stand with a hanging weight: the rope and weight swing toward the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.4],
  tour: [[313, 239], [90, 239], [250, 239], null],
  mount,
});

pettrough.code:
/**
 * Pet water bottle: three drinking bottles clipped to a cage wall, each with
 * a cap and a sipper spout ending in a ball. The pointer picks a bottle by
 * where it stands: it swings out from the wall on its clip, its neighbours a
 * little, staggered. At rest the middle bottle leans out, bright. Slider: stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const { Cam, fit, proj, rrect, circ, hull, poly, open, tween, tset, tval, tdone, mk, solid, pointer, register, disposer } = HL;
const BOX = (x0, y0, z0, x1, y1, z1, r = 2, b = 1.2) => {
  const o = rrect(x0, y0, x1, y1, r, 4), i = rrect(x0 + b, y0 + b, x1 - b, y1 - b, Math.max(r - b, 0.3), 4);
  return { a: o.map((q) => [q.u, q.v, z0]), b: o.map((q) => [q.u, q.v, z1]), c: i.map((q) => [q.u, q.v, z1]) };
};
const CYL = (ax, cx, cy, cz, R, l0, l1) => {
  const m = (R2, l) => circ(R2, 28).map((q) => ax === "z" ? [cx + q.u, cy + q.v, l] : ax === "x" ? [l, cy + q.u, cz + q.v] : [cx + q.u, l, cz + q.v]);
  return { a: m(R, l0), b: m(R, l1), c: m(Math.max(R - 1, R * 0.6), l1) };
};
const ROD = (p, q, R) => { const e = (c) => [[R, 0, 0], [-R, 0, 0], [0, R, 0], [0, -R, 0], [0, 0, R], [0, 0, -R]].map((d) => [c[0] + d[0], c[1] + d[1], c[2] + d[2]]); return { a: e(p), b: e(q), c: [] }; };
const rot = (ax, p, t) => {
  const c = Math.cos(t), s = Math.sin(t);
  return ax === "x" ? [p[0], p[1] * c - p[2] * s, p[1] * s + p[2] * c] : [p[0] * c + p[2] * s, p[1], -p[0] * s + p[2] * c];
};

const S = 2.05, AX = "x", ANS = 0.7, NB = 0.24, REST = [0.06, 0.32, 0.12], FAV = 1, HIT = [0, 9, -30], HW = 22, HH = 70;
const NAME = (a) => "bottle " + (a + 1);
const BOTTLE = (h) => [BOX(-7, 0, -12, 7, 2, -4, 1, 0.5), CYL("z", 0, 9, 0, 8, -6 - h, -2), CYL("z", 0, 9, 0, 5.5, -12 - h, -6 - h), ROD([0, 9, -12 - h], [0, 5, -28 - h], 1.4), CYL("z", 0, 5, 0, 2.4, -32 - h, -28 - h)];
const ITEMS = [{ o: [22, 0, 84], parts: BOTTLE(40), main: 1 }, { o: [60, 0, 84], parts: BOTTLE(48), main: 1 }, { o: [98, 0, 84], parts: BOTTLE(34), main: 1 }];
const STATIC_BACK = [BOX(-8, -8, 0, 128, 34, 4, 5, 1.6), BOX(-4, -5, 4, 124, 0, 92, 3, 1.2)];
const STATIC_FRONT = [];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, S);
  const xf = (it, t) => (p) => { const q = rot(AX, p, t); return [q[0] + it.o[0], q[1] + it.o[1], q[2] + it.o[2]]; };
  const fitPts = [];
  for (const pt of STATIC_BACK.concat(STATIC_FRONT)) fitPts.push(...pt.a, ...pt.b);
  for (const it of ITEMS) for (const t of [ANS, ...REST]) for (const pt of it.parts) if (pt.a) fitPts.push(...pt.a.map(xf(it, t)), ...pt.b.map(xf(it, t)));
  fit(C, fitPts, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const paint = (parent, pt, f) => {
    if (pt.w) return { pt, el: mk("path", { class: "nf" }, parent) };
    const s = solid(parent);
    return { pt, s };
  };
  const show = (o, f) => {
    if (o.el) { o.el.setAttribute("d", open([P(...o.pt.w), P(...f(o.pt.l))])); return; }
    o.s.sil.setAttribute("d", poly(hull(o.pt.a.concat(o.pt.b).map((p) => P(...f(p))))));
    o.s.cr.setAttribute("d", o.pt.c.length ? poly(o.pt.c.map((p) => P(...f(p)))) : "");
  };
  const id = (p) => p;
  for (const pt of STATIC_BACK) show(paint(g, pt), id);
  const items = ITEMS.map((it, k) => {
    const grp = mk("g", {}, g);
    const els = it.parts.map((pt) => paint(grp, pt));
    return { ...it, k, els, t: tween(REST[k]), last: NaN };
  });
  for (const pt of STATIC_FRONT) show(paint(g, pt), id);
  function draw(it, t) {
    if (t === it.last) return;
    it.last = t;
    const f = xf(it, t);
    for (const o of it.els) show(o, f);
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.t, now)); if (!tdone(it.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);
  const mids = items.map((it) => P(it.o[0] + HIT[0], it.o[1] + HIT[1], it.o[2] + HIT[2]));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < HW && Math.abs(mids[best][1] - sy) < HH ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), t = a < 0 ? REST[k] : d === 0 ? ANS : d === 1 ? NB : REST[k] * 0.4;
      tset(it.t, t, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const m = it.els[it.main].s;
      m.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : NAME(a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "pettrough",
  means: "Three water bottles clipped to a cage wall: the bottle under the pointer swings out on its clip, its neighbours a little after.",
  rules: [1, 2, 5, 6],
