  const c = Math.cos(rad(a)), s = Math.sin(rad(a));
  let [x, y, z] = sub(p, O);
  if (AX === "z") [x, y] = [x * c - y * s, x * s + y * c];
  else if (AX === "y") [x, z] = [x * c + z * s, -x * s + z * c];
