toastrack.code:
/**
 * Toast rack: a wire rack on a low tray, its arches holding four slices of
 * toast on edge. The pointer picks a slice by where it stands: it rises out
 * of its slot and tips forward, and the slices beside it tilt away,
 * staggered from it. At rest one slice sits half out, bright. The slider
 * is the stagger.
 *
 * The pattern: one of many in a single row (riffle).
 */
const { Cam, facing, fit, hull, poly, open, prism, proj, rings, rad, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 4, STEP = 18, T = 3, W = 30, HH = 24, BZ = 3, LIFT = 18, FAV = 1;
const X0 = 10, X1 = X0 + (N - 1) * STEP;
const REST = [[0, -5], [9, 10], [0, 4], [0, -3]];
const V = [0.61, 0.61, 0.5];
const PROF = [[1, 0], [W - 1, 0], [W - 1, HH - 6]];
for (let k = 0; k <= 10; k++) { const a = (k / 10) * Math.PI; PROF.push([W / 2 + (W / 2 - 1) * Math.cos(a) + (k === 0 || k === 10 ? 0 : 0), HH - 6 + 8 * Math.sin(a)]); }
PROF.push([1, HH - 6]);
const INSET = PROF.map(([y, z]) => [W / 2 + (y - W / 2) * 0.82, 2.5 + z * 0.84]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-8, -6, 0], [X1 + 14, W + 6, 0], [X0, W / 2, HH + 4 + LIFT + 4], [X1 + 10, 0, HH], [-4, W, HH]], 200, 168);
  const P = proj(C), g = mk("g", {}, svg);
  const [tr, ti] = rings(-8, -6, X1 + 14, W + 6, 5, 1.6);
  put(solid(g), prism(P, facing(C), tr, ti, 0, BZ));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, ax = x - STEP / 2;
    const arch = [[ax, 1, BZ], [ax, 1, BZ + 15], [ax, 4, BZ + 19], [ax, W - 4, BZ + 19], [ax, W - 1, BZ + 15], [ax, W - 1, BZ]];
    mk("path", { class: "nf lo", d: open(arch.map((p) => P(...p))) }, g);
    const grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil" }, grp), face = mk("path", { class: "nf lo" }, grp), crust = mk("path", { class: "nf lo" }, grp);
    items.push({ x, sil, face, crust, up: tween(REST[k][0]), tilt: tween(REST[k][1]), last: "" });
  }
  const ax = X1 + STEP / 2;
  mk("path", { class: "nf lo", d: open([[ax, 1, BZ], [ax, 1, BZ + 15], [ax, 4, BZ + 19], [ax, W - 4, BZ + 19], [ax, W - 1, BZ + 15], [ax, W - 1, BZ]].map((p) => P(...p))) }, g);

  function draw(it, up, tl) {
    const key = up.toFixed(2) + "," + tl.toFixed(2);
    if (key === it.last) return;
    it.last = key;
    const c = Math.cos(rad(tl)), s = Math.sin(rad(tl));
    const S = (dx, y, z) => P(it.x + dx * c + z * s, y, BZ + up - dx * s + z * c);
    const side = V[0] * c - V[2] * s > 0 ? T / 2 : -T / 2;
    const all = [...PROF.map(([y, z]) => S(-T / 2, y, z)), ...PROF.map(([y, z]) => S(T / 2, y, z))];
    it.sil.setAttribute("d", poly(hull(all)));
    it.face.setAttribute("d", poly(PROF.map(([y, z]) => S(side, y, z))));
    it.crust.setAttribute("d", poly(INSET.map(([y, z]) => S(side, y, z))));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.up, now), tval(it.tilt, now)); if (!tdone(it.up, now) || !tdone(it.tilt, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, W / 2, BZ + HH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 32 && Math.abs(mids[best][1] - sy) < 80 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = k - a;
      const [u, t] = a < 0 ? REST[k] : d === 0 ? [LIFT, 16] : [0, Math.sign(d) * (Math.abs(d) === 1 ? 14 : 7)];
      const dl = from < 0 ? 0 : Math.abs(k - from) * stag;
      tset(it.up, u, now, dl); tset(it.tilt, t, now, dl);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "slice " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "toastrack",
  means: "A wire toast rack holding four slices: the slice under the pointer rises and tips out, and its neighbours tilt away.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[185, 140], [220, 149], [245, 165], null],
  mount,
});

eggtimer.code:
/**
 * Egg timer: a sand glass in a frame of two round plates and three posts.
 * The pointer's place across the figure turns the whole timer over about
 * its waist, so the sand that sat in the low bulb rides up. At rest it
 * leans a little and the top bulb is bright. The slider is the full turn.
 *
 * The pattern: one object, turned by a continuous input.
 */
const { Cam, circ, fit, hull, poly, proj, clamp, rad, spring, stepS, disposer, mk, pointer, register } = HL;

const H = 44, R = 14, PH = 3, MID = H / 2, REST = 10;
const V = [0.61, 0.61, 0.5];
const disc = (r, n = 28) => circ(r, n).map((q) => [q.u, q.v]);
const prof = (t) => 1.6 + 8.4 * Math.sin(Math.PI * Math.min(1, t * 1.04)); // bulb radius by height 0..1

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let TURN = value;
  const C = Cam(45, 0.5, 3.8);
  fit(C, [[-R, -R, MID - R - 6], [R, R, MID + R + 6], [R, -R, MID], [-R, R, MID], [0, 0, 0], [0, 0, H]], 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const floor = mk("path", { class: "dash" }, g);
  floor.setAttribute("d", poly(disc(R + 8, 40).map(([u, v]) => P(u, v, 0))));
  const parts = [];
  const add = (cls) => { const p = { el: mk("path", { class: cls }, g), cr: null, z: 0 }; parts.push(p); return p; };
  const bot = add("sil"), top = add("sil"), posts = [0, 1, 2].map(() => add("sil")), lowB = add("sil"), upB = add("sil");
  bot.cr = mk("path", { class: "nf lo" }, g); top.cr = mk("path", { class: "nf lo" }, g);
  lowB.sand = mk("path", { class: "nf lo" }, g); upB.sand = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST, { k: 60, c
: 14 });
  let last = NaN;

  function draw(a) {
    if (a === last) return; last = a;
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a));
    const W = ([x, y, z]) => { const yy = y, zz = z - MID; return [x, yy * ca - zz * sa, MID + yy * sa + zz * ca]; };
    const S = (p) => { const w = W(p); return P(w[0], w[1], w[2]); };
    const dep = (p) => { const w = W(p); return w[0] * V[0] + w[1] * V[1] + w[2] * V[2]; };
    const cyl = (o, r, z0, z1, part) => {
      const ring = disc(r).map(([u, v]) => [u + o[0], v + o[1]]);
      const pts = [...ring.map(([u, v]) => S([u, v, z0])), ...ring.map(([u, v]) => S([u, v, z1]))];
      part.el.setAttribute("d", poly(hull(pts)));
      part.z = dep([o[0], o[1], (z0 + z1) / 2]);
      if (part.cr) { const capZ = dep([0, 0, z1]) > dep([0, 0, z0]) ? z1 : z0; part.cr.setAttribute("d", poly(ring.map(([u, v]) => S([u, v, capZ])))); }
    };
    cyl([0, 0], R, 0, PH, bot); cyl([0, 0], R, H - PH, H, top);
    posts.forEach((p, i) => { const t = rad(90 + i * 120); cyl([Math.cos(t) * (R - 3), Math.sin(t) * (R - 3)], 1.4, PH, H - PH, p); });
    const bulb = (z0, z1, part, sandFrom, sandTo) => {
      const pts = [];
      for (let i = 0; i <= 8; i++) { const t = i / 8, z = z0 + (z1 - z0) * t; pts.push(...disc(prof(z0 < MID ? 1 - t : t), 18).map(([u, v]) => S([u, v, z]))); }
      part.el.setAttribute("d", poly(hull(pts)));
      part.z = dep([0, 0, (z0 + z1) / 2]);
      const sp = [];
      for (let i = 0; i <= 4; i++) { const t = i / 4, z = sandFrom + (sandTo - sandFrom) * t; sp.push(...disc(prof(Math.abs(z - MID) / (MID - PH)) * 0.86, 14).map(([u, v]) => S([u, v, z]))); }
      part.sand.setAttribute("d", poly(hull(sp)));
    };
    bulb(PH, MID, lowB, PH + 1, PH + 9); bulb(MID, H - PH, upB, MID + 2, MID + 5);
    // paint far to near; sand rides with its bulb
    [...parts].sort((p, q) => p.z - q.z).forEach((p) => { g.appendChild(p.el); if (p.cr) g.appendChild(p.cr); if (p.sand) g.appendChild(p.sand); });
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  const L = P(-R, R, 0)[0] - 10, Rr = P(R, -R, 0)[0] + 10;
  const set = (a) => {
    ang.t = a;
    const turned = a > 90;
    upB.el.classList.toggle("hi", !turned); lowB.el.classList.toggle("hi", turned);
    read.textContent = a === REST ? "rest" : Math.round(a) + "°";
    B.wake();
  };
  set(REST);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { if (sx < L || sx > Rr || sy < 30 || sy > 300) return set(REST); set(Math.round(clamp((sx - L) / (Rr - L), 0, 1) * TURN)); },
    leave: () => set(REST),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { TURN = v; }, destroy: bag.dispose };
}

hairline({
  name: "eggtimer",
  means: "A sand egg timer in its frame: the pointer turns it over about its waist, and the sand rides up as it turns.",
  rules: [1, 3, 5, 6],
  range: [90, 180, 180],
  tour: [[170, 200], [205, 160], [238, 111], null],
  mount,
});

doorstop.code:
/**
 * Door wedge: a door on a floor, hung on a post, held open by a wedge
 * pushed under its free end. The pointer's bearing round the hinge swings
 * the door, and the wedge slides along the floor with the door's edge to
 * hold it. At rest the door stands part open and the wedge is bright. The
 * slider is the widest swing.
 *
 * The pattern: one part turned about a fixed axis by a continuous input.
 */
const { Cam, facing, fit, hull, poly, prism, proj, rings, unproj, clamp, rad, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const LD = 52, TD = 2.5, HD = 64, GAP = 3, REST = 72, WL = 16;
const V = [0.61, 0.61, 0.5];
// box faces over corners i = bx + 2 by + 4 bz, outward
const FACES = [[0, 2, 3, 1], [4, 5, 7, 6], [0, 1, 5, 4], [2, 6, 7, 3], [0, 4, 6, 2], [1, 3, 7, 5]];
const WF = [[0, 1, 2], [3, 5, 4], [0, 3, 4, 1], [1, 4, 5, 2], [0, 2, 5, 3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-10, -10, 0], [LD + 12, LD + 12, 0], [-10, -10, HD + 6], [LD, 0, HD], [0, LD, HD]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const [fr, fi] = rings(-10, -10, LD + 12, LD + 12, 6, 1.8);
  put(solid(g), prism(P, facing(C), fr, fi, -3, 0));
  const post = { sil: mk("path", { class: "sil" }, g), cr: mk("path", { class: "nf lo" }, g) };
  const door = { sil: mk("path", { class: "sil" }, g), cr: mk("path", { class: "nf lo" }, g) };
  const wedge = { sil: mk("path", { class: "sil" }, g), cr: mk("path", { class: "nf lo" }, g) };
  const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
  const solidOf = (o, pts, faces) => {
    o.sil.setAttribute("d", poly(hull(pts.map((p) => P(...p)))));
    let d = "";
    for (const f of faces) {
      const a = sub(pts[f[1]], pts[f[0]]), b = sub(pts[f[2]], pts[f[0]]);
      const n = [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
      if (n[0] * V[0] + n[1] * V[1] + n[2] * V[2] > 0) d += poly(f.map((i) => P(...pts[i])));
    }
    o.cr.setAttribute("d", d);
  };
  const box = (x0, x1, y0, y1, z0, z1, tf) => { const r = []; for (let i = 0; i < 8; i++) r.push(tf([i & 1 ? x1 : x0, i & 2 ? y1 : y0, i & 4 ? z1 : z0])); return r; };
  solidOf(post, box(-6, 0, -6, 0, 0, HD + 4, (p) => p), FACES);
  const ang = spring(REST, { k: 70, c: 15 });
  let last = NaN;
  function draw(a) {
    if (a === last) return; last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const R = ([u, w, z]) => [u * c - w * s, u * s + w * c, z];
    solidOf(door, box(0.5, LD, -TD / 2, TD / 2, GAP, HD, R), FACES);
    const u0 = LD - 10, wp = [];
    for (const z of [0, 1]) for (const [w, h] of [[-1, 0.6], [WL, 0], [WL, 7]]) wp.push(R([u0 + z * 9, w, h]));
    // reorder: triangle 0..2 at u0, 3..5 at u0+9
    solidOf(wedge, [wp[0], wp[1], wp[2], wp[3], wp[4], wp[5]].map(([x, y, z], i) => [x, y, i === 0 || i === 3 ? 0 : z]), WF);
    // depth: whichever is nearer paints last
    const dDoor = (LD / 2) * (c * V[0] + s * V[1]), dWedge = R([u0 + 4, WL / 2, 0]);
    const wd = dWedge[0] * V[0] + dWedge[1] * V[1];
    if (wd > dDoor) { g.appendChild(door.sil); g.appendChild(door.cr); g.appendChild(wedge.sil); g.appendChild(wedge.cr); }
    else { g.appendChild(wedge.sil); g.appendChild(wedge.cr); g.appendChild(door.sil); g.appendChild(door.cr); }
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  wedge.sil.classList.add("hi");
  const set = (a) => { ang.t = a; read.textContent = a === REST ? "rest" : Math.round(a) + "°"; B.wake(); };
  set(REST);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, 0);
      if (x < -12 || y < -12 || x > LD + 30 || y > LD + 30) return set(REST);
      set(Math.round(clamp((Math.atan2(y, x) * 180) / Math.PI, 8, MAX)));
    },
    leave: () => set(REST),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { MAX = v; }, destroy: bag.dispose };
}

hairline({
  name: "doorstop",
  means: "A door held open by a wedge on the floor: the pointer swings the door round its hinge and the wedge slides along to hold it.",
  rules: [1, 3, 5, 6],
