climbingrope.code:
/**
 * Rope climb: a gym climbing rope hanging from a beam over a mat, a knot
 * at its foot. The rope swings toward where the pointer stands on the
 * floor, its foot trailing in a soft bend. At rest it hangs with a slight
 * lean, bright. The slider is the reach of the swing.
 */
const { Cam, fit, circ, hull, poly, prism, proj, rings, ringAt, clamp, spring, stepS, unproj, disposer, mk, pointer, put, register, solid } = HL;

const Z = 150, L = 124, N = 24;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[-60, -40, 0], [60, 40, 0], [-60, 40, 0], [60, -40, 0], [0, 0, Z + 8]], 200, 162);
  const P = proj(C), front = facing0(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-44, -32, 44, 32, 8, 2);
  put(solid(g), prism(P, front, mr, mi, 0, 6));
  const rope = mk("path", { class: "sil hi" }, g), twist = mk("path", { class: "nf lo" }, g), knot = solid(g);
  const [br, bi] = rings(-56, -6, 56, 6, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, Z, Z + 8));
  const ax = spring(0.12), ay = spring(-0.05);
  let last = "";
  function draw() {
    const key = ax.x.toFixed(4) + ay.x.toFixed(4);
    if (key === last) return;
    last = key;
    const c = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N, b = Math.pow(t, 1.4);
      c.push([L * Math.sin(ax.x) * b, L * Math.sin(ay.x) * b, Z - L * t * (1 - 0.25 * (ax.x * ax.x + ay.x * ay.x))]);
    }
    const s = c.map((q) => P(q[0], q[1], q[2])), lft = [], rgt = [], w = 3.6;
    for (let i = 0; i <= N; i++) {
      const a = s[Math.max(0, i - 1)], b = s[Math.min(N, i + 1)], dx = b[0] - a[0], dy = b[1] - a[1], m = Math.hypot(dx, dy) || 1;
      lft.push([s[i][0] - (dy / m) * w, s[i][1] + (dx / m) * w]);
      rgt.push([s[i][0] + (dy / m) * w, s[i][1] - (dx / m) * w]);
    }
    rope.setAttribute("d", poly(lft.concat(rgt.reverse())));
    rgt.reverse();
    let d = "";
    for (let i = 1; i < N - 2; i += 2) d += "M" + lft[i][0].toFixed(2) + " " + lft[i][1].toFixed(2) + "L" + rgt[i + 1][0].toFixed(2) + " " + rgt[i + 1][1].toFixed(2);
    twist.setAttribute("d", d);
    const f = c[N - 3];
    knot.sil.setAttribute("d", poly(hull(ringAt(P, disc(f[0], f[1], 6), f[2] + 6).concat(ringAt(P, disc(f[0], f[1], 6), f[2] - 6)))));
    knot.sil.classList.add("hi");
  }
  const B = register(stage, (dt) => { const m = stepS(ax, dt) | stepS(ay, dt); draw(); return !!m; });
  bag.add(B.unregister);
  function aim(p) {
    if (!p) { ax.t = 0.12; ay.t = -0.05; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    ax.t = clamp(x / 100, -reach, reach); ay.t = clamp(y / 100, -reach, reach);
    read.textContent = "lean " + Math.round(Math.hypot(ax.t, ay.t) * 57.3) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}
function facing0(C) { return HL.facing(C); }

hairline({
  name: "climbingrope",
  means: "A gym climbing rope under a beam: it swings toward where the pointer stands on the floor, its knotted foot trailing.",
  rules: [1, 3, 5, 8],
  range: [0.2, 0.45, 0.7],
  tour: [[232, 296], [179, 185], [221, 291], null],
  mount,
});

vaulttable.code:
/**
 * Vault box: a tapered vaulting box of five stacked sections with a padded
 * top. The pointer picks a section by its height: it slides out of the
 * stack toward the viewer, and the sections beside it slide a little,
 * staggered from it. At rest one section stands out, bright. The slider is
 * the stagger.
 */
const { Cam, fit, facing, proj, prism, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 5, H = 14, W = 110, D = 46, OUT = 24, FAV = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [W, 0, 0], [0, D + OUT, 0], [W, D + OUT, 0], [0, 0, N * H], [W, D + OUT, N * H]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const items = [];
  for (let k = 0; k < N; k++) {
    const s = solid(g), top = k === N - 1;
    items.push({ k, s, top, x0: 5 * k, x1: W - 5 * k, y0: 2 * k, y1: D - 2 * k, z: tween(k === FAV ? 10 : 0), last: NaN });
  }
  function draw(it, o) {
    if (o === it.last) return;
    it.last = o;
    const r = it.top ? 10 : 4;
    const [ring, inner] = rings(it.x0, it.y0 + o, it.x1, it.y1 + o, r, it.top ? 2.4 : 1.4);
    put(it.s, prism(P, front, ring, inner, it.k * H, (it.k + 1) * H - (it.top ? 0 : 0.6)));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P((it.x0 + it.x1) / 2, (it.y0 + it.y1) / 2, it.k * H + H / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[1] - sy); if (dd < bd) { bd = dd; best = k; } });
    return bd < 16 && Math.abs(mids[best][0] - sx) < 110 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), o = a < 0 ? (k === FAV ? 10 : 0) : dd === 0 ? OUT : dd === 1 ? 9 : 3;
      tset(it.z, o, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tier " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "vaulttable",
  means: "A tapered vaulting box of five sections: the section under the pointer slides out of the stack, its neighbours a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 135], [200, 170], [228, 230], null],
  mount,
});

springboard2.code:
/**
 * Mini trampoline: a round frame on short legs, a mat slung inside it on a
 * ring of springs. The mat sinks under the pointer and tips toward where it
 * stands, the springs stretching with it. At rest the mat sags a little,
 * bright. The slider is how deep it sinks.
 */
const { Cam, fit, facing, circ, poly, prism, proj, ringAt, clamp, spring, stepS, unproj, disposer, mk, pointer, put, register, solid, seg } = HL;

const R = 52, RI = 47, RM = 35, Z = 30, NS = 20;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let deep = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R, R, 0], [R, -R, 0], [0, 0, Z + 3]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const legs = [0, 1, 2, 3, 4, 5].map((i) => [Math.cos((i + 0.5) * Math.PI / 3) * (R - 5), Math.sin((i + 0.5) * Math.PI / 3) * (R - 5)]).sort((a, b) => a[0] + a[1] - b[0] - b[1]);
  for (const [x, y] of legs) put(solid(g), prism(P, front, disc(x, y, 2.6, 12), disc(x, y, 1.6, 12), 0, Z));
  put(solid(g), prism(P, front, circ(R, 48), circ(RI, 48), Z, Z + 3));
  const springs = mk("path", { class: "nf lo" }, g), mat = solid(g);
  mat.sil.classList.add("hi");
  const D = spring(1.5), px = spring(8), py = spring(-6);
  let last = "";
  const zAt = (u, v) => Z + 3 - D.x - ((u * px.x + v * py.x) / (RM * RM)) * 1.6;
  function draw() {
    const key = [D.x, px.x, py.x].map((n) => n.toFixed(3)).join();
    if (key === last) return;
    last = key;
    const m = circ(RM, 48).map((q) => P(q.u, q.v, zAt(q.u, q.v)));
    const mi = circ(RM - 3, 48).map((q) => P(q.u, q.v, zAt(q.u, q.v)));
    mat.sil.setAttribute("d", poly(m));
    mat.cr.setAttribute("d", poly(mi));
    let d = "";
    for (let i = 0; i < NS; i++) {
      const a = (i / NS) * Math.PI * 2, c = Math.cos(a), s = Math.sin(a);
      d += seg(P(c * RI, s * RI, Z + 3), P(c * RM, s * RM, zAt(c * RM, s * RM)));
    }
    springs.setAttribute("d", d);
  }
  const B = register(stage, (dt) => { const mv = stepS(D, dt) | stepS(px, dt) | stepS(py, dt); draw(); return !!mv; });
  bag.add(B.unregister);
  function aim(p) {
    let on = false, x = 0, y = 0;
    if (p) { [x, y] = unproj(C, p[0], p[1], Z); on = Math.hypot(x, y) < R + 6; }
    if (!on) { D.t = 1.5; px.t = 8; py.t = -6; read.textContent = "rest"; B.wake(); return; }
    const r = Math.hypot(x, y), k = r > RM ? RM / r : 1;
    D.t = deep; px.t = x * k; py.t = y * k;
    read.textContent = "dip " + Math.round(deep + 1.6 * Math.min(1, r / RM));
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { deep = clamp(v, 0, 4.4); }, destroy: bag.dispose };
}

hairline({
  name: "springboard2",
  means: "A mini trampoline on short legs: the mat sinks under the pointer and tips toward it, its ring of springs stretching.",
  rules: [1, 3, 5, 8],
  range: [1.5, 3.4, 4.4],
  tour: [[200, 138], [125, 130], [200, 243], null],
  mount,
});

mats.code:
/**
 * Gym mat: a folding mat of four panels laid in a row. The pointer picks a
 * panel by where it stands on the floor: the panel tilts up on its hinge,
 * folding toward the far end, and the panels beside it tilt a little,
 * staggered from it. At rest one panel is half raised, bright. The slider
 * is the stagger.
 */
const { Cam, fit, fillet, hull, poly, proj, clamp, rad, tdone, tset, tval, tween, unproj, disposer, mk, pointer, register, solid } = HL;

const N = 4, W = 36, DY = 58, T = 6, FAV = 1, UP = 68, REST = 34;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [N * W, 0, 0], [0, DY, 0], [N * W, DY, 0], [W * 0.4, 0, W], [W * 0.4, DY, W]], 200, 172);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const items = [];
  for (let k = 0; k < N; k++) items.push({ k, s: solid(g), x1: (k + 1) * W, z: tween(k === FAV ? REST : 3 + 2 * k), last: NaN });

  function pt(it, a, u, h, y) {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return P(it.x1 - u * c + (h - T) * s, y, T + u * s + (h - T) * c);
  }
  function draw(it, a) {
    if (a === it.last) return;
    it.last = a;
    const pts = [];
    for (const u of [0, W]) for (const h of [0, T]) for (const y of [0, DY]) pts.push(pt(it, a, u, h, y));
    const hl = hull(pts);
    it.s.sil.setAttribute("d", poly(fillet(hl, hl.map(() => 1.6))));
    const e = 1.6, top = [pt(it, a, e, T, e), pt(it, a, W - e, T, e), pt(it, a, W - e, T, DY - e), pt(it, a, e, T, DY - e)];
    it.s.cr.setAttribute("d", poly(fillet(top, [1, 1, 1, 1])));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (y < -6 || y > DY + 6 || x < -6 || x > N * W + 6) return -1;
    return clamp(Math.floor(x / W), 0, N - 1);
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? REST : 3 + 2 * k) : dd === 0 ? UP : dd === 1 ? 22 : 5;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "panel " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

