mutebox.code:
/**
 * Rosin: three round rosin tins in a row, each lid hinged at its far edge
 * over an amber cake. The pointer picks a tin by where it stands: its lid
 * swings open and the lids beside it crack a little, staggered from it. At
 * rest one lid stands half open, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single row (riffle), a hinge instead of a lift.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, R = 24, STEP = 58, H = 7, LT = 4, OPEN = 105, FAV = 1;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  const X1 = (N - 1) * STEP;
  fit(C, [[-R - 4, -R - 4, 0], [X1 + R + 4, R + 4, 0], [-2 * R, 0, H + 2 * R], [X1 - 2 * R, 0, H + 2 * R], [X1 + R, -R, 0], [-R, R, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = k * STEP, grp = mk("g", {}, g);
    const lid = mk("g", {}, grp);
    const body = mk("g", {}, grp);
    put(solid(body), prism(P, front, disc(x, 0, R), disc(x, 0, R - 2), 0, H));
    mk("path", { class: "nf lo", d: poly(ringAt(P, disc(x, 0, R - 5, 32), H - 1)) }, body);
    mk("path", { class: "nf lo", d: poly(ringAt(P, disc(x + 3, 2, 6, 20), H - 1)) }, body);
    const ls = mk("path", { class: "sil" }, lid), lc = mk("path", { class: "nf lo" }, lid);
    items.push({ k, x, grp, lid, body, ls, lc, a: tween(k === FAV ? 50 : 0), last: NaN, behind: null });
  }

  function lidPts(x, deg, rr, dz) {
    const t = (deg * Math.PI) / 180, c = Math.cos(t), s = Math.sin(t), hx = x - R;
    return disc(x, 0, rr, 40).map((q) => { const dx = q.u - hx; return P(hx + dx * c - dz * s, q.v, H + dx * s + dz * c); });
  }
  function draw(it, deg) {
    if (deg === it.last) return;
    it.last = deg;
    const pts = lidPts(it.x, deg, R + 0.6, 0).concat(lidPts(it.x, deg, R + 0.6, LT));
    it.ls.setAttribute("d", poly(hull(pts)));
    it.lc.setAttribute("d", poly(lidPts(it.x, deg, R - 2, LT)));
    const behind = deg > 40;
    if (behind !== it.behind) { it.behind = behind; if (behind) it.lid.after(it.body); else it.body.after(it.lid); }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.a, now)); if (!tdone(it.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, H));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 70 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), z = a < 0 ? (k === FAV ? 50 : 0) : dd === 0 ? OPEN : dd === 1 ? 18 : 0;
      tset(it.a, z, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.ls.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "tin " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "mutebox",
  means: "Three rosin tins in a row: the lid under the pointer swings open on its hinge, and its neighbours crack open a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[116, 150], [200, 192], [284, 234], null],
  mount,
});

drumkey.code:
/**
 * Drum key: a T-handled tuning key seated on a tension rod at the rim of a
 * snare. The pointer is where the hand turns it: the key's paddle swings on
 * a spring to point at the pointer, round its square socket. At rest it sits
 * a quarter-turn askew, bright. The slider is how stiff the turn is.
 *
 * The pattern: a continuous aim on one part; the hit is the floor's plane.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 44, H = 18, KX = 18, KY = 18, ROD = 26, SOCK = 44, WING = 66, REST = 0.55;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const turn = (ring, a, cx, cy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [KX - 30, KY - 30, WING], [KX + 30, KY + 30, WING], [KX - 30, KY + 30, WING], [KX + 30, KY - 30, WING]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(R, 64), circ(R - 2.5, 64), 0, H));
  mk("path", { class: "nf lo", d: "M" + circ(R - 7, 64).map((q) => P(q.u, q.v, H).join(",")).join("L") + "Z" }, g);
  put(solid(g), prism(P, front, disc(KX, KY, 5, 20), disc(KX, KY, 4, 20), H, H + 3));
  put(solid(g), prism(P, front, disc(KX, KY, 2, 16), null, H + 3, ROD));
  const [sq, sqi] = rings(-4.5, -4.5, 4.5, 4.5, 1.5, 0.8);
  const sock = solid(g), neck = solid(g), wing = solid(g);
  const [wr, wi] = rings(-28, -3.2, 28, 3.2, 3, 1);
  const [nr] = rings(-6, -2.6, 6, 2.6, 2, 0.6);
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    put(sock, prism(P, front, turn(sq, a, KX, KY), turn(sqi, a, KX, KY), ROD - 6, SOCK));
    put(neck, prism(P, front, turn(nr, a, KX, KY), null, SOCK, SOCK + 4));
    put(wing, prism(P, front, turn(wr, a, KX, KY), turn(wi, a, KX, KY), SOCK + 4, WING));
  }
  wing.sil.classList.add("hi");
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [wx, wy] = unproj(C, sx, sy, 0);
      const want = Math.atan2(wy - KY, wx - KX);
      sp.t = sp.x + wrap(want - sp.x);
      read.textContent = "turn " + Math.round(((want * 180) / Math.PI + 360) % 180);
      B.wake();
    },
    leave: () => { sp.t = sp.x + wrap(REST - sp.x); read.textContent = "rest"; B.wake(); },
  }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

