    if (deg === last) return;
    last = deg;
    const tf = (p) => R(p, [CX + RB, CY, ZS], "y", rad(deg));
    const pts = [];
    for (const z of [ZS, ZS + HB / 2, ZS + HB]) for (const q of ring(z, z === ZS + HB / 2 ? RB + 2 : RB)) pts.push(P(...tf(q)));
