    const parts = move(x, 0).map((s) => { const el = mk("path", { class: s.sil ? "sil" : s.nf ? (s.lo ? "nf lo" : "nf") : "" }, grp); if (s.sil) hi.push(el); return el; });
    items.push({ k, x, parts, hi, v: tween(k === FAV ? 0.7 : 0), last: NaN });
  }
  function draw(it, v) {
    if (v === it.last) return;
