const SPINE = () => [];
const hole = (a, b, c) => { const r = []; for (let i = 0; i < 20; i++) { const t = (i / 20) * 2 * Math.PI; r.push([a, b + 4.5 * Math.cos(t), c + 4.5 * Math.sin(t)]); } return r; };
