  const shape = (pts) => hull(pts.map(([x, y, z]) => P(x, y, z)));
  const line = (pts) => pts.map(([x, y, z]) => P(x, y, z));
  const path = (s) => poly(s.open !== undefined ? line(s.pts) : shape(s.pts));
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-6, -6, X1 + 6, 2 * W + 6, 6, 2);
  put(solid(g), prism(P, front, cr, ci, 0, CZ));
  for (const s of SPINE()) mk("path", { d: path(s) }, g);
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = W + k * STEP, grp = mk("g", {}, g), hi = [];
    for (const s of still(x)) { const el = mk("path", { d: path(s), class: s.sil ? "sil" : s.nf ? "nf" : "" }, grp); if (s.sil) hi.push(el); }
    const parts = move(x, 0).map((s) => { const el = mk("path", { class: s.sil ? "sil" : s.nf ? (s.lo ? "nf lo" : "nf") : "" }, grp); if (s.sil) hi.push(el); return el; });
    items.push({ k, x, parts, hi, v: tween(k === FAV ? 0.7 : 0), last: NaN });
  }
  function draw(it, v) {
    if (v === it.last) return;
    it.last = v;
    move(it.x, v).forEach((s, i) => it.parts[i].setAttribute("d", path(s)));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.v, now)); if (!tdone(it.v, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);
  const mids = items.map((it) => P(it.x, W, CZ));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const dd = Math.abs(m[0] - sx); if (dd < bd) { bd = dd; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - sy) < 100 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const dd = Math.abs(k - a), v = a < 0 ? (k === FAV ? 0.7 : 0) : dd === 0 ? 1 : dd === 1 ? NB : dd === 2 ? NB / 2 : 0;
      tset(it.v, v, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      for (const el of it.hi) el.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "nestbox2",
  means: "three bird boxes on a rail, each with a pitched roof. The pointer picks a box",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[149,127],[200,152],[251,178],null],
  mount,
});

incentive.code:
/**
 * Incentive spirometer: three clear chambers on a base, a ball in each. The
 * pointer picks a chamber by its screen x: its ball rises to the top and the
 * balls beside it rise less, staggered from it. At rest the first ball floats
 * halfway, bright. The slider is the stagger.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, ringAt, circ, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, STEP = 24, TR = 11, BR = 10, Z0 = 6, TH = 50;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.5);
  const X1 = (N - 1) * STEP + 2 * TR + 8;
  fit(C, [[-4, -4, 0], [X1, 2 * TR + 8, 0], [X1, -4, 0], [-4, 2 * TR + 8, 0], [TR, TR, Z0 + TH + 4], [X1 - TR, TR, Z0 + TH + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, X1, 2 * TR + 8, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, Z0));
  const items = [];
  for (let k = 0; k < N; k++) {
    const x = TR + 4 + k * STEP, y = TR + 4, grp = mk("g", {}, g);
    const ball = mk("path", { class: "nf" }, grp), bcr = mk("path", { class: "nf lo" }, grp);
    const tube = solid(grp);
    put(tube, prism(P, front, disc(x, y, TR), disc(x, y, TR - 1.5), Z0, Z0 + TH));
    tube.sil.classList.add("nf");
    items.push({ k, x, y, ball, bcr, z: tween(k === 0 ? 0.75 : k === 1 ? 0.25 : 0), last: NaN });
  }
  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    const c = P(it.x, it.y, Z0 + BR + h * (TH - 2 * BR)), r = BR * C.S;
    const pts = (rr) => Array.from({ length: 28 }, (_, i) => [c[0] + rr * Math.cos((i / 28) * 6.2832), c[1] + rr * Math.sin((i / 28) * 6.2832)]);
    it.ball.setAttribute("d", poly(pts(r)));
    it.bcr.setAttribute("d", poly(pts(r * 0.55)));
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);
  const mids = items.map((it) => P(it.x, it.y, Z0 + TH / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 28 && Math.abs(mids[best][1] - sy) < 90 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), h = a < 0 ? (k === 0 ? 0.75 : k === 1 ? 0.25 : 0) : d === 0 ? 1 : d === 1 ? 0.4 : 0.1;
      tset(it.z, h, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.ball.classList.toggle("hi", k === (a < 0 ? 0 : a));
    });
    read.textContent = a < 0 ? "rest" : "ball " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "incentive",
  means: "An incentive spirometer: the pointer picks a chamber and its ball rises to the top, the balls beside it rising less.",
  rules: [1, 2, 4, 5],
  range: [0, 45, 90],
  tour: [[158, 120], [200, 133], [242, 146], null],
  mount,
});

pillsplitter.code:
/**
 * Pill splitter: a rounded clamshell case, a blade under its lid and a pill
 * waiting in the cradle. The pointer over the case swings the lid open on its
 * far hinge to show the pill; at rest the lid stands ajar, bright.
 * The slider is how far the lid opens.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, circ, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 70, D = 46, BH = 12, LT = 9, REST = 22;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, -LT, BH + D], [W, -LT, BH + D], [W, D, BH + LT]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g);
  const baseG = mk("g", {}, g);
  const [br, bi] = rings(0, 0, W, D, 9, 2);
  put(solid(baseG), prism(P, front, br, bi, 0, BH));
  // the cradle: a shallow V well with a pill in it
  mk("path", { d: poly(ringAt(P, rrect(12, 14, W - 12, D - 14, 8, 6), BH)), class: "nf lo" }, baseG);
  const pill = [];
  for (const [x, r] of [[W / 2 - 7, 6], [W / 2, 6], [W / 2 + 7, 6]]) pill.push(...ringAt(P, disc(x, D / 2, r), BH), ...ringAt(P, disc(x, D / 2, r), BH + 4));
  mk("path", { d: poly(hull(pill)), class: "nf" }, baseG);
  mk("path", { d: poly(ringAt(P, disc(W / 2, D / 2, 1.4, 12), BH + 4)), class: "nf lo" }, baseG);

  const lid = mk("path", { class: "sil" }, lidG), lcr = mk("path", { class: "nf lo" }, lidG), blade = mk("path", { class: "nf lo" }, lidG);
  const [lr, li] = [rrect(0, 0, W, D, 9, 4), rrect(2, 2, W - 2, D - 2, 7, 4)];
  const ang = tween(REST * open);
  let last = NaN;
  // rotate about the hinge line y = 0, z = BH
  const R = (a) => (q, zl) => { const t = (a * Math.PI) / 180, y = q.v * Math.cos(t) - zl * Math.sin(t), z = BH + q.v * Math.sin(t) + zl * Math.cos(t); return P(q.u, y, z); };
  function draw(a) {
    if (a === last) return;
    last = a;
    const f = R(a);
    lid.setAttribute("d", poly(hull(lr.map((q) => f(q, 0)).concat(lr.map((q) => f(q, LT))))));
    lcr.setAttribute("d", poly(li.map((q) => f(q, a > 90 ? 0 : LT))));
    blade.setAttribute("d", a > 30 ? poly([f({ u: 10, v: D / 2 }, -0.1), f({ u: W - 10, v: D / 2 }, -0.1), f({ u: W - 10, v: D / 2 + 1 }, -0.1), f({ u: 10, v: D / 2 + 1 }, -0.1)]) : "");
    if (a > 88) g.insertBefore(lidG, baseG); else baseG.after(lidG);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? 40 + 75 * open : REST, performance.now(), 0);
    lid.classList.add("hi");
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, BH); return x > -6 && x < W + 6 && y > -10 && y < D + 6; };
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; act = null; }, destroy: bag.dispose };
}

hairline({
  name: "pillsplitter",
  means: "A clamshell pill splitter: the pointer over the case swings its lid open on the hinge to show the pill in the cradle.",
  rules: [1, 4, 5, 6],
  range: [0.4, 1, 1],
  tour: [[200, 190], [160, 180], [240, 195], null],
  mount,
});

handsanitizer.code:
/**
 * Sanitizer stand: a floor stand, a pole, and a square bottle with a pump on
 * a turntable cradle. The pointer over the stand turns the bottle round so
 * the pump's nozzle swings toward the reader; at rest it stands half turned,
 * the bottle bright. The slider is how far it turns.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, circ, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PH = 70, BW = 30, BD = 18, BT = 56, REST = 25;
const disc = (r, n = 24) => circ(r, n);
const rot = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let turn = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[-36, -36, 0], [36, 36, 0], [36, -36, 0], [-36, 36, 0], [0, 0, PH + 4 + BT + 16]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-36, -36, 36, 36, 12, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  mk("path", { d: poly(ringAt(P, disc(10, 20), 4)), class: "nf lo" }, g);
  put(solid(g), prism(P, front, disc(3.2), disc(2), 4, PH));
  const parts = [
    { ring: rrect(-18, -14, 18, 14, 6, 4), inner: rrect(-16, -12, 16, 12, 4, 4), z0: PH, z1: PH + 4 },
    { ring: rrect(-BW / 2, -BD / 2, BW / 2, BD / 2, 6, 4), inner: rrect(-BW / 2 + 2, -BD / 2 + 2, BW / 2 - 2, BD / 2 - 2, 4, 4), z0: PH + 4, z1: PH + 4 + BT, hi: true },
    { ring: disc(4.5, 16), inner: disc(3, 16), z0: PH + 4 + BT, z1: PH + 4 + BT + 6 },
    { ring: disc(2, 12), inner: disc(1, 12), z0: PH + 10 + BT, z1: PH + 14 + BT },
    { ring: rrect(-4, -4, 20, 4, 3, 4), inner: rrect(-2.5, -2.5, 18.5, 2.5, 2, 4), z0: PH + 14 + BT, z1: PH + 19 + BT },
  ].map((p) => ({ ...p, s: solid(g) }));
  const bottle = parts[1].s;
  const label = mk("path", { class: "nf lo" }, bottle.g);
  const ang = tween(REST * turn);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const t = (a * Math.PI) / 180;
    for (const p of parts) put(p.s, prism(P, front, rot(p.ring, t), rot(p.inner, t), p.z0, p.z1));
    // a window strip on the bottle's front face: the level it holds
    const fx = BW / 2, pts = [[fx, -5, PH + 14], [fx, 5, PH + 14], [fx, 5, PH + 40], [fx, -5, PH + 40]].map(([u, v, z]) => { const c = Math.cos(t), s = Math.sin(t); return P(u * c - v * s, u * s + v * c, z); });
    label.setAttribute("d", Math.cos(t - Math.PI / 4) > 0.15 ? poly(pts) : "");
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const c0 = P(0, 0, 0), c1 = P(0, 0, PH + BT + 20);
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? REST * turn + 120 * turn : REST * turn, performance.now(), 0);
    bottle.sil.classList.add("hi");
    read.textContent = a ? "pump" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => Math.abs(sx - c0[0]) < 70 && sy < c0[1] + 40 && sy > c1[1] - 10;
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { turn = v; act = null; }, destroy: bag.dispose };
}

hairline({
  name: "handsanitizer",
  means: "A sanitizer stand: the pointer over it turns the pump bottle on its cradle so the nozzle swings round to the reader.",
  rules: [1, 4, 5, 9],
  range: [0.4, 1, 1],
  tour: [[200, 120], [200, 200], [210, 80], null],
  mount,
});

tourniquet.code:
/**
 * Tourniquet: a strap band standing as a loop, a buckle block on its near
 * side and a windlass rod across the buckle. The pointer over it turns the
 * rod and the loop draws tight; at rest the rod lies half turned, bright.
 * The slider is how tight it draws.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rrect, circ, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R0 = 44, R1 = 28, H = 16, REST = 0.2;
const rot = (ring, a, x, y) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: x + q.u * c - q.v * s, v: y + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let pull = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-R0, -R0, 0], [R0 + 8, R0 + 8, 0], [R0, -R0, 0], [-R0, R0, 0], [R0, R0, H + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const loop = solid(g), hole = mk("path", { class: "nf" }, loop.g);
  const buckle = solid(g), rod = solid(g), cap = solid(g);
  const t = tween(REST);
  let last = NaN;
  function draw(k) {
    if (k === last) return;
    last = k;
    const R = R0 + (R1 - R0) * k, a = Math.PI / 4;
    put(loop, prism(P, front, circ(R, 56), circ(R - 2, 56), 0, H));
    hole.setAttribute("d", poly(ringAt(P, circ(R - 3, 56), H)));
    const bx = R * Math.cos(a), by = R * Math.sin(a);
    put(buckle, prism(P, front, rot(rrect(-6, -12, 6, 12, 3, 4), a, bx, by), rot(rrect(-4.5, -10.5, 4.5, 10.5, 2, 4), a, bx, by), -1, H + 3));
    const ra = a + 0.4 + k * 2.2;
    put(rod, prism(P, front, rot(rrect(-3, -26, 3, 26, 3, 4), ra, bx, by), rot(rrect(-1.8, -24.8, 1.8, 24.8, 1.8, 4), ra, bx, by), H + 3, H + 8));
    put(cap, prism(P, front, rot(circ(3.4, 16), 0, bx, by), rot(circ(2, 16), 0, bx, by), H + 8, H + 10));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a ? 0.35 + 0.65 * pull : REST, performance.now(), 0);
    rod.sil.classList.add("hi");
    read.textContent = a ? "tight" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, H); return Math.hypot(x, y) < R0 + 14; };
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { pull = v; act = null; }, destroy: bag.dispose };
}

hairline({
  name: "tourniquet",
  means: "A tourniquet loop with a buckle: the pointer over it turns the windlass rod and the strap draws tight.",
  rules: [1, 4, 5, 9],
  range: [0.4, 1, 1],
  tour: [[200, 128], [150, 150], [240, 190], null],
  mount,
});

bpcuff.code:
/**
 * Wrist monitor: a cuff lying on its side as a short open sleeve, with the
 * monitor unit on top, its screen and one button. The pointer over it inflates
 * the cuff, the sleeve swelling and lifting the unit; at rest it is slightly
 * full, the unit bright. The slider is how far it inflates.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rrect, circ, rings, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 34, R0 = 16, R1 = 23, REST = 0.25;
// a circle standing in the y-z plane at x, centre (y0, z0)
const ring = (x, r, z0, n = 40) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push([x, r * Math.cos(t), z0 + r * Math.sin(t)]); } return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let inf = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-L, -R1, 0], [L, R1, 0], [L, -R1, 0], [-L, R1, 0], [0, 0, 2 * R1 + 12]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const sleeve = mk("path", { class: "sil" }, g), end = mk("path", { class: "nf lo" }, g), bore = mk("path", { class: "nf" }, g), seam = mk("path", { class: "nf lo" }, g);
  const unit = solid(g), screen = mk("path", { class: "nf lo" }, unit.g), btn = mk("path", { class: "nf" }, unit.g);
  const t = tween(REST);
  let last = NaN;
  const pp = (pts) => pts.map(([x, y, z]) => P(x, y, z));
  function draw(k) {
    if (k === last) return;
    last = k;
    const R = R0 + (R1 - R0) * k;
    sleeve.setAttribute("d", poly(hull(pp(ring(-L, R, R).concat(ring(L, R, R))))));
    end.setAttribute("d", poly(pp(ring(L, R, R))));
    bore.setAttribute("d", poly(pp(ring(L, R0 - 6, R))));
    seam.setAttribute("d", poly(pp(ring(L - 8, R, R).slice(0, 21))).replace("Z", ""));
    const z = 2 * R - 2;
    const [ur, ui] = rings(-16, -13, 16, 13, 6, 2);
    put(unit, prism(P, front, ur, ui, z, z + 9));
    screen.setAttribute("d", poly(rrect(-11, -9, 5, 9, 3, 4).map((q) => P(q.u, q.v, z + 9))));
    btn.setAttribute("d", poly(circ(2.6, 14).map((q) => P(q.u + 10, q.v, z + 9))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a ? 0.4 + 0.6 * inf : REST, performance.now(), 0);
    unit.sil.classList.add("hi");
    read.textContent = a ? "inflate" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, R0); return Math.abs(x) < L + 10 && Math.abs(y) < R1 + 14; };
  setActive(false);
