  setOn(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setOn(Math.hypot(sx - ctr[0], sy - ctr[1]) < HITR), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v / 100; if (on) { ang.t = REST + (ACT - REST) * amt; B.wake(); } }, destroy: bag.dispose };
}

