  name: "rubikcube",
  means: "A twist puzzle cube: its top layer turns about the axis to follow the pointer, and settles a little twisted at rest.",
  rules: [3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[110, 150], [300, 170], [230, 120], null],
  mount,
});

dartsboard2.code:
/**
 * Ring board: a square hoopla board with nine pegs, rings dropped over
 * three of them, on a low stand. The board turns about its centre to
 * follow the pointer across the frame; the ring on the middle peg is bright
 * at rest. The slider is how far it turns.
 *
 * The pattern: one part turning to follow the pointer (spotlights).
 */
const { Cam, circ, fit, facing, prism, proj, rings, rrect, clamp, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const W = 96, M = W / 2, T = 6, PH = 20, REST = 0.28;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const PEGS = [];
for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) PEGS.push([18 + i * 30, 18 + j * 30, i * 3 + j]);
const RINGED = new Set([4, 0, 7]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-20, -20, 0], [W + 20, W + 20, 0], [W + 20, -20, 0], [-20, W + 20, 0], [M, M, T + 4 + PH]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(M - 30, M - 30, M + 30, M + 30, 8, 1.5);
  put(solid(g), prism(P, front, sr, si, 0, 4));
  const rot = (a) => (u, v) => [M + (u - M) * Math.cos(a) - (v - M) * Math.sin(a), M + (u - M) * Math.sin(a) + (v - M) * Math.cos(a)];
  const turn = (ring, a) => ring.map((q) => { const [u, v] = rot(a)(q.u, q.v); return { u, v, nu: q.nu * Math.cos(a) - q.nv * Math.sin(a), nv: q.nu * Math.sin(a) + q.nv * Math.cos(a) }; });
  const board = solid(g), b0 = rrect(0, 0, W, W, 6, 4), b1 = rrect(1.6, 1.6, W - 1.6, W - 1.6, 5, 4);
  const pg = mk("g", {}, g);
  const parts = PEGS.map(([x, y, k]) => {
    const grp = mk("g", {}, pg);
    const ring = RINGED.has(k) ? solid(grp) : null, peg = solid(grp);
    if (k === 4) ring.sil.classList.add("hi");
    return { x, y, k, grp, ring, peg };
  });
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    put(board, prism(P, front, turn(b0, a), turn(b1, a), 4, 4 + T));
    const R = rot(a);
    for (const p of parts) {
      const [u, v] = R(p.x, p.y);
      p.d = u + v;
      if (p.ring) put(p.ring, prism(P, front, disc(u, v, 10, 32), disc(u, v, 4.5, 32), 4 + T, 4 + T + 2.6));
      put(p.peg, prism(P, front, disc(u, v, 2.6), disc(u, v, 1.6), 4 + T, 4 + T + PH));
    }
    parts.slice().sort((A, Bb) => A.d - Bb.d).forEach((p) => pg.appendChild(p.grp));
  }
  const sp = spring(REST, { k: 90, c: 16 });
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function aim(t, r) { sp.t = t; read.textContent = r ? "rest" : Math.round((t * 180) / Math.PI) + "°"; B.wake(); }
  aim(REST, 1);
  bag.add(pointer(stage, { move: ([sx]) => aim(clamp((sx - 200) / 130, -1, 1) * 0.75 * gain), leave: () => aim(REST, 1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

hairline({
  name: "dartsboard2",
  means: "A hoopla ring board with nine pegs on a stand: the board turns about its centre to follow the pointer, rings riding on it.",
  rules: [3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[100, 150], [310, 170], [230, 120], null],
  mount,
});

lotto.code:
/**
 * Bingo dabber: a squat ink bottle with a tall cap, standing beside a card
 * with a few squares already dabbed. Raising the pointer slides the cap up
 * off the sponge tip; at rest it sits a little ajar, bright. The slider is
 * how far it can lift.
 *
 * The pattern: one part sliding to follow the pointer.
 */
const { Cam, circ, fit, facing, prism, proj, rings, clamp, spring, stepS, disposer, mk, flatDot, place, pointer, put, register, solid } = HL;

const BR = 17, BH = 44, NR = 11, NH = 6, TR = 7, TH = 6, CR = 13, CH = 40, LIFT = 34, REST = 5;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-BR, -BR, 0], [100, 44, 0], [100, -34, 0], [-BR, 44, 0], [0, 0, BH + NH + CH + LIFT + 2]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the card, with its squares
  const [cr, ci] = rings(30, -34, 100, 44, 4, 1.4);
  put(solid(g), prism(P, front, cr, ci, 0, 1.6));
  const dabbed = new Set([0, 4, 8, 5]);
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
    const d = flatDot(g, C, dabbed.has(i * 3 + j) ? 6 : 2.4, dabbed.has(i * 3 + j) ? "dot m" : "dot off");
    place(d, P(44 + i * 21, -18 + j * 23, 1.6));
  }
  put(solid(g), prism(P, front, disc(BR), disc(BR - 2.5), 0, BH));
  put(solid(g), prism(P, front, disc(NR), disc(NR - 1.5), BH, BH + NH));
  put(solid(g), prism(P, front, disc(TR), disc(TR - 1.5), BH + NH, BH + NH + TH));
  const cap = solid(g), band = solid(g);
  cap.sil.classList.add("hi");
  let last = NaN;
  function draw(l) {
    if (l === last) return;
    last = l;
    const z = BH + 1 + l;
    put(cap, prism(P, front, disc(CR), disc(CR - 2), z, z + CH));
    put(band, prism(P, front, disc(CR + 1.2), disc(CR - 1), z, z + 7));
  }
  const sp = spring(REST, { k: 120, c: 18 });
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function aim(t, r) { sp.t = t; read.textContent = r ? "rest" : t > 16 ? "open" : "shut"; B.wake(); }
  aim(REST, 1);
  bag.add(pointer(stage, { move: ([, sy]) => aim(clamp((250 - sy) / 170, 0, 1) * LIFT * gain), leave: () => aim(REST, 1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

hairline({
  name: "lotto",
  means: "A bingo dabber beside a dabbed card: raising the pointer slides its cap up off the sponge tip, and it rests a little ajar.",
  rules: [3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[200, 120], [200, 60], [230, 200], null],
  mount,
});

wheelfortune.code:
/**
 * Fortune wheel: a big upright wheel on a post, twelve spokes and a peg at
 * each rim gap, a fixed flapper at the top. The wheel spins with the pointer
 * across the frame; one spoke, the winner, is bright at rest. The slider is
 * how far a sweep spins it.
 *
 * The pattern: one part turning to follow the pointer (spotlights).
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, seg, clamp, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const R = 56, ZC = 74, TH = 8, N = 12, REST = 0.35;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-R, -30, 0], [R, 16, 0], [-R, 0, ZC + R + 8], [R, -TH, ZC + R + 8], [R, 16, 0]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-34, -34, 34, 14, 6, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  const [pr, pi] = rings(-5, -22, 5, -12, 2, 0.8);
  put(solid(g), prism(P, front, pr, pi, 5, ZC));
  const W = (r, t, y) => P(r * Math.cos(t), y, ZC + r * Math.sin(t));
  const back = [], fr = [], inner = [];
  for (let i = 0; i < 64; i++) { const t = (i / 64) * 2 * Math.PI; back.push(W(R, t, -TH)); fr.push(W(R, t, 0)); inner.push(W(R - 7, t, 0)); }
  mk("path", { d: poly(hull(back.concat(fr))), class: "sil" }, g);
  mk("path", { d: poly(fr), class: "nf" }, g);
  mk("path", { d: poly(inner), class: "nf lo" }, g);
  const spokes = mk("path", { class: "nf lo" }, g), win = mk("path", { class: "nf hi" }, g);
  const pegs = [];
  for (let k = 0; k < N; k++) pegs.push(mk("circle", { r: 1.6, class: "dot off" }, g));
  const hub = [];
  for (let i = 0; i < 24; i++) hub.push(W(7, (i / 24) * 2 * Math.PI, 2));
  mk("path", { d: poly(hub), class: "" }, g);
  // the flapper: a small wedge pointing down at the rim
  mk("path", { d: poly([W(0, 0, 2).map((v, j) => v), P(-4, 2, ZC + R + 9), P(4, 2, ZC + R + 9)].slice(0, 0).concat([P(0, 2, ZC + R - 6), P(-5, 2, ZC + R + 8), P(5, 2, ZC + R + 8)])), class: "" }, g);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    let s = "";
    for (let k = 1; k < N; k++) { const t = a + (k * 2 * Math.PI) / N; s += seg(W(7, t, 0), W(R - 7, t, 0)); }
