 * round knob, held above the paper with an earlier print beside it. At rest
 * the knob is bright. The pointer over the sheet brings the stamp down onto
 * the paper and its rubber block takes the bright. The slider is the hover height.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 84, D = 64, CX = 50, CY = 30;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let up = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [CX, CY, 70]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(0, 0, W, D, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, 0, 1.2));
  mk("path", { class: "nf lo", d: poly(ringAt(P, rings(8, 40, 34, 58, 3, 1)[0], 1.2)) }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, disc(21, 49, 4), 1.2)) }, g);
  const print = mk("path", { class: "nf", d: poly(ringAt(P, rings(CX - 16, CY - 12, CX + 16, CY + 12, 3, 1)[0], 1.2)) }, g);
  const blk = solid(g), neck = solid(g), knob = mk("path", { class: "sil" }, g), kcr = mk("path", { class: "nf lo" }, g);
  const [br, bi] = rings(CX - 16, CY - 12, CX + 16, CY + 12, 3, 1.5);
  const z = tween(up);
  let last = NaN;
  function draw(z0) {
    if (z0 === last) return;
    last = z0;
    put(blk, prism(P, front, br, bi, z0, z0 + 9));
    put(neck, prism(P, front, disc(CX, CY, 4.5), disc(CX, CY, 3.5), z0 + 9, z0 + 22));
    const pts = [];
    for (const [r, h] of [[6, 0], [10, 3], [11, 6], [9.5, 10], [5, 13]]) pts.push(...ringAt(P, disc(CX, CY, r), z0 + 22 + h));
    knob.setAttribute("d", poly(hull(pts)));
    kcr.setAttribute("d", poly(ringAt(P, disc(CX, CY, 9), z0 + 32)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(z, v ? 1.2 : up, performance.now(), 0);
    knob.classList.toggle("hi", !v);
    blk.sil.classList.toggle("hi", v);
    read.textContent = v ? "press" : "rest";
    B.wake();
  }
  setOn(false);
  function hit([sx, sy]) { const [x, y] = unproj(C, sx, sy, 0); return x > -6 && x < W + 6 && y > -6 && y < D + 6; }
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { up = v; if (!on) { tset(z, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "loanstamp",
  means: "A rubber stamp held over a sheet: the pointer over the paper brings it down to press a fresh print.",
  rules: [1, 4, 5, 6],
  range: [18, 26, 34],
  tour: [[167, 211], [184, 150], [216, 250], null],
  mount,
});

officechair.code:
/**
 * Chair lever: an office chair on a cross base and gas column, a lever
 * under the seat. The pointer over the chair pulls the lever: the seat,
 * back and lever sink down the column. At rest the lever is bright.
 */
const { Cam, facing, fit, prism, proj, rings, unproj, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const SZ = 34, DROP = 13;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let drop = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-24, -24, 0], [24, 24, 0], [32, 8, SZ], [-16, -24, SZ + 44], [24, -24, SZ + 44]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (el, x0, y0, x1, y1, r, b, z0, z1) => { const [ri, ii] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, ri, ii, z0, z1)); };

  box(solid(g), -24, -3, 24, 3, 3, 1, 0, 3);
  box(solid(g), -3, -24, 3, 24, 3, 1, 0, 3);
  const col = solid(g), back = solid(g), post = solid(g), lever = solid(g), seat = solid(g);
  const h = tween(0);
  let last = "";
  function draw(d) {
    const k = d.toFixed(2); if (k === last) return; last = k;
    const z = SZ - d;
    box(col, -3, -3, 3, 3, 3, 1, 3, z);
    box(back, -16, -25, 16, -20, 5, 1.2, z + 12, z + 44);
    box(post, -3, -22, 3, -18, 1.5, 0.6, z, z + 14);
    box(lever, 14, 3, 31, 7, 1.5, 0.6, z - 3, z - 1);
    box(seat, -18, -19, 18, 19, 7, 1.6, z, z + 6);
  }
  const B = register(stage, (_dt, now) => { draw(tval(h, now)); return !tdone(h, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, SZ);
    if (x > -22 && x < 34 && y > -28 && y < 22) return 1;
    const [gx, gy] = unproj(C, sx, sy, 0);
    return Math.abs(gx) < 26 && Math.abs(gy) < 26 ? 1 : 0;
  }
  let act = -1;
  function setActive(a) {
    if (a === act) return; act = a;
    tset(h, a ? drop : 0, performance.now(), 0);
    lever.sil.classList.toggle("hi", !a);
    seat.sil.classList.toggle("hi", !!a);
    read.textContent = a ? "lever" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { drop = v; if (act) { tset(h, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "officechair",
  means: "An office chair: pull the gas lever and the seat and back sink down the column.",
  rules: [1, 5, 8],
  range: [6, 13, 18],
  tour: [[151, 159], [192, 215], [151, 250], null],
  mount,
});

deskstand.code:
/**
 * Book end: four books standing loose on a desk with a sliding L-shaped
 * book end beside them. The pointer over the row slides the book end in,
 * and the books close up against each other, staggered from it. At rest the
 * book end stands out, bright.
 */
const { Cam, facing, fit, prism, proj, rings, unproj, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = [7, 9, 6, 8], H = [40, 46, 36, 42], D = 26;
const REST = [0, 12, 27, 38], PACK = [0, 7.6, 17.2, 23.8], E0 = 58, E1 = 32.6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let step = value;
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[-2, 0, 0], [E0 + 6, D, 0], [-2, 0, 46], [E0 + 4, 0, 52], [E0 + 6, D, 0]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (el, x0, y0, x1, y1, r, b, z0, z1) => { const [ri, ii] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, ri, ii, z0, z1)); };

  const books = W.map((w, k) => ({ w, h: H[k], el: solid(g), x: tween(REST[k]), last: "" }));
  const end = { up: solid(g), foot: solid(g), x: tween(E0), last: "" };
  function drawBook(b, x) { const key = x.toFixed(2); if (key === b.last) return; b.last = key; box(b.el, x, 0, x + b.w, D, 1.4, 0.7, 0, b.h); }
  function drawEnd(x) {
    const key = x.toFixed(2); if (key === end.last) return; end.last = key;
    box(end.up, x, 1, x + 3, D - 1, 1.2, 0.6, 0, 52);
    box(end.foot, x - 14, 2, x + 3, D - 2, 1.2, 0.6, 0, 2);
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    books.forEach((b) => { drawBook(b, tval(b.x, now)); if (!tdone(b.x, now)) m = true; });
    drawEnd(tval(end.x, now)); if (!tdone(end.x, now)) m = true;
    return m;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 24);
    return x > -4 && x < E0 + 8 && y > -24 && y < D + 24 ? 1 : 0;
  }
  let act = -1;
  function setActive(a) {
    if (a === act) return; act = a;
    const now = performance.now();
    tset(end.x, a ? E1 : E0, now, 0);
    books.forEach((b, k) => tset(b.x, a ? PACK[k] : REST[k], now, (books.length - k) * step));
    end.up.sil.classList.toggle("hi", !a);
    books[3].el.sil.classList.toggle("hi", !!a);
    read.textContent = a ? "slide" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { step = v; }, destroy: bag.dispose };
}

hairline({
  name: "deskstand",
  means: "Four loose books and a book end: the end slides in and the books close up against it, one after another.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[125, 127], [172, 150], [215, 225], null],
  mount,
});

noteholder.code:
/**
 * Note spike: a heavy round base with a steel spike and a stack of notes
 * speared on it, each turned a little. The pointer over the spike slides the
 * notes up the spike and fans them, staggered from the top. At rest the top
 * note is bright.
 */
const { Cam, circ, facing, fit, prism, proj, rings, unproj, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const N = 5, ANG = [8, -12, 20, -4, 14], NZ = 10, GAPZ = 2.4, RISE = [4, 8, 12, 16, 20];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let step = value;
  const C = Cam(45, 0.5, 3.75);
  fit(C, [[-22, -22, 0], [22, 22, 0], [0, 0, 62], [-22, -22, 40], [22, 22, 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const rot = (ring, deg) => { const a = deg * Math.PI / 180, c = Math.cos(a), s = Math.sin(a); return ring.map((p) => ({ u: p.u * c - p.v * s, v: p.u * s + p.v * c, nu: p.nu * c - p.nv * s, nv: p.nu * s + p.nv * c })); };
  { const base = circ(16, 28), inner = circ(14.6, 28); put(solid(g), prism(P, front, base, inner, 0, 7)); }
  const lowSpike = solid(g);
  const notes = Array.from({ length: N }, (_, k) => ({ el: solid(g), z: tween(0), a: tween(0), last: "" }));
  const tip = solid(g);
  const [nr, ni] = rings(-15, -15, 15, 15, 1.6, 1.2);
  { const r = circ(0.9, 12); put(lowSpike, prism(P, front, r, null, 7, NZ + N * GAPZ)); put(tip, prism(P, front, r, null, NZ + N * GAPZ, 62)); }
  function drawNote(n, k, dz, da) {
    const key = dz.toFixed(2) + "," + da.toFixed(2); if (key === n.last) return; n.last = key;
    const z = NZ + k * GAPZ + dz, a = ANG[k] + da;
    put(n.el, prism(P, front, rot(nr, a), rot(ni, a), z, z + 0.8));
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    notes.forEach((n, k) => { drawNote(n, k, tval(n.z, now), tval(n.a, now)); if (!tdone(n.z, now) || !tdone(n.a, now)) m = true; });
    return m;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, NZ + 10);
    return Math.hypot(x, y) < 26 ? 1 : 0;
  }
  let act = -1;
  function setActive(a) {
    if (a === act) return; act = a;
    const now = performance.now();
    notes.forEach((n, k) => { const d = (N - 1 - k) * step; tset(n.z, a ? RISE[k] : 0, now, d); tset(n.a, a ? (k % 2 ? -1 : 1) * 14 * (k + 1) / N : 0, now, d); });
    notes[N - 1].el.sil.classList.toggle("hi", !a);
    notes[0].el.sil.classList.toggle("hi", !!a);
    read.textContent = a ? "notes" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { step = v; }, destroy: bag.dispose };
}

hairline({
  name: "noteholder",
  means: "A note spike: the speared notes slide up the spike and fan out, one after another from the top.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[200, 173], [253, 173], [147, 173], null],
  mount,
});

guiro.code:
/**
 * Guiro: a ridged gourd balanced on a post above a tray, with a scraper
 * stick lying across its back. The pointer slides the scraper along the
 * ridges and the gourd tilts toward it like a seesaw. At rest the scraper
 * is bright near the left end. The slider is the tilt's reach.
 */
const { Cam, circ, clamp, fit, facing, hull, poly, open, prism, proj, rings, spring, stepS, unproj, disposer, mk, pointer, put, register, solid, rad } = HL;

const nrm = (a) => { const l = Math.hypot(a[0], a[1], a[2]); return [a[0] / l, a[1] / l, a[2] / l]; };
const crs = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const VW = [0.612, 0.612, 0.5];
function disk(c, n, r, m = 28) {
  n = nrm(n); const u = nrm(crs(n, Math.abs(n[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0])), v = crs(n, u), out = [];
  for (let i = 0; i < m; i++) {
    const a = (i / m) * 2 * Math.PI, w = [0, 1, 2].map((j) => Math.cos(a) * u[j] + Math.sin(a) * v[j]);
    out.push([c[0] + r * w[0], c[1] + r * w[1], c[2] + r * w[2], w[0] * VW[0] + w[1] * VW[1] + w[2] * VW[2]]);
  }
  return out;
}
function arc(pts) {
  const n = pts.length; let s = pts.findIndex((p, i) => p[3] <= 0 && pts[(i + 1) % n][3] > 0);
  if (s < 0) s = 0; const out = [];
  for (let k = 1; k <= n; k++) { const p = pts[(s + k) % n]; if (p[3] > 0) out.push(p); else break; }
  return out;
}

const L = 124, PZ = 34, prof = (t) => 4 + 12 * Math.pow(Math.sin(Math.PI * t), 0.6);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-66, -24, 0], [66, 24, 0], [-62, 0, PZ + 44], [62, 0, PZ + 44], [-62, 0, PZ - 28], [62, 0, PZ - 28]], 200, 160);
  const P = proj(C), fr = facing(C), g = mk("g", {}, svg);
  const S = (pts) => pts.map((p) => P(p[0], p[1], p[2]));
  const [r0, r1] = rings(-64, -22, 64, 22, 9, 2);
  put(solid(g), prism(P, fr, r0, r1, 0, 4));
  put(solid(g), prism(P, fr, circ(4, 24), circ(3, 24), 4, PZ - 14));
  const body = mk("path", { class: "sil" }, g), ridges = mk("path", { class: "nf lo" }, g);
  const stick = mk("path", { class: "sil" }, g), knob = mk("path", { class: "nf" }, g);
  const s = spring(0.3, { k: 90, c: 17 }), active = { on: false };
  let last = "";

  function draw() {
    const a = rad(-(s.x - 0.5) * 2 * amp), d = [Math.cos(a), 0, Math.sin(a)], up = [-Math.sin(a), 0, Math.cos(a)];
    const ax = (t) => [d[0] * (t - 0.5) * L, 0, PZ + d[2] * (t - 0.5) * L];
    const key = a.toFixed(4) + s.x.toFixed(4);
    if (key === last) return; last = key;
    let all = [];
    for (let i = 0; i <= 16; i++) all = all.concat(disk(ax(i / 16), d, prof(i / 16), 24));
    body.setAttribute("d", poly(hull(S(all))));
    let rd = "";
    for (let t = 0.2; t < 0.81; t += 0.04) rd += open(S(arc(disk(ax(t), d, prof(t) + 0.2, 36))));
    ridges.setAttribute("d", rd);
    const c = ax(s.x).map((v, j) => v + up[j] * (prof(s.x) + 2.6));
    const e0 = [c[0] - 5, c[1] - 30, c[2] + 6], e1 = [c[0] + 5, c[1] + 30, c[2] - 3], sd = [10, 60, -9];
    let sp = [];
    for (let i = 0; i <= 6; i++) sp = sp.concat(disk(e0.map((v, j) => v + (sd[j] * i) / 6), sd, 2.2, 14));
    stick.setAttribute("d", poly(hull(S(sp))));
    knob.setAttribute("d", poly(hull(S(disk(e1, sd, 4, 18).concat(disk(e1.map((v, j) => v + sd[j] * 0.06), sd, 4, 18))))));
    read.textContent = active.on ? Math.round(-a * 57.3) + "°" : "rest";
  }

  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(); return m; });
  bag.add(B.unregister);
  function setOn(on) { active.on = on; last = ""; body.classList.toggle("hi", on); stick.classList.toggle("hi", !on); }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const w = unproj(C, sx, sy, PZ + 12); s.t = clamp((w[0] + L / 2) / L, 0.14, 0.86); setOn(true); B.wake(); },
    leave: () => { s.t = 0.3; setOn(false); B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  return { set: (v) => { amp = v; last = ""; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "guiro",
  means: "A ridged guiro balanced on a post: the scraper slides along its ridges to the pointer and the gourd tilts toward it.",
  rules: [1, 3, 5, 8],
  range: [0, 16, 24],
  tour: [[150, 140], [269, 183], [220, 172], null],
  mount,
});

fluteholder.code:
/**
 * Flute stand: a round base with a peg, and a flute standing on it. The
 * pointer leans the flute toward itself, pivoting on the peg; tone holes
 * and the lip plate lean with it. At rest it leans back, bright. The
 * slider is the lean.
 */
const { Cam, clamp, fit, hull, poly, open, proj, spring, stepS, unproj, disposer, mk, pointer, register, rad } = HL;

const nrm = (a) => { const l = Math.hypot(a[0], a[1], a[2]); return [a[0] / l, a[1] / l, a[2] / l]; };
const crs = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const VW = [0.612, 0.612, 0.5];
function disk(c, n, r, m = 28) {
  n = nrm(n); const u = nrm(crs(n, Math.abs(n[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0])), v = crs(n, u), out = [];
  for (let i = 0; i < m; i++) {
    const a = (i / m) * 2 * Math.PI, w = [0, 1, 2].map((j) => Math.cos(a) * u[j] + Math.sin(a) * v[j]);
    out.push([c[0] + r * w[0], c[1] + r * w[1], c[2] + r * w[2], w[0] * VW[0] + w[1] * VW[1] + w[2] * VW[2]]);
  }
  return out;
}
function arc(pts) {
  const n = pts.length; let s = pts.findIndex((p, i) => p[3] <= 0 && pts[(i + 1) % n][3] > 0);
  if (s < 0) s = 0; const out = [];
  for (let k = 1; k <= n; k++) { const p = pts[(s + k) % n]; if (p[3] > 0) out.push(p); else break; }
  return out;
}
const PZ = 26, R = 50, FL = 132;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-30, -30, 0], [30, 30, 0], [-50, -50, FL], [50, 50, FL], [-50, 50, FL], [50, -50, FL]], 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const S = (pts) => pts.map((p) => P(p[0], p[1], p[2]));
  const tube = (a, b, r) => { const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]]; let all = []; for (let i = 0; i <= 4; i++) all = all.concat(disk(a.map((v, j) => v + (d[j] * i) / 4), d, r, 12)); return poly(hull(S(all))); };
  mk("path", { d: poly(hull(S(disk([0, 0, 0], [0, 0, 1], 26, 40).concat(disk([0, 0, 5], [0, 0, 1], 26, 40))))) }, g);
  mk("path", { d: tube([0, 0, 5], [0, 0, PZ], 3) }, g);
  const plate = mk("path", { class: "sil hi" }, g), groove = mk("path", { class: "nf lo" }, g), bell = mk("path", { class: "nf" }, g);
  const tx = spring(-16), ty = spring(14);
  let last = "", on = false;
  function draw() {
    const key = tx.x.toFixed(3) + ty.x.toFixed(3) + amp + on;
    if (key === last) return; last = key;
    const n = nrm([Math.sin(rad(tx.x)), Math.sin(rad(ty.x)), 1]), c = [0, 0, PZ], at = (h) => c.map((v, j) => v + n[j] * h);
    plate.setAttribute("d", tube(c, at(FL), 5.5));
