shoepolisher.code:
/**
 * Shoe buffer: a shoe on the bench and a buffing brush held over it, a
 * block with a band of bristles underneath. The brush slides along the shoe
 * to stand over the pointer and rocks as it goes. At rest it sits over the
 * toe, tilted, bright. The slider is how far it rocks.
 */
const { Cam, fit, proj, rrect, hull, poly, rad, clamp, fillet, unproj, spring, stepS, mk, register, pointer, disposer } = HL;

const OUT = fillet([[0, 10], [30, 4], [92, 2], [122, 14], [122, 32], [92, 44], [30, 42], [0, 36]], [8, 10, 12, 14, 14, 12, 10, 8], 3);
const REST = 84, BZ = 44;
const ring = (x0, y0, x1, y1, r) => rrect(x0, y0, x1, y1, r).map((q) => [q.u, q.v]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let rock = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, 0, 0], [122, 46, 0], [122, 0, 0], [0, 46, 0], [10, 23, BZ + 26], [118, 23, BZ + 26]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const id = (p) => p;
  const slab = (r, z0, z1, T) => { const pts = []; for (const [u, v] of r) pts.push(P(...T([u, v, z0])), P(...T([u, v, z1]))); return poly(hull(pts)); };
  // the shoe: sole, then the upper as one rounded body with its collar
  mk("path", { class: "sil", d: slab(OUT, 0, 5, id) }, g);
  const up = [];
  for (const [u, v] of OUT) up.push(P(u * 0.94 + 4, v * 0.9 + 2.3, 5));
  for (const [u, v] of ring(4, 8, 74, 38, 14)) up.push(P(u, v, 26));
  for (const [u, v] of ring(70, 10, 112, 36, 12)) up.push(P(u, v, 16));
  mk("path", { class: "sil", d: poly(hull(up)) }, g);
  mk("path", { class: "nf lo", d: poly(ring(8, 12, 44, 34, 11).map(([u, v]) => P(u, v, 26))) }, g);
  const bristle = mk("path", {}, g), body = mk("path", { class: "sil hi" }, g), cr = mk("path", { class: "nf lo" }, g);
  const bx = spring(REST), tl = spring(14);
  let lx = NaN, lt = NaN;
  function draw(x, t) {
    if (x === lx && t === lt) return;
    lx = x; lt = t;
    const c = Math.cos(rad(t)), s = Math.sin(rad(t));
    const T = ([u, v, z]) => [x + u * c + z * s, v, BZ - u * s + z * c];
    bristle.setAttribute("d", slab(ring(-22, -9, 22, 9, 4), -7, 0, (p) => { const q = T(p); q[1] += 23; return q; }));
    body.setAttribute("d", slab(ring(-26, -12, 26, 12, 7), 0, 14, (p) => { const q = T(p); q[1] += 23; return q; }));
    cr.setAttribute("d", poly(ring(-24, -10, 24, 10, 5.5).map(([u, v]) => { const q = T([u, v, 14]); return P(q[0], q[1] + 23, q[2]); })));
  }
  const B = register(stage, (dt) => { const a = stepS(bx, dt), b = stepS(tl, dt); draw(bx.x, tl.x); return a || b; });
  bag.add(B.unregister);
  function aim(x, label) { bx.t = x; tl.t = x === REST && label === "rest" ? 14 : clamp((x - 61) / 40, -1, 1) * rock; read.textContent = label; B.wake(); }
  aim(REST, "rest");
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x] = unproj(C, sx, sy, 0); const t = clamp(x, 24, 100); aim(t, "x " + Math.round(t)); },
    leave: () => aim(REST, "rest"),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { rock = v; }, destroy: bag.dispose };
}

hairline({
  name: "shoepolisher",
  means: "A shoe buffer: the bristled brush slides along the shoe to stand over the pointer and rocks as it buffs.",
  rules: [1, 3, 5, 8],
  range: [6, 18, 30],
  tour: [[156, 187], [286, 252], [114, 166], null],
  mount,
});

deskhutch.code:
/**
 * Desk hutch: a cabinet standing on a desk top, an open cubby on its right
 * and a door on its left. The pointer's x across the hutch swings the door
 * open on its hinge; at rest it stands ajar, bright. The slider is how far it opens.
 */
const {
  Cam, fit, proj, hull, poly, seg, clamp, lerp, rad, spring, stepS, disposer, mk, pointer, register, solid,
} = HL;

const V = (o, a, b, c) => {
  const r = [];
  for (const i of [0, 1]) for (const j of [0, 1]) for (const k of [0, 1]) r.push([0, 1, 2].map((q) => o[q] + i * a[q] + j * b[q] + k * c[q]));
  return r;
};
const AX = (x0, y0, z0, x1, y1, z1) => V([x0, y0, z0], [x1 - x0, 0, 0], [0, y1 - y0, 0], [0, 0, z1 - z0]);
// a box as a hull, with the three edges that meet at its nearest corner as creases
function box(P, s, cs) {
  const pts = cs.map((c) => P(...c));
  s.sil.setAttribute("d", poly(hull(pts)));
  let n = 0, bd = -Infinity;
  cs.forEach((c, i) => { const d = c[0] * 0.61 + c[1] * 0.61 + c[2] * 0.5; if (d > bd) { bd = d; n = i; } });
  s.cr.setAttribute("d", [4, 2, 1].map((b) => seg(pts[n], pts[n ^ b])).join(""));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.75);
  const FIT = [[-8,-8,0],[128,-8,0],[128,62,0],[-8,62,0],[0,0,62],[120,30,62],[4,90,60]];
  fit(C, FIT, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const REST = 24, LO = 30, W = 78;
  box(P, solid(g), AX(-8, -8, 0, 128, 62, 5));
  box(P, solid(g), AX(0, 0, 5, 120, 28, 62));
  const fr = (x0, x1, z0, z1) => poly([P(x0, 28, z0), P(x1, 28, z0), P(x1, 28, z1), P(x0, 28, z1)]);
  mk("path", { d: fr(2, 2 + W, 8, 59) + fr(82, 118, 8, 59) + fr(84, 116, 33, 35), class: "nf" }, g);
  const door = solid(g);
  door.sil.classList.add("hi");
  const knob = mk("path", { class: "nf" }, g);
  function draw(th) {
    const t = rad(th), a = [Math.cos(t) * W, Math.sin(t) * W, 0], c = [-Math.sin(t) * 2.5, Math.cos(t) * 2.5, 0];
    box(P, door, V([2, 28, 8], a, [0, 0, 51], c));
    const k = [2 + a[0] * 0.88 + c[0], 28 + a[1] * 0.88 + c[1]];
    knob.setAttribute("d", seg(P(k[0], k[1], 30), P(k[0], k[1], 40)));
  }
  const sp = spring(REST);
  // hit: the rest pose's screen box, fixed; the pointer's x across it sets the amount
  const sx = FIT.map((p) => P(...p)), x0 = Math.min(...sx.map((p) => p[0])), x1 = Math.max(...sx.map((p) => p[0]));
  const y0 = Math.min(...sx.map((p) => p[1])), y1 = Math.max(...sx.map((p) => p[1]));
  const hit = ([x, y]) => (x < x0 || x > x1 || y < y0 || y > y1 ? -1 : clamp((x - x0) / (x1 - x0) * 1.25, 0, 1));
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function setT(t) {
    const v = t < 0 ? REST : clamp(lerp(LO, max, t), Math.min(LO, max), Math.max(LO, max));
    if (v === sp.t) return;
    sp.t = v;
    read.textContent = t < 0 ? "rest" : Math.round(v) + '°';
    B.wake();
  }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => setT(hit(p)), leave: () => setT(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "deskhutch",
  means: "A hutch on a desk: the pointer swings its cabinet door open on the hinge, further the further right it goes.",
  rules: [1, 3, 4, 5, 6],
  range: [70,105,130],
  tour: [[180, 120], [230, 130], [258, 133], null],
  mount,
});

chairmat.code:
/**
 * Footrest: a tilting foot plate, ridged, rocking on two supports over a
 * low base. The pointer's x across it rocks the plate from heel to toe; at
 * rest it leans back, bright. The slider is the furthest tilt forward.
 */
const {
  Cam, fit, proj, hull, poly, seg, clamp, lerp, rad, spring, stepS, disposer, mk, pointer, register, solid,
} = HL;

const V = (o, a, b, c) => {
  const r = [];
  for (const i of [0, 1]) for (const j of [0, 1]) for (const k of [0, 1]) r.push([0, 1, 2].map((q) => o[q] + i * a[q] + j * b[q] + k * c[q]));
  return r;
};
const AX = (x0, y0, z0, x1, y1, z1) => V([x0, y0, z0], [x1 - x0, 0, 0], [0, y1 - y0, 0], [0, 0, z1 - z0]);
// a box as a hull, with the three edges that meet at its nearest corner as creases
function box(P, s, cs) {
  const pts = cs.map((c) => P(...c));
  s.sil.setAttribute("d", poly(hull(pts)));
  let n = 0, bd = -Infinity;
  cs.forEach((c, i) => { const d = c[0] * 0.61 + c[1] * 0.61 + c[2] * 0.5; if (d > bd) { bd = d; n = i; } });
  s.cr.setAttribute("d", [4, 2, 1].map((b) => seg(pts[n], pts[n ^ b])).join(""));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.85);
  const FIT = [[-8,-6,0],[108,-6,0],[108,66,0],[-8,66,0],[-6,-4,44],[106,64,44]];
  fit(C, FIT, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const REST = -9, LO = -18, PX = 50, PZ = 25, HL_ = 56, HW = 34;
  box(P, solid(g), AX(0, 0, 0, 100, 60, 4));
  box(P, solid(g), AX(40, 4, 4, 60, 9, PZ - 1));
  box(P, solid(g), AX(40, 51, 4, 60, 56, PZ - 1));
  const plate = solid(g), ridges = mk("path", { class: "nf" }, g);
  plate.sil.classList.add("hi");
  function draw(ps) {
    const t = rad(ps), u = [Math.cos(t), 0, -Math.sin(t)], n = [Math.sin(t), 0, Math.cos(t)];
    const o = [PX - u[0] * HL_, 30 - HW, PZ - u[2] * HL_];
    box(P, plate, V(o, u.map((q) => q * 2 * HL_), [0, 2 * HW, 0], n.map((q) => q * 3)));
    let d = "";
    for (let s = 16; s < 2 * HL_ - 8; s += 16) {
      const p = [o[0] + u[0] * s + n[0] * 3, o[2] + u[2] * s + n[2] * 3];
      d += seg(P(p[0], 30 - HW + 5, p[1]), P(p[0], 30 + HW - 5, p[1]));
    }
    ridges.setAttribute("d", d);
  }
  const sp = spring(REST);
  // hit: the rest pose's screen box, fixed; the pointer's x across it sets the amount
  const sx = FIT.map((p) => P(...p)), x0 = Math.min(...sx.map((p) => p[0])), x1 = Math.max(...sx.map((p) => p[0]));
  const y0 = Math.min(...sx.map((p) => p[1])), y1 = Math.max(...sx.map((p) => p[1]));
  const hit = ([x, y]) => (x < x0 || x > x1 || y < y0 || y > y1 ? -1 : clamp((x - x0) / (x1 - x0) * 1.25, 0, 1));
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function setT(t) {
    const v = t < 0 ? REST : clamp(lerp(LO, max, t), Math.min(LO, max), Math.max(LO, max));
    if (v === sp.t) return;
    sp.t = v;
    read.textContent = t < 0 ? "rest" : (v > 0 ? '+' : '') + Math.round(v) + '°';
    B.wake();
  }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => setT(hit(p)), leave: () => setT(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "chairmat",
  means: "An adjustable footrest: the pointer rocks its ridged foot plate on the pivot, from leaning back to tipped forward.",
  rules: [1, 3, 4, 5, 6],
  range: [8,16,20],
  tour: [[190, 150], [230, 170], [259, 183], null],
  mount,
});

glockenspiel.code:
/**
 * Glockenspiel: eleven metal bars, long to short, resting on two felt rails
 * in a low case. The pointer strikes: the bars near it dip and slide toward the reader,
 * each on its own spring, the one under it deepest and bright. At rest one
 * bar rings, bright and tipped. The slider is the reach, in bars.
 *
 * The pattern: a continuous field along one row; the hit is on the plane of
 * the bars' resting tops, which never moves.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 11, BW = 8, GAP = 2.2, BH = 3, TOP = 8, FAV = 4, DMAX = 7;
const LEN = Array.from({ length: N }, (_, k) => 64 - k * 3.4);
const X1 = N * (BW + GAP), MID = 34;
const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.62 : u <= 1 ? 0.38 - ((u - 0.45) / 0.55) * 0.38 : 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let RAD = value * (BW + GAP), over = null;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-6, 0, -4], [X1 + 6, 68, -4], [X1 + 6, 0, -4], [-6, 72, -4], [X1 + 6, 72, -4], [-6, 0, TOP + BH + 2], [X1 + 6, 0, TOP + BH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the case floor and the far felt rail, which runs on the long bars' ends to the short ones'
  block(-6, 0, X1 + 6, 68, 3, 1.2, -4, 0);
  const railY = (k, s) => MID + s * (LEN[k] / 2 - 5);
  block(-3, railY(0, -1) - 2, X1 + 3, railY(0, -1) + 2, 1.5, 0.6, 0, TOP);
  const bars = LEN.map((len, k) => {
    const x0 = k * (BW + GAP) + GAP / 2;
    const rest = k === FAV ? DMAX * 0.6 : k === FAV - 1 || k === FAV + 1 ? DMAX * 0.2 : 0;
    return { k, x0, len, cx: x0 + BW / 2, el: solid(g), rest, sp: spring(rest, { eps: 0.02 }), drawn: NaN };
  });
  // the near rail goes in front of the bars
  block(-3, railY(0, 1) - 2, X1 + 3, railY(0, 1) + 2, 1.5, 0.6, 0, TOP - DMAX - 0.5);

  function draw(b) {
    const d = clamp(b.sp.x, 0, DMAX);
    if (d === b.drawn) return;
    b.drawn = d;
    const sy = d * 1.3, [ring, inner] = rings(b.x0, MID - b.len / 2 + sy, b.x0 + BW, MID + b.len / 2 + sy, 1.6, 0.8);
    put(b.el, prism(P, front, ring, inner, TOP - d, TOP + BH - d));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bars) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function retarget() {
    const hit = over ? bars[clamp(Math.floor(over[0] / (BW + GAP)), 0, N - 1)] : null;
    for (const b of bars) {
      b.sp.t = !over ? b.rest : b === hit ? DMAX : DMAX * 0.9 * falloff(Math.abs(b.cx - over[0]) / RAD);
      b.el.sil.classList.toggle("hi", over ? b === hit : b.k === FAV);
    }
    read.textContent = hit ? "bar " + String(hit.k + 1).padStart(2, "0") : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TOP + BH);
      over = x > -3 && x < X1 + 3 && y > 0 && y < 68 ? [clamp(x, 0, X1 - 0.01), y] : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { RAD = v * (BW + GAP); if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "glockenspiel",
  means: "Eleven glockenspiel bars on felt rails: the bars near the pointer dip and slide as struck, the one under it deepest.",
  rules: [1, 3, 5, 9],
  range: [2, 4, 6],
  tour: [[231, 167], [165, 138], [268, 186], null],
  mount,
});

rackunit.code:
/**
 * Effects rack: six units of different heights stacked between two rack
 * rails, each with a pair of knob dots and a handle on its face. The pointer
 * picks a unit by its height on screen: it slides out toward the reader like
 * a drawer, and the units beside it ease out a little, staggered from it. At
 * rest one unit is half out, bright. The slider is the stagger.
 *
 * The pattern: one of many in a single stack; the pick is the unit whose
 * resting face is nearest the pointer's y on screen.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const UH = [10, 14, 8, 12, 10, 14], W = 70, D = 40, OUT = 24, FAV = 3, GAP = 1;
const zs = []; { let z = 4; for (const h of UH) { zs.push(z); z += h + GAP; } }
const ZT = zs[zs.length - 1] + UH[UH.length - 1] + 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-6, 0, 0], [W + 6, D + OUT, 0], [W + 6, 0, 0], [-6, D + OUT, 0], [-6, 0, ZT], [W + 6, 0, ZT]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (x0, y0, x1, y1, r, b, z0, z1, el = solid(g)) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(el, prism(P, front, o, i, z0, z1)); return el; };

  // the foot, the back panel and the far rail
  block(-6, -2, W + 6, D + 2, 2, 1, 0, 4);
  block(-6, -2, W + 6, 1, 1.2, 0.5, 4, ZT);
  block(-6, 1, -1, D + 2, 1.2, 0.5, 4, ZT);
  const units = UH.map((h, k) => {
    const el = solid(g), marks = mk("path", { class: "nf lo" }, el.g);
    const dots = [mk("circle", { class: "dot off", r: 1.6 }, el.g), mk("circle", { class: "dot off", r: 1.6 }, el.g)];
    return { k, h, z0: zs[k], el, marks, dots, y: tween(k === FAV ? 12 : 0), last: "" };
  });
  const rail = block(W + 1, 1, W + 6, D + 2, 1.2, 0.5, 4, ZT);

  function draw(u, y) {
    const key = y.toFixed(2);
    if (key === u.last) return;
    u.last = key;
    const [r, i] = rings(1, y, W - 1, y + D, 1.4, 0.8);
    put(u.el, prism(P, front, r, i, u.z0, u.z0 + u.h));
    const zm = u.z0 + u.h / 2, f = y + D;
    u.marks.setAttribute("d", seg(P(W * 0.55, f, zm), P(W * 0.85, f, zm)) + seg(P(W * 0.55, f, zm - 2), P(W * 0.55, f, zm + 2)) + seg(P(W * 0.85, f, zm - 2), P(W * 0.85, f, zm + 2)));
    u.dots.forEach((d, j) => { const [sx, sy] = P(8 + j * 9, f, zm); d.setAttribute("cx", sx); d.setAttribute("cy", sy); });
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const u of units) { draw(u, tval(u.y, now)); if (!tdone(u.y, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  /** The unit whose resting face middle is nearest the pointer's y on screen; -1 off the rack. */
  const mids = units.map((u) => P(W / 2, D, u.z0 + u.h / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 16 && Math.abs(mids[best][0] - sx) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    units.forEach((u, k) => {
      const d = Math.abs(k - a);
      const y = a < 0 ? (k === FAV ? 12 : 0) : d === 0 ? OUT : d === 1 ? 7 : d === 2 ? 2 : 0;
      tset(u.y, y, now, from < 0 ? 0 : Math.abs(k - from) * stag);
      const on = k === (a < 0 ? FAV : a);
      u.el.sil.classList.toggle("hi", on);
      u.dots.forEach((d) => d.setAttribute("class", on ? "dot" : "dot off"));
    });
    read.textContent = a < 0 ? "rest" : "unit " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "rackunit",
  means: "Six effects units in a rack: the one under the pointer slides out like a drawer, its neighbours easing out in turn.",
  rules: [1, 2, 5, 8],
  range: [0, 40, 80],
  tour: [[189, 171], [189, 210], [189, 125], null],
  mount,
});

kidscar.code:
/**
 * Ride on toy: a little push car on a play mat, a chunky body, a seat at the
 * back, four fat wheels and a tall push handle. The pointer is where the car
 * is pushed to: it rolls along the mat on a spring to stand under it. At rest
 * it waits a third of the way along, its handle bright. The slider is how
 * quickly it rolls.
 *
 * The pattern: a continuous aim on the ground plane, which never moves.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 26, X1 = 104, REST = 46, W = 24;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-8, -12, 0], [134, W + 12, 0], [134, -12, 0], [-8, W + 12, 0], [X0 - 24, W / 2, 52], [X1 + 24, W / 2, 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-8, -12, 134, W + 12, 6, 2);
  put(solid(g), prism(P, front, mr, mi, 0, 2));
  const car = mk("g", {}, g);
  const wheel = (x, y) => {
    const a = [], b = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; a.push(P(x + 7 * Math.cos(t), y, 9 + 7 * Math.sin(t))); b.push(P(x + 7 * Math.cos(t), y + 4, 9 + 7 * Math.sin(t))); }
    return [poly(hull(a.concat(b))), poly(y < W / 2 ? b : a)];
  };
  const wf = [mk("path", { class: "sil" }, car), mk("path", { class: "sil" }, car)];
  const hub = [mk("path", { class: "nf lo" }, car), mk("path", { class: "nf lo" }, car)];
  const handle = mk("path", { class: "nf sil" }, car);
  const body = solid(car), seat = solid(car);
  const wn = [mk("path", { class: "sil" }, car), mk("path", { class: "sil" }, car)];
  const hn = [mk("path", { class: "nf lo" }, car), mk("path", { class: "nf lo" }, car)];
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;
  function draw(x) {
    if (Math.abs(x - last) < 1e-3) return;
    last = x;
    [[x - 14, -2, wf, hub, 0], [x + 14, -2, wf, hub, 1], [x - 14, W - 2, wn, hn, 0], [x + 14, W - 2, wn, hn, 1]].forEach(([wx, wy, s, h, i]) => {
      const [d, c] = wheel(wx, wy); s[i].setAttribute("d", d); h[i].setAttribute("d", c);
    });
    const hd = [P(x - 20, 3, 20), P(x - 26, 3, 50), P(x - 26, W - 3, 50), P(x - 20, W - 3, 20)];
    handle.setAttribute("d", "M" + hd.map((p) => p.join(",")).join("L"));
    const [br, bi] = rings(x - 24, 0, x + 24, W, 9, 2);
    put(body, prism(P, front, br, bi, 8, 22));
    const [sr, si] = rings(x - 20, 3, x - 2, W - 3, 5, 1.6);
    put(seat, prism(P, front, sr, si, 22, 28));
  }
  draw(REST);
  handle.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function aim(x) {
    sp.t = x == null ? REST : Math.max(X0, Math.min(X1, x));
    read.textContent = x == null ? "rest" : "push " + Math.round(((sp.t - X0) / (X1 - X0)) * 9);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); aim(x > -30 && x < 160 && y > -40 && y < W + 40 ? x : null); },
    leave: () => aim(null),
  }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "kidscar",
  means: "A push car on a play mat: it rolls along the mat to stand under the pointer, its push handle bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[134, 136], [200, 190], [258, 232], null],
  mount,
});

babymonitor.code:
/**
 * Baby monitor: a nursery camera on a round foot, a neck, a boxy head with a
 * round lens on its face and a short antenna on top. The pointer is the baby
 * it watches: the head pans on its spring to face it. At rest it looks a
 * little off to one side, its lens bright. The slider is how quickly it pans.
 *
 * The pattern: a continuous aim (officechairs' swivel, on one head); the hit
 * is on the floor's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = (45 + 30) * (Math.PI / 180), LIM = 70 * (Math.PI / 180), MID = 45 * (Math.PI / 180);
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 4.0);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([22 * Math.cos(a), 22 * Math.sin(a), 0], [16 * Math.cos(a), 16 * Math.sin(a), 56]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(18, 48), circ(16.4, 48), 0, 3));
  put(solid(g), prism(P, front, circ(3.2, 24), null, 3, 15));
  const head = solid(g), ant = solid(g), knob = solid(g);
  const lens = mk("path", { class: "nf" }, g), eye = mk("path", { class: "nf lo" }, g);
  const HR = rings(-10, -12, 10, 12, 4, 1.4), AR = circ(1.4, 16), KR = circ(2.6, 16);
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 1e-4) return;
    last = a;
    const T = (r) => turn(r, a);
    put(head, prism(P, front, T(HR[0]), T(HR[1]), 14, 34));
    const ax = -5 * Math.cos(a) - 8 * Math.sin(a), ay = -5 * Math.sin(a) + 8 * Math.cos(a);
    const at = (r) => r.map((q) => ({ ...q, u: q.u + ax, v: q.v + ay }));
    put(ant, prism(P, front, at(AR), null, 34, 52));
    put(knob, prism(P, front, at(KR), null, 51, 55));
    const c = Math.cos(a), s = Math.sin(a), ring = (R) => {
      const pts = [];
      for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2, v = R * Math.cos(t), z = 24 + R * Math.sin(t); pts.push(P(10.4 * c - v * s, 10.4 * s + v * c, z)); }
      return poly(pts);
    };
    const vis = c + s > 0.1;
    lens.setAttribute("d", vis ? ring(6.5) : "");
    eye.setAttribute("d", vis ? ring(3) : "");
  }
  draw(REST);
  lens.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function aim(p) {
    let t = REST;
    if (p) t = MID + Math.max(-LIM, Math.min(LIM, wrap(Math.atan2(p[1], p[0]) - MID)));
    sp.t = t;
    read.textContent = p ? "pan " + Math.round(((t - MID) * 180) / Math.PI) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (q) => { const [x, y] = unproj(C, q[0], q[1], 0), r = Math.hypot(x, y); aim(r > 6 && r < 90 ? [x, y] : null); },
    leave: () => aim(null),
  }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "babymonitor",
  means: "A nursery camera on a round foot: its head pans to face the pointer, lens bright, antenna turning with it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[200, 217], [100, 300], [300, 300], null],
  mount,
});

boulecase.code:
/**
 * Marble tray: a round solitaire board with thirty-two marbles in a cross of
 * holes, the centre hole empty. The board tilts down toward the pointer and
 * the marbles slide a little in their holes; the marble nearest the pointer
 * goes bright. At rest the marble that would jump first is bright.
 */
const { Cam, fit, proj, unproj, hull, poly, clamp, rad, spring, stepS, disposer, mk, pointer, register } = HL;
const R = 64, T = 7, G = 14, MR = 5.4, S = 2.05;
const holes = [];
for (let i = -3; i <= 3; i++) for (let j = -3; j <= 3; j++) if (Math.abs(i) <= 1 || Math.abs(j) <= 1) holes.push([i, j]);
holes.sort((a, b) => a[0] + a[1] - b[0] - b[1]);
const ring = (cx, cy, r, z, n = 40) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([cx + r * Math.cos(t), cy + r * Math.sin(t), z]); } return o; };
const FAV = holes.findIndex((h) => h[0] === 2 && h[1] === 0);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = rad(value);
  const C = Cam(45, 0.5, S);
  fit(C, [[-R, -R, -12], [R, R, -12], [R, -R, 22], [-R, R, 22], [0, 0, 26]], 200, 160);
  const P = proj(C);
  const ax = spring(0), ay = spring(0);
  const tf = ([x, y, z]) => { z -= T; let c = Math.cos(ax.x), s = Math.sin(ax.x); [y, z] = [y * c - z * s, y * s + z * c]; c = Math.cos(ay.x); s = Math.sin(ay.x); [x, z] = [x * c + z * s, -x * s + z * c]; return P(x, y, z + T); };
  const g = mk("g", {}, svg);
  const base = mk("path", { class: "sil" }, g), top = mk("path", { class: "nf lo" }, g);
  const hs = holes.map(() => mk("path", { class: "nf lo" }, g));
  const ms = holes.map(([i, j]) => (i === 0 && j === 0 ? null : mk("ellipse", { rx: MR * S, ry: MR * S }, g)));
  function draw() {
    base.setAttribute("d", poly(hull(ring(0, 0, R, 0).concat(ring(0, 0, R, T)).map(tf))));
    top.setAttribute("d", poly(ring(0, 0, R - 4, T).map(tf)));
    const dx = clamp(ay.x / 0.25, -1, 1) * 1.6, dy = clamp(-ax.x / 0.25, -1, 1) * 1.6;
    holes.forEach(([i, j], k) => {
      hs[k].setAttribute("d", poly(ring(i * G, j * G, 3.6, T, 16).map(tf)));
      if (!ms[k]) return;
      const [sx, sy] = tf([i * G + dx, j * G + dy, T + MR * 0.55]);
      ms[k].setAttribute("cx", sx.toFixed(2)); ms[k].setAttribute("cy", sy.toFixed(2));
    });
  }
  const B = register(stage, (dt) => { const a = stepS(ax, dt), b = stepS(ay, dt); draw(); return a || b; });
  bag.add(B.unregister);
  let act = -2;
  function aim(px, py, k) {
    const d = Math.hypot(px, py) || 1, f = clamp(d / R, 0, 1);
    ax.t = (-py / d) * max * f; ay.t = (px / d) * max * f;
    if (k !== act) {
      act = k;
      ms.forEach((m, q) => m && m.classList.toggle("hi", q === (k < 0 ? FAV : k)));
      const h = holes[k < 0 ? FAV : k];
      read.textContent = k < 0 ? "rest" : "abcdefg"[h[0] + 3] + (h[1] + 4);
    }
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, T);
    if (Math.hypot(x, y) > R + 8) return aim(2 * G, 0, -1);
    let best = -1, bd = Infinity;
    holes.forEach(([i, j], k) => { if (!ms[k]) return; const dd = Math.hypot(i * G - x, j * G - y); if (dd < bd) { bd = dd; best = k; } });
    aim(x, y, best);
  }
  aim(2 * G * 0.5, 0, -1);
  bag.add(pointer(stage, { move, leave: () => aim(2 * G * 0.5, 0, -1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = rad(v); }, destroy: bag.dispose };
}

hairline({
  name: "boulecase",
  means: "A round marble solitaire board: it tilts down toward the pointer and the nearest marble goes bright.",
  rules: [1, 3, 4, 5],
  range: [4, 10, 16],
  tour: [[150, 120], [250, 200], [200, 150], null],
  mount,
});

pinwheel.code:
/**
 * Pinwheel: four folded vanes on a hub at the top of a stick standing in a
 * small block. The pointer's x turns the wheel; the vane whose tip ends up
 * nearest the pointer goes bright. At rest one vane is bright.
 */
const { Cam, fit, proj, hull, poly, open, clamp, spring, stepS, disposer, mk, pointer, register } = HL;
const H = 100, R = 62, S = 1.55, N = [0.94, 0.34, 0], E1 = [-0.34, 0.94, 0];
const ring = (r, z, n = 24) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([r * Math.cos(t), r * Math.sin(t), z]); } return o; };
const at = (r, t, f = 0) => [r * Math.cos(t) * E1[0] + f * N[0], r * Math.cos(t) * E1[1] + f * N[1], H + r * Math.sin(t)];
const dep = (p) => (p[0] + p[1]) * 0.61 + p[2] * 0.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, S);
  fit(C, [at(R, 0), at(R, Math.PI), at(R, Math.PI / 2), [0, 0, 0], [16, 16, 0], [-16, -16, 0]], 200, 160);
  const P = proj(C), pp = (p) => P(p[0], p[1], p[2]);
  const g = mk("g", {}, svg);
  mk("path", { class: "sil", d: poly(hull(ring(16, 0).concat(ring(16, 8)).map(pp))) }, g);
  mk("path", { class: "nf lo", d: poly(ring(13, 8).map(pp)) }, g);
  mk("path", { class: "sil", d: poly(hull(ring(2.2, 8, 12).concat(ring(2.2, H - 2, 12)).map(pp))) }, g);
  const vanes = [0, 1, 2, 3].map(() => { const v = mk("g", {}, g); return { g: v, plate: mk("path", { class: "sil" }, v), fold: mk("path", { class: "nf lo" }, v) }; });
  const pin = mk("ellipse", { rx: 3.2 * S, ry: 3.2 * S, class: "sil" }, g);
  const hp = pp(at(0, 0, 6)); pin.setAttribute("cx", hp[0]); pin.setAttribute("cy", hp[1]);
  const phi = spring(0.35, { k: 60, c: 14 });
  let last = NaN, act = -2;
  function draw() {
    if (phi.x === last) return; last = phi.x;
    const order = vanes.map((v, k) => {
      const t = phi.x + (k * Math.PI) / 2, hub = at(0, 0), a = at(R * 0.5, t - 0.7), tip = at(R, t), fold = at(R * 0.55, t + 0.75, 16);
      v.plate.setAttribute("d", poly([hub, a, tip, fold].map(pp)));
      v.fold.setAttribute("d", open([tip, at(5, t + 0.3, 3)].map(pp)));
      return [dep(tip) + dep(fold), v];
    }).sort((x, y) => x[0] - y[0]);
    order.forEach(([, v]) => g.insertBefore(v.g, pin));
  }
  const B = register(stage, (dt) => { const m = stepS(phi, dt); draw(); return m; });
  bag.add(B.unregister);
  function choose(k) {
    if (k === act) return; act = k;
    vanes.forEach((v, q) => v.plate.classList.toggle("hi", q === (k < 0 ? 0 : k)));
  }
  function move([sx, sy]) {
    phi.t = 0.35 + ((sx - 200) / 200) * gain * Math.PI;
    let best = 0, bd = Infinity;
    vanes.forEach((_, k) => { const s = pp(at(R, phi.t + (k * Math.PI) / 2)); const d = Math.hypot(s[0] - sx, s[1] - sy); if (d < bd) { bd = d; best = k; } });
    choose(best);
    read.textContent = Math.round((((phi.t - 0.35) * 180) / Math.PI)) + "°";
    B.wake();
  }
  choose(-1); read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { phi.t = 0.35; choose(-1); read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = clamp(v, 0.25, 1.5); }, destroy: bag.dispose };
}

hairline({
  name: "pinwheel",
  means: "A toy pinwheel on a stick: the pointer's x turns the four vanes and the vane nearest the pointer goes bright.",
  rules: [1, 3, 4, 8],
  range: [0.25, 0.75, 1.5],
  tour: [[118, 145], [310, 110], [282, 107], null],
  mount,
});

tiddlybox.code:
/**
 * Game timer: a sand glass between two square plates on four posts. The
 * pointer's x turns the whole timer over, and the sand runs to whichever
 * bulb is down. The sand is the bright mark.
 */
const { Cam, fit, proj, hull, poly, rrect, clamp, rad, spring, stepS, disposer, mk, pointer, register } = HL;
const ZC = 42, S = 2.3, K = [Math.SQRT1_2, Math.SQRT1_2, 0];
const ring = (r, z, n = 28) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([r * Math.cos(t), r * Math.sin(t), z]); } return o; };
const sq = (z) => rrect(-22, -22, 22, 22, 5, 4).map((q) => [q.u, q.v, z]);
const dep = (p) => (p[0] + p[1]) * 0.61 + p[2] * 0.5;
const POSTS = [[-17, -17], [17, -17], [-17, 17], [17, 17]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let span = rad(value);
  const C = Cam(45, 0.5, S);
  fit(C, [[-36, -36, ZC - 52], [36, 36, ZC + 52], [36, -36, ZC], [-36, 36, ZC]], 200, 160);
  const P = proj(C), REST = 0.3;
  const th = spring(REST, { k: 60, c: 14 });
  const rot = (p, a) => {
    const [x, y, z] = [p[0], p[1], p[2] - ZC], c = Math.cos(a), s = Math.sin(a), d = K[0] * x + K[1] * y;
    const cx = [K[1] * z, -K[0] * z, K[0] * y - K[1] * x];
    return [x * c + cx[0] * s + K[0] * d * (1 - c), y * c + cx[1] * s + K[1] * d * (1 - c), z * c + cx[2] * s + ZC];
  };
  const g = mk("g", {}, svg);
  const parts = [];
  const add = (cls, fn) => { const el = mk("path", { class: cls }, g); parts.push({ el, fn }); return el; };
  add("sil", () => sq(0).concat(sq(5)));
  add("sil", () => sq(79).concat(sq(84)));
  POSTS.forEach(([x, y]) => add("sil", () => ring(2, 5, 10).concat(ring(2, 79, 10)).map((p) => [p[0] + x, p[1] + y, p[2]])));
  add("nf", () => ring(15, 5).concat(ring(2.5, ZC)));
  add("nf", () => ring(2.5, ZC).concat(ring(15, 79)));
  const sA = add("sil hi", () => null), sB = add("sil hi", () => null);
  let last = NaN;
  function draw() {
    const a = th.x; if (a === last) return; last = a;
    const f = (1 + Math.cos(a)) / 2, hA = 20 * f, hB = 20 * (1 - f);
    const L = [];
    for (const p of parts) {
      let pts = p.fn();
      if (p.el === sA) pts = hA > 0.6 ? ring(14, 5.5).concat(ring(14 - hA * 0.33, 5.5 + hA)) : null;
      if (p.el === sB) pts = hB > 0.6 ? ring(14, 78.5).concat(ring(14 - hB * 0.33, 78.5 - hB)) : null;
      if (!pts) { p.el.setAttribute("d", ""); L.push([-1e9, p.el]); continue; }
      const w = pts.map((q) => rot(q, a));
      p.el.setAttribute("d", poly(hull(w.map((q) => P(q[0], q[1], q[2])))));
      L.push([w.reduce((s, q) => s + dep(q), 0) / w.length + (p.el === sA || p.el === sB ? -2 : 0), p.el]);
    }
    L.sort((x, y) => x[0] - y[0]).forEach(([, el]) => g.appendChild(el));
    read.textContent = th.t === REST ? "rest" : Math.round(100 * (1 - f)) + "%";
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  const go = (t) => { th.t = t; B.wake(); };
  go(REST);
  bag.add(pointer(stage, { move: ([sx]) => go(REST + clamp((sx - 80) / 240, 0, 1) * span), leave: () => go(REST) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { span = rad(v); }, destroy: bag.dispose };
}

hairline({
  name: "tiddlybox",
  means: "A sand game timer in a frame: the pointer's x turns it over and the sand runs into the lower bulb.",
  rules: [3, 4, 5, 8],
  range: [90, 160, 180],
  tour: [[120, 160], [300, 160], [220, 160], null],
  mount,
});

corner.code:
/**
 * Corner flag: a flag pole on a sprung base at the corner of a pitch, the
 * quarter arc and touchlines dashed on the grass. The pointer pushes the
 * pole: it swings away from the pointer about its spring, the flag riding on
 * top, and springs back to a slight lean when the pointer leaves. At rest the
 * flag is bright. The slider is how far the spring gives.
 */
const { Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rrect, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const H = 92, REST = [0.1, -0.06];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let give = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-10, -10, 0], [70, 0, 0], [0, 70, 0], [0, 0, H + 6], [30, 30, H - 10], [-30, -30, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  mk("path", { class: "dash", d: open([P(0, 72, 0), P(0, 0, 0), P(72, 0, 0)]) }, g);
  const arc = [];
  for (let i = 0; i <= 20; i++) { const t = (i / 20) * Math.PI / 2; arc.push(P(30 * Math.cos(t), 30 * Math.sin(t), 0)); }
  mk("path", { class: "dash", d: open(arc) }, g);
  put(solid(g), prism(P, front, circ(7, 32), circ(5.5, 32), 0, 3));
  const coil = solid(g), pole = solid(g), flag = solid(g);
  const ax = spring(REST[0]), ay = spring(REST[1]);
  const R3 = (p, a, b) => {
    let [x, y, z] = p;
    [y, z] = [y * Math.cos(a) - z * Math.sin(a), y * Math.sin(a) + z * Math.cos(a)];
    [x, z] = [x * Math.cos(b) + z * Math.sin(b), -x * Math.sin(b) + z * Math.cos(b)];
    return [x, y, z + 3];
  };
  const slab = (s, ring, inner, a, b, m) => {
    const pr = (q, t) => P(...m(q.u, q.v, t));
    s.sil.setAttribute("d", poly(hull(ring.map((q) => pr(q, a)).concat(ring.map((q) => pr(q, b))))));
    s.cr.setAttribute("d", poly(inner.map((q) => pr(q, b))));
  };
  let last = "";
  function draw() {
    const key = ax.x.toFixed(3) + ay.x.toFixed(3);
    if (key === last) return;
    last = key;
    const a = ax.x, b = ay.x;
    slab(coil, circ(3.2, 20), circ(2.2, 20), 0, 12, (u, v, t) => R3([u, v, t], a * 0.3, b * 0.3));
    slab(pole, circ(1.6, 16), circ(0.8, 16), 12, H, (u, v, t) => R3([u, v, t], a, b));
    slab(flag, rrect(0, H - 26, 26, H - 2, 1.5, 4), rrect(1, H - 25, 25, H - 3, 1, 4), -0.4, 0.4,
      (u, w, t) => R3([u * 0.7 + 1, -u * 0.7 + t, w + Math.sin(u / 8) * 2], a, b));
  }
  const B = register(stage, (dt) => { const m = stepS(ax, dt) | stepS(ay, dt); draw(); return !!m; });
  bag.add(B.unregister);
  function aim(p) {
    let on = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x, y);
      if (d < 110) {
        on = true;
        const k = clamp(1 - d / 110, 0.25, 1) * 0.55 * give;
        ax.t = clamp((-y / (d || 1)) * -k, -0.6, 0.6); ay.t = clamp((-x / (d || 1)) * k, -0.6, 0.6);
        read.textContent = Math.round(Math.hypot(ax.t, ay.t) * 57) + "°";
      }
    }
    if (!on) { ax.t = REST[0]; ay.t = REST[1]; read.textContent = "rest"; }
    flag.sil.classList.toggle("hi", !on);
    pole.sil.classList.toggle("hi", on);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { give = v; }, destroy: bag.dispose };
}

