jumprope.code:
/**
 * Jump rope: two handles held up at either end, a long rope hanging between
 * them in a deep loop. The pointer over the figure turns the rope: it swings
 * up and over the handles' line, as in a skip, and the handle nearer the
 * pointer is the one turning it, bright. At rest the rope hangs, the left
 * handle bright. The slider is how far over the rope swings.
 */
const { Cam, circ, fit, hull, open, poly, proj, rad, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const L = 110, HZ = 46, R = 40, HL0 = 30, REST = -110;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, -R, HZ - R], [L, R, HZ - R], [L / 2, 0, HZ + R], [0, 0, HZ + HL0 + 4], [L, 0, HZ + HL0 + 4]], 200, 166);
  const P = proj(C), g = mk("g", {}, svg);
  const rope = mk("path", { class: "nf sil" }, g);
  const hands = [0, L].map((x) => {
    const cyl = (r, z0, z1) => hull(circ(r, 20).map((q) => P(x + q.u, q.v, z0)).concat(circ(r, 20).map((q) => P(x + q.u, q.v, z1))));
    const grp = mk("g", {}, g);
    const sil = mk("path", { class: "sil", d: poly(cyl(4.2, HZ + 4, HZ + HL0)) }, grp);
    mk("path", { class: "nf lo", d: poly(circ(3, 20).map((q) => P(x + q.u, q.v, HZ + HL0))) }, grp);
    mk("path", { class: "sil", d: poly(cyl(2.4, HZ, HZ + 5)) }, grp);
    return { x, sil };
  });
  const a = tween(REST);
  let last = NaN;
  function draw(ang) {
    if (ang === last) return;
    last = ang;
    const pts = [], c = Math.cos(rad(ang)), s = Math.sin(rad(ang));
    for (let i = 0; i <= 40; i++) { const t = i / 40, r = R * Math.sin(Math.PI * t); pts.push(P(t * L, r * c, HZ + r * s)); }
    rope.setAttribute("d", open(pts));
  }
  const B = register(stage, (_dt, now) => { draw(tval(a, now)); return !tdone(a, now); });
  bag.add(B.unregister);
  const ends = hands.map((h) => P(h.x, 0, HZ + 10)), mid = P(L / 2, 0, HZ);
  function hit([sx, sy]) {
    if (Math.hypot(sx - mid[0], sy - mid[1]) > 150) return -1;
    return Math.abs(sx - ends[0][0]) + Math.abs(sy - ends[0][1]) < Math.abs(sx - ends[1][0]) + Math.abs(sy - ends[1][1]) ? 0 : 1;
  }
  let act = -2;
  function setActive(k) {
    if (k === act) return;
    act = k;
    tset(a, k < 0 ? REST : REST + 190 * reach, performance.now(), 0);
    hands.forEach((h, i) => h.sil.classList.toggle("hi", i === (k < 0 ? 0 : k)));
    read.textContent = k < 0 ? "rest" : k === 0 ? "left" : "right";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; const k = act; act = -2; setActive(k); }, destroy: bag.dispose };
}

hairline({
  name: "jumprope",
  means: "A jump rope held up by its two handles: the pointer turns the rope up and over, from the handle nearer it.",
  rules: [1, 3, 4, 5],
  range: [0.5, 1, 1],
  tour: [[138, 81], [250, 185], [200, 160], null],
  mount,
});

glovedispenser.code:
/**
 * Glove dispenser: a wall holder with three glove boxes side by side, a tuft
 * of glove poking from each top slot. The pointer picks a box by where it
 * stands: it slides out of the holder, and the boxes beside it slide a little,
 * staggered from it. At rest the middle box is half out, bright.
 */
const { Cam, circ, fit, hull, poly, proj, rings, tset, tval, tdone, tween, disposer, mk, pointer, register, solid } = HL;

const N = 3, STEP = 42, OUT = 26, REST = [0.15, 0.55, 0.05], FAV = 1, AMT = [1, 0.45, 0.2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -8, 0], [128, -8, 40], [128, 40 + OUT, 0], [-4, 40 + OUT, 0], [128, 40 + OUT, 34]], 200, 166);
  const P = proj(C), g = mk("g", {}, svg);
  const W = (dy, ring, z) => ring.map((q) => P(q.u, q.v + dy, z));
  const body = (s, [o, i], z0, z1, dy = 0) => {
    s.sil.setAttribute("d", poly(hull(W(dy, o, z0).concat(W(dy, o, z1)))));
    s.cr.setAttribute("d", poly(W(dy, i, z1)));
  };
  body(solid(g), rings(-4, -8, 128, -3, 2, 1), 0, 40);
  body(solid(g), rings(-4, -3, 128, 40, 3, 1.5), 0, 3);

  const items = [];
  for (let k = 0; k < N; k++) {
    const x0 = k * STEP, x1 = x0 + 38, grp = mk("g", {}, g);
    const s = solid(grp), slot = mk("path", { class: "nf lo" }, grp), tuft = mk("path", { class: "nf" }, grp);
    const R = rings(x0, 0, x1, 36, 3, 1.4), SL = rings(x0 + 9, 11, x1 - 9, 25, 5, 1)[0];
    const puff = [];
    for (const [r, z] of [[6, 0], [5, 3], [3, 6]]) puff.push(circ(r, 16).map((q) => ({ u: q.u + (x0 + x1) / 2, v: q.v * 0.6 + 18, z: 24 + z })));
    const draw = (v) => {
      const dy = v * OUT;
      body(s, R, 3, 24, dy);
      slot.setAttribute("d", poly(W(dy, SL, 24)));
      tuft.setAttribute("d", poly(hull(puff.flatMap((ring) => ring.map((q) => P(q.u, q.v + dy, q.z))))));
    };
    items.push({ s, draw, tw: tween(REST[k]), last: NaN, mid: P((x0 + x1) / 2, 18, 14) });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { const v = tval(it.tw, now); if (v !== it.last) { it.last = v; it.draw(v); } if (!tdone(it.tw, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 45 && Math.abs(items[best].mid[1] - sy) < 70 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      tset(it.tw, a < 0 ? REST[k] : AMT[Math.abs(k - a)], now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "box " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "glovedispenser",
  means: "A wall holder of three glove boxes: the box under the pointer slides out, and the boxes beside it slide a little.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[153, 85], [214, 115], [275, 145], null],
  mount,
});

otoscopewall.code:
/**
 * Wall diagnostic: a wall board with a transformer bar and three instrument
 * handles standing in its cradles, coiled cords hanging beneath. The pointer
 * picks a handle by where it stands: it tilts forward out of its cradle, and
 * the handles beside it tilt a little, staggered from it. At rest the first
 * handle leans out, bright.
 */
const { Cam, circ, fit, hull, open, poly, proj, rings, tset, tval, tdone, tween, disposer, mk, pointer, register, solid } = HL;

const N = 3, STEP = 38, TILT = 0.75, REST = [0.5, 0.1, 0.2], FAV = 0, AMT = [1, 0.4, 0.15];
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-6, -10, 104], [126, -10, 104], [-6, -10, 4], [126, 30, 8], [-6, 30, 60], [126, 30, 100]], 200, 166);
  const P = proj(C), g = mk("g", {}, svg);
  const W = (tf, ring, z) => ring.map((q) => P(...tf([q.u, q.v, z])));
  const body = (s, [o, i], z0, z1, tf, o1 = o) => {
    s.sil.setAttribute("d", poly(hull(W(tf, o, z0).concat(W(tf, o1, z1)))));
    s.cr.setAttribute("d", poly(W(tf, i, z1)));
  };
  const id = (p) => p;
  body(solid(g), rings(-6, -10, 126, -4, 3, 1), 4, 104, id);
  body(solid(g), rings(2, -4, 118, 14, 4, 1.5), 36, 52, id);
  for (let k = 0; k < N; k++) {
    const x = 22 + k * STEP, pts = [];
    for (let t = 0; t <= 60; t++) { const a = t * 0.63; pts.push(P(x + 4 * Math.cos(a), 6 + 4 * Math.sin(a), 36 - t * 0.45)); }
    mk("path", { d: open(pts), class: "nf lo" }, g);
  }

  const items = [];
  for (let k = 0; k < N; k++) {
    const x = 22 + k * STEP, y = 5, grp = mk("g", {}, g);
    const h = solid(grp), head = solid(grp);
    const H = [disc(x, y, 5.5), disc(x, y, 4)];
    const heads = [
      [disc(x, y, 6.5), disc(x, y, 5), 86, 96, disc(x, y, 2.2)],
      [disc(x, y, 8), disc(x, y, 6.5), 86, 92, disc(x, y, 8)],
      [disc(x, y, 4.5), disc(x, y, 3), 86, 98, disc(x, y, 4.5)],
    ][k];
    const draw = (v) => {
      const a = -v * TILT, c = Math.cos(a), s = Math.sin(a), lift = v * 5;
      const tf = ([px, py, pz]) => { const dy = py - 11, dz = pz - 52; return [px, 11 + dy * c - dz * s, 52 + lift + dy * s + dz * c]; };
      body(h, H, 52, 86, tf);
      body(head, [heads[0], heads[1]], heads[2], heads[3], tf, heads[4]);
    };
    items.push({ s: h, draw, tw: tween(REST[k]), last: NaN, mid: P(x, y, 70) });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { const v = tval(it.tw, now); if (v !== it.last) { it.last = v; it.draw(v); } if (!tdone(it.tw, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    items.forEach((it, k) => { const d = Math.abs(it.mid[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 40 && Math.abs(items[best].mid[1] - sy) < 90 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      tset(it.tw, a < 0 ? REST[k] : AMT[Math.abs(k - a)], now, from < 0 ? 0 : Math.abs(k - from) * stag);
      it.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : ["oto", "ophth", "lamp"][a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

