    { s: box(-34, 6, 11, -4, 10, 14) }, { s: box(-34, 40, 11, -4, 44, 14) }, { s: box(-38, 6, 11, -34, 44, 14) },
    { s: solidOf([[0, 15], [84, 15], [94, 40], [-8, 40]], "y", 0, 50, [0, 0, 0]), m: tip, hi: 1, bias: 4 },
