  const R = all(0).map((v) => P(...v)), bx = [Math.min(...R.map((q) => q[0])) - 12, Math.max(...R.map((q) => q[0])) + 12];
  const by = [Math.min(...R.map((q) => q[1])) - 12, Math.max(...R.map((q) => q[1])) + 12];
