  let amt = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, -8, 0], [L, W + 8, 0], [0, W + 8, 0], [L, -8, 0], [L / 2, W / 2, RZ + 14]], 200, 160);
  const P = proj(C), front = facing(C);
