    last = cx;
    const tip = clamp((cx - x.t) * 0.04 * amt, -6, 6);
    const Z = (px, z) => z + (px - cx) * tip * 0.05;
    const ring = rrect(cx - RW / 2, -12, cx + RW / 2, W + 12, 4, 4);
    const pts = ring.map((q) => P(q.u, q.v, Z(q.u, RZ))).concat(ring.map((q) => P(q.u, q.v, Z(q.u, RZ + 3))));
