  const parts = [mk("path", { class: "sil hi" }, g), mk("path", { class: "sil hi" }, g), mk("path", { class: "sil hi" }, g)];
  const band = mk("path", { class: "nf lo" }, g);

  const t = tween(0);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
