  bag.add(B.unregister);
  const mid = P(0, 0, FZ / 2);
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(t, o ? 1 : 0, performance.now(), 0);
    read.textContent = o ? "lifted" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 90 && Math.abs(sy - mid[1]) < 110), leave: () => set(false) }));
