  name: "earthermo",
  means: "An ear thermometer in its dock: it turns to face the pointer and tips its probe toward it, the screen lit.",
  rules: [1, 3, 5, 6],
  range: [0, 15, 30],
  tour: [[340, 230], [60, 230], [200, 300], null],
  mount,
});

springscale.code:
/**
 * Spring balance: a hanging spring scale under the arm of a stand, a weight
 * on its hook. The pointer swings the balance toward it, and the further it
 * swings the more the spring stretches out of the barrel. At rest it hangs
 * a little off true, the barrel bright. The slider is the widest swing.
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, unproj, clamp, rad, hull, seg,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 112, BL = 40, BR = 6.5;
const add = (c, a, k) => [c[0] + a[0] * k, c[1] + a[1] * k, c[2] + a[2] * k];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a) => { const l = Math.hypot(...a); return a.map((v) => v / l); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-40, -40, 0], [34, 34, 0], [0, -40, TOP + 6], [-50, 50, 30], [50, -50, 30]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [b0, b1] = rings(-40, -40, 30, 30, 8, 2);
  put(solid(g), prism(P, front, b0, b1, 0, 5));
  const post = circ(3.5, 20).map((q) => ({ ...q, u: q.u, v: q.v - 40 }));
  put(solid(g), prism(P, front, post, circ(2, 20).map((q) => ({ ...q, u: q.u, v: q.v - 40 })), 5, TOP + 6));
  const arm = [[0, -40, TOP + 6], [0, 0, TOP + 6]];
  mk("path", { d: poly([P(...arm[0]), P(...arm[1]), P(0, 0, TOP + 2), P(0, -40, TOP + 2)]) }, g);
  const loop = mk("path", { class: "nf" }, g), barrel = mk("path", { class: "sil" }, g), cap = mk("path", { class: "nf lo" }, g);
  const mark = mk("path", { class: "nf lo" }, g), rod = mk("path", { class: "nf" }, g), hook = mk("path", { class: "nf" }, g);
  const wt = mk("path", { class: "" }, g), wtop = mk("path", { class: "nf lo" }, g);
  const ang = spring(rad(10)), dir = spring(rad(-60)), ext = spring(8);
  const w = norm([1, -1, 0]);

  function ring3(c, a, b, r, n = 32) { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push(P(...add(add(c, a, r * Math.cos(t)), b, r * Math.sin(t)))); } return o; }
  function draw() {
    const a = ang.x, b = dir.x;
    const d = [Math.sin(a) * Math.cos(b), Math.sin(a) * Math.sin(b), -Math.cos(a)];
    const p1 = norm(cross(d, w)), p2 = cross(d, p1);
    const h = [0, 0, TOP + 3];
    loop.setAttribute("d", poly(ring3(add(h, d, 3), d, w, 3, 20)));
    const t0 = add(h, d, 6), t1 = add(h, d, 6 + BL);
    barrel.setAttribute("d", poly(hull(ring3(t0, p1, p2, BR).concat(ring3(t1, p1, p2, BR)))));
    cap.setAttribute("d", poly(ring3(t0, p1, p2, BR)));
    const e = ext.x, m = add(h, d, 12 + e);
    mark.setAttribute("d", seg(P(...add(m, w, -BR)), P(...add(m, w, BR))) + seg(P(...add(add(h, d, 14), w, -2)), P(...add(add(h, d, 4 + BL), w, -2))));
    const r1 = add(t1, d, 6 + e);
    rod.setAttribute("d", open([P(...t1), P(...r1)]));
    const hk = []; for (let i = 0; i <= 10; i++) { const t = Math.PI * (i / 10) * 1.3; hk.push(P(...add(add(r1, d, 4 - 4 * Math.cos(t)), w, 4 * Math.sin(t)))); }
    hook.setAttribute("d", open(hk));
    const wc = add(r1, d, 8), wb = add(wc, d, 18);
    wt.setAttribute("d", poly(hull(ring3(wc, p1, p2, 11).concat(ring3(wb, p1, p2, 11)))));
    wtop.setAttribute("d", poly(ring3(wc, p1, p2, 11)));
  }
  draw();
  barrel.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(ang, dt) | stepS(dir, dt) | stepS(ext, dt); draw(); return !!m; });
  bag.add(B.unregister);
  function aim(wx, wy) {
    const a = Math.atan2(wy, wx);
    let dd = a - dir.t; dd = Math.atan2(Math.sin(dd), Math.cos(dd));
    dir.t += dd;
    const k = clamp(Math.hypot(wx, wy) / 70, 0, 1);
    ang.t = rad(reach) * k; ext.t = 4 + 18 * k;
    read.textContent = Math.round(10 + 40 * k) + " g";
    B.wake();
  }
  function rest() { ang.t = rad(10); ext.t = 8; read.textContent = "rest"; B.wake(); }
  rest();
  bag.add(pointer(stage, { move: ([sx, sy]) => { const [wx, wy] = unproj(C, sx, sy, 0); aim(wx, wy); }, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "springscale",
  means: "A spring balance on a stand: it swings toward the pointer, and the further it swings the more the spring stretches.",
  rules: [1, 3, 5, 6],
  range: [10, 25, 40],
  tour: [[365, 259], [60, 250], [200, 300], null],
  mount,
});

gyroscope.code:
/**
 * Gyroscope: a rotor in a gimbal ring on a post and a round foot. The
 * pointer turns the gimbal to face it and tips the rotor's axle by how far
 * away it stands. At rest the ring is turned a little and the rotor leans,
 * bright. The slider is the most the rotor may tip.
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, unproj, clamp, rad, hull,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const H = 62, RG = 36, RR = 26;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-RG, -RG, 0], [RG, RG, 0], [0, 0, H + RG + 2], [RG, -RG, H], [-RG, RG, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [b0, b1] = rings(-26, -26, 26, 26, 26, 2);
  put(solid(g), prism(P, front, b0, b1, 0, 6));
  put(solid(g), prism(P, front, disc(3.5, 20), disc(2, 20), 6, H - RG + 1));
  const back = mk("path", { class: "nf" }, g), backI = mk("path", { class: "nf lo" }, g);
  const axle = mk("path", { class: "nf" }, g);
  const rotor = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), hub = mk("path", { class: "nf" }, g);
  const frontR = mk("path", { class: "nf" }, g), frontI = mk("path", { class: "nf lo" }, g);
  const yaw = spring(rad(25)), tilt = spring(rad(22));
  const add = (c, a, k) => [c[0] + a[0] * k, c[1] + a[1] * k, c[2] + a[2] * k];
  const ring3 = (c, a, b, r, n = 48) => { const o = []; for (let i = 0; i <= n; i++) { const t = (i / n) * 2 * Math.PI; o.push(add(add(c, a, r * Math.cos(t)), b, r * Math.sin(t))); } return o; };

  function draw() {
    const y = yaw.x, t = tilt.x, c = [0, 0, H];
    const u = [Math.cos(y), Math.sin(y), 0], z = [0, 0, 1];
    const half = (pts, near) => { const o = []; let cur = []; for (const p of pts) { if ((p[0] + p[1] > 0) === near) cur.push(P(...p)); else if (cur.length) { o.push(open(cur)); cur = []; } } if (cur.length) o.push(open(cur)); return o.join(" "); };
    const gO = ring3(c, u, z, RG), gI = ring3(c, u, z, RG - 3.5);
    back.setAttribute("d", half(gO, false)); backI.setAttribute("d", half(gI, false));
    frontR.setAttribute("d", half(gO, true)); frontI.setAttribute("d", half(gI, true));
    const ax = [u[0] * Math.sin(t), u[1] * Math.sin(t), Math.cos(t)];
    const pv = [-Math.sin(y), Math.cos(y), 0];
    const q = [ax[1] * pv[2] - ax[2] * pv[1], ax[2] * pv[0] - ax[0] * pv[2], ax[0] * pv[1] - ax[1] * pv[0]];
    axle.setAttribute("d", open([P(...add(c, ax, -(RG - 3.5))), P(...add(c, ax, RG - 3.5))]));
    const top = ring3(add(c, ax, 3), pv, q, RR), bot = ring3(add(c, ax, -3), pv, q, RR);
    rotor.setAttribute("d", poly(hull(top.concat(bot).map((p) => P(...p)))));
    const up = ax[0] + ax[1] + ax[2] * 1.4 > 0 ? top : bot;
    face.setAttribute("d", poly(ring3(add(c, ax, up === top ? 3 : -3), pv, q, RR - 6).map((p) => P(...p))));
    hub.setAttribute("d", poly(ring3(add(c, ax, up === top ? 3 : -3), pv, q, 4, 20).map((p) => P(...p))));
  }
  draw();
  rotor.classList.add("hi");

  const B = register(stage, (dt) => { const m = stepS(yaw, dt) | stepS(tilt, dt); draw(); return !!m; });
  bag.add(B.unregister);
  function aim(wx, wy) {
    const a = Math.atan2(wy, wx);
    let d = a - yaw.t; d = Math.atan2(Math.sin(d), Math.cos(d));
    yaw.t += d;
    const k = clamp(Math.hypot(wx, wy) / 70, 0.15, 1);
    tilt.t = rad(reach) * k;
    read.textContent = Math.round((((yaw.t * 180) / Math.PI) % 360 + 360) % 360) + "°";
    B.wake();
  }
  function rest() { yaw.t = rad(25) + Math.round((yaw.t - rad(25)) / (2 * Math.PI)) * 2 * Math.PI; tilt.t = rad(22); read.textContent = "rest"; B.wake(); }
  rest();
  bag.add(pointer(stage, { move: ([sx, sy]) => { const [wx, wy] = unproj(C, sx, sy, 0); aim(wx, wy); }, leave: rest }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

