weatherhouse.code:
/**
 * Weather house: a little gabled house on a round base, two arched doors in
 * its front, and the weather pair on the turning ring round it, a woman in a
 * full skirt for fair days and a man in a brimmed hat for rain. At rest she
 * stands out at the left door, bright. The pointer over the house brings the
 * weather in: the ring swings round, she goes behind and he comes out at the
 * right door. The slider is how far the ring turns.
 *
 * The pattern: one gesture answering (a turn on a tween); figures repaint
 * behind or in front of the house as they pass; the hit is on fixed planes.
 */
const {
  Cam, circ, clamp, facing, fit, hull, lerp, open, poly, prism, proj, rings, ringAt, rrect, run, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX = 30, CY = 20, RR = 25, HZ = 30, RZ = 48, A0 = 110, A1 = 250;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[CX - 34, CY - 34, 0], [CX + 34, CY + 34, 0], [CX - 34, CY + 34, 0], [CX + 34, CY - 34, 0], [CX, CY, RZ + 2], [CX - 34, CY + 34, 32]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const disc = (r, n) => circ(r, n).map((q) => ({ ...q, u: q.u + CX, v: q.v + CY }));

  put(solid(g), prism(P, front, disc(33, 64), disc(31.6, 64), 0, 3));
  const back = mk("g", {}, g), house = mk("g", {}, g), fore = mk("g", {}, g);
  // the house, its gable roof and the two arched doors
  const [hr, hi] = rings(12, 8, 48, 32, 3, 1);
  put(solid(house), prism(P, front, hr, hi, 3, HZ));
  const foot = rrect(9, 5, 51, 35, 3, 6), ridge = rrect(10, 19, 50, 21, 1, 4);
  const roof = solid(house);
  roof.sil.setAttribute("d", poly(hull(ringAt(P, foot, HZ).concat(ringAt(P, ridge, RZ)))));
  roof.cr.setAttribute("d", open(ringAt(P, run(rrect(10, 5.5, 50.5, 34.5, 3, 6), front), HZ + 0.6)));
  const arch = (x) => {
    const o = [P(x - 5, 32, 3)];
    for (let i = 0; i <= 10; i++) { const a = (i / 10) * Math.PI; o.push(P(x - 5 * Math.cos(a), 32, 16 + 5 * Math.sin(a))); }
    o.push(P(x + 5, 32, 3));
    return open(o);
  };
  mk("path", { class: "nf lo", d: arch(21) + arch(39) }, house);

  // a figure: a body hull, a head, and a skirt or a hat brim
  function figure(skirt) {
    const grp = mk("g", {}, fore);
    return { grp, body: mk("path", { class: "sil" }, grp), head: mk("path", { class: "sil" }, grp), skirt };
  }
  const ring = (x, y, r, z, n = 20) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; o.push(P(x + r * Math.cos(a), y + r * Math.sin(a), z)); } return o; };
  const ball = (x, y, z, r) => { const [sx, sy] = P(x, y, z), k = r * 2.9, o = []; for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; o.push([sx + k * Math.cos(a), sy + k * Math.sin(a)]); } return poly(o); };
  const her = figure(true), him = figure(false);
  function drawFig(f, a) {
    const x = CX + RR * Math.cos(a), y = CY + RR * Math.sin(a);
    f.body.setAttribute("d", f.skirt
      ? poly(hull(ring(x, y, 7.5, 3).concat(ring(x, y, 3, 22))))
      : poly(hull(ring(x, y, 4.5, 3).concat(ring(x, y, 4.5, 22)))));
    f.head.setAttribute("d", ball(x, y, 26.5, 4.2) + (f.skirt ? "" : poly(hull(ring(x, y, 7.5, 29.5).concat(ring(x, y, 7.5, 30.5), ring(x, y, 3.6, 34))))));
    const inFront = x + y > CX + CY + 4;
    if (f.grp.parentNode !== (inFront ? fore : back)) (inFront ? fore : back).appendChild(f.grp);
  }

  const t = tween(0);
  let last = NaN;
  function draw(k) {
    if (k === last) return;
    last = k;
    const a = (lerp(A0, lerp(A0, A1, clamp(amt, 0, 1)), k) * Math.PI) / 180;
    drawFig(her, a);
    drawFig(him, a + Math.PI);
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(t, on ? 1 : 0, performance.now(), 0);
    her.body.classList.toggle("hi", !on);
    him.body.classList.toggle("hi", on);
    read.textContent = on ? "rain" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    return [0, 15, HZ, RZ].some((z) => {
      const [x, y] = unproj(C, sx, sy, z);
      return Math.hypot(x - CX, y - CY) < 38;
    });
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "weatherhouse",
  means: "A weather house: the pointer over it swings the ring round, the fair-weather woman goes in and the rain man comes out.",
  rules: [1, 4, 5, 6],
  range: [0.4, 1, 1],
  tour: [[134, 158], [200, 140], [250, 200], null],
  mount,
});

hosereel.code:
/**
 * Hose reel: a garden hose reel on its low stand, two spoked side wheels on
 * an axle, the wound drum between them, a crank on the near wheel and the
 * hose's end lying out on the ground with its nozzle. At rest the crank
 * stands up, its handle bright. The pointer over the reel pays the hose out:
 * the wheel and crank turn, and the hose runs out along the ground. The
 * slider is how far.
 *
 * The pattern: one gesture answering (a turn and a slide on one tween); the
 * hit is on fixed planes through the rest pose.
 */
const {
  Cam, clamp, facing, fit, hull, lerp, open, poly, prism, proj, rings, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 27, RD = 19, ZC = 32, W = 40, OUT0 = 10, OUT1 = 92;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-R, -4, 0], [R, W + 14, 0], [-R, -4, ZC + R], [R + OUT1 + 12, W / 2, 0], [-R, W + 14, ZC + R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const circle = (r, y, n = 40) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; o.push(P(r * Math.cos(a), y, ZC + r * Math.sin(a))); } return o; };
  const disc = (r, y0, y1) => poly(hull(circle(r, y0).concat(circle(r, y1))));

  // the stand
  const [sr, si] = rings(-R - 4, -6, R + 4, W + 6, 6, 1.4);
  put(solid(g), prism(P, front, sr, si, 0, 3));
  mk("path", { class: "nf lo", d: seg(P(-R * 0.6, 0, 3), P(0, 0, ZC)) + seg(P(R * 0.6, 0, 3), P(0, 0, ZC)) }, g);
  // the far wheel, the wound drum, then the hose paying out
  mk("path", { class: "sil", d: disc(R, -2.5, 0) }, g);
  mk("path", { class: "sil", d: disc(RD, 0, W) }, g);
  const hose = mk("path", { class: "nf sil" }, g), noz = mk("path", { class: "sil" }, g);
  // the near wheel, its spokes and the crank
  mk("path", { class: "sil", d: disc(R, W, W + 2.5) }, g);
  mk("path", { class: "nf lo", d: poly(circle(R - 3, W + 2.5)) }, g);
  const spokes = mk("path", { class: "nf lo" }, g);
  const arm = mk("path", { class: "nf sil" }, g), knob = mk("path", { class: "sil" }, g);

  const t = tween(0);
  let last = NaN;
  function draw(k) {
    if (k === last) return;
    last = k;
    const f = k * clamp(amt, 0, 1), th = Math.PI / 2 + f * Math.PI * 2.75, yN = W + 2.5;
    let sp = "";
    for (let i = 0; i < 4; i++) { const a = th + (i * Math.PI) / 2; sp += seg(P(0, yN, ZC), P((R - 3) * Math.cos(a), yN, ZC + (R - 3) * Math.sin(a))); }
    spokes.setAttribute("d", sp);
    const ex = 0.72 * R * Math.cos(th), ez = ZC + 0.72 * R * Math.sin(th);
    arm.setAttribute("d", seg(P(0, yN, ZC), P(ex, yN, ez)) + seg(P(0, yN, ZC), P(0, yN + 3, ZC)));
    const knobPts = [];
    for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2; knobPts.push(P(ex + 2 * Math.cos(a), yN, ez + 2 * Math.sin(a)), P(ex + 2 * Math.cos(a), yN + 9, ez + 2 * Math.sin(a))); }
    knob.setAttribute("d", poly(hull(knobPts)));
    const len = lerp(OUT0, OUT1, f), ye = W / 2, x1 = RD + 6 + len;
    const line = (d) => open([P(RD * 0.6, ye + d, ZC - RD * 0.8), P(RD + 1, ye + d, 6), P(RD + 6, ye + d, 1.2), P(x1, ye + 2 + d, 1.2)]);
    hose.setAttribute("d", line(-1.6) + line(1.6));
    const nz = [];
    for (let i = 0; i < 10; i++) { const a = (i / 10) * Math.PI * 2; nz.push(P(x1, ye + 2 + 2.4 * Math.cos(a), 2.4 + 2.4 * Math.sin(a)), P(x1 + 11, ye + 2 + 1.4 * Math.cos(a), 2.4 + 1.4 * Math.sin(a))); }
    noz.setAttribute("d", poly(hull(nz)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(t, on ? 1 : 0, performance.now(), 0);
    knob.classList.add("hi");
    read.textContent = on ? "pay out" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    return [0, ZC, ZC + R].some((z) => {
      const [x, y] = unproj(C, sx, sy, z);
      return x > -R - 6 && x < R + OUT0 + 40 && y > -8 && y < W + 14;
    });
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "hosereel",
  means: "A garden hose reel: the pointer over it turns the crank and wheel, and the hose pays out along the ground.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[101, 103], [150, 150], [200, 200], null],
  mount,
});

hole2punch.code:
/**
 * Hole punch: a two-hole office punch, a weighted base with a paper guide,
 * the die block across its back and a long lever hinged over it. At rest the
 * lever stands open, raised at its front, bright. The pointer over the punch
 * presses it: the lever swings down onto the block. The slider is how far.
 *
 * The pattern: one part answering (a tilt on a tween); the hit is on the
 * ground plane, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, rrect, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 0, X1 = 64, Y0 = 0, Y1 = 40, HZ = 22, HY = 6, OPEN = 34, SHUT = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[X0, Y0, 0], [X1, Y1, 0], [X0, Y1, 0], [X1, Y0, 0], [X0, Y1, HZ + 26], [X1, Y1, HZ + 26]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the base and the paper guide on it
  const [br, bi] = rings(X0, Y0, X1, Y1, 7, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  const [gr, gi] = rings(X0 + 4, Y1 - 6, X0 + 14, Y1 - 2, 1.5, 0.6);
  put(solid(g), prism(P, front, gr, gi, 5, 7));
  // the die block across the back, its two holes on top
  const [kr, ki] = rings(X0 + 4, Y0 + 2, X1 - 4, Y0 + 16, 4, 1.2);
  put(solid(g), prism(P, front, kr, ki, 5, HZ - 2));
  const holes = [18, 46].map((x) => poly(rrect(x - 3, 6, x + 3, 12, 3, 4).map((q) => P(q.u, q.v, HZ - 2)))).join("");
  mk("path", { class: "nf lo", d: holes }, g);

  // the lever: a thick rounded plate, hinged along x at the back
  const lev = solid(g);
  const LR = rrect(X0 - 2, 0, X1 + 2, Y1 + 4 - HY, 8, 10), LI = rrect(X0 + 0.5, 2.5, X1 - 0.5, Y1 + 1.5 - HY, 6, 10);
  const ang = tween(OPEN);
  let last = NaN;
  function at(q, w, a) {
    const r = (a * Math.PI) / 180, c = Math.cos(r), s = Math.sin(r);
    return P(q.u, HY + q.v * c - w * s, HZ + q.v * s + w * c);
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    const top = LR.map((q) => at(q, 3.5, a)), bot = LR.map((q) => at(q, 0, a));
    lev.sil.setAttribute("d", poly(hull(top.concat(bot))));
    lev.cr.setAttribute("d", poly(LI.map((q) => at(q, 3.5, a))));
  }
  lev.cr.setAttribute("class", "nf lo");

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? lerpA(amt) : OPEN, performance.now(), 0);
    lev.sil.classList.add("hi");
    read.textContent = on ? "punch" : "rest";
    B.wake();
  }
  const lerpA = (v) => OPEN + (SHUT - OPEN) * clamp(v, 0, 1);
  function hit([sx, sy]) {
    return [0, HZ, HZ + 18].some((z) => {
      const [x, y] = unproj(C, sx, sy, z);
      return x > X0 - 4 && x < X1 + 4 && y > Y0 - 4 && y < Y1 + 6;
    });
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "hole2punch",
  means: "A two-hole punch: the pointer over it presses the long lever down onto the die block.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[166, 120], [200, 170], [250, 190], null],
  mount,
});

letteropener.code:
/**
 * Letter opener: a sealed envelope lying flat, its flap folded over the back,
 * and a letter opener lying on it, a rounded handle and a long tapering blade.
 * At rest the opener lies at the envelope's left end, its handle bright. The
 * pointer over the envelope slits it: the opener slides along and the flap
 * swings open behind it. The slider is how far the flap opens.
 *
 * The pattern: one gesture answering (a slide and a tilt on one tween); the
 * hit is on the ground plane, which never moves.
 */
const {
  Cam, clamp, fillet, fit, hull, lerp, poly, proj, rings, prism, facing, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 92, Y1 = 58, EZ = 3, BY = 40, SLIDE = 34, FLAP = 30, OPEN = 64;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [0, Y1, 0], [X1, 0, 0], [0, 0, 26], [X1, 0, 26], [X1 + 12, BY, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the envelope: a thin rounded plate, its sealed-side folds on top
  const [er, ei] = rings(0, 0, X1, Y1, 3, 1);
  put(solid(g), prism(P, front, er, ei, 0, EZ));
  mk("path", { class: "nf lo", d: poly([P(1.5, Y1 - 1.5, EZ), P(X1 / 2, Y1 * 0.42, EZ), P(X1 - 1.5, Y1 - 1.5, EZ)]).replace(/Z$/, "") }, g);

  // the flap: a rounded triangle hinged along the back edge
  const flap = mk("path", { class: "sil" }, g);
  const FL = fillet([[1, 0], [X1 - 1, 0], [X1 / 2, FLAP]], [1, 1, 4], 4);
  // the opener: handle and blade, both thin plates
  const opener = mk("g", {}, g);
  const hand = mk("path", { class: "sil" }, opener), blade = mk("path", { class: "sil" }, opener);
  const HP = fillet([[0, -4.5], [26, -4.5], [26, 4.5], [0, 4.5]], [4, 1, 1, 4], 4);
  const BP = fillet([[26, -3.2], [70, -0.6], [74, 0.4], [26, 3.2]], [0.5, 1, 1, 0.5], 4);
  const t = tween(0);
  let last = NaN;
  function plate(pts, x0, z0, z1) {
    const ring = (z) => pts.map(([u, v]) => P(x0 + u, BY + v, z));
    return poly(hull(ring(z0).concat(ring(z1))));
  }
  function draw(k) {
    if (k === last) return;
    last = k;
    const a = (lerp(0, OPEN * clamp(amt, 0, 1), k) * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    flap.setAttribute("d", poly(FL.map(([u, v]) => P(u, v * c, EZ + v * s + 0.4))));
    const x0 = 4 + SLIDE * k;
    hand.setAttribute("d", plate(HP, x0, EZ, EZ + 4.5));
    blade.setAttribute("d", plate(BP, x0, EZ, EZ + 1.4));
  }

  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(t, on ? 1 : 0, performance.now(), 0);
    hand.classList.add("hi");
    read.textContent = on ? "slit" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, EZ);
    return x > -4 && x < X1 + 14 && y > -10 && y < Y1 + 4;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "letteropener",
  means: "A letter opener on a sealed envelope: the pointer over it slides the blade along and swings the flap open.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[133, 164], [200, 160], [270, 180], null],
  mount,
});

packcube.code:
/**
 * Packing cube: a soft zip-round travel cube, a rounded body with the zip
 * seam running round it and a carry loop on its end, and a mesh-panelled lid
 * hinged along the back. At rest the zip is half undone and the lid stands
 * ajar, bright. The pointer over the cube unzips it: the lid swings open.
 * The slider is how far it opens.
 *
 * The pattern: one part answering (a tilt on a tween); the hit is on fixed
 * planes through the rest pose.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, run, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 70, Y1 = 46, HZ = 28, AJAR = 14, WIDE = 72;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [0, Y1, 0], [X1, 0, 0], [0, 0, HZ + 48], [X1, 0, HZ + 48]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the body, its zip seam round the near sides and the carry loop on the end
  const [br, bi] = rings(0, 0, X1, Y1, 10, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, HZ));
  const seam = rrect(-0.01, -0.01, X1 + 0.01, Y1 + 0.01, 10, 10);
  mk("path", { class: "nf dash", d: open(ringAt(P, run(seam, front), HZ - 5)) }, g);
  const loop = [];
  for (let i = 0; i <= 12; i++) { const a = (i / 12) * Math.PI; loop.push(P(X1 + 3.5 * Math.sin(a), 16 + 7 * (1 - Math.cos(a)), HZ - 8)); }
  mk("path", { class: "nf sil", d: open(loop) }, g);

  // the lid: a thick rounded panel hinged along the back edge, mesh inset on top
  const lid = solid(g);
  lid.cr.setAttribute("class", "nf lo");
  const LR = rrect(0, 0, X1, Y1, 10, 10), LI = rrect(7, 7, X1 - 7, Y1 - 7, 5, 8);
  const ang = tween(AJAR);
  let last = NaN;
  function at(q, w, a) {
    const r = (a * Math.PI) / 180, c = Math.cos(r), s = Math.sin(r);
    return P(q.u, q.v * c - w * s, HZ + q.v * s + w * c);
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    lid.sil.setAttribute("d", poly(hull(LR.map((q) => at(q, 5, a)).concat(LR.map((q) => at(q, 0, a))))));
    lid.cr.setAttribute("d", poly(LI.map((q) => at(q, 5, a))));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  const wide = (v) => AJAR + (WIDE - AJAR) * clamp(v, 0, 1);
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? wide(amt) : AJAR, performance.now(), 0);
    lid.sil.classList.add("hi");
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    return [0, HZ, HZ + 14].some((z) => {
      const [x, y] = unproj(C, sx, sy, z);
      return x > -4 && x < X1 + 6 && y > -4 && y < Y1 + 4;
    });
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
