signpost.code:
/**
 * Rent sign: a post on a footing with an arm, and a board hung from the arm
 * on two short chains. The pointer over the board swings it out on its
 * chains, toward the street. At rest it hangs a little forward, bright.
 * The slider is how far it swings.
 *
 * The pattern: one part answering (a hinge). Tween on the swing; the hit is
 * the board's rest box on screen, which never moves.
 */
const {
  Cam, fit, hull, poly, proj, rad, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Z0 = 100, REST = 8;
const near = ([x, y, z]) => 0.61 * x + 0.61 * y + 0.5 * z;
/** a rounded slab in a local (u, v) plane, thickness t along w; T maps local to world */
function slab(P, T, u0, v0, u1, v1, r, t) {
  const ring = rrect(u0, v0, u1, v1, r, 3);
  const A = ring.map((q) => T(q.u, q.v, 0)), B = ring.map((q) => T(q.u, q.v, t));
  const um = (u0 + u1) / 2, vm = (v0 + v1) / 2, top = near(T(um, vm, t)) >= near(T(um, vm, 0));
  return { sil: poly(hull(A.concat(B).map((p) => P(...p)))), crease: poly((top ? B : A).map((p) => P(...p))), w: top ? t : 0 };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const sw = (u, s, w, th) => [u, s * Math.sin(th) + w * Math.cos(th), Z0 - s * Math.cos(th) + w * Math.sin(th)];
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-10, -10, 0], [10, 10, 0], [74, 0, Z0 + 6], [70, 0, Z0 - 48], sw(70, 48, 0, rad(80)), [0, 0, Z0 + 10]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  put(solid(g), slab(P, (u, v, w) => [u, v, w], -10, -10, 10, 10, 3, 3));
  put(solid(g), slab(P, (u, v, w) => [u, w - 3, v], -3, 3, 3, Z0 + 12, 1, 6));
  put(solid(g), slab(P, (u, v, w) => [u, w - 2.5, v], -4, Z0, 74, Z0 + 5, 1, 5));
  const chains = mk("path", { class: "nf" }, g);
  const board = solid(g);
  const face = mk("path", { class: "nf lo" }, board.g);
  const sw0 = tween(REST);
  let last = NaN;

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg), T = (u, v, w) => sw(u, v, w - 1, th);
    const s = slab(P, T, 12, 6, 68, 46, 2, 2);
    put(board, s);
    let d = "";
    for (const x of [18, 62]) d += seg(P(x, 0, Z0), P(...T(x, 6, 1)));
    chains.setAttribute("d", d);
    let f = poly(rrect(16, 10, 64, 42, 1.5, 2).map((q) => P(...T(q.u, q.v, s.w))));
    for (const [a, b, v] of [[22, 58, 20], [26, 54, 28], [30, 50, 35]]) f += seg(P(...T(a, v, s.w)), P(...T(b, v, s.w)));
    face.setAttribute("d", f);
  }

  const B = register(stage, (_dt, now) => { draw(tval(sw0, now)); return !tdone(sw0, now); });
  bag.add(B.unregister);

  const box = [[12, 6], [68, 6], [12, 46], [68, 46]].map(([u, v]) => P(...sw(u, v, 0, rad(REST))));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const hit = ([sx, sy]) => sx > Math.min(...xs) - 6 && sx < Math.max(...xs) + 6 && sy > Math.min(...ys) - 10 && sy < Math.max(...ys) + 6;

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(sw0, a ? amp : REST, performance.now(), 0);
    board.sil.classList.add("hi");
    read.textContent = a ? Math.round(amp) + "°" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; if (act) { tset(sw0, amp, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "signpost",
  means: "A rent sign hung from a post's arm: the pointer over the board swings it out on its chains.",
  rules: [1, 4, 5, 6],
  range: [30, 60, 80],
  tour: [[200, 160], [210, 170], [200, 180], null],
  mount,
});

catapult.code:
/**
 * Catapult: a toy catapult on a low sled, two posts holding an axle and a
 * long throwing arm with a cup at its end. At rest the arm lies cocked
 * back over the sled, bright. The pointer over the catapult releases it:
 * the arm swings up over the axle until it stands near upright. The
 * slider is how far the arm swings.
 *
 * The pattern: one part turning about an axle (swing).
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 64, PX = 22, PZ = 24, Y0 = 13, Y1 = 21, REST = 12;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-6, -2, 0], [86, 36, 0], [86, -2, 0], [-6, 36, 0], [PX - 10, 17, PZ + L + 8], [PX + L, 17, PZ + 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, 80, 34, 5, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, 6));
  // wheels' hint: two dim axles on the sled's near face
  mk("path", { d: poly(rings(8, 30, 20, 34, 2, 0.6)[0].map((q) => P(q.u, q.v, 2))), class: "nf lo" }, g);
  const postFar = solid(g);
  put(postFar, prism(P, front, ...rings(PX - 4, 4, PX + 4, 9, 1.5, 0.8), 6, PZ + 4));
  const arm = solid(g), cup = mk("path", { class: "nf" }, arm.g);
  const postNear = solid(g);
  put(postNear, prism(P, front, ...rings(PX - 4, 25, PX + 4, 30, 1.5, 0.8), 6, PZ + 4));
  mk("path", { d: poly(rings(PX - 2, 26, PX + 2, 29, 1, 0.5)[0].map((q) => P(q.u, q.v, PZ + 4))), class: "nf lo" }, postNear.g);

  const ang = tween(180 - REST);
  let last = NaN;
  function pts(a, s0, s1, t0, t1, y0, y1) {
    const r = (a * Math.PI) / 180, d = [Math.cos(r), Math.sin(r)], n = [-Math.sin(r), Math.cos(r)], out = [];
    for (const s of [s0, s1]) for (const t of [t0, t1]) for (const y of [y0, y1])
      out.push(P(PX + s * d[0] + t * n[0], y, PZ + s * d[1] + t * n[1]));
    return out;
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    // the arm points toward +x at a = 0 and swings up and back over the axle
    const b = 180 - a;
    arm.sil.setAttribute("d", poly(hull(pts(b, -8, L, -1.5, 1.5, Y0, Y1))));
    arm.cr.setAttribute("d", poly(hull(pts(b, -6, L - 2, 1.5, 1.5, Y0 + 1, Y1 - 1))));
    cup.setAttribute("d", poly(hull(pts(b, L - 12, L, 1.5, 7, Y0 - 2, Y1 + 2))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? 180 - swing : 180 - REST, performance.now(), 0);
    arm.sil.classList.add("hi");
    read.textContent = a ? "fire" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -20 && x < 100 && y > -30 && y < 50 ? 1 : 0;
  }
  setActive(0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = clamp(v, 60, 110); act = -2; }, destroy: bag.dispose };
}

hairline({
  name: "catapult",
  means: "A toy catapult cocked on its sled: the pointer releases it, and the long arm swings up over the axle with its cup.",
  rules: [1, 3, 5, 6],
  range: [60, 95, 110],
  tour: [[241, 202], [215, 215], [250, 195], null],
  mount,
});

slidepuzzle.code:
/**
 * Slide puzzle: a tray of eight square tiles in a three by three frame,
 * one corner slot empty. The pointer picks a tile on the tiles' top plane:
 * when it shares a row or column with the gap, it and the tiles between
 * slide one slot into the gap, staggered from it. At rest one tile sits
 * half way into the gap, bright. The slider is the stagger.
 *
 * The pattern: one of many on a grid (lockers), parts sliding one slot.
 */
const {
  Cam, clamp, facing, fit, prism, proj, rings, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 3, T = 20, G = 1.5, F = 5, TZ = 4, TH = 7, W = 2 * F + N * T;
const GX = 2, GY = 2, FAV = 5; // gap at (2,2); tile index 5 is (1,2)

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[0, 0, 0], [W, W, 0], [W, 0, 0], [0, W, 0], [0, 0, TZ + TH], [W, W, TZ + TH]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(0, 0, W, W, 5, 1.8);
  put(solid(g), prism(P, front, fr, fi, 0, TZ));
  const well = rings(F - 1, F - 1, W - F + 1, W - F + 1, 2, 0.5)[0];
  mk("path", { d: "M" + well.map((q) => P(q.u, q.v, TZ).join(",")).join("L") + "Z", class: "nf lo" }, g);
  const tl = mk("g", {}, g);

  const tiles = [];
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    if (i === GX && j === GY) continue;
    const el = solid(tl);
    const dir = i === GX ? [0, 1] : j === GY ? [1, 0] : [0, 0];
    tiles.push({ i, j, el, dir, s: tween(0), last: NaN, key: 0 });
  }
  tiles.forEach((t, k) => { t.rest = k === FAV ? 0.5 : 0; t.s = tween(t.rest); });

  function draw(t, s) {
    const x0 = F + t.i * T + G / 2 + s * T * t.dir[0], y0 = F + t.j * T + G / 2 + s * T * t.dir[1];
    t.key = x0 + y0;
    put(t.el, prism(P, front, ...rings(x0, y0, x0 + T - G, y0 + T - G, 3, 1.4), TZ, TZ + TH));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false, dirty = false;
    for (const t of tiles) {
      const s = tval(t.s, now);
      if (s !== t.last) { draw(t, s); t.last = s; dirty = true; }
      if (!tdone(t.s, now)) moving = true;
    }
    if (dirty) [...tiles].sort((a, b) => a.key - b.key).forEach((t) => tl.appendChild(t.el.g));
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TZ + TH);
    const i = Math.floor((x - F) / T), j = Math.floor((y - F) / T);
    if (i < 0 || j < 0 || i >= N || j >= N) return -1;
    return tiles.findIndex((t) => t.i === i && t.j === j);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now(), at = a >= 0 ? tiles[a] : null;
    tiles.forEach((t, k) => {
      let s = t.rest, d = 0;
      if (at) {
        s = 0;
        if (at.dir[0] && t.dir[0] && t.i >= at.i) { s = 1; d = t.i - at.i; }
        if (at.dir[1] && t.dir[1] && t.j >= at.j) { s = 1; d = t.j - at.j; }
      }
      tset(t.s, s, now, d * stag);
      t.el.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = at ? `tile ${at.i + 1}·${at.j + 1}` : "rest";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = clamp(v, 0, 90); }, destroy: bag.dispose };
}

hairline({
  name: "slidepuzzle",
  means: "A sliding tile puzzle with one empty corner: the tile under the pointer and those between it and the gap slide one slot over.",
  rules: [1, 2, 5, 6],
  range: [0, 45, 90],
  tour: [[200, 160], [240, 190], [170, 150], null],
  mount,
});

doorhanger.code:
/**
 * Door hanger: a door with its knob, and a card hung on the knob by its
 * round hole. The pointer is a draught across the door: the card swings on
 * the knob toward it, on a spring. At rest the card hangs at a slight angle,
 * bright. The slider is how far it can swing.
 *
 * The pattern: a continuous swing (a spring on an angle), hit by screen x.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rrect, circ, spring, stepS, rad,
  disposer, mk, pointer, register,
} = HL;

const K = [22, 0, 70], CW = 17, CH = 42, DROP = 34, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-42, 0, 0], [42, 0, 130], [K[0] - 48, 10, -8], [K[0] + 48, 10, -8]], 200, 184);
  const P = proj(C), g = mk("g", {}, svg);
  const add = (a, b, s) => a.map((x, i) => x + b[i] * s);
  function slab(c, U, V, W, a, b, t, r, ring) {
    const pts = [], R = ring || rrect(-a, -b, a, b, r, 4), at = (q, z) => P(...add(add(add(c, U, q.u), V, q.v), W, z));
    for (const q of R) pts.push(at(q, -t / 2), at(q, t / 2));
    const inner = rrect(-a + 2, -b + 2, a - 2, b - 2, Math.max(1, r - 2), 4).map((q) => at(q, t / 2));
    return { sil: poly(hull(pts)), cr: poly(inner) };
  }
  // the door, a leaf facing +y, then its frame lip
  const door = slab([0, -3, 65], [1, 0, 0], [0, 0, 1], [0, 1, 0], 40, 63, 4, 3);
  mk("path", { d: door.sil, class: "sil" }, g);
  mk("path", { d: door.cr, class: "nf lo" }, g);
  const pane = slab([0, -1, 100], [1, 0, 0], [0, 0, 1], [0, 1, 0], 20, 18, 0.5, 2);
  mk("path", { d: pane.cr, class: "nf lo" }, g);
  const rose = slab(K, [1, 0, 0], [0, 0, 1], [0, 1, 0], 5, 5, 3, 5, circ(5, 24));
  mk("path", { d: rose.sil, class: "sil" }, g);
  const card = mk("path", { class: "sil" }, g), crc = mk("path", { class: "nf lo" }, g), hole = mk("path", { class: "nf" }, g);
  const knob = slab(add(K, [0, 1, 0], 6), [1, 0, 0], [0, 0, 1], [0, 1, 0], 4, 4, 8, 4, circ(4, 20));
  const kn = mk("path", { d: knob.sil, class: "sil" }, g);

  const th = spring(REST);
  let last = NaN;
  function draw() {
    if (th.x === last) return;
    last = th.x;
    const a = rad(th.x), D = [Math.sin(a), 0, -Math.cos(a)], U = [Math.cos(a), 0, Math.sin(a)];
    const c = add(add(K, D, DROP), [0, 1, 0], 4);
    const s = slab(c, U, [-D[0], 0, -D[2]], [0, 1, 0], CW, CH, 1.6, 4);
    card.setAttribute("d", s.sil); crc.setAttribute("d", s.cr);
    hole.setAttribute("d", poly(circ(5.5, 20).map((q) => P(...add(add(K, U, q.u), [-D[0], 0, -D[2]], q.v).map((x, i) => x + (i === 1 ? 4.8 : 0))))));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  const kx = P(...K)[0];
  function aim(p) {
    const on = p && Math.abs(p[0] - 200) < 190;
    th.t = on ? clamp((p[0] - kx) / 70, -1, 1) * 40 * reach : REST;
    card.classList.toggle("hi", true);
    read.textContent = on ? "swing " + Math.round(th.t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

