  name: "curtainrope",
  means: "Two curtain halves on a stage rail: they draw apart as the pointer nears the middle, and hang just parted at rest.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.2],
  tour: [[60, 170], [200, 170], [320, 170], null],
  mount,
});

trapdoor.code:
/**
 * Stage trapdoor: a square of stage floor with a trap cut in it, its lid
 * hinged on the far edge over a dashed shaft. The pointer near the trap
 * swings the lid open on a spring, wider the closer it comes. At rest the
 * lid stands ajar, bright. The slider is how wide it can open.
 *
 * The pattern: a continuous swing, hit on the ground plane (unproj).
 */
const {
  Cam, clamp, fit, hull, poly, proj, rrect, seg, unproj, spring, stepS, rad,
  disposer, mk, pointer, register,
} = HL;

const F = 66, T = 6, H = 24, REST = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-F, -F, 0], [F, F, -T], [F, -F, 0], [-F, F, -T], [0, -H, T + 2 * H]], 200, 168);
  const P = proj(C), g = mk("g", {}, svg);
  const add = (a, b, s) => a.map((x, i) => x + b[i] * s);
  function slab(c, U, V, W, a, b, t, r) {
    const pts = [], at = (q, z) => P(...add(add(add(c, U, q.u), V, q.v), W, z));
    for (const q of rrect(-a, -b, a, b, r, 4)) pts.push(at(q, -t / 2), at(q, t / 2));
    const inner = rrect(-a + 2, -b + 2, a - 2, b - 2, Math.max(1, r - 2), 4).map((q) => at(q, t / 2));
    return { sil: poly(hull(pts)), cr: poly(inner) };
  }
  const floor = slab([0, 0, -T / 2], [1, 0, 0], [0, 1, 0], [0, 0, 1], F, F, T, 6);
  mk("path", { d: floor.sil, class: "sil" }, g);
  mk("path", { d: floor.cr, class: "nf lo" }, g);
  // boards across the floor, then the trap's opening and its shaft
  for (let x = -F + 22; x < F - 4; x += 22) if (Math.abs(x) > H + 4) mk("path", { d: seg(P(x, -F + 3, 0), P(x, F - 3, 0)), class: "lo" }, g);
  mk("path", { d: poly(rrect(-H, -H, H, H, 2, 4).map((q) => P(q.u, q.v, 0))), class: "nf" }, g);
  for (const [x, y] of [[-H, H], [H, H], [H, -H]]) mk("path", { d: seg(P(x, y, 0), P(x, y, -T)), class: "dash" }, g);
  const lid = mk("path", { class: "sil hi" }, g), lcr = mk("path", { class: "nf lo" }, g), ring = mk("path", { class: "nf" }, g);

  const th = spring(REST);
  let last = NaN;
  function draw() {
    if (th.x === last) return;
    last = th.x;
    const a = rad(th.x), V = [0, Math.cos(a), Math.sin(a)], W = [0, -Math.sin(a), Math.cos(a)];
    const c = add(add([0, -H, 0], V, H), W, 1.5);
    const s = slab(c, [1, 0, 0], V, W, H - 1, H - 1, 3, 2);
    lid.setAttribute("d", s.sil); lcr.setAttribute("d", s.cr);
    const k = add(add([0, -H, 0], V, 2 * H - 7), W, 3.2);
    ring.setAttribute("d", poly(rrect(-4, -2.4, 4, 2.4, 2.4, 4).map((q) => P(...add(add(k, [1, 0, 0], q.u), V, q.v)))));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  function aim(p) {
    let d = Infinity;
    if (p) { const [x, y] = unproj(C, p[0], p[1], 0); d = Math.hypot(x, y); }
    const on = d < 110;
    th.t = on ? clamp(1 - d / 110, 0.15, 1) * 105 * reach : REST;
    read.textContent = on ? "open " + Math.round(th.t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "trapdoor",
  means: "A trap in a stage floor: its lid swings open on the far hinge as the pointer comes near, wider the closer it is.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.85, 1],
  tour: [[200, 230], [200, 170], [120, 170], null],
  mount,
});

filmcanister.code:
/**
 * Film canister: a squat cylinder with a snap-on lid. The pointer pries the
 * lid up and tilts it back, and the spool of film rises with it out of the
 * body. At rest the lid sits a little ajar, bright. The slider is the reach.
 */
const { Cam, fit, hull, poly, proj, clamp, lerp, spring, stepS, mk, pointer, register, disposer } = HL;

const R = 22, H = 30, REST = 0.18;
const rotY = ([x, y, z], [px, py, pz], a) => { const c = Math.cos(a), s = Math.sin(a), dx = x - px, dz = z - pz; return [px + dx * c + dz * s, y, pz - dx * s + dz * c]; };
const ring = (cx, cy, cz, r, f = (p) => p, n = 40) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * 2 * Math.PI; o.push(f([cx + r * Math.cos(a), cy + r * Math.sin(a), cz])); } return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R - 10, -R, H + 46], [R + 6, R, H + 46]], 200, 156);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const cyl = (r, z0, z1, f) => hull(ring(0, 0, z0, r, f).map((p) => P(...p)).concat(ring(0, 0, z1, r, f).map((p) => P(...p))));
  const spool = mk("path", { class: "sil" }, g), spoolTop = mk("path", { class: "nf lo" }, g), core = mk("path", { class: "nf lo" }, g);
  const body = mk("path", { class: "sil" }, g), mouth = mk("path", { class: "nf lo" }, g);
  body.setAttribute("d", poly(cyl(R, 0, H)));
  mouth.setAttribute("d", poly(ring(0, 0, H, R - 1.4).map((p) => P(...p))));
  const lid = mk("path", { class: "sil hi" }, g), lidTop = mk("path", { class: "nf lo" }, g), nub = mk("path", { class: "nf" }, g);

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const lift = t * 32, a = -t * 0.55, pv = [-R, 0, H + lift];
    const f = (p) => rotY([p[0], p[1], p[2] + lift], pv, a);
    spool.setAttribute("d", poly(cyl(R - 3, H - 26 + 2, H + 2, f)));
    spoolTop.setAttribute("d", poly(ring(0, 0, H + 2, R - 4.5, f).map((p) => P(...p))));
    core.setAttribute("d", poly(ring(0, 0, H + 2, 3.5, f, 20).map((p) => P(...p))));
    lid.setAttribute("d", poly(cyl(R + 1.2, H + 2, H + 9, f)));
    lidTop.setAttribute("d", poly(ring(0, 0, H + 9, R - 0.4, f).map((p) => P(...p))));
    nub.setAttribute("d", poly(hull(ring(0, 0, H + 9, 4, f, 20).concat(ring(0, 0, H + 12, 4, f, 20)).map((p) => P(...p)))));
  }
  const sp = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, {
    move: ([sx]) => { const t = reach * lerp(0.6, 1, clamp((sx - 120) / 160, 0, 1)); sp.t = t; read.textContent = "open " + Math.round(t * 100); B.wake(); },
    leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "filmcanister",
  means: "A film canister: the pointer pries the lid up and back, and the spool of film rises out with it.",
  rules: [3, 5, 6, 8],
  range: [0.5, 0.75, 1],
