    for (const q of rrect(x0, y0, x1, y1, r, 4)) pts.push([q.u, q.v, z0], [q.u, q.v, z1]);
    lines.push(closed(rrect(x0 + b, y0 + b, x1 - b, y1 - b, Math.max(r - b, 0.4), 4).map((q) => [q.u, q.v, z1])));
