      const x = x0 + ((x1 - x0) * i) / n, y = y0 + ((y1 - y0) * i) / n;
      lines.push([[x, y1, z0 + 2], [x, y1, z1 - 2]], [[x1, y, z0 + 2], [x1, y, z1 - 2]]);
