    const [cx, cy, R0, z0, R1v, z1] = a, R1 = k === "cyl" ? R0 : R1v, Z1 = k === "cyl" ? R1v : z1;
    pts.push(...ring(R0, cx, cy, z0, 32), ...ring(R1, cx, cy, Z1, 32));
