    const [x0, x1, yc, R, z0, H, n] = a, at = (x, t) => [x, yc + R * Math.cos(t), z0 + H * Math.sin(t)];
    const hoop = (x) => Array.from({ length: 17 }, (_, i) => at(x, (i / 16) * Math.PI));
    pts.push(...hoop(x0), ...hoop(x1));
