cockpitswitch.code:
/**
 * Throttle: a throttle quadrant, a low housing with two slots and twin levers
 * joined by one crossbar handle. The pointer's place along the quadrant is the
 * power setting: the levers tilt on a spring to follow it, from idle at the
 * back to full at the front. At rest they sit just past idle, handle bright.
 * The slider is how far the levers swing.
 *
 * The pattern: a continuous tilt on one spring; the hit is on the fixed plane at the handle's height.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 40, PZ = 6, YS = [-7, 7], REST = -0.3, MAX = 0.62;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-28, -14, 0], [28, 14, 0], [-28, 14, 0], [28, -14, 0], [-28, 0, PZ + L + 4], [28, 0, PZ + L + 4], [0, -16, PZ + L + 4], [0, 16, PZ + L + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const ts = (s, ring, inner, z0, z1, T) => {
    const pts = (r, z) => r.map((q) => P(...T([q.u, q.v, z])));
    put(s, { sil: poly(hull(pts(ring, z0).concat(pts(ring, z1)))), crease: inner ? poly(pts(inner, z1)) : "" });
  };
  put(solid(g), prism(P, front, ...rings(-28, -14, 28, 14, 5, 1.6), 0, 12));
  for (const y of YS) mk("path", { class: "nf lo", d: poly(rings(-20, y - 1.2, 20, y + 1.2, 1.2, 0.4)[0].map((q) => P(q.u, q.v, 12))) }, g);
  const levers = YS.map(() => solid(g));
  const handle = solid(g);
  const [sr] = rings(-1.6, -1.6, 1.6, 1.6, 0.8, 0.4);
  const [hr, hi] = rings(-4, -16, 4, 16, 3, 1.2);
  const sp = spring(REST);
  let drawn = NaN, over = null;

  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const c = Math.cos(sp.x), s = Math.sin(sp.x);
    const T = (y0) => ([u, v, w]) => [w * s + u * c, y0 + v, PZ + w * c - u * s];
    levers.forEach((lv, k) => ts(lv, sr, null, 0, L, T(YS[k])));
    ts(handle, hr, hi, L - 3, L + 4, T(0));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    sp.t = over == null ? REST : clamp(over / 26, -1, 1) * MAX * value;
    handle.sil.classList.toggle("hi", true);
    read.textContent = over == null ? "rest" : Math.round(((clamp(over / 26, -1, 1) + 1) / 2) * 100) + "%";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], PZ + L);
      over = Math.abs(x) < 70 && Math.abs(y) < 50 ? x : null;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "cockpitswitch",
  means: "A throttle quadrant with twin levers: the pointer's place along it sets the power, and the levers tilt to follow.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[150, 75], [233, 114], [265, 130], null],
  mount,
});

embroideryhoop.code:
/**
 * Embroidery hoop: a round hoop with its fabric drawn taut, a little flower
 * stitched in the middle, and the brass screw clamp on its rim. The pointer
 * picks the hoop up: it tilts on a spring about its far edge, clamp rising,
 * and the rim takes the bright. At rest it lies almost flat, screw bright.
 * The slider is how far it tilts.
 *
 * The pattern: a tilt on one spring; the hit is on the ground plane.
 */
const {
  Cam, circ, fit, flatDot, hull, place, poly, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 42, H = 6, REST = 0.62, MAX = 0.98;
const STITCH = [[0, 0, "dot m"], [7, 0, "dot off"], [-7, 0, "dot off"], [0, 7, "dot off"], [0, -7, "dot off"], [-12, 12, "dot off"]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.4);
  const ext = [];
  for (let k = 0; k < 12; k++) { const t = (k / 12) * Math.PI * 2; ext.push([R * Math.cos(t), R * Math.sin(t), 0]); }
  const xm = 2 * R + 12;
  ext.push([R - xm * Math.cos(MAX * 1.4), 0, xm * Math.sin(MAX * 1.4) + 8], [R - xm * Math.cos(REST), 0, xm * Math.sin(REST) + 8]);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const ts = (s, ring, inner, z0, z1, T) => {
    const pts = (r, z) => r.map((q) => P(...T([q.u, q.v, z])));
    put(s, { sil: poly(hull(pts(ring, z0).concat(pts(ring, z1)))), crease: inner ? poly(pts(inner, z1)) : "" });
  };
  const hoop = solid(g), cloth = mk("path", { class: "nf lo" }, g);
  const dots = STITCH.map(([, , cls]) => flatDot(g, C, 1.6, cls));
  const lugs = [solid(g), solid(g)], screw = solid(g), head = solid(g);
  const [lr, li] = rings(-4, -2.4, 4, 2.4, 1, 0.5);
  const sp = spring(REST);
  let drawn = NaN, on = false;

  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const c = Math.cos(sp.x), s = Math.sin(sp.x);
    const W = ([x, y, z]) => [R + (x - R) * c + z * s, y, -(x - R) * s + z * c];
    ts(hoop, circ(R, 64), circ(R - 2, 64), 0, H, ([u, v, w]) => W([u, v, w]));
    cloth.setAttribute("d", poly(circ(R - 3.5, 64).map((q) => P(...W([q.u, q.v, H - 2])))));
    STITCH.forEach(([x, y], k) => place(dots[k], P(...W([x, y, H - 2]))));
    [-4, 4].forEach((y, k) => ts(lugs[k], lr, li, 0, 9, ([u, v, w]) => W([-R - 4 + u, y + v, w])));
    ts(screw, circ(1.8, 16), null, -9, 7, ([u, v, w]) => W([-R - 5 + u, w, 5 + v]));
    ts(head, circ(3.6, 20), circ(2.6, 20), 7, 10, ([u, v, w]) => W([-R - 5 + u, w, 5 + v]));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    sp.t = on ? MAX * value : REST;
    head.sil.classList.toggle("hi", !on);
    hoop.sil.classList.toggle("hi", on);
    read.textContent = on ? "lift" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); on = Math.hypot(x, y) < R + 30; retarget(); },
    leave: () => { on = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { value = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "embroideryhoop",
  means: "An embroidery hoop with a stitched flower: the pointer tilts it up off the table, screw clamp rising, and the rim lights.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[200, 242], [140, 195], [265, 255], null],
  mount,
});

yarnswift.code:
/**
 * Yarn swift: an umbrella swift clamped to a table, its slats hinged at the
 * top hub round a pole, a skein of yarn stretched round their tips. The
 * pointer near it opens the umbrella and turns it to face the pointer; away,
 * it folds back to half open. The skein is bright. The slider is how wide it
 * opens.
 *
 * The pattern: a continuous aim on two springs, hit on the ground plane.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, poly, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, L = 48, TOP = 78, wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wide = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-L, -L, TOP - 10], [L, L, TOP - 10], [L, -L, TOP - 10], [-L, L, TOP - 10], [0, 0, 0], [0, 0, TOP + 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-12, -9, 12, 9, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, 0, 8));
  put(solid(g), prism(P, front, circ(2.4, 20), null, 8, TOP));
  const back = mk("path", { class: "nf sil" }, g);
  put(solid(g), prism(P, front, circ(4, 24), null, TOP - 2, TOP + 4));
  const skein = mk("path", { class: "nf sil" }, g);
  const fore = mk("path", { class: "nf sil" }, g);
  skein.classList.add("hi");
  const op = spring(0.7), sp = spring(0.3);
  let drawn = "";
  function draw() {
    const key = op.x.toFixed(4) + sp.x.toFixed(4);
    if (key === drawn) return;
    drawn = key;
    const th = (12 + op.x * 76 * wide) * Math.PI / 180, hub = P(0, 0, TOP);
    let bk = "", fr = "";
    const tips = [], loop = [];
    for (let k = 0; k < N; k++) {
      const f = sp.x + (k / N) * Math.PI * 2, c = Math.cos(f), s = Math.sin(f);
      const r = L * Math.sin(th), z = TOP - L * Math.cos(th);
      const tip = P(r * c, r * s, z), mid = P(r * 0.5 * c, r * 0.5 * s, z + (TOP - z) * 0.5);
      const sl = P(0, 0, TOP - 26), line = seg(hub, tip) + seg(sl, mid);
      if (c + s > 0) fr += line; else bk += line;
      tips.push([r * c, r * s, z]);
    }
    for (let i = 0; i <= 36; i++) {
      const f = sp.x + (i / 36) * Math.PI * 2, r = L * Math.sin(th) * 0.92, z = TOP - L * Math.cos(th) + 2;
      loop.push(P(r * Math.cos(f), r * Math.sin(f), z));
    }
    back.setAttribute("d", bk);
    fore.setAttribute("d", fr);
    skein.setAttribute("d", poly(loop) + poly(loop.map(([x, y]) => [x, y + 5])));
  }
  const B = register(stage, (dt) => { const a = stepS(op, dt), b = stepS(sp, dt); draw(); return a || b; });
  bag.add(B.unregister);
  function set(p) {
    if (!p) { op.t = 0.7; read.textContent = "rest"; }
    else {
      const [x, y] = unproj(C, p[0], p[1], TOP - 20), r = Math.hypot(x, y);
      op.t = r < L * 1.6 ? 1 : 0.7;
      if (r > 4) sp.t = sp.t + wrap(Math.atan2(y, x) - sp.t);
      read.textContent = op.t === 1 ? "open" : "rest";
    }
    B.wake();
  }
  draw();
  read.textContent = "rest";
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wide = v; drawn = ""; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "yarnswift",
  means: "An umbrella yarn swift: near the pointer its slats open wide and turn to it, the skein stretching round them.",
  rules: [1, 3, 4, 5],
  range: [0.4, 0.8, 1],
  tour: [[254, 173], [272, 160], [150, 175], null],
  mount,
});

loupe.code:
/**
 * Jeweller loupe: a folding pocket loupe, a rounded case with a pivot pin
 * at one end and a glass in its ring swinging out of it. The pointer near it
 * swings the glass out towards the pointer; away, the glass rests half out
 * of its case. The glass ring is bright. The slider is how far it swings.
 *
 * The pattern: a continuous aim on one spring, hit on the ground plane.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, clamp, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const R = 17, D = 24, REST = 1.05;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 4.1);
  fit(C, [[-D - R, -D - R, 0], [D + R + 20, D + R, 0], [D + R + 20, -D - R, 0], [-D - R, D + R, 0], [0, 0, 14]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-14, -R - 3, D + R + 4, R + 3, R + 3, 2);
  put(solid(g), prism(P, front, cr, ci, 0, 7));
  const well = mk("path", { class: "nf lo" }, g);
  well.setAttribute("d", "");
  const lens = solid(g), glass = mk("path", { class: "nf lo" }, lens.g);
  put(solid(g), prism(P, front, disc(0, 0, 3.2, 18), null, 7, 13));
  place(flatDot(g, C, 1.3, "dot m"), P(0, 0, 13));
  lens.sil.classList.add("hi");
  const sw = spring(REST, { k: 90, c: 16 });
  let drawn = NaN;
  function draw() {
    if (Math.abs(sw.x - drawn) < 1e-4) return;
    drawn = sw.x;
    const a = sw.x, x = D * Math.cos(a), y = D * Math.sin(a);
    put(lens, prism(P, front, disc(x, y, R), disc(x, y, R - 3.5), 7, 11));
    const pts = disc(x, y, R - 6, 40).map((q) => P(q.u, q.v, 11));
    glass.setAttribute("d", "M" + pts.map((p) => p.join(",")).join("L") + "Z");
  }
  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(); return m; });
  bag.add(B.unregister);
  function set(p) {
    let t = REST, lab = "rest";
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 7), r = Math.hypot(x, y);
      if (r < 75) { t = clamp(Math.atan2(y, x), -0.4, 0.4 + 2.8 * reach); lab = Math.round(t * 57.3) + "°"; }
    }
    sw.t = t;
    read.textContent = lab;
    B.wake();
  }
  draw();
  read.textContent = "rest";
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "loupe",
  means: "A folding jeweller's loupe: the glass swings out of its case on the pivot pin, turning to follow the pointer.",
  rules: [1, 3, 4, 5],
  range: [0.4, 1, 1],
  tour: [[41, 140], [171, 151], [260, 120], null],
  mount,
});

cardcatalog.code:
/**
 * Card catalogue: a library cabinet of six drawers, two across and three
 * high, each with a label plate. The pointer picks a drawer on the cabinet's
 * face and that drawer slides out, long, showing its sides and the cards
 * standing in it; the rest slide home. At rest one drawer stands half open,
 * bright. The slider is how far the drawer comes out.
 */
const {
  Cam, fit, prism, proj, rings, seg, clamp, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const X = 14, Y = 22, H = 60, OUT = 30, FAV = 2;
const REST = [2, 3.5, 12, 1.5, 3, 2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.8);
  let out = OUT * value;
  fit(C, [[-X, -Y, H + 3], [X, Y, 0], [X + OUT * 1.2, -Y, H], [X + OUT * 1.2, Y, 0], [-X, Y, 0]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-X, -Y, X, Y, 1.5, 1);
  put(solid(g), prism(P, front, cr, ci, 0, H));
  const [tr, ti] = rings(-X - 2, -Y - 2, X + 2, Y + 2, 1.5, 1.2);
  put(solid(g), prism(P, front, tr, ti, H, H + 3));
  const dr = [];
  for (const row of [0, 1, 2]) for (const col of [0, 1]) {
    const i = row * 2 + col, y0 = col ? 1.5 : -Y + 2, y1 = col ? Y - 2 : -1.5, z0 = 4 + row * 18, z1 = z0 + 15;
    dr.push({ i, row, col, y0, y1, z0, z1, tw: tween(REST[i]), drawn: NaN });
  }
  // lower rows first, so a drawer out from above covers the ones beneath it
  for (const d of dr) {
    d.g = mk("g", {}, g);
    d.s = solid(d.g);
    d.lab = mk("path", { class: "nf sil", d: "" }, d.g);
  }
  function draw(d, now) {
    const o = tval(d.tw, now);
    if (Math.abs(o - d.drawn) < 1e-3) return;
    d.drawn = o;
    const [r, inn] = rings(X - 0.5, d.y0, X + o, d.y1, 1, 0.8);
    put(d.s, prism(P, front, r, inn, d.z0, d.z1));
    const fx = X + o, ym = (d.y0 + d.y1) / 2, zm = (d.z0 + d.z1) / 2;
    const cards = [];
    if (o > 6) for (let k = 1; k * 4 < o - 2; k++) cards.push(seg(P(fx - k * 4, d.y0 + 2, d.z1 + 2), P(fx - k * 4, d.y1 - 2, d.z1 + 2)));
    d.lab.setAttribute("d", seg(P(fx + 0.1, ym - 4, zm + 2), P(fx + 0.1, ym + 4, zm + 2)) + seg(P(fx + 0.1, ym - 2, zm - 3), P(fx + 0.1, ym + 2, zm - 3)) + cards.join(""));
  }
  const B = register(stage, (dt, now) => {
    let m = false;
    for (const d of dr) { draw(d, now); if (!tdone(d.tw, now)) m = true; }
    return m;
  });
  bag.add(B.unregister);
  g.append(...[...dr].sort((a, b) => a.row - b.row || a.col - b.col).map((d) => d.g));

  const o = P(X, 0, 0), ey = P(X, 1, 0), ez = P(X, 0, 1);
  const ay = [ey[0] - o[0], ey[1] - o[1]], az = [ez[0] - o[0], ez[1] - o[1]], det = ay[0] * az[1] - ay[1] * az[0];
  let pick = null;
  function retarget() {
    const now = performance.now();
    for (const d of dr) {
      const t = pick === null ? REST[d.i] : d === pick ? out : 1.5;
      tset(d.tw, t, now, pick ? Math.abs(d.i - pick.i) * 40 : 0);
      d.s.sil.classList.toggle("hi", pick ? d === pick : d.i === FAV);
    }
    read.textContent = pick ? "drawer " + "ABCDEF"[pick.i] : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const sx = p[0] - o[0], sy = p[1] - o[1];
      const y = (sx * az[1] - sy * az[0]) / det, z = (ay[0] * sy - ay[1] * sx) / det;
      pick = Math.abs(y) < Y + 4 && z > 0 && z < H + 6 ? dr[clamp(Math.floor((z - 4) / 18), 0, 2) * 2 + (y > 0 ? 1 : 0)] : null;
      retarget();
    },
    leave: () => { pick = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { out = OUT * v; retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "cardcatalog",
  means: "A card catalogue of six drawers: the drawer under the pointer slides out long to show its cards, and it is bright.",
  rules: [1, 2, 3, 5],
  range: [0.5, 1, 1.2],
  tour: [[214, 108], [170, 219], [190, 150], null],
  mount,
});

bookpress.code:
/**
 * Book press: a heavy base, two posts and a crossbar, a screw through the bar
 * with a long tommy-bar handle, and a platen over a book. The pointer works
 * it: over the press the handle turns and the platen screws down onto the
 * book; off it the platen rises. The handle is bright.
 */
const {
  Cam, circ, fit, prism, proj, rings, seg, rad, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const W = 30, D = 18, TOP = 70, BOOK = 12, REST = 0.25;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  let depth = value;
  fit(C, [[-W - 4, -D, 0], [W + 4, D, 0], [-24, -24, TOP + 12], [24, 24, TOP + 12], [0, 0, TOP + 14]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-W - 4, -D, W + 4, D, 2, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 6));
  const back = mk("g", {}, g);
  put(solid(back), prism(P, front, ...rings(-W, -3, -W + 6, 3, 1, 0.6), 6, TOP));
  put(solid(g), prism(P, front, ...rings(-16, -13, 16, 13, 1.5, 1), 6, 6 + BOOK));
  const plat = solid(g), screw = solid(g);
  put(solid(g), prism(P, front, ...rings(W - 6, -3, W, 3, 1, 0.6), 6, TOP));
  put(solid(g), prism(P, front, ...rings(-W - 1, -5, W + 1, 5, 1.5, 1), TOP, TOP + 7));
  const hub = solid(g);
  put(hub, prism(P, front, circ(4, 24), null, TOP + 7, TOP + 11));
  const bar = mk("path", { class: "nf sil", d: "" }, g);
  const sp = spring(REST, { k: 90, c: 18 });
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const t = sp.x, zp = 6 + BOOK + 2 + (1 - t) * 30, a = t * Math.PI * 1.5;
    put(plat, prism(P, front, ...rings(-20, -15, 20, 15, 1.5, 1), zp, zp + 5));
    put(screw, prism(P, front, circ(2.4, 16), null, zp + 5, TOP));
    const c = Math.cos(a) * 24, s = Math.sin(a) * 24;
    bar.setAttribute("d", seg(P(-c, -s, TOP + 9), P(c, s, TOP + 9)));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  let over = false;
  function retarget() {
    sp.t = over ? depth : REST;
    bar.classList.toggle("hi", true);
    read.textContent = over ? Math.round(depth * 100) + "%" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let hit = false;
      for (let z = 0; z <= TOP + 12; z += 6) { const [x, y] = unproj(C, p[0], p[1], z); if (Math.abs(x) < W + 6 && Math.abs(y) < D + 6) hit = true; }
      over = hit; retarget();
    },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { depth = Math.min(1, v); retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "bookpress",
  means: "A book press: over it the handle turns and the platen screws down onto the book; off it the platen rises again.",
  rules: [1, 3, 5],
  range: [0.5, 1, 1],
  tour: [[200, 138], [171, 202], [200, 72], null],
  mount,
});

anemometer.code:
/**
 * Anemometer: a mast with a three-cup rotor on top. The pointer is the wind:
 * the rotor turns on its spring so the nearest cup swings round to face it,
 * and that cup is bright. At rest the rotor stands a little turned, one cup
 * bright. The slider is how stiff the rotor's spring is.
 */
const {
  Cam, circ, facing, fit, prism, proj, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 46, R = 30, CR = 7.5, CH = 9, REST = 0.35, FAV = 0;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.0);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([(R + CR) * Math.cos(a), (R + CR) * Math.sin(a), H + CH], [14 * Math.cos(a), 14 * Math.sin(a), 0]); }
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(14, 48), circ(12.6, 48), 0, 3));
  put(solid(g), prism(P, front, circ(2.2, 20), null, 3, H - 2));
  const parts = [];
  for (let i = 0; i < 3; i++) {
    const grp = mk("g", {}, g);
    const arm = mk("path", { class: "nf sil", d: "" }, grp);
    parts.push({ i, grp, arm, cup: solid(grp), off: (i * 2 * Math.PI) / 3 });
  }
  const hub = { grp: mk("g", {}, g) };
  hub.s = solid(hub.grp);
  put(hub.s, prism(P, front, circ(4.5, 28), circ(3.4, 28), H - 2, H + 3));
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const items = [];
    for (const p of parts) {
      const a = sp.x + p.off, cx = R * Math.cos(a), cy = R * Math.sin(a);
      p.arm.setAttribute("d", seg(P(3.5 * Math.cos(a), 3.5 * Math.sin(a), H), P(cx, cy, H)));
      put(p.cup, prism(P, front, disc(cx, cy, CR), disc(cx, cy, CR - 1.4), H - CH / 2, H + CH / 2));
      items.push({ d: cx + cy, grp: p.grp });
    }
    items.push({ d: 0, grp: hub.grp });
    items.sort((a, b) => a.d - b.d);
    for (const it of items) g.append(it.grp);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let on = FAV;
    if (over) {
      const w = Math.atan2(over[1], over[0]);
      let best = 0, bd = Infinity;
      for (const p of parts) { const d = Math.abs(wrap(w - (sp.t + p.off))); if (d < bd) { bd = d; best = p.i; } }
      sp.t = sp.t + wrap(w - (sp.t + parts[best].off));
      on = best;
    } else sp.t = sp.t + wrap(REST - sp.t);
    for (const p of parts) p.cup.sil.classList.toggle("hi", p.i === on);
    read.textContent = over ? "cup " + (on + 1) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], H);
      over = Math.hypot(x, y) > R + 40 || Math.hypot(x, y) < 3 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "anemometer",
  means: "An anemometer's three-cup rotor: the rotor turns so the cup nearest the pointer swings round to it, and that cup is bright.",
  rules: [1, 3, 5],
  range: [0.5, 1, 1.6],
  tour: [[138, 102], [268, 96], [270, 172], null],
  mount,
});

barometer.code:
/**
 * Barometer: a round aneroid dial on its case, a ring of graduation ticks and
 * a long needle. The pointer is the weather: the needle swings on its spring
 * to point at it, clamped to the dial's arc, and the read-out gives the
 * pressure. At rest the needle leans to "fair", bright. The slider is how
 * stiff the needle's spring is.
 */
const {
  Cam, fit, hull, poly, proj, seg, spring, stepS, clamp,
  disposer, mk, pointer, register, solid,
} = HL;

const R = 40, Z0 = 52, D = 9, ARC = 2.2, REST = 0.62, N = 64;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.65);
  const at = (t, r, y) => [r * Math.sin(t), y, Z0 + r * Math.cos(t)];
  const ext = [];
  for (let k = 0; k < 16; k++) { const t = (k / 16) * Math.PI * 2; ext.push(at(t, R + 2, 0), at(t, R + 2, -D)); }
    fit(C, ext, 200, 160);
  const P = proj(C);
  const ring = (r, y) => Array.from({ length: N }, (_, k) => P(...at((k / N) * Math.PI * 2, r, y)));
  const g = mk("g", {}, svg);
  const cs = solid(g);
  cs.sil.setAttribute("d", poly(hull([...ring(R + 2, 0), ...ring(R + 2, -D)])));
  cs.cr.setAttribute("d", poly(ring(R + 2, 0)));
  const ticks = [];
  for (let k = 0; k <= 6; k++) {
    const t = -ARC + (k / 6) * 2 * ARC, L = k % 3 === 0 ? 6 : 3;
    ticks.push(seg(P(...at(t, R - 6, 0)), P(...at(t, R - 6 - L, 0))));
  }
  mk("path", { class: "nf sil", d: ticks.join("") }, g);
  const nd = mk("path", { class: "sil", d: "" }, g);
  const cap = mk("path", { class: "sil", d: "" }, g);
  const capPts = Array.from({ length: 20 }, (_, k) => { const a = (k / 20) * Math.PI * 2; return P(...at(a, 3.4, 0.6)); });
  cap.setAttribute("d", poly(capPts));
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const t = sp.x, n = t + Math.PI / 2, w = 8;
    const pts = [at(t, R - 7, 0.4), [w * Math.sin(n), 0.4, Z0 + w * Math.cos(n)], at(t + Math.PI, 18, 0.4), [-w * Math.sin(n), 0.4, Z0 - w * Math.cos(n)]];
    nd.setAttribute("d", poly(pts.map((q) => P(...q))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const o = P(0, 0, Z0), ex = P(1, 0, Z0), ez = P(0, 0, Z0 + 1);
  const ax = [ex[0] - o[0], ex[1] - o[1]], az = [ez[0] - o[0], ez[1] - o[1]], det = ax[0] * az[1] - ax[1] * az[0];

  let over = false;
  function retarget(p) {
    if (p) {
      const sx = p[0] - o[0], sy = p[1] - o[1];
      const dx = (sx * az[1] - sy * az[0]) / det, dz = (ax[0] * sy - ax[1] * sx) / det;
      over = Math.hypot(dx, dz) < R + 30 && Math.hypot(dx, dz) > 2;
      if (over) sp.t = clamp(Math.atan2(dx, dz), -ARC, ARC);
    } else over = false;
    if (!over) sp.t = REST;
    nd.classList.toggle("hi", true);
    read.textContent = over ? String(Math.round(1000 + (sp.t / ARC) * 40)) : "rest";
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => retarget(p), leave: () => retarget(null) }));
  bag.add(() => svg.replaceChildren());
  retarget(null);
  return {
    set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "barometer",
  means: "An aneroid barometer: its long needle swings to point at the pointer, clamped to the dial, and the read-out gives the pressure.",
  rules: [1, 3, 5],
  range: [0.5, 1, 1.6],
  tour: [[139, 166], [248, 128], [200, 110], null],
  mount,
});

stevenson.code:
/**
 * Stevenson screen: the louvred white box that shelters thermometers, on four
 * legs under a flat roof. The pointer opens it: over the screen the louvred
 * door swings wide on its hinge to show the thermometer inside; off it the
 * door falls back ajar. The door is bright. The slider is how far it opens.
 */
const {
  Cam, fit, poly, prism, proj, rings, seg, unproj, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const X = 20, Y = 16, Z0 = 34, Z1 = 74, HY = -14, L = 28, DZ0 = 37, DZ1 = 71, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  let open = 105 * value;
  fit(C, [[-X - 2, -Y - 2, Z1 + 5], [X + 2, Y + 2, 0], [X + L, HY, DZ0], [-X, Y, 0], [X, -Y, Z1 + 5]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const legs = [];
  for (const [x, y] of [[-X + 3, -Y + 3], [X - 3, -Y + 3], [-X + 3, Y - 3], [X - 3, Y - 3]]) legs.push(seg(P(x, y, 0), P(x, y, Z0)));
  mk("path", { class: "nf sil", d: legs.join("") }, g);
  const [br, bi] = rings(-X, -Y, X, Y, 1.5, 1);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  const [rr, ri] = rings(-X - 3, -Y - 3, X + 3, Y + 3, 1.5, 1.2);
  put(solid(g), prism(P, front, rr, ri, Z1, Z1 + 4));
  // the opening and the thermometer inside it, on the face the door covers
  const fx = X + 0.05, inner = [];
  inner.push(poly([P(fx, HY, DZ0), P(fx, HY + L, DZ0), P(fx, HY + L, DZ1), P(fx, HY, DZ1)]));
  inner.push(seg(P(fx, -1, DZ0 + 8), P(fx, -1, DZ1 - 6)), seg(P(fx, 1, DZ0 + 8), P(fx, 1, DZ1 - 6)));
  mk("path", { class: "nf sil", d: inner.join("") }, g);
  const door = solid(g);
  const sp = spring(REST, { k: 120, c: 20 });
  let drawn = NaN;

  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-3) return;
    drawn = sp.x;
    const a = rad(sp.x), fy = HY + L * Math.cos(a), fxx = X + L * Math.sin(a);
    const at = (t, z) => P(lerp(X, fxx, t), lerp(HY, fy, t), z);
    door.sil.setAttribute("d", poly([at(0, DZ0), at(1, DZ0), at(1, DZ1), at(0, DZ1)]));
    const sl = [];
    for (let k = 1; k < 9; k++) { const z = DZ0 + (k / 9) * (DZ1 - DZ0); sl.push(seg(at(0.1, z), at(0.9, z - 2))); }
    door.cr.setAttribute("d", sl.join(""));
  }
  const lerp = (a, b, t) => a + (b - a) * t;

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = false;
  function retarget() {
    sp.t = over ? open : REST;
    door.sil.classList.toggle("hi", true);
    read.textContent = over ? Math.round(open) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let hit = false;
      for (let z = 0; z <= Z1 + 4; z += 6) { const [x, y] = unproj(C, p[0], p[1], z); if (Math.abs(x) < X + 10 && Math.abs(y) < Y + 10) hit = true; }
      over = hit; retarget();
    },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { open = clamp(105 * v, 40, 120); retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "stevenson",
  means: "A Stevenson screen on its legs: over it the louvred door swings wide to show the thermometer inside, off it the door falls back ajar.",
  rules: [1, 3, 5],
  range: [0.5, 1, 1.15],
  tour: [[213, 133], [169, 50], [250, 150], null],
  mount,
});

barberpole.code:
/**
 * Barber pole: a striped pole on a base under a cap. The pointer spins the stripes.
 */
const {
  Cam, circ, rrect, fit, facing, hull, poly, open, prism, proj, ringAt, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const tr = (ring, a, px, py, dx, dy) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: (q.u - px) * c - (q.v - py) * s + px + dx, v: (q.u - px) * s + (q.v - py) * c + py + dy, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const box = (x0, y0, x1, y1, r) => rrect(x0, y0, x1, y1, r, 6);

const S = 3.2, REST = 0, ON = "spin", OFF = "rest", HW = 120, HH = 240, CTR = [0, 0, 44];
const BOX = [[-21, -21, 0], [21, 21, 0], [21, -21, 0], [-21, 21, 0], [0, 0, 92]];
const ball = [];
for (let i = 0; i <= 6; i++) { const t = (i / 6) * Math.PI; ball.push([disc(0, 0, 6 * Math.sin(t) + 0.01, 20), 80 + 6 - 6 * Math.cos(t)]); }
const PARTS = [
  { ring: disc(0, 0, 21), inner: disc(0, 0, 17), z0: 0, z1: 8 },
  { ring: disc(0, 0, 13), inner: disc(0, 0, 12.9), z0: 8, z1: 74 },
  { ring: disc(0, 0, 18), inner: disc(0, 0, 14), z0: 74, z1: 80 },
  { layers: ball, hi: 1 },
];
const pose = () => ({ a: 0, px: 0, py: 0, dx: 0, dy: 0, dz: 0 });
let stripes = null;
function deco(P, front, g, t) {
  if (!stripes) stripes = mk("path", { class: "nf" }, g);
  const ph = t * Math.PI / 3, segs = [];
  for (let k = 0; k < 6; k++) {
    const b = Math.floor(k / 2) * (2 * Math.PI / 3) + (k % 2) * 0.55 + ph;
    let run = [];
    for (let z = 9; z <= 73; z += 1.5) {
      const th = b + z * 0.1, c = Math.cos(th), s = Math.sin(th);
      if (front({ u: 13 * c, v: 13 * s, nu: c, nv: s })) run.push(P(13 * c, 13 * s, z));
      else { if (run.length > 1) segs.push(open(run)); run = []; }
    }
    if (run.length > 1) segs.push(open(run));
  }
  stripes.setAttribute("d", segs.join(" "));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value / 100;
  const C = Cam(45, 0.5, S);
  fit(C, BOX, 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const parts = PARTS.map((p) => ({ ...p, s: solid(g) }));
  const sp = spring(REST, { k: 90, c: 16 });
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const q = pose(t * amp);
    for (const p of parts) {
      const m = p.mv ? q : { a: 0, px: 0, py: 0, dx: 0, dy: 0, dz: 0, sh: 0 };
      const T = (r, z) => tr(r, m.a, m.px, m.py, m.dx + (m.sh || 0) * (z - (m.pz || 0)), m.dy);
      if (p.layers) {
        const pts = [];
        for (const [r, z] of p.layers) pts.push(...ringAt(P, T(r, z), z + m.dz));
        p.s.sil.setAttribute("d", poly(hull(pts)));
        p.s.cr.setAttribute("d", p.lip ? poly(ringAt(P, T(p.lip[0], p.lip[1]), p.lip[1] + m.dz)) : "");
      } else put(p.s, prism(P, front, T(p.ring, p.z0), T(p.inner, p.z0), p.z0 + m.dz, p.z1 + m.dz));
      p.s.sil.classList.toggle("hi", !!p.hi);
    }
    if (typeof deco === "function") deco(P, front, g, t * amp);
  }
  const B = register(stage, (dt) => { const mv = stepS(sp, dt); draw(sp.x); return mv; });
  bag.add(B.unregister);
  const ctr = P(...CTR);
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    sp.t = a ? 1 : REST;
    read.textContent = a ? ON : OFF;
    B.wake();
  }
  draw(REST);
  setActive(false);
  const hit = ([sx, sy]) => Math.abs(sx - ctr[0]) < HW && Math.abs(sy - ctr[1]) < HH;
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v / 100; last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "barberpole",
  means: "A barber pole on its base: point at it and the stripes spin up the pole.",
  rules: [1, 4, 5, 6],
  range: [30, 90, 100],
  tour: [[205,160],[200,100],[195,220],null],
  mount,
});

barberchair.code:
/**
 * Barber chair: a seat on a round pedestal with arms and a footrest, the
 * tall back and headrest hinged at the seat. The pointer's place along the
 * chair reclines the back; at rest it leans a little and is bright. The
 * slider is the deepest recline.
 */
const { Cam, fit, hull, poly, proj, rrect, rings, prism, facing, circ, unproj, clamp, rad, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-70, -6, 40], [70, 40, 0], [-6, 40, 105], [-6, -6, 105], [40, 40, 0], [-40, 40, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(18, 17, 24), disc(18, 17, 22), 0, 3));
  put(solid(g), prism(P, front, disc(18, 17, 8), disc(18, 17, 6.5), 3, 26));
  const back = mk("path", { class: "sil" }, g), head = mk("path", { class: "nf" }, g);
  const [sr, si] = rings(-2, 0, 40, 34, 6, 1.6);
  put(solid(g), prism(P, front, sr, si, 26, 36));
  const [ar, ai] = rings(6, 34, 38, 39, 2.5, 1);
  put(solid(g), prism(P, front, ar, ai, 46, 50));
  mk("path", { d: poly(hull([P(10, 36, 36), P(12, 36, 36), P(10, 36, 46), P(12, 36, 46)])), class: "lo" }, g);
