  mk("path", { d: poly(hull([P(40, 15, 28), P(40, 19, 28), P(48, 15, 10), P(48, 19, 10)])), class: "lo" }, g);
  const bring = rrect(-7, 1, 0, 33, 4, 4), hring = rrect(-6, 8, 0, 26, 4, 4);
  const tilt = (ring, t, w0, w1) => {
    const c = Math.cos(rad(t)), s = Math.sin(rad(t)), pts = [];
