hourglass.code:
/**
 * Hourglass: a sand glass on a pivot between two uprights. The pointer tips
 * it: across the frame the glass swings round its pivot on a spring, from a
 * slight lean at rest towards lying on its side. The glass stays bright. The
 * slider is how far it may tip.
 */
const {
  Cam, circ, fit, prism, proj, rings, rrect, facing, hull, poly, open, clamp,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const ZC = 38, H = 22, W = 15, REST = 0.22;
const PLATE = rrect(-W, -W, W, W, 4, 4), PIN = rrect(-W + 1.6, -W + 1.6, W - 1.6, W - 1.6, 2.6, 4);
const VIEW = [0.61, 0.61, 0.5];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.6);
  const R = 31, ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([R * Math.cos(a), -24, ZC + R * Math.sin(a)], [R * Math.cos(a), 24, ZC + R * Math.sin(a)]); }
  ext.push([-30, -30, 0], [30, 30, 0]);
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-26, -30, 26, 30, 5, 1.6), 0, 3));
  put(solid(g), prism(P, front, ...rings(-3, -26, 3, -21, 1.4, 0.6), 3, ZC + 4));
  const glassG = mk("g", {}, g);
  put(solid(g), prism(P, front, ...rings(-3, 21, 3, 26, 1.4, 0.6), 3, ZC + 4));

  // parts in local coords: list of [ring, z0, z1, crease ring]
  const parts = [];
  const plate = (z0, z1) => ({ rings: [[PLATE, z0], [PLATE, z1]], cap: [PIN, z0, z1], s: solid(glassG) });
  const pillar = (x, y) => ({ rings: [[circ(1.3, 12).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), -H + 3], [circ(1.3, 12).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), H - 3]], s: solid(glassG), c: [x, y] });
  const bulb = (sg) => ({ rings: [[circ(1.6, 16), sg * 1], [circ(10.5, 24), sg * 9], [circ(9, 24), sg * 15.5], [circ(6, 24), sg * (H - 3)]], s: solid(glassG), glass: true });
  const sand = { rings: [[circ(8.6, 24), 9.5], [circ(6, 24), H - 3.2], [circ(1.2, 12), 4.5]], s: solid(glassG) };
  parts.push(plate(-H, -H + 3), pillar(-11, -11), pillar(11, -11), bulb(-1), bulb(1), sand, pillar(-11, 11), pillar(11, 11), plate(H - 3, H));
  for (const p of parts) if (p.glass) p.s.sil.classList.add("hi");

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const c = Math.cos(t), s = Math.sin(t);
    const W3 = (u, v, z) => [u * c + z * s, v, ZC - u * s + z * c];
    const depth = [];
    for (const p of parts) {
      const pts = [];
      for (const [ring, z] of p.rings) for (const q of ring) pts.push(P(...W3(q.u, q.v, z)));
      let cr = "";
      if (p.cap) {
        const [ring, z0, z1] = p.cap, nz = [s, 0, c];
        const dot = nz[0] * VIEW[0] + nz[2] * VIEW[2];
        const z = dot > 0 ? z1 : z0;
        cr = poly(ring.map((q) => P(...W3(q.u, q.v, z))));
      }
      put(p.s, { sil: poly(hull(pts)), crease: cr });
      const zm = (p.rings[0][1] + p.rings[p.rings.length - 1][1]) / 2, cx = p.c ? p.c[0] : 0, cy = p.c ? p.c[1] : 0;
      const w = W3(cx, cy, zm);
      depth.push([w[0] + w[1] + (w[2] - ZC) * 0.8, p]);
    }
    depth.sort((a, b) => a[0] - b[0]);
    for (const [, p] of depth) glassG.appendChild(p.s.g);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function aim(sx) {
    if (sx == null) { sp.t = REST; read.textContent = "rest"; }
    else { sp.t = clamp((sx - 120) / 170, 0, 1) * (Math.PI / 2) * value; read.textContent = Math.round(sp.t * 180 / Math.PI) + "°"; }
    B.wake();
  }
  let cur = null;
  bag.add(pointer(stage, {
    move: (p) => { cur = p[0]; aim(cur); },
    leave: () => { cur = null; aim(null); },
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { value = v; if (cur != null) aim(cur); }, destroy: bag.dispose };
}

hairline({
  name: "hourglass",
  means: "An hourglass on a pivot: the pointer tips it over on its spring, from a slight lean towards lying on its side.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.3],
  tour: [[200, 88], [290, 140], [150, 160], null],
  mount,
});

planisphere.code:
/**
 * Star wheel: a planisphere, a star disc turning in its square holder. The
 * pointer turns the sky: the disc follows the pointer's angle round its pin on
 * a spring, carrying its constellations past the holder's index. At rest the
 * disc sits a little off the hour, its rim bright. The slider is how much of
 * the pointer's turn the disc takes.
 */
const {
  Cam, circ, fit, prism, proj, rings, facing, open, seg, unproj, clamp,
  spring, stepS, disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const R = 44, REST = 0.5;
const STARS = [[30, 0.3], [24, 0.7], [33, 1.0], [18, 1.3], [28, 1.9], [36, 2.3], [22, 2.6], [31, 3.1], [14, 3.5], [27, 3.9], [35, 4.3], [20, 4.8], [30, 5.3], [16, 5.8], [8, 0.9], [9, 4.1]];
const LINES = [[0, 1, 2, 4, 3, 1], [5, 6, 7, 5], [9, 10, 11, 8, 9], [12, 13, 0], [14, 3, 6], [15, 11, 12], [8, 15, 14, 2], [1, 6, 10], [4, 7, 13]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-56, -56, 0], [56, 56, 0], [-56, 56, 0], [56, -56, 0], [0, 0, 8]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, rings(-56, -56, 56, 56, 9, 2)[0], null, 0, 4));
  const disc = solid(g);
  put(disc, prism(P, front, circ(R, 96), null, 4, 6.5));
  disc.sil.classList.add("hi");
  const lines = mk("path", { class: "nf lo", d: "" }, g);
  const ticks = mk("path", { class: "nf lo", d: "" }, g);
  const dots = STARS.map((s, i) => flatDot(g, C, i % 3 ? 1.1 : 1.6, i % 3 ? "dot off" : "dot m"));
  put(solid(g), prism(P, front, circ(2.2, 16), null, 6.5, 9));
  // the index: a fixed tab on the holder pointing at the rim
  const tab = solid(g);
  put(tab, prism(P, front, ...rings(R + 2, -3, R + 9, 3, 1.2, 0.6), 4, 5.5));

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const at = (r, b) => P(r * Math.cos(b + a), r * Math.sin(b + a), 6.5);
    let d = "";
    for (const L of LINES) d += open(L.map((i) => at(STARS[i][0], STARS[i][1])));
    lines.setAttribute("d", d);
    let t = "";
    for (let k = 0; k < 36; k++) { const b = (k / 36) * Math.PI * 2; t += seg(at(R - 2.6, b), at(R - (k % 6 ? 5 : 8), b)); }
    ticks.setAttribute("d", t);
    STARS.forEach((s, i) => place(dots[i], at(s[0], s[1])));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const hour = (a) => { const h = Math.round((((-a / (Math.PI * 2)) * 24) % 24 + 24) % 24); return (h < 10 ? "0" : "") + h + "h"; };
  let over = null;
  function aim() {
    if (!over) { sp.t = REST; read.textContent = "rest"; }
    else {
      let want = REST + Math.atan2(over[1], over[0]) * 1.6 * value;
      sp.t = want;
      read.textContent = hour(want);
    }
    tab.sil.classList.toggle("hi", !!over);
    disc.sil.classList.toggle("hi", !over);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) < 70 && Math.hypot(x, y) > 4 ? [x, y] : null; aim(); },
    leave: () => { over = null; aim(); },
  }));
  bag.add(() => svg.replaceChildren());
  aim();
  return { set: (v) => { value = v; aim(); }, destroy: bag.dispose };
}

hairline({
  name: "planisphere",
  means: "A star wheel in its holder: the disc turns to follow the pointer round its pin, carrying its constellations past the index.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.4],
  tour: [[142, 180], [262, 140], [200, 230], null],
  mount,
});

foghorn.code:
/**
 * Foghorn: a squat plinth and post carrying a long flared horn. The pointer
 * over the figure swings the horn round on its post, mouth to the sea. At rest
 * the horn points down the shore, its mouth rim bright. The slider is the swing.
 */
const { Cam, fit, hull, poly, proj, tset, tval, tdone, tween, disposer, mk, pointer, register } = HL;

const rbox = (x0, y0, z0, x1, y1, z1, r) => { const a = []; for (const [cx, cy, s] of [[x1 - r, y1 - r, 0], [x0 + r, y1 - r, 1], [x0 + r, y0 + r, 2], [x1 - r, y0 + r, 3]]) for (let i = 0; i <= 4; i++) { const t = (s + i / 4) * Math.PI / 2; for (const z of [z0, z1]) a.push([cx + r * Math.cos(t), cy + r * Math.sin(t), z]); } return a; };
const cyl = (cx, cy, r, z0, z1, n = 20) => { const a = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; a.push([cx + r * Math.cos(t), cy + r * Math.sin(t), z0], [cx + r * Math.cos(t), cy + r * Math.sin(t), z1]); } return a; };
const PZ = 46, E = 0.12;
function hornRing(a, s, r, n = 28) {
  const d = [Math.cos(a) * Math.cos(E), Math.sin(a) * Math.cos(E), Math.sin(E)], u = [-Math.sin(a), Math.cos(a), 0], w = [-Math.cos(a) * Math.sin(E), -Math.sin(a) * Math.sin(E), Math.cos(E)], o = [];
  for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI, c = r * Math.cos(t), q = r * Math.sin(t); o.push([d[0] * s + c * u[0] + q * w[0], d[1] * s + c * u[1] + q * w[1], PZ + d[2] * s + c * u[2] + q * w[2]]); }
  return o;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.35);
  const A0 = (-25 * Math.PI) / 180;
  const ext = [...rbox(-22, -22, 0, 22, 22, 10, 6), ...hornRing(A0, 64, 22, 8), ...hornRing(A0 + Math.PI / 180 * 100, 64, 22, 8), ...hornRing(A0, -12, 7, 8)];
  fit(C, ext, 200, 165);
  const P = proj(C), pr = (pts) => poly(hull(pts.map((p) => P(...p))));
  const g = mk("g", {}, svg);
  mk("path", { class: "sil", d: pr(rbox(-22, -22, 0, 22, 22, 10, 6)) }, g);
  mk("path", { class: "nf lo", d: poly(rbox(-20, -20, 10, 20, 20, 10, 5).filter((_, i) => i % 2 === 0).map((p) => P(...p))) }, g);
  mk("path", { class: "sil", d: pr(cyl(0, 0, 6, 10, PZ - 4)) }, g);
  mk("path", { class: "sil", d: pr(cyl(0, 0, 9, PZ - 6, PZ + 2)) }, g);
  const horn = mk("path", { class: "sil" }, g), band = mk("path", { class: "nf lo" }, g), mouth = mk("path", { class: "nf hi" }, g);
  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = A0 + (t * swing * Math.PI) / 180, m = hornRing(a, 64, 22);
    horn.setAttribute("d", poly(hull([...hornRing(a, -12, 7), ...hornRing(a, 22, 9), ...m].map((p) => P(...p)))));
    band.setAttribute("d", poly(hornRing(a, 22, 9).map((p) => P(...p))));
    mouth.setAttribute("d", poly(m.map((p) => P(...p))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const rest = ext.map((p) => P(...p)), xs = rest.map((p) => p[0]), ys = rest.map((p) => p[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  let on = null;
  function set(a) {
    if (a === on) return;
    on = a;
    tset(tw, a ? 1 : 0, performance.now(), 0);
    read.textContent = a ? "sound" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > bx[0] && x < bx[1] && y > bx[2] && y < bx[3]), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "foghorn",
  means: "A foghorn on its post: the pointer swings the flared horn round to face the sea, its mouth rim bright.",
  rules: [1, 3, 5, 6],
  range: [50, 100, 120],
  tour: [[181, 121], [150, 140], [215, 165], null],
  mount,
});

divinghelmet.code:
/**
 * Diving helmet: a round copper helmet with a front porthole, seated on a
 * broad corselet. The pointer over the figure tilts the helmet back on its
 * rear hinge to open it. At rest the front porthole is bright. The slider is
 * how far it tilts.
 */
const { Cam, fit, hull, poly, proj, tset, tval, tdone, tween, disposer, mk, pointer, register } = HL;

const A = (20 * Math.PI) / 180, D = [Math.cos(A), Math.sin(A), 0], U = [-Math.sin(A), Math.cos(A), 0], W = [0, 0, 1];
const R = 24, CZ = 44, HX = [-R * 0.95 * D[0], -R * 0.95 * D[1], 26];
const add = (a, b, s = 1) => [a[0] + b[0] * s, a[1] + b[1] * s, a[2] + b[2] * s];
function ring(c, u, w, r, n = 28) { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push(add(add(c, u, r * Math.cos(t)), w, r * Math.sin(t))); } return o; }
function tilt(p, th) { // rotate about the hinge axis U through HX
  const q = add(p, HX, -1), c = Math.cos(th), s = Math.sin(th);
  const kd = q[0] * U[0] + q[1] * U[1], kx = [U[1] * q[2], -U[0] * q[2], U[0] * q[1] - U[1] * q[0]];
  return add(HX, [q[0] * c + kx[0] * s + U[0] * kd * (1 - c), q[1] * c + kx[1] * s + U[1] * kd * (1 - c), q[2] * c + kx[2] * s]);
}
const sphere = () => { const o = []; for (let i = -3; i <= 4; i++) { const f = (i / 4) * (Math.PI / 2) * 0.92; o.push(...ring([0, 0, CZ + R * Math.sin(f)], [1, 0, 0], [0, 1, 0], R * Math.cos(f), 24)); } return o; };
const neck = () => [...ring([0, 0, 24], [1, 0, 0], [0, 1, 0], 17), ...ring([0, 0, 30], [1, 0, 0], [0, 1, 0], 17)];
const SIDE = [Math.cos(A + 1.3), Math.sin(A + 1.3), 0], SU = [-SIDE[1], SIDE[0], 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.5);
  const shoulders = [...ring([0, 0, 2], [1, 0, 0], [0, 1, 0], 34, 32), ...ring([0, 0, 22], [1, 0, 0], [0, 1, 0], 19, 32)];
  const th1 = (-45 * Math.PI) / 180;
  fit(C, [...shoulders, ...sphere(), ...sphere().map((p) => tilt(p, th1))], 200, 165);
  const P = proj(C), pp = (pts) => pts.map((p) => P(...p));
  const g = mk("g", {}, svg);
  mk("path", { class: "sil", d: poly(hull(pp(shoulders))) }, g);
  mk("path", { class: "nf lo", d: poly(pp(ring([0, 0, 22], [1, 0, 0], [0, 1, 0], 19, 32))) }, g);
  for (const k of [0, 1, 2, 3]) { const a = A + Math.PI / 4 + (k * Math.PI) / 2, c = [27 * Math.cos(a), 27 * Math.sin(a), 8.5]; if (Math.cos(a) + Math.sin(a) > -0.3) mk("path", { class: "dot off", d: poly(pp(ring(c, [1, 0, 0], [0, 1, 0], 1.6, 10))) }, g); }
  mk("path", { class: "sil", d: poly(hull(pp([...ring(add(HX, U, -6), U, W, 3.5, 12), ...ring(add(HX, U, 6), U, W, 3.5, 12), add(HX, [0, 0, 1], -6)]))) }, g);
  const nk = mk("path", { class: "sil" }, g), hel = mk("path", { class: "sil" }, g), side = mk("path", { class: "nf lo" }, g);
  const rim = mk("path", { class: "nf" }, g), glass = mk("path", { class: "nf hi" }, g);
  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const th = (-t * amt * Math.PI) / 180, T = (pts) => pp(pts.map((p) => tilt(p, th)));
    nk.setAttribute("d", poly(hull(T(neck()))));
    hel.setAttribute("d", poly(hull(T(sphere()))));
    side.setAttribute("d", poly(T(ring(add([0, 0, CZ], SIDE, R - 1.5), SU, W, 6.5))));
    rim.setAttribute("d", poly(hull(T([...ring(add([0, 0, CZ], D, R - 3), U, W, 11.5), ...ring(add([0, 0, CZ], D, R + 1), U, W, 11.5)]))));
    glass.setAttribute("d", poly(T(ring(add([0, 0, CZ], D, R + 1.2), U, W, 8.5))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const rest = pp([...shoulders, ...sphere()]), xs = rest.map((p) => p[0]), ys = rest.map((p) => p[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  let on = null;
  function set(a) {
    if (a === on) return;
    on = a;
    tset(tw, a ? 1 : 0, performance.now(), 0);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > bx[0] && x < bx[1] && y > bx[2] && y < bx[3]), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "divinghelmet",
  means: "A diving helmet on its corselet: the pointer tilts the helmet back on its hinge, the front porthole bright.",
  rules: [1, 3, 5, 6],
  range: [20, 35, 45],
  tour: [[200, 99], [175, 120], [225, 135], null],
  mount,
});

lanterncarriage.code:
/**
 * Coal tender: a low railway tender on its frame and wheels, a long hatch over
 * its coal. The pointer over the figure swings the hatch up on its far hinge
 * to show the coal heaped inside. At rest the hatch sits a little ajar,
 * bright. The slider is how far it opens.
 */
const { Cam, fit, hull, poly, proj, tset, tval, tdone, tween, disposer, mk, pointer, register } = HL;

const rbox = (x0, y0, z0, x1, y1, z1, r, zs = [z0, z1]) => { const a = []; for (const [cx, cy, s] of [[x1 - r, y1 - r, 0], [x0 + r, y1 - r, 1], [x0 + r, y0 + r, 2], [x1 - r, y0 + r, 3]]) for (let i = 0; i <= 4; i++) { const t = (s + i / 4) * Math.PI / 2; for (const z of zs) a.push([cx + r * Math.cos(t), cy + r * Math.sin(t), z]); } return a; };
const wheel = (x, r, n = 24) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push([x + r * Math.cos(t), 41, 10 + r * Math.sin(t)]); } return o; };
const L = 92, Wd = 40, ZT = 42, HY = 2;
function lid(phi) { // a thin hatch hinged along x at y = HY, z = ZT
  const c = Math.cos(phi), s = Math.sin(phi);
  return rbox(6, 0, 0, L - 6, Wd - 6, 2.2, 3).map(([x, dy, dz]) => [x, HY + dy * c - dz * s, ZT + dy * s + dz * c]);
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.15);
  const R0 = (7 * Math.PI) / 180;
  fit(C, [...rbox(-4, 0, 0, L + 4, Wd, ZT, 6), ...lid((80 * Math.PI) / 180), ...wheel(16, 9)], 200, 160);
  const P = proj(C), pp = (pts) => pts.map((p) => P(...p));
  const g = mk("g", {}, svg);
  mk("path", { class: "sil", d: poly(hull(pp(rbox(-4, 3, 6, L + 4, Wd - 3, 14, 3)))) }, g);
  mk("path", { class: "sil", d: poly(hull(pp(rbox(0, 0, 14, L, Wd, ZT, 6)))) }, g);
  mk("path", { class: "nf lo", d: poly(pp(rbox(2, 2, ZT, L - 2, Wd - 2, ZT, 4, [ZT]))) }, g);
  for (const x of [16, 36, 56, 76]) { mk("path", { class: "sil", d: poly(pp(wheel(x, 9))) }, g); mk("path", { class: "dot off", d: poly(pp(wheel(x, 2, 10))) }, g); }
  const heapPts = [];
  for (const [r, z] of [[1, 0], [0.75, 4], [0.45, 7.5], [0.15, 9]]) heapPts.push(...rbox(8 + 30 * (1 - r), 6 + 12 * (1 - r), ZT, L - 8 - 30 * (1 - r), Wd - 6 - 12 * (1 - r), ZT, 6 * r + 1, [ZT + z]));
  const heap = mk("path", { class: "nf lo", d: poly(hull(pp(heapPts))) }, g);
  const hatch = mk("path", { class: "sil hi" }, g), hcr = mk("path", { class: "nf lo" }, g);
  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const phi = R0 + (t * (amt * Math.PI / 180 - R0)), lp = lid(phi);
    hatch.setAttribute("d", poly(hull(pp(lp))));
    hcr.setAttribute("d", poly(pp(lp.filter((_, i) => i % 2 === 1))));
    if (phi > 0.5) heap.after(hcr); else hcr.after(heap), hatch.after(heap), heap.before(hatch);
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const rest = pp([...rbox(-4, 0, 0, L + 4, Wd, ZT, 6), ...lid(R0)]), xs = rest.map((p) => p[0]), ys = rest.map((p) => p[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  let on = null;
  function set(a) {
    if (a === on) return;
    on = a;
    tset(tw, a ? 1 : 0, performance.now(), 0);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > bx[0] && x < bx[1] && y > bx[2] && y < bx[3]), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

