unicycle.code:
/**
 * Unicycle: a one-wheeled cycle with fork, saddle and pedals on a strip of
 * floor. The pointer rolls it along the strip to stand under it, the spokes
 * and cranks turning as it goes. At rest it stands left of centre, its tyre
 * bright. The slider is how far the strip runs.
 *
 * The pattern: one part sliding along a track (spring).
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, spring, stepS, clamp, seg, unproj, disposer, mk, pointer, put, register, solid } = HL;

const R = 34, TW = 4, SZ = 2 * R + 46, REST = -24, LEN = 92;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.55);
  fit(C, [[-LEN - 4, -16, 0], [LEN + 4, 16, 0], [-LEN + 4, 0, SZ + 8], [LEN - 4, 0, SZ + 8]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-LEN - 4, -16, LEN + 4, 16, 8, 2);
  put(solid(g), prism(P, front, fr, fi, -3, 0));
  const tyre = mk("path", { class: "sil hi" }, g), rim = mk("path", { class: "nf lo" }, g), spokes = mk("path", { class: "nf lo" }, g);
  const frame = mk("path", { class: "nf" }, g), seat = solid(g);
  const pos = spring(REST);
  let last = NaN;
  const wheel = (cx, r, y) => { const o = []; for (let i = 0; i < 40; i++) { const a = (i / 40) * 2 * Math.PI; o.push(P(cx + r * Math.cos(a), y, R + r * Math.sin(a))); } return o; };
  function draw() {
    if (pos.x === last) return;
    last = pos.x;
    const cx = pos.x, turn = -cx / R;
    tyre.setAttribute("d", poly(hull(wheel(cx, R, -TW).concat(wheel(cx, R, TW)))));
    rim.setAttribute("d", poly(wheel(cx, R - 4, TW)));
    let d = "";
    for (let k = 0; k < 8; k++) { const a = turn + (k * Math.PI) / 4; d += seg(P(cx, TW, R), P(cx + (R - 4) * Math.cos(a), TW, R + (R - 4) * Math.sin(a))); }
    spokes.setAttribute("d", d);
    const ca = turn + 0.6, k1 = [cx + 15 * Math.cos(ca), 11, R + 15 * Math.sin(ca)], k2 = [cx - 15 * Math.cos(ca), -11, R - 15 * Math.sin(ca)];
    frame.setAttribute("d", seg(P(cx, TW + 2, R), P(cx, TW + 2, SZ - 12)) + seg(P(cx, -TW - 2, R), P(cx, -TW - 2, SZ - 12)) + seg(P(cx, 0, SZ - 12), P(cx, 0, SZ))
      + seg(P(cx, TW + 3, R), P(...k1)) + seg(P(k1[0] - 4, k1[1], k1[2]), P(k1[0] + 4, k1[1], k1[2]))
      + seg(P(cx, -TW - 3, R), P(...k2)) + seg(P(k2[0] - 4, k2[1], k2[2]), P(k2[0] + 4, k2[1], k2[2])));
    const [sr, si] = rings(cx - 13, -6, cx + 11, 6, 5, 1.5);
    put(seat, prism(P, front, sr, si, SZ, SZ + 6));
  }
  const B = register(stage, (dt) => { const m = stepS(pos, dt); draw(); return m; });
  bag.add(B.unregister);
  function aim(t) {
    pos.t = t;
    read.textContent = t === REST ? "rest" : (t > 0 ? "+" : "") + Math.round(t);
    B.wake();
  }
  aim(REST);
  bag.add(pointer(stage, { move: ([sx, sy]) => { const [x] = unproj(C, sx, sy, 0); aim(Math.round(clamp(x, -reach, reach))); }, leave: () => aim(REST) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "unicycle",
  means: "A unicycle on a strip of floor: the pointer rolls it along the strip to stand under it, spokes and pedals turning as it goes.",
  rules: [1, 3, 5, 8],
  range: [30, 56, 56],
  tour: [[255, 271], [139, 213], [200, 240], null],
  mount,
});

thimble.code:
/**
 * Thimble box: a small rounded box with a hinged lid along its far edge and
 * a thimble resting inside. At rest the lid sits ajar, bright. The pointer
 * over the box swings the lid back on its hinge and the thimble rises out
 * of the opening after it. The slider is the thimble's lag behind the lid.
 */
const { Cam, circ, fit, hull, poly, prism, proj, rings, facing, tdone, tset, tval, tween, unproj, disposer, mk, pointer, put, register, solid } = HL;

const W = 36, H = 14, LT = 4, OPEN = 108, AJAR = 10, RISE = 11;

function rotY(p, c, a) {
  const s = Math.sin(a), co = Math.cos(a), x = p[0] - c[0], z = p[2] - c[2];
  return [c[0] + x * co + z * s, p[1], c[2] - x * s + z * co];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lag = value;
  const C = Cam(45, 0.5, 4.3);
  fit(C, [[0, 0, 0], [W, W, 0], [W, 0, 0], [0, W, 0], [-14, 0, H + W], [-14, W, H + W]], 200, 154);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ring, inner] = rings(0, 0, W, W, 6, 2.2);
  const lidBack = mk("g", {}, g);
  const box = solid(g);
  put(box, prism(P, front, ring, inner, 0, H));
  const th = solid(g), lidFront = mk("g", {}, g);
  const lid = solid(lidFront);
  const [lr, li] = rings(0, 0, W, W, 6, 1.4);
  const ang = tween(AJAR), rise = tween(0);
  let lastA = NaN, lastR = NaN;

  function drawLid(deg) {
    if (deg === lastA) return;
    lastA = deg;
    const a = -deg * Math.PI / 180, c = [0, 0, H], T = (u, v, z) => P(...rotY([u, v, z], c, a));
    const pts = [];
    lr.forEach((s) => { pts.push(T(s.u, s.v, H), T(s.u, s.v, H + LT)); });
    lid.sil.setAttribute("d", poly(hull(pts)));
    lid.cr.setAttribute("d", poly(li.map((s) => T(s.u, s.v, deg > 90 ? H : H + LT))));
    const par = deg > 90 ? lidBack : lidFront;
    if (lid.g.parentNode !== par) par.appendChild(lid.g);
  }
  function drawTh(r) {
    if (r === lastR) return;
    lastR = r;
    if (r < 0.4) { th.sil.setAttribute("d", ""); th.cr.setAttribute("d", ""); return; }
    const foot = circ(8, 24).map((s) => ({ ...s, u: s.u + W / 2, v: s.v + W / 2 }));
    const top = circ(6.4, 24).map((s) => ({ ...s, u: s.u + W / 2, v: s.v + W / 2 }));
    const pts = foot.map((s) => P(s.u, s.v, H)).concat(top.map((s) => P(s.u, s.v, H + r)));
    th.sil.setAttribute("d", poly(hull(pts)));
    const dimples = [];
    for (let k = 1; k <= 3; k++) dimples.push(poly(circ(1.6 * k, 16).map((s) => P(s.u + W / 2, s.v + W / 2, H + r))));
    th.cr.setAttribute("d", dimples.join(""));
  }
  const B = register(stage, (_dt, now) => {
    drawLid(tval(ang, now));
    drawTh(tval(rise, now));
    return !tdone(ang, now) || !tdone(rise, now);
  });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now();
    tset(ang, a ? OPEN : AJAR, now, a ? 0 : lag);
    tset(rise, a ? RISE : 0, now, a ? lag : 0);
    lid.sil.classList.toggle("hi", !a);
    th.sil.classList.toggle("hi", a);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -6 && x < W + 4 && y > -4 && y < W + 4;
  }
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lag = v; }, destroy: bag.dispose };
}

hairline({
  name: "thimble",
  means: "A thimble box: the pointer swings the hinged lid back and the thimble rises out of the box after it.",
  rules: [4, 5, 6, 8],
  range: [0, 160, 400],
  tour: [[221, 206], [221, 240], [221, 170], null],
  mount,
});

trekpole.code:
/**
 * Trail marker: a post on a low stone plinth with two pointed marker boards,
 * one high, one lower and turned the other way. At rest the high board points
 * down the trail, bright. The pointer on the ground turns the boards on the
 * post to point at it. The slider is the angle between the two boards.
 */
const { Cam, fit, hull, poly, prism, proj, rings, facing, spring, stepS, unproj, disposer, mk, pointer, put, register, solid } = HL;

const PH = 74, REST = -0.6, BL = [[2, -1.4], [36, -1.4], [44, 0], [36, 1.4], [2, 1.4]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gap = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 3.45);
  fit(C, [[-38, -38, 0], [38, 38, 0], [38, -38, PH], [-38, 38, PH]], 200, 218);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const plinth = solid(g);
  put(plinth, prism(P, front, ...rings(-12, -12, 12, 12, 8, 1.8), 0, 7));
  const back = mk("g", {}, g), postG = mk("g", {}, g), fore = mk("g", {}, g);
  const post = solid(postG);
  put(post, prism(P, front, ...rings(-2.6, -2.6, 2.6, 2.6, 1.4, 0.7), 7, PH));
  const cap = solid(postG);
  put(cap, prism(P, front, ...rings(-3.8, -3.8, 3.8, 3.8, 2, 0.9), PH, PH + 2.5));
  const boards = [[54, 64], [38, 47]].map(([z0, z1]) => ({ z0, z1, s: solid(fore), last: NaN }));
  const ang = spring(REST);

  function drawBoard(b, a) {
    if (a === b.last) return;
    b.last = a;
    const c = Math.cos(a), s = Math.sin(a), T = ([u, v], z) => P(u * c - v * s, u * s + v * c, z);
    const pts = [];
    BL.forEach((q) => pts.push(T(q, b.z0), T(q, b.z1)));
    b.s.sil.setAttribute("d", poly(hull(pts)));
    const m = (b.z0 + b.z1) / 2, h = (b.z1 - b.z0) / 2 - 1.6;
    b.s.cr.setAttribute("d", poly([T([5, 0], m - h), T([34, 0], m - h), T([40, 0], m), T([34, 0], m + h), T([5, 0], m + h)]));
    const par = c + s > 0 ? fore : back;
    if (b.s.g.parentNode !== par) par.appendChild(b.s.g);
  }
  const B = register(stage, (dt) => {
    const moving = stepS(ang, dt);
    drawBoard(boards[0], ang.x);
    drawBoard(boards[1], ang.x + Math.PI - gap);
    return moving;
  });
  bag.add(B.unregister);
  boards[0].s.sil.classList.add("hi");

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0), d = Math.hypot(x, y);
    if (d < 8 || d > 70) return leave();
    let a = Math.atan2(y, x);
    while (a - ang.t > Math.PI) a -= 2 * Math.PI;
    while (a - ang.t < -Math.PI) a += 2 * Math.PI;
    ang.t = a;
    const deg = Math.round(((a * 180) / Math.PI % 360 + 360) % 360);
    read.textContent = deg + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gap = (v * Math.PI) / 180; boards[1].last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "trekpole",
  means: "A trail marker: the pointer on the ground turns the post's two marker boards to point at it.",
  rules: [1, 3, 4, 8],
  range: [90, 150, 180],
  tour: [[102, 307], [285, 313], [176, 221], null],
  mount,
});

canteen.code:
/**
 * Canteen: a round flat flask standing on its edge, a short neck on top and
 * a screw cap tethered to it. At rest the cap is on, bright. The pointer over
 * the flask tips it to pour and the cap twists off and swings out on its
 * tether after it. The slider is the cap's lag behind the tilt.
 */
const { Cam, fit, hull, open, poly, proj, tdone, tset, tval, tween, unproj, disposer, mk, pointer, register, solid } = HL;

const R = 24, T = 8, NR = 5, NH = 6, CH = 6, TILT = 38, CAP = 1;

function rotY(p, c, a) {
  const s = Math.sin(a), co = Math.cos(a), x = p[0] - c[0], z = p[2] - c[2];
  return [c[0] + x * co + z * s, p[1], c[2] - x * s + z * co];
}
function disc(r, y, cz, n) {
  const out = [];
  for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; out.push([r * Math.cos(a), y, cz + r * Math.sin(a)]); }
  return out;
}
function cyl(r, z0, z1, n) {
  const out = [];
  for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; out.push([r * Math.cos(a), r * Math.sin(a), z0], [r * Math.cos(a), r * Math.sin(a), z1]); }
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lag = value;
  const C = Cam(45, 0.5, 3.9);
  fit(C, [[-R, -T, 0], [R + 16, T, 0], [-R, T, 2 * R + 14], [R + 20, T, 2 * R + 8], [R + 24, 0, 30]], 200, 162);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const body = solid(g), neck = solid(g), cap = solid(g);
  const tether = mk("path", { class: "nf lo" }, g);
  const tilt = tween(0), off = tween(0);
  let last = "";

  function draw(t, o) {
    const key = t + ":" + o;
    if (key === last) return;
    last = key;
    const a = (t * Math.PI) / 180, c = [R * 0.7, 0, 0], lift = t * 0.25;
    const W = (p) => { const q = rotY(p, c, a); return P(q[0], q[1], q[2] + lift); };
    const pts = [];
    [[-T / 2, R], [T / 2, R], [-T / 2 - 1.5, R - 2], [T / 2 + 1.5, R - 2]].forEach(([y, r]) => disc(r, y, R, 40).forEach((p) => pts.push(W(p))));
    body.sil.setAttribute("d", poly(hull(pts)));
    body.cr.setAttribute("d", poly(disc(R - 6, T / 2 + 1.5, R, 40).map(W)) + open([W([-R + 1, T / 2 + 1, R]), W([-R + 6, T / 2 + 1.5, R])]));
    const nz = 2 * R - 1;
    neck.sil.setAttribute("d", poly(hull(cyl(NR, nz, nz + NH, 20).map(W))));
    neck.cr.setAttribute("d", poly(disc(NR - 1.4, 0, 0, 20).map(([x, , y]) => W([x, y, nz + NH]))));
    // the cap: up the neck's axis, then out to the side on its tether
    const up = Math.min(o, 0.4) / 0.4 * 6, swing = Math.max(0, o - 0.4) / 0.6;
    const cz = nz + NH - 2 + up, cx = -swing * 16, czs = cz - swing * 14;
    const cp = cyl(NR + 1.2, czs, czs + CH, 20).map(([x, y, z]) => W([x + cx, y + swing * 6, z]));
    cap.sil.setAttribute("d", poly(hull(cp)));
    cap.cr.setAttribute("d", poly(disc(NR - 0.2, 0, 0, 20).map(([x, , y]) => W([x + cx, y + swing * 6, czs + CH]))));
    tether.setAttribute("d", open([W([-NR, 0, nz + 2]), W([-NR - 4 - swing * 4, swing * 4, nz - 4 + up * 0.3]), W([cx - NR - 1, swing * 6, czs + 1])]));
  }
  const B = register(stage, (_dt, now) => {
    draw(tval(tilt, now), tval(off, now));
    return !tdone(tilt, now) || !tdone(off, now);
  });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    const now = performance.now();
    tset(tilt, on ? TILT : 0, now, on ? lag : 0);
    tset(off, on ? CAP : 0, now, on ? 0 : lag);
    cap.sil.classList.toggle("hi", true);
    read.textContent = on ? "pour" : "rest";
    B.wake();
  }
  setActive(false);
  function hit([sx, sy]) {
    for (const z of [10, 24, 40]) { const [x, y] = unproj(C, sx, sy, z); if (Math.abs(x) < R + 4 && Math.abs(y) < T + 4) return true; }
    return false;
  }
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lag = v; }, destroy: bag.dispose };
}

hairline({
  name: "canteen",
  means: "A canteen: the pointer tips the flask to pour and the cap twists off and swings out on its tether.",
  rules: [4, 5, 6, 8],
  range: [0, 160, 400],
  tour: [[178, 164], [228, 242], [128, 85], null],
  mount,
});

gaiter.code:
/**
 * Map case: a flat rounded case lying on the ground, a window on its face
 * with the folds of a map behind it, and a flap hinged along its far edge.
 * At rest the flap sits ajar, bright. The pointer over the case swings the
 * flap right back and the folded map slides out after it. The slider is the
 * map's lag behind the flap.
 */
const { Cam, fit, hull, open, poly, prism, proj, rings, rrect, facing, tdone, tset, tval, tween, unproj, disposer, mk, pointer, put, register, solid } = HL;

const L = 56, D = 40, H = 5, FL = 30, LT = 1.6, OPEN = 168, AJAR = 9, SLIDE = 22;

function rotY(p, c, a) {
  const s = Math.sin(a), co = Math.cos(a), x = p[0] - c[0], z = p[2] - c[2];
  return [c[0] + x * co + z * s, p[1], c[2] - x * s + z * co];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lag = value;
  const C = Cam(45, 0.5, 3.75);
  fit(C, [[-FL, 0, 0], [L, D, 0], [L, 0, 0], [-FL, D, 0], [0, 0, 26], [0, D, 26]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g);
  const box = solid(g);
  put(box, prism(P, front, ...rings(0, 0, L, D, 5, 1.6), 0, H));
  // the window and the map's folds behind it
  const win = rrect(FL + 4, 5, L - 5, D - 5, 3, 4).map((s) => P(s.u, s.v, H));
  mk("path", { class: "nf lo", d: poly(win) + open([P(FL + 4 + (L - FL - 9) / 2, 5, H), P(FL + 4 + (L - FL - 9) / 2, D - 5, H)]) + open([P(FL + 4, D / 2, H), P(L - 5, D / 2, H)]) }, box.g);
  const map = solid(g), fr = mk("g", {}, g), flap = solid(fr);
  const [fr0, fi0] = rings(0, 0, FL, D, 5, 1.4);
  const ang = tween(AJAR), sl = tween(0);
  let lastA = NaN, lastS = NaN;

  function drawFlap(deg) {
    if (deg === lastA) return;
    lastA = deg;
    const a = -deg * Math.PI / 180, c = [0, 0, H], T = (u, v, z) => P(...rotY([u, v, z], c, a));
    const pts = [];
    fr0.forEach((s) => { pts.push(T(s.u, s.v, H), T(s.u, s.v, H + LT)); });
    flap.sil.setAttribute("d", poly(hull(pts)));
    flap.cr.setAttribute("d", poly(fi0.map((s) => T(s.u, s.v, deg > 90 ? H : H + LT))));
    const par = deg > 90 ? back : fr;
    if (flap.g.parentNode !== par) par.appendChild(flap.g);
  }
  function drawMap(d) {
    if (d === lastS) return;
    lastS = d;
    const x0 = 3 - d, x1 = FL + 2 - d * 0.4;
    const r = rrect(x0, 4, x1, D - 4, 1, 3), pts = [];
    r.forEach((s) => { pts.push(P(s.u, s.v, H), P(s.u, s.v, H + 0.8)); });
    map.sil.setAttribute("d", poly(hull(pts)));
    const xm = (x0 + x1) / 2;
    map.cr.setAttribute("d", open([P(xm, 4, H + 0.8), P(xm, D - 4, H + 0.8)]) + open([P(x0, D / 2, H + 0.8), P(x1, D / 2, H + 0.8)]));
  }
  const B = register(stage, (_dt, now) => {
    drawFlap(tval(ang, now));
    drawMap(tval(sl, now));
    return !tdone(ang, now) || !tdone(sl, now);
  });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now();
    tset(ang, a ? OPEN : AJAR, now, a ? 0 : lag);
    tset(sl, a ? SLIDE : 0, now, a ? lag : 0);
    flap.sil.classList.toggle("hi", !a);
    map.sil.classList.toggle("hi", a);
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -6 && x < L + 4 && y > -4 && y < D + 4;
  }
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lag = v; }, destroy: bag.dispose };
}

hairline({
  name: "gaiter",
  means: "A map case: the pointer swings the flap right back and the folded map slides out after it.",
  rules: [4, 5, 6, 8],
  range: [0, 160, 400],
  tour: [[205, 177], [256, 244], [219, 141], null],
  mount,
});

bearbell.code:
/**
 * Bear bell: a brass bell hanging from a strap clip on a pack strap, its
 * clapper hanging inside. The pointer over the bell swings it on its pin, the
 * clapper trailing behind on its own spring. At rest the bell hangs tipped,
 * its clapper bright. The slider is how far it swings.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, clamp, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 66, REST = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 4.0);
  fit(C, [[-26, -3, H + 14], [26, 3, H + 14], [-26, 3, H + 14], [26, -3, H + 14], [0, 0, H - 42], [-24, 0, H - 32], [24, 0, H - 32]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the strap: a flat band standing behind, and its clip
  const [sr, si] = rings(-26, -3, 26, 3, 2, 0.8);
  put(solid(g), prism(P, front, sr, si, H + 4, H + 14));
  const [kr, ki] = rings(-4, -4, 4, 4, 2, 0.8);
  put(solid(g), prism(P, front, kr, ki, H - 2, H + 6));
  const clap = mk("path", { class: "sil" }, g), body = mk("path", { class: "sil" }, g), mouth = mk("path", { class: "nf lo" }, g), slot = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST, { k: 70, c: 9 }), lag = spring(REST, { k: 40, c: 6 });

  // a ring of the bell at depth d below the pin, radius r, swung by a degrees
  const ring = (d, r, a, n = 36) => {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return circ(r, n).map((q) => { const z = -d; return P(q.u * c - z * s, q.v, H + q.u * s + z * c); });
  };
  const PROF = [[2, 5], [5, 8], [10, 10.5], [18, 12.5], [26, 15], [30, 17]];
  let last = "";
  function draw() {
    const a = ang.x, b = lag.x, key = a.toFixed(2) + b.toFixed(2);
    if (key === last) return;
    last = key;
    const pts = [];
    for (const [d, r] of PROF) pts.push(...ring(d, r, a));
    body.setAttribute("d", poly(hull(pts)));
    mouth.setAttribute("d", poly(ring(30, 17, a)));
    slot.setAttribute("d", poly(ring(18, 12.5, a).filter((_, i) => i % 36 > 14 && i % 36 < 22).concat(ring(26, 15, a).filter((_, i) => i % 36 > 14 && i % 36 < 22).reverse())));
    clap.setAttribute("d", poly(hull([...ring(34, 5, b, 20), ...ring(40, 4, b, 20), ...ring(29, 1.5, b, 12)])));
  }

  const B = register(stage, (dt) => { const m1 = stepS(ang, dt), m2 = stepS(lag, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);
  draw();

  const mid = P(0, 0, H - 18);
  let on = null;
  function set(p) {
    const hov = p && Math.abs(p[0] - mid[0]) < 70 && Math.abs(p[1] - mid[1]) < 70;
    const t = hov ? clamp(-amp + (p[0] - mid[0]) * 0.25, -48, 48) : REST;
    ang.t = t; lag.t = t * 1.25;
    if (hov !== on) {
      on = hov;
      body.classList.toggle("hi", hov);
      clap.classList.toggle("hi", !hov);
    }
    read.textContent = hov ? Math.round(Math.abs(t)) + "°" : "rest";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

