  name: "avalanche",
  means: "An avalanche probe in a slab of snow: the pointer leans the jointed probe toward itself, probing.",
  rules: [1, 3, 4, 5],
  range: [10, 24, 34],
  tour: [[200, 113], [226, 130], [176, 140], null],
  mount,
