  name: "mouthmodel",
  means: "A dental jaw model: the upper jaw swings open on its back hinge, wider as the pointer comes to the front.",
  rules: [1, 3, 4, 5],
  range: [40, 80, 100],
  tour: [[200, 271], [200, 210], [150, 240], null],
  mount,
