junctionbox.code:
/**
 * Junction box: a grey box with cable glands on its faces and a lid hinged
 * along the back edge. At rest the lid stands ajar, bright. The pointer over
 * the box swings the lid open to show the cavity. The slider is how far.
 *
 * The pattern: one part turning on a hinge.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, rrect, unproj, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 80, D = 56, H = 34, V = [0.612, 0.612, 0.5], REST = 16;
const shift = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-4, -4, 0], [W + 12, D + 12, 0], [W + 12, -4, 0], [-4, D + 12, 0], [0, -32, H + 52], [W, -32, H + 52]], 200, 168);
  const P = proj(C), front = facing(C);
  function slab(s, ring, inner, f, w0, w1) {
    const a = ring.map((q) => P(...f(q.u, q.v, w0))), b = ring.map((q) => P(...f(q.u, q.v, w1)));
    s.sil.setAttribute("d", poly(hull(a.concat(b))));
    const c0 = f(0, 0, w0), c1 = f(0, 0, w1), vis = (c1[0] - c0[0]) * V[0] + (c1[1] - c0[1]) * V[1] + (c1[2] - c0[2]) * V[2] > 0;
    s.cr.setAttribute("d", poly(inner.map((q) => P(...f(q.u, q.v, vis ? w1 : w0)))));
  }
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, W, D, 6, 4.5);
  put(solid(g), prism(P, front, br, bi, 0, H));
  mk("path", { class: "nf lo", d: poly(bi.map((q) => P(q.u, q.v, H))) }, g);
  mk("path", { class: "nf lo", d: poly(rrect(9, 9, W - 9, D - 9, 3, 4).map((q) => P(q.u, q.v, H - 10))) }, g);
  // cable glands: short cylinders out of the front and the side
  const gl = circ(5, 24), gi = circ(3, 24);
  for (const cx of [22, 58]) slab(solid(g), gl, gi, (u, v, w) => [cx + u, D + w, 15 + v], 0, 8);
  slab(solid(g), shift(gl, 0, 0), gi, (u, v, w) => [W + w, 28 + u, 15 + v], 0, 8);

  const lid = solid(g);
  lid.sil.classList.add("hi");
  const ring = rrect(-1, 0, W + 1, D + 2, 7, 6), inner = rrect(3, 4, W - 3, D - 2, 4, 6);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180);
    slab(lid, ring, inner, (u, v, w) => [u, -1 + v * c - w * s, H + v * s + w * c], 0, 4);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? open : REST, performance.now(), 0);
    read.textContent = o ? "open" : "rest";
    B.wake();
  }
  function hit([sx, sy]) { const [x, y] = unproj(C, sx, sy, H); return x > -8 && x < W + 10 && y > -10 && y < D + 10; }
  set(false);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (on) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "junctionbox",
  means: "A junction box with its lid ajar: the pointer over the box swings the lid open on its back hinge.",
  rules: [1, 5, 6, 8],
  range: [60, 105, 120],
  tour: [[160, 150], [200, 170], [240, 190], null],
  mount,
});

breakerpanel.code:
/**
 * Breaker switch: a knife switch on a base plate, two blades hinged at one
 * end and a handle on their crossbar. At rest the blades sit lifted a little,
 * the handle bright. The pointer over the switch throws the blades open out
 * of their jaws. The slider is how far they swing.
 *
 * The pattern: one part turning on a hinge.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, rrect, unproj, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const V = [0.612, 0.612, 0.5], REST = 14, HX = 11, HZ = 14;
const shift = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [98, 42, 0], [98, 0, 0], [0, 42, 0], [40, 20, 96], [-20, 20, 70]], 200, 172);
  const P = proj(C), front = facing(C);
  function slab(s, ring, inner, f, w0, w1) {
    const a = ring.map((q) => P(...f(q.u, q.v, w0))), b = ring.map((q) => P(...f(q.u, q.v, w1)));
    s.sil.setAttribute("d", poly(hull(a.concat(b))));
    const c0 = f(0, 0, w0), c1 = f(0, 0, w1), vis = (c1[0] - c0[0]) * V[0] + (c1[1] - c0[1]) * V[1] + (c1[2] - c0[2]) * V[2] > 0;
    s.cr.setAttribute("d", poly(inner.map((q) => P(...f(q.u, q.v, vis ? w1 : w0)))));
  }
  const g = mk("g", {}, svg);
  const block = (par, x, y) => { const [r, i] = rings(x, y, x + 10, y + 8, 2, 1.2); put(solid(par), prism(P, front, r, i, 5, HZ)); };
  const [br, bi] = rings(0, 0, 98, 42, 6, 2.2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  for (const x of [HX - 5, 74]) block(g, x, 6);
  const back = mk("g", {}, g);
  for (const x of [HX - 5, 74]) block(g, x, 28);
  const front2 = mk("g", {}, g);
  const hand = mk("g", {}, g);
  const bl = (y) => [rrect(0, y - 1.8, 72, y + 1.8, 1.4, 3), rrect(0.8, y - 0.9, 71.2, y + 0.9, 0.8, 3)];
  const b1 = solid(back), b2 = solid(front2), bar = solid(hand), hd = solid(hand);
  hd.sil.classList.add("hi");
  const [r1, i1] = bl(10), [r2, i2] = bl(32);
  const [xr, xi] = [rrect(52, 7, 60, 35, 2, 3), rrect(53.2, 8.2, 58.8, 33.8, 1.2, 3)];
  const hr = shift(circ(4.2, 24), 56, 21), hi = shift(circ(2.4, 24), 56, 21);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180);
    const f = (u, v, w) => [HX + u * c - w * s, v, HZ + u * s + w * c];
    slab(b1, r1, i1, f, 0, 3);
    slab(b2, r2, i2, f, 0, 3);
    slab(bar, xr, xi, f, 3, 6);
    slab(hd, hr, hi, f, 6, 28);
    if (-s * V[0] + c * V[2] < 0) back.before(hand); else front2.after(hand);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? open : REST, performance.now(), 0);
    read.textContent = o ? "off" : "rest";
    B.wake();
  }
  function hit([sx, sy]) { const [x, y] = unproj(C, sx, sy, 5); return x > -10 && x < 108 && y > -40 && y < 52; }
  set(false);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (on) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "breakerpanel",
  means: "A knife switch resting just off its jaws: the pointer over it throws the blades open by the handle.",
  rules: [1, 5, 6, 8],
  range: [40, 70, 85],
  tour: [[154, 193], [200, 232], [242, 262], null],
  mount,
});

trowelsift.code:
/**
 * Finds tray: a shallow tray of three compartments on a pivot post, sherds
 * lying in it. At rest it sits almost level and one sherd is bright. The
 * pointer tips the tray toward whichever end it stands over, the rim taking
 * the bright. The slider is how far it tips.
 *
 * The pattern: one part tilting toward the pointer.
 */
const { Cam, fillet, fit, facing, hull, poly, prism, proj, rings, rrect, unproj, spring, stepS, disposer, mk, pointer, put, register, solid, seg } = HL;

const V = [0.612, 0.612, 0.5], L = 104, D = 64, Z0 = 22, REST = 4;
const SH = [[18, 24, 0], [20, 44, 1.2], [52, 32, 2.2], [86, 22, 0.6], [84, 42, 3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, Z0 - 18], [L, D, Z0 - 18], [L, 0, Z0 + 26], [0, D, Z0 + 26], [36, 12, 0], [70, 52, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  function slab(s, ring, inner, f, w0, w1) {
    const a = ring.map((q) => P(...f(q.u, q.v, w0))), b = ring.map((q) => P(...f(q.u, q.v, w1)));
    s.sil.setAttribute("d", poly(hull(a.concat(b))));
    const c0 = f(0, 0, w0), c1 = f(0, 0, w1), vis = (c1[0] - c0[0]) * V[0] + (c1[1] - c0[1]) * V[1] + (c1[2] - c0[2]) * V[2] > 0;
    if (inner) s.cr.setAttribute("d", poly(inner.map((q) => P(...f(q.u, q.v, vis ? w1 : w0)))));
  }
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(34, 14, 70, 50, 6, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  const [qr, qi] = rings(46, 26, 58, 38, 4, 1.5);
  put(solid(g), prism(P, front, qr, qi, 4, Z0 - 1));
  const tray = solid(g), divs = mk("path", { class: "nf lo" }, g);
  const ring = rrect(0, 0, L, D, 7, 6), inner = rrect(4.5, 4.5, L - 4.5, D - 4.5, 4, 6);
  const sherds = SH.map(([x, y, k]) => {
    const pts = [0, 1, 2, 3, 4].map((i) => { const t = i * 1.257 + k, r = 6 + ((i * 7 + k * 3) % 4); return [x + r * Math.cos(t) * 1.2, y + r * Math.sin(t) * 0.8]; });
    return { s: mk("path", { class: "sil" }, g), pts: fillet(pts, pts.map(() => 1.6), 3) };
  });
  const ang = spring(REST);
  let last = NaN, act = false;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180);
    const f = (u, v, w) => { const d = u - L / 2; return [L / 2 + d * c - w * s, v, Z0 + d * s + w * c]; };
    slab(tray, ring, inner, f, 0, 9);
    divs.setAttribute("d", [36, 69].map((u) => seg(P(...f(u, 4.5, 9)), P(...f(u, D - 4.5, 9)))).join(""));
    for (const sh of sherds) sh.s.setAttribute("d", poly(hull(sh.pts.map(([u, v]) => P(...f(u, v, 2))).concat(sh.pts.map(([u, v]) => P(...f(u, v, 3.6)))))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function light(on) {
    act = on;
    tray.sil.classList.toggle("hi", on);
    sherds[2].s.classList.toggle("hi", !on);
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, Z0 + 9);
    const inside = x > -12 && x < L + 12 && y > -12 && y < D + 12;
    const t = Math.max(-1, Math.min(1, (x - L / 2) / (L / 2)));
    ang.t = inside ? -t * max : REST;
    if (inside !== act) light(inside);
    read.textContent = inside ? "tilt " + Math.round(Math.abs(t * max)) : "rest";
    B.wake();
  }
  function leave() { ang.t = REST; light(false); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "trowelsift",
  means: "A finds tray of sherds on a pivot post: the tray tips toward the end the pointer stands over.",
  rules: [1, 3, 5, 8],
  range: [6, 14, 20],
  tour: [[132, 100], [200, 136], [270, 166], null],
  mount,
});

pickaxe.code:
/**
 * Pickaxe: a miner's pick held over a rock on a slab of ground. The pointer
 * sets the swing: far from the rock the pick rises, over the rock it comes
 * down and its point meets the stone. At rest it hangs half raised, its head
 * bright. The slider is how quickly the swing follows.
 *
 * The pattern: a continuous angle on a spring; the hit is on the ground plane.
 */
const { Cam, fit, proj, facing, rings, prism, put, solid, mk, poly, hull, rrect, spring, stepS, register, pointer, disposer, unproj, clamp, lerp, rad } = HL;

const PV = [-58, 0, 44], LEN = 84, REST = 52, HI = 78, LO = 4;

function beam(P, a, b, w, h, up) {
  const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], n = Math.hypot(...d) || 1, D = d.map((x) => x / n);
  let s = [D[1] * up[2] - D[2] * up[1], D[2] * up[0] - D[0] * up[2], D[0] * up[1] - D[1] * up[0]];
  const sn = Math.hypot(...s) || 1; s = s.map((x) => x / sn);
  const t = [s[1] * D[2] - s[2] * D[1], s[2] * D[0] - s[0] * D[2], s[0] * D[1] - s[1] * D[0]];
  const ring = rrect(-w / 2, -h / 2, w / 2, h / 2, Math.min(w, h) * 0.45, 3);
  const at = (o) => ring.map((q) => P(...[0, 1, 2].map((j) => o[j] + q.u * s[j] + q.v * t[j])));
  return poly(hull(at(a).concat(at(b))));
}

function pose(th) {
  const c = Math.cos(rad(th)), s = Math.sin(rad(th));
  const H = [PV[0] + LEN * c, 0, PV[2] + LEN * s], n = [-s, 0, c], d = [c, 0, s];
  const tip = (k, L) => [H[0] + n[0] * L * k - d[0] * 7, 0, H[2] + n[2] * L * k - d[2] * 7];
  return { H, A: tip(-1, 30), B: tip(1, 24) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.7);
  const ex = [[-74, -40, -4], [74, 40, -4], [74, -40, 0], [-74, 40, 0], PV];
  for (const th of [LO, REST, HI]) { const q = pose(th); ex.push(q.A, q.B, q.H); }
  fit(C, ex, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-74, -40, 74, 40, 10, 2);
  put(solid(g), prism(P, front, gr, gi, -4, 0));
  const [rr, ri] = rings(20, -16, 50, 14, 10, 2);
  put(solid(g), prism(P, front, rr, ri, 0, 16));
  const handle = mk("path", { class: "sil" }, g), headA = mk("path", { class: "sil hi" }, g), headB = mk("path", { class: "sil hi" }, g);
  const th = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "";
  function draw() {
    const key = th.x.toFixed(2);
    if (key === last) return;
    last = key;
    const q = pose(th.x), up = [0, 1, 0];
    handle.setAttribute("d", beam(P, PV, q.H, 4, 5, up));
    headA.setAttribute("d", beam(P, [q.H[0], 0, q.H[2]], q.A, 7, 5, up));
    headB.setAttribute("d", beam(P, [q.H[0], 0, q.H[2]], q.B, 7, 5, up));
  }
  const L = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(L.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(x) > 100 || Math.abs(y) > 70) { th.t = REST; read.textContent = "rest"; }
      else { th.t = lerp(HI, LO, clamp((x + 60) / 100, 0, 1)); read.textContent = `swing ${Math.round(th.t)}°`; }
      L.wake();
    },
    leave: () => { th.t = REST; read.textContent = "rest"; L.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  draw();
  return { set: (v) => { th.k = 100 * v; th.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "pickaxe",
  means: "A miner's pick over a rock: the pointer sets the swing, and over the stone the point comes down to strike it.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[242, 241], [116, 202], [200, 230], null],
  mount,
});

peavey.code:
/**
 * Cant hook: a long-handled lever with a hinged hook, set against a log on a
 * slab. The pointer sets the lever: as it moves across, the handle swings
 * down over the log to roll it. At rest the handle leans up, its hook bright.
 * The slider is how quickly the lever follows.
 *
 * The pattern: a continuous angle on a spring; the hit is on the ground plane.
 */
const { Cam, fit, proj, facing, circ, rings, prism, put, solid, mk, poly, hull, rrect, spring, stepS, register, pointer, disposer, unproj, clamp, lerp, rad } = HL;

const PV = [-15, 0, 18], LEN = 96, REST = 70, HI = 100, LO = 22;

function beam(P, a, b, w, h, up) {
  const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], n = Math.hypot(...d) || 1, D = d.map((x) => x / n);
  let s = [D[1] * up[2] - D[2] * up[1], D[2] * up[0] - D[0] * up[2], D[0] * up[1] - D[1] * up[0]];
  const sn = Math.hypot(...s) || 1; s = s.map((x) => x / sn);
  const t = [s[1] * D[2] - s[2] * D[1], s[2] * D[0] - s[0] * D[2], s[0] * D[1] - s[1] * D[0]];
  const ring = rrect(-w / 2, -h / 2, w / 2, h / 2, Math.min(w, h) * 0.45, 4);
  const at = (o) => ring.map((q) => P(...[0, 1, 2].map((j) => o[j] + q.u * s[j] + q.v * t[j])));
  return [poly(hull(at(a).concat(at(b)))), poly(at(b))];
}

function pose(th) {
  const c = Math.cos(rad(th)), s = Math.sin(rad(th));
  const E = [PV[0] - LEN * c, 0, PV[2] + LEN * s];
  const k1 = [PV[0] - 12 * c, 0, PV[2] + 12 * s];
  const hk = [k1[0] + 22 * s + 6 * c, 0, k1[2] + 22 * c - 6 * s];
  const tip = [hk[0] + 10 * c, 0, hk[2] - 10 * s];
  return { E, k1, hk, tip };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.8);
  const ex = [[-70, -50, -5], [50, 50, -5], [50, -50, -5], [-70, 50, -5]];
  for (const th of [LO, REST, HI]) { const q = pose(th); ex.push(q.E, q.hk); }
  fit(C, ex, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-70, -50, 50, 50, 12, 2);
  put(solid(g), prism(P, front, gr, gi, -5, 0));
  const [lg, le] = beam(P, [2, -46, 16], [2, 4, 16], 32, 32, [0, 0, 1]);
  mk("path", { class: "sil", d: lg }, g);
  mk("path", { class: "nf lo", d: le }, g);
  mk("path", { class: "nf lo", d: poly(circ(5, 16).map((q) => P(2 + q.u, 4, 16 + q.v))) }, g);
  const handle = mk("path", { class: "sil" }, g), hookA = mk("path", { class: "sil hi" }, g), hookB = mk("path", { class: "sil hi" }, g);
  const th = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "";
  function draw() {
    const key = th.x.toFixed(2);
    if (key === last) return;
    last = key;
    const q = pose(th.x), up = [0, 1, 0];
    handle.setAttribute("d", beam(P, [PV[0], 8, PV[2]].map((v, j) => (j === 1 ? 8 : v)), [q.E[0], 8, q.E[2]], 5, 6, up)[0]);
    hookA.setAttribute("d", beam(P, [q.k1[0], 8, q.k1[2]], [q.hk[0], 8, q.hk[2]], 3.5, 4, up)[0]);
    hookB.setAttribute("d", beam(P, [q.hk[0], 8, q.hk[2]], [q.tip[0], 8, q.tip[2]], 3.5, 4, up)[0]);
  }
  const L = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(L.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -110 || x > 80 || Math.abs(y) > 80) { th.t = REST; read.textContent = "rest"; }
      else { th.t = lerp(HI, LO, clamp((x + 90) / 140, 0, 1)); read.textContent = `lever ${Math.round(th.t)}°`; }
      L.wake();
    },
    leave: () => { th.t = REST; read.textContent = "rest"; L.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  draw();
  return { set: (v) => { th.k = 100 * v; th.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
