  mount,
});

bottlecapper.code:
/**
 * Bottle capper: a bench capper on a base plate, a bottle under its bell.
 * The pointer over the capper pulls the long lever down: it swings on its
 * pivot at the column top, and the head with its bell slides down the
 * column onto the cap. At rest the lever is raised, bright. The slider is
 * how far the lever travels.
 *
 * The pattern: one part turning on a pivot, a second sliding with it.
 */
const {
  Cam, circ, fit, hull, poly, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const BX = 46, BY = 22, PX = 11, PZ = 96, L = 74, A0 = 0.62, A1 = -0.2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, 0, 0], [64, 44, 0], [PX + L * Math.cos(A0), 22, PZ + L * Math.sin(A0) + 4], [PX, 22, PZ + 6], [0, 44, 0], [64, 0, 0]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, z0, x1, y1, z1) => hull([x0, x1].flatMap((x) => [y0, y1].flatMap((y) => [z0, z1].map((z) => P(x, y, z)))));
  const cyl = (x, y, r, z0, z1) => hull(ringAt(P, disc(x, y, r), z0).concat(ringAt(P, disc(x, y, r), z1)));

  mk("path", { d: poly(box(0, 0, 0, 64, 44, 4)) }, g);
  mk("path", { d: poly(box(PX - 4, 18, 4, PX + 4, 26, PZ)) }, g);
  // the bottle: body, shoulder, neck, crown cap
  const bottle = [];
  for (const [r, z] of [[9, 4], [9, 36], [6, 44], [3.6, 52], [3.6, 60]]) bottle.push(...ringAt(P, disc(BX, BY, r), z));
  mk("path", { d: poly(hull(bottle)) }, g);
  mk("path", { d: poly(cyl(BX, BY, 4.4, 60, 63)) }, g);
  const head = mk("path", {}, g), bell = mk("path", {}, g);
  const lever = mk("path", { class: "sil" }, g), grip = mk("path", { class: "sil" }, g);
  mk("path", { d: poly(cyl(PX, 22, 3, PZ - 1, PZ + 1)), class: "nf" }, g);

  const t = tween(0);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const a = A0 + (A1 - A0) * p, ca = Math.cos(a), sa = Math.sin(a);
    const pt = (s, dz, y) => P(PX + s * ca - dz * sa, y, PZ + s * sa + dz * ca);
    const lv = [];
    for (const s of [-6, L]) for (const dz of [-2.5, 2.5]) for (const y of [19.5, 24.5]) lv.push(pt(s, dz, y));
    lever.setAttribute("d", poly(hull(lv)));
    const gp = [];
    for (const s of [L - 14, L + 2]) for (const dz of [-4, 4]) for (const y of [18.5, 25.5]) gp.push(pt(s, dz, y));
    grip.setAttribute("d", poly(hull(gp)));
    const hz = 80 - 16 * p;
    head.setAttribute("d", poly(box(PX - 6, 17, hz, BX + 2, 27, hz + 7)));
    bell.setAttribute("d", poly(cyl(BX, BY, 6, hz - 9, hz)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const mid = P(32, 22, 48), end = P(PX + (L - 6) * Math.cos(A0), 22, PZ + (L - 6) * Math.sin(A0));
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a > 0 ? reach : 0, performance.now(), 0);
    read.textContent = a > 0 ? "cap " + Math.round(reach * 100) : "rest";
    B.wake();
  }
  setActive(0);
  lever.classList.add("hi");
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setActive(Math.hypot(sx - mid[0], sy - mid[1]) < 95 || Math.hypot(sx - end[0], sy - end[1]) < 50 ? 1 : 0),
    leave: () => setActive(0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; if (act > 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "bottlecapper",
  means: "A bench bottle capper: the pointer pulls its long lever down, and the head slides down the column to crimp the cap.",
  rules: [1, 3, 5, 6],
  range: [40, 100, 100],
  tour: [[260, 22], [200, 180], [216, 300], null],
  mount,
});

winepress2.code:
/**
 * Wine thief: a barrel lying on two chocks, a glass wine thief standing in
 * its bung hole. The pointer over the barrel draws the thief: it slides up
 * out of the bung and tilts toward the viewer, a sample held in its bulb.
 * At rest the thief is bright, sitting in the bung. The slider is how far
 * it draws.
 *
 * The pattern: one part sliding out, then tilting.
 */
const {
  Cam, circ, fit, hull, poly, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const CZ = 30, BL = 34, L = 62;
const rad = (x) => 25 - 5 * (x / BL) ** 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-BL - 2, -26, 0], [BL + 2, 26, 0], [-BL, 0, CZ + 26], [BL, 0, CZ + 26], [0, 0, CZ + 25 + L + 30], [24, 0, CZ + 70], [-BL, 26, 0], [BL, -26, 0]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, z0, x1, y1, z1) => hull([x0, x1].flatMap((x) => [y0, y1].flatMap((y) => [z0, z1].map((z) => P(x, y, z)))));
  const ring = (x, r, a0 = 0, a1 = 2 * Math.PI, n = 36) => {
    const o = [];
    for (let i = 0; i <= n; i++) { const a = a0 + ((a1 - a0) * i) / n; o.push(P(x, r * Math.cos(a), CZ + r * Math.sin(a))); }
    return o;
  };
  const line = (pts) => "M" + pts.map((p) => p[0].toFixed(1) + " " + p[1].toFixed(1)).join("L");

  for (const x of [-20, 20]) mk("path", { d: poly(box(x - 5, -22, 0, x + 5, 22, 12)) }, g);
  const body = [];
  for (let x = -BL; x <= BL; x += BL / 4) body.push(...ring(x, rad(x)));
  mk("path", { d: poly(hull(body)) }, g);
  mk("path", { d: poly(ring(BL, rad(BL))), class: "nf" }, g);
  // hoops: the near half of each band
  const th = Math.atan2(0.8, 0.7);
  for (const x of [-BL + 6, -12, 12]) mk("path", { d: line(ring(x, rad(x) + 0.4, th - 1.6, th + 1.6, 24)), class: "nf" }, g);
  mk("path", { d: poly(ringAt(P, circ(5, 20), CZ + 25)), class: "nf" }, g);
  const tube = mk("path", { class: "sil" }, g), bulb = mk("path", { class: "sil" }, g);

  const t = tween(0);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const lift = 30 * Math.min(1, p * 1.6), tl = 0.75 * Math.max(0, p * 1.6 - 0.6) / 1;
    const bz = CZ + 23 + lift, ct = Math.cos(tl), st = Math.sin(tl);
    const at = (u, v, h) => P(u * ct + h * st, v, bz - u * st + h * ct);
    const shell = (prof) => {
      const o = [];
      for (const [r, h] of prof) for (const q of circ(r, 16)) o.push(at(q.u, q.v, h));
      return hull(o);
    };
    tube.setAttribute("d", poly(shell([[1.4, 0], [3, 5], [3, L - 4], [4.5, L - 4], [4.5, L]])));
    bulb.setAttribute("d", poly(shell([[3, 18], [7, 26], [7, 38], [3, 46]])));
  }

  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, CZ + 30);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a > 0 ? reach : 0, performance.now(), 0);
    read.textContent = a > 0 ? "draw " + Math.round(reach * 100) : "rest";
    B.wake();
  }
  setActive(0);
  tube.classList.add("hi");
  bulb.classList.add("hi");
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setActive(Math.hypot(sx - mid[0], sy - mid[1]) < 115 ? 1 : 0),
    leave: () => setActive(0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; if (act > 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "winepress2",
  means: "A barrel on its chocks with a wine thief in the bung: the pointer draws the thief up out of the barrel and tilts it to the light.",
  rules: [1, 3, 5, 6],
  range: [40, 100, 100],
  tour: [[200, 122], [190, 220], [340, 290], null],
  mount,
});

barrelrack.code:
/**
 * Barrel rack: a barrel lying across the two rails of a low cradle, a
 * chock at each end. The pointer over the rack rolls the barrel along the
 * rails: it turns as it goes, its bung hole travelling round. At rest the
 * barrel is bright at the near end. The slider is how far it rolls.
 *
 * The pattern: one part rolling, a turn and a slide together.
 */
const {
  Cam, fit, hull, poly, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const BL = 30, R = 24, RZ = 12, CZ = RZ + R - 3, X0 = -22, RUN = 40;
const rad = (y) => R - 5 * (y / BL) ** 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-56, -30, 0], [56, 30, 0], [-56, 30, 0], [56, -30, 0], [X0, 0, CZ + R + 2], [X0 + RUN, 0, CZ + R + 2]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, z0, x1, y1, z1) => hull([x0, x1].flatMap((x) => [y0, y1].flatMap((y) => [z0, z1].map((z) => P(x, y, z)))));
  const line = (pts) => "M" + pts.map((p) => p[0].toFixed(1) + " " + p[1].toFixed(1)).join("L");
  const rail = (y) => { for (const x of [-48, 48]) mk("path", { d: poly(box(x - 3, y - 3, 0, x + 3, y + 3, RZ - 4)) }, g); mk("path", { d: poly(box(-54, y - 4, RZ - 4, 54, y + 4, RZ)) }, g); };
  rail(-20);
  for (const x of [-54, 54]) mk("path", { d: poly(box(x - 2, -24, RZ, x + 2, 24, RZ + 6)) }, g);
  const body = mk("path", { class: "sil" }, g), hoops = mk("path", { class: "nf" }, g), bung = mk("path", { class: "nf" }, g);
  rail(20);

  const t = tween(0);
  let last = NaN;
  const th = Math.atan2(0.8, 0.7);
  function draw(p) {
    if (p === last) return;
    last = p;
    const cx = X0 + RUN * p, rot = (RUN * p) / R;
    const ring = (y, r, a0, a1, n) => { const o = []; for (let i = 0; i <= n; i++) { const a = a0 + ((a1 - a0) * i) / n; o.push(P(cx + r * Math.cos(a), y, CZ + r * Math.sin(a))); } return o; };
    const pts = [];
    for (let y = -BL; y <= BL; y += BL / 4) pts.push(...ring(y, rad(y), 0, 2 * Math.PI, 36));
    body.setAttribute("d", poly(hull(pts)));
    let d = line(ring(BL, rad(BL), 0, 2 * Math.PI, 36)) + "Z";
    for (const y of [-BL + 6, -10, 10]) d += line(ring(y, rad(y) + 0.4, th - 1.55, th + 1.55, 24));
    hoops.setAttribute("d", d);
    // the bung: a small ring on the belly, turning with the roll
    const a = Math.PI / 2 - 0.35 - rot, nx = Math.cos(a), nz = Math.sin(a);
    if (nx * 0.7 + nz * 0.8 > 0.15) {
      const o = [];
      for (let i = 0; i <= 20; i++) { const s = (i / 20) * 2 * Math.PI, u = 4 * Math.cos(s); o.push(P(cx + R * nx - u * nz, 4 * Math.sin(s), CZ + R * nz + u * nx)); }
      bung.setAttribute("d", line(o) + "Z");
    } else bung.setAttribute("d", "");
  }

  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, CZ);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a > 0 ? reach : 0, performance.now(), 0);
    read.textContent = a > 0 ? "roll " + Math.round(reach * 100) : "rest";
    B.wake();
  }
  setActive(0);
  body.classList.add("hi");
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setActive(Math.hypot(sx - mid[0], sy - mid[1]) < 120 ? 1 : 0),
    leave: () => setActive(0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; if (act > 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "barrelrack",
  means: "A barrel across the rails of a low cradle: the pointer rolls it along the rails, the bung hole turning round as it goes.",
  rules: [1, 3, 5, 6],
