  name: "inkstone",
  means: "An ink stone with a square ink stick lying on it: the pointer tilts the stick up onto its end, ready to grind.",
  rules: [1, 3, 5, 6],
  range: [45, 75, 90],
  tour: [[185, 140], [327, 191], [73, 186], null],
