  name: "origamicrane",
  means: "A folded paper crane: the pointer over it raises both wings on their fold, as in a flap.",
  rules: [1, 3, 5, 6],
  range: [40, 65, 80],
  tour: [[115, 192], [309, 195], [96, 82], null],
  mount,
