tinderbox.code:
/**
 * Tinder box: a small tin with a hinged lid and a steel striker lying
 * inside. At rest the lid sits ajar, bright. The pointer over the box
 * swings the lid open on its back hinge to show the striker. The slider
 * is how far the lid opens.
 *
 * The pattern: one hinged part swinging open (swing).
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 70, D = 46, H = 26, T = 6, REST = 14;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[0, -T, H + D], [W, -T, H + D], [0, D, 0], [W, D, 0], [0, 0, 0], [W, D, H + 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const H2 = (pts) => poly(hull(pts.map((p) => P(p[0], p[1], p[2]))));
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g), body = mk("g", {}, g), str = mk("g", {}, g);
  const [r0, r1] = rings(0, 0, W, D, 3, 3);
  put(solid(body), prism(P, front, r0, r1, 0, H));
  // the striker: a flat steel bar with a curled grip, lying inside
  const bar = [];
  for (const x of [14, 52]) for (const y of [16, 26]) for (const z of [H - 3, H + 1]) bar.push([x, y, z]);
  mk("path", { d: H2(bar) }, str);
  mk("path", { d: H2([[52, 16, H - 3], [52, 26, H - 3], [60, 16, H + 5], [60, 26, H + 5], [56, 16, H + 8], [56, 26, H + 8]]) }, str);
  const lid = mk("path", { class: "sil hi" }, lidG), seam = mk("path", { class: "nf lo" }, lidG);
  const th = tween(REST);
  let last = NaN;
  // a point of the lid: v from the hinge toward the front, w up through its thickness
  const L = (x, v, w, a) => [x, v * Math.cos(a) - w * Math.sin(a), H + v * Math.sin(a) + w * Math.cos(a)];
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const x of [0, W]) for (const v of [0, D]) for (const w of [0, T]) pts.push(L(x, v, w, a));
    lid.setAttribute("d", H2(pts));
    seam.setAttribute("d", poly([L(0, D, T, a), L(W, D, T, a), L(W, 0, T, a), L(0, 0, T, a)].map((p) => P(...p))));
    if (deg > 70) g.prepend(lidG); else g.append(lidG);
  }
  const B = register(stage, (_dt, now) => { draw(tval(th, now)); return !tdone(th, now); });
  bag.add(B.unregister);
  const mid = P(W / 2, D / 2, H / 2);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(th, on ? open : REST, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.hypot(sx - mid[0], sy - mid[1]) < 120), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act) { tset(th, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "tinderbox",
  means: "A tin tinder box: the pointer swings its hinged lid open on the back hinge to show the steel striker inside.",
  rules: [1, 3, 5, 6],
  range: [60, 105, 120],
  tour: [[153, 192], [299, 196], [90, 231], null],
  mount,
});

boxkite.code:
/**
 * Box kite: two square cloth cells on four spars, flying on a dashed line
 * tethered to a peg. The pointer is the wind: the kite turns to face it and
 * rises on its line. At rest it hangs a little askew, its top cell bright.
 * The slider is how quickly it follows (a stiffer or softer spring).
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const H = 18, Z0 = 22, CELL = 16, GAP = 18, REST = 0.35, RISE = 14;
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-H - 4, -H - 4, Z0], [H + 4, H + 4, Z0], [-H, H, Z0 + 2 * CELL + GAP + RISE], [0, 70, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  place(flatDot(g, C, 1.6, "dot m"), P(0, 70, 0));
  const line = mk("path", { class: "dash nf" }, g);
  const spars = mk("path", { class: "nf lo" }, g);
  const low = solid(g), high = solid(g);
  const [R, I] = rings(-H, -H, H, H, 2.5, 1.2);
  const ang = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  const up = spring(0, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let dA = NaN, dZ = NaN;

  function draw() {
    if (Math.abs(ang.x - dA) < 1e-4 && Math.abs(up.x - dZ) < 1e-3) return;
    dA = ang.x; dZ = up.x;
    const z = Z0 + up.x, r = turn(R, ang.x), i = turn(I, ang.x);
    put(low, prism(P, front, r, i, z, z + CELL));
    put(high, prism(P, front, r, i, z + CELL + GAP, z + 2 * CELL + GAP));
    const c = Math.cos(ang.x), s = Math.sin(ang.x);
    let d = "";
    for (const [u, v] of [[-H, -H], [H, -H], [H, H], [-H, H]]) {
      const x = u * c - v * s, y = u * s + v * c;
      d += seg(P(x, y, z - 4), P(x, y, z + 2 * CELL + GAP + 4));
    }
    spars.setAttribute("d", d);
    line.setAttribute("d", seg(P(0, 70, 0), P(H * (c - s), H * (s + c), z)));
  }

  const B = register(stage, (dt) => {
    const m1 = stepS(ang, dt), m2 = stepS(up, dt);
    draw();
    return m1 || m2;
  });
  bag.add(B.unregister);

  function aim(over) {
    if (over) {
      const t = Math.atan2(over[1], over[0]);
      ang.t = ang.t + (t - ang.t) - Math.PI / 2 * Math.round((t - ang.t) / (Math.PI / 2)) + Math.PI / 4;
      up.t = RISE;
      read.textContent = Math.round(((t * 180) / Math.PI + 360) % 360) + "°";
    } else { ang.t = REST; up.t = 0; read.textContent = "rest"; }
    high.sil.classList.toggle("hi", !over);
    low.sil.classList.toggle("hi", !!over);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      aim(r > 120 ? null : [x, y]);
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  draw();
  return {
    set: (v) => { for (const sp of [ang, up]) { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "boxkite",
  means: "A box kite on its line: it turns its corner into the pointer's wind and rises, its lower cell bright.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[330, 205], [101, 219], [253, 295], null],
  mount,
});

scrollcase.code:
/**
 * Scroll case: a tall round tube with a slip-on cap, a rolled scroll inside
 * and a second scroll lying loose beside it. The pointer over the case lifts
 * its cap away and slides the scroll up out of the tube. At rest the cap sits
 * ajar, bright. The slider is how far the scroll comes out.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 22, BH = 52, CH = 15, SR = 16, LIFT = 30, AJAR = 5, TOP = BH + 2 + LIFT * 1.2 + 4 + CH;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-R, -R, 0], [R, R, 0], [-R, R, TOP], [R, -R, TOP], [95, 8, 0], [40, 22, 18]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, R), disc(0, 0, R - 1.6), 0, BH));
  mk("path", { class: "nf lo", d: ringAt(P, disc(0, 0, R, 40), 14).filter((_, i) => i > 4 && i < 24).reduce((s, p, i, a) => i ? s + seg(a[i - 1], p) : s, "") }, g);
  const scroll = solid(g), cap = solid(g);
  // a loose scroll lying beside the case, along x
  const lie = [], end = [];
  for (let i = 0; i < 24; i++) {
    const t = (i / 24) * Math.PI * 2, y = 14 + 7 * Math.cos(t), z = 7 + 7 * Math.sin(t);
    lie.push(P(40, y, z), P(92, y, z));
    end.push(P(92, y, z));
  }
  mk("path", { class: "sil", d: poly(hull(lie)) }, g);
  mk("path", { class: "nf lo", d: poly(end) }, g);

  const lift = tween(AJAR);
  let last = NaN;
  function draw(l) {
    if (l === last) return;
    last = l;
    const k = clampK(l), s = 2 + k * LIFT * reach;
    put(scroll, prism(P, front, disc(0, 0, SR), disc(0, 0, SR - 4), BH - 2, BH + s));
    const z = (BH - 6 + AJAR) * (1 - k) + (BH + s + 2) * k;
    put(cap, prism(P, front, disc(0, 0, R + 1.6), disc(0, 0, R), z, z + CH));
  }
  const clampK = (l) => Math.max(0, (l - AJAR) / (LIFT - AJAR));

  const B = register(stage, (_dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, BH / 2);
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(lift, o ? LIFT : AJAR, performance.now(), 0);
    cap.sil.classList.toggle("hi", !o);
    scroll.sil.classList.toggle("hi", o);
    read.textContent = o ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: (p) => set(Math.abs(p[0] - mid[0]) < 60 && Math.abs(p[1] - mid[1]) < 120),
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "scrollcase",
  means: "A scroll case: the pointer lifts its cap away and slides the rolled scroll up out of the tube.",
  rules: [1, 5, 8, 9],
  range: [0.5, 1, 1.2],
  tour: [[169, 119], [169, 200], [178, 150], null],
  mount,
});

rotaryphone.code:
/**
 * Rotary dial: a telephone base with a finger plate of ten holes. The pointer
 * picks a hole by where it rests; the plate winds round to the finger stop by
 * that digit's distance. At rest one hole is bright and the plate sits a
 * little wound. The slider is how far the plate winds.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid, rad,
} = HL;

const CX = 45, CY = 45, BZ = 14, DZ = 18, R = 34, HR = 23, HOLE = 6.2, FAV = 3, REST = 0.35;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const holeA = (k) => rad(120 + k * 27);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value / 100;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [90, 90, 0], [90, 0, 0], [0, 90, 0], [CX, CY, DZ + 4]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 90, 90, 18, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  put(solid(g), prism(P, front, disc(CX, CY, R + 3), disc(CX, CY, R + 1.5), BZ, BZ + 1.5));
  const plate = solid(g);
  put(plate, prism(P, front, disc(CX, CY, R), disc(CX, CY, R - 1.5), BZ + 1.5, DZ));
  const holes = [], wells = [];
  for (let k = 0; k < 10; k++) {
    wells.push(mk("path", { class: "nf lo" }, g));
    holes.push(mk("path", { class: "nf" }, g));
  }
  put(solid(g), prism(P, front, disc(CX, CY, 11), disc(CX, CY, 9.5), DZ, DZ + 2.5));
  // the finger stop, fixed, past the last hole
  const sa = rad(40), sx = CX + (R - 2) * Math.cos(sa), sy = CY + (R - 2) * Math.sin(sa);
  mk("path", { d: poly(hull([...ringAt(P, disc(sx, sy, 2.2, 12), DZ), ...ringAt(P, disc(sx, sy, 2.2, 12), DZ + 6)])) }, g);

  const turn = tween(REST);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    for (let k = 0; k < 10; k++) {
      const a = holeA(k) - t, x = CX + HR * Math.cos(a), y = CY + HR * Math.sin(a);
      holes[k].setAttribute("d", poly(ringAt(P, disc(x, y, HOLE, 24), DZ)));
      wells[k].setAttribute("d", poly(ringAt(P, disc(x, y, HOLE, 24), BZ + 2)));
    }
  }
  const B = register(stage, (_dt, now) => { draw(tval(turn, now)); return !tdone(turn, now); });
  bag.add(B.unregister);

  function hit([px, py]) {
    const [x, y] = unproj(C, px, py, DZ);
    let best = -1, bd = 9;
    for (let k = 0; k < 10; k++) {
      const a = holeA(k), d = Math.hypot(CX + HR * Math.cos(a) - x, CY + HR * Math.sin(a) - y);
      if (d < bd) { bd = d; best = k; }
    }
    return best;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const k = a < 0 ? FAV : a;
    tset(turn, a < 0 ? REST : -(rad(40 + 360) - holeA(a)) * amt, performance.now(), 0);
    holes.forEach((h, i) => h.classList.toggle("hi", i === k));
    read.textContent = a < 0 ? "rest" : "dial " + ((a + 1) % 10);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v / 100; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "rotaryphone",
  means: "A rotary telephone dial: the hole under the pointer winds the finger plate round towards the stop, further for higher digits.",
  rules: [1, 3, 4, 5],
  range: [30, 100, 100],
  tour: [[142, 134], [196, 112], [240, 148], null],
  mount,
});

drawbridge.code:
/**
 * Drawbridge: a castle gatehouse wall with battlements and a plank bridge
 * hinged at the foot of its gate, held up by two chains. The pointer in front
 * of the wall lowers the bridge across the ground; leaving winds it back up.
 * At rest the bridge hangs half raised, bright. The slider is how far it drops.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 90, T = 16, H = 56, G0 = 30, G1 = 60, GH = 36, L = 40, TH = 3, REST = 1.0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let drop = value / 100;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 0], [W, T + L, 0], [W, 0, 0], [0, T + L, 0], [0, 0, H + 8], [W, T, H + 8]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [r0, i0] = rings(0, 0, W, T, 1, 1);
  put(solid(g), prism(P, front, r0, i0, 0, H));
  for (const x of [0, 26, 52, 78]) { const [r, i] = rings(x, 0, x + 12, T, 1, 1); put(solid(g), prism(P, front, r, i, H, H + 8)); }
  const arch = [];
  for (let i = 0; i <= 12; i++) { const a = (i / 12) * Math.PI; arch.push(P((G0 + G1) / 2 + ((G1 - G0) / 2) * Math.cos(a), T, GH - 15 + 15 * Math.sin(a))); }
  mk("path", { d: poly([P(G1, T, 0), ...arch, P(G0, T, 0)]), class: "nf" }, g);
  const chains = mk("path", { class: "nf lo" }, g), plank = mk("path", { class: "sil" }, g);

  const th = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a), pts = [];
    for (const x of [G0, G1]) for (const [d, n] of [[0, 0], [L, 0], [0, TH], [L, TH]]) pts.push(P(x, T + d * c - n * s, 1 + d * s + n * c));
    plank.setAttribute("d", poly(hull(pts)));
    const ty = T + (L - 2) * c, tz = 1 + (L - 2) * s + TH;
    chains.setAttribute("d", seg(P(G0 + 2, T, GH + 10), P(G0 + 2, ty, tz)) + seg(P(G1 - 2, T, GH + 10), P(G1 - 2, ty, tz)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(th, now)); return !tdone(th, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(th, a < 0 ? REST : 1.45 - 1.43 * drop, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "down";
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    setActive(x > -20 && x < W + 20 && y > T - 4 && y < T + L + 20 ? 1 : -1);
  }
  plank.classList.add("hi");
  setActive(-1);
  bag.add(pointer(stage, { move, leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { drop = v / 100; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "drawbridge",
  means: "A castle gate whose plank bridge, held on two chains, lowers across the ground when the pointer comes in front of it.",
  rules: [1, 3, 4, 5],
  range: [30, 100, 100],
  tour: [[179, 238], [240, 269], [200, 250], null],
  mount,
});

portcullis.code:
/**
 * Portcullis: a gatehouse of two towers and a lintel block, an iron grid gate hung between them. The pointer over the gate winches the grid up into the lintel; leaving lets it drop. At rest it hangs a little raised, its bottom rail bright. The slider is how far it rises.
 */
const { Cam, fit, proj, hull, poly, open, fillet, spring, stepS, disposer, mk, pointer, register } = HL;

const bx = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x0, y1, z0], [x1, y1, z0], [x0, y0, z1], [x1, y0, z1], [x0, y1, z1], [x1, y1, z1]];
const rotY = (pts, cx, cz, a) => pts.map(([x, y, z]) => { const u = x - cx, w = z - cz, c = Math.cos(a), s = Math.sin(a); return [cx + u * c - w * s, y, cz + u * s + w * c]; });
const up = (pts, d) => pts.map(([x, y, z]) => [x, y, z + d]);
const rad = (d) => (d * Math.PI) / 180;
const A0 = 0, AR = 8, A1 = 50;
function PARTS(L) {
  const out = [];
  for (let i = 0; i < 9; i++) { const x = 26 + i * 11; out.push({ k: "s", cls: "sil", pts: up([[x, 8, 0], [x + 3, 8, 0], [x, 12, 0], [x + 3, 12, 0], [x + 1.5, 10, -5], ...bx(x, 8, 4, x + 3, 12, 88).slice(4)], L) }); }
  [16, 40, 64, 86].forEach((z, i) => out.push({ k: "s", cls: i === 0 ? "sil hi" : "sil", pts: up(bx(24, 7, z, 116, 13, z + 4), L) }));
  out.push({ k: "s", cls: "sil", pts: bx(22, 0, 92, 118, 20, 140) });
  out.push({ k: "s", cls: "sil", pts: bx(0, 0, 0, 22, 20, 146) });
  out.push({ k: "s", cls: "sil", pts: bx(118, 0, 0, 140, 20, 146) });
  out.push({ k: "l", cls: "nf lo", pts: [[[22, 20, 100], [118, 20, 100]], [[2, 20, 120], [20, 20, 120]], [[120, 20, 120], [138, 20, 120]]] });
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value / 100;
  const ext = [];
  for (const a of [A0, AR, A1]) for (const p of PARTS(a)) (p.k === "s" ? [p.pts] : p.pts).forEach((l) => ext.push(...l));
  let C = Cam(45, 0.5, 1);
  fit(C, ext, 200, 164);
  let P = proj(C);
