keepnet.code:
/**
 * Landing net: a long handle ending in a round hoop, a mesh bag hanging from
 * the hoop. Over the net, it scoops: the handle pitches up about its grip and
 * the hoop rises with the bag swinging under it. At rest the net lies low,
 * its hoop bright. The slider is how high it scoops.
 *
 * The pattern: one part answering on the discrete clock (cloches).
 */
const {
  Cam, fit, hull, open, poly, proj, seg, tset, tval, tdone, tween, unproj, clamp,
  disposer, mk, pointer, register, rad,
} = HL;

const GX = 66, GZ = 10, LH = 52, R = 32, BAG = 38, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[GX, -R, 0], [GX - LH - 2 * R, R, -BAG + 10], [GX - LH - 2 * R, -R, 0], [GX - (LH + 2 * R) * 0.6, 0, GZ + (LH + 2 * R) * 0.8], [GX - LH - 2 * R, 0, GZ + (LH + 2 * R) * 0.75], [GX - LH - R, 0, -12], [GX, R, 0]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const net = mk("path", { class: "sil" }, g), mesh = mk("path", { class: "nf lo" }, g);
  const hoop = mk("path", { class: "nf hi" }, g);
  const handle = mk("path", { class: "sil" }, g), grip = mk("path", { class: "nf lo" }, g);

  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), dx = -Math.cos(a), dz = Math.sin(a);
    const at = (s, y) => [GX + s * dx, y, GZ + s * dz];
    const c = at(LH + R, 0), rim = [];
    for (let i = 0; i < 40; i++) { const t = (i / 40) * Math.PI * 2; rim.push(at(LH + R + R * Math.cos(t), R * Math.sin(t))); }
    const bot = [c[0] + 4, c[1], c[2] - BAG], low = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; low.push(P(bot[0] + 6 * Math.cos(t), bot[1] + 6 * Math.sin(t), bot[2])); }
    const sp = rim.map((q) => P(...q));
    net.setAttribute("d", poly(hull(sp.concat(low))));
    let m = "";
    for (let i = 0; i < 40; i += 5) if (rim[i][0] + rim[i][1] >= c[0] + c[1] - 4) m += seg(sp[i], P(...bot));
    mesh.setAttribute("d", m + poly(rim.map((q) => P(q[0] + (bot[0] - q[0]) * 0.5, q[1] * 0.55, q[2] + (bot[2] - q[2]) * 0.5))));
    hoop.setAttribute("d", poly(sp));
    const hp = [];
    for (const s of [0, LH]) for (let i = 0; i < 10; i++) { const t = (i / 10) * Math.PI * 2, r = s ? 1.6 : 2.6; hp.push(P(GX + s * dx - r * Math.sin(t) * dz, r * Math.cos(t), GZ + s * dz + r * Math.sin(t) * dx)); }
    handle.setAttribute("d", poly(hull(hp)));
    grip.setAttribute("d", seg(P(...at(16, -2.6)), P(...at(16, 2.6))));
  }

  const ang = tween(REST);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? top : REST, performance.now(), 0);
    read.textContent = a ? "scoop" : "rest";
    B.wake();
  }
  setActive(false);
  const over = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, GZ); return x < GX + 8 && x > GX - LH - 2 * R - 8 && Math.abs(y) < R + 10; };
  bag.add(pointer(stage, { move: (p) => setActive(over(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 20, 50); if (act) { tset(ang, top, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "keepnet",
  means: "A landing net on a long handle: over it, the net scoops up about its grip, the hoop rising with the mesh bag swinging under it.",
  rules: [1, 4, 5, 8],
  range: [20, 38, 50],
  tour: [[153, 182], [200, 230], [128, 150], null],
  mount,
});

crabtrap.code:
/**
 * Crab pot: a square wire cage with a funnel mouth on one side and a hinged
 * mesh lid. Over the pot, the lid swings open on its back hinge to show the
 * bait cup inside. At rest the lid stands ajar, bright. The slider is how far
 * the lid opens.
 *
 * The pattern: one part on a hinge (cloches, lifted to a swing).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, rrect, ringAt, seg, tset, tval, tdone, tween, unproj,
  disposer, mk, pointer, put, register, solid, rad,
} = HL;

const W = 70, D = 70, H = 30, T = 3, REST = 14;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, H + D * 0.75], [W, 0, H + D * 0.75], [0, D, H + T]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  // wire mesh on the near face, a funnel mouth on the right face
  let mesh = "";
  for (let x = 14; x < W; x += 14) mesh += seg(P(x, D, 3), P(x, D, H - 3));
  mesh += seg(P(4, D, H / 2), P(W - 4, D, H / 2));
  const mouth = [], throat = [];
  for (let i = 0; i < 24; i++) {
    const t = (i / 24) * Math.PI * 2;
    mouth.push(P(W, D / 2 + 11 * Math.cos(t), H / 2 + 9 * Math.sin(t)));
    throat.push(P(W, D / 2 + 4 * Math.cos(t), H / 2 + 3.5 * Math.sin(t)));
  }
  mk("path", { d: mesh, class: "nf lo" }, g);
  mk("path", { d: poly(mouth), class: "nf" }, g);
  mk("path", { d: poly(throat) + mouth.filter((_, i) => i % 6 === 0).map((m, i) => seg(m, throat[i * 6])).join(""), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(W / 2, D / 2, 9), H)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(W / 2, D / 2, 5), H + 2)), class: "nf lo" }, g);

  const lr = rrect(0, 0, W, D, 6, 4), li = rrect(3, 3, W - 3, D - 3, 3, 4);
  const lid = mk("g", {}, g);
  const lsil = mk("path", { class: "sil hi" }, lid), lcr = mk("path", { class: "nf lo" }, lid);
  const lmesh = mk("path", { class: "nf lo" }, lid);
  const L = (a) => (u, v, h) => P(u, v * Math.cos(a) - h * Math.sin(a), H + v * Math.sin(a) + h * Math.cos(a));
  const area = (pts) => pts.reduce((s, p, i) => { const q = pts[(i + 1) % pts.length]; return s + p[0] * q[1] - q[0] * p[1]; }, 0);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const f = L(rad(deg)), lo = lr.map((q) => f(q.u, q.v, 0)), hi = lr.map((q) => f(q.u, q.v, T));
    lsil.setAttribute("d", poly(hull(lo.concat(hi))));
    const up = area(hi) * area(lr.map((q) => P(q.u, q.v, 0))) > 0, h = up ? T : 0;
    lcr.setAttribute("d", poly(li.map((q) => f(q.u, q.v, h))));
    let m = "";
    for (let u = 17.5; u < W; u += 17.5) m += seg(f(u, 4, h), f(u, D - 4, h));
    for (let v = 17.5; v < D; v += 17.5) m += seg(f(4, v, h), f(W - 4, v, h));
    lmesh.setAttribute("d", m);
  }

  const ang = tween(REST);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const inside = (z, sx, sy) => { const [x, y] = unproj(C, sx, sy, z); return x > -6 && x < W + 6 && y > -6 && y < D + 6; };
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? maxA : REST, performance.now(), 0);
    read.textContent = a ? "lid" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(inside(H, sx, sy) || inside(0, sx, sy)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (act) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "crabtrap",
  means: "A wire crab pot with a funnel mouth: over the pot, its hinged mesh lid swings open on the back hinge to show the bait cup.",
  rules: [1, 4, 5, 8],
  range: [40, 70, 80],
  tour: [[200, 192], [200, 250], [160, 170], null],
  mount,
});

sundae.code:
/**
 * Sundae glass: a footed glass holding two scoops, a cherry on top and a
 * long spoon in the top scoop. The pointer over the glass digs the spoon
 * in: it lifts the top scoop and its cherry up and out over the rim. At
 * rest the spoon sits just in, the scoop bright. The slider is the reach.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, unproj,
} = HL;

const BZ = 52, REST = 0.12;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  const P0 = (x, y, z) => [x, y, z];
  fit(C, [P0(-26, -26, 0), P0(26, 26, 0), P0(26, -26, 0), P0(-26, 26, 0), P0(0, 0, 100), P0(44, -2, 104), P0(70, 26, 110)], 200, 162);
  const P = proj(C), front = facing(C);
  const ball = (x, y, z, r) => {
    const pts = [];
    for (let i = 0; i <= 8; i++) { const a = (i / 8) * Math.PI; pts.push(...ringAt(P, disc(x, y, r * Math.sin(a) + 0.3, 24), z - r * Math.cos(a))); }
    return poly(hull(pts));
  };
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 17), disc(0, 0, 15), 0, 3));
  put(solid(g), prism(P, front, disc(0, 0, 3, 16), disc(0, 0, 2, 16), 3, 24));
  const bowl = solid(g);
  bowl.sil.setAttribute("d", poly(hull(ringAt(P, disc(0, 0, 9), 22).concat(ringAt(P, disc(0, 0, 25), BZ)))));
  bowl.cr.setAttribute("d", poly(ringAt(P, disc(0, 0, 23), BZ)));
  const dome = [];
  for (let i = 0; i <= 6; i++) { const a = (i / 6) * (Math.PI / 2); dome.push(...ringAt(P, disc(0, 0, 23 * Math.cos(a) + 0.3), BZ + 18 * Math.sin(a))); }
  mk("path", { d: poly(hull(dome)) }, g);
  const top = mk("path", { class: "sil hi" }, g), cherry = mk("path", {}, g), spoon = mk("path", { class: "nf" }, g);
  const s = tween(REST);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const x = 40 * t, y = -6 * t, z = BZ + 26 + 16 * t;
    top.setAttribute("d", ball(x, y, z, 15));
    cherry.setAttribute("d", ball(x + 1, y - 1, z + 18, 4.5));
    spoon.setAttribute("d", seg(P(x + 6, y + 8, z - 4), P(x + 26, y + 30, z + 18)) + seg(P(x + 26, y + 30, z + 18), P(x + 30, y + 34, z + 22)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(s, now)); return !tdone(s, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(s, on ? reach : REST, performance.now(), 0);
    read.textContent = on ? "scoop" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => {
    const [x, y] = unproj(C, sx, sy, BZ);
    return Math.hypot(x, y) < 34;
  };
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { tset(s, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

