rosette.code:
/**
 * Rosette: a prize rosette standing upright, a pleated outer ring, a smaller
 * pleated ring inside it and a round button at the centre, with two ribbon
 * tails hanging below. The pointer spins the pleats, the inner ring against
 * the outer, and swings the tails toward it. At rest the button is bright.
 * The slider is how far the pleats spin.
 */
const {
  Cam, fit, poly, proj, clamp, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const R1 = 44, R2 = 31, RB = 17, TL = 70;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.02);
  const s2 = Math.SQRT1_2, Z0 = TL + 6;
  const W = (u, v, t = 0) => [u * s2 + t * s2, -u * s2 + t * s2, Z0 + v];
  fit(C, [W(-R1 - 4, R1 + 4), W(R1 + 4, R1 + 4), W(-R1 - 4, -TL - 6), W(R1 + 4, -TL - 6)], 200, 162);
  const P = proj(C), Q = (u, v, t) => P(...W(u, v, t));
  const g = mk("g", {}, svg);
  const tails = [-1, 1].map(() => mk("path", { class: "sil" }, g));
  const tcr = [-1, 1].map(() => mk("path", { class: "nf lo" }, g));
  const back = mk("path", { class: "lo" }, g), outer = mk("path", { class: "sil" }, g), oc = mk("path", { class: "nf lo" }, g);
  const inner = mk("path", { class: "sil" }, g), ic = mk("path", { class: "nf lo" }, g);
  const btn = mk("path", { class: "sil" }, g), bc = mk("path", { class: "nf lo" }, g);
  const star = (n, ro, ri, a, t = 0) => { const p = []; for (let i = 0; i < 2 * n; i++) { const r = i % 2 ? ri : ro, th = a + (i * Math.PI) / n; p.push(Q(r * Math.cos(th), r * Math.sin(th), t)); } return p; };
  const ring = (r, t = 0) => Array.from({ length: 36 }, (_, i) => { const th = (i / 36) * 2 * Math.PI; return Q(r * Math.cos(th), r * Math.sin(th), t); });
  const REST = 0.12;
  const sp = spring(REST);
  let last = NaN;

  function draw(a) {
    const k = Math.round(a * 400) / 400;
    if (k === last) return;
    last = k;
    [-1, 1].forEach((sd, i) => {
      const sw = sd * 0.32 + k * 0.5, ca = Math.cos(sw), sa = Math.sin(sw);
      const loc = [[-8, 0], [8, 0], [9, -TL], [0, -TL + 10], [-9, -TL]];
      const pts = loc.map(([x, y]) => Q(x * ca - y * sa, x * sa + y * ca, -2));
      tails[i].setAttribute("d", poly(pts));
      tcr[i].setAttribute("d", poly(loc.slice(0, 2).concat([[6, -TL + 6], [-6, -TL + 6]]).map(([x, y]) => Q(x * 0.7 * ca - y * 0.92 * sa, x * 0.7 * sa + y * 0.92 * ca, -2))));
    });
    back.setAttribute("d", poly(star(18, R1, R1 - 7, k * 2 + 0.1, -3)));
    outer.setAttribute("d", poly(star(18, R1, R1 - 7, k * 2)));
    oc.setAttribute("d", poly(ring(R1 - 10)));
    inner.setAttribute("d", poly(star(14, R2, R2 - 5, -k * 3 + 0.2, 1.5)));
    ic.setAttribute("d", poly(ring(R2 - 8, 1.5)));
    btn.setAttribute("d", poly(ring(RB, 3)));
    bc.setAttribute("d", poly(ring(RB - 4, 3)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const mid = Q(0, 0, 0);
  let act = null;
  function aim(p) {
    const on = !!p && Math.abs(p[0] - mid[0]) < 130 && p[1] > mid[1] - 110 && p[1] < mid[1] + 170;
    sp.t = on ? clamp((p[0] - mid[0]) / 90, -1, 1) * reach : REST;
    if (on !== act) { act = on; btn.classList.toggle("hi", !on); outer.classList.toggle("hi", on); }
    read.textContent = on ? Math.round((sp.t * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "rosette",
  means: "A prize rosette: the pointer spins its pleated rings against each other and swings the ribbon tails toward it.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[125, 82], [275, 90], [200, 235], null],
  mount,
});

plaque.code:
/**
 * Plaque stand: a tall award plaque standing in a slot on a weighted base.
 * The plaque turns on its base to face the pointer, following it as it
 * moves across. At rest it stands turned a little, bright. The slider is
 * how far it can turn.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BW = 100, BD = 46, BH = 14, PW = 74, PH = 96, PT = 3.5;
const CX = BW / 2, CY = BD / 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [BW, BD, 0], [BW, 0, 0], [0, BD, 0], [CX - 40, CY, BH + PH], [CX + 40, CY, BH + PH], [CX, CY - 40, BH + PH], [CX, CY + 40, BH + PH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, BW, BD, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  const [sr] = rings(CX - PW / 2 - 4, CY - 5, CX + PW / 2 + 4, CY + 5, 3, 1);
  const slot = mk("path", { class: "nf lo" }, g);
  slot.setAttribute("d", poly(sr.map((q) => P(q.u, q.v, BH))));
  const pg = mk("g", {}, g);
  const sil = mk("path", { class: "sil" }, pg), face = mk("path", { class: "nf lo" }, pg), boss = mk("path", { class: "nf" }, pg), plate = mk("path", { class: "nf lo" }, pg);

  const outer = rrect(-PW / 2, 0, PW / 2, PH, 10, 4), inner = rrect(-PW / 2 + 6, 6, PW / 2 - 6, PH - 6, 6, 4);
  const medal = rrect(-13, PH - 48, 13, PH - 22, 13, 6), bar = rrect(-20, 14, 20, 26, 3, 3);
  const at = (q, yaw, t) => { const c = Math.cos(yaw), s = Math.sin(yaw); return P(CX + q.u * c - t * s, CY + q.u * s + t * c, BH + q.v); };
  const area = (p) => { let s = 0; for (let i = 0; i < p.length; i++) { const a = p[i], b = p[(i + 1) % p.length]; s += a[0] * b[1] - b[0] * a[1]; } return s; };
  const s0 = Math.sign(area(inner.map((q) => at(q, 0, PT))));
  const REST = 18;
  const sp = spring(REST);
  let last = NaN;

  function draw(deg) {
    const d = Math.round(deg * 20) / 20;
    if (d === last) return;
    last = d;
    const yaw = (d * Math.PI) / 180;
    sil.setAttribute("d", poly(hull(outer.map((q) => at(q, yaw, -PT)).concat(outer.map((q) => at(q, yaw, PT))))));
    const ft = Math.sign(area(inner.map((q) => at(q, yaw, PT)))) === s0 ? PT : -PT;
    face.setAttribute("d", poly(inner.map((q) => at(q, yaw, ft))));
    const ft2 = ft + Math.sign(ft) * 1.6;
    boss.setAttribute("d", poly(hull(medal.map((q) => at(q, yaw, ft)).concat(medal.map((q) => at(q, yaw, ft2))))));
    plate.setAttribute("d", poly(bar.map((q) => at(q, yaw, ft))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const mid = P(CX, CY, BH + PH / 2);
  let act = null;
  function aim(p) {
    const on = !!p && Math.abs(p[0] - mid[0]) < 150 && Math.abs(p[1] - mid[1]) < 130;
    sp.t = on ? clamp(((p[0] - mid[0]) / 110) * reach, -reach, reach) : REST;
    if (on !== act) { act = on; sil.classList.toggle("hi", !on); boss.classList.toggle("hi", on); }
    read.textContent = on ? Math.round(sp.t) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "plaque",
  means: "An award plaque standing in a weighted base: it turns in its slot to face the pointer as the pointer moves across.",
  rules: [1, 3, 5, 8],
  range: [20, 50, 70],
  tour: [[151, 123], [255, 130], [200, 150], null],
  mount,
});

wateringcan.code:
/**
 * Watering can: a can with a long spout and a rose at its tip, standing on
 * the ground. The pointer over the can tips it forward on its front edge to
 * pour, and drops fall from the rose. At rest it stands leaning a little,
 * the rose bright. The slider is how far it tips.
 */
const {
  Cam, fit, facing, hull, poly, proj, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, place, register,
} = HL;

const W = 52, D = 36, H = 50, PX = W, Y0 = D / 2;
const S0 = [W - 4, 10], S1 = [W + 44, 56], RR = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 2.28);
  const tilt = (a) => { const c = Math.cos(a), s = Math.sin(a); return ([x, y, z]) => [PX + (x - PX) * c + z * s, y, -(x - PX) * s + z * c]; };
  const len = Math.hypot(S1[0] - S0[0], S1[1] - S0[1]), dx = (S1[0] - S0[0]) / len, dz = (S1[1] - S0[1]) / len;
  const rose = (off) => Array.from({ length: 24 }, (_, i) => { const t = (i / 24) * 2 * Math.PI; return [S1[0] + dx * off - dz * RR * Math.sin(t), Y0 + RR * Math.cos(t), S1[1] + dz * off + dx * RR * Math.sin(t)]; });
  const ext = [[0, 0, 0], [W, D, 0], [0, D, H + 18], [W, 0, H], [S1[0] + 4, Y0, S1[1] + RR], [S1[0] + 4, Y0, S1[1] - RR]];
  const drops = [[8, -6, -10], [16, 4, -18], [24, -2, -26], [12, 7, -32], [20, -8, -38]];
  const fp = [];
  for (const a of [0.1, 0.75]) { const T = tilt(a); for (const p of ext) fp.push(T(p)); }
  { const tp = tilt(0.75)([S1[0] + dx * 4, Y0, S1[1] + dz * 4]); for (const [ox, oy, oz] of drops) fp.push([tp[0] + ox, tp[1] + oy, tp[2] + oz * 0.8]); }
  fit(C, fp, 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const body = mk("path", { class: "sil" }, g), cre = mk("path", { class: "nf lo" }, g), hand = mk("path", {}, g);
  const spout = mk("path", { class: "sil" }, g), rs = mk("path", { class: "sil" }, g), rf = mk("path", { class: "nf lo" }, g);
  const dots = drops.map(() => mk("circle", { class: "dot", r: 0 }, g));
  const foot = rrect(0, 0, W, D, 10, 4), top = rrect(3, 3, W - 3, D - 3, 8, 4);
  const arc = (r) => Array.from({ length: 13 }, (_, i) => { const t = (i / 12) * Math.PI; return [W / 2 - r * Math.cos(t), Y0, H - 4 + r * Math.sin(t) * 0.8]; });
  const circ3 = (cx, cz, r) => Array.from({ length: 16 }, (_, i) => { const t = (i / 16) * 2 * Math.PI; return [cx + r * Math.cos(t), Y0 + r * Math.sin(t), cz]; });
  const tw = tween(0.1);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const T = tilt(a), Q = (p) => P(...T(p));
    body.setAttribute("d", poly(hull(foot.map((q) => Q([q.u, q.v, 0])).concat(foot.map((q) => Q([q.u, q.v, H]))))));
    cre.setAttribute("d", poly(top.map((q) => Q([q.u, q.v, H]))));
    hand.setAttribute("d", poly(arc(22).concat(arc(17).reverse()).map(Q)));
    spout.setAttribute("d", poly(hull(circ3(S0[0], S0[1], 4.5).concat(circ3(S1[0] - dx * 2, S1[1] - dz * 2, 2.6)).map(Q))));
    rs.setAttribute("d", poly(hull(rose(0).concat(rose(4)).map(Q))));
    rf.setAttribute("d", poly(rose(4).map((p) => { const c = [S1[0] + dx * 4, Y0, S1[1] + dz * 4]; return Q([c[0] + (p[0] - c[0]) * 0.7, c[1] + (p[1] - c[1]) * 0.7, c[2] + (p[2] - c[2]) * 0.7]); })));
    const k = Math.max(0, (a - 0.35) / 0.3);
    const tipW = T([S1[0] + dx * 4, Y0, S1[1] + dz * 4]);
    drops.forEach(([ox, oy, oz], i) => { const on = k > i / drops.length; dots[i].setAttribute("r", on ? 1.8 : 0); place(dots[i], P(tipW[0] + ox, tipW[1] + oy, tipW[2] + oz * 0.8)); });
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  rs.classList.add("hi");

  const mid = P(W / 2 + 20, Y0, H / 2);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? (tip * Math.PI) / 180 : 0.1, performance.now(), 0);
    read.textContent = on ? "pour" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => Math.abs(sx - mid[0]) < 130 && Math.abs(sy - mid[1]) < 100;
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; if (act) { tset(tw, (v * Math.PI) / 180, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "wateringcan",
  means: "A watering can with a long spout: the pointer tips it forward on its front edge and drops fall from the rose.",
  rules: [1, 3, 5, 6],
  range: [25, 40, 43],
  tour: [[130, 82], [236, 124], [165, 150], null],
  mount,
});

shears.code:
/**
 * Hedge shears: one pair lying flat, two long levers crossed at a bolt, blades
 * one way and grips the other. The pointer over them opens the blades wide.
 * At rest they are barely open, the upper blade bright.
 */
const { Cam, fit, facing, hull, open, poly, proj, rrect, ringAt, run, clamp, rad, spring, stepS, disposer, mk, pointer, put, solid } = HL;
const { register } = HL;

const REST = 10, OPEN = 52;
const rot = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };
const PARTS = [[rrect(4, -7, 104, 6, 5, 4), rrect(6, -5, 102, 4, 3.5, 4)], [rrect(-60, -3.5, -4, 3.5, 3, 4), rrect(-58, -2, -6, 2, 1.8, 4)], [rrect(-110, -6, -56, 6, 5.5, 4), rrect(-108, -4.2, -58, 4.2, 4, 4)]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 1.56);
  const A = rad(OPEN / 2);
  fit(C, [[104 * Math.cos(A), 104 * Math.sin(A), 0], [104 * Math.cos(A), -104 * Math.sin(A), 0], [-110 * Math.cos(A), 110 * Math.sin(A), 0], [-110 * Math.cos(A), -110 * Math.sin(A), 0], [0, 0, 12]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const levers = [0, 1].map(() => { const lg = mk("g", {}, g); return PARTS.map(() => solid(lg)); });
  const bolt = solid(g);
  const sp = spring(REST);
  let last = NaN;
  function slab(s, ring, inner, a, z0, z1) {
    const R = rot(ring, a), I = rot(inner, a);
    put(s, { sil: poly(hull(ringAt(P, R, z0).concat(ringAt(P, R, z1)))), crease: open(ringAt(P, run(I, front), z1)) });
  }
  function draw(deg) {
    if (deg === last) return; last = deg;
    const a = rad(deg / 2);
    levers.forEach((L, k) => { const s = k ? -a : a, z0 = k * 3.4; L.forEach((sol, j) => slab(sol, PARTS[j][0], PARTS[j][1], s, z0, z0 + 3)); });
    slab(bolt, rrect(-5, -5, 5, 5, 5, 4), rrect(-3.5, -3.5, 3.5, 3.5, 3.5, 4), 0, 6.4, 9);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const pts = [P(110, 40, 0), P(110, -40, 0), P(-115, 40, 0), P(-115, -40, 0)];
  const xs = pts.map((q) => q[0]), ys = pts.map((q) => q[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys) - 10, y1 = Math.max(...ys) + 10;
  let act = false;
  const target = () => REST + (OPEN - REST) * (0.4 + 0.6 * amt);
  function setA(on) {
    sp.t = on ? target() : REST;
    levers[1][0].sil.classList.toggle("hi", true);
    levers[0][0].sil.classList.toggle("hi", false);
    read.textContent = on ? "open " + Math.round(sp.t) + "°" : "rest";
    act = on; B.wake();
  }
  setA(false);
  bag.add(pointer(stage, { move: (p) => setA(p[0] > x0 && p[0] < x1 && p[1] > y0 && p[1] < y1), leave: () => setA(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { sp.t = target(); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "shears",
  means: "Hedge shears lying flat, two levers crossed at a bolt: the pointer over them opens the long blades wide.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[271, 201], [200, 160], [140, 128], null],
  mount,
});

gazebo.code:
/**
 * Garden arch: one rose arch, two posts under a round top, a low gate between
 * them. The pointer over it swings the gate open on its hinge. At rest the
 * gate stands just ajar, its frame bright.
 */
const { Cam, fit, open, poly, proj, facing, prism, rings, rad, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const Y = 44, H = 84, GW = 80, GH = 46, REST = 12, OPEN = 80;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-6, -Y - 4, 0], [GW, -Y, 0], [6, Y + 4, 0], [0, 0, H + Y + 6], [0, -Y, H + Y]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (y) => { const [r, i] = rings(-3.5, y - 3.5, 3.5, y + 3.5, 3, 1); put(solid(g), prism(P, front, r, i, 0, H)); };
  post(-Y);
  const arc = (r) => { const o = []; for (let i = 0; i <= 24; i++) { const a = Math.PI * (i / 24); o.push(P(0, -r * Math.cos(a), H + r * Math.sin(a))); } return o; };
  mk("path", { d: poly(arc(Y + 3.5).concat(arc(Y - 3.5).reverse())), class: "sil" }, g);
  const rungs = []; for (let k = 1; k < 8; k++) { const a = Math.PI * (k / 8); rungs.push(open([P(0, -(Y - 3.5) * Math.cos(a), H + (Y - 3.5) * Math.sin(a)), P(0, -(Y + 3.5) * Math.cos(a), H + (Y + 3.5) * Math.sin(a))])); }
  mk("path", { d: rungs.join(" "), class: "nf lo" }, g);
  post(Y);
  const gate = mk("path", { class: "sil" }, g), bars = mk("path", { class: "nf lo" }, g);
  const sp = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return; last = deg;
    const a = rad(deg), w = GW - 6;
    const at = (t, z) => P(t * w * Math.sin(a), -Y + 4 + t * w * Math.cos(a), z);
    gate.setAttribute("d", poly([at(0, 6), at(1, 6), at(1, GH), at(0.5, GH + 8), at(0, GH)]));
    const b = [];
    for (let k = 1; k < 8; k++) b.push(open([at(k / 8, 9), at(k / 8, GH - 2 + 8 * (1 - Math.abs(k / 8 - 0.5) * 2))]));
    b.push(open([at(0.02, 26), at(0.98, 26)]));
    bars.setAttribute("d", b.join(" "));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const pts = [P(0, -Y, 0), P(0, Y, 0), P(0, 0, H + Y), P(0, -Y, H), P(0, Y, H)];
  const xs = pts.map((q) => q[0]), ys = pts.map((q) => q[1]);
  const x0 = Math.min(...xs) - 8, x1 = Math.max(...xs) + 8, y0 = Math.min(...ys) - 6, y1 = Math.max(...ys) + 10;
  let act = false;
  const target = () => REST + (OPEN - REST) * (0.4 + 0.6 * amt);
  function setA(on) {
    sp.t = on ? target() : REST;
    gate.classList.toggle("hi", true);
    read.textContent = on ? "open " + Math.round(sp.t) + "°" : "rest";
    act = on; B.wake();
  }
  setA(false);
  bag.add(pointer(stage, { move: (p) => setA(p[0] > x0 && p[0] < x1 && p[1] > y0 && p[1] < y1), leave: () => setA(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { sp.t = target(); B.wake(); } }, destroy: bag.dispose };
}

