  name: "lavalamp",
  means: "A lava lamp with a wax blob in its glass: moving up the glass floats the blob up with it, stretching as it rises.",
  rules: [1, 3, 5, 6],
  range: [0.3, 1, 1],
  tour: [[200, 200], [200, 130], [200, 68], null],
