  name: "crossbow",
  means: "A crossbow with a bolt in its groove: moving back along the stock spans the string, the limbs bending as it pulls back.",
  rules: [1, 3, 5, 6],
  range: [0.4, 1, 1],
  tour: [[240, 170], [180, 145], [123, 118], null],
  mount,
