chainmail.code:
/**
 * Banner pole: a heraldic banner with a swallowtail hanging from the side of
 * a pole on a stepped foot. The pointer is the wind: the banner swings round
 * the pole away from it, and leaving lets it drift back. At rest the banner
 * streams to the right, bright. The slider is how far it can swing.
 *
 * The pattern: one part turning about an axis (aim).
 */
const { Cam, fit, facing, circ, poly, prism, proj, rings, rad, clamp, spring, stepS, disposer, mk, pointer, put, register, solid, flatDot, place } = HL;

const PH = 124, Z0 = 62, Z1 = 116, L = 58, REST = -25;
const disc = (r, n = 32) => circ(r, n);
const OUT = [[0, Z1], [L, Z1], [L - 12, (Z0 + Z1) / 2], [L, Z0], [0, Z0]];
const INN = [[4, Z1 - 5], [L - 7, Z1 - 5], [L - 18, (Z0 + Z1) / 2], [L - 7, Z0 + 5], [4, Z0 + 5]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-22, -22, 0], [22, 22, 0], [L, 0, Z0], [0, -L, Z1], [-L * 0.7, -L * 0.7, Z1], [L * 0.9, -L * 0.4, Z1], [0, 0, PH + 4]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(20), disc(18), 0, 5));
  put(solid(g), prism(P, front, disc(12), disc(10.5), 5, 10));
  const pole = solid(g);
  put(pole, prism(P, front, disc(2.6, 20), disc(2, 20), 10, PH));
  const top = flatDot(g, C, 3, "dot m");
  place(top, P(0, 0, PH + 3));
  const ban = mk("g", {}, g);
  const flag = mk("path", { class: "sil hi" }, ban), edge = mk("path", { class: "nf lo" }, ban);
  const th = spring(REST, { k: 60, c: 14 });
  let last = NaN, behind = null;
  function draw(a) {
    if (Math.abs(a - last) < 0.01) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const pt = ([r, z]) => P(r * c, r * s, z);
    flag.setAttribute("d", poly(OUT.map(pt)));
    edge.setAttribute("d", poly(INN.map(pt)));
    const b = c + s < 0;
    if (b !== behind) { behind = b; if (b) pole.g.before(ban); else top.after(ban); }
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(th.x); return m; });
  bag.add(B.unregister);
  const px = P(0, 0, 80)[0];
  function aim(p) {
    const f = p ? clamp((p[0] - px + 30) / 110, 0, 1) : -1;
    th.t = f < 0 ? REST : REST - swing * f;
    read.textContent = f < 0 ? "rest" : Math.round(-th.t) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; }, destroy: bag.dispose };
}

hairline({
  name: "chainmail",
  means: "A heraldic banner on a pole: the pointer is the wind, swinging the swallowtail banner round the pole away from it.",
  rules: [3, 5, 6, 8],
  range: [30, 90, 100],
  tour: [[200, 126], [244, 120], [150, 160], null],
  mount,
});

tackle.code:
/**
 * Fly box: a shallow box of flies with its lid hinged along the back edge.
 * The pointer over the box swings the lid open to show the rows of flies;
 * leaving lets it settle back ajar. At rest the lid is open a crack, bright.
 * The slider is how far the lid opens.
 *
 * The pattern: one hinged part (open).
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, rad, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid, flatDot, place, seg } = HL;

const W = 90, D = 60, H = 12, T = 4, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, H + D + 4], [0, 0, H + D + 4], [0, D, H]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [r0, r1] = rings(0, 0, W, D, 5, 1.6);
  put(solid(g), prism(P, front, r0, r1, 0, H));
  const [w0] = rings(5, 5, W - 5, D - 5, 3, 1);
  mk("path", { d: poly(w0.map((q) => P(q.u, q.v, H))), class: "nf lo" }, g);
  mk("path", { d: seg(P(W / 2, 5, H), P(W / 2, D - 5, H)), class: "dash" }, g);
  for (let i = 0; i < 4; i++) for (let j = 0; j < 3; j++) {
    const x = 14 + i * 9 + (i % 2) * 2, y = 15 + j * 15, d = flatDot(g, C, 1.6, "dot off");
    place(d, P(x, y, H));
    const e = flatDot(g, C, 1.6, (i + j) % 3 ? "dot off" : "dot m");
    place(e, P(W - x, D - y + 2, H));
  }
  const lid = mk("path", { class: "sil" }, g), lidc = mk("path", { class: "nf lo" }, g);
  const ang = tween(REST);
  const rot = (x, d, t, a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return P(x, d * c - t * s, H + d * s + t * c); };
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const x of [0, W]) for (const d of [0, D]) for (const t of [0, T]) pts.push(rot(x, d, t, a));
    lid.setAttribute("d", poly(hull(pts)));
    lidc.setAttribute("d", poly([rot(4, 4, T, a), rot(W - 4, 4, T, a), rot(W - 4, D - 4, T, a), rot(4, D - 4, T, a)]));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? max : REST, performance.now(), 0);
    lid.classList.add("hi");
    read.textContent = o ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: () => set(true), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "tackle",
  means: "A fly box with its lid hinged at the back: the pointer swings the lid open on rows of flies, and leaving lets it fall ajar.",
  rules: [3, 5, 6, 8],
  range: [60, 105, 125],
  tour: [[200, 190], [174, 181], [236, 196], null],
  mount,
});

harpoon.code:
/**
 * Fish trap: a round wicker trap, woven in bands, with a funnel lid hinged at
 * the back. The pointer tips the lid open to show the mouth of the trap;
 * leaving lets it settle back, just lifted. At rest the lid is bright.
 * The slider is how far the lid tips.
 *
 * The pattern: one hinged part (open).
 */
const { Cam, fit, facing, circ, hull, open, poly, prism, proj, rad, run, ringAt, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const R = 33, H = 54, LH = 22, REST = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-R, -R, 0], [R, R, 0], [0, -R - 4, H + 2 * R + 6], [R, R, H + 4]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const ring = circ(R, 48);
  put(solid(g), prism(P, front, ring, circ(R - 2.4, 48), 0, H));
  const near = run(ring, front);
  for (let z = 8; z < H; z += 8) mk("path", { d: open(near.map((q) => P(q.u, q.v, z))), class: "nf lo" }, g);
  for (const q of near.filter((_, i) => i % 3 === 1)) mk("path", { d: open([P(q.u, q.v, 2), P(q.u, q.v, H - 2)]), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, circ(10, 32), H)), class: "nf" }, g);
  const lid = mk("path", { class: "sil hi" }, g), band = mk("path", { class: "nf lo" }, g), mouth = mk("path", { class: "nf" }, g);
  const ang = tween(REST);
  const rot = (x, y, z, a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)), dy = y + R, dz = z; return P(x, -R + dy * c - dz * s, H + dy * s + dz * c); };
  let last = NaN;
  const lr = circ(R + 1, 40), mr = circ(9, 24), br = circ(R * 0.62, 32);
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = lr.map((q) => rot(q.u, q.v, 0, a)).concat(lr.map((q) => rot(q.u, q.v, 3, a)), mr.map((q) => rot(q.u, q.v, LH, a)));
    lid.setAttribute("d", poly(hull(pts)));
    band.setAttribute("d", poly(br.map((q) => rot(q.u, q.v, LH * 0.45, a))));
    mouth.setAttribute("d", poly(mr.map((q) => rot(q.u, q.v, LH, a))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? max : REST, performance.now(), 0);
    read.textContent = o ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: () => set(true), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

