  tour: [[257, 229], [215, 205], [180, 185], null],
  mount,
});

carpetbeater.code:
/**
 * Carpet sweeper: a low sweeper box on four wheels with its long handle,
 * the hinged lid over the dust pan on top. The pointer near the box tips
 * the lid open on its back hinge to show the pan inside. At rest the lid
 * is shut, bright. The slider is how far it opens.
 *
 * The pattern: one lid swinging on a hinge.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 84, D = 44, H = 16, WZ = 6, CZ = 0;
const disc = (x, y, r, n = 18) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, D + 8, WZ + H + D], [W, D + 8, WZ + H + D], [W / 2, -60, 95]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // handle, from the front face up and away
  const hb = [W / 2, 0, WZ + H / 2], ht = [W / 2, -58, 92];
  mk("path", { d: poly(hull(ringAt(P, disc(hb[0], hb[1], 2.4), hb[2]).concat(ringAt(P, disc(ht[0], ht[1], 2.4), ht[2])))), class: "sil" }, g);
  mk("path", { d: poly(hull(ringAt(P, disc(ht[0], ht[1], 4), ht[2] - 2).concat(ringAt(P, disc(ht[0] - 1, ht[1] - 4, 4), ht[2] + 8)))), class: "sil" }, g);
  for (const [x, y] of [[10, 0], [W - 10, 0], [10, D], [W - 10, D]]) {
    const pts = [];
    for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; for (const yy of [y - 2, y + 2]) pts.push(P(x + 5 * Math.cos(a), yy, WZ + 5 * Math.sin(a) - 0.5)); }
    mk("path", { d: poly(hull(pts)), class: "sil" }, g);
  }
  const [br, bi] = rings(0, 0, W, D, 6, 3);
  put(solid(g), prism(P, front, br, bi, WZ, WZ + H));
  const [ir] = rings(5, 5, W - 5, D - 5, 3, 1.5);
  mk("path", { d: poly(ir.map((q) => P(q.u, q.v, WZ + H))), class: "nf lo" }, g);
  const lid = mk("path", { class: "sil hi" }, g), lc = mk("path", { class: "nf" }, g);
  const a = tween(0);
  let last = NaN;

  function draw(f) {
    if (f === last) return;
    last = f;
    const ang = f * 1.75, T = WZ + H;
    const L = (x, y, dz) => { const r = D - y, c = Math.cos(ang), s = Math.sin(ang); return P(x, D - r * c - dz * s, T + r * s + dz * c); };
    const pts = [];
    for (const x of [1, W - 1]) for (const y of [1, D]) for (const dz of [0, 3]) pts.push(L(x, y, dz));
    lid.setAttribute("d", poly(hull(pts)));
    lc.setAttribute("d", poly([L(1, 1, 3), L(W - 1, 1, 3), L(W - 1, D, 3), L(1, D, 3)]) + " " + poly([L(W / 2 - 8, 6, 3), L(W / 2 + 8, 6, 3)]));
  }

  const B = register(stage, (_dt, now) => { draw(tval(a, now)); return !tdone(a, now); });
  bag.add(B.unregister);

  const c = P(W / 2, D / 2, WZ + H);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(a, on ? reach : 0, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.hypot(sx - c[0], sy - c[1]) < 95), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "carpetbeater",
  means: "A carpet sweeper on four wheels with its long handle: near the pointer its hinged lid tips open to show the dust pan.",
  rules: [1, 3, 5, 6],
  range: [0.5, 1, 1],
  tour: [[193, 211], [150, 180], [240, 190], null],
  mount,
});

toiletbrush.code:
/**
 * Toilet brush: a round holder with the brush standing in it, its lid
 * riding on the handle. The pointer near the holder draws the brush up and
 * out, leaning, the bristle head clear of the rim. At rest the handle sits
 * home, bright. The slider is how far it lifts.
 *
 * The pattern: one part lifting from its sleeve.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const HR = 21, HH = 36, LIFT = 38, CZ = 4;
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-HR - 6, -HR - 6, 0], [HR + 6, HR + 6, 0], [HR + 6, -HR - 6, 0], [-HR - 6, HR + 6, 0], [0, 0, 128], [20, 0, 128]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-HR - 6, -HR - 6, HR + 6, HR + 6, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, CZ));
  const bg = mk("g", {}, g);
  const head = mk("path", { class: "sil" }, bg), stem = mk("path", { class: "sil hi" }, bg), lid = mk("path", { class: "sil" }, bg), lidr = mk("path", { class: "nf lo" }, bg), knob = mk("path", { class: "nf" }, bg);
  const hg = mk("g", {}, g);
  put(solid(hg), prism(P, front, disc(0, 0, HR), disc(0, 0, HR - 2), CZ, CZ + HH));
  const z = tween(0);
  let last = NaN;

  function cyl(x0, z0, x1, z1, r, n = 20) { return hull(ringAt(P, disc(x0, 0, r, n), z0).concat(ringAt(P, disc(x1, 0, r, n), z1))); }
  function draw(f) {
    if (f === last) return;
    last = f;
    const up = f * LIFT, lean = f * 14, base = CZ + 6 + up, top = base + HH + 26;
    const at = (zz) => ((zz - base) / (top - base)) * lean;
    const hp = [];
    for (const [r, dz] of [[9, 0], [11, 6], [10.5, 12], [7, 16]]) hp.push(...ringAt(P, disc(at(base + dz), 0, r, 24), base + dz));
    head.setAttribute("d", poly(hull(hp)));
    stem.setAttribute("d", poly(cyl(at(base + 16), base + 16, lean, top, 2.4)));
    const lz = CZ + HH + 1 + up, lx = at(lz);
    lid.setAttribute("d", poly(hull(ringAt(P, disc(lx, 0, HR + 1.5, 40), lz).concat(ringAt(P, disc(lx, 0, HR - 3, 40), lz + 5)))));
    lidr.setAttribute("d", poly(ringAt(P, disc(lx, 0, HR + 1.5, 40), lz)));
    knob.setAttribute("d", poly(hull(ringAt(P, disc(lean, 0, 4, 16), top).concat(ringAt(P, disc(lean, 0, 4, 16), top + 4)))));
    // holder drawn last only while the brush is home
    if (f < 0.35) g.appendChild(hg); else g.insertBefore(hg, bg);
  }

  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  const c = P(0, 0, CZ + HH / 2);
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(z, a ? reach : 0, performance.now(), 0);
    read.textContent = a ? "out" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.hypot(sx - c[0], (sy - c[1]) * 0.6) < 90), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "toiletbrush",
  means: "A brush standing in its round holder: near the pointer it lifts out and leans, its lid riding up the handle.",
  rules: [1, 3, 5, 6],
  range: [0.5, 1, 1.2],
  tour: [[200, 146], [200, 196], [150, 230], null],
  mount,
});

plungercup.code:
/**
 * Shower head: a round head on a ball joint at the end of a short arm from a
 * wall plate. The head swivels to aim at the pointer, turning and tipping on
 * its ball. At rest it hangs a little to the right and tipped down, its spray
 * face bright. The slider is how far it may swivel.
 *
 * The pattern: one part aiming; the aim is picked from target poses, never
 * from the pose on screen.
 */
const { Cam, clamp, fit, hull, poly, proj, seg, tdone, tset, tval, tween, disposer, mk, pointer, register, solid, rad } = HL;

const PZ = 40, PY = 16, HR = 16, YAW0 = rad(18), PIT0 = rad(42);

function frame(yaw, pit) {
  const d = [Math.sin(yaw) * Math.cos(pit), Math.cos(yaw) * Math.cos(pit), -Math.sin(pit)];
  const u = [Math.cos(yaw), -Math.sin(yaw), 0];
  const v = [d[1] * u[2] - d[2] * u[1], d[2] * u[0] - d[0] * u[2], d[0] * u[1] - d[1] * u[0]];
  return { d, u, v };
}
function ring(f, off, r, n = 32) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2, c = r * Math.cos(a), s = r * Math.sin(a);
    out.push([0, 1, 2].map((k) => (k === 1 ? PY : k === 2 ? PZ : 0) + f.d[k] * off + f.u[k] * c + f.v[k] * s));
  }
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 5.2);
  fit(C, [[-20, 0, PZ + 14], [20, 0, PZ - 30], [-22, PY + 26, PZ - 26], [22, PY + 26, PZ - 26], [0, PY + 30, PZ + 4]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const plate = solid(g), arm = solid(g), head = solid(g), jets = mk("path", { class: "nf lo" }, g);
  plate.sil.setAttribute("d", poly(hull([[-8, 0, PZ - 9], [8, 0, PZ - 9], [8, 0, PZ + 9], [-8, 0, PZ + 9], [-8, -2, PZ - 9], [8, -2, PZ + 9]].map((p) => P(...p)))));
  plate.cr.setAttribute("d", poly([[-6, 0, PZ - 7], [6, 0, PZ - 7], [6, 0, PZ + 7], [-6, 0, PZ + 7]].map((p) => P(...p))));
  const tube = [];
  for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; tube.push([2.4 * Math.cos(a), 0, PZ + 2.4 * Math.sin(a)], [2.4 * Math.cos(a), PY, PZ + 2.4 * Math.sin(a)]); }
  arm.sil.setAttribute("d", poly(hull(tube.map((p) => P(...p)))));
  const yaw = tween(YAW0), pit = tween(PIT0);
  let ly = NaN, lp = NaN;

  function draw(y, p) {
    if (y === ly && p === lp) return;
    ly = y; lp = p;
    const f = frame(y, p), Q = (q) => P(...q);
    const pts = ring(f, 3, 3.5, 12).concat(ring(f, 8, HR), ring(f, 13, HR));
    head.sil.setAttribute("d", poly(hull(pts.map(Q))));
    head.cr.setAttribute("d", poly(ring(f, 13, HR).map(Q)) + poly(ring(f, 13, HR - 3.5).map(Q)));
    let j = "";
    [5, 9].forEach((r, k) => ring(f, 13, r, k ? 12 : 6).forEach((q) => { const a = Q(q); j += seg(a, [a[0] + 0.8, a[1] + 0.4]); }));
    jets.setAttribute("d", j);
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(yaw, now), tval(pit, now));
    return !tdone(yaw, now) || !tdone(pit, now);
  });
  bag.add(B.unregister);

  const piv = P(0, PY, PZ);
  function aim([sx, sy]) {
    if (Math.hypot(sx - piv[0], sy - piv[1]) > 210) return null;
    const M = rad(clamp(20 + reach * 0.5, 15, 65));
    let best = null, bd = Infinity;
    for (let i = -8; i <= 8; i++) for (let k = 0; k <= 6; k++) {
      const y = (i / 8) * M, p = rad(15 + k * 10), f = frame(y, p);
      const c = P(f.d[0] * 30, PY + f.d[1] * 30, PZ + f.d[2] * 30), dd = Math.hypot(c[0] - sx, c[1] - sy);
      if (dd < bd) { bd = dd; best = [y, p]; }
    }
    return best;
  }

  function setAim(a) {
    const now = performance.now();
    tset(yaw, a ? a[0] : YAW0, now, 0);
    tset(pit, a ? a[1] : PIT0, now, a ? 40 : 0);
    head.sil.classList.toggle("hi", !!a);
    head.cr.classList.toggle("hi", !a);
    read.textContent = a ? Math.round((a[0] * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  setAim(null);
  bag.add(pointer(stage, { move: (p) => setAim(aim(p)), leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "plungercup",
  means: "A shower head on a ball joint: it swivels on its arm to aim its spray face at the pointer.",
  rules: [1, 3, 4, 5],
  range: [0, 45, 90],
  tour: [[104, 205], [222, 241], [119, 189], null],
  mount,
});

bedwarmer.code:
/**
 * Bed warmer: a round brass pan on a long handle, with a pierced, domed lid
 * hinged on the handle side. Over the pan the lid swings open on its hinge to
 * show where the coals go. At rest the lid sits just ajar, bright. The slider
 * is how wide it opens.
 *
 * The pattern: one lid on a hinge; the hit is a fixed plane through the pan's rim.
 */
const { Cam, clamp, circ, facing, fit, hull, poly, prism, proj, rings, ringAt, unproj, tdone, tset, tval, tween, disposer, mk, pointer, register, solid, rad } = HL;

const R = 18, H = 7, AJAR = rad(10);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wide = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[-84, 0, 0], [R, 0, 0], [0, R, 0], [0, -R, 0], [-84, 0, 18], [-R - 6, 0, H + 2 * R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const handle = solid(g), grip = solid(g), lid = solid(g), holes = mk("path", { class: "nf lo" }, lid.g), pan = solid(g);
  const tube = (x0, z0, x1, z1, r) => {
    const pts = [];
    for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push([x0, r * Math.cos(a), z0 + r * Math.sin(a)], [x1, r * Math.cos(a), z1 + r * Math.sin(a)]); }
    return poly(hull(pts.map((p) => P(...p))));
  };
  handle.sil.setAttribute("d", tube(-R + 2, H - 2, -58, 12, 1.3));
  grip.sil.setAttribute("d", tube(-58, 12, -84, 16, 2.6));
  const [ro, ri] = rings(-R, -R, R, R, R, 1.2);
  put2(pan, prism(P, front, ro, ri, 0, H));
  function put2(s, p) { s.sil.setAttribute("d", p.sil); s.cr.setAttribute("d", p.crease); }

  const prof = [[0, R], [2.2, R * 0.86], [4, R * 0.62], [5.2, R * 0.34], [5.6, 0.01]];
  const holePts = [];
  [[6, 6], [11.5, 10]].forEach(([r, n], k) => { for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2 + k * 0.3; holePts.push([R + r * Math.cos(a), r * Math.sin(a), 5.6 * (1 - (r / R) ** 2)]); } });
  const ang = tween(AJAR);
  let last = NaN, behind = false;

  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const W = ([lx, ly, lz]) => P(-R + lx * c - lz * s, ly, H + lx * s + lz * c);
    const pts = [];
    prof.forEach(([lz, r]) => { for (let i = 0; i < 32; i++) { const b = (i / 32) * Math.PI * 2; pts.push([R + r * Math.cos(b), r * Math.sin(b), lz]); } });
    lid.sil.setAttribute("d", poly(hull(pts.map(W))));
    lid.cr.setAttribute("d", poly(pts.slice(0, 32).map(W)) + poly(pts.slice(64, 96).map(W)));
    let d = "";
    holePts.forEach(([x, y, z]) => { const q = []; for (let i = 0; i < 8; i++) { const b = (i / 8) * Math.PI * 2; q.push([x + 1.3 * Math.cos(b), y + 1.3 * Math.sin(b), z + 0.2]); } d += poly(q.map(W)); });
    holes.setAttribute("d", d);
    const back = a > rad(55);
    if (back !== behind) { behind = back; if (back) handle.g.after(lid.g); else pan.g.after(lid.g); }
  }
  pan.g.after(lid.g);

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return Math.hypot(x, y) < R + 10;
  }
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    const A = clamp(40 + wide, 35, 125);
    tset(ang, on ? rad(A) : AJAR, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  lid.sil.classList.add("hi");
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wide = v; act = null; }, destroy: bag.dispose };
}

