  name: "vortexmixer",
  means: "A vortex mixer: the pointer over it presses the test tube into the cup, which swings the tube hard over off-centre.",
  rules: [1, 5, 6],
  range: [12, 26, 30],
  tour: [[200, 228], [195, 206], [205, 290], null],
  mount,
