    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, H); set(x > -8 && x < W + 8 && y > -8 && y < D + HD); },
    leave: () => set(false),
  }));
