  name: "bridle",
  means: "A horse grooming box: the pointer over it swings the hinged lid up on a spring; at rest it sits a little ajar.",
  rules: [1, 3, 5, 8],
  range: [60, 100, 115],
  tour: [[171, 159], [235, 150], [130, 165], null],
  mount,
