neon.code:
/**
 * Neon sign: a backing panel on a weighted foot with a bent tube standing off
 * its face. The pointer tips the panel back on its foot hinge, as if to
 * catch the light. At rest it leans slightly, its tube bright.
 * The slider is how far it can tip.
 */
const { Cam, fit, facing, proj, rings, prism, put, solid, mk, poly, open, seg, fillet, hull, spring, stepS, clamp, rad, register, pointer, disposer } = HL;

const W = 56, H = 74, T = 2, Z = 7, REST = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-W, -10, 0], [W, 10, 0], [-W, 0, Z + H], [W, 0, Z + H], [-W, -50, Z + 50], [W, -50, Z + 50]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-W + 6, -12, W - 6, 12, 6, 1.6);
  put(solid(g), prism(P, front, fr, fi, 0, Z));
  const plate = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf lo" }, g);
  const legs = mk("path", { class: "nf lo" }, g), tube = mk("path", { class: "nf sil hi" }, g);

  const tx = (u) => -W + 18 + u * (2 * W - 36) - 9 * Math.sin(u * Math.PI * 8), th = (u) => H * 0.5 + 12 * Math.cos(u * Math.PI * 8) * (0.5 + 0.5 * Math.sin(u * Math.PI));
  const sp = spring(REST);
  let last = NaN;
  const pt = (x, t, h, b) => { const c = Math.cos(rad(b)), s = Math.sin(rad(b)); return P(x, t * c - h * s, Z + h * c + t * s); };
  const wave = (t, b) => {
    const q = [];
    for (let i = 0; i <= 90; i++) { const u = i / 90; q.push(pt(tx(u), t, th(u), b)); }
    return q;
  };
  function draw(b) {
    if (b === last) return;
    last = b;
    const pts = [];
    for (const x of [-W, W]) for (const t of [-T, T]) for (const h of [0, H]) pts.push(pt(x, t, h, b));
    const hp = hull(pts);
    plate.setAttribute("d", poly(fillet(hp, hp.map(() => 6))));
    const q = [pt(-W + 5, T, 5, b), pt(W - 5, T, 5, b), pt(W - 5, T, H - 5, b), pt(-W + 5, T, H - 5, b)];
    rim.setAttribute("d", poly(fillet(q, [4, 4, 4, 4])));
    let l = "";
    for (const u of [0.12, 0.5, 0.88]) l += seg(pt(tx(u), T, th(u), b), pt(tx(u), T + 5, th(u), b));
    legs.setAttribute("d", l);
    tube.setAttribute("d", open(wave(T + 5, b)));
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const mid = P(0, 0, Z + H / 2);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const t = clamp(Math.hypot(sx - mid[0], sy - mid[1]) / 180, 0, 1);
      sp.t = REST + (amp - REST) * (1 - 0.6 * t);
      read.textContent = Math.round(sp.t) + "°";
      B.wake();
    },
    leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

hairline({
  name: "neon",
  means: "A neon sign on a weighted foot: the pointer tips the panel back on its hinge, its bent tube riding along.",
  rules: [3, 4, 5, 8],
  range: [30, 48, 60],
  tour: [[159, 153], [68, 195], [250, 125], null],
  mount,
});

hardy.code:
/**
 * Hardy tool: a chisel-edged cutter standing in the square hardy hole of an
 * anvil's heel. Over it, the hardy lifts out of its hole on its square shank,
 * ready to be swapped; away, it drops back in. At rest the cutting edge is
 * bright. The slider is how high it lifts.
 */
const {
  Cam, fit, facing, hull, poly, open, prism, proj, ringAt, rings, rrect, run, unproj, tset, tval, tdone, tween, lerp, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const T = 30, HX = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-46, -24, 0], [46, 24, 0], [46, -24, 0], [-46, 24, 0], [HX, 0, T + 34 + 30]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-46, -24, 46, 24, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, T));
  mk("path", { d: poly(ringAt(P, rrect(HX - 6, -6, HX + 6, 6, 1, 2), T)), class: "lo" }, g);
  mk("path", { d: poly(ringAt(P, rrect(-34, -6, -26, 2, 4, 4), T)), class: "nf lo" }, g);
  const tool = mk("g", {}, g);
  const shank = solid(tool), collar = solid(tool), blade = mk("path", { class: "sil" }, tool), crease = mk("path", { class: "nf lo" }, tool), edge = mk("path", { class: "nf hi" }, tool);
  const [sr, si] = rings(HX - 5, -5, HX + 5, 5, 1.2, 1);
  const [cr, ci] = rings(HX - 11, -9, HX + 11, 9, 2.5, 1.2);
  const foot = rrect(HX - 10, -8, HX + 10, 8, 2, 4), top = rrect(HX - 10, -0.8, HX + 10, 0.8, 0.8, 2);
  const t = tween(0);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const L = v * lerp(12, 30, reach), z0 = T + L;
    if (L <= 0.5) put(shank, { sil: "", crease: "" });
    if (L > 0.5) put(shank, prism(P, front, sr, si, T, z0));
    put(collar, prism(P, front, cr, ci, z0, z0 + 4));
    const zb = z0 + 4, zt = zb + 26;
    blade.setAttribute("d", poly(hull(ringAt(P, foot, zb).concat(ringAt(P, top, zt)))));
    crease.setAttribute("d", open(ringAt(P, run(foot, front), zb + 1)));
    edge.setAttribute("d", seg(P(HX - 10, 0, zt), P(HX + 10, 0, zt)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(t, on ? 1 : 0, performance.now(), 0);
    read.textContent = on ? "lift" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, T + 15); return Math.abs(x - HX) < 26 && Math.abs(y) < 26; };
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "hardy",
  means: "A hardy cutter in an anvil heel's square hole: over it, the hardy lifts out on its square shank, then drops back in.",
  rules: [1, 4, 5, 6],
  range: [0.4, 0.8, 1],
  tour: [[213, 140], [200, 160], [230, 175], null],
  mount,
});

leatherpunch.code:
/**
 * Leather punch: a rotary punch seen side on, its wheel of tubes on the
 * upper jaw. The pointer over the tool squeezes the handles: the upper
 * handle swings down about the pivot and the anvil jaw rises to the wheel.
 * At rest the wheel is bright. The slider is how far it squeezes.
 */
const { Cam, fit, hull, poly, proj, circ, fillet, clamp, spring, stepS, disposer, mk, pointer, register } = HL;

const OPEN = 17, s = Math.SQRT1_2, Z0 = 46;
const W = (u, w, z) => [u * s + w * s, -u * s + w * s, z + Z0];
// fixed piece: upper jaw with wheel, lower handle
const JAW_B = [[-50, 2], [-50, 12], [6, 9], [6, 0]];
const HAN_B = [[-4, -2], [6, -8], [84, -20], [82, -28]];
// moving piece: anvil jaw, upper handle
const JAW_A = [[-52, -5], [-52, -12], [6, -7], [6, 3]];
const HAN_A = [[-4, 3], [6, 8], [84, 16], [82, 24]];
const WC = [-42, 7], WR = 11;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [W(-56, 0, -40), W(90, 0, 40), W(90, 0, -40), W(-56, 0, 30)], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const rnd = (pts) => fillet(pts, pts.map(() => 2.5), 3);
  function part(cls) {
    const q = mk("g", {}, g);
    return { sil: mk("path", { class: "sil " + cls }, q), cr: mk("path", { class: "nf lo" }, q) };
  }
  function draw(pt, pts, w0, w1, th) {
    const c = Math.cos(th), si = Math.sin(th);
    const r = rnd(pts).map(([u, z]) => [u * c - z * si, u * si + z * c]);
    const a = r.map(([u, z]) => P(...W(u, w0, z))), b = r.map(([u, z]) => P(...W(u, w1, z)));
    pt.sil.setAttribute("d", poly(hull(a.concat(b))));
    pt.cr.setAttribute("d", poly(b));
  }
  const circle = (cx, cz, R, n = 32) => circ(R, n).map((q) => [cx + q.u, cz + q.v]);
  const jb = part(""), hb = part(""), wheel = part(""), hub = part("");
  draw(jb, JAW_B, 0, 6, 0); draw(hb, HAN_B, 0, 6, 0);
  draw(wheel, circle(WC[0], WC[1], WR), -2, 9, 0);
  draw(hub, circle(WC[0], WC[1], 3.5, 16), 9, 10.5, 0);
  const tubes = [];
  for (let k = 0; k < 6; k++) {
    const t = (k / 6) * Math.PI * 2 + 0.5, d = mk("path", { class: "nf" }, g);
    const pts = circle(WC[0] + Math.cos(t) * 7.4, WC[1] + Math.sin(t) * 7.4, 1.5, 10).map(([u, z]) => P(...W(u, 9, z)));
    d.setAttribute("d", poly(pts)); tubes.push(d);
  }
  const ja = part(""), ha = part(""), boss = part("");
  draw(boss, circle(0, 0, 6, 20), -1, 13, 0);
  const th = spring(rad(OPEN));
  let last = NaN;
  function redraw() {
    if (th.x === last) return;
    last = th.x;
    draw(ja, JAW_A, 6, 12, th.x); draw(ha, HAN_A, 6, 12, th.x);
    boss.sil.parentNode.parentNode.appendChild(boss.sil.parentNode);
  }
  redraw();
  const B = register(stage, (dt) => { const m = stepS(th, dt); redraw(); return m; });
  bag.add(B.unregister);
  const box = [W(-56, 0, -36), W(90, 0, 36)].map((p) => P(...p));
  let on = null;
  function set(p) {
    const inside = p && p[0] > box[0][0] - 8 && p[0] < box[1][0] + 8 && Math.abs(p[1] - (box[0][1] + box[1][1]) / 2) < 70;
    const t = inside ? clamp((p[0] - box[0][0]) / (box[1][0] - box[0][0]), 0, 1) : -1;
    th.t = rad(OPEN) * (inside ? 1 - amt * (0.4 + 0.6 * t) : 1);
    if (inside !== on) {
      on = inside;
      wheel.sil.classList.toggle("hi", !inside);
      ha.sil.classList.toggle("hi", inside); ja.sil.classList.toggle("hi", inside);
    }
    read.textContent = inside ? "sq " + Math.round(100 * (1 - th.t / rad(OPEN))) : "rest";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; }, destroy: bag.dispose };
}
const rad = (d) => (d * Math.PI) / 180;

hairline({
  name: "leatherpunch",
  means: "A rotary leather punch side on: the pointer squeezes its handles, and the anvil jaw swings up to the wheel of tubes.",
  rules: [1, 3, 5, 8],
  range: [0, 0.8, 1],
  tour: [[36, 166], [342, 131], [351, 127], null],
  mount,
});

bookbind.code:
/**
 * Sewing frame: a bookbinder's frame, a crossbar on two posts with cords
 * strung down to the bed, and a text block waiting at the cords. The
 * pointer over the frame swings the open signature shut onto the block,
 * as each section is sewn on. At rest the open leaf is bright, lifted.
 */
const { Cam, fit, hull, poly, proj, fillet, seg, clamp, spring, stepS, disposer, mk, pointer, register } = HL;

const s = Math.SQRT1_2, U0 = 0, ZB = 8, ZS = 18, L = 60, OPEN = 110, TOP = 96;
const W = (u, w, z) => [u, w, z];
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [W(-60, -44, 0), W(60, 44, 0), W(-60, 44, 0), W(60, -44, 0), W(0, -44, TOP + 10), W(-50, 30, 50)], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  function part() {
    const q = mk("g", {}, g);
    return { sil: mk("path", { class: "sil" }, q), cr: mk("path", { class: "nf lo" }, q) };
  }
  function draw(pt, pts, w0, w1, th = 0, pv = [U0, ZS]) {
    const c = Math.cos(th), si = Math.sin(th);
    const r = fillet(pts, pts.map(() => 1.5), 3).map(([u, z]) => { const du = u - pv[0], dz = z - pv[1]; return [pv[0] + du * c - dz * si, pv[1] + du * si + dz * c]; });
    const a = r.map(([u, z]) => P(...W(u, w0, z))), b = r.map(([u, z]) => P(...W(u, w1, z)));
    pt.sil.setAttribute("d", poly(hull(a.concat(b))));
    pt.cr.setAttribute("d", poly(b));
  }
  const post = (w) => draw(part(), [[-5, ZB], [5, ZB], [5, TOP], [-5, TOP]], w - 4, w + 4);
  draw(part(), [[-62, 0], [62, 0], [62, ZB], [-62, ZB]], -46, 46);
  post(-40);
  draw(part(), [[U0, ZB], [U0 + L, ZB], [U0 + L, ZS], [U0, ZS]], -30, 30);
  const cords = mk("path", { class: "nf" }, g);
  cords.setAttribute("d", [-22, -7, 7, 22].map((w) => seg(P(...W(U0, w, ZB)), P(...W(U0, w, TOP - 6)))).join(""));
  const leaf = part();
  post(40);
  draw(part(), [[-6, TOP - 6], [6, TOP - 6], [6, TOP + 4], [-6, TOP + 4]], -46, 46);
  const th = spring(rad(OPEN));
  let last = NaN;
  function redraw() {
    if (th.x === last) return;
    last = th.x;
    draw(leaf, [[U0, ZS], [U0 + L, ZS], [U0 + L, ZS + 1.6], [U0, ZS + 1.6]], -34, 34, th.x);
  }
  redraw();
  const B = register(stage, (dt) => { const m = stepS(th, dt); redraw(); return m; });
  bag.add(B.unregister);
  const cen = P(...W(0, 0, 40));
  let on = null;
  function set(p) {
    const inside = !!p && Math.abs(p[0] - cen[0]) < 150 && Math.abs(p[1] - cen[1]) < 110;
    const t = inside ? clamp((p[0] - cen[0] + 150) / 300, 0, 1) : 0;
    th.t = rad(inside ? OPEN * (1 - amt * (0.9 + 0.1 * t)) : OPEN);
    if (inside !== on) { on = inside; leaf.sil.classList.toggle("hi", true); }
    read.textContent = inside ? "sig " + Math.round((th.t * 180) / Math.PI) : "rest";
    B.wake();
  }
  set(null);
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; }, destroy: bag.dispose };
}

hairline({
  name: "bookbind",
  means: "A bookbinder's sewing frame: the pointer swings the open signature shut onto the text block at the cords.",
  rules: [1, 3, 5, 8],
  range: [0, 0.8, 1],
  tour: [[132, 177], [234, 214], [268, 245], null],
  mount,
});

candlemould.code:
/**
 * Candle mould: a metal tube mould standing on a drip tray, the cast candle
 * inside it. Over the figure the tube lifts straight up off the candle; at
 * rest it hangs a little raised, the bright candle foot showing. The slider
 * is how far the tube lifts.
 */
const { Cam, circ, fit, facing, prism, proj, ringAt, rings, poly, seg, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const R = 15, H = 58, CR = 11, CH = 52, TZ = 4, REST = 0.25;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-26, -26, 0], [26, 26, 0], [26, -26, 0], [-26, 26, 0], [0, 0, TZ + H + 60]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-26, -26, 26, 26, 8, 2.2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  mk("path", { d: poly(ringAt(P, disc(0, 0, R + 3), TZ)), class: "nf lo" }, g);
  const candle = solid(g);
  put(candle, prism(P, front, disc(0, 0, CR), disc(0, 0, CR - 1.2), TZ, TZ + CH));
  candle.sil.classList.add("hi");
  const tube = solid(g), lip = mk("path", { class: "nf" }, g), mouth = mk("path", { class: "nf lo" }, g);
  const wick = mk("path", { class: "nf" }, g);
  const ring = mk("path", { class: "nf" }, g);
  const lift = tween(REST * value);

  function draw(f) {
    const z0 = TZ + f;
    put(tube, prism(P, front, disc(0, 0, R), disc(0, 0, R - 1.6), z0, z0 + H));
    lip.setAttribute("d", poly(ringAt(P, disc(0, 0, R + 2.5), z0 + 5)));
    mouth.setAttribute("d", poly(ringAt(P, disc(0, 0, R - 2), z0 + H)));
    ring.setAttribute("d", poly(ringAt(P, disc(0, 0, R + 2.5), z0 + H - 6)));
    wick.setAttribute("d", seg(P(0, 0, TZ + CH), P(0, 0, Math.max(z0 + H + 8, TZ + CH + 8))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);

  const a = P(0, 0, TZ), b = P(0, 0, TZ + H);
  const hit = ([sx, sy]) => Math.abs(sx - a[0]) < 60 && sy > b[1] - 30 && sy < a[1] + 50;
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(lift, (v ? 1 : REST) * reach, performance.now(), 0);
    read.textContent = v ? "out " + Math.round(reach) : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; tset(lift, (on ? 1 : REST) * v, performance.now(), 0); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "candlemould",
  means: "A metal candle mould on a drip tray: the tube lifts up off the cast candle under the pointer.",
  rules: [1, 3, 5],
  range: [30, 56, 60],
  tour: [[200, 141], [205, 170], [195, 120], null],
  mount,
});

tapestry.code:
/**
 * Rug hook: a rug hooking frame, the stretched canvas on a square frame
 * that pivots between two uprights on a floor stand. Over the figure the
 * frame tilts up toward the hooker; at rest it lies low, the bright patch of
 * hooked loops on it. The slider is how far it tilts.
 */
const { Cam, fit, proj, poly, clamp, rad, tset, tval, tdone, tween, disposer, mk, pointer, register } = HL;

const AZ = 44, W = 30, REST = 12;
const FACES = [[0, 2, 3, 1], [4, 5, 7, 6], [0, 4, 6, 2], [1, 3, 7, 5], [0, 1, 5, 4], [2, 6, 7, 3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-34, -38, 0], [34, 38, 0], [34, -38, 0], [-34, 38, 0], [-12, 0, AZ + 34], [12, 0, AZ + 34], [W, 0, AZ - 10]], 200, 165);
  const P = proj(C);
  const area = (q) => { let s = 0; for (let i = 0; i < q.length; i++) { const a = q[i], b = q[(i + 1) % q.length]; s += a[0] * b[1] - b[0] * a[1]; } return s; };
  const up = Math.sign(area([[0, 0, 1], [1, 0, 1], [1, 1, 1], [0, 1, 1]].map((p) => P(...p))));
  function box(x0, x1, y0, y1, z0, z1, f = (p) => p) {
    const c = [];
    for (let k = 0; k < 8; k++) c.push(P(...f([k & 1 ? x1 : x0, k & 2 ? y1 : y0, k & 4 ? z1 : z0])));
    return FACES.map((fc) => fc.map((i) => c[i])).filter((q) => Math.sign(area(q)) === up).map(poly).join("");
  }
  const g = mk("g", {}, svg);
  mk("path", { d: box(-34, 34, -38, -30, 0, 4) }, g);
  mk("path", { d: box(-3, 3, -36, -32, 4, AZ + 3) }, g);
  mk("path", { d: box(-3, 3, -32, 32, 0, 3) }, g);
  const frame = mk("path", {}, g), canvas = mk("path", { class: "nf lo" }, g), patch = mk("path", { class: "hi" }, g);
  mk("path", { d: box(-34, 34, 30, 38, 0, 4) }, g);
  mk("path", { d: box(-3, 3, 32, 36, 4, AZ + 3) }, g);
  const t = tween(0);

  function draw(f) {
    const th = rad(REST + f * reach), c = Math.cos(th), s = Math.sin(th);
    const tf = ([u, v, n]) => [u * c - n * s, v, AZ + u * s + n * c];
    frame.setAttribute("d", box(-W, W, -W, W, 0, 3, tf));
    const sq = (a, b, e, h) => poly([[a, e, 3.1], [b, e, 3.1], [b, h, 3.1], [a, h, 3.1]].map((p) => P(...tf(p))));
    canvas.setAttribute("d", sq(-W + 5, W - 5, -W + 5, W - 5));
    patch.setAttribute("d", sq(-6, 14, -12, 8));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const a = P(-34, 38, 0), b = P(34, -38, 0), top = P(0, 0, AZ + 34);
  const hit = ([sx, sy]) => sx > Math.min(a[0], b[0]) - 10 && sx < Math.max(a[0], b[0]) + 10 && sy > top[1] - 30 && sy < Math.max(a[1], b[1]) + 20;
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(t, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "up " + Math.round(REST + reach) : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 30, 60); draw(tval(t, performance.now())); }, destroy: bag.dispose };
}

hairline({
  name: "tapestry",
  means: "A rug hooking frame on its stand: under the pointer the canvas frame tilts up on its pivots toward the hooker.",
  rules: [1, 3, 5],
  range: [30, 50, 60],
  tour: [[230, 138], [200, 170], [170, 120], null],
  mount,
});

drumpedal.code:
/**
 * Bass pedal: a kick-drum pedal on its base plate, the footboard hinged at
 * the heel, a chain over the cam to the beater between two posts. Over the
 * figure the footboard presses down and the bright beater swings forward to
 * strike. The slider is how far the beater swings.
 */
const { Cam, fit, proj, poly, seg, clamp, rad, tset, tval, tdone, tween, disposer, mk, pointer, register } = HL;

const AX = 58, AZ = 62, HZ = 5, LEN = 40;
const FACES = [[0, 2, 3, 1], [4, 5, 7, 6], [0, 4, 6, 2], [1, 3, 7, 5], [0, 1, 5, 4], [2, 6, 7, 3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-6, -16, 0], [66, 16, 0], [66, -16, 0], [-6, 16, 0], [AX - 30, 0, AZ + 40], [AX + 30, 0, AZ + 40]], 200, 165);
  const P = proj(C);
  const area = (q) => { let s = 0; for (let i = 0; i < q.length; i++) { const a = q[i], b = q[(i + 1) % q.length]; s += a[0] * b[1] - b[0] * a[1]; } return s; };
  const up = Math.sign(area([[0, 0, 1], [1, 0, 1], [1, 1, 1], [0, 1, 1]].map((p) => P(...p))));
  function box(x0, x1, y0, y1, z0, z1, f = (p) => p) {
    const c = [];
    for (let k = 0; k < 8; k++) c.push(P(...f([k & 1 ? x1 : x0, k & 2 ? y1 : y0, k & 4 ? z1 : z0])));
    return FACES.map((fc) => fc.map((i) => c[i])).filter((q) => Math.sign(area(q)) === up).map(poly).join("");
  }
  const g = mk("g", {}, svg);
  mk("path", { d: box(-6, 66, -16, 16, 0, 3) }, g);
  mk("path", { d: box(AX - 5, AX + 5, -14, 14, 3, 8) }, g);
  const board = mk("path", {}, g), chain = mk("path", { class: "nf" }, g);
  mk("path", { d: box(AX - 2, AX + 2, -14, -10, 3, AZ + 4) }, g);
  const rod = mk("path", {}, g), head = mk("path", { class: "hi" }, g);
  mk("path", { d: box(AX - 3, AX + 3, -10, 10, AZ - 3, AZ + 3) }, g);
  mk("path", { d: box(AX - 2, AX + 2, 10, 14, 3, AZ + 4) }, g);
  const t = tween(0);

  function draw(f) {
    const tilt = rad(lerp(16, 3, f)), phi = rad(lerp(-28, -28 + reach, f));
    const bf = ([x, y, z]) => [x * Math.cos(tilt), y, HZ + x * Math.sin(tilt) + z];
    board.setAttribute("d", box(0, 50, -9, 9, 0, 2.4, bf));
    const toe = bf([50, 0, 2.4]);
    chain.setAttribute("d", seg(P(...toe), P(AX + 3, 0, AZ - 4)));
    const rf = ([x, y, z]) => [AX + x * Math.cos(phi) + z * Math.sin(phi), y, AZ - x * Math.sin(phi) + z * Math.cos(phi)];
    rod.setAttribute("d", box(-1, 1, -1, 1, 0, LEN, rf));
    head.setAttribute("d", box(-5, 5, -6, 6, LEN - 4, LEN + 8, rf));
  }
  const lerp = (a, b, k) => a + (b - a) * k;
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const lo = P(-6, 16, 0), hi2 = P(66, -16, AZ + 40);
  const hit = ([sx, sy]) => sx > Math.min(lo[0], hi2[0]) - 20 && sx < Math.max(lo[0], hi2[0]) + 20 && sy > hi2[1] - 20 && sy < lo[1] + 30;
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(t, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "hit " + Math.round(reach) : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 30, 70); draw(tval(t, performance.now())); }, destroy: bag.dispose };
}

hairline({
  name: "drumpedal",
  means: "A bass drum pedal: under the pointer the footboard presses down and the beater swings forward to strike.",
  rules: [1, 3, 5],
  range: [30, 60, 70],
  tour: [[196, 216], [200, 150], [240, 110], null],
  mount,
});

organstop.code:
/**
 * Organ stop: one draw-knob in a wooden jamb, a turned round knob on a long
 * shank. Over the figure the knob draws out of the jamb; at rest it sits
 * pushed in, its bright face toward the player. The slider is the draw.
 */
const { Cam, fit, proj, poly, hull, clamp, tset, tval, tdone, tween, disposer, mk, pointer, register } = HL;

const KZ = 34, KR = 14, SR = 5;
const FACES = [[0, 2, 3, 1], [4, 5, 7, 6], [0, 4, 6, 2], [1, 3, 7, 5], [0, 1, 5, 4], [2, 6, 7, 3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-10, -26, 0], [-10, 26, 0], [-10, -26, 70], [-10, 26, 70], [70, 0, KZ + KR], [70, 0, KZ - KR]], 200, 160);
  const P = proj(C);
  const area = (q) => { let s = 0; for (let i = 0; i < q.length; i++) { const a = q[i], b = q[(i + 1) % q.length]; s += a[0] * b[1] - b[0] * a[1]; } return s; };
  const up = Math.sign(area([[0, 0, 1], [1, 0, 1], [1, 1, 1], [0, 1, 1]].map((p) => P(...p))));
  function box(x0, x1, y0, y1, z0, z1) {
    const c = [];
    for (let k = 0; k < 8; k++) c.push(P(k & 1 ? x1 : x0, k & 2 ? y1 : y0, k & 4 ? z1 : z0));
    return FACES.map((fc) => fc.map((i) => c[i])).filter((q) => Math.sign(area(q)) === up).map(poly).join("");
  }
  const ring = (x, r) => { const o = []; for (let i = 0; i < 36; i++) { const a = (i / 36) * 2 * Math.PI; o.push(P(x, r * Math.cos(a), KZ + r * Math.sin(a))); } return o; };
  const g = mk("g", {}, svg);
  mk("path", { d: box(-10, 0, -26, 26, 0, 70) }, g);
  mk("path", { d: poly(ring(0.1, SR + 4)), class: "nf lo" }, g);
  const shank = mk("path", {}, g), knob = mk("path", {}, g), face = mk("path", { class: "hi" }, g), bead = mk("path", { class: "nf lo" }, g);
  const t = tween(0);

  function draw(f) {
    const x = 8 + f * reach;
    shank.setAttribute("d", poly(hull(ring(0, SR).concat(ring(x, SR)))));
    knob.setAttribute("d", poly(hull(ring(x, KR - 3).concat(ring(x + 4, KR), ring(x + 12, KR)))));
    face.setAttribute("d", poly(ring(x + 12, KR)));
    bead.setAttribute("d", poly(ring(x + 12, KR - 5)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const a = P(-10, 26, 0), b = P(62, -26, 70);
  const hit = ([sx, sy]) => sx > Math.min(a[0], b[0]) - 20 && sx < Math.max(a[0], b[0]) + 20 && sy > b[1] - 30 && sy < a[1] + 30;
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(t, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "on " + Math.round(reach) : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 20, 40); draw(tval(t, performance.now())); }, destroy: bag.dispose };
}

hairline({
  name: "organstop",
  means: "An organ draw-knob in its jamb: under the pointer the round knob pulls out on its shank to sound the stop.",
  rules: [1, 3, 5],
  range: [20, 36, 40],
  tour: [[206, 155], [222, 175], [190, 125], null],
  mount,
