lyre.code:
/**
 * Lyre: a soundbox with two curved arms rising to a crossbar, seven strings
 * strung between. The pointer picks the string nearest it: that string goes
 * bright and bows out as if plucked, and the lyre tips toward that side as a
 * player cradles it. At rest it leans a little, the middle string lit.
 *
 * The pattern: one of a few in a single row (riffle).
 */
const {
  Cam, fit, hull, open, poly, proj, rrect, run, facing, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 7, FAV = 3, MAX = 0.3, REST = -0.06;
const sx = (i) => -15 + i * 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.15);
  fit(C, [[-45, -10, 0], [45, 10, 0], [-45, -10, 80], [45, 10, 80]], 200, 160);
  const P0 = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const arms = mk("path", { class: "nf" }, g);
  const box = solid(mk("g", {}, g));
  const strs = Array.from({ length: N }, () => mk("path", { class: "nf lo" }, g));
  const bar = solid(mk("g", {}, g));
  const tilt = tween(REST), pl = tween(0);
  let pick = FAV, last = "";

  function draw(now) {
    const a = tval(tilt, now), b = tval(pl, now), key = a.toFixed(4) + b.toFixed(4) + pick;
    if (key === last) return;
    last = key;
    const ca = Math.cos(a), sa = Math.sin(a);
    const P = (x, y, z) => P0(x * ca + z * sa, y, -x * sa + z * ca);
    const slab = (r, z0, z1) => poly(hull(r.map((q) => P(q.u, q.v, z0)).concat(r.map((q) => P(q.u, q.v, z1)))));
    const r1 = rrect(-24, -7, 24, 7, 6, 4);
    put(box, { sil: slab(r1, 0, 16), crease: open(run(rrect(-22.5, -5.5, 22.5, 5.5, 4.5, 4), front).map((q) => P(q.u, q.v, 14.6))) });
    let s = "";
    for (const side of [-1, 1]) for (const o of [0, 4]) {
      const pts = [];
      for (let k = 0; k <= 16; k++) { const t = k / 16, x = side * (16 + o + 16 * Math.sin(t * 2.4) - 4 * t), z = 14 + t * 58; pts.push(P(x, 0, z)); }
      s += open(pts);
    }
    arms.setAttribute("d", s);
    const r2 = rrect(-28, -3, 28, 3, 2.5, 4);
    put(bar, { sil: slab(r2, 64, 70), crease: open(run(rrect(-27, -2, 27, 2, 1.5, 4), front).map((q) => P(q.u, q.v, 69))) });
    strs.forEach((el, i) => {
      const x0 = sx(i), x1 = sx(i) * 1.3, bow = i === pick ? 4 * b * reach : 0;
      el.setAttribute("d", open([P(x0, -1, 16), P((x0 + x1) / 2 + bow, -1 - bow, 40), P(x1, -1, 64)]));
    });
  }

  const L = register(stage, (_dt, now) => { draw(now); return !tdone(tilt, now) || !tdone(pl, now); });
  bag.add(L.unregister);

  const mids = Array.from({ length: N }, (_, i) => P0(sx(i) * 1.15, 0, 40));
  function hit([x, y]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - x); if (d < bd) { bd = d; best = k; } });
    return bd < 40 && Math.abs(mids[best][1] - y) < 110 ? best : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now();
    act = a;
    pick = a < 0 ? FAV : a;
    tset(tilt, a < 0 ? REST : ((a - 3) / 3) * MAX * reach, now, 0);
    tset(pl, a < 0 ? 0.3 : 1, now, 0);
    strs.forEach((el, k) => { el.classList.toggle("hi", k === pick); el.classList.toggle("lo", k !== pick); });
    read.textContent = a < 0 ? "rest" : "str " + (a + 1);
    L.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; act = -3; setActive(-1); }, destroy: bag.dispose };
}

hairline({
  name: "lyre",
  means: "A lyre: the string nearest the pointer lights and bows as if plucked, and the lyre tips toward that side.",
  rules: [1, 4, 5, 9],
  range: [0.3, 1, 1],
  tour: [[233, 177], [167, 143], [200, 160], null],
  mount,
});

djembe.code:
/**
 * Djembe: a goblet drum, a wide bowl on a narrow waist and flared foot, with
 * rope lacing running down the bowl. The pointer rocks the drum on its foot
 * toward the side it stands on, the skin bright, as a player tips it to play.
 * At rest it leans a little, head lit. The slider is how far it rocks.
 *
 * The pattern: one part following the pointer (spring).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, proj, ringAt, run, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = -0.08, MAX = 0.32;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-40, -30, 0], [40, 30, 0], [-40, -30, 70], [40, 30, 70], [-30, 30, 66], [30, -30, 66]], 200, 166);
  const P0 = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const foot = solid(mk("g", {}, g)), bowl = solid(mk("g", {}, g));
  const rope = mk("path", { class: "nf lo" }, g);
  const head = mk("path", { class: "nf hi" }, g);
  const tilt = spring(REST);
  let last = "";

  function draw() {
    const a = tilt.x, key = a.toFixed(4);
    if (key === last) return;
    last = key;
    // rock about the foot rim on the side it leans to
    const px = a > 0 ? 17 : -17, ca = Math.cos(a), sa = Math.sin(a);
    const P = (x, y, z) => { const dx = x - px; return P0(px + dx * ca + z * sa, y, -dx * sa + z * ca + Math.abs(px * sa) * 0); };
    const R = (ring, z) => ring.map((q) => P(q.u, q.v, z));
    const Rf = (ring, z) => ring.filter((q) => front({ nu: q.nu * ca, nv: q.nv })).map((q) => P(q.u, q.v, z));
    const f0 = disc(17), w = disc(8), b0 = disc(9), top = disc(25), inn = disc(23.4);
    put(foot, { sil: poly(hull(R(f0, 0).concat(R(w, 30)))), crease: open(Rf(run(disc(15.6), front), 1.6)) });
    put(bowl, { sil: poly(hull(R(b0, 30).concat(R(top, 66)))), crease: open(R(run(inn, front), 64.4)) });
    let s = "";
    for (let i = 0; i < 14; i++) {
      const t = (i / 14) * Math.PI * 2, c = Math.cos(t), n = Math.sin(t);
      if (!front({ nu: c, nv: n })) continue;
      const t2 = t + Math.PI / 14, c2 = Math.cos(t2), n2 = Math.sin(t2);
      s += open([P(c * 24, n * 24, 61), P(c2 * 15, n2 * 15, 44), P(Math.cos(t + Math.PI / 7) * 24, Math.sin(t + Math.PI / 7) * 24, 61)]);
    }
    rope.setAttribute("d", s);
    head.setAttribute("d", poly(R(top, 66)));
  }

  const L = register(stage, (dt) => { const m = stepS(tilt, dt); draw(); return m; });
  bag.add(L.unregister);

  function aim(p) {
    if (!p) { tilt.t = REST; read.textContent = "rest"; L.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 66);
    if (Math.hypot(x, y) > 70) return aim(null);
    const k = Math.max(-1, Math.min(1, (x - y) / 40));
    tilt.t = k * MAX * reach;
    read.textContent = (k < 0 ? "L" : "R") + Math.round(Math.abs(k) * 9);
    L.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; L.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "djembe",
  means: "A djembe goblet drum that rocks on its foot toward the pointer, its laced skin lit.",
  rules: [3, 4, 5, 9],
  range: [0.3, 1, 1],
  tour: [[303, 98], [97, 78], [250, 110], null],
  mount,
});

woodblock.code:
/**
 * Temple block: a hollow wooden block on a felt pad, a slit cut across its
 * face, and a mallet resting raised beside it. The pointer over the figure
 * swings the mallet down onto the block; the slider is how far it swings.
 * At rest the mallet head is the bright mark.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, ringAt, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GX = 78, GY = 14, GZ = 12, L = 52, HR = 8, A0 = 1.75, A1 = 2.79;
const ball = (P, x, y, z, r) => {
  const pts = [];
  for (let i = -3; i <= 3; i++) { const t = (i / 3) * (Math.PI / 2); pts.push(...ringAt(P, circ(r * Math.cos(t) + 0.01, 20).map((q) => ({ ...q, u: q.u + x, v: q.v + y })), z + r * Math.sin(t))); }
  return hull(pts);
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-4, -4, 0], [GX + 6, 32, 0], [GX + 6, -4, 0], [-4, 32, 0], [GX + L * Math.cos(A0), GY, GZ + L * Math.sin(A0) + HR]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-4, -4, 46, 32, 6, 1.5);
  put(solid(g), prism(P, front, pr, pi, 0, 3));
  const blk = solid(g), [br, bi] = rings(0, 0, 42, 28, 12, 2);
  put(blk, prism(P, front, br, bi, 3, 26));
  mk("path", { class: "nf", d: poly(ringAt(P, rrect(8, 12, 34, 16, 2, 4), 26)) + seg(P(42, 8, 10), P(42, 20, 10)) }, blk.g);
  const mg = mk("g", {}, g), handle = mk("path", { class: "sil" }, mg), head = mk("path", { class: "sil hi" }, mg);
  const t = tween(0);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const a = A0 + (A1 - A0) * v, hx = GX + L * Math.cos(a), hz = GZ + L * Math.sin(a);
    const h0 = ball(P, GX, GY, GZ, 2.2), h1 = ball(P, hx, GY, hz, 1.6);
    handle.setAttribute("d", poly(hull(h0.concat(h1))));
    head.setAttribute("d", poly(ball(P, hx, GY, hz, HR)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(t, a ? amt : 0, performance.now(), 0);
    read.textContent = a ? "tok" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: () => setActive(true), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { tset(t, amt, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "woodblock",
  means: "A temple block on its pad: the pointer swings the raised mallet down onto the block's slit top.",
  rules: [1, 3, 4, 5],
  range: [0.3, 1, 1],
  tour: [[178, 87], [143, 77], [174, 215], null],
  mount,
});

astrolabe.code:
/**
 * Astrolabe: a brass mater lying on its back with a hanging ring at the top,
 * the pierced rete over its face, star pointers on the rete, and the sighting
 * rule across both. The pointer turns rete and rule together to face it,
 * about the central pin. At rest the rule is the bright mark.
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 40, ZT = 4, A0 = -0.6;
const disc = (x, y, r, n = 48) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const rot = (ring, a) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[-R, -R - 12, 0], [R, R, 0], [R, -R - 12, 0], [-R, R, 0], [0, 0, 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const hang = solid(g), [hr, hi] = rings(-6, -R - 12, 6, -R + 4, 6, 1.5);
  put(hang, prism(P, front, hr, hi, 0, ZT));
  mk("path", { class: "nf", d: poly(ringAt(P, disc(0, -R - 5, 3, 20), ZT)) }, hang.g);
  const mat = solid(g);
  put(mat, prism(P, front, disc(0, 0, R), disc(0, 0, R - 1.5), 0, ZT));
  let tk = poly(ringAt(P, disc(0, 0, R - 6), ZT));
  for (let k = 0; k < 24; k++) { const a = (k / 24) * 2 * Math.PI, l = k % 6 ? 2.5 : 5; tk += seg(P((R - 6) * Math.cos(a), (R - 6) * Math.sin(a), ZT), P((R - 6 + l) * Math.cos(a), (R - 6 + l) * Math.sin(a), ZT)); }
  mk("path", { class: "nf lo", d: tk }, mat.g);
  const rete = mk("path", { class: "nf" }, g);
  const rule = solid(g);
  rule.sil.classList.add("hi");
  mk("path", { class: "nf", d: poly(ringAt(P, disc(0, 0, 2.5, 16), ZT + 3)) }, g);
  const t = tween(A0);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const z = ZT + 0.5, Q = (x, y) => { const c = Math.cos(a), s = Math.sin(a); return P(x * c - y * s, x * s + y * c, z); };
    const ecl = [];
    for (let k = 0; k < 48; k++) { const b = (k / 48) * 2 * Math.PI; ecl.push(Q(9 + 23 * Math.cos(b), 23 * Math.sin(b))); }
    let d = poly(ecl);
    for (const [b, r0, r1] of [[0.3, 14, 31], [1.5, 22, 33], [2.4, 16, 30], [3.5, 24, 33], [4.4, 18, 31], [5.4, 25, 33]]) {
      const c = Math.cos(b), s = Math.sin(b), w = 2.2;
      d += poly([Q(r0 * c - w * s, r0 * s + w * c), Q(r1 * c, r1 * s), Q(r0 * c + w * s, r0 * s - w * c)]);
    }
    d += seg(Q(-R + 6, 0), Q(-14, 0));
    rete.setAttribute("d", d);
    put(rule, prism(P, front, rot(rrect(-R + 2, -3, R - 2, 3, 3, 4), a + Math.PI / 2), rot(rrect(-R + 3, -2, R - 3, 2, 2, 4), a + Math.PI / 2), ZT + 1, ZT + 2.5));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);
  let cur = A0;
  function aim(p) {
    let a = A0;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], ZT), want = Math.atan2(y, x);
      a = A0 + (want - A0) * amt;
      while (a - cur > Math.PI) a -= 2 * Math.PI;
      while (cur - a > Math.PI) a += 2 * Math.PI;
    }
    if (Math.abs(a - cur) < 0.02) return;
    cur = a;
    tset(t, a, performance.now(), 0);
    read.textContent = p ? Math.round((((a * 180) / Math.PI) % 360 + 360) % 360) + "°" : "rest";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; }, destroy: bag.dispose };
}

hairline({
  name: "astrolabe",
  means: "An astrolabe on its back: the pointer turns the star rete and sighting rule round the pin to face it.",
  rules: [1, 2, 4, 5],
  range: [0.3, 1, 1],
  tour: [[162, 240], [113, 95], [282, 107], null],
  mount,
});

odometerwheel.code:
/**
 * Odometerwheel: a surveyor's measuring wheel, a spoked wheel on a long
 * handle with a counter, standing on a marked line. The pointer pulls it
 * along the line: it rolls there on a spring, its spokes turning by the
 * distance covered, and the counter reads it. At rest it stands left of
 * centre, its tyre bright. The slider is how quickly it follows.
 *
 * The pattern: a continuous slide on a spring, with rotation tied to it;
 * the hit is the pointer's screen x, which never moves.
 */
const {
  Cam, clamp, fit, hull, lerp, poly, proj, seg, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const R = 30, TH = 6, SPAN = 46, REST = -22, HL_ = 78, HA = 0.95;
const E = [Math.SQRT1_2, -Math.SQRT1_2, 0], W = [Math.SQRT1_2, Math.SQRT1_2, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.85);
  const at = (s, h, t) => [s * E[0] + t * W[0], s * E[1] + t * W[1], h];
  const hx = -HL_ * Math.cos(HA), hz = R + HL_ * Math.sin(HA);
  fit(C, [at(-SPAN - R + hx, 0, 0), at(SPAN + R, 0, 0), at(-SPAN + hx, hz + 4, 0), at(SPAN, 2 * R, 0)], 200, 166);
  const P = proj(C);
  const Q = (s, h, t) => P(...at(s, h, t));
  const g = mk("g", {}, svg);
  const marks = [seg(Q(-SPAN - R + hx, 0, 0), Q(SPAN + R, 0, 0))];
  for (let s = -SPAN - 20; s <= SPAN + 20; s += 10) marks.push(seg(Q(s, 0, -4), Q(s, 0, 4)));
  mk("path", { class: "nf lo", d: marks.join("") }, g);
  const handle = mk("path", { class: "nf" }, g), box = mk("path", { class: "sil" }, g);
  const tyre = mk("path", { class: "sil" }, g), hub = mk("path", { class: "nf lo" }, g), spokes = mk("path", { class: "nf" }, g);
  const x = spring(REST, { k: 80 * value, c: 16 * Math.sqrt(value) });
  let last = NaN;

  function ring(s0, t, r) {
    return Array.from({ length: 40 }, (_, i) => { const a = (i / 40) * Math.PI * 2; return Q(s0 + r * Math.cos(a), R + r * Math.sin(a), t); });
  }
  function draw() {
    const s0 = x.x;
    if (s0 === last) return;
    last = s0;
    const f = TH / 2;
    tyre.setAttribute("d", poly(hull(ring(s0, -f, R).concat(ring(s0, f, R)))));
    hub.setAttribute("d", poly(ring(s0, f, R - 4)) + poly(ring(s0, f + 0.5, 4)));
    const rot = -s0 / R, sp = [];
    for (let i = 0; i < 5; i++) {
      const a = rot + (i / 5) * Math.PI * 2;
      sp.push(seg(Q(s0 + 4 * Math.cos(a), R + 4 * Math.sin(a), f + 0.5), Q(s0 + (R - 4) * Math.cos(a), R + (R - 4) * Math.sin(a), f + 0.5)));
    }
    spokes.setAttribute("d", sp.join(""));
    // the handle: a fork behind the wheel up to a grip, with the counter on it
    const top = [s0 + hx, hz];
    handle.setAttribute("d", seg(Q(s0, R, -f - 2), Q(top[0], top[1], -f - 2)) +
      seg(Q(top[0], top[1], -f - 10), Q(top[0], top[1], -f + 6)));
    const m = [lerp(s0, top[0], 0.42), lerp(R, top[1], 0.42)], bp = [];
    for (const ds of [-5, 5]) for (const dh of [-4, 4]) for (const t of [-f - 6, -f + 2]) bp.push(Q(m[0] + ds, m[1] + dh, t));
    box.setAttribute("d", poly(hull(bp)));
  }
  const B = register(stage, (dt) => { const mv = stepS(x, dt); draw(); return mv; });
  bag.add(B.unregister);
  tyre.classList.add("hi");

  const c0 = Q(0, 0, 0), c1 = Q(SPAN, 0, 0);
  function roll(p) {
    if (!p) { x.t = REST; read.textContent = "rest"; }
    else {
      x.t = clamp(((p[0] - c0[0]) / (c1[0] - c0[0])) * SPAN, -SPAN, SPAN);
      read.textContent = (Math.round(x.t + SPAN) / 10).toFixed(1) + "m";
    }
    B.wake();
  }
  draw();
  roll(null);
  bag.add(pointer(stage, { move: (p) => roll(p), leave: () => roll(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { x.k = 80 * v; x.c = 16 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "odometerwheel",
  means: "A surveyor's measuring wheel on a marked line: it rolls after the pointer, its spokes turning, the counter reading the distance.",
  rules: [1, 3, 5],
  range: [0.4, 1, 2],
  tour: [[309, 244], [85, 244], [200, 230], null],
  mount,
});

clinometer.code:
/**
 * Clinometer: a quarter-circle plate with a sighting tube along its top
 * edge, pivoted on a post, a plumb needle hanging from the pivot across the
 * scale. The pointer is what to sight: the plate tilts to aim the tube at it
 * while the needle keeps hanging straight down. At rest it sights upward,
 * bright. The slider is how quickly it follows.
 *
 * The pattern: a continuous tilt on a spring; the hit is the pointer's
 * angle from the pivot's fixed screen point.
 */
const {
  Cam, clamp, fit, hull, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const R = 50, Z0 = R + 16, TH = 4, REST = 20, MAXT = 40;
const E = [Math.SQRT1_2, -Math.SQRT1_2, 0], W = [Math.SQRT1_2, Math.SQRT1_2, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  const at = (s, h, t) => [s * E[0] + t * W[0], s * E[1] + t * W[1], Z0 + h];
  fit(C, [[-16, -16, 0], [16, 16, 0], at(R + 6, R * 0.7, 0), at(-4, 8, 0), at(R * 0.8, -R * 0.8, 0)], 200, 166);
  const P = proj(C), front = facing(C);
  const Q = (s, h, t) => P(...at(s, h, t));
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-16, -16, 16, 16, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 7));
  mk("path", { class: "nf", d: seg(Q(0, -Z0 + 7, -7), Q(0, 0, -7)) + seg(Q(0, 0, -7), Q(0, 0, -TH / 2)) }, g);
  const plate = mk("path", { class: "sil" }, g), scale = mk("path", { class: "nf lo" }, g);
  const tube = mk("path", { class: "sil" }, g), needle = mk("path", { class: "nf" }, g);
  const sp = { k: 90 * value, c: 17 * Math.sqrt(value) };
  const th = spring(REST, sp);
  let last = NaN;

  function draw() {
    const T = th.x;
    if (T === last) return;
    last = T;
    const c = Math.cos(rad(T)), s = Math.sin(rad(T));
    const L = (u, v, t) => Q(u * c - v * s, u * s + v * c, t);
    const face = (t) => {
      const pts = [L(0, 0, t)];
      for (let i = 0; i <= 18; i++) { const a = rad(-90 + i * 5); pts.push(L(R * Math.cos(a), R * Math.sin(a), t)); }
      return pts;
    };
    plate.setAttribute("d", poly(hull(face(-TH / 2).concat(face(TH / 2)))));
    const ticks = [];
    for (let i = 0; i <= 9; i++) {
      const a = rad(-90 + i * 10), r0 = i % 3 === 0 ? R - 9 : R - 6;
      ticks.push(seg(L(r0 * Math.cos(a), r0 * Math.sin(a), TH / 2), L((R - 3) * Math.cos(a), (R - 3) * Math.sin(a), TH / 2)));
    }
    scale.setAttribute("d", ticks.join(""));
    const tp = [];
    for (const u of [-6, R + 6]) for (const v of [1, 7]) for (const t of [-3, 3]) tp.push(L(u, v, t));
    tube.setAttribute("d", poly(hull(tp)));
    needle.setAttribute("d", seg(Q(0, 0, TH / 2 + 0.5), Q(0, -(R - 4), TH / 2 + 0.5)));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  plate.classList.add("hi");

  const piv = P(...at(0, 0, 0));
  function aim(p) {
    if (!p) { th.t = REST; read.textContent = "rest"; }
    else {
      th.t = clamp(-Math.atan2(p[1] - piv[1], Math.max(8, p[0] - piv[0])) * 180 / Math.PI, -MAXT, MAXT);
      read.textContent = (th.t >= 0 ? "+" : "") + Math.round(th.t) + "°";
    }
    B.wake();
  }
  draw();
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { th.k = 90 * v; th.c = 17 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "clinometer",
  means: "A sighting clinometer on a post: the plate tilts to aim its tube at the pointer while the plumb needle hangs straight.",
  rules: [1, 3, 5],
  range: [0.4, 1, 2],
  tour: [[209, 162], [276, 53], [300, 220], null],
  mount,
});

heliograph.code:
/**
 * Heliograph: a signalling mirror on a fork, standing on a tripod. The
 * pointer is where the flash should go: the mirror turns and tilts to face
 * it on springs. At rest it is cocked up and aside, bright. The slider is
 * how quickly the mirror follows.
 *
 * The pattern: a continuous aim on two springs; the hit is the stage itself,
 * read in screen space, which never moves.
 */
const {
  Cam, circ, clamp, fit, hull, lerp, poly, proj, rad, seg, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const HC = 62, R = 30, TH = 3, LEG = 34, FORK = R + 5;
const REST = [-20, 42];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-LEG, -LEG, 0], [LEG, LEG, 0], [-R, R, HC + R], [R, -R, HC + R], [R, -R, HC - R], [-R, R, HC - R]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  // tripod: three legs to a head, a post up to the fork
  const head = P(0, 0, HC - R - 6), legs = [];
  for (let i = 0; i < 3; i++) {
    const t = rad(200 + i * 120);
    legs.push(seg(head, P(LEG * Math.cos(t), LEG * Math.sin(t), 0)));
  }
  mk("path", { class: "nf", d: legs.join("") }, g);
  mk("path", { class: "nf", d: seg(head, P(0, 0, HC - FORK + 2)) }, g);
  const fork = mk("path", { class: "nf" }, g);
  const rim = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), sight = mk("path", { class: "nf" }, g);
  const sp = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const yaw = spring(REST[0], sp), pit = spring(REST[1], sp);
  const V = [0.61, 0.61, 0.5];
  let lastKey = "";

  function draw() {
    const key = yaw.x.toFixed(2) + "," + pit.x.toFixed(2);
    if (key === lastKey) return;
    lastKey = key;
    const a = rad(yaw.x), b = rad(pit.x);
    const n = [Math.cos(b) * Math.cos(a), Math.cos(b) * Math.sin(a), Math.sin(b)];
    const u = [-Math.sin(a), Math.cos(a), 0];
    const v = [n[1] * u[2] - n[2] * u[1], n[2] * u[0] - n[0] * u[2], n[0] * u[1] - n[1] * u[0]];
    const ring = (off, r) => Array.from({ length: 40 }, (_, i) => {
      const t = (i / 40) * Math.PI * 2, q = (j) => [0, 0, HC][j] + n[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const facesUs = n[0] * V[0] + n[1] * V[1] + n[2] * V[2] > 0;
    const fr = ring(TH / 2, R), bk = ring(-TH / 2, R);
    rim.setAttribute("d", poly(hull(fr.concat(bk))));
    face.setAttribute("d", poly(facesUs ? ring(TH / 2, R - 5) : ring(-TH / 2, R - 5)));
    // the fork: from the post up both sides to the mirror's trunnions
    const L = [FORK * u[0], FORK * u[1]], top = HC - FORK + 2;
    fork.setAttribute("d", seg(P(-L[0], -L[1], top), P(L[0], L[1], top)) +
      seg(P(-L[0], -L[1], top), P(-L[0], -L[1], HC)) + seg(P(L[0], L[1], top), P(L[0], L[1], HC)) +
      seg(P(-L[0], -L[1], HC), P(-R * u[0], -R * u[1], HC)) + seg(P(L[0], L[1], HC), P(R * u[0], R * u[1], HC)));
    sight.setAttribute("d", facesUs ? seg(P(n[0] * 2, n[1] * 2, HC + n[2] * 2), P(n[0] * 9, n[1] * 9, HC + n[2] * 9)) : "");
  }
  const B = register(stage, (dt) => { const m1 = stepS(yaw, dt), m2 = stepS(pit, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);
  rim.classList.add("hi");

  function aim(p) {
    if (!p) { yaw.t = REST[0]; pit.t = REST[1]; read.textContent = "rest"; }
    else {
      yaw.t = clamp(lerp(-5, 95, p[0] / 400), -5, 95);
      pit.t = clamp(lerp(40, -30, p[1] / 320), -30, 40);
      read.textContent = Math.round(yaw.t) + "°";
    }
    B.wake();
  }
  draw();
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { for (const s of [yaw, pit]) { s.k = 100 * v; s.c = 18 * Math.sqrt(v); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "heliograph",
  means: "A signalling mirror on a tripod fork: it turns and tilts on springs to face the pointer.",
  rules: [1, 3, 5],
  range: [0.4, 1, 2],
  tour: [[200, 99], [110, 220], [310, 60], null],
  mount,
});

chronometer.code:
/**
 * Chronometer: a marine chronometer's square wooden box, its dial set in a
 * gimbal ring under a hinged lid. The pointer over the box swings the lid up
 * and back on its hinge to show the dial; leaving lets it settle ajar. At
 * rest the lid stands slightly open, bright. The slider is how far it opens.
 *
 * The pattern: one hinged part on a spring; the hit is the whole stage.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 56, H = 30, T = 7, REST = 26;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[0, -T - 4, 0], [W, D, 0], [W, -T - 4, H + D + 2], [0, D, 0], [0, 0, H + D + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g);
  const lid = mk("path", { class: "sil" }, lidG), panel = mk("path", { class: "nf lo" }, lidG);
  const boxG = mk("g", {}, g);
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(solid(boxG), prism(P, front, br, bi, 0, H));
  const cx = W / 2, cy = D / 2;
  mk("path", { class: "nf", d: poly(ringAt(P, disc(cx, cy, 22), H)) }, boxG);
  mk("path", { class: "nf lo", d: poly(ringAt(P, disc(cx, cy, 18), H + 0.5)) }, boxG);
  const ticks = [];
  for (let i = 0; i < 12; i++) {
    const t = (i / 12) * Math.PI * 2;
    ticks.push(seg(P(cx + 15 * Math.cos(t), cy + 15 * Math.sin(t), H + 0.5), P(cx + 17 * Math.cos(t), cy + 17 * Math.sin(t), H + 0.5)));
  }
  ticks.push(seg(P(cx, cy, H + 0.5), P(cx - 10, cy + 3, H + 0.5)), seg(P(cx, cy, H + 0.5), P(cx + 4, cy - 13, H + 0.5)));
  mk("path", { class: "nf", d: ticks.join("") }, boxG);
  // the lid's top edge, in front: drawn after when the lid is down
  const a = spring(REST, { k: 90, c: 16 });
  let last = NaN, behind = null;

  function rot(x, y, z, A) {
    const dy = y, dz = z - H, c = Math.cos(rad(A)), s = Math.sin(rad(A));
    return P(x, dy * c - dz * s, H + dy * s + dz * c);
  }
  function draw() {
    const A = a.x;
    if (A === last) return;
    last = A;
    const pts = [];
    for (const x of [0, W]) for (const y of [0, D]) for (const z of [H, H + T]) pts.push(rot(x, y, z, A));
    lid.setAttribute("d", poly(hull(pts)));
    const m = 6;
    panel.setAttribute("d", A > 12 ? poly([rot(m, m, H, A), rot(W - m, m, H, A), rot(W - m, D - m, H, A), rot(m, D - m, H, A)]) : "");
    const back = A > 90;
    if (back !== behind) { behind = back; if (back) boxG.after(lidG); else lidG.after(boxG); }
  }
  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(); return m; });
  bag.add(B.unregister);

  function setOpen(on) {
    a.t = on ? clamp(maxA, 40, 112) : REST;
    lid.classList.add("hi");
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  draw();
  setOpen(false);
  bag.add(pointer(stage, { move: () => setOpen(true), leave: () => setOpen(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (a.t !== REST) setOpen(true); }, destroy: bag.dispose };
}

hairline({
  name: "chronometer",
  means: "A marine chronometer box: the pointer swings its hinged lid up and back to show the dial in its gimbal ring.",
  rules: [1, 3, 5, 6],
  range: [60, 105, 112],
  tour: [[191, 180], [120, 230], [280, 196], null],
  mount,
});

capstan.code:
/**
 * Capstan: a ship's capstan, a drum on a round foot under a wide head with
 * six bars shipped in its sockets. The pointer is where the crew walks: the
 * head and its bars turn on a spring to put the bright first bar under the
 * pointer. At rest the bars sit at an angle, the first one bright. The slider
 * is how stiffly the capstan follows.
 *
 * The pattern: a continuous aim (officechairs' spring on an angle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, R0 = 14, R1 = 54, W = 3, HZ = 40, REST = 0.35;
const disc = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-R1, -R1, 0], [R1, R1, 0], [R1, -R1, 0], [-R1, R1, 0], [-R1, R1, HZ + 10], [R1, -R1, HZ + 10], [0, 0, HZ + 10]], 200, 222);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(24), disc(21), 0, 5));
  put(solid(g), prism(P, front, disc(14), disc(12.5), 5, HZ - 8));
  put(solid(g), prism(P, front, disc(21), disc(18.5), HZ - 8, HZ));
  // the pawl on the foot
  put(solid(g), prism(P, front, circ(3, 12).map((q) => ({ ...q, u: q.u + 20, v: q.v - 8 })), circ(2, 12).map((q) => ({ ...q, u: q.u + 20, v: q.v - 8 })), 5, 8));
  const bars = [];
  for (let k = 0; k < N; k++) {
    const grp = mk("g", {}, g);
    bars.push({ k, grp, sil: mk("path", { class: "sil" + (k === 0 ? " hi" : "") }, grp), cr: mk("path", { class: "nf lo" }, grp) });
  }
  const sp = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = NaN;
  function bar(a, r, w) {
    const c = Math.cos(a), s = Math.sin(a), pts = [];
    for (let i = 0; i <= 8; i++) { const t = -Math.PI / 2 + (i / 8) * Math.PI; pts.push({ u: (r + w * Math.cos(t)) * c - w * Math.sin(t) * s, v: (r + w * Math.cos(t)) * s + w * Math.sin(t) * c }); }
    for (let i = 0; i <= 8; i++) { const t = Math.PI / 2 + (i / 8) * Math.PI; pts.push({ u: (R0 + w * Math.cos(t)) * c - w * Math.sin(t) * s, v: (R0 + w * Math.cos(t)) * s + w * Math.sin(t) * c }); }
    return pts;
  }
  function draw() {
    const a0 = sp.x;
    if (a0 === last) return;
    last = a0;
    const order = [];
    bars.forEach((b, k) => {
      const a = a0 + (k * 2 * Math.PI) / N, ring = bar(a, R1, W);
      b.sil.setAttribute("d", poly(hull(ringAt(P, ring, HZ).concat(ringAt(P, ring, HZ + 5)))));
      b.cr.setAttribute("d", poly(ringAt(P, bar(a, R1 - 1, W - 1), HZ + 5)));
      order.push([P(R1 * 0.6 * Math.cos(a), R1 * 0.6 * Math.sin(a), HZ)[1], b]);
    });
    order.sort((p, q) => p[0] - q[0]).forEach(([, b]) => g.appendChild(b.grp));
  }
  draw();
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let on = false;
  function aim(p) {
    const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
    if (r > R1 + 30) return leave();
    let a = Math.atan2(y, x);
    while (a - sp.t > Math.PI) a -= 2 * Math.PI;
    while (a - sp.t < -Math.PI) a += 2 * Math.PI;
    sp.t = a; on = true;
    const deg = Math.round(((a * 180) / Math.PI % 360 + 360) % 360);
    read.textContent = String(deg).padStart(3, "0") + "°";
    B.wake();
  }
  function leave() { on = false; sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sp.k = 100 * v; sp.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "capstan",
  means: "A ship's capstan: the head and its six bars turn on a spring to bring the bright bar round under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.6],
  tour: [[183, 169], [292, 191], [108, 191], null],
  mount,
});

telegraph.code:
/**
 * Engine telegraph: a ship's bridge telegraph, a round dial on a column with
 * notched orders round its rim and a long lever over the face. The pointer
 * picks an order by where it stands across the dial: the lever swings to that
 * notch. At rest the lever stands at stop, bright. The slider is the throw.
 *
 * The pattern: a choice between notches (a tween on one angle).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 34, ZC = 70, TH = 8, L = 44, NS = 3, ST = 0.38, REST = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let throwK = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-14, -40, 0], [14, 40, 0], [TH, -L, ZC + L], [TH, L, ZC + L], [TH, 0, ZC - R - 4], [-TH, 0, ZC + R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(16, 32), circ(13.5, 32), 0, 5));
  put(solid(g), prism(P, front, circ(8, 24), circ(6.5, 24), 5, ZC - R + 6));
  // the dial: a drum on its side, face toward +x
  const face = (x, r, n = 48) => Array.from({ length: n }, (_, i) => { const t = (i / n) * 2 * Math.PI; return P(x, r * Math.cos(t), ZC + r * Math.sin(t)); });
  mk("path", { d: poly(hull(face(-TH, R).concat(face(TH, R)))), class: "sil" }, g);
  mk("path", { d: poly(face(TH, R - 3)), class: "nf lo" }, g);
  for (let k = -NS; k <= NS; k++) {
    const a = k * ST - Math.PI / 2, p = P(TH, (R - 6) * Math.cos(a + Math.PI / 2 - Math.PI / 2) * 0 + (R - 7) * Math.sin(k * ST), ZC + (R - 7) * Math.cos(k * ST));
    const q = P(TH, (R - 3) * Math.sin(k * ST), ZC + (R - 3) * Math.cos(k * ST));
    mk("path", { d: `M${p[0]},${p[1]}L${q[0]},${q[1]}`, class: "nf lo" }, g);
  }
  const lever = mk("g", {}, g), lsil = mk("path", { class: "sil hi" }, lever), grip = mk("path", { class: "nf" }, lever);
  mk("path", { d: poly(face(TH + 1, 4, 16)), class: "nf" }, g);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(a), c = Math.cos(a), w = 3, pts = [];
    for (const [r, o] of [[-6, -w], [-6, w], [L, w], [L, -w]]) for (const x of [TH + 1, TH + 4]) pts.push(P(x, r * s + o * c, ZC + r * c - o * s));
    lsil.setAttribute("d", poly(hull(pts)));
    const gp = [];
    for (const [r, o] of [[L - 2, -7], [L - 2, 7], [L + 3, 7], [L + 3, -7]]) for (const x of [TH + 2, TH + 9]) gp.push(P(x, r * s + o * c, ZC + r * c - o * s));
    grip.setAttribute("d", poly(hull(gp)));
    lever.appendChild(grip);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const ctr = P(TH, 0, ZC), span = R * C.S * 0.9;
  let act = 99;
  function setActive(k) {
    if (k === act) return;
    act = k;
    tset(ang, k === null ? REST : k * ST * throwK, performance.now(), 0);
    read.textContent = k === null ? "rest" : k === 0 ? "stop" : (k > 0 ? "ahd " : "ast ") + Math.abs(k);
    B.wake();
  }
  function hit([sx, sy]) {
    if (Math.abs(sy - ctr[1]) > 130 || Math.abs(sx - ctr[0]) > span * 1.6) return null;
    return Math.max(-NS, Math.min(NS, Math.round(((sx - ctr[0]) / span) * NS)));
  }
  setActive(null);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { throwK = v; const k = act; act = 99; setActive(k); }, destroy: bag.dispose };
}

hairline({
  name: "telegraph",
  means: "A ship's engine telegraph: the lever swings across the dial to the order notch under the pointer, ahead or astern.",
  rules: [1, 4, 5, 8],
  range: [0.6, 1, 1.2],
  tour: [[250, 73], [144, 167], [256, 110], null],
  mount,
});

binnacle.code:
/**
 * Binnacle: a ship's compass stand, a round pedestal on a foot holding the
 * compass bowl under a domed brass hood. The pointer over the binnacle lifts
 * the hood off the bowl to show the compass card and its lubber mark. At rest
 * the hood sits a little raised, bright. The slider is how far it lifts.
 *
 * The pattern: one part answering (cloche).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 16, BR = 32, DR = 30, DH = 22, REST = 3;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-BR, -BR, 0], [BR, BR, 0], [BR, -BR, 0], [-BR, BR, 0], [0, 0, BZ + 6 + 18 + DH + 4], [DR, DR, BZ + 6 + 18], [-DR, -DR, BZ + 6 + 18]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 24), disc(0, 0, 21), 0, 4));
  put(solid(g), prism(P, front, disc(0, 0, 14), disc(0, 0, 12), 4, BZ));
  put(solid(g), prism(P, front, disc(0, 0, BR), disc(0, 0, BR - 3), BZ, BZ + 6));
  // the compass card and its lubber mark
  mk("path", { d: poly(ringAt(P, disc(0, 0, 22, 36), BZ + 6.2)), class: "nf lo" }, g);
  const [a, b] = [P(-17, 0, BZ + 6.4), P(17, 0, BZ + 6.4)];
  mk("path", { d: `M${a[0]},${a[1]}L${b[0]},${b[1]}`, class: "nf" }, g);
  const [c, d] = [P(0, -9, BZ + 6.4), P(0, 9, BZ + 6.4)];
  mk("path", { d: `M${c[0]},${c[1]}L${d[0]},${d[1]}`, class: "nf lo" }, g);

  const hood = mk("g", {}, g);
  const dome = mk("path", { class: "sil hi" }, hood), rim = mk("path", { class: "nf lo" }, hood);
  const knob = mk("path", { class: "nf" }, hood), win = mk("path", { class: "nf lo" }, hood);
  const z = tween(REST);
  let last = NaN;
  function draw(l) {
    if (l === last) return;
    last = l;
    const base = BZ + 6.2 + l, pts = [];
    for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(0, 0, DR * Math.cos(t), 32), base + DH * Math.sin(t))); }
    pts.push(...ringAt(P, disc(0, 0, DR, 40), base - 2));
    dome.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly(ringAt(P, disc(0, 0, DR, 40), base + 1)));
    const top = base + DH;
    knob.setAttribute("d", poly(hull(ringAt(P, disc(0, 0, 4, 16), top - 1).concat(ringAt(P, disc(0, 0, 3.5, 16), top + 5)))));
    // a sight window on the hood's front
    const w = [];
    for (let i = 0; i <= 8; i++) { const t = -0.5 + i / 8; w.push(P(DR * 0.93 * Math.cos(Math.PI / 4 + t * 0.6), DR * 0.93 * Math.sin(Math.PI / 4 + t * 0.6), base + 4)); }
    for (let i = 8; i >= 0; i--) { const t = -0.5 + i / 8; w.push(P(DR * 0.8 * Math.cos(Math.PI / 4 + t * 0.6), DR * 0.8 * Math.sin(Math.PI / 4 + t * 0.6), base + 9)); }
    win.setAttribute("d", poly(w));
  }

  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, BZ / 2 + 10);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(z, a > 0 ? lift : REST, performance.now(), 0);
    read.textContent = a > 0 ? "open" : "rest";
    B.wake();
  }
  setActive(0);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.abs(sx - mid[0]) < 110 && Math.abs(sy - mid[1]) < 120 ? 1 : 0), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; if (act > 0) { tset(z, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "binnacle",
  means: "A ship's binnacle: the domed hood lifts off the compass bowl when the pointer comes over it, showing the card inside.",
  rules: [1, 5, 6, 8],
  range: [8, 16, 18],
  tour: [[200, 96], [150, 150], [270, 196], null],
  mount,
});

oarlock.code:
/**
 * Oarlock: a forked rowlock on its pin in a gunwale socket, an oar resting
 * in the fork. The rowlock swivels on its pin toward the pointer, carrying
 * the oar round with it; leaving lets it settle at a slight angle. The slider
 * is the widest swivel.
 *
 * The pattern: one part turning to face the pointer (swivel).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, circ, clamp, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GL = 90, PX = 45, PY = 0, B0 = 62, REST = 10, HW = 6, ZB = 14, ZO = 22;
const disc = (x, y, r) => circ(r, 24).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.9);
  const end = (a, t) => [PX + Math.cos(rad(a)) * t, PY + Math.sin(rad(a)) * t, ZO];
  fit(C, [[0, -7, 0], [GL, 7, 0], [GL, -7, 0], [0, 7, 0], end(B0 - 50, 74), end(B0 + 50, 74), end(B0 - 50, -36), end(B0 + 50, -36), [PX, PY, ZO + 12]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(0, -7, GL, 7, 4, 1.8);
  put(solid(g), prism(P, front, gr, gi, 0, 10));
  put(solid(g), prism(P, front, disc(PX, PY, 4.5), disc(PX, PY, 3), 10, 12.5));
  const lock = mk("g", {}, g), hornA = mk("path", { class: "sil hi" }, lock), base = mk("path", { class: "sil hi" }, lock);
  const oar = mk("path", { class: "sil" }, lock), blade = mk("path", { class: "sil" }, lock), hornB = mk("path", { class: "sil hi" }, lock);

  function tube(a, b, r) {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], n = Math.hypot(...d), u = d.map((v) => v / n);
    const p = Math.abs(u[2]) > 0.9 ? [1, 0, 0] : [0, 0, 1];
    let e1 = [u[1] * p[2] - u[2] * p[1], u[2] * p[0] - u[0] * p[2], u[0] * p[1] - u[1] * p[0]];
    const m = Math.hypot(...e1); e1 = e1.map((v) => v / m);
    const e2 = [u[1] * e1[2] - u[2] * e1[1], u[2] * e1[0] - u[0] * e1[2], u[0] * e1[1] - u[1] * e1[0]];
    const pts = [];
    for (const c of [a, b]) for (let k = 0; k < 16; k++) { const t = (k / 16) * Math.PI * 2, cs = Math.cos(t) * r, sn = Math.sin(t) * r; pts.push(P(c[0] + e1[0] * cs + e2[0] * sn, c[1] + e1[1] * cs + e2[1] * sn, c[2] + e1[2] * cs + e2[2] * sn)); }
    return poly(hull(pts));
  }
  const sw = spring(REST);
  let last = NaN;
  function draw(da) {
    if (da === last) return;
    last = da;
    const a = rad(B0 + da), c = Math.cos(a), s = Math.sin(a), nx = -s * HW, ny = c * HW;
    const hA = [PX + nx, PY + ny], hB = [PX - nx, PY - ny];
    hornA.setAttribute("d", tube([...hA, ZB], [...hA, ZO + 6], 1.7));
    hornB.setAttribute("d", tube([...hB, ZB], [...hB, ZO + 6], 1.7));
    base.setAttribute("d", tube([...hA, ZB], [...hB, ZB], 2.2) + tube([PX, PY, 11], [PX, PY, ZB], 2));
    oar.setAttribute("d", tube(end(B0 + da, -36), end(B0 + da, 46), 2.3));
    const bw = 7, b0 = end(B0 + da, 44), b1 = end(B0 + da, 74), bl = [];
    for (const q of [b0, b1]) for (const sgn of [-1, 1]) for (const z of [-1, 1]) bl.push(P(q[0] + sgn * -s * bw, q[1] + sgn * c * bw, q[2] + z * 0.8));
    blade.setAttribute("d", poly(hull(bl)));
    const fA = hA[0] + hA[1] > hB[0] + hB[1];
    (fA ? hornA : hornB).parentNode.appendChild(fA ? hornA : hornB);
    lock.insertBefore(fA ? hornB : hornA, base);
  }

  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(sw.x); return m; });
  bag.add(B.unregister);

  const piv = P(PX, PY, ZO);
  function move([sx, sy]) {
    const inside = Math.abs(sx - piv[0]) < 180 && Math.abs(sy - piv[1]) < 130;
    sw.t = inside ? clamp(((piv[0] - sx) / 110) * maxA, -maxA, maxA) : REST;
    read.textContent = inside ? Math.round(sw.t) + "°" : "rest";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { sw.t = REST; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = clamp(v, 20, 50); }, destroy: bag.dispose };
}

hairline({
  name: "oarlock",
  means: "A forked rowlock on its gunwale pin with an oar in it: the lock swivels toward the pointer, carrying the oar round.",
  rules: [1, 3, 5, 8],
  range: [20, 40, 50],
  tour: [[66, 163], [148, 112], [333, 204], null],
  mount,
});

traytable.code:
/**
 * Tray table: the back of an aircraft seat with its fold-down tray, latched
 * ajar at rest. The pointer over the seat folds the tray down flat on its
 * hinge; leaving lets it swing back to ajar. The slider is how far it opens.
 *
 * The pattern: one part swinging on a hinge (lid).
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rings, rrect, clamp, rad, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 84, D = 10, H = 104, ZH = 52, TX0 = 9, TX1 = 75, TD = 36, TH = 2.6, REST = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [W, D, 0], [0, D + TD, ZH], [W, D + TD, ZH], [W, 0, H], [0, D, H]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, H));
  // the stowed tray's recess and the latch above it, on the seat's back face
  const rec = rrect(TX0 - 1, ZH - 1, TX1 + 1, ZH + TD + 1, 3, 4).map((q) => P(q.u, D, q.v));
  mk("path", { d: poly(rec), class: "nf lo" }, g);
  const [lr, li] = rings(W / 2 - 4, D, W / 2 + 4, D + 2.5, 1.2, 0.5);
  put(solid(g), prism(P, front, lr, li, ZH + TD + 4, ZH + TD + 8));
  const tg = mk("g", {}, g), tray = mk("path", { class: "sil" }, tg), face = mk("path", { class: "nf lo" }, tg);

  const ang = tween(REST);
  let last = NaN;
  function corner(x, d, t, a) {
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    return P(x, D + d * s + t * c, ZH + d * c - t * s);
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const x of [TX0, TX1]) for (const d of [0, TD]) for (const t of [0, TH]) pts.push(corner(x, d, t, a));
    const h = hull(pts);
    tray.setAttribute("d", poly(fillet(h, h.map(() => 1.6))));
    const t = a < 45 ? TH : 0;
    const f = rrect(TX0 + 2.5, 2.5, TX1 - 2.5, TD - 2.5, 3, 4).map((q) => corner(q.u, q.v, t, a));
    face.setAttribute("d", poly(f));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const mid = P(W / 2, D + 10, ZH);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? maxA : REST, performance.now(), 0);
    tray.classList.add("hi");
    read.textContent = on ? "down" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => Math.abs(sx - mid[0]) < 90 && Math.abs(sy - mid[1]) < 120;
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = clamp(v, 60, 96); if (act) { tset(ang, maxA, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "traytable",
  means: "A seat back with its tray table ajar: the pointer folds the tray down flat on its hinge, and leaving swings it back up.",
  rules: [1, 3, 5, 6],
  range: [60, 90, 96],
  tour: [[205, 168], [170, 20], [230, 221], null],
  mount,
});

oxygenmask.code:
/**
 * Oxygen mask: an overhead cabin panel whose door swings down and lets a
 * cup mask drop on its coiled tube. The pointer over it opens the door and
 * drops the mask. At rest the door is ajar and the cup's rim is bright. The
 * slider is how far the mask falls.
 */
const { Cam, fit, proj, hull, poly, open, rrect, circ, rad, tween, tset, tval, tdone, mk, register, pointer, disposer } = HL;

const CX = 30, CY = 20, PZ = 80, TOP = 70;
const rot = (p, o, a) => { const c = Math.cos(a), s = Math.sin(a), dx = p[0] - o[0], dz = p[2] - o[2]; return [o[0] + dx * c - dz * s, p[1], o[2] + dx * s + dz * c]; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let fall = value;
  const C = Cam(45, 0.5, 2.85);
  const door = rrect(6, 6, 54, 34, 3, 3);
  const doorPts = (a) => door.map((q) => rot([q.u, q.v, PZ - 1], [6, 0, PZ], -a)).concat(door.map((q) => rot([q.u, q.v, PZ + 1], [6, 0, PZ], -a)));
  const cupPts = (zt) => circ(5, 20).map((q) => [CX + q.u, CY + q.v, zt]).concat(circ(11, 28).map((q) => [CX + q.u, CY + q.v, zt - 13]));
  const ext = doorPts(rad(100)).concat(cupPts(TOP - 50), [[0, 0, PZ + 8], [60, 40, PZ + 8], [60, 0, PZ], [0, 40, PZ]]);
  fit(C, ext, 200, 166);
  const P = proj(C), pp = (pts) => pts.map((p) => P(...p));
  const g = mk("g", {}, svg);
  const dr = mk("path", { class: "sil" }, g), tube = mk("path", { class: "nf" }, g);
  const cup = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf" }, g), bag2 = mk("path", { class: "nf lo" }, g);
  // the panel overhead, painted last: it covers what is still inside
  const pr = rrect(0, 0, 60, 40, 5, 6), pi = rrect(2, 2, 58, 38, 4, 6);
  mk("path", { class: "sil", d: poly(hull(pp(pr.map((q) => [q.u, q.v, PZ]).concat(pr.map((q) => [q.u, q.v, PZ + 8]))))) }, g);
  mk("path", { class: "nf lo", d: poly(pp(pi.map((q) => [q.u, q.v, PZ + 8]))) }, g);
  const vents = [16, 44].map((x) => mk("path", { class: "nf lo", d: poly(pp(circ(3, 12).map((q) => [x + q.u, 20 + q.v, PZ + 8]))) }, g));
  const REST = 0.15, t = tween(REST);
  let last = NaN;
  const B = register(stage, (_dt, now) => {
    const k = tval(t, now);
    if (k !== last) {
      last = k;
      const zt = TOP - k * 50, a = rad(25 + Math.min(1, k * 2) * 70);
      dr.setAttribute("d", poly(hull(pp(doorPts(a)))));
      cup.setAttribute("d", poly(hull(pp(cupPts(zt)))));
      rim.setAttribute("d", poly(pp(circ(11, 28).map((q) => [CX + q.u, CY + q.v, zt - 13]))));
      bag2.setAttribute("d", poly(pp(circ(7.5, 24).map((q) => [CX + q.u, CY + q.v, zt - 13]))));
      const coil = [];
      for (let i = 0; i <= 24; i++) { const z = PZ - (PZ - zt) * i / 24; coil.push(P(CX + (i % 2 ? 1.6 : -1.6), CY, z)); }
      tube.setAttribute("d", open(coil));
    }
    return !tdone(t, now);
  });
  bag.add(B.unregister);
  const box = pp(ext), xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const inside = ([x, y]) => x > Math.min(...xs) && x < Math.max(...xs) && y > Math.min(...ys) && y < Math.max(...ys);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(t, on ? fall / 50 : REST, performance.now(), 0);
    rim.classList.toggle("hi", !on);
    cup.classList.toggle("hi", on);
    read.textContent = on ? "drop " + Math.round(fall) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => { vents.length = 0; svg.replaceChildren(); });
  return { set: (v) => { fall = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "oxygenmask",
  means: "An overhead panel: the pointer over it swings the door down and drops the cup mask on its coiled tube.",
  rules: [1, 3, 5, 8],
  range: [25, 38, 50],
  tour: [[200, 154], [150, 110], [215, 210], null],
  mount,
});

clocking.code:
/**
 * Time clock: a wall clock-in machine with a dial on its face and a card
 * slot on its top, a time card standing half out. The pointer over it
 * pushes the card down into the slot and the minute hand jumps on. At rest
 * the card is bright. The slider is how deep the card goes.
 */
const { Cam, fit, proj, hull, poly, open, rrect, rings, prism, circ, facing, rad, tween, tset, tval, tdone, mk, solid, put, register, pointer, disposer } = HL;

const W = 52, D = 26, HT = 46, CH = 40;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let deep = value;
  const C = Cam(45, 0.5, 2.7);
  const ext = [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [8, 13, HT + CH], [44, 13, HT + CH]];
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C), pp = (pts) => pts.map((p) => P(...p));
  const g = mk("g", {}, svg);
  const [r0, r1] = rings(0, 0, W, D, 7, 2);
  put(solid(g), prism(P, front, r0, r1, 0, HT));
  mk("path", { class: "nf lo", d: poly(pp(rrect(6, 11.5, 46, 14.5, 1.5, 3).map((q) => [q.u, q.v, HT]))) }, g);
  // the dial on the front face, and its two hands
  const dial = circ(11, 32).map((q) => [26 + q.u, D + 0.2, 30 + q.v]);
  mk("path", { d: poly(pp(dial)) }, g);
  mk("path", { class: "nf lo", d: poly(pp(circ(9, 28).map((q) => [26 + q.u, D + 0.3, 30 + q.v]))) }, g);
  const hr = mk("path", { class: "nf", d: open(pp([[26, D + 0.4, 30], [30, D + 0.4, 34]])) }, g);
  const mn = mk("path", { class: "nf" }, g);
  mk("path", { class: "nf lo", d: poly(pp(rrect(16, 6, 36, 12, 2, 3).map((q) => [q.u, D + 0.2, q.v]))) }, g);
  const card = mk("path", { class: "sil" }, g), rows = mk("path", { class: "nf lo" }, g);
  const REST = 0, t = tween(REST);
  let last = NaN;
  const B = register(stage, (_dt, now) => {
    const k = tval(t, now);
    if (k !== last) {
      last = k;
      const h = CH - k, top = HT + h, cr = rrect(8, HT, 44, top, 1.5, 3);
      card.setAttribute("d", poly(hull(pp(cr.map((q) => [q.u, 12.6, q.v]).concat(cr.map((q) => [q.u, 13.4, q.v]))))));
      let d = "";
      for (let z = top - 8; z > HT + 2; z -= 4) d += open(pp([[11, 13.5, z], [41, 13.5, z]]));
      d += open(pp([[11, 13.5, top - 4], [18, 13.5, top - 4]]));
      rows.setAttribute("d", d);
      const a = rad(90 - 30 - k * 4.5);
      mn.setAttribute("d", open(pp([[26, D + 0.4, 30], [26 + 8 * Math.cos(a), D + 0.4, 30 + 8 * Math.sin(a)]])));
    }
    return !tdone(t, now);
  });
  bag.add(B.unregister);
  const box = pp(ext), xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const inside = ([x, y]) => x > Math.min(...xs) && x < Math.max(...xs) && y > Math.min(...ys) && y < Math.max(...ys);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(t, on ? deep : REST, performance.now(), 0);
    card.classList.toggle("hi", !on);
    mn.classList.toggle("hi", on);
    read.textContent = on ? "in " + Math.round(deep) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => { hr.remove(); svg.replaceChildren(); });
  return { set: (v) => { deep = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "clocking",
  means: "A time clock: the pointer over it pushes the time card down into the slot and the minute hand jumps on.",
  rules: [1, 3, 5, 8],
  range: [30, 35, 38],
  tour: [[200, 93], [200, 200], [150, 160], null],
  mount,
});

tapemeasure.code:
/**
 * Tape measure: a rounded square case standing on its edge, its steel blade
 * running out of the mouth at the foot with a hook on the end. The pointer
 * over it pulls the blade out along the ground; the slider is how far. At
 * rest a short length of blade lies out, its hook bright.
 */
const { Cam, clamp, fillet, fit, hull, poly, proj, unproj, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

// a world point turned about an axis along x or y through h, then moved by d
function rot(p, r) {
  if (!r) return p;
  let [x, y, z] = p;
  const c = Math.cos(r.a), s = Math.sin(r.a), d = r.d || [0, 0, 0];
  if (r.ax === "y") { const u = x - r.h[0], w = z - r.h[1]; x = r.h[0] + u * c - w * s; z = r.h[1] + u * s + w * c; }
  else if (r.ax === "x") { const u = y - r.h[0], w = z - r.h[1]; y = r.h[0] + u * c - w * s; z = r.h[1] + u * s + w * c; }
  return [x + d[0], y + d[1], z + d[2]];
}
const box = ([x0, y0, z0, x1, y1, z1]) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
const rnd = (pts, r) => fillet(pts, pts.map(() => r), 3);
function part(g, cls) { const p = mk("g", {}, g); return { g: p, sil: mk("path", { class: cls || "sil" }, p), cr: mk("path", { class: "nf lo" }, p) }; }
// a solid from its corners: a rounded hull, and the top face as its one crease
function draw(P, el, pts, top, r, rr) {
  const q = pts.map((p) => P(...rot(p, r)));
  el.sil.setAttribute("d", poly(rnd(hull(q), rr || 2.5)));
  el.cr.setAttribute("d", top ? poly(rnd(top.map((i) => q[i]), 1.5)) : "");
}
const TOPF = [4, 5, 6, 7];

function make(F) {
  return function mount({ stage, svg, read }, value) {
    const bag = disposer();
    let amp = value;
    const C = Cam(45, 0.5, F.S);
    fit(C, F.ext(F.range[2]), 200, 166);
    const P = proj(C), g = mk("g", {}, svg);
    const fig = F.build(g, P), tw = tween(F.rest);
    let last = NaN;
    const B = register(stage, (_dt, now) => {
      const t = tval(tw, now);
      if (t !== last) { last = t; fig.render(t, amp); }
      return !tdone(tw, now);
    });
    bag.add(B.unregister);
    // the hit: the pointer on a fixed plane through the resting body
    function hit([sx, sy]) {
      const [x, y] = unproj(C, sx, sy, F.hz), [x0, y0, x1, y1] = F.foot;
      return x > x0 && x < x1 && y > y0 && y < y1;
    }
    let act = null;
    function set(on) {
      if (on === act) return;
      act = on;
      tset(tw, on ? 1 : F.rest, performance.now(), 0);
      read.textContent = on ? F.say(amp) : "rest";
      B.wake();
    }
    set(false);
    fig.hi.classList.add("hi");
    bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(false) }));
    bag.add(() => svg.replaceChildren());
    return { set: (v) => { amp = v; last = NaN; if (act) read.textContent = F.say(amp); B.wake(); }, destroy: bag.dispose };
  };
}
const hide = (el) => { el.sil.setAttribute("d", ""); el.cr.setAttribute("d", ""); };

const CS = 30, W = 12, BL = 64;
const F = {
  S: 3.8, rest: 0.4, hz: 2, foot: [-6, -14, CS + BL + 10, W + 14], range: [0.5, 0.8, 1],
  say: (a) => "out " + Math.round(a * 100) + "%",
  ext() {
    return box([0, 0, 0, CS + BL + 4, W, CS]);
  },
  build(g, P) {
    const blade = part(g), hook = part(g), cas = part(g), lock = part(g);
    draw(P, cas, box([0, 0, 0, CS, W, CS]), TOPF, null, 9);
    draw(P, lock, box([6, -1, CS - 4, 16, W + 1, CS + 1.5]), null, null, 1.5);
    return {
      hi: hook.sil,
      render(t, a) {
        const x = CS + 1 + BL * t * a;
        draw(P, blade, box([CS - 2, 1.5, 1, x, W - 1.5, 2.2]), TOPF, null, 0.6);
        draw(P, hook, box([x, 1, 0, x + 2.5, W - 1, 5]), null, null, 0.8);
      },
    };
  },
};

hairline({
  name: "tapemeasure",
  means: "A tape measure: the pointer over it pulls the steel blade out of the case along the ground, hook first.",
  rules: [3, 4, 5, 6],
  range: [0.5, 0.8, 1],
  tour: [[149, 183], [283, 250], [82, 150], null],
  mount: make(F),
});

staplegun.code:
/**
 * Staple gun: a heavy-duty staple gun, a squat body with the staple track
 * along its foot and a long lever hinged at the back. The pointer over it
 * squeezes the lever open and shut; the slider is how far it swings. At rest
 * the lever sits a little open, bright.
 */
const { Cam, clamp, fillet, fit, hull, poly, proj, unproj, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

// a world point turned about an axis along x or y through h, then moved by d
function rot(p, r) {
  if (!r) return p;
  let [x, y, z] = p;
  const c = Math.cos(r.a), s = Math.sin(r.a), d = r.d || [0, 0, 0];
  if (r.ax === "y") { const u = x - r.h[0], w = z - r.h[1]; x = r.h[0] + u * c - w * s; z = r.h[1] + u * s + w * c; }
  else if (r.ax === "x") { const u = y - r.h[0], w = z - r.h[1]; y = r.h[0] + u * c - w * s; z = r.h[1] + u * s + w * c; }
  return [x + d[0], y + d[1], z + d[2]];
}
const box = ([x0, y0, z0, x1, y1, z1]) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
const rnd = (pts, r) => fillet(pts, pts.map(() => r), 3);
function part(g, cls) { const p = mk("g", {}, g); return { g: p, sil: mk("path", { class: cls || "sil" }, p), cr: mk("path", { class: "nf lo" }, p) }; }
// a solid from its corners: a rounded hull, and the top face as its one crease
function draw(P, el, pts, top, r, rr) {
  const q = pts.map((p) => P(...rot(p, r)));
  el.sil.setAttribute("d", poly(rnd(hull(q), rr || 2.5)));
  el.cr.setAttribute("d", top ? poly(rnd(top.map((i) => q[i]), 1.5)) : "");
}
const TOPF = [4, 5, 6, 7];

function make(F) {
  return function mount({ stage, svg, read }, value) {
