filterwrench.code:
/**
 * Oil filter wrench: a spin-on filter canister standing on its base, a strap
 * band cinched round its middle and a long handle off the band. The handle
 * swings round the canister to point at the pointer, on a spring; at rest it
 * points out to the front right, the strap bright. The slider is the reach.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, clamp, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 22, FH = 50, SZ = 26, L = 50, REST = -40;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, circ(R + L + 6, 16).map((q) => [q.u, q.v, SZ]).concat([[0, 0, 0], [0, 0, FH + 4]]), 200, 166);
  const P = proj(C), front = facing(C);
  const back = mk("g", {}, svg), g = mk("g", {}, svg), fore = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, R + 3), disc(0, 0, R + 1), 0, 4));
  put(solid(g), prism(P, front, disc(0, 0, R), disc(0, 0, R - 2), 4, FH));
  mk("path", { d: poly(ringAt(P, disc(0, 0, 7, 24), FH)), class: "nf lo" }, g);
  const strap = mk("path", { class: "sil hi" }, g);
  const s0 = ringAt(P, disc(0, 0, R + 1.5), SZ - 3), s1 = ringAt(P, disc(0, 0, R + 1.5), SZ + 3);
  strap.setAttribute("d", poly(hull(s0.concat(s1))));
  const hg = mk("g", {}, fore), handle = mk("path", { class: "sil" }, hg), grip = mk("path", { class: "nf lo" }, hg);
  const ang = spring(REST);
  let last = NaN, side = 1;
  const bar = (a, r0, r1, w, z) => { const c = Math.cos(a), s = Math.sin(a), out = []; for (const r of [r0, r1]) for (const q of circ(w, 12)) out.push(P(c * r - s * q.u, s * r + c * q.u, z + q.v)); return poly(hull(out)); };
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180;
    handle.setAttribute("d", bar(a, R, R + L, 3.4, SZ));
    grip.setAttribute("d", bar(a, R + L * 0.55, R + L - 3, 4.4, SZ));
    const s = Math.cos(a) + Math.sin(a) >= 0 ? 1 : -1;
    if (s !== side) { side = s; (s > 0 ? fore : back).appendChild(hg); }
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, SZ), d = Math.hypot(x, y);
    if (d > R + L + 16) return leave();
    let deg = (Math.atan2(y, x) * 180) / Math.PI;
    while (deg - ang.x > 180) deg -= 360;
    while (deg - ang.x < -180) deg += 360;
    ang.t = REST + clamp(deg - REST, -reach, reach);
    read.textContent = (((Math.round(ang.t) % 360) + 360) % 360) + "°";
    B.wake();
  }
  function leave() { ang.t = REST + 360 * Math.round((ang.x - REST) / 360); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "filterwrench",
  means: "A strap wrench round an oil filter, its long handle swinging round to point at the pointer.",
  rules: [1, 3, 5, 8],
  range: [60, 150, 180],
  tour: [[66, 195], [85, 109], [391, 166], null],
  mount,
});

enginecrane.code:
/**
 * Engine stand: a post on a T foot holds an engine block out on its mount
 * head, free to roll about the long axis. The pointer across the block rolls
 * it over on a spring, one way or the other by where it stands; at rest the
 * block sits tipped, its pulley bright. The slider is the roll's reach.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 52, BX0 = 10, BX1 = 70, HW = 20, HH = 17, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-26, -34, 0], [-26, 34, 0], [BX1 + 6, -28, H + 28], [BX1 + 6, 28, H - 28], [BX1 + 6, 0, H + 28]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const roll = (q, a, x) => { const c = Math.cos(a), s = Math.sin(a); return P(x, q.u * c - q.v * s, H + q.u * s + q.v * c); };
  const [fr, fi] = rings(-30, -34, -18, 34, 5, 1.5);
  put(solid(g), prism(P, front, fr, fi, 0, 6));
  const [lr, li] = rings(-28, -6, 10, 6, 4, 1.5);
  put(solid(g), prism(P, front, lr, li, 0, 5));
  const [pr0, pi0] = rings(-27, -4, -19, 4, 3, 1.2);
  put(solid(g), prism(P, front, pr0, pi0, 6, H + 6));
  const [ar, ai] = rings(-24, -3, BX0, 3, 2, 1);
  put(solid(g), prism(P, front, ar, ai, H - 3, H + 3));
  const blk = rrect(-HW, -HH, HW, HH, 6, 6), inner = rrect(-HW + 3, -HH + 3, HW - 3, HH - 3, 4, 6);
  const head = circ(10, 24);
  mk("path", { d: poly(hull(head.map((q) => P(BX0 - 4, q.u, H + q.v)).concat(head.map((q) => P(BX0, q.u, H + q.v))))), class: "sil" }, g);
  const body = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), bank = mk("path", { class: "nf lo" }, g);
  const pul = mk("path", { class: "sil hi" }, g), hub = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180;
    body.setAttribute("d", poly(hull(blk.map((q) => roll(q, a, BX0)).concat(blk.map((q) => roll(q, a, BX1))))));
    face.setAttribute("d", poly(inner.map((q) => roll(q, a, BX1))));
    bank.setAttribute("d", poly([{ u: -HW, v: HH * 0.35 }, { u: HW, v: HH * 0.35 }].map((q) => roll(q, a, BX1)).concat([{ u: HW, v: HH * 0.35 }, { u: -HW, v: HH * 0.35 }].map((q) => roll(q, a, BX0)))));
    const pc = circ(8, 24).map((q) => ({ u: q.u, v: q.v - 6 }));
    pul.setAttribute("d", poly(hull(pc.map((q) => roll(q, a, BX1)).concat(pc.map((q) => roll(q, a, BX1 + 5))))));
    hub.setAttribute("d", poly(circ(2.5, 12).map((q) => roll({ u: q.u, v: q.v - 6 }, a, BX1 + 5))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < BX0 - 10 || x > BX1 + 14 || Math.abs(y) > 34) return leave();
    const t = clamp(y / 30, -1, 1);
    ang.t = t * maxA;
    read.textContent = Math.round(ang.t) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "enginecrane",
  means: "An engine stand: the pointer across the block rolls it over on its mount head, one way or the other.",
  rules: [1, 3, 5, 8],
  range: [30, 80, 90],
  tour: [[265, 122], [225, 141], [189, 160], null],
  mount,
});

partswasher.code:
/**
 * Parts washer: a solvent tub sitting on its drum, its lid hinged along the
 * back edge. The pointer over the tub lifts the lid open on a spring, further
 * the nearer it comes to the front; at rest the lid stands ajar, bright.
 * The slider is how far the lid can open.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, spring, stepS, unproj, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 90, D = 60, DR = 30, DH = 46, TH = 22, LT = 3, REST = 16;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.85);
  const Z = DH + TH;
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, 0, Z + D], [W, 0, Z + D], [0, D, Z + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const cx = W / 2, cy = D / 2;
  put(solid(g), prism(P, front, disc(cx, cy, DR), disc(cx, cy, DR - 2), 0, DH));
  mk("path", { d: poly(ringAt(P, disc(cx, cy, DR, 40), DH * 0.5)).replace(/Z$/, ""), class: "nf lo" }, g);
  const [br, bi] = rings(0, 0, W, D, 6, 2);
  put(solid(g), prism(P, front, br, bi, DH, Z));
  mk("path", { d: poly(ringAt(P, rrect(6, 6, W - 6, D - 6, 4, 6), Z)), class: "nf lo" }, g);
  const lidR = rrect(-1, 0, W + 1, D + 2, 5, 6), lidI = rrect(4, 5, W - 4, D - 3, 3, 6);
  const lid = mk("path", { class: "sil" }, g), lidC = mk("path", { class: "nf lo" }, g), knob = mk("path", { class: "nf" }, g);
  const at = (q, a, off) => { const c = Math.cos(a), s = Math.sin(a); return P(q.u, q.v * c + off * s, Z + q.v * s - off * c + off); };
  const ang = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180;
    lid.setAttribute("d", poly(hull(lidR.map((q) => at(q, a, 0)).concat(lidR.map((q) => at(q, a, LT))))));
    lidC.setAttribute("d", poly(lidI.map((q) => at(q, a, LT))));
    const k = [{ u: cx - 8, v: D - 6 }, { u: cx + 8, v: D - 6 }];
    knob.setAttribute("d", poly(hull(k.map((q) => at(q, a, LT)).concat(k.map((q) => at(q, a, LT + 4))))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  lid.classList.add("hi");

  function move([sx, sy]) {
    let best = null;
    for (const z of [Z, DH * 0.5]) { const [x, y] = unproj(C, sx, sy, z); if (x > -4 && x < W + 4 && y > -4 && y < D + 4) { best = y; break; } }
    if (best === null) return leave();
    const t = clamp(best / D, 0, 1);
    ang.t = REST + (maxA - REST) * (0.45 + 0.55 * t);
    read.textContent = Math.round(ang.t) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "partswasher",
  means: "A parts washer on its drum: the pointer over the tub lifts the hinged lid, wider the nearer the front.",
  rules: [1, 3, 5, 8],
  range: [40, 85, 95],
  tour: [[174, 179], [220, 215], [180, 140], null],
  mount,
});

timinglight.code:
/**
 * Timing light: a strobe gun stood on its grip on the bench, a long body
 * with a wide lamp head at the front and a trigger under it. The pointer is
 * the mark on the crank pulley: the gun turns on its grip to aim the head
 * at it, on a spring. At rest it points off to one side, its head bright.
 * The slider is how stiffly it turns.
 *
 * The pattern: a continuous aim (terrain's spring, on an angle); the depth
 * order of head and body swaps as it turns.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 0.5;
const box = (u0, v0, u1, v1, r, b) => rings(u0, v0, u1, v1, r, b);
// footprints in the gun's own frame: +u is where it aims
const GRIP = box(-22, -6, -8, 6, 4, 1.4), BODY = box(-30, -8, 20, 8, 6, 1.6), HEAD = box(18, -14, 32, 14, 6, 1.8), TRIG = box(-6, -3, 2, 3, 2, 0.8);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-36, -36, 0], [36, 36, 0], [36, -36, 48], [-36, 36, 48], [0, 0, 50]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-14, -14, 14, 14, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  const cord = mk("path", { class: "nf lo" }, g);
  const grip = solid(g), trig = solid(g), body = solid(g), head = solid(g);
  head.sil.classList.add("hi");

  const ang = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  const rot = (ring, a) => ring.map((q) => {
    const c = Math.cos(a), s = Math.sin(a);
    const uu = q.u + 15;
    return { u: uu * c - q.v * s, v: uu * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c };
  });
  const rp = (r, a) => [rot(r[0], a), rot(r[1], a)];
  let last = NaN;
  function draw() {
    const a = ang.x;
    if (a === last) return;
    last = a;
    let [o, i] = rp(GRIP, a); put(grip, prism(P, front, o, i, 3, 30));
    [o, i] = rp(TRIG, a); put(trig, prism(P, front, o, i, 22, 31));
    [o, i] = rp(BODY, a); put(body, prism(P, front, o, i, 30, 44));
    [o, i] = rp(HEAD, a); put(head, prism(P, front, o, i, 26, 48));
    const c = Math.cos(a), s = Math.sin(a), tail = [-15 * c, -15 * s];
    cord.setAttribute("d", seg(P(tail[0], tail[1], 36), P(tail[0] - 10 * c, tail[1] - 10 * s, 20)) + seg(P(tail[0] - 10 * c, tail[1] - 10 * s, 20), P(-30, 6, 3)));
    // the head sits in front of the body when it aims toward the viewer
    if (c + s > 0) body.g.after(head.g); else body.g.before(head.g);
  }
  draw();
  read.textContent = "rest";

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      let t = Math.atan2(y, x);
      while (t - ang.t > Math.PI) t -= 2 * Math.PI;
      while (t - ang.t < -Math.PI) t += 2 * Math.PI;
      ang.t = t;
      read.textContent = ((Math.round(t * 180 / Math.PI) % 360) + 360) % 360 + "°";
      B.wake();
    },
    leave: () => { ang.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { ang.k = 100 * v; ang.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "timinglight",
  means: "A strobe timing light stood on its grip: the gun turns to aim its lamp head at the pointer, like the mark on a pulley.",
  rules: [1, 3, 5, 6, 8],
  range: [0.5, 1, 1.6],
  tour: [[348, 196], [76, 184], [52, 196], null],
  mount,
});

rocketnozzle.code:
/**
 * Rocket nozzle: one engine hung under its thrust plate, a short combustion
 * chamber and a wide bell, pushed by two actuator rods. The pointer is where
 * the thrust should go: the bell gimbals on its pivot so its mouth swings
 * toward the pointer, on a spring. At rest it leans a little, bright.
 * The slider is the gimbal's reach in degrees.
 *
 * The pattern: a continuous aim (terrain's spring, on an angle).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, open, prism, proj, rings, run, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 84, REST = [0.16, -0.08];
const disc = (r, n = 32) => circ(r, n);
// bell profile: [radius, height] from the throat down to the mouth
const PROF = [];
for (let i = 0; i <= 8; i++) { const t = i / 8; PROF.push([7 + 22 * Math.pow(t, 0.8), 64 - 62 * t]); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-26, -26, PZ + 7], [26, 26, PZ + 7], [26, -26, PZ], [-26, 26, PZ], [-40, 0, 6], [40, 0, 6], [0, 40, 6], [0, -40, 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const bell = mk("path", { class: "sil hi" }, g);
  const ribs = [0.45, 0.75].map(() => mk("path", { class: "nf lo" }, g));
  const lip = mk("path", { class: "nf" }, g);
  const chamber = mk("path", { class: "sil" }, g);
  const rods = mk("path", { class: "nf" }, g);
  const [pr, pi] = rings(-22, -22, 22, 22, 7, 2);
  put(solid(g), prism(P, front, pr, pi, PZ, PZ + 7));

  const gx = spring(REST[0], { k: 90, c: 16 }), gy = spring(REST[1], { k: 90, c: 16 });
  function R(x, y, z, a, b) {
    const dz = z - PZ;
    const x1 = x * Math.cos(a) - dz * Math.sin(a), z1 = x * Math.sin(a) + dz * Math.cos(a);
    const y2 = y * Math.cos(b) - z1 * Math.sin(b), z2 = y * Math.sin(b) + z1 * Math.cos(b);
    return P(x1, y2, z2 + PZ);
  }
  const ringR = (r, z, a, b, keep) => (keep ? run(disc(r), front) : disc(r)).map((q) => R(q.u, q.v, z, a, b));
  let la = NaN, lb = NaN;
  function draw() {
    const a = gx.x, b = gy.x;
    if (a === la && b === lb) return;
    la = a; lb = b;
    const pts = [];
    for (const [r, z] of PROF) pts.push(...ringR(r, z, a, b));
    bell.setAttribute("d", poly(hull(pts)));
    [0.45, 0.75].forEach((t, i) => { const [r, z] = PROF[Math.round(t * 8)]; ribs[i].setAttribute("d", open(ringR(r, z, a, b, true))); });
    lip.setAttribute("d", open(ringR(PROF[8][0], PROF[8][1] + 2.5, a, b, true)));
    chamber.setAttribute("d", poly(hull(ringR(9, PZ, a, b).concat(ringR(10, 64, a, b), ringR(7.5, 61, a, b)))));
    rods.setAttribute("d", seg(P(18, 0, PZ), R(13, 0, 48, a, b)) + seg(P(0, 18, PZ), R(0, 13, 48, a, b)));
  }
  draw();
  read.textContent = "rest";

  const B = register(stage, (dt) => { const m1 = stepS(gx, dt), m2 = stepS(gy, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y) || 1;
      const m = (reach * Math.PI / 180) * clamp(r / 40, 0, 1);
      gx.t = (x / r) * m; gy.t = (y / r) * m;
      read.textContent = "tilt " + Math.round(m * 180 / Math.PI) + "°";
      B.wake();
    },
    leave: () => { gx.t = REST[0]; gy.t = REST[1]; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "rocketnozzle",
  means: "A rocket engine's bell under its thrust plate: the nozzle gimbals on its pivot so its mouth swings toward the pointer.",
  rules: [1, 3, 5, 8],
  range: [10, 20, 30],
  tour: [[133, 219], [118, 279], [200, 297], null],
  mount,
});

flipbook.code:
/**
 * Flip book: a small pad of pages on its back cover, bound along one edge.
 * The pointer across the pad thumbs pages over the spine, more the nearer it
 * stands to the spine, staggered from the page it touched. At rest the top
 * pages curl up a little and the top one is bright. The slider is the stagger.
 */
const { Cam, fit, fillet, poly, prism, proj, rings, unproj, clamp, rad, tween, tset, tval, tdone, mk, pointer, put, register, solid, disposer, facing } = HL;

const W = 56, D = 40, N = 9, T = 1.6, Z0 = 3;
const REST = [16, 9, 4];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[-W, 0, 0], [W, D, 0], [W, 0, 0], [-W, D, 0], [0, 0, W + 4], [0, D, W + 4]], 180, 155);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-1, -2, W + 2, D + 2, 3, 1.2);
  put(solid(g), prism(P, front, cr, ci, 0, Z0));
  const pg = mk("g", {}, g);
  const pages = [];
  for (let j = 0; j < N; j++) {
    const el = mk("path", { class: j === 0 ? "sil hi" : "" }, pg);
    pages.push({ j, el, a: tween(REST[j] || 0), z: Z0 + (N - 1 - j) * T, last: NaN, flip: false });
  }

  function draw(p, a) {
    if (a === p.last) return;
    p.last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a)), z = p.z + T * 0.5;
    const q = [P(0, 0, z), P(W * c, 0, z + W * s), P(W * c, D, z + W * s), P(0, D, z)];
    p.el.setAttribute("d", poly(fillet(q, [0.5, 3, 3, 0.5])));
  }
  let order = "";
  function sortPages(now) {
    const ks = pages.map((p) => ({ p, k: tval(p.a, now) > 90 ? p.j : 100 + N - p.j })).sort((x, y) => x.k - y.k);
    const o = ks.map((x) => x.p.j).join();
    if (o !== order) { order = o; ks.forEach((x) => pg.appendChild(x.p.el)); }
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const p of pages) { draw(p, tval(p.a, now)); if (!tdone(p.a, now)) moving = true; }
    sortPages(now);
    return moving;
  });
  bag.add(B.unregister);

  let act = -2;
  function setK(k) {
    if (k === act) return;
    const now = performance.now(), from = act;
    act = k;
    pages.forEach((p) => {
      const a = k < 0 ? (REST[p.j] || 0) : p.j < k ? 172 - p.j * 1.5 : p.j === k ? 24 : 0;
      tset(p.a, a, now, Math.abs(p.j - Math.max(k, 0)) * stag);
      p.el.classList.toggle("sil", p.j === (k < 0 ? 0 : k));
      p.el.classList.toggle("hi", p.j === (k < 0 ? 0 : k));
    });
    read.textContent = k < 0 ? "rest" : "p " + (k + 1);
    B.wake();
  }
  setK(-1);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [wx, wy] = unproj(C, sx, sy, Z0 + N * T);
      if (wx < -6 || wx > W + 6 || wy < -10 || wy > D + 10) return setK(-1);
      setK(1 + Math.round(clamp((W - wx) / W, 0, 1) * (N - 3)));
    },
    leave: () => setK(-1),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "flipbook",
  means: "A flip book on its cover: the pointer thumbs pages over the spine, more the nearer it is to the spine, one after another.",
  rules: [1, 2, 5, 6],
  range: [0, 40, 80],
  tour: [[191, 165], [241, 190], [290, 214], null],
  mount,
});

zoetrope.code:
/**
 * Zoetrope: a slotted drum on a spindle and round foot. The pointer over it
 * lifts the drum on its spindle and turns it by where the pointer stands, the
 * slots sliding round the wall. At rest the drum sits turned a little, its
 * rim bright. The slider is how far it turns.
 */
const { Cam, circ, fit, poly, prism, proj, ringAt, hull, seg, spring, stepS, clamp, mk, pointer, put, register, solid, disposer, facing } = HL;

const R = 32, H = 38, BZ = 10, N = 12, SR = 16, L0 = 8;
const ring = (r, n = 56) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [0, 0, BZ + 26 + H + 4]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ring(SR + 8), ring(SR + 6), 0, 3));
  put(solid(g), prism(P, front, ring(SR), ring(SR - 2), 3, 5));
  const spin = solid(g);
  const drum = solid(g);
  const lip = mk("path", { class: "nf lo" }, g), slots = mk("path", { class: "nf" }, g);
  drum.sil.classList.add("hi");
  const lift = spring(L0), rot = spring(0.35);
  let last = "";

  function draw() {
    const z0 = BZ + 4 + lift.x, z1 = z0 + H, a = rot.x, key = z0.toFixed(2) + a.toFixed(3);
    if (key === last) return;
    last = key;
    put(spin, prism(P, front, ring(3, 16), ring(2, 16), 5, z0 + 2));
    put(drum, prism(P, front, ring(R), ring(R - 2), z0, z1));
    lip.setAttribute("d", poly(ringAt(P, ring(R - 2.5), z1)));
    let d = "";
    for (let i = 0; i < N; i++) {
      const t = a + (i / N) * Math.PI * 2, nu = Math.cos(t), nv = Math.sin(t);
      if (!front({ u: R * nu, v: R * nv, nu, nv })) continue;
      for (const dt of [-0.06, 0.06]) {
        const c = Math.cos(t + dt), s = Math.sin(t + dt);
        d += seg(P(R * c, R * s, z1 - 4), P(R * c, R * s, z1 - 20));
      }
    }
    slots.setAttribute("d", d);
  }

  const B = register(stage, (dt) => {
    const m1 = stepS(lift, dt), m2 = stepS(rot, dt);
    draw();
    return m1 || m2;
  });
  bag.add(B.unregister);
  draw();

  const c0 = P(0, 0, BZ + 4 + H / 2);
  function move([sx, sy]) {
    const on = Math.abs(sx - c0[0]) < 120 && Math.abs(sy - c0[1]) < 90;
    if (!on) return leave();
    const f = clamp((sx - c0[0]) / 110, -1, 1);
    lift.t = 22;
    rot.t = 0.35 + f * Math.PI * (0.4 + amt);
    read.textContent = "turn " + Math.round(f * 100);
    B.wake();
  }
  function leave() { lift.t = L0; rot.t = 0.35; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; }, destroy: bag.dispose };
}

hairline({
  name: "zoetrope",
