bilboquet.code:
/**
 * Bilboquet: a cup on a turned stick standing in its foot, a ball tied to the
 * stick by a string. The pointer over the toy swings the ball up on its
 * string and drops it into the cup; leaving lets it fall back to hang. At
 * rest the ball hangs a little to one side, bright. The slider is its lean.
 */
const { Cam, circ, fit, hull, open, poly, prism, proj, ringAt, facing, lerp, clamp, tween, tset, tval, tdone, mk, pointer, put, register, solid, disposer } = HL;

const S = 3.7, TIE = 40, L = 34, BR = 8, CZ0 = 58, CZ1 = 70, SEAT = 75;
const ring = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lean = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-16, -16, 0], [16, 16, 0], [L + BR, 0, TIE], [0, 0, SEAT + BR + 2], [-14, 0, CZ1]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ring(16), ring(14), 0, 3));
  put(solid(g), prism(P, front, ring(3, 16), ring(2, 16), 3, CZ0 - 6));
  put(solid(g), prism(P, front, ring(4.5, 20), ring(3.5, 20), TIE - 2, TIE + 2));
  const cup = mk("path", { class: "sil" }, g);
  cup.setAttribute("d", poly(hull(ringAt(P, ring(3, 20), CZ0 - 6).concat(ringAt(P, ring(13), CZ1)))));
  mk("path", { d: poly(ringAt(P, ring(11), CZ1)), class: "nf lo" }, g);
  const str = mk("path", { class: "nf lo" }, g);
  const ball = mk("ellipse", { class: "sil hi", rx: BR * S, ry: BR * S }, g);
  const t = tween(0);
  let last = "";

  function pos(u) {
    const a0 = -Math.PI / 2 + lean, a1 = 0.6;
    const arc = (a) => [L * Math.cos(a) + 4.5, 0, TIE + L * Math.sin(a)];
    if (u < 0.6) return arc(lerp(a0, a1, u / 0.6));
    const s = (u - 0.6) / 0.4, p0 = arc(a1), c = [16, 0, 104], p1 = [0, 0, SEAT];
    return [0, 2].reduce((q, k) => (q[k] = (1 - s) * (1 - s) * p0[k] + 2 * s * (1 - s) * c[k] + s * s * p1[k], q), [0, 0, 0]);
  }
  function draw(u) {
    const key = u.toFixed(4) + lean;
    if (key === last) return;
    last = key;
    const b = pos(clamp(u, 0, 1)), tie = [4.5, 0, TIE], sb = P(...b);
    ball.setAttribute("cx", sb[0]); ball.setAttribute("cy", sb[1]);
    const dx = b[0] - tie[0], dz = b[2] - tie[2], slack = Math.max(0, L - Math.hypot(dx, dz));
    const pts = [];
    for (let i = 0; i <= 12; i++) {
      const s = i / 12;
      pts.push(P(lerp(tie[0], b[0], s), 0, lerp(tie[2], b[2], s) - slack * 1.1 * Math.sin(Math.PI * s)));
    }
    str.setAttribute("d", open(pts));
  }

  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);
  draw(0);

  const c0 = P(10, 0, 38);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(t, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "catch" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => set(Math.abs(sx - c0[0]) < 110 && Math.abs(sy - c0[1]) < 130),
    leave: () => set(false),
  }));
  set(false);
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lean = v; last = ""; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "bilboquet",
  means: "A cup-and-ball toy: the pointer swings the ball up on its string and drops it into the cup; leaving lets it fall to hang.",
  rules: [3, 5, 8],
  range: [0, 0.3, 0.6],
  tour: [[163, 51], [205, 160], [163, 270], null],
  mount,
});

etchsketch.code:
/**
 * Drawing toy: a flat drawing toy with a grey screen and two round knobs on
 * its front edge. The pointer over it stands the toy up on its near edge and
 * turns the knobs with the pointer's x, and the line on the screen follows.
 * At rest it leans back a little, its drawn line bright. The slider is how
 * far it stands up.
 *
 * The pattern: one part tilting toward the pointer (spring).
 */
const { Cam, circ, clamp, fit, hull, open, poly, proj, rrect, seg, spring, stepS, unproj, disposer, mk, pointer, register, solid } = HL;

const W = 92, D = 66, H = 9, KR = 6;
const PATH = [[22, 48], [22, 30], [40, 30], [40, 40], [58, 40], [58, 24], [72, 24]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let up = value;
  const C = Cam(45, 0.5, 2.0);
  const pose = (a) => { const c = Math.cos(a), s = Math.sin(a); return (u, v, w) => [u, D - v * c + w * s, v * s + w * c]; };
  const ext = [];
  for (const a of [0.3, 1.2]) { const f = pose(a); for (const u of [0, W]) for (const v of [0, D]) for (const w of [0, H + 5]) ext.push(f(u, v, w)); }
  fit(C, ext, 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const body = solid(g), scr = solid(g);
  const line = mk("path", { class: "nf hi" }, g);
  const knobs = [0, 1].map(() => ({ s: solid(g), notch: mk("path", { class: "nf" }, g) }));
  const R = rrect(0, 0, W, D, 6, 6), RI = rrect(2, 2, W - 2, D - 2, 4, 6), S = rrect(14, 16, W - 14, D - 8, 4, 6), SI = rrect(16, 18, W - 16, D - 10, 3, 6);
  const K = circ(KR, 24), KI = circ(KR - 1.5, 24);
  const tilt = spring(0.3), turn = spring(0.6), prog = spring(0.55);
  let last = "";

  function draw() {
    const key = [tilt.x, turn.x, prog.x].map((n) => n.toFixed(4)).join();
    if (key === last) return;
    last = key;
    const f = pose(tilt.x), Q = (u, v, w) => P(...f(u, v, w));
    body.sil.setAttribute("d", poly(hull(R.map((q) => Q(q.u, q.v, 0)).concat(R.map((q) => Q(q.u, q.v, H))))));
    body.cr.setAttribute("d", poly(RI.map((q) => Q(q.u, q.v, H))));
    scr.sil.setAttribute("d", poly(S.map((q) => Q(q.u, q.v, H + 0.4))));
    scr.cr.setAttribute("d", poly(SI.map((q) => Q(q.u, q.v, H + 0.4))));
    // the drawn line, up to the stylus
    const n = PATH.length - 1, t = clamp(prog.x, 0, 1) * n, k = Math.floor(Math.min(t, n - 1e-6)), fr = t - k;
    const pts = PATH.slice(0, k + 1).map(([u, v]) => Q(u, v, H + 0.6));
    const a = PATH[k], b = PATH[k + 1];
    pts.push(Q(a[0] + (b[0] - a[0]) * fr, a[1] + (b[1] - a[1]) * fr, H + 0.6));
    line.setAttribute("d", open(pts));
    knobs.forEach((kn, i) => {
      const cu = i ? W - 9 : 9, cv = D - 7, th = turn.x * (i ? -1 : 1);
      kn.s.sil.setAttribute("d", poly(hull(K.map((q) => Q(cu + q.u, cv + q.v, H)).concat(K.map((q) => Q(cu + q.u, cv + q.v, H + 5))))));
      kn.s.cr.setAttribute("d", poly(KI.map((q) => Q(cu + q.u, cv + q.v, H + 5))));
      kn.notch.setAttribute("d", seg(Q(cu, cv, H + 5), Q(cu + Math.cos(th) * (KR - 1.5), cv + Math.sin(th) * (KR - 1.5), H + 5)));
    });
  }

  const B = register(stage, (dt) => {
    const m = [stepS(tilt, dt), stepS(turn, dt), stepS(prog, dt)].some(Boolean);
    draw();
    return m;
  });
  bag.add(B.unregister);
  draw();

  const rest = pose(0.3);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -10 && x < W + 10 && y > -10 && y < D + 25;
  }
  function onMove(p) {
    if (!hit(p)) return onLeave();
    const s = clamp((p[0] - 110) / 180, 0, 1);
    tilt.t = 0.3 + up * 0.95; turn.t = s * Math.PI * 2; prog.t = s;
    read.textContent = "knob " + Math.round(s * 9);
    B.wake();
  }
  function onLeave() { tilt.t = 0.3; turn.t = 0.6; prog.t = 0.55; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: onMove, leave: onLeave }));
  bag.add(() => svg.replaceChildren());
  void rest;
  return { set: (v) => { up = v; }, destroy: bag.dispose };
}

hairline({
  name: "etchsketch",
  means: "A drawing toy lying back: the pointer stands it up, turns its two knobs and runs the line across its screen.",
  rules: [1, 3, 5, 8],
  range: [0.3, 0.8, 1],
  tour: [[211, 186], [122, 179], [299, 197], null],
  mount,
});

magicslate.code:
/**
 * Magic slate: a board with a clear film held by a band along its far edge,
 * a doodle pressed into the film. The pointer over it lifts the film up off
 * the board, further the nearer the pointer comes to the near edge, as when
 * you peel it to wipe the drawing. At rest the film is just raised, bright.
 * The slider is how far the film can lift.
 *
 * The pattern: one part tilting toward the pointer (spring).
 */
const { Cam, clamp, fit, hull, open, poly, proj, rrect, spring, stepS, unproj, disposer, mk, pointer, register, solid } = HL;

const W = 84, D = 104, HB = 6, BAND = 14;
const DOODLE = [];
for (let i = 0; i <= 40; i++) { const t = (i / 40) * Math.PI * 2; DOODLE.push([W / 2 + 20 * Math.sin(t), 58 + 14 * Math.sin(2 * t)]); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.98);
  const film = (a) => (u, v, w) => [u, BAND + (v - BAND) * Math.cos(a) - w * Math.sin(a), HB + 0.6 + (v - BAND) * Math.sin(a) + w * Math.cos(a)];
  const ext = [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0]];
  for (const a of [0.2, 1.35]) { const f = film(a); for (const u of [0, W]) ext.push(f(u, D - 2, 0)); }
  fit(C, ext, 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const board = solid(g), slate = solid(g), sheet = solid(g), band = solid(g);
  const doodle = mk("path", { class: "nf lo" }, g);
  const R = rrect(0, 0, W, D, 6, 6), RI = rrect(2, 2, W - 2, D - 2, 4, 6);
  const S = rrect(8, BAND + 4, W - 8, D - 8, 3, 6);
  const F = rrect(3, BAND, W - 3, D - 3, 3, 6), FI = rrect(5, BAND + 2, W - 5, D - 5, 2, 6);
  const BR = rrect(0, 0, W, BAND + 2, 4, 6), BI = rrect(2, 2, W - 2, BAND, 3, 6);
  const Q = (x, y, z) => P(x, y, z);
  board.sil.setAttribute("d", poly(hull(R.map((q) => Q(q.u, q.v, 0)).concat(R.map((q) => Q(q.u, q.v, HB))))));
  board.cr.setAttribute("d", poly(RI.map((q) => Q(q.u, q.v, HB))));
  slate.sil.setAttribute("d", poly(S.map((q) => Q(q.u, q.v, HB + 0.2))));
  slate.sil.setAttribute("class", "nf lo");
  sheet.sil.classList.add("hi");
  const lift = spring(0.2);
  let last = NaN;

  function draw() {
    if (lift.x === last) return;
    last = lift.x;
    const f = film(lift.x), T = (u, v, w) => P(...f(u, v, w));
    sheet.sil.setAttribute("d", poly(hull(F.map((q) => T(q.u, q.v, 0)).concat(F.map((q) => T(q.u, q.v, 0.8))))));
    sheet.cr.setAttribute("d", poly(FI.map((q) => T(q.u, q.v, 0.8))));
    doodle.setAttribute("d", open(DOODLE.map(([u, v]) => T(u, v, 0.9))));
  }
  band.sil.setAttribute("d", poly(hull(BR.map((q) => Q(q.u, q.v, HB)).concat(BR.map((q) => Q(q.u, q.v, HB + 3))))));
  band.cr.setAttribute("d", poly(BI.map((q) => Q(q.u, q.v, HB + 3))));

  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();

  function onMove(p) {
    const [x, y] = unproj(C, p[0], p[1], HB);
    if (x < -10 || x > W + 10 || y < -10 || y > D + 15) return onLeave();
    const s = clamp((y - 10) / (D - 20), 0, 1);
    lift.t = 0.35 + s * reach;
    read.textContent = "lift " + Math.round(s * 9);
    B.wake();
  }
  function onLeave() { lift.t = 0.2; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: onMove, leave: onLeave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "magicslate",
  means: "A magic slate: the pointer peels its clear film up off the board, higher the nearer it comes to the near edge.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[147, 250], [231, 208], [133, 257], null],
  mount,
});

pinwheel2.code:
/**
 * Pogo stick: a pole with foot pegs, a handlebar and a bare spring above the
 * foot. At rest it leans, spring squeezed, the spring bright. The pointer
 * over it springs it upright and up off the ground, the spring stretched.
 * The slider is how high it hops.
 *
 * The pattern: one part answering the pointer on a spring.
 */
const { Cam, fit, hull, lerp, open, poly, proj, spring, stepS, disposer, mk, pointer, register } = HL;

const RING = [];
for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; RING.push([Math.cos(t), Math.sin(t)]); }

function mount({ stage, svg, read }, value) {
  let hop = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  const at = (t) => { const a = lerp(0.42, -0.08, t), h = t * hop, c = lerp(14, 0, t); return { a, h, c, X: (x, s) => [x, -Math.sin(a) * s, h + Math.cos(a) * s] }; };
  const ext = [];
  for (const t of [0, 1]) { const f = at(t); for (const x of [-34, 34]) for (const s of [0, 140]) ext.push(f.X(x, s)); }
  ext.push([0, 30, 0], [0, -60, 0]);
  fit(C, ext, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const parts = ["low", "coil", "house", "peg", "bar", "grip"].map((k) => [k, mk("path", { class: k === "coil" ? "nf hi" : "sil" }, g)]);
  const el = Object.fromEntries(parts);
  const rod = (A, Bp, r) => {
    const pts = [];
    for (const E of [A, Bp]) for (const [c, s] of RING) pts.push(P(E[0] + r * c, E[1] + r * s, E[2]), P(E[0] + r * c, E[1], E[2] + r * s), P(E[0], E[1] + r * c, E[2] + r * s));
    return poly(hull(pts));
  };
  const sp = spring(0);
  let last = NaN;
  function draw() {
    if (sp.x === last) return;
    last = sp.x;
    const { a, c, X } = at(sp.x), top = 128 - c;
    el.low.setAttribute("d", rod(X(0, 2), X(0, 54 - c), 2.2));
    const coil = [];
    for (let i = 0; i <= 96; i++) { const t = (i / 96) * 8 * Math.PI * 2, s = 10 + (i / 96) * (34 - c); const p = X(0, s); coil.push(P(p[0] + 4.6 * Math.cos(t), p[1] + 4.6 * Math.sin(t) * Math.cos(a), p[2] + 4.6 * Math.sin(t) * Math.sin(a))); }
    el.coil.setAttribute("d", open(coil));
    el.house.setAttribute("d", rod(X(0, 44 - c), X(0, top), 5.5));
    el.peg.setAttribute("d", rod(X(-18, 50 - c), X(18, 50 - c), 2.6));
    el.bar.setAttribute("d", rod(X(0, top - 2), X(0, top + 4), 3));
    el.grip.setAttribute("d", rod(X(-32, top + 6), X(32, top + 6), 3));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  const box = ext.map((p) => P(...p));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const inside = ([sx, sy]) => sx > Math.min(...xs) && sx < Math.max(...xs) && sy > Math.min(...ys) && sy < Math.max(...ys);
  function onMove(p) { if (!inside(p)) return onLeave(); sp.t = 1; read.textContent = "hop"; B.wake(); }
  function onLeave() { sp.t = 0; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: onMove, leave: onLeave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { hop = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pinwheel2",
  means: "A pogo stick leaning on a squeezed spring: the pointer springs it upright and up off the ground.",
  rules: [1, 3, 5, 8],
  range: [8, 18, 24],
  tour: [[196, 174], [182, 268], [224, 56], null],
  mount,
});

snowplow.code:
/**
 * Snow pusher: a wide curved-up blade on a long handle with a cross grip.
 * The pointer's y slides it forward along the ground and tips the handle
 * down as it pushes. At rest it stands back, its blade edge bright. The
 * slider is how far one push goes.
 *
 * The pattern: one part sliding with the pointer (spring).
 */
const { Cam, clamp, fit, hull, lerp, poly, proj, rrect, spring, stepS, disposer, mk, pointer, register, solid } = HL;

const RING = [];
for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; RING.push([Math.cos(t), Math.sin(t)]); }
const BW = 46;

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.12);
  fit(C, [[-BW, -60, 0], [BW, -60, 0], [-BW, 70, 0], [BW, 70, 0], [0, -60, 80], [0, 40, 50]], 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const el = Object.fromEntries(["shaft", "grip"].map((k) => [k, mk("path", { class: "sil" }, g)]));
  const blade = solid(g);
  blade.sil.classList.add("hi");
  const rod = (A, Bp, r) => {
    const pts = [];
    for (const E of [A, Bp]) for (const [c, s] of RING) pts.push(P(E[0] + r * c, E[1] + r * s, E[2]), P(E[0] + r * c, E[1], E[2] + r * s), P(E[0], E[1] + r * c, E[2] + r * s));
    return poly(hull(pts));
  };
  const BR = rrect(-BW, 0, BW, 22, 4, 6), BI = rrect(-BW + 2, 2, BW - 2, 20, 3, 6);
  const sp = spring(0);
  let last = NaN;
  function draw() {
    if (sp.x === last) return;
    last = sp.x;
    const y0 = lerp(-40, -40 + reach, sp.x), tilt = lerp(0.95, 0.6, sp.x);
    const Bp = (u, v, w) => P(u, y0 + 8 - v * Math.cos(1.25) + w * Math.sin(1.25), v * Math.sin(1.25) + w * Math.cos(1.25));
    const hx = 0, hy = y0 - 70 * Math.cos(tilt), hz = 10 + 70 * Math.sin(tilt);
    el.shaft.setAttribute("d", rod([0, y0 + 2, 8], [hx, hy, hz], 2.2));
    el.grip.setAttribute("d", rod([-12, hy, hz], [12, hy, hz], 2.6));
    blade.sil.setAttribute("d", poly(hull(BR.map((q) => Bp(q.u, q.v, 0)).concat(BR.map((q) => Bp(q.u, q.v, 2.5))))));
    blade.cr.setAttribute("d", poly(BI.map((q) => Bp(q.u, q.v, 2.5))));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  function onMove([sx, sy]) {
    if (sx < 70 || sx > 330 || sy < 40 || sy > 290) return onLeave();
    const s = clamp((sy - 80) / 160, 0, 1);
    sp.t = 0.25 + 0.75 * s;
    read.textContent = "push " + Math.round(s * 9);
    B.wake();
  }
  function onLeave() { sp.t = 0; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: onMove, leave: onLeave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "snowplow",
  means: "A snow pusher standing back: the pointer slides its wide blade forward along the ground and tips the handle down.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 100],
  tour: [[178, 214], [207, 148], [207, 268], null],
  mount,
});

hotwater.code:
/**
 * Hand warmer: a pocket hand warmer, a rounded clamshell case with its lid
 * hinged along the back edge and a burner grille inside. The pointer's height
 * along the case sets how far the lid swings open on a spring; nearer the
 * front, the wider it opens, showing the burner's holes. At rest the lid sits
 * just ajar, bright. The slider is the widest the lid will open.
 *
 * The pattern: a continuous aim on one hinged part; the hit is a fixed screen box round every pose.
 */
const {
  Cam, clamp, facing, fit, hull, lerp, open, poly, prism, proj, rad, rings, rrect, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const W = 26, D = 40, HB = 9, HL_ = 8, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 4.6);
  const lidRing = rrect(0, 0, W, D, 7, 8), lidIn = rrect(1.6, 1.6, W - 1.6, D - 1.6, 5.4, 8);
  const lw = (x, y, zl, a) => {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return [x, y * c - zl * s, HB + y * s + zl * c];
  };
  const ext = [];
  [0, 130].forEach((a) => [[0, 0], [W, 0], [0, D], [W, D]].forEach(([x, y]) => [0, HL_].forEach((z) => ext.push(lw(x, y, z, a)))));
  ext.push([0, D, 0], [W, D, 0], [W, 0, 0], [0, 0, 0]);
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const sp0 = ext.map((q) => P(...q)), xs = sp0.map((q) => q[0]), ys = sp0.map((q) => q[1]);
  const bx = [Math.min(...xs), Math.max(...xs)], by = [Math.min(...ys), Math.max(...ys)];

  // the case: a rounded body, with the burner grille on its top
  const [r0, i0] = rings(0, 0, W, D, 7, 1.6);
  const body = solid(g);
  put(body, prism(P, front, r0, i0, 0, HB));
  const grille = rrect(6, 8, W - 6, D - 8, 4, 6);
  mk("path", { class: "nf lo", d: poly(grille.map((p) => P(p.u, p.v, HB))) }, body.g);
  for (let i = 0; i < 3; i++) for (let j = 0; j < 2; j++) {
    const d = flatDot(body.g, C, 1.6, "dot off");
    place(d, P(10 + j * 6, 13 + i * 7, HB));
  }

  // the lid: a rounded plate turning about the hinge on the back edge
  const lid = { g: mk("g", {}, g) };
  lid.sil = mk("path", { class: "sil hi" }, lid.g);
  lid.cr = mk("path", { class: "nf lo" }, lid.g);
  const hinge = mk("path", { class: "nf lo" }, g);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    lidRing.forEach((p) => { pts.push(P(...lw(p.u, p.v, 0, a)), P(...lw(p.u, p.v, HL_, a))); });
    lid.sil.setAttribute("d", poly(hull(pts)));
    if (a < 80) {
      const keep = lidIn.map((p) => (front(p) ? P(...lw(p.u, p.v, HL_, a)) : null));
      const k0 = keep.findIndex((p, i) => p && !keep[(i - 1 + keep.length) % keep.length]);
      const runPts = [];
      for (let i = 0; i < keep.length; i++) { const p = keep[(k0 + i) % keep.length]; if (!p) break; runPts.push(p); }
      lid.cr.setAttribute("d", open(runPts));
    } else lid.cr.setAttribute("d", poly(lidIn.map((p) => P(...lw(p.u, p.v, 0, a)))));
    hinge.setAttribute("d", open([P(4, 0, HB), P(W - 4, 0, HB)]));
  }
  const sp = spring(REST);
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (p[0] < bx[0] - 8 || p[0] > bx[1] + 8 || p[1] < by[0] - 8 || p[1] > by[1] + 8) return leave();
    const t = clamp((p[1] - by[0]) / (by[1] - by[0]), 0, 1);
    sp.t = lerp(REST + 20, maxA, t);
    read.textContent = "lid " + Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "hotwater",
  means: "A pocket hand warmer: its hinged lid swings open toward the pointer, wider the nearer the front, showing the burner.",
  rules: [1, 3, 5, 8],
  range: [70, 110, 130],
  tour: [[200, 130], [190, 230], [120, 200], null],
  mount,
});

mess.code:
/**
 * Mess tin: a rounded camping pan with a slotted handle hinged at its near
 * end. At rest the handle stands half folded over the tin, bright. The
 * pointer over the tin swings the handle out to lie level, ready to hold.
 * The slider is how far the handle opens.
 *
 * The pattern: one part swinging on a hinge.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, rrect, tdone, tset, tval, tween, rad, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 56, Y1 = 34, H = 16, L = 52, W0 = 10, W1 = 24, REST = 35;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[0, 0, 0], [X1 + L, Y1, 0], [X1, Y1, 0], [0, Y1, 0], [X1, 0, H + L], [0, 0, H]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ring, inner] = rings(0, 0, X1, Y1, 8, 2);
  put(solid(g), prism(P, front, ring, inner, 0, H));
  // the hinge lug on the near end
  const [lr, li] = rings(X1 - 2, W0 + 1, X1 + 3, W1 - 1, 2, 0.8);
  put(solid(g), prism(P, front, lr, li, H - 4, H + 1));
  const hg = mk("g", {}, g);
  const plate = mk("path", { class: "sil" }, hg), slot = mk("path", { class: "nf lo" }, hg);
  const outer = rrect(0, W0, L, W1, 5, 4), hole = rrect(14, W0 + 4, L - 7, W1 - 4, 2.5, 4);
  const ang = tween(REST);
  let last = NaN;

  function at(s, th) {
    const c = Math.cos(rad(th)), sn = Math.sin(rad(th));
    return P(X1 - s.u * c, s.v, H + 1 + s.u * sn);
  }
  function draw(th) {
    if (th === last) return;
    last = th;
    plate.setAttribute("d", poly(outer.map((s) => at(s, th))));
    slot.setAttribute("d", poly(hole.map((s) => at(s, th))));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -8 && x < X1 + L + 4 && y > -8 && y < Y1 + 8;
  }
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? open : REST, performance.now(), 0);
    plate.classList.add("hi");
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "mess",
  means: "A mess tin whose slotted handle stands half folded at rest and swings out level when the pointer comes over the tin.",
  rules: [1, 5, 6, 8],
  range: [120, 175, 180],
  tour: [[180, 149], [200, 190], [166, 137], null],
  mount,
});

sleepmat.code:
/**
 * Sleeping mat: a foam mat half unrolled on the ground, the rest of it still
 * wound in a roll at its near end. At rest the roll is bright. The pointer
 * over the mat unrolls it: the roll travels out and shrinks as the mat
 * lays flat behind it. The slider is how far it unrolls.
 *
 * The pattern: one part rolling out.
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, facing, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 56, FULL = 110, R0 = 18, REST = 62;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let to = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[0, 0, 0], [FULL + 10, W, 0], [FULL + 10, 0, 0], [0, W, 0], [REST, 0, 2 * R0], [REST + 2 * R0, W, 2 * R0]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const mat = solid(g);
  const roll = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), core = mk("path", { class: "nf lo" }, g);
  roll.classList.add("hi");
  const len = tween(REST);
  let last = NaN;
  const circle = (cx, y, r, cz = r) => { const o = []; for (let i = 0; i < 32; i++) { const t = (i / 32) * Math.PI * 2; o.push(P(cx + r * Math.cos(t), y, cz + r * Math.sin(t))); } return o; };

  function draw(l) {
    if (l === last) return;
    last = l;
    const r = 4 + (R0 - 4) * (1 - l / FULL);
    const [mr, mi] = rings(0, 0, l + r, W, 3, 1);
    put(mat, prism(P, front, mr, mi, 0, 2));
    roll.setAttribute("d", poly(hull(circle(l + r, 0, r).concat(circle(l + r, W, r)))));
    face.setAttribute("d", poly(circle(l + r, W, r)));
    core.setAttribute("d", poly(circle(l + r, W, r * 0.45, r)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(len, now)); return !tdone(len, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -8 && x < FULL + 14 && y > -10 && y < W + 10;
  }
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(len, a ? to : REST, performance.now(), 0);
    read.textContent = a ? "unroll" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { to = v; if (act) { tset(len, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "sleepmat",
  means: "A foam sleeping mat half unrolled, its roll at the near end; the pointer over it rolls the roll out until the mat lies flat.",
  rules: [1, 5, 6, 8],
  range: [96, 104, 108],
  tour: [[143, 139], [181, 158], [105, 120], null],
  mount,
});

leafblower.code:
/**
 * Leaf blower: a motor housing on the ground with a loop handle on top and a
 * long blow tube coupled at its front. The pointer over it swings the tube
 * round to sweep. At rest the tube points ahead, its tip bright.
 */
const { Cam, fit, facing, hull, open, poly, proj, rrect, ringAt, run, rad, lerp, spring, stepS, disposer, mk, pointer, put, solid } = HL;
const { register } = HL;

const xf = (ring, a, du, dv) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: q.u * c - q.v * s + du, v: q.u * s + q.v * c + dv, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };
const ring2 = (u0, v0, u1, v1, r, b) => [rrect(u0, v0, u1, v1, r, 4), rrect(u0 + b, v0 + b, u1 - b, v1 - b, Math.max(r - b, 0.5), 4)];
const PIV = [30, 0];
const TUBE = [ring2(0, -7, 92, 7, 6.5, 2), ring2(88, -9, 104, 9, 4, 2)];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-40, -30, 0], [30, 30, 40], [134, 0, 6], [30 + 104 * Math.cos(rad(50)), 104 * Math.sin(rad(50)), 0], [30 + 104 * Math.cos(rad(-20)), 104 * Math.sin(rad(-20)), 0]], 228, 182);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const tg = mk("g", {}, g);
  const tube = TUBE.map(() => solid(tg));
  const bg = mk("g", {}, g);
  const housing = solid(bg), grip = solid(bg), collar = solid(bg);
  function slab(s, R, I, z0, z1) {
    put(s, { sil: poly(hull(ringAt(P, R, z0).concat(ringAt(P, R, z1)))), crease: open(ringAt(P, run(I, front), z1)) });
  }
  const [hr, hi] = ring2(-40, -28, 28, 28, 14, 2.2);
  slab(housing, hr, hi, 0, 30);
  const [gr, gi] = ring2(-30, -5, 16, 5, 5, 1.6);
  slab(grip, gr, gi, 30, 42);
  const [cr, ci] = ring2(22, -11, 36, 11, 5, 1.8);
  slab(collar, cr, ci, 4, 24);
  const sp = spring(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return; last = t;
    const a = rad(lerp(-14, 48, t));
    TUBE.forEach(([r, i], j) => slab(tube[j], xf(r, a, PIV[0], PIV[1]), xf(i, a, PIV[0], PIV[1]), 7, 21));
    if (a > 0) g.append(tg); else g.append(bg);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const pts = [P(-45, -35, 0), P(140, 0, 0), P(100, 90, 0), P(-45, 35, 0), P(130, -40, 0)];
  const xs = pts.map((q) => q[0]), ys = pts.map((q) => q[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys) - 30, y1 = Math.max(...ys) + 10;
  let act = false;
  const target = () => 0.45 + 0.55 * amt;
  function setA(on) {
    sp.t = on ? target() : 0;
    tube[1].sil.classList.toggle("hi", true);
    read.textContent = on ? "sweep " + Math.round(lerp(-14, 48, sp.t)) + "°" : "rest";
    act = on; B.wake();
  }
  setA(false);
  bag.add(pointer(stage, { move: (p) => setA(p[0] > x0 && p[0] < x1 && p[1] > y0 && p[1] < y1), leave: () => setA(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { sp.t = target(); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "leafblower",
  means: "A leaf blower on the ground, housing and loop handle: the pointer over it swings the long blow tube round to sweep.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[183, 221], [294, 214], [120, 110], null],
  mount,
});

lensmeter.code:
/**
 * Lens meter: an optician's lensometer, a base and column carrying a head
 * with an eyepiece on top and a lens stage at its nose. The pointer over the
 * instrument tilts the whole head forward on its pivot, as for reading a lens
 * held flat. At rest the head leans back a little, its eyepiece bright. The
 * slider is the tilt.
 *
 * The pattern: one part following the pointer (swing).
 */
const { Cam, circ, rrect, fit, hull, poly, proj, clamp, spring, stepS, mk, pointer, register, disposer } = HL;

const PIV = [-14, 0, 42], REST = 0.18, TILT = -0.62;
const rot = (p, o, a) => { const x = p[0] - o[0], z = p[2] - o[2], c = Math.cos(a), s = Math.sin(a); return [o[0] + x * c - z * s, p[1], o[2] + x * s + z * c]; };
const box = (x0, y0, x1, y1, z0, z1, r = 3) => { const g = rrect(x0, y0, x1, y1, r, 5); return g.map((q) => [q.u, q.v, z0]).concat(g.map((q) => [q.u, q.v, z1])); };
const cyl = (r, x, y, z0, z1) => { const c = circ(r, 24); return c.map((q) => [x + q.u, y + q.v, z0]).concat(c.map((q) => [x + q.u, y + q.v, z1])); };
const HEAD = [box(-30, -13, 22, 13, 36, 62, 6), box(18, -9, 40, 9, 38, 48, 3), cyl(8, 34, 0, 48, 50), cyl(6, -20, 0, 60, 80), cyl(7.5, -20, 0, 80, 86)];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let sw = value;
  const C = Cam(45, 0.5, 2.35);
  const all = (a) => HEAD.flat().map((p) => rot(p, PIV, a));
  fit(C, box(-34, -26, 34, 26, 0, 8).concat(all(REST), all(TILT)), 200, 166);
  const P = proj(C), T = (p) => P(...p);
  const g = mk("g", {}, svg);
  const path = (pts, cls) => mk("path", { class: cls, d: poly(hull(pts.map(T))) }, g);
  path(box(-34, -26, 34, 26, 0, 8, 7), "sil");
  mk("path", { class: "nf lo", d: poly(rrect(-31, -23, 31, 23, 5, 5).map((q) => T([q.u, q.v, 8]))) }, g);
  path(box(-22, -8, -6, 8, 8, 44, 4), "sil");
  path(cyl(5, -14, 0, 38, 46), "sil");
  const parts = HEAD.map((_, i) => mk("path", { class: i >= 3 ? "sil hi" : "sil" }, g));
  const crease = mk("path", { class: "nf lo" }, g);
  g.insertBefore(crease, parts[1]);
  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    HEAD.forEach((pts, i) => parts[i].setAttribute("d", poly(hull(pts.map((p) => T(rot(p, PIV, a)))))));
    crease.setAttribute("d", poly(rrect(-27, -10, 19, 10, 4, 5).map((q) => T(rot([q.u, q.v, 62], PIV, a)))));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const bx = hull(box(-34, -26, 40, 26, 0, 86).map(T)), xs = bx.map((p) => p[0]), ys = bx.map((p) => p[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  function aim(p) {
    const inside = p && p[0] > x0 && p[0] < x1 && p[1] > y0 && p[1] < y1;
    const t = inside ? clamp(1.2 - (p[1] - y0) / (y1 - y0), 0.3, 1) : null;
    sp.t = t === null ? REST : REST + t * (TILT - REST) * (sw / 100);
    read.textContent = t === null ? "rest" : "tilt " + Math.round(t * 100) + "%";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sw = v; }, destroy: bag.dispose };
}

hairline({
  name: "lensmeter",
  means: "An optician's lens meter: the head with its eyepiece and lens stage tilts forward on its pivot as the pointer comes over.",
  rules: [1, 3, 4, 5],
  range: [40, 100, 100],
  tour: [[200, 116], [210, 200], [167, 60], null],
  mount,
});

mortarpharm.code:
/**
 * Pill tin: a round pocket tin of pills with a hinged lid. The pointer over
 * the tin swings the lid open on its back hinge to show the pills. At rest
 * the lid sits ajar, bright. The slider is how far the lid opens.
 *
 * The pattern: one part following the pointer (swing).
 */
const { Cam, circ, fit, hull, poly, proj, clamp, spring, stepS, mk, pointer, register, disposer, flatDot, place } = HL;

const R = 30, H = 15, LH = 6, PIV = [-R - 1, 0, H];
const rot = (p, o, a) => { const x = p[0] - o[0], z = p[2] - o[2], c = Math.cos(a), s = Math.sin(a); return [o[0] + x * c - z * s, p[1], o[2] + x * s + z * c]; };
const ring = (r, z, n = 40) => circ(r, n).map((q) => [q.u, q.v, z]);
const REST = 0.42, OPEN = 1.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let sw = value;
  const C = Cam(45, 0.5, 2.95);
  const lidPts = (a) => ring(R + 1.5, H, 32).concat(ring(R + 1.5, H + LH, 32)).map((p) => rot(p, PIV, a));
  fit(C, ring(R, 0, 16).concat(lidPts(OPEN), lidPts(REST)), 200, 162);
  const P = proj(C), T = (p) => P(...p);
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g), baseG = mk("g", {}, g);
  mk("path", { class: "sil", d: poly(hull(ring(R, 0).concat(ring(R, H)).map(T))) }, baseG);
  mk("path", { class: "lo", d: poly(ring(R - 2.2, H).map(T)) }, baseG);
  const pills = [[-8, -6], [6, -12], [12, 4], [-4, 10], [-16, 4], [2, -1], [16, -8], [-12, -16], [8, 16]];
  for (const [x, y] of pills) place(flatDot(baseG, C, 2.6, "dot m"), T([x, y, H]));
  const lid = mk("path", { class: "sil hi" }, lidG), lidIn = mk("path", { class: "nf lo" }, lidG);
  const sp = spring(REST);
  let last = NaN, behind = null;
  function draw(a) {
    if (a === last) return;
    last = a;
    lid.setAttribute("d", poly(hull(lidPts(a).map(T))));
    lidIn.setAttribute("d", poly(ring(R - 1, H + LH, 32).map((p) => T(rot(p, PIV, a)))));
    const b = a > 0.9;
    if (b !== behind) { behind = b; if (b) g.insertBefore(lidG, baseG); else baseG.after(lidG); }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const box = hull(ring(R + 2, 0).concat(ring(R + 2, H + LH)).map(T));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys) - 30, y1 = Math.max(...ys) + 10;
  function aim(p) {
    const inside = p && p[0] > x0 && p[0] < x1 && p[1] > y0 && p[1] < y1;
    const t = inside ? clamp(1.2 - (p[1] - y0) / (y1 - y0), 0.35, 1) : null;
    sp.t = t === null ? REST : REST + t * (OPEN - REST) * (sw / 100);
    lid.classList.add("hi");
    read.textContent = t === null ? "rest" : "lid " + Math.round(t * 100) + "%";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sw = v; }, destroy: bag.dispose };
}

hairline({
  name: "mortarpharm",
  means: "A round pocket pill tin: the hinged lid swings open on its back hinge as the pointer comes over, showing the pills.",
  rules: [1, 3, 4, 5],
  range: [40, 100, 100],
  tour: [[225, 263], [225, 205], [225, 165], null],
  mount,
});

florist.code:
/**
 * Flower bucket: a florist's tapered zinc bucket of stems, standing in a
 * tilting display stand. The pointer over it tips the bucket back on the
 * stand's front pivot to show the blooms. At rest the bucket stands nearly
 * upright, one bloom bright. The slider is the tilt.
 *
 * The pattern: one part following the pointer (swing).
 */
const { Cam, circ, rrect, fit, hull, poly, open, proj, clamp, spring, stepS, mk, pointer, register, disposer } = HL;

const PIV = [18, 0, 12], REST = -0.08, TILT = 0.55;
const rot = (p, o, a) => { const x = p[0] - o[0], z = p[2] - o[2], c = Math.cos(a), s = Math.sin(a); return [o[0] + x * c - z * s, p[1], o[2] + x * s + z * c]; };
const box = (x0, y0, x1, y1, z0, z1, r = 3) => { const g = rrect(x0, y0, x1, y1, r, 5); return g.map((q) => [q.u, q.v, z0]).concat(g.map((q) => [q.u, q.v, z1])); };
const ring = (r, x, y, z, n = 28) => circ(r, n).map((q) => [x + q.u, y + q.v, z]);
const BLOOMS = [[-8, -8, 78, 6], [6, -10, 84, 5.5], [-12, 6, 72, 5], [4, 6, 90, 6.5], [12, -2, 74, 5], [-2, 0, 96, 5.5]];
const FAV = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let sw = value;
  const C = Cam(45, 0.5, 2.35);
  const bucket = ring(15, 0, 0, 12, 36).concat(ring(19, 0, 0, 50, 36));
  const tops = BLOOMS.flatMap(([x, y, z, r]) => ring(r, x, y, z + 3, 8));
  fit(C, box(-26, -26, 26, 26, 0, 12).concat(bucket.map((p) => rot(p, PIV, TILT)), tops.map((p) => rot(p, PIV, TILT)), tops.map((p) => rot(p, PIV, REST))), 200, 166);
  const P = proj(C), T = (p) => P(...p);
  const g = mk("g", {}, svg);
  const path = (pts, cls) => mk("path", { class: cls, d: poly(hull(pts.map(T))) }, g);
  path(box(-26, -26, 26, 26, 0, 4, 6), "sil");
  path(box(-20, -24, -14, -18, 4, 12, 2).concat(box(-20, 18, -14, 24, 4, 12, 2)), "nf lo");
  path(box(-24, -24, 24, 24, 9, 12, 8), "sil");
  mk("path", { class: "nf lo", d: poly(rrect(-20, -20, 20, 20, 6, 5).map((q) => T([q.u, q.v, 12]))) }, g);
  const body = mk("path", { class: "sil" }, g), mouth = mk("path", { class: "lo" }, g), band = mk("path", { class: "nf lo" }, g);
  const stems = mk("path", { class: "nf" }, g);
  const heads = BLOOMS.map((_, i) => ({ s: mk("path", { class: i === FAV ? "sil hi" : "sil" }, g), c: mk("path", { class: "nf lo" }, g) }));
  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const R = (p) => T(rot(p, PIV, a));
    body.setAttribute("d", poly(hull(bucket.map(R))));
    mouth.setAttribute("d", poly(ring(18.2, 0, 0, 50, 36).map(R)));
    band.setAttribute("d", open(ring(17, 0, 0, 30, 36).filter((p) => p[0] + p[1] > -4).sort((p, q) => Math.atan2(p[1], p[0]) - Math.atan2(q[1], q[0])).map(R)));
    stems.setAttribute("d", BLOOMS.map(([x, y, z]) => "M" + R([x * 0.4, y * 0.4, 50]).join(",") + "L" + R([x, y, z]).join(",")).join(""));
    BLOOMS.forEach(([x, y, z, r], i) => {
      heads[i].s.setAttribute("d", poly(hull(ring(r * 0.5, x, y, z, 12).concat(ring(r, x, y, z + 3, 16), ring(r * 0.7, x, y, z + 5, 12)).map(R))));
      heads[i].c.setAttribute("d", poly(ring(r * 0.35, x, y, z + 5, 10).map(R)));
    });
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const bx = hull(box(-26, -26, 26, 26, 0, 100).map(T)), xs = bx.map((p) => p[0]), ys = bx.map((p) => p[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  function aim(p) {
    const inside = p && p[0] > x0 && p[0] < x1 && p[1] > y0 && p[1] < y1;
    const t = inside ? clamp(1.2 - (p[1] - y0) / (y1 - y0), 0.3, 1) : null;
    sp.t = t === null ? REST : REST + t * (TILT - REST) * (sw / 100);
    read.textContent = t === null ? "rest" : "tip " + Math.round(t * 100) + "%";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sw = v; }, destroy: bag.dispose };
}

hairline({
  name: "florist",
  means: "A florist's bucket of blooms in a tilting stand: the bucket tips back on its pivot as the pointer comes over.",
  rules: [1, 3, 4, 5],
  range: [40, 100, 100],
  tour: [[202, 147], [199, 70], [202, 260], null],
  mount,
});

meatslicer.code:
/**
 * Meat slicer: a deli slicer, a heavy base with a round blade standing on it
 * under its guard, and a carriage in front of the blade carrying a block of
 * ham against it. The pointer pushes the carriage: it slides along its track
 * to follow the pointer, past the blade and back, on one spring. At rest the
 * carriage waits at the near end, the blade's guard bright. The slider is
 * how far the carriage may travel.
 *
 * The pattern: a continuous aim on one value; the hit is on the floor's
 * plane, which never moves.
 */
const {
  Cam, clamp, fit, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 14, BY = 26, BZ = 30, R = 20, REST = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[0, -14, 0], [44, -14, 0], [44, 66, 0], [0, 66, 0], [BX, BY, BZ + R + 3], [36, -14, 30], [36, 66, 30]], 200, 166);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 44, 52, 8, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, 10));
  // the blade's post and the round blade in its guard, standing in the plane x = BX
  put(solid(g), prism(P, front, rings(BX - 6, BY - 5, BX, BY + 5, 2, 0.8)[0], null, 10, BZ));
  const disc = (r, x) => { const p = []; for (let i = 0; i < 48; i++) { const a = (i / 48) * Math.PI * 2; p.push(P(x, BY + r * Math.cos(a), BZ + r * Math.sin(a))); } return p; };
  const guard = mk("path", { class: "sil", d: poly(disc(R + 2.5, BX - 1.5)) }, g);
  mk("path", { class: "sil", d: poly(disc(R + 2.5, BX)) }, g);
  mk("path", { class: "nf lo", d: poly(disc(R - 3, BX)) + poly(disc(4, BX)) + seg(P(BX, BY - R, BZ), P(BX, BY - R - 4, BZ - 6)) }, g);
  // the track along y, in front of the blade
  mk("path", { class: "nf lo", d: seg(P(40, -12, 10), P(40, 64, 10)) + seg(P(22, -12, 10), P(22, 64, 10)) }, g);
  const cart = mk("g", {}, g), tray = solid(cart), ham = solid(cart), push = solid(cart);
  const hamFace = mk("path", { class: "nf lo" }, cart);
  const sp = spring(REST);
  let drawn = NaN;

  function draw(s) {
    if (Math.abs(s - drawn) < 1e-3) return;
    drawn = s;
    const [tr, ti] = rings(18, s - 12, 42, s + 12, 3, 1);
    put(tray, prism(P, front, tr, ti, 10, 13));
    const [hr, hi] = rings(BX + 2, s - 9, 34, s + 9, 6, 1.4);
    put(ham, prism(P, front, hr, hi, 13, 34));
    // the meat's grain on its cut face
    hamFace.setAttribute("d", seg(P(BX + 2, s - 4, 18), P(BX + 2, s + 4, 26)) + seg(P(BX + 2, s - 1, 16), P(BX + 2, s + 6, 21)));
    const [pr, pi] = rings(34, s - 6, 40, s + 6, 2, 0.8);
    put(push, prism(P, front, pr, pi, 13, 40));
  }

  const L = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(L.unregister);

  function set(y) {
    const on = y !== null;
    sp.t = on ? clamp(y, 26 - 26 * reach, 26 + 26 * reach) : REST;
    guard.classList.toggle("hi", !on);
    ham.sil.classList.toggle("hi", on);
    read.textContent = on ? "pos " + Math.round(sp.t) : "rest";
    L.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      set(x > -10 && x < 60 && y > -24 && y < 76 ? y : null);
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "meatslicer",
  means: "A deli meat slicer: the carriage with its block of ham slides along its track past the round blade, following the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[249, 172], [200, 215], [167, 250], null],
  mount,
});

lasthammer.code:
/**
 * Cobbler last: a shoe last standing on its iron post and block, a sole laid
 * on it, and the cobbler's hammer held over it. The pointer is the hand: the
 * nearer it comes to the last, the lower the hammer swings, on one spring
 * about its grip, until the head meets the sole. At rest the hammer is
 * raised, its head bright. The slider is how high it can rise.
 *
 * The pattern: a continuous aim on one angle; the hit is on the floor's
 * plane, which never moves.
 */
const {
  Cam, clamp, fit, hull, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GX = 44, GZ = 52, LEN = 38, TOPZ = 40, REST = 52;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let high = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[-20, -14, 0], [24, 18, 0], [GX + 6, 0, GZ], [GX - LEN * 0.4, 0, GZ + LEN * 0.95], [-6, 0, TOPZ + 20]], 200, 166);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  const [b0, b1] = rings(-20, -14, 24, 18, 4, 1.4);
  put(solid(g), prism(P, front, b0, b1, 0, 12));
  put(solid(g), prism(P, front, rings(-1, -2, 5, 4, 2, 0.8)[0], null, 12, TOPZ - 8));
  // the last: a foot-shaped block, toe toward -x
  const [l0, l1] = rings(-16, -6, 22, 8, 7, 1.2);
  put(solid(g), prism(P, front, l0, l1, TOPZ - 8, TOPZ));
  mk("path", { class: "nf lo", d: poly(HL.ringAt(P, rings(-15, -5, 21, 7, 6, 1)[0], TOPZ)) }, g);
  put(solid(g), prism(P, front, rings(9, -5, 21, 7, 5, 1)[0], rings(9, -5, 21, 7, 5, 1)[1], TOPZ, TOPZ + 12));
  const ham = mk("g", {}, g), handle = mk("path", { class: "sil" }, ham), head = mk("path", { class: "sil" }, ham);
  const sp = spring(REST);
  let drawn = NaN;
  const box = (cx, cz, hx, hy, hz, a, ux, uz) => {
    const pts = [];
    for (const sx of [-1, 1]) for (const sy of [-1, 1]) for (const sz of [-1, 1]) {
      const lx = sx * hx, lz = sz * hz;
      pts.push(P(cx + lx * ux - lz * uz, sy * hy, cz + lx * uz + lz * ux));
    }
    return pts;
  };

  function draw(deg) {
    if (Math.abs(deg - drawn) < 1e-3) return;
    drawn = deg;
    const a = (deg * Math.PI) / 180, ux = -Math.cos(a), uz = Math.sin(a);
    const hx = GX + ux * LEN, hz = GZ + uz * LEN;
    handle.setAttribute("d", poly(hull(box(GX + ux * LEN * 0.5, GZ + uz * LEN * 0.5, LEN * 0.5, 2, 1.6, a, ux, uz))));
    // the head stands across the handle's end: its long side along the swing's normal
    head.setAttribute("d", poly(hull(box(hx, hz, 4, 4.5, 9, a, ux, uz))));
  }

  const L = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(L.unregister);

  function set(d) {
    const on = d !== null;
    sp.t = on ? clamp((d / 70) * high, 6, high) : REST;
    head.classList.toggle("hi", true);
    read.textContent = on ? Math.round(sp.t) + "°" : "rest";
    L.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x - 4, y);
      set(d < 90 ? d : null);
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { high = v; }, destroy: bag.dispose };
}

hairline({
  name: "lasthammer",
  means: "A cobbler's shoe last with a hammer over it: the nearer the pointer comes, the lower the hammer swings onto the sole.",
  rules: [1, 3, 5, 8],
  range: [40, 64, 80],
  tour: [[300, 240], [166, 239], [93, 229], null],
  mount,
});

tailorchalk.code:
/**
 * Tailor shears: long bent-handled shears lying on the cutting table, the
 * lower blade flat on the cloth, the upper blade on one pivot screw with the
 * big finger bow. The pointer is the hand: over the shears, the upper blade
 * swings open, wider the nearer the pointer is to the bow. At rest the jaws
 * are a little open, the upper blade bright. The slider is how wide they open.
 */
const {
  Cam, fit, prism, proj, facing, fillet, circ, rrect, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid, flatDot, place, unproj,
} = HL;

const R = Math.PI / 180, REST = 7, OPEN = 34;
const LOWER = [[92, -1], [60, -4.5], [4, -6], [-8, -5], [-10, 1], [4, 1.5], [60, 1], [90, 0.4]];
const UPPER = [[90, 1.2], [60, 5.5], [4, 6.5], [-8, 6], [-10, 0], [4, -0.5], [60, -0.2], [92, 0]];
function ringOf(pts) {
  let a = 0;
  for (let i = 0; i < pts.length; i++) { const p = pts[i], q = pts[(i + 1) % pts.length]; a += p[0] * q[1] - q[0] * p[1]; }
  const sg = a > 0 ? 1 : -1;
  return pts.map((p, i) => {
    const pr = pts[(i - 1 + pts.length) % pts.length], nx = pts[(i + 1) % pts.length];
    const dx = nx[0] - pr[0], dy = nx[1] - pr[1], l = Math.hypot(dx, dy) || 1;
    return { u: p[0], v: p[1], nu: (sg * dy) / l, nv: (-sg * dx) / l };
  });
}
const off = (ring, du, dv) => ring.map((q) => ({ ...q, u: q.u + du, v: q.v + dv }));
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.4);
  const ext = [[94, -8, 0], [-48, -22, 0], [-50, 26, 8]];
  for (let k = 0; k <= 8; k++) { const a = (k / 8) * (OPEN + 8) * R; ext.push([94 * Math.cos(a), 94 * Math.sin(a), 8], [-50 * Math.cos(a) + 18 * Math.sin(a), -50 * Math.sin(a) - 18 * Math.cos(a), 8]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const parts = [
    { z: 0, blade: ringOf(fillet(LOWER, [1, 3, 3, 2, 2, 2, 3, 1], 3)), loop: off(circ(9, 32), -22, -9), hole: off(circ(5.5, 32), -22, -9), up: false },
    { z: 2.4, blade: ringOf(fillet(UPPER, [1, 3, 3, 2, 2, 2, 3, 1], 3)), loop: rrect(-48, 3, -14, 24, 9, 6), hole: rrect(-44, 7, -18, 20, 6, 6), up: true },
  ].map((h) => { const grp = mk("g", {}, g); return { ...h, grp, L: solid(grp), B: solid(grp), H: solid(grp) }; });
  const screw = flatDot(g, C, 2.2, "dot off");
  const open = spring(REST);
  let drawn = NaN;

  function draw() {
    if (Math.abs(open.x - drawn) < 1e-3) return;
    drawn = open.x;
    for (const h of parts) {
      const a = (h.up ? open.x : -2) * R, z = h.z;
      put(h.L, prism(P, front, turn(h.loop, a), null, z, z + 2.4));
      put(h.H, prism(P, front, turn(h.hole, a), null, z + 2.3, z + 2.4));
      put(h.B, prism(P, front, turn(h.blade, a), null, z, z + 2.4));
    }
    place(screw, P(0, 0, 5));
  }
  const Bk = register(stage, (dt) => { const m = stepS(open, dt); draw(); return m; });
  bag.add(Bk.unregister);

  function set(t) {
    open.t = t == null ? REST : clamp(REST + (OPEN - REST) * value * t, REST, 44);
    read.textContent = t == null ? "rest" : Math.round(open.t) + "°";
    Bk.wake();
  }
  parts[1].B.sil.classList.add("hi");
  parts[1].L.sil.classList.add("hi");
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -60 || x > 100 || Math.abs(y) > 40) return set(null);
      set(clamp(0.55 + (20 - x) / 90, 0.4, 1));
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "tailorchalk",
  means: "Tailor shears on the cutting table: the upper blade swings open on its screw, wider as the pointer nears the bow.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.3],
  tour: [[103, 134], [180, 175], [300, 228], null],
  mount,
});

pinwheelmeasure.code:
/**
 * Pattern wheel: a tailor's tracing wheel, a spiked steel wheel on a fork at
 * the end of a long handle, standing on the pattern paper. The pointer is the
 * hand: the wheel rolls along the line to follow it, spinning as it goes and
 * leaving a dotted trace behind. At rest it waits at the start of a short
 * trace, its wheel bright. The slider is how fast it follows.
 */
const {
  Cam, fit, proj, hull, poly, open, seg, spring, stepS, clamp,
  disposer, mk, pointer, register, unproj,
} = HL;

const RW = 13, X0 = -52, REST = -24, XMAX = 30, HX = -46, HZ = 44;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[X0, 0, 0], [XMAX + RW + 3, 0, 0], [X0 + 8 + HX, 0, RW + HZ], [XMAX + HX, 0, RW + HZ], [XMAX + RW, 0, 2 * RW + 3]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const trail = mk("path", { class: "nf dash" }, g);
  const handle = mk("path", { class: "sil" }, g), ferrule = mk("path", { class: "sil" }, g);
  const spikes = mk("path", { class: "nf sil" }, g), wheel = mk("path", { class: "sil hi" }, g), hub = mk("path", { class: "nf lo" }, g);
  const pos = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  let drawn = NaN;

  const ringPts = (c, d, r, n = 24) => {
    let u = Math.abs(d[2]) > 0.9 ? [1, 0, 0] : [d[1], -d[0], 0];
    const ul = Math.hypot(...u); u = u.map((x) => x / ul);
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    return Array.from({ length: n }, (_, i) => {
      const t = (i / n) * Math.PI * 2, q = (j) => c[j] + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
  };
  const tube = (a, b, r0, r1) => {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], n = Math.hypot(...d), e = d.map((x) => x / n);
    return poly(hull(ringPts(a, e, r0).concat(ringPts(b, e, r1))));
  };
  function draw() {
    if (Math.abs(pos.x - drawn) < 1e-3) return;
    drawn = pos.x;
    const X = pos.x, hc = [X, 0, RW], roll = -X / RW;
    trail.setAttribute("d", open([P(X0, 0, 0), P(X, 0, 0)]));
    const mid = [X + HX * 0.38, 0, RW + HZ * 0.38], top = [X + HX, 0, RW + HZ];
    handle.setAttribute("d", tube(mid, top, 4.2, 5));
    ferrule.setAttribute("d", tube(hc, mid, 2, 3));
    let d = "";
    for (let i = 0; i < 28; i++) {
      const t = roll + (i / 28) * Math.PI * 2, c = Math.cos(t), s = Math.sin(t);
      d += seg(P(X + RW * c, 0, RW + RW * s), P(X + (RW + 3) * c, 0, RW + (RW + 3) * s));
    }
    spikes.setAttribute("d", d);
    wheel.setAttribute("d", tube([X, -1.2, RW], [X, 1.2, RW], RW, RW));
    hub.setAttribute("d", poly(ringPts([X, 1.3, RW], [0, 1, 0], 3, 16)));
  }
  const Bk = register(stage, (dt) => { const m = stepS(pos, dt); draw(); return m; });
  bag.add(Bk.unregister);

  function set(x) {
    pos.t = x == null ? REST : clamp(x, X0 + 8, XMAX);
    read.textContent = x == null ? "rest" : Math.round(pos.t - X0) + " mm";
    Bk.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.abs(y) > 60 || x < X0 - 50 || x > XMAX + 40) return set(null);
      set(x);
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { pos.k = 100 * v; pos.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

