  mount,
});

truffletray.code:
/**
 * Truffle box: a shallow box of twelve truffles in a grid, its lid hinged
 * along the back edge. The pointer over the box swings the lid up to show
 * the truffles; leaving lowers it to rest just ajar. At rest the lid is
 * bright. The slider is how far the lid opens.
 *
 * The pattern: one plate turned about a fixed hinge; the hit is the box's
 * rest footprint, which never moves. The lid is painted behind the truffles
 * once it stands past upright.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, rrect, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BW = 92, BD = 64, H = 14, LT = 3, REST = 12;
const disc = (x, y, r, n = 18) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[0, 0, 0], [BW, BD, 0], [BW, 0, 0], [0, BD, 0], [0, -8, H + BD + 2], [BW, -8, H + BD + 2], [0, BD, H + 12]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g), boxG = mk("g", {}, g);
  const [br, bi] = rings(0, 0, BW, BD, 5, 1.6);
  put(solid(boxG), prism(P, front, br, bi, 0, H));
  mk("path", { d: poly(ringAt(P, rrect(3, 3, BW - 3, BD - 3, 3, 4), H)), class: "lo" }, boxG);
  for (let j = 0; j < 3; j++) for (let i = 0; i < 4; i++) {
    const x = 14 + i * 21.3, y = 13 + j * 19, pts = [];
    for (const [r, z] of [[7, 0], [6.4, 2.6], [4.6, 4.6], [2, 5.8]]) pts.push(...ringAt(P, disc(x, y, r), H - 1 + z));
    mk("path", { d: poly(hull(pts)) }, boxG);
  }
  const lid = mk("path", { class: "sil hi" }, lidG), lidIn = mk("path", { class: "nf lo" }, lidG);
  const outer = rrect(-1, 0, BW + 1, BD + 1, 5, 4), inner = rrect(5, 6, BW - 5, BD - 5, 3, 4);
  const ang = tween(REST);
  let last = NaN, behind = false;

  // a lid point: x along the hinge, y away from it, d up through the plate
  const L = (a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return (x, y, d) => P(x, y * c - d * s, H + y * s + d * c); };

  function draw(a) {
    if (a === last) return;
    last = a;
    const f = L(a), pts = [];
    for (const q of outer) pts.push(f(q.u, q.v, 0), f(q.u, q.v, LT));
    lid.setAttribute("d", poly(hull(pts)));
    lidIn.setAttribute("d", poly(inner.map((q) => f(q.u, q.v, a > 90 ? 0 : LT))));
    const b = a > 70;
    if (b !== behind) { behind = b; if (b) boxG.after(lidG); else lidG.after(boxG); }
  }
  boxG.after(lidG);

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? max : REST, performance.now(), 0);
    read.textContent = v ? "open " + Math.round(max) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, H); setOn(x > -12 && x < BW + 12 && y > -12 && y < BD + 12); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "truffletray",
  means: "A box of twelve truffles: the pointer swings its hinged lid up to show them, and leaving lowers it back ajar.",
  rules: [1, 3, 5, 6],
  range: [70, 100, 115],
  tour: [[194, 215], [215, 250], [175, 170], null],
  mount,
});

winedecanter.code:
/**
 * Decanter: a wide-bellied wine decanter with a long neck and a ball stopper,
 * on a round coaster. The pointer over the coaster tips the decanter on the
 * edge of its foot to pour; leaving stands it back up with a slight lean. At
 * rest the stopper is bright; pouring gives the bright to the belly.
 *
 * The pattern: one lathed body turned about a fixed pivot; the hit is the
 * coaster's rest disc, which never moves.
 */
const {
  Cam, circ, clamp, fit, proj, hull, poly, prism, facing, rad, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RC = 50, Z0 = 4, FOOT = 17, REST = 4;
const BULB = [[17, 0], [25, 5], [28, 12], [25, 21], [15, 29], [6, 33]];
const NECK = [[5.2, 31], [4.6, 50], [5.6, 58], [6.6, 61]];
const STOP = [[2.6, 61], [4.8, 64], [5.8, 68], [4.4, 72], [1, 74]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.98);
  fit(C, [[-RC, -RC, 0], [RC, RC, 0], [RC, -RC, 0], [-RC, RC, 0], [0, 0, Z0 + 78], [40, 0, Z0 + 66]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(RC, 64), circ(RC - 2, 64), 0, Z0));
  const pour = mk("path", { class: "nf lo" }, g);
  const bulb = mk("path", { class: "sil" }, g), neck = mk("path", { class: "sil" }, g), lip = mk("path", { class: "nf lo" }, g);
  const stop = mk("path", { class: "sil hi" }, g);
  const lathe = (prof) => prof.map(([r, z]) => circ(r, 32).map((q) => [q.u, q.v, z]));
  const parts = [[bulb, lathe(BULB)], [neck, lathe(NECK)], [stop, lathe(STOP)]];
  const lipRing = lathe([[6.6, 61]])[0];
  const tilt = tween(REST);
  let last = NaN;

  function xf([x, y, z], a) {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a)), dx = x - FOOT;
    return P(FOOT + dx * c + z * s, y, Z0 + Math.max(0, -dx * s + z * c));
  }

  function draw(a) {
    if (a === last) return;
    last = a;
    for (const [el, rs] of parts) { const pts = []; for (const r of rs) for (const p of r) pts.push(xf(p, a)); el.setAttribute("d", poly(hull(pts))); }
    lip.setAttribute("d", poly(lipRing.map((p) => xf(p, a))));
    const f = clamp((a - 22) / 20, 0, 1);
    if (f > 0) {
      const top = xf([6.6, 0, 61], a), r = 3 + 9 * f;
      pour.setAttribute("d", seg(top, P(RC - 14, 0, Z0)) + poly(circ(r, 24).map((q) => P(RC - 14 + q.u * 0.7, q.v, Z0 + 0.1))));
    } else pour.setAttribute("d", "");
  }

  const B = register(stage, (_dt, now) => { draw(tval(tilt, now)); return !tdone(tilt, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(tilt, v ? max : REST, performance.now(), 0);
    read.textContent = v ? "pour " + Math.round(max) + "°" : "rest";
    bulb.classList.toggle("hi", v);
    stop.classList.toggle("hi", !v);
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, Z0); setOn(Math.hypot(x, y) < RC + 12); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "winedecanter",
  means: "A wine decanter on a coaster: the pointer tips it on its foot to pour, and leaving stands it back up.",
  rules: [1, 3, 5, 8],
  range: [30, 40, 50],
  tour: [[200, 163], [255, 215], [140, 160], null],
  mount,
});

tastevin.code:
/**
 * Wine cradle: a bottle lying in a tray slung between two posts, pinned at
 * its middle. The pointer over the base tips the cradle so the neck dips to
 * pour; leaving rocks it back, neck raised. At rest the bottle is bright.
 * The slider is how far the neck dips.
 *
 * The pattern: one body turned about a fixed pin; the hit is the base's rest
 * footprint, which never moves. Far post, tray, bottle, near post, back to
 * front.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Z0 = 5, PZ = 34, PY = 15, REST = 14;
const BOT = [[-34, 2], [-33, 9], [8, 9], [15, 7], [20, 3.6], [33, 3.4], [34, 4.2], [36, 4.2]];
const TRAY = [[-36, -13], [12, -13], [12, 13], [-36, 13]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-40, -24, 0], [40, 24, 0], [40, -24, 0], [-40, 24, 0], [-36, 0, PZ + 34], [36, 0, PZ + 22], [30, 0, Z0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-40, -24, 40, 24, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, Z0));
  const post = (y) => { const [r, i] = rings(-2.5, y - 2.5, 2.5, y + 2.5, 2.4, 0.8); put(solid(g), prism(P, front, r, i, Z0, PZ + 3)); };
  post(-PY);
  const tray = mk("path", { class: "" }, g), trayIn = mk("path", { class: "nf lo" }, g);
  const body = mk("path", { class: "sil hi" }, g), lip = mk("path", { class: "nf lo" }, g);
  post(PY);
  const pin = mk("path", { class: "nf", d: poly(circ(2.6, 16).map((q) => P(q.u, PY + 2.6, PZ + q.v))) }, g);
  const rngs = BOT.map(([u, r]) => circ(r, 24).map((q) => [u, q.u, q.v]));
  const ang = tween(REST);
  let last = NaN;

  const xf = ([u, y, w], a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return P(u * c - w * s, y, PZ + u * s + w * c); };

  function draw(a) {
    if (a === last) return;
    last = a;
    const tp = [];
    for (const [u, y] of TRAY) tp.push(xf([u, y, -14], a), xf([u, y, -7], a));
    tray.setAttribute("d", poly(hull(tp)));
    trayIn.setAttribute("d", poly(TRAY.map(([u, y]) => xf([u * 0.94 - 1, y * 0.8, -7], a))));
    const pts = [];
    for (const r of rngs) for (const p of r) pts.push(xf(p, a));
    body.setAttribute("d", poly(hull(pts)));
    lip.setAttribute("d", poly(rngs[5].map((p) => xf(p, a))) + seg(xf([8, -9, 0], a), xf([8, 9, 0], a)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? -max : REST, performance.now(), 0);
    read.textContent = v ? "pour " + Math.round(max) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, Z0); setOn(x > -48 && x < 48 && y > -32 && y < 32); },
    leave: () => setOn(false),
  }));
  bag.add(() => { pin.remove(); svg.replaceChildren(); });
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "tastevin",
  means: "A wine bottle in a pouring cradle: the pointer tips it on its pin so the neck dips to pour, and leaving rocks it back.",
  rules: [1, 3, 5, 8],
  range: [14, 22, 30],
  tour: [[200, 216], [228, 260], [175, 170], null],
  mount,
});

hatpress.code:
/**
 * Hat block: a milliner's wooden crown block seated in its brim board, a
 * wide round flange on a low foot. The pointer draws the crown block up out
 * of the brim, higher the nearer it comes to the middle, and the brim stays
 * put. At rest the crown sits a little proud, its tie groove bright. The
 * slider is how high the crown may lift.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, ringAt, run, clamp, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BR = 50, CR = 27, FZ = 5, BZ = 11, CH = 30, REST = 7;
const disc = (r, n = 48) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxLift = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[-BR, -BR, 0], [BR, BR, 0], [-BR, BR, 0], [BR, -BR, 0], [0, 0, BZ + 70 + CH + 12]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(34), disc(31), 0, FZ));
  put(solid(g), prism(P, front, disc(BR), disc(BR - 3), FZ, BZ));
  mk("path", { d: poly(ringAt(P, disc(CR + 3), BZ)), class: "nf lo" }, g);
  const cg = solid(g), groove = mk("path", { class: "nf hi" }, g), seam = mk("path", { class: "nf lo" }, g);

  const lift = spring(REST);
  let last = NaN;
  function draw(z) {
    if (Math.abs(z - last) < 0.01) return;
    last = z;
    const z0 = BZ + z, pts = [];
    pts.push(...ringAt(P, disc(CR), z0));
    const prof = [[CR, 0], [CR, CH * 0.6], [CR - 1.5, CH * 0.78], [CR - 5, CH * 0.92], [CR - 11, CH * 1.0], [CR - 19, CH * 1.05], [4, CH * 1.08]];
    for (const [r, h] of prof) pts.push(...ringAt(P, disc(r), z0 + h));
    put(cg, { sil: poly(hull(pts)), crease: "" });
    groove.setAttribute("d", open(ringAt(P, run(disc(CR), front), z0 + 8)));
    seam.setAttribute("d", open(ringAt(P, run(disc(CR - 1.5), front), z0 + CH * 0.78)));
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [gx, gy] = unproj(C, sx, sy, BZ);
    const d = Math.hypot(gx, gy);
    if (d > 110) return leave();
    const f = clamp(1 - (d - 10) / 90, 0.12, 1);
    lift.t = REST + (maxLift - REST) * f;
    read.textContent = "lift " + Math.round(lift.t);
    B.wake();
  }
  function leave() { lift.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxLift = v; }, destroy: bag.dispose };
}

hairline({
  name: "hatpress",
  means: "A milliner's crown block seated in its brim board: the pointer draws the crown up out of the brim, higher toward the middle.",
  rules: [1, 3, 5, 8],
  range: [30, 55, 70],
  tour: [[248, 251], [200, 227], [136, 259], null],
  mount,
});

banknote.code:
/**
 * Banknote: a teller's note tray, a shallow rounded tray holding a stack of
 * notes under a hinged weight bar. The pointer lifts the bar off the stack
 * on its back hinge, higher the nearer it comes, so the notes can be
 * counted out. At rest the bar is tipped up a little, bright. The slider is
 * how far the bar may swing.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rad, clamp, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TW = 120, TD = 70, TZ = 8, NZ = 14, HY = 10, BD = 44, BT = 2.5, REST = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-4, -4, 0], [TW + 4, TD + 4, 0], [TW + 4, -4, 0], [-4, TD + 4, 0], [10, HY, NZ + BD + 4], [TW - 10, HY, NZ + BD + 4]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(0, 0, TW, TD, 10, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  const [wr, wi] = rings(6, 6, TW - 6, TD - 6, 7, 1);
  mk("path", { d: poly(wr.map((q) => P(q.u, q.v, TZ))), class: "nf lo" }, g);
  // the stack of notes, with two edges showing its leaves
  const [nr, ni] = rings(14, 12, TW - 14, TD - 10, 2, 1.2);
  put(solid(g), prism(P, front, nr, ni, TZ - 2, NZ));
  for (const z of [TZ + 1.5, TZ + 3.5]) mk("path", { d: open([P(14, TD - 10, z), P(TW - 14, TD - 10, z)]), class: "nf lo" }, g);
  // hinge knuckles
  for (const x of [22, TW - 22]) put(solid(g), prism(P, front, ...rings(x - 5, HY - 4, x + 5, HY + 4, 3, 1), NZ, NZ + 5));
  const bar = solid(g);
  bar.sil.classList.add("hi");
  const grip = mk("path", { class: "nf lo" }, g);

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.01) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (x, d, t) => P(x, HY + d * c - t * s, NZ + 2 + d * s + t * c);
    const xs = [20, TW - 20], top = [], bot = [];
    for (const [x, d] of [[xs[0], 0], [xs[1], 0], [xs[1], BD], [xs[0], BD]]) { top.push(at(x, d, BT)); bot.push(at(x, d, 0)); }
    put(bar, { sil: poly(hull(top.concat(bot))), crease: open(top.concat([top[0]])) });
    grip.setAttribute("d", open([at(TW / 2 - 14, BD - 6, BT), at(TW / 2 + 14, BD - 6, BT)]));
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [gx, gy] = unproj(C, sx, sy, NZ);
    const d = Math.hypot(gx - TW / 2, gy - TD / 2);
    if (d > 120) return leave();
    ang.t = REST + (maxA - REST) * clamp(1 - (d - 10) / 90, 0.1, 1);
    read.textContent = "bar " + Math.round(ang.t) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "banknote",
  means: "A teller's note tray: the pointer lifts the hinged weight bar off the stack of notes, higher the nearer it comes.",
  rules: [1, 3, 5, 8],
  range: [60, 95, 110],
  tour: [[258, 221], [200, 192], [142, 163], null],
  mount,
});

quillknife.code:
/**
 * Quill knife: a folding pen knife lying on its side, a slim rounded handle
 * with a pivot pin at one end and the blade swung part open. The pointer
 * swings the blade about its pin, toward wherever it stands, open past the
 * handle's end or folded back over it. At rest the blade is half open, bright.
 * The slider is how far the blade may open.
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rings, rad, clamp, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HL_ = 92, HW = 18, HZ = 10, PX = 84, PY = 9, BZ = 1.6, REST = 72;
const BLADE = fillet([[-7, -7], [58, -7], [84, -1], [64, 6], [12, 8], [-7, 7]], [5, 4, 1.5, 6, 6, 5], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxOpen = value;
  const C = Cam(45, 0.5, 2.65);
  const ext = [[-2, -2, 0], [HL_ + 2, HW + 2, 0], [-2, HW + 2, 0], [HL_ + 2, -2, 0]]; for (let a = 0; a <= 180; a += 15) ext.push([PX + 85 * Math.cos(rad(a)), PY + 85 * Math.sin(rad(a)), HZ]);
  fit(C, ext, 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [hr, hi] = rings(0, 0, HL_, HW, 9, 1.8);
  put(solid(g), prism(P, front, hr, hi, 0, HZ));
  // liner groove along the handle top and the two pins
  mk("path", { d: open([P(10, HW / 2, HZ), P(PX - 10, HW / 2, HZ)]), class: "nf lo" }, g);
  const pin = (x) => { const r = []; for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2; r.push(P(x + 2.4 * Math.cos(a), PY + 2.4 * Math.sin(a), HZ)); } return r; };
  mk("path", { d: poly(pin(8)), class: "nf lo" }, g);
  const bl = solid(g);
  bl.sil.classList.add("hi");
  const nick = mk("path", { class: "nf lo" }, g);
  mk("path", { d: poly(pin(PX)), class: "nf" }, g);

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.01) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const w = ([u, v]) => [PX + u * c - v * s, PY + u * s + v * c];
    const top = BLADE.map((q) => { const [x, y] = w(q); return P(x, y, HZ + BZ); });
    const bot = BLADE.map((q) => { const [x, y] = w(q); return P(x, y, HZ); });
    put(bl, { sil: poly(hull(top.concat(bot))), crease: open(top.concat([top[0]])) });
    const n = []; for (let i = 0; i <= 6; i++) { const t = Math.PI * (i / 6); const [x, y] = w([44 + 4 * Math.cos(t), -3 + 2.5 * Math.sin(t)]); n.push(P(x, y, HZ + BZ)); }
    nick.setAttribute("d", open(n));
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [gx, gy] = unproj(C, sx, sy, 0);
    const dx = gx - PX, dy = gy - PY;
    if (Math.hypot(dx, dy) > 150 || Math.hypot(dx, dy) < 4) return leave();
    let th = Math.atan2(dy, dx) * 180 / Math.PI;
    if (th < 0) th = th > -90 ? 0 : 180;
    const lo = 180 - maxOpen;
    ang.t = clamp(th, lo, 180);
    const open_ = Math.round(180 - ang.t);
    read.textContent = open_ < 8 ? "shut" : "open " + open_ + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxOpen = v; }, destroy: bag.dispose };
}

hairline({
  name: "quillknife",
  means: "A folding pen knife on its side: the blade swings about its pin toward the pointer, open past the handle or folded back over it.",
  rules: [1, 3, 5, 8],
  range: [90, 150, 180],
  tour: [[355, 241], [261, 288], [36, 232], null],
  mount,
});

sealingwax.code:
/**
 * Seal press: a cast-iron embossing press on a small base, a C-shaped body
 * with a lower die and a long lever arm carrying the upper die. The pointer
 * near it pulls the lever down on its back pivot until the dies meet. At rest
 * the lever is raised, bright. The slider is how high the lever lifts.
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const cl = (v, a, b) => Math.max(a, Math.min(b, v));
const cyl = (x, y, r, z0, z1, n = 20) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * 2 * Math.PI; o.push([x + r * Math.cos(a), y + r * Math.sin(a), z0], [x + r * Math.cos(a), y + r * Math.sin(a), z1]); } return o; };
const loop = (x, y, r, z, n = 24) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * 2 * Math.PI; o.push([x + r * Math.cos(a), y + r * Math.sin(a), z]); } return o; };
const box = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
const top = (x0, y0, x1, y1, z) => [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]];
const H = [-22, 0, 42];
function rotY(q, a) {
  const x = q[0] - H[0], z = q[2] - H[2], c = Math.cos(a), s = Math.sin(a);
  return [H[0] + x * c + z * s, q[1], H[2] + z * c - x * s];
}

const RANGE = [20, 34, 44], REST = 0.15, CEN = [10, 0, 34];
function build(t, amp) {
  const a = (-(1 - t) * amp + 2 * t) * (Math.PI / 180), m = (q) => rotY(q, a);
  return [
    { pts: box(-34, -20, 0, 36, 20, 5), loops: [top(-34, -20, 36, 20, 5)] },
    { pts: box(-30, -8, 5, -14, 8, 40), loops: [top(-30, -8, -14, 8, 40)] },
    { pts: box(-14, -7, 5, 30, 7, 18), loops: [top(-14, -7, 30, 7, 18)] },
    { pts: cyl(20, 0, 8, 18, 23, 20), loops: [loop(20, 0, 8, 23, 20)] },
    { pts: cyl(-22, 0, 6, 36, 48, 16).map(m) },
    { pts: cyl(20, 0, 7.5, 24, 38, 20).map(m), loops: [loop(20, 0, 7.5, 24, 20).map(m)] },
    { pts: box(-28, -5, 37, 58, 5, 46).map(m), hi: true, loops: [top(-28, -5, 58, 5, 46).map(m)] },
    { pts: cyl(62, 0, 8, 34, 50, 18).map(m), loops: [loop(62, 0, 8, 50, 18).map(m)] },
  ];
}
const label = (t, on) => (on ? "p " + Math.round(t * 100) : "rest");

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.5);
  const ext = [];
  for (const t of [0, 0.5, 1]) for (const it of build(t, RANGE[2])) ext.push(...it.pts);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const c = P(CEN[0], CEN[1], CEN[2]);
  const g = mk("g", {}, svg);
  const els = [], hiEls = [];
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    build(t, amp).forEach((it, i) => {
      if (!els[i]) { els[i] = { s: mk("path", { class: "sil" }, g), l: (it.loops || []).map(() => mk("path", { class: "nf lo" }, g)) }; if (it.hi) hiEls.push(els[i].s); }
      els[i].s.setAttribute("d", poly(hull(it.pts.map((q) => P(q[0], q[1], q[2])))));
      (it.loops || []).forEach((lp, j) => els[i].l[j].setAttribute("d", poly(lp.map((q) => P(q[0], q[1], q[2])))));
    });
  }
  const tw = tween(REST);
  draw(REST);
  hiEls.forEach((e) => e.classList.add("hi"));
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  function aim(p) {
    const t = p ? cl(1.3 - Math.hypot(p[0] - c[0], p[1] - c[1]) / 120, 0, 1) : REST;
    tset(tw, t, performance.now(), 0);
    read.textContent = label(t, !!p);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "sealingwax",
  means: "A cast-iron embossing seal press: the pointer pulls its long lever down on the back pivot until the dies meet.",
  rules: [1, 3, 5, 6],
  range: [20, 34, 44],
  tour: [[218, 178], [262, 176], [180, 205], null],
  mount,
});

blottingrock.code:
/**
 * Sand shaker: a turned pounce pot, waisted, with a dished top pierced with
 * holes, standing on a letter sheet. The pointer near it tips the pot over its
 * foot to shake sand onto the sheet. At rest it leans a little, its rim
 * bright. The slider is how far it tips.
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, place, pointer, register } = HL;

const cl = (v, a, b) => Math.max(a, Math.min(b, v));
const ring = (x, y, r, z, n = 24) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * 2 * Math.PI; o.push([x + r * Math.cos(a), y + r * Math.sin(a), z]); } return o; };
const box = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
const H = [16, 0, 2];
function rotY(q, a) {
  const x = q[0] - H[0], z = q[2] - H[2], c = Math.cos(a), s = Math.sin(a);
  return [H[0] + x * c + z * s, q[1], H[2] + z * c - x * s];
}
const HOLES = [[0, 0], [5, 0], [-5, 0], [0, 5], [0, -5], [3.6, 3.6], [-3.6, -3.6], [3.6, -3.6], [-3.6, 3.6]];

const REST = 0.15, CEN = [10, 0, 20];
function build(t, amp) {
  const a = (8 + (amp - 8) * t) * (Math.PI / 180), m = (q) => rotY(q, a);
  return {
    parts: [
      { pts: box(-26, -24, 0, 60, 24, 2), loops: [] },
      { pts: ring(0, 0, 16, 2).concat(ring(0, 0, 16, 6)).map(m), loops: [] },
      { pts: ring(0, 0, 15, 6).concat(ring(0, 0, 8, 19)).map(m), loops: [] },
      { pts: ring(0, 0, 8, 19).concat(ring(0, 0, 16, 33)).map(m), loops: [] },
      { pts: ring(0, 0, 17, 33).concat(ring(0, 0, 17, 37)).map(m), hi: true, loops: [ring(0, 0, 13.5, 36.2, 28).map(m)] },
    ],
    holes: HOLES.map(([x, y]) => m([x, y, 35.6])),
  };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 3.1);
  const ext = [];
  for (const t of [0, 0.5, 1]) for (const it of build(t, 80).parts) ext.push(...it.pts);
  fit(C, ext, 200, 170);
  const P = proj(C), pp = (q) => P(q[0], q[1], q[2]);
  const c = pp(CEN);
  const g = mk("g", {}, svg);
  const els = [], hiEls = [], dots = HOLES.map(() => null);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const b = build(t, amp);
    b.parts.forEach((it, i) => {
      if (!els[i]) { els[i] = { s: mk("path", { class: "sil" }, g), l: it.loops.map(() => mk("path", { class: "nf lo" }, g)) }; if (it.hi) hiEls.push(els[i].s); }
      els[i].s.setAttribute("d", poly(hull(it.pts.map(pp))));
      it.loops.forEach((lp, j) => els[i].l[j].setAttribute("d", poly(lp.map(pp))));
    });
    b.holes.forEach((q, i) => { if (!dots[i]) dots[i] = mk("circle", { r: 1.3, class: "dot off" }, g); place(dots[i], pp(q)); });
  }
  const tw = tween(REST);
  draw(REST);
  hiEls.forEach((e) => e.classList.add("hi"));
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  function aim(p) {
    const t = p ? cl(1.3 - Math.hypot(p[0] - c[0], p[1] - c[1]) / 120, 0, 1) : REST;
    tset(tw, t, performance.now(), 0);
    read.textContent = p ? Math.round(8 + (amp - 8) * t) + "deg" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "blottingrock",
  means: "A turned pounce pot with a pierced, dished top on a letter sheet: the pointer tips it over its foot to shake out sand.",
  rules: [1, 3, 5, 6],
  range: [50, 65, 80],
  tour: [[163, 92], [205, 135], [250, 175], null],
  mount,
});

penwiper.code:
/**
 * Pen rack: a dip pen lying across the notched posts of a small wooden rack,
 * holder, brass ferrule and nib. The pointer near it lifts the pen off the
 * rack and tips the nib down, ready to write. At rest it sits just raised,
 * bright. The slider is how far the nib tips.
 */
const { Cam, fit, hull, poly, proj, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const cl = (v, a, b) => Math.max(a, Math.min(b, v));
const box = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]];
const top = (x0, y0, x1, y1, z) => [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]];
const ZC = 27;
const xr = (x, r, n = 18) => { const o = []; for (let i = 0; i < n; i++) { const a = (i / n) * 2 * Math.PI; o.push([x, r * Math.cos(a), ZC + r * Math.sin(a)]); } return o; };
function mv(q, a, lift) {
  const x = q[0], z = q[2] - ZC, c = Math.cos(a), s = Math.sin(a);
  return [x * c + z * s, q[1], ZC + lift + z * c - x * s];
}

const REST = 0.12, CEN = [0, 0, 30];
function build(t, amp) {
  const a = amp * t * (Math.PI / 180), lift = 24 * t * t, m = (q) => mv(q, a, lift);
  return [
    { pts: box(-42, -16, 0, 42, 16, 6), loops: [top(-42, -16, 42, 16, 6)] },
    { pts: box(-36, -5, 6, -26, 5, 24), loops: [top(-36, -5, -26, 5, 24)] },
    { pts: box(26, -5, 6, 36, 5, 24), loops: [top(26, -5, 36, 5, 24)] },
    { pts: xr(-58, 3).concat(xr(-52, 4.4)).map(m) },
    { pts: xr(-52, 4.4).concat(xr(18, 3.4)).map(m), hi: true },
    { pts: xr(18, 3.6).concat(xr(30, 4)).map(m), loops: [xr(24, 3.8).map(m)] },
    { pts: [[30, -3.4, ZC], [30, 3.4, ZC], [44, 1.8, ZC - 0.4], [52, 0, ZC - 0.8], [44, -1.8, ZC - 0.4]].map(m), raw: true, loops: [[[30, 0, ZC], [41, 0, ZC - 0.3]].map(m)] },
  ];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.6);
  const ext = [];
  for (const t of [0, 0.5, 1]) for (const it of build(t, 44)) ext.push(...it.pts);
  fit(C, ext, 200, 166);
  const P = proj(C), pp = (q) => P(q[0], q[1], q[2]);
  const c = pp(CEN);
  const g = mk("g", {}, svg);
  const els = [], hiEls = [];
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    build(t, amp).forEach((it, i) => {
      if (!els[i]) { els[i] = { s: mk("path", { class: "sil" }, g), l: (it.loops || []).map(() => mk("path", { class: "nf lo" }, g)) }; if (it.hi) hiEls.push(els[i].s); }
      els[i].s.setAttribute("d", poly(it.raw ? it.pts.map(pp) : hull(it.pts.map(pp))));
      (it.loops || []).forEach((lp, j) => els[i].l[j].setAttribute("d", (lp.length > 2 ? poly : (p) => "M" + p.map((q) => q.join(",")).join("L"))(lp.map(pp))));
    });
  }
  const tw = tween(REST);
  draw(REST);
  hiEls.forEach((e) => e.classList.add("hi"));
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  function aim(p) {
    const t = p ? cl(1.3 - Math.hypot(p[0] - c[0], p[1] - c[1]) / 120, 0, 1) : REST;
    tset(tw, t, performance.now(), 0);
    read.textContent = p ? "up " + Math.round(t * 100) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "penwiper",
  means: "A dip pen lying across a small notched wooden rack: the pointer lifts it off the posts and tips the nib down to write.",
  rules: [1, 3, 5, 6],
  range: [24, 34, 44],
  tour: [[203, 196], [150, 168], [262, 222], null],
  mount,
});

spicetin.code:
/**
 * Spice tin: a flat rounded tin with a lid hinged along its back edge and a
 * heap of spice inside. The pointer over the tin swings the lid up on its
 * hinge and back past upright; at rest it stands ajar, bright. The slider is
 * how far the lid opens.
 *
 * The pattern: one part answering the pointer, a lid turned about a hinge.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 32, D = 21, H = 20, LT = 3.2;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[-W, -D, 0], [W, D, 0], [-W, D, 0], [W, -D, 0], [-W, -D - 12, H + 2 * D + 4], [W, -D - 12, H + 2 * D + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const body = mk("g", {}, g);
  const [br, bi] = rings(-W, -D, W, D, 7, 2.2);
  put(solid(body), prism(P, front, br, bi, 0, H));
  // the spice: a low heap inside the rim
  const heap = [];
  for (const [r, z] of [[16, 0], [12, 3], [7, 5.5], [3, 6.5]]) heap.push(...ringAt(P, disc(3, 2, r, 22), H - 5 + z));
  mk("path", { d: poly(hull(heap)), class: "nf lo" }, body);
  // the hinge pins along the back edge
  for (const x of [-W + 9, W - 9]) put(solid(body), prism(P, front, disc(x, -D - 0.6, 2, 14), null, H - 3, H + 1.5));

  const lidG = mk("g", {}, g), lid = solid(lidG);
  lid.sil.classList.add("hi");
  const [lr, li] = rings(-W - 0.8, -D - 0.8, W + 0.8, D + 0.8, 7.5, 2.4);

  let last = NaN, behind = null;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = rad(18 + (112 * amp - 18) * t), ca = Math.cos(a), sa = Math.sin(a);
    // a lid sample (x, v from the hinge, w up through the lid) turned about the hinge line
    const L = (q, w) => { const v = q.v + D + 0.8; return P(q.u, -D - 0.8 + v * ca - w * sa, H + v * sa + w * ca); };
    const pts = lr.map((q) => L(q, 0)).concat(lr.map((q) => L(q, LT)));
    lid.sil.setAttribute("d", poly(hull(pts)));
    const up = a > Math.PI / 2;
    lid.cr.setAttribute("d", poly(li.map((q) => L(q, up ? 0 : LT))));
    if (up !== behind) { behind = up; if (up) body.before(lidG); else body.after(lidG); }
  }
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, H);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 110 && Math.abs(sy - mid[1]) < 80), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "spicetin",
  means: "A flat spice tin with a hinged lid: the pointer swings the lid up and back on its hinge to show the spice inside.",
  rules: [1, 4, 5, 8],
  range: [0.6, 1, 1],
  tour: [[186, 209], [150, 196], [232, 228], null],
  mount,
});

cakepop.code:
/**
 * Pie bird: a little ceramic bird funnel standing up through the crust of a
 * round pie, its beak open to let the steam out. The pointer over the pie
 * makes the bird rise out of the crust and tip its beak up to the sky; at
 * rest it sits low and leaning a little, bright. The slider is how far it
 * rises and tips.
 *
 * The pattern: one part answering the pointer, a body lifted and tilted.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PR = 40, DZ = 8, CZ = 13, H2 = Math.SQRT1_2;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-PR, -PR, 0], [PR, PR, 0], [-PR, PR, 0], [PR, -PR, 0], [0, 0, CZ + 58], [16, -16, CZ + 44]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [dr, di] = rings(-PR, -PR, PR, PR, PR, 2.4);
  put(solid(g), prism(P, front, dr, di, 0, DZ));
  // the crust: a low dome inside the rim, with vent slits
  const dome = [];
  for (const [r, z] of [[PR - 3, DZ], [PR - 8, DZ + 3.5], [PR - 18, CZ], [8, CZ + 0.6]]) dome.push(...ringAt(P, disc(0, 0, r), z));
  mk("path", { d: poly(hull(dome)) }, g);
  let slits = "";
  for (let i = 0; i < 6; i++) { const a = (i / 6) * Math.PI * 2 + 0.3; slits += open([P(19 * Math.cos(a), 19 * Math.sin(a), CZ - 1.2), P(27 * Math.cos(a), 27 * Math.sin(a), DZ + 3)]); }
  mk("path", { d: slits, class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(0, 0, 9.5, 28), CZ)), class: "nf lo" }, g);

  const body = mk("path", { class: "sil hi" }, g), wing = mk("path", { class: "nf lo" }, g);
  const head = mk("path", { class: "sil hi" }, g), beak = mk("path", { class: "nf" }, g), eye = mk("path", { class: "nf" }, g);

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = rad(-8 + 30 * amp * t), lift = 14 * amp * t, ca = Math.cos(a), sa = Math.sin(a);
    // local (f forward toward the beak, s sideways, h up) turned back about the base, then lifted
    const B = (f, s, h) => { const ff = f * ca - h * sa, hh = f * sa + h * ca; return P(ff * H2 - s * H2, -ff * H2 - s * H2, CZ - 4 + lift + hh); };
    const ring = (r, h, f0 = 0, n = 24) => circ(r, n).map((q) => B(f0 + q.u, q.v, h));
    body.setAttribute("d", poly(hull([...ring(8.5, 0), ...ring(8, 8), ...ring(6.5, 18), ...ring(4.5, 26, 1)])));
    wing.setAttribute("d", open([B(-2, 7.4, 16), B(-7, 6.5, 9), B(-9, 6, 4)]));
    const hp = [];
    for (let i = -3; i <= 3; i++) { const h = 33 + 6.5 * (i / 3), r = 6.5 * Math.sqrt(1 - (i / 3) ** 2) + 0.2; hp.push(...ring(r, h, 2)); }
    head.setAttribute("d", poly(hull(hp)));
    beak.setAttribute("d", poly([B(7.5, 0, 35), B(16, 0, 33.5), B(7.8, 0, 31), B(13, 0, 33.3)]));
    eye.setAttribute("d", poly(circ(1, 10).map((q) => B(4.5 + q.u * 0.4, -5.6, 36 + q.v))));
  }
  const tw = tween(0);
  const Bk = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(Bk.unregister);

  const mid = P(0, 0, CZ + 10);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "steam" : "rest";
    Bk.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 120 && Math.abs(sy - mid[1]) < 100), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; Bk.wake(); }, destroy: bag.dispose };
}

