nailstand.code:
/**
 * Nail lamp: a domed UV curing lamp on its base tray, with an arched opening
 * at the front for the hand. The pointer tilts the hood up on its back
 * hinge: the further it stands from the lamp, the higher the hood swings,
 * showing the cure pad under it. At rest the arched opening is bright.
 * The slider is how far the hood may tilt.
 */
const {
  Cam, fit, hull, poly, open, proj, rrect, rings, prism, facing, clamp, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 60, D = 52, BZ = 4, HZ = 24, MAXA = 0.62, REST = 0.06;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-18, -8, 0], [L + 8, D + 8, 0], [48, D, 60], [-16, 0, 26], [L + 8, D + 8, 26]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -6, L + 8, D + 6, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [pr, pi] = rings(10, 10, L - 6, D - 10, 8, 1.5);
  const pad = solid(g);
  put(pad, prism(P, front, pr, pi, BZ, BZ + 1.5));
  const hood = solid(g);
  const arch = mk("path", { class: "nf" }, g);
  const lens = mk("path", { class: "nf lo" }, g);
  const foot = rrect(0, 0, L, D, 14, 6), top = rrect(6, 5, L - 8, D - 5, 11, 6), inner = rrect(8, 7, L - 10, D - 7, 9, 6);
  const tilt = (a, x, y, z) => {
    const c = Math.cos(a), s = Math.sin(a), dz = z - BZ;
    return P(x * c - dz * s, y, BZ + x * s + dz * c);
  };
  const op = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = foot.map((q) => tilt(a, q.u, q.v, BZ)).concat(top.map((q) => tilt(a, q.u, q.v, HZ + BZ)));
    hood.sil.setAttribute("d", poly(hull(pts)));
    hood.cr.setAttribute("d", poly(inner.map((q) => tilt(a, q.u, q.v, HZ + BZ - 0.2))));
    const ap = [];
    for (let i = 0; i <= 16; i++) {
      const t = (i / 16) * Math.PI;
      const xx = L - 0.6 - 1.8 * Math.sin(t);
      ap.push(tilt(a, xx, D / 2 - 17 * Math.cos(t), BZ + 13 * Math.sin(t)));
    }
    arch.setAttribute("d", poly(ap));
    const lp = [];
    for (let i = 0; i < 20; i++) { const t = (i / 20) * Math.PI * 2; lp.push(tilt(a, L / 2 + 6 * Math.cos(t), D / 2 + 6 * Math.sin(t), HZ + BZ - 0.1)); }
    lens.setAttribute("d", poly(lp));
  }
  const B = register(stage, (dt) => { const m = stepS(op, dt); draw(op.x); return m; });
  bag.add(B.unregister);

  const mid = P(L / 2, D / 2, BZ + HZ / 2);
  let on = null;
  function aim(p) {
    const inside = p && Math.abs(p[0] - mid[0]) < 150 && Math.abs(p[1] - mid[1]) < 120;
    const o = inside ? clamp(Math.hypot(p[0] - mid[0], p[1] - mid[1]) / 60, 0.3, 1) : 0;
    op.t = inside ? Math.max(REST, o * MAXA * reach) : REST;
    const act = !!inside;
    if (act !== on) {
      on = act;
      arch.classList.toggle("hi", !act);
      hood.sil.classList.toggle("hi", act);
    }
    read.textContent = act ? Math.round((op.t * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; }, destroy: bag.dispose };
}

hairline({
  name: "nailstand",
  means: "A UV nail lamp on its tray: the pointer tilts the domed hood up on its back hinge to show the cure pad beneath.",
  rules: [1, 3, 4, 5],
  range: [40, 80, 100],
  tour: [[219, 251], [150, 150], [290, 180], null],
  mount,
});

mirrorlight.code:
/**
 * Vanity mirror: a tri-fold mirror on a low plinth, a tall centre glass with
 * a hinged wing on each side. The pointer picks a wing by where it stands:
 * that wing opens flat beside the glass and the other folds in across it; over
 * the middle both open flat. At rest the left wing stands ajar, the right half
 * shut, and the centre glass is bright. The slider is how far the other folds.
 *
 * The pattern: one of a few parts, picked by screen x (riffle).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, tdone, tset, tval, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HW = 20, WW = 20, Z0 = 6, Z1 = 78, T = 1.8, REST = 32;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-HW - WW, -8, 0], [HW + WW, -8, 0], [-HW - WW, 0, Z1], [HW + WW, 0, Z1], [HW, WW, 0], [-HW, WW, Z1], [HW + 4, 20, Z1]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-HW - 4, -9, HW + 4, 7, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, Z0));

  // a panel standing on the line from (hx, hy) along angle a (deg), u from u0 to u1
  const face = (hx, hy, dx, dy, ring, off) => ring.map((q) => P(hx + q.u * dx + off[0], hy + q.u * dy + off[1], q.v));
  const outer = (u0, u1, z0, z1) => rrect(u0, z0, u1, z1, 5, 5);
  const glass = (u0, u1, z0, z1) => rrect(u0 + 4, z0 + 4, u1 - 4, z1 - 4, 2.5, 4);

  function panel(el, hx, hy, dx, dy, u0, u1, z0, z1) {
    const n = [-dy * T, dx * T];
    const back = n[0] + n[1] < 0 ? n : [-n[0], -n[1]], fr = [0, 0];
    const o = outer(u0, u1, z0, z1);
    const a = face(hx, hy, dx, dy, o, back), b = face(hx, hy, dx, dy, o, fr);
    el.sil.setAttribute("d", poly(hull(a.concat(b))));
    el.edge.setAttribute("d", poly(b));
    el.gl.setAttribute("d", poly(face(hx, hy, dx, dy, glass(u0, u1, z0, z1), fr)));
  }
  const mkPanel = (parent) => {
    const grp = mk("g", {}, parent);
    return { grp, sil: mk("path", { class: "sil" }, grp), edge: mk("path", { class: "nf lo" }, grp), gl: mk("path", { class: "nf lo" }, grp) };
  };

  const mid = mkPanel(g);
  panel(mid, 0, 0, 1, 0, -HW, HW, Z0, Z1);
  const wings = [-1, 1].map((s) => ({ s, el: mkPanel(g), a: tween(s < 0 ? REST : 100), last: NaN }));

  function draw(w, a) {
    if (a === w.last) return;
    w.last = a;
    const dx = w.s * Math.cos(rad(a)), dy = Math.sin(rad(a));
    panel(w.el, w.s * HW, 0, dx, dy, 0.6, WW, Z0 + 3, Z1 - 3);
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const w of wings) { draw(w, tval(w.a, now)); if (!tdone(w.a, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const cx = P(0, 0, (Z0 + Z1) / 2), lx = P(-HW - WW / 2, 4, 40), rx = P(HW + WW / 2, 4, 40);
  function hit([sx, sy]) {
    if (sy < P(0, 0, Z1 + 8)[1] || sy > P(0, 10, 0)[1] + 10) return -1;
    if (sx < lx[0] - 30 || sx > rx[0] + 30) return -1;
    if (Math.abs(sx - cx[0]) < 16) return 1;
    return sx < cx[0] ? 0 : 2;
  }

  let act = -2;
  const NAMES = ["left", "mid", "right"];
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    wings.forEach((w, k) => {
      const i = k * 2; // 0 or 2
      const to = a < 0 ? (i ? 100 : REST) : a === 1 || a === i ? 0 : swing;
      tset(w.a, to, now, from < 0 ? 0 : Math.abs(i - from) * 25);
      w.el.sil.classList.toggle("hi", a === i);
    });
    mid.sil.classList.toggle("hi", a < 0 || a === 1);
    read.textContent = a < 0 ? "rest" : NAMES[a];
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; }, destroy: bag.dispose };
}

hairline({
  name: "mirrorlight",
  means: "A tri-fold vanity mirror: the wing under the pointer opens flat while the other folds in across the glass.",
  rules: [1, 2, 5, 6],
  range: [70, 140, 165],
  tour: [[128, 88], [192, 134], [247, 141], null],
  mount,
