chessbox.code:
/**
 * Chess box: a folding wooden chess box, two hinged halves whose insides make
 * the board. At rest the near half stands up on its hinge, half open, and the
 * far half lies flat, bright. The pointer over the box swings the near half
 * down flat to lay out the full board; leaving folds it back up. The slider
 * is where the half rests.
 *
 * The pattern: one part swinging on a hinge (cloches, one item).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween, unproj, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 36, L = 72, T = 6, SQ = W / 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restA = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[0, 0, 0], [2 * W, 0, 0], [0, L, 0], [2 * W, L, 0], [W, 0, T + W], [W, L, T + W]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the far half, lying flat, with its squares
  const fixed = solid(g);
  const [fr, fi] = rings(0, 0, W, L, 3, 1.4);
  put(fixed, prism(P, front, fr, fi, 0, T));
  fixed.sil.classList.add("sil");
  let d = "";
  for (let i = 1; i < 4; i++) d += seg(P(i * SQ, 2, T), P(i * SQ, L - 2, T));
  for (let j = 1; j < 8; j++) d += seg(P(2, j * SQ + 0, T), P(W - 2, j * SQ, T));
  mk("path", { d, class: "nf lo" }, g);

  // the near half, hinged along x = W at the board's height
  const mg = mk("g", {}, g), msil = mk("path", { class: "sil" }, mg), mface = mk("path", { class: "nf lo" }, mg), mgrid = mk("path", { class: "nf lo" }, mg);
  const outer = rrect(0, 0, W, L, 3, 4), face = rrect(1.4, 1.4, W - 1.4, L - 1.4, 1.8, 4);
  const at = (a, u, v, w) => P(W + u * Math.cos(a) + w * Math.sin(a), v, T + u * Math.sin(a) - w * Math.cos(a));
  const ang = tween(restA);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg);
    const top = outer.map((q) => at(a, q.u, q.v, 0)), bot = outer.map((q) => at(a, q.u, q.v, T));
    msil.setAttribute("d", poly(hull(top.concat(bot))));
    const up = deg < 55;
    mface.setAttribute("d", up ? poly(face.map((q) => at(a, q.u, q.v, 0))) : "");
    let gd = "";
    if (up) {
      for (let i = 1; i < 4; i++) gd += seg(at(a, i * SQ, 2, 0), at(a, i * SQ, L - 2, 0));
      for (let j = 1; j < 8; j++) gd += seg(at(a, 2, j * SQ, 0), at(a, W - 2, j * SQ, 0));
    }
    mgrid.setAttribute("d", gd);
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, T);
    return x > -8 && x < 2 * W + 8 && y > -8 && y < L + 8 ? 1 : -1;
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a > 0 ? 0 : restA, performance.now(), 0);
    fixed.sil.classList.toggle("hi", a < 0);
    msil.classList.toggle("hi", a > 0);
    read.textContent = a < 0 ? "rest" : "open";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restA = v; if (act < 0) { tset(ang, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "chessbox",
  means: "A folding chess box: the pointer swings the standing half down flat to lay out the board, and it folds back up after.",
  rules: [1, 3, 5, 6],
  range: [70, 105, 140],
  tour: [[190, 137], [124, 194], [200, 125], null],
  mount,
});

scoreboardpeg.code:
/**
 * Score dial: a round tabletop counter with a ring of twelve score notches
 * and a long arm turning on a centre knob. The pointer picks a notch by its
 * direction from the centre and the arm swings round to it; at rest the arm
 * points at three, bright. The slider is how far out the arm reaches.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 50, H = 10, N = 12, REST = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let len = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [0, 0, H + 11]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(R, 72), circ(R - 2, 72), 0, H));
  mk("path", { d: poly(circ(R - 14, 64).map((q) => P(q.u, q.v, H))), class: "nf lo" }, g);
  const ang = (k) => (k / N) * Math.PI * 2 - Math.PI / 2;
  let d = "";
  for (let k = 0; k < N; k++) { const a = ang(k), l = k % 3 === 0 ? 9 : 5; d += seg(P((R - 4) * Math.cos(a), (R - 4) * Math.sin(a), H), P((R - 4 - l) * Math.cos(a), (R - 4 - l) * Math.sin(a), H)); }
  mk("path", { d, class: "nf lo" }, g);
  const arm = mk("path", { class: "sil hi" }, g), armT = mk("path", { class: "nf lo" }, g);
  const knob = solid(g);
  put(knob, prism(P, front, circ(6, 24), circ(4.5, 24), H, H + 9));
  const tw = tween(ang(REST));
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const L = (R - 6) * len, c = Math.cos(a), s = Math.sin(a), q = (u, v, z = H + 2) => P(u * c - v * s, u * s + v * c, z);
    const sh = [[-16, -7], [L - 12, -6], [L, 0], [L - 12, 6], [-16, 7]];
    arm.setAttribute("d", poly(hull(sh.map(([u, v]) => q(u, v)).concat(sh.map(([u, v]) => q(u, v, H + 5))))));
    armT.setAttribute("d", poly(sh.map(([u, v]) => q(u * 0.86, v * 0.6, H + 5))));
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let act = -2;
  function setActive(k) {
    if (k === act) return;
    act = k;
    let target = ang(k < 0 ? REST : k), now = performance.now(), from = tval(tw, now);
    while (target - from > Math.PI) target -= Math.PI * 2;
    while (from - target > Math.PI) target += Math.PI * 2;
    tset(tw, target, now, 0);
    read.textContent = k < 0 ? "rest" : String(k === 0 ? N : k).padStart(2, "0");
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, H), r = Math.hypot(x, y);
      if (r > R + 6 || r < 4) return setActive(-1);
      setActive(((Math.round((Math.atan2(y, x) + Math.PI / 2) / (Math.PI * 2 / N)) % N) + N) % N);
    },
    leave: () => setActive(-1),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { len = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "scoreboardpeg",
