gobowl.code:
/**
 * Go bowl: a round wooden bowl of stones with a domed lid. The pointer over
 * the bowl lifts the lid clear and swings it aside, showing the stones; at
 * rest the lid sits ajar, bright. The slider is how far the lid lifts.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 40, H = 30, LR = 42;
const disc = (x, y, r, n = 48) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [-24, -40, H + 64], [0, 0, H + 20]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the bowl: a wide foot, a fuller belly, an open mouth
  const belly = [];
  for (const [r, z] of [[R * 0.72, 0], [R * 0.95, H * 0.35], [R, H * 0.6], [R * 0.9, H]]) belly.push(...ringAt(P, disc(0, 0, r), z));
  mk("path", { d: poly(hull(belly)), class: "sil" }, g);
  mk("path", { d: poly(ringAt(P, disc(0, 0, R * 0.9), H)), class: "lo" }, g);
  mk("path", { d: poly(ringAt(P, disc(0, 0, R * 0.78), H)), class: "nf lo" }, g);
  // the stones: a heap of small lenses inside the mouth
  for (const [x, y] of [[-14, -6], [-4, -16], [8, -10], [-10, 8], [4, 2], [16, 4], [-2, 14], [12, 16], [-20, -2]]) {
    const st = [];
    for (const [r, z] of [[5.5, 0], [4, 1.8]]) st.push(...ringAt(P, disc(x, y, r, 16), H - 3 + z));
    mk("path", { d: poly(hull(st)), class: "lo" }, g);
  }
  const lidG = mk("g", {}, g), lid = mk("path", { class: "sil" }, lidG), lidRim = mk("path", { class: "nf lo" }, lidG);
  const REST = 0.18, lift = tween(REST);
  let last = NaN;

  function draw(t) {
    if (t === last) return;
    last = t;
    const dx = -24 * t, dy = -40 * t, z0 = H + 2 + 34 * t, tilt = 0.35 * t, pts = [];
    const ring = (r, z) => disc(0, 0, r).map((q) => {
      const zz = z + q.v * Math.sin(tilt) * 0.6;
      return P(dx + q.u, dy + q.v * Math.cos(tilt), zz);
    });
    for (let i = 0; i <= 6; i++) { const a = (i / 6) * (Math.PI / 2); pts.push(...ring(LR * Math.cos(a), z0 + 11 * Math.sin(a))); }
    lid.setAttribute("d", poly(hull(pts)));
    lidRim.setAttribute("d", poly(ring(LR, z0 + 1.5)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);
  const mid = P(0, 0, H / 2);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(lift, on ? reach : REST, performance.now(), 0);
    lid.classList.toggle("hi", true);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setActive(Math.hypot((sx - mid[0]) / 1.4, sy - mid[1]) < 90),
    leave: () => setActive(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { tset(lift, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "gobowl",
  means: "A round Go bowl of stones: the pointer over it lifts the domed lid clear and swings it aside.",
  rules: [1, 4, 5, 8],
  range: [0.3, 0.8, 1],
  tour: [[200, 196], [176, 172], [228, 214], null],
  mount,
});

backgammon.code:
/**
 * Backgammon case: a flat wooden case hinged along its back edge, the board
 * inside laid out as two rows of long points. The pointer over the case
 * swings the lid up and back to open the board; at rest the lid stands ajar,
 * bright. The slider is how far the lid opens.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 104, D = 72, T = 8, LT = 7, REST = 24;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, -16, T + D + 2], [W, -16, T + D + 2]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const baseG = mk("g", {}, g);
  const [r0, i0] = rings(0, 0, W, D, 6, 1.8);
  put(solid(baseG), prism(P, front, r0, i0, 0, T));
  // the board: a rim, a bar down the middle and two rows of points
  const pts = (zf, tf) => {
    let d = "";
    const half = (x0) => {
      for (let k = 0; k < 6; k++) {
        const x = x0 + k * 7.6;
        d += open([tf(x, 5), tf(x + 3.8, 30), tf(x + 7.6, 5)]) + open([tf(x, D - 5), tf(x + 3.8, D - 30), tf(x + 7.6, D - 5)]);
      }
    };
    half(5); half(W / 2 + 2.4);
    return d;
  };
  mk("path", { d: poly(rrect(4, 4, W - 4, D - 4, 2, 2).map((q) => P(q.u, q.v, T))), class: "nf lo" }, baseG);
  mk("path", { d: pts(T, (x, y) => P(x, y, T)), class: "nf lo" }, baseG);
  mk("path", { d: poly([P(W / 2 - 2.4, 4, T), P(W / 2 + 2.4, 4, T), P(W / 2 + 2.4, D - 4, T), P(W / 2 - 2.4, D - 4, T)]), class: "nf lo" }, baseG);
  const lidG = mk("g", {}, g), lid = mk("path", { class: "sil hi" }, lidG), face = mk("path", { class: "nf lo" }, lidG), lpts = mk("path", { class: "nf lo" }, lidG);
  const tw = tween(REST);
  const outer = rrect(0, 0, W, D, 6, 6), inner = rrect(1.8, 1.8, W - 1.8, D - 1.8, 4.2, 6), board = rrect(4, 4, W - 4, D - 4, 2, 2);
  let last = NaN;

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = (deg * Math.PI) / 180, c = Math.cos(th), s = Math.sin(th);
    // the lid turns about the hinge line y = 0, z = T; zl = 0 is its board face
    const L = (x, y, zl) => P(x, y * c - zl * s, T + y * s + zl * c);
    const ring = (rg, zl) => rg.map((q) => L(q.u, q.v, zl));
    lid.setAttribute("d", poly(hull(ring(outer, 0).concat(ring(outer, LT)))));
    if (deg < 62) { face.setAttribute("d", poly(ring(inner, LT))); lpts.setAttribute("d", ""); }
    else { face.setAttribute("d", poly(ring(board, 0))); lpts.setAttribute("d", pts(0, (x, y) => L(x, y, 0))); }
    if (deg > 70) g.insertBefore(lidG, baseG); else g.appendChild(lidG);
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const mid = P(W / 2, D / 2, T);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? 100 * reach : REST, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setActive(Math.hypot((sx - mid[0]) / 1.6, sy - mid[1]) < 85),
    leave: () => setActive(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { tset(tw, 100 * v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "backgammon",
  means: "A backgammon case: the pointer swings the hinged lid up and back, opening the board of long points.",
  rules: [1, 4, 5, 6, 8],
  range: [0.6, 1, 1],
  tour: [[188, 234], [168, 205], [214, 262], null],
  mount,
});

wheelbalancer.code:
/**
 * Wheel balancer: a garage machine with a wheel on its shaft and a guard
 * hood above. The pointer on the figure swings the hood down over the tyre
 * and spins the wheel with the pointer's x; leaving lifts the hood back. At
 * rest the hood stands raised, bright. The slider is how far the wheel spins.
 *
 * The pattern: one part answering a continuous input (spring).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WX = 60, WY = 16, WZ = 34, R = 24, W0 = 52, W1 = 66, HR = 30, HOPEN = 0.5 * Math.PI;
const ring = (x, R0, n = 36, a0 = 0, a1 = 2 * Math.PI) => {
  const o = [];
  for (let i = 0; i <= n; i++) { const t = a0 + ((a1 - a0) * i) / n; o.push([x, WY + R0 * Math.cos(t), WZ + R0 * Math.sin(t)]); }
  return o;
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let span = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[0, -16, 0], [44, 34, 0], [W1 + 4, WY + HR, 0], [W1 + 4, WY - HR, WZ + HR], [0, -16, WZ + HR], [W1, WY, WZ + HR]], 200, 160);
  const P = proj(C), front = facing(C);
  const pr = (pts) => pts.map((q) => P(q[0], q[1], q[2]));
  const g = mk("g", {}, svg);
  // floor plate and cabinet
  const [fr, fi] = rings(-4, -16, W1 + 6, 36, 4, 1.5);
  put(solid(g), prism(P, front, fr, fi, 0, 2));
  const [br, bi] = rings(0, -4, 42, 34, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, 2, 30));
  const hoodG = mk("g", {}, g);
  const hood = mk("path", { class: "sil hi" }, hoodG), hoodIn = mk("path", { class: "nf lo" }, hoodG);
  const wheelG = mk("g", {}, g);
  mk("path", { d: poly(hull(pr([[42, WY - 3, WZ], [42, WY + 3, WZ], [W0, WY - 3, WZ], [W0, WY + 3, WZ], [42, WY, WZ - 3], [42, WY, WZ + 3], [W0, WY, WZ + 3], [W0, WY, WZ - 3]]))) }, wheelG);
  mk("path", { d: poly(hull(pr(ring(W0, R).concat(ring(W1, R))))), class: "sil" }, wheelG);
  mk("path", { d: poly(pr(ring(W1, R))) }, wheelG);
  mk("path", { d: poly(pr(ring(W1, R - 7))), class: "nf lo" }, wheelG);
  const spokes = mk("path", { class: "nf" }, wheelG);
  mk("path", { d: poly(pr(ring(W1 + 1, 4, 16))) }, wheelG);

  const h = spring(HOPEN, { k: 70, c: 15 }), a = spring(0.3, { k: 60, c: 14 });
  let lh = NaN, la = NaN, behind = null;
  function draw() {
    if (h.x !== lh) {
      lh = h.x;
      const o = ring(W0 - 2, HR, 24, h.x, h.x + Math.PI).concat(ring(W1 + 3, HR, 24, h.x, h.x + Math.PI));
      hood.setAttribute("d", poly(hull(pr(o))));
      hoodIn.setAttribute("d", poly(pr(ring(W1 + 3, HR - 3, 24, h.x, h.x + Math.PI))));
      const b = h.x > 0.3 * Math.PI;
      if (b !== behind) { behind = b; if (b) wheelG.before(hoodG); else wheelG.after(hoodG); }
    }
    if (a.x !== la) {
      la = a.x;
      let d = "";
      for (let k = 0; k < 5; k++) {
        const t = a.x + (k * 2 * Math.PI) / 5, c = Math.cos(t), s = Math.sin(t);
        d += seg(P(W1, WY + 4 * c, WZ + 4 * s), P(W1, WY + (R - 7) * c, WZ + (R - 7) * s));
      }
      spokes.setAttribute("d", d);
    }
  }
  const B = register(stage, (dt) => {
    const m1 = stepS(h, dt), m2 = stepS(a, dt);
    draw();
    return m1 || m2;
  });
  bag.add(B.unregister);
  draw();
  read.textContent = "rest";

  const mid = P(30, 16, 20);
  function move([sx, sy]) {
    const on = Math.abs(sx - mid[0]) < 150 && Math.abs(sy - mid[1]) < 130;
    if (!on) return leave();
    h.t = 0.02;
    const f = clamp((sx - mid[0] + 150) / 300, 0, 1);
    a.t = 0.3 + f * (span * Math.PI) / 180;
    read.textContent = Math.round(f * span) + "°";
    B.wake();
  }
  function leave() { h.t = HOPEN; a.t = 0.3; read.textContent = "rest"; B.wake(); }
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { span = v; }, destroy: bag.dispose };
}

hairline({
  name: "wheelbalancer",
  means: "A wheel balancer: the pointer swings the guard hood down over the tyre and spins the wheel; leaving lifts the hood.",
  rules: [1, 3, 5, 6],
  range: [90, 360, 720],
  tour: [[205, 131], [162, 206], [122, 116], null],
  mount,
});

bearingpuller.code:
/**
 * Gear puller: a two-jaw puller hooked under a gear on a shaft. The pointer's
 * height turns the T-handle, and the forcing screw draws the yoke, jaws and
 * gear up the shaft. Leaving lets it settle back. At rest the handle is
 * bright. The slider is how far the gear can be pulled.
 *
 * The pattern: one part answering a continuous input (spring).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, spring, stepS, clamp, circ,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GZ = 16, GT = 6, YZ = 52, TOP = 100, JX = 25;
const disc = (r, n = 28) => circ(r, n).map((q) => ({ ...q }));
const cyl = (r, z0, z1) => { const o = []; for (let i = 0; i < 24; i++) { const t = (i / 24) * 2 * Math.PI; o.push([r * Math.cos(t), r * Math.sin(t), z0], [r * Math.cos(t), r * Math.sin(t), z1]); } return o; };
const box = (x0, y0, z0, x1, y1, z1, a = 0) => {
  const o = [], c = Math.cos(a), s = Math.sin(a);
  for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x * c - y * s, x * s + y * c, z]);
  return o;
};
const teeth = (z) => { const o = []; for (let i = 0; i < 64; i++) { const t = (i / 64) * 2 * Math.PI, r = i % 4 < 2 ? 22 : 19; o.push([r * Math.cos(t), r * Math.sin(t), z]); } return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxL = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-30, -30, 0], [30, 30, 0], [-30, 30, 0], [30, -30, 0], [0, 0, TOP + 4], [-JX - 4, 0, YZ + 34], [JX + 4, 0, YZ + 34], [17, 17, TOP], [-17, -17, TOP]], 200, 162);
  const P = proj(C), front = facing(C);
  const pr = (pts) => pts.map((q) => P(q[0], q[1], q[2]));
  const H = (pts) => poly(hull(pr(pts)));
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-30, -30, 30, 30, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  const farJaw = mk("path", { class: "sil" }, g);
  put(solid(g), prism(P, front, disc(6), disc(4.5), 5, 34));
  const gear = mk("path", { class: "sil" }, g), gearTop = mk("path", { class: "nf" }, g), bore = mk("path", { class: "nf lo" }, g);
  const lowScrew = mk("path", {}, g);
  const nearJaw = mk("path", { class: "sil" }, g), yoke = mk("path", { class: "sil" }, g);
  mk("path", { d: H(cyl(2.8, YZ, TOP - 2)) }, g);
  const handle = mk("path", { class: "sil hi" }, g);
  mk("path", { d: H(cyl(4, TOP - 5, TOP + 2)) }, g);

  const L = spring(3, { k: 60, c: 14 });
  let last = NaN;
  function draw() {
    if (L.x === last) return;
    last = L.x;
    const l = L.x, gz = GZ + l, yz = YZ + l;
    const jaw = (sx) => H(box(sx * JX - 3, -3, gz - 4, sx * JX + 3, 3, yz + 4).concat(box(sx * 17, -3, gz - 4, sx * JX, 3, gz - 1)));
    farJaw.setAttribute("d", jaw(-1));
    nearJaw.setAttribute("d", jaw(1));
    gear.setAttribute("d", H(teeth(gz).concat(teeth(gz + GT))));
    gearTop.setAttribute("d", poly(pr(teeth(gz + GT))));
    bore.setAttribute("d", poly(pr(cyl(6.5, gz + GT, gz + GT).filter((_, i) => i % 2 === 0))));
    lowScrew.setAttribute("d", H(cyl(2.8, 34, yz)));
    yoke.setAttribute("d", H(box(-JX - 5, -5, yz, JX + 5, 5, yz + 7)));
    handle.setAttribute("d", H(box(-18, -1.6, TOP - 3, 18, 1.6, TOP, 0.6 + l * 0.22)));
  }
  const B = register(stage, (dt) => { const m = stepS(L, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  read.textContent = "rest";

  const base = P(0, 0, 0);
  function move([sx, sy]) {
    const f = clamp((base[1] - sy) / 200, 0, 1);
    L.t = 3 + f * (maxL - 3);
    read.textContent = Math.round(L.t) + "mm";
    B.wake();
  }
  function leave() { L.t = 3; read.textContent = "rest"; B.wake(); }
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxL = v; }, destroy: bag.dispose };
}

hairline({
  name: "bearingpuller",
  means: "A gear puller on a shaft: the pointer turns the screw's T-handle and the jaws draw the gear up the shaft.",
  rules: [1, 3, 5, 6],
  range: [12, 24, 30],
  tour: [[200, 69], [200, 237], [200, 150], null],
  mount,
});

snowmaker.code:
/**
 * Snow cannon: a fan drum on a column over a wheeled base. The pointer aims
 * it: its height tilts the drum up, its side pans it. Leaving lowers it to
 * a rest aim. At rest the drum's mouth is bright. The slider is how far the
 * drum may tilt.
 *
 * The pattern: one part aiming at the pointer (spring).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, spring, stepS, clamp, rad, circ,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 24, PY = 24, PZ = 40, R = 14, BK = 16, FW = 26;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
function frame(yaw, el) {
  const d = [Math.cos(el) * Math.cos(yaw), Math.cos(el) * Math.sin(yaw), Math.sin(el)];
  const u = [-Math.sin(yaw), Math.cos(yaw), 0];
  const v = [d[1] * u[2] - d[2] * u[1], d[2] * u[0] - d[0] * u[2], d[0] * u[1] - d[1] * u[0]];
  return { d, u, v };
}
function circle(f, s, r, n = 32) {
  const o = [];
  for (let i = 0; i < n; i++) {
    const t = (i / n) * 2 * Math.PI, c = Math.cos(t) * r, q = Math.sin(t) * r;
    o.push([PX + f.d[0] * s + f.u[0] * c + f.v[0] * q, PY + f.d[1] * s + f.u[1] * c + f.v[1] * q, PZ + f.d[2] * s + f.u[2] * c + f.v[2] * q]);
  }
  return o;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxEl = value;
  const C = Cam(45, 0.5, 2.85);
  const ext = [[0, 0, 0], [48, 48, 0], [0, 48, 0], [48, 0, 0]];
  for (const yw of [0, 45, 90]) for (const e of [0, 80]) ext.push(...circle(frame(rad(yw), rad(e)), FW, R, 8), ...circle(frame(rad(yw), rad(e)), -BK, R, 8));
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const pr = (pts) => pts.map((q) => P(q[0], q[1], q[2]));
  const g = mk("g", {}, svg);
  const [br, bi] = rings(2, 2, 46, 46, 6, 2);
  put(solid(g), prism(P, front, br, bi, 3, 9));
  for (const [wx, wy] of [[6, 46], [46, 6], [44, 44]]) put(solid(g), prism(P, front, disc(wx, wy, 4), disc(wx, wy, 2.5), 0, 4));
  put(solid(g), prism(P, front, disc(PX, PY, 4), disc(PX, PY, 2.5), 9, PZ));
  const drumG = mk("g", {}, g);
  const drum = mk("path", { class: "sil" }, drumG), mouth = mk("path", { class: "sil hi" }, drumG);
  const lip = mk("path", { class: "nf lo" }, drumG), grille = mk("path", { class: "nf" }, drumG);

  const yaw = spring(rad(45), { k: 70, c: 15 }), el = spring(rad(18), { k: 70, c: 15 });
  let ly = NaN, le = NaN;
  function draw() {
    if (yaw.x === ly && el.x === le) return;
    ly = yaw.x; le = el.x;
    const f = frame(yaw.x, el.x);
    const fr = circle(f, FW, R), bk = circle(f, -BK, R);
    drum.setAttribute("d", poly(hull(pr(fr.concat(bk)))));
    mouth.setAttribute("d", poly(pr(fr)));
    lip.setAttribute("d", poly(pr(circle(f, FW - 3, R - 3))));
    const hub = circle(f, FW - 3, 2.5, 6), rim = circle(f, FW - 3, R - 3, 6);
    let d = poly(pr(hub));
    for (let k = 0; k < 6; k++) d += seg(P(...hub[k]), P(...rim[k]));
    grille.setAttribute("d", d);
  }
  const B = register(stage, (dt) => {
    const m = stepS(yaw, dt) | stepS(el, dt);
    draw();
    return !!m;
  });
  bag.add(B.unregister);
  draw();
  read.textContent = "rest";

  const piv = P(PX, PY, PZ);
  function move([sx, sy]) {
    const fx = clamp((sx - piv[0] + 160) / 320, 0, 1), fy = clamp((piv[1] + 40 - sy) / 160, 0, 1);
    yaw.t = rad(90 - 90 * fx);
    el.t = rad(maxEl * fy);
    read.textContent = Math.round(maxEl * fy) + "°";
    B.wake();
  }
  function leave() { yaw.t = rad(45); el.t = rad(18); read.textContent = "rest"; B.wake(); }
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxEl = v; }, destroy: bag.dispose };
}

hairline({
  name: "snowmaker",
  means: "A snow cannon on its stand: the pointer tilts the fan drum up and pans it to aim; leaving lowers it back.",
  rules: [1, 3, 5],
  range: [30, 60, 80],
  tour: [[200, 29], [103, 227], [297, 29], null],
  mount,
});

curlbroom.code:
/**
 * Ice scraper: a windscreen pane lying under frost, and a hand scraper on
 * it. The pointer's side slides the scraper along the glass; the frost is
 * gone wherever the blade has passed. Leaving sends it back to a half-cleared
 * rest. At rest the blade is bright. The slider is the blade's width.
 *
 * The pattern: one part answering a continuous input (spring).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GX = 120, GY = 64, GZ = 4, REST = 45;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let bw = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [GX, GY, 0], [GX, 0, 0], [0, GY, 0], [-30, GY / 2, 40], [GX - 30, GY / 2, 40]], 200, 165);
  const P = proj(C), front = facing(C);
  const pr = (pts) => pts.map((q) => P(q[0], q[1], q[2]));
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(0, 0, GX, GY, 10, 3);
  put(solid(g), prism(P, front, gr, gi, 0, GZ));
  const frost = mk("path", { class: "nf lo" }, g);
  const handle = mk("path", { class: "sil" }, g), blade = mk("path", { class: "sil hi" }, g), edge = mk("path", { class: "nf" }, g);
  const marks = [];
  for (let i = 0; i < 26; i++) for (let j = 0; j < 9; j++) {
    const x = 8 + i * 4.2 + ((j * 7) % 3), y = 8 + j * 6 + ((i * 5) % 3);
    marks.push([x, y]);
  }
  const X = spring(REST, { k: 60, c: 14 });
  let last = NaN, lw = NaN;
  function draw() {
    if (X.x === last && bw === lw) return;
    last = X.x; lw = bw;
    const x = X.x, y0 = GY / 2 - bw / 2, y1 = GY / 2 + bw / 2;
    let d = "";
    for (const [mx, my] of marks) if (mx > x + 3 || my < y0 - 1 || my > y1 + 1) d += seg(P(mx, my, GZ), P(mx + 2, my - 1.2, GZ));
    frost.setAttribute("d", d);
    const bl = [];
    for (const y of [y0, y1]) bl.push([x, y, GZ], [x + 3, y, GZ], [x - 6, y, GZ + 10], [x - 9, y, GZ + 10]);
    blade.setAttribute("d", poly(hull(pr(bl))));
    edge.setAttribute("d", seg(P(x + 1.5, y0, GZ + 0.5), P(x + 1.5, y1, GZ + 0.5)));
    const hd = [];
    for (const y of [GY / 2 - 3, GY / 2 + 3]) hd.push([x - 6, y, GZ + 8], [x - 8, y, GZ + 13], [x - 34, y, GZ + 34], [x - 37, y, GZ + 30]);
    handle.setAttribute("d", poly(hull(pr(hd))));
  }
  const B = register(stage, (dt) => { const m = stepS(X, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  read.textContent = "rest";

  const a = P(0, GY / 2, 0), b = P(GX, GY / 2, 0);
  function move([sx]) {
    const f = clamp((sx - a[0]) / (b[0] - a[0]), 0, 1);
    X.t = 12 + f * (GX - 18);
    read.textContent = Math.round(f * 100) + "%";
    B.wake();
  }
  function leave() { X.t = REST; read.textContent = "rest"; B.wake(); }
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { bw = v; B.wake(); last = NaN; draw(); }, destroy: bag.dispose };
}

