  name: "curlbroom",
  means: "A windscreen ice scraper: the pointer slides the blade along the frosted glass, clearing the frost behind it.",
  rules: [1, 3, 5],
  range: [24, 40, 56],
  tour: [[269, 226], [117, 150], [283, 233], null],
  mount,
});

skijump.code:
/**
 * Ski binding: a length of ski with its binding, the toe piece forward and
 * the heel piece behind on its long release lever. The pointer works the
 * heel: it flips up about its hinge on a spring, the lever rising nearly
 * upright, and goes bright. At rest the toe piece is bright.
 * The slider is how far the heel flips.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SK = 4, XH = 16, ZH = SK + 4, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-70, -14, 0], [80, 14, 0], [-70, 14, 0], [80, -14, 0], [30, 0, 70], [70, 0, 50]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-70, -11, 80, 11, 10, 2);
  put(solid(g), prism(P, front, sr, si, 0, SK));
  const [pr, pi] = rings(-50, -8, 50, 8, 3, 1.4);
  put(solid(g), prism(P, front, pr, pi, SK, SK + 2));
  const [tr, ti] = rings(-48, -10, -26, 10, 6, 2);
  const toe = solid(g);
  put(toe, prism(P, front, tr, ti, SK + 2, SK + 16));
  const heel = mk("path", { class: "sil" }, g), cup = mk("path", { class: "nf lo" }, g), lever = mk("path", { class: "sil" }, g);
  const sw = spring(REST);
  let last = NaN;
  const box = (x0, x1, y0, y1, z0, z1) => {
    const out = [];
    for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) out.push([x, y, z]);
    return out;
  };

  function draw() {
    const a = rad(sw.x);
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const T = ([x, y, z]) => { const dx = x - XH, dz = z - ZH; return P(XH + dx * c - dz * s, y, ZH + dx * s + dz * c); };
    heel.setAttribute("d", poly(hull(box(16, 44, -10, 10, SK + 2, SK + 18).map(T))));
    cup.setAttribute("d", poly([[17, -7, SK + 15], [17, 7, SK + 15], [24, 7, SK + 17], [24, -7, SK + 17]].map(T)));
    lever.setAttribute("d", poly(hull(box(36, 72, -5, 5, SK + 18, SK + 22).map(T))));
  }
  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(); return m; });
  bag.add(B.unregister);

  const mid = P(20, 0, 10);
  function setOver(p) {
    const on = !!p && Math.hypot(p[0] - mid[0], p[1] - mid[1]) < 160;
    sw.t = on ? reach : REST;
    toe.sil.classList.toggle("hi", !on);
    lever.classList.toggle("hi", on);
    read.textContent = on ? "heel" : "rest";
    B.wake();
  }
  setOver(null);
  bag.add(pointer(stage, { move: setOver, leave: () => setOver(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "skijump",
  means: "A ski binding on a length of ski: the heel piece flips up on its hinge and the release lever rises.",
  rules: [3, 4, 5, 8],
  range: [30, 60, 75],
  tour: [[253, 181], [120, 150], [300, 230], null],
  mount,
});

rainchain.code:
/**
 * Rain chain: a run of cups hung on links from a gutter, down to a stone
 * basin. The pointer pushes the chain: it swings toward the pointer's side
 * on a spring, the lower cups whipping further. The cup nearest the pointer
 * is bright; at rest the chain leans a little and the bottom cup is bright.
 * The slider is how far the chain may swing.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, rad, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 6, GAP = 17, TOP = 120, R1 = 7, R0 = 4.2, CH = 8, REST = 6;
const U = [Math.SQRT1_2, -Math.SQRT1_2];
const disc = (r, n = 24) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-56, -8, TOP + 8], [56, 8, TOP + 8], [-56, 8, 0], [56, -8, 0], [-30, 30, 10], [30, -30, 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the basin on the ground
  put(solid(g), prism(P, front, circ(16, 40), circ(13, 40), 0, 7));
  // the gutter
  const [gr, gi] = rings(-54, -7, 54, 7, 4, 1.6);
  put(solid(g), prism(P, front, gr, gi, TOP, TOP + 9));
  const links = mk("path", { class: "nf lo" }, g);
  const cups = [];
  for (let i = 0; i < N; i++) {
    const s = solid(g);
    cups.push({ i, s, last: "" });
  }
  const sw = spring(REST);
  let over = -1;

  function pos(i, a) {
    const d = GAP * (i + 1), w = 1 + 0.06 * i, t = rad(a * w);
    const off = Math.sin(t) * d, z = TOP - Math.cos(t) * d;
    return [U[0] * off, U[1] * off, z];
  }
  function cupPaths(c, i) {
    const ring = (r, z) => ringAt(P, disc(r).map((q) => ({ ...q, u: q.u + c[0], v: q.v + c[1] })), z);
    const top = ring(R1, c[2] + CH / 2), bot = ring(R0, c[2] - CH / 2);
    return { sil: poly(hull(top.concat(bot))), crease: poly(ring(R1 - 1.6, c[2] + CH / 2 - 0.6)) };
  }
  let lastA = NaN;
  function draw() {
    const a = sw.x;
    if (a === lastA) return;
    lastA = a;
    let d = "", prev = [0, 0, TOP];
    for (const cu of cups) {
      const c = pos(cu.i, a);
      put(cu.s, cupPaths(c, cu.i));
      d += seg(P(...prev), P(c[0], c[1], c[2] + CH / 2));
      prev = [c[0], c[1], c[2] - CH / 2];
    }
    d += seg(P(...prev), P(prev[0] * 0.5, prev[1] * 0.5, 7));
    links.setAttribute("d", d);
  }
  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(); return m; });
  bag.add(B.unregister);

  const top = P(0, 0, TOP), rests = cups.map((cu) => P(...pos(cu.i, 0)));
  function setOver(p) {
    if (!p) { over = -1; sw.t = REST; }
    else {
      let best = 0, bd = Infinity;
      rests.forEach((m, k) => { const dd = Math.abs(m[1] - p[1]); if (dd < bd) { bd = dd; best = k; } });
      over = best;
      sw.t = clamp((p[0] - top[0]) / 90, -1, 1) * reach;
    }
    const hiK = over < 0 ? N - 1 : over;
    cups.forEach((cu, k) => cu.s.sil.classList.toggle("hi", k === hiK));
    read.textContent = over < 0 ? "rest" : "cup " + (over + 1);
    B.wake();
  }
  setOver(null);
  bag.add(pointer(stage, { move: setOver, leave: () => setOver(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "rainchain",
  means: "Cups hung on links from a gutter to a basin: the chain swings toward the pointer, lower cups whipping further.",
  rules: [1, 3, 5, 8],
  range: [10, 32, 45],
  tour: [[307, 221], [110, 200], [270, 150], null],
  mount,
});

thermostat.code:
/**
 * Dial thermostat: a round dial on a square plate on the wall, its cover
 * hinged at one side over the coil. The pointer draws the cover open on a
 * spring, wider the nearer it comes, to show the spiral coil inside; the coil
 * goes bright. At rest the cover sits shut with its setting tab bright.
 * The slider is how far the cover may open.
 */
const {
  Cam, clamp, fit, hull, poly, open, proj, rad, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const R = 30, YC = 0, ZC = 50, X0 = 3, X1 = 7, X2 = 18, YH = R + 2, REST = 4, N = 40;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, -44, 6], [0, 44, 6], [0, -44, 94], [0, 44, 94], [X2 + 2 * R, YH, ZC], [X2, -R, ZC]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  // a disc of samples in the wall's plane (y, z), at depth x
  const ring = (r, x, y0 = YC, z0 = ZC, n = N) => Array.from({ length: n }, (_, i) => {
    const t = (i / n) * Math.PI * 2;
    return [x, y0 + r * Math.cos(t), z0 + r * Math.sin(t)];
  });
  const pr = (pts) => pts.map((q) => P(...q));
  const slab = (pts0, pts1) => poly(hull(pr(pts0).concat(pr(pts1))));
  // the back plate: a rounded square standing on the wall
  const sq = (h, x, rr) => {
    const out = [];
    for (const [cy, cz, a0] of [[h - rr, h - rr, 0], [-h + rr, h - rr, 90], [-h + rr, -h + rr, 180], [h - rr, -h + rr, 270]])
      for (let i = 0; i <= 4; i++) { const t = rad(a0 + i * 22.5); out.push([x, YC + cy + rr * Math.cos(t), ZC + cz + rr * Math.sin(t)]); }
    return out;
  };
  mk("path", { class: "sil", d: slab(sq(42, 0, 8), sq(42, X0, 8)) }, g);
  mk("path", { class: "nf lo", d: poly(pr(sq(40, X0, 7))) }, g);
  mk("path", { class: "sil", d: slab(ring(R, X0), ring(R, X1)) }, g);
  // the coil: a spiral on the base's face
  const sp = [];
  for (let i = 0; i <= 120; i++) { const t = (i / 120) * Math.PI * 7, r = 3 + (i / 120) * (R - 8); sp.push([X1, YC + r * Math.cos(t), ZC + r * Math.sin(t)]); }
  const coil = mk("path", { class: "nf", d: open(pr(sp)) }, g);
  const cover = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g), tab = mk("path", { class: "sil" }, g);
  const sw = spring(REST);
  let last = NaN;

  function draw() {
    const a = rad(sw.x);
    if (a === last) return;
    last = a;
    const ca = Math.cos(a), sa = Math.sin(a);
    const T = ([x, y, z]) => { const dx = x - X1, dy = y - YH; return [X1 + dx * ca - dy * sa, YH + dy * ca + dx * sa, z]; };
    const back = ring(R, X1 + 0.4).map(T), fr = ring(R, X2).map(T);
    cover.setAttribute("d", poly(hull(pr(back).concat(pr(fr)))));
    face.setAttribute("d", poly(pr(ring(R - 3, X2).map(T))));
    const tb = [[X2, -4, ZC + R - 2], [X2, 4, ZC + R - 2], [X2, 4, ZC + R + 7], [X2, -4, ZC + R + 7]];
    tab.setAttribute("d", slab(tb.map(T), tb.map((q) => T([q[0] - 5, q[1], q[2]]))));
  }
  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(); return m; });
  bag.add(B.unregister);

  const mid = P(X2, YC, ZC);
  function setOver(p) {
    let on = false;
    if (p) {
      const d = Math.hypot(p[0] - mid[0], p[1] - mid[1]);
      on = d < 150;
      sw.t = on ? reach * clamp(1.25 - d / 150, 0.45, 1) : REST;
    } else sw.t = REST;
    tab.classList.toggle("hi", !on);
    coil.classList.toggle("hi", on);
    read.textContent = on ? Math.round(sw.t) + "°" : "rest";
    B.wake();
  }
  setOver(null);
  bag.add(pointer(stage, { move: setOver, leave: () => setOver(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "thermostat",
  means: "A round dial thermostat on a wall plate: its cover swings open toward the pointer to show the spiral coil inside.",
  rules: [3, 4, 5, 8],
  range: [40, 75, 100],
  tour: [[227, 181], [160, 235], [275, 120], null],
  mount,
});

cookiecutter.code:
/**
 * Cookie press: a barrel press standing on a baking sheet, plunger rod on
 * top, pistol grip and trigger at its side. The pointer squeezes: the
 * trigger pulls in and the press lifts clear on a spring, leaving the fresh
 * cookie under its nozzle bright. At rest the trigger is bright.
 * The slider is how high the press lifts.
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 3, NZ = 10, TOPZ = 70, REST = 4;
const at = (ring, x, y) => ring.map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-40, -40, 0], [40, 40, 0], [40, -40, 0], [-40, 40, 0], [0, 0, TOPZ + 34 + 40], [34, 0, TOPZ + 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(-40, -40, 40, 40, 6, 2);
  put(solid(g), prism(P, front, tr, ti, 0, BZ));
  let fresh;
  for (const [x, y] of [[-24, -22], [22, -24], [0, 0], [-24, 20]]) {
    const s = solid(g);
    put(s, prism(P, front, at(circ(8, 24), x, y), at(circ(5, 24), x, y), BZ, BZ + 3));
    if (!x && !y) fresh = s;
  }
  const parts = [
    { ring: at(circ(1.8, 12), 0, 0), inner: at(circ(1, 12), 0, 0), z0: TOPZ + 4, z1: TOPZ + 34 },
    { ring: at(circ(6, 24), 0, 0), inner: at(circ(4.5, 24), 0, 0), z0: TOPZ + 34, z1: TOPZ + 37 },
    { ring: at(circ(5, 20), 0, 0), inner: at(circ(3.5, 20), 0, 0), z0: NZ, z1: NZ + 8 },
    { ring: at(circ(13, 40), 0, 0), inner: at(circ(11, 40), 0, 0), z0: NZ + 8, z1: TOPZ },
    { ring: at(circ(15, 40), 0, 0), inner: at(circ(13, 40), 0, 0), z0: TOPZ, z1: TOPZ + 5 },
    { ring: rings(8, -4, 36, 4, 3, 1.2)[0], inner: rings(8, -4, 36, 4, 3, 1.2)[1], z0: TOPZ - 6, z1: TOPZ + 2 },
    { trig: true, z0: TOPZ - 28, z1: TOPZ - 6 },
    { ring: rings(30, -4.5, 38, 4.5, 3, 1.2)[0], inner: rings(30, -4.5, 38, 4.5, 3, 1.2)[1], z0: TOPZ - 36, z1: TOPZ - 6 },
  ].map((p) => ({ ...p, s: solid(g) }));
  const trig = parts.find((p) => p.trig);
  const sw = spring(REST);
  let last = NaN;

  function draw() {
    const L = sw.x;
    if (L === last) return;
    last = L;
    const pull = Math.min(1, L / 24) * 7;
    for (const p of parts) {
      if (p.trig) {
        const [r, i] = rings(16 + pull, -3, 22 + pull, 3, 2.5, 1);
        put(p.s, prism(P, front, r, i, p.z0 + L, p.z1 + L));
      } else put(p.s, prism(P, front, p.ring, p.inner, p.z0 + L, p.z1 + L));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(); return m; });
  bag.add(B.unregister);

  const mid = P(10, 0, 40);
  function setOver(p) {
    const on = !!p && Math.hypot(p[0] - mid[0], p[1] - mid[1]) < 150;
    sw.t = on ? reach : REST;
    trig.s.sil.classList.toggle("hi", !on);
    fresh.sil.classList.toggle("hi", on);
    read.textContent = on ? "press" : "rest";
    B.wake();
  }
  setOver(null);
  bag.add(pointer(stage, { move: setOver, leave: () => setOver(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "cookiecutter",
  means: "A cookie press on a baking sheet: its trigger pulls and the press lifts clear, leaving a fresh cookie under the nozzle.",
  rules: [3, 4, 5, 8],
  range: [16, 32, 40],
  tour: [[200, 192], [110, 250], [290, 150], null],
  mount,
});

valet.code:
/**
 * Valet stand: a round foot, a pole, a shoulder board on top and a trouser
 * bar under it. The pointer turns the top: board and bar swivel on the pole
 * to face it, on a spring. At rest the top stands turned a little, the
 * shoulder board bright. The slider is how quickly it follows.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rad, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 112, HW = 46, BAR = 68, BL = 34, REST = -38;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-HW, -HW, 0], [HW, HW, 0], [HW, -HW, 0], [-HW, HW, 0], [0, 0, H + 18]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(30, 48), circ(27.5, 48), 0, 4));
  put(solid(g), prism(P, front, circ(2.4, 16), circ(1.4, 16), 4, H));
  const bar = mk("path", { class: "sil" }, g), board = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g);
  const sw = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  // the board's outline: a flat bottom and an arched shoulder line, convex
  const outline = [];
  for (let i = 0; i <= 16; i++) { const t = i / 16, x = -HW + 2 * HW * t; outline.push([x, H + 4 + 12 * Math.sin(Math.PI * t) ** 0.6]); }
  outline.push([HW - 2, H], [-HW + 2, H]);
  let last = NaN;

  function draw() {
    const th = rad(sw.x);
    if (th === last) return;
    last = th;
    const c = Math.cos(th), s = Math.sin(th);
    const W = (lx, ly, lz) => P(lx * c - ly * s, lx * s + ly * c, lz);
    const fr = outline.map(([x, z]) => W(x, 3, z)), bk = outline.map(([x, z]) => W(x, -3, z));
    board.setAttribute("d", poly(hull(fr.concat(bk))));
    face.setAttribute("d", poly(outline.map(([x, z]) => W(x * 0.9, 3, H + (z - H) * 0.8 + 1.4))));
    const rod = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2, ly = 5 + 2.2 * Math.cos(t), lz = BAR + 2.2 * Math.sin(t); rod.push(W(-BL, ly, lz), W(BL, ly, lz)); }
    bar.setAttribute("d", poly(hull(rod)));
  }
  const B = register(stage, (dt) => { const m = stepS(sw, dt); draw(); return m; });
  bag.add(B.unregister);

  function setOver(p) {
    let on = false;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      on = r > 4 && r < 140;
      if (on) {
        let t = (Math.atan2(y, x) * 180) / Math.PI - 90;
        while (t - sw.t > 90) t -= 180;
        while (t - sw.t < -90) t += 180;
        sw.t = t;
      }
    }
    if (!on) sw.t = REST;
    board.classList.toggle("hi", true);
    read.textContent = on ? (((Math.round(sw.t) % 180) + 180) % 180) + "°" : "rest";
    B.wake();
  }
  setOver(null);
  bag.add(pointer(stage, { move: setOver, leave: () => setOver(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sw.k = 100 * v; sw.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

