  name: "cymbal",
  means: "A hi-hat stand: over it, the foot pedal presses down and the top cymbal drops to close onto the bottom one.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[200, 146], [170, 110], [228, 200], null],
  mount,
});

tuningpeg.code:
/**
 * Ukulele: a small four-string ukulele lying on its back, pegs on the
 * headstock. The pointer over it lifts the neck: the ukulele tips up on its
 * tail as if picked up to tune. At rest the pegs are bright; when the
 * pointer plays, the body is. The slider is how far the neck lifts.
 *
 * The pattern: one part turning about a hinge (tilt).
 */
const { Cam, circ, fit, hull, poly, proj, rad, open, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const RL = 26, RU = 19, XU = 32, TH = 10, TAIL = -RL, REST = 20;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[RL, -RL, 0], [RL, RL, 0], [-96, 0, 0], [0, RL, 0], [-XU, -RU, 0], [-16, 0, 120], [-92, 0, 48]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const upper = mk("path", { class: "sil" }, g), lower = mk("path", { class: "sil" }, g), hole = mk("path", { class: "nf lo" }, g);
  const bridge = mk("path", { class: "nf" }, g);
  const neck = mk("path", { class: "nf" }, g), head = mk("path", { class: "nf" }, g), strings = mk("path", { class: "nf lo" }, g);
  const pegs = Array.from({ length: 4 }, () => mk("path", { class: "nf" }, g));

  let W = (p) => p;
  const disc = (x, r, z, n = 36) => circ(r, n).map((q) => W([x + q.u, q.v, z]));
  const box = (x0, x1, y0, y1, z0, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push(W([x, y, z])); return poly(hull(o)); };
  const tw = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const f = rad(deg), c = Math.cos(f), s = Math.sin(f);
    W = ([x, y, z]) => { const dx = x - TAIL; return P(-(TAIL + dx * c - z * s), y, z * c + dx * s); };
    lower.setAttribute("d", poly(hull(disc(0, RL, 0).concat(disc(0, RL, TH)))));
    upper.setAttribute("d", poly(hull(disc(XU, RU, 0).concat(disc(XU, RU, TH)))));
    hole.setAttribute("d", poly(disc(XU - 2, 7, TH)));
    bridge.setAttribute("d", box(-8, -4, -9, 9, TH, TH + 1.5));
    neck.setAttribute("d", box(XU + 14, 82, -4, 4, TH - 4, TH));
    head.setAttribute("d", box(82, 98, -6.5, 6.5, TH - 5, TH - 1));
    strings.setAttribute("d", [-3, -1, 1, 3].map((y) => open([W([-6, y * 1.3, TH + 1.5]), W([84, y, TH])])).join(" "));
    pegs.forEach((el, k) => {
      const x = 86 + (k % 2) * 7, y = k < 2 ? -6.5 : 6.5, d = k < 2 ? -5 : 5;
      el.setAttribute("d", poly(hull(circ(2.4, 12).map((q) => W([x + q.u, y, TH - 3 + q.v])).concat(circ(2.4, 12).map((q) => W([x + q.u, y + d, TH - 3 + q.v]))))));
    });
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(-10, 0, 30);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? REST + 45 * amp : REST, performance.now(), 0);
    lower.classList.toggle("hi", on);
    upper.classList.toggle("hi", on);
    pegs.forEach((el) => el.classList.toggle("hi", !on));
    read.textContent = on ? "lift" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => Math.hypot(sx - mid[0], (sy - mid[1]) * 1.4) < 120;
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "tuningpeg",
  means: "A ukulele on its back: over it, the neck lifts and the ukulele tips up on its tail, pegs first, to be tuned.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[219, 201], [180, 160], [250, 220], null],
  mount,
});

hoofpick.code:
/**
 * Branding iron: a long iron with a round brand head and a wooden grip, laid across a two-post stand. The pointer lifts the head end, the iron pivoting on the rear post.
 *
 * The pattern: one part turning about a fixed axis, driven by a spring.
 */
const { Cam, fit, proj, unproj, hull, poly, clamp, r2, spring, stepS, mk, pointer, register, disposer } = HL;

const rz = (x0, y0, x1, y1, z) => [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]];
const box = (x0, y0, x1, y1, z0, z1) => [rz(x0, y0, x1, y1, z0), rz(x0, y0, x1, y1, z1)];
const alongX = (sec, x0, x1) => [x0, x1].map((x) => sec.map(([y, z]) => [x, y, z]));
const lathe = (cx, cy, prof, n = 20) => prof.map(([r, z]) => Array.from({ length: n }, (_, j) => { const t = (j / n) * 2 * Math.PI; return [cx + r * Math.cos(t), cy + r * Math.sin(t), z]; }));
const turnX = (yc, zc, a) => { const c = Math.cos(a), s = Math.sin(a); return ([x, y, z]) => [x, yc + (y - yc) * c - (z - zc) * s, zc + (y - yc) * s + (z - zc) * c]; };
const same = (p) => p;
const turnY = (xc, zc, a) => { const c = Math.cos(a), s = Math.sin(a); return ([x, y, z]) => [xc + (x - xc) * c - (z - zc) * s, y, zc + (x - xc) * s + (z - zc) * c]; };
const rodX = (x0, x1, yc, zc, r, n = 14) => alongX(Array.from({ length: n }, (_, j) => { const t = (j / n) * 2 * Math.PI; return [yc + r * Math.cos(t), zc + r * Math.sin(t)]; }), x0, x1);

function mesh(rings, smooth) {
  const pts = rings.flat(), n = rings[0].length, m = rings.length, faces = [];
  const id = (i, j) => i * n + ((j + n) % n);
  for (let i = 0; i < m - 1; i++) for (let j = 0; j < n; j++) faces.push([id(i, j), id(i, j + 1), id(i + 1, j + 1), id(i + 1, j)]);
  faces.push(rings[0].map((_, j) => id(0, j)), rings[m - 1].map((_, j) => id(m - 1, j)));
  const avg = (q) => [0, 1, 2].map((k) => q.reduce((s, p) => s + p[k], 0) / q.length), c = avg(pts);
  for (const f of faces) {
    const q = f.map((i) => pts[i]), fc = avg(q);
    let nx = 0, ny = 0, nz = 0;
    q.forEach((a, k) => { const b = q[(k + 1) % q.length]; nx += (a[1] - b[1]) * (a[2] + b[2]); ny += (a[2] - b[2]) * (a[0] + b[0]); nz += (a[0] - b[0]) * (a[1] + b[1]); });
    if (nx * (fc[0] - c[0]) + ny * (fc[1] - c[1]) + nz * (fc[2] - c[2]) < 0) f.reverse();
  }
  return { pts, faces, smooth, n };
}

function drawMesh(P, s0, M, xf, el) {
  const sp = M.pts.map((p) => P(...xf(p)));
  let d = "";
  for (const f of M.faces) {
    let A = 0;
    f.forEach((i, k) => { const a = sp[i], b = sp[f[(k + 1) % f.length]]; A += a[0] * b[1] - b[0] * a[1]; });
    if (A * s0 <= 0) continue;
    f.forEach((i, k) => {
      const j = f[(k + 1) % f.length];
      if (M.smooth && Math.floor(i / M.n) !== Math.floor(j / M.n)) return;
      d += "M" + r2(sp[i][0]) + " " + r2(sp[i][1]) + "L" + r2(sp[j][0]) + " " + r2(sp[j][1]);
    });
  }
  el.sil.setAttribute("d", poly(hull(sp)));
  el.ed.setAttribute("d", d);
  if (el.in) el.in.setAttribute("d", M.inner.map((L) => poly(L.map((p) => P(...xf(p))))).join(""));
}

const D = Math.PI / 180;
const XF = (a) => turnY(12, 32, a);
const disc = (x, r, n = 28) => Array.from({ length: n }, (_, j) => { const t = (j / n) * 2 * Math.PI; return [x, 12 + r * Math.cos(t), 32 + r * Math.sin(t)]; });
const PARTS = [
  [box(-2, 2, 66, 22, 0, 4), false, false],
  [box(9, 9, 15, 15, 4, 30), false, false],
  [box(53, 9, 59, 15, 4, 30), false, false],
  [rodX(-30, -4, 12, 32, 3.4), true, true],
  [rodX(-4, 92, 12, 32, 1.6), true, true],
  [rodX(92, 96, 12, 32, 13, 28), true, true, [disc(96.2, 9), disc(96.2, 4)]],
];
const REST = 0, HI = 0.8, HC = [50, 12, 30], RR = 90;
const ORDER = () => [0, 1, 2, 3, 4, 5];
const READ = (a) => Math.round(a / D) + "°";

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const parts = PARTS.map(([rings, smooth, mov, inner, hi]) => { const M = mesh(rings, smooth); M.mov = mov; M.inner = inner; M.hi = hi === undefined ? mov : hi; return M; });
  const all = [];
  for (const M of parts) for (const a of [REST, HI]) for (const p of M.pts) all.push(M.mov ? XF(a)(p) : p);
  const C1 = Cam(45, 0.5, 1), P1 = proj(C1), s1 = all.map((p) => P1(...p));
  const w = Math.max(...s1.map((q) => q[0])) - Math.min(...s1.map((q) => q[0])), h = Math.max(...s1.map((q) => q[1])) - Math.min(...s1.map((q) => q[1]));
  const C = Cam(45, 0.5, Math.min(372 / w, 296 / h));
  fit(C, all, 200, 162);
  const P = proj(C), o = P(0, 0, 0), a1 = P(1, 0, 0), b1 = P(1, 1, 0);
  const s0 = (a1[0] - o[0]) * (b1[1] - o[1]) - (a1[1] - o[1]) * (b1[0] - o[0]);
  const g = mk("g", {}, svg);
  const els = parts.map((M) => {
    const grp = mk("g", {}, g);
    const el = { grp, sil: mk("path", { class: "sil" }, grp), ed: mk("path", { class: "nf" }, grp) };
    if (M.inner) el.in = mk("path", { class: "nf lo" }, grp);
    if (M.hi) el.sil.classList.add("hi");
    return el;
  });
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const xf = XF(a);
    parts.forEach((M, i) => drawMesh(P, s0, M, M.mov ? xf : same, els[i]));
    ORDER(a).forEach((i) => g.appendChild(els[i].grp));
  }
  const sp = spring(REST);
  const B = register(stage, (dt) => { const mv = stepS(sp, dt); draw(sp.x); return mv; });
  bag.add(B.unregister);
  draw(REST);
  function aim(p) {
    let t = 0;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], HC[2]); t = clamp((RR - Math.hypot(wx - HC[0], wy - HC[1])) / (RR * 0.55), 0, 1); }
    sp.t = REST + t * (MAX - REST);
    read.textContent = t > 0 ? READ(sp.t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { MAX = v; }, destroy: bag.dispose };
}

hairline({
  name: "hoofpick",
  means: "A branding iron on its stand: the pointer lifts the brand head, the iron pivoting on the rear post.",
  rules: [1, 3, 5, 6],
  range: [0.4, 0.7, 0.8],
  tour: [[294, 227], [214, 196], [330, 170], null],
  mount,
});

beehood.code:
/**
