const D = Math.PI / 180;
const XF = (a) => turnX(-1, 32, a);
const hole = Array.from({ length: 20 }, (_, j) => { const t = (j / 20) * 2 * Math.PI; return [36 + 5 * Math.cos(t), 44.2, 13 + 5 * Math.sin(t)]; });
const PARTS = [
  [box(0, 0, 72, 44, 0, 32), false, false, [hole, rz(3, 3, 69, 41, 32)]],
  [box(-1, -1, 73, 45, 32, 41), false, true],
  [box(31, 37, 41, 40, 41, 45), false, true],
];
const REST = 0.14, HI = 1.9, HC = [36, 22, 38], RR = 80;
const ORDER = (a) => (a > 1.45 ? [1, 2, 0] : [0, 1, 2]);
const READ = (a) => Math.round(a / D) + "°";

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const parts = PARTS.map(([rings, smooth, mov, inner, hi]) => { const M = mesh(rings, smooth); M.mov = mov; M.inner = inner; M.hi = hi === undefined ? mov : hi; return M; });
  const all = [];
