birdtable.code:
/**
 * Bird table: a tray on a post with a gabled roof on four corner posts. The
 * roof is hinged along its back eave: the pointer over the table tilts it up
 * and back, wider the nearer the front the pointer comes. At rest the roof
 * sits a little lifted, bright. The slider is the widest tilt.
 *
 * The pattern: one lid turning on a hinge (open).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const T0 = 52, T1 = 56, UP = 80, RX = 30, EZ = 82, RZ = 104, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-24, -24, 0], [28, 28, 0], [-RX, -RX, T0], [RX, RX, T0], [-RX, RX, RZ], [RX, -RX, RZ], [-RX - 20, 0, RZ + 40], [-RX, RX, EZ + 62]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // feet: a low cross on the ground
  const [fa, fai] = rings(-22, -4, 22, 4, 2, 1);
  put(solid(g), prism(P, front, fa, fai, 0, 4));
  const [fb, fbi] = rings(-4, -22, 4, 22, 2, 1);
  put(solid(g), prism(P, front, fb, fbi, 0, 4));
  const [pr, pi] = rings(-3.5, -3.5, 3.5, 3.5, 1.5, 1);
  put(solid(g), prism(P, front, pr, pi, 4, T0));
  // the tray with a raised lip
  const [tr, ti] = rings(-26, -26, 26, 26, 3, 3);
  put(solid(g), prism(P, front, tr, ti, T0, T1));
  let d = "";
  for (const [x, y] of [[-6, 4], [2, -8], [9, 6], [-12, -4], [4, 12]]) d += seg(P(x, y, T1), P(x + 2, y + 1, T1));
  mk("path", { d, class: "nf lo" }, g);
  for (const [x, y] of [[-23, -23], [23, -23], [-23, 23], [23, 23]].sort((a, b) => a[0] + a[1] - b[0] - b[1])) {
    const [ur, ui] = rings(x - 1.6, y - 1.6, x + 1.6, y + 1.6, 0.8, 0.6);
    put(solid(g), prism(P, front, ur, ui, T1, UP));
  }

  const roof = mk("g", {}, g);
  const sil = mk("path", { class: "sil hi" }, roof), faces = mk("path", { class: "nf lo" }, roof);
  const ang = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    // hinge line: x = -RX, z = UP, along y
    const at = (x, y, z) => { const dx = x + RX, dz = z - UP; return P(-RX + dx * c - dz * s, y, UP + dx * s + dz * c); };
    const pts = [];
    for (const y of [-RX - 3, RX + 3]) pts.push(at(-RX - 3, y, EZ - 2), at(-RX - 3, y, EZ), at(0, y, RZ), at(0, y, RZ + 3), at(RX + 3, y, EZ), at(RX + 3, y, EZ - 2));
    sil.setAttribute("d", poly(hull(pts)));
    const Y = RX + 3;
    faces.setAttribute("d",
      seg(at(0, -Y, RZ + 3), at(0, Y, RZ + 3)) +
      seg(at(-RX - 3, Y, EZ), at(0, Y, RZ + 3)) + seg(at(0, Y, RZ + 3), at(RX + 3, Y, EZ)) +
      seg(at(RX + 3, -Y, EZ), at(RX + 3, Y, EZ)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let tgt = null, lastP = null;
  function lift(p) {
    lastP = p;
    let a = REST;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], T0);
      if (wy > -45 && wy < 45 && wx > -45 && wx < 50) a = maxA * clamp((wx + 40) / 80, 0.35, 1);
    }
    a = Math.round(a);
    if (a === tgt) return;
    tgt = a;
    ang.t = a;
    read.textContent = !p || a === REST ? "rest" : "roof " + a + "°";
    B.wake();
  }
  lift(null);
  bag.add(pointer(stage, { move: lift, leave: () => lift(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; tgt = null; lift(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "birdtable",
  means: "A bird table on a post: its gabled roof is hinged at the back eave and tilts up as the pointer comes over the tray.",
  rules: [1, 3, 5, 6],
  range: [40, 70, 95],
  tour: [[185, 186], [225, 199], [252, 212], null],
  mount,
});

hedgehog.code:
/**
 * Hedgehog house: a low wooden box with an arched doorway and a pitched
 * roof hinged along its back edge. The pointer over the house lifts the
 * roof, wider the nearer the front it comes, to show the straw nest. At
 * rest the roof sits a little ajar, bright. The slider is the widest opening.
 *
 * The pattern: one lid turning on a hinge (open).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const D = 70, Wd = 92, H = 38, RH = 24, OV = 6, REST = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-6, -6, -4], [D + 6, Wd + 6, -4], [D + 6, -6, -4], [-6, Wd + 6, -4], [-OV, 0, H + D + 2 * OV + 4], [-OV, Wd, H + D + 2 * OV + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-6, -6, D + 6, Wd + 6, 3, 1.5);
  put(solid(g), prism(P, front, br, bi, -4, 0));
  const [tr, ti] = rings(0, 0, D, Wd, 1.5, 1.2);
  put(solid(g), prism(P, front, tr, ti, 0, H));
  // the doorway: an arch on the front-left face, with a step of shadow line
  const arch = [];
  const yc = Wd, xc = D * 0.55, ar = 11;
  for (let i = 0; i <= 12; i++) { const t = Math.PI * i / 12; arch.push(P(xc + ar * Math.cos(t), yc, 2 + 14 + ar * Math.sin(t) * 0.9)); }
  arch.unshift(P(xc + ar, yc, 2)); arch.push(P(xc - ar, yc, 2));
  mk("path", { d: poly(arch), class: "nf" }, g);
  // straw nest on the floor, seen when the roof lifts
  let d = "";
  for (const [x, y, l] of [[18, 22, 16], [30, 40, 20], [44, 30, 14], [24, 60, 18], [46, 64, 16], [36, 52, 12]]) d += seg(P(x, y, H), P(x + l * 0.5, y + l, H));
  mk("path", { d, class: "nf lo" }, g);

  const roof = mk("g", {}, g);
  const sil = mk("path", { class: "sil hi" }, roof), faces = mk("path", { class: "nf lo" }, roof);
  const ang = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    // local x from the hinge at the back edge, dz up from the box top
    const at = (x, y, dz) => P(-OV + x * c - dz * s, y, H + x * s + dz * c);
    const L = D + 2 * OV, prof = [[0, 0], [L / 2, RH], [L, 0]], pts = [];
    for (const [x, dz] of prof) for (const y of [-OV, Wd + OV]) pts.push(at(x, y, dz));
    sil.setAttribute("d", poly(hull(pts)));
    faces.setAttribute("d",
      seg(at(L / 2, -OV, RH), at(L / 2, Wd + OV, RH)) +
      poly([at(0, Wd + OV, 0), at(L / 2, Wd + OV, RH), at(L, Wd + OV, 0)]));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let tgt = null, lastP = null;
  function lift(p) {
    lastP = p;
    let a = REST;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], H);
      if (wy > -30 && wy < Wd + 30 && wx > -40 && wx < D + 50) a = maxA * clamp((wx + 30) / (D + 40), 0.3, 1);
    }
    a = Math.round(a);
    if (a === tgt) return;
    tgt = a;
    ang.t = a;
    read.textContent = !p || a === REST ? "rest" : "roof " + a + "°";
    B.wake();
  }
  lift(null);
  bag.add(pointer(stage, { move: lift, leave: () => lift(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; tgt = null; lift(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "hedgehog",
  means: "A hedgehog house with an arched door: its pitched roof lifts on a back hinge as the pointer nears, to show the nest.",
  rules: [1, 3, 5, 6],
  range: [30, 70, 95],
  tour: [[194, 176], [238, 214], [251, 223], null],
  mount,
});

compostbin2.code:
/**
 * Wormery: a square sump with a tap, two stacked worm trays and a lid. The
 * pointer over the stack lifts the top tray and its lid, higher the higher
 * the pointer goes, to show the compost in the tray below; that tray rises
 * a little after it. At rest the lid sits a little ajar, bright. The slider
 * is the highest lift.
 *
 * The pattern: one stack opening (lift).
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, spring, stepS, circ,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 84, SUMP = 22, TH = 17, LH = 6, REST = 3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxL = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-4, -4, 0], [W + 4, W + 4, 0], [W + 4, -4, 0], [-4, W + 4, 0], [0, 0, SUMP + 2 * TH + LH + 1.6 * 36 + 4], [W, W, SUMP + 2 * TH + LH + 1.6 * 36]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(0, 0, W, W, 5, 1.6);
  const [lr, li] = rings(-2, -2, W + 2, W + 2, 6, 2);
  put(solid(g), prism(P, front, sr, si, 0, SUMP));
  // the tap on the sump's front-left face
  const disc = (x, z, r) => circ(r, 16).map((q) => P(x + q.u, W, z + q.v));
  const tap = mk("path", { class: "nf" }, g);
  tap.setAttribute("d", poly(hull(disc(W * 0.5, 8, 3.5).concat(circ(3.5, 16).map((q) => P(W * 0.5 + q.u, W + 7, 8 + q.v))))) +
    seg(P(W * 0.5, W + 6, 11), P(W * 0.5, W + 6, 17)));

  const t1 = { g: mk("g", {}, g) }, t2 = { g: mk("g", {}, g) }, lid = { g: mk("g", {}, g) };
  const s1 = solid(t1.g), c1 = mk("path", { class: "nf lo" }, t1.g);
  const s2 = solid(t2.g), c2 = mk("path", { class: "nf lo" }, t2.g);
  const sl = solid(lid.g);
  sl.sil.classList.add("hi");
  const knob = mk("path", { class: "nf" }, lid.g);
  const worms = (z) => {
    let d = "";
    for (const [x, y, dx, dy] of [[18, 16, 14, 5], [50, 24, 11, 14], [28, 46, 16, -4], [58, 58, 8, 12], [16, 66, 12, 3], [42, 36, 7, 10]]) {
      d += open3([P(x, y, z), P(x + dx * 0.5, y + dy * 0.5 + 2, z), P(x + dx, y + dy, z)]);
    }
    return d;
  };
  const open3 = (pts) => "M" + pts.map((p) => p[0].toFixed(2) + " " + p[1].toFixed(2)).join("L");

  const lift = spring(REST);
  let last = NaN;
  function draw(L) {
    if (L === last) return;
    last = L;
    const a = SUMP + L * 0.3, b = SUMP + TH + L, c = SUMP + 2 * TH + L * 1.6;
    put(s1, prism(P, front, sr, si, a, a + TH));
    c1.setAttribute("d", worms(a + TH));
    put(s2, prism(P, front, sr, si, b, b + TH));
    c2.setAttribute("d", worms(b + TH));
    put(sl, prism(P, front, lr, li, c, c + LH));
    knob.setAttribute("d", poly(hull(ringAt(P, circ(4, 16).map((q) => ({ ...q, u: q.u + W / 2, v: q.v + W / 2 })), c + LH).concat(
      ringAt(P, circ(4, 16).map((q) => ({ ...q, u: q.u + W / 2, v: q.v + W / 2 })), c + LH + 3)))));
  }

  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);

  // hit: the stack's rest box on screen, which never moves
  const top = P(W / 2, W / 2, SUMP + 2 * TH + LH)[1], bot = P(W, W, 0)[1], xl = P(0, W, 0)[0], xr = P(W, 0, 0)[0];
  let tgt = null, lastP = null;
  function go(p) {
    lastP = p;
    let L = REST;
    if (p && p[0] > xl - 20 && p[0] < xr + 20 && p[1] > top - 60 && p[1] < bot + 10) L = maxL * clamp((bot - p[1]) / (bot - top), 0.35, 1);
    L = Math.round(L);
    if (L === tgt) return;
    tgt = L;
    lift.t = L;
    read.textContent = L === REST ? "rest" : "lift " + L;
    B.wake();
  }
  go(null);
  bag.add(pointer(stage, { move: go, leave: () => go(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxL = v; tgt = null; go(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "compostbin2",
  means: "A wormery of stacked trays on a tapped sump: the top tray and lid lift as the pointer rises over it, showing the compost below.",
  rules: [1, 2, 3, 5],
  range: [14, 26, 36],
  tour: [[200, 230], [200, 166], [200, 132], null],
  mount,
});

enlarger.code:
/**
 * Enlarger: a darkroom photo enlarger, a baseboard with a print easel, a
 * tall column at the back, and the lamp head on its arm with the lens and
 * bellows below. The pointer over the enlarger cranks the head up the
 * column, the bellows stretching under it. At rest the head sits low, its
 * lens rim bright over the easel. The slider is how far it climbs.
 *
 * The pattern: one part sliding on a fixed track; the hit is the rest box.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 4, CH = 104, H0 = 36, HX = 18, HY = 8, HW = 30, HD = 28, HH = 20;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 1.95);
  const ext = [[-4, -4, 0], [62, 54, 0], [62, -4, 0], [-4, 54, 0], [4, 16, CH + 4], [HX + HW, HY + HD, H0 + 40 + HH], [HX, HY, H0 + 40 + HH]];
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -4, 62, 54, 4, 1.4);
  const board = solid(g);
  put(board, prism(P, front, br, bi, 0, BZ));
  // the easel: a frame lying on the board, with its blades
  const [er, ei] = rings(HX - 2, HY + 4, HX + HW + 6, HY + HD + 10, 1.5, 4);
  mk("path", { class: "nf lo", d: poly(ringAt(P, er, BZ)) + poly(ringAt(P, ei, BZ)) }, g);
  // the column, standing at the back
  const [cr, ci] = rings(0, 14, 8, 22, 3, 1);
  put(solid(g), prism(P, front, cr, ci, BZ, CH));
  const head = mk("g", {}, g);
  const arm = solid(head), bel = mk("path", { class: "nf" }, head), lens = solid(head), box = solid(head), lamp = solid(head);
  const LX = HX + HW / 2 + 2, LY = HY + HD / 2 + 2;
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    const [ar, ai] = rings(6, 14, HX + 2, 22, 1.5, 0.6);
    put(arm, prism(P, front, ar, ai, z + 6, z + 14));
    const top = ringAt(P, disc(LX, LY, 10), z), bot = ringAt(P, disc(LX, LY, 8), z - 10 - (z - H0) * 0.25);
    bel.setAttribute("d", poly(hull(top.concat(bot))));
    const lz = z - 10 - (z - H0) * 0.25;
    put(lens, prism(P, front, disc(LX, LY, 6), disc(LX, LY, 4.6), lz - 8, lz));
    const [hr, hi] = rings(HX, HY, HX + HW, HY + HD, 6, 1.8);
    put(box, prism(P, front, hr, hi, z, z + HH));
    put(lamp, prism(P, front, disc(LX, LY, 9), disc(LX, LY, 7.4), z + HH, z + HH + 6));
  }
  const hz = tween(H0);
  const B = register(stage, (_dt, now) => { draw(tval(hz, now)); return !tdone(hz, now); });
  bag.add(B.unregister);

  const box0 = hull(ext.map((p) => P(...p)));
  const xs = box0.map((p) => p[0]), ys = box0.map((p) => p[1]);
  const [x0, x1, y0, y1] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(hz, a > 0 ? H0 + lift : H0, performance.now(), 0);
    lens.sil.classList.toggle("hi", a <= 0);
    box.sil.classList.toggle("hi", a > 0);
    read.textContent = a > 0 ? "head +" + Math.round(lift) : "rest";
    B.wake();
  }
  setActive(0);
  const hit = ([sx, sy]) => (sx > x0 && sx < x1 && sy > y0 && sy < y1 ? 1 : 0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; if (act > 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "enlarger",
  means: "A darkroom photo enlarger: with the pointer over it, the lamp head climbs its column and the bellows stretch under it.",
  rules: [1, 5, 6],
  range: [10, 28, 40],
  tour: [[210, 149], [206, 250], [175, 90], null],
  mount,
});

devtank.code:
/**
 * Devtank: a film developing tank, a tall drum with the reel's spiral just
 * inside its mouth, closed by a wide light-tight lid with a pouring funnel
 * on top. The pointer over the tank lifts the lid clear and swings it aside,
 * showing the reel. At rest the lid sits snug, its rim bright. The slider is
 * how far the lid lifts.
 *
 * The pattern: one part lifting off; the hit is the rest box.
 */
const {
  Cam, circ, fit, facing, hull, poly, open, prism, proj, ringAt, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 22, TZ = 54, LR = 25, LH = 13, FR = 9;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.95);
  const ext = [[-R - 2, -R - 2, 0], [R + 2, R + 2, 0], [R + 2, -R - 2, 0], [-R - 2, R + 2, 0], [0, 0, TZ + LH + 9], [24, -24, TZ + 18 + LH + 8], [24 + LR, -24, TZ + 18], [24, -24 - LR, TZ + 18], [24 - 7, -24 - 7, TZ + 18 + LH + 8]];
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the drum, with a foot ring and the reel's spiral in its mouth
  put(solid(g), prism(P, front, disc(0, 0, R + 2), disc(0, 0, R + 0.8), 0, 4));
  put(solid(g), prism(P, front, disc(0, 0, R), disc(0, 0, R - 1.6), 4, TZ));
  const sp = [];
  for (let i = 0; i <= 160; i++) { const a = (i / 160) * Math.PI * 9, r = 4 + (i / 160) * (R - 7); sp.push(P(r * Math.cos(a), r * Math.sin(a), TZ - 1)); }
  mk("path", { class: "nf lo", d: open(sp) + poly(ringAt(P, disc(0, 0, 3.4, 16), TZ - 1)) }, g);
  const lidG = mk("g", {}, g);
  const lid = solid(lidG), fun = solid(lidG), cap = mk("path", { class: "nf lo" }, lidG);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const z = TZ - 6 + t * lift, x = t * 24, y = -t * 24;
    put(lid, prism(P, front, disc(x, y, LR), disc(x, y, LR - 2), z, z + LH));
    put(fun, prism(P, front, disc(x, y, FR), disc(x, y, FR - 1.4), z + LH, z + LH + 7));
    cap.setAttribute("d", poly(ringAt(P, disc(x, y, 4, 20), z + LH + 7)));
  }
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const pts = ext.slice(0, 5).map((p) => P(...p));
