    read.textContent = a > 0 ? "lid off" : "rest";
    B.wake();
  }
  setActive(0);
  const hit = ([sx, sy]) => (sx > x0 - 10 && sx < x1 + 10 && sy > y0 - 10 && sy < y1 + 6 ? 1 : 0);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(0) }));
