postbike.code:
/**
 * Post trolley: a deep mail box on four casters with a push handle at the
 * back, its lid hinged along the back edge. The pointer's height is the lid:
 * it swings up and over toward the handle. At rest it stands a crack open,
 * the latch bright. The slider is the rest opening.
 *
 * The pattern: one lid opening on a hinge by the pointer (open).
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, ringAt, clamp, rad, circ,
  disposer, mk, pointer, put, register, solid, spring, stepS, facing, flatDot, place,
} = HL;

const X0 = -20, X1 = 20, Y = 14, Z = 40, AMAX = 115;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let restA = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-26, -16, 0], [22, 16, 0], [-26, 0, 62], [X0, -Y, Z + 42], [X0 + 40 * Math.cos(rad(60)), Y, Z + 40 * Math.sin(rad(60))]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => { const [r, i] = rings(x - 3.5, y - 3.5, x + 3.5, y + 3.5, 3.5, 1); put(solid(g), prism(P, front, r, i, 0, 9)); };
  wheel(-15, -10); wheel(15, -10); wheel(-15, 10);
  const bar = (a, b, r) => hull(circ(r, 12).flatMap((q) => [P(a[0] + q.u, a[1] + q.v, a[2]), P(b[0] + q.u, b[1] + q.v, b[2])]));
  for (const y of [-11, 11]) mk("path", { class: "sil", d: poly(bar([-23, y, 30], [-25, y, 60], 1.6)) }, g);
  mk("path", { class: "sil", d: poly(hull([-1, 1].flatMap((s) => circ(1.8, 12).flatMap((q) => [P(-25 + q.u, s * 12, 60 + q.v)])))) }, g);
  const [br, bi] = rings(X0, -Y, X1, Y, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, 9, Z));
  const mouth = mk("path", { class: "nf lo" }, g);
  wheel(15, 10);
  const lid = mk("path", { class: "sil" }, g), lidc = mk("path", { class: "nf lo" }, g);
  const latch = flatDot(g, C, 2.4, "dot");
  const [lr, li] = rings(0, -Y - 1, X1 - X0 + 1, Y + 1, 3, 1.4);
  const A = spring(restA);
  let last = NaN, act = false;

  function draw() {
    const a = A.x;
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (q, t) => P(X0 + q.u * c - t * s, q.v, Z + q.u * s + t * c);
    lid.setAttribute("d", poly(hull(lr.flatMap((q) => [at(q, 0), at(q, 2.2)]))));
    lidc.setAttribute("d", poly(li.map((q) => at(q, a > 100 ? 0 : 2.2))));
    mouth.setAttribute("d", a > 8 ? poly(ringAt(P, bi, Z)) : "");
    place(latch, at({ u: X1 - X0 - 2, v: 0 }, 2.2));
    read.textContent = act ? Math.round(a) + "°" : "rest";
  }

  const B = register(stage, (dt) => { const m = stepS(A, dt); draw(); return m; });
  bag.add(B.unregister);
  function setActive(on, a) {
    act = on; A.t = a;
    lid.classList.toggle("hi", on);
    latch.setAttribute("class", on ? "dot off" : "dot");
    last = NaN; B.wake();
  }
  setActive(false, restA);
  draw();
  bag.add(pointer(stage, {
    move: ([, sy]) => setActive(true, clamp(AMAX - ((sy - 60) / 190) * AMAX, 0, AMAX)),
    leave: () => setActive(false, restA),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { restA = v; if (!act) setActive(false, v); }, destroy: bag.dispose };
}

hairline({
  name: "postbike",
  means: "A post trolley: the lid of the mail box swings open on its back hinge as the pointer rises.",
  rules: [1, 3, 4, 5],
  range: [4, 12, 20],
  tour: [[200, 225], [242, 172], [233, 308], null],
  mount,
});

papermould.code:
/**
 * Paper mould: the papermaker's wire mould, a wooden frame strung with laid
 * wires, and the loose deckle frame that sits on it. The pointer rocks the
 * mould on its long axis, the shake that settles the pulp, and the deckle
 * lifts clear as it tips. At rest it lies near flat, the deckle bright.
 *
 * The pattern: one part tilting on a spring that follows the pointer.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rad, rrect, seg, spring, stepS, unproj,
  disposer, mk, pointer, register, solid,
} = HL;

const W = 30, D = 21, TH = 3, REST = 5, MAX = 30, LIFT = 9;
function rot([x, y, z], a, up) {
  const c = Math.cos(a), s = Math.sin(a), zz = z + up;
  return [x * c - zz * s, y, x * s + zz * c + 14];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.75);
  const ext = [];
  [-MAX, MAX].forEach((d) => [[-W, -D], [W, -D], [W, D], [-W, D]].forEach(([x, y]) => ext.push(rot([x, y, TH * 2], rad(d), LIFT))));
  fit(C, ext, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const mould = solid(g), wires = mk("path", { class: "nf lo" }, mould.g), deckle = solid(g);
  const sp = spring(REST);
  let last = NaN;
  function frame(r0, r1, z0, z1, a, up) {
    const pts = r0.map((r) => P(...rot([r.u, r.v, z0], a, up))).concat(r0.map((r) => P(...rot([r.u, r.v, z1], a, up))));
    return { sil: poly(hull(pts)), cr: poly(r1.map((r) => P(...rot([r.u, r.v, z1], a, up)))) };
  }
  const mO = rrect(-W, -D, W, D, 3, 5), mI = rrect(-W + 4, -D + 4, W - 4, D - 4, 1.5, 4);
  const dO = rrect(-W + 1, -D + 1, W - 1, D - 1, 3, 5), dI = rrect(-W + 4, -D + 4, W - 4, D - 4, 1.5, 4);

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), up = LIFT * clamp((deg - REST) / (MAX - REST), 0, 1);
    const m = frame(mO, mI, 0, TH, a, 0);
    mould.sil.setAttribute("d", m.sil);
    mould.cr.setAttribute("d", m.cr);
    let w = "";
    for (let i = 1; i < 10; i++) { const x = -W + 4 + i * (2 * W - 8) / 10; w += seg(P(...rot([x, -D + 4, TH], a, 0)), P(...rot([x, D - 4, TH], a, 0))); }
    for (let j = 1; j < 3; j++) { const y = -D + 4 + j * (2 * D - 8) / 3; w += seg(P(...rot([-W + 4, y, TH], a, 0)), P(...rot([W - 4, y, TH], a, 0))); }
    wires.setAttribute("d", w);
    const k = frame(dO, dI, TH, TH + 2.4, a, up);
    deckle.sil.setAttribute("d", k.sil + k.cr);
    deckle.cr.setAttribute("d", "");
  }
  deckle.sil.classList.add("hi");
  deckle.sil.setAttribute("fill-rule", "evenodd");

  const R = register(stage, (dt) => {
    const m = stepS(sp, dt);
    draw(Math.round(sp.x * 100) / 100);
    return m;
  });
  bag.add(R.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 14);
    if (Math.abs(x) > W + 14 || Math.abs(y) > D + 14) return leave();
    sp.t = REST + (MAX - REST) * clamp((x + W) / (2 * W), 0, 1) * reach;
    read.textContent = Math.round(sp.t) + "°";
    R.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; R.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "papermould",
  means: "A papermaker's mould and deckle: the wired mould rocks toward the pointer and the loose deckle frame lifts off it.",
  rules: [3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[269, 262], [200, 228], [131, 193], null],
  mount,
});

signalbox.code:
/**
 * Signal lever: one lever of a signal box frame, a tall shaft rising from a
 * slot in its cast-iron base, with the catch handle up by the grip. The
 * pointer pulls the lever: the nearer the pointer to the signalman, the
 * further the shaft swings back through its slot. At rest it stands forward
 * in the frame, bright. The slider is the reach.
 *
 * The pattern: one part tilting on a spring that follows the pointer.
 */
const {
  Cam, clamp, fit, hull, poly, prism, proj, facing, rad, rings, rrect, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 8, H = 66, REST = -24, MAX = 30;
function rot([x, y, z], a) {
  const dz = z - PZ, c = Math.cos(a), s = Math.sin(a);
  return [x, y * c + dz * s, PZ - y * s + dz * c];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.25);
  fit(C, [[-12, -26, 0], [12, 26, 0], [12, -26, 0], [-12, 26, 0], rot([0, 0, H + 4], rad(REST)), rot([0, 0, H + 4], rad(MAX))], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const T = (p, a) => P(...rot(p, a));
  // the base: a low iron block with the lever's slot and its quadrant
  const base = solid(g);
  const [bR, bI] = rings(-10, -24, 10, 24, 4, 1.4);
  put(base, prism(P, front, bR, bI, 0, PZ));
  let q = "";
  for (let i = 0; i <= 12; i++) { const a = rad(REST + (MAX - REST) * i / 12); q += i ? "L" : "M"; const p = P(0, 20 * Math.sin(a), PZ); q += p[0].toFixed(2) + " " + p[1].toFixed(2); }
  mk("path", { class: "nf lo", d: q + seg(P(-1.5, -20, PZ), P(-1.5, 20, PZ)) + seg(P(1.5, -20, PZ), P(1.5, 20, PZ)) }, base.g);

  const shaft = solid(g), grip = solid(g), latch = solid(g);
  const sp = spring(REST);
  let last = NaN;
  function box(ring, inner, z0, z1, a) {
    const pts = ring.map((r) => T([r.u, r.v, z0], a)).concat(ring.map((r) => T([r.u, r.v, z1], a)));
    return { sil: poly(hull(pts)), cr: poly(inner.map((r) => T([r.u, r.v, z1], a))) };
  }
  const sR = rrect(-2.4, -1.8, 2.4, 1.8, 1.2, 4), sI = rrect(-1.6, -1, 1.6, 1, 0.6, 4);
  const gR = rrect(-3, -2.6, 3, 2.6, 2.4, 6), gI = rrect(-2.2, -1.8, 2.2, 1.8, 1.6, 6);
  const lR = rrect(-2, 1.8, 2, 5.4, 1, 4), lI = rrect(-1.3, 2.5, 1.3, 4.7, 0.5, 4);

  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg);
    const s = box(sR, sI, PZ - 2, H - 12, a), k = box(gR, gI, H - 13, H, a), l = box(lR, lI, H - 30, H - 16, a);
    shaft.sil.setAttribute("d", s.sil); shaft.cr.setAttribute("d", seg(T([0, 1.8, PZ + 4], a), T([0, 1.8, H - 14], a)));
    grip.sil.setAttribute("d", k.sil); grip.cr.setAttribute("d", k.cr);
    latch.sil.setAttribute("d", l.sil); latch.cr.setAttribute("d", l.cr);
  }
  grip.sil.classList.add("hi");

  const R = register(stage, (dt) => {
    const m = stepS(sp, dt);
    draw(Math.round(sp.x * 100) / 100);
    return m;
  });
  bag.add(R.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (Math.abs(x) > 40 || Math.abs(y) > 60) return leave();
    const t = clamp((y + 40) / 80, 0, 1);
    sp.t = REST + (MAX - REST) * t * reach;
    read.textContent = sp.t > 10 ? "off" : "on";
    R.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; R.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "signalbox",
  means: "A signal box lever in its iron base: the shaft swings back through its slot as the pointer pulls toward the signalman.",
  rules: [3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[131, 278], [200, 240], [269, 209], null],
  mount,
});

foggong.code:
/**
 * Fog bell: a big bronze bell hung from a beam between two posts on a slab,
 * its clapper ball hanging under the lip. The pointer's place along the
 * frame swings the bell on its spring toward it, the clapper riding with it.
 * At rest the bell hangs a little tipped, its lip bright. The
 * slider is how far the bell may swing.
 *
 * The pattern: one part answering on a spring (lean).
 */
const {
  Cam, circ, fit, facing, hull, poly, open, run, prism, proj, rings, spring, stepS, unproj, clamp, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZP = 96, MAX = rad(34), REST = rad(-7);
const PROF = [[-6, 9], [-12, 15], [-22, 17], [-34, 19], [-46, 24], [-56, 30], [-60, 31]];
const rot = (x, y, dz, f) => [x * Math.cos(f) - dz * Math.sin(f), y, ZP + x * Math.sin(f) + dz * Math.cos(f)];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[-44, -58, 0], [44, 58, 0], [44, -58, 0], [-44, 58, 0], [0, 0, 108], [-50, 0, 40], [50, 0, 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-40, -56, 40, 56, 10, 2);
  put(solid(g), prism(P, front, sr, si, 0, 6));
  const post = (y) => { const [a, b] = rings(-6, y - 6, 6, y + 6, 4, 1.2); put(solid(g), prism(P, front, a, b, 6, 100)); };
  post(-46);
  const ballS = solid(g);
  const bell = solid(g), bow = mk("path", { class: "nf lo" }, bell.g), lip = mk("path", { class: "nf lo" }, bell.g);
  const [br, bi] = rings(-7, -52, 7, 52, 4, 1.5);
  put(solid(g), prism(P, front, br, bi, 100, 108));
  post(46);

  const W = (pts) => pts.map((q) => P(...q));
  const ringW = (r, dz, f, n = 32) => circ(r, n).map((q) => ({ ...q, w: rot(q.u, q.v, dz, f) }));
  let last = NaN;
  function draw(f) {
    if (f === last) return;
    last = f;
    const pts = [];
    for (const [dz, r] of PROF) for (const q of ringW(r, dz, f, 24)) pts.push(P(...q.w));
    pts.push(P(...rot(0, 0, 0, f)));
    bell.sil.setAttribute("d", poly(hull(pts)));
    bell.cr.setAttribute("d", "");
    bow.setAttribute("d", open(run(ringW(23, -45, f), front).map((q) => P(...q.w))));
    lip.setAttribute("d", open(run(ringW(30.5, -58, f), front).map((q) => P(...q.w))));
    const bp = [];
    for (const [dz, r] of [[-62, 2], [-65, 5], [-69, 5.5], [-73, 4], [-75, 1.5]]) for (const q of ringW(r, dz, f, 16)) bp.push(P(...q.w));
    ballS.sil.setAttribute("d", poly(hull(bp)));
  }
  const sp = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function active() { lip.setAttribute("class", "nf hi"); }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (Math.abs(y) > 90 || Math.abs(x) > 120) return leave();
    sp.t = clamp(x / 50, -1, 1) * MAX * clamp(gain, 0, 1);
    active(true);
    read.textContent = Math.round(sp.t * 180 / Math.PI) + "°";
    B.wake();
  }
  function leave() { sp.t = REST; active(false); read.textContent = "rest"; B.wake(); }
  draw(REST);
  active(false);
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

