pestleboard.code:
/**
 * Mezzaluna: a crescent chopping blade with a handle standing at each end,
 * resting on a round-cornered board. The blade rolls on its curved edge:
 * the pointer's place along the board rocks it toward that end, the curve
 * rolling so the edge always meets the board. At rest it leans a little to
 * one side, its blade bright. The slider is how far it rocks.
 *
 * The pattern: one part following the pointer (spring), hit on a fixed plane.
 */
const {
  Cam, clamp, fillet, fit, facing, hull, poly, prism, proj, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 46, BZ = 5, T = 1.4, HT = 3.6, REST = 0.16;
const BX0 = -60, BX1 = 60, BY0 = -26, BY1 = 26;
// the blade in its own plane (u along the board, w up), bottom on a circle of radius R
const blade = [];
for (let i = 0; i <= 16; i++) { const u = -34 + (68 * i) / 16; blade.push([u, R - Math.sqrt(R * R - u * u)]); }
for (let i = 16; i >= 0; i--) { const u = -34 + (68 * i) / 16; blade.push([u, 24 - (1156 - u * u) * 0.0085]); }
const post = (c) => fillet([[c - 3.4, 18], [c + 3.4, 18], [c + 4.6, 50], [c - 4.6, 50]], [1, 1, 3, 3], 4);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[BX0, BY0, 0], [BX1, BY1, 0], [BX1, BY0, 0], [BX0, BY1, 0], [-40, 0, BZ + 52], [40, 0, BZ + 52]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(BX0, BY0, BX1, BY1, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, BZ));

  const farB = mk("path", { class: "lo" }, g);
  const nearB = mk("path", { class: "sil hi" }, g), edge = mk("path", { class: "nf lo" }, g);
  const hand = [mk("path", { class: "sil" }, g), mk("path", { class: "sil" }, g)];
  const th = spring(REST);
  let last = NaN;

  // roll: the arc's centre slides R·θ along the board, the shape turns θ about it
  function at(th, u, w, y) {
    const cu = -R * th, du = u, dw = w - R, c = Math.cos(th), s = Math.sin(th);
    return P(cu + du * c - dw * s, y, BZ + R + du * s + dw * c);
  }
  function draw(t) {
    if (t === last) return;
    last = t;
    const face = (pts, y) => pts.map(([u, w]) => at(t, u, w, y));
    farB.setAttribute("d", poly(face(blade, -T)));
    nearB.setAttribute("d", poly(face(blade, T)));
    edge.setAttribute("d", poly(face(blade.slice(0, 17).concat(blade.slice(0, 17).reverse().map(([u, w]) => [u, w + 1.6])), T)));
    [-30, 30].forEach((c, i) => hand[i].setAttribute("d", poly(hull(face(post(c), -HT).concat(face(post(c), HT))))));
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(th.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BZ);
    if (x < BX0 - 4 || x > BX1 + 4 || y < BY0 - 30 || y > BY1 + 6) return leave();
    const f = clamp(x / 44, -1, 1);
    th.t = -f * reach;
    read.textContent = f < -0.25 ? "left" : f > 0.25 ? "right" : "mid";
    B.wake();
  }
  function leave() { th.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "pestleboard",
  means: "A mezzaluna on a chopping board: the curved blade rolls toward the end of the board under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.2, 0.42, 0.55],
  tour: [[110, 190], [265, 231], [200, 205], null],
  mount,
});

butterchurn2.code:
/**
 * Butter curler: a block of butter with a curler drawn across its top, a
 * hooked blade on a slanted handle. The pointer's place along the block
 * pulls the curler there; the shaving rolls up in front of the hook, the
 * curl growing with the distance pulled, and a scraped track stays behind.
 * At rest the curler is part way along, its curl bright. The slider is how
 * thick the curl rolls.
 *
 * The pattern: one part following the pointer (spring), hit on a fixed plane.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rings, prism, facing, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = -40, X1 = 40, Y0 = -18, Y1 = 18, TOP = 22, START = 34, END = -30, REST = 8, W = 8;
const disc = (r, n = 20) => Array.from({ length: n }, (_, i) => [r * Math.cos((i / n) * 2 * Math.PI), r * Math.sin((i / n) * 2 * Math.PI)]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let thick = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[X0, Y0, 0], [X1, Y1, 0], [X1, Y0, 0], [X0, Y1, 0], [END - 14, 0, TOP + 20], [START + 44, 0, TOP + 34]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(X0, Y0, X1, Y1, 5, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, TOP));

  const track = mk("path", { class: "nf lo" }, g), curl = mk("path", { class: "sil hi" }, g), turn = mk("path", { class: "nf lo" }, g);
  const blade = mk("path", { class: "sil" }, g), handle = mk("path", { class: "sil" }, g);
  const cx = spring(REST);
  let last = NaN;
  // a round section in the x–z plane, given width along y
  const roll = (x, z, r, w) => hull(disc(r, 24).flatMap(([a, b]) => [P(x + a, -w, z + b), P(x + a, w, z + b)]));
  function draw(c) {
    if (c === last) return;
    last = c;
    const pulled = clamp((START - c) / (START - END), 0, 1), r = 2 + thick * pulled;
    track.setAttribute("d", poly([P(c, -W, TOP), P(START, -W, TOP), P(START, W, TOP), P(c, W, TOP)]));
    curl.setAttribute("d", poly(roll(c - r - 1, TOP + r, r, W - 1)));
    const ring = disc(r * 0.55, 16).map(([a, b]) => P(c - r - 1 + a, W - 1, TOP + r + b));
    turn.setAttribute("d", poly(ring));
    // the hook: a curved blade standing on the butter, opening toward the curl
    const hook = [];
    for (let i = 0; i <= 8; i++) { const t = (i / 8) * Math.PI * 0.9; for (const y of [-W, W]) hook.push(P(c + 3 - 4 * Math.cos(t), y, TOP + 5 * Math.sin(t) + 4 * (i / 8))); }
    blade.setAttribute("d", poly(hull(hook)));
    const cap = (x, z) => disc(3.2, 12).flatMap(([a, b]) => [P(x + a, b, z - 2.5), P(x + a, b, z + 2.5)]);
    handle.setAttribute("d", poly(hull(cap(c + 6, TOP + 9).concat(cap(c + 42, TOP + 31)))));
  }

  const B = register(stage, (dt) => { const m = stepS(cx, dt); draw(cx.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TOP);
    if (x < X0 - 6 || x > X1 + 6 || y < Y0 - 10 || y > Y1 + 10) return leave();
    cx.t = clamp(x, END, START);
    const f = (START - cx.t) / (START - END);
    read.textContent = "curl " + Math.round(f * 100);
    B.wake();
  }
  function leave() { cx.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { thick = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "butterchurn2",
  means: "A butter curler pulled across a block of butter: the shaving rolls into a curl that grows the further the pointer pulls it.",
  rules: [1, 3, 5, 8],
  range: [5, 9, 12],
  tour: [[126, 134], [175, 165], [215, 200], null],
  mount,
});

sushimould.code:
/**
 * Rice mould: an onigiri press, a rounded triangular frame standing open
 * on a small tray, and the triangular presser that fits inside it, with a
 * knob on top. The pointer over the mould lifts the presser up out of the
 * frame, showing the rice packed inside; leaving presses it back down. At
 * rest the presser sits half pressed, its plate bright. The slider is the lift.
 *
 * The pattern: one part answering hover with a lift (tween), hit on the ground.
 */
const {
  Cam, fillet, fit, hull, open, poly, proj, unproj, tset, tval, tween, tdone,
  disposer, mk, pointer, register,
} = HL;

const tri = (R, rr, rot = 15) => fillet([0, 120, 240].map((a) => { const t = ((a + rot) * Math.PI) / 180; return [R * Math.cos(t), R * Math.sin(t)]; }), [rr, rr, rr], 6);
const H = 20, REST = 16, TH = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, tri(46, 12).map(([x, y]) => [x, y, 0]).concat(tri(30, 7).map(([x, y]) => [x, y, 3 + H + 30 + TH + 12])), 200, 168);
  const P = proj(C);
  const at = (pts, z) => pts.map(([x, y]) => P(x, y, z));
  const body = (pts, z0, z1, cls = "sil") => mk("path", { class: cls, d: poly(hull(at(pts, z0).concat(at(pts, z1)))) }, g);
  const g = mk("g", {}, svg);

  // tray, then the frame with its open top, then the rice mound inside
  const tray = tri(46, 12), outer = tri(36, 9), inner = tri(31, 7), rice = tri(27, 7);
  body(tray, 0, 3);
  mk("path", { class: "nf lo", d: poly(at(tri(44, 11), 3)) }, g);
  body(outer, 3, 3 + H);
  mk("path", { d: poly(at(inner, 3 + H)) }, g);
  mk("path", { class: "nf lo", d: poly(hull(at(rice, 3 + H - 2).concat(at(tri(18, 6), 3 + H + 5)))) }, g);

  // the presser: a plate a little smaller than the opening, a stem and a knob
  const plate = mk("path", { class: "sil hi" }, g), crease = mk("path", { class: "nf lo" }, g);
  const stem = mk("path", { class: "sil" }, g), knob = mk("path", { class: "sil" }, g);
  const disc = (r) => Array.from({ length: 24 }, (_, i) => [r * Math.cos((i / 24) * 2 * Math.PI), r * Math.sin((i / 24) * 2 * Math.PI)]);
  const z = tween(REST);
  let last = NaN;
  function draw(lv) {
    if (lv === last) return;
    last = lv;
    const z0 = 3 + H - REST + lv;
    plate.setAttribute("d", poly(hull(at(tri(29.5, 7), z0).concat(at(tri(29.5, 7), z0 + TH)))));
    crease.setAttribute("d", open(at(tri(27.5, 6), z0 + TH)));
    stem.setAttribute("d", poly(hull(at(disc(3), z0 + TH).concat(at(disc(3), z0 + TH + 7)))));
    knob.setAttribute("d", poly(hull(at(disc(7), z0 + TH + 7).concat(at(disc(6), z0 + TH + 12)))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  let act = null;
  function set(a) {
    if (a === act) return;
    act = a;
    tset(z, a ? REST + lift : REST, performance.now(), 0);
    read.textContent = a ? "lift" : "rest";
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 3 + H);
    set(Math.hypot(x, y) < 46);
  }
  set(false);
  bag.add(pointer(stage, { move, leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; if (act) { act = null; set(true); } }, destroy: bag.dispose };
}

hairline({
  name: "sushimould",
  means: "An onigiri mould on its tray: the pointer lifts the triangular presser out of the frame to show the rice packed inside.",
  rules: [1, 3, 5, 6],
  range: [14, 26, 30],
  tour: [[228, 189], [250, 200], [205, 180], null],
  mount,
});

appleslicer.code:
/**
 * Apple corer: a round slicer, a ring of eight blades around a coring tube,
 * with a handle out to each side, held over an apple on a round board. The
 * pointer over the apple presses the slicer down onto it; leaving lifts it
 * again. At rest the slicer hangs high above the fruit, its ring bright.
 * The slider is how far it comes down.
 *
 * The pattern: one part answering hover with a press (tween), hit on the ground.
 */
const {
  Cam, fit, hull, open, poly, proj, seg, unproj, tset, tval, tween, tdone,
  disposer, mk, pointer, register,
} = HL;

const disc = (r, n = 32, cx = 0, cy = 0) => Array.from({ length: n }, (_, i) => [cx + r * Math.cos((i / n) * 2 * Math.PI), cy + r * Math.sin((i / n) * 2 * Math.PI)]);
const BZ = 4, AH = 34, RR = 23, UP = 74, TH = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let press = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-40, -40, 0], [40, 40, 0], [40, -40, 0], [-40, 40, 0], [-50, 0, UP + TH], [50, 0, UP + TH], [0, -50, UP + TH]], 200, 168);
  const P = proj(C);
  const at = (pts, z) => pts.map(([x, y]) => P(x, y, z));
  const g = mk("g", {}, svg);

  // the board, then the apple: stacked rings hulled into a round fruit, a dimple and a stem
  mk("path", { class: "sil", d: poly(hull(at(disc(40, 48), 0).concat(at(disc(40, 48), BZ)))) }, g);
  mk("path", { class: "nf lo", d: open(at(disc(38, 48), BZ).concat([at(disc(38, 48), BZ)[0]])) }, g);
  const fruit = [];
  for (let i = 0; i <= 8; i++) { const t = -0.35 + (i / 8) * 1.75; fruit.push(...at(disc(20 * Math.cos(t - 0.35) + 2, 24), BZ + AH * (0.5 + 0.5 * Math.sin(t - 0.35)))); }
  mk("path", { class: "sil", d: poly(hull(fruit)) }, g);
  mk("path", { class: "nf lo", d: poly(at(disc(5, 16), BZ + AH - 2)) + seg(P(0, 0, BZ + AH - 2), P(1.5, -1, BZ + AH + 6)) }, g);

  // the slicer: handles, the ring band, the blades and the coring tube
  const hands = mk("path", { class: "sil" }, g), ring = mk("path", { class: "sil hi" }, g);
  const hole = mk("path", { class: "nf lo" }, g), blades = mk("path", { class: "nf" }, g), core = mk("path", { class: "sil" }, g);
  const z = tween(UP);
  let last = NaN;
  function draw(z0) {
    if (z0 === last) return;
    last = z0;
    const bar = (s) => poly(hull(at(disc(3.2, 12, s * 30, 0), z0 + 1).concat(at(disc(3.2, 12, s * 46, 0), z0 + 1), at(disc(3.2, 12, s * 46, 0), z0 + 4), at(disc(3.2, 12, s * 30, 0), z0 + 4))));
    hands.setAttribute("d", bar(-1) + bar(1));
    ring.setAttribute("d", poly(hull(at(disc(RR, 40), z0).concat(at(disc(RR, 40), z0 + TH)))));
    hole.setAttribute("d", poly(at(disc(RR - 2.2, 40), z0 + TH)));
    let b = "";
    for (let k = 0; k < 8; k++) { const a = (k / 8) * 2 * Math.PI + 0.2; b += seg(P(5 * Math.cos(a), 5 * Math.sin(a), z0 + TH), P((RR - 2.2) * Math.cos(a), (RR - 2.2) * Math.sin(a), z0 + TH)); }
    blades.setAttribute("d", b);
    core.setAttribute("d", poly(hull(at(disc(5, 20), z0 - 2).concat(at(disc(5, 20), z0 + TH + 1)))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  let act = null;
  function set(a) {
    if (a === act) return;
    act = a;
    tset(z, a ? UP - press : UP, performance.now(), 0);
    read.textContent = a ? "press" : "rest";
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, BZ + AH / 2);
    set(Math.hypot(x, y) < 40);
  }
  set(false);
  bag.add(pointer(stage, { move, leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { press = v; if (act) { act = null; set(true); } }, destroy: bag.dispose };
}

