  name: "travelalarm",
  means: "A folding travel clock: over it, the lid holding the dial swings up on its back hinge to stand and face you.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[200, 228], [200, 138], [200, 297], null],
  mount,
});

lintbrush.code:
/**
 * Clothes brush: a long oval wooden back over a bed of bristle tufts. The
 * pointer over it rolls the brush over on its long axis, turning the
 * bristles up to face you, as if picked up to brush a coat. At rest it lies
 * tilted on its bristles and the back is bright; when the pointer plays, the
 * bristle bed is. The slider is how far it rolls.
 *
 * The pattern: one part turning about an axis (roll).
 */
const { Cam, fit, hull, poly, proj, rrect, tdone, tset, tval, tween, disposer, mk, pointer, register } = HL;

const L = 62, B = 19, BH = 12, TOP = 24, ZC = 12, REST = 18;
const back = rrect(-L, -B, L, B, B * 0.95, 6), bed = rrect(-L + 7, -B + 5, L - 7, B - 5, B - 6, 6);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-L, -B - 12, 0], [L, B + 12, 0], [L, -B - 12, 0], [-L, B + 12, 0], [0, 0, ZC + B + 30], [0, 0, ZC + B + 30]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const bristles = mk("g", {}, g), block = mk("g", {}, g);
  const bSil = mk("path", { class: "sil" }, bristles), tufts = mk("path", { class: "nf lo" }, bristles);
  const kSil = mk("path", { class: "sil" }, block), kTop = mk("path", { class: "nf lo" }, block);

  function draw(deg) {
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a), lift = 11 * Math.sin(Math.min(a, Math.PI / 2) * 1);
    const W = (x, y, z) => [x, y * c - (z - ZC) * s, ZC + lift + y * s + (z - ZC) * c];
    const Q = (x, y, z) => P(...W(x, y, z));
    const ring = (rr, z) => rr.map((q) => Q(q.u, q.v, z));
    kSil.setAttribute("d", poly(hull(ring(back, BH).concat(ring(back, TOP)))));
    const upTop = s * 0 - 0.61 * s + 0.5 * c > 0;
    kTop.setAttribute("d", poly(ring(rrect(-L + 2, -B + 2, L - 2, B - 2, B - 3, 6), upTop ? TOP : BH)));
    bSil.setAttribute("d", poly(hull(ring(bed, 0).concat(ring(bed, BH)))));
    const under = 0.61 * s - 0.5 * c > 0;
    let d = "";
    if (under) for (let i = 0; i < 9; i++) for (let j = -1; j <= 1; j++) {
      const x = -44 + i * 11, y = j * 7.5;
      d += poly(Array.from({ length: 10 }, (_, k) => { const t = (k / 10) * Math.PI * 2; return Q(x + 2.6 * Math.cos(t), y + 2.6 * Math.sin(t), 0); })) + " ";
    }
    tufts.setAttribute("d", d);
    // paint the part nearer the viewer last
    const v = (p) => 0.61 * p[0] + 0.61 * p[1] + 0.5 * p[2];
    if (v(W(0, 0, BH / 2)) > v(W(0, 0, (BH + TOP) / 2))) block.after(bristles); else bristles.after(block);
  }
  const tw = tween(REST);
  let last = NaN;
  const B2 = register(stage, (_dt, now) => { const x = tval(tw, now); if (x !== last) { last = x; draw(x); } return !tdone(tw, now); });
  bag.add(B2.unregister);

  const mid = P(0, 0, ZC);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? REST + 110 * amp : REST, performance.now(), 0);
    bSil.classList.toggle("hi", on);
    kSil.classList.toggle("hi", !on);
    read.textContent = on ? "brush" : "rest";
    B2.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => Math.hypot(sx - mid[0], sy - mid[1]) < 120;
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "lintbrush",
  means: "A wooden clothes brush: over it, the brush rolls over on its long axis to turn its bristle tufts up to you.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1],
  tour: [[200, 140], [285, 232], [115, 85], null],
  mount,
});

shawlpin.code:
/**
 * Shawlpin: a ring brooch lying flat, its band open at the front between two
 * knobbed terminals, a long pin hinged on the band's far side and laid across
 * it. The pin swings round its hinge toward the pointer on a spring. At rest
 * it lies a little off the centre line and is bright. The slider is how far
 * it may swing either way.
 *
 * The pattern: a continuous aim (a spring on one angle), read on the ground
 * plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, ringAt, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RO = 52, RI = 40, T = 4.5, L = 106, BASE = 45, REST = 64;
const HX = -46 * Math.SQRT1_2, HY = -46 * Math.SQRT1_2;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  const ext = [[-RO, -RO, 0], [RO, RO, 0], [RO, -RO, 0], [-RO, RO, 0]];
  for (let a = BASE - 50; a <= BASE + 50; a += 10) ext.push([HX + L * Math.cos(rad(a)), HY + L * Math.sin(rad(a)), T + 3]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the band: a flat ring, its hole drawn as the far inner wall showing through
  put(solid(g), prism(P, front, circ(RO, 64), circ(RO - 1.5, 64), 0, T));
  mk("path", { d: poly(ringAt(P, circ(RI, 64), T)) }, g);
  mk("path", { d: poly(ringAt(P, circ(RI, 64), 0)), class: "nf lo" }, g);
  // the gap at the front, and its two knobbed terminals
  for (const s of [-1, 1]) {
    const a = rad(BASE + s * 16), cx = (RO + RI) / 2 * Math.cos(a), cy = (RO + RI) / 2 * Math.sin(a);
    put(solid(g), prism(P, front, disc(cx, cy, 6.5), disc(cx, cy, 5), 0, T + 3));
  }
  mk("path", { d: poly(ringAt(P, disc(HX, HY, 6), T + 3).concat(ringAt(P, disc(HX, HY, 6), T)).reverse()), class: "nf lo" }, g);
  const pin = mk("path", { class: "sil hi" }, g);
  const loop = mk("path", { class: "nf" }, g);
  const sp = spring(REST);
  let last = NaN;

  function draw() {
    const a = sp.x;
    if (a === last) return;
    last = a;
    const ux = Math.cos(rad(a)), uy = Math.sin(rad(a)), z = T + 2;
    const head = ringAt(P, disc(HX, HY, 3.4, 16), z).concat(ringAt(P, disc(HX, HY, 3.4, 16), z + 2));
    const tip = [P(HX + L * ux, HY + L * uy, z), P(HX + L * ux, HY + L * uy, z + 1.2)];
    pin.setAttribute("d", poly(hull(head.concat(tip))));
    loop.setAttribute("d", poly(ringAt(P, disc(HX, HY, 1.6, 12), z + 2)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    const a = clamp(Math.atan2(y - HY, x - HX) * 180 / Math.PI, BASE - reach, BASE + reach);
    sp.t = a;
    read.textContent = (a >= BASE ? "+" : "") + Math.round(a - BASE) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "shawlpin",
  means: "A ring brooch lying flat: its long pin swings round the hinge on the far side of the band to point at the pointer.",
  rules: [1, 3, 5, 8],
  range: [20, 45, 50],
  tour: [[361, 179], [39, 179], [200, 262], null],
  mount,
