fanfold.code:
/**
 * Fanfold: a folding hand fan held upright, its sticks pinned at a rivet,
 * a pleated leaf across their tips. One guard stays put on the left; the
 * leading guard follows the pointer round the rivet on a spring, and every
 * stick between spreads evenly after it. At rest the fan is half open and
 * the leading guard is bright. The slider is how far it may open.
 *
 * The pattern: a continuous aim (a spring on one angle), read against the
 * rivet, which never moves.
 */
const {
  Cam, clamp, fit, poly, proj, seg, spring, stepS, rad,
  disposer, mk, pointer, register,
} = HL;

const R = 78, R1 = 34, N = 13, A0 = -82, REST = 8, H = 6;
const D = [Math.SQRT1_2, -Math.SQRT1_2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.35);
  const W = (r, a) => [D[0] * r * Math.sin(rad(a)), D[1] * r * Math.sin(rad(a)), H + r * Math.cos(rad(a))];
  const ext = [];
  for (let a = -90; a <= 90; a += 15) ext.push(W(R, a));
  ext.push([0, 0, 0]);
  fit(C, ext, 200, 168);
  const P = proj(C);
  const Q = (r, a) => P(...W(r, a));
  const g = mk("g", {}, svg);
  const leaf = mk("path", { class: "sil" }, g);
  const pleats = mk("path", { class: "nf lo" }, g);
  const sticks = mk("path", { class: "nf" }, g);
  const guard0 = mk("path", { class: "nf sil" }, g);
  const guard1 = mk("path", { class: "nf sil hi" }, g);
  const rivet = mk("circle", { r: 2.6, class: "dot m" }, g);
  const piv = Q(0, 0);
  rivet.setAttribute("cx", piv[0]); rivet.setAttribute("cy", piv[1]);
  const sp = spring(REST);
  let last = NaN;

  function draw() {
    const a1 = sp.x;
    if (a1 === last) return;
    last = a1;
    const angs = Array.from({ length: N }, (_, i) => A0 + ((a1 - A0) * i) / (N - 1));
    const outer = [], inner = [];
    angs.forEach((a, i) => {
      const half = i < N - 1 ? (a + angs[i + 1]) / 2 : null;
      outer.push(Q(R, a));
      if (half !== null) outer.push(Q(R - 3, half));
      inner.push(Q(R1, a));
      if (half !== null) inner.push(Q(R1 - 1.5, half));
    });
    leaf.setAttribute("d", poly(outer.concat(inner.reverse())));
    pleats.setAttribute("d", angs.slice(1, -1).map((a) => seg(Q(R1, a), Q(R, a))).join(""));
    sticks.setAttribute("d", angs.slice(1, -1).map((a) => seg(piv, Q(R1, a))).join(""));
    guard0.setAttribute("d", seg(Q(-8, A0), Q(R + 2, A0)));
    guard1.setAttribute("d", seg(Q(-8, a1), Q(R + 2, a1)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  // screen basis of the fan's plane, for reading the pointer's angle round the rivet
  const ex = Q(1, 90), ez = Q(1, 0);
  const bx = [ex[0] - piv[0], ex[1] - piv[1]], bz = [ez[0] - piv[0], ez[1] - piv[1]];
  const det = bx[0] * bz[1] - bx[1] * bz[0];

  function aim(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const dx = p[0] - piv[0], dy = p[1] - piv[1];
    const u = (dx * bz[1] - dy * bz[0]) / det, w = (bx[0] * dy - bx[1] * dx) / det;
    const a = clamp(Math.atan2(u, w) * 180 / Math.PI, -50, maxA);
    sp.t = a;
    read.textContent = Math.round(a - A0) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; }, destroy: bag.dispose };
}

hairline({
  name: "fanfold",
  means: "A folding hand fan held upright: its leading guard follows the pointer round the rivet and the pleated leaf spreads after it.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 90],
  tour: [[300, 131], [383, 241], [200, 90], null],
  mount,
});

paraso.code:
/**
 * Paraso: a lace parasol standing on its ferrule, a crook handle low on the
 * shaft and a scalloped canopy on eight ribs. The nearer the pointer comes
 * to the shaft, the wider the canopy opens, on a spring; leaving lets it
 * fall back half furled. The canopy's rim is bright at rest. The slider is
 * how wide the ribs may open.
 *
 * The pattern: a continuous reach (a spring on one angle), read on the
 * ground plane, which never moves.
 */
const {
  Cam, clamp, fit, hull, poly, open, proj, seg, unproj, spring, stepS, rad, lerp,
  disposer, mk, pointer, register,
} = HL;

const TOP = 128, LR = 72, NR = 8, CLOSED = 10, REST = 0.42;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 1.86);
  fit(C, [[-LR, -LR, TOP - 20], [LR, LR, TOP - 20], [LR, -LR, TOP - 20], [-LR, LR, TOP - 20], [0, 0, 0], [0, 0, TOP + 8]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const shaft = mk("path", { class: "nf sil" }, g);
  shaft.setAttribute("d", seg(P(0, 0, 0), P(0, 0, TOP + 8)));
  const crook = [];
  for (let i = 0; i <= 10; i++) { const t = rad(180 * i / 10); crook.push(P(-6 * Math.SQRT1_2 * (1 - Math.cos(t)), 6 * Math.SQRT1_2 * (1 - Math.cos(t)), 30 - 6 * Math.sin(t))); }
  mk("path", { d: open([P(0, 0, 34)].concat(crook)), class: "nf sil" }, g);
  const canopy = mk("path", { class: "sil hi" }, g);
  const lace = mk("path", { class: "nf lo" }, g);
  const ribs = mk("path", { class: "nf lo" }, g);
  const sp = spring(REST);
  let last = NaN;

  function draw() {
    const o = sp.x;
    if (o === last) return;
    last = o;
    const th = rad(lerp(CLOSED, maxT, o)), apex = P(0, 0, TOP);
    const tip = (phi, l = LR) => P(l * Math.sin(th) * Math.cos(phi), l * Math.sin(th) * Math.sin(phi), TOP - l * Math.cos(th));
    const edge = [], inner = [];
    for (let i = 0; i < NR; i++) {
      for (let j = 0; j < 6; j++) {
        const f = j / 6, phi = rad(360 * (i + f) / NR), sag = Math.sin(Math.PI * f) * 0.08;
        edge.push(tip(phi, LR * (1 - sag)));
        inner.push(tip(phi, LR * (0.88 - sag)));
      }
    }
    canopy.setAttribute("d", poly([apex].concat(edge)).length ? poly(hull([apex].concat(edge))) : "");
    const fr = (k) => { const phi = rad(360 * k / NR); return Math.cos(phi) + Math.sin(phi) > -0.3; };
    lace.setAttribute("d", open(inner.filter((_, k) => fr(k / 6))));
    let d = "";
    for (let i = 0; i < NR; i++) if (fr(i)) d += seg(apex, tip(rad(360 * i / NR)));
    ribs.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function reach(p) {
    if (!p) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
    const o = clamp(1.15 - r / 110, 0.12, 1);
    sp.t = o;
    read.textContent = Math.round(o * 100) + "%";
    B.wake();
  }
  reach(null);
  bag.add(pointer(stage, { move: reach, leave: () => reach(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "paraso",
  means: "A lace parasol standing on its tip: the nearer the pointer comes to the shaft, the wider its scalloped canopy opens on the ribs.",
  rules: [1, 3, 5, 8],
  range: [50, 70, 80],
  tour: [[330, 230], [200, 294], [90, 250], null],
  mount,
});

snuffbox.code:
/**
 * Snuff box: a flat pocket box with a shallow lid hinged along its back on a
 * long knuckle and a thumb catch at the front. The pointer lifts the lid open.
 *
 * The pattern: one part turning about a fixed axis, driven by a spring.
 */
const { Cam, fit, proj, unproj, hull, poly, clamp, r2, spring, stepS, mk, pointer, register, disposer } = HL;

const rz = (x0, y0, x1, y1, z) => [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]];
const box = (x0, y0, x1, y1, z0, z1) => [rz(x0, y0, x1, y1, z0), rz(x0, y0, x1, y1, z1)];
const alongX = (sec, x0, x1) => [x0, x1].map((x) => sec.map(([y, z]) => [x, y, z]));
const lathe = (cx, cy, prof, n = 20) => prof.map(([r, z]) => Array.from({ length: n }, (_, j) => { const t = (j / n) * 2 * Math.PI; return [cx + r * Math.cos(t), cy + r * Math.sin(t), z]; }));
