  [rodX(-16, 10, 0, 9, 1.2, 10), true, true, [worm]],
];
const REST = 0.75, HI = 1.8, HC = [30, 0, 6], RR = 75;
const ORDER = () => [0, 1, 2, 3];
const FITA = [0.75, 1.1, 1.5, 1.8];
const READ = (a) => Math.round(a / D) + "°";

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const parts = PARTS.map(([rings, smooth, mov, inner, hi]) => { const M = mesh(rings, smooth); M.mov = mov; M.inner = inner; M.hi = hi === undefined ? mov : hi; return M; });
  const all = [];
  for (const M of parts) for (const a of FITA) for (const p of M.pts) all.push(M.mov ? XF(a)(p) : p);
  const C1 = Cam(45, 0.5, 1), P1 = proj(C1), s1 = all.map((p) => P1(...p));
  const w = Math.max(...s1.map((q) => q[0])) - Math.min(...s1.map((q) => q[0])), h = Math.max(...s1.map((q) => q[1])) - Math.min(...s1.map((q) => q[1]));
  const C = Cam(45, 0.5, Math.min(372 / w, 296 / h));
  fit(C, all, 200, 162);
  const P = proj(C), o = P(0, 0, 0), a1 = P(1, 0, 0), b1 = P(1, 1, 0);
  const s0 = (a1[0] - o[0]) * (b1[1] - o[1]) - (a1[1] - o[1]) * (b1[0] - o[0]);
  const g = mk("g", {}, svg);
  const els = parts.map((M) => {
    const grp = mk("g", {}, g);
    const el = { grp, sil: mk("path", { class: "sil" }, grp), ed: mk("path", { class: "nf" }, grp) };
    if (M.inner) el.in = mk("path", { class: "nf lo" }, grp);
    if (M.hi) el.sil.classList.add("hi");
    return el;
  });
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const xf = XF(a);
    parts.forEach((M, i) => drawMesh(P, s0, M, M.mov ? xf : same, els[i]));
    ORDER(a).forEach((i) => g.appendChild(els[i].grp));
  }
  const sp = spring(REST);
  const B = register(stage, (dt) => { const mv = stepS(sp, dt); draw(sp.x); return mv; });
  bag.add(B.unregister);
  draw(REST);
  function aim(p) {
    let t = 0;
    if (p) { const [wx, wy] = unproj(C, p[0], p[1], HC[2]); t = clamp((RR - Math.hypot(wx - HC[0], wy - HC[1])) / (RR * 0.55), 0, 1); }
    sp.t = REST + t * (MAX - REST);
    read.textContent = t > 0 ? READ(sp.t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { MAX = v; }, destroy: bag.dispose };
}

hairline({
  name: "pocketknife",
  means: "A waiter's corkscrew knife: the pointer swings the long arm with its coiled worm out of the slim handle on the pivot.",
  rules: [1, 3, 5, 6],
  range: [1.1, 1.5, 1.8],
  tour: [[117, 177], [198, 229], [36, 172], null],
  mount,
});

keyring.code:
/**
 * Key ring: a split ring hung from a wall peg, three keys threaded on it.
 * The pointer's side is where the ring swings: the whole ring tilts toward
 * it on a spring, and the keys swing further, lagging on their own spring.
 * The key nearest the pointer is bright; at rest the middle key is. The
 * slider is how far the ring swings.
 *
 * The pattern: a continuous swing (spotlights' spring, on an angle); the
 * key is picked from its rest position, which never moves.
 */
const {
  Cam, circ, clamp, fillet, fit, facing, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 13, ATT = -2 * R - 2, REST = -9, FAN = [-16, 3, 21], OFF = [-2.5, 1, 3.5];
const HN = Math.hypot(1, 0.55), H = [1 / HN, -0.55 / HN], N = [0.55 / HN, 1 / HN];
const BLADE = [[-4.6, 12], [4.6, 12], [4.6, 16], [2.6, 16], [2.6, 21], [4.4, 23], [2.6, 25.5], [4.4, 28.5], [2.6, 30.5],
  [4.6, 33.5], [2.6, 36], [2.6, 42], [0, 46], [-2.6, 43.5], [-2.6, 16], [-4.6, 16]];
const BR = BLADE.map(() => 0.7);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  // world point from assembly-local (u along the hanging plane, w up), at depth off
  const W = (u, w, off) => [H[0] * u + N[0] * off, H[1] * u + N[1] * off, w];
  const rot = (u, w, a) => [u * Math.cos(a) - w * Math.sin(a), u * Math.sin(a) + w * Math.cos(a)];
  // a key point (t across, s down its length) under swing a and key angle b
  const kp = (k, t, s, a, b) => {
    const f = rad(FAN[k]) + b, u = t * Math.cos(f) + s * Math.sin(f), w = ATT + t * Math.sin(f) - s * Math.cos(f);
    return rot(u, w, a);
  };
  const ext = [];
  for (const sg of [-1, 1]) {
    const a = rad(REST + sg * 30), b = rad(sg * 12);
    for (let k = 0; k < 3; k++) for (const [t, s] of [[-7.5, 7], [7.5, 7], [0, 46], [4.6, 30]]) ext.push(W(...kp(k, t, s, a, b), OFF[k]));
  }
  ext.push(W(-8, 10, 0), W(8, 10, 0));
  const C = Cam(45, 0.5, 3.65);
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the peg block on the wall, and its pin
  const [br, bi] = rings(-5, -3.5, 5, 3.5, 2.5, 1);
  put(solid(g), prism(P, front, br.map((q) => ({ ...q, v: q.v - 6 })), bi.map((q) => ({ ...q, v: q.v - 6 })), 2, 10));
  mk("path", { d: seg(P(0, -3, 4), P(0, 0, -1.2)), class: "nf" }, g);

  const keyEls = [0, 1, 2].map(() => ({ back: mk("path", { class: "lo" }), body: mk("path", { class: "sil" }), bow: mk("path", { class: "sil" }), hole: mk("path", { class: "nf lo" }) }));
  const ringEls = { outer: mk("path", { class: "nf sil" }), inner: mk("path", { class: "nf lo" }) };
  // paint far to near: key 0, the ring, keys 1 and 2
  const order = [keyEls[0], ringEls, keyEls[1], keyEls[2]];
  for (const o of order) for (const el of Object.values(o)) g.appendChild(el);

  const A = spring(rad(REST)), K = spring(0, { k: 70, c: 9 });
  let last = "", act = -1;

  function draw() {
    const key = A.x.toFixed(4) + "," + K.x.toFixed(4);
    if (key === last) return;
    last = key;
    const a = A.x, b = K.x, cw = -R - 2;
    const ringPath = (r) => poly(circ(r, 40).map((q) => P(...W(...rot(q.u, cw + q.v, a), 0))));
    ringEls.outer.setAttribute("d", ringPath(R + 1.3));
    ringEls.inner.setAttribute("d", ringPath(R - 1.3));
    keyEls.forEach((e, k) => {
      const pt = (t, s, off) => P(...W(...kp(k, t, s, a, b), OFF[k] + off));
      const blade = fillet(BLADE.map(([t, s]) => [t, s]), BR, 3);
      const bow = circ(7.5, 28).map((q) => [q.u, 7 + q.v]);
      e.back.setAttribute("d", poly(blade.map(([t, s]) => pt(t, s, -1.3))) + poly(bow.map(([t, s]) => pt(t, s, -1.3))));
      e.body.setAttribute("d", poly(blade.map(([t, s]) => pt(t, s, 0))));
      e.bow.setAttribute("d", poly(bow.map(([t, s]) => pt(t, s, 0))));
      e.hole.setAttribute("d", poly(circ(2.4, 16).map((q) => pt(q.u, 3.6 + q.v, 0))));
    });
  }

  const B = register(stage, (dt) => { const m1 = stepS(A, dt), m2 = stepS(K, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  const cx0 = P(0, 0, 0)[0];
  const tips = [0, 1, 2].map((k) => P(...W(...kp(k, 0, 30, rad(REST), 0), OFF[k]))[0]);
  function aim(sx) {
    if (sx == null) { A.t = rad(REST); K.t = 0; act = -1; }
    else {
      const d = clamp((sx - cx0) / 30, -1, 1);
      A.t = rad(REST + d * 30 * reach); K.t = rad(d * 12 * reach);
      let bd = Infinity;
      tips.forEach((x, k) => { if (Math.abs(x - sx) < bd) { bd = Math.abs(x - sx); act = k; } });
    }
    keyEls.forEach((e, k) => { const on = k === (act < 0 ? 1 : act); e.body.classList.toggle("hi", on); e.bow.classList.toggle("hi", on); });
    read.textContent = act < 0 ? "rest" : `key ${act + 1} · ${Math.round(A.t * 180 / Math.PI)}°`;
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => aim(p[0]), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "keyring",
  means: "A key ring on a wall peg: it swings toward the pointer's side, the keys swinging further, and the nearest key lights.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[151, 250], [300, 262], [205, 245], null],
  mount,
});

envelopemoist.code:
/**
 * Envelope moistener: a low desk well holding a wet sponge, with a hinged
 * lid along its back edge. The pointer over it swings the lid up and back,
 * showing the sponge an envelope flap is drawn across. At rest the lid sits
 * ajar, bright. The slider is how far the lid swings.
 */
const { Cam, clamp, fit, hull, poly, proj, rad, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

const W = 60, D = 40, H = 18, T = 5;
const box = (P, x0, y0, z0, x1, y1, z1, f) => {
  const pts = [];
  for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) pts.push(P(...(f ? f(x, y, z) : [x, y, z])));
  return poly(hull(pts));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0], [0, -6, H + D + 4], [W, -6, H + D + 4]], 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g);
  mk("path", { d: box(P, 0, 0, 0, W, D, H), class: "sil" }, g);
  mk("path", { d: box(P, 4, 4, H - 0.5, W - 4, D - 4, H + 0.5), class: "nf lo" }, g);
  mk("path", { d: box(P, 7, 7, H, W - 7, D - 7, H + 4), class: "sil" }, g);
  const front = mk("g", {}, g);
  const lid = mk("path", { class: "sil hi" });
  const o = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const th = rad(10 + t * (swing - 10)), c = Math.cos(th), s = Math.sin(th);
    const f = (x, y, z) => { const dy = y + 1, dz = z - H; return [x, -1 + dy * c - dz * s, H + dy * s + dz * c]; };
    lid.setAttribute("d", box(P, -1, -1, H, W + 1, D + 1, H + T, f));
    (th > rad(70) ? back : front).appendChild(lid);
  }
  const B = register(stage, (_dt, now) => { draw(tval(o, now)); return !tdone(o, now); });
  bag.add(B.unregister);
  const ctr = P(W / 2, D / 2, H);
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(o, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "lid " + Math.round(swing) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setOn(Math.abs(sx - ctr[0]) < 120 && Math.abs(sy - ctr[1]) < 90), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = clamp(v, 40, 120); last = NaN; if (on) read.textContent = "lid " + Math.round(swing) + "°"; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "envelopemoist",
  means: "An envelope moistener: the pointer over it swings the hinged lid up and back to show the wet sponge inside.",
  rules: [1, 3, 5, 6],
  range: [40, 100, 120],
  tour: [[194, 192], [172, 199], [215, 305], null],
  mount,
});

thermos.code:
/**
 * Flask: a vacuum flask standing on the ground, its cup screwed on as a lid.
 * The pointer over the flask takes the cup off: it lifts, swings out and
 * lands upright beside the flask, showing the stopper. At rest the cup sits
 * a little loose on top, bright. The slider is how far it is set down.
 */
const {
  Cam, circ, fit, facing, lerp, prism, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 18.5, H = 54, CR = 20, CH = 20, AWAY = 41;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let far = value;
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[-CR, -CR, 0], [AWAY + CR, CR, 0], [CR, CR, 0], [0, 0, H + 6 + CH + 14], [AWAY, 0, CH]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, R), disc(0, 0, R - 1.6), 0, H));
  put(solid(g), prism(P, front, disc(0, 0, R + 0.6), disc(0, 0, R - 1), H - 12, H - 9));
  put(solid(g), prism(P, front, disc(0, 0, 8), disc(0, 0, 6.5), H, H + 6));
  put(solid(g), prism(P, front, disc(0, 0, 3), null, H + 6, H + 8));
  const cup = solid(g);
  cup.sil.classList.add("hi");
  const lip = solid(g);
  const t = tween(0.12);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const x = lerp(0, AWAY * far, v), z0 = (H + 1 + v * 2) * (1 - v) + Math.sin(v * Math.PI) * 18;
    // the cup sits upside-down as a lid, and stands upright once set down: same hull either way
    put(cup, prism(P, front, disc(x, 0, CR), disc(x, 0, CR - 1.6), z0, z0 + CH));
    put(lip, prism(P, front, disc(x, 0, CR + 0.5), disc(x, 0, CR - 0.8), z0 + (v > 0.5 ? CH - 3 : 0), z0 + (v > 0.5 ? CH : 3)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(t, now)); return !tdone(t, now); });
  bag.add(B.unregister);

  const a = P(-R, R, 0), b = P(R, -R, 0), top = P(0, 0, H + CH + 4), bot = P(0, 0, 0);
  const hit = ([sx, sy]) => sx > Math.min(a[0], b[0]) - 6 && sx < Math.max(a[0], b[0]) + 6 && sy > top[1] - 14 && sy < bot[1] + 12;
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(t, o ? 1 : 0.12, performance.now(), 0);
    read.textContent = o ? "cup off" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { far = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "thermos",
  means: "A vacuum flask with its cup on as a lid: the pointer takes the cup off and sets it down beside the flask.",
  rules: [1, 4, 5, 8],
  range: [0.7, 1, 1],
  tour: [[156, 200], [156, 135], [150, 100], null],
  mount,
});

walkingstick.code:
/**
 * Shooting stick: a walking stick with a spike and a ground disc at its
 * foot, and at its head a handle of two leaves. The pointer over the stick
 * opens the leaves out flat into a seat, staggered one after the other. At
 * rest they hang slightly apart, the near leaf bright. The slider is the stagger.
 */
const {
  Cam, circ, fillet, fit, facing, hull, poly, prism, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TOP = 92, W = 20, D = 30, REST = 0.5, OPEN = Math.PI / 2;
const disc = (r, z, n = 32) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-D - 2, -W, TOP + 3], [D + 2, W, TOP + 3], [0, 0, 0], [-D, 0, TOP - D], [14, 14, 0], [-14, -14, 0]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(12, 40), circ(10.5, 40), 10, 12));
  mk("path", { class: "nf", d: poly(hull([P(-1.2, 0, 10), P(1.2, 0, 10), P(0, 0, 0)])) }, g);
  const far = mk("path", { class: "sil" }, g);
  put(solid(g), prism(P, front, circ(2.4, 20), null, 12, TOP));
  put(solid(g), prism(P, front, circ(3.6, 20), circ(2.4, 20), TOP - 4, TOP));
  const near = mk("path", { class: "sil" }, g);
  const leaves = [{ s: -1, el: far, t: tween(REST), last: NaN }, { s: 1, el: near, t: tween(REST), last: NaN }];
  const shape = fillet([[0, -W / 2], [D, -W], [D, W], [0, W / 2]], [2, 9, 9, 2], 4);
  function draw(L, f) {
    if (f === L.last) return;
    L.last = f;
    const pts = [];
    for (const off of [0, 2.2]) for (const [d, w] of shape) pts.push(P(L.s * (d * Math.sin(f) + off * Math.cos(f)), w, TOP - d * Math.cos(f) + off * Math.sin(f)));
    L.el.setAttribute("d", poly(hull(pts)));
  }
  const B = register(stage, (_dt, now) => { let m = false; for (const L of leaves) { draw(L, tval(L.t, now)); if (!tdone(L.t, now)) m = true; } return m; });
  bag.add(B.unregister);

  const a = P(0, 0, TOP + 4), b = P(0, 0, 0);
  const hit = ([sx, sy]) => Math.abs(sx - a[0]) < 60 && sy > a[1] - 30 && sy < b[1] + 10;
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    const now = performance.now();
    leaves.forEach((L, i) => tset(L.t, o ? OPEN : REST, now, (o ? i : 1 - i) * stag));
    near.classList.add("hi");
    read.textContent = o ? "seat" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stag = v; }, destroy: bag.dispose };
}

hairline({
  name: "walkingstick",
  means: "A shooting stick: the pointer over it opens the two leaves of its handle out flat into a seat, one after the other.",
  rules: [1, 2, 5, 8],
  range: [0, 60, 120],
  tour: [[219, 247], [219, 145], [219, 95], null],
  mount,
});

compass3.code:
/**
 * Map measurer: a folded map with a route on it and an opisometer standing on
 * the route, a round dial on edge with a needle, a small tracing wheel below
 * and a grip above. The pointer along the map rolls the measurer to that
 * point; its wheel and needle turn with the distance. At rest it stands a
 * third of the way along, its dial bright. The slider is the needle's gearing.
 *
 * The pattern: a continuous answer, a spring on the pointer's ground x.
 */
const { Cam, clamp, rings, prism, fit, hull, poly, open, seg, proj, unproj, facing, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const MX = 120, MY = 26, R = 15, WR = 4.5, ZC = 2 + 2 * WR + R + 1, X0 = 34;
const disc = (x, z, r, y, n = 32) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push([x + r * Math.cos(t), y, z + r * Math.sin(t)]); } return o; };
const tube = (x, z0, z1, r, n = 14) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push([x + r * Math.cos(t), r * Math.sin(t), z0], [x + r * Math.cos(t), r * Math.sin(t), z1]); } return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gear = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-4, -MY, 0], [MX + 4, MY, 0], [MX + 4, -MY, 0], [-4, MY, 0], [8, 0, ZC + R + 26], [MX - 8, 0, ZC + R + 26]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-4, -MY, MX + 4, MY, 3, 1.2);
  put(solid(g), prism(P, front, mr, mi, 0, 2));
  mk("path", { class: "nf lo", d: seg(P(MX / 2, -MY, 2), P(MX / 2, MY, 2)) + seg(P(MX / 4, -MY, 2), P(MX / 4, MY, 2)) + seg(P((3 * MX) / 4, -MY, 2), P((3 * MX) / 4, MY, 2)) }, g);
  const route = [];
  for (let x = 6; x <= MX - 6; x += 2) route.push(P(x, 0, 2));
  mk("path", { class: "nf dash", d: open(route) }, g);
  const wheel = solid(g), spokes = mk("path", { class: "nf lo" }, wheel.g);
  const grip = solid(g), dial = solid(g), needle = mk("path", { class: "nf" }, dial.g);
  dial.sil.classList.add("hi");
  const sp = spring(X0);
  let last = NaN;

  function draw(x) {
    if (x === last) return;
    last = x;
    const roll = -x / WR, turn = (x / 40) * gear;
    wheel.sil.setAttribute("d", poly(hull(disc(x, 2 + WR, WR, 1.2, 20).concat(disc(x, 2 + WR, WR, -1.2, 20)).map((p) => P(...p)))));
    spokes.setAttribute("d", [0, 1, 2].map((k) => { const a = roll + (k * Math.PI * 2) / 3; return seg(P(x, 1.3, 2 + WR), P(x + (WR - 1) * Math.cos(a), 1.3, 2 + WR + (WR - 1) * Math.sin(a))); }).join(""));
    grip.sil.setAttribute("d", poly(hull(tube(x, ZC + R - 2, ZC + R + 8, 2).concat(tube(x, ZC + R + 8, ZC + R + 24, 3.6)).map((p) => P(...p)))));
    dial.sil.setAttribute("d", poly(hull(disc(x, ZC, R, 2.2).concat(disc(x, ZC, R, -2.2)).map((p) => P(...p)))));
    dial.cr.setAttribute("d", poly(disc(x, ZC, R - 2, 2.3).map((p) => P(...p))));
    const a = Math.PI / 2 - turn;
    needle.setAttribute("d", seg(P(x, 2.4, ZC), P(x + (R - 4) * Math.cos(a), 2.4, ZC + (R - 4) * Math.sin(a))));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 2);
    if (x < -4 || x > MX + 4 || Math.abs(y) > MY + 30) return leave();
    sp.t = clamp(x, 8, MX - 8);
    read.textContent = Math.round(sp.t / 4) + " km";
    B.wake();
  }
  function leave() { sp.t = X0; read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gear = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "compass3",
  means: "A map measurer on a route: it rolls to the point under the pointer, its wheel and dial needle turning with the distance.",
  rules: [1, 3, 5, 8],
