  tour: [[138, 163], [175, 120], [200, 200], null],
  mount,
});

bellows3.code:
/**
 * Toasting fork: a long fork with a turned grip, a telescoping shaft and a
 * three-tined head holding a slice of bread. At rest the shaft is drawn in,
 * the head bright. The pointer over the fork slides the shaft out, carrying
 * the head and the bread away towards the fire. The slider is the reach.
 *
 * The pattern: one part answering a hover, hit on the ground plane.
 */
const { Cam, fit, hull, poly, open, seg, proj, unproj, tween, tset, tval, tdone, disposer, mk, pointer, register, solid } = HL;

const Z = 12, G = 30, S1 = 46, E0 = 8;
const tube = (x0, x1, r, n = 16) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push([x0, r * Math.cos(t), Z + r * Math.sin(t)], [x1, r * Math.cos(t), Z + r * Math.sin(t)]); } return o; };
const slab = (x, w, h, d) => [[x, -w, Z - h], [x, w, Z - h], [x, w, Z + h], [x, -w, Z + h], [x + d, -w, Z - h], [x + d, w, Z - h], [x + d, w, Z + h], [x + d, -w, Z + h]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.7);
  const far = G + S1 + 60 + 34;
  fit(C, [[0, -14, Z - 14], [far, 14, Z + 14], [0, 14, Z + 14], [far, -14, Z - 14], [0, 0, 0], [far, 0, 0]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const grip = solid(g), rings_ = mk("path", { class: "nf lo" }, grip.g);
  grip.sil.setAttribute("d", poly(hull(tube(0, G, 4.2).concat(tube(2, G - 2, 4.8)).map((p) => P(...p)))));
  rings_.setAttribute("d", [8, 15, 22].map((x) => open(tube(x, x, 4.6).filter((_, i) => i % 2 === 0).slice(0, 9).map((p) => P(...p)))).join(""));
  const outer = solid(g);
  outer.sil.setAttribute("d", poly(hull(tube(G, G + S1, 2).map((p) => P(...p)))));
  const inner = solid(g), head = solid(g), tines = mk("path", { class: "nf" }, head.g), bread = solid(g);
  head.sil.classList.add("hi");
  const tw = tween(E0);
  let last = NaN;

  function draw(e) {
    if (e === last) return;
    last = e;
    const x0 = G + S1 - 6, x1 = G + S1 + e, hx = x1 + 3;
    inner.sil.setAttribute("d", poly(hull(tube(x0, x1, 1.3).map((p) => P(...p)))));
    head.sil.setAttribute("d", poly(hull(slab(x1, 9, 1.2, 3).map((p) => P(...p)))));
    tines.setAttribute("d", [-8, 0, 8].map((y) => seg(P(hx, y, Z), P(hx + 22, y, Z))).join(""));
    bread.sil.setAttribute("d", poly(hull(slab(hx + 12, 13, 13, 4).map((p) => P(...p)))));
    bread.cr.setAttribute("d", poly([[-11, -11], [11, -11], [11, 9], [7, 12], [-7, 12], [-11, 9]].map(([y, z]) => P(hx + 16.2, y, Z + z))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, Z); return x > -6 && x < G + S1 + E0 + 40 && Math.abs(y) < 22; };
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? reach : E0, performance.now(), 0);
    read.textContent = on ? "reach" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "bellows3",
  means: "A toasting fork with a telescoping shaft: under the pointer the shaft slides out, carrying the bread away.",
  rules: [1, 4, 5, 8],
  range: [30, 50, 60],
  tour: [[66, 95], [140, 130], [210, 166], null],
  mount,
});

coalscuttle.code:
/**
 * Coal scuttle: a boxy fireside scuttle on a plinth, with a domed lid hinged
 * along its back edge and a knob at the front. At rest the lid sits ajar,
 * bright. The pointer over the scuttle swings the lid up and back on its
 * hinge to show the opening. The slider is how far the lid opens.
 *
 * The pattern: one part answering a hover, hit on the rest pose.
 */
const { Cam, circ, rrect, rings, prism, fit, hull, poly, proj, rad, facing, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const L = 44, Wd = 32, BZ = 36, HZ = BZ + 1;
const at = (ring, z, ox = 0, oy = 0) => ring.map((q) => [q.u + ox, q.v + oy, z]);
const roty = (p, a, cx, cz) => { const dx = p[0] - cx, dz = p[2] - cz, c = Math.cos(a), s = Math.sin(a); return [cx + dx * c + dz * s, p[1], cz - dx * s + dz * c]; };
const LID = [at(rrect(-1, -1, L + 1, Wd + 1, 5, 8), HZ), at(rrect(-1, -1, L + 1, Wd + 1, 5, 8), HZ + 3), at(rrect(5, 4, L - 6, Wd - 4, 6, 8), HZ + 9)];
const LIDCR = at(rrect(6.4, 5.4, L - 7.4, Wd - 5.4, 4.6, 8), HZ + 9);
const KNOB = [at(circ(2.4, 14), HZ + 2, L - 2, Wd / 2), at(circ(2.4, 14), HZ + 6, L + 2.5, Wd / 2)];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 3.05);
  const pose = (p, a) => roty(p, -a, 0, HZ);
  const ext = [[-3, -3, 0], [L + 3, Wd + 3, 0], [L + 3, -3, 0], [-3, Wd + 3, 0]];
  for (const a of [0, rad(125)]) for (const r of LID.concat(KNOB)) for (const p of r) ext.push(pose(p, a));
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-3, -3, L + 3, Wd + 3, 4, 1.4);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  const [br, bi] = rings(0, 0, L, Wd, 5, 2.2);
  const body = solid(g);
  put(body, prism(P, front, br, bi, 4, BZ));
  mk("path", { class: "nf lo", d: poly(at(rrect(4, 4, L - 4, Wd - 4, 3, 6), BZ - 0.2).map((p) => P(...p))) }, body.g);
  const lid = solid(g), knob = solid(g);
  lid.sil.classList.add("hi");
  const tw = tween(rad(14));
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const prj = (r) => r.map((p) => P(...pose(p, a)));
    lid.sil.setAttribute("d", poly(hull(LID.flatMap(prj))));
    lid.cr.setAttribute("d", poly(prj(LIDCR)));
    knob.sil.setAttribute("d", poly(hull(KNOB.flatMap(prj))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const rest = ext.slice(0, 4).concat(LID.flat().map((p) => pose(p, rad(14)))).map((p) => P(...p));
  const xs = rest.map((q) => q[0]), ys = rest.map((q) => q[1]);
  const box = [Math.min(...xs) - 4, Math.min(...ys) - 4, Math.max(...xs) + 4, Math.max(...ys) + 4];
  const hit = ([sx, sy]) => sx > box[0] && sx < box[2] && sy > box[1] && sy < box[3];

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? rad(open) : rad(14), performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "coalscuttle",
  means: "A boxy coal scuttle with a domed lid hinged at the back: under the pointer the lid swings up and open.",
  rules: [1, 4, 5, 8],
  range: [70, 105, 125],
  tour: [[240, 162], [200, 150], [190, 230], null],
  mount,
});

kindling.code:
/**
 * Log carrier: a canvas sling laid on the hearth with three logs on it and a
 * wooden dowel along each side flap. The pointer over it folds both flaps up
 * to carry, the dowels meeting over the logs. At rest the far flap is half
 * raised, its dowel bright. The slider is how far the flaps fold.
 */
const { Cam, fit, hull, poly, proj, rad, unproj, spring, stepS, disposer, mk, pointer, register } = HL;

const L = 72, H = 15, F = 32, LR = 7, REST = [58, 12];
function cylX(P, x0, x1, y, z, r) {
  const a = [], b = [];
  for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; a.push(P(x0, y + r * Math.cos(t), z + r * Math.sin(t))); b.push(P(x1, y + r * Math.cos(t), z + r * Math.sin(t))); }
  return { sil: poly(hull(a.concat(b))), cap: poly(b) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let fold = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, -H - F, 0], [L, H + F, 0], [0, H + F, 0], [L, -H - F, 0], [0, 0, F + 4], [L, 0, F + 4]], 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const back = mk("g", {}, g);
  const farFlap = mk("path", { class: "sil" }, back), farDow = mk("path", { class: "sil" }, back), farCap = mk("path", { class: "nf" }, back);
  mk("path", { d: poly([P(0, -H, 0), P(L, -H, 0), P(L, H, 0), P(0, H, 0)]), class: "sil" }, g);
  mk("path", { d: poly([P(0, -H + 3, 0), P(L, -H + 3, 0)]), class: "dash nf" }, g);
  mk("path", { d: poly([P(0, H - 3, 0), P(L, H - 3, 0)]), class: "dash nf" }, g);
  for (const [y, z] of [[-7.5, LR], [7.5, LR], [0, LR + 12]]) {
    const c = cylX(P, 5, L - 5, y, z, LR);
    mk("path", { d: c.sil, class: "sil" }, g);
    mk("path", { d: c.cap }, g);
    const r2 = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; r2.push(P(L - 5, y + 3 * Math.cos(t), z + 3 * Math.sin(t))); }
    mk("path", { d: poly(r2), class: "nf lo" }, g);
  }
  const front = mk("g", {}, g);
  const nearFlap = mk("path", { class: "sil" }, front), nearDow = mk("path", { class: "sil" }, front), nearCap = mk("path", { class: "nf" }, front);

  const A = [spring(REST[0], { k: 90, c: 16 }), spring(REST[1], { k: 90, c: 16 })];
  const last = [NaN, NaN];
  function flap(side, deg, path, dow, cap) {
    const a = rad(deg), s = side < 0 ? -1 : 1, yy = (d) => s * (H + d * Math.cos(a)), zz = (d) => d * Math.sin(a);
    path.setAttribute("d", poly([P(0, s * H, 0), P(L, s * H, 0), P(L, yy(F), zz(F)), P(0, yy(F), zz(F))]));
    const c = cylX(P, -6, L + 6, yy(F + 1), zz(F + 1), 2.2);
    dow.setAttribute("d", c.sil); cap.setAttribute("d", c.cap);
  }
  function draw() {
    if (A[0].x !== last[0]) { last[0] = A[0].x; flap(-1, A[0].x, farFlap, farDow, farCap); }
    if (A[1].x !== last[1]) { last[1] = A[1].x; flap(1, A[1].x, nearFlap, nearDow, nearCap); }
  }
  draw();
  const B = register(stage, (dt) => { const m0 = stepS(A[0], dt), m1 = stepS(A[1], dt); draw(); return m0 || m1; });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) { if (v) { A[0].t = fold; A[1].t = fold; B.wake(); } return; }
    on = v;
    A[0].t = v ? fold : REST[0]; A[1].t = v ? fold : REST[1];
    farDow.classList.toggle("hi", true); nearDow.classList.toggle("hi", v);
    read.textContent = v ? "carry" : "rest";
    B.wake();
  }
  setOn(false);
  function hit([sx, sy]) { const [x, y] = unproj(C, sx, sy, 0); return x > -12 && x < L + 12 && y > -H - F - 6 && y < H + F + 6; }
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { fold = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "kindling",
  means: "A canvas log carrier on the hearth: the pointer folds both flaps up around the logs, dowel handles meeting on top.",
  rules: [1, 3, 5, 8],
  range: [50, 80, 90],
  tour: [[200, 144], [135, 214], [207, 120], null],
  mount,
});

spark.code:
/**
 * Fireside tongs: a long pair of hearth tongs hanging from a ring handle over
 * a hearth tile, the two arms pinned at a rivet below the ring, each ending
 * in a claw. The pointer opens the jaws wide. At rest they stand barely open,
 * the near arm bright. The slider is how wide the jaws open.
 */
const { Cam, fit, hull, poly, proj, rad, prism, rings, facing, put, solid, spring, stepS, disposer, mk, pointer, register } = HL;

const TOP = 122, LEN = 104, REST = 5;
function box(P, o, d, n, a, b, c) {
  // centre o, unit axes d (along), n (across, in plane), y; half sizes a, b, c
  const pts = [];
  for (const i of [-1, 1]) for (const j of [-1, 1]) for (const k of [-1, 1])
    pts.push(P(o[0] + i * a * d[0] + j * b * n[0], o[1] + k * c, o[2] + i * a * d[2] + j * b * n[2]));
  return poly(hull(pts));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.05);
  const ex = LEN * Math.sin(rad(40)), ez = TOP - LEN * Math.cos(rad(40));
  fit(C, [[-ex - 6, 0, ez], [ex + 6, 0, ez], [0, 0, TOP + 22], [-34, -22, 0], [34, 22, 0], [34, -22, 0], [-34, 22, 0]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [r0, r1] = rings(-34, -22, 34, 22, 4, 2);
  put(solid(g), prism(P, front, r0, r1, 0, 5));
  const coal = [];
  for (const [x, y, r] of [[-4, 2, 7], [6, -3, 6]]) for (let i = 0; i < 14; i++) { const t = (i / 14) * Math.PI * 2; coal.push(P(x + r * Math.cos(t), y + r * Math.sin(t), 5), P(x + r * 0.6 * Math.cos(t), y + r * 0.6 * Math.sin(t), 11)); }
  mk("path", { d: poly(hull(coal)), class: "nf lo" }, g);
  const ring = [];
  for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; ring.push(P(9 * Math.cos(t), 0, TOP + 11 + 9 * Math.sin(t))); }
  const ringIn = ring.map((_, i) => { const t = (i / 28) * Math.PI * 2; return P(6 * Math.cos(t), 0, TOP + 11 + 6 * Math.sin(t)); });
  mk("path", { d: poly(ring) + poly(ringIn), class: "sil", "fill-rule": "evenodd" }, g);
  const arms = [-1, 1].map((s) => {
    const grp = mk("g", {}, g);
    return { s, arm: mk("path", { class: "sil" }, grp), claw: mk("path", { class: "sil" }, grp) };
  });
  const rivet = mk("ellipse", { class: "dot m" }, g);
  const pv = P(0, 0, TOP);
  rivet.setAttribute("cx", pv[0]); rivet.setAttribute("cy", pv[1]); rivet.setAttribute("rx", 2.4); rivet.setAttribute("ry", 2.4);

  const A = spring(REST, { k: 110, c: 18 });
  let last = NaN;
  function draw() {
    if (A.x === last) return;
    last = A.x;
    for (const it of arms) {
      const a = rad(A.x), d = [it.s * Math.sin(a), 0, -Math.cos(a)], n = [Math.cos(a), 0, it.s * Math.sin(a)];
      const mid = [d[0] * LEN / 2, 0, TOP + d[2] * LEN / 2];
      it.arm.setAttribute("d", box(P, mid, d, n, LEN / 2 + 4, 1.6, 1.6));
      const end = [d[0] * (LEN - 3) - it.s * 3 * n[0], 0, TOP + d[2] * (LEN - 3) - it.s * 3 * n[2]];
      it.claw.setAttribute("d", box(P, end, d, n, 6, 1.2, 8));
    }
  }
  draw();
  const B = register(stage, (dt) => { const m = stepS(A, dt); draw(); return m; });
  bag.add(B.unregister);

  const lo = P(-ex, 0, ez), hi = P(ex, 0, ez);
  function hit([sx, sy]) { return sx > Math.min(lo[0], P(-34, 22, 0)[0]) - 10 && sx < Math.max(hi[0], P(34, -22, 0)[0]) + 10 && sy > P(0, 0, TOP + 22)[1] - 10 && sy < P(34, 22, 0)[1] + 10; }
  let on = null;
  function setOn(v) {
    if (v !== on) {
      on = v;
      arms[1].arm.classList.toggle("hi", true); arms[1].claw.classList.toggle("hi", true);
      read.textContent = v ? "grip" : "rest";
    }
    A.t = v ? open : REST;
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = v; if (on) setOn(true); }, destroy: bag.dispose };
}

