  name: "filmclip",
  means: "A film strip hanging from its clip on a drying line: the pointer's place along the line swings the strip on its clip.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[254, 211], [150, 190], [205, 140], null],
  mount,
