tablettoken.code:
/**
 * Token machine: a single-line tablet instrument, a tall cabinet on a plinth
 * with a dial on its face and a slide at its foot. The pointer, drawn out in
 * front of the cabinet, pulls the slide toward it, and once it is far enough
 * out the tablet shows in its tray; the dial's needle follows the slide. At
 * rest the slide stands a little open, its front bright.
 */
const {
  Cam, circ, fit, facing, open, poly, prism, proj, rings, unproj, clamp,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const W = 60, D = 40, H = 84, REST = 12, ZP = 20;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-6, -6, 0], [W + 6, -6, 0], [-6, D + 6, 0], [W + 6, D + 6, 0], [0, 0, H + 4], [8, D + 54, 10], [52, D + 54, 30]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-6, -6, W + 6, D + 6, 5, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 4));
  const [cr, ci] = rings(0, 0, W, D, 4, 1.5);
  put(solid(g), prism(P, front, cr, ci, 4, H));
  const [tr, ti] = rings(-3, -3, W + 3, D + 3, 4, 1.5);
  put(solid(g), prism(P, front, tr, ti, H, H + 4));
  // the dial on the front face (y = D) and the slot the slide runs in
  const face = (x, z) => P(x, D, z);
  mk("path", { d: poly(circ(11, 32).map((q) => face(30 + q.u, 58 + q.v))), class: "nf" }, g);
  mk("path", { d: poly([face(8, 9), face(52, 9), face(52, 31), face(8, 31)]), class: "nf lo" }, g);
  const needle = mk("path", { class: "nf" }, g);
  const dg = mk("g", {}, g);
  const tray = solid(dg), tab = solid(dg), plate = solid(dg), pull = solid(dg);
  plate.sil.classList.add("hi");

  const out = spring(REST);
  let last = NaN;
  function draw(o) {
    if (o === last) return;
    last = o;
    const [ar, ai] = rings(11, D - 2, 49, D + o + 0.5, 1.5, 0.8);
    put(tray, prism(P, front, ar, ai, 12, 24));
    if (o > 26) {
      const cy = D + o - 13;
      put(tab, prism(P, front, disc(30, cy, 9), disc(30, cy, 6.5), 24, 26));
    } else put(tab, { sil: "", crease: "" });
    const [fr, fi] = rings(8, D + o, 52, D + o + 4, 1.5, 0.8);
    put(plate, prism(P, front, fr, fi, 10, 30));
    const [kr, ki] = rings(23, D + o + 4, 37, D + o + 7, 1.5, 0.6);
    put(pull, prism(P, front, kr, ki, 18, 22));
    const a = (-150 + (o / 46) * 120) * Math.PI / 180;
    needle.setAttribute("d", open([face(30, 58), face(30 + 9 * Math.cos(a), 58 - 9 * Math.sin(a))]));
  }

  const B = register(stage, (dt) => { const m = stepS(out, dt); draw(out.x); return m; });
  bag.add(B.unregister);

  function aim([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, ZP);
    if (x < -10 || x > W + 10 || y < D - 20 || y > D + 80) return null;
    return clamp(y - D - 4, 0, reach);
  }
  function setAim(o) {
    out.t = o === null ? REST : o;
    read.textContent = o === null ? "rest" : o > 26 ? "tablet" : "pull " + Math.round(o);
    B.wake();
  }
  draw(REST);
  setAim(null);
  bag.add(pointer(stage, { move: (p) => setAim(aim(p)), leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "tablettoken",
  means: "A single-line token instrument: the slide at its foot pulls out toward the pointer and shows the tablet in its tray.",
  rules: [1, 3, 5, 8],
  range: [30, 46, 46],
  tour: [[121, 247], [169, 223], [135, 240], null],
  mount,
});

cooperhoop.code:
/**
 * Barrel hoop: a cooper's barrel standing on its chime, bellied in the
 * middle, with a hoop and the hoop driver resting on it. The pointer's
 * height over the barrel drives the hoop down the staves (it grows with the
 * belly as it goes), the driver riding on its top edge. At rest the hoop
 * sits loose near the head, bright.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, clamp,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const H = 84, R0 = 23, RM = 29, REST = H - 12, BAND = 5;
const rz = (z) => R0 + (RM - R0) * Math.sin(Math.PI * clamp(z / H, 0, 1));
const ring = (r, n = 40) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let low = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-RM - 4, -RM - 4, 0], [RM + 4, RM + 4, 0], [RM + 4, -RM - 4, 0], [-RM - 4, RM + 4, 0], [0, 0, H + 4], [24, 24, H + 40]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-RM - 8, -RM - 8, RM + 8, RM + 8, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  const prof = [];
  for (let i = 0; i <= 12; i++) { const z = (i / 12) * H; prof.push(...ringAt(P, ring(rz(z)), 3 + z)); }
  const barrel = solid(g);
  barrel.sil.setAttribute("d", poly(hull(prof)));
  barrel.cr.setAttribute("d", poly(ringAt(P, ring(R0 - 2.5), 3 + H)));
  // the fixed bottom hoop and the staves' joints: dim front arcs
  for (const z of [8, 13]) mk("path", { d: open(ringAt(P, run(ring(rz(z) + 0.4), front), 3 + z)), class: "nf lo" }, g);
  for (const a of [-0.55, 0.05, 0.6, 1.15, 1.75]) {
    const t = Math.PI / 4 + a, pts = [];
    for (let i = 1; i < 12; i++) { const z = (i / 12) * H; pts.push(P(rz(z) * Math.cos(t), rz(z) * Math.sin(t), 3 + z)); }
    mk("path", { d: open(pts), class: "nf lo" }, g);
  }
  const hoop = mk("path", { class: "sil hi" }, g);
  const drv = solid(g), blade = mk("path", { class: "nf lo" }, g);

  const zt = spring(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    const r1 = rz(z) + 0.8, r2 = rz(z + BAND) + 0.8;
    const lo = ringAt(P, run(ring(r1), front), 3 + z), hi = ringAt(P, run(ring(r2), front), 3 + z + BAND);
    hoop.setAttribute("d", poly(lo.concat(hi.reverse())));
    const c = (r2 + 3) * Math.SQRT1_2, z0 = 3 + z + BAND;
    const [dr, di] = rings(c - 3, c - 3, c + 3, c + 3, 1.5, 0.6);
    put(drv, prism(P, front, dr, di, z0, z0 + 44));
    blade.setAttribute("d", open([P(c - 3, c + 3, z0 + 10), P(c + 3, c - 3, z0 + 10)]));
  }

  const B = register(stage, (dt) => { const m = stepS(zt, dt); draw(zt.x); return m; });
  bag.add(B.unregister);

  const o = P(0, 0, 3), u = P(0, 0, 4);
  const per = o[1] - u[1];
  function aim([sx, sy]) {
    if (Math.abs(sx - o[0]) > RM * 2.4 || sy > o[1] + 40 || sy < o[1] - (H + 50) * per) return null;
    return clamp((o[1] - sy) / per - 8, low, REST);
  }
  function setAim(z) {
    zt.t = z === null ? REST : z;
    read.textContent = z === null ? "rest" : "hoop " + Math.round(z);
    B.wake();
  }
  draw(REST);
  setAim(null);
  bag.add(pointer(stage, { move: (p) => setAim(aim(p)), leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { low = v; }, destroy: bag.dispose };
}

hairline({
  name: "cooperhoop",
  means: "A cooper's barrel: the hoop driver drives the hoop down the staves to the pointer's height, the hoop growing with the belly.",
  rules: [1, 3, 5, 8],
  range: [20, 30, 50],
  tour: [[200, 208], [200, 242], [200, 175], null],
  mount,
});

litterpick.code:
/**
 * Litter picker: a long shaft with a pistol grip and trigger at the top and a
 * pair of broad jaws at its foot. The pointer near the picker squeezes it
 * open: the jaws spread wide on their pivot; at rest they hang a little
 * apart, bright. The slider is how wide they open.
 */
const {
  Cam, fit, hull, poly, proj, ringAt, circ, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const LP = 96, TILT = -34, JL = 34, REST = 7;
const disc = (x, y, r, n = 14) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.5);
  // s along the shaft from its foot, o across it in the screen plane
  const ax = (s, o = 0) => { const t = (TILT * Math.PI) / 180, w = s * Math.sin(t) + o * Math.cos(t); return [w * 0.707, -w * 0.707, 30 + s * Math.cos(t) - o * Math.sin(t)]; };
  const jaw = (side, a, s) => { const t = (a * Math.PI) / 180; return ax(-s * Math.cos(t), side * s * Math.sin(t)); };
  fit(C, [ax(LP + 12, -14), ax(LP + 12, 12), jaw(1, 52, JL + 3), jaw(-1, 52, JL + 3), ax(-JL - 3)], 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const bar = (a, b, r) => hull(ringAt(P, disc(a[0], a[1], r), a[2]).concat(ringAt(P, disc(b[0], b[1], r), b[2])));
  const jaws = [mk("path", { class: "sil hi" }, g), mk("path", { class: "sil hi" }, g)];
  mk("path", { d: poly(bar(ax(0), ax(LP), 2)), class: "sil" }, g);
  mk("path", { d: poly(hull([...bar(ax(-2), ax(6), 3.6)])), class: "nf" }, g);
  mk("path", { d: poly(hull([...bar(ax(LP - 4), ax(LP + 10, -12), 3), ...bar(ax(LP - 2), ax(LP + 8), 3)])), class: "sil" }, g);
  mk("path", { d: poly(bar(ax(LP - 12, 1), ax(LP - 4, 9), 1.6)), class: "nf lo" }, g);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    [1, -1].forEach((side, i) => {
      const pts = [];
      for (let k = 0; k <= 6; k++) { const s = (k / 6) * JL, w = 3 + 4 * Math.sin((k / 6) * Math.PI) ; pts.push(jaw(side, a, s), jaw(side, a - side * 0 + (w / Math.max(s, 6)) * 57.3 * 0.5, s)); }
      const tip = jaw(side, a - 10, JL + 2);
      pts.push(tip);
      jaws[i].setAttribute("d", poly(hull(pts.flatMap((p) => ringAt(P, disc(p[0], p[1], 1.2, 8), p[2])))));
    });
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? 22 + 30 * reach : REST, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  const p0 = P(...ax(-JL)), p1 = P(...ax(LP + 10));
  const hit = ([sx, sy]) => { const dx = p1[0] - p0[0], dy = p1[1] - p0[1]; const t = Math.max(0, Math.min(1, ((sx - p0[0]) * dx + (sy - p0[1]) * dy) / (dx * dx + dy * dy))); return Math.hypot(sx - p0[0] - t * dx, sy - p0[1] - t * dy) < 46; };
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; act = null; }, destroy: bag.dispose };
}

hairline({
  name: "litterpick",
  means: "A litter picker: the pointer near it squeezes the grip and the broad jaws at its foot spread wide open on their pivot.",
  rules: [1, 4, 5],
  range: [0.3, 1, 1],
  tour: [[269, 290], [225, 225], [165, 110], null],
  mount,
});

grit.code:
/**
 * Grit bin: a squat roadside bin with a humped lid hinged along its back,
 * a heap of grit inside. The pointer over the bin swings the lid up and back
 * to show the grit; at rest the lid sits ajar, bright.
 * The slider is how far the lid opens.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, circ, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 84, D = 52, H = 36, LT = 12, REST = 14;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-4, 0, 0], [W + 4, D, 0], [W, 0, 0], [0, D, 0], [0, -LT, H + D], [W, -LT, H + D], [W, D, H + LT]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const lidG = mk("g", {}, g);
  const baseG = mk("g", {}, g);
  // two low skids, then the body
  for (const x of [6, W - 14]) { const [sr, si] = rings(x, 2, x + 8, D - 2, 3, 1); put(solid(baseG), prism(P, front, sr, si, 0, 4)); }
  const [br, bi] = rings(0, 0, W, D, 8, 2);
  put(solid(baseG), prism(P, front, br, bi, 4, H));
  mk("path", { d: poly(ringAt(P, rrect(5, 5, W - 5, D - 5, 5, 4), H)), class: "nf lo" }, baseG);
  // the grit: a low heap in the mouth
  const heap = [];
  for (const [r, z] of [[20, 0], [14, 4], [7, 7]]) heap.push(...ringAt(P, disc(W / 2 + 4, D / 2, r, 20), H - 3 + z));
  mk("path", { d: poly(hull(heap)), class: "nf lo" }, baseG);
  // a hasp on the front face
  mk("path", { d: poly(hull(ringAt(P, rrect(W / 2 - 6, D, W / 2 + 6, D + 1.5, 1, 2), H - 9).concat(ringAt(P, rrect(W / 2 - 6, D, W / 2 + 6, D + 1.5, 1, 2), H - 3)))), class: "nf" }, baseG);

  const lid = mk("path", { class: "sil" }, lidG), lcr = mk("path", { class: "nf lo" }, lidG);
  const lr = rrect(-2, -2, W + 2, D + 2, 9, 4), top = rrect(10, 8, W - 10, D - 10, 12, 4), ti = rrect(12, 10, W - 12, D - 12, 10, 4);
  const ang = tween(REST);
  let last = NaN;
  // rotate about the hinge line y = 0, z = H
  const R = (a) => (q, zl) => { const t = (a * Math.PI) / 180, y = q.v * Math.cos(t) - zl * Math.sin(t), z = H + q.v * Math.sin(t) + zl * Math.cos(t); return P(q.u, y, z); };
  function draw(a) {
    if (a === last) return;
    last = a;
    const f = R(a);
    lid.setAttribute("d", poly(hull(lr.map((q) => f(q, 0)).concat(lr.map((q) => f(q, 3)), top.map((q) => f(q, LT))))));
    lcr.setAttribute("d", a > 95 ? "" : open(ti.map((q) => f(q, LT))) + "Z");
    if (a > 90) g.insertBefore(lidG, baseG); else baseG.after(lidG);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? 30 + 80 * reach : REST, performance.now(), 0);
    lid.classList.add("hi");
    read.textContent = a ? "open" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, H); return x > -6 && x < W + 6 && y > -10 && y < D + 6; };
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; act = null; }, destroy: bag.dispose };
}

hairline({
  name: "grit",
  means: "A roadside grit bin: the pointer over it swings the humped lid up on its back hinge to show the heap of grit.",
  rules: [1, 4, 5, 6],
  range: [0.4, 1, 1],
  tour: [[190, 167], [164, 208], [222, 200], null],
  mount,
});

bandstand2.code:
/**
 * Lamp bracket: a wall plate with a braced iron arm on a pivot and a lantern
 * hanging from its end. The pointer near the lamp swings the arm out round
 * its pivot, carrying the lantern with it; at rest the arm stands angled
 * off the wall, the lantern bright. The slider is how far it swings.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, circ, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 64, ZA = 100, REST = 14;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const sq = (x, y, h, r = 2) => rrect(x - h, y - h, x + h, y + h, Math.min(r, h - 0.2), 3);

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 2.9);
  const ends = [10, 40, 70, 110].map((d) => [L * Math.cos((d * Math.PI) / 180), L * Math.sin((d * Math.PI) / 180)]);
  fit(C, [[-14, -4, 44], [14, -4, 122], ...ends.flatMap(([x, y]) => [[x, y, ZA + 4], [x - 12, y + 12, 50], [x + 12, y - 12, 50]])], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the wall plate, with a pivot knuckle
  const [pr, pi] = rings(-12, -4, 12, 0, 2, 0.8);
  put(solid(g), prism(P, front, pr, pi, 52, 118));
  for (const z of [62, 108]) mk("path", { d: poly(ringAt(P, disc(0, -4.2, 1.4, 10), z)), class: "nf lo" }, g);
  const [kr, ki] = [disc(0, 2, 3, 16), disc(0, 2, 2, 16)];
  put(solid(g), prism(P, front, kr, ki, 66, ZA + 6));

  const brace = mk("path", { class: "nf" }, g), arm = mk("path", { class: "nf" }, g), scroll = mk("path", { class: "nf lo" }, g);
  const hook = mk("path", { class: "nf" }, g);
  const lamp = mk("path", { class: "sil hi" }, g), brim = mk("path", { class: "nf lo" }, g), glass = mk("path", { class: "nf lo" }, g);
  const ang = tween(REST);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const t = (d * Math.PI) / 180, ux = Math.cos(t), uy = Math.sin(t) ;
    const at = (s) => [s * ux, 2 + s * uy];
    const [ex, ey] = at(L), [mx, my] = at(L * 0.6);
    arm.setAttribute("d", poly(hull(ringAt(P, disc(0, 2, 2.2), ZA).concat(ringAt(P, disc(0, 2, 2.2), ZA + 3.5), ringAt(P, disc(ex, ey, 2), ZA), ringAt(P, disc(ex, ey, 2), ZA + 3.5)))));
    brace.setAttribute("d", poly(hull(ringAt(P, disc(0, 2, 1.6), 70).concat(ringAt(P, disc(mx, my, 1.6), ZA), ringAt(P, disc(0, 2, 1.6), 72)))));
    const [cx, cy] = at(L * 0.3);
    scroll.setAttribute("d", poly(ringAt(P, disc(cx, cy, 5, 20).map((q) => q), ZA - 6)));
    const zl = ZA - 12;
    hook.setAttribute("d", seg(P(ex, ey, ZA), P(ex, ey, zl + 2)));
    const parts = [[sq(ex, ey, 5), zl - 42], [sq(ex, ey, 7), zl - 38], [sq(ex, ey, 10), zl - 16], [sq(ex, ey, 12.5), zl - 13], [sq(ex, ey, 12.5), zl - 11], [sq(ex, ey, 3, 1), zl - 2], [sq(ex, ey, 1.6, 1), zl + 1]];
    lamp.setAttribute("d", poly(hull(parts.flatMap(([r, z]) => ringAt(P, r, z)))));
    brim.setAttribute("d", poly(ringAt(P, sq(ex, ey, 11.5), zl - 12)) + poly(ringAt(P, sq(ex, ey, 6.4), zl - 37)));
    glass.setAttribute("d", seg(P(ex + 6.6, ey + 6.6, zl - 36), P(ex + 9.4, ey + 9.4, zl - 17)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a ? REST + 45 + 45 * reach : REST, performance.now(), 0);
    read.textContent = a ? "swung" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, 80); return Math.hypot(x, y) < L + 22 && y > -8; };
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; act = null; }, destroy: bag.dispose };
}

hairline({
  name: "bandstand2",
  means: "A wall lamp bracket: the pointer near it swings the braced arm out round its pivot, carrying the hanging lantern.",
  rules: [1, 4, 5, 6],
  range: [0.3, 1, 1],
  tour: [[323, 213], [210, 184], [290, 230], null],
  mount,
});

bottlewarmer.code:
/**
 * Bottle warmer: a round warming pot with a bottle standing in it under a
 * domed lid hinged at the back. Over the pot the lid swings up on its hinge
 * and shows the bottle's teat. At rest the lid sits just ajar, bright. The
 * slider is how wide it opens.
 *
 * The pattern: one lid on a hinge; the hit is a fixed plane through the rim.
 */
const { Cam, clamp, facing, fit, hull, open, poly, prism, proj, rrect, run, ringAt, unproj, tdone, tset, tval, tween, disposer, mk, pointer, register, solid, rad } = HL;

const R = 24, H = 46, AJAR = rad(12);
const prof = [[0, R + 1], [4, R], [10, R - 3.5], [16, R - 10], [20, R - 17], [21.5, 0.01]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let wide = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-R, -R, 0], [R, R, 0], [R, -R, 0], [-R, R, 0], [-R - 22, 0, H + 2 * R + 2], [0, 0, H + 22]], 226, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const body = solid(g), dial = mk("path", { class: "nf lo" }, body.g), opening = mk("path", { class: "nf lo" }, body.g);
  const bottle = solid(g), teat = solid(g), lid = solid(g);
  const ro = rrect(-R, -R, R, R, R, 14), ri = rrect(-R + 1.6, -R + 1.6, R - 1.6, R - 1.6, R - 1.6, 14);
  const pb = prism(P, front, ro, ri, 0, H);
  body.sil.setAttribute("d", pb.sil); body.cr.setAttribute("d", pb.crease);
  opening.setAttribute("d", poly(ringAt(P, rrect(-15, -15, 15, 15, 15, 14), H)));
  const dc = []; for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; dc.push(P(R * 0.98 * Math.cos(rad(45)) + 4 * Math.cos(a) * 0.7, R * 0.98 * Math.sin(rad(45)) - 4 * Math.cos(a) * 0.7, 16 + 4 * Math.sin(a))); }
  dial.setAttribute("d", poly(dc));
  const bo = rrect(-13, -13, 13, 13, 13, 14), bi = rrect(-11.5, -11.5, 11.5, 11.5, 11.5, 14);
  const pbt = prism(P, front, bo, bi, H, H + 9);
  bottle.sil.setAttribute("d", pbt.sil); bottle.cr.setAttribute("d", pbt.crease);
  const tp = [];
  [[0, 7], [4, 6], [8, 4], [12, 3.2], [15, 2.4], [16.5, 0.01]].forEach(([z, r]) => { for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; tp.push(P(r * Math.cos(a), r * Math.sin(a), H + 9 + z)); } });
  teat.sil.setAttribute("d", poly(hull(tp)));
  teat.cr.setAttribute("d", open(ringAt(P, run(rrect(-9, -9, 9, 9, 9, 14), front), H + 9)));
  const ang = tween(AJAR);
  let last = NaN, behind = false;

  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const W = ([lx, ly, lz]) => P(-R + lx * c - lz * s, ly, H + lx * s + lz * c);
    const pts = [];
    prof.forEach(([lz, r]) => { for (let i = 0; i < 32; i++) { const b = (i / 32) * Math.PI * 2; pts.push([R + r * Math.cos(b), r * Math.sin(b), lz]); } });
    lid.sil.setAttribute("d", poly(hull(pts.map(W))));
    lid.cr.setAttribute("d", poly(pts.slice(64, 96).map(W)));
    const back = a > rad(60);
    if (back !== behind) { behind = back; if (back) body.g.after(lid.g); else teat.g.after(lid.g); }
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return Math.hypot(x, y) < R + 12;
  }
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? rad(clamp(40 + wide, 45, 95)) : AJAR, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  lid.sil.classList.add("hi");
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { wide = v; act = null; }, destroy: bag.dispose };
}

