const SCALE = 3.2, REST = 0.14, X0 = 130;
const LABEL = (s) => Math.round(6 + 94 * s) + "°";
const W = 60, H = 44;
function parts(s) {
  const a = 6 + 94 * s, out = [];
  out.push(B(-3, -3, 0, 1, 3, H + 2), B(W - 1, -3, 0, W + 3, 3, H + 2), B(1, -2, 0, W - 1, 2, 2));
  out.push(B(-4, -4, 10, 2, 4, 14), B(-4, -4, H - 12, 2, 4, H - 8), B(W - 2, -4, 10, W + 4, 4, 14), B(W - 2, -4, H - 12, W + 4, 4, H - 8));
  const L = W - 4, gate = [B(0, -1.2, H - 6, L, 1.2, H - 2, true), B(0, -1, 4, L, 1, 7), B(0, -1.4, 4, 2.4, 1.4, H - 2), B(L - 2.4, -1.4, 4, L, 1.4, H - 2), B(L - 6, -2.4, H - 9, L - 1, 2.4, H - 5)];
  for (let i = 1; i < 7; i++) { const x = (i * L) / 7; gate.push(B(x - 0.6, -0.6, 7, x + 0.6, 0.6, H - 6)); }
  out.push(...gate.map((b) => mv(rot(b, "z", a, [0, 0, 0]), 2, 0, 0)));
  return out;
}

hairline({
  name: "stairgate",
