strawjar.code:
/**
 * Straw dispenser: a round glass jar with a rim collar, a bunch of straws
 * standing in it. The pointer over the jar pushes the straws up out of it,
 * the front ones highest, staggered outward. At rest one straw stands
 * proud, bright. The slider is how far they rise.
 *
 * The pattern: one part rising out of a fixed body (toaster).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX = 30, CY = 30, R = 24, H = 30, SR = 1.8, SL = 26, FAV = 4;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const SPOTS = [[-12, -8], [0, -15], [12, -9], [-16, 4], [-4, -2], [8, 1], [16, 8], [-9, 12], [3, 13]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.45);
  fit(C, [[CX - R, CY - R, 0], [CX + R, CY + R, 0], [CX - R, CY + R, 0], [CX + R, CY - R, 0], [CX, CY - 11, H + SL + 20], [CX + 12, CY + 6, H + SL + 20]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [jr, ji] = rings(CX - R, CY - R, CX + R, CY + R, R, 2);
  put(solid(g), prism(P, front, jr, ji, 0, H));
  const [cr, ci] = rings(CX - R - 1.5, CY - R - 1.5, CX + R + 1.5, CY + R + 1.5, R + 1.5, 1.2);
  put(solid(g), prism(P, front, cr, ci, H - 5, H));
  mk("path", { d: poly(ringAt(P, disc(CX, CY, R - 2), H)), class: "nf lo" }, g);
  const order = SPOTS.map((s, i) => i).sort((a, b) => SPOTS[a][0] + SPOTS[a][1] - SPOTS[b][0] - SPOTS[b][1]);
  const straws = order.map((i) => {
    const [dx, dy] = SPOTS[i], el = mk("path", { class: "sil" }, g);
    return { i, x: CX + dx, y: CY + dy, el, w: 0.55 + 0.45 * ((dx + dy + 20) / 40), last: NaN };
  });
  const sp = spring(0);
  function draw(s) {
    for (const st of straws) {
      const up = st.i === FAV ? Math.max(s, 0.35) : s;
      const top = H + SL - 14 + up * 32 * st.w;
      if (top === st.last) continue;
      st.last = top;
      st.el.setAttribute("d", poly(hull(ringAt(P, disc(st.x, st.y, SR, 12), H - 1).concat(ringAt(P, disc(st.x, st.y, SR, 12), top)))));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(0);
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    sp.t = v ? reach : 0;
    straws.forEach((st) => st.el.classList.toggle("hi", v ? st.i === 7 : st.i === FAV));
    read.textContent = v ? "push" : "rest";
    B.wake();
  }
  setOn(false);
  function hit([sx, sy]) {
    const m = P(CX, CY, H * 0.7);
    return Math.abs(sx - m[0]) < 70 && Math.abs(sy - m[1]) < 90;
  }
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { sp.t = v; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "strawjar",
  means: "A straw dispenser jar: the pointer over it pushes the straws up out of the rim, the front ones highest.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[200, 161], [188, 150], [214, 176], null],
  mount,
});

sugarshaker.code:
/**
 * Sugar pourer: a round glass body, a metal cone top and a short spout with
 * a hinged flap. The pointer over it tips the pourer forward on its front
 * edge, and the flap swings open as it goes; away, it stands with a slight
 * lean, the flap bright. The slider is how far it tips.
 *
 * The pattern: one part tilting on a fixed edge (spotlights' rotated hull).
 */
const {
  Cam, circ, fit, hull, poly, proj, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const CX = 30, CY = 30, R = 17, H = 44, TH = 14, REST = 0.06;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 3.9);
  const Y0 = CY + R;
  const rot = (x, y, z, a) => [x, Y0 + (y - Y0) * Math.cos(a) + z * Math.sin(a), -(y - Y0) * Math.sin(a) + z * Math.cos(a)];
  const ext = [];
  for (const a of [0, 1.1]) for (const [x, y, z] of [[CX - R, CY - R, 0], [CX + R, CY + R, 0], [CX - R, CY + R, 0], [CX + R, CY - R, 0], [CX, CY, H + TH + 10], [CX, CY + 10, H + TH + 8]]) ext.push(rot(x, y, z, a));
  fit(C, ext, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const body = mk("path", { class: "sil" }, g), band = mk("path", { class: "nf lo" }, g), level = mk("path", { class: "nf lo" }, g);
  const cone = mk("path", { class: "sil" }, g), spout = mk("path", { class: "sil" }, g), flap = mk("path", { class: "sil hi" }, g);
  const sp = spring(REST, { k: 80, c: 16 });
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const W = (x, y, z) => P(...rot(x, y, z, a));
    const ring = (r, z, n = 36, ox = 0, oy = 0) => circ(r, n).map((q) => W(CX + ox + q.u, CY + oy + q.v, z));
    body.setAttribute("d", poly(hull(ring(R, 0).concat(ring(R, H)))));
    band.setAttribute("d", poly(ring(R, 4)));
    level.setAttribute("d", poly(ring(R - 0.5, H * 0.55)));
    cone.setAttribute("d", poly(hull(ring(R + 1, H).concat(ring(R + 1, H + 3), ring(6, H + TH)))));
    // spout leans toward the front edge
    spout.setAttribute("d", poly(hull(ring(4.5, H + TH - 5, 16, 0, 4).concat(ring(3.6, H + TH + 6, 16, 0, 9)))));
    const f = 0.15 + 1.9 * Math.max(0, (a - REST) / 1.1);
    const hz = H + TH + 6, hy = CY + 9 - 3.6;
    const fl = circ(4.2, 16).map((q) => [CX + q.u, q.v + 3.6, 0]).map(([x, v]) => W(x, hy + v * Math.cos(f), hz + v * Math.sin(f)));
    flap.setAttribute("d", poly(hull(fl)));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(REST);
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    sp.t = v ? tip : REST;
    flap.classList.toggle("hi", !v);
    cone.classList.toggle("hi", v);
    read.textContent = v ? "pour" : "rest";
    B.wake();
  }
  setOn(false);
  function hit([sx, sy]) {
    const m = P(CX, CY, H / 2 + 6);
    return Math.abs(sx - m[0]) < 70 && Math.abs(sy - m[1]) < 100;
  }
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; if (on) { sp.t = v; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "sugarshaker",
  means: "A sugar pourer: the pointer over it tips the glass forward on its front edge and the spout flap swings open.",
  rules: [1, 3, 5, 8],
  range: [0.6, 0.95, 1.1],
  tour: [[253, 157], [240, 140], [262, 180], null],
  mount,
});

napkindisp.code:
/**
 * Napkin holder: a low base with two upright end plates and a stack of
 * napkins standing between them, pressed forward by the spring plate. The
 * pointer over it draws the napkins up out of the holder, the front one
 * highest, the rest following less. At rest the front napkin stands a
 * little proud, bright. The slider is how far they rise.
 *
 * The pattern: items rising from slots (toaster).
 */
const {
  Cam, fit, facing, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 0, X1 = 54, Y1 = 34, NH = 34, N = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-4, -2, 0], [X1 + 4, Y1 + 2, 0], [-4, Y1 + 2, 0], [X1 + 4, -2, 0], [X1 / 2, 6, 4 + NH + 34], [X1 / 2, Y1, 4 + NH + 34]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-4, -2, X1 + 4, Y1 + 2, 4, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const [lr, li] = rings(-4, 2, 0, Y1 - 2, 1.5, 0.6);
  put(solid(g), prism(P, front, lr, li, 4, 30));
  const [pr, pi] = rings(2, 3, X1 - 2, 5.5, 1, 0.5);
  put(solid(g), prism(P, front, pr, pi, 4, 26));
  const naps = [];
  for (let i = 0; i < N; i++) {
    const y = 7 + i * 4.2, s = solid(g);
    const [nr, ni] = rings(3, y, X1 - 3, y + 2.4, 1, 0.6);
    naps.push({ i, s, nr, ni, last: NaN });
  }
  const [rr, ri] = rings(X1, 2, X1 + 4, Y1 - 2, 1.5, 0.6);
  put(solid(g), prism(P, front, rr, ri, 4, 30));
  const sp = spring(0);
  function draw(v) {
    for (const n of naps) {
      const w = (n.i + 1) / N, up = n.i === N - 1 ? Math.max(v, 0.18) : v;
      const z = 4 + up * 36 * w * w;
      if (z === n.last) continue;
      n.last = z;
      put(n.s, prism(P, front, n.nr, n.ni, z, z + NH));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(0);
  naps[N - 1].s.sil.classList.add("hi");
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    sp.t = v ? reach : 0;
    read.textContent = v ? "pull" : "rest";
    B.wake();
  }
  setOn(false);
  function hit([sx, sy]) {
    const m = P(X1 / 2, Y1 / 2, 20);
    return Math.abs(sx - m[0]) < 100 && Math.abs(sy - m[1]) < 90;
  }
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { sp.t = v; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "napkindisp",
  means: "A napkin holder: the pointer over it draws the napkins up between the end plates, the front one highest.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1],
  tour: [[200, 181], [185, 165], [218, 196], null],
  mount,
});

tipjar.code:
/**
 * Tip jar: a round glass jar on a coaster, a lid with a coin standing in its
 * slot. The pointer on the counter tips the jar toward it, rocking on the
 * edge of its foot, further the further the pointer is. At rest the jar
 * leans a little and the coin is bright. The slider is the most it tips.
 *
 * The pattern: a continuous aim (a spring per tilt component).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 22, Z0 = 3, H = 50, NR = 17, LR = 19, REST = [5, -4];
const disc = (r, z, n = 40) => circ(r, n).map((q) => [q.u, q.v, z]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const C = Cam(45, 0.5, 2.6);
  const ext = [];
  for (const [a, b] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) ext.push([a * 32, b * 32, 0], [a * 38, b * 38, Z0 + H + 10]);
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(32, 48), circ(30, 48), 0, Z0));

  const body = mk("path", { class: "sil" }, g), shoulder = mk("path", { class: "nf lo" }, g);
  const lid = mk("path", { class: "sil" }, g), lidTop = mk("path", { class: "nf lo" }, g);
  const slot = mk("path", { class: "nf lo" }, g), coin = mk("path", { class: "sil" }, g);
  const tx = spring(REST[0]), ty = spring(REST[1]);

  function xf(p) {
    const a = Math.hypot(tx.x, ty.x) * Math.PI / 180;
    if (a < 1e-4) return P(p[0], p[1], p[2]);
    const dx = tx.x / Math.hypot(tx.x, ty.x), dy = ty.x / Math.hypot(tx.x, ty.x);
    const px = dx * R, py = dy * R, qx = p[0] - px, qy = p[1] - py, qz = p[2] - Z0;
    const s = qx * dx + qy * dy, w = -qx * dy + qy * dx;
    const s2 = s * Math.cos(a) + qz * Math.sin(a), z2 = -s * Math.sin(a) + qz * Math.cos(a);
    return P(px + s2 * dx - w * dy, py + s2 * dy + w * dx, Z0 + z2);
  }
  const ringP = (r, z, n) => disc(r, z, n).map(xf);

  let last = "";
  function draw() {
    const key = tx.x.toFixed(2) + "," + ty.x.toFixed(2);
    if (key === last) return;
    last = key;
    const pts = ringP(R - 2, Z0, 40).concat(ringP(R, Z0 + 4, 40), ringP(R, Z0 + H - 8, 40), ringP(NR, Z0 + H, 40));
    body.setAttribute("d", poly(hull(pts)));
    shoulder.setAttribute("d", open(ringP(R - 1.5, Z0 + H - 8, 40).slice(0, 21)));
    lid.setAttribute("d", poly(hull(ringP(LR, Z0 + H, 40).concat(ringP(LR, Z0 + H + 6, 40)))));
    lidTop.setAttribute("d", poly(ringP(LR - 2, Z0 + H + 6, 40)));
    const zt = Z0 + H + 6;
    slot.setAttribute("d", poly([[-7, 7, zt], [7, -7, zt], [7.6, -6.4, zt], [-6.4, 7.6, zt]].map(xf)));
    const cp = [];
    for (let i = 0; i <= 16; i++) { const t = (i / 16) * Math.PI, c = 8 * Math.cos(t); cp.push(xf([c * 0.7071 + 0.3, -c * 0.7071 + 0.3, zt + 8 * Math.sin(t)])); }
    coin.setAttribute("d", poly(cp));
  }

  const B = register(stage, (dt) => {
    const m = stepS(tx, dt) | stepS(ty, dt);
    draw();
    return !!m;
  });
  bag.add(B.unregister);

  let on = false;
  function aim(p) {
    const [x, y] = p ? unproj(C, p[0], p[1], 0) : [0, 0];
    const d = Math.hypot(x, y);
    on = !!p && d < 110;
    if (!on) { tx.t = REST[0]; ty.t = REST[1]; } else {
      const amt = MAX * clamp(d / 40, 0, 1) / Math.max(d, 1e-3);
      tx.t = x * amt; ty.t = y * amt;
    }
    body.classList.toggle("hi", on);
    coin.classList.toggle("hi", !on);
    read.textContent = on ? Math.round(Math.hypot(tx.t, ty.t)) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { MAX = v; }, destroy: bag.dispose };
}

hairline({
  name: "tipjar",
  means: "A tip jar with a coin in its lid: the pointer on the counter tips the jar toward it, further the further away.",
  rules: [3, 5, 8],
  range: [8, 22, 30],
  tour: [[233, 276], [99, 233], [200, 170], null],
  mount,
});

sandbag.code:
/**
 * Slam ball: a heavy rubber ball over a floor mat, with the ring it has worn
 * into the mat. The pointer above the ball lifts it, higher the higher the
 * pointer, and leaving lets it drop back toward the mat. At rest it hangs just
 * off the mat and the worn ring is bright. The slider is the highest lift.
 *
 * The pattern: a continuous aim (one spring on the height); the hit is a
 * fixed column over the ball's rest place.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BR = 26, MZ = 3, REST = 8;
const disc = (r, z, n = 40) => circ(r, n).map((q) => [q.u, q.v, z]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-44, -44, 0], [44, 44, 0], [44, -44, 0], [-44, 44, 0], [0, 0, MZ + 2 * BR + 50]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [mr, mi] = rings(-44, -44, 44, 44, 8, 2);
  put(solid(g), prism(P, front, mr, mi, 0, MZ));
  const wear = mk("path", { d: poly(disc(BR * 0.7, MZ).map((p) => P(...p))), class: "nf sil" }, g);
  const drop = mk("path", { class: "dash" }, g);
  const ball = mk("path", { class: "sil" }, g), seam = mk("path", { class: "nf lo" }, g), seam2 = mk("path", { class: "nf lo" }, g);
  const h = spring(REST);
  let last = NaN;
  function draw() {
    const z0 = MZ + h.x;
    if (z0 === last) return;
    last = z0;
    const pts = [];
    for (let i = -6; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...disc(BR * Math.cos(t), z0 + BR + BR * Math.sin(t), 32).map((p) => P(...p))); }
    ball.setAttribute("d", poly(hull(pts)));
    const eq = disc(BR - 0.6, z0 + BR, 48).map((p) => P(...p));
    seam.setAttribute("d", open(eq.slice(0, 25)));
    const mer = [];
    for (let i = 0; i <= 24; i++) { const t = (i / 24) * Math.PI - Math.PI / 2; mer.push(P(BR * 0.97 * Math.cos(t) * 0.7071, -BR * 0.97 * Math.cos(t) * 0.7071, z0 + BR + BR * 0.97 * Math.sin(t))); }
    seam2.setAttribute("d", open(mer));
    drop.setAttribute("d", h.x > 2 ? open([P(0, 0, MZ), P(0, 0, z0)]) : "");
  }
  const B = register(stage, (dt) => { const m = stepS(h, dt); draw(); return m; });
  bag.add(B.unregister);

  const base = P(0, 0, MZ + BR), half = BR * 2.5 + 10;
  function aim(p) {
    const on = !!p && Math.abs(p[0] - base[0]) < half && p[1] < base[1] + half && p[1] > 0;
    h.t = on ? clamp((base[1] - p[1]) / 2.5 + 20, 0, MAX) : REST;
    ball.classList.toggle("hi", on);
    wear.classList.toggle("hi", !on);
    read.textContent = on ? "lift " + Math.round(h.t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { MAX = v; }, destroy: bag.dispose };
}

hairline({
  name: "sandbag",
  means: "A slam ball over a floor mat: the pointer above it lifts the ball, higher the higher it is, and leaving drops it.",
  rules: [1, 3, 5, 8],
  range: [20, 40, 50],
  tour: [[200, 176], [200, 111], [200, 24], null],
  mount,
});

greenhousevent.code:
/**
 * Vent opener: a greenhouse roof vent, a framed pane hinged along its top,
 * pushed open by a wax-cylinder arm at its side. The pointer is the warmth:
 * the nearer it comes to the pane, the wider the arm pushes it open. At rest
 * the pane stands ajar, bright. The slider is how far the arm can reach.
 *
 * The pattern: a continuous opening on a spring; the hit is on the ground
 * plane, which never moves.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rad, unproj, spring, stepS,
  disposer, mk, pointer, register, solid,
} = HL;

const W = 64, H = 48, PL = 42, REST = 18;

function mount({ stage, svg, read }, value) {
  let reach = value;
  const bag = disposer();
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-4, -4, 0], [W + 10, -4, 0], [W + 10, 0, H + 4], [-4, 0, H + 4], [0, PL, H], [W, PL, H], [W, 30, 10]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const box = (x0, x1, y0, y1, z0, z1) => { const p = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) p.push(P(x, y, z)); return poly(hull(p)); };
  const frame = solid(g);
  frame.sil.setAttribute("d", box(-4, W + 4, -4, 0, 0, H + 4));
  frame.cr.setAttribute("d", poly([P(2, 0.1, 4), P(W - 2, 0.1, 4), P(W - 2, 0.1, H - 2), P(2, 0.1, H - 2)]));
  const arm = mk("path", { class: "sil" }, g), rod = mk("path", { class: "sil" }, g);
  const pane = solid(g);
  pane.sil.classList.add("hi");
  const th = spring(rad(REST));
  let last = NaN, open = false;

  function draw() {
    const t = th.x;
    if (t === last) return;
    last = t;
    const at = (x, d, s) => [x, d * Math.sin(t) + s * Math.cos(t), H - d * Math.cos(t) + s * Math.sin(t)];
    const pts = [];
    for (const x of [0, W]) for (const d of [0, PL]) for (const s of [0, 2.4]) pts.push(P(...at(x, d, s)));
    pane.sil.setAttribute("d", poly(hull(pts)));
    pane.cr.setAttribute("d", poly([at(4, 4, 2.5), at(W - 4, 4, 2.5), at(W - 4, PL - 4, 2.5), at(4, PL - 4, 2.5)].map((q) => P(...q))));
    // the arm: a cylinder pivoting on the frame's side, its rod to the pane's lower corner
    const base = [W + 6, 0, 6], tipP = at(W + 6, PL * 0.75, 1.2);
    const dir = tipP.map((v, i) => v - base[i]), n = Math.hypot(...dir), u = dir.map((v) => v / n);
    const mid = base.map((v, i) => v + u[i] * n * 0.55);
    const tube = (a, b, r) => { const p = []; for (const q of [a, b]) for (let i = 0; i < 10; i++) { const k = (i / 10) * Math.PI * 2; p.push(P(q[0] + r * Math.cos(k), q[1] + r * Math.sin(k), q[2] + r * Math.cos(k + 1))); } return poly(hull(p)); };
    arm.setAttribute("d", tube(base, mid, 3.4));
    rod.setAttribute("d", tube(mid, tipP, 1.3));
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);

  function set(target) {
    open = target !== null;
    const deg = open ? target : REST;
    th.t = rad(deg);
    read.textContent = open ? "open " + Math.round(deg) + "°" : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x < -20 || x > W + 30 || y < -10 || y > 110) return set(null);
      set(clamp(10 + (y / 80) * 62 * reach, 10, 72));
    },
    leave: () => set(null),
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { reach = clamp(v, 0, 1); }, destroy: bag.dispose };
}

hairline({
  name: "greenhousevent",
  means: "A greenhouse vent on its opener arm: the nearer the pointer comes, the wider the arm pushes the hinged pane open.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[141, 209], [66, 310], [98, 300], null],
  mount,
});

logsplitter2.code:
/**
 * Leaf grabber: a scissor-action leaf grabber lying on the lawn, two long
 * arms crossed at a bolt, each ending in a fanned rake head. The pointer over
 * it opens the jaws: both arms swing apart round the bolt. At rest the jaws
 * are almost closed and the upper head is bright. The slider is how wide.
 */
const { Cam, fit, hull, poly, proj, rrect, seg, tween, tset, tval, tdone, unproj, disposer, mk, pointer, register } = HL;

const rz = (a) => ([x, y, z]) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a), z];
const chain = (...fs) => (p) => fs.reduce((q, f) => f(q), p);
const D = Math.PI / 180, REST = 4, BASE = -12 * D, T = 3;

function fan(r0, r1, h0, h1, n = 10) {
  const out = [{ u: r0, v: -h0 }];
  for (let i = 0; i <= n; i++) { const a = (-1 + 2 * i / n) * h1; out.push({ u: r1 * Math.cos(a) + r0 * 0.15, v: r1 * Math.sin(a) }); }
  out.push({ u: r0, v: h0 });
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.3);
  const ext = [];
  for (const s of [-1, 1]) for (const th of [REST, 30]) for (const p of [[-84, 0, 0], [62, 22, 0], [62, -22, 0], [0, 0, 10]]) ext.push(chain(rz(s * th * D), rz(BASE))(p));
  fit(C, ext, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);

  const parts = [
    { ring: rrect(-76, -2.5, 6, 2.5, 2.5), z0: 0, z1: T },
    { ring: rrect(-86, -4.5, -52, 4.5, 4.5), z0: 0, z1: T + 2 },
    { ring: fan(4, 60, 3, 0.36), z0: 0, z1: 1.6, head: true },
  ];
  const arms = [1, -1].map((s, k) => {
    const grp = mk("g", {}, g);
    const els = parts.map((pt) => ({ pt, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp) }));
    const tines = mk("path", { class: "nf lo" }, grp);
    return { s, k, dz: k * (T + 2), els, tines };
  });
  const bolt = mk("path", { class: "" }, g);
  const open = tween(0);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    const th = (REST + (max - REST) * o) * D;
    for (const a of arms) {
      const Tf = chain(rz(a.s * th), rz(BASE)), at = (q, z) => P(...Tf([q.u, q.v, z + a.dz]));
      for (const e of a.els) {
        const { ring, z0, z1 } = e.pt;
        const top = ring.map((q) => at(q, z1));
        e.sil.setAttribute("d", poly(hull(ring.map((q) => at(q, z0)).concat(top))));
        const inner = ring.map((q) => ({ u: q.u * 0.94 + (e.pt.head ? 2.5 : -2.2) * 0.4, v: q.v * 0.8 }));
        e.cr.setAttribute("d", poly(inner.map((q) => at(q, z1))));
      }
      let d = "";
      for (let i = -3; i <= 3; i++) { const an = i * 0.1; d += seg(at({ u: 30 * Math.cos(an), v: 30 * Math.sin(an) }, 1.6), at({ u: 66 * Math.cos(an), v: 66 * Math.sin(an) }, 1.6)); }
      a.tines.setAttribute("d", d);
    }
    const ring = rrect(-3.5, -3.5, 3.5, 3.5, 3.5).map((q) => P(...rz(BASE)([q.u, q.v, 0])));
    const ringT = rrect(-3.5, -3.5, 3.5, 3.5, 3.5).map((q) => P(...rz(BASE)([q.u, q.v, 2 * T + 5])));
    bolt.setAttribute("d", poly(hull(ring.concat(ringT))));
  }

  const B = register(stage, (_dt, now) => { draw(tval(open, now)); return !tdone(open, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(open, a ? 1 : 0, performance.now(), 0);
    arms[0].els[2].sil.classList.toggle("hi", !a);
    arms[1].els[2].sil.classList.toggle("hi", a);
    read.textContent = a ? "open " + Math.round(max) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0), [u, v] = rz(-BASE)([x, y, 0]);
    return u > -90 && u < 70 && Math.abs(v) < 34;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "logsplitter2",
  means: "A scissor leaf grabber on the lawn: the pointer over it swings both rake-headed arms apart round the bolt, opening the jaws.",
  rules: [1, 3, 5, 8],
  range: [14, 24, 32],
  tour: [[280, 180], [200, 160], [125, 130], null],
  mount,
});

gluegun.code:
/**
 * Glue gun: a hot glue gun standing on its grip, a fat barrel, a tapered
 * nozzle, a trigger and a glue stick out of the back. The pointer over it
 * squeezes the trigger and tips the whole gun nozzle-down onto the bench, a
 * bead of glue at the tip. At rest the trigger is bright. The slider is how
 * far it tips.
 */
const { Cam, fillet, fit, hull, poly, proj, rrect, tween, tset, tval, tdone, unproj, disposer, mk, pointer, register } = HL;

const rz = (a) => ([x, y, z]) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a), z];
const pitch = (a) => ([x, y, z]) => [x * Math.cos(a) - z * Math.sin(a), y, x * Math.sin(a) + z * Math.cos(a)];
const tr = (dx, dy, dz) => ([x, y, z]) => [x + dx, y + dy, z + dz];
const chain = (...fs) => (p) => fs.reduce((q, f) => f(q), p);
const D = Math.PI / 180, BASE = -8 * D, PX = -30;
const rr = (u0, v0, u1, v1, r) => rrect(u0, v0, u1, v1, r).map((q) => [q.u, q.v]);

// side profiles [u = x, v = z], each extruded across y, in paint order
const STICK = rr(-64, 39, -36, 47, 4);
const GRIP = fillet([[-38, 40], [-14, 40], [-20, 0], [-40, 0]], [3, 3, 4, 4]);
const BARREL = rr(-42, 32, 30, 54, 10);
const NOZZLE = fillet([[28, 37], [28, 49], [48, 44.5], [48, 41.5]], [2, 2, 1.2, 1.2]);
const TRIG = rr(-12, 14, -4, 32, 3.5);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.35);
  const pose = (o) => chain(tr(-PX, 0, 0), pitch(-max * o * D), tr(PX, 0, 0), rz(BASE));
  const ext = [];
  for (const o of [0, 1]) for (const p of [[-66, 0, 48], [50, 0, 44], [-40, 0, 0], [-14, 0, 56], [50, 0, 0]]) for (const y of [-12, 12]) ext.push(chain(tr(0, y, 0), (q) => q)(pose(o)(p)));
  max = 60; for (const p of [[50, 0, 44], [-66, 0, 48]]) ext.push(pose(1)(p)); max = value;
  fit(C, ext, 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const pad = rrect(-58, -22, 64, 22, 8);
  mk("path", { class: "nf lo", d: poly(pad.map((q) => P(...rz(BASE)([q.u, q.v, 0])))) }, g);
  const drop = mk("path", { class: "nf" }, g);
  const parts = [[STICK, -4, 4], [GRIP, -7, 7], [TRIG, -4, 4], [BARREL, -9, 9], [NOZZLE, -4, 4]].map(([pr, y0, y1]) => ({ pr, y0, y1, sil: mk("path", { class: "sil" }, g), cr: mk("path", { class: "nf lo" }, g) }));
  const trig = parts[2], noz = parts[4];
  const tw = tween(0);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    const Tf = pose(o);
    for (const pt of parts) {
      let pr = pt.pr;
      if (pt === trig) pr = pr.map(([u, v]) => [u - 6 * o * (32 - v) / 18, v]);
      const at = (y) => pr.map(([u, v]) => P(...Tf([u, y, v])));
      pt.sil.setAttribute("d", poly(hull(at(pt.y0).concat(at(pt.y1)))));
      const cx = pr.reduce((s, p) => s + p[0], 0) / pr.length, cz = pr.reduce((s, p) => s + p[1], 0) / pr.length;
      pt.cr.setAttribute("d", pt === trig ? "" : poly(pr.map(([u, v]) => P(...Tf([cx + (u - cx) * 0.86, pt.y1, cz + (v - cz) * 0.8])))));
    }
    const tip = Tf([49, 0, 43]);
    const r = 3.5 * o, ring = rrect(-r, -r, r, r, r).map((q) => P(tip[0] + q.u, tip[1] + q.v, 0));
    drop.setAttribute("d", o > 0.05 ? poly(hull(ring.concat(ring.map(([x, y]) => [x, y - 4 * o])))) : "");
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? 1 : 0, performance.now(), 0);
    trig.sil.classList.toggle("hi", !a);
    noz.sil.classList.toggle("hi", a);
    read.textContent = a ? "tip " + Math.round(max) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0), [u, v] = rz(-BASE)([x, y, 0]);
    return u > -70 && u < 66 && Math.abs(v) < 30;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "gluegun",
  means: "A hot glue gun on a bench pad: the pointer over it squeezes the trigger and tips the gun nozzle-down, a bead of glue at the tip.",
  rules: [1, 3, 5, 8],
  range: [20, 32, 42],
  tour: [[205, 173], [160, 152], [111, 137], null],
  mount,
});

stampblock.code:
/**
 * Clay stamp: a block print stamp on a sheet, a square block with a turned
 * knob on top and a carved motif on its face. The pointer over it lifts the
 * block off the sheet and tilts its face up to show the carving, the print
 * left on the paper. At rest the knob is bright. The slider is the tilt.
 */
const { Cam, fit, hull, poly, proj, rrect, tween, tset, tval, tdone, unproj, disposer, mk, pointer, register } = HL;

const pitch = (a) => ([x, y, z]) => [x * Math.cos(a) - z * Math.sin(a), y, x * Math.sin(a) + z * Math.cos(a)];
const tr = (dx, dy, dz) => ([x, y, z]) => [x + dx, y + dy, z + dz];
const chain = (...fs) => (p) => fs.reduce((q, f) => f(q), p);
const D = Math.PI / 180, LIFT = 34;
const disc = (r, n = 24) => rrect(-r, -r, r, r, r, n / 4);
const MOTIF = [[-12, -12, 12, 12, 3], [-5, -16, 5, -10, 2], [-5, 10, 5, 16, 2], [-16, -5, -10, 5, 2], [10, -5, 16, 5, 2]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-50, -40, 0], [50, 40, 0], [-50, 40, 0], [50, -40, 0], [0, 0, 70], [26, 0, 60]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const sheet = rrect(-48, -38, 48, 38, 3);
  mk("path", { class: "sil", d: poly(hull(sheet.map((q) => P(q.u, q.v, 0)).concat(sheet.map((q) => P(q.u, q.v, 1))))) }, g);
  const print = mk("path", { class: "nf lo" }, g);
  const knob = mk("path", { class: "sil hi" }, g), body = mk("path", { class: "sil" }, g), bcr = mk("path", { class: "nf lo" }, g);
  const relief = mk("path", { class: "nf" }, g);
  const tw = tween(0);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    const Tf = chain(tr(0, 0, -7), pitch(-max * o * D), tr(0, 0, 8 + LIFT * o));
    const at = (r, z) => r.map((q) => P(...Tf([q.u, q.v, z])));
    const blk = rrect(-22, -22, 22, 22, 4);
    body.setAttribute("d", poly(hull(at(blk, 0).concat(at(blk, 14)))));
    bcr.setAttribute("d", o > 0.5 ? poly(at(rrect(-20, -20, 20, 20, 3), 0)) : poly(at(rrect(-20, -20, 20, 20, 3), 14)));
    const neck = at(disc(4), 14).concat(at(disc(4), 24)), ball = at(disc(9), 24).concat(at(disc(9), 30), at(disc(6), 33));
    knob.setAttribute("d", poly(hull(neck.concat(ball))));
    if (o < 0.5) bcr.after(knob); else body.before(knob);
    let d = "";
    if (o > 0.5) for (const [a, b, c, e, r] of MOTIF) d += poly(hull(at(rrect(a, b, c, e, r), 0).concat(at(rrect(a, b, c, e, r), -2))));
    relief.setAttribute("d", d);
    let pd = "";
    if (o > 0.3) for (const [a, b, c, e, r] of MOTIF) pd += poly(rrect(-e, b, -a, e, r).map((q) => P(q.u, q.v, 1)));
    print.setAttribute("d", pd);
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? 1 : 0, performance.now(), 0);
    knob.classList.toggle("hi", !a);
    body.classList.toggle("hi", a);
    read.textContent = a ? "tilt " + Math.round(max) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return Math.abs(x) < 52 && Math.abs(y) < 42;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "stampblock",
  means: "A block print stamp on a sheet: the pointer over it lifts the block and tilts its carved face up, the print left on the paper.",
  rules: [1, 3, 5, 8],
  range: [60, 90, 110],
  tour: [[200, 214], [150, 200], [76, 187], null],
  mount,
});

cuttingmat.code:
/**
 * Craft knife: a slim pen-shaped knife with a knurled grip, a collet and an angled
 * blade, lying on a small cutting mat. The pointer tips the knife up onto its
 * blade point, the way it is held to cut.
 *
 * The pattern: one part turning about a fixed axis, driven by a spring.
 */
const { Cam, fit, proj, unproj, hull, poly, clamp, r2, spring, stepS, mk, pointer, register, disposer } = HL;

const rz = (x0, y0, x1, y1, z) => [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]];
const box = (x0, y0, x1, y1, z0, z1) => [rz(x0, y0, x1, y1, z0), rz(x0, y0, x1, y1, z1)];
const alongX = (sec, x0, x1) => [x0, x1].map((x) => sec.map(([y, z]) => [x, y, z]));
