  name: "rowmachine",
  means: "A hangboard on two ropes, cut with finger pockets and a jug: over it, the board swings out on its ropes.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.3],
  tour: [[255, 205], [225, 190], [285, 222], null],
  mount,
});

cartridge.code:
/**
 * Game cartridge: a low console with a slot across its top and one cartridge
 * seated in it. The pointer is the hand: the nearer it comes, the further the
 * cartridge slides up out of the slot, on a spring. At rest it sits a little
 * proud of the slot, bright. The slider is how far it may rise.
 *
 * The pattern: a continuous lift (terrain's spring); the hit is the floor's plane.
 */
const {
  Cam, clamp, fit, facing, lerp, prism, proj, rings, unproj, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const TOP = 14, H = 30, REST = 8, MAX = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[-40, -28, 0], [40, 28, 0], [40, -28, 0], [-40, 28, 0], [0, 0, TOP + H + MAX * 1.2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-40, -28, 40, 28, 9, 2);
  put(solid(g), prism(P, front, br, bi, 0, TOP));
  const [sr, si] = rings(-21, -5, 21, 5, 2, 1);
  put(solid(g), prism(P, front, sr, si, TOP - 0.01, TOP));
  for (const x of [-28, -22]) place(flatDot(g, C, 1.6, x === -28 ? "dot m" : "dot off"), P(x, 18, TOP));
  const cart = solid(g), label = mk("path", { class: "nf lo" }, g);
  cart.sil.classList.add("hi");
  const [cr, ci] = rings(-18, -3, 18, 3, 1.5, 0.8);
  const sp = spring(REST);
  let last = NaN;

  function draw() {
    const z = Math.round(sp.x * 100) / 100;
    if (z === last) return;
    last = z;
    const z1 = TOP - H + 8 + z + H;
    put(cart, prism(P, front, cr, ci, TOP, z1));
    const a = P(-12, 3, z1 - 4), b = P(12, 3, z1 - 4), c = P(12, 3, Math.max(TOP + 1, z1 - 16)), d = P(-12, 3, Math.max(TOP + 1, z1 - 16));
    label.setAttribute("d", `M${a}L${b}L${c}L${d}Z`);
  }
  const R = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(R.unregister);

  function aim(p) {
    let r = Infinity;
    if (p) { const [x, y] = unproj(C, p[0], p[1], 0); r = Math.hypot(x, y * 1.4); }
    const over = r < 110;
    sp.t = over ? lerp(REST, MAX * gain, clamp(1 - (r - 20) / 80, 0, 1)) : REST;
    read.textContent = over ? `${Math.round((sp.t / (MAX * 1.2)) * 100)}%` : "rest";
    R.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

hairline({
  name: "cartridge",
  means: "A console with one game cartridge in its slot: the nearer the pointer comes, the further the cartridge slides up out.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[200, 194], [70, 216], [330, 239], null],
  mount,
});

crtmonitor.code:
/**
 * CRT monitor: a deep tube monitor, its bezel square and its back tapering to
 * the neck of the tube, sat on a round swivel foot. The pointer is where the
 * user sits: the whole set swivels on its foot and tips on its tilt hinge to
 * face it, on springs. At rest it is turned a little aside, screen bright.
 * The slider is how far it may turn.
 *
 * The pattern: a continuous aim on two angles; the hit is the floor's plane.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rrect, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 10, ZC = 30, REST = [0.32, -0.08];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-28, -28, 0], [28, 28, 0], [28, -28, 0], [-28, 28, 0], [0, 0, ZC + 24]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(18, 48), circ(16.4, 48), 0, 3));
  put(solid(g), prism(P, front, circ(5, 24), circ(4, 24), 3, PZ));
  // local rings: the bezel in the x-z plane at y = 16, the back at y = -24
  const plane = (ring, y) => ring.map((q) => [q.u, y, ZC + q.v]);
  const bezel = plane(rrect(-23, -20, 23, 20, 4, 4), 16), lip = plane(rrect(-23, -20, 23, 20, 4, 4), 12);
  const back = plane(rrect(-15, -14, 15, 12, 6, 4), -24);
  const glass = plane(rrect(-18, -15.5, 18, 15.5, 6, 6), 16.3), cap = plane(rrect(-5, -5, 5, 5, 2.5, 4), -30);
  const body = mk("path", { class: "sil" }, g), neck = mk("path", { class: "nf lo" }, g);
  const rim = mk("path", { class: "nf lo" }, g), screen = mk("path", { class: "nf" }, g);
  const sb = spring(REST[0]), st = spring(REST[1]);
  let last = "", over = false;

  function pose([x, y, z]) {
    const a = st.x, b = sb.x, ca = Math.cos(a), sa = Math.sin(a), cb = Math.cos(b), s = Math.sin(b);
    const zz = z - PZ, y1 = y * ca - zz * sa, z1 = y * sa + zz * ca + PZ;
    return P(x * cb - y1 * s, x * s + y1 * cb, z1);
  }
  function draw() {
    const key = sb.x.toFixed(3) + st.x.toFixed(3);
    if (key === last) return;
    last = key;
    const B = bezel.map(pose), L = lip.map(pose), K = back.map(pose), Q = cap.map(pose);
    body.setAttribute("d", poly(hull(B.concat(L, K))));
    neck.setAttribute("d", poly(hull(K.concat(Q))));
    rim.setAttribute("d", poly(B));
    screen.setAttribute("d", poly(glass.map(pose)));
    // the tube's neck hides behind the body when it faces away
    if (sb.x > -0.2) g.insertBefore(neck, body); else body.after(neck);
  }
  const R = register(stage, (dt) => { const a = stepS(sb, dt), b = stepS(st, dt); draw(); return a || b; });
  bag.add(R.unregister);

  function aim(p) {
    if (!p) { over = false; sb.t = REST[0]; st.t = REST[1]; }
    else {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = true;
      sb.t = clamp(Math.atan2(-x, Math.max(y, 4)), -1, 1) * gain;
      st.t = clamp((r - 60) / 70, -1, 1) * -0.32 * gain;
    }
    screen.classList.toggle("hi", !over);
    body.classList.toggle("hi", over);
    read.textContent = over ? `${Math.round(sb.t * 57.3)}° ${Math.round(st.t * 57.3)}°` : "rest";
    R.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = v; }, destroy: bag.dispose };
}

hairline({
  name: "crtmonitor",
  means: "A deep tube monitor on a swivel foot: it turns and tips on its hinge to face wherever the pointer is.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.2],
  tour: [[64, 182], [324, 263], [200, 300], null],
  mount,
});

viewfinder.code:
/**
 * Viewfinder hood: a box medium-format camera with a lens on its front and a
 * waist-level finder on top, its lid hinged at the back. The pointer lifts the
 * lid: higher in the frame it stands open over the focusing screen, lower it
 * folds shut. At rest it stands ajar, bright. The slider is how stiffly it follows.
 *
 * The pattern: one hinged part following the pointer on a spring (open).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, rrect, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 26, H = 44, FT = H + 5, L = 21, REST = 38;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-W, -W, 0], [W, W + 16, 0], [W, -W, 0], [-W, W + 16, 0], [0, -L, FT + 2 * L + 2], [W, -W, FT + 2 * L]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-W, -W, W, W, 5, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const [fr, fi] = rings(-L, -L, L, L, 3, 1.2);
  put(solid(g), prism(P, front, fr, fi, H, FT));
  const [sr] = rings(-L + 4, -L + 4, L - 4, L - 4, 2, 1);
  mk("path", { d: poly(sr.map((q) => P(q.u, q.v, FT + 0.1))), class: "nf lo" }, g);
  // the lens, standing out of the front face along +y
  const lensAt = (R, y) => circ(R, 32).map((q) => P(q.u, y, H / 2 + q.v));
  for (const [R, y0, y1] of [[15, W, W + 6], [12, W + 6, W + 16]]) {
    mk("path", { d: poly(hull(lensAt(R, y0).concat(lensAt(R, y1)))), class: "sil" }, g);
    mk("path", { d: poly(lensAt(R - 1.5, y1)), class: "nf lo" }, g);
  }
  mk("path", { d: poly(lensAt(6, W + 16)), class: "nf lo" }, g);
  const lid = mk("path", { class: "sil hi" }, g), lidIn = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST, { k: 100 * value, c: 18 * Math.sqrt(value) });
  const plate = rrect(-L, 0, L, 2 * L, 3, 4), inset = rrect(-L + 3, 3, L - 3, 2 * L - 3, 2, 4);
  let last = NaN;

  function draw() {
    const a = Math.round(ang.x * 20) / 20;
    if (a === last) return;
    last = a;
    const t = ((180 - a) * Math.PI) / 180, e2 = [0, Math.cos(t), Math.sin(t)], e3 = [0, -Math.sin(t), Math.cos(t)];
    const at = (ring, w) => ring.map((q) => P(q.u, L + e2[1] * q.v + e3[1] * w, FT + e2[2] * q.v + e3[2] * w));
    const a0 = at(plate, 0), a1 = at(plate, -1.6);
    lid.setAttribute("d", poly(hull(a0.concat(a1))));
    lidIn.setAttribute("d", a < 92 ? poly(at(inset, 0)) : poly(at(inset, -1.6)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { ang.t = REST; read.textContent = "rest"; }
    else { ang.t = Math.round(clamp((250 - p[1]) / 1.4, 0, 105)); read.textContent = "lid " + ang.t + "°"; }
    lid.classList.toggle("hi", true);
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return { set: (v) => { ang.k = 100 * v; ang.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "viewfinder",
  means: "A box camera with a waist-level finder: the pointer lifts its hinged lid open over the screen or folds it shut.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[252, 40], [214, 200], [200, 130], null],
  mount,
