diffuser.code:
/**
 * Beauty dish: a wide shallow reflector on a light stand, with a small
 * deflector plate held in its middle. The pointer aims the dish: up and down
 * the frame tilts it, across swivels it. At rest it faces the viewer, tilted
 * down a little, and the deflector is bright. The slider is how stiffly it follows.
 *
 * The pattern: a continuous aim on two springs (spotlights).
 */
const {
  Cam, circ, clamp, fit, hull, poly, prism, proj, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 36, DEEP = 13, PZ = 58, REST = [-12, 0];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-40, -40, 0], [40, 40, 0], [40, -40, 0], [-40, 40, 0], [0, 0, PZ + R + 6], [30, 30, PZ + 30], [-30, -30, PZ + 30]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const front = (q) => q.nu + q.nv > 0;
  put(solid(g), prism(P, front, circ(16, 40), circ(14, 40), 0, 3));
  const [pr, pi] = rings(-1.6, -1.6, 1.6, 1.6, 1.5, 0.5);
  put(solid(g), prism(P, front, pr, pi, 3, PZ));
  const shell = mk("path", { class: "sil" }, g), mouth = mk("path", { class: "nf lo" }, g);
  const rod = mk("path", { class: "nf lo" }, g), plate = mk("path", { class: "nf hi" }, g);
  const sp = { k: 100 * value, c: 18 * Math.sqrt(value) };
  const tilt = spring(REST[0], sp), turn = spring(REST[1], sp);
  let last = "";

  function draw() {
    const key = tilt.x.toFixed(2) + "," + turn.x.toFixed(2);
    if (key === last) return;
    last = key;
    const t = (tilt.x * Math.PI) / 180, f = ((turn.x - 45) * Math.PI) / 180, cf = Math.cos(f), sf = Math.sin(f);
    const rz = ([x, y, z]) => [x * cf - y * sf, x * sf + y * cf, z];
    const e1 = rz([1, 0, 0]), e2 = rz([0, -Math.sin(t), Math.cos(t)]), e3 = rz([0, Math.cos(t), Math.sin(t)]);
    const at = (r, w, n = 48) => circ(r, n).map((q) => P(...[0, 1, 2].map((j) => [0, 0, PZ][j] + e1[j] * q.u + e2[j] * q.v + e3[j] * w)));
    const rim = at(R, DEEP), seen = e3[0] + e3[1] + e3[2] * 1.2 > 0;
    shell.setAttribute("d", poly(hull(at(9, 0).concat(at(R * 0.8, DEEP * 0.7), rim))));
    mouth.setAttribute("d", seen ? poly(rim) : "");
    rod.setAttribute("d", seen ? poly(hull(at(1.2, 0, 12).concat(at(1.2, DEEP + 4, 12)))) : "");
    plate.setAttribute("d", seen ? poly(hull(at(10, DEEP + 4).concat(at(10, DEEP + 5.2)))) : "");
  }

  const B = register(stage, (dt) => { const a = stepS(tilt, dt), b = stepS(turn, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { tilt.t = REST[0]; turn.t = REST[1]; read.textContent = "rest"; }
    else {
      tilt.t = Math.round(clamp((180 - p[1]) / 1.6, -40, 70));
      turn.t = Math.round(clamp((p[0] - 200) / 1.6, -80, 80));
      read.textContent = (tilt.t >= 0 ? "up " : "dn ") + Math.abs(tilt.t) + "°";
    }
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  aim(null);
  return {
    set: (v) => { tilt.k = turn.k = 100 * v; tilt.c = turn.c = 18 * Math.sqrt(v); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "diffuser",
  means: "A beauty dish on a light stand: the wide reflector tilts and swivels to aim where the pointer is.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[330, 60], [260, 130], [110, 240], null],
  mount,
});

bicyclebell.code:
/**
 * Bicycle bell: a domed bell clamped on a length of handlebar, with a thumb
 * lever on its base plate. The pointer rings it: the lever swings in and the
 * dome rocks toward the pointer's side. At rest the lever is bright.
 * The slider is how far the dome rocks.
 *
 * The pattern: a continuous aim on a spring, picked on the base plane.
 */
const {
  Cam, circ, clamp, fit, hull, poly, proj, rad, unproj, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const BR = 4.5, BL = 62, PZ = 10, DR = 21, DH = 15, LV = 32;
const AX = [Math.SQRT1_2, Math.SQRT1_2, 0];

function rot(p, c, th) {
  const v = [p[0] - c[0], p[1] - c[1], p[2] - c[2]], cs = Math.cos(th), sn = Math.sin(th);
  const d = AX[0] * v[0] + AX[1] * v[1] + AX[2] * v[2];
  const x = [AX[1] * v[2] - AX[2] * v[1], AX[2] * v[0] - AX[0] * v[2], AX[0] * v[1] - AX[1] * v[0]];
  return [0, 1, 2].map((j) => c[j] + v[j] * cs + x[j] * sn + AX[j] * d * (1 - cs));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, -BL, -BR], [0, BL, BR], [DR + 6, DR + 6, PZ], [-DR - 6, -DR - 6, PZ + DH + 8], [DR + LV, 4, PZ]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const tube = (a, b, r, n = 20) => {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], L = Math.hypot(...d), e = d.map((x) => x / L);
    let u = Math.abs(e[2]) < 0.9 ? [e[1], -e[0], 0] : [1, 0, 0];
    const un = Math.hypot(...u); u = u.map((x) => x / un);
    const w = [e[1] * u[2] - e[2] * u[1], e[2] * u[0] - e[0] * u[2], e[0] * u[1] - e[1] * u[0]];
    const ring = (o) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return P(...[0, 1, 2].map((j) => o[j] + r * (Math.cos(t) * u[j] + Math.sin(t) * w[j]))); });
    return poly(hull(ring(a).concat(ring(b))));
  };
  // the handlebar, then the clamp and the base plate
  mk("path", { class: "sil", d: tube([0, -BL, 0], [0, BL, 0], BR, 28) }, g);
  mk("path", { class: "sil", d: tube([0, -6, 0], [0, 6, 0], BR + 2.2, 28) }, g);
  mk("path", { class: "sil", d: tube([0, 0, 2], [0, 0, PZ - 1], 4) }, g);
  const plate = circ(DR - 3, 40);
  mk("path", { class: "sil", d: poly(hull(plate.map((q) => P(q.u, q.v, PZ - 1.5)).concat(plate.map((q) => P(q.u, q.v, PZ))))) }, g);
  const dome = mk("path", { class: "sil" }, g), lip = mk("path", { class: "nf lo" }, g), nut = mk("path", { class: "sil" }, g);
  const lever = mk("path", { class: "sil" }, g), pad = mk("path", { class: "sil" }, g);

  const tilt = spring(-0.12), push = spring(0);
  let last = "", over = false;
  const piv = [DR - 6, DR - 6, PZ];
  function draw() {
    const key = tilt.x.toFixed(3) + push.x.toFixed(3);
    if (key === last) return;
    last = key;
    const th = rad(26) * tilt.x * reach, c = [0, 0, PZ + 1], pts = [];
    for (let i = 0; i <= 7; i++) {
      const t = (i / 7) * (Math.PI / 2), r = DR * Math.cos(t) + (i === 0 ? 1.5 : 0);
      for (const q of circ(r, 32)) pts.push(P(...rot([q.u, q.v, PZ + 1 + DH * Math.sin(t)], c, th)));
    }
    dome.setAttribute("d", poly(hull(pts)));
    lip.setAttribute("d", poly(circ(DR - 1, 40).map((q) => P(...rot([q.u, q.v, PZ + 3.5], c, th)))));
    const nt = circ(3.2, 16), top = PZ + DH;
    nut.setAttribute("d", poly(hull(nt.map((q) => P(...rot([q.u, q.v, top], c, th))).concat(nt.map((q) => P(...rot([q.u, q.v, top + 4.5], c, th)))))));
    const a = rad(10 - 75 * push.x), tip = [piv[0] + LV * Math.cos(a), piv[1] - LV * Math.sin(a) * 0.2 + LV * Math.sin(a), PZ];
    lever.setAttribute("d", tube(piv, tip, 2.2));
    pad.setAttribute("d", tube([tip[0], tip[1], PZ - 2.5], [tip[0], tip[1], PZ + 2.5], 5.5));
  }

  const B = register(stage, (dt) => { const m1 = stepS(tilt, dt), m2 = stepS(push, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  function aim(p) {
    let s = 0;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], PZ);
      over = Math.hypot(x, y) < 78;
      s = clamp((x - y) / Math.SQRT2 / 34, -1, 1);
    } else over = false;
    tilt.t = over ? s : -0.12;
    push.t = over ? 1 : 0;
    dome.classList.toggle("hi", over);
    lever.classList.toggle("hi", !over);
    pad.classList.toggle("hi", !over);
    read.textContent = over ? `ding ${Math.round(26 * s * reach)}°` : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = ""; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "bicyclebell",
  means: "A bell on a handlebar: the pointer rings it, the thumb lever swings in and the dome rocks toward the pointer's side.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.3],
  tour: [[330, 183], [85, 183], [200, 150], null],
  mount,
});

pannier.code:
/**
 * Pannier: a bike bag hung on a rack rail by two hooks, its flap folded over
 * the top and down the front with a buckle strap. The pointer opens it: the
 * flap swings up and back on its hinge to show the bag's mouth. At rest the
 * flap is bright. The slider is how far the flap opens.
 *
 * The pattern: one part on a hinge, a discrete open or shut on the 700ms ease.
 */
const {
  Cam, fillet, fit, facing, poly, prism, proj, rad, rings, ringAt, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 26, H = 58, DROP = 26;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-8, -4, 0], [W + 8, D + 4, 0], [W + 8, -4, 0], [-8, D + 4, 0], [0, -DROP, H + D + 8], [W, 0, H + 14]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the rack rail and its hooks, behind the bag
  const [rr, ri] = rings(-8, -2, W + 8, 2, 1.5, 0.6);
  put(solid(g), prism(P, front, rr, ri, H + 8, H + 11));
  for (const x of [12, W - 12]) mk("path", { class: "nf sil", d: seg(P(x, 1, H), P(x, 1, H + 10)) }, g);
  const [br, bi] = rings(0, 0, W, D, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, H));
  const mouth = mk("path", { class: "nf", d: poly(ringAt(P, rings(4, 4, W - 4, D - 4, 5, 1)[0], H)) }, g);
  const top = mk("path", { class: "sil" }, g), drop = mk("path", { class: "sil" }, g), strap = mk("path", { class: "nf" }, g);
  const open = tween(0.08);
  let last = NaN;

  // a point on the flap, (x, s) with s running from the hinge across the top and then down the front
  function flapPt(x, s, a) {
    const ly = Math.min(s, D + 1.5), lz = s > D + 1.5 ? -(s - D - 1.5) : 0;
    const c = Math.cos(a), n = Math.sin(a);
    return P(x, -1 + ly * c - (lz + 1.5) * n + 1.5 * n, H + 1.5 + ly * n + lz * c);
  }
  function draw(o) {
    if (o === last) return;
    last = o;
    const a = rad(118) * o * reach;
    const panel = (s0, s1) => poly(fillet([flapPt(-1, s0, a), flapPt(W + 1, s0, a), flapPt(W + 1, s1, a), flapPt(-1, s1, a)], [2, 2, 5, 5], 4));
    top.setAttribute("d", panel(0, D + 1.5));
    drop.setAttribute("d", panel(D + 1.5, D + 1.5 + DROP));
    strap.setAttribute("d", poly(fillet([flapPt(W / 2 - 5, D + 4, a), flapPt(W / 2 + 5, D + 4, a), flapPt(W / 2 + 5, D + DROP + 6, a), flapPt(W / 2 - 5, D + DROP + 6, a)], [1, 1, 1, 1], 3)));
    // a flap past upright paints behind the mouth
    if (a > rad(70)) mouth.after(top, drop, strap); else g.append(top, drop, strap);
  }

  const B = register(stage, (_dt, now) => { draw(tval(open, now)); return !tdone(open, now); });
  bag.add(B.unregister);

  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(open, v ? 1 : 0.08, performance.now(), 0);
    top.classList.toggle("hi", !v); drop.classList.toggle("hi", !v);
    mouth.classList.toggle("hi", v);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], H / 2); set(x > -20 && x < W + 20 && y > -30 && y < D + 40); },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pannier",
  means: "A bike pannier hung on a rack rail: the pointer opens it, and the flap swings up and back to show the bag's mouth.",
  rules: [1, 5, 6, 8],
  range: [0.5, 1, 1],
  tour: [[189, 155], [230, 200], [160, 230], null],
  mount,
});

bikelight.code:
/**
 * Bike light: a front lamp on a strap clip round a length of handlebar. The
 * lamp swivels on its clip to aim where the pointer is, following on a
 * spring. At rest it points ahead and a little down, its lens bright.
 * The slider is how quickly it follows.
 *
 * The pattern: a continuous aim on a spring, hit on the ground plane.
 */
const {
  Cam, clamp, fit, hull, poly, proj, unproj, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const BR = 4.5, BL = 60, CZ = 14, LEN = 34, RB = 7, RF = 10;
const REST = [0.5, 0.15];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[0, -BL, -BR], [0, BL, BR], [30, -24, CZ + 20], [-30, 24, CZ + 20], [30, 24, CZ - 14], [-24, -24, CZ - 10]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const frame = (a, b) => {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], L = Math.hypot(...d), e = d.map((x) => x / L);
    let u = Math.abs(e[2]) < 0.9 ? [e[1], -e[0], 0] : [1, 0, 0];
    const un = Math.hypot(...u); u = u.map((x) => x / un);
    const w = [e[1] * u[2] - e[2] * u[1], e[2] * u[0] - e[0] * u[2], e[0] * u[1] - e[1] * u[0]];
    return (o, r, n = 24) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return P(...[0, 1, 2].map((j) => o[j] + r * (Math.cos(t) * u[j] + Math.sin(t) * w[j]))); });
  };
  const tube = (a, b, r, n) => { const f = frame(a, b); return poly(hull(f(a, r, n).concat(f(b, r, n)))); };
  mk("path", { class: "sil", d: tube([0, -BL, 0], [0, BL, 0], BR, 28) }, g);
  mk("path", { class: "sil", d: tube([0, -5, 0], [0, 5, 0], BR + 2, 28) }, g);
  mk("path", { class: "sil", d: tube([0, 0, 3], [0, 0, CZ - 3], 3.2) }, g);
  const knuckle = mk("path", { class: "sil", d: tube([0, -4, CZ], [0, 4, CZ], 4) }, g);
  const body = mk("path", { class: "sil" }, g), bezel = mk("path", { class: "nf lo" }, g), lens = mk("path", { class: "nf" }, g);
  const yaw = spring(REST[0], { k: 100 * value, c: 18 * Math.sqrt(value) }), pit = spring(REST[1], { k: 100 * value, c: 18 * Math.sqrt(value) });
  let last = "";

  function draw() {
    const key = yaw.x.toFixed(3) + pit.x.toFixed(3);
    if (key === last) return;
    last = key;
    const d = [Math.cos(yaw.x) * Math.cos(pit.x), Math.sin(yaw.x) * Math.cos(pit.x), -Math.sin(pit.x)];
    const c = [0, 0, CZ + RF - 2], a = c.map((v, j) => v - d[j] * LEN * 0.35), b = c.map((v, j) => v + d[j] * LEN * 0.65);
    const f = frame(a, b), back = f(a, RB), fr = f(b, RF), bz = f(b.map((v, j) => v - d[j] * 4), RF);
    body.setAttribute("d", poly(hull(back.concat(fr))));
    bezel.setAttribute("d", poly(bz));
    lens.setAttribute("d", d[0] + d[1] > -0.2 ? poly(f(b, RF - 2.5)) : "");
    if (d[0] + d[1] < 0) g.insertBefore(body, knuckle); else knuckle.after(body);
  }
  // keep the lens and bezel above the body in either order
  const B = register(stage, (dt) => { const m1 = stepS(yaw, dt), m2 = stepS(pit, dt); draw(); body.after(bezel, lens); return m1 || m2; });
  bag.add(B.unregister);

  function aim(p) {
    let over = false, x = 0, y = 0;
    if (p) { [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) < 90; }
    if (over) {
      yaw.t = Math.atan2(y, x);
      pit.t = clamp(0.6 - Math.hypot(x, y) / 90, -0.5, 0.6);
      read.textContent = `${Math.round(((yaw.t * 180) / Math.PI + 360) % 360)}°`;
    } else { yaw.t = REST[0]; pit.t = REST[1]; read.textContent = "rest"; }
    lens.classList.toggle("hi", !over);
    body.classList.toggle("hi", over);
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { yaw.k = pit.k = 100 * v; yaw.c = pit.c = 18 * Math.sqrt(v); }, destroy: bag.dispose };
}

hairline({
  name: "bikelight",
  means: "A front bike light clipped to a handlebar: it swivels on its clip to aim where the pointer is.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.6],
  tour: [[60, 182], [340, 182], [200, 240], null],
  mount,
});

handlebar.code:
/**
 * Handlebar bag: a boxy bag strapped under a bicycle's handlebar, its lid
 * hinged at the back and folding down over the front. The pointer over the
 * bag lifts the lid open; leaving lets it fall back ajar. The slider is how
 * far the lid swings.
 */
const {
  Cam, fit, fillet, hull, poly, prism, proj, rings, clamp, rad, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 34, H = 34, FL = 18, BY = -4, BZ = H - 2, BR = 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.3);
  const rot = (x, y, z, a) => { const dy = y, dz = z - H, c = Math.cos(rad(a)), s = Math.sin(rad(a)); return [x, dy * c - dz * s, H + dy * s + dz * c]; };
  const lidPts = (a) => [[0, 0, H], [W, 0, H], [W, D + 1, H], [0, D + 1, H], [0, D + 1, H - FL], [W, D + 1, H - FL]].map(([x, y, z]) => rot(x, y, z, a));
  fit(C, [[-22, BY, BZ], [W + 22, BY, BZ], [0, D, 0], [W, D, 0], [0, 0, 0], ...lidPts(115), ...lidPts(0)], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the handlebar: a round bar running across behind the bag
  const bar = [];
  for (const x of [-22, W + 22]) for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; bar.push(P(x, BY + BR * Math.cos(t), BZ + BR * Math.sin(t))); }
  const barG = mk("g", {}, g);
  mk("path", { d: poly(hull(bar)), class: "sil" }, barG);
  // two straps over the bar
  for (const x of [12, W - 12]) {
    const s = [];
    for (let i = 0; i < 12; i++) { const t = (i / 12) * Math.PI * 2; s.push(P(x - 3, BY + (BR + 1.4) * Math.cos(t), BZ + (BR + 1.4) * Math.sin(t)), P(x + 3, BY + (BR + 1.4) * Math.cos(t), BZ + (BR + 1.4) * Math.sin(t))); }
    mk("path", { d: poly(hull(s)), class: "lo" }, barG);
  }

  const body = mk("g", {}, g);
  const [r0, r1] = rings(0, 0, W, D, 7, 2);
  put(solid(body), prism(P, front, r0, r1, 0, H));
  const lid = mk("g", {}, g);
  const top = mk("path", {}, lid), flap = mk("path", { class: "sil" }, lid), buckle = mk("path", { class: "lo" }, lid);

  const ang = tween(14);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const L = lidPts(a).map((p) => P(...p));
    top.setAttribute("d", poly(fillet([L[0], L[1], L[2], L[3]], [3, 3, 3, 3])));
    flap.setAttribute("d", poly(fillet([L[3], L[2], L[5], L[4]], [2, 2, 5, 5])));
    const bk = [[W / 2 - 6, D + 1, H - FL + 2], [W / 2 + 6, D + 1, H - FL + 2], [W / 2 + 6, D + 1, H - FL + 9], [W / 2 - 6, D + 1, H - FL + 9]].map((p) => P(...rot(...p, a)));
    buckle.setAttribute("d", poly(fillet(bk, [1.5, 1.5, 1.5, 1.5])));
    if (a > 95) lid.before(body); else body.after(lid);
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const box = hull([[0, 0, 0], [W, 0, 0], [W, D, 0], [0, D, 0], [0, 0, H], [W, 0, H], [W, D, H], [0, D, H]].map((p) => P(...p)));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const bx0 = Math.min(...xs), bx1 = Math.max(...xs), by0 = Math.min(...ys) - 10, by1 = Math.max(...ys);
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? maxA : 14, performance.now(), 0);
    flap.classList.add("hi");
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setOn(sx > bx0 && sx < bx1 && sy > by0 && sy < by1), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = clamp(v, 60, 115); if (on) { tset(ang, maxA, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

