roomsign.code:
/**
 * Valet tag: a valet's paper key tag with a punched eyelet and a tear-off
 * stub, hung by its string from the peg of a desk stand. The pointer swings
 * it on the peg, the tag kicking out to one side. At rest it hangs with a
 * slight lean, bright. The slider is how far it swings.
 *
 * The pattern: one part swinging on the discrete clock; hit on the ground.
 */
const {
  Cam, circ, clamp, fillet, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PY = -22, PZ = 118, TY = 10, SL = 10, REST = 0.14, MAXA = 0.95;
const SHAPE = fillet([[-11, 0], [11, 0], [21, -12], [21, -78], [-21, -78], [-21, -12]], [2, 2, 3, 3, 3, 3], 4);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-34, -34, 0], [34, 34, 0], [34, -34, 0], [-34, 34, 0], [0, PY, PZ + 6], [-70, TY, PZ - 50], [70, TY, PZ - 50], [0, TY, PZ - SL - 80]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(30, 44), circ(28, 44), 0, 5));
  const [pr, pi] = rings(-3, PY - 3, 3, PY + 3, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 5, PZ + 4));
  const [ar, ai] = rings(-2, PY, 2, TY + 6, 2, 0.8);
  put(solid(g), prism(P, front, ar, ai, PZ - 2, PZ + 2));
  const str = mk("path", { class: "nf lo" }, g), tag = mk("path", { class: "sil hi" }, g);
  const eye = mk("path", { class: "nf lo" }, g), perf = mk("path", { class: "nf lo" }, g);
  const A = tween(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a), top = PZ - 2;
    const q = (u, w, y = TY) => { const ww = w - SL; return P(u * c - ww * s, y, top + u * s + ww * c); };
    const pts = [];
    for (const y of [TY - 1, TY + 1]) for (const [u, w] of SHAPE) pts.push(q(u, w, y));
    tag.setAttribute("d", poly(hull(pts)));
    eye.setAttribute("d", poly(circ(3.2, 16).map((o) => q(o.u, -7 + o.v, TY + 1))));
    let d = "";
    for (let u = -19; u < 19; u += 4) d += seg(q(u, -56, TY + 1), q(u + 2, -56, TY + 1));
    perf.setAttribute("d", d);
    str.setAttribute("d", seg(P(0, TY, top), q(-2, -7, TY)) + seg(P(0, TY, top), q(2, -7, TY)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(A, now)); return !tdone(A, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    const k = v ? 1 : 0;
    if (k === on) return;
    on = k;
    const a = k ? -MAXA * clamp(reach, 0.15, 1) : REST;
    tset(A, a, performance.now(), 0);
    read.textContent = k ? "swing " + Math.round((-a * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 40); setOn(Math.abs(x) < 70 && Math.abs(y - TY) < 70); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "roomsign",
  means: "A valet key tag with an eyelet and tear-off stub, hung on a desk peg: the pointer swings it out to one side.",
  rules: [1, 3, 5, 8],
  range: [0.2, 1, 1],
  tour: [[194, 139], [175, 120], [217, 206], null],
  mount,
});

whistle.code:
/**
 * Whistle: a pea whistle on a lanyard, its loop hanging off a hook ring.
 * The pointer on the whistle tips it up on its ring, mouthpiece raised to
 * blow. At rest it hangs slightly tipped, bright. The slider is the tip.
 */
const {
  Cam, fit, hull, open, poly, proj, rings, clamp, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, register, solid,
} = HL;

const PX = 44, PZ = 30;
function rotY(p, a) {
  const dx = p[0] - PX, dz = p[2] - PZ, c = Math.cos(a), s = Math.sin(a);
  return [PX + dx * c - dz * s, p[1], PZ + dx * s + dz * c];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.0);
  const ext = [[-22, 6, 20], [-22, 14, 12], [28, 20, 4], [0, 0, 24], [28, 0, 4]].flatMap((p) => [rotY(p, rad(-70)), rotY(p, rad(-10))]);
  fit(C, ext.concat([[PX + 16, -12, 0], [PX, 10, 0]]), 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  // ground cord: the lanyard lying away from the ring
  const cord = mk("path", { class: "nf lo" }, g);
  const pts = [];
  for (let i = 0; i <= 16; i++) { const t = i / 16; pts.push(P(PX + 16 * t, 10 - 22 * t + 6 * Math.sin(t * 6), PZ * (1 - t) * (1 - t))); }
  cord.setAttribute("d", open(pts));
  const parts = [
    { box: [0, 0, 28, 20, 4, 24], r: 9, b: 1.6 },
    { box: [-22, 6, 0, 14, 12, 20], r: 2, b: 1 },
  ];
  const sols = parts.map(() => solid(g));
  const ring = mk("path", { class: "nf" }, g);
  const pea = mk("path", { class: "nf lo" }, g);
  function solidPts(pt, a) {
    const [x0, y0, x1, y1, z0, z1] = pt.box;
    const [rg, inn] = rings(x0, y0, x1, y1, pt.r, pt.b);
    const pr = (q, z) => P(...rotY([q.u, q.v, z], a));
    const sil = poly(hull(rg.map((q) => pr(q, z0)).concat(rg.map((q) => pr(q, z1)))));
    const cr = poly(inn.map((q) => pr(q, z1)));
    return { sil, cr };
  }
  const tw = tween(rad(-10));
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    parts.forEach((pt, i) => { const d = solidPts(pt, a); sols[i].sil.setAttribute("d", d.sil); sols[i].cr.setAttribute("d", d.cr); });
    const rp = [];
    for (let i = 0; i <= 20; i++) { const t = (i / 20) * Math.PI * 2; rp.push(P(...rotY([PX - 6 + 7 * Math.cos(t), 10, PZ + 7 * Math.sin(t)], a))); }
    ring.setAttribute("d", poly(rp));
    const sp = [];
    for (let i = 0; i <= 16; i++) { const t = (i / 16) * Math.PI * 2; sp.push(P(...rotY([10 + 5 * Math.cos(t), 10 + 5 * Math.sin(t), 24], a))); }
    pea.setAttribute("d", poly(sp));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const mid = P(10, 10, 14);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? rad(-10 - 60 * clamp(amt, 0.2, 1)) : rad(-10), performance.now(), 0);
    sols[0].sil.classList.toggle("hi", true);
    read.textContent = on ? "blow" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([x, y]) => setActive(Math.hypot(x - mid[0], y - mid[1]) < 80), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "whistle",
  means: "A pea whistle on its lanyard: the pointer tips it up on its ring, mouthpiece raised to blow.",
  rules: [1, 3, 5, 8],
  range: [0.2, 0.7, 1],
  tour: [[164, 202], [140, 190], [185, 214], null],
  mount,
