fitband.code:
/**
 * Fitness band: a tracker pod with a screen and two straps lying open on the
 * desk, one strap punched with holes, the other ending in its clasp. The
 * pointer picks a strap by where it stands: that strap swings up about the
 * pod as if wrapping a wrist. At rest the clasp strap is a little raised,
 * bright. The slider is how far the strap swings.
 */
const { Cam, fit, hull, poly, proj, rings, rrect, ringAt, facing, prism, circ, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid, rad } = HL;

const PX = 13, ZP = 1.4, SL = 40, SW = 6, ST = 2.6, REST = [20, 52];
const disc = (x, y, r, n = 12) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let openA = value;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-PX - SL, -9, 0], [PX + SL, 9, 0], [-PX - SL, 9, 0], [PX + SL, -9, 0], [PX, 0, SL + 4], [-PX, 0, SL + 4], [0, 0, SL * 0.8]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // a strap, in its own frame: u runs out from the pod, y across, w up from the pivot
  const plate = rrect(-3, -SW, SL, SW, 5, 10), crease = rrect(-1, -SW + 1.2, SL - 1.2, SW - 1.2, 3.8, 10);
  const buckle = rrect(SL - 9, -SW - 1.6, SL + 1, SW + 1.6, 2.5, 6), slot = rrect(SL - 6.5, -SW + 0.8, SL - 2, SW - 0.8, 1.2, 6);
  const straps = [-1, 1].map((s, k) => ({ s, k, el: solid(g), extra: null, a: tween(REST[k]), last: NaN }));
  straps.forEach((st) => (st.extra = mk("path", { class: "nf lo" }, st.el.g)));
  const pod = solid(g);
  const [pr, pi] = rings(-PX - 1, -8, PX + 1, 8, 7.5, 1.5);
  put(pod, prism(P, front, pr, pi, 0, 7));
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(-8, -4.5, 8, 4.5, 3, 6), 7)) }, pod.g);
  g.appendChild(straps[1].el.g);

  function drawStrap(st, a) {
    if (a === st.last) return;
    st.last = a;
    const c = Math.cos(rad(a)), sn = Math.sin(rad(a)), s = st.s;
    const W = (u, y, w) => P(s * (PX + u * c - w * sn), y, ZP + u * sn + w * c);
    const ring = (rg, w) => rg.map((q) => W(q.u, q.v, w));
    const pts = ring(plate, -ST / 2).concat(ring(plate, ST / 2));
    const d = poly(hull(s > 0 ? pts.concat(ring(buckle, -ST / 2 - 0.4), ring(buckle, ST / 2 + 1)) : pts));
    st.el.sil.setAttribute("d", d);
    st.el.cr.setAttribute("d", poly(ring(s > 0 ? rrect(-1, -SW + 1.2, SL - 10, SW - 1.2, 3.8, 10) : crease, ST / 2)));
    let marks = "";
    if (s < 0) for (const u of [16, 21, 26, 31]) marks += poly(ring(disc(u, 0, 1.1), ST / 2));
    else marks = poly(ring(buckle, ST / 2 + 1)) + poly(ring(slot, ST / 2 + 1));
    st.extra.setAttribute("d", marks);
    if (s < 0) { if (a > 80) pod.g.after(st.el.g); else g.insertBefore(st.el.g, g.firstChild); }
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    straps.forEach((st) => { drawStrap(st, tval(st.a, now)); if (!tdone(st.a, now)) m = true; });
    return m;
  });
  bag.add(B.unregister);
  const mids = [-1, 1].map((s) => P(s * (PX + SL / 2), 0, 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = k; } });
    return bd < 80 ? best : -1;
  }
  let act = -2;
  function apply() {
    const now = performance.now();
    straps.forEach((st) => tset(st.a, act < 0 ? REST[st.k] : st.k === act ? openA : 2, now, 0));
  }
  function setActive(a) {
    if (a === act) return;
    act = a;
    apply();
    straps.forEach((st) => st.el.sil.classList.toggle("hi", st.k === (a < 0 ? 1 : a)));
    read.textContent = a < 0 ? "rest" : a === 1 ? "clasp" : "holes";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { openA = v; if (act >= 0) { apply(); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "fitband",
  means: "A fitness band lying open: the strap under the pointer swings up about the tracker pod, as if wrapping a wrist.",
  rules: [1, 4, 5, 8],
  range: [60, 110, 140],
  tour: [[284, 245], [200, 212], [120, 185], null],
  mount,
});

dronecontroller.code:
/**
 * Drone remote: a flat controller with two thumb sticks and a pair of wide
 * paddle antennas hinged along its back edge. At rest the antennas lean back
 * low, bright. The pointer over the remote swings them up to stand tall, on
 * a spring. The slider is how far they swing.
 *
 * The pattern: one part answering (aim), hit on the rest footprint.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 64, D = 32, H = 10, AL = 30, HZ = 6, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-4, -AL, 0], [W + 4, D + 4, 0], [W + 4, -4, AL + HZ], [-4, -4, AL + HZ], [W + 4, -AL, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the antennas: two paddles on one hinge line behind the body
  const ants = [[6, 26], [W - 26, W - 6]].map(([x0, x1]) => {
    const [o, i] = rings(x0, 0, x1, AL, 4, 1.2);
    return { o, i, el: solid(g) };
  });
  const hinge = mk("path", { class: "nf lo" }, g);
  hinge.setAttribute("d", open([P(4, -1, HZ), P(W - 4, -1, HZ)]));

  // the body, its grips and the sticks
  const [bo, bi] = rings(0, 0, W, D, 9, 1.6);
  put(solid(g), prism(P, front, bo, bi, 0, H));
  const disc = (x, y, r) => circ(r, 24).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
  for (const x of [16, W - 16]) {
    put(solid(g), prism(P, front, disc(x, 14, 5), disc(x, 14, 4), H, H + 2));
    put(solid(g), prism(P, front, disc(x, 14, 1.6), disc(x, 14, 1), H + 2, H + 7));
  }
  const pad = rings(W / 2 - 6, 20, W / 2 + 6, 26, 2, 0.8);
  put(solid(g), prism(P, front, pad[0], pad[1], H, H + 1));

  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const T = (q, w) => P(q.u, -1 - q.v * c + w * s, HZ + q.v * s + w * c);
    for (const an of ants) {
      const pts = an.o.map((q) => T(q, 0)).concat(an.o.map((q) => T(q, 2.2)));
      an.el.sil.setAttribute("d", poly(hull(pts)));
      an.el.cr.setAttribute("d", open(run(an.i, front).map((q) => T(q, 2.2))));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(clamp(sp.x, 0, 90)); return m; });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    sp.t = v ? clamp(REST + swing, 0, 90) : REST;
    for (const an of ants) an.el.sil.classList.add("hi");
    read.textContent = v ? "ant " + Math.round(sp.t) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -4 && x < W + 4 && y > -12 && y < D + 4;
  }
  setOn(false);
  draw(REST);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (on) { sp.t = clamp(REST + v, 0, 90); read.textContent = "ant " + Math.round(sp.t) + "°"; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "dronecontroller",
  means: "A drone remote with two thumb sticks: over it, the paddle antennas on its back edge swing up to stand tall.",
  rules: [1, 3, 5, 8],
  range: [30, 66, 76],
  tour: [[98, 141], [131, 186], [165, 232], null],
  mount,
});

cameradoor.code:
/**
 * Action camera: a small rounded box with a round lens on its front, a
 * shutter button on top and a battery door on its side. At rest the door
 * stands ajar, bright. The pointer over the camera swings the door open on
 * its hinge, on a spring, to show the battery. The slider is how far.
 *
 * The pattern: one part answering (aim), hit on the rest footprint.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, run, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 44, D = 30, H = 32, LU = D - 4, REST = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 3.65);
  fit(C, [[0, 0, 0], [W, D + 8, 0], [W + LU, 2, 0], [W + LU, 2, H], [0, 0, H + 3], [W + 4, D, 0], [W + 24, -9, H], [W + 24, -9, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [bo, bi] = rings(0, 0, W, D, 6, 1.6);
  put(solid(g), prism(P, front, bo, bi, 0, H));
  // the shutter button on top
  const [so, si] = rings(W - 18, 8, W - 8, 16, 2.5, 1);
  put(solid(g), prism(P, front, so, si, H, H + 2.6));
  // the lens: a barrel standing out of the front face, glass inside
  const LX = 15, LZ = H / 2 + 1, Y = (q, r, w) => P(LX + q.u * r, D + w, LZ + q.v * r);
  const ring = circ(1, 40);
  const barrel = solid(g);
  barrel.sil.setAttribute("d", poly(hull(ring.map((q) => Y(q, 10, 0)).concat(ring.map((q) => Y(q, 10, 5))))));
  barrel.cr.setAttribute("d", poly(ring.map((q) => Y(q, 7, 5))));
  mk("path", { class: "nf lo", d: poly(ring.map((q) => Y(q, 3.5, 5.2))) }, g);
  // the battery in its bay on the side face
  const X = (u, v) => P(W + 0.2, 4 + u, v);
  const [to, ti] = rings(2, 5, LU - 4, H - 5, 2, 1);
  mk("path", { class: "nf lo", d: poly(to.map((q) => X(q.u, q.v))) }, g);
  mk("path", { class: "nf lo", d: poly(ti.map((q) => X(q.u, q.v + 4))).replace(/Z$/, "") }, g);

  // the door: a plate hinged on the side face's far edge
  const [dO, dI] = rings(0, 3, LU, H - 3, 3, 1.2);
  const door = solid(g);
  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const T = (q, w) => P(W + q.u * s + w * c, 2 + q.u * c - w * s, q.v);
    door.sil.setAttribute("d", poly(hull(dO.map((q) => T(q, 0)).concat(dO.map((q) => T(q, 2))))));
    door.cr.setAttribute("d", poly(dI.map((q) => T(q, 2))));
  }
  door.sil.classList.add("hi");
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(clamp(sp.x, 0, 115)); return m; });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    sp.t = v ? clamp(REST + swing, 0, 115) : REST;
    read.textContent = v ? "door " + Math.round(sp.t) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    return x > -4 && x < W + 10 && y > -4 && y < D + 6;
  }
  setOn(false);
  draw(REST);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (on) { sp.t = clamp(REST + v, 0, 115); read.textContent = "door " + Math.round(sp.t) + "°"; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "cameradoor",
  means: "An action camera with a round lens: over it, the battery door on its side swings open on its hinge to show the battery.",
  rules: [1, 3, 5, 8],
  range: [40, 86, 100],
  tour: [[101, 72], [119, 115], [137, 163], null],
  mount,
});

servomotor.code:
/**
 * Servo: a hobby servo, its case standing on two mounting tabs, the output
 * shaft near one end, a long double-arm horn on the spline. The pointer over
 * the servo drives it: the horn sweeps round on its shaft. At rest the horn
 * sits a little askew, bright. The slider is how far the horn sweeps.
 *
 * The pattern: one part turning about a fixed pivot.
 */
const { Cam, fit, facing, circ, hull, poly, prism, proj, rad, rings, tset, tval, tdone, tween, disposer, flatDot, mk, place, pointer, put, register, solid } = HL;

const SX = 11, HZ = 27, L = 27;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 4.3);
  fit(C, [[-30, -12, 0], [30, 12, 0], [-30, 12, 0], [30, -12, 0], [SX - L - 4, -L, HZ], [SX + L + 4, L, HZ], [SX - L, L, HZ], [SX + L, -L, HZ]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-20, -10, 20, 10, 3, 1.4);
  put(solid(g), prism(P, front, br, null, 0, 15));
  const [tr, ti] = rings(-29, -6, 29, 6, 2.5, 1.1);
  put(solid(g), prism(P, front, tr, ti, 15, 17));
  for (const x of [-25.5, 25.5]) place(flatDot(g, C, 1.3, "dot off"), P(x, 0, 17));
  put(solid(g), prism(P, front, br, bi, 17, 22));
  put(solid(g), prism(P, front, disc(SX, 0, 6.5), disc(SX, 0, 5.3), 22, 24.5));
  put(solid(g), prism(P, front, disc(SX, 0, 4.2, 20), null, 24.5, HZ - 2.5));

  const horn = solid(g);
  horn.sil.classList.add("hi");
  const holes = [8, 13, 18, 23, -8, -13, -18, -23].map(() => flatDot(g, C, 0.9, "dot off"));
  const screw = flatDot(g, C, 1.5, "dot m");
  const plan = [];
  for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; plan.push([6.5 * Math.cos(t), 6.5 * Math.sin(t)], [L + 3.2 * Math.cos(t), 3.2 * Math.sin(t)], [-L + 3.2 * Math.cos(t), 3.2 * Math.sin(t)]); }
  const inner = plan.map(([u, v]) => [u * 0.9, v * 0.78]);

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = rad(28 + 100 * amp * t), ca = Math.cos(a), sa = Math.sin(a);
    const K = ([u, v], z) => P(SX + u * ca - v * sa, u * sa + v * ca, z);
    horn.sil.setAttribute("d", poly(hull(plan.map((p) => K(p, HZ - 2.5)).concat(plan.map((p) => K(p, HZ))))));
    horn.cr.setAttribute("d", poly(hull(inner.map((p) => K(p, HZ)))));
    [8, 13, 18, 23, -8, -13, -18, -23].forEach((u, i) => place(holes[i], K([u, 0], HZ)));
    place(screw, K([0, 0], HZ));
  }
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, 12);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "sweep" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 150 && Math.abs(sy - mid[1]) < 110), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; draw(tval(tw, performance.now())); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "servomotor",
  means: "A hobby servo on its mounting tabs: the pointer drives it, and the long horn sweeps round on the output shaft.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1.4],
  tour: [[230, 186], [150, 150], [227, 215], null],
  mount,
});

linearrail.code:
/**
 * Linear actuator: an electric linear actuator lying on the bench, a square
 * tube with its motor alongside and a gearbox joining them at the back, a
 * polished rod in the tube ending in a rod-end eye. The pointer over it runs
 * the motor: the rod drives out of the tube. At rest the rod sits nearly home,
 * bright. The slider is the stroke, how far the rod drives out.
 *
 * The pattern: one part sliding along a fixed axis.
 */
const { Cam, fit, facing, circ, hull, poly, prism, proj, rings, tset, tval, tdone, tween, disposer, flatDot, mk, place, pointer, put, register, solid } = HL;

const ZA = 11, X1 = 18, STROKE = 44;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[-50, -9, 0], [-50, 25, 0], [X1 + 12 + STROKE * 1.3, -6, 0], [X1 + 12 + STROKE * 1.3, 6, 18], [-50, -9, 20], [0, 25, 20]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const R = (x0, y0, x1, y1, r, b) => rings(x0, y0, x1, y1, r, b);
  put(solid(g), prism(P, front, ...R(-50, -9, -38, 25, 4, 1.2), 2, 20));
  put(solid(g), prism(P, front, ...R(-38, -7, X1, 7, 3, 1.2), 4, 18));
  put(solid(g), prism(P, front, ...R(-38, 10, -2, 24, 6.5, 1.4), 4, 18));
  for (const x of [-34, -26, -18]) place(flatDot(g, C, 0.9, "dot off"), P(x, 17, 18));
  put(solid(g), prism(P, front, ...R(X1 - 1, -6, X1 + 3, 6, 2, 0.8), 5, 17));

  const rod = solid(g), eye = solid(g);
  rod.sil.classList.add("hi");
  const hole = flatDot(g, C, 1.6, "dot m");
  const ring = circ(3.6, 24), inner = circ(2.4, 24);
  const at = (q, x) => P(x, q.u, ZA + q.v);

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const e = X1 + 3 + 6 + STROKE * amp * t;
    rod.sil.setAttribute("d", poly(hull(ring.map((q) => at(q, X1 + 3)).concat(ring.map((q) => at(q, e))))));
    rod.cr.setAttribute("d", "");
    put(eye, prism(P, front, ...rings(e - 1, -5.5, e + 11, 5.5, 5.4, 1.3), ZA - 4.5, ZA + 4.5));
    place(hole, P(e + 5.5, 0, ZA + 4.5));
  }
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 8, 10);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "extend" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 170 && Math.abs(sy - mid[1]) < 110), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; draw(tval(tw, performance.now())); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "linearrail",
  means: "An electric linear actuator, motor alongside its tube: the pointer runs it, and the rod drives out to its rod-end eye.",
  rules: [1, 4, 5, 8],
  range: [0.4, 1, 1.3],
  tour: [[241, 172], [150, 150], [267, 195], null],
