pantilt.code:
/**
 * Pan tilt head: a pan servo standing on the bench, a turntable on its shaft,
 * a U-bracket rising from the turntable and, held between its arms, a small
 * camera block with its lens. The pointer over the head aims it: the bracket
 * pans round and the camera tilts up on its axle. At rest the camera looks a
 * little off to one side, bright. The slider is how far the head swings.
 *
 * The pattern: nested turns, a pan about z carrying a tilt about y.
 */
const { Cam, fit, facing, circ, hull, poly, prism, proj, rad, rings, rrect, tset, tval, tdone, tween, disposer, flatDot, mk, place, pointer, put, register, solid } = HL;

const AZ = 38;
// [ring, extrusion range, mapping (u, v, w) -> local x, y, z]
const box = (x0, y0, x1, y1, z0, z1, r) => ({ ring: rrect(x0, y0, x1, y1, r, 4), inner: rrect(x0 + 1.4, y0 + 1.4, x1 - 1.4, y1 - 1.4, r - 1, 4), w: [z0, z1], map: (u, v, w) => [u, v, w] });
const side = (y, x0, x1, z0, z1) => ({ ring: rrect(x0, z0, x1, z1, 2.5, 4), inner: null, w: [y - 1, y + 1], map: (u, v, w) => [u, w, v] });
const lens = { ring: circ(5.2, 20), inner: circ(3.8, 20), w: [13, 20], map: (u, v, w) => [w, u, AZ + v] };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 4.4);
  fit(C, [[-17, -13, 0], [17, 13, 0], [-17, 13, 0], [17, -13, 0], [-22, -22, 50], [22, 22, 50], [-22, 22, 30], [22, -22, 30], [0, 0, 56]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-15, -11, 15, 11, 3, 1.4);
  put(solid(g), prism(P, front, sr, null, 0, 13));
  put(solid(g), prism(P, front, rings(-19, -5, 19, 5, 2, 1)[0], rings(-19, -5, 19, 5, 2, 1)[1], 13, 15));
  for (const x of [-16.5, 16.5]) place(flatDot(g, C, 1, "dot off"), P(x, 0, 15));
  put(solid(g), prism(P, front, sr, si, 15, 19));

  const parts = [
    { s: box(-13, -14, 13, 14, 19, 22, 12) },
    { s: side(-13, -5, 5, 21, 42), z: 1 },
    { s: side(13, -5, 5, 21, 42), z: 1 },
    { s: box(-11, -9, 13, 9, AZ - 7, AZ + 7, 3), tilt: true, hi: true },
    { s: lens, tilt: true },
  ];
  for (const p of parts) { p.el = solid(g); if (p.hi) p.el.sil.classList.add("hi"); }
  const axle = [flatDot(g, C, 1.2, "dot m"), flatDot(g, C, 1.2, "dot m")];

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const pa = rad(12 + 80 * amp * t), ta = rad(8 + 32 * amp * t);
    const cp = Math.cos(pa), sp = Math.sin(pa), ct = Math.cos(ta), st = Math.sin(ta);
    const W = ([x, y, z], tl) => {
      if (tl) { const dz = z - AZ; [x, z] = [x * ct - dz * st, AZ + x * st + dz * ct]; }
      return [x * cp - y * sp, x * sp + y * cp, z];
    };
    const depth = [];
    for (const p of parts) {
      const { ring, inner, w, map } = p.s;
      const pts = [];
      for (const ww of w) for (const q of ring) pts.push(P(...W(map(q.u, q.v, ww), p.tilt)));
      p.el.sil.setAttribute("d", poly(hull(pts)));
      p.el.cr.setAttribute("d", inner ? poly(inner.map((q) => P(...W(map(q.u, q.v, w[1]), p.tilt)))) : "");
      const c = W(map(0, p.s === lens ? 0 : (p.s.ring[0].v + p.s.ring[8].v) / 2, (w[0] + w[1]) / 2), p.tilt);
      depth.push([c[0] + c[1] + (p.s === lens ? 0 : 0), p]);
    }
    const [base, ...rest] = depth;
    rest.sort((a, b) => a[0] - b[0]);
    let prev = base[1].el.g;
    for (const [, p] of rest) { prev.after(p.el.g); prev = p.el.g; }
    [-14.5, 14.5].forEach((y, i) => place(axle[i], P(...W([0, y, AZ], false))));
    for (let i = 0; i < 2; i++) parts[1 + i].el.g.after(axle[i]);
  }
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, 25);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "aim" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 140 && Math.abs(sy - mid[1]) < 120), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; draw(tval(tw, performance.now())); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pantilt",
  means: "A pan tilt head on its servo: the pointer aims it, the bracket panning round and the camera tilting up between its arms.",
  rules: [1, 4, 5, 6, 8],
  range: [0.4, 1, 1.3],
  tour: [[200, 101], [150, 170], [262, 151], null],
  mount,
});

breadboard2.code:
/**
 * Breadboard: a solderless breadboard, rows of contact holes either side of
 * the centre channel and a power rail along each edge, one jumper wire arched
 * across the channel on its two plugs. The pointer over the board pulls the
 * jumper's far plug out and swings it round to a new row. At rest the jumper
 * spans the channel, bright. The slider is how far it swings.
 *
 * The pattern: one part turning about a fixed pivot, lifting as it goes.
 */
const { Cam, fit, facing, poly, prism, proj, rad, rings, open, tset, tval, tdone, tween, disposer, flatDot, mk, place, pointer, put, register, solid } = HL;

const BZ = 6, A = [-20, 11], B0 = [12, -13], PH = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[-46, -30, 0], [46, 30, 0], [-46, 30, 0], [46, -30, 0], [-20, 11, 44], [-46, -30, 30]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-46, -30, 46, 30, 4, 1.6), 0, BZ));
  mk("path", { class: "nf lo", d: open([P(-42, -1.2, BZ), P(42, -1.2, BZ)]) + open([P(-42, 1.2, BZ), P(42, 1.2, BZ)]) }, g);
  for (const y of [-26, 26]) mk("path", { class: "nf lo", d: open([P(-40, y + (y < 0 ? 3.5 : -3.5), BZ), P(40, y + (y < 0 ? 3.5 : -3.5), BZ)]) }, g);
  for (let x = -40; x <= 40; x += 6) for (const y of [-21, -16, -11, -6, 6, 11, 16, 21, -26, 26]) if (Math.abs(y) < 26 || (x + 46) % 12 !== 0) place(flatDot(g, C, 0.6, "dot off"), P(x, y, BZ));

  const plugA = solid(g);
  put(plugA, prism(P, front, ...rings(A[0] - 2, A[1] - 2, A[0] + 2, A[1] + 2, 0.8, 0.5), BZ, BZ + PH));
  const wire = mk("path", { class: "sil hi" }, g);
  const plugB = solid(g);
  const pin = flatDot(g, C, 0.9, "dot m");

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = rad(-118 * amp * t), ca = Math.cos(a), sa = Math.sin(a);
    const dx = B0[0] - A[0], dy = B0[1] - A[1];
    const B = [A[0] + dx * ca - dy * sa, A[1] + dx * sa + dy * ca], lift = 13 * t;
    put(plugB, prism(P, front, ...rings(B[0] - 2, B[1] - 2, B[0] + 2, B[1] + 2, 0.8, 0.5), BZ + lift, BZ + PH + lift));
    place(pin, P(B[0], B[1], BZ + lift));
    const c = [];
    for (let i = 0; i <= 24; i++) {
      const s = i / 24, e = s * s * (3 - 2 * s);
      c.push(P(A[0] + (B[0] - A[0]) * e, A[1] + (B[1] - A[1]) * e, BZ + PH + lift * s + 22 * Math.sin(Math.PI * s)));
    }
    const L = [], R = [];
    for (let i = 0; i < c.length; i++) {
      const p = c[Math.max(0, i - 1)], q = c[Math.min(c.length - 1, i + 1)];
      const tx = q[0] - p[0], ty = q[1] - p[1], n = Math.hypot(tx, ty) || 1, w = 1.6;
      L.push([c[i][0] - (ty / n) * w, c[i][1] + (tx / n) * w]);
      R.push([c[i][0] + (ty / n) * w, c[i][1] - (tx / n) * w]);
    }
    wire.setAttribute("d", poly(L.concat(R.reverse())));
    if ((B[0] + B[1]) > (A[0] + A[1])) wire.after(plugB.g); else plugB.g.after(wire);
    plugB.g.after(pin);
  }
  const tw = tween(0);
  const Bk = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(Bk.unregister);

  const mid = P(0, 0, BZ);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "row 9" : "rest";
    Bk.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 160 && Math.abs(sy - mid[1]) < 100), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; draw(tval(tw, performance.now())); Bk.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "breadboard2",
  means: "A solderless breadboard with one jumper wire: the pointer pulls the jumper's far plug out and swings it round to a new row.",
  rules: [1, 4, 5, 6, 8],
  range: [0.4, 1, 1.3],
  tour: [[194, 128], [120, 200], [300, 215], null],
  mount,
});

archivebox.code:
/**
 * Archive box: a cardboard banker's box with a telescoping lid, hand holes in
 * its ends and a label frame on the front. Over the box the lid lifts off and
 * tips back, showing the files standing inside. At rest the lid sits a little
 * askew on top, bright. The slider is how high the lid lifts.
 */
const {
  Cam, facing, fit, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 104, Y1 = 66, H = 56, SK = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [X1, Y1, 0], [X1, 0, 0], [0, Y1, 0], [0, -20, H + 70], [X1, -20, H + 70]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the files standing inside, painted before the body that frames them
  const files = [10, 26, 42, 58, 74, 88].map((x, k) => {
    const s = solid(g), top = H - 8 + (k % 3) * 3 - 3;
    const [fr, fi] = rings(x, 5, x + 3, Y1 - 5, 1, 0.6);
    put(s, prism(P, front, fr, fi, 2, top));
    return s;
  });

  // the body, open at the top
  const [br, bi] = rings(0, 0, X1, Y1, 3, 1.2);
  const bp = prism(P, front, br, bi, 0, H);
  mk("path", { class: "sil", "fill-rule": "evenodd", d: bp.sil + " " + poly(ringAt(P, rrect(1.6, 1.6, X1 - 1.6, Y1 - 1.6, 2, 4), H)) }, g);
  // hand hole in the right end, label frame on the front
  const hole = rrect(Y1 / 2 - 14, H - 20, Y1 / 2 + 14, H - 12, 4, 4).map((q) => P(X1, q.u, q.v));
  mk("path", { class: "lo", d: poly(hole) }, g);
  mk("path", { class: "nf lo", d: poly([P(X1 / 2 - 18, Y1, H - 34), P(X1 / 2 + 18, Y1, H - 34), P(X1 / 2 + 18, Y1, H - 22), P(X1 / 2 - 18, Y1, H - 22)]) }, g);

  // the lid: a shallow tray turned over, lifting and tipping about its back edge
  const lid = solid(mk("g", {}, g));
  const lo = rrect(-2, -2, X1 + 2, Y1 + 2, 3.5, 4), li = rrect(-0.6, -0.6, X1 + 0.6, Y1 + 0.6, 3, 4);
  const hole2 = mk("path", { class: "nf lo" }, lid.g);
  const LZ = H - SK + 1;
  const L = (u, v, z, a, h) => P(u, -2 + (v + 2) * Math.cos(a) - z * Math.sin(a), LZ + h + (v + 2) * Math.sin(a) + z * Math.cos(a));
  const up = tween(0);
  let last = NaN;

  function drawLid(t) {
    if (t === last) return;
    last = t;
    const h = 3 + t, a = rad(5 + t * 0.7);
    lid.sil.setAttribute("d", poly(hull(lo.map((q) => L(q.u, q.v, 0, a, h)).concat(lo.map((q) => L(q.u, q.v, SK, a, h))))));
    lid.cr.setAttribute("d", poly(li.map((q) => L(q.u, q.v, SK, a, h))));
    lid.cr.setAttribute("class", "nf lo");
    hole2.setAttribute("d", poly(rrect(Y1 / 2 - 10, 3, Y1 / 2 + 10, 8, 2.5, 4).map((q) => L(X1 + 2, q.u, q.v, a, h))));
  }

  const B = register(stage, (_dt, now) => {
    drawLid(tval(up, now));
    return !tdone(up, now);
  });
  bag.add(B.unregister);
  lid.sil.classList.add("hi");

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H / 2);
    return x > -16 && x < X1 + 16 && y > -16 && y < Y1 + 16;
  }
  let act = null;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(up, a ? lift : 0, performance.now(), 0);
    read.textContent = a ? "+" + Math.round(lift) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "archivebox",
  means: "A cardboard archive box: over it the telescoping lid lifts off and tips back to show the files inside; the slider sets the lift.",
  rules: [1, 4, 5, 6],
