  name: "bookcradle",
  means: "A book open on a foam cradle: over it the book opens flatter and the wedges sink with it; the slider sets how far it opens.",
  rules: [1, 4, 5, 6],
  range: [10, 24, 30],
  tour: [[200, 161], [222, 186], [180, 176], null],
  mount,
});

cat6.code:
/**
 * Sash window: a window frame on its sill with two glazed sashes, the upper
 * one fixed and the lower one in front of it. Raising the pointer slides the
 * lower sash up over the upper one; lower, it comes back down. At rest it
 * stands open a hand's width, bright.
 *
 * The pattern: one part following a continuous input (spring).
 */
const {
  Cam, fit, facing, prism, proj, rings, clamp, spring, stepS, poly, seg,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 9, X0 = 6, X1 = 58;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value, syLast = null;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-4, 0, 0], [68, 14, 0], [0, 0, 100], [64, 8, 100]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent) => {
    const [o, i] = rings(x0, y0, x1, y1, r, b), s = solid(parent || g);
    put(s, prism(P, front, o, i, z0, z1));
    return s;
  };
  const face = (y, z0, z1, el) => {
    const w = (X1 - X0) / 3, zm = (z0 + z1) / 2;
    let d = poly([P(X0 + 4, y, z0 + 4), P(X1 - 4, y, z0 + 4), P(X1 - 4, y, z1 - 4), P(X0 + 4, y, z1 - 4)]);
    d += seg(P(X0 + w, y, z0 + 4), P(X0 + w, y, z1 - 4)) + seg(P(X0 + 2 * w, y, z0 + 4), P(X0 + 2 * w, y, z1 - 4));
    d += seg(P(X0 + 4, y, zm), P(X1 - 4, y, zm));
    el.setAttribute("d", d);
  };
  box(0, 0, 64, 6, 2, 1.2, 4, 100);
  mk("path", { class: "nf lo", d: poly([P(X0, 6, 8), P(X1, 6, 8), P(X1, 6, 94), P(X0, 6, 94)]) }, g);
  box(-4, 0, 68, 14, 2, 1.2, 0, 4);
  box(X0, 6, X1, 8, 1, 0.5, 50, 94);
  face(8, 50, 94, mk("path", { class: "nf lo" }, g));
  const sg = mk("g", {}, g);
  const sash = solid(sg), bars = mk("path", { class: "nf lo" }, sg);
  sash.sil.classList.add("hi");

  let last = NaN;
  function draw(L) {
    if (Math.abs(L - last) < 0.05) return;
    last = L;
    const [o, i] = rings(X0, 8, X1, 10, 1, 0.5);
    put(sash, prism(P, front, o, i, 8 + L, 52 + L));
    face(10, 8 + L, 52 + L, bars);
  }

  const lift = spring(REST);
  draw(REST);
  let on = false;
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); show(); return m; });
  bag.add(B.unregister);
  function show() { read.textContent = on ? "up " + Math.round(lift.x) : "rest"; }
  function aim() { lift.t = syLast == null ? REST : clamp((250 - syLast) / 170, 0, 1) * 40 * reach; B.wake(); }
  show();
  bag.add(pointer(stage, {
    move: ([, sy]) => { on = true; syLast = sy; aim(); },
    leave: () => { on = false; syLast = null; aim(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; aim(); }, destroy: bag.dispose };
}

hairline({
  name: "cat6",
  means: "A sash window on its sill: raise the pointer and the lower sash slides up in front of the upper one; lower it and the sash comes down.",
  rules: [3, 4, 5, 8],
  range: [0.3, 1, 1],
  tour: [[200, 90], [200, 240], [200, 140], null],
  mount,
});

iceshovel.code:
/**
 * Ice scoop: a hotel ice scoop, a round-bottomed trough with a slanted lip
 * and a round handle, lying on a drip tray beside a few cubes. The pointer on
 * the scoop picks it up: it lifts off the tray and tips its lip forward to
 * pour. At rest the scoop lies on the tray and its mouth is bright. The
 * slider is how far it tips.
 *
 * The pattern: one part turning; the hit is the rest pose's outline.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 14, LEN = 50, LIP = 36, HL_ = 34, HR = 3.4, Z0 = 4 + R, N = 18;
const rad = (d) => (d * Math.PI) / 180;
const lipX = (t) => LIP + (LEN - LIP) * (1 - Math.sin(t));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 2.2);
  // local scoop: top edge at z 0, bottom at -R; back plate at x 0
  const back = [], lip = [], backIn = [];
  for (let i = 0; i <= N; i++) {
    const t = (i / N) * Math.PI, y = R * Math.cos(t), z = -R * Math.sin(t);
    back.push([0, y, z]); backIn.push([1.6, y * 0.88, z * 0.88]); lip.push([lipX(t), y, z]);
  }
  const handle = [];
  for (let i = 0; i < 12; i++) {
    const t = (i / 12) * Math.PI * 2, dy = HR * Math.cos(t), dz = HR * Math.sin(t);
    handle.push([0, dy, -R * 0.55 + dz], [-HL_, dy, -R * 0.15 + dz]);
  }
  const pose = (a, lift) => ([x, y, z]) => {
    const c = Math.cos(a), s = Math.sin(a), dx = x, dz = z + R;
    return [dx * c - dz * s, y, -R + dx * s + dz * c + Z0 + lift];
  };
  const POUR = (a) => pose(-rad(a), 6 + 46 * Math.sin(rad(a)));
  const ext = [[-46, -28, 0], [98, 28, 0], [98, -28, 0], [-46, 28, 0]]
    .concat([...back, ...lip, ...handle].map(pose(rad(4), 0)), [...back, ...lip, ...handle].map(POUR(70)));
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-46, -28, 98, 28, 8, 2); put(solid(g), prism(P, front, r, i, 0, 3)); }
  for (const [x, y] of [[62, 2], [74, -12], [80, 6]]) { const [r, i] = rings(x, y, x + 9, y + 9, 1.6, 0.8); put(solid(g), prism(P, front, r, i, 3, 12)); }
  const hd = mk("path", { class: "sil" }, g), shell = mk("path", { class: "sil" }, g);
  const inner = mk("path", { class: "nf lo" }, g), mouth = mk("path", { class: "nf" }, g);

  const ang = tween(-4);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const T = POUR(a), Q = (p) => P(...T(p));
    hd.setAttribute("d", poly(hull(handle.map(Q))));
    shell.setAttribute("d", poly(hull([...back, ...lip].map(Q))));
    inner.setAttribute("d", "M" + backIn.map(Q).map((p) => p.join(",")).join("L"));
    const ring = [[0, -R, 0], [0, R, 0], ...lip.slice(1, -1), [LEN, -R, 0]];
    mouth.setAttribute("d", poly(ring.map(Q)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const outline = hull([...back, ...lip, ...handle].map((p) => P(...POUR(-4)(p))));
  function inside([x, y]) {
    let s = 0;
    for (let i = 0; i < outline.length; i++) {
      const a = outline[i], b = outline[(i + 1) % outline.length], cr = (b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0]);
      if (cr !== 0) { if (s && Math.sign(cr) !== s) return false; s = Math.sign(cr); }
    }
    return true;
  }
  let on = null;
  function setOn(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? tip : -4, performance.now(), 0);
    shell.classList.toggle("hi", o); hd.classList.toggle("hi", o);
    mouth.classList.toggle("hi", !o);
    read.textContent = o ? "tip " + Math.round(tip) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(inside(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "iceshovel",
  means: "A hotel ice scoop on a drip tray: the pointer picks it up and it tips its lip forward to pour.",
  rules: [1, 4, 5, 8],
  range: [20, 45, 70],
  tour: [[198, 189], [140, 165], [222, 196], null],
  mount,
});

filmloader.code:
/**
 * Film back: a medium format film magazine standing on its face, a winding
 * knob on top and the dark slide in its slot. The pointer on the back draws
 * the dark slide up out of its slot. At rest the slide sits home with its
 * tab showing, bright. The slider is how far the slide is drawn.
 *
 * The pattern: one part sliding; the hit is the rest pose's outline.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const DX = 26, WY = 50, HZ = 50, REST = 5;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.7);
  fit(C, [[-4, -4, 0], [DX + 4, WY + 4, 0], [DX, -4, 0], [-4, WY, 0], [0, 0, HZ + 37], [6, WY, HZ + 37]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  { const [r, i] = rings(-4, -4, DX + 4, WY + 4, 4, 1.4); put(solid(g), prism(P, front, r, i, 0, 3)); }
  { const [r, i] = rings(0, 0, DX, WY, 4, 1.6); put(solid(g), prism(P, front, r, i, 3, HZ)); }
  mk("path", { class: "nf lo", d: poly([[3, 3], [7, 3], [7, WY - 3], [3, WY - 3]].map(([x, y]) => P(x, y, HZ))) }, g);
  const slide = solid(g);
  put(solid(g), prism(P, front, disc(17, 14, 6), disc(17, 14, 4.6), HZ, HZ + 4));
  put(solid(g), prism(P, front, disc(17, 14, 2), null, HZ + 4, HZ + 7));
  const [sr, si] = rings(3.5, 4, 6.5, WY - 4, 1, 0.5);
  const lift = tween(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    put(slide, prism(P, front, sr, si, HZ, HZ + z));
  }
  const B = register(stage, (_dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);

  const outline = hull([[0, 0, 0], [DX, 0, 0], [DX, WY, 0], [0, WY, 0], [0, 0, HZ + 6], [DX, 0, HZ + 6], [DX, WY, HZ + 6], [0, WY, HZ + 6]].map((p) => P(...p)));
  function inside([x, y]) {
    let s = 0;
    for (let i = 0; i < outline.length; i++) {
      const a = outline[i], b = outline[(i + 1) % outline.length], cr = (b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0]);
      if (cr !== 0) { if (s && Math.sign(cr) !== s) return false; s = Math.sign(cr); }
    }
    return true;
  }
  let on = null;
  function setOn(o) {
    if (o === on) return;
    on = o;
    tset(lift, o ? max : REST, performance.now(), 0);
    read.textContent = o ? "out " + Math.round(max) : "rest";
    B.wake();
  }
  slide.sil.classList.add("hi");
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(inside(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "filmloader",
  means: "A medium format film back: the pointer on it draws the dark slide up out of its slot.",
  rules: [1, 4, 5, 8],
  range: [14, 33, 36],
  tour: [[200, 170], [246, 192], [200, 148], null],
  mount,
