  name: "ssdslot",
  means: "An M.2 drive in its slot: the pointer backs out the screw and the drive tilts up on its connector.",
  rules: [1, 3, 5, 6],
  range: [12, 32, 52],
  tour: [[159, 203], [211, 232], [260, 297], null],
  mount,
