cpucooler.code:
/**
 * CPU socket: a square socket on a patch of motherboard, a processor seated
 * in it, the hinged load plate over the processor and the retention lever
 * along its side. The pointer over the board lifts the lever and swings the
 * load plate open on its far hinge, baring the chip. At rest everything is
 * latched, the lever just off its hook, bright. The slider is how far the
 * load plate swings.
 *
 * The pattern: one part on a hinge; the hit is the board's fixed plane.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, rrect, rad, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HX = -3, PZ = 7.2, PT = 1.4, LX = 47, LY = 48, LZ = 3, LREST = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let open = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-14, -14, -4], [58, 58, -4], [58, -14, -4], [-14, 58, -4], [-32, 0, 56], [-32, 44, 56], [LX, LY, 52]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const block = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  block(-14, -14, 58, 58, 5, 1.8, -4, 0);
  block(-6, -6, 46, 46, 3, 1.2, 0, 3);
  const chipG = mk("g", {}, g);
  const [c1, c2] = rings(5, 5, 35, 35, 2, 1);
  put(solid(chipG), prism(P, front, c1, c2, 3, 5));
  const [c3, c4] = rings(10, 10, 30, 30, 2.5, 1);
  put(solid(chipG), prism(P, front, c3, c4, 5, 7));

  // a thin plate turned about a hinge line along y: u runs from the hinge, h is its thickness
  function hinged(x0, z0, sgn, a) {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return (u, v, h) => P(x0 + sgn * (u * c - h * s), v, z0 + u * s + h * c);
  }
  const area = (pts) => pts.reduce((acc, p, i) => { const q = pts[(i + 1) % pts.length]; return acc + p[0] * q[1] - q[0] * p[1]; }, 0);

  // the load plate: a frame with a window over the processor
  const plateG = mk("g", {}, g);
  const plate = { sil: mk("path", { class: "sil" }, plateG), cr: mk("path", { class: "nf lo" }, plateG), a: tween(0), last: NaN };
  const pOut = rrect(0, -4, 48, 44, 3, 4), pIn = rrect(1, -3, 47, 43, 2, 4), pWin = rrect(11, 8, 35, 32, 3, 4);
  function drawPlate(a) {
    if (a === plate.last) return;
    plate.last = a;
    const f = hinged(HX, PZ, 1, a);
    const outer = hull(pOut.map((q) => f(q.u, q.v, 0)).concat(pOut.map((q) => f(q.u, q.v, PT))));
    let win = pWin.map((q) => f(q.u, q.v, PT));
    if (Math.sign(area(win)) === Math.sign(area(outer))) win = win.reverse();
    plate.sil.setAttribute("d", poly(outer) + poly(win));
    plate.cr.setAttribute("d", poly(pIn.map((q) => f(q.u, q.v, PT))));
    if (a > 30 && plateG.nextSibling !== chipG) g.insertBefore(plateG, chipG);
    if (a <= 30 && chipG.nextSibling !== plateG) chipG.after(plateG);
  }

  // the lever: a rod pivoting at its near end, with a tab at its far end
  const lever = { sil: mk("path", { class: "sil hi" }, g), a: tween(LREST), last: NaN };
  const rod = rrect(0, LY - 1.2, 50, LY + 1.2, 1.1, 4), tab = rrect(44, LY - 1.2, 50, LY + 5, 1.5, 4);
  function drawLever(a) {
    if (a === lever.last) return;
    lever.last = a;
    const f = hinged(LX, LZ, -1, a), pts = (ring) => ring.map((q) => f(q.u, q.v, 0)).concat(ring.map((q) => f(q.u, q.v, 1.6)));
    lever.sil.setAttribute("d", poly(hull(pts(rod))) + poly(hull(pts(tab))));
  }

  const B = register(stage, (_dt, now) => {
    drawPlate(tval(plate.a, now));
    drawLever(tval(lever.a, now));
    return !tdone(plate.a, now) || !tdone(lever.a, now);
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -20 && x < 62 && y > -20 && y < 62;
  }
  let on = null;
  function apply(o) {
    const now = performance.now();
    tset(lever.a, o ? Math.min(open, 80) : LREST, now, 0);
    tset(plate.a, o ? open : 0, now, o ? 160 : 0);
    read.textContent = o ? "open " + Math.round(open) : "rest";
    B.wake();
  }
  function setOn(o) { if (o === on) return; on = o; apply(o); }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { open = clamp(v, 70, 125); if (on) apply(true); }, destroy: bag.dispose };
}

hairline({
  name: "cpucooler",
  means: "A CPU socket: the pointer lifts the retention lever and swings the load plate open off the processor.",
  rules: [1, 3, 5, 6],
  range: [70, 100, 125],
  tour: [[204, 172], [204, 213], [204, 298], null],
  mount,
});

ramstick.code:
/**
 * RAM slot: a memory stick standing in its long slot on a patch of
 * motherboard, a row of chips along its face and a latch clip at each end.
 * The pointer over the board swings both clips outward and the stick rises
 * out of the slot. At rest the stick is seated, bright, one clip leaning
 * loose. The slider is how far the stick rises.
 *
 * The pattern: one part lifting; the hit is the board's fixed plane.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, rad, seg, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 92, H = 26, TH = 1.8, SZ = 6, CH = 15, OPEN = 38;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-14, -10, -4], [L + 14, 12, -4], [L + 14, -10, -4], [-14, 12, -4], [0, 0, SZ + H + 32], [L, TH, SZ + H + 32], [-14, 0, 14], [L + 14, 0, 14]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(-14, -10, L + 14, 12, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, -4, 0));
  const [sr, si] = rings(-6, -2.2, L + 6, TH + 2.2, 1.6, 0.7);
  const slot = solid(g);
  put(slot, prism(P, front, sr, si, 0, SZ));
  mk("path", { class: "nf lo", d: poly([P(0, 0, SZ), P(L, 0, SZ), P(L, TH, SZ), P(0, TH, SZ)]) }, slot.g);

  // a clip: a paddle hinged at its foot, leaning outward by b degrees
  function clip(xh, sgn) {
    const s = { sil: mk("path", { class: "sil" }, g), a: tween(0), last: NaN };
    s.draw = (b) => {
      if (b === s.last) return;
      s.last = b;
      const c = Math.cos(rad(b)), n = Math.sin(rad(b)), pts = [];
      for (const w of [-0.8, 3.2]) for (const u of [0, CH]) for (const y of [-2, TH + 2]) {
        const dx = -sgn * w, dz = u;
        pts.push(P(xh + c * dx - sgn * n * dz, y, SZ - 3 + sgn * n * dx + c * dz));
      }
      s.sil.setAttribute("d", poly(hull(pts)));
    };
    return s;
  }
  const left = clip(-1, 1);
  const stickG = mk("g", {}, g);
  const stick = solid(stickG), chips = mk("path", { class: "nf lo" }, stickG);
  stick.sil.classList.add("hi");
  const right = clip(L + 1, -1);
  const z = tween(0);
  let last = NaN;
  const [kr, ki] = rings(0, 0, L, TH, 0.6, 0.5);
  function drawStick(h) {
    if (h === last) return;
    last = h;
    const z0 = SZ + h, y = TH + 0.02;
    put(stick, prism(P, front, kr, ki, z0, z0 + H));
    let d = "";
    for (let k = 0; k < 8; k++) {
      const x0 = 4 + k * 10.8 + (k > 3 ? 2 : 0);
      d += poly([P(x0, y, z0 + 8), P(x0 + 8, y, z0 + 8), P(x0 + 8, y, z0 + 20), P(x0, y, z0 + 20)]);
    }
    chips.setAttribute("d", d + seg(P(2, y, z0 + 4), P(L - 2, y, z0 + 4)));
  }

  const B = register(stage, (_dt, now) => {
    drawStick(tval(z, now));
    left.draw(tval(left.a, now));
    right.draw(tval(right.a, now));
    return !tdone(z, now) || !tdone(left.a, now) || !tdone(right.a, now);
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const inside = (zz) => { const [x, y] = unproj(C, sx, sy, zz); return x > -20 && x < L + 20 && y > -20 && y < 18; };
    return inside(0) || inside(SZ + H * 0.6);
  }
  let on = null;
  function apply(o) {
    const now = performance.now();
    tset(left.a, o ? OPEN : 14, now, 0);
    tset(right.a, o ? OPEN : 0, now, 60);
    tset(z, o ? lift : 0, now, o ? 180 : 0);
    read.textContent = o ? "lift " + Math.round(lift) : "rest";
    B.wake();
  }
  function setOn(o) { if (o === on) return; on = o; apply(o); }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = clamp(v, 10, 32); if (on) apply(true); }, destroy: bag.dispose };
}

hairline({
  name: "ramstick",
  means: "A memory stick in its slot: the pointer swings the end clips open and the stick rises out of the slot.",
  rules: [1, 3, 5, 6],
  range: [10, 22, 32],
  tour: [[102, 168], [200, 159], [294, 302], null],
  mount,
});

pcside.code:
/**
 * PC case: a desktop tower, its front with drive bays and a power light, and
 * a side panel hinged at the back edge. The pointer over the case swings the
 * panel wide to show the board, fan and graphics card inside; at rest the
 * panel stands ajar, bright. The slider is how far the panel swings.
 */
const {
  Cam, circ, fit, flatDot, hull, place, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 26, D = 56, H = 58, T = 2, REST = 16;

function inside(pt, poly) {
  let s = 0;
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const c = (b[0] - a[0]) * (pt[1] - a[1]) - (b[1] - a[1]) * (pt[0] - a[0]);
    if (c !== 0) { if (s && Math.sign(c) !== s) return false; s = Math.sign(c); }
  }
  return true;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [W, D, 0], [0, D, 0], [W, 0, H], [W + D, 0, 0], [W + D, 0, H], [0, 0, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [r0, i0] = rings(0, 0, W, D, 4, 1.4);
  const body = solid(g);
  put(body, prism(P, front, r0, i0, 0, H));
  // front: two drive bays, a vent stack and the power light
  let fr = seg(P(5, D, H - 8), P(W - 5, D, H - 8)) + seg(P(5, D, H - 14), P(W - 5, D, H - 14));
  for (let k = 0; k < 6; k++) fr += seg(P(7, D, 8 + k * 4), P(W - 7, D, 8 + k * 4));
  mk("path", { class: "nf lo", d: fr }, body.g);
  place(flatDot(body.g, C, 1.6, "dot m"), P(W / 2, D, H - 4));
  // inside, on the open side: board, rear fan, graphics card, power supply
  const X = W - 0.5;
  const yz = (pts) => pts.map(([y, z]) => P(X, y, z));
  const fan = circ(7, 20).map((q) => [11 + q.u, 44 + q.v]);
  const hub = circ(2, 10).map((q) => [11 + q.u, 44 + q.v]);
  let ins = poly(yz([[4, 16], [40, 16], [40, 54], [4, 54]])) + poly(yz(fan)) + poly(yz(hub));
  ins += poly(yz([[6, 24], [46, 24], [46, 29], [6, 29]])) + poly(yz([[4, 4], [30, 4], [30, 12], [4, 12]]));
  ins += poly(yz([[24, 40], [34, 40], [34, 50], [24, 50]]));
  mk("path", { class: "nf lo", d: ins }, g);

  const pan = solid(g);
  const pr = rrect(0, 0, D, H, 4, 4), pi = rrect(2.2, 2.2, D - 2.2, H - 2.2, 2.4, 4);
  pan.cr.setAttribute("class", "nf lo");
  pan.sil.classList.add("hi");
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180);
    const xf = (v, w, t) => P(W + t * c + v * s, v * c - t * s, w);
    const pts = [];
    for (const q of pr) pts.push(xf(q.u, q.v, 0), xf(q.u, q.v, T));
    const t = c > s ? T : 0;
    let d = poly(pi.map((q) => xf(q.u, q.v, t)));
    for (let k = 0; k < 5; k++) d += seg(xf(8, 18 + k * 5, t), xf(18, 18 + k * 5, t));
    pan.sil.setAttribute("d", poly(hull(pts)));
    pan.cr.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const rest = [];
  for (const [x, y] of [[0, 0], [W, 0], [W, D], [0, D], [W + D * 0.28, D * 0.96]]) rest.push(P(x, y, 0), P(x, y, H));
  const area = hull(rest);
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a < 0 ? REST : maxA, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "open";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p, area) ? 1 : -1), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "pcside",
  means: "A PC tower: the pointer over the case swings its side panel open on the rear hinge to show the board and fan.",
  rules: [1, 5, 6, 8],
  range: [40, 80, 100],
  tour: [[167, 154], [150, 210], [185, 110], null],
  mount,
});

trackpad.code:
/**
 * Keyboard tray: a desk on two panel legs with a tray hung under its top and
 * a keyboard on the tray. The pointer over the desk slides the tray out from
 * under the top toward the sitter; at rest it sits half out, its rim bright.
 * The slider is how far the tray runs out.
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, facing,
  disposer, mk, pointer, put, register, solid,
} = HL;

const DW = 96, DD = 56, DZ = 40, TX0 = 22, TX1 = 74, L = 62, TZ = 25, REST = 30;

function inside(pt, pg) {
  let s = 0;
  for (let i = 0; i < pg.length; i++) {
    const a = pg[i], b = pg[(i + 1) % pg.length];
    const c = (b[0] - a[0]) * (pt[1] - a[1]) - (b[1] - a[1]) * (pt[0] - a[0]);
    if (c !== 0) { if (s && Math.sign(c) !== s) return false; s = Math.sign(c); }
  }
  return true;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, DZ + 4], [DW, 0, 0], [0, DD, 0], [DW, DD, 0], [TX0, DD + REST + 30, TZ], [TX1, DD + REST + 30, TZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const x0 of [2, DW - 6]) {
    const [r, i] = rings(x0, 6, x0 + 4, DD - 6, 2, 0.8);
    put(solid(g), prism(P, front, r, i, 0, DZ));
  }
  const back = solid(g);
  const [dr, di] = rings(0, 0, DW, DD, 4, 1.6);
  put(solid(g), prism(P, front, dr, di, DZ, DZ + 4));
  const tray = solid(g), kb = solid(g);
  tray.sil.classList.add("hi");
  const keys = mk("path", { class: "nf lo" }, kb.g);

  const slide = tween(REST);
  let last = NaN;
  function draw(s) {
    if (s === last) return;
    last = s;
    const y0 = DD - L + s, y1 = DD + s;
    if (DD - y0 > 3) { const [r, i] = rings(TX0, y0, TX1, DD, 3, 1); put(back, prism(P, front, r, i, TZ, TZ + 2)); }
    else put(back, { sil: "", crease: "" });
    const [fr, fi] = rings(TX0, DD, TX1, y1, 3, 1);
    put(tray, prism(P, front, fr, fi, TZ, TZ + 2));
    const k0 = y1 - 30, k1 = y1 - 5;
    const [kr, ki] = rings(TX0 + 5, k0, TX1 - 5, k1, 2.5, 1.2);
    put(kb, prism(P, front, kr, ki, TZ + 2, TZ + 5));
    let d = "";
    for (let j = 1; j < 5; j++) d += seg(P(TX0 + 8, k0 + j * 5, TZ + 5), P(TX1 - 8, k0 + j * 5, TZ + 5));
    for (let j = 0; j < 9; j++) { const x = TX0 + 12 + j * 4; d += seg(P(x, k0 + 5, TZ + 5), P(x, k0 + 20, TZ + 5)); }
    d += seg(P(TX0 + 20, k0 + 22.5, TZ + 5), P(TX1 - 20, k0 + 22.5, TZ + 5));
    keys.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(slide, now)); return !tdone(slide, now); });
  bag.add(B.unregister);

  const area = hull([[0, 0, DZ + 4], [DW, 0, 0], [DW, DD, 0], [0, DD, 0], [0, 0, 0], [DW, 0, DZ + 4], [TX0, DD + REST, TZ], [TX1, DD + REST, TZ]].map((q) => P(...q)));
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(slide, a < 0 ? REST : REST + maxA, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "out";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p, area) ? 1 : -1), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "trackpad",
  means: "A desk's keyboard tray: the pointer over the desk slides the tray and its keyboard out from under the top.",
  rules: [1, 5, 6, 8],
  range: [10, 22, 30],
  tour: [[152, 189], [205, 225], [250, 150], null],
  mount,
});

penplotter.code:
/**
 * Pen plotter: a flatbed with a sheet on it, a gantry bridge across the bed
 * on two uprights, and a pen carriage riding the bridge. The pointer over the
 * bed sends the bridge along the bed and the carriage along the bridge, on
 * springs, so the pen travels to the point. At rest the carriage is bright.
 * The slider is the reach: how far toward the pointer the pen travels.
 *
 * The pattern: a continuous aim (terrain's spring); the hit is on the bed's
 * top plane, which never moves.
 */
const {
  Cam, clamp, fit, facing, poly, open, prism, proj, rings, ringAt, circ, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 100, BY = 70, BZ = 6, TOP = 30, REST = [26, 46];
const box = (P, front, x0, y0, x1, y1, z0, z1, r = 2, b = 1.2) => {
  const [o, i] = rings(x0, y0, x1, y1, r, b);
  return prism(P, front, o, i, z0, z1);
};
const disc = (x, y, r) => circ(r, 20).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, -12, 0], [BX, -12, TOP], [BX, BY + 12, 0], [0, BY + 12, TOP], [0, 0, 0], [BX, BY, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const back = solid(g);
  put(solid(g), box(P, front, 0, 0, BX, BY, 0, BZ, 3, 1.6));
  const [po] = rings(10, 8, BX - 10, BY - 8, 1, 0.5);
  mk("path", { d: poly(ringAt(P, po, BZ + 0.3)), class: "nf lo" }, g);
  const trace = [];
  for (let i = 0; i <= 30; i++) { const t = i / 30; trace.push(P(18 + t * 60, 35 + 14 * Math.sin(t * Math.PI * 2.2) * (1 - t * 0.4), BZ + 0.3)); }
  mk("path", { d: open(trace), class: "nf lo" }, g);
  const bar = solid(g), pen = solid(g), carr = solid(g), fore = solid(g);
  carr.sil.classList.add("hi");

  const gx = spring(REST[0]), py = spring(REST[1]);
  let lx = NaN, ly = NaN;
  function draw() {
    const x = gx.x, y = py.x;
    if (x === lx && y === ly) return;
    lx = x; ly = y;
    put(back, box(P, front, x - 5, -12, x + 5, -3, 0, TOP));
    put(bar, box(P, front, x - 4, -10, x + 4, BY + 10, TOP - 7, TOP, 2, 1));
    put(fore, box(P, front, x - 5, BY + 3, x + 5, BY + 12, 0, TOP));
    put(pen, prism(P, front, disc(x + 9, y, 1.8), disc(x + 9, y, 1), BZ + 0.5, 16));
    put(carr, box(P, front, x + 4, y - 6, x + 14, y + 6, 13, TOP + 2, 2, 1));
  }
  draw();

  const B = register(stage, (dt) => { const a = stepS(gx, dt), b = stepS(py, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function aim(p) {
    const [x, y] = p ? unproj(C, p[0], p[1], BZ) : [NaN, NaN];
    const on = p && x > 0 && x < BX && y > 0 && y < BY;
    const tx = on ? clamp(REST[0] + (x - 9 - REST[0]) * reach, 6, BX - 16) : REST[0];
    const ty = on ? clamp(REST[1] + (y - REST[1]) * reach, 8, BY - 8) : REST[1];
    gx.t = tx; py.t = ty;
    read.textContent = on ? Math.round(tx) + "·" + Math.round(ty) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "penplotter",
  means: "A flatbed pen plotter: the pointer over the bed slides the gantry and its pen carriage over to that point on the sheet.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[221, 159], [278, 166], [200, 190], null],
  mount,
});

tickettap.code:
/**
 * Contactless reader: a ticket validator on a post, its broad reader head on
 * a pivot at the top, a tap ring on its face. The pointer's place along the
 * ground tilts the head toward it on a spring. At rest the head leans toward
 * the viewer, bright. The slider is the tilt's far end, in degrees.
 *
 * The pattern: a continuous aim (terrain's spring, on an angle); the hit is
 * on the ground plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rrect, rad, unproj, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const H = 50, HU = 22, HV = 21, HW = 9, REST = 22, REACH = 70;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let most = value;
  const C = Cam(45, 0.5, 2.75);
  const outer = rrect(-HU, -HV, HU, HV, 5, 4), inner = rrect(-HU + 2, -HV + 2, HU - 2, HV - 2, 3.5, 4);
  const tap = circ(9, 32), led = [-HU + 6, HV - 5];
  const W = (u, v, w, th) => [u * Math.cos(th) + w * Math.sin(th), v, H + w * Math.cos(th) - u * Math.sin(th)];
  const ext = [];
  for (const d of [-64, 64]) for (const [u, v] of [[-HU, -HV], [HU, HV], [HU, -HV], [-HU, HV]]) for (const w of [0, HW]) ext.push(W(u, v, w, rad(d)));
  fit(C, ext.concat([[-18, -18, 0], [18, 18, 0], [18, -18, 0], [-18, 18, 0]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, 18, 40), disc(0, 0, 15.5, 40), 0, 3));
  put(solid(g), prism(P, front, disc(0, 0, 5.5), disc(0, 0, 4.3), 3, H - 4));
  put(solid(g), prism(P, front, disc(0, 0, 8), disc(0, 0, 6.5), H - 7, H - 2));
  const head = solid(g);
  head.sil.classList.add("hi");
  const ring = mk("path", { class: "nf lo" }, g), ring2 = mk("path", { class: "nf lo" }, g);
  const dot = mk("circle", { r: 2.2, class: "dot m" }, g);

  const th = spring(REST);
  // the face's winding at rest: when it flips, the face has turned away and its marks are hidden
  const area = (f) => f.reduce((s, p, i) => { const n = f[(i + 1) % f.length]; return s + p[0] * n[1] - n[0] * p[1]; }, 0);
  const sgn = Math.sign(area(inner.map((q) => P(...W(q.u, q.v, HW, 0)))));
  let last = NaN;
  function draw() {
    const a = th.x;
    if (a === last) return;
    last = a;
    const t = rad(a), at = (q, w) => P(...W(q.u, q.v, w, t));
    const pts = outer.map((q) => at(q, 0)).concat(outer.map((q) => at(q, HW)));
    head.sil.setAttribute("d", poly(hull(pts)));
    const fc = inner.map((q) => at(q, HW)), show = area(fc) * sgn > 0;
    head.cr.setAttribute("d", show ? poly(fc) : "");
    ring.setAttribute("d", show ? poly(tap.map((q) => at({ u: q.u + 4, v: q.v }, HW))) : "");
    ring2.setAttribute("d", show ? poly(tap.map((q) => at({ u: q.u * 0.45 + 4, v: q.v * 0.45 }, HW))) : "");
    place(dot, at({ u: led[0], v: led[1] }, HW));
    dot.setAttribute("r", show ? 2.2 : 0);
  }
  draw();

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(p) {
    let a = REST;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      a = clamp((x - y * 0.3) / REACH, -1, 1) * most;
    }
    th.t = a;
    read.textContent = p ? Math.round(a) + "°" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { most = v; }, destroy: bag.dispose };
}

