nailclip.code:
/**
 * Nail clippers: two springy strips riveted at the back and meeting at the
 * jaw, a pin through them and a long lever riding on the pin. The pointer
 * sweeping from the back toward the jaw swings the lever up on its pin and
 * over, from stowed to the ready position. At rest the lever stands half up,
 * bright. The slider is how far over a full sweep swings it.
 *
 * The pattern: a continuous swing on a spring; the hit is the pointer's
 * screen x against the clipper's fixed rest pose.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, circ, rrect, spring, stepS, rad, ringAt,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 56, PX = 44, PZ = 11, LL = 50, LW = 5, TH = 1.4, REST = 50;
const at = (x, y, r, n) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let over = value;
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-6, -7, 0], [L + 2, 7, 0], [L + 2, -7, 0], [-6, 7, 0], [PX, 0, PZ + LL + 2], [PX + LL * 0.7, 0, PZ + LL * 0.7], [PX - LL * 0.7, 0, PZ + LL * 0.7]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(0, -6, L, 6, 4, 1), 0, 2.4));
  // the top strip rises from the rivet to the jaw
  const strip = rrect(0, -6, L - 1, 6, 4, 4), sp2 = [];
  for (const q of strip) { const z = 2.4 + (q.u / L) * 4.2; sp2.push(P(q.u, q.v, z), P(q.u, q.v, z + 2)); }
  mk("path", { class: "sil", d: poly(hull(sp2)) }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, at(4, 0, 1.6, 16), 4.6)) }, g);
  put(solid(g), prism(P, front, at(PX, 0, 1.8, 20), at(PX, 0, 1.2, 20), 7.5, PZ));
  const lever = mk("path", { class: "sil hi" }, g), dimple = mk("path", { class: "nf lo" }, g);
  const ring = rrect(-4, -LW, LL, LW, 3.5, 4);
  const sp = spring(REST);
  let last = "";

  function draw() {
    const key = sp.x.toFixed(2);
    if (key === last) return;
    last = key;
    const a = rad(sp.x), c = Math.cos(a), s = Math.sin(a);
    const pt = (u, v, t) => P(PX - u * c + t * s, v, PZ + u * s + t * c);
    const pts = [];
    for (const q of ring) pts.push(pt(q.u, q.v, 0), pt(q.u, q.v, TH));
    lever.setAttribute("d", poly(hull(pts)));
    const d = circ(2.6, 16).map((q) => pt(LL - 7 + q.u, q.v, TH));
    dimple.setAttribute("d", poly(d));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const back = P(-4, 0, 0), jaw = P(L, 0, 0), mid = P(L / 2, 0, PZ);
  function aim(p) {
    if (!p || Math.abs(p[1] - mid[1]) > 130) { sp.t = REST; read.textContent = "rest"; B.wake(); return; }
    const f = clamp((p[0] - back[0]) / (jaw[0] - back[0]), 0, 1), deg = f * 180 * over;
    sp.t = deg;
    read.textContent = Math.round(deg) + "°";
    B.wake();
  }
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { over = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "nailclip",
  means: "Nail clippers: sweeping the pointer from the rivet toward the jaw swings the lever up on its pin and over into place.",
  rules: [1, 3, 4, 5, 8],
  range: [0.4, 0.85, 1],
  tour: [[120, 190], [185, 220], [257, 253], null],
  mount,
});

hairstraight.code:
/**
 * Hair straightener: two long flat paddles hinged at the cord end, a heated
 * plate inside the tip of each. The upper paddle swings up about the hinge;
 * the nearer the pointer comes to the tips, the wider the jaws open. At rest
 * the jaws are just ajar, the lower plate bright. The slider is how far the
 * upper paddle can open.
 *
 * The pattern: one part tilting on a hinge (tilt).
 */
const {
  Cam, clamp, fit, hull, open, poly, proj, rad, rrect, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HX = 6, HZ = 11, REST = 7, MAX = 28, L = 120;

// a straight bar between two world points, with a rounded section w × h
function tube(P, p0, p1, w, h) {
  const d = [p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]], L = Math.hypot(...d), a = d.map((q) => q / L);
  let s = [-a[1], a[0], 0], sl = Math.hypot(s[0], s[1]);
  if (sl < 1e-3) { s = [1, 0, 0]; sl = 1; }
  s = s.map((q) => q / sl);
  let u = [a[1] * s[2] - a[2] * s[1], a[2] * s[0] - a[0] * s[2], a[0] * s[1] - a[1] * s[0]];
  if (u[2] < 0) u = u.map((q) => -q);
  const ring = rrect(-w / 2, -h / 2, w / 2, h / 2, Math.min(w, h) / 2, 4);
  const at = (c, q) => P(c[0] + s[0] * q.u + u[0] * q.v, c[1] + s[1] * q.u + u[1] * q.v, c[2] + s[2] * q.u + u[2] * q.v);
  const k = h / 2 - Math.min(1, h / 4), b = Math.min(1.5, L / 4);
  const q0 = p0.map((v, i) => v + a[i] * b), q1 = p1.map((v, i) => v - a[i] * b);
  return { sil: poly(hull(ring.map((q) => at(p0, q)).concat(ring.map((q) => at(p1, q))))), crease: open([at(q0, { u: 0, v: k }), at(q1, { u: 0, v: k })]) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-22, -12, 0], [L + 4, 12, 0], [L - 20, 0, 88], [L - 20, 12, 88], [-22, 12, 0]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  // the cord leaving the hinge, then the lower paddle and its plate
  put(solid(g), tube(P, [-22, 0, 4], [HX, 0, 7], 4, 4));
  put(solid(g), tube(P, [HX, 0, 6], [L, 0, 6], 18, 8));
  const [pr, pi] = rings(L - 58, -6, L - 4, 6, 3, 1);
  const plate = solid(g);
  plate.sil.classList.add("hi");
  {
    const top = pr.map((q) => P(q.u, q.v, 10.6)), bot = pr.map((q) => P(q.u, q.v, 10));
    put(plate, { sil: poly(hull(top.concat(bot))), crease: poly(pi.map((q) => P(q.u, q.v, 10.6))) });
  }
  // the hinge barrel across the paddles
  put(solid(g), tube(P, [HX, -10, HZ], [HX, 10, HZ], 9, 9));
  const arm = solid(g), cap = mk("path", { class: "nf lo" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const Q = (x, y, z) => { const dx = x - HX, dz = z - HZ; return P(HX + dx * c - dz * s, y, HZ + dx * s + dz * c); };
    put(arm, tube(Q, [HX, 0, 16], [L, 0, 16], 18, 8));
    const d = [];
    for (let k = 0; k < 12; k++) d.push(Q(L - 70 + 36 * (k < 6 ? k / 5 : (11 - k) / 5), k < 6 ? -4 : 4, 20.2));
    cap.setAttribute("d", poly(d));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  function move(p) {
    const [x, y] = unproj(C, p[0], p[1], 0);
    const t = Math.abs(y) > 70 ? 0 : clamp((x + 10) / (L + 10), 0, 1);
    sp.t = REST + MAX * reach * t;
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  draw(REST);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "hairstraight",
  means: "A hair straightener: the upper paddle swings up on its hinge, the jaws opening wider as the pointer nears the tips.",
  rules: [1, 3, 5, 8],
