toothbrushe.code:
/**
 * Electric toothbrush: a round-shouldered handle standing in its charging
 * dock, a slim neck and a small head with its bristle tuft. The brush tilts
 * in the dock towards the pointer, further the farther the pointer is; a
 * spring follows. At rest it leans a little, the bristles bright. The slider
 * is how far it can lean.
 *
 * The pattern: one part tilting towards the pointer (aim).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rad, rrect, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZP = 8, MAX = 26, RX = 0, RY = 24;

// a straight bar between two world points, with a rounded section w × h
function tube(P, p0, p1, w, h) {
  const d = [p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]], L = Math.hypot(...d), a = d.map((q) => q / L);
  let s = [-a[1], a[0], 0], sl = Math.hypot(s[0], s[1]);
  if (sl < 1e-3) { s = [1, 0, 0]; sl = 1; }
  s = s.map((q) => q / sl);
  let u = [a[1] * s[2] - a[2] * s[1], a[2] * s[0] - a[0] * s[2], a[0] * s[1] - a[1] * s[0]];
  if (u[2] < 0) u = u.map((q) => -q);
  const ring = rrect(-w / 2, -h / 2, w / 2, h / 2, Math.min(w, h) / 2, 4);
  const at = (c, q) => P(c[0] + s[0] * q.u + u[0] * q.v, c[1] + s[1] * q.u + u[1] * q.v, c[2] + s[2] * q.u + u[2] * q.v);
  const k = h / 2 - Math.min(1, h / 4), b = Math.min(1.5, L / 4);
  const q0 = p0.map((v, i) => v + a[i] * b), q1 = p1.map((v, i) => v - a[i] * b);
  return { sil: poly(hull(ring.map((q) => at(p0, q)).concat(ring.map((q) => at(p1, q))))), crease: open([at(q0, { u: 0, v: k }), at(q1, { u: 0, v: k })]) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-28, -22, 0], [28, 22, 0], [0, 0, 106], [0, 40, 100], [40, 0, 100], [-30, -30, 100]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-26, -20, 26, 20, 14, 2);
  put(solid(g), prism(P, front, dr, di, 0, ZP));
  const handle = solid(g), neck = solid(g), head = solid(g), tuft = solid(g);
  const btn = mk("path", { class: "nf lo" }, g);
  tuft.sil.classList.add("hi");
  const sx = spring(RX), sy = spring(RY);
  let lx = NaN, ly = NaN;
  function draw(ax, ay) {
    if (ax === lx && ay === ly) return;
    lx = ax; ly = ay;
    const th = Math.hypot(ax, ay), ux = th ? ax / th : 1, uy = th ? ay / th : 0, c = Math.cos(rad(th)), s = Math.sin(rad(th));
    const Q = (x, y, z) => {
      const a = x * ux + y * uy, w = -x * uy + y * ux, h = z - ZP, a2 = a * c + h * s, h2 = -a * s + h * c;
      return P(a2 * ux - w * uy, a2 * uy + w * ux, ZP + h2);
    };
    put(handle, tube(Q, [0, 0, ZP - 2], [0, 0, 66], 15, 15));
    put(neck, tube(Q, [0, 0, 66], [0, 0, 90], 6, 6));
    put(head, tube(Q, [0, 0, 89], [0, 0, 106], 8, 5));
    put(tuft, tube(Q, [4, 0, 91], [4, 0, 104], 7, 5));
    const d = [];
    for (let k = 0; k < 14; k++) { const t = (k / 14) * Math.PI * 2; d.push(Q(7.6, 2.4 * Math.cos(t), 46 + 4 * Math.sin(t))); }
    btn.setAttribute("d", poly(d));
  }

  const B = register(stage, (dt) => { const a = stepS(sx, dt), b = stepS(sy, dt); draw(sx.x, sy.x); return a || b; });
  bag.add(B.unregister);
  function move(p) {
    const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
    if (r < 4) return;
    const th = MAX * reach * clamp(r / 60, 0, 1);
    sx.t = (th * x) / r; sy.t = (th * y) / r;
    read.textContent = Math.round(th) + "°";
    B.wake();
  }
  function leave() { sx.t = RX; sy.t = RY; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  draw(RX, RY);
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "toothbrushe",
  means: "An electric toothbrush in its charging dock: the brush leans in the dock towards the pointer, further as it moves away.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[329, 283], [110, 250], [200, 90], null],
  mount,
});

lightswitch.code:
/**
 * Light switch: a wall plate standing upright with a bat toggle in its bezel.
 * At rest the toggle stands up, on, its tip bright. The pointer over the
 * plate flips it down past the middle. The slider is how far it throws.
 *
 * The pattern: one part turning on a hinge.
 */
const { Cam, circ, fit, hull, poly, proj, rings, tset, tval, tdone, tween, disposer, mk, place, pointer, register, solid } = HL;

const V = [0.612, 0.612, 0.5], REST = 40, PX = 25, PZ = 40, L = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 3.1);
  fit(C, [[0, 0, 0], [50, 0, 0], [0, 0, 80], [50, 4, 80], [0, 4, 0], [25, 40, 40], [25, 26, 72], [25, 26, 8]], 200, 166);
  const P = proj(C);
  function slab(s, ring, inner, f, w0, w1) {
    const a = ring.map((q) => P(...f(q.u, q.v, w0))), b = ring.map((q) => P(...f(q.u, q.v, w1)));
    s.sil.setAttribute("d", poly(hull(a.concat(b))));
    const c0 = f(0, 0, w0), c1 = f(0, 0, w1), vis = (c1[0] - c0[0]) * V[0] + (c1[1] - c0[1]) * V[1] + (c1[2] - c0[2]) * V[2] > 0;
    s.cr.setAttribute("d", poly(inner.map((q) => P(...f(q.u, q.v, vis ? w1 : w0)))));
  }
  const wall = (u, v, w) => [u, w, v];
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(0, 0, 50, 80, 7, 2.4);
  slab(solid(g), pr, pi, wall, 0, 4);
  for (const z of [10, 70]) place(mk("circle", { r: 1.6, class: "dot off" }, g), P(PX, 4, z));
  const [br, bi] = rings(PX - 8, PZ - 13, PX + 8, PZ + 13, 4, 1.4);
  slab(solid(g), br, bi, wall, 4, 7);
  const lg = mk("g", {}, g), tg = mk("g", {}, g);
  const lev = solid(lg), tip = solid(tg);
  tip.sil.classList.add("hi");
  const cr = circ(3.6, 20), ci = circ(2.2, 20), kr = circ(5.4, 20), ki = circ(3.8, 20);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180);
    const f = (u, v, w) => [PX + u, 7 - v * s + w * c, PZ + v * c + w * s];
    slab(lev, cr, ci, f, 0, L);
    slab(tip, kr, ki, f, L - 7, L);
    if (c * V[1] + s * V[2] > 0) lg.after(tg); else tg.after(lg);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const box = [[0, 0, 0], [50, 0, 0], [0, 4, 80], [50, 4, 80]].map((p) => P(...p));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const X0 = Math.min(...xs) - 6, X1 = Math.max(...xs) + 6, Y0 = Math.min(...ys) - 6, Y1 = Math.max(...ys) + 6;
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? -swing : REST, performance.now(), 0);
    read.textContent = o ? "off" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > X0 && x < X1 && y > Y0 && y < Y1), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (on) { tset(ang, -v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "lightswitch",
  means: "A wall light switch with its bat toggle up: the pointer over the plate flips the toggle down to off.",
  rules: [1, 4, 5, 8],
  range: [20, 50, 70],
  tour: [[151, 148], [205, 200], [175, 80], null],
  mount,
});

dimmer.code:
/**
 * Dimmer: a square wall plate with a long paddle knob on a round collar. At
 * rest the knob leans low, its edge bright. The pointer over the plate turns
 * the knob up round its axis. The slider is how far it turns.
 *
 * The pattern: one part turning on its axis.
 */
const { Cam, circ, fit, hull, poly, proj, rings, rrect, tset, tval, tdone, tween, disposer, mk, place, pointer, register, solid } = HL;

const V = [0.612, 0.612, 0.5], REST = -35, CX = 30, CZ = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let turn = value;
  const C = Cam(45, 0.5, 3.35);
  fit(C, [[0, 0, 0], [60, 0, 0], [0, 0, 60], [60, 4, 60], [0, 4, 0], [CX, 20, CZ + 22], [CX, 20, CZ - 22]], 200, 166);
  const P = proj(C);
  function slab(s, ring, inner, f, w0, w1) {
    const a = ring.map((q) => P(...f(q.u, q.v, w0))), b = ring.map((q) => P(...f(q.u, q.v, w1)));
    s.sil.setAttribute("d", poly(hull(a.concat(b))));
    const c0 = f(0, 0, w0), c1 = f(0, 0, w1), vis = (c1[0] - c0[0]) * V[0] + (c1[1] - c0[1]) * V[1] + (c1[2] - c0[2]) * V[2] > 0;
    s.cr.setAttribute("d", poly(inner.map((q) => P(...f(q.u, q.v, vis ? w1 : w0)))));
  }
  const wall = (u, v, w) => [u, w, v];
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(0, 0, 60, 60, 8, 2.4);
  slab(solid(g), pr, pi, wall, 0, 4);
  for (const [x, z] of [[8, 8], [52, 52]]) place(mk("circle", { r: 1.6, class: "dot off" }, g), P(x, 4, z));
  const at = (u, v, w) => [CX + u, w, CZ + v];
  slab(solid(g), circ(12, 24), circ(10.4, 24), at, 4, 7);
  const knob = solid(g);
  knob.sil.classList.add("hi");
  const dot = mk("circle", { r: 2, class: "dot" }, g);
  const kr = rrect(-21, -7.5, 21, 7.5, 7.5, 6), ki = rrect(-19.4, -5.9, 19.4, 5.9, 5.9, 6);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos((a * Math.PI) / 180), s = Math.sin((a * Math.PI) / 180);
    const f = (u, v, w) => [CX + u * c - v * s, w, CZ + u * s + v * c];
    slab(knob, kr, ki, f, 7, 17);
    place(dot, P(...f(15, 0, 17)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const box = [[0, 0, 0], [60, 0, 0], [0, 4, 60], [60, 4, 60]].map((p) => P(...p));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const X0 = Math.min(...xs) - 6, X1 = Math.max(...xs) + 6, Y0 = Math.min(...ys) - 6, Y1 = Math.max(...ys) + 6;
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? REST + turn : REST, performance.now(), 0);
    read.textContent = o ? Math.round((turn / 180) * 100) + "%" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > X0 && x < X1 && y > Y0 && y < Y1), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { turn = v; if (on) { tset(ang, REST + v, performance.now(), 0); read.textContent = Math.round((v / 180) * 100) + "%"; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "dimmer",
  means: "A wall dimmer with a long paddle knob: the pointer over the plate turns the knob up round its collar to brighten.",
  rules: [1, 4, 5, 8],
  range: [60, 110, 160],
  tour: [[193, 224], [160, 110], [240, 200], null],
  mount,
});

socketcover.code:
/**
 * Floor socket: a square brass plate set in the floor, a recessed socket
 * face with two round pin holes and an earth slot, under a flat lid hinged
 * at its far edge. The pointer over it flips the lid up on its hinge to bare
 * the socket. At rest the lid sits a little ajar, bright. The slider is how
 * far the lid swings.
 *
 * The pattern: one part tilting about a fixed hinge.
 */
const { Cam, clamp, fit, hull, poly, proj, rad, rrect, ringAt, tset, tval, tdone, tween, disposer, mk, pointer, register, solid } = HL;

const H = 36, L = 31, ZT = 5, TH = 2.6;
const disc = (x, y, r, n = 20) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * 2 * Math.PI; o.push([x + r * Math.cos(t), y + r * Math.sin(t)]); } return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-H, -H, 0], [H, H, 0], [-H, H, 0], [H, -H, 0], [-54, -L, 66], [-54, L, 66], [-L, L, 8]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);

  // the plate set in the floor, with its recessed face
  const base = solid(g);
  base.sil.setAttribute("d", poly(hull(ringAt(P, rrect(-H, -H, H, H, 6, 6), 0).concat(ringAt(P, rrect(-H, -H, H, H, 6, 6), ZT)))));
  base.cr.setAttribute("d", poly(ringAt(P, rrect(-H + 2, -H + 2, H - 2, H - 2, 4.5, 6), ZT)));
  const face = [poly(ringAt(P, rrect(-19, -21, 21, 21, 7, 6), ZT)), poly(ringAt(P, rrect(-17, -19, 19, 19, 5.5, 6), ZT))];
  for (const s of [-1, 1]) face.push(poly(disc(4, s * 9, 3.6).map(([x, y]) => P(x, y, ZT))));
  face.push(poly(ringAt(P, rrect(-12, -2.2, -7, 2.2, 1.2, 3), ZT)));
  mk("path", { class: "nf lo", d: face.join("") }, g);

  // the lid: a thin plate turning about the hinge line x = -L, z = ZT
  const lg = mk("g", {}, g);
  const knuck = mk("path", { class: "nf" }, lg);
  const lid = solid(lg);
  lid.sil.classList.add("hi");
  const ring = rrect(-L, -L, L, L, 5, 6), inn = rrect(-L + 2.4, -L + 2.4, L - 2.4, L - 2.4, 3.5, 6);
  const notch = rrect(L - 9, -6, L - 3, 6, 2.5, 4);
  const notchEl = mk("path", { class: "nf lo" }, lg);

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = rad(lerp(10, clamp(96 * amp, 20, 112), t)), ca = Math.cos(a), sa = Math.sin(a);
    const W = (x, y, z) => { const dx = x + L, dz = z - ZT; return P(-L + dx * ca - dz * sa, y, ZT + dx * sa + dz * ca); };
    const R = (r, z) => r.map((q) => W(q.u, q.v, z));
    lid.sil.setAttribute("d", poly(hull(R(ring, ZT + 0.2).concat(R(ring, ZT + TH)))));
    // the crease on whichever face of the lid looks at us
    const up = -0.61 * sa + 0.5 * ca > 0, zc = up ? ZT + TH : ZT + 0.2;
    lid.cr.setAttribute("d", poly(R(inn, zc)));
    notchEl.setAttribute("d", poly(R(notch, zc)));
    knuck.setAttribute("d", poly(hull(R(rrect(-L - 2, -14, -L + 4, 14, 2.5, 4), ZT).concat(R(rrect(-L - 2, -14, -L + 4, 14, 2.5, 4), ZT + TH + 1)))));
  }
  const lerp = (x, y, t) => x + (y - x) * t;
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, ZT);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 130 && Math.abs(sy - mid[1]) < 80), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "socketcover",
  means: "A floor socket under a hinged lid: the pointer flips the lid up on its far hinge to bare the pin holes, and it drops back on leaving.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.15],
  tour: [[212, 228], [160, 236], [262, 246], null],
  mount,
});

intercom2.code:
/**
 * Door phone: a tall wall unit with a speaker grille and a call button, and
 * a handset hanging on its face, earpiece cup at the top, mouthpiece cup at
 * the bottom, tied to the unit by a coiled cord. The pointer over the unit
 * lifts the handset off its hook, up and out, tipping it toward the ear.
 * At rest it hangs in place, bright. The slider is how far it is lifted.
 *
 * The pattern: one part lifting and tilting off a fixed body.
 */
const { Cam, fit, hull, open, poly, prism, proj, rad, rings, rrect, tset, tval, tdone, tween, facing, disposer, mk, pointer, put, register, solid } = HL;

const PW = 34, PH = 100, HY0 = -28, HY1 = -14;
const box = (x0, x1, y0, y1, z0, z1) => { const o = [], r = rrect(x0, z0, x1, z1, Math.min(x1 - x0, z1 - z0) / 2.2, 4); for (const y of [y0, y1]) for (const q of r) o.push([q.u, y, q.v]); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-7, -PW, 0], [0, PW, 0], [-7, PW, PH], [-7, -PW, PH], [46, HY0, 106], [36, HY1, 20], [20, HY1, 10]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the wall unit, its face at x = 0 looking at us
  const [pr, pi] = rings(-7, -PW, 0, PW, 3, 1.4);
  put(solid(g), prism(P, front, pr, pi, 0, PH));
  const F = (y, z) => P(0, y, z);
  const det = [];
  for (let i = 0; i < 3; i++) for (let j = 0; j < 4; j++) {
    const cy = 6 + i * 6, cz = 64 + j * 6, d = [];
    for (let k = 0; k < 10; k++) { const t = (k / 10) * 2 * Math.PI; d.push(F(cy + 1.4 * Math.cos(t), cz + 1.4 * Math.sin(t))); }
    det.push(poly(d));
  }
  det.push(poly(rrect(5, 30, 19, 44, 3, 4).map((q) => F(q.u, q.v))), poly(rrect(8, 33, 16, 41, 2, 4).map((q) => F(q.u, q.v))));
  det.push(poly(rrect(HY0 - 1, 49, HY1 + 1, 55, 2, 4).map((q) => F(q.u, q.v))));
  mk("path", { class: "nf lo", d: det.join("") }, g);

  // the handset, in its own frame: two cups facing the wall and a grip bar
  const cord = mk("path", { class: "nf lo" }, g);
  const hg = mk("g", {}, g);
  const parts = [box(0.5, 9, HY0, HY1, 76, 92), box(0.5, 9, HY0, HY1, 16, 32), box(5, 10, HY0 + 1, HY1 - 1, 22, 86)];
  const sols = parts.map(() => { const s = solid(hg); s.sil.classList.add("hi"); return s; });

  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const k = Math.min(1.25, amp) * t, a = rad(28 * k), ca = Math.cos(a), sa = Math.sin(a), ox = 22 * k, oz = 12 * k;
    const W = ([x, y, z]) => { const dx = x - 5, dz = z - 16; return P(5 + ox + dx * ca + dz * sa, y, 16 + oz - dx * sa + dz * ca); };
    parts.forEach((pts, i) => {
      const s = pts.map(W);
      sols[i].sil.setAttribute("d", poly(hull(s)));

      if (i === 2) sols[i].cr.setAttribute("d", open([W([10, HY0 + 2.5, 24]), W([10, HY0 + 2.5, 84])]));
      else sols[i].cr.setAttribute("d", open([W([9, HY0 + 2, i ? 18 : 78]), W([9, HY0 + 2, i ? 30 : 90])]));
    });
    // the coiled cord: from the mouthpiece down and back into the unit
    const end = W([3, HY0 + 3, 16]), st = P(0, HY0 + 3, 6), c = [];
    for (let i = 0; i <= 40; i++) { const u = i / 40, w = Math.sin(u * Math.PI * 12) * 2.6; c.push([end[0] + (st[0] - end[0]) * u + w, end[1] + (st[1] - end[1]) * u + 22 * Math.sin(u * Math.PI)]); }
    cord.setAttribute("d", open(c));
  }
  const tw = tween(0);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, PH / 2);
  let on = null;
  function set(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? "lift" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => set(Math.abs(sx - mid[0]) < 110 && Math.abs(sy - mid[1]) < 130), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

