  name: "intercom2",
  means: "A door phone on the wall: the pointer lifts the handset off its hook, up and out toward the ear, and it hangs back up on leaving.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.25],
  tour: [[171, 163], [205, 118], [150, 222], null],
  mount,
});

meatthermo.code:
/**
 * Meat thermometer: a folding probe thermometer lying on the counter, its
 * long needle hinged at the end of the handle. At rest the needle is half
 * folded, bright. The pointer over the thermometer swings the needle open
 * on its hinge; the slider sets how far it opens.
 *
 * The pattern: one part swinging about a hinge.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, unproj, clamp, rad, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BL = 42, BW = 16, BH = 9, L = 74, HX = BL - 3, HY = BW + 3.5, PZ0 = 2, PZ1 = 5.5, REST = 95;

function needle(ang) {
  // a tapered bar, hinged at its root, swung by ang degrees from folded
  const a = rad(ang), dx = -Math.cos(a), dy = Math.sin(a);
  const ring = rrect(0, -3, L, 3, 2.6, 4).map((q) => {
    const t = 1 - 0.72 * clamp(q.u / L, 0, 1) ** 1.4, u = q.u, v = q.v * t;
    return { u: HX + u * dx - v * dy, v: HY + u * dy + v * dx, nu: q.nu * dx - q.nv * dy, nv: q.nu * dy + q.nv * dx };
  });
  return ring;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-4, -4, 0], [BL + 4, BW + 4, BH], [HX + L, HY, 0], [HX + L * 0.7, HY + L * 0.7, 0], [HX + 6, HY + L, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the handle, with its display window and button
  const [br, bi] = rings(0, 0, BL, BW, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BH));
  const [wr] = rings(8, 3, 26, BW - 3, 2.5, 1);
  mk("path", { d: poly(ringAt(P, wr, BH)), class: "nf lo" }, g);
  const btn = mk("ellipse", { class: "dot m" }, g);
  const bp = P(33, BW / 2, BH);
  btn.setAttribute("cx", bp[0]); btn.setAttribute("cy", bp[1]); btn.setAttribute("rx", 1.8); btn.setAttribute("ry", 1.1);

  // the needle and its hinge collar
  const ng = mk("g", {}, g);
  const ns = solid(ng);
  const col = solid(ng);
  const colRing = rrect(HX - 4, HY - 4, HX + 4, HY + 4, 4, 4);
  put(col, prism(P, front, colRing, rrect(HX - 2.6, HY - 2.6, HX + 2.6, HY + 2.6, 2.6, 4), 1, PZ1 + 1.2));
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const ring = needle(a);
    const pts = ringAt(P, ring, PZ0).concat(ringAt(P, ring, PZ1));
    ns.sil.setAttribute("d", poly(hull(pts)));
    ns.cr.setAttribute("d", open(ringAt(P, run(ring, front), PZ1 - 0.6)));
  }
  ns.sil.classList.add("hi");

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? maxA : REST, performance.now(), 0);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -12 && x < HX + L * 0.8 && y > -12 && y < HY + L + 6;
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { maxA = v; if (on) { tset(ang, maxA, performance.now(), 0); B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "meatthermo",
  means: "A folding meat thermometer: the long probe swings open on its hinge at the end of the handle.",
  rules: [1, 3, 5, 8],
  range: [120, 180, 180],
  tour: [[117, 174], [42, 219], [200, 120], null],
  mount,
});

kitchenscale2.code:
/**
 * Kitchen timer cube: a flip timer, a rounded cube with a small display on
 * its side and a pip code on its top face. At rest it sits square, one pip
 * bright. The pointer over it tips the cube onto its edge, as a hand flips
 * it to start a count; the slider sets how far it tips.
 *
 * The pattern: one solid tilting about a ground edge.
 */
const {
  Cam, fit, hull, open, poly, proj, rrect, circ, unproj, rad, tset, tval, tdone, tween,
  disposer, mk, pointer, register,
} = HL;

const S = 46, R = 9, B = 2.2, REST = 0;
const PIPS = [[13, 13], [23, 23], [33, 33]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-2, -2, 0], [S + 30, S + 2, 0], [S + 2, -2, S + 20], [-2, S + 2, S], [S + 40, S + 2, 30]], 200, 172);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const sil = mk("path", { class: "sil" }, g);
  const top = mk("path", { class: "nf lo" }, g);
  const disp = mk("path", { class: "nf lo" }, g);
  const pips = PIPS.map((_, i) => mk("path", { class: i === 1 ? "dot" : "dot off" }, g));

  const foot = rrect(0, 0, S, S, R, 5), inner = rrect(B, B, S - B, S - B, R - B, 5);
  const screen = rrect(9, 9, S - 9, S * 0.5, 3, 4); // on the +y face: u along x, v along z
  const pipRing = circ(2.2, 14);
  const tilt = tween(REST);
  let last = NaN;

  function draw(th) {
    if (th === last) return;
    last = th;
    const c = Math.cos(rad(th)), s = Math.sin(rad(th));
    const W = (x, y, z) => { const dx = x - S; return P(S + dx * c + z * s, y, -dx * s + z * c); };
    const pts = [];
    for (const q of foot) pts.push(W(q.u, q.v, 0), W(q.u, q.v, S));
    sil.setAttribute("d", poly(hull(pts)));
    top.setAttribute("d", poly(inner.map((q) => W(q.u, q.v, S - 0.4))));
    disp.setAttribute("d", poly(screen.map((q) => W(q.u, S, S - q.v))));
    PIPS.forEach(([x, y], i) => pips[i].setAttribute("d", poly(pipRing.map((q) => W(x + q.u, y + q.v, S)))));
  }

  const L = register(stage, (_dt, now) => { draw(tval(tilt, now)); return !tdone(tilt, now); });
  bag.add(L.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(tilt, v ? maxT : REST, performance.now(), 0);
    sil.classList.toggle("hi", v);
    pips[1].setAttribute("class", v ? "dot off" : "dot");
    read.textContent = v ? "flip" : "rest";
    L.wake();
  }
  function hit([sx, sy]) {
    const inA = ([x, y]) => x > -20 && x < S + 40 && y > -20 && y < S + 20;
    return inA(unproj(C, sx, sy, 0)) || inA(unproj(C, sx, sy, S));
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { maxT = v; if (on) { tset(tilt, maxT, performance.now(), 0); L.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "kitchenscale2",
  means: "A flip kitchen timer cube: the pointer tips the cube up onto its edge, the way a hand flips it to start the count.",
  rules: [1, 3, 5, 8],
  range: [25, 50, 70],
  tour: [[200, 97], [126, 189], [250, 170], null],
  mount,
});

multitool.code:
/**
 * Multitool: an oscillating multi-tool, a long motor body with a narrow head
 * and a wide plunge blade clamped flat under it. The blade swings round the
 * spindle to point at the pointer, as its oscillation sweeps side to side.
 * At rest it points a little to the near side, bright.
 * The slider is how far the blade can swing.
 *
 * The pattern: a continuous aim (a spring on an angle); the hit is on the
 * blade's plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX = 14, ZB = 18, L0 = 5, L1 = 58, REST = 25;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-84, -12, 50], [-84, 12, 28], [CX + L1, 0, ZB], [CX + 40, 40, ZB], [CX + 40, -40, ZB]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const blade = solid(g);
  blade.sil.classList.add("hi");
  put(solid(g), prism(P, front, circ(8, 24), circ(6.5, 24), ZB + 2, 28));
  let [r, i] = rings(-84, -11, 4, 11, 10, 1.6);
  put(solid(g), prism(P, front, r, i, 28, 48));
  [r, i] = rings(-84, -4, -78, 4, 2, 0.8);
  put(solid(g), prism(P, front, r, i, 34, 42));
  [r, i] = rings(0, -10, 24, 10, 8, 1.4);
  put(solid(g), prism(P, front, r, i, 27, 46));

  const A = spring(REST);
  let reach = 70 * value, over = null, last = NaN;
  // the blade's outline, in its own frame: u along the blade, v across
  const shape = [[L0, -7], [L1 - 10, -12], [L1, -12], [L1, 12], [L1 - 10, 12], [L0, 7]];

  function draw() {
    if (Math.abs(A.x - last) < 0.01) return;
    last = A.x;
    const a = (A.x * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    const at = (pts, z) => pts.map(([u, v]) => P(CX + u * c - v * s, u * s + v * c, z));
    const top = at(shape, ZB + 2), bot = at(shape, ZB);
    const teeth = at(Array.from({ length: 13 }, (_, k) => [L1 + (k % 2 ? 0 : -2.2), -12 + 2 * k]), ZB + 2);
    blade.sil.setAttribute("d", poly(hull(top.concat(bot))));
    blade.cr.setAttribute("d", open(at([[L1 - 4, -11], [L1 - 4, 11]], ZB + 2)) + open(teeth));
  }

  const B = register(stage, (dt) => { const m = stepS(A, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    const t = over === null ? REST : clamp(over, -reach, reach);
    A.t = t;
    read.textContent = over === null ? "rest" : `${Math.round(t)}°`;
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZB), dx = x - CX, rr = Math.hypot(dx, y);
      over = rr > L1 + 40 || rr < 4 || dx < -10 ? null : (Math.atan2(y, dx) * 180) / Math.PI;
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return {
    set: (v) => { reach = 70 * v; retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "multitool",
  means: "An oscillating multi-tool: the wide plunge blade under its head swings round the spindle to point at the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1.2],
  tour: [[328, 203], [194, 259], [290, 240], null],
  mount,
});

stud.code:
/**
 * Stud finder: a hand-sized finder lying on a strip of wall with its studs
 * marked as dim lines. The pointer over the wall slides the finder along it
 * to the next stud, its sensor line lighting where it stops. At rest the
 * finder sits short of the first stud, bright. The slider is how far it slides.
 */
const { Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const WL = 170, WW = 46, WZ = 5, FL = 50, FW = 34, FZ = 16, X0 = 8, SL = 100;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  const box = [[0, 0, 0], [WL, WW, 0], [WL, 0, 0], [0, WW, 0], [X0, 6, WZ + FZ + 3], [WL - 8, 6, WZ + FZ + 3]];
  fit(C, box, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [wr, wi] = rings(0, 0, WL, WW, 5, 2);
  put(solid(g), prism(P, front, wr, wi, 0, WZ));
  let st = "";
  for (const x of [72, 138]) st += seg(P(x, 3, WZ), P(x, WW - 3, WZ));
  mk("path", { d: st, class: "nf lo" }, g);
  const body = solid(g), pad = solid(g), sensor = mk("path", { class: "nf" }, g);
  body.sil.classList.add("hi");

  const tw = tween(0);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const x = X0 + SL * v, y = (WW - FW) / 2;
    const [br, bi] = rings(x, y, x + FL, y + FW, 12, 1.6);
    put(body, prism(P, front, br, bi, WZ, WZ + FZ));
    const [pr, pi] = rings(x + 8, y + 7, x + 32, y + FW - 7, 6, 1.2);
    put(pad, prism(P, front, pr, pi, WZ + FZ, WZ + FZ + 2.5));
    sensor.setAttribute("d", seg(P(x + FL - 7, y + 6, WZ + FZ), P(x + FL - 7, y + FW - 6, WZ + FZ)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const sp = box.map((p) => P(...p));
  const xs = sp.map((p) => p[0]), ys = sp.map((p) => p[1]);
  const inside = ([sx, sy]) => sx > Math.min(...xs) - 8 && sx < Math.max(...xs) + 8 && sy > Math.min(...ys) - 8 && sy < Math.max(...ys) + 8;
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? reach : 0, performance.now(), 0);
    read.textContent = a ? "stud" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { tset(tw, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "stud",
  means: "A stud finder on a strip of wall: the pointer slides it along the wall to the next stud.",
  rules: [1, 3, 5, 6],
  range: [0.3, 1, 1],
  tour: [[124, 108], [200, 175], [270, 230], null],
  mount,
});

multimeter.code:
/**
 * Multimeter: a handheld meter lying on the bench, a window at its head, a
 * big rotary dial and the probe jacks at its foot. The pointer over it tilts
 * the meter up on its back edge, as it is propped to be read. At rest it lies
 * nearly flat, its dial bright. The slider is how far it tilts.
 */
const { Cam, circ, fit, facing, poly, prism, proj, rings, ringAt, rrect, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const L = 100, W = 62, H = 12, T0 = 6, TILT = 52;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.2);
  const P0 = proj(C);
  const tp = (deg) => { const a = deg * Math.PI / 180, c = Math.cos(a), s = Math.sin(a); return (x, y, z) => [L - (L - x) * c - z * s * -1 * -1, y, (L - x) * s + z * c]; };
  const box = [];
  for (const d of [T0, T0 + TILT]) { const f = tp(d); for (const x of [0, L]) for (const y of [0, W]) for (const z of [0, H + 5]) box.push(f(x, y, z)); }
  fit(C, box, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const body = solid(g), win = mk("path", { class: "nf lo" }, g), jacks = mk("path", { class: "nf lo" }, g);
  const dial = solid(g), ptr = mk("path", { class: "nf" }, g);
  dial.sil.classList.add("hi");

  const tw = tween(0);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const f = tp(T0 + TILT * v), Q = (x, y, z) => P(...f(x, y, z));
    const [br, bi] = rings(0, 0, L, W, 12, 1.8);
    put(body, prism(Q, front, br, bi, 0, H));
    win.setAttribute("d", poly(ringAt(Q, rrect(8, 10, 32, W - 10, 4, 4), H)));
    let j = "";
    for (const y of [16, 31, 46]) j += poly(ringAt(Q, disc(88, y, 3.2, 16), H));
    jacks.setAttribute("d", j);
    put(dial, prism(Q, front, disc(58, W / 2, 17), disc(58, W / 2, 15), H, H + 4));
    ptr.setAttribute("d", seg(Q(46, W / 2 - 6, H + 4), Q(68, W / 2 + 7, H + 4)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const sp = box.map((p) => P(...p));
  const xs = sp.map((p) => p[0]), ys = sp.map((p) => p[1]);
  const inside = ([sx, sy]) => sx > Math.min(...xs) - 8 && sx < Math.max(...xs) + 8 && sy > Math.min(...ys) - 8 && sy < Math.max(...ys) + 8;
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? reach : 0, performance.now(), 0);
    read.textContent = a ? "tilt" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act) { tset(tw, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "multimeter",
  means: "A multimeter lying on the bench with its dial and jacks: the pointer tilts it up on its back edge to be read.",
  rules: [1, 3, 5, 6],
  range: [0.3, 1, 1],
  tour: [[213, 218], [178, 190], [240, 250], null],
  mount,
});

tilesaw.code:
/**
 * Tile nipper: a pair of nippers lying flat, two long handles crossing at a
 * riveted pivot, with broad blunt jaws for biting the edge off a tile. The
 * pointer over the nipper swings the top arm about the rivet: its handle opens
 * away and its jaw gapes. At rest the jaws sit a little apart and the top jaw
 * is bright. The slider is how wide it opens.
 *
 * The pattern: one part turning about a fixed axis, tweened on hover.
 */
const { Cam, circ, rrect, fit, proj, hull, poly, rad, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

const REST = 12, LOW = -12, G = -24;
const V = [0.61, 0.61, 0.5];
function bx(a0, b0, a1, b1, c0, c1, r) {
  const q = rrect(a0, b0, a1, b1, r, 4), qi = rrect(a0 + 1.3, b0 + 1.3, a1 - 1.3, b1 - 1.3, Math.max(r - 1.3, 0.4), 4);
  return { pts: [c0, c1].flatMap((c) => q.map((s) => [s.u, s.v, c])), cr: qi.map((s) => [s.u, s.v, c1]), n: [0, 0, 1] };
