  function draw(v) {
    const a = rad(REST + v * amp);
    if (a === last) return;
    last = a;
    for (const e of els) {
      const f = e.pt.m ? (p) => turn(p, a) : (p) => p;
      e.sil.setAttribute("d", poly(hull(e.pt.s.pts.map((p) => P(...f(p))))));
      e.cr.setAttribute("d", poly(e.pt.s.cr.map((p) => P(...f(p)))));
