reelmic.code:
/**
 * Studio monitor: a two-way speaker cabinet hung in a yoke on a desk stand,
 * woofer and tweeter on its front. The pointer is where the listener's ears
 * are: the cabinet pitches on its side bolts to aim at them, down when the
 * pointer is in front, back when it is behind. At rest it leans back a
 * little and its woofer is bright. The slider is how far it may tilt.
 *
 * The pattern: a continuous aim (spotlights' spring, on one angle); the hit
 * is on a fixed plane at the bolts' height, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, rrect, run, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PIV = 54, HW = 14, HD = 12, HH = 21, YX = 17, MAX = rad(28), REST = -0.16;
const AZ = rad(45), KK = 0.5, V = [Math.sin(AZ), Math.cos(AZ), KK / Math.sqrt(1 - KK * KK)];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.15);
  fit(C, [[-20, -16, 0], [20, 16, 0], [20, -16, 0], [-20, 16, 0], [HW, HD + 12, PIV + HH + 4], [-HW, -HD - 12, PIV + HH + 4], [HW, HD + 14, PIV - HH], [-HW, -HD - 14, PIV - HH]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-20, -16, 20, 16, 6, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  put(solid(g), prism(P, front, circ(3, 20), circ(2, 20), 3, PIV - HH - 8));
  const [yr, yi] = rings(-YX - 1.5, -2, YX + 1.5, 2, 1.5, 0.6);
  put(solid(g), prism(P, front, yr, yi, PIV - HH - 8, PIV - HH - 5));
  mk("path", { class: "nf sil", d: seg(P(-YX, 0, PIV - HH - 5), P(-YX, 0, PIV)) }, g);
  const box = mk("path", { class: "sil" }, g), crease = mk("path", { class: "nf lo" }, g);
  const woof = mk("path", { class: "nf" }, g), cone = mk("path", { class: "nf lo" }, g), tweet = mk("path", { class: "nf" }, g);
  mk("path", { class: "nf sil", d: seg(P(YX, 0, PIV - HH - 5), P(YX, 0, PIV)) }, g);
  const bolt = mk("path", { class: "nf" }, g);
  const ring = rrect(-HW, -HD, HW, HD, 4, 4), inner = rrect(-HW + 1.6, -HD + 1.6, HW - 1.6, HD - 1.6, 2.4, 4);
  const th = spring(REST);
  let last = NaN, over = null;

  function draw() {
    const t = th.x;
    if (t === last) return;
    last = t;
    const c = Math.cos(t), s = Math.sin(t);
    // pitch about x: +z leans toward +y by t
    const rot = (p) => [p[0], p[1] * c + p[2] * s, -p[1] * s + p[2] * c];
    const at = (u, v, w) => { const q = rot([u, v, w]); return P(q[0], q[1], PIV + q[2]); };
    const faces = (q) => dot(rot([q.nu, q.nv, 0]), V) > 0;
    const top = dot(rot([0, 0, 1]), V) > 0 ? HH : -HH;
    box.setAttribute("d", poly(hull(ring.map((q) => at(q.u, q.v, -HH)).concat(ring.map((q) => at(q.u, q.v, HH))))));
    crease.setAttribute("d", open(run(inner, faces).map((q) => at(q.u, q.v, top))));
    const disc = (r, w, n) => poly(circ(r, n).map((q) => at(q.u, HD + 0.2, w + q.v)));
    woof.setAttribute("d", disc(10, -6, 40));
    cone.setAttribute("d", disc(5.5, -6, 32) + disc(2, -6, 16));
    tweet.setAttribute("d", disc(4.2, 12, 28));
    bolt.setAttribute("d", poly(circ(1.8, 12).map((q) => P(YX + 0.5, q.u, PIV + q.v))));
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    th.t = over ? clamp(over[1] / 40, -1, 1) * MAX * reach : REST;
    woof.setAttribute("class", over ? "nf" : "nf hi");
    box.setAttribute("class", over ? "sil hi" : "sil");
    read.textContent = over ? `pitch ${Math.round((-th.t * 180) / Math.PI)}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], PIV); over = Math.hypot(x, y) > 95 ? null : [x, y]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "reelmic",
  means: "A studio monitor in a yoke on a desk stand: the cabinet pitches on its bolts to aim at the pointer, down in front, up behind.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1.4],
  tour: [[133, 139], [200, 55], [155, 188], null],
  mount,
});

keytar.code:
/**
 * Keyboard stand: a synth keyboard on an X stand, two scissor frames under
 * it. The pointer's height says how high to play: the scissors open, their
 * feet draw in, and the keyboard rises; low, they spread and it sinks. At
 * rest the stand sits low and the black keys are bright. The slider is how
 * far the scissors may open.
 *
 * The pattern: a continuous value (a spring on one angle) read from the
 * pointer's screen height against fixed bands, never the moving parts.
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, proj, rad, rings, ringAt, run, seg, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const LB = 64, FX = 30, KX = 48, KY = 13, KH = 6, A0 = rad(40), SPAN = rad(32), AMAX = rad(78);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  const hiZ = LB * Math.sin(AMAX) + KH, sp = (LB / 2) * Math.cos(A0);
  fit(C, [[-KX, -sp, 0], [KX, sp, 0], [KX, -sp, 0], [-KX, sp, 0], [-KX, -KY, hiZ], [KX, KY, hiZ]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const far = mk("path", { class: "nf sil" }, g), near = mk("path", { class: "nf sil" }, g);
  const kb = mk("path", { class: "sil" }, g), cr = mk("path", { class: "nf lo" }, g);
  const whites = mk("path", { class: "nf lo" }, g), blacks = mk("path", { class: "nf" }, g);
  const [ring, inner] = rings(-KX, -KY, KX, KY, 3, 1.4);
  const a = spring(A0);
  let last = NaN, over = false, lastT = null;

  function frame(x, an) {
    const s = (LB / 2) * Math.cos(an), h = LB * Math.sin(an);
    return seg(P(x, -s, 0), P(x, s, h)) + seg(P(x, s, 0), P(x, -s, h)) + seg(P(x, -s - 4, 0), P(x, -s + 4, 0)) + seg(P(x, s - 4, 0), P(x, s + 4, 0));
  }

  function draw() {
    const an = a.x;
    if (an === last) return;
    last = an;
    const h = LB * Math.sin(an), z1 = h + KH;
    far.setAttribute("d", frame(-FX, an));
    near.setAttribute("d", frame(FX, an));
    kb.setAttribute("d", poly(hull(ringAt(P, ring, h).concat(ringAt(P, ring, z1)))));
    cr.setAttribute("d", open(ringAt(P, run(inner, front), z1)));
    let w = "", b = "";
    for (let i = 0; i <= 26; i++) {
      const x = -KX + 6 + i * ((2 * KX - 12) / 26);
      w += seg(P(x, -1, z1), P(x, KY - 2, z1));
      if ([0, 1, 3, 4, 5].includes(i % 7) && i < 26) b += seg(P(x + 1.6, -1, z1), P(x + 1.6, 5, z1));
    }
    whites.setAttribute("d", w + seg(P(-KX + 6, -1, z1), P(KX - 6, -1, z1)));
    blacks.setAttribute("d", b);
  }

  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(); return m; });
  bag.add(B.unregister);

  // fixed bands: the stand's rest footprint on screen, top to bottom
  const yTop = P(0, 0, hiZ)[1], yBot = P(0, 0, 0)[1];
  function target(sy) { return clamp((yBot - sy) / (yBot - yTop), 0, 1); }

  function retarget(t) {
    lastT = t;
    over = t !== null;
    a.t = over ? Math.min(AMAX, A0 + t * SPAN * reach) : A0;
    blacks.setAttribute("class", over ? "nf" : "nf hi");
    kb.setAttribute("class", over ? "sil hi" : "sil");
    read.textContent = over ? `h ${Math.round(LB * Math.sin(a.t) + KH)}` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { retarget(Math.abs(p[0] - 200) > 150 ? null : target(p[1])); },
    leave: () => retarget(null),
  }));
  bag.add(() => svg.replaceChildren());
  retarget(null);
  return { set: (v) => { reach = v; retarget(lastT); }, destroy: bag.dispose };
}

hairline({
  name: "keytar",
  means: "A synth keyboard on an X stand: the pointer's height opens the scissor frames and the keyboard rises or sinks with them.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1.4],
  tour: [[200, 108], [200, 200], [200, 88], null],
  mount,
});

lifebuoy2.code:
/**
 * Throw line bag: a rescue throw bag hung by its rope from the arm of a
 * dockside post, a padded cylinder with a drawstring collar and a reflective
 * band. The pointer over the bag swings it out from the post on the discrete
 * clock, ready to throw. At rest it hangs with a slight lean, its collar
 * bright. The slider is how far it swings.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 100, PX = -26, R = 13, H0 = 12, H1 = 52, REST = 8;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value / 100;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[PX - 12, -14, 0], [PX + 12, 14, 0], [0, -R, PZ + 6], [0, R, PZ + 6], [H1 * 0.8 + R, R, PZ - H1 * 0.6], [-R, 0, PZ - H1]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(PX - 12, -14, PX + 12, 14, 5, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, 3));
  const [pr, pi] = rings(PX - 3, -3, PX + 3, 3, 2.5, 0.8);
  put(solid(g), prism(P, front, pr, pi, 3, PZ + 6));
  const [ar, ai] = rings(PX - 3, -2.5, 4, 2.5, 2, 0.8);
  put(solid(g), prism(P, front, ar, ai, PZ + 2, PZ + 6));
  const rope = mk("path", { class: "nf" }, g);
  const body = solid(g), band = mk("path", { class: "nf lo" }, g), collar = mk("path", { class: "nf" }, g);
  const ang = tween(REST);
  let last = NaN;
  function ring(th, h, r) {
    const s = Math.sin(rad(th)), c = Math.cos(rad(th)), out = [];
    for (let i = 0; i < 36; i++) {
      const t = (i / 36) * 2 * Math.PI, cu = Math.cos(t) * r, cv = Math.sin(t) * r;
      out.push(P(h * s + cu * c, cv, PZ - h * c + cu * s));
    }
    return out;
  }
  function draw(th) {
    if (th === last) return;
    last = th;
    const s = Math.sin(rad(th)), c = Math.cos(rad(th));
    rope.setAttribute("d", seg(P(0, 0, PZ + 2), P(H0 * s, 0, PZ - H0 * c)) + seg(P(0, 0, PZ + 2), P((H0 + 1) * s - 3 * c, 0, PZ - (H0 + 1) * c - 3 * s)));
    const top = ring(th, H0 + 2, R - 1), bot = ring(th, H1, R), mid = ring(th, H0 + 5, R);
    body.sil.setAttribute("d", poly(hull(top.concat(mid, bot))));
    body.cr.setAttribute("d", poly(ring(th, H0 + 5, R - 1.5)));
    band.setAttribute("d", poly(hull(ring(th, 30, R + 0.2).concat(ring(th, 36, R + 0.2)))));
    collar.setAttribute("d", poly(hull(ring(th, H0, 5).concat(ring(th, H0 + 4, 7)))));
  }
  collar.classList.add("hi");
  body.cr.classList.add("lo");

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  // hit: the bag's rest outline on screen, which never moves
  const pts = ring(REST, H0, R).concat(ring(REST, H1, R));
  const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
  const x0 = Math.min(...xs) - 10, x1 = Math.max(...xs) + 10, y0 = Math.min(...ys) - 10, y1 = Math.max(...ys) + 10;
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? REST + 52 * amt : REST, performance.now(), 0);
    read.textContent = v ? "swing" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setOn(sx > x0 && sx < x1 && sy > y0 && sy < y1), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v / 100; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "lifebuoy2",
  means: "A rescue throw bag hung from a dockside post: the pointer over the bag swings it out on its rope, ready to throw.",
  rules: [1, 4, 5, 9],
  range: [30, 100, 100],
  tour: [[195, 138], [195, 160], [205, 110], null],
  mount,
});

firealarm2.code:
/**
 * Fire alarm pull: a manual call point, a square box on a short post with a
 * recess in its front face and a pull handle hinged at the recess's foot.
 * The pointer over the box pulls the handle: it swings out and down from the
 * face on the discrete clock. At rest the handle stands a little proud, bright.
 * The slider is how far the handle swings.
 */
const {
  Cam, fit, facing, fillet, hull, poly, prism, proj, rings, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const D = 22, W = 40, Z0 = 26, Z1 = 70, HZ = 34, H = 26, HY0 = 8, HY1 = 32, TH = 3, REST = 16;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value / 100;
  const C = Cam(45, 0.5, 2.85);
  fit(C, [[-4, -4, 0], [D + 4, W + 4, 0], [D + 4, -4, 0], [-4, W + 4, 0], [0, 0, Z1], [D + H + 4, W, HZ], [D, W, Z1]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // foot plate and post
  const [fr, fi] = rings(-4, -4, D + 4, W + 4, 4, 1.5);
  put(solid(g), prism(P, front, fr, fi, 0, 3));
  const [pr, pi] = rings(D / 2 - 4, W / 2 - 4, D / 2 + 4, W / 2 + 4, 3.5, 1);
  put(solid(g), prism(P, front, pr, pi, 3, Z0));
  // the box
  const [br, bi] = rings(0, 0, D, W, 4, 1.8);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  // the recess on the front face (x = D)
  const face = (y, z) => P(D + 0.01, y, z);
  mk("path", { d: poly(fillet([face(HY0 - 2, HZ - 2), face(HY1 + 2, HZ - 2), face(HY1 + 2, HZ + H + 2), face(HY0 - 2, HZ + H + 2)], [2, 2, 2, 2])), class: "nf lo" }, g);
  // the handle: a thick plate hinged along its lower edge
  const hd = mk("path", { class: "sil" }, g), hc = mk("path", { class: "nf lo" }, g), grip = mk("path", { class: "nf lo" }, g);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const pt = (y, h, t) => P(D + h * s + t * c, y, HZ + h * c - t * s);
    const outer = [pt(HY0, 0, TH), pt(HY1, 0, TH), pt(HY1, H, TH), pt(HY0, H, TH)];
    const inner = [pt(HY0, 0, 0), pt(HY1, 0, 0), pt(HY1, H, 0), pt(HY0, H, 0)];
    hd.setAttribute("d", poly(fillet(hull(outer.concat(inner)), Array(8).fill(1.5))));
    hc.setAttribute("d", poly(fillet(outer, [1.5, 1.5, 1.5, 1.5])));
    grip.setAttribute("d", poly(fillet([pt(HY0 + 5, H - 7, TH), pt(HY1 - 5, H - 7, TH), pt(HY1 - 5, H - 3, TH), pt(HY0 + 5, H - 3, TH)], [1, 1, 1, 1])));
  }
  hd.classList.add("hi");

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  // hit: the box's rest outline on screen, which never moves
  const box = [];
  for (const [x, y] of [[0, 0], [D, 0], [D, W], [0, W]]) box.push(P(x, y, Z0), P(x, y, Z1));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const bx0 = Math.min(...xs) - 8, bx1 = Math.max(...xs) + 8, by0 = Math.min(...ys) - 8, by1 = Math.max(...ys) + 8;
  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, v ? REST + (100 - REST) * amt : REST, performance.now(), 0);
    read.textContent = v ? "pulled" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setOn(sx > bx0 && sx < bx1 && sy > by0 && sy < by1), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v / 100; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "firealarm2",
  means: "A manual call point on a post: the pointer over the box pulls its handle, which swings out and down from the face.",
  rules: [1, 4, 5, 9],
  range: [30, 100, 100],
  tour: [[222, 136], [240, 170], [200, 110], null],
  mount,
});

defib.code:
/**
 * Defibrillator cabinet: a wall cabinet on a low plinth, a beacon on its top,
 * the AED unit standing inside behind a windowed door. The pointer over the
 * cabinet swings the door open on its hinge; leaving lets it fall back ajar.
 * At rest the door stands slightly open, bright. The slider is how far it opens.
 *
 * The pattern: one part swinging on a hinge.
 */
const {
  Cam, circ, fillet, fit, facing, poly, prism, proj, rings, ringAt, rad, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, open, hull,
} = HL;

const W = 60, D = 24, H = 84, Z0 = 8, REST = 16;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ang = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-6, -6, 0], [W + 6, D + 6, 0], [-40, D + 62, Z0], [W + 6, -6, H + 12], [-40, D + 62, H]], 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-6, -6, W + 6, D + 6, 4, 1.5);
  put(solid(g), prism(P, front, pr, pi, 0, Z0));
  const [br, bi] = rings(0, 0, W, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, Z0, Z0 + H));
  put(solid(g), prism(P, front, disc(W / 2, D / 2, 6), disc(W / 2, D / 2, 4.4), Z0 + H, Z0 + H + 7));
  const onFace = (pts) => pts.map(([x, z]) => P(x, D, z));
  // the opening and the unit inside: a case with a carry handle
  mk("path", { d: poly(fillet(onFace([[5, Z0 + 5], [W - 5, Z0 + 5], [W - 5, Z0 + H - 5], [5, Z0 + H - 5]]), [3, 3, 3, 3])), class: "lo" }, g);
  mk("path", { d: poly(fillet(onFace([[14, Z0 + 14], [W - 14, Z0 + 14], [W - 14, Z0 + 52], [14, Z0 + 52]]), [4, 4, 4, 4])), class: "nf" }, g);
  mk("path", { d: open(onFace([[22, Z0 + 52], [22, Z0 + 60], [W - 22, Z0 + 60], [W - 22, Z0 + 52]])), class: "nf" }, g);
  mk("path", { d: poly(fillet(onFace([[22, Z0 + 26], [W - 22, Z0 + 26], [W - 22, Z0 + 42], [22, Z0 + 42]]), [2, 2, 2, 2])), class: "nf lo" }, g);

  const door = mk("path", { class: "sil hi" }, g), win = mk("path", { class: "nf lo" }, g), knob = mk("path", { class: "nf" }, g);
  const Wd = W - 3, hx = 1.5, za = Z0 + 3, zb = Z0 + H - 3;
  const at = (s, z, a) => P(hx + s * Math.cos(rad(a)), D + 0.5 + s * Math.sin(rad(a)), z);
  const sw = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    door.setAttribute("d", poly(fillet([at(0, za, a), at(Wd, za, a), at(Wd, zb, a), at(0, zb, a)], [3, 3, 3, 3])));
    win.setAttribute("d", poly(fillet([at(7, za + 8, a), at(Wd - 7, za + 8, a), at(Wd - 7, zb - 8, a), at(7, zb - 8, a)], [3, 3, 3, 3])));
    knob.setAttribute("d", poly(fillet([at(Wd - 4.5, Z0 + 36, a), at(Wd - 2.5, Z0 + 36, a), at(Wd - 2.5, Z0 + 50, a), at(Wd - 4.5, Z0 + 50, a)], [1, 1, 1, 1])));
  }
  const B = register(stage, (_dt, now) => { draw(tval(sw, now)); return !tdone(sw, now); });
  bag.add(B.unregister);

  const box = hull(ringAt(P, br, Z0).concat(ringAt(P, br, Z0 + H)));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const inside = ([sx, sy]) => sx > Math.min(...xs) - 10 && sx < Math.max(...xs) + 10 && sy > Math.min(...ys) - 10 && sy < Math.max(...ys) + 10;
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(sw, on ? ang : REST, performance.now(), 0);
    read.textContent = on ? "open " + Math.round(ang) + "°" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(inside(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { ang = v; if (act) { tset(sw, ang, performance.now(), 0); read.textContent = "open " + Math.round(ang) + "°"; B.wake(); } },
    destroy: bag.dispose,
  };
}

