  name: "windowlatch",
  means: "A casement window in a wall: over it, the crank winds the sash wide open on its hinge; leaving, it swings back ajar.",
  rules: [1, 4, 5, 6],
  range: [45, 85, 110],
  tour: [[214, 157], [180, 110], [236, 200], null],
  mount,
