  name: "chestfreezer",
  means: "A chest freezer: over it, the long lid swings up on its back hinge to show the cold well and wire basket inside.",
  rules: [1, 3, 5, 8],
  range: [40, 75, 100],
  tour: [[196, 205], [165, 160], [225, 262], null],
  mount,
});

rangehood.code:
/**
 * Cooker hood: a wall chimney over a slim canopy, with a glass visor hinged
 * along the canopy's front edge. At rest the visor hangs tilted a little
 * forward, bright. Over the hood the visor swings up on its hinge, the way
 * it lifts to run the fan. The slider is how far the visor tilts.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, rrect, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const X = 66, D = 40, Z0 = 40, Z1 = 48, HY = D, HZ = 46, L = 26, T = 2.2, REST = 28;
const toR = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, 0, Z0], [X, D, Z0], [X, 0, Z0], [0, D, Z0], [22, 0, 96], [44, 18, 96], [0, D + L, HZ], [X, D + L, HZ + 4], [X, D, HZ - L]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, a, i, z0, z1)); return s; };
  // the chimney, then the canopy in front of it
  box(22, 0, 44, 18, 2, 1, Z1, 96);
  box(0, 0, X, D, 4, 1.6, Z0, Z1);
  // the fan grille on the canopy top
  mk("path", { d: poly(rrect(6, 22, X - 6, D - 5, 2, 4).map((q) => P(q.u, q.v, Z1))), class: "nf lo" }, g);
  for (let x = 14; x < X - 8; x += 8) mk("path", { d: `M${P(x, 24, Z1)}L${P(x, D - 7, Z1)}`, class: "nf lo" }, g);
  // the visor, hinged along the front edge
  const vis = solid(g);
  vis.sil.classList.add("hi");
  const vr = rrect(2, 0, X - 2, L, 4, 6), vi = rrect(5, 3, X - 5, L - 6, 2.5, 6);
  const knobs = [mk("path", { class: "nf" }, g), mk("path", { class: "nf" }, g)];
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(toR(a)), s = Math.sin(toR(a));
    const Tf = (x, u, w) => P(x, HY + u * s + w * c, HZ - u * c + w * s);
    const pts = vr.map((q) => Tf(q.u, q.v, 0)).concat(vr.map((q) => Tf(q.u, q.v, T)));
    put(vis, { sil: poly(hull(pts)), crease: poly(vi.map((q) => Tf(q.u, q.v, T))) });
    [X - 18, X - 10].forEach((x, k) => {
      const kp = [];
      for (const dx of [-2.5, 2.5]) for (const du of [L - 4.5, L - 1.5]) for (const w of [T, T + 1.5]) kp.push(Tf(x + dx, du, w));
      knobs[k].setAttribute("d", poly(hull(kp)));
    });
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const mid = P(X / 2, D / 2, 60);
  let on = false;
  function setOn(v) {
    on = v;
    tset(ang, on ? reach : REST, performance.now(), 0);
    read.textContent = on ? "visor up" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => { const v = Math.abs(x - mid[0]) < 140 && Math.abs(y - mid[1]) < 120; if (v !== on) setOn(v); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "rangehood",
  means: "A cooker hood: over it, the glass visor on the canopy's front edge tilts up on its hinge to open the extractor.",
  rules: [1, 3, 5, 8],
  range: [60, 90, 110],
  tour: [[205, 175], [200, 140], [241, 216], null],
  mount,
});

stovetop.code:
/**
 * Gas hob: a steel plate with four burners and a row of knobs along the
 * front. At rest one burner burns low, bright. The pointer picks a burner by
 * where it stands on the plate: its knob turns and its flame ring leaps up,
 * while the rest go out. The slider is how tall the flame burns.
 */
const { Cam, circ, fit, facing, poly, prism, proj, rings, tset, tval, tdone, tween, unproj, disposer, mk, pointer, put, register, solid } = HL;

const X = 76, Y = 70, PZ = 4, FAV = 1, LOW = 5, NT = 12;
const BUR = [[20, 18, 10], [56, 16, 8], [20, 44, 8], [56, 42, 10]];
const disc = (x, y, r, n = 36) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tall = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[0, 0, 0], [X, Y, 0], [X, 0, 0], [0, Y, 0], [20, 18, 38], [56, 16, 38]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(0, 0, X, Y, 6, 2);
  put(solid(g), prism(P, front, pr, pi, 0, PZ));
  const order = BUR.map((b, k) => k).sort((a, b) => BUR[a][0] + BUR[a][1] - BUR[b][0] - BUR[b][1]);
  const bs = [];
  for (const k of order) {
    const [x, y, r] = BUR[k];
    put(solid(g), prism(P, front, disc(x, y, r + 2), disc(x, y, r), PZ, PZ + 1.5));
    const back = mk("g", {}, g), cap = solid(g), fr = mk("g", {}, g);
    put(cap, prism(P, front, disc(x, y, r * 0.65), disc(x, y, r * 0.65 - 1.2), PZ + 1.5, PZ + 4));
    const tongues = [];
    for (let i = 0; i < NT; i++) {
      const t = (i / NT) * 2 * Math.PI, isBack = Math.cos(t) + Math.sin(t) < 0;
      tongues.push({ t, el: mk("path", { class: "nf" }, isBack ? back : fr) });
    }
    bs[k] = { x, y, r, cap, tongues, h: tween(k === FAV ? LOW : 0), last: NaN };
  }
  // the knobs along the front edge
  const knobs = [0, 1, 2, 3].map((k) => {
    const x = 13 + k * 17, y = Y - 8, s = solid(g);
    put(s, prism(P, front, disc(x, y, 4.2, 28), disc(x, y, 3, 28), PZ, PZ + 3.5));
    const mark = mk("path", { class: "nf" }, g);
    return { x, y, mark, a: tween(k === FAV ? 0.6 : 0), last: NaN };
  });
  function draw(b, h) {
    if (h === b.last) return;
    b.last = h;
    const r0 = b.r * 0.65, z0 = PZ + 3;
    for (const tg of b.tongues) {
      if (h < 0.3) { tg.el.setAttribute("d", ""); continue; }
      const at = (rr, ang, z) => P(b.x + rr * Math.cos(ang), b.y + rr * Math.sin(ang), z);
      tg.el.setAttribute("d", poly([at(r0, tg.t - 0.2, z0), at(r0 + 1.2 + h * 0.18, tg.t - 0.08, z0 + h * 0.55), at(r0 + 1 + h * 0.3, tg.t, z0 + h), at(r0 + 1.2 + h * 0.18, tg.t + 0.08, z0 + h * 0.55), at(r0, tg.t + 0.2, z0)]));
    }
  }
  function drawKnob(kn, a) {
    if (a === kn.last) return;
    kn.last = a;
    const ang = -2.4 + a * 2.2, z = PZ + 3.5;
    kn.mark.setAttribute("d", `M${P(kn.x, kn.y, z)}L${P(kn.x + 3.2 * Math.cos(ang), kn.y + 3.2 * Math.sin(ang), z)}`);
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    bs.forEach((b) => { draw(b, tval(b.h, now)); if (!tdone(b.h, now)) m = true; });
    knobs.forEach((kn) => { drawKnob(kn, tval(kn.a, now)); if (!tdone(kn.a, now)) m = true; });
    return m;
  });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, PZ);
    let best = -1, bd = 22;
    BUR.forEach(([x, y], k) => { const d = Math.hypot(wx - x, wy - y); if (d < bd) { bd = d; best = k; } });
    return best;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now(), sel = a < 0 ? FAV : a;
    bs.forEach((b, k) => {
      tset(b.h, k !== sel ? 0 : a < 0 ? LOW : tall, now, 0);
      b.cap.sil.classList.toggle("hi", k === sel);
      b.tongues.forEach((tg) => tg.el.classList.toggle("hi", k === sel));
    });
    knobs.forEach((kn, k) => tset(kn.a, k === sel ? (a < 0 ? 0.6 : 0.6 + tall / 30) : 0, now, 0));
    read.textContent = a < 0 ? "rest" : "burner " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tall = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "stovetop",
  means: "A gas hob: the burner under the pointer lights, its knob turns and its ring of flame leaps up while the others go out.",
  rules: [1, 3, 4, 5],
  range: [10, 20, 28],
  tour: [[147, 174], [272, 182], [221, 208], null],
  mount,
});

mopedseat.code:
/**
 * Scooter seat: a step-through moped with its long seat hinged at the front
 * edge. At rest the seat sits a little ajar, bright. Over the moped the seat
 * swings up on its hinge to show the helmet in the storage well under it.
 * The slider is how far the seat opens.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, rrect, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const HX = 38, HZ = 32, L = 36, W = 10, T = 4, REST = 12;
const toR = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, -17, 0], [86, 17, 0], [0, 0, 32], [HX, -W, HZ + L], [HX, W, HZ + L], [70, 0, 52], [86, 0, 20]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, a, i, z0, z1)); };
  function wheel(cx) {
    const ring = circ(10, 28), hub = circ(4.5, 20), s = solid(g);
    const pts = [-2.5, 2.5].flatMap((y) => ring.map((q) => P(cx + q.u, y, 10 + q.v)));
    put(s, { sil: poly(hull(pts)), crease: poly(hub.map((q) => P(cx + q.u, 2.5, 10 + q.v))) });
  }
  wheel(14);
  box(0, -W, 42, W, 7, 1.6, 14, HZ);
  // the storage well and the helmet resting in it
  mk("path", { d: poly(rrect(4, -7, 34, 7, 5, 6).map((q) => P(q.u, q.v, HZ))), class: "nf lo" }, g);
  const dome = [];
  for (let i = 0; i <= 5; i++) { const t = (i / 5) * (Math.PI / 2); dome.push(...circ(7 * Math.cos(t), 20).map((q) => P(20 + q.u, q.v, HZ + 3.5 * Math.sin(t)))); }
  mk("path", { d: poly(hull(dome)), class: "nf" }, g);
  // the seat
  const seat = solid(g);
  seat.sil.classList.add("hi");
  const sr = rrect(0, -W, L, W, 6, 6), si = rrect(2, -W + 2, L - 2, W - 2, 4.5, 6);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(toR(a)), s = Math.sin(toR(a));
    const Tf = (u, v, w) => P(HX - u * c + w * s, v, HZ + u * s + w * c);
    const pts = sr.map((q) => Tf(q.u, q.v, 0)).concat(sr.map((q) => Tf(q.u, q.v, T)));
    put(seat, { sil: poly(hull(pts)), crease: poly(si.map((q) => Tf(q.u, q.v, T))) });
  }
  box(40, -9, 66, 9, 3, 1.2, 10, 14);
  box(62, -9, 70, 9, 3, 1.2, 10, 48);
  wheel(76);
  box(64, -17, 68, 17, 2, 0.8, 48, 51);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const mid = P(40, 0, 20);
  let on = false;
  function setOn(v) {
    on = v;
    tset(ang, on ? reach : REST, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => { const v = Math.abs(x - mid[0]) < 140 && Math.abs(y - mid[1]) < 160; if (v !== on) setOn(v); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "mopedseat",
  means: "A step-through moped: over it, the long seat swings up on its front hinge to show the helmet stowed underneath.",
  rules: [1, 3, 5, 8],
  range: [40, 75, 100],
  tour: [[151, 115], [189, 60], [240, 200], null],
  mount,
});

truckramp.code:
/**
 * Van loading ramp: a box van with a ramp hinged at the sill of its rear
 * opening. At rest the ramp leans just off the doorway, bright. Over the
 * van it folds down on its hinge toward the ground. The slider is how far
 * it lowers.
 */
const { Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, rrect, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const RX = 70, HZ = 10, L = 40, W = 15, T = 2.4, REST = 16;
const toR = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-20, -22, 0], [RX, 26, 0], [-20, 22, 0], [RX, -22, 56], [0, 22, 56], [RX + L, 0, 0], [RX, 0, HZ + L + 2]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, a, i, z0, z1)); };
  box(-20, -20, 4, 20, 8, 1.6, 8, 36);
  box(0, -22, RX, 22, 5, 1.6, 8, 56);
  // the doorway on the rear face
  mk("path", { d: poly(rrect(HZ + 1, -W - 1, 52, W + 1, 3, 6).map((q) => P(RX, q.v, q.u))), class: "nf lo" }, g);
  function wheel(cx) {
    const ring = circ(9, 28), hub = circ(4, 20), s = solid(g);
    const pts = [21, 25].flatMap((y) => ring.map((q) => P(cx + q.u, y, 9 + q.v)));
    put(s, { sil: poly(hull(pts)), crease: poly(hub.map((q) => P(cx + q.u, 25, 9 + q.v))) });
  }
  wheel(-6);
  wheel(54);
  const ramp = solid(g), treads = mk("path", { class: "nf lo" }, g);
  ramp.sil.classList.add("hi");
  const rr = rrect(0, -W, L, W, 3, 6), ri = rrect(1.5, -W + 1.5, L - 1.5, W - 1.5, 2, 6);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const e = toR(90 - a), c = Math.cos(e), s = Math.sin(e);
    const Tf = (u, v, w) => P(RX + u * c - w * s, v, Math.max(0, HZ + u * s) + w * c);
    const pts = rr.map((q) => Tf(q.u, q.v, 0)).concat(rr.map((q) => Tf(q.u, q.v, T)));
    put(ramp, { sil: poly(hull(pts)), crease: poly(ri.map((q) => Tf(q.u, q.v, T))) });
    let d = "";
    for (let k = 1; k <= 5; k++) { const u = (k * L) / 6; d += "M" + Tf(u, -W + 3, T).join(",") + "L" + Tf(u, W - 3, T).join(","); }
    treads.setAttribute("d", d);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const mid = P(40, 0, 24);
  let on = false;
  function setOn(v) {
    on = v;
    tset(ang, on ? clamp(reach, REST, 104) : REST, performance.now(), 0);
    read.textContent = on ? "down" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => { const v = Math.abs(x - mid[0]) < 160 && Math.abs(y - mid[1]) < 150; if (v !== on) setOn(v); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "truckramp",
