  rules: [1, 3, 5, 8],
  range: [50, 100, 104],
  tour: [[259, 125], [242, 173], [180, 120], null],
  mount,
});

firepit.code:
/**
 * Fire pit: a wide steel bowl on a pedestal with a domed mesh spark screen
 * resting on its rim. At rest the screen sits a little tipped, bright. Over
 * the pit it tilts up on its back edge to show the logs inside. The slider
 * is how far the screen opens.
 */
const { Cam, circ, fit, hull, open, poly, proj, ringAt, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const RZ = 26, BR = 28, DR = 27, DH = 16, REST = 10;
const toR = (d) => (d * Math.PI) / 180;
const VX = Math.cos(toR(30)) * Math.SQRT1_2, VZ = 0.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.3);
  fit(C, [[-30, -30, 0], [30, 30, 0], [-30, 30, RZ], [30, -30, RZ], [-58, 0, RZ + 2 * DR], [-50, -20, 70], [10, 0, RZ + DR + 8]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const cyl = (r0, r1, z0, z1, inner) => {
    const s = solid(g);
    put(s, { sil: poly(hull(ringAt(P, circ(r0, 40), z0).concat(ringAt(P, circ(r1, 40), z1)))), crease: inner ? poly(ringAt(P, circ(r1 - 2, 40), z1)) : "" });
  };
  cyl(20, 20, 0, 2, false);
  cyl(6, 6, 2, 14, false);
  cyl(13, BR, 14, RZ, true);
  // the logs on the coals
  const mound = [];
  for (const [r, z] of [[18, 0], [12, 3], [5, 5]]) mound.push(...ringAt(P, circ(r, 24), RZ - 3 + z));
  mk("path", { d: poly(hull(mound)), class: "nf lo" }, g);
  for (const [a, b] of [[[-10, -6], [9, 5]], [[-8, 7], [8, -8]]]) mk("path", { d: open([P(a[0], a[1], RZ + 3), P(b[0], b[1], RZ + 3)]), class: "nf" }, g);
  // the spark screen
  const lid = solid(g), mesh = mk("path", { class: "nf lo" }, g), loop = mk("path", { class: "nf" }, g);
  lid.sil.classList.add("hi");
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(toR(a)), s = Math.sin(toR(a));
    const rot = (x, y, z) => { const dx = x + DR, dz = z; return [-DR + dx * c - dz * s, y, RZ + dx * s + dz * c]; };
    const pt = (x, y, z) => P(...rot(x, y, z));
    const seen = (x, y, z) => { const nx = x / (DR * DR), nz = z / (DH * DH), y2 = y / (DR * DR); return (nx * c - nz * s) * VX + y2 * VX + (nx * s + nz * c) * VZ > 0; };
    const lats = [], all = [];
    for (let i = 0; i <= 6; i++) {
      const t = (i / 6) * (Math.PI / 2), ring = circ(DR * Math.cos(t), 40).map((q) => [q.u, q.v, DH * Math.sin(t)]);
      all.push(...ring.map((p) => pt(...p)));
      if (i === 2 || i === 4) lats.push(ring);
    }
    put(lid, { sil: poly(hull(all)), crease: "" });
    let d = "";
    const strand = (ps) => { let on = false; for (const p of ps) { const v = a > 50 || seen(...p), q = pt(...p).join(","); d += v ? (on ? "L" : "M") + q : ""; on = v; } };
    lats.forEach((ring) => strand(ring.concat([ring[0]])));
    strand(circ(DR, 40).map((q) => [q.u, q.v, 0.01]).concat([[DR, 0, 0.01]]));
    for (let m = 0; m < 12; m++) {
      const th = (m / 12) * Math.PI * 2, ps = [];
      for (let i = 0; i <= 8; i++) { const t = (i / 8) * (Math.PI / 2); ps.push([DR * Math.cos(t) * Math.cos(th), DR * Math.cos(t) * Math.sin(th), DH * Math.sin(t)]); }
      strand(ps);
    }
    mesh.setAttribute("d", d);
    loop.setAttribute("d", poly(circ(4, 16).map((q) => pt(q.u, 0, DH + 4 + q.v))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const mid = P(0, 0, RZ);
  let on = false;
  function setOn(v) {
    on = v;
    tset(ang, on ? reach : REST, performance.now(), 0);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => { const v = Math.abs(x - mid[0]) < 140 && Math.abs(y - mid[1]) < 150; if (v !== on) setOn(v); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "firepit",
  means: "A steel fire pit bowl with a domed mesh spark screen: over it, the screen tilts up on its back edge to show the logs.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 105],
  tour: [[200, 159], [135, 172], [247, 228], null],
  mount,
});

scissorlift.code:
/**
 * Scissor lift: a wheeled chassis whose crossed arms push a railed deck up.
 * Over the lift the deck rises to its top on the 700ms ease; leaving lowers
 * it to a part-raised rest, the deck bright. The slider is how high it goes.
 *
 * The pattern: one part answering a discrete choice (tween).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, clamp, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 30, BASE = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-46, -20, 0], [46, 20, 0], [46, -20, 0], [-46, 20, 0], [-46, -20, BASE + 75 + 15], [46, 20, BASE + 75 + 15]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-40, -17, 40, 17, 5, 1.6);
  put(solid(g), prism(P, front, cr, ci, 5, BASE));
  const wheels = [[-28, 17], [28, 17]].map(([x, y]) => {
    const pts = [];
    for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push(P(x + 5.5 * Math.cos(a), y + 0.5, 6 + 5.5 * Math.sin(a))); }
    return mk("path", { d: poly(pts) }, g);
  });
  const back = mk("g", {}, g), fr = mk("g", {}, g);
  const N = 3;
  const armsB = [], armsF = [];
  for (let i = 0; i < N * 2; i++) { armsB.push(mk("path", { class: "lo" }, back)); armsF.push(mk("path", {}, fr)); }
  const deck = solid(g);
  deck.sil.classList.add("hi");
  const rail = mk("path", { class: "nf" }, g);
  const [dr, di] = rings(-46, -20, 46, 20, 3, 1.4);
  const L = 34;

  function strip(a, b, y) {
    const t = 1.6;
    return poly([P(a[0], y, a[1] - t), P(b[0], y, b[1] - t), P(b[0], y, b[1] + t), P(a[0], y, a[1] + t)]);
  }
  const lift = tween(REST);
  let last = NaN;
  function draw(H) {
    if (H === last) return;
    last = H;
    const h = H / N;
    for (let s = 0; s < N; s++) {
      const z0 = BASE + s * h, z1 = z0 + h;
      const A = [[-L, z0], [L, z1]], Bb = [[L, z0], [-L, z1]];
      armsB[2 * s].setAttribute("d", strip(A[0], A[1], -14));
      armsB[2 * s + 1].setAttribute("d", strip(Bb[0], Bb[1], -14));
      armsF[2 * s].setAttribute("d", strip(A[0], A[1], 14));
      armsF[2 * s + 1].setAttribute("d", strip(Bb[0], Bb[1], 14));
    }
    const zt = BASE + H;
    put(deck, prism(P, front, dr, di, zt, zt + 4));
    const zr = zt + 15, c = [[-44, -18], [44, -18], [44, 18], [-44, 18]];
    let d = "M" + c.map(([x, y]) => P(x, y, zr).join(",")).join("L") + "Z";
    for (const [x, y] of c) d += "M" + P(x, y, zt + 4).join(",") + "L" + P(x, y, zr).join(",");
    d += "M" + P(-44, 18, zt + 10).join(",") + "L" + P(44, 18, zt + 10).join(",");
    rail.setAttribute("d", d);
  }

  const B = register(stage, (dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);

  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 115 || sy < 20 || sy > 300) return leave();
    tset(lift, top, performance.now(), 0);
    read.textContent = "up " + Math.round(top);
    B.wake();
  }
  function leave() { tset(lift, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 40, 75); }, destroy: bag.dispose };
}

hairline({
  name: "scissorlift",
  means: "A scissor lift: over it the crossed arms unfold and push the railed deck up; the slider sets how high it climbs.",
  rules: [3, 5, 8],
  range: [40, 60, 75],
  tour: [[200, 181], [200, 250], [175, 120], null],
  mount,
});

cherrypicker.code:
/**
 * Cherry picker: a wheeled base, a turret and a long boom with a bucket on
 * its end. Over the machine the boom swings up on the 700ms ease and the
 * bucket rides it, kept level; leaving lowers it to a low reach, the bucket
 * bright. The slider is the boom's top angle.
 *
 * The pattern: one part answering a discrete choice (tween).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, clamp, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 34, LEN = 70, PX = -24, PZ = 26;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.65);
  const end = (a) => [PX + LEN * Math.cos(rad(a)), PZ + LEN * Math.sin(rad(a))];
  const pts = [[-42, -18, 0], [42, 18, 0], [42, -18, 0], [-42, 18, 0]];
  for (const a of [REST, 75]) { const [ex, ez] = end(a); pts.push([ex - 9, -9, ez - 18], [ex + 9, 9, ez + 6]); }
  fit(C, pts, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [cr, ci] = rings(-40, -16, 40, 16, 5, 1.6);
  put(solid(g), prism(P, front, cr, ci, 5, 15));
  for (const x of [-26, 26]) {
    const w = [];
    for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; w.push(P(x + 6 * Math.cos(a), 16.5, 6 + 6 * Math.sin(a))); }
    mk("path", { d: poly(w) }, g);
  }
  const [tr, ti] = rings(PX - 9, -9, PX + 9, 9, 6, 1.4);
  put(solid(g), prism(P, front, tr, ti, 15, PZ));
  const boom = mk("path", {}, g), fly = mk("path", { class: "lo nf" }, g);
  const hinge = mk("circle", { class: "dot m", r: 2.2 }, g);
  const bucket = solid(g);
  bucket.sil.classList.add("hi");
  const [br, bi] = rings(-8, -8, 8, 8, 2.5, 1.2);
  const mv = (ring, x) => ring.map((q) => ({ ...q, u: q.u + x }));

  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const [ex, ez] = end(a), c = Math.cos(rad(a)), s = Math.sin(rad(a)), t = 3;
    const q = (x, z) => P(x, 0, z);
    boom.setAttribute("d", poly([q(PX - s * t, PZ + c * t), q(ex - s * t, ez + c * t), q(ex + s * t, ez - c * t), q(PX + s * t, PZ - c * t)]));
    const m = 0.55;
    fly.setAttribute("d", "M" + q(PX + LEN * m * c, PZ + LEN * m * s).join(",") + "L" + q(ex, ez).join(","));
    const [hx, hy] = P(PX, 0, PZ);
    hinge.setAttribute("cx", hx); hinge.setAttribute("cy", hy);
    put(bucket, prism(P, front, mv(br, ex), mv(bi, ex), ez - 16, ez + 2));
  }

  const B = register(stage, (dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 130 || sy < 15 || sy > 305) return leave();
    tset(ang, top, performance.now(), 0);
    read.textContent = "boom " + Math.round(top) + "°";
    B.wake();
  }
  function leave() { tset(ang, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 52, 75); }, destroy: bag.dispose };
}

hairline({
  name: "cherrypicker",
  means: "A cherry picker: over it the long boom swings up and lifts the bucket; the slider sets the boom's top angle.",
  rules: [3, 5, 8],
  range: [52, 64, 75],
  tour: [[264, 129], [200, 200], [140, 175], null],
  mount,
});

airpurifier.code:
/**
 * Air purifier: a tall rounded tower with a round outlet grille on top and a
 * front panel hinged at its foot. The pointer over the purifier swings the
 * panel down and out, showing the pleated filter behind it; leaving closes
 * it. At rest the panel stands a little ajar, bright. The slider is how far
 * the panel opens.
 */
const {
  Cam, circ, fit, hull, open, poly, proj, rad, rings, clamp, seg, tset, tval, tdone, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = 30.5, H0 = 8, REST = 7, V = [0.61, 0.61, 0.5];
const hinge = (a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return ([u, v, w]) => [X0 + w * c + v * s, u, H0 - w * s + v * c]; };
function tsolid(P, [ring, inner], z0, z1, T) {
  const at = (z) => ring.map((q) => P(...T([q.u, q.v, z])));
  const a = T([0, 0, z0]), b = T([0, 0, z1]);
  const up = (b[0] - a[0]) * V[0] + (b[1] - a[1]) * V[1] + (b[2] - a[2]) * V[2] >= 0;
  return { sil: poly(hull(at(z0).concat(at(z1)))), crease: poly(inner.map((q) => P(...T([q.u, q.v, up ? z1 : z0])))), up };
}
const disc = (x, y, r) => circ(r, 32).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const ID = (p) => p;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.5);
  const ext = [[0, 0, 0], [30, 44, 0], [0, 44, 0], [30, 0, 0], [0, 0, 92], [30, 44, 92]];
  for (const u of [3, 41]) for (const v of [0, 78]) ext.push(hinge(80)([u, v, 3]));
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  put(solid(g), tsolid(P, rings(0, 0, 30, 44, 7, 2), 0, 92, ID));
  mk("path", { d: poly(disc(15, 22, 11).map((q) => P(q.u, q.v, 92))), class: "nf lo" }, g);
  mk("path", { d: poly(disc(15, 22, 6).map((q) => P(q.u, q.v, 92))), class: "nf lo" }, g);
  let d = "";
  for (let y = 7; y <= 37; y += 3) d += seg(P(30, y, 12), P(30, y, 80));
  mk("path", { d: poly([P(30, 4, 10), P(30, 40, 10), P(30, 40, 82), P(30, 4, 82)]), class: "nf lo" }, g);
  mk("path", { d, class: "nf lo" }, g);

  const panel = solid(g), slots = mk("path", { class: "nf lo" }, g);
  panel.sil.classList.add("hi");
  const ring = rings(3, 0, 41, 78, 6, 2);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.01) return;
    last = a;
    const T = hinge(a), p = tsolid(P, ring, 0, 3, T);
    put(panel, p);
    let s = "";
    if (p.up) for (let v = 52; v <= 68; v += 4) s += seg(P(...T([10, v, 3])), P(...T([34, v, 3])));
    slots.setAttribute("d", s);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, on ? max : REST, performance.now(), 0);
    read.textContent = on ? Math.round(max) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    setOn(clamp(x, -6, 90) === x && clamp(y, -6, 50) === y);
  }
  bag.add(pointer(stage, { move, leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "airpurifier",
  means: "A tower air purifier: the pointer swings its front panel down on a foot hinge to show the pleated filter; leaving closes it.",
  rules: [1, 3, 5, 8],
  range: [30, 60, 80],
  tour: [[134, 253], [160, 268], [146, 222], null],
  mount,
});

heater2.code:
/**
 * Oil heater: an oil-filled column heater, a bank of rounded fins on two
 * castor feet, a control box at one end with a round dial on top. The
 * pointer over the heater tips it back onto its rear castors, as a hand
 * does to wheel it away; leaving sets it down. At rest the dial is bright.
 * The slider is how far it tips.
 */
const {
  Cam, circ, fit, hull, poly, proj, rad, rings, clamp, tset, tval, tdone, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const Y0 = -10, REST = 4, N = 7, V = [0.61, 0.61, 0.5];
const rot = (a) => { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); return ([x, y, z]) => [x, Y0 + (y - Y0) * c - z * s, (y - Y0) * s + z * c]; };
function tsolid(P, [ring, inner], z0, z1, T) {
  const at = (z) => ring.map((q) => P(...T([q.u, q.v, z])));
  const a = T([0, 0, z0]), b = T([0, 0, z1]);
  const up = (b[0] - a[0]) * V[0] + (b[1] - a[1]) * V[1] + (b[2] - a[2]) * V[2] >= 0;
  return { sil: poly(hull(at(z0).concat(at(z1)))), crease: poly(inner.map((q) => P(...T([q.u, q.v, up ? z1 : z0])))) };
}
const disc = (x, y, r) => circ(r, 28).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.15);
  const ext = [];
  for (const a of [0, 30]) for (const x of [0, 82]) for (const y of [Y0, 46]) for (const z of [0, 78]) ext.push(rot(a)([x, y, z]));
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const parts = [];
  const add = (r, z0, z1, hi) => { const s = solid(g); if (hi) s.sil.classList.add("hi"); parts.push({ s, r, z0, z1 }); };
  add(rings(6, Y0, 12, 46, 3, 1), 0, 5);
  add(rings(58, Y0, 64, 46, 3, 1), 0, 5);
  add(rings(2, 14, 80, 22, 3, 1), 5, 10);
  for (let i = 0; i < N; i++) add(rings(i * 10, 0, i * 10 + 7, 36, 3.5, 1), 9, 70 - (i % 2) * 0);
  add(rings(70, 4, 82, 32, 4, 1.2), 46, 72);
  add([disc(76, 18, 5), disc(76, 18, 3.5)], 72, 77, true);

  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.01) return;
    last = a;
    const T = rot(a);
    for (const p of parts) put(p.s, tsolid(P, p.r, p.z0, p.z1, T));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(ang, on ? max : REST, performance.now(), 0);
    read.textContent = on ? Math.round(max) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    setOn(clamp(x, -8, 90) === x && clamp(y, Y0 - 6, 52) === y);
  }
  bag.add(pointer(stage, { move, leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

