rowboat.code:
/**
 * Rowing boat: a clinker dinghy with a seat across it and a pair of oars
 * in their rowlocks. The pointer's place along the boat is the stroke: the
 * oars sweep from catch to finish, blades dipping, and the boat surges on.
 * At rest the oars hang mid-stroke, bright. The slider is the sweep.
 *
 * The pattern: a continuous input driving one mechanism (a spring).
 */
const {
  Cam, fit, hull, poly, proj, clamp, lerp, rad, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const L = 120, B = 40, H = 13, OUT = 64, IN = 16, REST = 0.35;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-14, -B / 2 - OUT, 0], [L + 14, B / 2 + OUT, 0], [L / 2, 0, H + 12], [-14, B / 2 + OUT, 0], [L + 14, -B / 2 - OUT, 0]], 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const half = (u) => (B / 2) * Math.pow(Math.max(0, Math.sin((Math.PI * u) / L)), 0.55) * (u > L * 0.75 ? 1 : 1);
  const ring = (dx, z, k) => { const a = []; for (let i = 0; i <= 30; i++) { const u = (i / 30) * L; a.push(P(u + dx, half(u) * k, z)); } for (let i = 30; i >= 0; i--) { const u = (i / 30) * L; a.push(P(u + dx, -half(u) * k, z)); } return a; };
  const farOar = mk("path", { class: "sil hi" }, g);
  const body = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf" }, g), inner = mk("path", { class: "nf lo" }, g), seat = mk("path", {}, g);
  const nearOar = mk("path", { class: "sil hi" }, g);
  const sp = spring(REST, { k: 60, c: 14 });
  let last = NaN;
  function oar(side, phi, dip, dx) {
    const ox = L / 2 + dx, oy = side * half(L / 2), dxs = Math.sin(rad(phi)), dys = Math.cos(rad(phi));
    const at = (r, w, z) => P(ox - r * dxs + w * dys, oy + side * r * dys + w * dxs * side * -1, z);
    const zt = (r) => H + 2 - (r / OUT) * dip;
    return poly([at(-IN, -1.2, H + 4), at(OUT - 16, -1.2, zt(OUT - 16)), at(OUT - 16, -4, zt(OUT - 16)), at(OUT, -4.5, zt(OUT)), at(OUT, 4.5, zt(OUT)), at(OUT - 16, 4, zt(OUT - 16)), at(OUT - 16, 1.2, zt(OUT - 16)), at(-IN, 1.2, H + 4)]);
  }
  function draw(t) {
    if (t === last) return;
    last = t;
    const phi = lerp(-amp, amp, t), dx = lerp(-8, 10, t), dip = lerp(4, 16, Math.sin(Math.PI * t));
    body.setAttribute("d", poly(hull(ring(dx, 0, 0.55).concat(ring(dx, H, 1)))));
    rim.setAttribute("d", poly(ring(dx, H, 1)));
    inner.setAttribute("d", poly(ring(dx, H - 1, 0.8)));
    seat.setAttribute("d", poly([P(L / 2 + 10 + dx, -half(L / 2) * 0.8, H - 1), P(L / 2 + 22 + dx, -half(L / 2) * 0.8, H - 1), P(L / 2 + 22 + dx, half(L / 2) * 0.8, H - 1), P(L / 2 + 10 + dx, half(L / 2) * 0.8, H - 1)]));
    farOar.setAttribute("d", oar(-1, phi, dip, dx));
    nearOar.setAttribute("d", oar(1, phi, dip, dx));
  }
  const Bk = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(Bk.unregister);
  const x0 = P(0, 0, H)[0] - 40, x1 = P(L, 0, H)[0] + 40;
  function aim(t, label) { sp.t = t; read.textContent = label; Bk.wake(); }
  aim(REST, "rest");
  bag.add(pointer(stage, {
    move: ([sx]) => { const t = clamp((sx - x0) / (x1 - x0), 0, 1); aim(t, t < 0.5 ? "catch" : "drive"); },
    leave: () => aim(REST, "rest"),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 10, 50); last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "rowboat",
  means: "A rowing boat: the pointer along it sets the stroke, and the oars sweep from catch to finish as the boat surges on.",
  rules: [1, 3, 5, 8],
  range: [10, 32, 50],
  tour: [[287, 180], [113, 117], [200, 150], null],
  mount,
});

clampbench.code:
/**
 * Folding workbench: a split top of two long jaws, the front one on screws,
 * standing on two crossed pairs of legs. The pointer's nearness unfolds it:
 * the legs scissor wide, the top rises, and the front jaw winds open from
 * the back one. At rest it stands half folded, the front jaw bright. The
 * slider is how far it unfolds.
 *
 * The pattern: one part answering the pointer's nearness (spring).
 */
const {
  Cam, circ, clamp, facing, fit, hull, lerp, poly, prism, proj, ringAt, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 74, L = 46, H0 = 20, H1 = 42, J0 = 1, J1 = 12, REST = 0.15, XS = [8, W - 8];
const disc = (x, y, r, n = 12) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, -32, 0], [W, -32, 0], [0, 50, 0], [W, 50, 0], [0, 0, H1 + 5], [W, 24, H1 + 5]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const backLegs = mk("path", { class: "sil" }, g), frontLegs = mk("path", { class: "sil" }, g);
  const ties = mk("path", { class: "nf lo" }, g);
  const back = solid(g), jaw = solid(g), screws = mk("path", { class: "nf lo" }, g);
  jaw.sil.classList.add("hi");
  const rod = (a, b, r) => poly(hull(ringAt(P, disc(a[0], a[1], r), a[2]).concat(ringAt(P, disc(b[0], b[1], r), b[2]))));

  const sp = spring(REST);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const h = lerp(H0, H1, p), f = Math.sqrt(L * L - h * h) * 0.6, j = lerp(J0, J1, p), mid = 11;
    let bl = "", fl = "", t = "";
    for (const x of XS) {
      bl += rod([x, mid + f, h], [x, mid - f, 0], 1.8);
      fl += rod([x, mid - f, h], [x, mid + f, 0], 1.8);
    }
    t += seg(P(XS[0], mid - f, 1), P(XS[1], mid - f, 1)) + seg(P(XS[0], mid + f, 1), P(XS[1], mid + f, 1));
    backLegs.setAttribute("d", bl);
    frontLegs.setAttribute("d", fl);
    ties.setAttribute("d", t);
    put(back, prism(P, front, rrect(0, 0, W, 10, 2.5, 4), rrect(1.2, 1.2, W - 1.2, 8.8, 1.5, 4), h, h + 6));
    put(jaw, prism(P, front, rrect(0, 10 + j, W, 20 + j, 2.5, 4), rrect(1.2, 11.2 + j, W - 1.2, 18.8 + j, 1.5, 4), h, h + 6));
    screws.setAttribute("d", seg(P(4, 20 + j, h + 3), P(-6, 20 + j, h + 3)) + seg(P(W - 4, 20 + j, h + 3), P(W + 6, 20 + j, h + 3)));
    read.textContent = Math.round(p * 100) + "%";
  }
  draw(sp.x);
  read.textContent = "rest";

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  const c = P(W / 2, 11, 25);
  let here = false, near = 0;
  function aim([sx, sy]) { here = true; near = clamp(1 - Math.hypot(sx - c[0], (sy - c[1]) * 1.6) / 240, 0, 1); sp.t = REST + (reach - REST) * near; B.wake(); }
  function leave() { here = false; sp.t = REST; B.wake(); }
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (here) { sp.t = REST + (reach - REST) * near; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "clampbench",
  means: "A folding workbench: the nearer the pointer, the wider its legs scissor open, the higher its top and the wider its jaw.",
  rules: [3, 5, 8, 9],
  range: [0.4, 1, 1],
  tour: [[186, 138], [145, 91], [244, 188], null],
  mount,
});

changingtable.code:
/**
 * Changingtable: a baby changing unit, a chest of two drawers whose padded
 * changing top folds out on a hinge along its front edge. The pointer's x
 * unfolds the flap from lying on the chest to standing level beyond it. At
 * rest the flap is bright, half lifted. The slider is how far it opens.
 *
 * The pattern: one part turning on a hinge or axis, driven by the pointer's x.
 */
const { Cam, fit, hull, poly, proj, clamp, lerp, rad, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const K = 0.5, CE = Math.sqrt(1 - K * K) / Math.SQRT2;
const depth = (p) => (p[0] + p[1]) * CE + p[2] * K;
const B = (x0, y0, z0, x1, y1, z1, hi) => ({ hi, c: [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]] });
const NB = [[1, 3, 4], [0, 2, 5], [1, 3, 6], [0, 2, 7], [0, 5, 7], [1, 4, 6], [2, 5, 7], [3, 4, 6]];
function rot(b, ax, deg, o) {
  const a = rad(deg), c = Math.cos(a), s = Math.sin(a);
  const f = (p) => { const q = [p[0] - o[0], p[1] - o[1], p[2] - o[2]]; let r;
    if (ax === "z") r = [q[0] * c - q[1] * s, q[0] * s + q[1] * c, q[2]];
    else if (ax === "y") r = [q[0] * c + q[2] * s, q[1], -q[0] * s + q[2] * c];
    else r = [q[0], q[1] * c - q[2] * s, q[1] * s + q[2] * c];
    return [r[0] + o[0], r[1] + o[1], r[2] + o[2]]; };
  if (b.c) b.c = b.c.map(f);
  if (b.pts) { b.pts = b.pts.map(f); b.lines = (b.lines || []).map((l) => l.map(f)); }
  return b;
}
const mv = (b, dx, dy, dz) => { const f = (p) => [p[0] + dx, p[1] + dy, p[2] + dz]; if (b.c) b.c = b.c.map(f); if (b.pts) { b.pts = b.pts.map(f); b.lines = (b.lines || []).map((l) => l.map(f)); } return b; };


function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, K, SCALE);
  const ext = [];
  for (const s of [0, 0.25, 0.5, 0.75, 1]) for (const b of parts(s)) ext.push(...(b.c || b.pts));
  fit(C, ext, 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const pool = [];
  let last = NaN;
  function draw(s) {
    if (s === last) return;
    last = s;
    const ps = parts(s).map((b) => ({ b, d: depth((b.c || b.pts).reduce((a, p) => [a[0] + p[0], a[1] + p[1], a[2] + p[2]], [0, 0, 0]).map((v) => v / (b.c || b.pts).length)) + (b.dz || 0) }));
    ps.sort((a, b) => a.d - b.d);
    ps.forEach(({ b }, i) => {
      if (!pool[i]) pool[i] = solid(g);
      const sd = pool[i];
      g.appendChild(sd.g);
      let crease = "";
      if (b.c) {
        let h = 0; b.c.forEach((p, k) => { if (depth(p) > depth(b.c[h])) h = k; });
        const a = P(...b.c[h]);
        crease = NB[h].map((k) => { const q = P(...b.c[k]); return `M${a[0].toFixed(2)},${a[1].toFixed(2)}L${q[0].toFixed(2)},${q[1].toFixed(2)}`; }).join("");
      } else {
        crease = b.lines.map((l) => "M" + l.map((p) => P(...p).map((v) => v.toFixed(2)).join(",")).join("L")).join("");
      }
      put(sd, { sil: poly(hull((b.c || b.pts).map((p) => P(...p)))), crease });
      sd.sil.classList.toggle("hi", !!b.hi);
    });
    for (let i = ps.length; i < pool.length; i++) put(pool[i], { sil: "", crease: "" });
  }
  const sp = spring(REST);
  const L = register(stage, (dt) => { const m = stepS(sp, dt); draw(clamp(sp.x, -0.05, 1.05)); return m; });
  bag.add(L.unregister);
  draw(REST);
  let here = false;
  const say = () => { read.textContent = here ? LABEL(clamp(sp.t, 0, 1)) : "rest"; };
  say();
  bag.add(pointer(stage, {
    move: ([sx]) => { here = true; sp.t = clamp(lerp(REST, 1, clamp((sx - X0) / 150, 0, 1)) * reach + REST * (1 - reach), 0, 1); say(); L.wake(); },
    leave: () => { here = false; sp.t = REST; say(); L.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}


const SCALE = 3.15, REST = 0.2, X0 = 120;
const LABEL = (s) => Math.round(100 * s) + "%";
function parts(s) {
  const out = [], a = lerp(-178, 0, s);
  out.push(B(0, 0, 0, 36, 30, 36), B(0, 0, 36, 3, 30, 46));
  out.push(B(36, 2, 4, 37.5, 28, 17), B(36, 2, 20, 37.5, 28, 33), B(37.5, 13, 9, 39, 17, 12), B(37.5, 13, 25, 39, 17, 28));
  const flap = [B(36, 0, 36, 69, 30, 41, true), B(37, 0, 41, 68, 4, 45), B(37, 26, 41, 68, 30, 45), B(65, 4, 41, 68, 26, 44)];
  out.push(...flap.map((b) => rot(b, "y", a, [36, 0, 41])));
  return out;
}

hairline({
  name: "changingtable",
  means: "A baby changing unit: the pointer unfolds its padded changing top on the hinge, from lying on the chest to level beyond it.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[168, 126], [157, 212], [257, 187], null],
  mount,
});

roundabout.code:
/**
 * Playground roundabout: a round deck on a low hub, a centre pole and six
 * hand bars that rise from the rim and bend in to the pole. The pointer over
 * the deck spins it: the bright bar swings round towards the pointer on a
 * spring. At rest the deck sits a little turned, one bar bright. The slider is
 * how far the deck turns towards the pointer.
 *
 * The pattern: a continuous aim on one angle; the hit is on the deck's plane,
 * which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, open, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 40, DZ = 8, N = 6, REST = 0.35, FAV = 0;
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.9);
  const ext = [];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; ext.push([R * Math.cos(a), R * Math.sin(a), 0], [R * Math.cos(a), R * Math.sin(a), DZ + 3]); }
  ext.push([0, 0, DZ + 34]);
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(12, 32), circ(10.5, 32), 0, DZ));
  put(solid(g), prism(P, front, circ(R, 64), circ(R - 2.2, 64), DZ, DZ + 3));
  const lines = mk("path", { class: "nf lo" }, g);
  const far = mk("g", {}, g);
  put(solid(g), prism(P, front, circ(3, 20), circ(2.2, 20), DZ + 3, DZ + 30));
  const near = mk("g", {}, g);
  const bars = [];
  for (let k = 0; k < N; k++) bars.push({ k, el: mk("path", { class: "nf sil" }, far), side: far });

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const a0 = sp.x;
    if (Math.abs(a0 - drawn) < 1e-4) return;
    drawn = a0;
    const T = DZ + 3, d = [];
    for (let k = 0; k < N; k++) {
      const a = a0 + (k / N) * Math.PI * 2, c = Math.cos(a), s = Math.sin(a), b = a + Math.PI / N;
      const r1 = R - 3;
      bars[k].el.setAttribute("d", open([P(r1 * c, r1 * s, T), P(r1 * c, r1 * s, T + 13), P(9 * c, 9 * s, T + 24), P(3 * c, 3 * s, T + 24)]));
      const side = c + s > 0 ? near : far;
      if (side !== bars[k].side) { side.appendChild(bars[k].el); bars[k].side = side; }
      d.push(open([P(5 * Math.cos(b), 5 * Math.sin(b), T), P((R - 3) * Math.cos(b), (R - 3) * Math.sin(b), T)]));
    }
    lines.setAttribute("d", d.join(""));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let pick = FAV;
    if (over) {
      const pa = Math.atan2(over[1], over[0]);
      sp.t = REST + amt * wrap(pa - REST);
      let bd = Infinity;
      for (let k = 0; k < N; k++) { const dd = Math.abs(wrap(sp.t + (k / N) * Math.PI * 2 - pa)); if (dd < bd) { bd = dd; pick = k; } }
      if (amt > 0.6) pick = FAV;
    } else sp.t = REST;
    bars.forEach((b) => b.el.classList.toggle("hi", b.k === pick));
    read.textContent = over ? "bar " + (pick + 1) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], DZ + 3), r = Math.hypot(x, y);
      over = r > R + 6 || r < 4 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "roundabout",
  means: "A playground roundabout: the deck spins its bright hand bar round towards the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[163, 127], [122, 185], [270, 200], null],
  mount,
});

tetherball.code:
/**
 * Tetherball: a tall pole on a round weighted base, a rope from its top and
 * the ball on the rope. The pointer around the pole swings the ball out
 * towards it: the rope turns to the pointer's side and lifts the ball out on a
 * spring. At rest the ball hangs a little out from the pole, bright. The
 * slider is how far out the ball swings.
 *
 * The pattern: a continuous aim on two numbers (side and swing); the hit is on
 * the ground plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, poly, open, run, ringAt, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const H = 84, L = 50, BR = 8, AZ0 = -0.6, TH0 = 0.7, TH1 = 1.15;
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.8);
  const ext = [[0, 0, H + 3]];
  for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2, r = L * Math.sin(TH1) + BR; ext.push([r * Math.cos(a), r * Math.sin(a), H - L * Math.cos(TH1)], [20 * Math.cos(a), 20 * Math.sin(a), 0]); }
  fit(C, ext, 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, circ(20, 48), circ(18, 48), 0, 5));
  const far = mk("g", {}, g);
  put(solid(g), prism(P, front, circ(1.8, 16), null, 5, H));
  put(solid(g), prism(P, front, circ(2.6, 16), circ(1.8, 16), H, H + 2));
  const near = mk("g", {}, g);
  const ballG = mk("g", {}, far);
  const rope = mk("path", { class: "nf sil" }, ballG);
  const ball = mk("path", { class: "sil hi" }, ballG);
  const seam = mk("path", { class: "nf lo" }, ballG);
  let side = far;

  const az = spring(AZ0), th = spring(TH0);
  let dA = NaN, dT = NaN;
  function draw() {
    if (Math.abs(az.x - dA) < 1e-4 && Math.abs(th.x - dT) < 1e-4) return;
    dA = az.x; dT = th.x;
    const r = L * Math.sin(th.x), c = Math.cos(az.x), s = Math.sin(az.x);
    const bx = r * c, by = r * s, bz = H - L * Math.cos(th.x);
    const top = H - 1, k = (L - BR) / L;
    rope.setAttribute("d", open([P(0, 0, top), P(bx * k, by * k, top + (bz - top) * k)]));
    const ctr = P(bx, by, bz), R = BR * C.S, pts = [];
    for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push([ctr[0] + R * Math.cos(t), ctr[1] + R * Math.sin(t)]); }
    ball.setAttribute("d", poly(pts));
    seam.setAttribute("d", open(ringAt(P, run(disc(bx, by, BR), front), bz)));
    const want = bx + by > 0 ? near : far;
    if (want !== side) { want.appendChild(ballG); side = want; }
  }

  const B = register(stage, (dt) => { const m1 = stepS(az, dt), m2 = stepS(th, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    if (over) {
      az.t = az.t + wrap(Math.atan2(over[1], over[0]) - az.t);
      th.t = TH0 + amt * (TH1 - TH0);
    } else { az.t = az.t + wrap(AZ0 - az.t); th.t = TH0; }
    read.textContent = over ? "out " + Math.round((th.t * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r > 70 || r < 6 ? null : [x, y];
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "tetherball",
  means: "A tetherball pole: the ball on its rope swings out round the pole towards the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.2, 1, 1],
  tour: [[111, 290], [300, 245], [150, 215], null],
  mount,
});

zipline.code:
/**
 * Zip line: a cable strung down from a tall post to a short one, a trolley
 * riding it and a round seat hung from the trolley on two ropes. The pointer
 * along the cable slides the trolley there on a spring, seat and all. At rest
 * the trolley waits near the high end, the seat bright. The slider is how far
 * the trolley rides towards the pointer.
 *
 * The pattern: a continuous aim on one number; the hit is the pointer's screen
 * x against the cable's fixed ends.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, open, spring, stepS, clamp, lerp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = -70, X1 = 70, Z0 = 74, Z1 = 44, DROP = 34, SR = 9, REST = -34, LO = -56, HI = 52;
const cz = (x) => lerp(Z0, Z1, (x - X0) / (X1 - X0));
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[X0 - 8, -8, 0], [X1 + 8, 8, 0], [X0, 0, Z0 + 4], [X1, 0, Z1 + 4], [HI, SR, cz(HI) - DROP - 2], [LO, -SR, cz(LO) - DROP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x, h) => {
    const [r0, r1] = rings(x - 7, -7, x + 7, 7, 3, 1.2);
    put(solid(g), prism(P, front, r0, r1, 0, 3));
    put(solid(g), prism(P, front, disc(x, 0, 2.4, 16), null, 3, h));
    put(solid(g), prism(P, front, disc(x, 0, 3.4, 16), disc(x, 0, 2.4, 16), h, h + 2.5));
  };
  post(X0, Z0 + 1.5);
  mk("path", { class: "nf sil", d: open([P(X0, 0, Z0), P(X1, 0, Z1)]) }, g);
  const rig = mk("g", {}, g);
  const ropes = mk("path", { class: "nf sil" }, rig);
  const seat = solid(rig), trolley = solid(rig);
  seat.sil.classList.add("hi");
  post(X1, Z1 + 1.5);

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const x = sp.x;
    if (Math.abs(x - drawn) < 1e-3) return;
    drawn = x;
    const z = cz(x), sz = z - DROP;
    const [t0, t1] = rings(x - 5, -3, x + 5, 3, 1.6, 0.7);
    put(trolley, prism(P, front, t0, t1, z - 4, z + 1.5));
    put(seat, prism(P, front, disc(x, 0, SR), disc(x, 0, SR - 1.6), sz - 2.2, sz));
    ropes.setAttribute("d", open([P(x - 2, 0, z - 4), P(x - SR + 2, 0, sz)]) + open([P(x + 2, 0, z - 4), P(x + SR - 2, 0, sz)]));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const A = P(X0, 0, Z0), Bp = P(X1, 0, Z1);
  let over = null;
  function retarget() {
    sp.t = over === null ? REST : REST + amt * (over - REST);
    read.textContent = over === null ? "rest" : "ride " + Math.round(((sp.t - LO) / (HI - LO)) * 100) + "%";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const t = (sx - A[0]) / (Bp[0] - A[0]), ly = lerp(A[1], Bp[1], t);
      over = t < -0.1 || t > 1.1 || sy < ly - 30 || sy > ly + 110 ? null : clamp(lerp(X0, X1, t), LO, HI);
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "zipline",
  means: "A zip line between two posts: the trolley and its hanging seat ride along the cable to the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[273, 176], [130, 80], [205, 130], null],
  mount,
});

gumball.code:
/**
 * Gumball machine: a glass globe of gumballs on a squat body, a cap on top and
 * a crank on the body's face. The pointer on the machine turns the crank, and
 * the wheel under the globe stirs the gumballs round on a spring. At rest the
 * crank sits a little turned, bright. The slider is how far the crank turns.
 *
 * The pattern: a continuous aim on one angle; the hit is the machine's rest
 * box on screen.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, poly, open, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const GR = 21, GZ = 54, BALL = 4.6, REST = 0.3, TURN = 2.4;
const BALLS = [];
for (let i = 0; i < 16; i++) { const a = i * 2.4, h = -0.8 + (i / 15) * 1.3, r = 15 * Math.sqrt(1 - h * h * 0.5); BALLS.push([r * Math.cos(a), r * Math.sin(a), GZ + h * 12]); }

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[-16, -16, 0], [16, 16, 0], [0, 0, GZ + GR + 5], [-GR, GR, GZ], [GR, -GR, GZ]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [b0, b1] = rings(-16, -16, 16, 16, 6, 1.8);
  put(solid(g), prism(P, front, b0, b1, 0, 32));
  const ctr = P(0, 0, GZ), R = GR * C.S, gl = [];
  for (let i = 0; i < 48; i++) { const t = (i / 48) * Math.PI * 2; gl.push([ctr[0] + R * Math.cos(t), ctr[1] + R * Math.sin(t)]); }
  mk("path", { class: "sil", d: poly(gl) }, g);
  const balls = mk("g", {}, g);
  const bEls = BALLS.map(() => mk("path", { class: "" }, balls));
  put(solid(g), prism(P, front, circ(10, 32), circ(8.6, 32), 32, 36));
  put(solid(g), prism(P, front, circ(6, 24), circ(4.8, 24), GZ + GR - 1, GZ + GR + 4));
  // the chute and the crank on the +x face
  const chute = [];
  for (let i = 0; i <= 8; i++) { const t = Math.PI + (i / 8) * Math.PI; chute.push(P(16.2, 5 * Math.cos(t), 9 + 5 * Math.sin(t) * -1)); }
  mk("path", { class: "nf lo", d: poly(chute) }, g);
  const hub = [];
  for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; hub.push(P(16.4, 6 * Math.cos(t), 21 + 6 * Math.sin(t))); }
  mk("path", { class: "", d: poly(hub) }, g);
  const crank = mk("path", { class: "nf sil hi" }, g);

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const pts = BALLS.map(([x, y, z], i) => { const c = Math.cos(a), s = Math.sin(a); return { i, x: x * c - y * s, y: x * s + y * c, z }; });
    pts.sort((p, q) => p.x + p.y - (q.x + q.y) - (p.z - q.z) * 0.3);
    pts.forEach((p, j) => {
      const c0 = P(p.x, p.y, p.z), r = BALL * C.S, d = [];
      for (let k = 0; k < 16; k++) { const t = (k / 16) * Math.PI * 2; d.push([c0[0] + r * Math.cos(t), c0[1] + r * Math.sin(t)]); }
      bEls[j].setAttribute("d", poly(d));
    });
    const f = a * 2.5, c = Math.cos(f), s = Math.sin(f);
    crank.setAttribute("d", open([P(17, -11 * c, 21 - 11 * s), P(17, 11 * c, 21 + 11 * s), P(21, 11 * c, 21 + 11 * s)]));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const lo = P(0, 0, 0), hi = P(0, 0, GZ + GR + 4);
  let over = false;
  function retarget() {
    sp.t = over ? REST + amt * TURN : REST;
    read.textContent = over ? "turn " + Math.round((amt * TURN * 180) / Math.PI) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { over = Math.abs(sx - lo[0]) < 85 && sy > hi[1] - 10 && sy < lo[1] + 50; retarget(); },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amt = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "gumball",
  means: "A gumball machine: the pointer turns its crank and the gumballs in the glass globe stir round.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[236, 217], [200, 140], [165, 245], null],
  mount,
});

vandegraaff.code:
/**
 * Van de Graaff generator: a plinth, a belt column and a big round dome, with
 * a small grounding ball on its own stand. The pointer over it raises the
 * telescoping column, lifting the dome high above the plinth on a spring. At
 * rest the dome is bright. The slider is how high the dome rises.
 *
 * The pattern: a single object on a spring (terrain's spring, on a lift).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const CX = 28, CY = 28, R = 22, Z0 = 12, H = 30;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, 0], [56, 0, 0], [56, 56, 0], [0, 56, 0], [CX - R, CY, Z0 + H + 26 + 2 * R], [CX + R, CY, Z0 + H + 26 + 2 * R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 56, 56, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, Z0));
  // the grounding ball, on a thin stand at the right
  put(solid(g), prism(P, front, disc(50, 8, 1.4, 12), disc(50, 8, 0.8, 12), Z0, Z0 + 26));
  const ball = [];
  for (let i = -3; i <= 3; i++) { const t = (i / 3) * (Math.PI / 2); ball.push(...ringAt(P, disc(50, 8, 5 * Math.cos(t), 16), Z0 + 30 + 5 * Math.sin(t))); }
  mk("path", { d: poly(hull(ball)) }, g);
  const sleeve = solid(g);
  put(sleeve, prism(P, front, disc(CX, CY, 10), disc(CX, CY, 8.6), Z0, Z0 + H));
  const col = solid(g), belt = mk("path", { class: "nf lo" }, g);
  const dome = mk("path", { class: "sil hi" }, g), seam = mk("path", { class: "nf lo" }, g);

  let last = NaN;
  function draw(l) {
    if (l === last) return;
    last = l;
    const top = Z0 + H + l;
    put(col, prism(P, front, disc(CX, CY, 7), disc(CX, CY, 5.8), Z0 + H, top + 4));
    belt.setAttribute("d", open([P(CX + 2, CY + 6.7, Z0 + H + 1), P(CX + 2, CY + 6.7, top + 2)]) + open([P(CX + 6.7, CY + 2, Z0 + H + 1), P(CX + 6.7, CY + 2, top + 2)]));
    const zc = top + R - 4, pts = [];
    for (let i = -6; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); pts.push(...ringAt(P, disc(CX, CY, R * Math.cos(t), 36), zc + R * Math.sin(t))); }
    dome.setAttribute("d", poly(hull(pts)));
    seam.setAttribute("d", open(ringAt(P, run(disc(CX, CY, R * 0.96, 48), front), zc - R * 0.28)));
  }

  const sp = spring(4);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(4);

  const c0 = P(CX, CY, 0), cTop = P(CX, CY, Z0 + H + 4 + 2 * R + 4), cNear = P(56, 56, 0);
  let on = false;
  function setOn(a) {
    on = a;
    sp.t = a ? reach : 4;
    read.textContent = a ? "lift" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => Math.abs(sx - c0[0]) < 70 && sy > cTop[1] - 10 && sy < cNear[1] + 6;
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { sp.t = v; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "vandegraaff",
  means: "A Van de Graaff generator: the pointer over it raises the belt column, lifting the big round dome high above the plinth.",
  rules: [1, 3, 5, 8],
  range: [12, 20, 26],
  tour: [[200, 110], [200, 237], [238, 262], null],
  mount,
});

stirrer.code:
/**
 * Magnetic stirrer: a low stir plate with a front knob and a glass beaker of
 * liquid on it, a stir bar lying on the bottom. The pointer over it starts
 * the stirrer: the bar turns and the liquid's surface pulls down into a deep
 * vortex, ring by ring, on a spring. At rest the surface is bright. The
 * slider is how deep the vortex pulls.
 *
 * The pattern: a single object on a spring (terrain's spring, on a depth).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const CX = 30, CY = 28, BR = 22, Z0 = 12, LZ = 46, TOP = 58;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, 0, 0], [60, 0, 0], [60, 56, 0], [0, 56, 0], [CX - BR, CY, TOP], [CX + BR, CY, TOP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(0, 0, 60, 56, 8, 2), 0, Z0));
  const kb = disc(0, 0, 4.5, 20);
  mk("path", { d: poly(hull(kb.map((q) => P(44 + q.u, 56, 6 + q.v)).concat(kb.map((q) => P(44 + q.u, 59, 6 + q.v))))) }, g);
  const glassBack = mk("path", { class: "nf lo" }, g);
  glassBack.setAttribute("d", open(ringAt(P, run(disc(CX, CY, BR), (q) => !front(q)), TOP)));
  const bar = mk("path", { class: "nf" }, g);
  const surf = [0, 1, 2, 3, 4, 5, 6, 7, 8].map((i) => mk("path", { class: i === 0 ? "nf hi" : "nf lo" }, g));
  const glass = mk("path", { class: "sil nf" }, g);
  glass.setAttribute("d", poly(hull(ringAt(P, disc(CX, CY, BR), Z0).concat(ringAt(P, disc(CX, CY, BR), TOP)))));
  mk("path", { d: open(ringAt(P, run(disc(CX, CY, BR), front), TOP)), class: "nf" }, g);

  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const a = d / 3;
    surf.forEach((p, i) => {
      const f = i / 9, r = (BR - 0.8) * (1 - f * 0.7);
      p.setAttribute("d", poly(ringAt(P, disc(CX, CY, r), Math.max(Z0 + 5, LZ - d * Math.pow(f, 0.4) * 1.5))));
    });
    const c = Math.cos(a) * 15, s = Math.sin(a) * 15;
    bar.setAttribute("d", poly(hull([P(CX - c, CY - s, Z0 + 1), P(CX + c, CY + s, Z0 + 1), P(CX - c, CY - s, Z0 + 4), P(CX + c, CY + s, Z0 + 4)])));
  }

  const sp = spring(3);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(3);

  const c0 = P(CX, CY, 0), cTop = P(CX, CY, TOP + 12), cNear = P(60, 56, 0);
  let on = false;
  function setOn(a) {
    on = a;
    sp.t = a ? reach : 3;
    read.textContent = a ? "stir" : "rest";
    B.wake();
  }
  const hit = ([sx, sy]) => Math.abs(sx - c0[0]) < 75 && sy > cTop[1] - 10 && sy < cNear[1] + 6;
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { sp.t = v; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "stirrer",
  means: "A magnetic stirrer with a beaker on it: the pointer starts the stir bar, and the liquid's surface pulls down into a deep vortex.",
  rules: [1, 3, 5, 8],
  range: [18, 26, 30],
  tour: [[200, 115], [200, 186], [203, 250], null],
  mount,
});

lawnmower2.code:
/**
 * Lawn mower: a push mower with a deck, an engine cap, a grass box behind
 * and a long handle. The pointer over it pushes it: the whole mower rolls
 * forward on a spring, the wheels turning as it goes. At rest the deck is
 * bright. The slider is how far one push rolls it.
 *
 * The pattern: a single object on a spring (terrain's spring, on a slide).
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-46, -6, 0], [50 + 46, -6, 0], [50 + 46, 36, 0], [-46, 36, 0], [-44, 15, 56], [96, 15, 22]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const mkWheel = () => ({ s: mk("path", {}, g), h: mk("path", { class: "nf lo" }, g) });
  const wFar = [mkWheel(), mkWheel()];
  const box = solid(g), deck = solid(g), cap = solid(g);
  const handle = mk("path", { class: "nf" }, g), grip = mk("path", { class: "nf" }, g);
  const wNear = [mkWheel(), mkWheel()];
  deck.sil.classList.add("hi");

  function wheel(w, x, y, z, R, t, ang) {
    const a = disc(0, 0, R, 24).map((q) => P(x + q.u, y, z + q.v)), b = disc(0, 0, R, 24).map((q) => P(x + q.u, y + t, z + q.v));
    w.s.setAttribute("d", poly(hull(a.concat(b))));
    const yo = t > 0 ? y + t : y, c = Math.cos(ang) * R * 0.7, s = Math.sin(ang) * R * 0.7;
    w.h.setAttribute("d", seg(P(x - c, yo, z - s), P(x + c, yo, z + s)) + seg(P(x + s, yo, z - c), P(x - s, yo, z + c)));
  }
  let last = NaN;
  function draw(o) {
    if (o === last) return;
    last = o;
    const ang = o / 9;
    wheel(wFar[0], 6 + o, -4, 9, 9, 3, ang); wheel(wFar[1], 38 + o, -4, 7, 7, 3, ang);
    const [br, bi] = rings(-28 + o, 3, 0 + o, 27, 5, 1.6);
    put(box, prism(P, front, br, bi, 10, 30));
    const [dr, di] = rings(0 + o, 0, 46 + o, 30, 9, 2);
    put(deck, prism(P, front, dr, di, 4, 13));
    put(cap, prism(P, front, disc(25 + o, 15, 10), disc(25 + o, 15, 8.4), 13, 21));
    handle.setAttribute("d", seg(P(-2 + o, 5, 15), P(-44 + o, 5, 54)) + seg(P(-2 + o, 25, 15), P(-44 + o, 25, 54)));
    grip.setAttribute("d", poly(hull(ringAt(P, disc(-44 + o, 4, 1.6, 10), 54).concat(ringAt(P, disc(-44 + o, 26, 1.6, 10), 54)))));
    wheel(wNear[0], 6 + o, 30, 9, 9, 3, ang); wheel(wNear[1], 38 + o, 30, 7, 7, 3, ang);
  }

  const sp = spring(0);
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(0);

  let on = false;
  function setOn(a) {
    on = a;
    sp.t = a ? reach : 0;
    read.textContent = a ? "push" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -46 && x < 50 && y > -8 && y < 38;
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(hit(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { sp.t = v; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "lawnmower2",
  means: "A push mower with a grass box and long handle: the pointer over it pushes it, and it rolls forward on turning wheels.",
  rules: [1, 3, 5, 8],
  range: [20, 36, 46],
  tour: [[197, 188], [162, 170], [228, 200], null],
  mount,
});

chainsaw.code:
/**
 * Chainsaw: the engine body with its rear handle, the top handle and the
 * hand guard, and the long bar with its chain. The pointer along the saw is
 * how far the nose kicks up: the whole saw tips back on its rear handle, on a
 * spring. At rest it lies almost flat, the chain bright. The slider is how
 * far it can tip.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rrect, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = -36, REST = 6, AMP = 30, VMAX = 1.4;
const AX = { z: (u, v, w) => [u, v, w], y: (u, v, w) => [u, w, v], x: (u, v, w) => [w, u, v] };
const PARTS = [
  ["z", -36, -3, -20, 3, 4, 12, 3, 1],
  ["z", -22, -10, 12, 10, 0, 20, 6, 1.5],
  ["z", -17, -3, -13, 3, 18, 30, 1.5, 0.6],
  ["z", 2, -3, 6, 3, 18, 30, 1.5, 0.6],
  ["y", -18, 26, 7, 31, -3, 3, 2.4, 0.8],
  ["x", -9, 16, 9, 34, 12, 14, 3, 0.6],
  ["y", 10, 4, 76, 16, -1.5, 1.5, 6, 1],
];

function tilt(deg) {
  const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
  return ([x, y, z]) => [PX + (x - PX) * c - z * s, y, (x - PX) * s + z * c];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.9);
  const box = [];
  for (const d of [0, REST + AMP * VMAX]) for (const x of [-36, 78]) for (const y of [-10, 10]) for (const z of [0, 34]) box.push(tilt(d)([x, y, z]));
  fit(C, box, 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const els = PARTS.map(() => solid(g));
  const chain = mk("path", { class: "nf hi" }, g);
  const sp = spring(REST);
  let drawn = NaN;

  function slab(T, [axis, u0, v0, u1, v1, w0, w1, r, b]) {
    const o = AX[axis], R = rrect(u0, v0, u1, v1, r, 4), I = rrect(u0 + b, v0 + b, u1 - b, v1 - b, Math.max(0.3, r - b), 4);
    const at = (ring, w) => ring.map((q) => P(...T(o(q.u, q.v, w))));
    return { sil: poly(hull(at(R, w0).concat(at(R, w1)))), crease: poly(at(I, w1)) };
  }
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-3) return;
    drawn = sp.x;
    const T = tilt(sp.x);
    PARTS.forEach((p, i) => put(els[i], slab(T, p)));
    chain.setAttribute("d", poly(rrect(8, 2, 78, 18, 8, 6).map((q) => P(...T([q.u, 1.6, q.v])))));
  }
  draw();

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(t) {
    sp.t = t == null ? REST : REST + t * AMP * amp;
    read.textContent = t == null ? "rest" : Math.round(sp.t) + "°";
    B.wake();
  }
  let last = null;
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      last = Math.abs(y) > 45 || x < -60 || x > 100 ? null : clamp((x + 40) / 116, 0, 1);
      aim(last);
    },
    leave: () => { last = null; aim(null); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest";
  return {
    set: (v) => { amp = v; if (last != null) aim(last); },
    destroy: bag.dispose,
  };
}

