  mount,
});

airlinecart.code:
/**
 * Drinks trolley: a half-size airline cart on four casters, standing in the
 * aisle on a runner of carpet. Drawers line its side, doors close its end and
 * a tray rims its top. The pointer is where the crew wants it: the trolley
 * rolls along the aisle to that row on a spring. At rest it stands a little
 * way in, its tray rim bright. The slider is how far down the aisle it goes.
 */
const {
  Cam, circ, clamp, fit, facing, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 40, W = 18, H = 46, RUN = 92, REST = 14;
const disc = (x, y, r, n = 12) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-8, -10, 0], [L + RUN + 8, W + 10, 0], [L + RUN + 8, -10, 0], [-8, W + 10, 0], [0, 0, H + 3], [L + RUN, W, H + 3]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ar, ai] = rings(-8, -10, L + RUN + 8, W + 10, 6, 2);
  put(solid(g), prism(P, front, ar, ai, -2, 0));
  for (let x = 6; x < L + RUN; x += 22) mk("path", { d: seg(P(x, -6, 0), P(x, W + 6, 0)), class: "lo dash" }, g);
  const cart = mk("g", {}, g);
  const wheels = [0, 1, 2, 3].map(() => solid(cart));
  const body = solid(cart), tray = solid(cart);
  const marks = mk("path", { class: "lo nf" }, cart), latch = mk("path", { class: "nf" }, cart);
  const tx = spring(REST);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    [[3, 3], [L - 3, 3], [3, W - 3], [L - 3, W - 3]].forEach(([x, y], k) => {
      put(wheels[k], prism(P, front, disc(o + x, y, 2.6), disc(o + x, y, 1.6), 0, 4));
    });
    const [br, bi] = rings(o, 0, o + L, W, 3, 1.4);
    put(body, prism(P, front, br, bi, 4, H));
    const [tr, ti] = rings(o - 1.5, -1.5, o + L + 1.5, W + 1.5, 3.5, 1.6);
    put(tray, prism(P, front, tr, ti, H, H + 3));
    let d = "";
    for (const z of [14, 24, 34]) d += seg(P(o + 3, W, z), P(o + L - 3, W, z));
    d += seg(P(o + L, W / 2, 8), P(o + L, W / 2, H - 4));
    for (const z of [9, 19, 29, 39]) d += seg(P(o + L / 2 - 4, W, z), P(o + L / 2 + 4, W, z));
    marks.setAttribute("d", d);
    const c = P(o + L, W / 2 + 2.5, H - 10), q = P(o + L, W / 2 + 2.5, H - 16);
    latch.setAttribute("d", poly([[c[0] - 1, c[1]], [c[0] + 1, c[1]], [q[0] + 1, q[1]], [q[0] - 1, q[1]]]));
  }

  const B = register(stage, (dt) => {
    const m = stepS(tx, dt);
    draw(tx.x);
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) {
      tx.t = REST;
      body.sil.classList.remove("hi"); tray.sil.classList.add("hi");
      read.textContent = "rest";
    } else {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      if (wy < -14 || wy > W + 14 || wx < -16 || wx > L + RUN + 16) return aim(null);
      const f = clamp((wx - L / 2) / RUN, 0, 1);
      tx.t = f * RUN * reach;
      body.sil.classList.add("hi"); tray.sil.classList.remove("hi");
      read.textContent = "row " + (10 + Math.round(f * 18));
    }
    B.wake();
  }
  aim(null);
  draw(REST);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "airlinecart",
  means: "An airline drinks trolley in the aisle: it rolls down the aisle to the row under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.3, 0.65, 1],
  tour: [[155, 175], [211, 203], [261, 228], null],
  mount,
});

clockpost.code:
/**
 * Street clock: a round two-faced clock head on a slim post, standing on a
 * plinth. The pointer is a passer-by: the head turns on its collar to face
 * them, and its hands sweep round as it turns. At rest it faces a little
 * left, its minute hand bright. The slider is how far the head turns.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, seg, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 30, T = 9, PZ = 64, HZ = PZ + R + 2, REST = 20;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-12, -12, 0], [12, 12, 0], [-R, R, HZ], [R, -R, HZ], [0, 0, HZ + R], [R * 0.7, R * 0.7, HZ - R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-11, -11, 11, 11, 7, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 6));
  put(solid(g), prism(P, front, circ(5, 24), circ(3.5, 24), 6, 12));
  put(solid(g), prism(P, front, circ(2.6, 20), circ(1.6, 20), 12, PZ));
  put(solid(g), prism(P, front, circ(4.5, 24), circ(3, 24), PZ - 2, PZ + 3));
  const head = solid(g);
  const face = mk("path", { class: "nf lo" }, g), ticks = mk("path", { class: "nf lo" }, g);
  const hour = mk("path", { class: "nf" }, g), minute = mk("path", { class: "nf hi" }, g);
  const yaw = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const side = c + s >= 0 ? 1 : -1;
    const at = (off, r, th) => P(-s * r * Math.cos(th) + c * off, c * r * Math.cos(th) + s * off, HZ + r * Math.sin(th));
    const rim = (off, r, n = 40) => Array.from({ length: n }, (_, i) => at(off, r, (i / n) * Math.PI * 2));
    head.sil.setAttribute("d", poly(hull(rim(T / 2, R).concat(rim(-T / 2, R)))));
    head.cr.setAttribute("d", "");
    const fo = side * T / 2;
    face.setAttribute("d", poly(rim(fo, R - 2.5)));
    let d = "";
    for (let i = 0; i < 12; i++) { const th = (i / 12) * Math.PI * 2; d += seg(at(fo, R - 7, th), at(fo, R - (i % 3 ? 5 : 3.5), th)); }
    ticks.setAttribute("d", d);
    const turn = (a - REST) * 6;
    const mth = rad(90 - turn * side), hth = rad(90 - (300 + turn / 12) * side);
    minute.setAttribute("d", open([at(fo, 0, 0), at(fo, R - 8, mth)]));
    hour.setAttribute("d", open([at(fo, 0, 0), at(fo, R - 14, hth)]));
  }

  const B = register(stage, (dt) => {
    const m = stepS(yaw, dt);
    draw(yaw.x);
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { yaw.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    if (Math.hypot(x, y) > 140) return aim(null);
    const ang = Math.atan2(y, x) * 180 / Math.PI;
    const off = clamp(((ang - 45 + 540) % 360) - 180, -80, 80);
    yaw.t = 45 + off * reach;
    const mins = Math.round(((yaw.t - REST) * 6 / 360) * 60 + 600) % 720;
    read.textContent = (Math.floor(mins / 60) || 12) + ":" + String(mins % 60).padStart(2, "0");
    B.wake();
  }
  aim(null);
  draw(REST);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "clockpost",
  means: "A street clock on a post: its round head turns on its collar to face the pointer, and the hands sweep round as it turns.",
  rules: [1, 3, 5, 8],
  range: [0.35, 0.7, 1],
  tour: [[254, 290], [161, 304], [146, 296], null],
  mount,
});

swingdoor.code:
/**
 * Saloon doors: two short louvred leaves hung between two tall posts under
 * a lintel. The pointer near the doorway pushes both leaves open on a
 * spring, wider the closer it comes. At rest they hang just ajar, the right
 * leaf bright. The slider is how far they can swing.
 *
 * The pattern: a continuous swing, hit on a fixed plane (unproj).
 */
const {
  Cam, clamp, fit, hull, poly, proj, rings, rrect, seg, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, prism, facing, register, solid,
} = HL;

const LW = 30, Z0 = 22, Z1 = 60, PH = 86, REST = 14, ZM = (Z0 + Z1) / 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-LW - 4, -4, 0], [LW + 4, 4, 0], [-LW - 4, 0, PH + 6], [LW + 4, 0, PH + 6], [-LW, LW, Z0], [LW, LW, Z0], [0, LW, Z1]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const add = (a, b, s) => a.map((x, i) => x + b[i] * s);
  function slab(c, U, V, W, a, b, t, r) {
    const pts = [], at = (u, v, z) => P(...add(add(add(c, U, u), V, v), W, z));
    for (const q of rrect(-a, -b, a, b, r, 4)) pts.push(at(q.u, q.v, -t / 2), at(q.u, q.v, t / 2));
    const s = W[0] + W[1] >= 0 ? 1 : -1;
    const inner = rrect(-a + 2.4, -b + 2.4, a - 2.4, b - 2.4, Math.max(1, r - 2), 4).map((q) => at(q.u, q.v, s * t / 2));
    let lv = "";
    for (let v = -b + 8; v < b - 6; v += 4.5) lv += seg(at(-a + 5, v, s * t / 2), at(a - 5, v, s * t / 2));
    return { sil: poly(hull(pts)), cr: poly(inner), lv };
  }
  // sill, far post, lintel
  const [sr, si] = rings(-LW - 6, -5, LW + 6, 5, 3, 1.2);
  put(solid(g), prism(P, front, sr, si, 0, 3));
  const post = (x) => { const [r, i] = rings(x - 3, -3, x + 3, 3, 2, 1); put(solid(g), prism(P, front, r, i, 3, PH)); };
  post(-LW - 2);
  const [lr, li] = rings(-LW - 6, -4, LW + 6, 4, 2.5, 1.2);
  put(solid(g), prism(P, front, lr, li, PH, PH + 6));
  const leaf = () => ({ sil: mk("path", { class: "sil" }, g), cr: mk("path", { class: "nf lo" }, g), lv: mk("path", { class: "lo" }, g) });
  const L = leaf(), R = leaf();
  post(LW + 2);
  R.sil.classList.add("hi");

  const th = spring(REST);
  let last = NaN;
  function hang(el, a, side) {
    const U = [side * Math.cos(a), Math.sin(a), 0], W = [-Math.sin(a) * side, Math.cos(a) * side, 0];
    const c = add([-side * LW, 0, ZM], U, LW / 2);
    const s = slab(c, U, [0, 0, 1], W, LW / 2 - 0.6, (Z1 - Z0) / 2, 3, 3);
    el.sil.setAttribute("d", s.sil); el.cr.setAttribute("d", s.cr); el.lv.setAttribute("d", s.lv);
  }
  function draw() {
    if (th.x === last) return;
    last = th.x;
    hang(L, rad(th.x), 1); hang(R, rad(th.x * 0.92), -1);
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  function aim(p) {
    let d = Infinity;
    if (p) { const [x, y] = unproj(C, p[0], p[1], ZM); d = Math.hypot(x, y); }
    const on = d < 90;
    th.t = on ? clamp(1 - d / 90, 0.2, 1) * 80 * reach + 6 : REST;
    L.sil.classList.toggle("hi", on);
    read.textContent = on ? "swing " + Math.round(th.t) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "swingdoor",
  means: "Saloon doors between two posts: both louvred leaves swing open as the pointer comes near, wider the closer it is.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.85, 1],
  tour: [[223, 175], [170, 215], [205, 184], null],
  mount,
});

revolving.code:
/**
 * Revolving door: four glass wings round a central post, on a round floor
 * plate under a round canopy, with a curved glass wall behind. The pointer
 * across the doorway turns the wings on a spring, further the further it
 * goes from the middle. At rest one wing is bright. The slider is how far
 * the wings can turn.
 *
 * The pattern: a continuous turn, hit on a fixed plane (unproj).
 */
const {
  Cam, circ, clamp, fit, hull, poly, proj, prism, rings, ringAt, rrect, seg, unproj, spring, stepS, rad,
  disposer, facing, mk, pointer, put, register, solid,
} = HL;

const R = 40, H = 74, REST = 22;
const disc = (r, n = 48) => circ(r, n);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-R - 4, -R - 4, 0], [R + 4, R + 4, 0], [R + 4, -R - 4, 0], [-R - 4, R + 4, 0], [0, 0, H + 8]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const add = (a, b, s) => a.map((x, i) => x + b[i] * s);
  put(solid(g), prism(P, front, disc(R + 5), disc(R + 3), 0, 3));
  // the curved glass wall at the back, between the two openings
  const arc = [];
  for (let i = 0; i <= 20; i++) { const t = rad(180 + 15 + (i / 20) * 60); arc.push([R * Math.cos(t), R * Math.sin(t)]); }
  const back = arc.map(([x, y]) => P(x, y, 3)).concat(arc.slice().reverse().map(([x, y]) => P(x, y, H)));
  mk("path", { d: poly(back), class: "nf lo" }, g);
  const rot = mk("g", {}, g);
  const post = solid(rot);
  put(post, prism(P, front, disc(3, 20), disc(2, 20), 3, H));
  const wings = [0, 1, 2, 3].map((k) => {
    const wg = mk("g", {}, rot);
    return { k, g: wg, sil: mk("path", { class: k === 0 ? "sil hi" : "sil" }, wg), cr: mk("path", { class: "nf lo" }, wg), bar: mk("path", { class: "lo" }, wg) };
  });
  const [cr, ci] = [disc(R + 5), disc(R + 2)];
  put(solid(g), prism(P, front, cr, ci, H, H + 7));

  function slab(c, U, V, W, a, b, t, r) {
    const pts = [], at = (u, v, z) => P(...add(add(add(c, U, u), V, v), W, z));
    for (const q of rrect(-a, -b, a, b, r, 4)) pts.push(at(q.u, q.v, -t / 2), at(q.u, q.v, t / 2));
    const s = W[0] + W[1] >= 0 ? 1 : -1;
    const inner = rrect(-a + 2.4, -b + 2.4, a - 2.4, b - 2.4, Math.max(1, r - 2), 4).map((q) => at(q.u, q.v, s * t / 2));
    return { sil: poly(hull(pts)), cr: poly(inner), bar: seg(at(a - 12, -2, s * (t / 2 + 1)), at(a - 4, -2, s * (t / 2 + 1))) };
  }
  const th = spring(REST);
  let last = NaN;
  function draw() {
    if (th.x === last) return;
    last = th.x;
    const order = [];
    for (const w of wings) {
      const a = rad(th.x + w.k * 90), U = [Math.cos(a), Math.sin(a), 0], W = [-Math.sin(a), Math.cos(a), 0];
      const s = slab([U[0] * (R / 2 + 1), U[1] * (R / 2 + 1), H / 2 + 1.5], U, [0, 0, 1], W, R / 2 - 2.5, H / 2 - 3.5, 2.2, 3);
      w.sil.setAttribute("d", s.sil); w.cr.setAttribute("d", s.cr); w.bar.setAttribute("d", s.bar);
      order.push([U[0] + U[1], w.g]);
    }
    order.push([0, post.g]);
    order.sort((p, q) => p[0] - q[0]).forEach(([, el]) => rot.appendChild(el));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  const mid = P(0, 0, H / 2);
  function aim(p) {
    let on = false;
    if (p) { const [x, y] = unproj(C, p[0], p[1], H / 2); on = Math.hypot(x, y) < R * 1.6; }
    const dx = p ? clamp((p[0] - mid[0]) / 90, -1, 1) : 0;
    th.t = on ? REST + (dx >= 0 ? 0.35 + dx : dx - 0.35) * 55 * reach : REST;
    read.textContent = on ? "turn " + Math.round(th.t - REST) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

