  name: "pocketdoor",
  means: "A pocket door: it slides sideways into a hidden pocket in the wall as the pointer comes near, further the closer it is.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.85, 1],
  tour: [[242, 193], [300, 235], [215, 175], null],
