  name: "slotcar",
  means: "A slot car on a piece of track: it slides along the guide slot to stand under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[262, 195], [59, 127], [341, 213], null],
  mount,
});

puppetstage.code:
/**
 * Marionette: a wooden puppet hanging on strings from a cross-shaped control
 * bar. The pointer tips the control bar left or right, on a spring: one end
 * dips, the puppet swings under it, the hand on the high side lifts and the
 * legs trail. At rest the bar hangs tipped a little, bright. The slider is
 * how far the bar may tip.
 *
 * The pattern: a continuous aim read from the pointer's screen x.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rad, seg, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const BZ = 128, BL = 34, REST = rad(-12);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, 0, 18], [0, 0, BZ + 6], [-45, 0, 80], [45, 0, 80]], 200, 174);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const strings = mk("path", { class: "nf lo" }, g);
  const legs = mk("path", { class: "nf" }, g);
  const body = mk("path", { class: "sil" }, g), head = mk("path", { class: "sil" }, g);
  const arms = mk("path", { class: "nf" }, g);
  const cross = mk("path", { class: "sil" }, g), bar = mk("path", { class: "sil hi" }, g);
  const sa = spring(REST);
  let last = NaN, over = null;

  const blob = (cx, cy, cz, rx, ry, rz, n = 12) => {
    const pts = [];
    for (let i = 0; i < n; i++) for (let j = 0; j <= n / 2; j++) {
      const t = (i / n) * 2 * Math.PI, f = (j / (n / 2)) * Math.PI - Math.PI / 2;
      pts.push(P(cx + rx * Math.cos(f) * Math.cos(t), cy + ry * Math.cos(f) * Math.sin(t), cz + rz * Math.sin(f)));
    }
    return poly(hull(pts));
  };
  const beam = (a, b, w, h) => {
    const pts = [];
    for (const p of [a, b]) for (const dy of [-w, w]) for (const dz of [-h, h]) pts.push(P(p[0], p[1] + dy, p[2] + dz));
    return poly(hull(pts));
  };

  function draw() {
    const a = sa.x;
    if (Math.abs(a - last) < 0.0005) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const L = [-BL * c, 0, BZ - BL * s], R = [BL * c, 0, BZ + BL * s];
    const dx = -46 * s, sw = 0.6 * a;
    const hz = 82, bz0 = 52, bz1 = 76;
    const hl = [dx - 18, 0, 62 - 16 * s], hr = [dx + 18, 0, 62 + 16 * s];
    bar.setAttribute("d", beam(L, R, 3, 2.4));
    cross.setAttribute("d", beam([0, -20, BZ], [0, 20, BZ], 2.4, 2));
    head.setAttribute("d", blob(dx, 0, hz + 9, 8, 8, 9));
    body.setAttribute("d", blob(dx, 0, (bz0 + bz1) / 2, 10, 7, 13));
    arms.setAttribute("d", seg(P(dx - 9, 0, 72), P(...hl)) + seg(P(dx + 9, 0, 72), P(...hr)));
    const foot = (sx) => P(dx + sx + 40 * sw, 0, 20);
    legs.setAttribute("d", seg(P(dx - 5, 0, bz0 + 2), foot(-7)) + seg(P(dx + 5, 0, bz0 + 2), foot(7)));
    strings.setAttribute("d", seg(P(...L), P(...hl)) + seg(P(...R), P(...hr)) +
      seg(P(0, -20, BZ), P(dx, -4, hz + 14)) + seg(P(0, 20, BZ), P(dx, 4, hz + 14)));
  }

  const B = register(stage, (dt) => { const m = stepS(sa, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    const lim = rad(12 + 26 * reach);
    sa.t = over === null ? REST : clamp(over, -1, 1) * lim;
    read.textContent = over === null ? "rest" : "tilt " + Math.round((sa.t * 180) / Math.PI);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { over = p[1] < 10 || p[1] > 310 ? null : (p[0] - 200) / 110; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "puppetstage",
  means: "A marionette on strings from a control bar: the pointer tips the bar and the puppet swings and lifts a hand.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[320, 160], [90, 160], [250, 170], null],
  mount,
});

rcar.code:
/**
 * RC car: a chunky remote control buggy on four fat wheels, a domed shell on
 * a low chassis and a whip antenna at the back. The pointer is where the car
 * is steered to: it turns on the spot, on a spring, to point its nose there.
 * At rest it sits angled to the left, its chassis bright. The slider is how
 * far the car may turn.
 *
 * The pattern: a continuous aim on the ground plane, which never moves.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WR = 8, WW = 7, REST = rad(-35);
const WHEELS = [[-17, -17], [17, -17], [-17, 17], [17, 17]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.5);
  fit(C, [[-38, -38, 0], [38, 38, 0], [38, -38, 0], [-38, 38, 0], [0, 0, 46]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const farG = mk("g", {}, g), bodyG = mk("g", {}, g), nearG = mk("g", {}, g);
  const wheels = WHEELS.map(() => mk("path", { class: "sil" }, farG));
  const chassis = solid(bodyG), shell = solid(bodyG), wing = solid(bodyG);
  const ant = mk("path", { class: "nf" }, bodyG);
  chassis.sil.classList.add("hi");
  const sa = spring(REST);
  let last = NaN, over = null;

  const turn = (ring, a) => ring.map((q) => ({
    u: q.u * Math.cos(a) - q.v * Math.sin(a), v: q.u * Math.sin(a) + q.v * Math.cos(a),
    nu: q.nu * Math.cos(a) - q.nv * Math.sin(a), nv: q.nu * Math.sin(a) + q.nv * Math.cos(a),
  }));
  const box = (x0, y0, x1, y1, r, b, a, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); return prism(P, front, turn(o, a), turn(i, a), z0, z1); };

  function draw() {
    const a = sa.x;
    if (Math.abs(a - last) < 0.0005) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a), W = (u, v, z) => P(u * c - v * s, u * s + v * c, z);
    WHEELS.forEach(([u, v], k) => {
      const pts = [];
      for (let i = 0; i < 18; i++) { const t = (i / 18) * Math.PI * 2; for (const dv of [-WW / 2, WW / 2]) pts.push(W(u + WR * Math.cos(t), v + Math.sign(v) * dv, WR + WR * Math.sin(t))); }
      wheels[k].setAttribute("d", poly(hull(pts)));
      const wx = u * c - v * s, wy = u * s + v * c;
      (wx + wy > 0 ? nearG : farG).appendChild(wheels[k]);
    });
    put(chassis, box(-30, -12, 30, 12, 8, 2, a, 6, 13));
    put(shell, box(-14, -11, 14, 11, 9, 2, a, 13, 22));
    put(wing, box(-30, -13, -24, 13, 2, 0.8, a, 22, 24));
    ant.setAttribute("d", seg(W(-20, 8, 13), W(-24, 9, 44)));
    const rx = -22 * c - 8 * s, ry = -22 * s + 8 * c;
    if (rx + ry < 0) bodyG.insertBefore(ant, chassis.g); else bodyG.appendChild(ant);
  }

  const B = register(stage, (dt) => { const m = stepS(sa, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    const lim = rad(40 + 130 * reach);
    sa.t = over === null ? REST : clamp(over, -lim, lim);
    read.textContent = over === null ? "rest" : "steer " + Math.round((sa.t * 180) / Math.PI);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      over = r > 130 || r < 6 ? null : Math.atan2(y, x);
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "rcar",
  means: "A remote control buggy on fat wheels: it turns on the spot to point its nose at the pointer.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[200, 290], [60, 190], [340, 190], null],
  mount,
});

outdoorshower.code:
/**
 * Outdoor shower: a timber post on a slatted deck square, a tap half way up
 * and a long arm at the top carrying a wide rain head. The pointer is where
 * the water should fall: the arm swings round the post on a spring to hold
 * the head over it. At rest the arm points off to the left, its head bright.
 * The slider is how far the arm may swing.
 *
 * The pattern: a continuous aim on the ground plane, which never moves.
 */
const {
  Cam, circ, clamp, fit, facing, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PZ = 118, AL = 40, HR = 11, REST = rad(-80);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[-48, -48, 0], [48, 48, 0], [48, -48, 0], [-48, 48, 0], [0, 0, PZ + 6]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [dr, di] = rings(-34, -34, 34, 34, 6, 2);
  put(solid(g), prism(P, front, dr, di, 0, 5));
  const slats = mk("path", { class: "nf lo" }, g);
  slats.setAttribute("d", [-17, 0, 17].map((v) => seg(P(-32, v, 5), P(32, v, 5))).join(""));
  const farG = mk("g", {}, g);
  const [pr, pi] = rings(-4, -4, 4, 4, 2, 1);
  put(solid(g), prism(P, front, pr, pi, 5, PZ + 4));
  const [tr, ti] = rings(4, -2, 9, 2, 1, 0.6);
  put(solid(g), prism(P, front, tr, ti, 54, 59));
  mk("path", { d: seg(P(9, 0, 60), P(9, 0, 66)), class: "nf" }, g);
  const nearG = mk("g", {}, g);
  const arm = solid(farG), drop = solid(farG), head = solid(farG);
  head.sil.classList.add("hi");
  const sa = spring(REST);
  let last = NaN, over = null;

  const turn = (ring, a) => ring.map((q) => ({
    u: q.u * Math.cos(a) - q.v * Math.sin(a), v: q.u * Math.sin(a) + q.v * Math.cos(a),
    nu: q.nu * Math.cos(a) - q.nv * Math.sin(a), nv: q.nu * Math.sin(a) + q.nv * Math.cos(a),
  }));
  const disc = (x, y, r) => circ(r, 32).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

  function draw() {
    const a = sa.x;
    if (Math.abs(a - last) < 0.0005) return;
    last = a;
    const [ar, ai] = rings(-2, -2, AL, 2, 2, 0.6);
    put(arm, prism(P, front, turn(ar, a), turn(ai, a), PZ - 2, PZ + 2));
    const hx = AL * Math.cos(a), hy = AL * Math.sin(a);
    put(drop, prism(P, front, disc(hx, hy, 2), disc(hx, hy, 1.2), PZ - 8, PZ - 2));
    put(head, prism(P, front, disc(hx, hy, HR), disc(hx, hy, HR - 2), PZ - 11, PZ - 8));
    const grp = hx + hy > 0 ? nearG : farG;
    for (const s of [arm, drop, head]) grp.appendChild(s.g);
  }

  const B = register(stage, (dt) => { const m = stepS(sa, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    const lim = rad(30 + 150 * reach), mid = rad(45);
    sa.t = over === null ? REST : mid + clamp(over - mid, -lim, lim);
    read.textContent = over === null ? "rest" : "arm " + Math.round((((sa.t * 180) / Math.PI) + 360) % 360);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      if (r > 140 || r < 4) over = null;
      else { let t = Math.atan2(y, x); while (t < rad(45) - Math.PI) t += 2 * Math.PI; while (t > rad(45) + Math.PI) t -= 2 * Math.PI; over = t; }
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "outdoorshower",
  means: "An outdoor shower post on a deck: the arm swings round the post to hold its rain head over the pointer.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[200, 260], [330, 190], [80, 190], null],
  mount,
});

cello.code:
/**
 * Cello: a cello lying on its back, the waisted body with its two bouts, the
 * bridge, the long neck and the scroll, the endpin towards us. The pointer
 * along it picks how far to raise it: the cello tilts up about the endpin,
 * scroll first, as if being stood up to play. At rest it lies low, the
 * strings bright. The slider is the largest tilt, so how far it rises.
 *
 * The pattern: one rigid body tilting about its foot, picked on the rest plane.
 */
const {
  Cam, clamp, fit, poly, hull, proj, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, register, solid,
} = HL;

const EP = 160, REST = 5;
// half-width of the body along u (u = distance from the endpin)
const wid = (u) => {
  const t = (u - 14) / 90;
  if (t < 0 || t > 1) return 0;
  return (18.5 + 4 * Math.cos((2 * Math.PI * (t - 0.27)) / 0.55) - 4 * t) * Math.pow(Math.sin(Math.PI * t), 0.35);
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 1.95);
  const rot = (deg) => {
    const c = Math.cos((deg * Math.PI) / 180), s = Math.sin((deg * Math.PI) / 180);
    return ([x, y, z]) => [EP + (x - EP) * c + z * s, y, -(x - EP) * s + z * c];
  };
  const ext = [];
  for (const a of [0, 30]) for (const q of [[EP, 0, 0], [EP - 14, 24, 12], [EP - 14, -24, 12], [-8, 8, 12], [-8, -8, 0], [EP - 60, 24, 0], [EP - 60, -24, 0]]) ext.push(rot(a)(q));
  fit(C, ext, 200, 168);
  const P = proj(C);
  const g = mk("g", {}, svg);

  const outline = (z) => {
    const L = [], Rr = [];
    for (let u = 14; u <= 104; u += 2) { const w = wid(u); L.push([EP - u, w, z]); Rr.push([EP - u, -w, z]); }
    return L.concat(Rr.reverse());
  };
  const box = (x0, y0, x1, y1, z, r = 1.5) => {
    const o = [];
    for (const [cx, cy, a] of [[x1 - r, y1 - r, 0], [x0 + r, y1 - r, 90], [x0 + r, y0 + r, 180], [x1 - r, y0 + r, 270]]) {
      for (let i = 0; i <= 4; i++) { const t = ((a + i * 22.5) * Math.PI) / 180; o.push([cx + r * Math.cos(t), cy + r * Math.sin(t), z]); }
    }
    return o;
  };
  const shapes = [];
  const plate = (pts, cls) => { const p = mk("path", { class: cls }, g); shapes.push({ p, pts, flat: true }); return p; };
  const sol = (base, top, cr) => { const s = solid(g); shapes.push({ s, base, top, cr }); return s; };

  plate(outline(0), "sil");
  plate(outline(11), "sil");
  plate(outline(11).map(([x, y, z]) => [EP - 59 + (x - EP + 59) * 0.93, y * 0.88, z]), "nf lo");
  sol(box(EP - 14, -1.2, EP, 1.2, 4), box(EP - 14, -1.2, EP, 1.2, 6.5), null);
  sol(box(EP - 50, -9, EP - 47, 9, 11), box(EP - 50, -9, EP - 47, 9, 17), null);
  sol(box(EP - 170, -4, EP - 96, 4, 10), box(EP - 170, -4, EP - 96, 4, 14), box(EP - 169, -3, EP - 97, 3, 14));
  sol(box(EP - 184, -5, EP - 168, 5, 8), box(EP - 184, -5, EP - 168, 5, 13), box(EP - 183, -4, EP - 169, 4, 13));
  const strings = [-2.7, -0.9, 0.9, 2.7].map((y) => {
    const p = mk("path", { class: "nf" }, g);
    shapes.push({ p, pts: [[EP - 22, y, 12], [EP - 49, y, 17.5], [EP - 168, y, 15]], line: true });
    return p;
  });

  const tilt = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const R = rot(deg), T = (q) => P(...R(q));
    for (const h of shapes) {
      if (h.line) h.p.setAttribute("d", "M" + h.pts.map(T).map((q) => q.join(",")).join("L"));
      else if (h.flat) h.p.setAttribute("d", poly(h.pts.map(T)));
      else {
        h.s.sil.setAttribute("d", poly(hull(h.base.concat(h.top).map(T))));
        if (h.cr) h.s.cr.setAttribute("d", poly(h.cr.map(T)));
      }
    }
  }
  const B = register(stage, (_dt, now) => { draw(tval(tilt, now)); return !tdone(tilt, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 11);
    const u = EP - x;
    if (u < -4 || u > 188 || Math.abs(y) > (u < 106 ? 26 : 9)) return -1;
    return 3 - clamp(Math.floor(u / 48), 0, 3);
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(tilt, a < 0 ? REST : REST + ((4 - a) / 4) * maxT, performance.now(), 0);
    for (const s of strings) s.classList.add("hi");
    read.textContent = a < 0 ? "rest" : "raise " + (4 - a);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "cello",
  means: "A cello lying on its back, endpin towards us: the pointer along it picks how far to raise it, and it tilts up about the endpin.",
  rules: [1, 3, 5, 8],
  range: [10, 22, 24],
  tour: [[210, 225], [144, 192], [102, 166], null],
  mount,
});

trombone.code:
/**
 * Trombone: a slide trombone lying on its side, the flared bell resting on
 * the ground, the bell section's tuning bend behind, and the long U of the
 * outer slide running out past the bell. The pointer along the slide picks
 * one of the seven slide positions: the outer slide glides out to it. At
 * rest it sits closed in first position, bright. The slider is the step between
 * positions, so how far the slide travels.
 *
 * The pattern: one part sliding along its axis, picked on a plane.
 */
const {
  Cam, clamp, fit, poly, proj, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, register,
} = HL;

const H = 13, YB = -18, TH = 1.4, REST = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let step = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-48, YB - 13, 0], [-48, 9, H], [56, YB + 13, 2 * H], [172, 9, H], [172, -2, H]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);

  // a tube as a thin plate: a centreline offset each side, drawn at two heights
  function band(line, w) {
    const L = [], R = [];
    for (let i = 0; i < line.length; i++) {
      const a = line[Math.max(0, i - 1)], b = line[Math.min(line.length - 1, i + 1)];
      const dx = b[0] - a[0], dy = b[1] - a[1], n = Math.hypot(dx, dy) || 1;
      L.push([line[i][0] - (dy / n) * w, line[i][1] + (dx / n) * w]);
      R.push([line[i][0] + (dy / n) * w, line[i][1] - (dx / n) * w]);
    }
    return L.concat(R.reverse());
  }
  function arc(cx, cy, r, a0, a1, n = 10) {
    const o = [];
    for (let i = 0; i <= n; i++) { const t = a0 + ((a1 - a0) * i) / n; o.push([cx + r * Math.cos(t), cy + r * Math.sin(t)]); }
    return o;
  }
  const at = (pts, z, dx = 0) => poly(pts.map(([x, y]) => P(x + dx, y, z)));
  function plate(parent, pts, cls) {
    const lo = mk("path", { class: "sil", d: at(pts, H - TH) }, parent);
    const hi = mk("path", { class: cls || "", d: at(pts, H + TH) }, parent);
    return { lo, hi, pts };
  }

  // bell section: tube back from the slide, tuning bend, forward into the bell
  plate(g, band([[6, 0], [-36, 0]].concat(arc(-36, -9, 9, Math.PI / 2, 1.5 * Math.PI)).concat([[-36, YB], [40, YB]]), 1.3));
  plate(g, band([[-14, -1], [-14, YB + 1]], 1));
  // the bell: a flared horn on the y-z plane, its mouth facing +x
  const rr = (x) => 1.6 + 11.4 * Math.pow(clamp((x - 26) / 30, 0, 1), 2.6);
  const ring = (x) => { const o = [], r = rr(x); for (let i = 0; i < 40; i++) { const t = (i / 40) * 2 * Math.PI; o.push(P(x, YB + r * Math.cos(t), H + r * Math.sin(t))); } return o; };
  const ax = P(56, YB, H), a0 = P(26, YB, H), nx = -(ax[1] - a0[1]), ny = ax[0] - a0[0];
  const up = [], dn = [];
  for (let x = 26; x <= 56; x += 2) {
    const pts = ring(x);
    let mx = pts[0], mn = pts[0];
    for (const q of pts) { const d = q[0] * nx + q[1] * ny; if (d > mx[0] * nx + mx[1] * ny) mx = q; if (d < mn[0] * nx + mn[1] * ny) mn = q; }
    up.push(mx); dn.push(mn);
  }
  mk("path", { class: "sil", d: poly(up.concat(dn.reverse())) }, g);
  mk("path", { class: "sil", d: poly(ring(56)) }, g);
  mk("path", { class: "nf lo", d: poly(ring(55).map(([x, y], i) => { const c = P(55.5, YB, H); return [c[0] + (x - c[0]) * 0.7, c[1] + (y - c[1]) * 0.7]; })) }, g);

  // inner slide (fixed), mouthpiece, and the moving outer slide
  plate(g, band([[6, 0], [84, 0]], 1));
  plate(g, band([[-4, 7], [84, 7]], 1));
  plate(g, band([[9, 0], [9, 7]], 0.9));
  plate(g, band([[-11, 7], [-4, 7]], 1.8));
  const outer = mk("g", {}, g);
  const shape = band([[22, 0], [86, 0]].concat(arc(86, 3.5, 3.5, -Math.PI / 2, Math.PI / 2)).concat([[22, 7]]), 1.6);
  const grip = band([[30, 0], [30, 7]], 1.1);
  const o1 = plate(outer, shape, "hi"), o2 = plate(outer, grip);

  const pos = tween(REST * step);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    for (const o of [o1, o2]) { o.lo.setAttribute("d", at(o.pts, H - TH, d)); o.hi.setAttribute("d", at(o.pts, H + TH, d)); }
  }
  const B = register(stage, (_dt, now) => { draw(tval(pos, now)); return !tdone(pos, now); });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < -50 || x > 170 || y < YB - 16 || y > 16) return -1;
    return clamp(Math.round((x - 40) / 18), 0, 6);
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(pos, (a < 0 ? REST : a) * step, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "pos " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { step = v; setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "trombone",
  means: "A slide trombone on its side, bell on the ground: the pointer along the slide picks one of seven positions and the slide glides out.",
  rules: [1, 3, 5, 8],
  range: [3, 9, 10],
  tour: [[198, 160], [270, 196], [342, 232], null],
  mount,
});

sundial3.code:
/**
 * Garden sundial: a stone pedestal with a round dial on top and a tall
 * triangular gnomon. The gnomon swings round the dial to face the pointer,
 * its dashed shadow falling opposite; the slider is how far it swings.
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, rrect, clamp,
  spring, stepS, disposer, mk, pointer, put, register, solid, flatDot, place, unproj, seg,
} = HL;

const DR = 30, ZT = 38, GH = 30, REST = 200;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.4);
  fit(C, [[-DR, -DR, 0], [DR, DR, 0], [DR, -DR, ZT], [-DR, DR, ZT], [0, 0, ZT + GH]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-20, -20, 20, 20, 6, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, 6));
  const [cr, ci] = rings(-11, -11, 11, 11, 5, 1.2);
  put(solid(g), prism(P, front, cr, ci, 6, ZT - 6));
  const [hr, hi] = rings(-16, -16, 16, 16, 6, 1.4);
  put(solid(g), prism(P, front, hr, hi, ZT - 6, ZT - 3));
  const dr = rrect(-DR, -DR, DR, DR, DR, 14), di = rrect(-DR + 2, -DR + 2, DR - 2, DR - 2, DR - 2, 14);
  put(solid(g), prism(P, front, dr, di, ZT - 3, ZT));
  for (let i = 0; i < 12; i++) {
    const t = (i / 12) * Math.PI * 2;
    place(flatDot(g, C, 0.9, i % 3 ? "dot off" : "dot m"), P(Math.cos(t) * (DR - 6), Math.sin(t) * (DR - 6), ZT));
  }
  const shadow = mk("path", { class: "dash nf" }, g);
  const gno = mk("path", { class: "sil hi" }, g), edge = mk("path", { class: "lo nf" }, g);
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    const ar = Math.round(a * 10) / 10;
    if (ar === last) return;
    last = ar;
    const t = (ar * Math.PI) / 180, c = Math.cos(t), s = Math.sin(t);
    const at = (r, w, z) => P(r * c - w * s, r * s + w * c, z);
    const tri = (w) => fillet([at(-6, w, ZT), at(DR - 4, w, ZT), at(-6, w, ZT + GH)], [1, 1.5, 1.5]);
    shadow.setAttribute("d", seg(P(0, 0, ZT), P(-c * (DR - 4), -s * (DR - 4), ZT)));
    gno.setAttribute("d", poly(tri(-1.4)) + poly(tri(1.4)));
    edge.setAttribute("d", poly(tri(1.4)));
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  function aim(p) {
    const [x, y] = unproj(C, p[0], p[1], ZT);
    const r = Math.hypot(x, y);
    if (r > DR + 14) return leave();
    let d = (Math.atan2(y, x) * 180) / Math.PI - REST;
    d = ((d % 360) + 540) % 360 - 180;
    ang.t = REST + d * (0.3 + 0.7 * reach);
    const h = Math.round((((ang.t % 360) + 360) % 360) / 30) % 12 || 12;
    read.textContent = "h " + h;
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  let lastP = null;
  bag.add(pointer(stage, { move: (p) => { lastP = p; aim(p); }, leave: () => { lastP = null; leave(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (lastP) aim(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "sundial3",
  means: "A garden sundial on a pedestal: the gnomon swings round the dial to face the pointer, its dashed shadow falling opposite.",
  rules: [1, 3, 5, 8, 9],
  range: [0, 1, 1],
  tour: [[253, 145], [137, 149], [200, 172], null],
  mount,
});

faxmachine.code:
/**
 * Fax machine: a squat body with a paper tray at the back, a handset on its
 * cradle and a keypad of dots. The pointer over it feeds the printed sheet
 * out of the front slot; the slider is how far the sheet runs out.
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, clamp, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, flatDot, place, unproj, seg,
} = HL;

const L = 50, W = 70, H = 16, REST = 10, FEED = 56;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let run = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-14, 0, 0], [L + REST + FEED, 6, 0], [L, 0, 0], [L, W, 0], [-14, 6, 44], [0, W, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const tray = mk("path", { class: "sil" }, g);
  const tq = (x0, z0, x1, z1) => [P(x0, 8, z0), P(x0, 50, z0), P(x1, 50, z1), P(x1, 8, z1)];
  tray.setAttribute("d", poly(fillet(tq(6, H, -12, 44), [1, 1, 2, 2])));
  mk("path", { class: "lo nf", d: poly(fillet(tq(5, H + 2, -9, 40), [1, 1, 2, 2])) }, g);
  const [br, bi] = rings(0, 0, L, W, 7, 1.8);
  put(solid(g), prism(P, front, br, bi, 0, H));
  mk("path", { class: "lo nf", d: seg(P(L, 4, 5), P(L, 60, 5)) }, g);
  const [cr, ci] = rings(10, 54, 44, 66, 4, 1);
  put(solid(g), prism(P, front, cr, ci, H, H + 2));
  const [hr, hi] = rings(8, 55, 46, 65, 5, 1.2);
  put(solid(g), prism(P, front, hr, hi, H + 2, H + 8));
