    place(flatDot(g, C, 1.1, "dot off"), P(20 + i * 7, 18 + j * 7, H));
  const sheet = mk("path", { class: "sil hi" }, g), lines = mk("path", { class: "lo nf" }, g);
  const tw = tween(REST);
