  const posts = mk("path", { class: "nf sil" }, g);
  wheel(-20, 15); wheel(20, 15);
  const roof = solid(g);
  let drawn = NaN;

  function draw(a) {
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
