photocopier.code:
/**
 * Photocopier: one office copier, a cabinet with two paper drawers and an
 * output tray, the scan glass on top under a hinged lid. The pointer over
 * the copier swings the lid up on its back hinge to bare the glass; leaving
 * lets it fall back to its rest, held a little ajar, bright. The slider is
 * how far the lid opens.
 *
 * The pattern: one part answering the whole figure (hover in a fixed box).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, rrect, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const DX = 40, DY = 52, H = 36, T = 3, REST = 0.22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ang = value;
  const C = Cam(45, 0.5, 2.9);
  const ext = [[0, 0, 0], [DX, DY + 10, 0], [DX, 0, 0], [0, DY + 10, 0], [0, 0, H + DX + 2], [0, DY, H + DX + 2], [DX * 0.3, DY, H + DX]];
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [o, i] = rings(0, 0, DX, DY, 4, 1.4);
  put(solid(g), prism(P, front, o, i, 0, H));
  mk("path", { class: "nf lo", d: poly([[4, 6], [DX - 4, 6], [DX - 4, DY - 6], [4, DY - 6]].map(([x, y]) => P(x, y, H))) }, g);
  mk("path", { class: "nf lo", d: [8, 18].map((z) => seg(P(DX, 5, z), P(DX, DY - 5, z)) + seg(P(DX, DY / 2 - 6, z + 4), P(DX, DY / 2 + 6, z + 4))).join("") + seg(P(DX, 5, 27), P(DX, DY - 5, 27)) }, g);
  const [to, ti] = rings(8, DY - 2, DX - 6, DY + 9, 2, 0.8);
  put(solid(g), prism(P, front, to, ti, 22, 23.5));       // output tray

  const lid = solid(g);
  lid.sil.classList.add("hi");
  const ring = rrect(0, 1, DX, DY - 1, 3, 4), inner = rrect(3, 4, DX - 3, DY - 4, 1.5, 4);
  const L = (t, y, n, c, s) => P(t * c - n * s, y, H + t * s + n * c);
  const a = tween(REST);
  let last = NaN;
  function draw(q) {
    if (q === last) return;
    last = q;
    const c = Math.cos(q), s = Math.sin(q), pts = [];
    for (const n of [0, T]) for (const p of ring) pts.push(L(p.u, p.v, n, c, s));
    lid.sil.setAttribute("d", poly(hull(pts)));
    const n = -0.61 * s + 0.5 * c > 0 ? T : 0;
    lid.cr.setAttribute("d", poly(inner.map((p) => L(p.u, p.v, n, c, s))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(a, now)); return !tdone(a, now); });
  bag.add(B.unregister);

  // the hit: a fixed screen box around the copier at rest
  const sp = ext.slice(0, 4).concat([[0, 0, H + 12], [0, DY, H + 12]]).map((q) => P(...q));
  const xs = sp.map((q) => q[0]), ys = sp.map((q) => q[1]);
  const inBox = ([sx, sy]) => sx > Math.min(...xs) - 6 && sx < Math.max(...xs) + 6 && sy > Math.min(...ys) - 6 && sy < Math.max(...ys) + 6;

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(a, v ? ang : REST, performance.now(), 0);
    read.textContent = v ? "open" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(inBox(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { ang = v; if (on) { tset(a, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "photocopier",
  means: "A photocopier: the pointer over it swings the lid up on its back hinge to bare the scan glass, and it drops back on leaving.",
  rules: [1, 3, 5, 6, 8],
  range: [0.8, 1.3, 1.75],
  tour: [[210, 170], [260, 230], [150, 225], null],
  mount,
});

carwash.code:
/**
 * Car wash: a car parked on a wash bay, and over it a gantry arch on two
 * legs carrying a pair of tall side brushes and one long top brush. The
 * pointer over the bay sends the arch rolling along the car, its brushes
 * spinning as it goes; leaving rolls it back to its rest at the car's nose,
 * its beam bright. The slider is how far the arch travels.
 *
 * The pattern: one part answering the whole figure (hover in a fixed box).
 */
const {
  Cam, circ, facing, fit, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const FX = 52, FY = 30, LY = 25, TOP = 38, REST = -34;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  const ext = [[-FX, -FY, 0], [FX, FY, 0], [-FX, FY, 0], [FX, -FY, 0], [REST, -LY, TOP + 4], [REST + 80, LY, TOP + 4], [REST, LY, TOP + 4]];
  fit(C, ext, 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const blk = (par, x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(par), prism(P, front, o, i, z0, z1)); };
  blk(g, -FX, -FY, FX, FY, 5, 1.6, -2.5, 0);                     // bay floor
  mk("path", { class: "nf dash", d: seg(P(-FX + 6, -LY, 0), P(FX - 6, -LY, 0)) + seg(P(-FX + 6, LY, 0), P(FX - 6, LY, 0)) }, g);
  const far = mk("g", {}, svg);
  const car = mk("g", {}, svg);
  for (const x of [-16, 16]) for (const y of [-11.4, 11.4]) put(solid(car), prism(P, front, disc(x, y, 3, 16), null, 0, 3));
  blk(car, -27, -11, 27, 11, 6, 1.6, 3, 13);                     // car body
  blk(car, -12, -9, 12, 9, 5, 1.4, 13, 21);                      // cabin
  const near = mk("g", {}, svg), topg = mk("g", {}, svg);
  const S = (par) => solid(par);
  const legF = S(far), brF = S(far), legN = S(near), brN = S(near), tbr = S(topg), beam = S(topg);
  beam.sil.classList.add("hi");
  const marks = [brF, brN, tbr].map((s) => mk("path", { class: "nf lo" }, s.g));

  const a = tween(REST);
  let last = NaN;
  function vbrush(s, m, x, y, ph) {
    put(s, prism(P, front, disc(x, y, 4.8), disc(x, y, 3.8), 4, TOP - 1));
    let d = "";
    for (let k = 0; k < 6; k++) {
      const q = ph + (k * Math.PI) / 3, nx = Math.cos(q), ny = Math.sin(q);
      if (nx + ny > 0.2) d += seg(P(x + 4.8 * nx, y + 4.8 * ny, 7), P(x + 4.8 * nx, y + 4.8 * ny, TOP - 4));
    }
    m.setAttribute("d", d);
  }
  function draw(x) {
    if (x === last) return;
    last = x;
    const ph = x * 0.18;
    for (const [leg, y] of [[legF, -LY], [legN, LY]]) {
      const [o, i] = rings(x - 3, y - 3, x + 3, y + 3, 1.4, 0.7);
      put(leg, prism(P, front, o, i, 0, TOP));
    }
    vbrush(brF, marks[0], x, -LY + 8, ph);
    vbrush(brN, marks[1], x, LY - 8, -ph);
    const [o, i] = rings(x - 4, -LY - 4, x + 4, LY + 4, 2, 1);
    put(beam, prism(P, front, o, i, TOP, TOP + 4));
    const pts = [];
    for (const y of [-13, 13]) for (let k = 0; k < 16; k++) { const q = (k / 16) * Math.PI * 2; pts.push(P(x + 5 * Math.cos(q), y, 31 + 5 * Math.sin(q))); }
    tbr.sil.setAttribute("d", poly(hull(pts)));
    tbr.cr.setAttribute("d", "");
    let d = "";
    for (let k = 0; k < 6; k++) {
      const q = ph + (k * Math.PI) / 3, nx = Math.cos(q), nz = Math.sin(q);
      if (nx + nz > 0.1) d += seg(P(x + 5 * nx, -11, 31 + 5 * nz), P(x + 5 * nx, 11, 31 + 5 * nz));
    }
    marks[2].setAttribute("d", d);
  }

  const B = register(stage, (_dt, now) => {
    const x = tval(a, now);
    draw(x);
    return !tdone(a, now);
  });
  bag.add(B.unregister);

  // the hit: a fixed screen box around the bay and the arch at rest
  const sp = ext.map((q) => P(...q));
  const xs = sp.map((q) => q[0]), ys = sp.map((q) => q[1]);
  const inBox = ([sx, sy]) => sx > Math.min(...xs) && sx < Math.max(...xs) && sy > Math.min(...ys) && sy < Math.max(...ys);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(a, v ? REST + reach : REST, performance.now(), 0);
    read.textContent = v ? "wash" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => setOn(inBox(p)), leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) { tset(a, REST + v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "carwash",
  means: "A car wash: the gantry arch with its spinning brushes rolls along the parked car under the pointer, and back on leaving.",
  rules: [1, 3, 5, 6, 8],
  range: [30, 55, 80],
  tour: [[200, 170], [230, 190], [170, 150], null],
  mount,
});

bowsaw.code:
/**
 * Bow saw: a bent tubular bow holding a toothed blade across a log. The
 * pointer's x on the ground strokes the saw along its blade on a spring; at
 * rest it sits a little off centre. The slider is the stroke's reach.
 */
const { Cam, clamp, fit, hull, poly, open, proj, unproj, spring, stepS, disposer, mk, pointer, register } = HL;

const L = 86, ZB = 58, REST = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[-L - 40, 0, 50], [L + 40, 0, 50], [0, -50, 0], [0, 50, 0], [0, 0, ZB + 86]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const R = 30, end = (y) => Array.from({ length: 28 }, (_, i) => { const a = (i / 28) * Math.PI * 2; return P(R * Math.cos(a), y, R + R * Math.sin(a)); });
  mk("path", { class: "sil", d: poly(hull(end(-50).concat(end(50)))) }, g);
  mk("path", { class: "nf lo", d: poly(end(50)) }, g);
  mk("path", { class: "nf lo", d: poly(Array.from({ length: 20 }, (_, i) => { const a = (i / 20) * Math.PI * 2; return P(11 * Math.cos(a), 50, R + 11 * Math.sin(a)); })) }, g);
  const bow = mk("path", { class: "sil" }, g);
  const blade = mk("path", { class: "sil hi" }, g), teeth = mk("path", { class: "nf lo" }, g);
  const dx = spring(REST);
  let amp = value, last = null, over = null;
  function draw() {
    if (last === dx.x.toFixed(2)) return;
    last = dx.x.toFixed(2);
    const o = dx.x, Q = (x, y, z) => P(x + o, y, z);
    const outer = [], inner = [];
    for (let i = 0; i <= 24; i++) {
      const u = -1 + (2 * i) / 24, x = u * (L + 4);
      outer.push(Q(x, 0, ZB + 4 + 82 * (1 - u * u) + 6));
      inner.push(Q(x * 0.94, 0, ZB + 4 + 82 * (1 - u * u)));
    }
    outer.unshift(Q(-L - 4, 0, ZB - 2)); outer.push(Q(L + 4, 0, ZB - 2));
    inner.unshift(Q(-L + 2, 0, ZB - 2)); inner.push(Q(L - 2, 0, ZB - 2));
    bow.setAttribute("d", poly(outer.concat(inner.reverse())));
    const b = [Q(-L, -1.5, ZB), Q(L, -1.5, ZB), Q(L, 1.5, ZB), Q(-L, 1.5, ZB), Q(-L, -1.5, ZB + 10), Q(L, -1.5, ZB + 10), Q(L, 1.5, ZB + 10), Q(-L, 1.5, ZB + 10)];
    blade.setAttribute("d", poly(hull(b)));
    const t = [];
    for (let x = -L + 4; x <= L - 4; x += 8) t.push(Q(x, 1.5, ZB + 1), Q(x + 4, 1.5, ZB + 4));
    teeth.setAttribute("d", open(t));
  }
  const B = register(stage, (dt) => { const m = stepS(dx, dt); draw(); return m; });
  bag.add(B.unregister);
  function retarget() {
    dx.t = over == null ? REST : clamp(over, -1, 1) * 40 * amp;
    read.textContent = over == null ? "rest" : `${dx.t > 0 ? "+" : ""}${Math.round(dx.t)}`;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) > 150 ? null : (x - y) / 80; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amp = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "bowsaw",
  means: "A bow saw across a log: it strokes along its blade toward the pointer and settles back just off centre.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[320, 293], [80, 221], [200, 257], null],
  mount,
});

plumbbob.code:
/**
 * Plumb bob: a brass bob on a cord under a wall bracket, with the true
 * vertical dashed beneath it. The pointer's x on the ground swings the bob
 * on a spring; at rest it hangs a little off true. The slider is the reach.
 */
const { Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, seg, unproj, spring, stepS, rad, flatDot, place,
  disposer, mk, pointer, put, register, solid } = HL;

const PIV = [0, 0, 128], CORD = 46, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-40, -40, 0], [40, 40, 0], [0, 0, 136], [-50, 0, 60], [50, 0, 60]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-30, -30, 30, 30, 10, 1.6);
  put(solid(g), prism(P, front, pr, pi, -3, 0));
  mk("path", { class: "dash", d: seg(P(0, 0, 0), P(0, 0, PIV[2] - 4)) }, g);
  const mark = flatDot(g, C, 3, "dot m"); place(mark, P(0, 0, 0));
  const [br, bi] = rings(-12, -7, 12, 7, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, PIV[2], PIV[2] + 8));
  const cord = mk("path", { class: "nf sil" }, g);
  const bob = mk("path", { class: "sil hi" }, g), band = mk("path", { class: "nf lo" }, g);
  let amp = value;
  const th = spring(REST);
  let last = null, over = null;
  // profile of the bob along its axis: [distance below cord end, radius]
  const PROF = [[0, 3.5], [6, 9], [14, 15], [26, 15], [34, 10]];
  function draw() {
    if (last === th.x.toFixed(2)) return;
    last = th.x.toFixed(2);
    const t = rad(th.x), s = Math.sin(t), c = Math.cos(t);
    const at = (ox, oy, oz) => P(PIV[0] + ox * c - oz * s, PIV[1] + oy, PIV[2] + ox * s + oz * c);
    const top = at(0, 0, -CORD);
    cord.setAttribute("d", seg(P(...PIV), top));
    const ringPts = (d, r) => circ(r, 28).map((q) => at(q.u, q.v, -CORD - d));
    let pts = [];
    for (const [d, r] of PROF) pts = pts.concat(ringPts(d, r));
    pts.push(at(0, 0, -CORD - 52));
    bob.setAttribute("d", poly(hull(pts)));
    band.setAttribute("d", poly(ringPts(14, 15)));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  function retarget() {
    th.t = over == null ? REST : clamp(over, -1, 1) * 30 * amp;
    read.textContent = over == null ? "rest" : `${Math.round(th.t)}°`;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) > 110 ? null : (x - y) / 70; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amp = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "plumbbob",
  means: "A plumb bob on its cord: it swings toward the pointer and settles back near true over the ground mark.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[142, 158], [258, 216], [200, 151], null],
  mount,
});

brace.code:
/**
 * Brace and bit: a cranked brace standing on its bit in a board. The pointer
 * turns the crank about the bit's axis on a spring, the grip sweeping round;
 * at rest it stands a quarter turn off. The slider is how far it turns.
 */
const { Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, unproj, spring, stepS, rad, disposer, mk, pointer, put, register, solid } = HL;

const RC = 38, REST = -60;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.45);
  fit(C, [[-60, -60, 0], [60, 60, 0], [-RC - 8, 0, 100], [RC + 8, 0, 100], [0, 0, 172]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-58, -46, 58, 46, 8, 1.6);
  put(solid(g), prism(P, front, br, bi, -12, 0));
  const cyl = (r, z0, z1, ox = 0, oy = 0) => { const m = (q) => ({ ...q, u: q.u + ox, v: q.v + oy }); return prism(P, front, circ(r, 24).map(m), circ(r - 1, 24).map(m), z0, z1); };
  put(solid(g), cyl(2.5, 0, 34));
  put(solid(g), cyl(7, 34, 58));
  const crank = mk("path", { class: "sil" }, g);
  const grip = solid(g), head = solid(g);
  grip.sil.classList.add("hi");
  const th = spring(REST);
  let amp = value, last = null, over = null;
  function draw() {
    if (last === th.x.toFixed(2)) return;
    last = th.x.toFixed(2);
    const c = Math.cos(rad(th.x)), s = Math.sin(rad(th.x));
    const W = (d, z) => [d * c, d * s, z];
    const path = [W(0, 58), W(0, 66), W(RC, 82), W(RC, 126), W(0, 142), W(0, 150)];
    const tube = (k) => path.map(([x, y, z]) => P(x + k * s, y - k * c, z));
    const side = path.map(([x, y, z], i) => { const sh = i === 0 || i === 5 ? 0 : 0; return P(x, y, z + sh); });
    const a = tube(3), b = tube(-3);
    const pts = side.map((q, i) => [q, a[i], b[i]]);
    let d = "";
    for (let i = 0; i < pts.length - 1; i++) d += poly(hull([pts[i][1], pts[i][2], pts[i + 1][1], pts[i + 1][2], P(path[i][0] + 3 * c, path[i][1] + 3 * s, path[i][2]), P(path[i + 1][0] - 3 * c, path[i + 1][1] - 3 * s, path[i + 1][2])]));
    crank.setAttribute("d", d);
    put(grip, cyl(7, 88, 120, RC * c, RC * s));
    put(head, cyl(15, 150, 162));
  }
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(); return m; });
  bag.add(B.unregister);
  function retarget() {
    th.t = over == null ? REST : REST + clamp(over, -1, 1) * 150 * amp;
    read.textContent = over == null ? "rest" : `${Math.round(th.t - REST)}°`;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) > 140 ? null : (x - y) / 90; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { amp = v; retarget(); }, destroy: bag.dispose };
}

