  name: "brace",
  means: "A brace and bit in a board: the crank swings round the bit toward the pointer and settles back a quarter turn off.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[313, 279], [87, 207], [200, 243], null],
  mount,
});

knitting.code:
/**
 * Knitting needles: a ball of yarn on the ground, wound round with strands,
 * a loose end trailing off, and two knobbed needles stuck into its top. The
 * pointer over it swings the needles wide apart, staggered from the side it
 * is on, and the ball turns as if the yarn were pulled. At rest the needles
 * stand in a narrow, uneven V, the left one bright. The slider is the spread.
 *
 * The pattern: one object answering as a whole; the hit is a fixed screen disc.
 */
const {
  Cam, clamp, fit, hull, open, poly, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const R = 28, CZ = R, L = 92, S = 2.2, SQ = Math.SQRT1_2;
const C0 = [0, 0, CZ], RIGHT = [SQ, -SQ, 0], VIEW = [SQ * 0.866, SQ * 0.866, 0.5];
const REST = [-0.3, 0.42], FAV = 0;
const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
function ring3(c, a, r, n = 16) {
  const h = Math.abs(a[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  let u = [a[1] * h[2] - a[2] * h[1], a[2] * h[0] - a[0] * h[2], a[0] * h[1] - a[1] * h[0]];
  const lu = Math.hypot(...u); u = u.map((q) => q / lu);
  const v = [a[1] * u[2] - a[2] * u[1], a[2] * u[0] - a[0] * u[2], a[0] * u[1] - a[1] * u[0]];
  return Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2, c1 = Math.cos(t) * r, s1 = Math.sin(t) * r; return [0, 1, 2].map((j) => c[j] + u[j] * c1 + v[j] * s1); });
}
const ball = (c, r, n = 6) => { let o = []; for (let i = -n; i <= n; i++) { const z = (i / n) * r; o = o.concat(ring3([c[0], c[1], c[2] + z], [0, 0, 1], Math.sqrt(Math.max(0, r * r - z * z)) + 0.01, 24)); } return o; };
const WRAPS = [[0.3, 0], [1.1, 0.4], [1.2, 1.5], [0.9, 2.6], [1.45, 3.4], [0.7, 4.6]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, S);
  const reach = (th) => [0, 1, 2].map((j) => C0[j] + (Math.cos(th) * (j === 2 ? 1 : 0) + Math.sin(th) * RIGHT[j]) * (L + 8));
  fit(C, [[-R, -R, 0], [R + 26, R + 30, 0], [R, -R, 0], [-R, R, 0], reach(-1.3), reach(1.3), reach(0)], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  // the loose end, trailing over the ground in front
  const tail = [];
  for (let i = 0; i <= 14; i++) { const t = i / 14; tail.push(P(R * 0.7 + t * 30, R * 0.7 + Math.sin(t * 5) * 6 + t * 18, Math.max(0, 6 - t * 30) + 0.2)); }
  mk("path", { d: open(tail), class: "nf lo" }, g);
  const body = mk("path", { class: "sil", d: poly(hull(ball(C0, R).map((q) => P(...q)))) }, g);
  const wraps = mk("path", { class: "nf lo" }, g);
  const ndl = [0, 1].map((k) => { const grp = mk("g", {}, g); return { k, rod: mk("path", { class: "sil" }, grp), knob: mk("path", { class: "sil" }, grp), th: tween(REST[k]) }; });
  const spin = tween(0);
  let last = "";

  function draw(now) {
    const th = ndl.map((n) => tval(n.th, now)), s = tval(spin, now), key = th.join() + s;
    if (key === last) return;
    last = key;
    let d = "";
    for (const [tilt, az] of WRAPS) {
      const a = az + s, nrm = [Math.sin(tilt) * Math.cos(a), Math.sin(tilt) * Math.sin(a), Math.cos(tilt)];
      const pts = ring3(C0, nrm, R * 0.97, 48);
      let run = [];
      for (let i = 0; i <= 48; i++) {
        const q = pts[i % 48];
        if (dot3([q[0] - C0[0], q[1] - C0[1], q[2] - C0[2]], VIEW) > 2) run.push(P(...q));
        else { if (run.length > 1) d += open(run); run = []; }
      }
      if (run.length > 1) d += open(run);
    }
    wraps.setAttribute("d", d);
    ndl.forEach((n, k) => {
      const dir = [0, 1, 2].map((j) => Math.cos(th[k]) * (j === 2 ? 1 : 0) + Math.sin(th[k]) * RIGHT[j] + (k ? -0.12 : 0.12) * SQ);
      const a = [0, 1, 2].map((j) => C0[j] + dir[j] * 8), b = [0, 1, 2].map((j) => C0[j] + dir[j] * L);
      n.rod.setAttribute("d", poly(hull(ring3(a, dir, 1.2, 12).concat(ring3(b, dir, 2.2, 12)).map((q) => P(...q)))));
      n.knob.setAttribute("d", poly(hull(ball(b, 4.6, 3).map((q) => P(...q)))));
    });
  }

  const B = register(stage, (_dt, now) => { draw(now); return !(ndl.every((n) => tdone(n.th, now)) && tdone(spin, now)); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(side) {
    if (side === act) return;
    act = side;
    const now = performance.now(), on = side >= 0;
    ndl.forEach((n, k) => {
      const open = (0.35 + 0.8 * amp) * (k ? 1 : -1);
      tset(n.th, on ? open : REST[k], now, on ? Math.abs(k - side) * 60 : 0);
      n.rod.classList.toggle("hi", k === (on ? side : FAV));
      n.knob.classList.toggle("hi", k === (on ? side : FAV));
    });
    tset(spin, on ? 1.6 * amp : 0, now, 0);
    read.textContent = on ? (side ? "R " : "L ") + Math.round((0.35 + 0.8 * amp) * 115) + "°" : "rest";
    B.wake();
  }
  setActive(-1);
  const mid = P(...C0), top = P(C0[0], C0[1], CZ + L * 0.6);
  bag.add(pointer(stage, {
    move: (p) => { const dx = p[0] - mid[0]; setActive(Math.abs(dx) < 110 && p[1] > top[1] - 50 && p[1] < mid[1] + 100 ? (dx < 0 ? 0 : 1) : -1); },
    leave: () => setActive(-1),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 0.2, 1); const a = act; act = -2; setActive(a); }, destroy: bag.dispose };
}

hairline({
  name: "knitting",
  means: "A yarn ball with two needles stuck in its top: the pointer swings the needles wide apart and turns the ball as the yarn pulls.",
  rules: [1, 2, 4, 5],
  range: [0.2, 0.6, 1],
  tour: [[170, 150], [235, 160], [200, 200], null],
  mount,
});

toydrum.code:
/**
 * Toy drum: a round drum with hoops and zigzag cords, a strap looped over it
 * from its lugs, and two sticks resting on its head. The pointer over the
 * drum raises both sticks high for a beat, staggered, and the strap swings
 * forward. At rest one stick is lifted a little, bright. The slider is how
 * high the sticks rise.
 *
 * The pattern: one object answering as a whole; the hit is on the ground plane.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 32, L = 58, BZ = 46, S = 2.45;
const SQ = Math.SQRT1_2;
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
function ring3(c, a, r, n = 16) {
  const h = Math.abs(a[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  let u = [a[1] * h[2] - a[2] * h[1], a[2] * h[0] - a[0] * h[2], a[0] * h[1] - a[1] * h[0]];
  const lu = Math.hypot(...u); u = u.map((q) => q / lu);
  const v = [a[1] * u[2] - a[2] * u[1], a[2] * u[0] - a[0] * u[2], a[0] * u[1] - a[1] * u[0]];
  return Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2, c1 = Math.cos(t) * r, s1 = Math.sin(t) * r; return [0, 1, 2].map((j) => c[j] + u[j] * c1 + v[j] * s1); });
}
const cyl = (a, b, r0, r1) => { const d = sub(b, a), l = Math.hypot(...d), ax = d.map((q) => q / l); return ring3(a, ax, r0).concat(ring3(b, ax, r1)); };
const ball = (c, r) => { let o = []; for (let i = -4; i <= 4; i++) { const z = (i / 4) * r; o = o.concat(ring3([c[0], c[1], c[2] + z], [0, 0, 1], Math.sqrt(Math.max(0, r * r - z * z)) + 0.01, 16)); } return o; };
// the two butts, in front of the drum, and the sticks' rest drop onto the head
const ANG = [Math.PI / 4 - 0.62, Math.PI / 4 + 0.62];
const BUTT = ANG.map((a) => [Math.cos(a) * (R + 24), Math.sin(a) * (R + 24), BZ]);
const DROP = Math.asin((BZ - 39) / L);
const REST = [0.18, 0], FAV = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-R - 6, -R - 6, 0], [R + 30, R + 30, 0], [R + 6, -R - 6, 0], [-R - 6, R + 6, 0], [0, 0, BZ + L * 0.95], [-R, -R, 60]], 200, 166);
  const P = proj(C), front = facing(C);
  const pp = (pts) => pts.map((q) => P(...q));
  const g = mk("g", {}, svg);
  const strap = mk("path", {}, g);
  const drum = mk("g", {}, g);
  put(solid(drum), prism(P, front, circ(R, 48), circ(R - 1.5, 48), 5, 30));
  // zigzag cords between the hoops, on the side facing us
  const zz = [];
  for (let i = 0; i <= 12; i++) { const a = Math.PI / 4 - Math.PI / 2 + (i / 12) * Math.PI; zz.push(P(Math.cos(a) * R, Math.sin(a) * R, i % 2 ? 29 : 7)); }
  mk("path", { d: open(zz), class: "nf lo" }, drum);
  put(solid(drum), prism(P, front, circ(R + 1.5, 48), circ(R, 48), 0, 7));
  put(solid(drum), prism(P, front, circ(R + 1.5, 48), circ(R - 2, 48), 29, 36));
  for (const s of [1, -1]) {
    const c = [s * SQ * (R + 1), -s * SQ * (R + 1), 18];
    mk("path", { d: poly(hull(pp(ball(c, 3)))), class: "sil" }, drum);
  }
  const sticks = BUTT.map((b, k) => {
    const grp = mk("g", {}, g);
    return { k, b, grp, body: mk("path", { class: "sil" }, grp), tip: mk("path", { class: "sil" }, grp), up: tween(REST[k]) };
  });
  const sw = tween(-0.9);
  let last = "";

  function draw(now) {
    const a = sticks.map((s) => tval(s.up, now)), f = tval(sw, now), key = a.join() + f + amp;
    if (key === last) return;
    last = key;
    // strap: a band looped from lug to lug, swung about the lug axis by f
    const ax = [SQ, -SQ, 0], n = [SQ, SQ, 0], o = [], i2 = [];
    for (let i = 0; i <= 24; i++) {
      const t = (i / 24) * Math.PI, w = [0, 0, 1].map((u, j) => Math.cos(f) * u + Math.sin(f) * n[j]);
      const pt = (r) => P(...[0, 1, 2].map((j) => ax[j] * Math.cos(t) * (R + 1) + w[j] * Math.sin(t) * r + (j === 2 ? 18 : 0)));
      o.push(pt(R + 22)); i2.unshift(pt(R + 17));
    }
    strap.setAttribute("d", poly(o.concat(i2)));
    if (f > 0) g.insertBefore(drum, strap); else g.insertBefore(strap, drum);
    sticks.forEach((s, k) => {
      const e = -DROP + a[k] * amp * 1.35, d = [-Math.cos(ANG[k]) * Math.cos(e), -Math.sin(ANG[k]) * Math.cos(e), Math.sin(e)];
      const tip = [0, 1, 2].map((j) => s.b[j] + d[j] * L);
      s.body.setAttribute("d", poly(hull(pp(cyl(s.b, tip, 2.2, 1.5)))));
      s.tip.setAttribute("d", poly(hull(pp(ball(tip, 3.4)))));
    });
  }

  const B = register(stage, (_dt, now) => { draw(now); return !(sticks.every((s) => tdone(s.up, now)) && tdone(sw, now)); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(on, side) {
    const id = on ? side : -1;
    if (id === act) return;
    act = id;
    const now = performance.now();
    sticks.forEach((s, k) => {
      tset(s.up, on ? 1 : REST[k], now, on ? Math.abs(k - side) * 60 : 0);
      s.body.classList.toggle("hi", k === (on ? side : FAV));
      s.tip.classList.toggle("hi", k === (on ? side : FAV));
    });
    tset(sw, on ? 0.15 : -0.9, now, 0);
    read.textContent = on ? (side ? "R " : "L ") + Math.round(amp * 77) + "°" : "rest";
    B.wake();
  }
  setActive(false, 0);
  const mid = P(0, 0, 0)[0];
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); setActive(Math.hypot(x - 8, y - 8) < R + 30, p[0] < mid ? 1 : 0); },
    leave: () => setActive(false, 0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 0.2, 1); last = ""; if (act >= 0) read.textContent = (act ? "R " : "L ") + Math.round(amp * 77) + "°"; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "toydrum",
  means: "A toy drum with a strap and two sticks: the pointer over it raises both sticks high to strike and swings the strap forward.",
  rules: [1, 2, 4, 5],
  range: [0.3, 0.75, 1],
  tour: [[230, 170], [170, 165], [200, 200], null],
  mount,
});

cancrusher.code:
/**
 * Can crusher: a wall plate with a base shelf, a can standing on it, a press
 * plate above and a long lever hinged at the top of the wall plate. At rest
 * the lever stands raised, bright; the pointer on the figure swings it down,
 * driving the press plate onto the can, which squashes. The slider is the swing.
 */
const { Cam, fit, hull, poly, proj, tween, tset, tval, tdone, disposer, mk, pointer, register, rad } = HL;

const box = (x0, y0, z0, x1, y1, z1) => [[x0, y0, z0], [x1, y0, z0], [x0, y1, z0], [x1, y1, z0], [x0, y0, z1], [x1, y0, z1], [x0, y1, z1], [x1, y1, z1]];
const ring = (x, y, z, r, n = 28) => Array.from({ length: n }, (_, i) => {
  const a = (i / n) * Math.PI * 2;
  return [x + Math.cos(a) * r, y + Math.sin(a) * r, z];
});
const cyl = (x, y, r, z0, z1) => ring(x, y, z0, r).concat(ring(x, y, z1, r));
const rot = (p, o, a) => {
  const c = Math.cos(a), s = Math.sin(a), di = p[0] - o[0], dj = p[2] - o[2];
  return [o[0] + di * c - dj * s, p[1], o[2] + di * s + dj * c];
};

const S = 2.55, HP = [6, 15, 62], D = 24;
const ang = (t, a) => rad(50 - 62 * Math.min(1, t * a));
const pinAt = (t, a) => rot([HP[0] + D, 15, HP[2]], HP, ang(t, a));
const plateZ = (t, a) => pinAt(t, a)[2] - 46;
const LEVER = box(HP[0] - 4, 11, HP[2] - 3, HP[0] + 74, 19, HP[2] + 3);
const GRIP = box(HP[0] + 62, 9, HP[2] - 5, HP[0] + 80, 21, HP[2] + 5);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, S);
  const all = [...box(0, 2, 0, 6, 28, 70), ...box(6, 4, 0, 30, 26, 4)];
  for (const t of [0, 1]) for (const p of LEVER.concat(GRIP)) all.push(rot(p, HP, ang(t, 1.3)));
  fit(C, all, 200, 162);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const shape = (pts, cls) => { const el = mk("path", { class: cls || "sil" }, g); if (pts) el.setAttribute("d", poly(hull(pts.map((p) => P(...p))))); return el; };
  shape(box(0, 2, 0, 6, 28, 70));
  shape(box(-1, 13, 58, 7, 17, 66), "nf lo");
  shape(box(6, 4, 0, 30, 26, 4));
  const can = shape(null), rim = mk("path", { class: "nf lo" }, g);
  const link = shape(null), plate = shape(null), lever = shape(null, "sil hi"), grip = shape(null, "sil hi");
  const flat = (pts) => poly(pts.map((p) => P(...p)));
  const hb0 = all.map((p) => P(...p));
  const xs = hb0.map((p) => p[0]), ys = hb0.map((p) => p[1]);
  const hb = [Math.min(...xs) - 6, Math.min(...ys) - 6, Math.max(...xs) + 6, Math.max(...ys) + 6];
  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = ang(t, amp), pz = plateZ(t, amp), top = pz - 0.2, pin = pinAt(t, amp);
    const r = 8 + (30 - (top - 4)) * 0.08;
    can.setAttribute("d", poly(hull(cyl(18, 15, r, 4, top).map((p) => P(...p)))));
    rim.setAttribute("d", flat(ring(18, 15, top, r - 2)));
    plate.setAttribute("d", poly(hull(box(7, 5, pz, 29, 25, pz + 3).map((p) => P(...p)))));
    link.setAttribute("d", poly(hull(box(16, 13, pz + 3, 20, 17, pz + 4).concat(box(pin[0] - 2, 13, pin[2] - 1, pin[0] + 2, 17, pin[2])).map((p) => P(...p)))));
    lever.setAttribute("d", poly(hull(LEVER.map((p) => P(...rot(p, HP, a))))));
    grip.setAttribute("d", poly(hull(GRIP.map((p) => P(...rot(p, HP, a))))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let on = null;
  function set(a) {
    if (a === on) return;
    on = a;
    tset(tw, a ? 1 : 0, performance.now(), 0);
    read.textContent = a ? "crush" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => set(x > hb[0] && x < hb[2] && y > hb[1] && y < hb[3]),
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; draw(tval(tw, performance.now())); }, destroy: bag.dispose };
}

hairline({
  name: "cancrusher",
  means: "A wall can crusher: the long lever swings down from its hinge and drives the press plate onto the can, squashing it.",
  rules: [1, 3, 4, 5, 6],
  range: [0.5, 1, 1.3],
  tour: [[202, 99], [140, 130], [274, 197], null],
  mount,
});

woodstove.code:
/**
 * Wood stove: a cast-iron firebox on four short legs, a top plate and a
 * flue pipe rising from it, a glass-fronted door on its front face. The
 * pointer over the stove swings the door open on its hinge, wider the
 * nearer it comes to the handle, and the fire inside flares in the draft.
 * At rest the door stands ajar, bright. The slider is how far it opens.
 *
 * The pattern: one part swinging on a hinge (single object).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 40, BY = 50, Z0 = 8, Z1 = 44, HY = 6, W = 38, DZ0 = 11, DZ1 = 40, REST = 16, T = 2.2;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.6);
  const ex = BX + W * Math.sin(rad(130)), ey = HY + W * Math.cos(rad(130));
  fit(C, [[-2, -2, 0], [BX + 2, BY + 2, 0], [-2, BY + 2, 0], [BX + 2, -2, 0], [18, 22, 74], [ex, ey, DZ1], [ex, ey, DZ0], [BX + 2, BY + 2, 47]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // legs, far to near
  for (const [x, y] of [[4, 4], [4, BY - 4], [BX - 4, 4], [BX - 4, BY - 4]]) put(solid(g), prism(P, front, disc(x, y, 2.6), disc(x, y, 1.6), 0, Z0 + 1));
  // firebox and top plate
  const [br, bi] = rings(0, 0, BX, BY, 4, 1.5);
  put(solid(g), prism(P, front, br, bi, Z0, Z1));
  const [tr, ti] = rings(-2, -2, BX + 2, BY + 2, 4, 1.5);
  put(solid(g), prism(P, front, tr, ti, Z1, Z1 + 3));
  // flue pipe with a collar
  put(solid(g), prism(P, front, disc(18, 22, 7.5, 28), disc(18, 22, 6, 28), Z1 + 3, Z1 + 6));
  put(solid(g), prism(P, front, disc(18, 22, 5.5, 28), disc(18, 22, 4.2, 28), Z1 + 6, 74));
  // the opening on the front face, logs and fire inside it
  const F = (y, z) => P(BX, y, z);
  mk("path", { d: poly([F(HY + 2, DZ0 + 2), F(HY + 2, DZ1 - 2), F(HY + W - 2, DZ1 - 2), F(HY + W - 2, DZ0 + 2)]), class: "lo" }, g);
  mk("path", { d: open([F(HY + 6, DZ0 + 5), F(HY + W - 8, DZ0 + 8)]) + open([F(HY + 9, DZ0 + 8), F(HY + W - 5, DZ0 + 5)]), class: "nf lo" }, g);
  const flame = mk("path", { class: "nf" }, g);
  const door = mk("path", { class: "sil" }, g), glass = mk("path", { class: "nf lo" }, g), handle = mk("path", { class: "nf" }, g);
  mk("path", { d: open([F(HY, DZ0 + 4), F(HY, DZ0 + 7)]) + open([F(HY, DZ1 - 7), F(HY, DZ1 - 4)]), class: "nf" }, g);

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.05) return;
    last = a;
    const s = Math.sin(rad(a)), c = Math.cos(rad(a));
    const at = (u, z, o) => P(BX + u * s + o * c, HY + u * c - o * s, z);
    door.setAttribute("d", poly(hull([at(0, DZ0, 0), at(W, DZ0, 0), at(W, DZ1, 0), at(0, DZ1, 0), at(0, DZ0, T), at(W, DZ0, T), at(W, DZ1, T), at(0, DZ1, T)])));
    glass.setAttribute("d", poly([at(6, DZ0 + 6, T), at(W - 8, DZ0 + 6, T), at(W - 8, DZ1 - 6, T), at(6, DZ1 - 6, T)]) + open([at(10, DZ0 + 10, T), at(18, DZ1 - 10, T)]));
    handle.setAttribute("d", open([at(W - 3.5, DZ0 + 11, T), at(W - 3.5, DZ0 + 11, T + 3.5), at(W - 3.5, DZ1 - 11, T + 3.5), at(W - 3.5, DZ1 - 11, T)]));
    const k = clamp((a - REST) / 100, 0, 1), top = DZ0 + 14 + 13 * k, m = HY + W / 2;
    flame.setAttribute("d", poly([F(m - 9, DZ0 + 7), F(m - 6, DZ0 + 13 + 5 * k), F(m - 3, DZ0 + 11), F(m + 1, top), F(m + 4, DZ0 + 12), F(m + 7, DZ0 + 15 + 6 * k), F(m + 10, DZ0 + 7)]));
  }
  draw(REST);

  const B = register(stage, (dt) => {
    const moving = stepS(ang, dt);
    draw(ang.x);
    return moving;
  });
  bag.add(B.unregister);

  // hit area: the stove's rest outline on screen; reach falls off from the closed door's handle
  const box = hull([...[[0, 0], [BX, 0], [BX, BY], [0, BY]].flatMap(([x, y]) => [P(x, y, 0), P(x, y, Z1 + 3)]), P(18, 22, 74)]);
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const bx0 = Math.min(...xs) - 4, bx1 = Math.max(...xs) + 4, by0 = Math.min(...ys) - 4, by1 = Math.max(...ys) + 4;
  const hp = P(BX, HY + W - 3.5, (DZ0 + DZ1) / 2);
  let on = null;
  function move([sx, sy]) {
    const inside = sx > bx0 && sx < bx1 && sy > by0 && sy < by1;
    if (inside) {
      const f = clamp(1 - Math.hypot(sx - hp[0], sy - hp[1]) / 260, 0.45, 1);
      ang.t = REST + (max - REST) * f;
    } else ang.t = REST;
    if (inside !== on) { on = inside; door.classList.add("hi"); }
    read.textContent = inside ? "door " + Math.round(ang.t) + "°" : "rest";
    B.wake();
  }
  door.classList.add("hi");
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => move([-999, -999]) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { ang.t = REST + (max - REST) * 0.9; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "woodstove",
  means: "A wood stove on short legs with a flue: the pointer swings its glass door open, wider near the handle, and the fire flares.",
  rules: [1, 3, 5, 8],
  range: [50, 105, 125],
  tour: [[188, 185], [162, 58], [151, 270], null],
  mount,
});

eggchair.code:
/**
 * Eggchair: a hanging egg chair. A round foot, an arched stand and a short
 * chain hold a woven egg pod with its mouth and seat cushion turned to the
 * viewer. The pointer's side of the stand is where the pod swings; the slider
 * sets how far. At rest it hangs a little aside, its shell bright.
 *
 * The pattern: a continuous aim (one spring on the swing angle); the hit is the
 * pointer's screen x against the fixed pivot, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, spring, stepS, clamp, rad, hull,
  disposer, mk, pointer, put, register, solid, poly, seg,
} = HL;

const ZP = 135, LC = 12, H = 100, R = 40, F0 = Math.PI / 4, REST = rad(9), A = rad(32);
const K = [Math.SQRT1_2, Math.SQRT1_2, 0];
const rad_ = (t) => R * Math.pow(Math.sin(Math.PI * t), 0.6) * (0.86 + 0.14 * t);
const surf = (t, th, f) => [rad_(t) * f * Math.cos(th), rad_(t) * f * Math.sin(th), -LC - H * t];
function swing(v, a) {
  const c = Math.cos(a), s = Math.sin(a), d = K[0] * v[0] + K[1] * v[1];
  const cx = [K[1] * v[2], -K[0] * v[2], K[0] * v[1] - K[1] * v[0]];
  return [v[0] * c + cx[0] * s + K[0] * d * (1 - c), v[1] * c + cx[1] * s + K[1] * d * (1 - c), ZP + v[2] * c + cx[2] * s];
}
const POD = [];
for (let i = 0; i <= 14; i++) for (let j = 0; j < 24; j++) POD.push(surf(i / 14, (j / 24) * Math.PI * 2, 1));
const loop = (tc, ts, span, f) => {
  const o = [];
  for (let i = 0; i < 36; i++) { const s = (i / 36) * Math.PI * 2; o.push(surf(tc + ts * Math.sin(s), F0 + span * Math.cos(s), f)); }
  return o;
};
const MOUTH = loop(0.5, 0.3, 1.2, 1), SEAT = loop(0.74, 0.1, 0.85, 0.8);
const POLE = [];
for (let i = 0; i <= 20; i++) {
  const t = i / 20, u = 1 - t, b = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
  const p = [[-34, -10, 4], [-140, -30, 90], [-85, -14, 192], [0, 0, ZP + 8]];
  POLE.push([0, 1, 2].map((k) => b[0] * p[0][k] + b[1] * p[1][k] + b[2] * p[2][k] + b[3] * p[3][k]));
}

function band(pts, w) {
  const L = [], Rr = [];
  for (let i = 0; i < pts.length; i++) {
    const p = pts[Math.max(0, i - 1)], q = pts[Math.min(pts.length - 1, i + 1)];
    const dx = q[0] - p[0], dy = q[1] - p[1], m = Math.hypot(dx, dy) || 1;
    L.push([pts[i][0] - (dy / m) * w, pts[i][1] + (dx / m) * w]);
    Rr.push([pts[i][0] + (dy / m) * w, pts[i][1] - (dx / m) * w]);
  }
  return poly(L.concat(Rr.reverse()));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.5);
  const ext = POLE.slice();
  for (const a of [-A * 1.3, A * 1.3]) for (let i = 0; i < POD.length; i += 7) ext.push(swing(POD[i], a));
  for (let k = 0; k < 8; k++) ext.push([40 * Math.cos(k), 40 * Math.sin(k), 0]);
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let amp = value;

  put(solid(g), prism(P, front, circ(40, 32), circ(37.5, 32), 0, 4));
  mk("path", { class: "sil", d: band(POLE.map((q) => P(...q)), 3) }, g);
  const chain = mk("path", { class: "lo nf" }, g);
  const pod = mk("path", { class: "sil" }, g);
  const mouth = mk("path", {}, g);
  const seat = mk("path", { class: "lo" }, g);
  const pv = P(0, 0, ZP);

  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const S = (v) => P(...swing(v, a));
    chain.setAttribute("d", seg(pv, S([0, 0, -LC])));
    pod.setAttribute("d", poly(hull(POD.map(S))));
    mouth.setAttribute("d", poly(MOUTH.map(S)));
    seat.setAttribute("d", poly(SEAT.map(S)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function mark(label) { pod.classList.add("hi"); read.textContent = label; B.wake(); }
  const rest = () => { sp.t = REST; mark("rest"); };

  bag.add(pointer(stage, {
    move: (p) => {
      const dx = p[0] - pv[0];
      if (Math.abs(dx) > 190) { rest(); return; }
      const a = clamp(dx / 110, -1, 1) * A * amp;
      sp.t = -a;
      mark((a < 0 ? "-" : "+") + String(Math.round(Math.abs(a) * 180 / Math.PI)).padStart(2, "0") + "°");
    },
    leave: rest,
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  rest();
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

