mokapot.code:
/**
 * Moka pot: an eight-sided stovetop pot, its lower boiler screwed to the
 * upper jug, a hinged lid, a pouring spout and a side handle. The pointer
 * on the jug flips the lid open on its hinge; on the boiler the jug unscrews,
 * twisting and lifting off the threaded collar. At rest the lid sits ajar,
 * bright. The slider is how far the pot opens.
 *
 * The pattern: one object, two parts answering (cloches).
 */
const {
  Cam, fit, facing, hull, open, poly, proj, run, clamp, rad, tset, tval, tdone, tween,
  disposer, mk, pointer, register, solid,
} = HL;

const S8 = Math.cos(Math.PI / 8);
// a rounded octagon ring of radius R, corner radius r
function oct(R, r = 2.4) {
  const out = [], c = R - r / S8;
  for (let i = 0; i < 8; i++) {
    const a = rad(i * 45 + 22.5 - 45);
    for (let j = 0; j <= 3; j++) {
      const b = a - rad(22.5) + (j / 3) * rad(45);
      out.push({ u: c * Math.cos(a) + r * Math.cos(b), v: c * Math.sin(a) + r * Math.sin(b), nu: Math.cos(b), nv: Math.sin(b) });
    }
  }
  return out;
}
const twist = (ring, t) => ring.map((q) => {
  const c = Math.cos(t), s = Math.sin(t);
  return { u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c };
});

const H = [-Math.SQRT1_2, Math.SQRT1_2], SP = [Math.SQRT1_2, -Math.SQRT1_2]; // handle side, spout side
const ZW = 30, ZU = 31, ZT = 64, RB = 22, RW = 16, RT = 21;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-30, -30, 0], [30, 30, 0], [0, 0, ZT + 34], [-40, 40, 40], [40, -40, 70]], 200, 172);
  const P = proj(C), front = facing(C);
  const ringAt = (ring, z) => ring.map((q) => P(q.u, q.v, z));
  const g = mk("g", {}, svg);

  // the boiler: a frustum, then the threaded collar
  const base = solid(g);
  base.sil.setAttribute("d", poly(hull(ringAt(oct(RB), 0).concat(ringAt(oct(RW + 1), ZW)))));
  base.cr.setAttribute("d", open(ringAt(run(oct(RW - 0.5), front), ZW)));
  const valve = mk("ellipse", { class: "dot m", rx: 1.8, ry: 1.8 }, g);
  const vp = P(SP[0] * 17 + 9, SP[1] * 17 + 9, 14); valve.setAttribute("cx", vp[0]); valve.setAttribute("cy", vp[1]);
  const collar = solid(g);
  collar.sil.setAttribute("d", poly(hull(ringAt(oct(RW - 2), ZW).concat(ringAt(oct(RW - 2), ZW + 6)))));
  collar.cr.setAttribute("d", open(ringAt(run(oct(RW - 3.2), front), ZW + 3)));

  const jug = solid(g), handle = mk("path", { class: "sil" }, g), spout = mk("path", { class: "sil" }, g);
  const lid = solid(g), knob = mk("path", {}, g);

  const st = { lift: tween(0), tw: tween(0), lid: tween(14) };
  let last = "";
  function at(x, y, z, L, T) { const c = Math.cos(T), s = Math.sin(T); return P(x * c - y * s, x * s + y * c, z + L); }
  function capsule(a, b, r, L, T) {
    const pts = [];
    for (const [x, y, z] of [a, b]) for (let i = 0; i < 12; i++) { const t = (i / 12) * Math.PI * 2; pts.push(at(x + r * Math.cos(t), y + r * Math.sin(t), z, L, T), at(x + r * Math.cos(t), y + r * Math.sin(t), z + r * 1.4, L, T)); }
    return poly(hull(pts));
  }
  function draw(L, T, th) {
    const key = [L, T, th].map((n) => n.toFixed(2)).join();
    if (key === last) return;
    last = key;
    jug.sil.setAttribute("d", poly(hull(ringAt(twist(oct(RW), T), ZU + L).concat(ringAt(twist(oct(RT), T), ZT + L)))));
    jug.cr.setAttribute("d", open(ringAt(run(twist(oct(RT - 1.8), T), front), ZT + L)));
    const hx = (d, z) => [H[0] * d, H[1] * d, z];
    handle.setAttribute("d", capsule(hx(18, 55), hx(34, 54), 2.6, L, T) + capsule(hx(34, 54), hx(37, 34), 2.6, L, T));
    const sp = [];
    for (const [d, w, z] of [[RT - 1, 5, ZT], [RT - 1, 5, ZT - 9], [RT + 9, 0.6, ZT + 2], [RT + 1, 0.6, ZT - 13]]) {
      sp.push(at(SP[0] * d + SP[1] * w, SP[1] * d - SP[0] * w, z, L, T), at(SP[0] * d - SP[1] * w, SP[1] * d + SP[0] * w, z, L, T));
    }
    spout.setAttribute("d", poly(hull(sp)));
    // the lid: rotate about the hinge on the handle side, then twist and lift
    const a = rad(-th), ca = Math.cos(a), sa = Math.sin(a), ax = [Math.SQRT1_2, Math.SQRT1_2];
    const hp = [H[0] * RT, H[1] * RT, ZT + 0.5];
    const tilt = (x, y, z) => {
      const v = [x - hp[0], y - hp[1], z - hp[2]], d = ax[0] * v[0] + ax[1] * v[1];
      const cr = [ax[1] * v[2], -ax[0] * v[2], ax[0] * v[1] - ax[1] * v[0]];
      return [hp[0] + v[0] * ca + cr[0] * sa + ax[0] * d * (1 - ca), hp[1] + v[1] * ca + cr[1] * sa + ax[1] * d * (1 - ca), hp[2] + v[2] * ca + cr[2] * sa];
    };
    const lp = (q, z) => { const p = tilt(q.u, q.v, z); return at(p[0], p[1], p[2], L, T); };
    const o = oct(RT + 0.6), oi = oct(RT - 3);
    lid.sil.setAttribute("d", poly(hull(o.map((q) => lp(q, ZT + 0.5)).concat(oi.map((q) => lp(q, ZT + 5))))));
    lid.cr.setAttribute("d", poly(oct(RT - 4.5).map((q) => lp(q, ZT + 5))));
    const kn = [];
    for (const q of oct(3.4, 1.2)) kn.push(lp(q, ZT + 5), lp(q, ZT + 9.5));
    knob.setAttribute("d", poly(hull(kn)));
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(st.lift, now), tval(st.tw, now), tval(st.lid, now));
    return !(tdone(st.lift, now) && tdone(st.tw, now) && tdone(st.lid, now));
  });
  bag.add(B.unregister);

  // hit test on the rest pose: the pot's screen box, split at the collar
  const box = [[-RT, -RT, 0], [RT, RT, 0], [-RT, RT, ZT + 9], [RT, -RT, ZT], [0, 0, ZT + 9]].map((p) => P(...p));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]), yw = P(0, 0, ZW + 3)[1];
  const X0 = Math.min(...xs) - 10, X1 = Math.max(...xs) + 10, Y0 = Math.min(...ys) - 8, Y1 = Math.max(...ys) + 4;
  function hit([sx, sy]) {
    if (sx < X0 || sx > X1 || sy < Y0 || sy > Y1) return "rest";
    return sy < yw ? "lid" : "base";
  }

  let act = "", tgt = null;
  function apply() {
    const now = performance.now();
    const T = act === "lid" ? [6, 0, 95] : act === "base" ? [30, 40, 30] : [0, 0, 14];
    tset(st.lift, T[0] * (act === "rest" ? 1 : amp), now, 0);
    tset(st.tw, rad(T[1] * (act === "rest" ? 1 : amp)), now, 40);
    tset(st.lid, T[2] * (act === "rest" ? 1 : amp), now, act === "base" ? 120 : 0);
    B.wake();
  }
  function setActive(a) {
    if (a === act) return;
    act = a;
    lid.sil.classList.toggle("hi", a !== "base");
    base.sil.classList.toggle("hi", a === "base");
    read.textContent = a;
    apply();
  }
  setActive("rest");
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive("rest") }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 0.2, 1); act !== "rest" && apply(); }, destroy: bag.dispose };
}

hairline({
  name: "mokapot",
  means: "A stovetop moka pot: on the jug its hinged lid flips open; on the boiler the jug twists and lifts off its threaded collar.",
  rules: [1, 3, 5, 6],
  range: [0.3, 0.8, 1],
  tour: [[200, 104], [198, 235], [167, 155], null],
  mount,
});

cardshuffler.code:
/**
 * Card shuffler: a box with two half-decks waiting in its top trays, a crank
 * on a post between them and a drawer at the front. The pointer on the
 * shuffler turns the crank: the half-decks sink as their cards drop, and the
 * drawer slides out holding the shuffled stack. At rest the crank sits a
 * quarter turn round, bright. The slider is how far the crank is turned.
 *
 * The pattern: one object, one gesture (cloches).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, run, clamp, rad, tset, tval, tdone, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 60, BY = 36, BZ = 20, PX = 30, PY = 18, PZ = 40, ARM = 15;
const DECKS = [[4, 7, 26, 29, 12], [34, 7, 56, 29, 10]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [BX, 0, 0], [0, BY + 26, 0], [BX, BY + 26, 0], [PX, PY, PZ + 8], [PX + ARM, PY - ARM, PZ + 8], [PX - ARM, PY + ARM, PZ + 8]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, z0, z1, r = 2.5, b = 1.4) => { const s = solid(parent); const [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };

  // the drawer sits under the body's front face, so it is painted after it
  box(g, 0, 0, BX, BY, 0, BZ, 4, 1.8);
  for (const [x0, y0, x1, y1] of DECKS) box(g, x0 - 1.5, y0 - 1.5, x1 + 1.5, y1 + 1.5, BZ, BZ + 1.6, 2, 0.8);

  const deckG = DECKS.map(() => mk("g", {}, g));
  const post = mk("g", {}, g);
  box(post, PX - 2.6, PY - 2.6, PX + 2.6, PY + 2.6, BZ, PZ, 2.6, 1);
  g.insertBefore(post, deckG[1]);
  const arm = mk("path", { class: "sil" }, g), knob = mk("path", { class: "sil" }, g);
  const drawer = mk("g", {}, g);

  const st = { turn: tween(0), out: tween(0) };
  let last = "";
  function cyl(cx, cy, r, z0, z1) {
    const pts = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; pts.push(P(cx + r * Math.cos(t), cy + r * Math.sin(t), z0), P(cx + r * Math.cos(t), cy + r * Math.sin(t), z1)); }
    return poly(hull(pts));
  }
  function draw(t, o) {
    const key = t.toFixed(3) + "," + o.toFixed(3);
    if (key === last) return;
    last = key;
    // the half-decks sink as the crank turns
    DECKS.forEach(([x0, y0, x1, y1, h], k) => {
      const gk = deckG[k], top = BZ + 1.6 + Math.max(1.2, h * (1 - 0.85 * t));
      gk.replaceChildren();
      const [rg, ri] = rings(x0, y0, x1, y1, 1.6, 1);
      put(solid(gk), prism(P, front, rg, ri, BZ + 1.6, top));
      for (let z = BZ + 4; z < top - 1.5; z += 3) mk("path", { class: "nf lo", d: open(ringAt(P, run(rg, front), z)) }, gk);
    });
    // the crank: an arm from the post to a knob
    const a = rad(-75 + 300 * t), ex = PX + ARM * Math.cos(a), ey = PY + ARM * Math.sin(a);
    const pts = [];
    for (const [x, y] of [[PX, PY], [ex, ey]]) for (let i = 0; i < 12; i++) { const q = (i / 12) * Math.PI * 2; pts.push(P(x + 2.4 * Math.cos(q), y + 2.4 * Math.sin(q), PZ), P(x + 2.4 * Math.cos(q), y + 2.4 * Math.sin(q), PZ + 2.6)); }
    arm.setAttribute("d", poly(hull(pts)));
    knob.setAttribute("d", cyl(ex, ey, 2.2, PZ + 2.6, PZ + 9));
    // the drawer: floor, the shuffled stack, then its front plate
    drawer.replaceChildren();
    const d = 3 + 22 * o, y1 = BY + d;
    box(drawer, 8, BY - 1, 52, y1, 2, 3.4, 2, 0.8);
    const sh = 1 + 9 * t;
    const [cr, ci] = rings(14, BY, 46, Math.max(BY + 1.5, y1 - 2), 1.6, 0.7);
    if (d > 6) { put(solid(drawer), prism(P, front, cr, ci, 3.4, 3.4 + sh)); for (let z = 6; z < 3.4 + sh - 1.5; z += 3) mk("path", { class: "nf lo", d: open(ringAt(P, run(cr, front), z)) }, drawer); }
    box(drawer, 6, y1, 54, y1 + 2.4, 1.5, 13, 1.2, 0.6);
    const pull = mk("path", { class: "nf lo", d: open([P(24, y1 + 2.4, 8), P(36, y1 + 2.4, 8)]) }, drawer);
    pull.setAttribute("class", "nf");
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(st.turn, now), tval(st.out, now));
    return !(tdone(st.turn, now) && tdone(st.out, now));
  });
  bag.add(B.unregister);

  // hit test on the rest pose: the shuffler's screen box
  const sc = [[0, 0, 0], [BX, 0, 0], [0, BY + 6, 0], [BX, BY + 6, 0], [PX, PY, PZ + 9], [0, 0, BZ + 14], [BX, BY, BZ]].map((p) => P(...p));
  const xs = sc.map((p) => p[0]), ys = sc.map((p) => p[1]);
  const X0 = Math.min(...xs), X1 = Math.max(...xs), Y0 = Math.min(...ys) - 6, Y1 = Math.max(...ys);
  const hit = ([sx, sy]) => sx > X0 && sx < X1 && sy > Y0 && sy < Y1;

  let act = null;
  function apply() {
    const now = performance.now();
    tset(st.turn, act ? amp : 0.08, now, 0);
    tset(st.out, act ? amp : 0, now, act ? 140 : 0);
    B.wake();
  }
  function setActive(a) {
    if (a === act) return;
    act = a;
    arm.classList.toggle("hi", true);
    knob.classList.toggle("hi", true);
    read.textContent = a ? "crank" : "rest";
    apply();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 0.2, 1); if (act) apply(); }, destroy: bag.dispose };
}

hairline({
  name: "cardshuffler",
  means: "A card shuffler: the pointer turns its crank, the two half-decks sink into the box and the drawer slides out with the shuffled stack.",
  rules: [1, 3, 5, 6],
  range: [0.3, 0.9, 1],
  tour: [[228, 89], [253, 188], [170, 150], null],
  mount,
});

dumper.code:
/**
 * Dumper: a site dumper, the small four-wheeled kind, with a deep skip over
 * its front wheels and the driver's seat under a roll bar behind it. The
 * pointer's place across the frame tips the skip forward on its front hinge,
 * its back rising over the bonnet. At rest the skip sits cracked a few
 * degrees, bright. The slider is how far it tips.
 *
 * The pattern: one hinged part (swing).
 */
const { Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 112, W = 50, Z0 = 12, ZB = 24, HX = 106, SL = 50, SH = 30, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.0);
  const sp = (y, d, h, a) => [HX - d * Math.cos(rad(a)) + h * Math.sin(rad(a)), y, ZB + d * Math.sin(rad(a)) + h * Math.cos(rad(a))];
  fit(C, [[0, 0, 0], [L + 10, W, 0], [0, W, 0], [L, 0, 0], [0, 4, ZB + 40], sp(0, SL + 4, SH, 100), sp(W, -8, SH, 100), sp(0, SL + 4, SH, 0)], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y, r) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(x + r * Math.cos(t), y, r + r * Math.sin(t))); }
    return pts;
  };
  const wheels = (y) => { mk("path", { d: poly(wheel(22, y, 12)) }, g); mk("path", { d: poly(wheel(HX - 14, y, 15)) }, g); };
  wheels(3);
  const [chr, chi] = rings(4, 7, L - 4, W - 7, 4, 1.2);
  put(solid(g), prism(P, front, chr, chi, Z0, ZB));
  const [ser, sei] = rings(10, 12, 32, W - 12, 4, 1.2);
  put(solid(g), prism(P, front, ser, sei, ZB, ZB + 9));
  mk("path", { d: seg(P(12, 14, ZB + 9), P(8, 14, ZB + 24)) + seg(P(12, W - 14, ZB + 9), P(8, W - 14, ZB + 24)), class: "nf lo" }, g);
  mk("path", { d: open([P(6, 6, ZB), P(4, 6, ZB + 40), P(4, W - 6, ZB + 40), P(6, W - 6, ZB)]), class: "nf" }, g);
  mk("path", { d: seg(P(40, W / 2, ZB), P(46, W / 2, ZB + 16)), class: "nf lo" }, g);
  const sw = [];
  for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; sw.push(P(44 + 2 * Math.sin(t), W / 2 + 7 * Math.cos(t), ZB + 17 + 6 * Math.sin(t))); }
  mk("path", { d: poly(sw), class: "nf" }, g);
  const skip = mk("path", { class: "sil hi" }, g), rim = mk("path", { class: "nf lo" }, g);
  wheels(W - 3);
  const ang = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const y of [0, W]) for (const [d, h] of [[0, 0], [SL, 0], [SL + 4, SH], [-8, SH]]) pts.push(P(...sp(y, d, h, a)));
    skip.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly([sp(4, SL, SH, a), sp(4, -4, SH, a), sp(W - 4, -4, SH, a), sp(W - 4, SL, SH, a)].map((p) => P(...p))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(a, r) { ang.t = a; read.textContent = r ? "rest" : Math.round(a) + "°"; B.wake(); }
  draw(REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(REST + clamp((sx - 60) / 220, 0, 1) * (max - REST)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "dumper",
  means: "A site dumper with its skip hinged over the front wheels: the pointer tips the skip forward, its back rising high.",
  rules: [1, 3, 5, 6],
  range: [45, 80, 100],
  tour: [[211, 140], [253, 255], [112, 184], null],
  mount,
});

trencher.code:
/**
 * Trencher: a ride-on trencher, a squat wheeled body with its engine up front
 * and the seat behind, and the long chain boom hinged at the tail. The
 * pointer's place across the frame lowers the boom from its carried pose down
 * into the cut, the trench marked dashed behind it. At rest the boom rides
 * raised, bright. The slider is how deep it goes.
 *
 * The pattern: one hinged part (swing).
 */
const { Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 74, W = 48, PZ = 30, BL = 92, BT = 7, BW = 6, REST = 32;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.75);
  const bp = (y, d, h, a) => P0(-d * Math.cos(rad(a)) - h * Math.sin(rad(a)), y, PZ + d * Math.sin(rad(a)) - h * Math.cos(rad(a)));
  let P0 = (x, y, z) => [x, y, z];
  const ext = [];
  for (const a of [REST, REST - 85]) for (const h of [-BT, BT]) ext.push(bp(W / 2, BL, h, a));
  fit(C, [[0, 0, 0], [L, W, 0], [0, W, 0], [L, 0, 0], [40, W / 2, 52], [-BL, W / 2, 0]].concat(ext), 200, 166);
  const P = proj(C), front = facing(C);
  P0 = P;
  const g = mk("g", {}, svg);
  mk("path", { d: poly([P(-BL + 6, W / 2 - 4, 0), P(-4, W / 2 - 4, 0), P(-4, W / 2 + 4, 0), P(-BL + 6, W / 2 + 4, 0)]), class: "nf dash" }, g);
  const boom = mk("path", { class: "sil hi" }, g), chain = mk("path", { class: "nf lo" }, g);
  const wheel = (x, y, r) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(x + r * Math.cos(t), y, r + r * Math.sin(t))); }
    return pts;
  };
  const wheels = (y) => { for (const x of [16, 58]) mk("path", { d: poly(wheel(x, y, 14)) }, g); };
  wheels(2);
  mk("path", { d: open([P(2, W / 2 - 6, 18), P(-3, W / 2 - 6, PZ), P(-3, W / 2 + 6, PZ), P(2, W / 2 + 6, 18)]), class: "nf" }, g);
  const [br, bi] = rings(0, 6, L, W - 6, 5, 1.4);
  put(solid(g), prism(P, front, br, bi, 12, 30));
  const [sr, si] = rings(8, 14, 24, W - 14, 4, 1.2);
  put(solid(g), prism(P, front, sr, si, 30, 38));
  mk("path", { d: seg(P(9, 16, 38), P(5, 16, 50)) + seg(P(9, W - 16, 38), P(5, W - 16, 50)), class: "nf lo" }, g);
  const [er, ei] = rings(36, 9, L - 2, W - 9, 6, 1.4);
  put(solid(g), prism(P, front, er, ei, 30, 50));
  mk("path", { d: seg(P(32, W / 2, 30), P(28, W / 2, 46)), class: "nf lo" }, g);
  wheels(W - 2);
  const ang = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const y of [W / 2 - BW, W / 2 + BW]) for (const d of [-4, BL]) for (const h of [-BT, BT]) pts.push(bp(y, d, h, a));
    boom.setAttribute("d", poly(hull(pts)));
    const yc = W / 2 + BW, ch = [];
    for (let i = 0; i <= 8; i++) { const t = -Math.PI / 2 + (i / 8) * Math.PI; ch.push(bp(yc, BL - 6 + 3.5 * Math.cos(t), 3.5 * Math.sin(t), a)); }
    chain.setAttribute("d", open([bp(yc, 4, -3.5, a)].concat(ch, [bp(yc, 4, 3.5, a)])));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(a, r) { ang.t = a; read.textContent = r ? "rest" : Math.round(a) + "°"; B.wake(); }
  draw(REST);
  aim(REST, true);
