  const ang = spring(REST);
  let last = NaN;
  const lp = (y, d, zl, a) => P(HX + d * Math.cos(rad(a)) - zl * Math.sin(rad(a)), y, HZ + d * Math.sin(rad(a)) + zl * Math.cos(rad(a)));
