snowplough.code:
/**
 * Snow plough: a short cab truck with a wide curved blade on its nose. The
 * pointer's place across the frame angles the blade, left or right, lifting it
 * a little as it swings. At rest the blade sits angled, bright. The slider is
 * how far it can angle.
 *
 * The pattern: one hinged part (yaw about a pin).
 */
const { Cam, clamp, facing, fit, hull, poly, prism, proj, rad, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 96, W = 48, Z0 = 9, PX = L + 14, BH = 30, BW = 92, REST = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [L, W, 0], [PX + 30, W / 2 - 50, 0], [PX + 30, W / 2 + 50, 0], [0, 0, 56], [PX, W / 2 + 50, BH + 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(x + 11 * Math.cos(t), y, 11 + 11 * Math.sin(t))); }
    return pts;
  };
  for (const x of [20, 74]) mk("path", { d: poly(wheel(x, 4)) }, g);
  const [chr, chi] = rings(0, 6, L, W - 6, 3, 1);
  put(solid(g), prism(P, front, chr, chi, Z0, 20));
  const [br, bi] = rings(2, 3, 52, W - 3, 4, 1.4);
  put(solid(g), prism(P, front, br, bi, 20, 40));
  const [cr, ci] = rings(56, 2, L, W - 2, 6, 1.6);
  put(solid(g), prism(P, front, cr, ci, 20, 56));
  mk("path", { d: seg(P(L, 8, 44), P(L, W - 8, 44)), class: "nf lo" }, g);
  for (const x of [20, 74]) mk("path", { d: poly(wheel(x, W - 4)) }, g);
  const arms = mk("path", { class: "nf" }, g);
  const blade = mk("path", { class: "sil hi" }, g), lip = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST), lift = spring(4);
  let last = "";

  // blade point: s along its width (-1..1), curl c (0 at the face, depth by height), z height
  function bp(a, h, s, z, back) {
    const cu = 8 * Math.sin((z / BH) * Math.PI) + back;
    const lx = 12 - cu, ly = s * BW / 2;
    const c = Math.cos(rad(a)), sn = Math.sin(rad(a));
    return P(PX + lx * c - ly * sn, W / 2 + lx * sn + ly * c, z + h);
  }
  function draw() {
    const a = ang.x, h = lift.x, key = a.toFixed(2) + h.toFixed(2);
    if (key === last) return;
    last = key;
    const pts = [];
    for (const s of [-1, -0.5, 0, 0.5, 1]) for (const z of [2, BH / 2, BH]) for (const b of [0, 5]) pts.push(bp(a, h, s, z, b));
    blade.setAttribute("d", poly(hull(pts)));
    lip.setAttribute("d", seg(bp(a, h, -0.97, 4, 0), bp(a, h, 0.97, 4, 0)) + seg(bp(a, h, -0.97, BH - 3, 0), bp(a, h, 0.97, BH - 3, 0)));
    arms.setAttribute("d", seg(P(L, 12, 16), bp(a, h, -0.25, 12, 6)) + seg(P(L, W - 12, 16), bp(a, h, 0.25, 12, 6)));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt), n = stepS(lift, dt); draw(); return m || n; });
  bag.add(B.unregister);

  function aim(a, r) { ang.t = a; lift.t = r ? 4 : 4 + 10 * Math.abs(a) / 45; read.textContent = r ? "rest" : (a < 0 ? "L " : "R ") + Math.abs(Math.round(a)) + "°"; B.wake(); }
  draw();
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(clamp((sx - 200) / 140, -1, 1) * max), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "snowplough",
  means: "A snow plough truck with a wide curved blade on its nose: the pointer angles the blade left or right, lifting it as it swings.",
  rules: [1, 3, 5, 6],
  range: [20, 35, 45],
  tour: [[80, 160], [320, 160], [200, 200], null],
  mount,
});

gritter.code:
/**
 * Gritter lorry: a cab, a tipped V hopper of salt, and a spinner disc hung
 * under its tail. The pointer's place across the frame spins the disc round
 * and throws a fan of grit behind it, wider and further the further across.
 * At rest the disc is bright and a little grit lies close. The slider is how
 * far the grit is thrown.
 *
 * The pattern: one turning part with a spread it throws.
 */
const { Cam, clamp, circ, facing, fit, hull, poly, prism, proj, rad, rings, ringAt, seg, spring, stepS, disposer, mk, pointer, place, put, register, solid } = HL;

const L = 112, W = 46, Z0 = 9, SX = L + 10, SZ = 12, SR = 15, N = 42;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[0, 0, 0], [0, W, 0], [L, 0, 60], [SX + 70, W / 2 - 40, 0], [SX + 70, W / 2 + 40, 0], [0, 0, 56]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => poly(Array.from({ length: 24 }, (_, i) => { const t = (i / 24) * Math.PI * 2; return P(x + 11 * Math.cos(t), y, 11 + 11 * Math.sin(t)); }));
  for (const x of [22, 88]) mk("path", { d: wheel(x, 4) }, g);
  const [chr, chi] = rings(0, 6, L, W - 6, 3, 1);
  put(solid(g), prism(P, front, chr, chi, Z0, 20));
  const [cr, ci] = rings(0, 2, 36, W - 2, 6, 1.6);
  put(solid(g), prism(P, front, cr, ci, 20, 54));
  mk("path", { d: seg(P(0, 8, 42), P(0, W - 8, 42)), class: "nf lo" }, g);
  // the V hopper: a narrow foot, a wide top
  const hop = solid(g);
  const foot = rings(46, W / 2 - 8, L - 2, W / 2 + 8, 3, 1)[0], top = rings(42, 0, L + 2, W, 4, 1.4);
  hop.sil.setAttribute("d", poly(hull(ringAt(P, foot, 20).concat(ringAt(P, top[0], 58)))));
  hop.cr.setAttribute("d", poly(ringAt(P, top[1], 58)));
  for (const x of [22, 88]) mk("path", { d: wheel(x, W - 4) }, g);
  mk("path", { d: seg(P(L - 4, W / 2, 22), P(SX, W / 2, SZ + 3)), class: "nf" }, g);
  const disc = solid(g); disc.sil.classList.add("hi");
  const mv = (r) => r.map((q) => ({ ...q, u: q.u + SX, v: q.v + W / 2 }));
  put(disc, prism(P, front, mv(circ(SR, 32)), mv(circ(SR - 2, 32)), SZ - 2, SZ));
  const vanes = mk("path", { class: "nf" }, g);
  const grains = Array.from({ length: N }, () => mk("circle", { r: 2.2, class: "dot m" }, g));
  const spin = spring(0), reach = spring(0.25);
  let last = "";

  function draw() {
    const key = spin.x.toFixed(2) + reach.x.toFixed(3);
    if (key === last) return;
    last = key;
    let d = "";
    for (let k = 0; k < 4; k++) {
      const a = rad(spin.x + k * 90);
      d += seg(P(SX + 3 * Math.cos(a), W / 2 + 3 * Math.sin(a), SZ + 0.2), P(SX + (SR - 3) * Math.cos(a), W / 2 + (SR - 3) * Math.sin(a), SZ + 3));
    }
    vanes.setAttribute("d", d);
    const r = reach.x;
    grains.forEach((el, i) => {
      const ray = (i % 6) / 5 - 0.5, ring = Math.floor(i / 6) / 6;
      const a = rad(ray * 170 * r), dist = SR + 6 + (8 + ring * 70) * r;
      place(el, P(SX + dist * Math.cos(a), W / 2 + dist * Math.sin(a), 0));
    });
  }
  const B = register(stage, (dt) => { const m = stepS(spin, dt), n = stepS(reach, dt); draw(); return m || n; });
  bag.add(B.unregister);

  function aim(t, r) {
    reach.t = r ? 0.25 : 0.3 + 0.7 * t * max; spin.t = r ? 0 : 720 * t;
    read.textContent = r ? "rest" : Math.round(reach.t * 100) + "%"; B.wake();
  }
  draw();
  aim(0, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(clamp((sx - 40) / 300, 0, 1)), leave: () => aim(0, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "gritter",
  means: "A gritter lorry with a spinner disc under its tail: the pointer spins the disc and throws a fan of grit wider behind it.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[120, 160], [330, 200], [250, 230], null],
  mount,
});

jeep.code:
/**
 * Off-road jeep: a boxy body on four big wheels, the rear door hinged at one
 * side with the spare wheel bolted to it. The pointer's place across the
 * frame swings the door open, the spare wheel riding out with it. At rest the
 * door stands just ajar and the spare tyre is bright. The slider is how far
 * the door opens.
 *
 * The pattern: one hinged part (swing).
 */
const { Cam, clamp, facing, fit, hull, poly, prism, proj, rad, rings, ringAt, rrect, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 110, W = 62, Z0 = 12, ZB = 40, ZT = 66, HY = W - 3, GW = W - 6, R = 18, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [L, W, 0], [L + GW + 14, HY, 0], [0, 0, ZT], [L, W, ZT], [L + GW, HY, ZT]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y, r) => {
    const pts = [];
    for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push(P(x + r * Math.cos(t), y, 16 + r * Math.sin(t))); }
    return pts;
  };
  for (const x of [24, 88]) mk("path", { d: poly(wheel(x, 2, 16)) }, g);
  const [br, bi] = rings(0, 4, L, W - 4, 6, 1.4);
  put(solid(g), prism(P, front, br, bi, Z0, ZB));
  const foot = rrect(34, 4, L, W - 4, 6, 6), top = rrect(44, 8, L - 2, W - 8, 5, 6), inner = rrect(46, 10, L - 4, W - 10, 4, 6);
  const cab = solid(g);
  cab.sil.setAttribute("d", poly(hull(ringAt(P, foot, ZB).concat(ringAt(P, top, ZT)))));
  mk("path", { d: seg(P(38, W - 4, ZB + 2), P(46, W - 8, ZT - 2)), class: "nf lo" }, g);
  mk("path", { d: seg(P(72, W - 4, ZB + 2), P(72, W - 8, ZT - 2)), class: "nf lo" }, g);
  mk("path", { d: seg(P(4, W - 4, ZB - 3), P(34, W - 4, ZB - 3)), class: "nf lo" }, g);
  for (const x of [24, 88]) { mk("path", { d: poly(wheel(x, W, 16)) }, g); mk("path", { d: poly(wheel(x, W, 7)), class: "nf lo" }, g); }
  const gate = mk("path", {}, g), win = mk("path", { class: "nf lo" }, g);
  const tyre = mk("path", { class: "sil hi" }, g), hub = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST);
  let last = NaN;

  // a point on the door: d along it from the hinge, n out from its face, z up
  const gp = (a, d, n, z) => P(L + d * Math.sin(rad(a)) + n * Math.cos(rad(a)), HY - d * Math.cos(rad(a)) + n * Math.sin(rad(a)), z);
  const ring = (a, n, r) => {
    const pts = [];
    for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; pts.push(gp(a, GW / 2 + r * Math.cos(t), n, 34 + r * Math.sin(t))); }
    return pts;
  };
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const d of [0, GW]) for (const n of [0, 3]) for (const z of [Z0 + 2, ZT - 4]) pts.push(gp(a, d, n, z));
    gate.setAttribute("d", poly(hull(pts)));
    win.setAttribute("d", poly([gp(a, 6, 3, ZT - 8), gp(a, GW - 6, 3, ZT - 8), gp(a, GW - 6, 3, ZB + 4), gp(a, 6, 3, ZB + 4)]));
    tyre.setAttribute("d", poly(hull(ring(a, 4, R).concat(ring(a, 13, R)))));
    hub.setAttribute("d", poly(ring(a, 13, 8)));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(a, r) { ang.t = a; read.textContent = r ? "rest" : Math.round(a) + "°"; B.wake(); }
  draw(REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(REST + clamp((sx - 60) / 240, 0, 1) * (max - REST)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

