speedboat.code:
/**
 * Speedboat: a planing hull with a raked windscreen and a big outboard on
 * the transom. The pointer near the stern tilts the outboard up out of the
 * water, its leg swinging back; far away it rests trimmed down. The slider
 * is how far the motor tilts. At rest the cowling is bright.
 */
const {
  Cam, fit, hull, poly, proj, clamp, lerp, rad, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const L = 92, B = 34, H = 10, REST = 0.12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-40, -B / 2, 0], [L, B / 2, 0], [0, 0, H + 26], [-40, 0, H + 10], [0, 0, -30]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const half = (u) => (B / 2) * Math.pow(clamp((L - u) / (L * 0.55), 0, 1), 0.6);
  const ring = (z, k, dz) => { const a = []; for (let i = 0; i <= 24; i++) { const u = (i / 24) * L; a.push(P(u, half(u) * k, z + (dz ? dz * (u / L) : 0))); } for (let i = 24; i >= 0; i--) { const u = (i / 24) * L; a.push(P(u, -half(u) * k, z + (dz ? dz * (u / L) : 0))); } return a; };
  const leg = mk("path", { class: "sil" }, g), cowl = mk("path", { class: "sil hi" }, g), cowlCr = mk("path", { class: "nf lo" }, g);
  const body = mk("path", { class: "sil" }, g), rim = mk("path", { class: "nf" }, g), inner = mk("path", { class: "nf lo" }, g);
  const deck = mk("path", { class: "lo" }, g), screen = mk("path", { class: "sil" }, g);
  body.setAttribute("d", poly(hull(ring(0, 0.45, 0).concat(ring(H, 1, 4)))));
  rim.setAttribute("d", poly(ring(H, 1, 4)));
  inner.setAttribute("d", poly(ring(H - 1, 0.78, 4)));
  const ws = L * 0.5, hw = half(ws) * 0.86, zw = H + 2;
  deck.setAttribute("d", poly([P(ws, -hw, zw), P(ws + 26, 0, zw + 1.5), P(ws, hw, zw)]));
  screen.setAttribute("d", poly([P(ws, -hw, zw), P(ws - 6, -hw * 0.8, zw + 9), P(ws - 6, hw * 0.8, zw + 9), P(ws, hw, zw)]));
  const box = (x0, x1, y, z0, z1, a) => {
    const pts = [];
    for (const x of [x0, x1]) for (const yy of [-y, y]) for (const z of [z0, z1]) {
      const c = Math.cos(a), s = Math.sin(a);
      pts.push(P(-2 + x * c + z * s, yy, H + 2 - x * s + z * c));
    }
    return hull(pts);
  };
  const sp = spring(REST);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const a = rad(lerp(4, amp, t));
    leg.setAttribute("d", poly(box(-4, 3, 2.2, -34, 0, a)));
    cowl.setAttribute("d", poly(box(-14, 4, 7, 0, 18, a)));
    const c = box(-12.5, 2.5, 5.6, 16, 18, a);
    cowlCr.setAttribute("d", poly(c));
  }
  const Bk = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(Bk.unregister);
  const st = P(-6, 0, H + 10);
  function aim(t, label) { sp.t = t; read.textContent = label; Bk.wake(); }
  aim(REST, "rest");
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const t = clamp(1.25 - Math.hypot(sx - st[0], sy - st[1]) / 180, 0, 1); aim(t, t > 0.6 ? "tilt up" : "trim"); },
    leave: () => aim(REST, "rest"),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 30, 85); last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "speedboat",
  means: "A speedboat: the pointer near the stern tilts the big outboard up out of the water, its leg swinging back behind the transom.",
  rules: [1, 3, 5, 8],
  range: [30, 70, 85],
  tour: [[157, 97], [250, 190], [170, 112], null],
  mount,
});

paddlesteamer.code:
/**
 * Paddle steamer: a long hull with a deckhouse and a tall funnel, and one big
 * side paddle wheel. The pointer's place along the hull turns the wheel: its
 * boards sweep round through the water. At rest the wheel stands a little
 * turned, its rim bright. The slider is how far the wheel turns.
 *
 * The pattern: one part turning to the pointer.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 130, W = 34, HZ = 14, CX = 62, R = 30, CZ = 22, Y0 = W + 2, Y1 = W + 14, NB = 10, REST = 14;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [L, 0, 0], [0, Y1, 0], [L, Y1, 0], [CX, Y1, CZ + R], [CX, Y1, CZ - R], [L - 40, 14, HZ + 70]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [hr, hi] = rings(0, 0, L, W, 16, 2);
  put(solid(g), prism(P, front, hr, hi, 0, HZ));
  const [dr, di] = rings(28, 6, 100, W - 6, 4, 1.5);
  put(solid(g), prism(P, front, dr, di, HZ, HZ + 14));
  put(solid(g), prism(P, front, disc(L - 46, W / 2, 6), disc(L - 46, W / 2, 4.8), HZ + 14, HZ + 50));
  put(solid(g), prism(P, front, disc(34, W / 2, 1.2, 10), disc(34, W / 2, 0.6, 10), HZ + 14, HZ + 40));

  const wg = mk("g", {}, g);
  const far = mk("path", { class: "nf lo" }, wg);
  const boards = mk("path", {}, wg);
  const spokes = mk("path", { class: "nf lo" }, wg);
  const rim = mk("path", { class: "sil nf hi" }, wg);
  const hub = mk("path", { class: "nf" }, wg);
  const W3 = (r, a, y) => P(CX + r * Math.cos(a), y, CZ + r * Math.sin(a));
  const ring3 = (r, y) => { const o = []; for (let i = 0; i < 48; i++) o.push(W3(r, (i / 48) * 2 * Math.PI, y)); return o; };

  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a0 = (deg * Math.PI) / 180;
    far.setAttribute("d", poly(ring3(R, Y0)));
    rim.setAttribute("d", poly(ring3(R, Y1)));
    let bd = "", sd = "";
    for (let k = 0; k < NB; k++) {
      const a = a0 + (k / NB) * 2 * Math.PI;
      bd += poly([W3(R - 9, a, Y0), W3(R + 1, a, Y0), W3(R + 1, a, Y1), W3(R - 9, a, Y1)]);
      sd += seg(W3(4, a, Y1), W3(R, a, Y1));
    }
    boards.setAttribute("d", bd);
    spokes.setAttribute("d", sd);
    hub.setAttribute("d", poly(hull(ring3(4, Y0).concat(ring3(4, Y1 + 2)))));
  }

  const ang = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  function move([sx, sy]) {
    const [wx] = unproj(C, sx, sy, 0);
    const t = clamp((wx - CX) / (L / 2), -1, 1);
    ang.t = REST + t * reach;
    read.textContent = Math.round(ang.t) + "°";
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { ang.t = REST; read.textContent = "rest"; B.wake(); } }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

