/**
 * Glider: a slim sailplane with very long wings and a T-tail. The pointer's
 * x throws the two ailerons opposite ways and the glider banks after them.
 * The ailerons are the bright mark.
 */
const { Cam, fit, proj, hull, poly, clamp, spring, stepS, disposer, mk, pointer, register } = HL;
const S = 1.9, Z0 = 50;
const disc = (x, r, y = 0, z = Z0, n = 14) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([x, y + r * Math.cos(t), z + r * Math.sin(t)]); } return o; };
const box = (x0, x1, y0, y1, z0, z1) => { const o = []; [x0, x1].forEach((x) => [y0, y1].forEach((y) => [z0, z1].forEach((z) => o.push([x, y, z])))); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-2, -96, Z0 + 50], [-2, 96, Z0 - 50], [14, 96, Z0 - 50], [-60, 0, Z0 + 24], [40, 0, Z0 - 6]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const n = ["ailF", "wingF", "fin", "stab", "body", "canopy", "wingN", "ailN"];
  const el = {};
  n.forEach((k) => (el[k] = mk("path", { class: k === "canopy" ? "nf lo" : "sil" }, g)));
  el.ailF.classList.add("hi"); el.ailN.classList.add("hi");
  const phi = spring(0.5, { k: 60, c: 14 });
  let last = NaN;
  function draw() {
    if (phi.x === last) return; last = phi.x;
    const t = phi.x, r = clamp(0.12 + (t - 0.5) * 0.14, -0.55, 0.65), cr = Math.cos(r), sr = Math.sin(r);
    const d = clamp(0.18 + (t - 0.5) * 0.3, -0.7, 0.7);
    const T = (p) => { const y = p[1], z = p[2] - Z0; return P(p[0], y * cr - z * sr, Z0 + y * sr + z * cr); };
    const sh = (pts) => poly(hull(pts.map(T)));
    const ail = (y0, y1, s) => box(-10, -2, y0, y1, Z0 + 4, Z0 + 5).map(([x, y, z]) => { const u = x + 2, a = d * s; return [-2 + u * Math.cos(a), y, z - u * Math.sin(a)]; });
    el.ailF.setAttribute("d", sh(ail(-94, -54, 1)));
    el.ailN.setAttribute("d", sh(ail(54, 94, -1)));
    el.wingF.setAttribute("d", sh(box(-2, 14, -4, -4, Z0 + 4, Z0 + 6).concat(box(-2, 6, -95, -95, Z0 + 4, Z0 + 5))));
    el.wingN.setAttribute("d", sh(box(-2, 14, 4, 4, Z0 + 4, Z0 + 6).concat(box(-2, 6, 95, 95, Z0 + 4, Z0 + 5))));
    el.fin.setAttribute("d", sh(box(-62, -50, -1, 1, Z0 + 1, Z0 + 4).concat(box(-62, -56, -1, 1, Z0 + 22, Z0 + 22))));
    el.stab.setAttribute("d", sh(box(-64, -56, -20, 20, Z0 + 21, Z0 + 23)));
    el.body.setAttribute("d", sh(disc(-60, 1.5).concat(disc(-20, 3), disc(10, 6, 0, Z0 + 1), disc(30, 4), disc(40, 1.5))));
    el.canopy.setAttribute("d", poly(disc(20, 4.2, 0, Z0 + 4).filter((p) => p[2] >= Z0 + 4).concat([[10, 0, Z0 + 7]]).map(T)));
  }
  const B = register(stage, (dt) => { const m = stepS(phi, dt); draw(); return m; });
  bag.add(B.unregister);
  function move([sx]) {
    phi.t = 0.5 + clamp((sx - 200) / 200, -1, 1) * gain * 4;
    read.textContent = Math.round((clamp(0.12 + (phi.t - 0.5) * 0.14, -0.55, 0.65) * 180) / Math.PI) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { phi.t = 0.5; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = clamp(v, 0.25, 1.5); }, destroy: bag.dispose };
}

hairline({
  name: "glider",
  means: "A glider with long wings: the pointer's x throws the ailerons opposite ways and the sailplane banks after them.",
  rules: [3, 4, 5, 8],
  range: [0.25, 0.75, 1.5],
  tour: [[96, 202], [294, 102], [200, 166], null],
  mount,
});

catamaran.code:
/**
 * Catamaran: two slim hulls joined by beams and a trampoline, one mast in
 * the middle. The pointer's x swings the boom and mainsail round the mast;
 * the sail is the bright mark. The slider is how far the boom may swing.
 */
const { Cam, fit, proj, rrect, hull, poly, clamp, spring, stepS, disposer, mk, pointer, register } = HL;

const box = (x0, y0, z0, x1, y1, z1, r = 1.5) => {
  const ring = rrect(x0, y0, x1, y1, Math.min(r, (x1 - x0) / 2.2, (y1 - y0) / 2.2), 6);
  return ring.map((q) => [q.u, q.v, z0]).concat(ring.map((q) => [q.u, q.v, z1]));
};
const MX = 8, REST = 0.3;
const swing = (pts, a) => pts.map((p) => {
  const dx = p[0] - MX, dy = p[1], c = Math.cos(a), s = Math.sin(a);
  return [MX + dx * c - dy * s, dx * s + dy * c, p[2]];
});
const sail = () => [[MX, -0.8, 18], [MX, 0.8, 18], [MX, 0, 118], [MX - 8, 0, 100], [MX - 50, -0.8, 20], [MX - 50, 0.8, 20]];
const boom = () => box(MX - 54, -1.6, 14, MX + 2, 1.6, 18, 1.2);
const ITEMS = [
  { cls: "sil", f: () => box(-64, 18, 0, 62, 30, 12, 6) },
  { cls: "sil", f: () => box(-40, -26, 10, -34, 26, 14, 1) },
  { cls: "sil", f: () => box(26, -26, 10, 32, 26, 14, 1) },
  { cls: "lo", f: () => box(-36, -22, 11, 28, 22, 12, 1) },
  { cls: "sil", f: () => box(-64, -30, 0, 62, -18, 12, 6) },
  { cls: "sil", f: () => box(MX - 2, -2, 12, MX + 2, 2, 122, 1) },
  { cls: "sil", f: (a) => swing(boom(), a) },
  { cls: "sil hi", f: (a) => swing(sail(), a) },
];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.25);
  const all = [];
  for (const it of ITEMS) for (const a of [-1.4, 0, 1.4]) all.push(...it.f(a));
  fit(C, all, 200, 160);
  const P = proj(C), g = mk("g", {}, svg);
  const els = ITEMS.map((it) => ({ it, el: mk("path", { class: it.cls }, g) }));
  const ang = spring(REST, { k: 70, c: 14 });
  let last = NaN, on = false;
  function draw() {
    if (ang.x === last) return;
    last = ang.x;
    for (const e of els) e.el.setAttribute("d", poly(hull(e.it.f(ang.x).map((p) => P(p[0], p[1], p[2])))));
    read.textContent = on ? "boom " + Math.round((ang.t * 180) / Math.PI) + "°" : "rest";
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();
  const aim = (u) => { on = true; last = NaN; ang.t = clamp(u, -1, 1) * 1.4 * amp; B.wake(); };
  let lastU = REST / 1.4;
  bag.add(pointer(stage, {
    move: (p) => { lastU = (p[0] - 200) / 130; aim(lastU); },
    leave: () => { on = false; last = NaN; ang.t = REST; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; if (on) aim(lastU); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "catamaran",
  means: "A catamaran on twin hulls with a trampoline between: the pointer swings the boom and mainsail round the mast.",
  rules: [1, 3, 4, 5],
  range: [0.3, 0.8, 1],
  tour: [[135, 169], [214, 18], [68, 201], null],
  mount,
});

pirateship.code:
/**
 * Pirate ship: a deep hull with a raised stern castle, a bowsprit and one
 * tall mast carrying two square sails and a pennant. The pointer braces the
 * yards round: the sails turn on the mast to face the side the pointer is
 * on. At rest they hang braced a little, the topsail bright. The slider is
 * how far the yards can swing.
 */
const {
  Cam, fit, hull, open, poly, proj, clamp, fillet, rad, rings, prism, facing, ringAt, run, rrect, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 120, W = 34, HZ = 16, MX = 64, MY = 17, REST = 0.3;
const SAILS = [[34, 62, 30, 26], [66, 90, 22, 18]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [L, W, 0], [L + 22, MY, 34], [MX, MY, 104], [MX - 30, MY - 30, 34], [MX + 30, MY + 30, 34]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the hull: a narrower keel under a wide deck
  const hl = solid(g);
  const foot = rrect(10, 7, L - 14, W - 7, 8, 10), top = rrect(0, 0, L, W, 15, 10), inner = rrect(2, 2, L - 2, W - 2, 13, 10);
  put(hl, { sil: poly(hull(ringAt(P, foot, 0).concat(ringAt(P, top, HZ)))), crease: open(ringAt(P, run(inner, front), HZ)) });
  mk("path", { class: "nf lo", d: seg(P(14, W, 10), P(L - 18, W, 10)) }, hl.g);
  // the stern castle and the bowsprit
  const cs = solid(g);
  const [cr, ci] = rings(3, 3, 28, W - 3, 6, 1.2);
  put(cs, prism(P, front, cr, ci, HZ, HZ + 14));
  mk("path", { class: "nf lo", d: seg(P(28, 8, HZ + 9), P(28, W - 8, HZ + 9)) }, cs.g);
  mk("path", { class: "nf", d: seg(P(L - 4, MY, HZ + 2), P(L + 22, MY, 34)) }, g);
  // the mast and its pennant
  const ms = solid(g);
  const [mr, mi] = rings(MX - 2, MY - 2, MX + 2, MY + 2, 2, 0.6);
  put(ms, prism(P, front, mr, mi, HZ, 100));
  mk("path", { d: poly(fillet([P(MX, MY, 100), P(MX - 22, MY, 96), P(MX, MY, 92)], [0.6, 1, 0.6])) }, g);

  // the sails: plates turned about the mast, the foot bellied forward
  const sails = SAILS.map(() => { const s = solid(g); s.yard = mk("path", { class: "nf" }, s.g); return s; });
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const dx = -Math.sin(a), dy = Math.cos(a), nx = Math.cos(a) * 6, ny = Math.sin(a) * 6;
    SAILS.forEach(([z0, z1, w0, w1], k) => {
      const at = (u, z, b) => P(MX + dx * u + nx * b, MY + dy * u + ny * b, z);
      const pts = [at(-w1, z1, 0), at(w1, z1, 0), at(w0, z0, 0.4), at(0, z0 + 2, 1), at(-w0, z0, 0.4)];
      sails[k].sil.setAttribute("d", poly(fillet(pts, [1.5, 1.5, 2, 6, 2])));
      sails[k].cr.setAttribute("d", open([at(0, z1 - 1, 0.2), at(0, (z0 + z1) / 2, 0.8), at(0, z0 + 3, 1)]));
      sails[k].cr.setAttribute("class", "nf lo");
      sails[k].yard.setAttribute("d", seg(at(-w1 - 4, z1 + 1, 0), at(w1 + 4, z1 + 1, 0)));
    });
  }
  const sp = spring(REST);
  const Bk = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(Bk.unregister);

  // the hit: a fixed patch of sea round the ship; its side picks the brace
  function aim(t) {
    const on = t !== null;
    sp.t = on ? t : REST;
    sails[0].sil.classList.toggle("hi", on);
    sails[1].sil.classList.toggle("hi", true);
    read.textContent = on ? Math.round((t * 180) / Math.PI) + "°" : "rest";
    Bk.wake();
  }
  aim(null);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, 0);
      if (x < -30 || x > L + 40 || y < -70 || y > W + 70) return aim(null);
      aim(clamp((y - MY) / 45, -1, 1) * rad(amp));
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 20, 70); }, destroy: bag.dispose };
}

hairline({
  name: "pirateship",
  means: "A pirate ship with two square sails on one tall mast: the pointer braces the yards round, the sails turning to face its side.",
  rules: [1, 3, 5, 8],
  range: [20, 55, 70],
  tour: [[125, 250], [330, 236], [210, 190], null],
  mount,
});

hydrofoil.code:
/**
 * Hydrofoil: a pointed hull with a cabin, standing on two struts over a
 * wide bow foil and a narrower stern foil that stay at the waterline. The
 * pointer near the boat lifts the hull up its struts, clear of the water;
 * away it settles low. At rest it sits half-lifted, the bow foil bright.
 * The slider is how high the foils lift the hull.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, lerp, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 112, B = 32, H = 12, REST = 0.3, LOW = 4, FX = 80, RX = 16;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[0, -B / 2 - 10, 0], [L, B / 2 + 10, 0], [FX, B / 2 + 12, 0], [0, 0, 48 + H + 12], [L, 0, 48 + H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const half = (u) => (B / 2) * Math.pow(clamp((L - u) / (L * 0.5), 0, 1), 0.6);
  const ring = (z, k) => {
    const a = [];
    for (let i = 0; i <= 24; i++) { const u = (i / 24) * L; a.push(P(u, half(u) * k, z)); }
    for (let i = 24; i >= 0; i--) { const u = (i / 24) * L; a.push(P(u, -half(u) * k, z)); }
    return a;
  };
  // the foils: thin wings at the waterline, the stern one first
  const foil = (x, span, cls) => {
    const pts = [P(x - 6, -span, 0), P(x + 3, -span, 0), P(x + 3, span, 0), P(x - 6, span, 0), P(x - 6, span, -2), P(x - 6, -span, -2)];
    const s = solid(g);
    s.sil.setAttribute("d", poly(fillet(hull(pts), Array(hull(pts).length).fill(1.5))));
    s.cr.setAttribute("class", "nf lo");
    s.cr.setAttribute("d", seg(P(x - 5, -span + 2, 0), P(x - 5, span - 2, 0)));
    if (cls) s.sil.classList.add(cls);
    return s;
  };
  foil(RX, 16);
  const bow = foil(FX, 28, "hi");
  // the struts: one pair under the bow, one under the stern
  const struts = [[RX - 2, -5], [RX - 2, 5], [FX - 2, -7], [FX - 2, 7]].map(([x, y]) => ({ x, y, s: solid(g) }));
  // the hull and its cabin
  const hl = solid(g), cab = solid(g);
  const [cr, ci] = rings(26, -8, 60, 8, 5, 1.2);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const z = lerp(LOW, amp, t);
    struts.forEach(({ x, y, s }) => {
      const [sr, si] = rings(x - 2, y - 1.2, x + 2, y + 1.2, 1.2, 0.4);
      put(s, prism(P, front, sr, si, 0, z + 3));
    });
    hl.sil.setAttribute("d", poly(hull(ring(z, 0.4).concat(ring(z + H, 1)))));
    hl.cr.setAttribute("class", "nf lo");
    hl.cr.setAttribute("d", open(ring(z + H, 0.86)));
    put(cab, prism(P, front, cr, ci, z + H, z + H + 10));
  }
  const sp = spring(REST);
  const Bk = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(Bk.unregister);

  // the hit: a fixed patch of water round the boat; nearer its middle lifts higher
  function aim(t) {
    const on = t !== null;
    sp.t = on ? t : REST;
    bow.sil.classList.toggle("hi", !on);
    hl.sil.classList.toggle("hi", on);
    read.textContent = on ? "lift " + Math.round(lerp(LOW, amp, t)) : "rest";
    Bk.wake();
  }
  aim(null);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      const [x, y] = unproj(C, sx, sy, 0);
      if (x < -30 || x > L + 30 || Math.abs(y) > 60) return aim(null);
      aim(clamp(1.4 - Math.hypot(x - L / 2, y) / 70, 0, 1));
    },
    leave: () => aim(null),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 20, 48); last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "hydrofoil",
  means: "A hydrofoil on two foils at the waterline: the pointer near the boat lifts the hull up its struts, clear of the water.",
  rules: [1, 3, 5, 8],
  range: [20, 38, 48],
  tour: [[200, 230], [120, 205], [290, 250], null],
  mount,
});

paramotor.code:
/**
 * Paramotor: a pilot in a harness with the motor's round prop cage on the
 * back, hanging under a long arched wing on its lines. The pointer's x swings
 * the wing over the pilot like a pendulum, and the prop turns with it. The
 * wing is the bright mark.
 */
const { Cam, fit, proj, hull, poly, open, clamp, spring, stepS, disposer, mk, pointer, register } = HL;
const S = 1.9, Z0 = 0, ZP = 34, RW = 78, TW = 0.78;
const box = (x0, x1, y0, y1, z0, z1) => { const o = []; [x0, x1].forEach((x) => [y0, y1].forEach((y) => [z0, z1].forEach((z) => o.push([x, y, z])))); return o; };
const hoop = (x, r, zc, n = 24) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([x, r * Math.cos(t), zc + r * Math.sin(t)]); } return o; };
const rot = (b) => (p) => { const y = p[1], z = p[2] - ZP; return [p[0], y * Math.cos(b) - z * Math.sin(b), ZP + y * Math.sin(b) + z * Math.cos(b)]; };
const arc = (x, b, dz = 0) => { const o = []; for (let k = 0; k <= 16; k++) { const t = -TW + (2 * TW * k) / 16; o.push(rot(b)([x, RW * Math.sin(t), ZP + RW * Math.cos(t) + dz])); } return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, S);
  const ext = [];
  [-0.75, 0.75].forEach((b) => ext.push(...arc(14, b), ...arc(-14, b)));
  fit(C, ext.concat([[-14, 22, Z0], [-14, -22, Z0], [10, 0, Z0]]), 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const n = ["lines", "wing", "ribs", "cage", "cageIn", "prop", "motor", "pilot", "head"];
  const el = {};
  n.forEach((k) => (el[k] = mk("path", { class: k === "lines" || k === "ribs" || k === "cageIn" ? "nf lo" : k === "cage" ? "nf sil" : "sil" }, g)));
  el.wing.classList.add("hi");
  const sh = (pts) => poly(hull(pts.map((p) => P(...p))));
  const zc = Z0 + 22;
  el.cage.setAttribute("d", poly(hoop(-16, 22, zc).map((p) => P(...p))));
  el.cageIn.setAttribute("d", poly(hoop(-16, 20, zc).map((p) => P(...p))));
  el.motor.setAttribute("d", sh(box(-15, -6, -7, 7, zc - 8, zc + 8)));
  el.pilot.setAttribute("d", sh(box(-6, 8, -6, 6, Z0 + 10, Z0 + 34).concat(box(4, 18, -5, 5, Z0 + 8, Z0 + 14))));
  el.head.setAttribute("d", sh(hoop(1, 5, Z0 + 40, 12).concat(hoop(-3, 5, Z0 + 40, 12))));
  const b = spring(0.14);
  let last = NaN;
  function draw() {
    if (b.x === last) return; last = b.x;
    const v = b.x, R = rot(v);
    const le = arc(14, v), te = arc(-14, v), le2 = arc(14, v, -4), te2 = arc(-14, v, -3);
    el.wing.setAttribute("d", poly(le.concat(le2.slice().reverse()).map((p) => P(...p))) + poly(le.concat(te.slice().reverse()).map((p) => P(...p))) );
    let ribs = "", lines = "";
    for (let k = 2; k <= 14; k += 2) ribs += open([P(...le[k]), P(...te[k])]);
    [1, 4, 7, 9, 12, 15].forEach((k) => { const s = k < 8 ? -1 : 1; lines += open([P(...le2[k]), P(...R([2, s * 6, ZP]))]) + open([P(...te2[k]), P(...R([-2, s * 6, ZP]))]); });
    el.ribs.setAttribute("d", ribs);
    el.lines.setAttribute("d", lines);
    const a = 0.5 + v * 4, pts = [];
    [0, Math.PI].forEach((o) => { const c = Math.cos(a + o), s = Math.sin(a + o); [[3, 3], [10, 3.5], [18, 2]].forEach(([u, w]) => [-1, 1].forEach((q) => pts.push([-19, u * c - q * w * s, zc + u * s + q * w * c]))); });
    el.prop.setAttribute("d", sh(pts.slice(0, 6)) + sh(pts.slice(6)));
  }
  const B = register(stage, (dt) => { const m = stepS(b, dt); draw(); return m; });
  bag.add(B.unregister);
  function move([sx]) {
    b.t = clamp((sx - 200) / 90, -1, 1) * gain * 0.6;
    read.textContent = Math.round((b.t * 180) / Math.PI) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { b.t = 0.14; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = clamp(v, 0.3, 1.25); }, destroy: bag.dispose };
}

hairline({
  name: "paramotor",
  means: "A paramotor pilot with a caged prop on the back: the pointer's x swings the arched wing over them on its lines, and the prop turns.",
  rules: [3, 4, 5, 8],
  range: [0.3, 0.9, 1.25],
  tour: [[286, 86], [152, 153], [299, 102], null],
  mount,
});

spaceshuttle.code:
/**
 * Space shuttle: an orbiter with delta wings, a tall fin and two long
 * payload bay doors on its back. The pointer swings the doors open on their
 * hinges, wider the further right it goes. The doors are the bright mark.
 */
const { Cam, fit, proj, hull, poly, clamp, spring, stepS, disposer, mk, pointer, register } = HL;
const S = 2.0, Z0 = 40, R = 11, L = 13;
const disc = (x, r, z = Z0, n = 16) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([x, r * Math.cos(t), z + r * Math.sin(t)]); } return o; };
const box = (x0, x1, y0, y1, z0, z1) => { const o = []; [x0, x1].forEach((x) => [y0, y1].forEach((y) => [z0, z1].forEach((z) => o.push([x, y, z])))); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-60, -44, Z0 - 12], [58, 0, Z0], [-60, 44, Z0 - 12], [-58, 0, Z0 + 36], [-30, 26, Z0 + 10], [24, -26, Z0 + 10], [0, 0, Z0 + R + L]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const n = ["wing", "fin", "body", "bay", "doorF", "doorN"];
  const el = {};
  n.forEach((k) => (el[k] = mk("path", { class: k === "bay" ? "nf lo" : "sil" }, g)));
  el.doorF.classList.add("hi"); el.doorN.classList.add("hi");
  const o = spring(0);
  let last = NaN;
  const ang = (v) => 0.12 + v * 2.2;
  function draw() {
    if (o.x === last) return; last = o.x;
    const a = ang(o.x);
    const sh = (pts) => poly(hull(pts.map((p) => P(...p))));
    el.wing.setAttribute("d", sh([[-56, -44, Z0 - 6], [-56, 44, Z0 - 6], [-44, -44, Z0 - 6], [-44, 44, Z0 - 6], [10, -12, Z0 - 6], [10, 12, Z0 - 6], [34, -9, Z0 - 6], [34, 9, Z0 - 6]].concat([[-56, 0, Z0 - 8], [-56, 0, Z0 - 4]])));
    el.fin.setAttribute("d", sh(box(-56, -36, -1.5, 1.5, Z0 + 4, Z0 + 6).concat(box(-60, -52, -1.5, 1.5, Z0 + 34, Z0 + 36))));
    el.body.setAttribute("d", sh(disc(-56, 10).concat(disc(-30, R), disc(28, R), disc(42, 8, Z0 - 1), disc(52, 4, Z0 - 3), disc(56, 1.5, Z0 - 4))));
    const hz = Z0 + R * 0.72, hy = R * 0.69, x0 = -42, x1 = 30;
    el.bay.setAttribute("d", poly([[x0, -hy, hz], [x1, -hy, hz], [x1, hy, hz], [x0, hy, hz]].map((p) => P(...p))));
    const door = (s) => {
      const dy = -s * Math.cos(a), dz = Math.sin(a), pts = [];
      [x0, x1].forEach((x) => [0, L].forEach((u) => [0, 1.4].forEach((t) => pts.push([x, s * hy + u * dy + t * s * Math.sin(a) * 0, hz + u * dz + t]))));
      return sh(pts);
    };
    el.doorF.setAttribute("d", door(-1));
    el.doorN.setAttribute("d", door(1));
  }
  const B = register(stage, (dt) => { const m = stepS(o, dt); draw(); return m; });
  bag.add(B.unregister);
  function move([sx]) {
    o.t = clamp(gain * (0.6 + 0.4 * clamp((sx - 80) / 240, 0, 1)), 0, 1.2);
    read.textContent = Math.round((ang(o.t) * 180) / Math.PI) + "°";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { o.t = 0; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = clamp(v, 0.3, 1.2); }, destroy: bag.dispose };
}

hairline({
  name: "spaceshuttle",
  means: "A space shuttle orbiter: the pointer swings its two long payload bay doors open on their hinges, wider toward the right.",
  rules: [3, 4, 5, 8],
  range: [0.3, 0.85, 1.2],
  tour: [[233, 178], [312, 244], [151, 94], null],
  mount,
});

cropduster.code:
/**
 * Crop duster: a low-wing ag plane with a tall hopper ahead of the cockpit
 * and a spray boom along the wing's trailing edge. The pointer swings the
 * boom's nozzles down and lets the spray fall, heavier toward the left.
 * The boom is the bright mark.
 */
const { Cam, fit, proj, hull, poly, open, clamp, spring, stepS, disposer, mk, pointer, register } = HL;
const S = 2.15, Z0 = 50, NZ = [-52, -40, -28, -16, 16, 28, 40, 52];
const disc = (x, r, z = Z0, n = 16) => { const o = []; for (let k = 0; k < n; k++) { const t = (k / n) * 2 * Math.PI; o.push([x, r * Math.cos(t), z + r * Math.sin(t)]); } return o; };
const box = (x0, x1, y0, y1, z0, z1) => { const o = []; [x0, x1].forEach((x) => [y0, y1].forEach((y) => [z0, z1].forEach((z) => o.push([x, y, z])))); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let gain = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-50, 0, Z0 + 26], [44, 0, Z0], [0, -60, Z0 - 6], [0, 60, Z0 - 6], [-40, 52, Z0 - 50], [-40, -52, Z0 - 50]].map(([x, y, z]) => [-x, y, z]), 200, 166);
  const P0 = proj(C), P = (x, y, z) => P0(-x, y, z);
  const g = mk("g", {}, svg);
  const n = ["prop", "wing", "body", "hopper", "canopy", "boom", "spray", "fin", "stab"];
  const el = {};
  n.forEach((k) => (el[k] = mk("path", { class: k === "spray" ? "nf lo" : k === "canopy" ? "nf lo" : k === "boom" ? "nf sil hi" : "sil" }, g)));
  const sh = (pts) => poly(hull(pts.map((p) => P(...p))));
  el.stab.setAttribute("d", sh(box(-50, -40, -20, 20, Z0 + 1, Z0 + 3)));
  el.wing.setAttribute("d", sh(box(-6, 14, -60, 60, Z0 - 7, Z0 - 5).concat(box(-4, 16, 0, 0, Z0 - 7, Z0 - 5))));
  el.fin.setAttribute("d", sh(box(-50, -36, -1.5, 1.5, Z0 + 2, Z0 + 4).concat(box(-52, -46, -1.5, 1.5, Z0 + 24, Z0 + 26))));
  el.body.setAttribute("d", sh(disc(-50, 2.5).concat(disc(-20, 5), disc(6, 8, Z0 + 1), disc(34, 8), disc(40, 5))));
  el.hopper.setAttribute("d", sh(box(12, 26, -6, 6, Z0 + 4, Z0 + 15)));
  el.canopy.setAttribute("d", poly([[0, 0, Z0 + 8], [4, 0, Z0 + 16], [10, 0, Z0 + 16], [11, 0, Z0 + 9]].map((p) => P(...p))));
  el.prop.setAttribute("d", sh(box(44, 46, -1.5, 1.5, Z0 - 16, Z0 + 16)) + poly(disc(46, 3).map((p) => P(...p))));
  const s = spring(0.1);
  let last = NaN;
  function draw() {
    if (s.x === last) return; last = s.x;
    const v = clamp(s.x, 0, 1.1), a = 0.25 + v * 1.1, bx = -9, bz = Z0 - 9;
    let boom = open([P(bx, -56, bz), P(bx, 56, bz)]), spray = "";
    NZ.forEach((y) => {
      const tip = [bx - 4 * Math.cos(a), y, bz - 4 * Math.sin(a)];
      boom += open([P(bx, y, bz), P(...tip)]) + open([P(bx + 3, y, Z0 - 6), P(bx, y, bz)]);
      const len = 3 + v * 50;
      [-4, 0, 4].forEach((d) => { spray += open([P(...tip), P(tip[0] - len * 0.35, y + d * (1 + v), tip[2] - len)]); });
    });
    el.boom.setAttribute("d", boom);
    el.spray.setAttribute("d", spray);
  }
  const B = register(stage, (dt) => { const m = stepS(s, dt); draw(); return m; });
  bag.add(B.unregister);
  function move([sx]) {
    s.t = clamp(gain * (0.45 + 0.55 * clamp((320 - sx) / 220, 0, 1)), 0, 1.1);
    read.textContent = Math.round(s.t * 100) + "%";
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave: () => { s.t = 0.1; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { gain = clamp(v, 0.3, 1.3); }, destroy: bag.dispose };
}

