const SCALE = 2.0, REST = 0.3, X0 = 125;
const LABEL = (s) => Math.round(lerp(4, 52, s)) + "°";
const oct = (r, z0, z1, n = 8) => { const pts = [], top = []; for (let k = 0; k < n; k++) { const a = (k + 0.5) * Math.PI * 2 / n, x = r * Math.cos(a), y = r * Math.sin(a); pts.push([x, y, z0]); top.push([x, y, z1]); } pts.push(...top); return { pts, lines: [top.concat([top[0]])] }; };
function parts(s) {
  const out = [], spin = lerp(0, 120, s), fl = rad(lerp(4, 52, s)), TZ = 84, R = 30, L = 30;
  out.push(oct(22, 0, 3, 12), oct(5, 3, TZ));
  const top = [oct(R + 3, TZ, TZ + 4, 16), oct(14, TZ + 4, TZ + 12, 12), oct(4, TZ + 12, TZ + 18, 8)];
  for (let k = 0; k < 8; k++) {
    const ex = R + L * Math.sin(fl), ez = TZ - L * Math.cos(fl);
    const chain = { pts: [[R, -0.7, TZ], [R, 0.7, TZ], [ex, -0.7, ez], [ex, 0.7, ez]], lines: [] };
    const seat = rot(mv(B(-3.5, -4, -7, 3.5, 4, 0), ex, 0, ez), "y", -lerp(4, 52, s) * 0.5, [ex, 0, ez]);
    seat.hi = k === 0;
    for (const b of [chain, seat]) top.push(rot(b, "z", spin + k * 45, [0, 0, 0]));
  }
  out.push(...top);
  return out;
}

hairline({
  name: "swingride",
  means: "A fairground chair swing ride: the pointer spins the crown, and its eight hanging chairs fly further out on their chains.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[150, 200], [300, 180], [220, 150], null],
  mount,
