highstriker.code:
/**
 * High striker: a fairground strength tester. A tall rail stands on a
 * plinth with a striking pad at its foot and a bell at its crown; a puck
 * rides a collar on the rail, and a big mallet waits raised beside it.
 * The pointer swings the mallet down onto the pad and the puck shoots up
 * the rail toward the bell. At rest the bell is bright; when struck, the
 * puck is. The slider is the strength of the blow: how high the puck goes.
 *
 * The pattern: one part turning about a hinge (swing) driving a slide.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, lerp, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const TH = 168, PZ0 = 12, PH = 9, BZ = TH + 2;
const G = [40, -30, 30], UP = [-10, -20, 65], DOWN = [-24, 46, -18], ML = 56;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-30, -30, 0], [30, 30, 0], [30, -30, 0], [-30, 30, 0], [0, 0, BZ + 14], [34, -58, 96], [30, 30, 0], [24, 8, 4]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-30, -30, 30, 30, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 8));
  // the pad, in front of the rail
  put(solid(g), prism(P, front, disc(16, 16, 9), disc(16, 16, 7), 8, 12));
  // the rail and its crown
  const [rr, ri] = rings(-4, -4, 4, 4, 3, 1);
  put(solid(g), prism(P, front, rr, ri, 8, TH));
  const bell = mk("path", { class: "sil" }, g);
  const bp = [];
  for (let i = 0; i <= 6; i++) { const t = (i / 6) * (Math.PI / 2); bp.push(...disc(0, 0, 14 * Math.cos(t) + 2, 32).map((q) => P(q.u, q.v, BZ + 12 * Math.sin(t)))); }
  bell.setAttribute("d", poly(hull(bp)));
  mk("path", { d: poly(disc(0, 0, 14, 32).map((q) => P(q.u, q.v, BZ + 1))), class: "nf lo" }, g);
  const puck = solid(g), stick = mk("path", { class: "sil" }, g), head = mk("path", { class: "sil" }, g);

  function cyl(a, b, r) {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], n = Math.hypot(...d), e = d.map((x) => x / n);
    const z = Math.abs(e[2]) > 0.9 ? [1, 0, 0] : [0, 0, 1];
    let u = [e[1] * z[2] - e[2] * z[1], e[2] * z[0] - e[0] * z[2], e[0] * z[1] - e[1] * z[0]];
    const un = Math.hypot(...u); u = u.map((x) => x / un);
    const v = [u[1] * e[2] - u[2] * e[1], u[2] * e[0] - u[0] * e[2], u[0] * e[1] - u[1] * e[0]];
    const ring = (p) => Array.from({ length: 20 }, (_, i) => { const t = (i / 20) * Math.PI * 2; return P(...[0, 1, 2].map((j) => p[j] + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]))); });
    return poly(hull(ring(a).concat(ring(b))));
  }

  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const s = Math.min(1, t * 1.6), q = Math.max(0, (t - 0.25) / 0.75);
    const dv = UP.map((x, j) => lerp(x, DOWN[j], s)), dn = Math.hypot(...dv), e = dv.map((x) => x / dn);
    const tip = G.map((x, j) => x + e[j] * ML);
    stick.setAttribute("d", cyl(G, tip, 2.6));
    let hx = [e[1], -e[0], 0]; const hn = Math.hypot(...hx) || 1; hx = hx.map((x) => (x / hn) * 13);
    head.setAttribute("d", cyl(tip.map((x, j) => x - hx[j]), tip.map((x, j) => x + hx[j]), 8));
    const z = PZ0 + q * amp * (BZ - PZ0 - PH - 1);
    put(puck, prism(P, front, disc(0, 0, 9, 24), disc(0, 0, 7, 24), z, z + PH));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(4, -10, 70);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    last = NaN;
    tset(tw, on ? 1 : 0, performance.now(), 0);
    puck.sil.classList.toggle("hi", on);
    bell.classList.toggle("hi", !on);
    read.textContent = on ? Math.round(amp * 100) + "%" : "rest";
    B.wake();
  }
  setActive(false);
  const hit = ([sx, sy]) => Math.abs(sx - mid[0]) < 90 && Math.abs(sy - mid[1]) < 150;
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; last = NaN; B.wake(); if (act) read.textContent = Math.round(amp * 100) + "%"; }, destroy: bag.dispose };
}

hairline({
  name: "highstriker",
  means: "A fairground high striker: over it, the mallet swings down on the pad and the puck shoots up the rail to the bell.",
  rules: [1, 4, 5, 8],
  range: [0.3, 1, 1],
  tour: [[182, 246], [196, 150], [182, 40], null],
  mount,
});

ropebridge.code:
/**
 * Rope bridge: a plank deck slung between two pairs of posts, hand ropes
 * above, hangers down to each plank. The pointer picks a plank by where it
 * stands: the deck swings sideways and dips under it, staggered out from the
 * plank. At rest the middle plank is bright. The slider is how far it swings.
 *
 * The pattern: one of many in a single row (cloches).
 */
const {
  Cam, fit, facing, open, prism, proj, rings, tdone, tset, tval, tween, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 13, L = 190, HW = 12, DZ = 30, SAG = 9, PH = 54, FAV = 6;
const tx = (i) => (i + 0.5) / N;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.48);
  fit(C, [[-12, -HW - 34, 0], [L + 12, HW + 34, 0], [-12, HW + 34, PH], [L + 12, -HW - 34, PH], [L / 2, HW + 30, DZ - SAG - 12]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x, y, gr) => { const [r, i] = rings(x - 3, y - 3, x + 3, y + 3, 2.5, 0.8); put(solid(gr), prism(P, front, r, i, 0, PH)); };
  for (const [x, y] of [[-6, -HW - 2], [L + 6, -HW - 2]]) post(x, y, g);
  const farRope = mk("path", { class: "nf" }, g), farHang = mk("path", { class: "nf lo" }, g);
  const planks = [];
  for (let i = 0; i < N; i++) planks.push({ s: solid(g), dy: tween(0), dz: tween(0) });
  const nearHang = mk("path", { class: "nf lo" }, g), nearRope = mk("path", { class: "nf" }, g);
  const footRopes = mk("path", { class: "nf lo" }, g);
  const ng = mk("g", {}, g);
  for (const [x, y] of [[-6, HW + 2], [L + 6, HW + 2]]) post(x, y, ng);
  let last = "";

  const W = L / N;
  function draw(now) {
    const v = planks.map((p) => [tval(p.dy, now), tval(p.dz, now)]);
    const key = v.join();
    if (key === last) return;
    last = key;
    const deck = (i) => DZ - SAG * Math.sin(Math.PI * tx(i)) + v[i][1];
    planks.forEach((p, i) => {
      const x0 = i * W + 1.4, y = v[i][0], z = deck(i);
      const [r, inn] = rings(x0, -HW + y, x0 + W - 2.8, HW + y, 1.4, 0.6);
      put(p.s, prism(P, front, r, inn, z - 1.6, z));
    });
    const rope = (side, up) => {
      const pts = [P(-6, side * (HW + 2), up ? PH - 4 : DZ)];
      planks.forEach((_, i) => pts.push(P(tx(i) * L, side * HW + v[i][0], deck(i) + (up ? 18 : 0))));
      pts.push(P(L + 6, side * (HW + 2), up ? PH - 4 : DZ));
      return open(pts);
    };
    const hang = (side) => planks.map((_, i) => "M" + P(tx(i) * L, side * HW + v[i][0], deck(i) + 18).join(",") + "L" + P(tx(i) * L, side * HW + v[i][0], deck(i)).join(",")).join("");
    farRope.setAttribute("d", rope(-1, true));
    nearRope.setAttribute("d", rope(1, true));
    farHang.setAttribute("d", hang(-1));
    nearHang.setAttribute("d", hang(1));
    footRopes.setAttribute("d", rope(1, false));
  }

  const B = register(stage, (_dt, now) => { draw(now); return planks.some((p) => !tdone(p.dy, now) || !tdone(p.dz, now)); });
  bag.add(B.unregister);

  const mids = planks.map((_, i) => P(tx(i) * L, 0, DZ - SAG * Math.sin(Math.PI * tx(i))));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 16 && Math.abs(mids[best][1] - sy) < 60 ? best : -1;
  }

  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    planks.forEach((p, i) => {
      const s = Math.sin(Math.PI * tx(i)), near = a < 0 ? 0 : Math.exp(-(((i - a) / 3) ** 2));
      tset(p.dy, a < 0 ? 4 * s : amp * s * clamp(0.55 + 0.45 * near, 0, 1), now, from < 0 ? 0 : Math.abs(i - from) * 40);
      tset(p.dz, a < 0 ? 0 : -amp * 0.3 * near * s, now, from < 0 ? 0 : Math.abs(i - from) * 40);
      p.s.sil.classList.toggle("hi", i === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "plank " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; if (act >= 0) setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "ropebridge",
  means: "A plank rope bridge between posts: the plank under the pointer dips and the deck swings sideways, spreading out from it.",
  rules: [1, 2, 3, 5],
  range: [12, 22, 30],
  tour: [[200, 144], [150, 118], [250, 175], null],
  mount,
});

logflume.code:
/**
 * Log flume: a trough on legs that runs flat, drops down a chute and runs
 * out at the bottom, with a hollowed log boat waiting at the top. The
 * pointer over the flume sends the log down the drop, pitching nose-down on
 * the slope. At rest the log is bright. The slider is how far it runs.
 *
 * The pattern: one part answering as a whole (cloches, one item).
 */
const {
  Cam, fit, hull, open, poly, proj, rrect, unproj, tset, tval, tdone, tween,
  disposer, mk, pointer, register,
} = HL;

const L = 200, HW = 14, X0 = 24, BL = 44, BW = 22, BH = 11;
const sm = (t) => { t = Math.min(1, Math.max(0, t)); return t * t * (3 - 2 * t); };
const prof = (x) => 4 + 60 * (1 - sm((x - 50) / 90));
const slope = (x) => Math.atan2(prof(x + 1) - prof(x - 1), 2);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[0, -HW, 0], [L, HW, 0], [0, HW, 80], [L, -HW, 0], [0, -HW, 80]], 200, 162);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const line = (y, dz) => { const pts = []; for (let x = 0; x <= L; x += 4) pts.push(P(x, y, prof(x) + dz)); return open(pts); };
  let legs = "";
  for (let x = 10; x < 140; x += 26) for (const y of [-HW, HW]) legs += "M" + P(x, y, 0).join(",") + "L" + P(x, y, prof(x)).join(",");
  mk("path", { d: legs, class: "nf lo dash" }, g);
  mk("path", { d: line(-HW, 9), class: "nf" }, g);
  mk("path", { d: line(-HW, 0) + line(HW, 0).replace(/^M/, "M"), class: "nf lo" }, g);
  mk("path", { d: open([P(0, -HW, prof(0)), P(0, -HW, prof(0) + 9)]) + open([P(L, -HW, prof(L)), P(L, -HW, prof(L) + 9)]), class: "nf lo" }, g);
  const boat = mk("path", { class: "sil" }, g), seat = mk("path", { class: "nf lo" }, g);
  mk("path", { d: line(HW, 9), class: "nf" }, g);
  mk("path", { d: open([P(0, HW, prof(0)), P(0, HW, prof(0) + 9), P(0, -HW, prof(0) + 9)]) + open([P(L, HW, prof(L)), P(L, HW, prof(L) + 9)]), class: "nf" }, g);

  const foot = rrect(-BL / 2, -BW / 2, BL / 2, BW / 2, 9, 4), top = rrect(-BL / 2, -BW / 2, BL / 2, BW / 2, 10, 4);
  const hollow = rrect(-BL / 2 + 8, -BW / 2 + 4, BL / 2 - 8, BW / 2 - 4, 6, 4);
  const pos = tween(0);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const cx = X0 + d, cz = prof(cx) + 1, a = slope(cx), c = Math.cos(a), s = Math.sin(a);
    const at = (ring, h) => ring.map((q) => P(cx + q.u * c - h * s, q.v, cz + q.u * s + h * c));
    boat.setAttribute("d", poly(hull(at(foot, 0).concat(at(top, BH)))));
    seat.setAttribute("d", poly(at(hollow, BH)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(pos, now)); return !tdone(pos, now); });
  bag.add(B.unregister);

  const mid = P(X0, 0, prof(X0) + BH / 2);
  function hit([sx, sy]) {
    if (Math.hypot(sx - mid[0], sy - mid[1]) < 40) return 1;
    const [x, y] = unproj(C, sx, sy, 0);
    return x > 0 && x < L && Math.abs(y) < HW + 4 ? 1 : -1;
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(pos, a > 0 ? reach : 0, performance.now(), 0);
    boat.classList.add("hi");
    read.textContent = a > 0 ? "run " + Math.round(reach) : "rest";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (act > 0) setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "logflume",
  means: "A log flume trough with a hollow log boat at the top: the pointer sends the log down the drop, nose-down on the chute.",
  rules: [1, 3, 5, 6],
  range: [70, 120, 150],
  tour: [[114, 77], [200, 200], [160, 150], null],
  mount,
});

bouncycastle.code:
/**
 * Bouncy castle: an inflated floor with puffy walls along its back and a
 * turret at each corner, every turret a fat column with a round cap. The
 * pointer picks the nearest corner: that turret bounces up tall, its
 * neighbours dip a little, staggered from it. At rest the turrets stand at
 * uneven heights, the front one bright. The slider is how high it bounces.
 *
 * The pattern: one of a few parts picked by its rest pose on screen.
 */
const {
  Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, ringAt, run, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 64, Y1 = 52, FZ = 7, TR = 8, REST = [34, 26, 28, 22], FAV = 3;
const CORN = [[0, 0], [X1, 0], [0, Y1], [X1, Y1]];
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-TR, -TR, 0], [X1 + TR, Y1 + TR, 0], [X1 + TR, -TR, 0], [-TR, Y1 + TR, 0], [0, 0, 34 + 30 + 10], [X1, Y1, 22 + 30 + 10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-2, -2, X1 + 2, Y1 + 2, 10, 2);
  put(solid(g), prism(P, front, fr, fi, 0, FZ));
  const make = () => { const s = mk("g", {}, g); return { g: s, sil: mk("path", { class: "sil" }, s), cr: mk("path", { class: "nf lo" }, s) }; };
  const tur = [make()];
  // the puffy back walls, between the far turrets
  const [w1, w1i] = rings(0, -3, X1, 3, 3, 1.2), [w2, w2i] = rings(-3, 0, 3, Y1, 3, 1.2);
  put(solid(g), prism(P, front, w2, w2i, FZ, FZ + 16));
  put(solid(g), prism(P, front, w1, w1i, FZ, FZ + 16));
  tur.push(make(), make(), make());
  const items = tur.map((t, k) => ({ ...t, x: CORN[k][0], y: CORN[k][1], h: tween(REST[k]), last: NaN }));

  function draw(it, h) {
    if (h === it.last) return;
    it.last = h;
    const ring = disc(it.x, it.y, TR), pts = ringAt(P, ring, FZ).concat(ringAt(P, ring, FZ + h));
    for (let i = 1; i <= 4; i++) { const t = (i / 4) * (Math.PI / 2); pts.push(...ringAt(P, disc(it.x, it.y, (TR + 1.5) * Math.cos(t)), FZ + h + 2 + 7 * Math.sin(t))); }
    pts.push(...ringAt(P, disc(it.x, it.y, TR + 1.5), FZ + h + 2));
    it.sil.setAttribute("d", poly(hull(pts)));
    it.cr.setAttribute("d", open(ringAt(P, run(disc(it.x, it.y, TR + 1.2), front), FZ + h + 1.5)) + open(ringAt(P, run(disc(it.x, it.y, TR), front), FZ + h * 0.5)));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.h, now)); if (!tdone(it.h, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it, k) => P(it.x, it.y, FZ + REST[k] / 2));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.hypot(m[0] - sx, (m[1] - sy) * 0.6); if (d < bd) { bd = d; best = k; } });
    return bd < 70 ? best : -1;
  }
  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    items.forEach((it, k) => {
      const d = k === a ? 0 : (k ^ a) === 3 ? 2 : 1;
      const h = a < 0 ? REST[k] : d === 0 ? REST[k] + lift : REST[k] - 6 + d * 2;
      tset(it.h, clamp(h, 12, 70), now, from < 0 ? 0 : d * 45);
      it.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "turret " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; const a = act; act = -3; setActive(a); }, destroy: bag.dispose };
}

hairline({
  name: "bouncycastle",
  means: "An inflatable bouncy castle: the corner turret nearest the pointer bounces up tall while the others dip a little.",
  rules: [1, 2, 5, 9],
  range: [10, 22, 30],
  tour: [[296, 158], [190, 95], [205, 215], null],
  mount,
});

gokart.code:
/**
 * Go-kart: a low tray chassis, a bucket seat, fat rear wheels and a steering
 * wheel on its column. The pointer's side steers: the front wheels turn on
 * their kingpins and the steering wheel turns with them, on a spring. At rest
 * the wheels sit a little off straight, the steering wheel bright. The
 * slider is the steering lock.
 *
 * The pattern: parts turning on an axis, driven by the pointer's x.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const RW = 9, FW = 9, REST = 10, SX = 34, SZ = 20, SR = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lock = value;
  const C = Cam(45, 0.5, 3.35);
  fit(C, [[-4, -24, 0], [58, 24, 0], [58, -24, 0], [-4, 24, 0], [10, 0, 26], [SX, 0, SZ + SR]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (cx, cy, r, w, s) => {
    const d = [Math.cos(s), Math.sin(s)], a = [-d[1], d[0]], pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; for (const sgn of [-1, 1]) pts.push(P(cx + d[0] * r * Math.cos(t) + a[0] * w * sgn / 2, cy + d[1] * r * Math.cos(t) + a[1] * w * sgn / 2, r + r * Math.sin(t))); }
    return poly(hull(pts));
  };
  const rearFar = mk("path", { class: "sil", d: wheel(8, -17, RW, 8, 0) }, g);
  const ff = mk("path", { class: "sil" }, g);
  const [cr, ci] = rings(-2, -12, 54, 12, 6, 1.6);
  put(solid(g), prism(P, front, cr, ci, 4, 7));
  const [sr, si] = rings(6, -8, 18, 8, 4, 1.4);
  put(solid(g), prism(P, front, sr, si, 7, 22));
  mk("path", { class: "nf lo", d: open([P(SX + 6, 0, 7), P(SX - 1, 0, SZ)]) + open([P(46, -15, 6), P(46, 15, 6)]) }, g);
  const sw = mk("path", { class: "sil hi" }, g), spoke = mk("path", { class: "nf lo" }, g);
  mk("path", { class: "sil", d: wheel(8, 17, RW, 8, 0) }, g);
  const fn = mk("path", { class: "sil" }, g);
  void rearFar;
  // the steering wheel: a ring tilted back toward the driver
  const tilt = rad(55);
  const swp = (r, t) => P(SX + r * Math.cos(t) * Math.cos(tilt), r * Math.sin(t), SZ + r * Math.cos(t) * Math.sin(tilt));
  const ang = spring(REST);
  let last = NaN;
  function draw(s) {
    if (s === last) return;
    last = s;
    ff.setAttribute("d", wheel(46, -17, FW, 8, rad(s)));
    fn.setAttribute("d", wheel(46, 17, FW, 8, rad(s)));
    const ring = [], rot = rad(s * 3);
    for (let i = 0; i < 32; i++) ring.push(swp(SR, (i / 32) * Math.PI * 2));
    sw.setAttribute("d", poly(ring));
    spoke.setAttribute("d", open([swp(SR, rot), swp(0, 0), swp(SR, rot + Math.PI)]) + open([swp(0, 0), swp(SR, rot - Math.PI / 2)]));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(REST);
  function aim(p) {
    const u = p ? clamp((p[0] - 200) / 90, -1, 1) : null;
    ang.t = u === null ? REST : u * lock;
    read.textContent = u === null ? "rest" : "steer " + Math.round(ang.t) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lock = v; }, destroy: bag.dispose };
}

hairline({
  name: "gokart",
  means: "A go-kart: the front wheels and the steering wheel turn toward the pointer's side, as far as the steering lock allows.",
  rules: [3, 5, 8, 9],
  range: [20, 40, 55],
  tour: [[330, 190], [70, 173], [260, 150], null],
  mount,
});

minigolf.code:
/**
 * Mini golf windmill: a little windmill hut on a putting pad, a tunnel
 * through its foot and four broad sails on its face, a ball waiting on the
 * carpet. The pointer's side turns the sails on a spring; at rest they stand
 * off the cross, the lead sail bright. The slider is how far they can turn.
 *
 * The pattern: one part turning on an axis, driven by the pointer's x.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rad, rings, ringAt, rrect, open, run, spring, stepS,
  disposer, mk, pointer, put, register, solid, flatDot, place,
} = HL;

const HW = 9, HZ = 30, RZ = 44, XS = HW + 2.5, R0 = 3, R1 = 27, W0 = 3, W1 = 11, REST = 20;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-22, -22, 0], [26, 26, 0], [XS, -R1, HZ], [XS, R1, HZ], [XS, 0, HZ + R1], [XS, 0, HZ - R1], [0, 0, RZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-22, -22, 26, 26, 8, 2);
  put(solid(g), prism(P, front, pr, pi, 0, 2.5));
  const hole = mk("ellipse", { class: "lo" }, g);
  const hp = P(-14, 16, 2.5); hole.setAttribute("cx", hp[0]); hole.setAttribute("cy", hp[1]); hole.setAttribute("rx", 4.2); hole.setAttribute("ry", 2.1);
  // the hut and its tunnel
  const [hr, hi] = rings(-HW, -HW, HW, HW, 2, 1.2);
  const hut = solid(g);
  put(hut, prism(P, front, hr, hi, 2.5, HZ - 6));
  const arch = [];
  for (let i = 0; i <= 12; i++) { const t = Math.PI * i / 12; arch.push(P(-4 * Math.cos(t), HW, 2.5 + 5 + 5 * Math.sin(t))); }
  arch.unshift(P(-4, HW, 2.5)); arch.push(P(4, HW, 2.5));
  mk("path", { class: "nf lo", d: open(arch) }, hut.g);
  // the cap: a pyramid roof from the hut's top to a point
  const foot = rrect(-HW - 1.5, -HW - 1.5, HW + 1.5, HW + 1.5, 2, 4), top = rrect(-0.8, -0.8, 0.8, 0.8, 0.6, 2);
  const roof = solid(g);
  roof.sil.setAttribute("d", poly(hull(ringAt(P, foot, HZ - 6).concat(ringAt(P, top, RZ)))));
  roof.cr.setAttribute("d", open(ringAt(P, run(foot, front), HZ - 6)));
  // the hub and the sails, in the plane x = XS
  const hub = mk("ellipse", { class: "" }, g);
  const sails = [0, 1, 2, 3].map((k) => { const sg = mk("g", {}, g); return { sil: mk("path", { class: k === 0 ? "sil hi" : "sil" }, sg), lat: mk("path", { class: "nf lo" }, sg) }; });
  const hc = P(XS + 1, 0, HZ); hub.setAttribute("cx", hc[0]); hub.setAttribute("cy", hc[1]); hub.setAttribute("rx", 3.2); hub.setAttribute("ry", 3.6);
  const ball = flatDot(g, C, 2.6, "dot m"); place(ball, P(14, 18, 2.5));
  const at = (r, n, t) => { const d = [Math.cos(t), Math.sin(t)], m = [-Math.sin(t), Math.cos(t)]; return P(XS, d[0] * r + m[0] * n, HZ + d[1] * r + m[1] * n); };
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    sails.forEach((s, k) => {
      const t = rad(a + k * 90);
      s.sil.setAttribute("d", poly([at(R0, -W0 / 2, t), at(R1, -W1 / 2, t), at(R1, W1 / 2, t), at(R0, W0 / 2, t)]));
      s.lat.setAttribute("d", open([at(R0 + 2, 0, t), at(R1 - 1, 0, t)]) + open([at(R1 * 0.55, -W1 * 0.36, t), at(R1 * 0.55, W1 * 0.36, t)]));
    });
    g.appendChild(hub);
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(REST);
  function aim(p) {
    const u = p ? clamp((p[0] - 200) / 90, -1, 1) : null;
    ang.t = u === null ? REST : REST + u * reach;
    read.textContent = u === null ? "rest" : "sails " + Math.round(ang.t) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "minigolf",
  means: "A mini golf windmill: the sails on the hut's face turn toward the pointer's side, the further out the further they go.",
  rules: [3, 5, 8, 9],
  range: [15, 40, 45],
  tour: [[276, 203], [120, 170], [256, 113], null],
  mount,
});

irrigationpivot.code:
/**
 * Irrigation pivot: a centre-pivot rig on its crop circle, a steel tower at
 * the hub and a long pipe span carried by three wheeled A-frame towers, with
 * a truss under it and sprinkler drops hanging from it. The pointer is where
 * the water should go: the whole span sweeps round the hub on a spring to
 * point at it. At rest the span lies toward the reader, bright. The slider is
 * how far round the span will sweep.
 *
 * The pattern: a continuous aim (officechairs' spring on an angle); the hit
 * is on the field's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, seg, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 84, TW = [30, 57, 84], PZ = 22, REST = rad(28);
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.62);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([(L + 8) * Math.cos(a), (L + 8) * Math.sin(a), 0], [(L + 6) * Math.cos(a), (L + 6) * Math.sin(a), PZ + 3]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the crop circle, a dashed guide on the ground, and the wheel track of each tower
  const ringPath = (r) => { const pts = circ(r, 72).map((q) => P(q.u, q.v, 0)); return "M" + pts.map((p) => p.join(",")).join("L") + "Z"; };
  mk("path", { class: "nf dash", d: ringPath(L + 6) }, g);
  mk("path", { class: "nf lo", d: TW.map(ringPath).join("") }, g);

  const hub = mk("g", {}, g);
  { const [r, i] = rings(-9, -9, 9, 9, 2.5, 1.2); put(solid(hub), prism(P, front, r, i, 0, 2)); }
  { const [r, i] = rings(-4, -4, 4, 4, 1.2, 0.8); put(solid(hub), prism(P, front, r, i, 2, PZ + 6)); }
  { const [r, i] = rings(-6, -6, 6, 6, 2, 1); put(solid(hub), prism(P, front, r, i, PZ + 6, PZ + 9)); }

  const span = mk("g", {}, g);
  const legs = mk("path", { class: "nf sil" }, span);
  const truss = mk("path", { class: "nf lo" }, span);
  const wheels = TW.map(() => [0, 1].map(() => mk("ellipse", { class: "", rx: 3.2, ry: 1.9 }, span)));
  const pipe = solid(span);
  const [PR, PI] = rings(3, -1.6, L + 9, 1.6, 1.2, 0.5);
  pipe.sil.classList.add("hi");

  const sp = spring(REST);
  let drawn = NaN, spanFirst = null;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a), at = (r, w, z) => P(r * c - w * s, r * s + w * c, z);
    put(pipe, prism(P, front, turn(PR, a), turn(PI, a), PZ, PZ + 3.2));
    let L1 = "", T1 = "";
    TW.forEach((r, i) => {
      L1 += seg(at(r, -9, 2.5), at(r, 0, PZ)) + seg(at(r, 9, 2.5), at(r, 0, PZ)) + seg(at(r, -9, 2.5), at(r, 9, 2.5));
      [-9, 9].forEach((w, j) => { const p = at(r, w, 1.9); wheels[i][j].setAttribute("cx", p[0]); wheels[i][j].setAttribute("cy", p[1]); });
      const r0 = i ? TW[i - 1] : 4, m = (r0 + r) / 2;
      T1 += seg(at(r0, 0, PZ), at(m, 0, PZ - 7)) + seg(at(m, 0, PZ - 7), at(r, 0, PZ));
      for (const f of [0.3, 0.7]) { const d = r0 + (r - r0) * f; T1 += seg(at(d, 0, PZ), at(d, 0, PZ - 9)); }
    });
    T1 += seg(at(L + 7, 0, PZ), at(L + 7, 0, PZ - 6));
    legs.setAttribute("d", L1);
    truss.setAttribute("d", T1);
    // the span is painted before the hub when it points away from the reader
    const first = c + s < 0;
    if (first !== spanFirst) { spanFirst = first; if (first) hub.before(span); else hub.after(span); }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let aim = null;
  function retarget() {
    const goal = aim == null ? REST : REST + reach * wrap(aim - REST);
    sp.t = sp.t + wrap(goal - sp.t);
    read.textContent = aim == null ? "rest" : Math.round(((goal * 180) / Math.PI + 360) % 360) + "°";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      aim = r > L + 30 || r < 6 ? null : Math.atan2(y, x);
      retarget();
    },
    leave: () => { aim = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  read.textContent = "rest";
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "irrigationpivot",
  means: "A centre-pivot irrigation rig: its long sprinkler span sweeps round the hub to point at the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.2, 1, 1],
  tour: [[129, 150], [292, 137], [150, 215], null],
  mount,
});

railturntable.code:
/**
 * Railway turntable: a round pit with its bridge across it, a locomotive on
 * the bridge's rails, and roads of track running out from the rim. The
 * pointer picks the road: the bridge and its engine swing round on a spring
 * to face it. At rest the engine stands a little askew of the roads, its cab
 * bright. The slider is how far round the bridge will swing.
 *
 * The pattern: a continuous aim (officechairs' spring on an angle); the hit
 * is on the yard's plane, which never moves.
 */
const {
  Cam, circ, facing, fit, prism, proj, rings, run, open, seg, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 48, ROAD = 30, REST = rad(22), ROADS = [0, 60, 105, 180, 250, 300].map(rad);
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));
const turn = (ring, a) => {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  const ext = [];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; ext.push([(R + ROAD + 2) * Math.cos(a), (R + ROAD + 2) * Math.sin(a), 0], [(R - 20) * Math.cos(a), (R - 20) * Math.sin(a), 22]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // roads of track out from the rim, then the pit: its rim and the far half of its floor
  let rails = "", ties = "";
  for (const a of ROADS) {
    const c = Math.cos(a), s = Math.sin(a), at = (r, w) => P(r * c - w * s, r * s + w * c, 0);
    for (const w of [-3, 3]) rails += seg(at(R + 1, w), at(R + ROAD, w));
    for (let r = R + 4; r < R + ROAD; r += 5) ties += seg(at(r, -5), at(r, 5));
  }
  mk("path", { class: "nf lo", d: ties }, g);
  mk("path", { class: "nf sil", d: rails }, g);
  const rim = circ(R, 72);
  mk("path", { class: "", d: "M" + rim.map((q) => P(q.u, q.v, 0).join(",")).join("L") + "Z" }, g);
  mk("path", { class: "nf lo", d: open(run(rim, (q) => !front(q)).map((q) => P(q.u * 0.97, q.v * 0.97, -7))) }, g);
  mk("path", { class: "nf lo", d: open(circ(R - 6, 60).map((q) => P(q.u, q.v, -7)).concat([P(R - 6, 0, -7)])) }, g);

  const br = mk("g", {}, g);
  const deck = solid(br), track = mk("path", { class: "nf lo" }, br);
  const [DR, DI] = rings(-R + 1, -6, R - 1, 6, 1.5, 0.8);
  const parts = [
    { ring: rings(-20, -5, 20, 5, 1.5, 0.8), z0: 1.5, z1: 5.5, d: 0 },
    { ring: rings(-5, -4.2, 19, 4.2, 4, 1), z0: 5.5, z1: 13.5, d: 8 },
    { ring: rings(-20, -5.5, -5, 5.5, 1.5, 0.8), z0: 5.5, z1: 21, d: -12 },
    { ring: [circ(1.8, 16).map((q) => ({ ...q, u: q.u + 15 })), null], z0: 13.5, z1: 19, d: 15, top: true },
  ];
  for (const p of parts) p.el = solid(br);
  parts[2].el.sil.classList.add("hi");

  const sp = spring(REST);
  let drawn = NaN, order = "";
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a), at = (u, w, z) => P(u * c - w * s, u * s + w * c, z);
    put(deck, prism(P, front, turn(DR, a), turn(DI, a), -2, 0.8));
    let t = "";
    for (const w of [-3, 3]) t += seg(at(-R + 2, w, 1), at(R - 2, w, 1));
    for (let u = -R + 5; u < R - 2; u += 5) t += seg(at(u, -4.5, 0.9), at(u, 4.5, 0.9));
    track.setAttribute("d", t);
    for (const p of parts) put(p.el, prism(P, front, turn(p.ring[0], a), p.ring[1] && turn(p.ring[1], a), p.z0, p.z1));
    // paint the engine's parts far to near; the chimney always after its boiler
    const k = (p) => (p.top ? 1e3 : 0) + (p === parts[0] ? -1e3 : p.d * (c + s));
    const sorted = parts.slice().sort((p, q) => k(p) - k(q)), key = sorted.map((p) => p.d).join();
    if (key !== order) { order = key; for (const p of sorted) br.appendChild(p.el.g); }
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  let aim = null;
  function retarget() {
    const goal = aim == null ? REST : REST + reach * wrap(aim - REST);
    sp.t = sp.t + wrap(goal - sp.t);
    read.textContent = aim == null ? "rest" : "road " + (Math.round((goal * 180) / Math.PI + 360) % 360);
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0), r = Math.hypot(x, y);
      aim = r > R + ROAD + 10 || r < 8 ? null : Math.atan2(y, x);
      retarget();
    },
    leave: () => { aim = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  read.textContent = "rest";
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "railturntable",
  means: "A railway turntable: the bridge in its pit swings the locomotive round to face the road under the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.2, 1, 1],
  tour: [[109, 126], [299, 117], [180, 215], null],
  mount,
});

jackhammer.code:
/**
 * Jackhammer: a pneumatic breaker standing on its chisel in a slab of road,
 * a fat cylinder body, an air hose stub and a wide T-handle. The nearer the
 * pointer comes, the further the whole body drives down its chisel into the
 * slab and the grips spread. At rest it is half pressed, handle bright. The
 * slider sets how far the stroke goes.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, spring, stepS,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const SZ = 6, BIT = 30, BODY = 44, REST = 0.3;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stroke = value;
  const C = Cam(45, 0.5, 2.2);
  const TOP = SZ + BIT + BODY + 14;
  fit(C, [[-26, -26, 0], [26, 26, 0], [26, -26, 0], [-26, 26, 0], [-24, 0, TOP], [24, 0, TOP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-26, -26, 26, 26, 5, 1.6);
  put(solid(g), prism(P, front, sr, si, 0, SZ));
  mk("path", { class: "nf lo", d: seg(P(3, 2, SZ), P(14, 9, SZ)) + seg(P(14, 9, SZ), P(21, 6, SZ)) + seg(P(-3, 4, SZ), P(-6, 17, SZ)) + seg(P(-3, -3, SZ), P(-14, -10, SZ)) }, g);
  const chips = [[8, -4], [-7, 6], [6, 8], [-6, -7]].map(([x, y]) => ({ x, y, el: flatDot(g, C, 1.6, "dot off") }));
  const bit = mk("path", { class: "sil" }, g), collar = solid(g), body = solid(g), neck = solid(g), handle = solid(g);
  const hose = mk("path", { class: "nf lo" }, g);
  handle.sil.classList.add("hi");
  const [cr, ci] = rings(-6, -6, 6, 6, 5, 1), [br, bi] = rings(-10, -10, 10, 10, 9, 1.6), [nr, ni] = rings(-3.5, -3.5, 3.5, 3.5, 3, 0.8);

  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const drop = BIT * 0.7 * p, zb = SZ + BIT - drop, top = zb + 6 + BODY;
    bit.setAttribute("d", poly(hull(ringAt(P, disc(0, 0, 2.6), SZ).concat(ringAt(P, disc(0, 0, 2.6), zb)))));
    put(collar, prism(P, front, cr, ci, zb, zb + 6));
    put(body, prism(P, front, br, bi, zb + 6, top));
    put(neck, prism(P, front, nr, ni, top, top + 6));
    const w = 18 + 4 * p, [hr, hh] = rings(-w, -2.5, w, 2.5, 2.4, 0.7);
    put(handle, prism(P, front, hr, hh, top + 6, top + 10));
    hose.setAttribute("d", seg(P(8, 6, top - 8), P(18, 14, top - 12)) + seg(P(18, 14, top - 12), P(22, 20, SZ + 2)));
    chips.forEach((c, i) => {
      const up = p * (5 + i * 3);
      place(c.el, P(c.x * (0.6 + p), c.y * (0.6 + p), SZ + up));
      c.el.setAttribute("class", p > 0.6 && i === 0 ? "dot m" : "dot off");
    });
  }

  const press = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(press, dt); draw(press.x); return m; });
  bag.add(B.unregister);
  const ax = P(0, 0, SZ + 40);

  function aim(pt) {
    const d = Math.hypot(pt[0] - ax[0], (pt[1] - ax[1]) * 0.5);
    if (d > 110) return leave();
    const f = clamp(1 - d / 110, 0.1, 1) * (0.35 + 0.65 * stroke / 100);
    press.t = clamp(f * 1.3, REST * 0.5, 1);
    read.textContent = Math.round(press.t * BIT * 0.7) + " mm";
    B.wake();
  }
  function leave() { press.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { stroke = v; }, destroy: bag.dispose };
}

hairline({
  name: "jackhammer",
  means: "A breaker on its chisel in a slab of road: the nearer the pointer, the further the body drives down the chisel and chips fly.",
  rules: [1, 3, 5, 8],
  range: [0, 60, 100],
  tour: [[200, 130], [200, 204], [214, 170], null],
  mount,
});

scaffoldtower.code:
/**
 * Scaffold tower: a mobile tower on four castors, a braced lower frame and a
 * telescoping top stage, its platform and guard rails riding up out of the
 * lower posts. The nearer the pointer comes, the higher the top stage climbs.
 * At rest it stands part raised, platform bright. The slider sets the climb.
 */
const {
  Cam, clamp, fit, facing, poly, prism, proj, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 34, D = 22, WH = 8, LOW = 64, RISE = 40, REST = 0.3;
const CORN = [[-W, -D], [W, -D], [-W, D], [W, D]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let climb = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[-W - 3, -D - 3, 0], [W + 3, D + 3, 0], [W + 3, -D - 3, 0], [-W - 3, D + 3, 0], [-W, -D, LOW + RISE + 18], [W, D, LOW + RISE + 18]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x, y, r) => rings(x - r, y - r, x + r, y + r, r * 0.9, 0.4);
  const wheels = CORN.map(([x, y]) => { const s = solid(g); const [a, b] = rings(x - 3, y - 3, x + 3, y + 3, 2.8, 0.8); put(s, prism(P, front, a, b, 0, WH)); return s; });
  const braces = mk("path", { class: "nf lo" }, g);
  const lows = CORN.map(() => solid(g)), ups = CORN.map(() => solid(g));
  const backRail = mk("path", { class: "nf sil" }, g);
  const deck = solid(g);
  const frontRail = mk("path", { class: "nf sil" }, g);
  // the nearest corner's posts go after the deck
  lows[3].g.after(deck.g); ups[3].g.after(lows[3].g); frontRail.after(ups[3].g);
  deck.sil.classList.add("hi");
  const [dr, di] = rings(-W - 1, -D - 1, W + 1, D + 1, 2, 1.2);
  let b = "";
  for (const z of [WH + 4, WH + 32, LOW - 2]) b += seg(P(-W, -D, z), P(W, -D, z)) + seg(P(-W, -D, z), P(-W, D, z)) + seg(P(W, -D, z), P(W, D, z)) + seg(P(-W, D, z), P(W, D, z));
  b += seg(P(-W, D, WH + 4), P(W, D, WH + 32)) + seg(P(W, -D, WH + 32), P(W, D, LOW - 2)) + seg(P(-W, -D, WH + 4), P(W, -D, WH + 32));
  braces.setAttribute("d", b);
  CORN.forEach(([x, y], i) => { const [a, c] = post(x, y, 1.8); put(lows[i], prism(P, front, a, c, WH, LOW)); });

  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const zp = LOW + RISE * p, top = zp + 18;
    CORN.forEach(([x, y], i) => { const [a, c] = post(x, y, 1.3); put(ups[i], prism(P, front, a, c, LOW - 6, top)); });
    put(deck, prism(P, front, dr, di, zp - 2, zp));
    const r = (z) => [seg(P(-W, -D, z), P(W, -D, z)) + seg(P(-W, -D, z), P(-W, D, z)), seg(P(W, -D, z), P(W, D, z)) + seg(P(-W, D, z), P(W, D, z))];
    const a = r(top), m = r(zp + 9);
    backRail.setAttribute("d", a[0] + m[0]);
    frontRail.setAttribute("d", a[1] + m[1]);
  }

  const lift = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);
  const ax = P(0, 0, LOW);

  function aim(pt) {
    const d = Math.hypot(pt[0] - ax[0], (pt[1] - ax[1]) * 0.6);
    if (d > 120) return leave();
    lift.t = clamp(clamp(1.25 - d / 100, 0.15, 1) * (0.3 + 0.7 * climb / 100), 0.1, 1);
    read.textContent = "+" + Math.round(lift.t * RISE) + " cm";
    B.wake();
  }
  function leave() { lift.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { climb = v; }, destroy: bag.dispose };
}

hairline({
  name: "scaffoldtower",
  means: "A mobile scaffold tower on castors: the nearer the pointer, the higher its telescoping top stage and platform climb.",
  rules: [1, 3, 5, 8],
  range: [0, 60, 100],
  tour: [[200, 146], [200, 220], [184, 90], null],
  mount,
});

skiplorry.code:
/**
 * Skip lorry: a cab and flat chassis on three axles with two lifting arms
 * pivoting at the back, a flared skip hung from their tips on chains. The
 * nearer the pointer comes, the further the arms swing up and over the tail,
 * carrying the skip off the bed and down behind the lorry. At rest the skip
 * rides on the bed, its rim bright. The slider sets how far the arms swing.
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, rrect, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = -22, PZ = 20, L = 50, CH = 10, SH = 18, A0 = 32, A1 = 168, REST = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[-92, -12, 0], [58, 16, 0], [58, -14, 48], [-92, 12, 0], [-22, 0, 72], [-60, -12, 60]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => { const pts = circ(8, 18).map((q) => P(x + q.u, y, 8 + q.v)); return mk("path", { class: "sil", d: poly(pts) + seg(P(x, y, 8), P(x + 2.5, y, 8)) }, g); };
  [-46, -32, 40].forEach((x) => wheel(x, -13));
  const [cr, ci] = rings(-52, -12, 58, 12, 2, 1);
  put(solid(g), prism(P, front, cr, ci, 9, 15));
  const arm = (y) => mk("path", { class: "sil" }, g);
  const farArm = arm(-15), skip = solid(g), chains = mk("path", { class: "nf lo" }, g), nearArm = arm(15);
  const cab = solid(g);
  const [kr, ki] = rings(34, -13, 58, 13, 5, 1.4);
  put(cab, prism(P, front, kr, ki, 15, 48));
  mk("path", { class: "nf lo", d: open([P(58, -10, 30), P(58, -10, 44), P(58, 10, 44), P(58, 10, 30)]) + seg(P(46, 13, 22), P(46, 13, 44)) }, g);
  [-46, -32, 40].forEach((x) => wheel(x, 13));
  skip.sil.classList.add("hi");
  const foot = rrect(-13, -10, 13, 10, 2, 4), top = rrect(-19, -11, 19, 11, 2, 4), inner = rrect(-17.6, -9.6, 17.6, 9.6, 1.2, 4);
  const at = (ring, dx) => ring.map((q) => ({ ...q, u: q.u + dx }));
  const armPath = (y, tx, tz) => {
    const dx = tx - PX, dz = tz - PZ, n = Math.hypot(dx, dz), ox = -dz / n * 2, oz = dx / n * 2;
    return poly([P(PX + ox, y, PZ + oz), P(tx + ox, y, tz + oz), P(tx - ox, y, tz - oz), P(PX - ox, y, PZ - oz)]);
  };

  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const th = rad(lerp(A0, A1, p)), tx = PX + L * Math.cos(th), tz = PZ + L * Math.sin(th);
    const z1 = tz - CH, z0 = z1 - SH;
    farArm.setAttribute("d", armPath(-15, tx, tz));
    nearArm.setAttribute("d", armPath(15, tx, tz));
    skip.sil.setAttribute("d", poly(hull(ringAt(P, at(foot, tx), z0).concat(ringAt(P, at(top, tx), z1)))));
    skip.cr.setAttribute("d", open(ringAt(P, run(at(inner, tx), front), z1)));
    chains.setAttribute("d", [-1, 1].map((s) => seg(P(tx, 15 * s, tz), P(tx - 16, 11 * s, z1)) + seg(P(tx, 15 * s, tz), P(tx + 16, 11 * s, z1))).join(""));
  }

  const swing = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(swing, dt); draw(swing.x); return m; });
  bag.add(B.unregister);
  const ax = P(-10, 0, 24);

  function aim(pt) {
    const d = Math.hypot(pt[0] - ax[0], (pt[1] - ax[1]) * 0.7);
    if (d > 150) return leave();
    swing.t = clamp(1.2 - d / 120, 0.12, 1) * (0.3 + 0.7 * reach / 100);
    read.textContent = Math.round(lerp(A0, A1, swing.t)) + "°";
    B.wake();
  }
  function leave() { swing.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

