  name: "skiplorry",
  means: "A skip lorry: the nearer the pointer, the further its two arms swing up over the tail, lifting the skip off the bed and down behind.",
  rules: [1, 3, 5, 8],
  range: [0, 70, 100],
  tour: [[264, 165], [205, 200], [150, 165], null],
  mount,
});

watertower.code:
/**
 * Water tower: a round tank on four splayed legs, under a conical roof
 * hinged at one side. The pointer near the roof swings it open, wider the
 * nearer it comes, showing the tank's open mouth. At rest the roof is
 * shut, bright. The slider is the widest swing.
 *
 * The pattern: one lid turning on a hinge (open).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, ringAt, run, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 38, LZ = 40, TZ = 84, RZ = 104, LF = 36, LT = 26;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function rot(p, a) {
  const T0 = -(R + 3), d = (p[0] + p[1]) / Math.SQRT2, t = (p[0] - p[1]) / Math.SQRT2 - T0, rz = p[2] - TZ;
  const s = Math.sin(rad(a)), c = Math.cos(rad(a));
  const t2 = t * c - rz * s + T0, z2 = t * s + rz * c;
  return [(d + t2) / Math.SQRT2, (d - t2) / Math.SQRT2, TZ + z2];
}
const roofPts = () => circ(R + 3, 40).map((q) => [q.u, q.v, TZ]).concat([[0, 0, RZ], [0, 0, RZ + 5]]);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.62);
  fit(C, [[-LF - 3, -LF - 3, 0], [LF + 3, LF + 3, 0], [LF + 3, -LF - 3, 0], [-LF - 3, LF + 3, 0], [0, 0, RZ + 5]].concat(roofPts().map((p) => rot(p, 85))), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const post = (x0, y0, x1, y1) => {
    const pts = circ(2.4, 12).map((q) => P(x0 + q.u, y0 + q.v, 0)).concat(circ(2.4, 12).map((q) => P(x1 + q.u, y1 + q.v, LZ)));
    mk("path", { d: poly(hull(pts)) }, g);
  };
  const legs = [[-1, -1], [1, -1], [-1, 1], [1, 1]];
  legs.slice(0, 3).forEach(([a, b]) => post(a * LF, b * LF, a * LT, b * LT));
  // cross braces between the legs, two tiers
  let br = "";
  for (const f of [0.35, 0.7]) {
    const at = ([a, b]) => P(a * lerpL(f), b * lerpL(f), LZ * f);
    br += open([at([-1, 1]), at([1, 1]), at([1, -1])]) + open([at([-1, 1]), at([1, -1])]);
  }
  function lerpL(f) { return LF + (LT - LF) * f; }
  mk("path", { d: br, class: "nf lo" }, g);
  post(LF, LF, LT, LT);
  const tank = mk("g", {}, g);
  put(solid(tank), prism(P, front, disc(0, 0, R), disc(0, 0, R - 2.5), LZ, TZ));
  put(solid(tank), prism(P, front, disc(0, 0, R + 2), disc(0, 0, R - 0.5), LZ - 4, LZ));
  mk("path", { d: open(ringAt(P, run(disc(0, 0, R), front), LZ + 14)) + open(ringAt(P, run(disc(0, 0, R), front), LZ + 27)), class: "nf lo" }, tank);
  const mouth = mk("path", { class: "nf lo" }, tank);
  const roof = mk("g", {}, g);
  const rs = mk("path", { class: "sil hi" }, roof);
  const rc = mk("path", { class: "nf lo" }, roof);
  const ang = spring(0);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = roofPts().map((p) => P(...rot(p, a)));
    rs.setAttribute("d", poly(hull(pts)));
    const rim = circ(R + 1, 40);
    const keep = a < 6 ? run(rim, front) : rim;
    const ring = keep.map((q) => P(...rot([q.u, q.v, TZ], a)));
    rc.setAttribute("d", a < 6 ? open(ring) : poly(ring));
    mouth.setAttribute("d", a > 4 ? poly(ringAt(P, disc(0, 0, R - 4), TZ)) : "");
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  const tp = P(0, 0, TZ + 8);
  let tgt = null, lastP = null;
  function turn(p) {
    lastP = p;
    let a = 0;
    if (p) {
      const dd = Math.hypot(p[0] - tp[0], p[1] - tp[1]);
      if (dd < 150) a = maxA * clamp(1.15 - dd / 130, 0.3, 1);
    }
    a = Math.round(a);
    if (a === tgt) return;
    tgt = a;
    ang.t = a;
    read.textContent = !p || a === 0 ? "rest" : "roof " + a + "°";
    B.wake();
  }
  turn(null);
  draw(0);
  bag.add(pointer(stage, { move: turn, leave: () => turn(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; tgt = null; turn(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "watertower",
  means: "A water tower on four legs: the pointer near the top swings its conical roof open on a side hinge, showing the tank's mouth.",
  rules: [1, 3, 5, 6],
  range: [40, 65, 85],
  tour: [[206, 132], [228, 156], [184, 196], null],
  mount,
});

dredger.code:
/**
 * Dredger: a flat hull with a tall gantry carrying a long bucket ladder.
 * The pointer near the bow swings the ladder down into the water, steeper
 * the nearer it comes, and the bucket chain runs on along it. At rest the
 * ladder is raised, bright. The slider is the steepest swing.
 *
 * The pattern: one long arm turning on a pivot (tilt).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 0, PZ = 50, L = 96, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.6);
  const tipAt = (a) => [PX + L * Math.cos(rad(a)), 0, PZ - L * Math.sin(rad(a))];
  fit(C, [[-70, -26, 0], [40, 26, 0], [-70, 26, 0], [40, -26, 0], [0, 0, PZ + 8], tipAt(REST), tipAt(60), [PX + 30, 0, -10]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  mk("path", { d: poly([P(-80, -36, 0), P(52, -36, 0), P(52, 36, 0), P(-80, 36, 0)]), class: "nf dash" }, g);
  const [hr, hi] = rings(-66, -22, 34, 22, 10, 1.8);
  put(solid(g), prism(P, front, hr, hi, 0, 14));
  const [cr, ci] = rings(-58, -14, -30, 14, 4, 1.4);
  put(solid(g), prism(P, front, cr, ci, 14, 34));
  const box = (x0, y0, z0, x1, y1, z1) => {
    const pts = [];
    for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) pts.push(P(x, y, z));
    return poly(hull(pts));
  };
  mk("path", { d: box(PX - 3, -16, 14, PX + 3, -12, PZ + 4) }, g);
  mk("path", { d: box(PX - 3, -16, PZ, PX + 3, 16, PZ + 5) }, g);
  const arm = mk("g", {}, g);
  const lad = mk("path", { class: "sil hi" }, arm);
  const rail = mk("path", { class: "nf lo" }, arm);
  const bk = mk("path", { class: "" }, arm);
  mk("path", { d: box(PX - 3, 12, 14, PX + 3, 16, PZ + 4) }, g);
  const ang = spring(REST), run = spring(0);
  let last = NaN;
  function draw(a, r) {
    const key = a.toFixed(2) + r.toFixed(2);
    if (key === last) return;
    last = key;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const at = (u, y, w) => P(PX + u * c + w * s, y, PZ - u * s + w * c);
    const pts = [];
    for (const u of [-4, L]) for (const y of [-6, 6]) for (const w of [-4, 2]) pts.push(at(u, y, w));
    lad.setAttribute("d", poly(hull(pts)));
    rail.setAttribute("d", open([at(0, -6, -4), at(L, -6, -4)]) + open([at(0, 6, 2), at(L - 4, 6, 2)]));
    let d = "";
    for (let i = 0; i < 6; i++) {
      const u = 10 + ((i * 16 + r) % 90);
      const q = [];
      for (const du of [-5, 5]) for (const y of [-7, 7]) for (const w of [-4, -13]) q.push(at(u + du * (w < -5 ? 1.3 : 1), y, w));
      d += poly(hull(q));
    }
    bk.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); const n = stepS(run, dt); draw(ang.x, run.x); return m || n; });
  bag.add(B.unregister);

  const tp = P(...tipAt(REST + 10));
  let tgt = null, lastP = null;
  function turn(p) {
    lastP = p;
    let a = REST;
    if (p) {
      const dd = Math.hypot(p[0] - tp[0], p[1] - tp[1]);
      if (dd < 160) a = REST + (maxA - REST) * clamp(1.15 - dd / 140, 0.3, 1);
    }
    a = Math.round(a);
    if (a === tgt) return;
    tgt = a;
    ang.t = a;
    run.t = (a - REST) * 0.6;
    read.textContent = !p || a === REST ? "rest" : "ladder " + a + "°";
    B.wake();
  }
  turn(null);
  draw(REST, 0);
  bag.add(pointer(stage, { move: turn, leave: () => turn(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; tgt = null; turn(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "dredger",
  means: "A bucket-ladder dredger: the pointer near the bow swings the long ladder down into the water and the bucket chain runs on.",
  rules: [1, 3, 5, 6],
  range: [35, 48, 60],
  tour: [[292, 171], [254, 150], [196, 128], null],
  mount,
});

liftbridge.code:
/**
 * Lift bridge: a truss span hung between two tall towers, with counterweights
 * riding outside them on cables over the tower tops. The pointer over the
 * bridge raises the whole span straight up, level, while the counterweights
 * sink. At rest the span sits just above its seats, bright. The slider is how
 * high it lifts.
 */
const {
  Cam, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 96, Wd = 22, TW = 14, TH = 84, REST = 10, DK = 5, TR = 11;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-TW - 12, -2, 0], [L + TW + 12, Wd + 2, 0], [-TW - 12, Wd + 2, 0], [L + TW + 12, -2, 0], [-TW, 0, TH + 4], [L + TW, Wd, TH + 4]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b) => { const [ring, inner] = rings(x0, y0, x1, y1, r, b); const s = solid(g); return (z0, z1) => put(s, prism(P, front, ring, inner, z0, z1)); };
  // far counterweight, far tower, cables, span, near tower, near counterweight
  const cwA = box(-TW - 11, 5, -TW - 2, Wd - 5, 1.5, 1);
  box(-TW, -1, 0, Wd + 1, 2, 1.2)(0, TH);
  const cab = mk("path", { class: "nf lo" }, g);
  const deck = box(1, 0, L - 1, Wd, 1.5, 1.2);
  const truss = mk("path", { class: "nf" }, g);
  box(L, -1, L + TW, Wd + 1, 2, 1.2)(0, TH);
  const cwB = box(L + TW + 2, 5, L + TW + 11, Wd - 5, 1.5, 1);
  // the deck's bright silhouette is the rest mark and the answer
  g.querySelectorAll(".sil")[2].classList.add("hi");

  const th = tween(REST);
  let last = NaN;
  function draw(h) {
    if (h === last) return;
    last = h;
    deck(h, h + DK);
    const top = h + DK + TR;
    let t = "";
    for (const y of [1, Wd - 1]) {
      t += seg(P(3, y, top), P(L - 3, y, top));
      for (let i = 0; i <= 8; i++) {
        const x = 3 + (i * (L - 6)) / 8;
        t += seg(P(x, y, h + DK), P(x, y, top));
        if (i < 8) t += seg(P(x, y, i < 4 ? top : h + DK), P(x + (L - 6) / 8, y, i < 4 ? h + DK : top));
      }
    }
    truss.setAttribute("d", t);
    const cw = TH - 14 - (h - REST) * 0.9;
    cwA(cw - 16, cw); cwB(cw - 16, cw);
    let c = "";
    for (const y of [3, Wd - 3]) {
      c += seg(P(-2, y, top), P(-2, y, TH)) + seg(P(-TW, y, TH), P(-TW - 6, y, TH)) + seg(P(-TW - 6, y, TH), P(-TW - 6, y, cw));
      c += seg(P(L + 2, y, top), P(L + 2, y, TH)) + seg(P(L + TW, y, TH), P(L + TW + 6, y, TH)) + seg(P(L + TW + 6, y, TH), P(L + TW + 6, y, cw));
    }
    cab.setAttribute("d", c);
  }
  const B = register(stage, (_dt, now) => { draw(tval(th, now)); return !tdone(th, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(th, a < 0 ? REST : REST + 50 * lift, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "up " + Math.round(50 * lift);
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    setActive(x > -TW - 14 && x < L + TW + 14 && y > -30 && y < Wd + 30 ? 1 : -1);
  }
  setActive(-1);
  bag.add(pointer(stage, { move, leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; if (act >= 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "liftbridge",
  means: "A truss span between two towers: the pointer over the bridge lifts the whole deck straight up while the counterweights sink.",
  rules: [1, 3, 4, 5],
  range: [0.3, 1, 1],
  tour: [[200, 204], [165, 190], [235, 222], null],
  mount,
});

heliostat.code:
/**
 * Heliostat: a faceted mirror on a two-axis head atop a slim pedestal. The
 * pointer is the sun: the mirror tilts and swings to face it, on a spring,
 * and comes back to a gentle lean toward the viewer when the pointer leaves.
 * The mirror's rim is the one bright mark. The slider is how far it may tilt.
 */
const {
  Cam, circ, clamp, fillet, fit, facing, hull, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const A = 36, Bh = 23, TK = 2.2, PZ = 48, OFF = 6, REST = [0.62, 0.12];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.75);
  fit(C, [[-40, -40, 0], [40, 40, 0], [-40, 40, 0], [40, -40, 0], [0, 0, PZ + 26], [-30, 30, PZ + 24], [30, -30, PZ + 24]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const stand = mk("g", {}, g);
  put(solid(stand), prism(P, front, circ(14, 40), circ(12.6, 40), 0, 3));
  put(solid(stand), prism(P, front, circ(3.6, 24), circ(2.8, 24), 3, PZ - 4));
  const [gr, gi] = rings(-5, -5, 5, 5, 2, 1);
  put(solid(stand), prism(P, front, gr, gi, PZ - 5, PZ + 4));
  const pg = mk("g", {}, g), arm = mk("path", { class: "nf" }, pg), panel = solid(pg), facets = mk("path", { class: "nf lo" }, pg);
  panel.sil.classList.add("hi");

  const hx = spring(REST[0]), hy = spring(REST[1]);
  let last = "", over = null;
  function draw() {
    const key = hx.x.toFixed(3) + "," + hy.x.toFixed(3);
    if (key === last) return;
    last = key;
    const s = clamp(Math.hypot(hx.x, hy.x), 0.05, 0.97), az = Math.atan2(hy.x, hx.x), c = Math.sqrt(1 - s * s);
    const n = [s * Math.cos(az), s * Math.sin(az), c], u = [-Math.sin(az), Math.cos(az), 0];
    const v = [n[1] * u[2] - n[2] * u[1], n[2] * u[0] - n[0] * u[2], n[0] * u[1] - n[1] * u[0]];
    const o = [n[0] * OFF, n[1] * OFF, PZ + n[2] * OFF];
    const W = (a, b, t) => [o[0] + a * u[0] + b * v[0] + t * n[0], o[1] + a * u[1] + b * v[1] + t * n[1], o[2] + a * u[2] + b * v[2] + t * n[2]];
    const Q = (a, b, t) => P(...W(a, b, t));
    const corners = [];
    for (const a of [-A, A]) for (const b of [-Bh, Bh]) for (const t of [-TK / 2, TK / 2]) corners.push(Q(a, b, t));
    // which face looks at the camera: compare the screen order of a face's corners
    const p0 = Q(-A, -Bh, 0), p1 = Q(A, -Bh, 0), p2 = Q(-A, Bh, 0);
    const cross = (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0]);
    const t = cross < 0 ? TK / 2 : -TK / 2, i = 2;
    { const h = hull(corners); panel.sil.setAttribute("d", poly(fillet(h, h.map(() => 2.5)))); }
    panel.cr.setAttribute("d", poly([Q(-A + i, -Bh + i, t), Q(A - i, -Bh + i, t), Q(A - i, Bh - i, t), Q(-A + i, Bh - i, t)]));
    let f = "";
    for (const a of [-A / 3, A / 3]) f += seg(Q(a, -Bh + i, t), Q(a, Bh - i, t));
    f += seg(Q(-A + i, 0, t), Q(A - i, 0, t));
    facets.setAttribute("d", f);
    arm.setAttribute("d", open([P(0, 0, PZ), P(...W(0, 0, -TK / 2))]));
    // the mirror's lower edge behind the pedestal: paint it first
    const lo = v[2] > 0 ? W(0, -Bh, 0) : W(0, Bh, 0);
    if (lo[0] + lo[1] < -3) g.prepend(pg); else g.append(pg);
  }
  const B = register(stage, (dt) => { const a = stepS(hx, dt), b = stepS(hy, dt); draw(); return a || b; });
  bag.add(B.unregister);

  function retarget() {
    let tx = REST[0], ty = REST[1];
    if (over) {
      const [x, y] = over, r = Math.hypot(x, y) || 1, s = clamp(r / 70, 0.3, 1) * 0.94 * reach;
      tx = (x / r) * s; ty = (y / r) * s;
      read.textContent = "tilt " + Math.round((Math.asin(clamp(Math.hypot(tx, ty), 0, 1)) * 180) / Math.PI);
    } else read.textContent = "rest";
    hx.t = tx; hy.t = ty;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); over = Math.hypot(x, y) > 120 ? null : [x, y]; retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "heliostat",
  means: "A faceted mirror on a pedestal: the pointer is the sun, and the mirror tilts and swings round to face it.",
  rules: [1, 3, 4, 5],
  range: [0.3, 1, 1],
  tour: [[64, 202], [300, 180], [220, 262], null],
  mount,
});

tunnelboring.code:
/**
 * Tunnel boring machine: a long round shield lying on its cradle, with a
 * spoked cutter head on its nose. The pointer over the machine drives the
 * head: it turns and thrusts forward out of the shield, then draws back and
 * settles when the pointer leaves. The cutter head's rim is the bright mark.
 * The slider is how far it turns and thrusts.
 */
const {
  Cam, fit, hull, poly, proj, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, register,
} = HL;

const R = 24, LEN = 92, HD = 7, N = 40;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -R - 4, 0], [LEN + HD + 30, R + 4, 0], [-4, R + 4, 0], [LEN + HD + 30, -R - 4, 0], [0, 0, 2 * R + 6], [LEN + HD + 30, 0, 2 * R + 6]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const ringAtX = (x, r, cz = R + 2) => Array.from({ length: N }, (_, i) => { const t = (i / N) * Math.PI * 2; return P(x, r * Math.cos(t), cz + r * Math.sin(t)); });
  // cradle, shield and its seams
  mk("path", { d: poly(hull([P(8, -R + 4, 0), P(LEN - 8, -R + 4, 0), P(LEN - 8, R - 4, 0), P(8, R - 4, 0), P(8, -R + 4, 6), P(LEN - 8, -R + 4, 6), P(LEN - 8, R - 4, 6), P(8, R - 4, 6)])), class: "sil" }, g);
  mk("path", { d: poly(hull(ringAtX(0, R).concat(ringAtX(LEN, R)))), class: "sil" }, g);
  let seams = "";
  for (const x of [LEN / 3, (2 * LEN) / 3]) { const r = ringAtX(x, R - 0.6); for (let i = 0; i < N; i++) { const a = r[i], b = r[(i + 1) % N]; const t = (i / N) * Math.PI * 2; if (Math.cos(t) > -0.2) seams += seg(a, b); } }
  mk("path", { d: seams, class: "nf lo" }, g);
  const shaft = mk("path", { class: "sil" }, g);
  const head = mk("path", { class: "sil hi" }, g), face = mk("path", { class: "" }, g), spokes = mk("path", { class: "nf" }, g), hub = mk("path", { class: "" }, g);

  const ph = tween(0);
  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const d = 26 * reach * p, a = 0.3 + p * Math.PI * 2.2 * reach, x0 = LEN + 1 + d, x1 = x0 + HD;
    shaft.setAttribute("d", poly(hull(ringAtX(LEN - 2, 9).concat(ringAtX(x0 + 1, 9)))));
    head.setAttribute("d", poly(hull(ringAtX(x0, R + 2).concat(ringAtX(x1, R + 2)))));
    face.setAttribute("d", poly(ringAtX(x1, R + 0.5)));
    let s = "";
    for (let k = 0; k < 6; k++) {
      const t = a + (k * Math.PI) / 3, c = Math.cos(t), si = Math.sin(t);
      s += seg(P(x1, 5 * c, R + 2 + 5 * si), P(x1, (R - 1) * c, R + 2 + (R - 1) * si));
      for (const f of [0.45, 0.75]) { const tt = t + 0.28; s += seg(P(x1, R * f * Math.cos(tt), R + 2 + R * f * Math.sin(tt)), P(x1, (R * f + 3) * Math.cos(tt), R + 2 + (R * f + 3) * Math.sin(tt))); }
    }
    spokes.setAttribute("d", s);
    hub.setAttribute("d", poly(ringAtX(x1 + 1.5, 5)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ph, now)); return !tdone(ph, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ph, a < 0 ? 0 : 1, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "bore " + Math.round(26 * reach);
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    setActive(x > -10 && x < LEN + HD + 34 && Math.abs(y) < R + 40 ? 1 : -1);
  }
  setActive(-1);
  bag.add(pointer(stage, { move, leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; draw(tval(ph, performance.now())); if (act >= 0) read.textContent = "bore " + Math.round(26 * reach); }, destroy: bag.dispose };
}

hairline({
  name: "tunnelboring",
  means: "A tunnel boring machine: the pointer over it turns its spoked cutter head and thrusts it forward out of the shield.",
  rules: [1, 3, 4, 5],
  range: [0.3, 1, 1],
  tour: [[182, 207], [130, 180], [250, 230], null],
  mount,
});

radarmast.code:
/**
 * Radar antenna: a lattice-free mast on a square plinth carrying a turntable
 * and a long flat antenna with a feed boom. The pointer is a bearing: the
 * antenna sweeps round on a spring to face it. At rest it faces a little off
 * broadside, bright. The slider is how far of the way round it sweeps.
 */
const {
  Cam, circ, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZM = 58, ZA0 = 66, ZA1 = 92, HL2 = 54, D = 3.5, BOOM = 26, REST = -0.4;

function rot(ring, a) {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-HL2, -HL2, 0], [HL2, HL2, 0], [HL2, -HL2, ZA1], [-HL2, HL2, ZA1], [-HL2, -HL2, ZA1], [HL2, HL2, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [pr, pi] = rings(-16, -16, 16, 16, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, 0, 8));
  const foot = rrect(-6, -6, 6, 6, 2, 6), top = rrect(-3.5, -3.5, 3.5, 3.5, 1.5, 6), tin = rrect(-2.5, -2.5, 2.5, 2.5, 1, 6);
  put(solid(g), { sil: poly(hull(ringAt(P, foot, 8).concat(ringAt(P, top, ZM)))), crease: open(ringAt(P, run(tin, front), ZM)) });
  put(solid(g), prism(P, front, circ(9, 32), circ(7.6, 32), ZM, ZA0 - 2));
  const back = mk("g", {}, g), ant = solid(g), slats = mk("path", { class: "nf lo" }, g), fore = mk("g", {}, g);
  ant.sil.classList.add("hi");
  const boom = mk("path", { class: "nf lo" }, back), horn = mk("path", { class: "sil" }, back);
  const [ar, ai] = rings(-HL2, -D, HL2, D, 2, 1);
  const [hr] = rings(-4, -3, 4, 3, 1.5, 0.8);

  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    put(ant, prism(P, front, rot(ar, a), rot(ai, a), ZA0, ZA1));
    const c = Math.cos(a), s = Math.sin(a), nx = -s, ny = c;
    let sl = "";
    for (const t of [-36, -18, 0, 18, 36]) sl += seg(P(t * c + nx * D, t * s + ny * D, ZA0 + 3), P(t * c + nx * D, t * s + ny * D, ZA1 - 3));
    slats.setAttribute("d", sl);
    const fx = nx * (D + BOOM), fy = ny * (D + BOOM);
    boom.setAttribute("d", seg(P(nx * D, ny * D, ZA0 + 4), P(fx, fy, ZA0 + 10)) + seg(P(nx * D, ny * D, ZA1 - 4), P(fx, fy, ZA0 + 10)));
    const hrr = hr.map((q) => ({ u: fx + q.u * c - q.v * s, v: fy + q.u * s + q.v * c }));
    horn.setAttribute("d", poly(hull(ringAt(P, hrr, ZA0 + 6).concat(ringAt(P, hrr, ZA0 + 14)))));
    const toCam = nx + ny > 0;
    if (toCam && boom.parentNode !== fore) { fore.append(boom, horn); }
    if (!toCam && boom.parentNode !== back) { back.append(boom, horn); }
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let over = null;
  function retarget() {
    let tgt = REST;
    if (over != null) {
      let d = over - REST;
      d = Math.atan2(Math.sin(d), Math.cos(d));
      tgt = REST + reach * d;
    }
    let dd = tgt - ang.t;
    dd = Math.atan2(Math.sin(dd), Math.cos(dd));
    ang.t += dd;
    const deg = Math.round((((-tgt * 180) / Math.PI) % 360 + 360) % 360);
    read.textContent = over == null ? "rest" : `brg ${deg}`;
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, (ZA0 + ZA1) / 2), r = Math.hypot(x, y);
    over = r < 6 || r > 150 ? null : Math.atan2(y, x) - Math.PI / 2;
    retarget();
  }
  bag.add(pointer(stage, { move, leave: () => { over = null; retarget(); } }));
  bag.add(() => svg.replaceChildren());
  retarget();
  draw(ang.x);
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "radarmast",
  means: "A radar mast whose long flat antenna and feed boom sweep round on a spring to face the pointer's bearing.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[294, 109], [106, 72], [260, 230], null],
  mount,
});

swingbridge.code:
/**
 * Swing bridge: a road deck balanced on a round pier in mid-channel, stayed
 * from a small tower at its middle, between two stone banks. The pointer over
 * the channel swings the deck round on its pivot to let boats through; leaving
 * swings it back. At rest it stands just off its banks, bright. The slider is
 * how far round it swings.
 */
const {
  Cam, circ, fit, facing, prism, proj, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BX = 46, BE = 70, BW = 44, ZB = 14, DL = 45, DW = 8.5, DT = 5.5, TZ = 38, REST = 0.1, OPEN = 1.5;

function spin(ring, a) {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.6);
  fit(C, [[-BE, -DL, -4], [BE, DL, -4], [BE, -DL, -4], [-BE, DL, -4], [0, -DL, TZ], [-BE, -BW, TZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [sr, si] = rings(-BE - 4, -DL - 4, BE + 4, DL + 4, 4, 1.6);
  put(solid(g), prism(P, front, sr, si, -4, 0));
  for (const [x0, x1] of [[-BE, -BX], [BX, BE]]) {
    const [r, i] = rings(x0, -BW, x1, BW, 3, 1.4);
    put(solid(g), prism(P, front, r, i, 0, ZB));
  }
  put(solid(g), prism(P, front, circ(9, 32), circ(7.6, 32), 0, ZB));
  const deck = solid(g), rails = mk("path", { class: "nf lo" }, g), stays = mk("path", { class: "nf lo" }, g), tower = solid(g);
  deck.sil.classList.add("hi");
  const [dr, di] = rings(-DL, -DW, DL, DW, 2, 1.2);
  const [tr, ti] = rings(-3.5, -5, 3.5, 5, 1.5, 0.8);

  const tw = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a), W = (u, v, z) => P(u * c - v * s, u * s + v * c, z);
    const z1 = ZB + DT;
    put(deck, prism(P, front, spin(dr, a), spin(di, a), ZB + 0.5, z1));
    let r = "";
    for (const v of [-DW + 1, DW - 1]) {
      r += seg(W(-DL + 3, v, z1 + 4), W(DL - 3, v, z1 + 4));
      for (let u = -DL + 3; u <= DL - 3; u += 11.5) r += seg(W(u, v, z1), W(u, v, z1 + 4));
    }
    rails.setAttribute("d", r);
    let st = "";
    for (const v of [-4, 4]) for (const u of [-DL + 4, -DL / 2, DL / 2, DL - 4]) st += seg(W(0, v * 0.6, TZ), W(u, v, z1 + 4));
    stays.setAttribute("d", st);
    put(tower, prism(P, front, spin(tr, a), spin(ti, a), z1, TZ));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(on) {
    if (on === act) return;
    act = on;
    const to = on > 0 ? REST + (OPEN - REST) * reach : REST;
    tset(tw, to, performance.now(), 0);
    read.textContent = on > 0 ? `${Math.round((to * 180) / Math.PI)}°` : "rest";
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, ZB);
    setActive(Math.abs(x) < BE + 10 && Math.abs(y) < DL + 10 ? 1 : -1);
  }
  bag.add(pointer(stage, { move, leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  setActive(-1);
  return { set: (v) => { reach = v; if (act > 0) { act = -2; setActive(1); } }, destroy: bag.dispose };
}

hairline({
  name: "swingbridge",
  means: "A swing bridge whose stayed road deck turns round on its mid-channel pier to open the way when the pointer comes over it.",
  rules: [1, 3, 4, 5],
  range: [0.3, 1, 1],
  tour: [[218, 175], [168, 120], [232, 220], null],
  mount,
});

steeldrum.code:
/**
 * Steel drum: a steel pan, a deep skirted bowl with hammered note fields,
 * hung on a tripod stand with two mallets resting across its face. The pan
 * swings on its stand to tip the note under the pointer toward the player,
 * and that note is bright. At rest the pan leans a little forward with the
 * centre note bright. The slider is how far the pan can swing.
 */
const { Cam, circ, clamp, fit, hull, poly, proj, seg, unproj, spring, stepS, disposer, mk, pointer, register } = HL;

const R = 50, Z0 = 62, D = 22, MAX = 0.42, REST = [0.1, 0.14];
const NOTES = [[0, 0, 9]].concat(Array.from({ length: 6 }, (_, i) => { const t = (i / 6) * Math.PI * 2 + 0.4; return [Math.cos(t) * 30, Math.sin(t) * 30, 8]; }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-R - 8, -R - 8, 0], [R + 8, R + 8, 0], [-R, R, Z0 + 20], [R, -R, Z0 + 20], [0, 0, Z0 + 24]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const legs = mk("path", { class: "nf sil" }, g);
  let ld = seg(P(0, 0, Z0 - D - 2), P(0, 0, Z0 - D - 16));
  for (let k = 0; k < 3; k++) { const a = 0.9 + k * 2.094; ld += seg(P(Math.cos(a) * 46, Math.sin(a) * 46, 0), P(0, 0, Z0 - D - 16)); }
  legs.setAttribute("d", ld);
  const body = mk("path", { class: "sil" }, g), top = mk("path", { class: "nf" }, g), bowl = mk("path", { class: "nf lo" }, g);
  const notes = NOTES.map(() => mk("path", { class: "nf lo" }, g));
  const sticks = mk("path", { class: "nf sil" }, g), tips = [mk("path", {}, g), mk("path", {}, g)];
  const tx = spring(REST[0]), ty = spring(REST[1]);
  let lim = MAX * value, last = "", pick = 0;
  function draw() {
    const key = tx.x.toFixed(3) + ty.x.toFixed(3);
    if (key === last) return;
    last = key;
    const a = tx.x, b = ty.x;
    const T = (x, y, z) => {
      const x1 = x * Math.cos(a) + z * Math.sin(a), z1 = -x * Math.sin(a) + z * Math.cos(a);
      const y2 = y * Math.cos(b) - z1 * Math.sin(b), z2 = y * Math.sin(b) + z1 * Math.cos(b);
      return P(x1, y2, Z0 + z2);
    };
    const ring = (r, z, cx = 0, cy = 0, n = 48) => circ(r, n).map((q) => T(cx + q.u, cy + q.v, z));
    body.setAttribute("d", poly(hull(ring(R, 0).concat(ring(R, -D), ring(R - 4, -D - 3)))));
    top.setAttribute("d", poly(ring(R, 0)));
    bowl.setAttribute("d", poly(ring(R - 3, -0.5)));
    NOTES.forEach(([x, y, r], i) => notes[i].setAttribute("d", poly(ring(r, -3, x, y, 24).map((p, j) => p))));
    const S = [[[-34, 8, 1], [20, 40, 1]], [[-30, 22, 1], [34, 30, 1]]];
    sticks.setAttribute("d", S.map(([p, q]) => seg(T(...p), T(...q))).join(""));
    S.forEach(([p], i) => tips[i].setAttribute("d", poly(ring(4, 3, p[0], p[1], 20))));
  }
  const B = register(stage, (dt) => { const m1 = stepS(tx, dt), m2 = stepS(ty, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);
  function aim(t, k) {
    tx.t = t[0]; ty.t = t[1];
    pick = k;
    notes.forEach((n, i) => { n.classList.toggle("hi", i === k); n.classList.toggle("lo", i !== k); });
    read.textContent = t === REST ? "rest" : "note " + (k + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], Z0), r = Math.hypot(x, y);
      if (r > R + 30) return aim(REST, 0);
      let k = 0, bd = Infinity;
      NOTES.forEach(([nx, ny], i) => { const d = Math.hypot(x - nx, y - ny); if (d < bd) { bd = d; k = i; } });
      if (r < 6) return aim([REST[0], REST[1] + 0.001], 0);
      const m = clamp(r / R, 0, 1) * lim;
      aim([-(x / r) * m, (y / r) * m], k);
    },
    leave: () => aim(REST, 0),
  }));
  bag.add(() => svg.replaceChildren());
  draw(); aim(REST, 0);
  return { set: (v) => { lim = MAX * v; }, destroy: bag.dispose };
}

hairline({
  name: "steeldrum",
  means: "A steel pan on its stand: the pan swings to tip the note under the pointer up, and that note is bright.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.5],
  tour: [[228, 122], [140, 70], [262, 128], null],
  mount,
});

frenchhorn.code:
/**
 * French horn: the coiled brass on a horn stand, three rotary valves with
 * their levers on top of the coil, the leadpipe running out to the
 * mouthpiece, and the wide bell flaring from the coil's side. The horn swivels
 * on its stand to point its bell at the pointer. At rest it turns its bell
 * toward the viewer with the bell's rim bright. The slider is how far it can
 * swing from rest.
 */
const { Cam, circ, clamp, fit, hull, open, poly, prism, proj, seg, unproj, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const H = 62, A0 = -0.6, MAX = 1.3;
const BELL = [[16, 3.5], [30, 6], [42, 10], [50, 17], [53, 22]];
const wrap = (a) => a - Math.PI * 2 * Math.round(a / (Math.PI * 2));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.3);
  const ext = [];
  for (let k = 0; k < 8; k++) { const t = (k / 8) * Math.PI * 2; ext.push([56 * Math.cos(t), 56 * Math.sin(t), H - 30], [40 * Math.cos(t), 40 * Math.sin(t), H + 34]); }
  ext.push([0, 0, 0]);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, () => true, circ(22, 48), circ(20.5, 48), 0, 2.5));
  mk("path", { class: "nf sil", d: seg(P(0, 0, 2.5), P(0, 0, H - 28)) }, g);
  const horn = mk("g", {}, g);
  const coil = mk("path", { class: "nf sil" }, horn), inner = mk("path", { class: "nf lo" }, horn);
  const pipe = mk("path", { class: "nf sil" }, horn), mouth = mk("path", {}, horn);
  const valves = [0, 1, 2].map(() => mk("path", { class: "sil" }, horn));
  const levers = mk("path", { class: "nf sil" }, horn);
  const bellG = mk("g", {}, g), bell = mk("path", { class: "sil" }, bellG), rim = mk("path", { class: "nf hi" }, bellG), throat = mk("path", { class: "nf lo" }, bellG);
  const sp = spring(A0);
  let lim = MAX * value, last = NaN, bellFirst = null;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - last) < 1e-4) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const T = (u, v, w) => P(u * c - v * s, u * s + v * c, H + w);
    const loop = (r, v, n = 56) => Array.from({ length: n + 1 }, (_, i) => { const t = (i / n) * Math.PI * 2; return T(r * Math.cos(t), v, r * Math.sin(t)); });
    coil.setAttribute("d", [26, 21].map((r, i) => open(loop(r, i * 3 - 1.5))).join(""));
    inner.setAttribute("d", open(loop(16, 3)));
    pipe.setAttribute("d", open([T(-10, 0, 25), T(-24, 0, 20), T(-38, 0, 12), T(-46, 0, 8)]));
    mouth.setAttribute("d", poly(hull(circ(3, 16).map((q) => T(-46, q.u, 8 + q.v)).concat(circ(1.5, 12).map((q) => T(-51, q.u, 7 + q.v))))));
    [-9, 0, 9].forEach((u, i) => valves[i].setAttribute("d", poly(hull(circ(3.6, 18).flatMap((q) => [T(u + q.u, -5, 27 + q.v), T(u + q.u, 5, 27 + q.v)])))));
    levers.setAttribute("d", [-9, 0, 9].map((u) => seg(T(u, 5, 27), T(u - 6, 9, 35))).join(""));
    const ring = (u, r) => circ(r, 40).map((q) => T(u, q.u, -12 + q.v));
    bell.setAttribute("d", poly(hull(BELL.flatMap(([u, r]) => ring(u, r)))));
    rim.setAttribute("d", poly(ring(53, 22)));
    throat.setAttribute("d", poly(ring(53, 13)));
    // the bell is painted after the coil when its axis turns toward the viewer
    const bf = c + s < 0;
    if (bf !== bellFirst) { bellFirst = bf; if (bf) horn.before(bellG); else horn.after(bellG); }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function aim(t) {
    sp.t = t === null ? A0 : A0 + clamp(wrap(t - A0), -lim, lim);
    read.textContent = t === null ? "rest" : Math.round(((sp.t - A0) * 180) / Math.PI) + "°";
    B.wake();
  }
  let over = null;
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], H - 12), r = Math.hypot(x, y);
      over = r < 8 || r > 110 ? null : Math.atan2(y, x);
      aim(over);
    },
    leave: () => { over = null; aim(null); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); aim(null);
  return { set: (v) => { lim = MAX * v; aim(over); }, destroy: bag.dispose };
}

hairline({
  name: "frenchhorn",
  means: "A French horn on its stand: the coiled brass swivels to point its bell at the pointer.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.6],
  tour: [[200, 250], [111, 140], [289, 140], null],
  mount,
});

timpani.code:
/**
 * Timpani: a copper kettle on three legs with a foot pedal, its head held by
 * a counterhoop and tension rods, two mallets resting on the head. The
 * pointer over the drum presses the pedal: the head rises on its rods to
 * tune up and both mallets swing high to strike, staggered. At rest the
 * pedal stands raised, bright. The slider is how far the head and mallets go.
 *
 * The pattern: one object answering as a whole; the hit is on the ground plane.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const R = 34, RZ = 58, L = 52, S = 2.45;
const SQ = Math.SQRT1_2;
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
function ring3(c, a, r, n = 16) {
  const h = Math.abs(a[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  let u = [a[1] * h[2] - a[2] * h[1], a[2] * h[0] - a[0] * h[2], a[0] * h[1] - a[1] * h[0]];
  const lu = Math.hypot(...u); u = u.map((q) => q / lu);
  const v = [a[1] * u[2] - a[2] * u[1], a[2] * u[0] - a[0] * u[2], a[0] * u[1] - a[1] * u[0]];
  return Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2, c1 = Math.cos(t) * r, s1 = Math.sin(t) * r; return [0, 1, 2].map((j) => c[j] + u[j] * c1 + v[j] * s1); });
}
const cyl = (a, b, r0, r1) => { const d = sub(b, a), l = Math.hypot(...d), ax = d.map((q) => q / l); return ring3(a, ax, r0).concat(ring3(b, ax, r1)); };
const ball = (c, r) => { let o = []; for (let i = -3; i <= 3; i++) { const z = (i / 3) * r; o = o.concat(ring3([c[0], c[1], c[2] + z], [0, 0, 1], Math.sqrt(Math.max(0, r * r - z * z)) + 0.01, 14)); } return o; };
const ANG = [Math.PI / 4 - 0.55, Math.PI / 4 + 0.55];
const BUTT = ANG.map((a) => [Math.cos(a) * (R + 30), Math.sin(a) * (R + 30), RZ + 10]);
const DROP = Math.asin(9 / L);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-R - 4, -R - 4, 0], [R + 34, R + 34, 0], [R + 4, -R - 4, 0], [-R - 4, R + 4, 0], [0, 0, RZ + 16], [-10, -10, RZ + 10 + L * 0.7 + 6], [BUTT[0][0], BUTT[0][1], RZ + 10 + L * 0.7], [BUTT[1][0], BUTT[1][1], RZ + 10 + L * 0.7]], 200, 170);
  const P = proj(C), front = facing(C);
  const pp = (pts) => pts.map((q) => P(...q));
  const g = mk("g", {}, svg);
  // legs and casters, away from the pedal side
  for (const a of [Math.PI / 4 + 2.1, Math.PI / 4 + Math.PI, Math.PI / 4 - 2.1]) {
    const foot = [Math.cos(a) * 30, Math.sin(a) * 30, 4];
    mk("path", { d: poly(hull(pp(cyl([Math.cos(a) * 8, Math.sin(a) * 8, 22], foot, 2, 2)))), class: "sil" }, g);
    mk("path", { d: poly(hull(pp(ball(foot, 4)))), class: "sil" }, g);
  }
  // the pedal: a footplate hinged at its back end, on a strut under the kettle
  mk("path", { d: poly(hull(pp(cyl([0, 0, 22], [SQ * 10, SQ * 10, 4], 2.2, 2.2)))), class: "sil" }, g);
  const pedal = mk("path", { class: "sil" }, g);
  // the kettle: a deep bowl, hull of its rings
  const bowl = [];
  for (let i = 0; i <= 8; i++) { const t = i / 8, r = 9 + (R - 9) * Math.sin((t * Math.PI) / 2), z = 20 + (RZ - 20) * Math.pow(t, 0.7); bowl.push(...pp(circ(r, 40).map((q) => [q.u, q.v, z]))); }
  mk("path", { d: poly(hull(bowl)), class: "sil" }, g);
  const arc = [];
  for (let i = 0; i <= 20; i++) { const a = Math.PI / 4 - 1.3 + (i / 20) * 2.6; arc.push(P(Math.cos(a) * (R - 1.5), Math.sin(a) * (R - 1.5), RZ - 9)); }
  mk("path", { d: open(arc), class: "nf lo" }, g);
  const rods = mk("path", { class: "nf" }, g);
  const hoop = solid(g);
  const mallets = BUTT.map((b) => {
    const grp = mk("g", {}, g);
    return { b, body: mk("path", { class: "sil" }, grp), tip: mk("path", { class: "sil" }, grp), up: tween(0) };
  });
  const press = tween(0);
  let last = "";

  function draw(now) {
    const p = tval(press, now), a = mallets.map((m) => tval(m.up, now)), key = p + "," + a.join() + amp;
    if (key === last) return;
    last = key;
    const lift = p * amp * 12, hz = RZ + lift;
    // pedal tilts down from 16° as the head rises
    const tilt = (1 - p * clamp(amp + 0.2, 0, 1)) * 0.3, d = [SQ, SQ], n = [-SQ, SQ];
    const pt = (s, w, h) => [d[0] * (10 + s * Math.cos(tilt)) + n[0] * w, d[1] * (10 + s * Math.cos(tilt)) + n[1] * w, 3 + s * Math.sin(tilt) + h];
    const plate = [];
    for (const s of [0, 24]) for (const w of [-7, 7]) for (const h of [0, 2.5]) plate.push(P(...pt(s, w, h)));
    pedal.setAttribute("d", poly(hull(plate)));
    let rd = "";
    for (let i = 0; i < 5; i++) {
      const q = Math.PI / 4 - 1.2 + i * 0.6, c = Math.cos(q), s = Math.sin(q);
      const lo = P(c * (R + 1.5), s * (R + 1.5), RZ - 12), hi = P(c * (R + 1.5), s * (R + 1.5), hz + 1);
      rd += `M${lo[0]},${lo[1]}L${hi[0]},${hi[1]}`;
    }
    rods.setAttribute("d", rd);
    put(hoop, prism(P, front, circ(R + 2.5, 48), circ(R + 0.5, 48), hz - 2, hz + 2));
    mallets.forEach((m, k) => {
      const e = -DROP + a[k] * amp * 0.9, dir = [-Math.cos(ANG[k]) * Math.cos(e), -Math.sin(ANG[k]) * Math.cos(e), Math.sin(e)];
      const tip = [0, 1, 2].map((j) => m.b[j] + dir[j] * L + (j === 2 ? lift * (1 - a[k]) : 0));
      m.body.setAttribute("d", poly(hull(pp(cyl(m.b, tip, 1.8, 1.4)))));
      m.tip.setAttribute("d", poly(hull(pp(ball(tip, 5.5)))));
    });
  }

  const B = register(stage, (_dt, now) => { draw(now); return !(tdone(press, now) && mallets.every((m) => tdone(m.up, now))); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(on) {
    const id = on ? 1 : -1;
    if (id === act) return;
    act = id;
    const now = performance.now();
    tset(press, on ? 1 : 0, now, 0);
    mallets.forEach((m, k) => tset(m.up, on ? 1 : 0, now, on ? 60 + k * 60 : 0));
    pedal.classList.toggle("hi", !on);
    hoop.sil.classList.toggle("hi", on);
    read.textContent = on ? "+" + Math.round(amp * 12) + " mm" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0), [u, v] = unproj(C, p[0], p[1], RZ); setActive(Math.hypot(x - 6, y - 6) < R + 34 || Math.hypot(u, v) < R + 8); },
    leave: () => setActive(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 0.2, 1); last = ""; if (act > 0) read.textContent = "+" + Math.round(amp * 12) + " mm"; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "timpani",
