clarinet.code:
/**
 * Clarinet: a clarinet standing on a three-legged peg stand, bell down, its
 * lower joint, upper joint, barrel and mouthpiece stacked with ring keys
 * down the front. The pointer over it draws the upper joint, barrel and
 * mouthpiece up off the lower tenon, as when taking it apart. At rest the
 * bell is bright. The slider is how far the upper half comes off.
 *
 * The pattern: one object answering as a whole; the hit is the rest pose.
 */
const {
  Cam, clamp, fit, hull, poly, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const S = 1.3, LIFT = 28, LEG = 62;
const SQ = Math.SQRT1_2;
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
function ring3(c, a, r, n = 18) {
  const h = Math.abs(a[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  let u = [a[1] * h[2] - a[2] * h[1], a[2] * h[0] - a[0] * h[2], a[0] * h[1] - a[1] * h[0]];
  const lu = Math.hypot(...u); u = u.map((q) => q / lu);
  const v = [a[1] * u[2] - a[2] * u[1], a[2] * u[0] - a[0] * u[2], a[0] * u[1] - a[1] * u[0]];
  return Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2, c1 = Math.cos(t) * r, s1 = Math.sin(t) * r; return [0, 1, 2].map((j) => c[j] + u[j] * c1 + v[j] * s1); });
}
const cyl = (a, b, r0, r1) => { const d = sub(b, a), l = Math.hypot(...d), ax = d.map((q) => q / l); return ring3(a, ax, r0).concat(ring3(b, ax, r1)); };
const ball = (c, r) => { let o = []; for (let i = -3; i <= 3; i++) { const z = (i / 3) * r; o = o.concat(ring3([c[0], c[1], c[2] + z], [0, 0, 1], Math.sqrt(Math.max(0, r * r - z * z)) + 0.01, 14)); } return o; };
const up = (z0, z1, r0, r1) => cyl([0, 0, z0], [0, 0, z1], r0, r1);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-LEG, -LEG, 0], [LEG, LEG, 0], [LEG, -LEG, 0], [-LEG, LEG, 0], [0, 0, 190 + LIFT]], 200, 162);
  const P = proj(C);
  const pp = (pts) => pts.map((q) => P(...q));
  const shape = (pts, parent, cls = "sil") => mk("path", { d: poly(hull(pp(pts))), class: cls }, parent);
  const g = mk("g", {}, svg);
  const legs = [Math.PI / 4 + 2.09, Math.PI / 4 - 2.09, Math.PI / 4];
  const leg = (a) => { const f = [Math.cos(a) * LEG, Math.sin(a) * LEG, 2.5]; shape(cyl([Math.cos(a) * 14, Math.sin(a) * 14, 8], f, 1.8, 1.8), g); shape(ball(f, 3), g); };
  leg(legs[0]); leg(legs[1]);
  // the bell, flaring onto the stand's peg
  const bellPts = [];
  for (let i = 0; i <= 6; i++) { const t = i / 6; bellPts.push(...ring3([0, 0, 8 + t * 20], [0, 0, 1], 6 + 10 * Math.pow(1 - t, 2.2), 24)); }
  const bell = shape(bellPts, g);
  leg(legs[2]);
  // the lower joint with its tenon ring and keys
  shape(up(26, 92, 5.5, 5.5), g);
  const keys = (z0, z1, parent) => {
    let rd = "";
    const off = [SQ * 5.6, SQ * 5.6];
    for (let z = z0; z <= z1; z += 11) {
      const c = ring3([off[0], off[1], z], [SQ, SQ, 0], 2.1, 12).map((q) => P(...q));
      rd += "M" + c.map((p) => p.join(",")).join("L") + "Z";
    }
    const a = P(off[0] - 3.2, off[1] + 3.2, z0 - 4), b = P(off[0] - 3.2, off[1] + 3.2, z1 + 4);
    rd += `M${a[0]},${a[1]}L${b[0]},${b[1]}`;
    mk("path", { d: rd, class: "nf lo" }, parent);
  };
  keys(36, 80, g);
  shape(up(90, 97, 6.6, 6.6), g);
  // the upper half: upper joint, barrel, mouthpiece and reed, which come off together
  const top = mk("g", {}, g);
  const upper = shape(up(97, 150, 5.5, 5.5), top);
  keys(106, 140, top);
  shape(up(148, 155, 6.6, 6.6), top);
  shape(up(155, 172, 6.8, 6.2), top);
  shape(up(172, 190, 5.2, 2.8), top);
  shape(cyl([SQ * 3.6, SQ * 3.6, 176], [SQ * 2.4, SQ * 2.4, 189], 1.4, 1.1), top);
  const lift = tween(0);
  let last = NaN;

  function draw(now) {
    const z = tval(lift, now) * LIFT * amp;
    if (z === last) return;
    last = z;
    const dy = P(0, 0, z)[1] - P(0, 0, 0)[1];
    top.setAttribute("transform", `translate(0 ${dy.toFixed(2)})`);
  }
  const B = register(stage, (_dt, now) => { draw(now); return !tdone(lift, now); });
  bag.add(B.unregister);

  let act = -2;
  function setActive(on) {
    const id = on ? 1 : -1;
    if (id === act) return;
    act = id;
    tset(lift, on ? 1 : 0, performance.now(), 0);
    bell.classList.toggle("hi", !on);
    upper.classList.toggle("hi", on);
    read.textContent = on ? "up " + Math.round(LIFT * amp) : "rest";
    B.wake();
  }
  setActive(false);
  const base = P(0, 0, 0), crown = P(0, 0, 190);
  bag.add(pointer(stage, {
    move: (p) => setActive(Math.abs(p[0] - base[0]) < 34 && p[1] < base[1] + 10 && p[1] > crown[1] - 10),
    leave: () => setActive(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 0.2, 1); last = NaN; if (act > 0) read.textContent = "up " + Math.round(LIFT * amp); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "clarinet",
  means: "A clarinet on a peg stand: the pointer draws its upper joint, barrel and mouthpiece up off the lower tenon, as when taking it apart.",
  rules: [1, 4, 5],
  range: [0.3, 0.75, 1],
  tour: [[200, 110], [200, 189], [200, 54], null],
  mount,
});

trumpet.code:
/**
 * Trumpet: one trumpet on its side, the lead pipe looping round to three
 * piston valves and back out to a flared bell. The pointer picks a valve by
 * where it stands: its piston draws up out of the casing, and its
 * neighbours rise a little, staggered. At rest the middle piston stands
 * half out, bright. The slider is how far a piston draws.
 *
 * The pattern: one of many in a single row (keys).
 */
const {
  Cam, circ, fit, facing, poly, prism, proj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const VX = [-12, 0, 12], ZC = 46, FAV = 1, S = 2.2;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function tube(P, line) {
  const pts = line.map(([x, z]) => P(x, 0, z)), L = [], R = [];
  pts.forEach((p, i) => {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
    const tx = b[0] - a[0], ty = b[1] - a[1], d = Math.hypot(tx, ty) || 1, w = line[i][2] * S;
    L.push([p[0] - (ty / d) * w, p[1] + (tx / d) * w]); R.push([p[0] + (ty / d) * w, p[1] - (tx / d) * w]);
  });
  return poly(L.concat(R.reverse()));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, S);
  fit(C, [[-74, 0, 26], [74, -16, 40], [74, 16, 40], [0, 0, 6], [0, 0, ZC + 58], [74, 0, 56], [74, 0, 24]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // lead pipe from the mouthpiece round the front bow, and the rear bow up to the bell pipe
  mk("path", { d: tube(P, [[-72, 27, 3.2], [-67, 27, 1.4], [36, 27, 1.9], [43, 25, 1.9], [46, 20, 1.9], [43, 15, 1.9], [36, 13, 1.9], [12, 13, 1.9]]) }, g);
  mk("path", { d: tube(P, [[-12, 13, 1.9], [-28, 13, 1.9], [-35, 17, 1.9], [-37, 26, 1.9], [-35, 35, 1.9], [-28, 40, 2], [12, 40, 2]]) }, g);

  const items = VX.map((x, k) => {
    const grp = mk("g", {}, g);
    put(solid(grp), prism(P, front, disc(x, 0, 4.6), disc(x, 0, 3.6), 6, ZC));
    put(solid(grp), prism(P, front, disc(x, 0, 5.4), disc(x, 0, 4.4), ZC, ZC + 2.2));
    const body = solid(grp), stem = solid(grp), btn = solid(grp);
    return { k, x, body, stem, btn, z: tween(k === FAV ? 12 : 0), last: NaN };
  });

  // the bell pipe and its flare, nearest the viewer
  const bell = [];
  for (let i = 0; i <= 14; i++) { const x = 14 + i * 4.2; bell.push([x, 40, 2 + 14 * Math.pow(i / 14, 2.6)]); }
  mk("path", { d: tube(P, bell) }, g);
  const rim = circ(16, 40).map((q) => P(73, q.u, 40 + q.v));
  mk("path", { d: poly(rim), class: "sil" }, g);
  mk("path", { d: poly(circ(13.5, 40).map((q) => P(73, q.u, 40 + q.v))), class: "nf lo" }, g);

  function draw(it, lift) {
    if (lift === it.last) return;
    it.last = lift;
    const z0 = ZC + 2.2, x = it.x;
    put(it.body, lift > 0.3 ? prism(P, front, disc(x, 0, 3.6), disc(x, 0, 2.8), z0, z0 + lift) : { sil: "", crease: "" });
    put(it.stem, prism(P, front, disc(x, 0, 1.3, 12), disc(x, 0, 0.8, 12), z0 + lift, z0 + lift + 5));
    put(it.btn, prism(P, front, disc(x, 0, 4.4), disc(x, 0, 3.4), z0 + lift + 5, z0 + lift + 7.5));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const it of items) { draw(it, tval(it.z, now)); if (!tdone(it.z, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  const mids = items.map((it) => P(it.x, 0, ZC));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    mids.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 14 && sy > mids[best][1] - 100 && sy < mids[best][1] + 80 ? best : -1;
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now(), from = a >= 0 ? a : act, top = 22 + 26 * amt;
    act = a;
    items.forEach((it, k) => {
      const d = Math.abs(k - a), z = a < 0 ? (k === FAV ? 12 : 0) : d === 0 ? top : d === 1 ? top * 0.6 : 0;
      tset(it.z, z, now, from < 0 ? 0 : Math.abs(k - from) * 45);
      it.btn.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "valve " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; if (act >= 0) setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "trumpet",
  means: "A trumpet on its side: the piston under the pointer draws up out of its valve casing, its neighbours rise a little after it.",
  rules: [1, 2, 3, 5],
  range: [0, 0.5, 1],
  tour: [[188, 152], [207, 162], [169, 142], null],
  mount,
});

trolleybus.code:
/**
 * Trolleybus: a long rounded body on two axles with a roof pod, two trolley
 * poles trailing back from a pivot on the pod, and two overhead wires above.
 * The nearer the pointer comes, the further the poles swing up off the roof
 * until their shoes meet the wires. At rest the poles lie low and bright.
 * The slider sets how far the poles rise.
 */
const {
  Cam, circ, clamp, fit, facing, lerp, open, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 22, PZ = 52, L = 92, A0 = 5, A1 = 30, REST = 0, WZ = PZ + L * Math.sin(rad(A1));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.75);
  const tx1 = PX - L * Math.cos(rad(A1));
  fit(C, [[-64, -16, 0], [64, 16, 0], [64, -16, 48], [-64, 16, 0], [tx1 - 20, -8, WZ], [50, 8, WZ]], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  mk("path", { class: "nf lo", d: [-7, 7].map((y) => seg(P(tx1 - 20, y, WZ), P(50, y, WZ))).join("") }, g);
  const wheel = (x, y) => { const pts = circ(9, 18).map((q) => P(x + q.u, y, 9 + q.v)); return mk("path", { class: "sil", d: poly(pts) + seg(P(x, y, 9), P(x + 3, y, 9)) }, g); };
  [-36, 38].forEach((x) => wheel(x, -14));
  const [br, bi] = rings(-62, -15, 62, 15, 7, 1.6);
  put(solid(g), prism(P, front, br, bi, 8, 48));
  mk("path", { class: "nf lo", d: open([P(-56, 15, 26), P(56, 15, 26)]) + open([P(-56, 15, 42), P(56, 15, 42)]) + open([P(62, -11, 26), P(62, -11, 42), P(62, 11, 42), P(62, 11, 26)]) + [-30, -6, 18, 40].map((x) => seg(P(x, 15, 26), P(x, 15, 42))).join("") }, g);
  const [pr, pi] = rings(-6, -10, 28, 10, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 48, PZ));
  [-36, 38].forEach((x) => wheel(x, 14));
  const poles = [-7, 7].map(() => mk("path", { class: "sil hi" }, g));
  const bar = (y, th) => {
    const dx = -Math.cos(th), dz = Math.sin(th), ox = -dz * 1.6, oz = dx * 1.6;
    const tx = PX + L * dx, tz = PZ + L * dz;
    return poly([P(PX + ox, y, PZ + oz), P(tx + ox, y, tz + oz), P(tx - ox, y, tz - oz), P(PX - ox, y, PZ - oz)]) +
      seg(P(tx - 5, y, tz + 3), P(tx + 5, y, tz + 3)) + seg(P(tx, y, tz), P(tx, y, tz + 3));
  };

  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const th = rad(lerp(A0, A1, p));
    poles[0].setAttribute("d", bar(-7, th));
    poles[1].setAttribute("d", bar(7, th));
  }

  const lift = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);
  const ax = P(-10, 0, 40);

  function aim(pt) {
    const d = Math.hypot(pt[0] - ax[0], (pt[1] - ax[1]) * 0.7);
    if (d > 160) return leave();
    lift.t = clamp(1.25 - d / 120, 0.15, 1) * (0.3 + 0.7 * reach / 100);
    read.textContent = Math.round(lerp(A0, A1, lift.t)) + "°";
    B.wake();
  }
  function leave() { lift.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "trolleybus",
  means: "A trolleybus: the nearer the pointer, the further its two trolley poles swing up off the roof to meet the overhead wires.",
  rules: [1, 3, 5, 8],
  range: [0, 70, 100],
  tour: [[167, 155], [205, 190], [126, 138], null],
  mount,
});

articulated.code:
/**
 * Articulated lorry: a short tractor unit with its cab and a long box
 * semi-trailer resting on the fifth wheel, hinged on the kingpin. The nearer
 * the pointer comes, the further the trailer swings round the kingpin, its
 * tail sweeping out toward the viewer as in a tight turn. At rest the trailer
 * sits almost straight, its outline bright. The slider sets the swing.
 */
const {
  Cam, circ, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const KX = 44, A0 = 6, A1 = 42, REST = 0;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.5);
  const sw = (x, y, a) => [KX + (x - KX) * Math.cos(a) - y * Math.sin(a), (x - KX) * Math.sin(a) + y * Math.cos(a)];
  const ext = [[-90, 15], [-90, -15], [56, 15], [56, -15]].flatMap(([x, y]) => [A0, A1].map((d) => [...sw(x, y, -rad(d)), 62]));
  fit(C, ext.concat([[92, -14, 0], [92, 14, 0], [-90, 15, 0], [92, 14, 54]]), 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheelD = (pt) => poly(circ(8, 18).map((q) => P(...pt(q.u, q.v)))) + seg(P(...pt(0, 0)), P(...pt(2.5, 0)));
  const fixedWheel = (x, y) => mk("path", { class: "sil", d: wheelD((u, v) => [x + u, y, 8 + v]) }, g);
  const farTW = [-70, -52].map(() => mk("path", { class: "sil" }, g));
  [42, 82].forEach((x) => fixedWheel(x, -12));
  const [cr, ci] = rings(34, -12, 92, 12, 2, 1);
  put(solid(g), prism(P, front, cr, ci, 9, 15));
  mk("path", { class: "dot", d: poly(circ(4, 12).map((q) => P(KX + q.u, q.v, 15))) }, g);
  const trailer = solid(g);
  trailer.sil.classList.add("hi");
  const legs = mk("path", { class: "nf lo" }, g);
  const nearTW = [-70, -52].map(() => mk("path", { class: "sil" }, g));
  const [kr, ki] = rings(66, -13, 92, 13, 5, 1.4);
  put(solid(g), prism(P, front, kr, ki, 15, 54));
  mk("path", { class: "nf lo", d: open([P(92, -10, 34), P(92, -10, 48), P(92, 10, 48), P(92, 10, 34)]) + seg(P(78, 13, 24), P(78, 13, 48)) }, g);
  [42, 82].forEach((x) => fixedWheel(x, 12));
  const [tr, ti] = rings(-90, -15, 56, 15, 3, 1.6);
  const turn = (ring, a) => ring.map((q) => {
    const [u, v] = sw(q.u, q.v, a);
    return { ...q, u, v, nu: q.nu * Math.cos(a) - q.nv * Math.sin(a), nv: q.nu * Math.sin(a) + q.nv * Math.cos(a) };
  });

  let last = NaN;
  function draw(p) {
    if (p === last) return;
    last = p;
    const a = -rad(lerp(A0, A1, p));
    put(trailer, prism(P, front, turn(tr, a), turn(ti, a), 17, 62));
    const tw = (x, y) => wheelD((u, v) => { const [wx, wy] = sw(x + u, y, a); return [wx, wy, 8 + v]; });
    [-70, -52].forEach((x, i) => { farTW[i].setAttribute("d", tw(x, -13)); nearTW[i].setAttribute("d", tw(x, 13)); });
    legs.setAttribute("d", [-12, 12].map((y) => { const [lx, ly] = sw(24, y, a); return seg(P(lx, ly, 17), P(lx, ly, 3)); }).join(""));
  }

  const swing = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(swing, dt); draw(swing.x); return m; });
  bag.add(B.unregister);
  const ax = P(-20, 0, 40);

  function aim(pt) {
    const d = Math.hypot(pt[0] - ax[0], (pt[1] - ax[1]) * 0.7);
    if (d > 160) return leave();
    swing.t = clamp(1.25 - d / 120, 0.15, 1) * (0.3 + 0.7 * reach / 100);
    read.textContent = Math.round(lerp(A0, A1, swing.t)) + "°";
    B.wake();
  }
  function leave() { swing.t = REST; read.textContent = "rest"; B.wake(); }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "articulated",
  means: "An articulated lorry: the nearer the pointer, the further its trailer swings round the kingpin, the tail sweeping out.",
  rules: [1, 3, 5, 8],
  range: [0, 70, 100],
  tour: [[200, 113], [250, 165], [128, 77], null],
  mount,
});

monstertruck.code:
/**
 * Monster truck: a pickup body riding high on four giant tyres, joined to the
 * axles by long suspension struts. The pointer's place across the frame lifts
 * the whole body up on its struts, high over the wheels, as on a bounce. At
 * rest the body sits a little up, its cab bright. The slider is how high the
 * suspension lifts.
 *
 * The pattern: one part sliding on a fixed track (lift).
 */
const { Cam, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, rrect, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 132, W = 84, R = 26, TW = 18, X1 = 28, X2 = 106, ZF = 46, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[X1 - R, 0, 0], [X2 + R, W, 0], [X2 + R, 0, 0], [X1 - R, W, 0], [0, 6, ZF + 50 + 18], [96, 12, ZF + 50 + 42], [L, W - 6, ZF + 50]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const ring = (x, y, r) => {
    const pts = [];
    for (let i = 0; i < 32; i++) { const t = (i / 32) * Math.PI * 2; pts.push(P(x + r * Math.cos(t), y, R + r * Math.sin(t))); }
    return pts;
  };
  const tyre = (x, y0, y1) => {
    mk("path", { d: poly(hull(ring(x, y0, R).concat(ring(x, y1, R)))) }, g);
    mk("path", { d: poly(ring(x, y1, R - 7)) + poly(ring(x, y1, 6)), class: "nf lo" }, g);
  };
  for (const x of [X1, X2]) tyre(x, 0, TW);
  const struts = mk("path", { class: "nf" }, g);
  const body = mk("g", {}, g);
  const low = solid(body), cab = solid(body), lines = mk("path", { class: "nf lo" }, body);
  cab.sil.classList.add("hi");
  for (const x of [X1, X2]) tyre(x, W - TW, W);
  const [br, bi] = rings(0, 8, L, W - 8, 6, 1.6);
  const foot = rrect(54, 10, 100, W - 10, 5, 6), top = rrect(62, 16, 94, W - 16, 4, 6);
  const lift = spring(REST);
  let last = NaN;

  function draw(h) {
    if (h === last) return;
    last = h;
    const z = ZF + h;
    let s = "";
    for (const x of [X1, X2]) {
      s += seg(P(x, TW, R), P(x, W - TW, R));
      for (const y of [TW + 6, W - TW - 6]) s += seg(P(x - 6, y, R), P(x - 2, y, z)) + seg(P(x + 6, y, R), P(x + 2, y, z));
    }
    struts.setAttribute("d", s);
    put(low, prism(P, front, br, bi, z, z + 18));
    cab.sil.setAttribute("d", poly(hull(ringAt(P, foot, z + 16).concat(ringAt(P, top, z + 42)))));
    cab.cr.setAttribute("d", "");
    lines.setAttribute("d", seg(P(4, W - 8, z + 18), P(52, W - 8, z + 18)) + seg(P(58, W - 10, z + 21), P(70, W - 16, z + 38)) + seg(P(98, W - 10, z + 21), P(92, W - 16, z + 38)) + seg(P(78, W - 10, z + 20), P(78, W - 16, z + 40)));
  }
  const B = register(stage, (dt) => { const m = stepS(lift, dt); draw(lift.x); return m; });
  bag.add(B.unregister);
  function aim(h, r) { lift.t = h; read.textContent = r ? "rest" : "+" + Math.round(h); B.wake(); }
  draw(REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(REST + clamp((sx - 60) / 240, 0, 1) * (max - REST)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "monstertruck",
  means: "A monster truck on four giant tyres: the pointer lifts the whole body high on its long suspension struts, as on a bounce.",
  rules: [1, 3, 5, 6],
  range: [24, 38, 50],
  tour: [[167, 89], [216, 98], [263, 66], null],
  mount,
});

dunebuggy.code:
/**
 * Dune buggy: a low open tub on four fat tyres under a tubular roll cage, the
 * engine bare at the back. The pointer's place across the frame steers the
 * front wheels, swinging them hard left or right on their kingpins. At rest
 * they point a few degrees off straight, bright. The slider is how far they
 * can steer.
 *
 * The pattern: one pair of parts turning about a vertical axis (turn).
 */
const { Cam, clamp, fit, facing, hull, lerp, open, poly, prism, proj, rad, rings, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 124, W = 76, XR = 26, RR = 20, XF = 104, RF = 20, TF = 16, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.85);
  fit(C, [[0, 0, 0], [L + 6, W + 4, 0], [L + 6, -4, 0], [0, W, 0], [40, 16, 66], [78, W - 16, 66], [XR, 0, 2 * RR], [XR, W, 2 * RR]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const rearRing = (y, r) => {
    const pts = [];
    for (let i = 0; i < 32; i++) { const t = (i / 32) * Math.PI * 2; pts.push(P(XR + r * Math.cos(t), y, RR + r * Math.sin(t))); }
    return pts;
  };
  const rear = (y0, y1, yo) => {
    mk("path", { d: poly(hull(rearRing(y0, RR).concat(rearRing(y1, RR)))) }, g);
    mk("path", { d: poly(rearRing(yo, RR - 7)), class: "nf lo" }, g);
  };
  // a point on a front wheel at (XF, yc) steered by a: d along the rolling direction, n across, z up
  const fp = (yc, a, d, n, z) => P(XF + d * Math.cos(rad(a)) - n * Math.sin(rad(a)), yc + d * Math.sin(rad(a)) + n * Math.cos(rad(a)), z);
  const fRing = (yc, a, n, r) => {
    const pts = [];
    for (let i = 0; i < 32; i++) { const t = (i / 32) * Math.PI * 2; pts.push(fp(yc, a, r * Math.cos(t), n, RF + r * Math.sin(t))); }
    return pts;
  };
  const frontWheel = (yc, side) => ({ yc, side, tyre: mk("path", { class: "sil hi" }, g), hub: mk("path", { class: "nf lo" }, g) });
  rear(0, 18, 0);
  const far = frontWheel(8, -1);
  const [br, bi] = rings(4, 16, L, W - 16, 8, 1.6);
  put(solid(g), prism(P, front, br, bi, 14, 28));
  put(solid(g), prism(P, front, ...rings(6, 22, 30, W - 22, 4, 1.2), 28, 40));
  mk("path", { d: seg(P(46, 24, 28), P(58, 24, 40)) + seg(P(46, W - 24, 28), P(58, W - 24, 40)) + seg(P(84, W / 2, 28), P(80, W / 2 + 6, 40)), class: "nf lo" }, g);
  let cage = "";
  for (const x of [40, 78]) cage += open([P(x, 18, 28), P(x, 18, 66), P(x, W - 18, 66), P(x, W - 18, 28)]);
  for (const y of [18, W - 18]) cage += seg(P(40, y, 66), P(78, y, 66)) + seg(P(78, y, 66), P(106, y, 28)) + seg(P(40, y, 66), P(20, y, 40));
  mk("path", { d: cage, class: "nf" }, g);
  rear(W - 18, W, W);
  const near = frontWheel(W - 8, 1);
  const steer = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    for (const w of [far, near]) {
      w.tyre.setAttribute("d", poly(hull(fRing(w.yc, a, -TF / 2, RF).concat(fRing(w.yc, a, TF / 2, RF)))));
      w.hub.setAttribute("d", poly(fRing(w.yc, a, w.side * TF / 2, RF - 8)));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(steer, dt); draw(steer.x); return m; });
  bag.add(B.unregister);
  function aim(a, r) { steer.t = a; read.textContent = r ? "rest" : (a < 0 ? "L" : "R") + Math.abs(Math.round(a)) + "°"; B.wake(); }
  draw(REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(lerp(-max, max * 0.5, clamp((sx - 90) / 220, 0, 1))), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

