  { ring: disc(0, 0, 26, 2), z0: 0, z1: 6, xf: ID },
  { ring: disc(0, 0, 6, 1.2), z0: 6, z1: 60, xf: ID },
  { ring: box(-4, -17, 4, 17, 2, 1), z0: 58, z1: 63, xf: ID },
  { ring: box(-3, -17, 3, -12, 1.5, 0.8), z0: 63, z1: HP + 4, xf: ID },
