  { ring: disc(0, 0, 7.5, 1.4), z0: -10, z1: 10, xf: bar },
  ...ball(1, true),
  { ring: box(-3, 12, 3, 17, 1.5, 0.8), z0: 63, z1: HP + 4, xf: ID },
] };

