        e.cr.setAttribute("d", poly(inner.map(Q(up ? p.z1 : p.z0))));
      }
    }
    // the hit is the rest pose's outline, grown a little: it never moves with the part
    const H = hull(pts(S.a0).map((q) => P(...q))), cx = H.reduce((s, q) => s + q[0], 0) / H.length, cy = H.reduce((s, q) => s + q[1], 0) / H.length;
    const HG = H.map((q) => [cx + (q[0] - cx) * 1.12, cy + (q[1] - cy) * 1.12]);
    const side = (p, sg) => HG.every((q, i) => { const r = HG[(i + 1) % HG.length]; return sg * ((r[0] - q[0]) * (p[1] - q[1]) - (r[1] - q[1]) * (p[0] - q[0])) >= 0; });
    const inside = (p) => side(p, 1) || side(p, -1);
    for (const e of els) if (e.p.hi) e.sil.classList.add("hi");
    const tw = tween(0);
    let drawn = NaN, on = false;
    const B = register(stage, (_dt, now) => {
      const a = S.a0 + (S.a1 - S.a0) * tval(tw, now) * amp;
      if (a !== drawn) { drawn = a; draw(a); }
      return !tdone(tw, now);
    });
    bag.add(B.unregister);
    const set = (v) => {
      if (v === on) return;
      on = v;
      tset(tw, v ? 1 : 0, performance.now(), 0);
      read.textContent = v ? S.word : "rest";
      B.wake();
    };
    bag.add(pointer(stage, {
      move: (p) => set(inside(p)),
      leave: () => set(false),
    }));
    bag.add(() => svg.replaceChildren());
    read.textContent = "rest";
    return { set: (v) => { amp = v; drawn = NaN; B.wake(); }, destroy: bag.dispose };
  };
}
// beam engine: a rocking beam on a column, the piston rod in a cylinder at one end, a connecting rod to a flywheel's crank at the other
const HB = 68, FX = 42, FZ = 34, FR = 24, CR = 12, BL = 40;
const crank = (a) => [FX + CR * Math.sin(a * R), FZ + CR * Math.cos(a * R)];
const tilt = (a) => Math.asin(clampB((crank(a)[1] + 34 - HB) / BL));
function clampB(v) { return Math.max(-1, Math.min(1, v)); }
const endR = (a) => { const b = tilt(a); return [BL * Math.cos(b), HB + BL * Math.sin(b)]; };
const endL = (a) => { const b = tilt(a); return [-BL * Math.cos(b), HB - BL * Math.sin(b)]; };
const XZ = () => (u, v, w) => [u, w, v];
// a rod from A to B in the x-z plane; v runs 0..L0 along it
const rod = (A, B, L0) => (a) => { const p = A(a), q = B(a), dx = q[0] - p[0], dz = q[1] - p[1], L = Math.hypot(dx, dz), k = L / L0;
  return (u, v, w) => [p[0] + (dx / L) * v * k - (dz / L) * u, w, p[1] + (dz / L) * v * k + (dx / L) * u]; };
const spin = (a) => (u, v, w) => [FX + u * Math.cos(a * R) + v * Math.sin(a * R), w, FZ - u * Math.sin(a * R) + v * Math.cos(a * R)];
const beam = (a) => { const b = tilt(a); return (u, v, w) => [u * Math.cos(b) - v * Math.sin(b), w, HB + u * Math.sin(b) + v * Math.cos(b)]; };
const rim = Array.from({ length: 14 }, (_, k) => { const t = (k / 14) * 360;
  return { ring: box(-5.6, FR - 3, 5.6, FR, 1.2, 0), z0: -2.5, z1: 2.5, xf: (a) => { const f = spin(a + t); return f; } }; });
const spokes = Array.from({ length: 6 }, (_, k) => ({ ring: box(-1.3, 3, 1.3, FR - 2.5, 0.6, 0), z0: -1.5, z1: 1.5, xf: (a) => spin(a + k * 60) }));
const SPEC = { S: 1.95, a0: 30, a1: 240, word: "rock", parts: [
  { ring: box(-58, -16, 72, 16, 5, 1.5), z0: 0, z1: 8, xf: ID },
  { ring: disc(-40, 0, 11, 1.4), z0: 8, z1: 44, xf: ID },
  { ring: box(-1.4, 0, 1.4, 30, 0.6, 0), z0: -1.4, z1: 1.4, xf: rod((a) => [endL(a)[0], 40], endL, 30) },
  { ring: box(-5, -7, 5, 7, 2, 1), z0: 8, z1: HB - 4, xf: ID },
  ...spokes,
  { ring: disc(0, 0, 4.5, 1), z0: -4, z1: 4, xf: spin },
  ...rim,
  { ring: box(-2.6, -3, 2.6, CR + 3, 1.6, 0.8), z0: 4, z1: 6.5, xf: spin },
  { ring: box(-1.8, 0, 1.8, 34, 0.8, 0), z0: 6.5, z1: 9, xf: rod((a) => crank(a), endR, 34) },
  { ring: box(-47, -4.5, 47, 4.5, 3, 1.2), z0: -3.5, z1: 3.5, xf: beam, hi: true },
  { ring: disc(0, 0, 3, 0.8), z0: 3.5, z1: 6, xf: () => (u, v, w) => [u, w, HB + v] },
] };

hairline({
  name: "beamengine",
  means: "A beam engine: the great beam rocks on its column as the flywheel turns, crank and rods driving it, when the pointer comes near.",
  rules: [1, 3, 4, 5, 8],
  range: [0.5, 1, 1.2],
  tour: [[190, 109], [290, 139], [110, 184], null],
  mount: figure(SPEC),
});

stirling.code:
/**
 * Stirling engine: a hot cylinder on a base plate, a small power cylinder on
 * top of it, and a spoked flywheel on a post, joined by a crank and a rod.
 * The pointer warms the engine: the flywheel turns through a broad arc, the
 * rod swings and the piston rises and falls with it. At rest the flywheel
 * waits, bright. The slider is how far the flywheel turns.
 *
 * The pattern: one part answering a discrete choice (a tween on an angle).
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const FX = 30, FY = 0, FZ = 44, R = 28, T = 4, CR = 14, ANG = 150, REST = 200;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-46, -22, 0], [48, 22, 0], [48, -22, 0], [-46, 22, 0], [FX, FY, FZ + R], [FX, FY - R, FZ], [FX + T, FY + R, FZ]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-46, -22, 48, 22, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  // the hot cylinder and the power cylinder on it
  put(solid(g), prism(P, front, disc(-22, 0, 15), disc(-22, 0, 13), 5, 24));
  put(solid(g), prism(P, front, disc(-22, 0, 6), disc(-22, 0, 4.6), 24, 34));
  const piston = solid(g);
  // the post holding the flywheel's axle
  const [pr, pi] = rings(FX - 6, FY - 3, FX - 1, FY + 3, 1.2, 0.6);
  put(solid(g), prism(P, front, pr, pi, 5, FZ + 2));
  const wp = (r, a, x) => P(x, FY + r * Math.cos(a), FZ + r * Math.sin(a));
  const ring = (r, y, n = 56) => Array.from({ length: n }, (_, i) => wp(r, (i / n) * Math.PI * 2, y));
  const wheel = mk("path", { class: "sil hi" }, g);
  const face = mk("path", { class: "lo" }, g);
  const spokes = mk("path", { class: "sil" }, g);
  const hub = mk("path", { class: "" }, g);
  const rod = mk("path", { class: "nf sil" }, g);
  const pin = mk("path", { class: "" }, g);
  wheel.setAttribute("d", poly(hull(ring(R, FX).concat(ring(R, FX + T)))));
  face.setAttribute("d", poly(ring(R - 4, FX + T)));

  const tw = tween(0);
  let last = "";
  function draw(s) {
    const a0 = (REST + s * amp * ANG) * Math.PI / 180;
    const key = a0.toFixed(4);
    if (key === last) return;
    last = key;
    let sp = "";
    for (let i = 0; i < 3; i++) {
      const a = a0 + (i / 3) * Math.PI * 2, w = 0.2, v = 0.07;
      sp += poly([wp(4, a - w, FX + T), wp(R - 3, a - v, FX + T), wp(R - 3, a + v, FX + T), wp(4, a + w, FX + T)]);
    }
    spokes.setAttribute("d", sp);
    hub.setAttribute("d", poly(hull(ring(4, FX + T, 16).concat(ring(4, FX + T + 3, 16)))));
    const cp = [FX + T + 3, FY + CR * Math.cos(a0), FZ + CR * Math.sin(a0)];
    const zp = 36 + 5 * Math.sin(a0);
    put(piston, prism(P, front, disc(-22, 0, 4.4), disc(-22, 0, 3.2), 32, zp));
    rod.setAttribute("d", seg(P(-22, 0, zp), P(cp[0], cp[1], cp[2])));
    pin.setAttribute("d", poly(hull(circ(2.4, 14).map((q) => P(cp[0], cp[1] + q.u, cp[2] + q.v)).concat(circ(2.4, 14).map((q) => P(cp[0] + 2, cp[1] + q.u, cp[2] + q.v))))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(FX, FY, FZ - 8);
  let on = null;
  function choose(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? `turn ${Math.round(amp * ANG)}°` : "rest";
    B.wake();
  }
  choose(false);
  bag.add(pointer(stage, { move: (p) => choose(Math.hypot(p[0] - mid[0], p[1] - mid[1]) < R * 3.4), leave: () => choose(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { amp = v; last = ""; if (on) read.textContent = `turn ${Math.round(amp * ANG)}°`; B.wake(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "stirling",
  means: "A Stirling engine on its plate: the pointer warms it and the flywheel turns, swinging the rod as the piston rises and falls.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.5],
  tour: [[258, 129], [236, 92], [270, 172], null],
  mount,
});

sawmill.code:
/**
 * Sawmill: a long bed with a toothed round blade standing in it, and a
 * carriage carrying a log on rails. The pointer feeds the log: the carriage
 * runs along the bed past the blade. At rest the carriage waits at the far
 * end, its log bright. The slider is how far the carriage runs.
 *
 * The pattern: one part answering a discrete choice (a tween on a slide).
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const BX = 66, BR = 24, BZ = 12, BY = 7, LR = 9, LL = 46, X0 = -56, RUN = 52;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-BX, -16, 0], [BX, 16, 0], [BX, -16, 0], [-BX, 16, 0], [8, BY, BZ + BR], [X0, -4, 30], [X0 + LL + RUN * 1.5, -4, 30]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-BX, -16, BX, 16, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, 6));
  const [rl, rli] = rings(-BX + 4, -12, BX - 4, -9, 1, 0.5), [rn, rni] = rings(-BX + 4, 1, BX - 4, 4, 1, 0.5);
  put(solid(g), prism(P, front, rl, rli, 6, 8));
  put(solid(g), prism(P, front, rn, rni, 6, 8));
  const car = mk("g", {}, g);
  const deck = solid(car), log = mk("path", { class: "sil hi" }, car), end = mk("path", { class: "nf lo" }, car), rings2 = mk("path", { class: "nf lo" }, car);
  // the blade: a toothed disc standing on the near side of the log's path
  const teeth = [];
  for (let i = 0; i < 48; i++) {
    const a = (i / 48) * Math.PI * 2, r = i % 2 ? BR : BR - 2.6;
    teeth.push(P(8 + r * Math.cos(a), BY, BZ + r * Math.sin(a)));
  }
  const [gr, gi] = rings(-4, BY - 3, 20, BY + 3, 2, 1);
  put(solid(g), prism(P, front, gr, gi, 6, 10));
  mk("path", { class: "sil", d: poly(teeth) }, g);
  mk("path", { class: "nf lo", d: poly(circ(BR - 7, 36).map((q) => P(8 + q.u, BY, BZ + q.v))) }, g);
  mk("path", { class: "", d: poly(circ(3, 16).map((q) => P(8 + q.u, BY, BZ + q.v))) }, g);

  const tw = tween(0);
  let last = NaN;
  function draw(s) {
    const x = X0 + s * amp * RUN;
    if (x === last) return;
    last = x;
    const [dr, di] = rings(x, -14, x + LL, 6, 2, 1.2);
    put(deck, prism(P, front, dr, di, 8, 12));
    const at = (xx, r) => circ(r, 28).map((q) => P(xx, -4 + q.u, 12 + LR + q.v));
    log.setAttribute("d", poly(hull(at(x + 3, LR).concat(at(x + LL - 3, LR)))));
    end.setAttribute("d", poly(at(x + LL - 3, LR)));
    rings2.setAttribute("d", poly(at(x + LL - 3, LR * 0.55)) + poly(at(x + LL - 3, LR * 0.15)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  const mid = P(0, 0, 14);
  let on = null;
  function choose(v) {
    if (v === on) return;
    on = v;
    tset(tw, v ? 1 : 0, performance.now(), 0);
    read.textContent = v ? `feed ${Math.round(amp * RUN)}` : "rest";
    B.wake();
  }
  choose(false);
  bag.add(pointer(stage, { move: (p) => choose(Math.hypot(p[0] - mid[0], (p[1] - mid[1]) * 1.6) < 150), leave: () => choose(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { amp = v; last = NaN; if (on) read.textContent = `feed ${Math.round(amp * RUN)}`; B.wake(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "sawmill",
  means: "A sawmill bed with a round blade: the pointer feeds the log, and its carriage runs along the rails past the blade.",
  rules: [1, 4, 5, 8],
  range: [0.5, 1, 1.5],
  tour: [[158, 107], [200, 140], [236, 176], null],
  mount,
});

printingpress.code:
/**
 * Printing press: a screw press of two tall cheeks and a head, the bed rails
 * running out to the front. The pointer works it: over the press the bed runs
 * in under the platen, the bar swings round and the platen screws down; off
 * it the bed runs back out. The bar is bright. The slider is how far it works.
 */
const {
  Cam, circ, fit, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const TOP = 84, REST = 0.08;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.05);
  let depth = value;
  fit(C, [[-30, -24, 0], [76, 16, 0], [-28, -28, TOP + 10], [28, 28, TOP + 10], [0, 0, TOP + 12], [76, 16, 14]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-26, -16, 76, 16, 2, 1.4), 0, 8));
  put(solid(g), prism(P, front, ...rings(-4, -24, 4, -16, 1.5, 0.8), 0, TOP));
  const bed = solid(g), tym = solid(g), plat = solid(g), screw = solid(g);
  put(solid(g), prism(P, front, ...rings(-4, 16, 4, 24, 1.5, 0.8), 0, TOP));
  put(solid(g), prism(P, front, ...rings(-7, -27, 7, 27, 2, 1.2), TOP, TOP + 9));
  const hub = solid(g);
  const bar = mk("path", { class: "nf sil hi", d: "" }, g);
  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const t = sp.x, bx = 50 * (1 - t), zp = 15 + (1 - t) * 34, a = 0.5 + t * 2.1;
    put(bed, prism(P, front, ...rings(bx - 18, -14, bx + 18, 14, 1.5, 1), 8, 13));
    put(tym, prism(P, front, ...rings(bx - 14, -11, bx + 14, 11, 1, 0.8), 13, 15));
    put(plat, prism(P, front, ...rings(-13, -13, 13, 13, 1.5, 1), zp, zp + 6));
    put(screw, prism(P, front, circ(3, 16), null, zp + 6, TOP));
    put(hub, prism(P, front, circ(5, 20), null, zp + 16, zp + 21));
    bar.setAttribute("d", seg(P(0, 0, zp + 18), P(Math.cos(a) * 34, Math.sin(a) * 34, zp + 18)));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  let over = false;
  function retarget() {
    sp.t = over ? depth : REST;
    read.textContent = over ? "pull " + Math.round(depth * 100) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let hit = false;
      for (let z = 0; z <= TOP + 10; z += 6) { const [x, y] = unproj(C, p[0], p[1], z); if (x > -30 && x < 78 && Math.abs(y) < 28) hit = true; }
      over = hit; retarget();
    },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { depth = Math.max(0.3, Math.min(1, v)); retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "printingpress",
  means: "A printing press: over it the bed runs in under the platen, the bar swings and the platen screws down; off it the bed runs out.",
  rules: [1, 3, 5],
  range: [0.3, 1, 1],
  tour: [[161, 130], [235, 265], [165, 50], null],
  mount,
});

mangle.code:
/**
 * Mangle: two cast side frames on a base, a pair of long rollers between
 * them and a crank on the near frame. The pointer works it: over the mangle
 * the top roller lifts open and the crank swings round; off it the rollers
 * close again. The crank handle is bright. The slider is how far it works.
 */
const {
  Cam, fit, hull, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const R = 11, BZ = 30, TOP = 112, REST = 0.1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  let depth = value;
  fit(C, [[-36, -30, 0], [48, 30, 0], [-30, -16, TOP + 6], [30, 16, TOP + 6], [54, 0, BZ + 40], [54, 0, BZ - 36], [54, 40, BZ], [36, -40, BZ]], 200, 166);
  const P = proj(C), front = facing(C);
  function hcyl(x0, x1, z) {
    const pts = [], near = [];
    for (let k = 0; k < 28; k++) {
      const a = (k / 28) * Math.PI * 2, y = Math.cos(a) * R, zz = z + Math.sin(a) * R;
      pts.push(P(x0, y, zz)); const q = P(x1, y, zz); pts.push(q); near.push(q);
    }
    return { sil: poly(hull(pts)), crease: poly(near) };
  }
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-36, -18, 36, 18, 2, 1.4), 0, 5));
  const side = (x0) => { for (const y0 of [-15, 10]) put(solid(g), prism(P, front, ...rings(x0, y0, x0 + 5, y0 + 5, 1.5, 0.8), 5, TOP)); put(solid(g), prism(P, front, ...rings(x0 - 1, -16, x0 + 6, 16, 2, 1), TOP - 6, TOP)); };
  side(-32);
  const low = solid(g), top = solid(g);
  put(low, hcyl(-27, 27, BZ));
  side(27);
  const hub = mk("path", { class: "nf sil", d: "" }, g);
  const arm = mk("path", { class: "nf sil hi", d: "" }, g);
  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const t = sp.x, zt = BZ + 2 * R + 1 + t * 40, a = -0.5 + t * 4.2;
    put(top, hcyl(-27, 27, zt));
    const ey = Math.cos(a) * 40, ez = BZ + Math.sin(a) * 40;
    hub.setAttribute("d", seg(P(32, 0, BZ), P(36, 0, BZ)));
    arm.setAttribute("d", open([P(36, 0, BZ), P(36, ey, ez), P(54, ey, ez)]));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  let over = false;
  function retarget() {
    sp.t = over ? depth : REST;
    read.textContent = over ? "turn " + Math.round(depth * 100) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let hit = false;
      for (let z = 0; z <= TOP + 6; z += 6) { const [x, y] = unproj(C, p[0], p[1], z); if (Math.abs(x) < 46 && Math.abs(y) < 30) hit = true; }
      over = hit; retarget();
    },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { depth = Math.max(0.3, Math.min(1, v)); retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "mangle",
  means: "A mangle: over it the top roller lifts open and the crank swings round; off it the rollers close again.",
  rules: [1, 3, 5],
  range: [0.3, 1, 1],
  tour: [[156, 160], [185, 250], [140, 45], null],
  mount,
});

jetengine.code:
/**
 * Jet engine: a turbofan on a ground cradle, the fan facing the viewer in its
 * intake and the reverser sleeve at the back of the nacelle. The pointer works
 * it: over the engine the fan spins round and the sleeve slides back, opening
 * the reverser on the core; off it the sleeve closes. The fan is bright.
 */
const {
  Cam, fit, hull, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, facing,
} = HL;

const Z = 36, REST = 0.08;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.95);
  let depth = value;
  fit(C, [[-92, -24, 0], [44, 24, 0], [-92, -24, Z + 24], [44, 24, Z + 24]], 200, 166);
  const P = proj(C), front = facing(C);
  function hcyl(x0, x1, r) {
    const pts = [], near = [];
    for (let k = 0; k < 32; k++) {
      const a = (k / 32) * Math.PI * 2, y = Math.cos(a) * r, z = Z + Math.sin(a) * r;
      pts.push(P(x0, y, z)); const q = P(x1, y, z); pts.push(q); near.push(q);
    }
    return { sil: poly(hull(pts)), crease: poly(near) };
  }
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-70, -16, 36, 16, 2, 1.4), 0, 4));
  for (const x of [-50, 14]) put(solid(g), prism(P, front, ...rings(x, -8, x + 10, 8, 1.5, 1), 4, Z - 18));
  put(solid(g), hcyl(-84, -10, 12));
  const sleeve = solid(g);
  put(solid(g), hcyl(-4, 40, 23));
  const disc = mk("path", { class: "lo", d: poly(Array.from({ length: 32 }, (_, k) => { const a = k / 32 * Math.PI * 2; return P(40, Math.cos(a) * 19, Z + Math.sin(a) * 19); })) }, g);
  const fan = mk("path", { class: "nf sil hi", d: "" }, g);
  const sp = spring(REST);
  let drawn = NaN;
  function draw() {
    if (Math.abs(sp.x - drawn) < 1e-4) return;
    drawn = sp.x;
    const t = sp.x, x1 = -5 - t * 34;
    put(sleeve, hcyl(x1 - 34, x1, 22));
    let d = "";
    for (let i = 0; i < 9; i++) {
      const a = t * 3 + (i / 9) * Math.PI * 2, b = a + 0.25;
      d += seg(P(40, Math.cos(a) * 4, Z + Math.sin(a) * 4), P(40, Math.cos(b) * 18, Z + Math.sin(b) * 18));
    }
    fan.setAttribute("d", d);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  let over = false;
  function retarget() {
    sp.t = over ? depth : REST;
    read.textContent = over ? "rev " + Math.round(depth * 100) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      let hit = false;
      for (let z = 0; z <= Z + 24; z += 6) { const [x, y] = unproj(C, p[0], p[1], z); if (x > -94 && x < 44 && Math.abs(y) < 26) hit = true; }
      over = hit; retarget();
    },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return { set: (v) => { depth = Math.max(0.3, Math.min(1, v)); retarget(); }, destroy: bag.dispose };
}

