ridemower.code:
/**
 * Ride-on mower: a low tractor body with a hood, seat, steering wheel and a
 * wide cutting deck slung between the wheels, and a grass catcher hung at
 * the back. Over the mower the catcher swings up on its top hinge to tip
 * out on the 700ms ease; leaving lowers it shut, the catcher bright. The
 * slider is how far it tips.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, lerp, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const HX = -28, HZ = 38;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tip = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-60, -15, 0], [34, 15, 0], [34, -15, 0], [-60, 15, 0], [-62, 15, 66], [-28, -15, 70]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 2, b = 1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, o, i, z0, z1)); return s; };
  const catcher = mk("path", { class: "sil hi" }, g), slats = mk("path", { class: "nf lo" }, g);
  const wheel = (cx, y, dy, r) => {
    const ring = (yy, rr) => Array.from({ length: 22 }, (_, i) => { const t = (i / 22) * Math.PI * 2; return P(cx + rr * Math.cos(t), yy, r + rr * Math.sin(t)); });
    mk("path", { d: poly(hull(ring(y, r).concat(ring(y + dy, r)))), class: "sil" }, g);
    mk("path", { d: poly(ring(y + (dy > 0 ? dy : 0), r * 0.4)), class: "nf lo" }, g);
  };
  wheel(-18, -16, 4, 9); wheel(22, -14, 3, 5);
  for (const y of [-11, 8]) box(g, -30, y, -27, y + 3, 8, 40, 0.8, 0.4);
  box(g, -31, -12, -26, 12, 38, 41, 1.2, 0.5);
  box(g, -10, -17, 16, 17, 3, 7, 8, 2);
  box(g, -26, -11, 30, 11, 8, 14, 4, 1.4);
  box(g, 8, -10, 30, 10, 14, 25, 5, 1.6);
  box(g, -17, -8, -4, 8, 14, 19, 3, 1.2);
  box(g, -19, -8, -15, 8, 19, 32, 2, 0.8);
  box(g, 2, -1, 4, 1, 14, 30, 0.8, 0.4);
  mk("path", { d: poly(Array.from({ length: 20 }, (_, i) => { const t = (i / 20) * Math.PI * 2; return P(3 + 6 * Math.cos(t), 6 * Math.sin(t), 31); })), class: "nf" }, g);
  wheel(-18, 12, 4, 9); wheel(22, 11, 3, 5);
  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const f = rad(-lerp(0, tip, t)), c = Math.cos(f), s = Math.sin(f);
    const T = (x, y, z) => { const dx = x - HX, dz = z - HZ; return P(HX + dx * c - dz * s, y, HZ + dx * s + dz * c); };
    const pts = [];
    for (const z of [6, 38]) for (const q of rrect(-56, -15, -28, 15, 4, 3)) pts.push(T(q.u, q.v, z));
    catcher.setAttribute("d", poly(hull(pts)));
    let d = "";
    for (const z of [16, 27]) d += "M" + T(-56, 15, z).join(",") + "L" + T(-28, 15, z).join(",");
    slats.setAttribute("d", d);
  }
  const B = register(stage, (dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 140 || sy < 15 || sy > 305) return leave();
    tset(tw, 1, performance.now(), 0);
    read.textContent = "tip " + Math.round(tip);
    B.wake();
  }
  function leave() { tset(tw, 0, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tip = clamp(v, 45, 95); last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "ridemower",
  means: "A ride-on mower: over it the grass catcher at the back swings up on its hinge to tip out; the slider sets how far.",
  rules: [3, 5, 8],
  range: [45, 75, 95],
  tour: [[149, 122], [215, 160], [180, 215], null],
  mount,
});

telehandler.code:
/**
 * Telehandler: a four-wheeled body with a side cab and a long telescopic
 * boom pinned at the rear, a fork carriage at its tip. Over the machine the
 * boom swings up and its inner section slides out on the 700ms ease; leaving
 * lowers and retracts it, the forks bright. The slider is how far it reaches.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, lerp, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = -34, PZ = 26, A0 = 6, E0 = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.78);
  fit(C, [[-44, -16, 0], [62, 16, 0], [62, -16, 0], [-44, 16, 0], [36, -14, 92], [58, 0, 70]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 2, b = 1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, o, i, z0, z1)); return s; };
  const wheel = (cx, y, dy) => {
    const ring = (yy, r) => Array.from({ length: 22 }, (_, i) => { const t = (i / 22) * Math.PI * 2; return P(cx + r * Math.cos(t), yy, 9 + r * Math.sin(t)); });
    mk("path", { d: poly(hull(ring(y, 9).concat(ring(y + dy, 9)))), class: "sil" }, g);
    mk("path", { d: poly(ring(y + (dy > 0 ? dy : 0), 3.5)), class: "nf lo" }, g);
  };
  wheel(-24, -16, 4); wheel(20, -16, 4);
  box(g, -40, -12, 34, 12, 8, 20, 4, 1.4);
  box(g, -14, -12, 8, -1, 20, 46, 4, 1.4);
  box(g, -15, -13, 9, 0, 46, 48, 3, 1);
  // the boom: an outer and an inner section along the angle, and the forks at the tip
  const boom = mk("g", {}, g);
  const outer = mk("path", { class: "sil" }, boom), inner = mk("path", { class: "sil" }, boom);
  const carriage = mk("path", { class: "sil hi" }, boom), tines = mk("path", { class: "sil hi" }, boom);
  wheel(-24, 12, 4); wheel(20, 12, 4);
  const sec = (a0, a1, y0, y1, n0, n1, T) => { const pts = []; for (const n of [n0, n1]) for (const s of rrect(a0, y0, a1, y1, 1.5, 3)) pts.push(P(...T(s.u, s.v, n))); return poly(hull(pts)); };
  const tw = tween(0);
  let last = NaN;
  function draw(t) {
    if (t === last) return;
    last = t;
    const th = rad(lerp(A0, 6 + 36 * reach, t)), e = lerp(E0, 4 + 24 * reach, t);
    const c = Math.cos(th), s = Math.sin(th);
    const T = (a, y, n) => [PX + a * c - n * s, y, PZ + a * s + n * c];
    outer.setAttribute("d", sec(-4, 58, 1, 10, -4, 4, T));
    inner.setAttribute("d", sec(50, 62 + e, 2, 9, -3, 3, T));
    const [tx, , tz] = T(62 + e, 0, 0);
    const cb = [];
    for (const y of [-2, 12]) for (const [dx, dz] of [[0, -16], [2, -16], [2, 4], [0, 4]]) cb.push(P(tx + dx, y, tz + dz));
    carriage.setAttribute("d", poly(hull(cb)));
    const tn = (y0) => { const p = []; for (const y of [y0, y0 + 2.5]) for (const [x, z] of [[2, -16], [20, -16], [20, -14.5], [2, -14.5]]) p.push(P(tx + x, y, tz + z)); return poly(hull(p)); };
    tines.setAttribute("d", tn(-1) + tn(8));
  }
  const B = register(stage, (dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 140 || sy < 15 || sy > 305) return leave();
    tset(tw, 1, performance.now(), 0);
    read.textContent = "reach " + Math.round(reach * 100);
    B.wake();
  }
  function leave() { tset(tw, 0, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 0.4, 1); last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "telehandler",
  means: "A telehandler: over it the telescopic boom swings up and slides out, carrying the forks; the slider sets how far it reaches.",
  rules: [3, 5, 8],
  range: [0.4, 0.7, 1],
  tour: [[171, 141], [249, 90], [210, 205], null],
  mount,
});

cateringtruck.code:
/**
 * Catering truck: an airport catering truck, a cab at the front and a tall
 * box body on crossed scissor arms. Over the truck the body rises on the
 * 700ms ease to meet an aircraft door; leaving lowers it onto the chassis,
 * the body bright. The slider is how high it climbs.
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, clamp, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BASE = 14, REST = 2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-52, -18, 0], [54, 18, 0], [54, -18, 0], [-52, 18, 0], [-52, -18, BASE + 56 + 35], [28, 18, BASE + 56 + 35]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 2, b = 1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, o, i, z0, z1)); return s; };
  const wheel = (cx, y) => {
    const pts = [];
    for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; pts.push(P(cx + 7 * Math.cos(a), y, 7 + 7 * Math.sin(a))); }
    mk("path", { d: poly(pts) }, g);
  };
  wheel(-32, -16); wheel(36, -16);
  box(g, -50, -15, 52, 15, 6, BASE, 3, 1.2);
  const back = mk("g", {}, g), fr = mk("g", {}, g);
  const armsB = [mk("path", { class: "lo" }, back), mk("path", { class: "lo" }, back)];
  const armsF = [mk("path", {}, fr), mk("path", {}, fr)];
  const body = solid(g);
  body.sil.classList.add("hi");
  const door = mk("path", { class: "nf lo" }, g);
  box(g, 30, -15, 52, 15, BASE, 40, 5, 1.6);
  box(g, 30, -15, 52, 15, 40, 42, 3, 1);
  wheel(-32, 16); wheel(36, 16);
  const [br, bi] = rings(-50, -17, 27, 17, 3, 1.4);
  const L = 26;
  const strip = (a, b, y) => poly([P(a[0], y, a[1] - 1.6), P(b[0], y, b[1] - 1.6), P(b[0], y, b[1] + 1.6), P(a[0], y, a[1] + 1.6)]);
  const lift = tween(REST);
  let last = NaN;
  function draw(H) {
    if (H === last) return;
    last = H;
    const z0 = BASE, z1 = BASE + H;
    const A = [[-12 - L, z0], [-12 + L, z1]], Bb = [[-12 + L, z0], [-12 - L, z1]];
    armsB[0].setAttribute("d", strip(A[0], A[1], -12)); armsB[1].setAttribute("d", strip(Bb[0], Bb[1], -12));
    armsF[0].setAttribute("d", strip(A[0], A[1], 12)); armsF[1].setAttribute("d", strip(Bb[0], Bb[1], 12));
    const zt = BASE + H + 1;
    put(body, prism(P, front, br, bi, zt, zt + 34));
    door.setAttribute("d", poly([P(27, -10, zt + 6), P(27, 10, zt + 6), P(27, 10, zt + 30), P(27, -10, zt + 30)]));
  }
  const B = register(stage, (dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);
  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 130 || sy < 15 || sy > 305) return leave();
    tset(lift, top, performance.now(), 0);
    read.textContent = "up " + Math.round(top);
    B.wake();
  }
  function leave() { tset(lift, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 30, 56); }, destroy: bag.dispose };
}

hairline({
  name: "cateringtruck",
  means: "An airport catering truck: over it the scissor arms open and lift the box body; the slider sets how high it rises.",
  rules: [3, 5, 8],
  range: [30, 44, 56],
  tour: [[184, 162], [150, 120], [230, 225], null],
  mount,
});

legcurl.code:
/**
 * Leg curl: a lying bench on two posts and a rail, and at its foot a lever on
 * a pivot carrying the ankle roller and a pair of weight plates. The pointer's
 * place along the bench is the curl: the lever swings up and back over the
 * pad on a spring, plates and all. At rest it hangs a little raised, the
 * roller bright. The slider is how far the curl goes.
 *
 * The pattern: a continuous input driving one hinged part (spring).
 */
const { Cam, clamp, fillet, fit, hull, lerp, open, poly, proj, rings, prism, facing, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const PX = 24, PZ = 31, REST = 0.35;
const rot = (a) => ([x, z]) => [PX + (x - PX) * Math.cos(a) - (z - PZ) * Math.sin(a), PZ + (x - PX) * Math.sin(a) + (z - PZ) * Math.cos(a)];
function beam(P, A, B, t, y0, y1) {
  const dx = B[0] - A[0], dz = B[1] - A[1], L = Math.hypot(dx, dz) || 1, nx = (-dz / L) * t / 2, nz = (dx / L) * t / 2, pts = [];
  for (const [x, z] of [A, B]) for (const s of [1, -1]) for (const y of [y0, y1]) pts.push(P(x + s * nx, y, z + s * nz));
  const h = hull(pts);
  return { sil: poly(fillet(h, h.map(() => 1.2), 3)), crease: open([P(A[0] + nx * 0.6, y1 - 1, A[1] + nz * 0.6), P(B[0] + nx * 0.6, y1 - 1, B[1] + nz * 0.6)]) };
}
function cylY(P, cx, cz, R, y0, y1) {
  const pts = [], face = [];
  for (let i = 0; i < 32; i++) { const a = (i / 32) * Math.PI * 2, x = cx + R * Math.cos(a), z = cz + R * Math.sin(a); pts.push(P(x, y0, z), P(x, y1, z)); face.push(P(cx + (R - 1.2) * Math.cos(a), y1, cz + (R - 1.2) * Math.sin(a))); }
  return { sil: poly(hull(pts)), crease: open(face.concat([face[0]])) };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let vmax = value, tt = null;
  const C = Cam(45, 0.5, 3.0);
  const ext = [[-44, -16, 0], [30, 16, 0], [-44, 16, 0], [30, -16, 0], [-40, 0, 32]];
  for (const a of [0, -1, -1.8, -2.7]) for (const p of [[PX, 4], [PX, 22], [PX - 9, 13], [PX + 9, 13]]) { const [x, z] = rot(a)(p); ext.push([x, -16, z], [x, 16, z]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r) => { const [a, b] = rings(x0, y0, x1, y1, r, 1); put(solid(g), prism(P, front, a, b, z0, z1)); };
  const farPlate = solid(g);
  box(-44, -6, 30, 6, 0, 3, 2);
  box(-36, -4, -30, 4, 3, 26, 1.5);
  box(16, -4, 22, 4, 3, PZ - 2, 1.5);
  box(-42, -10, 20, 10, 26, 31, 3);
  const lever = solid(g), roller = solid(g), nearPlate = solid(g);
  put(solid(g), cylY(P, PX, PZ, 2.2, -5, 5));
  roller.sil.classList.add("hi");

  const sp = spring(-REST * vmax);
  let drawn = NaN;
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const R = rot(a);
    put(lever, beam(P, R([PX, PZ]), R([PX, 4]), 3, -2, 2));
    const [rx, rz] = R([PX, 7]), [qx, qz] = R([PX, 15]);
    put(roller, cylY(P, rx, rz, 3.6, -11, 11));
    put(farPlate, cylY(P, qx, qz, 9, -16, -12.5));
    put(nearPlate, cylY(P, qx, qz, 9, 12.5, 16));
  }
  const target = () => { sp.t = tt === null ? -REST * vmax : -vmax * lerp(0, 2, tt); };
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const xa = P(-42, 0, 31)[0], xb = P(PX, 0, 10)[0];
  bag.add(pointer(stage, {
    move: (p) => { tt = clamp((p[0] - xa) / (xb - xa), 0, 1); target(); read.textContent = Math.round((-sp.t * 180) / Math.PI) + "°"; B.wake(); },
    leave: () => { tt = null; target(); read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest"; draw();
  return { set: (v) => { vmax = v; target(); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "legcurl",
  means: "A leg curl: the lever with its ankle roller and plates swings up over the bench as far as the pointer takes it.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.3],
  tour: [[123, 90], [263, 223], [193, 156], null],
  mount,
});

pecdeck.code:
/**
 * Chest fly machine: a seat and backrest under a tall frame, with two pad
 * arms hung from the ends of its top beam. The nearer the pointer comes to the
 * middle, the further the fly is squeezed: both arms swing round their pivots on springs
 * until the pads close in front of the chest. The near pad is bright.
 */
const { Cam, circ, facing, fit, prism, proj, rings, spring, stepS, clamp, rad, disposer, mk, pointer, put, register, solid } = HL;

const PX = -23, PY = 24, L = 28, A0 = 100, SPAN = 120, RESTS = [0.22, 0.12];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.35);
  fit(C, [[-34, -16, 0], [8, 16, 0], [-36, -56, 30], [-36, 56, 30], [-36, 0, 78], [4, 0, 30], [-36, -56, 66], [-36, 56, 66]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r = 1.5) => {
    const [a, b] = rings(x0, y0, x1, y1, r, Math.min(1, Math.min(x1 - x0, y1 - y0) / 4));
    put(s, prism(P, front, a, b, z0, z1));
  };
  const turn = (ring, cx, cy, al) => {
    const c = Math.cos(al), s = Math.sin(al);
    return ring.map((q) => ({ ...q, u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
  };
  const rbox = (s, cx, cy, al, hl, hw, z0, z1, r) => {
    const [a, b] = rings(-hl, -hw, hl, hw, r, Math.min(0.8, hw / 2.5));
    put(s, prism(P, front, turn(a, cx, cy, al), turn(b, cx, cy, al), z0, z1));
  };
  const disc = (s, x, y, R, z0, z1) => {
    const m = (q) => ({ ...q, u: q.u + x, v: q.v + y });
    put(s, prism(P, front, circ(R, 24).map(m), circ(R - 0.8, 24).map(m), z0, z1));
  };
  box(solid(g), -34, -16, 8, 16, 0, 3, 3);
  const mkArm = () => { const a = mk("g", {}, g); return { g: a, pad: solid(a), bar: solid(a), piv: solid(a) }; };
  const far = mkArm();
  const col = solid(g); box(col, -32, -4, -25, 4, 3, 76, 2);
  box(solid(g), -8, -2, -4, 2, 3, 22, 1);
  box(solid(g), -27, -27, -19, 27, 72, 77, 2.5);
  box(solid(g), -20, -10, -15, 10, 28, 66, 2.5);
  const seat = solid(g); box(seat, -15, -10, 3, 10, 22, 27, 4);
  const near = mkArm();
  near.pad.sil.classList.add("hi");
  const arms = [far, near], sps = RESTS.map((r) => spring(r)), drawn = [NaN, NaN];
  const ang = (t, side) => side * rad(A0 - SPAN * t * amp);
  function drawArm(i) {
    const t = sps[i].x;
    if (Math.abs(t - drawn[i]) < 1e-4) return;
    drawn[i] = t;
    const side = i ? 1 : -1, py = PY * side, al = ang(t, side);
    const dx = Math.cos(al), dy = Math.sin(al), A = arms[i];
    rbox(A.bar, PX + dx * L / 2, py + dy * L / 2, al, L / 2 + 2, 1.6, 63, 67, 1.2);
    rbox(A.pad, PX + dx * L, py + dy * L, al, 5, 2, 34, 63, 1.6);
    disc(A.piv, PX, py, 2, 63, 72);
    if (i === 0) {
      if (PX + dx * L > -16) seat.g.after(far.g); else col.g.before(far.g);
    }
  }
  const draw = () => { drawArm(0); drawArm(1); };
  const B = register(stage, (dt) => { const m0 = stepS(sps[0], dt), m1 = stepS(sps[1], dt); draw(); return m0 || m1; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const c = P(-6, 0, 40)[0], w = Math.abs(P(PX, PY + L, 40)[0] - c);
      const t = clamp(1.25 - Math.abs(p[0] - c) / w, 0, 1);
      sps[0].t = t; sps[1].t = t;
      read.textContent = "fly " + Math.round(t * 100) + "%"; B.wake();
    },
    leave: () => { sps.forEach((s, i) => { s.t = RESTS[i]; }); read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest"; draw();
  return { set: (v) => { amp = v; drawn[0] = drawn[1] = NaN; draw(); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "pecdeck",
  means: "A chest fly machine: both pad arms swing round their pivots and close in front of the seat as the pointer nears the middle.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1.25],
  tour: [[139, 153], [215, 180], [250, 169], null],
  mount,
});

latpulldown.code:
/**
 * Lat pulldown: a seat and knee pad under a tall frame, a top beam with a
 * cable running over it, the long bar hanging above the seat and the weight
 * stack in its guide rods at the back. The pointer's height is how far the
 * bar is pulled: it comes down on a spring and the top of the stack rises on
 * the cable. The bar is bright. The slider sets how far a pull carries it.
 */
const { Cam, fit, facing, prism, proj, rings, spring, stepS, clamp, disposer, mk, pointer, put, register, solid, seg } = HL;

const REST = 0.18, BAR0 = 70, MAX = 34, N = 9, LIFT = 5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-46, -28, 0], [22, 28, 0], [-46, 28, 0], [22, -28, 0], [-46, 0, 94], [14, 0, 94], [12, -27, BAR0 + 4], [12, 27, BAR0 + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r = 1.5) => {
    const [a, b] = rings(x0, y0, x1, y1, r, Math.min(1, Math.min(x1 - x0, y1 - y0) / 4));
    put(s, prism(P, front, a, b, z0, z1));
  };
  box(solid(g), -46, -16, 22, 16, 0, 3, 3);
  const cable = mk("path", { class: "nf lo" }, g);
  mk("path", { class: "nf lo", d: seg(P(-36, -7, 3), P(-36, -7, 82)) + seg(P(-36, 7, 3), P(-36, 7, 82)) }, g);
  const plates = [];
  for (let i = 0; i < N; i++) plates.push(solid(g));
  box(solid(g), -28, -4, -22, 4, 3, 88, 1.5);
  box(solid(g), -42, -5, 16, 5, 86, 92, 2);
  const lines = mk("path", { class: "nf lo" }, g);
  box(solid(g), 6, -6, 18, 6, 3, 16, 2);
  box(solid(g), 4, -9, 20, 9, 16, 20, 3);
  box(solid(g), 1, -10, 5, 10, 27, 32, 2);
  mk("path", { class: "nf lo", d: seg(P(3, 0, 20), P(3, 0, 27)) }, g);
  const bar = solid(g);
  bar.sil.classList.add("hi");
  const sp = spring(REST);
  let gain = value / 1.4, drawn = NaN;
  function draw() {
    const t = sp.x * gain;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const bz = BAR0 - MAX * t, lift = MAX * t;
    for (let i = 0; i < N; i++) {
      const z = 3 + i * 3 + (i >= N - LIFT ? lift : 0);
      box(plates[i], -42, -10, -30, 10, z, z + 2.6, 1.5);
    }
    const top = 3 + N * 3 + lift;
    cable.setAttribute("d", seg(P(-36, 0, top), P(-36, 0, 86)));
    lines.setAttribute("d", seg(P(12, 0, 86), P(12, 0, bz + 4)) + seg(P(12, -24, bz + 1), P(12, -24, bz - 6)) + seg(P(12, 24, bz + 1), P(12, 24, bz - 6)));
    box(bar, 10, -27, 14, 27, bz, bz + 3.5, 1.7);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      const a = P(12, 0, BAR0)[1], b = P(12, 0, BAR0 - MAX)[1];
      sp.t = clamp((p[1] - a) / (b - a), 0, 1);
      read.textContent = Math.round(sp.t * 100) + "%"; B.wake();
    },
    leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest"; draw();
  return { set: (v) => { gain = v / 1.4; drawn = NaN; draw(); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "latpulldown",
  means: "A lat pulldown: the bar comes down as far as the pointer pulls it, and the weight stack rises on the cable.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[268, 111], [206, 206], [237, 168], null],
  mount,
});

speedbag.code:
/**
 * Speed bag: a wall board, a bracket and a round rebound platform, with the
 * teardrop bag hanging from its swivel underneath. The pointer's side of the
 * bag is where it swings: it tilts on the swivel toward the pointer on a
 * spring. At rest it hangs a little off true, and the bag is bright. The
 * slider sets how wide a swing goes.
 */
const { Cam, fit, facing, prism, proj, rings, circ, hull, poly, open, spring, stepS, clamp, rad, disposer, mk, pointer, put, register, solid, seg } = HL;

const REST = -0.3, MAXA = 62, L = 44, HX = 2, HZ = 88;
const U = [Math.SQRT1_2, -Math.SQRT1_2];
const rOf = (s) => (s < 3 ? 2.2 : Math.max(2.2, 14 * Math.pow(Math.sin(Math.PI * Math.pow((s - 3) / (L - 3), 0.75)), 0.65)));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.7);
  const end = (k) => [HX + U[0] * k * 40, U[1] * k * 40, HZ - 30];
  fit(C, [[-36, -24, 56], [-36, 24, 102], [24, 0, 94], [2, 22, 94], [2, -22, 94], end(1), end(-1), [HX, 0, HZ - L]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r = 1.5) => {
    const [a, b] = rings(x0, y0, x1, y1, r, Math.min(1, Math.min(x1 - x0, y1 - y0) / 4));
    put(s, prism(P, front, a, b, z0, z1));
  };
  box(solid(g), -38, -24, -33, 24, 56, 102, 2);
  mk("path", { class: "nf lo", d: seg(P(-33, 0, 66), P(-14, 0, 88)) }, g);
  const bg = solid(g);
  bg.sil.classList.add("hi");
  box(solid(g), -33, -3, 0, 3, 87, 90, 1);
  const m = (q) => ({ ...q, u: q.u + HX, v: q.v });
  put(solid(g), prism(P, front, circ(22, 48).map(m), circ(20.8, 48).map(m), 90, 94));
  const sp = spring(REST);
  let gain = value / 1.4, drawn = NaN;
  function draw() {
    const t = sp.x * gain;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const a = rad(MAXA * t), d = [Math.sin(a) * U[0], Math.sin(a) * U[1], -Math.cos(a)];
    const e1 = [Math.cos(a) * U[0], Math.cos(a) * U[1], Math.sin(a)], e2 = [Math.SQRT1_2, Math.SQRT1_2, 0];
    const pts = [], crease = [];
    for (let s = 0; s <= L; s += 1.5) {
      const r = rOf(s), c = [HX + d[0] * s, d[1] * s, HZ + d[2] * s];
      for (let k = 0; k < 24; k++) {
        const q = (k / 24) * Math.PI * 2, cs = Math.cos(q), sn = Math.sin(q);
        const p = P(c[0] + r * (cs * e1[0] + sn * e2[0]), c[1] + r * (cs * e1[1] + sn * e2[1]), c[2] + r * (cs * e1[2] + sn * e2[2]));
        pts.push(p);
        if (Math.abs(s - 21) < 0.1 && sn > -0.05) crease.push(p);
      }
    }
    bg.sil.setAttribute("d", poly(hull(pts)));
    bg.cr.setAttribute("d", open(crease.sort((p, q) => p[0] - q[0])));
  }
  const B = register(stage, (dt) => { const mv = stepS(sp, dt); draw(); return mv; });
  bag.add(B.unregister);
  bag.add(pointer(stage, {
    move: (p) => {
      sp.t = clamp((p[0] - P(HX, 0, HZ - 20)[0]) / 30, -1, 1);
      read.textContent = Math.round(sp.t * MAXA * gain) + "°"; B.wake();
    },
    leave: () => { sp.t = REST; read.textContent = "rest"; B.wake(); },
  }));
  bag.add(() => svg.replaceChildren());
  read.textContent = "rest"; draw();
  return { set: (v) => { gain = v / 1.4; drawn = NaN; draw(); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "speedbag",
  means: "A speed bag: the teardrop bag swings on its swivel under the round platform toward the side the pointer comes from.",
  rules: [1, 3, 5, 8],
  range: [0.5, 1, 1.4],
  tour: [[236, 189], [160, 190], [293, 201], null],
  mount,
});

mufflefurnace.code:
/**
 * Muffle furnace: a lab box furnace with a squat chamber, a vent on top and a
 * thick front door hinged along its foot. The pointer over the furnace drops
 * the door forward and down to open the chamber. At rest the door stands
 * ajar, bright. The slider is how far the door drops.
 *
 * The pattern: one part swinging on a hinge.
 */
const { Cam, circ, fit, hull, poly, prism, proj, facing, rings, ringAt, rad, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 60, D = 48, H = 58, HZ = 8, DH = 42, T = 4, REST = 14;
const disc = (x, y, r, n = 16) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let drop = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[0, 0, H + 8], [W, 0, 0], [0, D + DH + T, 0], [W, D + DH + T, 0], [0, D, 0]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [vr, vi] = [disc(W * 0.3, D * 0.3, 5), disc(W * 0.3, D * 0.3, 3.6)];
  put(solid(g), prism(P, front, ...rings(0, 0, W, D, 5, 2), 0, H));
  put(solid(g), prism(P, front, vr, vi, H, H + 8));
  // the chamber mouth on the front face, and two knobs under the door
  const face = (x, z) => P(x, D, z);
  mk("path", { d: poly([face(13, 13), face(W - 13, 13), face(W - 13, HZ + DH - 6), face(13, HZ + DH - 6)]), class: "nf lo" }, g);
  mk("path", { d: poly([face(16, 13), face(W - 16, 13), face(W - 19, 19), face(19, 19)]), class: "nf lo" }, g);
  [W * 0.32, W * 0.68].forEach((x) => { const k = mk("circle", { r: 1.6, class: "dot off" }, g); const p = face(x, 4); k.setAttribute("cx", p[0]); k.setAttribute("cy", p[1]); });

  const doorG = mk("g", {}, g);
  const handle = mk("path", { d: "", class: "nf" }, doorG);
  const door = solid(doorG);
  door.sil.classList.add("hi");
  const [dr, di] = rings(7, 0, W - 7, DH, 3, 1.8);
  const z = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), s = Math.sin(a), c = Math.cos(a);
    const at = (u, v, w) => P(u, D + v * s + w * c, HZ + v * c - w * s);
    const out = deg < 50;
    const A = dr.map((q) => at(q.u, q.v, 0)), B = dr.map((q) => at(q.u, q.v, T));
    put(door, { sil: poly(hull(A.concat(B))), crease: poly(di.map((q) => at(q.u, q.v, out ? T : 0))) });
    const hv = DH - 6, h0 = W / 2 - 11, h1 = W / 2 + 11;
    handle.setAttribute("d", "M" + [at(h0, hv, T), at(h0, hv, T + 4), at(h1, hv, T + 4), at(h1, hv, T)].map((p) => p.join(",")).join("L"));
    if (out) doorG.appendChild(handle); else doorG.insertBefore(handle, door.g);
  }

  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  const mid = P(W / 2, D / 2 + 10, H / 2);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(z, on ? drop : REST, performance.now(), 0);
    read.textContent = on ? "door " + Math.round(drop) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(Math.hypot(sx - mid[0], (sy - mid[1]) * 1.2) < 125), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { drop = v; if (act) { read.textContent = "door " + Math.round(v); tset(z, v, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "mufflefurnace",
  means: "A muffle furnace: the pointer over it drops the heavy front door forward on its foot hinge to open the chamber.",
  rules: [1, 5, 6],
  range: [40, 88, 95],
  tour: [[195, 157], [232, 112], [165, 228], null],
  mount,
});

rotavap.code:
/**
 * Rotary evaporator: a heating bath on the bench, a lift post beside it,
 * and the head on the post: motor, angled vapour duct, round evaporating
 * flask, upright condenser and its receiving flask. Over the machine the
 * head tilts down on its pivot to dip the flask toward the bath; leaving
 * lifts it again. The slider is how far the head tilts.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, circ, ringAt, seg, tween, tset, tval, tdone, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PV = [96, 22, 72], REST = -6;
const rot = (p, a) => { const dx = p[0] - PV[0], dz = p[2] - PV[2], ca = Math.cos(a), sa = Math.sin(a); return [PV[0] + dx * ca - dz * sa, p[1], PV[2] + dx * sa + dz * ca]; };
function cyl(a, b, r, n = 20) {
  const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], l = Math.hypot(...d), u = d.map((v) => v / l);
  const e1 = [0, 1, 0], e2 = [u[1] * 0 - u[2] * 1, u[2] * 0 - u[0] * 0, u[0] * 1 - u[1] * 0];
  const o = [];
  for (const c of [a, b]) for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2, cs = Math.cos(t) * r, sn = Math.sin(t) * r; o.push([c[0] + e1[0] * cs + e2[0] * sn, c[1] + e1[1] * cs + e2[1] * sn, c[2] + e1[2] * cs + e2[2] * sn]); }
  return o;
}
function ball(c, r) {
  const o = [];
  for (let i = 0; i <= 8; i++) for (let j = 0; j < 16; j++) { const th = (i / 8) * Math.PI, ph = (j / 16) * Math.PI * 2; o.push([c[0] + r * Math.sin(th) * Math.cos(ph), c[1] + r * Math.sin(th) * Math.sin(ph), c[2] + r * Math.cos(th)]); }
  return o;
}
const box = (x0, x1, y0, y1, z0, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x, y, z]); return o; };
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ang = value, on = false;
  const C = Cam(45, 0.5, 1.7);
  const FC = [30, 22, 62];
  const parts = {
    recv: ball([112, 22, 46], 10).concat(cyl([112, 22, 54], [112, 22, 62], 2.6)),
    cond: cyl([108, 22, 82], [112, 22, 128], 7),
    duct: cyl([88, 22, 70], [FC[0] + 12, 22, FC[2] + 3], 3),
    motor: box(84, 108, 12, 32, 62, 84),
    flask: ball(FC, 15).concat(cyl([FC[0] + 10, 22, FC[2] + 2], [FC[0] + 20, 22, FC[2] + 4], 4.5)),
  };
  const head = [].concat(...Object.values(parts));
  fit(C, [[0, 0, 0], [130, 44, 0], [0, 44, 0], [130, 0, 0]].concat(head.map((p) => rot(p, rad(REST))), head.map((p) => rot(p, rad(22)))), 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(28, 22, 28), disc(28, 22, 26), 0, 24));
  mk("path", { d: poly(ringAt(P, disc(28, 22, 24), 19)), class: "nf lo" }, g);
  const [br, bi] = rings(74, 0, 130, 44, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 7));
  put(solid(g), prism(P, front, disc(96, 22, 4.5, 20), disc(96, 22, 3, 20), 7, 104));
  const S = {};
  for (const k of ["recv", "cond", "duct", "motor", "flask"]) S[k] = solid(g);
  S.flask.sil.classList.add("hi");
  const ht = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), q = (p) => P(...rot(p, a));
    for (const k in S) S[k].sil.setAttribute("d", poly(hull(parts[k].map(q))));
    let cr = "";
    for (let z = 88; z < 124; z += 6) cr += seg(q([108 + (z - 82) * 0.087 - 4, 22, z]), q([108 + (z - 82) * 0.087 + 4, 22, z + 3]));
    S.cond.cr.setAttribute("d", cr);
    S.motor.cr.setAttribute("d", seg(q([108, 32, 84]), q([108, 12, 84])) + seg(q([108, 32, 84]), q([84, 32, 84])));
    S.flask.cr.setAttribute("d", seg(q([FC[0] - 9, 22, FC[2] - 6]), q([FC[0] + 4, 22, FC[2] - 12])));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ht, now)); return !tdone(ht, now); });
  bag.add(B.unregister);

  const rest = head.map((p) => P(...rot(p, rad(REST)))).concat([[0, 0, 0], [130, 44, 0], [0, 44, 0], [130, 0, 0]].map((p) => P(...p)));
  const xs = rest.map((p) => p[0]), ys = rest.map((p) => p[1]);
  const bx = [Math.min(...xs) - 6, Math.max(...xs) + 6, Math.min(...ys) - 6, Math.max(...ys) + 6];
  const hit = ([sx, sy]) => sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3];
  function setOn(v) {
    on = v;
    tset(ht, on ? ang : REST, performance.now(), 0);
    read.textContent = on ? "dip " + Math.round(ang) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => { const h = hit(p); if (h !== on) setOn(h); }, leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { ang = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "rotavap",
  means: "A rotary evaporator: over the machine its head tilts on the lift post, dipping the round flask down toward the heating bath.",
  rules: [1, 3, 5, 6],
  range: [8, 18, 22],
  tour: [[158, 98], [236, 130], [210, 215], null],
  mount,
});

tuberocker.code:
/**
 * Tube rocker: a low motor base with a ribbed platform on a pivot, five
 * capped sample tubes lying across it. The pointer's side of the platform
 * tips down and the tubes rock with it; leaving settles it to a slight lean.
 * The slider is the rocking angle.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, seg, clamp, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 110, D = 70, ZC = 30, REST = -5;
const rot = (p, a) => { const dx = p[0] - L / 2, dz = p[2] - ZC, ca = Math.cos(a), sa = Math.sin(a); return [L / 2 + dx * ca - dz * sa, p[1], ZC + dx * sa + dz * ca]; };
function tube(x0, x1, y, z, r, n = 18) {
  const pts = [];
  for (const x of [x0, x1]) for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; pts.push([x, y + r * Math.cos(t), z + r * Math.sin(t)]); }
  return pts;
}
const box = (x0, x1, y0, y1, z0, z1) => { const o = []; for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) o.push([x, y, z]); return o; };

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.95);
  const plate = box(0, L, 0, D, ZC, ZC + 3);
  const tubes = [10, 22, 34, 46, 58].map((y, k) => ({ body: tube(12, 92, y, ZC + 8, 4.6), cap: tube(92, 102, y, ZC + 8, 5.6), k }));
  const all = plate.concat(...tubes.map((t) => t.body.concat(t.cap)));
  fit(C, [[22, 14, 0], [88, 56, 0]].concat(all.map((p) => rot(p, rad(26))), all.map((p) => rot(p, rad(-26)))), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(22, 14, 88, 56, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, 18));
  const [pr, pi] = rings(48, 30, 62, 40, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 18, ZC));
  const led = mk("circle", { r: 2.4, class: "dot off" }, g);
  const lp = P(70, 56, 9); led.setAttribute("cx", lp[0]); led.setAttribute("cy", lp[1]);
  const pl = solid(g);
  pl.sil.classList.add("hi");
  const tg = tubes.map((t) => ({ ...t, b: solid(g), c: solid(g) }));
  const sp = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), q = (p) => P(...rot(p, a));
    pl.sil.setAttribute("d", poly(hull(plate.map(q))));
    let cr = seg(q([0, D, ZC + 3]), q([L, D, ZC + 3])) + seg(q([L, 0, ZC + 3]), q([L, D, ZC + 3]));
    for (const y of [16, 28, 40, 52]) cr += seg(q([4, y, ZC + 3]), q([L - 4, y, ZC + 3]));
    pl.cr.setAttribute("d", cr);
    for (const t of tg) {
      t.b.sil.setAttribute("d", poly(hull(t.body.map(q))));
      t.c.sil.setAttribute("d", poly(hull(t.cap.map(q))));
      t.b.cr.setAttribute("d", seg(q(t.body[3]), q(t.body[21])));
    }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  const rest = all.map((p) => P(...rot(p, rad(REST)))).concat([[22, 14, 0], [88, 56, 0]].map((p) => P(...p)));
  const xs = rest.map((p) => p[0]), ys = rest.map((p) => p[1]);
  const bx = [Math.min(...xs) - 6, Math.max(...xs) + 6, Math.min(...ys) - 6, Math.max(...ys) + 6];
  const cx = (bx[0] + bx[1]) / 2, hw = (bx[1] - bx[0]) / 2;
  let px = null;
  function aim() {
    if (px === null) { sp.t = REST; read.textContent = "rest"; }
    else { const s = clamp((px - cx) / (hw * 0.7), -1, 1); sp.t = -s * max; read.textContent = (s < 0 ? "L " : "R ") + Math.round(Math.abs(s * max)) + "°"; }
    B.wake();
  }
  aim();
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { px = sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3] ? sx : null; aim(); },
    leave: () => { px = null; aim(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; aim(); }, destroy: bag.dispose };
}

hairline({
  name: "tuberocker",
  means: "A lab tube rocker: its platform of capped tubes tips toward the side under the pointer and settles to a lean on leaving.",
  rules: [1, 3, 5, 8],
  range: [8, 20, 26],
  tour: [[299, 169], [160, 140], [228, 200], null],
  mount,
});

waterbath.code:
/**
 * Lab water bath: a rounded steel tank with a gabled lid hinged along its
 * back edge. Over the bath the lid swings up and back to show the water
 * line inside; leaving lowers it to rest, just ajar. The slider is how far
 * the lid opens.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, ringAt, seg, tween, tset, tval, tdone, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 92, D = 58, H = 36, RH = 15, REST = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ang = value, on = false;
  const C = Cam(45, 0.5, 1.85);
  const hinge = (p, a) => { const dy = p[1], dz = p[2] - H, ca = Math.cos(a), sa = Math.sin(a); return [p[0], dy * ca - dz * sa, H + dy * sa + dz * ca]; };
  const eave = [], ridge = [[-2, D / 2, H + 3 + RH], [W + 2, D / 2, H + 3 + RH]];
  for (const x of [-2, W + 2]) for (const y of [-2, D + 2]) for (const z of [H, H + 3]) eave.push([x, y, z]);
  const lidPts = eave.concat(ridge);
  const ext = [[0, 0, 0], [W, D, 0], [W, 0, 0], [0, D, 0]].concat(lidPts.map((p) => hinge(p, rad(100))), lidPts.map((p) => hinge(p, rad(REST))));
  fit(C, ext, 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [tr, ti] = rings(0, 0, W, D, 7, 2);
  put(solid(g), prism(P, front, tr, ti, 0, H));
  mk("path", { d: poly(ringAt(P, rrect(4, 4, W - 4, D - 4, 5, 6), H - 7)), class: "nf lo" }, g);
  for (const x of [26, 46, 66]) mk("path", { d: poly(ringAt(P, rrect(x - 4, 22, x + 4, 30, 3, 4), H - 7)), class: "nf lo" }, g);
  const dial = mk("circle", { r: 2.6, class: "dot off" }, g);
  const dp = P(W, D * 0.32, H * 0.45); dial.setAttribute("cx", dp[0]); dial.setAttribute("cy", dp[1]);
  const lid = solid(g);
  const lt = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), q = (p) => P(...hinge(p, a));
    const r0 = q(ridge[0]), r1 = q(ridge[1]);
    const g0 = q([W + 2, -2, H + 3]), g1 = q([W + 2, D + 2, H + 3]);
    lid.sil.setAttribute("d", poly(hull(lidPts.map(q))));
    lid.cr.setAttribute("d", seg(r0, r1) + seg(g0, r1) + seg(g1, r1) + seg(q([-2, D + 2, H + 3]), g1));
  }
  lid.sil.classList.add("hi");
  const B = register(stage, (_dt, now) => { draw(tval(lt, now)); return !tdone(lt, now); });
  bag.add(B.unregister);

  const box = hull(ext.slice(0, 4).concat(lidPts.map((p) => hinge(p, rad(REST)))).map((p) => P(...p)));
  const xs = box.map((p) => p[0]), ys = box.map((p) => p[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  const hit = ([sx, sy]) => sx > bx[0] - 6 && sx < bx[1] + 6 && sy > bx[2] - 6 && sy < bx[3] + 6;
  function setOn(v) {
    on = v;
    tset(lt, on ? ang : REST, performance.now(), 0);
    read.textContent = on ? "lid " + Math.round(ang) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, { move: (p) => { const h = hit(p); if (h !== on) setOn(h); }, leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { ang = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "waterbath",
  means: "A lab water bath with a gabled lid: over the tank the lid swings up on its back hinge to show the water inside.",
  rules: [1, 3, 5, 6],
  range: [40, 80, 100],
  tour: [[186, 169], [250, 230], [150, 200], null],
  mount,
});

policecar.code:
/**
 * Police car: a three-box sedan on four wheels, a glassy cabin, a push bar
 * at the nose and a long light bar across the roof. The pointer over the car
 * raises the light bar on its mast and turns it round, on two springs, so
 * it sweeps from across the roof to along it. At rest the bar sits low and
 * across, bright. The slider is how high it rises and how far it turns.
 *
 * The pattern: one part answering, hit on the rest pose's screen box.
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rad, rings, rrect, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WR = 9, WW = 6, ROOF = 37, BX = -4, HL2 = 20, HW = 5;
const WHEELS = [[-28, -18], [28, -18], [-28, 18], [28, 18]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-48, -24, 0], [52, 24, 0], [52, -24, 0], [-48, 24, 0], [BX - 21, -21, ROOF + 26], [BX + 21, 21, ROOF + 26]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = ([u, v]) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; for (const dv of [-WW / 2, WW / 2]) pts.push(P(u + WR * Math.cos(t), v + Math.sign(v) * dv, WR + WR * Math.sin(t))); }
    return poly(hull(pts));
  };
  const hub = ([u, v]) => poly(hull([0, 1, 2, 3, 4, 5, 6, 7].map((i) => P(u + 3.5 * Math.cos(i * 0.785), v + Math.sign(v) * (WW / 2 + 0.2), WR + 3.5 * Math.sin(i * 0.785)))));
  const wheelSet = (w) => { mk("path", { d: wheel(w), class: "sil" }, g); mk("path", { d: hub(w), class: "nf lo" }, g); };
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, o, i, z0, z1)); return s; };
  WHEELS.filter((w) => w[1] < 0).forEach(wheelSet);
  box(-46, -18, 46, 18, 6, 1.6, 8, 22);
  // cabin: wide foot, short roof
  const foot = rrect(-26, -17, 18, 17, 5, 6), top = rrect(-18, -14, 8, 14, 4, 6);
  const at = (ring, z) => ring.map((q) => P(q.u, q.v, z));
  mk("path", { d: poly(hull(at(foot, 22).concat(at(top, ROOF)))), class: "sil" }, g);
  mk("path", { d: poly([P(-22, 17, 23), P(-6, 17, 23), P(-6, 14.5, 36), P(-16, 14.5, 36)]) + poly([P(-2, 17, 23), P(14, 17, 23), P(6, 14.5, 36), P(-2, 14.5, 36)]), class: "nf lo" }, g);
  // a stripe down the near flank
  mk("path", { d: seg(P(-44, 18, 15), P(44, 18, 15)), class: "nf lo" }, g);
  box(46, -12, 51, 12, 2, 0.8, 8, 20);
  WHEELS.filter((w) => w[1] > 0).forEach(wheelSet);
  // mast and light bar, drawn on top of the roof
  const mast = mk("path", { class: "nf" }, g);
  const bar = solid(g), domes = mk("path", { class: "nf lo" }, g);
  bar.sil.setAttribute("class", "sil hi");
  const base = rrect(-HW, -HL2, HW, HL2, 3, 6), inner = rrect(-HW + 1.2, -HL2 + 1.2, HW - 1.2, HL2 - 1.2, 2, 6);
  const sh = spring(0), sa = spring(0);
  let lastH = NaN, lastA = NaN, over = false;

  function draw() {
    const h = Math.max(0, sh.x), a = sa.x;
    if (Math.abs(h - lastH) < 0.01 && Math.abs(a - lastA) < 0.0005) return;
    lastH = h; lastA = a;
    const c = Math.cos(a), s = Math.sin(a);
    const turn = (ring) => ring.map((q) => ({ u: BX + q.u * c - q.v * s, v: q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
    const z0 = ROOF + 1 + h, z1 = z0 + 5;
    put(bar, prism(P, front, turn(base), turn(inner), z0, z1));
    let d = "";
    for (const k of [-1, 1]) for (const t of [0.35, 0.75]) {
      const v = k * HL2 * t, p0 = [BX - 4 * s * 0 + (-HW) * c - v * s, (-HW) * s + v * c], p1 = [BX + HW * c - v * s, HW * s + v * c];
      d += seg(P(p0[0], p0[1], z1), P(p1[0], p1[1], z1));
    }
    domes.setAttribute("d", d);
    mast.setAttribute("d", seg(P(BX, 0, ROOF), P(BX, 0, z0)) + seg(P(BX - 1.5, 0, ROOF), P(BX - 1.5, 0, z0)));
  }

  const B = register(stage, (dt) => { const m1 = stepS(sh, dt), m2 = stepS(sa, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);
  const bb = [[-48, -24, 0], [52, 24, 0], [52, -24, 0], [-48, 24, 0], [BX, -HL2, ROOF + 6], [BX, HL2, ROOF + 6]].map((q) => P(...q));
  const xs = bb.map((q) => q[0]), ys = bb.map((q) => q[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];

  function retarget() {
    sh.t = over ? 6 + 14 * reach : 0;
    sa.t = over ? rad(40 + 50 * reach) : 0;
    read.textContent = over ? "turn " + Math.round((sa.t * 180) / Math.PI) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { over = sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3]; retarget(); },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  draw();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "policecar",
  means: "A police sedan with a light bar on the roof: the pointer over it raises the bar on its mast and turns it round to sweep.",
  rules: [1, 3, 5, 8],
  range: [0, 1, 1],
  tour: [[189, 125], [152, 156], [248, 262], null],
  mount,
});

limousine.code:
/**
 * Limousine: a stretched sedan on four wheels, a long low cabin and a row of
 * passenger doors down its near flank. The pointer along the car swings the
 * door under it open on its front hinge, its neighbours following less and
 * later, on the 700ms tween. At rest every door is shut and the second one
 * bright. The slider is how far the doors swing.
 *
 * The pattern: a single row, picked by screen x on the rest pose.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, rrect, seg, tween, tset, tval, tdone,
  disposer, mk, pointer, register, solid, put,
} = HL;

const WR = 8, WW = 6, Y = 17.5, DW = 16, Z0 = 10, Z1 = 31, REST = 1;
const WHEELS = [[-56, -16], [54, -16], [-56, 16], [54, 16]];
const HINGE = [-30, -12, 6, 24];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-76, -20, 0], [74, 20, 0], [74, -20, 0], [-76, 36, 0], [-40, -15, 34], [24, 34, 31]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = ([u, v]) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; for (const dv of [-WW / 2, WW / 2]) pts.push(P(u + WR * Math.cos(t), v + Math.sign(v) * dv, WR + WR * Math.sin(t))); }
    return poly(hull(pts));
  };
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  WHEELS.filter((w) => w[1] < 0).forEach((w) => mk("path", { d: wheel(w), class: "sil" }, g));
  box(-74, -17, 72, 17, 7, 1.6, 7, 20);
  const foot = rrect(-50, -17, 40, 17, 5, 6), top = rrect(-46, -16.5, 32, 16.5, 4, 6);
  mk("path", { d: poly(hull(foot.map((q) => P(q.u, q.v, 20)).concat(top.map((q) => P(q.u, q.v, 34))))), class: "sil" }, g);
  mk("path", { d: seg(P(-44, 16.5, 32.5), P(30, 16.5, 32.5)), class: "nf lo" }, g);
  box(72, -11, 76, 11, 2, 0.8, 8, 17);
  WHEELS.filter((w) => w[1] > 0).forEach((w) => mk("path", { d: wheel(w), class: "sil" }, g));
  // the doors: open hollows behind, then the leaves, back to front
  const holes = HINGE.map((h) => mk("path", { d: poly([P(h - DW, Y, Z0), P(h, Y, Z0), P(h, Y, Z1), P(h - DW, Y, Z1)]), class: "nf lo" }, g));
  const leaves = HINGE.map(() => ({ s: mk("path", { class: "sil" }, g), w: mk("path", { class: "nf lo" }, g), tw: tween(0), last: NaN }));
  let chosen = -1;

  function draw(now) {
    leaves.forEach((L, i) => {
      const a = tval(L.tw, now);
      if (Math.abs(a - L.last) < 0.0005) return;
      L.last = a;
      const h = HINGE[i], c = Math.cos(a), s = Math.sin(a);
      const at = (d, t, z) => P(h - d * c + t * s, Y + d * s + t * c, z);
      const pts = [];
      for (const z of [Z0, Z1]) for (const d of [0, DW]) for (const t of [0, 1]) pts.push(at(d, t, z));
      L.s.setAttribute("d", poly(hull(pts)));
      L.w.setAttribute("d", poly([at(2, 1, 21), at(DW - 2, 1, 21), at(DW - 2, 1, 29), at(2, 1, 29)]) + seg(at(DW - 3, 1, 17), at(DW - 6, 1, 17)));
    });
  }

  const B = register(stage, (dt, now) => { draw(now); return leaves.some((L) => !tdone(L.tw, now)); });
  bag.add(B.unregister);
  const mids = HINGE.map((h) => P(h - DW / 2, Y, Z0)[0]);
  const bb = [[-76, -20, 0], [74, 20, 0], [74, -20, 0], [-76, 20, 0], [-46, -15, 34], [32, 15, 34]].map((q) => P(...q));
  const xs = bb.map((q) => q[0]), ys = bb.map((q) => q[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];

  function retarget() {
    const now = performance.now();
    leaves.forEach((L, i) => {
      const f = chosen < 0 ? 0 : [1, 0.42, 0.16, 0.06][Math.abs(i - chosen)];
      tset(L.tw, rad((35 + 50 * reach) * f), now, chosen < 0 ? 0 : Math.abs(i - chosen) * 45);
      L.s.setAttribute("class", i === (chosen < 0 ? REST : chosen) ? "sil hi" : "sil");
    });
    read.textContent = chosen < 0 ? "rest" : "door " + (chosen + 1);
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => {
      let k = -1;
      if (sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3]) { let bd = 1e9; mids.forEach((m, i) => { const d = Math.abs(m - sx); if (d < bd) { bd = d; k = i; } }); }
      if (k !== chosen) { chosen = k; retarget(); }
    },
    leave: () => { chosen = -1; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  draw(performance.now());
  return { set: (v) => { reach = clamp(v, 0, 1); retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "limousine",
  means: "A stretch limousine with a row of passenger doors: the pointer along it swings the door beneath open, its neighbours less.",
  rules: [1, 2, 3, 4, 5, 8],
  range: [0, 1, 1],
  tour: [[161, 129], [136, 135], [210, 173], null],
  mount,
});

rallycar.code:
/**
 * Rally car: a short hatchback on four chunky tyres, a sloped cabin with a
 * roof scoop, a wide rear spoiler and long-travel coil springs at each wheel.
 * The pointer over the car makes it jump: the whole body heaves up off the
 * wheels on its suspension, on a spring, the coils stretching beneath it.
 * At rest the body sits low, the roof scoop bright. The slider is how high
 * the body rises.
 *
 * The pattern: one part answering, hit on the rest pose's screen box.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, run, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WR = 10, WW = 7, LIFT = 22;
const WHEELS = [[-27, -19], [29, -19], [-27, 19], [29, 19]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[-44, -24, 0], [44, 24, 0], [44, -24, 0], [-44, 24, 0], [-44, -20, 44 + LIFT], [10, 16, 44 + LIFT]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = ([u, v]) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; for (const dv of [-WW / 2, WW / 2]) pts.push(P(u + WR * Math.cos(t), v + Math.sign(v) * dv, WR + WR * Math.sin(t))); }
    return poly(hull(pts));
  };
  const hub = ([u, v]) => poly(hull([0, 1, 2, 3, 4, 5, 6, 7].map((i) => P(u + 4 * Math.cos(i * 0.785), v + Math.sign(v) * (WW / 2 + 0.2), WR + 4 * Math.sin(i * 0.785)))));
  const wheelSet = (w) => { mk("path", { d: wheel(w), class: "sil" }, g); mk("path", { d: hub(w), class: "nf lo" }, g); };
  WHEELS.filter((w) => w[1] < 0).forEach(wheelSet);
  const coils = mk("path", { class: "nf lo" }, g);
  const body = mk("g", {}, g);
  const box = (x0, y0, x1, y1, r, b, z0, z1, par = body) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(par); put(s, prism(P, front, o, i, z0, z1)); return s; };
  // rear spoiler: two struts then the blade
  mk("path", { d: seg(P(-40, -10, 30), P(-42, -10, 36)) + seg(P(-40, 10, 30), P(-42, 10, 36)), class: "nf" }, body);
  box(-46, -18, -38, 18, 1.5, 0.6, 36, 38.5);
  box(-42, -17, 42, 17, 6, 1.6, 14, 28);
  // cabin: a sloped hull from a wide foot to a short roof
  const foot = rrect(-34, -16, 18, 16, 5, 6), top = rrect(-30, -13, 0, 13, 4, 6), inner = rrect(-29, -12, -1, 12, 3, 6);
  put(solid(body), { sil: poly(hull(ringAt(P, foot, 28).concat(ringAt(P, top, 41)))), crease: open(ringAt(P, run(inner, front), 41)) });
  mk("path", { d: poly([P(-24, 16, 30), P(-8, 16, 30), P(-8, 13.5, 39), P(-22, 13.5, 39)]) + poly([P(-4, 16, 30), P(12, 16, 30), P(-1, 13.5, 39), P(-4, 13.5, 39)]), class: "nf lo" }, body);
  // roof scoop: the bright mark
  const scoop = box(-20, -5, -8, 5, 2, 0.7, 41, 44.5);
  scoop.sil.setAttribute("class", "sil hi");
  mk("path", { d: poly([P(-8, -3.5, 42), P(-8, 3.5, 42), P(-8, 3.5, 44), P(-8, -3.5, 44)]), class: "nf lo" }, body);
  box(34, -17, 44, 17, 3, 1, 11, 15);
  mk("path", { d: seg(P(42, -12, 23), P(42, -6, 23)) + seg(P(42, 6, 23), P(42, 12, 23)), class: "nf lo" }, body);
  WHEELS.filter((w) => w[1] > 0).forEach(wheelSet);
  const sp = spring(0);
  let last = NaN, over = false;
  const dz = P(0, 0, 1)[1] - P(0, 0, 0)[1];

  function draw() {
    const h = Math.max(0, sp.x);
    if (Math.abs(h - last) < 0.01) return;
    last = h;
    body.setAttribute("transform", "translate(0 " + (h * dz).toFixed(2) + ")");
    let d = "";
    for (const [u, v] of WHEELS) {
      const y = v * 0.75, z0 = WR, z1 = 15 + h, n = 7;
      const pts = [];
      for (let k = 0; k <= n * 2; k++) pts.push(P(u + (k % 2 ? 2.5 : -2.5), y, z0 + ((z1 - z0) * k) / (n * 2)));
      d += open(pts);
    }
    coils.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const bb = [[-44, -24, 0], [44, 24, 0], [44, -24, 0], [-44, 24, 0], [-46, -18, 44], [-20, 16, 44]].map((q) => P(...q));
  const xs = bb.map((q) => q[0]), ys = bb.map((q) => q[1]);
  const bx = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];

  function retarget() {
    sp.t = over ? 6 + (LIFT - 6) * reach : 0;
    read.textContent = over ? "jump " + Math.round(sp.t) : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { over = sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3]; retarget(); },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  draw();
  return { set: (v) => { reach = v; retarget(); }, destroy: bag.dispose };
}

