lighttower.code:
/**
 * Light tower: a generator trailer on two wheels with a telescoping mast and a
 * bar of four lamps on top. The pointer runs the mast up: the higher it rides
 * over the trailer, the further the two inner sections slide out, carrying the
 * lamp bar, and the lamps all light. At rest the mast is nearly stowed and one
 * lens is bright. The slider is how far the mast may extend.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, rrect, seg, spring, stepS, lerp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 34, MX = -20, SEC = 26, E0 = 0.1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let v = value, over = null, last = "";
  const C = Cam(45, 0.5, 1.84);
  const topAt = (e) => BZ + 30 + 2 * (2 + SEC * e);
  fit(C, [[-42, -30, 0], [64, 0, 0], [-42, 30, 0], [42, 20, 0], [MX, -32, topAt(1) + 18], [MX, 32, topAt(1) + 18]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const block = (s, x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); return s; };
  const disc = (x, y, z, r, n = 28) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return P(x + r * Math.cos(t), y, z + r * Math.sin(t)); });
  const wheel = (y, d) => {
    mk("path", { class: "sil", d: poly(hull(disc(0, y - d * 4, 10, 10).concat(disc(0, y + d * 4, 10, 10)))) }, g);
    mk("path", { class: "", d: poly(disc(0, y + 4, 10, 10)) }, g);
    mk("path", { class: "nf lo", d: poly(disc(0, y + 4, 10, 4.5)) }, g);
  };
  wheel(-21, 1);
  // drawbar and jack, then the generator body
  block(solid(g), 30, -3, 64, 3, 1.5, 0.6, 12, 16);
  block(solid(g), 56, -2.5, 61, 2.5, 1.5, 0.6, 0, 14);
  block(solid(g), -42, -17, 42, 17, 4, 1.6, 10, BZ);
  mk("path", { class: "nf lo", d: seg(P(-10, 17, 14), P(-10, 17, BZ - 4)) + seg(P(14, 17, 14), P(14, 17, BZ - 4)) }, g);
  wheel(21, -1);
  // mast: a fixed outer section, then two sliding ones
  block(solid(g), MX - 5, -5, MX + 5, 5, 1.8, 0.8, BZ, BZ + 30);
  const mid = solid(g), inner = solid(g);
  const bar = solid(g);
  const lamps = [-30, -15, 0, 15].map((y) => ({ y, s: solid(g), lens: mk("path", { class: "" }, g) }));
  const ext = spring(E0);

  function draw() {
    const key = ext.x.toFixed(3);
    if (key === last) return;
    last = key;
    const t1 = BZ + 30, t2 = t1 + 2 + SEC * ext.x, t3 = t2 + 2 + SEC * ext.x;
    block(mid, MX - 3.6, -3.6, MX + 3.6, 3.6, 1.4, 0.7, t1, t2);
    block(inner, MX - 2.4, -2.4, MX + 2.4, 2.4, 1, 0.5, t2, t3);
    block(bar, MX - 2.5, -32, MX + 2.5, 32, 1.2, 0.5, t3, t3 + 3);
    for (const l of lamps) {
      block(l.s, MX - 4, l.y + 0.6, MX + 4, l.y + 14.4, 2, 0.8, t3 + 3, t3 + 17);
      l.lens.setAttribute("d", poly(rrect(l.y + 2.4, t3 + 5, l.y + 12.6, t3 + 15, 2, 4).map((q) => P(MX + 4.05, q.u, q.v))));
    }
  }

  const B = register(stage, (dt) => { const m = stepS(ext, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    const on = over != null;
    ext.t = on ? v * lerp(0.5, 1, over) : E0;
    lamps.forEach((l, k) => l.lens.classList.toggle("hi", on || k === 1));
    read.textContent = on ? `mast ${Math.round(ext.t * 100)}%` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      over = p[0] < 40 || p[0] > 360 || p[1] < 4 || p[1] > 316 ? null : clamp((250 - p[1]) / 190, 0, 1);
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return { set: (nv) => { v = nv; retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "lighttower",
  means: "A mobile light tower: raise the pointer and the telescoping mast slides up, lifting the bar of lamps as they light.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[180, 210], [179, 125], [179, 60], null],
  mount,
});

windowrobot.code:
/**
 * Window robot: a square window-cleaning robot stuck to a pane of glass in
 * its frame, a round cleaning pad on its face. The pointer over the glass
 * draws the robot sliding across the pane toward it, on a spring, and it
 * stops at the frame. At rest it sits low in one corner, its pad bright.
 * The slider is its reach: how far toward the pointer it slides.
 *
 * The pattern: one part sliding on a plane (follow), hit on the fixed pane.
 */
const {
  Cam, clamp, fit, hull, poly, proj, rrect, lerp, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const GW = 100, GH = 76, F = 5, RS = 30, RD = 9, REST = [24, 22];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value / 100;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-F, 0, -F], [GW + F, 0, -F], [-F, 0, GH + F], [GW + F, 0, GH + F], [-F, 8, -F], [GW + F, 8, -F], [GW, RD + 2, 0], [0, RD + 2, GH]], 200, 166);
  const P = proj(C), g = mk("g", {}, svg);
  // a ring in the x–z plane, standing at depth y
  const face = (ring, x, z, y) => ring.map((q) => P(x + q.u, y, z + q.v));

  // the frame, the glass, the sill
  const outer = rrect(-F, -F, GW + F, GH + F, 6, 6), inner = rrect(0, 0, GW, GH, 2, 4);
  mk("path", { class: "sil", d: poly(hull(face(outer, 0, 0, -2).concat(face(outer, 0, 0, 2)))) }, g);
  mk("path", { class: "nf lo", d: poly(face(inner, 0, 0, 2)) + poly(face(rrect(1.5, 1.5, GW - 1.5, GH - 1.5, 1, 4), 0, 0, 0)) }, g);
  mk("path", { class: "sil", d: poly(hull(face(rrect(-F - 3, -F - 3, GW + F + 3, -F, 1.5, 4), 0, 0, -2).concat(face(rrect(-F - 3, -F - 3, GW + F + 3, -F, 1.5, 4), 0, 0, 8)))) }, g);
  const wipe = mk("path", { class: "nf dash" }, g);

  // the robot: a rounded square body, its face, its pad, a tether eye on top
  const body = mk("path", { class: "sil" }, g), cr = mk("path", { class: "nf lo" }, g);
  const pad = mk("path", { class: "nf" }, g), eye = mk("path", { class: "nf lo" }, g);
  const sq = rrect(-RS / 2, -RS / 2, RS / 2, RS / 2, 8, 8), sqi = rrect(-RS / 2 + 2, -RS / 2 + 2, RS / 2 - 2, RS / 2 - 2, 6, 8);
  const ring = (r, n) => Array.from({ length: n }, (_, i) => { const t = (i / n) * Math.PI * 2; return { u: r * Math.cos(t), v: r * Math.sin(t) }; });
  const padR = ring(8, 24), eyeR = ring(2, 10);

  const sx = spring(REST[0]), sz = spring(REST[1]);
  let last = "";
  function draw(x, z) {
    const key = x.toFixed(2) + "," + z.toFixed(2);
    if (key === last) return;
    last = key;
    body.setAttribute("d", poly(hull(face(sq, x, z, 1).concat(face(sq, x, z, RD)))));
    cr.setAttribute("d", poly(face(sqi, x, z, RD)));
    pad.setAttribute("d", poly(face(padR, x, z, RD + 0.4)));
    eye.setAttribute("d", poly(face(eyeR, x, z + RS / 2 - 4, RD + 0.4)));
    wipe.setAttribute("d", poly([P(REST[0], 0.5, REST[1]), P(x, 0.5, z), P(x, 0.5, z)]));
  }

  const B = register(stage, (dt) => {
    const m = stepS(sx, dt) | stepS(sz, dt);
    draw(sx.x, sz.x);
    return !!m;
  });
  bag.add(B.unregister);

  // the hit: the pointer on the glass plane, which never moves
  const o = P(0, 0, 0), ex = P(1, 0, 0), ez = P(0, 0, 1);
  const ax = [ex[0] - o[0], ex[1] - o[1]], az = [ez[0] - o[0], ez[1] - o[1]], det = ax[0] * az[1] - ax[1] * az[0];
  function onGlass([px, py]) {
    const dx = px - o[0], dy = py - o[1];
    const x = (dx * az[1] - dy * az[0]) / det, z = (ax[0] * dy - ax[1] * dx) / det;
    return x < -F || x > GW + F || z < -F || z > GH + F ? null : [x, z];
  }

  let tgt = null;
  function aim(p) {
    tgt = p;
    const lo = RS / 2 + 1;
    const x = p ? clamp(lerp(REST[0], p[0], reach), lo, GW - lo) : REST[0];
    const z = p ? clamp(lerp(REST[1], p[1], reach), lo, GH - lo) : REST[1];
    sx.t = x; sz.t = z;
    body.classList.toggle("hi", !!p);
    pad.classList.toggle("hi", !p);
    read.textContent = p ? Math.round(x) + "·" + Math.round(z) : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(onGlass(p)), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v / 100; aim(tgt); }, destroy: bag.dispose };
}

hairline({
  name: "windowrobot",
  means: "A window-cleaning robot on a pane of glass: it slides across the glass toward the pointer and stops at the frame.",
  rules: [1, 3, 4, 5],
  range: [30, 70, 100],
  tour: [[255, 143], [280, 240], [165, 175], null],
  mount,
});

poolrobot.code:
/**
 * Pool robot: a boxy pool cleaner on two rubber tracks, a brush roller
 * across its nose, and a filter lid hinged along its far side. The pointer
 * over the robot swings the lid up and over on that hinge to show the
 * filter basket, wider the nearer the pointer is to the open side. At rest
 * the lid is shut and the brush roller is bright. The slider is how far the
 * lid swings.
 *
 * The pattern: one part on a hinge (lid), hit on a fixed plane.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rad, rings, rrect, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 56, W = 40, HZ = 16, HY = 0, LH = 9, TR = 8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 2.9);
  const rot = (x, y, z, a) => {
    const dy = y - HY, dz = z - HZ, c = Math.cos(a), s = Math.sin(a);
    return [x, HY + dy * c - dz * s, HZ + dy * s + dz * c];
  };
  const far = [[0, W, HZ], [L, W, HZ], [L, W, HZ + LH]].map((p) => rot(p[0], p[1], p[2], rad(110)));
  fit(C, [[-2, -7, 0], [L + 9, W + 7, 0], [L + 9, -7, 0], [-2, W + 7, 0], [0, 0, HZ + LH], ...far], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // a track: a stadium loop standing in the x–z plane, with its cleats
  function track(y0, y1) {
    const a = [], b = [];
    for (let i = 0; i <= 32; i++) {
      const t = (i / 32) * Math.PI * 2, cx = Math.cos(t) >= 0 ? L - 2 - TR : 2 + TR;
      a.push(P(cx + TR * Math.cos(t), y0, TR + TR * Math.sin(t))); b.push(P(cx + TR * Math.cos(t), y1, TR + TR * Math.sin(t)));
    }
    mk("path", { class: "sil", d: poly(hull(a.concat(b))) }, g);
    let cl = "";
    for (const x of [2 + TR, L - 2 - TR]) {
      const hub = [];
      for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; hub.push(P(x + 4 * Math.cos(t), y1, TR + 4 * Math.sin(t))); }
      cl += poly(hub);
    }
    mk("path", { class: "nf lo", d: poly(b) + cl }, g);
  }
  track(-7, -1);

  // the body and the filter basket under the lid
  const [br, bi] = rings(0, 0, L, W, 9, 1.6);
  put(solid(g), prism(P, front, br, bi, 3, HZ));
  mk("path", { class: "nf lo", d: poly(rrect(8, 6, L - 8, W - 6, 6, 6).map((q) => P(q.u, q.v, HZ))) + poly(rrect(12, 10, L - 12, W - 10, 4, 6).map((q) => P(q.u, q.v, HZ))) }, g);

  // the brush roller across the nose
  const roll = [];
  for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; roll.push(P(L + 3 + 5 * Math.cos(t), 1, 5 + 5 * Math.sin(t)), P(L + 3 + 5 * Math.cos(t), W - 1, 5 + 5 * Math.sin(t))); }
  const brush = mk("path", { class: "sil", d: poly(hull(roll)) }, g);
  let ribs = "";
  for (let k = 1; k < 6; k++) { const y = (W * k) / 6; ribs += poly([P(L + 8, y - 1.5, 5), P(L + 3, y + 1.5, 10)]); }
  mk("path", { class: "nf lo", d: ribs }, g);

  // the lid, hinged along the far side
  const shell = mk("path", { class: "sil" }, g), top = mk("path", { class: "nf lo" }, g);
  const foot = rrect(0, 0, L, W, 9, 8), crown = rrect(5, 5, L - 5, W - 5, 6, 8), inner = rrect(7, 7, L - 7, W - 7, 4, 8);
  track(W + 1, W + 7);

  const ang = tween(0);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), R = (ring, z) => ring.map((q) => P(...rot(q.u, q.v, z, a)));
    shell.setAttribute("d", poly(hull(R(foot, HZ).concat(R(crown, HZ + LH)))));
    top.setAttribute("d", poly(R(inner, HZ + LH)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  // the hit: the pointer on the lid's resting plane, which band across the robot
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, HZ);
    if (x < -4 || x > L + 10 || y < -8 || y > W + 8) return -1;
    return clamp(Math.round((y / W) * 3), 0, 3);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const deg = a < 0 ? 0 : Math.round(maxA * (0.55 + 0.15 * a));
    tset(ang, deg, performance.now(), 0);
    shell.classList.toggle("hi", a >= 0);
    brush.classList.toggle("hi", a < 0);
    read.textContent = a < 0 ? "rest" : "lid " + deg + "°";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "poolrobot",
  means: "A pool cleaning robot on tracks: its filter lid swings up on the far hinge, wider the nearer the pointer is to the open side.",
  rules: [1, 3, 4, 5],
  range: [40, 80, 110],
  tour: [[219, 180], [190, 196], [150, 214], null],
  mount,
});

robotmower.code:
/**
 * Robot lawnmower: a low chassis on two big rear wheels and two small front
 * casters, under a domed shell hinged at the back, a round stop button on
 * its top. The pointer over the mower lifts the shell open on its rear hinge
 * to show the cutting deck and blade disc; the nearer the pointer is to the
 * front, the wider it opens. At rest the shell sits just ajar, the stop
 * button bright. The slider is how far the shell opens.
 *
 * The pattern: one part on a hinge (lid), hit on the ground plane.
 */
const {
  Cam, clamp, circ, facing, fit, hull, poly, prism, proj, rad, rings, rrect, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 64, W = 44, HZ = 9, HX = 2, LH = 15, REST = 6;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 3.05);
  const rot = (x, y, z, a) => {
    const dx = x - HX, dz = z - HZ, c = Math.cos(a), s = Math.sin(a);
    return [HX + dx * c - dz * s, y, HZ + dx * s + dz * c];
  };
  const far = [[L, 0, 0], [L, W, 0], [L - 8, W / 2, LH]].map((p) => rot(p[0], p[1], p[2] + HZ, rad(70)));
  fit(C, [[-4, -6, 0], [L + 2, W + 6, 0], [L + 2, -6, 0], [-4, W + 6, 0], [-6, W / 2, LH + HZ], ...far], 200, 172);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // a wheel: a disc standing in the x–z plane, with a hub
  function wheel(par, x, y0, y1, r, cz) {
    const a = [], b = [];
    for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; a.push(P(x + r * Math.cos(t), y0, cz + r * Math.sin(t))); b.push(P(x + r * Math.cos(t), y1, cz + r * Math.sin(t))); }
    const hub = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; hub.push(P(x + r * 0.4 * Math.cos(t), y1, cz + r * 0.4 * Math.sin(t))); }
    mk("path", { class: "sil", d: poly(hull(a.concat(b))) }, par);
    mk("path", { class: "nf lo", d: poly(b) + poly(hub) }, par);
  }
  wheel(g, 14, -7, -1, 10, 10);
  wheel(g, L - 10, 1, 4, 4.5, 4.5);

  // the chassis and its cutting deck
  const [cr0, ci0] = rings(2, 0, L - 2, W, 12, 1.6);
  put(solid(g), prism(P, front, cr0, ci0, 2, HZ));
  mk("path", { class: "nf lo", d: poly(disc(L / 2 + 4, W / 2, 15, 32).map((q) => P(q.u, q.v, HZ))) + poly(disc(L / 2 + 4, W / 2, 4, 16).map((q) => P(q.u, q.v, HZ))) }, g);
  const blade = [[-13, -2], [13, -2], [13, 2], [-13, 2]];
  mk("path", { class: "nf", d: poly(blade.map(([u, v]) => P(L / 2 + 4 + (u - v) * 0.7, W / 2 + (u + v) * 0.7, HZ + 0.6))) }, g);

  // the shell: a rounded dome on a hinge at the back, and the stop button on its top
  const lid = mk("g", {}, g);
  const shell = mk("path", { class: "sil" }, lid), top = mk("path", { class: "nf lo" }, lid);
  const btn = mk("path", { class: "sil" }, lid), btnTop = mk("path", { class: "nf lo" }, lid);
  const foot = rrect(0, -2, L, W + 2, 16, 8), crown = rrect(10, 5, L - 6, W - 5, 12, 8), inner = rrect(12, 7, L - 8, W - 7, 10, 8);
  const bt = disc(22, W / 2, 5, 20), bti = disc(22, W / 2, 3.6, 20);
  wheel(g, 14, W + 1, W + 7, 10, 10);
  wheel(g, L - 10, W - 4, W - 1, 4.5, 4.5);

  const ang = tween(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), R = (ring, z) => ring.map((q) => P(...rot(q.u, q.v, z, a)));
    shell.setAttribute("d", poly(hull(R(foot, HZ).concat(R(crown, HZ + LH)))));
    top.setAttribute("d", poly(R(inner, HZ + LH)));
    btn.setAttribute("d", poly(hull(R(bt, HZ + LH - 0.5).concat(R(bt, HZ + LH + 3.5)))));
    btnTop.setAttribute("d", poly(R(bti, HZ + LH + 3.5)));
  }

  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  // the hit: the pointer on the ground plane, over the mower's footprint
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, HZ);
    if (x < -4 || x > L + 6 || y < -8 || y > W + 8) return -1;
    return clamp(Math.round((x / L) * 3), 0, 3);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(ang, a < 0 ? REST : maxA * (0.55 + 0.15 * a), performance.now(), 0);
    shell.classList.toggle("hi", a >= 0);
    btn.classList.toggle("hi", a < 0);
    read.textContent = a < 0 ? "rest" : "lid " + Math.round(maxA * (0.55 + 0.15 * a)) + "°";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxA = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "robotmower",
  means: "A robot lawnmower: its shell lifts open on the rear hinge to show the blade, wider the nearer the pointer is to the front.",
  rules: [1, 3, 4, 5],
  range: [25, 50, 70],
  tour: [[168, 160], [208, 182], [252, 206], null],
  mount,
});

robotdog.code:
/**
 * Robot dog: a quadruped on four jointed legs, a long body, a blocky head on
 * a pivot and a short antenna tail. The pointer is a hand held out: the dog
 * lifts its head and raises its near front paw to shake it, tail up. At rest
 * it sniffs the ground, head low, the beacon on its back the bright mark.
 * The slider is how high the paw and head come up.
 *
 * The pattern: one answer on a spring; the hit is the rest pose's screen box.
 */
const {
  Cam, circ, facing, fit, hull, open, poly, proj, rings, run, seg, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, register, solid,
} = HL;

const disc = (x, y, r) => circ(r, 14).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const LEGS = [[-13, -6], [13, -6], [-13, 6], [13, 6]];
const HIP = 19, KNEE = 9;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 4.4);
  fit(C, [[-26, -9, 0], [34, 9, 0], [-26, 9, 0], [34, -9, 0], [-26, 0, 38], [34, 0, 44], [36, 6, 22]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const leg = () => { const grp = mk("g", {}, g); return { grp, a: mk("path", { class: "sil" }, grp), b: mk("path", { class: "sil" }, grp), knee: flatDot(grp, C, 1.2, "dot off") }; };
  const legs = LEGS.map(([x, y]) => ({ x, y, ...leg() }));
  const BODY = rings(-18, -8, 18, 8, 4, 1.4), HEAD = rings(14, -6.5, 30, 6.5, 3.2, 1.3);
  const body = solid(g);
  const tail = mk("path", { class: "nf sil" }, g), tip = flatDot(g, C, 1.3, "dot off");
  const beacon = flatDot(g, C, 1.8, "dot");
  const head = solid(g), eye = mk("path", { class: "nf lo" }, g), ear = mk("path", { class: "nf sil" }, g);
  // the near legs go in front of the body's lower edge, the far ones behind it
  g.prepend(legs[0].grp, legs[1].grp);
  g.insertBefore(legs[2].grp, body.g); g.insertBefore(legs[3].grp, head.g);

  // a solid from a ring and its crease ring, both carried through T
  const box = (ring, inner, z0, z1, T) => {
    const pts = [];
    for (const z of [z0, z1]) for (const q of ring) pts.push(P(...T(q.u, q.v, z)));
    return { sil: poly(hull(pts)), cr: open(run(inner, front).map((q) => P(...T(q.u, q.v, z1)))) };
  };
  const bar = (a, b, r) => {
    const pts = [];
    for (const [x, y, z] of [a, b]) for (const q of disc(x, y, r)) pts.push(P(q.u, q.v, z));
    return poly(hull(pts));
  };
  const S = (s, d) => { s.sil.setAttribute("d", d.sil); s.cr.setAttribute("d", d.cr); };
  S(body, box(BODY[0], BODY[1], 17, 25, (x, y, z) => [x, y, z]));
  place(beacon, P(-6, 0, 25));

  const sp = spring(0);
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    // the near front paw swings forward and up about its hip
    for (const L of legs) {
      const lift = L === legs[3] ? t * 1.5 : 0, bend = L === legs[3] ? t * 0.3 : 0;
      const hip = [L.x, L.y, L === legs[3] ? 18 : HIP];
      const kn = [L.x + 2 + Math.sin(lift) * (HIP - KNEE), L.y, HIP - Math.cos(lift) * (HIP - KNEE)];
      const la = lift - 0.25 - bend;
      const ft = [kn[0] + Math.sin(la) * KNEE, L.y, Math.max(0.8, kn[2] - Math.cos(la) * KNEE)];
      L.a.setAttribute("d", bar(hip, kn, 2.1));
      L.b.setAttribute("d", bar(kn, ft, 1.7));
      place(L.knee, P(...kn));
    }
    // the head pitches about its neck: low at rest, raised as it answers
    const ph = -0.22 + t * 0.75, c = Math.cos(ph), s = Math.sin(ph);
    const T = (x, y, z) => { const dx = x - 15, dz = z - 25; return [15 + dx * c - dz * s, y, 25 + dx * s + dz * c]; };
    S(head, box(HEAD[0], HEAD[1], 21, 31, T));
    eye.setAttribute("d", seg(P(...T(30, -4, 27.5)), P(...T(30, 4, 27.5))));
    ear.setAttribute("d", seg(P(...T(17, -3, 31)), P(...T(14, -3, 36))) + seg(P(...T(17, 3, 31)), P(...T(14, 3, 36))));
    const ta = 0.6 + t * 0.7, te = [-18 - Math.cos(ta) * 10, 0, 23 + Math.sin(ta) * 10];
    tail.setAttribute("d", seg(P(-18, 0, 23), P(...te)));
    place(tip, P(...te));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const box0 = [P(-26, 0, 20)[0], P(34, 0, 20)[0], P(0, 0, 40)[1] - 20, P(0, 0, 0)[1] + 30];
  let on = false;
  function setOn(v) {
    on = v;
    sp.t = on ? clamp(amp, 0, 1) : 0;
    head.sil.classList.toggle("hi", on);
    legs[3].a.classList.toggle("hi", on); legs[3].b.classList.toggle("hi", on);
    beacon.setAttribute("class", on ? "dot off" : "dot");
    read.textContent = on ? "paw" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setOn(sx > box0[0] - 10 && sx < box0[1] + 10 && sy > box0[2] && sy < box0[3]),
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  setOn(false);
  return {
    set: (v) => { amp = v; if (on) { sp.t = clamp(amp, 0, 1); B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "robotdog",
  means: "A robot dog on four jointed legs: offered the pointer it lifts its head and raises a front paw to shake; at rest it sniffs the ground.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[256, 149], [275, 139], [180, 150], null],
  mount,
});

telepresence.code:
/**
 * Telepresence robot: a round rolling base, a telescoping mast, and a tablet
 * screen with a camera on its bezel. The pointer is someone stepping up: the
 * mast extends to bring the screen to eye height and the screen tips forward
 * to face them. At rest the mast is low and the screen leans back, the power
 * light on the base the bright mark. The slider is how far the mast extends.
 *
 * The pattern: one answer on a spring; the hit is the rest pose's screen box.
 */
const {
  Cam, circ, facing, fit, hull, open, poly, proj, prism, rrect, run, spring, stepS, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const disc = (r, n = 28) => circ(r, n);
const SQ = Math.SQRT1_2, MAST = 30, REACH = 20;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 3.85);
  fit(C, [[-18, -18, 0], [18, 18, 0], [18, -18, 0], [-18, 18, 0], [16, -16, MAST + 8 + REACH + 13], [-16, 16, MAST + 8 + REACH + 13]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(17), disc(15.4), 0, 7));
  put(solid(g), prism(P, front, disc(9), disc(7.8), 7, 10));
  const power = flatDot(g, C, 1.7, "dot");
  place(power, P(17 * SQ, 17 * SQ, 4));
  put(solid(g), prism(P, front, disc(3.2, 16), null, 10, MAST));
  const upper = solid(g);
  const screen = mk("path", { class: "sil" }, g), glass = mk("path", { class: "nf lo" }, g);
  const cam = flatDot(g, C, 1.3, "dot off");
  const PLATE = rrect(-20, -1.6, 20, 1.6, 1.5, 4), GLASS = rrect(-17.5, -10, 17.5, 10, 1.6, 4);

  const sp = spring(0);
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const lift = 3 + t * REACH, zs = MAST + 8 + lift, th = 0.32 - t * 0.42;
    const c = Math.cos(th), s = Math.sin(th);
    // u across the screen, w through it toward the viewer, h up it; th tips the top back
    const W = (u, w, h) => {
      const w2 = w * c - h * s, h2 = h * c + w * s;
      return P((u + w2) * SQ, (-u + w2) * SQ, zs + h2);
    };
    put(upper, prism(P, front, disc(2.3, 16), null, MAST - 6, zs));
    const pts = [];
    for (const h of [-13, 13]) for (const q of PLATE) pts.push(W(q.u, q.v, h));
    screen.setAttribute("d", poly(hull(pts)));
    glass.setAttribute("d", poly(GLASS.map((q) => W(q.u, 1.7, q.v))));
    place(cam, W(0, 1.7, 11.6));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const xs = [P(-18, 18, 0)[0], P(18, -18, 0)[0]], ys = [P(0, 0, MAST + 30)[1] - 20, P(18, 18, 0)[1] + 10];
  let on = false;
  function setOn(v) {
    on = v;
    sp.t = on ? clamp(amp, 0, 1) : 0;
    screen.classList.toggle("hi", on);
    power.setAttribute("class", on ? "dot off" : "dot");
    cam.setAttribute("class", on ? "dot m" : "dot off");
    read.textContent = on ? "call" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setOn(sx > xs[0] - 10 && sx < xs[1] + 10 && sy > ys[0] && sy < ys[1]),
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  setOn(false);
  return {
    set: (v) => { amp = v; if (on) { sp.t = clamp(amp, 0, 1); B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "telepresence",
  means: "A telepresence robot on a rolling base: at the pointer its mast extends and the screen tips forward to face you.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[200, 110], [200, 240], [150, 170], null],
  mount,
});

deliverybot.code:
/**
 * Delivery robot: a six-wheeled sidewalk cooler with a deep lid hinged at the
 * back and a tall whip flag on its rear. The pointer is the customer: the lid
 * swings up and back on its hinge to show the empty cargo well. At rest the
 * lid sits just ajar and the pennant on the flag is the bright mark.
 * The slider is how far the lid opens.
 *
 * The pattern: one answer on a spring; the hit is the rest pose's screen box.
 */
const {
  Cam, facing, fit, hull, open, poly, proj, prism, rings, run, spring, stepS, clamp,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = -18, X1 = 18, Y = 12, ZB = 5, ZT = 20, ZL = 28;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 3.7);
  fit(C, [[X0 - 2, -Y - 2, 0], [X1 + 2, Y + 2, 0], [X1 + 2, -Y - 2, 0], [X0 - 2, Y + 2, 0], [X0 - 8, -Y, ZT + 38], [X0 - 1, -8, 62]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => {
    const pts = [];
    for (const yy of [y - 1.4, y + 1.4]) for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2; pts.push(P(x + 5 * Math.cos(a), yy, 5 + 5 * Math.sin(a))); }
    const hub = [];
    for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2; hub.push(P(x + 1.8 * Math.cos(a), y + (y > 0 ? 1.5 : -1.5), 5 + 1.8 * Math.sin(a))); }
    return [poly(hull(pts)), poly(hub)];
  };
  // the flag whip, farthest, then far wheels, body, near wheels, lid
  mk("path", { d: poly(hull([P(X0 - 1, -8, 12), P(X0 - 0.4, -8, 12), P(X0 - 0.4, -8, 62), P(X0 - 1, -8, 62)])), class: "sil" }, g);
  const flag = mk("path", { d: poly([P(X0 - 0.7, -8, 61), P(X0 - 0.7, -8 - 11, 57.5), P(X0 - 0.7, -8, 54)]), class: "nf sil" }, g);
  for (const x of [X0 + 6, 0, X1 - 6]) { const [w] = wheel(x, -Y - 1.6); mk("path", { d: w, class: "sil" }, g); }
  const [br, bi] = rings(X0, -Y, X1, Y, 5, 1.6);
  put(solid(g), prism(P, front, br, bi, ZB, ZT));
  const [wr] = rings(X0 + 2.5, -Y + 2.5, X1 - 2.5, Y - 2.5, 3, 1);
  mk("path", { d: poly(wr.map((q) => P(q.u, q.v, ZT))), class: "nf lo" }, g);
  for (const x of [X0 + 6, 0, X1 - 6]) { const [w, h] = wheel(x, Y + 1.6); mk("path", { d: w, class: "sil" }, g); mk("path", { d: h, class: "nf lo" }, g); }
  const lid = solid(g);
  const [lr, li] = rings(X0, -Y, X1, Y, 5, 1.6);

  const sp = spring(0);
  let drawn = NaN;
  function draw() {
    const t = sp.x;
    if (Math.abs(t - drawn) < 1e-4) return;
    drawn = t;
    const ph = 0.1 + t * 1.75, c = Math.cos(ph), s = Math.sin(ph);
    const T = (x, y, z) => { const dx = x - X0, dz = z - ZT; return P(X0 + dx * c - dz * s, y, ZT + dx * s + dz * c); };
    const pts = [];
    for (const z of [ZT, ZL]) for (const q of lr) pts.push(T(q.u, q.v, z));
    lid.sil.setAttribute("d", poly(hull(pts)));
    lid.cr.setAttribute("d", open(run(li, front).map((q) => T(q.u, q.v, ZL))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);

  const xs = [P(X0, Y, 0)[0], P(X1, -Y, 0)[0]], ys = [P(X0, -Y, ZL + 10)[1], P(X1, Y, 0)[1] + 10];
  let on = false;
  function setOn(v) {
    on = v;
    sp.t = on ? clamp(amp, 0, 1) : 0;
    lid.sil.classList.toggle("hi", on);
    flag.classList.toggle("hi", !on);
    read.textContent = on ? "open" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: ([sx, sy]) => setOn(sx > xs[0] - 10 && sx < xs[1] + 10 && sy > ys[0] && sy < ys[1]),
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  setOn(false);
  return {
    set: (v) => { amp = v; if (on) { sp.t = clamp(amp, 0, 1); B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "deliverybot",
  means: "A six-wheeled sidewalk delivery robot with a whip flag: at the pointer its deep lid swings up on its hinge to show the cargo well.",
  rules: [1, 3, 5, 6],
  range: [0.3, 1, 1],
  tour: [[213, 180], [150, 230], [260, 205], null],
  mount,
});

babyincubator.code:
/**
 * Baby incubator: a cabinet on a pillar stand, a mattress and pillow on its
 * tray and a clear hood over them with two round hand ports on its front.
 * The pointer opens the hood: it tips up and back on its rear hinge to show
 * the bed. At rest it sits a little open, bright. The slider is how far the
 * hood opens.
 *
 * The pattern: one hinged part swinging open (lid).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid, rad,
} = HL;

const box = (x0, y0, x1, y1, r = 2) => rrect(x0, y0, x1, y1, r);
function XF(it, x, y, z, t) {
  const a = rad(it.ang * t), dy = y - it.hy, dz = z - it.hz;
  return [x, it.hy + dy * Math.cos(a) - dz * Math.sin(a), it.hz + dy * Math.sin(a) + dz * Math.cos(a)];
}
const port = (cx, cz, r) => { const o = []; for (let i = 0; i <= 16; i++) { const a = (i / 16) * Math.PI * 2; o.push([cx + r * Math.cos(a), 44 - (cz + r * Math.sin(a) - 56) * 0.18, cz + r * Math.sin(a)]); } return o; };
const ITEMS = [
  { ring: box(6, 6, 70, 42, 6), inner: box(8, 8, 68, 40, 5), z0: 0, z1: 6 },
  { ring: box(32, 18, 44, 30, 4), inner: box(33.5, 19.5, 42.5, 28.5, 3), z0: 6, z1: 40 },
  { ring: box(0, 0, 76, 48, 5), inner: box(2, 2, 74, 46, 4), z0: 40, z1: 56 },
  { ring: box(6, 6, 70, 42, 4), inner: box(8, 8, 68, 40, 3), z0: 56, z1: 60 },
  { ring: box(10, 12, 24, 36, 5), inner: box(12, 14, 22, 34, 4), z0: 60, z1: 64 },
  { mov: 1, hi: 1, ring: box(2, 2, 74, 44, 9), top: box(10, 8, 66, 38, 9), z0: 56, z1: 90, hy: 2, hz: 56, ang: 62,
    face: [port(24, 73, 7), port(52, 73, 7), [[12, 39, 84], [64, 39, 84]]] },
];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value / 100;
  const C = Cam(45, 0.5, 2.0);
  const ext = [];
  for (const it of ITEMS) for (const t of [0, 1]) for (const z of [it.z0, it.z1]) for (const q of it.ring) ext.push(it.mov ? XF(it, q.u, q.v, z, t) : [q.u, q.v, z]);
  fit(C, ext, 200, 165);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const it of ITEMS) {
    if (!it.mov) { put(solid(g), prism(P, front, it.ring, it.inner, it.z0, it.z1)); continue; }
    const grp = mk("g", {}, g);
    it.sil = mk("path", { class: "sil" }, grp);
    it.dt = mk("path", { class: "nf lo" }, grp);
  }
  const MOVS = ITEMS.filter((it) => it.mov);
  const tw = tween(0.2);
  function draw(t) {
    for (const it of MOVS) {
      const pts = it.ring.map((q) => P(...XF(it, q.u, q.v, it.z0, t))).concat((it.top || it.ring).map((q) => P(...XF(it, q.u, q.v, it.z1, t))));
      it.sil.setAttribute("d", poly(hull(pts)));
      it.dt.setAttribute("d", it.face.map((f) => open(f.map((w) => P(...XF(it, w[0], w[1], w[2], t))))).join(" "));
    }
  }
  let last = NaN;
  const B = register(stage, (_dt, now) => {
    const v = tval(tw, now);
    if (v !== last) { last = v; draw(v); }
    return !tdone(tw, now);
  });
  bag.add(B.unregister);

  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const it of ITEMS) for (const z of [it.z0, it.z1]) for (const q of it.ring) {
    const [sx, sy] = P(q.u, q.v, z); x0 = Math.min(x0, sx); x1 = Math.max(x1, sx); y0 = Math.min(y0, sy); y1 = Math.max(y1, sy);
  }
  const hit = ([sx, sy]) => (sx < x0 - 6 || sx > x1 + 6 || sy < y0 - 6 || sy > y1 + 6 ? -1 : 0);
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(tw, a < 0 ? 0.2 : amp, performance.now(), 0);
    MOVS.forEach((it) => it.sil.classList.toggle("hi", !!it.hi));
    read.textContent = a < 0 ? "rest" : "hood " + Math.round(62 * amp) + "°";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v / 100; if (act >= 0) setActive(act, true); }, destroy: bag.dispose };
}

