  name: "examcouch",
  means: "An examination couch on four legs: the pointer's place along the couch raises the backrest on its hinge.",
  rules: [1, 3, 5, 8],
  range: [20, 100, 100],
  tour: [[109, 135], [153, 133], [220, 167], null],
  mount,
