surgicallamp.code:
/**
 * Surgical lamp: a ceiling canopy, a short pole, a long arm and a wide dome
 * head on a drop with a sterile handle under it. The pointer's place on the
 * floor swings the arm round its pole so the head hangs over that side. At
 * rest the arm reaches to the near left and the dome's rim is bright. The
 * slider is how far round the arm will swing.
 */
const { Cam, circ, clamp, fit, hull, poly, proj, rrect, spring, stepS, unproj, disposer, mk, pointer, register, solid } = HL;

const ARM = 50, TOP = 108, ZA = 92, ZH = 54, RH = 22, REST = 120;
const D = Math.PI / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  const ext = [];
  for (let a = 0; a < 360; a += 30) ext.push([(ARM + RH) * Math.cos(a * D), (ARM + RH) * Math.sin(a * D), ZH - 6], [(ARM + RH) * Math.cos(a * D), (ARM + RH) * Math.sin(a * D), ZA + 4]);
  ext.push([0, 0, TOP + 4]);
  fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const ring = (r, cx, cy, z, n = 40) => circ(r, n).map((q) => P(cx + q.u, cy + q.v, z));
  const cyl = (s, cx, cy, r0, z0, r1, z1, cr) => {
    s.sil.setAttribute("d", poly(hull(ring(r0, cx, cy, z0).concat(ring(r1, cx, cy, z1)))));
    if (cr) s.cr.setAttribute("d", poly(ring(r1 - cr, cx, cy, z1)));
  };
  // static: canopy and pole
  const pole = mk("g", {}, g);
  cyl(solid(pole), 0, 0, 3, ZA, 3, TOP - 2, 1);
  cyl(solid(pole), 0, 0, 12, TOP - 2, 9, TOP + 4, 1.5);
  // moving: head (with handle), drop, arm
  const mv = mk("g", {}, g);
  const handle = solid(mv), head = solid(mv), drop = solid(mv), arm = solid(mv);
  head.sil.classList.add("hi");
  const aO = rrect(-4, -3, ARM + 4, 3, 3, 4), aI = rrect(-2.8, -1.8, ARM + 2.8, 1.8, 1.8, 4);
  const rot = (rg, a, z) => rg.map((q) => P(q.u * Math.cos(a) - q.v * Math.sin(a), q.u * Math.sin(a) + q.v * Math.cos(a), z));

  const ang = spring(REST);
  let last = NaN, behind = null;
  function draw() {
    const a = Math.round(ang.x * 10) / 10;
    if (a === last) return;
    last = a;
    const r = a * D, hx = ARM * Math.cos(r), hy = ARM * Math.sin(r);
    arm.sil.setAttribute("d", poly(hull(rot(aO, r, ZA - 4).concat(rot(aO, r, ZA)))));
    arm.cr.setAttribute("d", poly(rot(aI, r, ZA)));
    cyl(drop, hx, hy, 2.2, ZH + 12, 2.2, ZA - 2, 0);
    cyl(head, hx, hy, RH, ZH, 10, ZH + 13, 2);
    cyl(handle, hx, hy, 3, ZH - 7, 3, ZH, 0);
    const b = hx + hy < 0;
    if (b !== behind) { behind = b; if (b) g.insertBefore(mv, pole); else g.appendChild(mv); }
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  let goal = null;
  function retarget() {
    if (goal === null) { ang.t = REST; read.textContent = "rest"; }
    else {
      let d = goal - REST; d = ((d + 540) % 360) - 180;
      ang.t = REST + d * reach;
      read.textContent = Math.round(((ang.t % 360) + 360) % 360) + "°";
    }
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZH), r = Math.hypot(x, y);
      goal = r > 120 || r < 4 ? null : Math.atan2(y, x) / D;
      retarget();
    },
    leave: () => { goal = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  draw();
  retarget();
  return { set: (v) => { reach = clamp(v, 0, 1); retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "surgicallamp",
  means: "A ceiling surgical lamp: its long arm swings round the pole so the wide dome head hangs over the pointer's side.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[315, 227], [209, 139], [130, 230], null],
  mount,
});

operatingtable.code:
/**
 * Operating table: a long padded top on a single column over a wide base.
 * The pointer's place along the table tilts the top on its pivot, the end
 * under the pointer dipping down. At rest the top lies with a slight head-up
 * tilt and its outline is bright. The slider is how far the top will tilt.
 */
const { Cam, clamp, fit, facing, hull, lerp, poly, prism, proj, rad, rings, rrect, spring, stepS, unproj, disposer, mk, pointer, put, register, solid } = HL;

const L = 50, W = 14, T = 5, ZP = 40, REST = 6, MAX = 24;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.6);
  const s = Math.sin(rad(MAX)) * L;
  fit(C, [[-L, -W, ZP + s + T], [L, W, ZP + s + T], [-L, W, ZP - s], [L, -W, ZP - s], [-24, 16, 0], [24, -16, 0]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-26, -16, 26, 16, 7, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const [cr, ci] = rings(-7, -7, 7, 7, 4, 1.2);
  put(solid(g), prism(P, front, cr, ci, 4, ZP - 3));
  const [hr, hi] = rings(-10, -8, 10, 8, 3, 1.2);
  put(solid(g), prism(P, front, hr, hi, ZP - 4, ZP));
  const top = solid(g);
  top.sil.classList.add("hi");
  const pad = mk("path", { class: "lo nf" }, g);
  const tO = rrect(-L, -W, L, W, 5, 4), tI = rrect(-L + 2, -W + 2, L - 2, W - 2, 3.4, 4);
  const at = (ring, a, t) => ring.map((q) => P(q.u * Math.cos(a) - t * Math.sin(a), q.v, ZP + q.u * Math.sin(a) + t * Math.cos(a)));

  const ang = spring(REST);
  let last = NaN;
  function draw() {
    const a = Math.round(ang.x * 10) / 10;
    if (a === last) return;
    last = a;
    const r = rad(a);
    top.sil.setAttribute("d", poly(hull(at(tO, r, 0).concat(at(tO, r, T)))));
    top.cr.setAttribute("d", poly(at(tI, r, T)));
    // the joint between head section and body: one dim line across the pad
    pad.setAttribute("d", poly([at([{ u: -L + 22, v: -W + 2 }], r, T)[0], at([{ u: -L + 22, v: W - 2 }], r, T)[0]]));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  const sx0 = P(-L, 0, ZP)[0], sx1 = P(L, 0, ZP)[0];
  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, ZP);
    if (wx < -L - 20 || wx > L + 20 || wy < -W - 30 || wy > W + 30) return leave();
    const t = clamp((sx - sx0) / (sx1 - sx0), 0, 1);
    ang.t = lerp(-MAX, MAX, t) * reach;
    read.textContent = Math.round(ang.t) + "°";
    B.wake();
  }
  function leave() { ang.t = REST; read.textContent = "rest"; B.wake(); }
  leave();
  draw();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 0, 1); }, destroy: bag.dispose };
}

hairline({
  name: "operatingtable",
  means: "An operating table on its column: the pointer's place along the top tilts it on its pivot, that end dipping down.",
  rules: [1, 3, 5, 8],
  range: [0.3, 1, 1],
  tour: [[281, 208], [119, 139], [200, 172], null],
  mount,
});

shaver.code:
/**
 * Shaver: an electric foil shaver standing on its foot, a rounded grip with
 * a panel and a power button, a neck, and a wide head carrying two foil
 * rolls. The head is hinged at its back edge: the higher the pointer goes up
 * the shaver, the further the head pops up and swings back, baring the
 * cutter block. At rest it sits a little ajar and the button is the bright
 * mark. The slider is how far back the head can swing.
 *
 * The pattern: one part on a hinge, its angle a spring driven by the
 * pointer's height over the rest pose's fixed screen band.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, rrect, seg, spring, stepS,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const HY = -7, HZ = 40, REST = 6, FR = 3.5, FZ = 49.2, HT = 48;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = value;
  const C = Cam(45, 0.5, 4.3);
  // the head's local points, rotated about the hinge (an x axis at HY, HZ) and popped up
  const blk = rrect(-16, -7, 16, 7, 4.5, 6);
  function pose(t) {
    const a = (t * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a), up = 5 * clamp(t / 40, 0, 1);
    return ([x, y, z]) => { const dy = y - HY, dz = z - HZ; return [x, HY + dy * c - dz * s, HZ + dy * s + dz * c + up]; };
  }
  function headPts(R) {
    const pts = [];
    blk.forEach((q) => { pts.push(R([q.u, q.v, HZ]), R([q.u, q.v, HT])); });
    [-15.5, 15.5].forEach((x) => [-3.4, 3.4].forEach((yc) => {
      for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; pts.push(R([x, yc + FR * Math.cos(a), FZ + FR * Math.sin(a)])); }
    }));
    return pts;
  }
  fit(C, [[-12, -7, 0], [12, 7, 0], [16, 7, 53], [-16, -7, 53]].concat(headPts(pose(110))), 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the grip, its panel and the power button
  const body = solid(g);
  const [br, bi] = rings(-12, -7, 12, 7, 6, 1.4);
  put(body, prism(P, front, br, bi, 0, 36));
  const panel = rrect(-6, 7, 6, 25, 4.5, 4).map((q) => P(q.u, 7, q.v));
  mk("path", { class: "nf lo", d: poly(panel) + seg(P(-3.5, 7, 13), P(3.5, 7, 13)) + seg(P(-3.5, 7, 17), P(3.5, 7, 17)) }, body.g);
  const btn = mk("circle", { class: "dot", r: 3 }, body.g);
  place(btn, P(0, 7, 30));
  const neck = solid(g);
  const [nr, ni] = rings(-10, -5.5, 10, 5.5, 4, 1);
  put(neck, prism(P, front, nr, ni, 36, HZ));

  // the head, then the cutter block it covers
  const hg = mk("g", {}, g);
  const hsil = mk("path", { class: "sil" }, hg), hcr = mk("path", { class: "nf lo" }, hg);
  const cut = solid(g);
  const [cr, ci] = rings(-14, -4, 14, 4, 1.5, 0.6);
  put(cut, prism(P, front, cr, ci, HZ, HZ + 3));
  let blades = "";
  for (let k = -2; k <= 2; k++) blades += seg(P(-13, k * 1.5, HZ + 3), P(13, k * 1.5, HZ + 3));
  mk("path", { class: "nf lo", d: blades }, cut.g);

  let last = NaN;
  function draw(t) {
    if (Math.abs(t - last) < 0.02) return;
    last = t;
    const R = pose(t), Q = (p) => P(...R(p));
    hsil.setAttribute("d", poly(hull(headPts(R).map((p) => P(...p)))));
    let d = "";
    [-3.4, 3.4].forEach((yc) => {
      const arc = [];
      for (let i = 0; i <= 12; i++) { const a = (i / 12) * Math.PI; arc.push(Q([15.5, yc + FR * Math.cos(a), FZ + FR * Math.sin(a)])); }
      d += open(arc) + seg(Q([-15.5, yc, FZ + FR]), Q([15.5, yc, FZ + FR]));
    });
    d += seg(Q([-15.5, 0, HT - 0.8]), Q([15.5, 0, HT - 0.8])) + open([Q([15.6, 6.9, HT - 1]), Q([15.6, 6.9, HZ + 1.5])]);
    hcr.setAttribute("d", d);
    if (t > 38) { if (!cut.g.isConnected) hg.after(cut.g); } else cut.g.remove();
  }

  const ang = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  // the hit: a fixed screen band over the rest pose; height along it sets the swing
  const top = P(0, 0, 54)[1], bot = P(0, 0, 6)[1];
  const xs = [P(-16, 7, 44)[0], P(16, -7, 44)[0], P(-12, 7, 0)[0], P(12, -7, 0)[0]];
  const x0 = Math.min(...xs) - 6, x1 = Math.max(...xs) + 6;
  let f = -1;
  function aim() {
    ang.t = f < 0 ? REST : amax * (0.2 + 0.8 * f);
    const on = f >= 0;
    hsil.classList.toggle("hi", on);
    btn.setAttribute("class", on ? "dot off" : "dot");
    read.textContent = on ? Math.round(ang.t) + "°" : "rest";
    B.wake();
  }
  function move([sx, sy]) {
    f = sx < x0 || sx > x1 || sy < top - 30 || sy > P(12, 7, 0)[1] + 8 ? -1 : clamp((bot - sy) / (bot - top), 0, 1);
    aim();
  }
  aim();
  bag.add(pointer(stage, { move, leave: () => { f = -1; aim(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = v; if (f >= 0) aim(); }, destroy: bag.dispose };
}

hairline({
  name: "shaver",
  means: "An electric foil shaver: the higher the pointer climbs it, the further its hinged head pops up and swings back off the cutters.",
  rules: [1, 3, 4, 5],
  range: [30, 80, 110],
  tour: [[134, 249], [134, 182], [145, 95], null],
  mount,
});

hairdryer2.code:
/**
 * Hair dryer: a handheld dryer, a round barrel with a grilled intake at the
 * back and a flat concentrator nozzle at the front, and a handle hinged
 * under the barrel. Over the dryer the handle unfolds, swinging down from
 * along the barrel to hang below it, ready to hold. At rest the handle is
 * folded nearly flat, bright. The slider is how far it swings open.
 *
 * The pattern: one hinged part on a spring; the hit is a fixed screen box.
 */
const { Cam, fit, poly, open, hull, proj, rrect, rad, spring, stepS, mk, solid, register, pointer, disposer } = HL;
const R = 13, L = 70, HL_ = 40, ZB = R + HL_ + 3, HX = 40, FOLD = 82;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[-6, -R - 2, ZB + R], [L + 16, R + 2, ZB - R], [HX, -6, 0], [HX, 6, 0], [-4, 0, ZB - R - 10], [L + 16, -R, ZB + R]], 200, 166);
  const P = proj(C), g = mk("g", {}, svg);
  const ring = (x, r, rz, n = 32) => { const o = []; for (let i = 0; i < n; i++) { const t = (i / n) * Math.PI * 2; o.push(P(x, r * Math.cos(t), ZB + rz * Math.sin(t))); } return o; };
  const handle = solid(g);
  const sec = rrect(-7, -6, 7, 6, 4.5, 4);
  const cap = mk("path", { class: "sil" }, g), grille = mk("path", { class: "nf lo", d: poly(ring(-5, R - 4, R - 4)) + poly(ring(-5, R - 8, R - 8)) }, g);
  cap.setAttribute("d", poly(hull(ring(-5, R + 1, R + 1).concat(ring(2, R + 1, R + 1)))));
  const barrel = mk("path", { class: "sil", d: poly(hull(ring(2, R, R).concat(ring(L, R - 2, R - 2)))) }, g);
  mk("path", { class: "nf lo", d: open(ring(8, R, R).filter((_, i) => i < 17)) }, g);
  const slot = (x, w, h) => rrect(-w, -h, w, h, Math.min(h, 3), 3).map((q) => P(x, q.u, ZB + q.v));
  mk("path", { class: "sil", d: poly(hull(ring(L - 2, R - 2, R - 2).concat(slot(L + 16, R - 1, 3.2)))) }, g);
  mk("path", { class: "nf lo", d: poly(slot(L + 16, R - 3, 1.4)) }, g);
  const th = spring(FOLD);
  let last = NaN;
  function draw(a) {
    if (a === last) return; last = a;
    const t = rad(a), d = [-Math.sin(t), 0, -Math.cos(t)], n = [Math.cos(t), 0, -Math.sin(t)], h0 = [HX, 0, ZB - R + 4], pts = [];
    for (const s of [0, HL_]) for (const q of sec) pts.push(P(h0[0] + s * d[0] + q.u * n[0], q.v, h0[2] + s * d[2] + q.u * n[2]));
    handle.sil.setAttribute("d", poly(hull(pts)));
    handle.cr.setAttribute("d", seg3(h0, d, n));
  }
  function seg3(h0, d, n) {
    const a = P(h0[0] + 10 * d[0] - 7 * n[0], 6, h0[2] + 10 * d[2] - 7 * n[2]), e = P(h0[0] + (HL_ - 4) * d[0] - 7 * n[0], 6, h0[2] + (HL_ - 4) * d[2] - 7 * n[2]);
    return open([a, e]);
  }
  handle.cr.setAttribute("class", "nf lo");
  draw(FOLD);
  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(th.x); return m; });
  bag.add(B.unregister);
  const box = [P(-6, R, ZB + R), P(L + 16, R, ZB), P(L + 16, -R, ZB + R), P(-6, -R, ZB + R), P(HX, 0, 0), P(-6, R, ZB - R)];
  const bx0 = Math.min(...box.map((p) => p[0])), bx1 = Math.max(...box.map((p) => p[0])), by0 = Math.min(...box.map((p) => p[1])), by1 = Math.max(...box.map((p) => p[1]));
  let on = null;
  function set(v) {
    if (v === on) return; on = v;
    th.t = v ? FOLD - swing : FOLD;
    handle.sil.classList.toggle("hi", true);
    read.textContent = v ? Math.round(swing) + "°" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => set(x > bx0 - 6 && x < bx1 + 6 && y > by0 - 6 && y < by1 + 6), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (on) { th.t = FOLD - v; B.wake(); } }, destroy: bag.dispose };
}
hairline({
  name: "hairdryer2",
  means: "A handheld hair dryer: over it the folded handle swings down from under the barrel to hang ready to hold.",
  rules: [1, 3, 4, 5],
  range: [50, 70, 82],
  tour: [[184, 106], [140, 104], [236, 150], null],
  mount,
});

bathscale.code:
/**
 * Bathroom scale: a square base with a thick glass platform floating over it,
 * two foot pads and a round dial on the platform. The pointer steps on the
 * platform: it sinks onto the base and the dial's needle swings round. At
 * rest the platform floats high, bright. The slider is how far it sinks.
 *
 * The pattern: a continuous press on a spring; the hit is on the platform's
 * rest plane, which never moves.
 */
const { Cam, fit, facing, poly, prism, proj, rings, ringAt, circ, rrect, seg, spring, stepS, mk, solid, put, register, pointer, unproj, disposer } = HL;
const L = 64, BZ = 5, UP = 17;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
const pad = (x0, y0, x1, y1) => rrect(x0, y0, x1, y1, 5, 4);
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let sink = value;
  const C = Cam(45, 0.5, 3.0);
  fit(C, [[0, 0, 0], [L, L, 0], [L, 0, UP + 4], [0, L, UP + 4], [0, 0, UP + 4], [L, L, 0]], 200, 166);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, L, L, 9, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [pr, pi] = rings(2, 2, L - 2, L - 2, 8, 1.6);
  const plate = solid(g), pads = mk("path", { class: "nf lo" }, g);
  const dial = mk("path", { class: "nf" }, g), needle = mk("path", { class: "nf" }, g);
  const REST = UP, z = spring(REST);
  let last = NaN;
  function draw(h) {
    if (h === last) return; last = h;
    const t = h + 3.5;
    put(plate, prism(P, front, pr, pi, h, t));
    pads.setAttribute("d", poly(ringAt(P, pad(8, 10, 28, 46), t)) + poly(ringAt(P, pad(36, 10, 56, 46), t)));
    dial.setAttribute("d", poly(ringAt(P, disc(L - 12, L / 2, 6.5), t)));
    const a = -2.4 + 4.2 * (REST - h) / 12, cx = L - 12, cy = L / 2;
    needle.setAttribute("d", seg(P(cx, cy, t), P(cx + 5.5 * Math.cos(a), cy + 5.5 * Math.sin(a), t)));
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(z, dt); draw(z.x); return m; });
  bag.add(B.unregister);
  let on = null;
  function set(v) {
    if (v === on) return; on = v;
    z.t = v ? REST - sink : REST;
    plate.sil.classList.toggle("hi", true);
    read.textContent = v ? (60 + sink * 1.5).toFixed(1) + "kg" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, { move: ([x, y]) => { const [wx, wy] = unproj(C, x, y, REST + 3.5); set(wx > -4 && wx < L + 4 && wy > -4 && wy < L + 4); }, leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { sink = v; if (on) { z.t = REST - v; B.wake(); } }, destroy: bag.dispose };
}
hairline({
  name: "bathscale",
  means: "A bathroom scale: the pointer steps on the glass platform, it sinks onto the base and the dial's needle swings round.",
  rules: [1, 3, 4, 5],
  range: [6, 9, 12],
  tour: [[200, 140], [172, 132], [226, 152], null],
  mount,
});

showerenclosure.code:
/**
 * Shower enclosure: a square shower tray with a riser and head in the back
 * corner, a fixed glass side panel and a glass door on a pivot hinge at the
 * front corner, with a long pull handle. At rest the door stands a little
 * ajar, bright. Over it the door swings out on its pivot. The slider is how
 * far it swings.
 */
const { Cam, circ, fit, hull, poly, proj, rrect, ringAt, rings, prism, facing, seg, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const W = 40, H = 78, Z0 = 4, REST = 14, DW = 38;
const toR = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [W + 37, W + 7, 0], [0, W + 2, 0], [W + 2, 0, 0], [3, 3, H + 4], [W + 37, W + 7, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  function slab(ring, inner, Tf, w0, w1) {
    const a = ring.map((q) => P(...Tf(q.u, q.v, w0))), b = ring.map((q) => P(...Tf(q.u, q.v, w1)));
    return { sil: poly(hull(a.concat(b))), crease: poly(inner.map((q) => P(...Tf(q.u, q.v, w1)))) };
  }
  // the tray
  const [tr, ti] = rings(0, 0, W + 2, W + 2, 4, 1.6);
  put(solid(g), prism(P, front, tr, ti, 0, Z0));
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(18, 18, 24, 24, 3, 4), Z0)) }, g);
  // the riser in the back corner, its arm and the round head
  mk("path", { class: "nf", d: seg(P(3, 3, Z0), P(3, 3, H - 2)) + seg(P(3, 3, H - 2), P(11, 11, H - 2)) }, g);
  const hd = circ(5, 24).map((q) => ({ ...q, u: q.u + 12, v: q.v + 12 }));
  put(solid(g), { sil: poly(hull(ringAt(P, hd, H - 5).concat(ringAt(P, hd, H - 3)))), crease: poly(ringAt(P, circ(3.6, 24).map((q) => ({ ...q, u: q.u + 12, v: q.v + 12 })), H - 5)) });
  // the fixed glass side panel, standing on the tray's near-left edge
  const pr = rrect(0, Z0, W, H, 2, 4), pi = rrect(2.5, Z0 + 2.5, W - 2.5, H - 2.5, 1, 4);
  const side = solid(g);
  side.sil.classList.add("nf");
  put(side, slab(pr, pi, (u, v, w) => [u, W + w, v], 0, 1.2));
  // the door: a glass plate on a pivot at the front corner, with its handle
  const door = solid(g);
  door.sil.classList.add("nf", "hi");
  const handle = mk("path", { class: "nf" }, door.g);
  const dr = rrect(0, Z0 + 0.5, DW, H, 2, 4), di = rrect(2.5, Z0 + 3, DW - 2.5, H - 2.5, 1, 4);
  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const s = Math.sin(toR(a)), c = Math.cos(toR(a));
    const Tf = (u, v, w) => [W + u * s + w * c, W - u * c + w * s, v];
    put(door, slab(dr, di, Tf, 0, 1.2));
    handle.setAttribute("d", seg(P(...Tf(DW - 5, 30, 3.5)), P(...Tf(DW - 5, 54, 3.5))) + seg(P(...Tf(DW - 5, 30, 1.2)), P(...Tf(DW - 5, 30, 3.5))) + seg(P(...Tf(DW - 5, 54, 1.2)), P(...Tf(DW - 5, 54, 3.5))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  const mid = P(W / 2, W / 2, H / 2);
  let on = false;
  function setOn(v) {
    on = v;
    tset(ang, on ? reach : REST, performance.now(), 0);
    read.textContent = on ? "door" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => { const v = Math.abs(x - mid[0]) < 140 && Math.abs(y - mid[1]) < 130; if (v !== on) setOn(v); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "showerenclosure",
  means: "A shower enclosure on a square tray: over it, the glass door swings out on its pivot hinge beside the fixed side panel.",
  rules: [1, 3, 5, 8],
  range: [40, 80, 100],
  tour: [[235, 164], [262, 100], [150, 120], null],
  mount,
});

flushcistern.code:
/**
 * High-level cistern: a tank high on two wall brackets, its flush pipe running
 * down to the toilet bowl, and a lever on the tank's end with a long pull
 * chain and a weighted handle. At rest the chain hangs a little aslant, its
 * handle bright. Over it the handle is pulled: the lever tips down and the
 * chain swings out. The slider is how far it swings.
 */
const { Cam, circ, fit, hull, poly, proj, rrect, rings, ringAt, prism, facing, fillet, seg, tset, tval, tdone, tween, disposer, mk, pointer, put, register, solid } = HL;

const TZ = 96, TH = 18, TY = 44, PV = [14, 41, TZ + 13], LL = 13, CL = 48, NL = 9, REST = 7;
const toR = (d) => (d * Math.PI) / 180;
const at = (cx, cy, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + cx, v: q.v + cy }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.5);
  fit(C, [[0, 0, 0], [38, 34, 0], [0, TY, TZ + TH], [40, 4, 40], [40, 60, 40], [14, 0, TZ], [0, 0, TZ + TH], [14, TY, TZ + TH], [36, 30, 0], [4, 25, 0]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the bowl: a tapered pedestal with a seat ring
  const foot = rrect(4, 9, 26, 25, 7, 12), top = rrect(0, 4, 36, 30, 12, 14);
  put(solid(g), { sil: poly(hull(ringAt(P, foot, 0).concat(ringAt(P, top, 28)))), crease: poly(ringAt(P, rrect(1.5, 5.5, 34.5, 28.5, 10.5, 14), 28)) });
  mk("path", { class: "nf lo", d: poly(ringAt(P, rrect(9, 9, 33, 25, 8, 14), 28)) }, g);
  // the flush pipe, down the wall and into the back of the bowl
  mk("path", { class: "nf", d: seg(P(2, 15, TZ), P(2, 15, 34)) + seg(P(2, 19, TZ), P(2, 19, 34)) + seg(P(2, 15, 34), P(6, 15, 28)) + seg(P(2, 19, 34), P(6, 19, 28)) }, g);
  // the brackets and the tank
  for (const y of [6, TY - 6]) {
    const [r, i] = rings(0, y - 1.5, 12, y + 1.5, 1, 0.5);
    put(solid(g), prism(P, front, r, i, TZ - 6, TZ));
  }
  const [tr, ti] = rings(0, 0, 14, TY, 3, 1.4);
  put(solid(g), prism(P, front, tr, ti, TZ, TZ + TH));
  // the lever, the chain and the handle
  const lever = solid(g), chain = mk("path", { class: "nf" }, g), handle = solid(g);
  handle.sil.classList.add("hi");
  const sw = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const k = (a - REST) / 50, lt = toR(-28 * k);
    const tip = [PV[0] + LL * Math.cos(lt), PV[1], PV[2] + LL * Math.sin(lt)];
    const [lr, li] = rings(-1, -1.2, LL + 1, 1.2, 1, 0.5);
    const lp = (q, z) => P(PV[0] + q.u * Math.cos(lt), PV[1] + q.v, PV[2] + q.u * Math.sin(lt) + z);
    put(lever, { sil: poly(hull(lr.map((q) => lp(q, -1)).concat(lr.map((q) => lp(q, 1))))), crease: poly(li.map((q) => lp(q, 1))) });
    const s = Math.sin(toR(a)) * 0.707, c = Math.cos(toR(a));
    const pt = (d) => [tip[0] + d * s, tip[1] - d * s, tip[2] - d * c];
    let d = "";
    for (let i = 0; i < NL; i++) {
      const A = P(...pt((i / NL) * CL)), Bp = P(...pt(((i + 1) / NL) * CL));
      const dx = Bp[0] - A[0], dy = Bp[1] - A[1], m = Math.hypot(dx, dy) || 1, nx = (-dy / m) * 1.6, ny = (dx / m) * 1.6;
      d += poly(fillet([[A[0] + nx, A[1] + ny], [Bp[0] + nx, Bp[1] + ny], [Bp[0] - nx, Bp[1] - ny], [A[0] - nx, A[1] - ny]], [1.5, 1.5, 1.5, 1.5], 3));
    }
    chain.setAttribute("d", d);
    const e = pt(CL);
    const ring = (dz, r) => ringAt(P, at(e[0], e[1], r), e[2] - dz);
    put(handle, { sil: poly(hull(ring(0, 1.6).concat(ring(4, 3.4), ring(14, 3.8), ring(16, 3)))), crease: poly(ring(4, 2.2)) });
  }
  const B = register(stage, (_dt, now) => { draw(tval(sw, now)); return !tdone(sw, now); });
  bag.add(B.unregister);
  const mid = P(18, 30, 60);
  let on = false;
  function setOn(v) {
    on = v;
    tset(sw, on ? reach : REST, performance.now(), 0);
    read.textContent = on ? "pull" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: ([x, y]) => { const v = Math.abs(x - mid[0]) < 140 && Math.abs(y - mid[1]) < 140; if (v !== on) setOn(v); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (on) setOn(true); }, destroy: bag.dispose };
}

hairline({
  name: "flushcistern",
  means: "A high-level cistern with a pull chain: over it, the handle is pulled, the lever tips down and the chain swings out.",
  rules: [1, 3, 5, 8],
  range: [20, 40, 50],
  tour: [[182, 179], [225, 140], [207, 60], null],
  mount,
});

marblerun.code:
/**
 * Marble run: a centre post holding a fixed lower chute and, on its top, a
 * long tipping chute that rocks on a pivot like a seesaw, with a marble in
 * its groove. The pointer's side of the post tips the chute down that way
 * and the marble rolls to the low end. At rest the chute leans a little
 * left, the marble bright partway down. The slider is how far it tips.
 *
 * The pattern: one value along a path (spring).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rad, rings, ringAt, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 150, W = 16, R = 7, XC = L / 2, ZP = 74, REST = -0.45;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.75);
  const ext = 26;
  fit(C, [[XC - 30, -24, 0], [XC + 30, W + 10, 0], [0, W / 2, ZP + ext + 10], [L, W / 2, ZP + ext + 10], [0, W / 2, ZP - ext - 4], [L, W / 2, ZP - ext]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(XC - 30, -24, XC + 30, W + 10, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  const [pr, pi] = rings(XC - 4, -16, XC + 4, -8, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 5, ZP + 2));
  // the fixed lower chute, sloping down to the left
  const lo = (x) => 20 + ((x - 20) / (L - 40)) * 14;
  const ls = solid(g), c0 = [];
  for (const x of [20, L - 20]) for (const y of [0, W]) for (const dz of [-3, 0]) c0.push(P(x, y, lo(x) + dz));
  ls.sil.setAttribute("d", poly(hull(c0)));
  ls.cr.setAttribute("d", seg(P(21, W - 1.5, lo(21) + 1.6), P(L - 21, W - 1.5, lo(L - 21) + 1.6)));
  mk("path", { class: "nf lo", d: seg(P(21, 1.5, lo(21) + 1.6), P(L - 21, 1.5, lo(L - 21) + 1.6)) }, g);
  mk("path", { class: "nf lo", d: poly(ringAt(P, disc(XC, -12, 3, 12), ZP - 3)) }, g);
  // the tipping chute and its marble
  const up = solid(g), lip = mk("path", { class: "nf lo" }, g), stops = mk("path", { class: "nf lo" }, g);
  const mg = mk("g", {}, g), ball = mk("path", { class: "sil hi" }, mg), eq = mk("path", { class: "nf lo" }, mg);
  const pin = mk("path", { class: "nf" }, g);

  const tilt = spring(REST), roll = spring(REST);
  const max = () => rad(6 + (value / 100) * 18);
  let last = "";
  function at(x, y, dz, a) { const d = x - XC; return P(XC + d * Math.cos(a), y, ZP + d * Math.sin(a) + dz); }
  function draw() {
    const key = tilt.x.toFixed(4) + roll.x.toFixed(4) + value;
    if (key === last) return;
    last = key;
    const a = -tilt.x * max(), c = [];
    for (const x of [0, L]) for (const y of [0, W]) for (const dz of [-4, 0]) c.push(at(x, y, dz, a));
    up.sil.setAttribute("d", poly(hull(c)));
    up.cr.setAttribute("d", seg(at(1, W - 1.5, 1.6, a), at(L - 1, W - 1.5, 1.6, a)));
    lip.setAttribute("d", seg(at(1, 1.5, 1.6, a), at(L - 1, 1.5, 1.6, a)));
    stops.setAttribute("d", seg(at(3, 1.5, 0, a), at(3, W - 1.5, 0, a)) + seg(at(L - 3, 1.5, 0, a), at(L - 3, W - 1.5, 0, a)));
    pin.setAttribute("d", poly(ringAt(P, disc(XC, W / 2, 2.5, 12), ZP - 2)));
    const x = XC + clamp(roll.x, -1, 1) * (L / 2 - R - 4), d = x - XC;
    const cx = XC + d * Math.cos(a), cz = ZP + d * Math.sin(a) + R;
    const pts = [];
    for (let i = -5; i <= 5; i++) { const b = (i / 5) * (Math.PI / 2); pts.push(...ringAt(P, disc(cx, W / 2, R * Math.cos(b)), cz + R * Math.sin(b))); }
    ball.setAttribute("d", poly(hull(pts)));
    eq.setAttribute("d", seg(P(cx - R * 0.7, W / 2 + R * 0.7, cz), P(cx + R * 0.7, W / 2 + R * 0.7, cz)));
  }

  const B = register(stage, (dt) => { const m1 = stepS(tilt, dt), m2 = stepS(roll, dt); draw(); return m1 || m2; });
  bag.add(B.unregister);

  const xa = P(0, W / 2, 0)[0], xb = P(L, W / 2, 0)[0], xm = (xa + xb) / 2;
  function move([sx]) {
    const s = clamp((sx - xm) / ((xb - xa) / 2), -1, 1);
    tilt.t = s; roll.t = Math.sign(s) * Math.min(1, Math.abs(s) * 1.6);
    read.textContent = (s < 0 ? "left " : "right ") + Math.round(Math.abs(s) * (6 + (value / 100) * 18)) + "°";
    B.wake();
  }
  function leave() { tilt.t = REST; roll.t = REST; read.textContent = "rest"; B.wake(); }
  draw(); read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { value = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "marblerun",
  means: "A marble run's tipping chute rocks on its post like a seesaw toward the pointer, and the marble rolls down to the low end.",
  rules: [1, 3, 5, 6],
  range: [0, 60, 100],
  tour: [[107, 99], [287, 165], [293, 192], null],
  mount,
});

hammerbench.code:
/**
 * Hammer bench: a wooden bench on two end blocks with four pegs standing
 * through its top, and a mallet over them. The pointer picks a peg by where
 * its top stands: the mallet slides over it and pounds it down into the
 * bench. At rest the mallet hangs raised over the second peg, bright. The
 * slider is how deep each blow drives the peg.
 *
 * The pattern: one of many in a single row (riffle).
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const N = 4, STEP = 34, X0 = 22, BW = 36, TZ = 22, PH = 16, PR = 6, HR = 9, HL2 = 17, HAND = 54, REST = 1, UP = 36;
const LEN = X0 * 2 + (N - 1) * STEP;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.8);
  fit(C, [[0, 0, 0], [LEN, BW, 0], [LEN, 0, 0], [0, BW, 0], [X0, BW / 2, TZ + PH + UP + HR + 4], [LEN - X0 + HL2, BW / 2 + HAND, TZ + 4], [X0 - HL2, BW / 2, TZ + PH + UP + HR + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  for (const x of [0, LEN - 14]) { const [r, i] = rings(x + 2, 2, x + 12, BW - 2, 3, 1.2); put(solid(g), prism(P, front, r, i, 0, TZ - 6)); }
  const [tr, ti] = rings(0, 0, LEN, BW, 5, 2);
  put(solid(g), prism(P, front, tr, ti, TZ - 6, TZ));
  const pegs = [];
  for (let k = 0; k < N; k++) {
    const x = X0 + k * STEP, y = BW / 2;
    mk("path", { class: "nf lo", d: poly(ringAt(P, disc(x, y, PR + 1.5), TZ)) }, g);
    pegs.push({ k, x, y, s: solid(g), h: tween(k === REST ? PH * 0.55 : PH - (k === 3 ? 4 : 0)), last: NaN });
  }
  const mal = mk("g", {}, g), handle = mk("path", { class: "" }, mal), head = solid(mal), face = mk("path", { class: "nf lo" }, mal);
  const mx = tween(X0 + REST * STEP), mz = tween(TZ + PH * 0.55 + UP);

  let last = "";
  function draw(now) {
    for (const p of pegs) {
      const h = tval(p.h, now);
      if (h === p.last) continue;
      p.last = h;
      const [r, i] = [disc(p.x, p.y, PR), disc(p.x, p.y, PR - 1.6)];
      put(p.s, prism(P, front, r, i, TZ, TZ + Math.max(1, h)));
    }
    const x = tval(mx, now), z = tval(mz, now) + HR, y = BW / 2, key = x.toFixed(3) + z.toFixed(3);
    if (key === last) return;
    last = key;
    const hp = [];
    for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2; hp.push(P(x - 4, y + 2 + 2.5 * Math.cos(a), z + 2.5 * Math.sin(a)), P(x + 4, y + HAND + 2.5 * Math.cos(a), z + 2.5 * Math.sin(a))); }
    handle.setAttribute("d", poly(hull(hp)));
    const cy = [], cap = [];
    for (let i = 0; i < 24; i++) {
      const a = (i / 24) * Math.PI * 2, dy = HR * Math.cos(a), dz = HR * Math.sin(a);
      cy.push(P(x - HL2, y + dy, z + dz), P(x + HL2, y + dy, z + dz));
      cap.push(P(x + HL2, y + (HR - 2) * Math.cos(a), z + (HR - 2) * Math.sin(a)));
    }
    head.sil.setAttribute("d", poly(hull(cy)));
    head.cr.setAttribute("d", seg(P(x - HL2 + 2, y + HR - 1, z + 2), P(x + HL2 - 2, y + HR - 1, z + 2)));
    face.setAttribute("d", poly(cap));
  }

  const B = register(stage, (_dt, now) => {
    draw(now);
    return !tdone(mx, now) || !tdone(mz, now) || pegs.some((p) => !tdone(p.h, now));
  });
  bag.add(B.unregister);

  const tops = pegs.map((p) => P(p.x, p.y, TZ + PH));
  function hit([sx, sy]) {
    let best = -1, bd = Infinity;
    tops.forEach((m, k) => { const d = Math.abs(m[0] - sx); if (d < bd) { bd = d; best = k; } });
    return bd < 26 && Math.abs(tops[best][1] - sy) < 90 ? best : -1;
  }

  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    const now = performance.now(), deep = 3 + (value / 100) * (PH - 4);
    pegs.forEach((p, k) => {
      tset(p.h, a < 0 ? (k === REST ? PH * 0.55 : PH - (k === 3 ? 4 : 0)) : k === a ? PH - deep : PH, now, 0);
      p.s.sil.classList.toggle("hi", k === a);
    });
    const k = a < 0 ? REST : a;
    tset(mx, X0 + k * STEP, now, 0);
    tset(mz, a < 0 ? TZ + PH * 0.55 + UP : TZ + PH - deep, now, a < 0 ? 0 : 120);
    head.sil.classList.toggle("hi", a < 0);
    read.textContent = a < 0 ? "rest" : "peg " + (a + 1) + "·" + Math.round(deep);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { value = v; setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "hammerbench",
  means: "A toy hammer bench: the mallet slides over the peg under the pointer and pounds it down into the bench.",
  rules: [1, 4, 5, 6],
  range: [0, 60, 100],
  tour: [[135, 135], [265, 200], [200, 168], null],
  mount,
});

slinky.code:
/**
 * Coil spring toy: a coil of wire rings standing on the top step of a short
 * stair. The pointer over the stair sends the coil walking: its top rings
 * arch over and land on the lower step while the bottom rings stay put. At
 * rest it stands compact, its top ring bright. The slider is how far it
 * reaches down the stair.
 *
 * The pattern: one part arching toward the pointer (spring).
 */
const { Cam, clamp, fit, facing, lerp, poly, prism, proj, rings, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const N = 16, R = 12, CX = 20, CY = 20, TOP = 30, LOW = 12, GAP = 1.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = 45 + 40 * value;
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[0, 0, 0], [118, 42, 0], [0, 42, 0], [118, 0, 0], [0, 0, TOP], [62, CY, 72]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [ua, ub] = rings(0, 0, 40, 42, 3, 1.5);
  put(solid(g), prism(P, front, ua, ub, 0, TOP));
  const [la, lb] = rings(40, 0, 118, 42, 3, 1.5);
  put(solid(g), prism(P, front, la, lb, 0, LOW));
  const coil = [];
  for (let i = 0; i < N; i++) coil.push(mk("path", { class: "nf" + (i === N - 1 ? " hi" : "") }, g));
  const prog = spring(0, { k: 70, c: 14 });
  let last = "";

  function draw() {
    const key = prog.x.toFixed(4) + "," + reach;
    if (key === last) return;
    last = key;
    const p = clamp(prog.x, -0.1, 1.1), H = 22 + reach * 0.3;
    for (let i = 0; i < N; i++) {
      const th = Math.PI * i / (N - 1), m = (1 - Math.cos(th)) / 2;
      const ax = CX + reach * m, az = lerp(TOP, LOW, m) + H * Math.sin(th) + GAP;
      let tx = reach / 2 * Math.sin(th), tz = (LOW - TOP) / 2 * Math.sin(th) + H * Math.cos(th);
      const tl = Math.hypot(tx, tz) || 1;
      const cx = lerp(CX, ax, p), cz = lerp(TOP + GAP + i * GAP, az, p);
      let nx = lerp(0, tx / tl, p), nz = lerp(1, tz / tl, p);
      const nl = Math.hypot(nx, nz) || 1; nx /= nl; nz /= nl;
      const pts = [];
      for (let k = 0; k < 28; k++) {
        const f = (k / 28) * Math.PI * 2, c = Math.cos(f) * R, s = Math.sin(f) * R;
        pts.push(P(cx + c * nz, CY + s, cz - c * nx));
      }
      coil[i].setAttribute("d", poly(pts));
    }
  }

  const B = register(stage, (dt) => { const m = stepS(prog, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();

  const box = [[0, 0, 0], [118, 42, 0], [0, 42, 0], [118, 0, 0], [0, 0, TOP + N * GAP + 14], [40, 42, TOP + N * GAP + 14]].map((q) => P(...q));
  const bx0 = Math.min(...box.map((q) => q[0])) - 10, bx1 = Math.max(...box.map((q) => q[0])) + 10;
  const by0 = Math.min(...box.map((q) => q[1])) - 10, by1 = Math.max(...box.map((q) => q[1])) + 10;
  function onMove([sx, sy]) {
    if (sx < bx0 || sx > bx1 || sy < by0 || sy > by1) return onLeave();
    prog.t = 1;
    coil[N - 1].classList.add("hi");
    read.textContent = "step " + Math.round(reach);
    B.wake();
  }
  function onLeave() { prog.t = 0; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: onMove, leave: onLeave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = 45 + 40 * v; last = ""; draw(); }, destroy: bag.dispose };
}

hairline({
  name: "slinky",
  means: "A coil spring toy on a stair: the pointer sends its top rings arching over to land on the lower step.",
  rules: [1, 3, 5, 8],
  range: [0, 0.7, 1],
  tour: [[128, 78], [206, 150], [255, 230], null],
  mount,
});

windupmouse.code:
/**
 * Wind-up mouse: a clockwork mouse with round ears, a curled tail and a
 * winding key on its back. The pointer over it lets the spring go: the key
 * spins, the tail swings and the mouse scoots forward across the floor. At
 * rest it sits wound, its key bright. The slider is how far it scoots.
 *
 * The pattern: one part turning while the whole slides (spring).
 */
const { Cam, clamp, fit, hull, open, poly, proj, seg, spring, stepS, disposer, mk, pointer, register } = HL;

const BC = 15, KX = -8;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let far = 20 + 25 * value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-50, -16, 0], [73, 16, 0], [-50, 16, 0], [73, -16, 0], [-8, 0, 34], [37, 0, 34]], 200, 165);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const track = mk("path", { class: "dash" }, g);
  const tail = mk("path", { class: "nf" }, g);
  const earF = mk("path", { class: "sil" }, g);
  const body = mk("path", { class: "sil" }, g);
  const spine = mk("path", { class: "nf lo" }, g);
  const shaft = mk("path", { class: "nf" }, g);
  const key = mk("path", { class: "sil hi" }, g);
  const earN = mk("path", { class: "sil" }, g);
  const nose = mk("path", {}, g);
  const go = spring(0, { k: 60, c: 13 });
  let last = "";

  function draw() {
    const key0 = go.x.toFixed(4);
    if (key0 === last) return;
    last = key0;
    const s = go.x, Q = (x, y, z) => P(x + s, y, z);
    const pts = [];
    for (const z of [0, 4, 8, 11, 13.5, BC]) {
      const r = Math.sqrt(Math.max(0, 1 - (z / BC) ** 2));
      for (let k = 0; k < 32; k++) { const f = (k / 32) * Math.PI * 2, c = Math.cos(f); pts.push(Q(c * (c > 0 ? 28 : 22) * r, Math.sin(f) * 14 * r, z)); }
    }
    body.setAttribute("d", poly(hull(pts)));
    spine.setAttribute("d", open([-20, -10, 0, 10, 20].map((x) => Q(x, 0, BC * Math.sqrt(1 - (x / (x > 0 ? 28 : 22)) ** 2)))));
    const ear = (y) => poly(Array.from({ length: 24 }, (_, k) => { const f = (k / 24) * Math.PI * 2; return Q(9 - Math.sin(f) * 1.5, y + Math.cos(f) * 6, 18 + Math.sin(f) * 6); }));
    earF.setAttribute("d", ear(-7));
    earN.setAttribute("d", ear(7));
    nose.setAttribute("d", poly(hull(Array.from({ length: 12 }, (_, k) => { const f = (k / 12) * Math.PI * 2; return Q(28 + Math.cos(f) * 1.6, Math.sin(f) * 2.2, 3 + Math.sin(f) * 2); }))));
    const sw = Math.sin(s * 0.35) * 0.9;
    tail.setAttribute("d", open(Array.from({ length: 14 }, (_, k) => { const t = k / 13; return Q(-21 - 24 * t, (14 * Math.sin(t * Math.PI * 1.3) + 4 * t) * (1 + sw) * 0.8, 3 + 2 * Math.sin(t * Math.PI)); })));
    const phi = -0.8 + s * 0.22, dx = Math.cos(phi), dy = Math.sin(phi), bow = [];
    for (const sg of [-1, 1]) for (let k = 0; k < 20; k++) { const f = (k / 20) * Math.PI * 2; bow.push(Q(KX + dx * (sg * 5 + Math.cos(f) * 4.5), dy * (sg * 5 + Math.cos(f) * 4.5), 28 + Math.sin(f) * 4.5)); }
    key.setAttribute("d", poly(hull(bow)));
    shaft.setAttribute("d", seg(Q(KX, 0, 14), Q(KX, 0, 24)));
    track.setAttribute("d", seg(P(30 + s, 0, 0), P(32 + far, 0, 0)));
  }

  const B = register(stage, (dt) => { const m = stepS(go, dt); draw(); return m; });
  bag.add(B.unregister);
  draw();

  const box = [[-50, -16, 0], [30, 16, 0], [-50, 16, 0], [30, -16, 0], [KX, 0, 34]].map((q) => P(...q));
  const bx0 = Math.min(...box.map((q) => q[0])) - 12, bx1 = Math.max(...box.map((q) => q[0])) + 12;
  const by0 = Math.min(...box.map((q) => q[1])) - 12, by1 = Math.max(...box.map((q) => q[1])) + 12;
  function onMove([sx, sy]) {
    if (sx < bx0 || sx > bx1 || sy < by0 || sy > by1) return onLeave();
    go.t = far;
    read.textContent = "run " + Math.round(far);
    B.wake();
  }
  function onLeave() { go.t = 0; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: onMove, leave: onLeave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { far = clamp(20 + 25 * v, 20, 45); if (go.t) go.t = far; last = ""; draw(); B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "windupmouse",
  means: "A wind-up mouse: the pointer lets its spring go, the key spins, the tail swings and the mouse scoots across the floor.",
  rules: [1, 3, 5, 8],
  range: [0, 0.7, 1],
  tour: [[159, 76], [130, 130], [197, 197], null],
  mount,
});

pullduck.code:
/**
 * Pull-along duck: a wooden duck on a wheeled board, a pull cord at its
 * front. Over it, the duck flaps: both wings swing up off its sides on their
 * hinges and the head dips forward, the way the toy does when pulled. At rest
 * the wings lie folded and the beak is bright. The slider is how far the
 * wings open.
 *
 * The pattern: one object, one gesture (a tween on the hover).
 */
const {
  Cam, circ, fit, fillet, hull, open, poly, proj, unproj, tset, tval, tdone, tween, rad,
  disposer, mk, pointer, register,
} = HL;

const WING = [[14, 0], [10, 7], [2, 12], [-8, 15], [-20, 17], [-16, 8], [-14, 0]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-36, -24, 0], [42, 24, 0], [42, -24, 0], [-36, 24, 0], [10, 0, 58], [-10, -30, 50], [-10, 30, 50]], 200, 170);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const R = circ(1, 28);
  const ell = (cx, cy, cz, a, b, c, zmin, xf) => {
    const pts = [];
    for (let i = 0; i <= 10; i++) {
      const t = -Math.PI / 2 + (i / 10) * Math.PI, z = Math.max(zmin, cz + c * Math.sin(t)), s = Math.cos(t);
      for (const q of R) pts.push(xf(cx + a * s * q.u, cy + b * s * q.v, z));
    }
    return hull(pts);
  };
  const id = (x, y, z) => P(x, y, z);
  const wheel = (x, y) => {
    const pts = [];
    for (const dy of [-1.5, 1.5]) for (const q of R) pts.push(P(x + 6 * q.u, y + dy, 6 + 6 * q.v));
    mk("path", { d: poly(hull(pts)), class: "sil" }, g);
    mk("path", { d: poly(R.map((q) => P(x + 2 * q.u, y + Math.sign(y) * 1.6, 6 + 2 * q.v))), class: "nf lo" }, g);
  };
  wheel(-20, -16); wheel(22, -16);
  const farWing = mk("path", { class: "sil" }, g);
  // the board
  const board = [[-30, -14], [32, -14], [32, 14], [-30, 14]];
  const bpts = [];
  for (const z of [6, 10]) for (const [x, y] of board) bpts.push(P(x, y, z));
  mk("path", { d: poly(fillet(hull(bpts), Array(6).fill(3))), class: "sil" }, g);
  mk("path", { d: poly(fillet(board.map(([x, y]) => P(x, y, 10)), [3, 3, 3, 3])), class: "nf lo" }, g);
  wheel(-20, 16); wheel(22, 16);
  mk("path", { d: open([P(32, 0, 8), P(40, 4, 4), P(44, 14, 1), P(46, 24, 0.5)]), class: "nf lo" }, g);
  // body, tail up at the back
  const body = ell(0, 0, 21, 26, 13, 11, 10, id).concat([P(-32, 0, 36), P(-30, -3, 33), P(-30, 3, 33)]);
  mk("path", { d: poly(hull(body)), class: "sil" }, g);
  const head = mk("path", { class: "sil" }, g), beak = mk("path", { class: "sil" }, g), eye = mk("path", { class: "nf lo" }, g);
  const nearWing = mk("path", { class: "sil" }, g);

  const st = { w: tween(-58), h: tween(0) };
  let last = "";
  function wing(el, side, a) {
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a));
    const pts = WING.map(([s, t]) => P(s - 2, side * (10 + t * ca), 25 + t * sa));
    el.setAttribute("d", poly(fillet(pts, Array(pts.length).fill(2.5))));
    return pts;
  }
  function draw(w, h) {
    const key = w.toFixed(2) + h.toFixed(2);
    if (key === last) return;
    last = key;
    wing(farWing, -1, w);
    wing(nearWing, 1, w);
    const ch = Math.cos(rad(h)), sh = Math.sin(rad(h));
    const xf = (x, y, z) => { const dx = x - 16, dz = z - 26; return P(16 + dx * ch + dz * sh, y, 26 - dx * sh + dz * ch); };
    head.setAttribute("d", poly(hull(ell(20, 0, 40, 9, 8, 9, 0, xf).concat(ell(18, 0, 28, 7, 7, 6, 0, xf)))));
    beak.setAttribute("d", poly(hull(ell(31, 0, 38, 6, 4, 2.2, 0, xf))));
    eye.setAttribute("d", poly(circ(1.4, 12).map((q) => xf(23 + q.u, 7.6, 43 + q.v))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(st.w, now), tval(st.h, now)); return !tdone(st.w, now) || !tdone(st.h, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    const now = performance.now();
    tset(st.w, v ? -58 + 150 * reach : -58, now, 0);
    tset(st.h, v ? 26 * reach : 0, now, v ? 60 : 0);
    farWing.classList.toggle("hi", v); nearWing.classList.toggle("hi", v); beak.classList.toggle("hi", !v);
    read.textContent = v ? "flap " + Math.round(92 * reach) + "°" : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); setOn(x > -50 && x < 56 && Math.abs(y) < 40); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; const o = on; on = null; setOn(o); }, destroy: bag.dispose };
}

hairline({
  name: "pullduck",
  means: "A wooden pull-along duck on wheels: over it, both wings swing up off its sides and its head dips, as when it is pulled.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[194, 144], [230, 190], [160, 175], null],
  mount,
});

stereoviewer.code:
/**
 * Stereo viewer: a toy picture viewer, two eyepieces on its face, a picture
 * reel standing in the slot on top and an advance lever on its side. Over
 * it, the lever clicks down and the reel rises out of the slot, turning its
 * ring of slides round. At rest the reel sits low and the lever is bright.
 * The slider is how far the reel rises and turns.
 *
 * The pattern: one object, one gesture (a tween on the hover).
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, seg, unproj, tset, tval, tdone, tween, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const ZT = 30, RR = 22, RC = 34, N = 7;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 3.05);
  fit(C, [[-32, -14, 0], [34, 20, 0], [34, -14, 0], [-32, 20, 0], [0, 0, RC + RR + 28], [-22, 0, RC + 28], [22, 0, RC + 28]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [o, i] = rings(-30, -12, 30, 12, 7, 1.8);
  put(solid(g), prism(P, front, o, i, 0, ZT));
  mk("path", { d: seg(P(-RR - 2, 0, ZT), P(RR + 2, 0, ZT)), class: "nf lo" }, g);
  const reel = mk("g", {}, g);
  const leverG = mk("g", {}, g);
  for (const x of [-13, 13]) {
    const pts = [];
    for (const y of [12, 18]) for (const q of circ(6, 24)) pts.push(P(x + q.u, y, 15 + q.v));
    mk("path", { d: poly(hull(pts)), class: "sil" }, g);
    mk("path", { d: poly(circ(3.6, 20).map((q) => P(x + q.u, 18, 15 + q.v))), class: "nf lo" }, g);
  }
  const st = { h: tween(3), a: tween(8) };
  let last = "", act = null;
  const disc = (cx, cz, r, n, z0) => circ(r, n).map((q) => [cx + q.u, cz + q.v]).filter(([, z]) => z >= z0);
  function draw(h, a) {
    const key = h.toFixed(2) + a.toFixed(2);
    if (key === last) return;
    last = key;
    reel.replaceChildren(); leverG.replaceChildren();
    const cz = RC + h, half = Math.sqrt(Math.max(0, RR * RR - (ZT - cz) ** 2));
    const rim = disc(0, cz, RR, 64, ZT).map(([x, z]) => P(x, 0, z)).concat([P(-half, 0, ZT), P(half, 0, ZT)]);
    const rs = mk("path", { d: poly(hull(rim)), class: "sil" }, reel);
    const turn = rad(h * 12);
    for (let k = 0; k < N; k++) {
      const t = turn + (k / N) * Math.PI * 2, wx = 15 * Math.cos(t), wz = cz + 15 * Math.sin(t);
      if (wz - 3.6 < ZT + 0.5) continue;
      mk("path", { d: poly(circ(3.4, 14).map((q) => P(wx + q.u, 0, wz + q.v))), class: "nf lo" }, reel);
    }
    if (cz - 3 > ZT) mk("path", { d: poly(circ(2.6, 14).map((q) => P(q.u, 0, cz + q.v))), class: "nf" }, reel);
    const ca = Math.cos(rad(a)), sa = Math.sin(rad(a)), ey = 16 * ca, ez = 24 + 16 * sa, pts = [];
    for (const x of [30, 33]) for (const [y, z, r] of [[0, 24, 3.4], [ey, ez, 2.4]]) for (const q of circ(r, 14)) pts.push(P(x, y + q.u, z + q.v));
    const lv = mk("path", { d: poly(hull(pts)), class: "sil" }, leverG);
    (act ? rs : lv).classList.add("hi");
  }
  const B = register(stage, (_dt, now) => { draw(tval(st.h, now), tval(st.a, now)); return !tdone(st.h, now) || !tdone(st.a, now); });
  bag.add(B.unregister);
  function setOn(v) {
    if (v === act) return;
    act = v; last = "";
    const now = performance.now();
    tset(st.a, v ? 8 - 52 * reach : 8, now, 0);
    tset(st.h, v ? 3 + 14.5 * reach : 3, now, v ? 80 : 0);
    read.textContent = v ? "slide " + (1 + Math.round(6 * reach)) : "rest";
    B.wake();
  }
  setOn(false);
  bag.add(pointer(stage, {
    move: (p) => { const [x, y] = unproj(C, p[0], p[1], 0); setOn(x > -50 && x < 54 && y > -40 && y < 40); },
    leave: () => setOn(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; const o2 = act; act = null; setOn(o2); }, destroy: bag.dispose };
}

hairline({
  name: "stereoviewer",
  means: "A toy stereo picture viewer: over it, the side lever clicks down and the picture reel rises from its slot, turning its slides.",
  rules: [1, 3, 5, 8],
  range: [0.3, 0.8, 1],
  tour: [[204, 171], [230, 200], [175, 190], null],
  mount,
});

metalshear.code:
/**
 * Bench shear: a cast body bolted to a base plate, a fixed lower blade along
 * its front and a long lever pinned at the back that carries the upper blade.
 * Over the shear the lever swings down and the upper blade closes past the
 * lower one. At rest the lever stands raised, bright. The slider is how far
 * the lever travels.
 */
const { Cam, clamp, facing, fit, hull, poly, prism, proj, rad, rings, seg, unproj, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid } = HL;

function box(g) { const grp = mk("g", {}, g); return { g: grp, sil: mk("path", { class: "sil" }, grp), cr: mk("path", { class: "nf lo" }, grp) }; }
function drawBox(P, el, b, T) {
  const [x0, x1, y0, y1, z0, z1] = b, pts = [];
  for (const x of [x0, x1]) for (const y of [y0, y1]) for (const z of [z0, z1]) pts.push(P(...T([x, y, z])));
  el.sil.setAttribute("d", poly(hull(pts)));
  el.cr.setAttribute("d", poly([[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]].map((p) => P(...T(p)))));
}
const ID = (p) => p;
const PX = 8, PZ = 30, UP = 42, L = 86;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let travel = 14 + 30 * value;
  const C = Cam(45, 0.5, 2.5);
  const tip = (a) => [PX + L * Math.cos(rad(a)), 0, PZ + L * Math.sin(rad(a))];
  fit(C, [[-4, -2, 0], [62, 36, 0], [PX + L * Math.cos(rad(UP)), 18, PZ + 4 + L * Math.sin(rad(UP))], [PX + L, 18, PZ], [PX + 64, 36, 0]], 200, 165);
  const P = proj(C), front = facing(C), g = mk("g", {}, svg);
  const base = solid(g);
  const [br, bi] = rings(-4, -2, 62, 36, 5, 1.6);
  put(base, prism(P, front, br, bi, 0, 5));
  const body = box(g), arm = box(g), blade = box(g), lower = box(g), sheet = box(g);
  drawBox(P, body, [0, 18, 8, 24, 5, PZ + 2], ID);
  drawBox(P, lower, [10, 52, 22, 25, 5, 20], ID);
  drawBox(P, sheet, [30, 58, 25, 34, 5, 6.2], ID);
  const T = (a) => {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    return ([dx, y, dz]) => [PX + dx * c - dz * s, y, PZ + dx * s + dz * c];
  };
  const ang = tween(UP);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const t = T(a);
    drawBox(P, blade, [4, 44, 19, 22, -14, 0], t);
    drawBox(P, arm, [-6, L, 15, 21, 0, 5], t);
  }
  draw(UP);
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    return x > -10 && x < 100 && y > -10 && y < 44;
  }
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(ang, on ? UP - travel : UP, performance.now(), 0);
    arm.sil.classList.toggle("hi", true);
    read.textContent = on ? "cut" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { travel = clamp(14 + 30 * v, 14, 44); if (act) { tset(ang, UP - travel, performance.now(), 0); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "metalshear",
  means: "A bench shear: over it the long lever swings down on its pin and the upper blade closes past the fixed one.",
  rules: [1, 3, 5],
  range: [0, 0.6, 1],
  tour: [[188, 250], [170, 208], [135, 177], null],
  mount,
});

dustextractor.code:
/**
 * Dust extractor: a drum on four casters with a hose port on its side and a
 * lid on top carrying the motor dome. The lid is hinged at the back; the
 * pointer's height over the extractor tips it open on a spring, the motor
 * dome riding with it. At rest the lid sits a little ajar, its rim bright.
 *
 * The pattern: one part following a continuous input (hinge).
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, clamp, rad, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const REST = 0.15, R = 26, CX = 30, CY = 30, DZ = 50, HX = CX - R - 1, MAXA = 62;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.55);
  fit(C, [[0, 0, 0], [60, 60, 0], [60, 0, 0], [0, 60, 0], [-20, 30, 92], [30, 30, 100], [70, 70, 30]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const caster = (x, y) => put(solid(g), prism(P, front, disc(x, y, 3.5, 16), disc(x, y, 2.5, 16), 0, 6));
  caster(CX - 18, CY - 18); caster(CX + 18, CY - 18); caster(CX - 18, CY + 18);
  put(solid(g), prism(P, front, disc(CX, CY, R, 40), disc(CX, CY, R - 2.4, 40), 6, DZ));
  caster(CX + 18, CY + 18);
  const pc = [CX + R * 0.62, CY + R * 0.85, 30], px = 0.62, py = 0.85;
  const port = [];
  for (const L of [-2, 12]) for (let i = 0; i < 20; i++) {
    const a = (i / 20) * 2 * Math.PI, c = 6 * Math.cos(a), s = 6 * Math.sin(a);
    port.push(P(pc[0] + px * L + py * c * 0.8, pc[1] + py * L - px * c * 0.8, pc[2] + s));
  }
  mk("path", { d: poly(hull(port)), class: "sil" }, g);
  const ring12 = [];
  for (let i = 0; i < 20; i++) { const a = (i / 20) * 2 * Math.PI; ring12.push(P(pc[0] + px * 12 + py * 4.4 * Math.cos(a) * 0.8, pc[1] + py * 12 - px * 4.4 * Math.cos(a) * 0.8, pc[2] + 4.4 * Math.sin(a))); }
  mk("path", { d: poly(ring12), class: "nf lo" }, g);
  const lid = solid(g), dome = solid(g), cap = solid(g);
  const sp = spring(REST);
  let last = NaN;
  const tilt = (ring, z, a) => ring.map((q) => { const dx = q.u - HX, dz = z - DZ; return P(HX + dx * Math.cos(a) - dz * Math.sin(a), q.v, DZ + dx * Math.sin(a) + dz * Math.cos(a)); });
  const body = (s, r, z0, z1, a) => { s.sil.setAttribute("d", poly(hull(tilt(disc(CX, CY, r), z0, a).concat(tilt(disc(CX, CY, r), z1, a))))); s.cr.setAttribute("d", poly(tilt(disc(CX, CY, r - 2), z1, a))); };
  function draw() {
    const v = sp.x;
    if (v === last) return;
    last = v;
    const a = rad(v * MAXA * reach / 100);
    body(lid, R + 1.5, DZ, DZ + 7, a);
    body(dome, 18, DZ + 7, DZ + 26, a);
    body(cap, 9, DZ + 26, DZ + 30, a);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const yT = P(CX, CY, DZ + 40)[1], yB = P(CX, CY, 10)[1], xs = [P(0, 60, 0)[0] - 10, P(60, 0, 0)[0] + 20];
  let state = "";
  function set(p) {
    let t = REST, on = false;
    if (p && p[0] > xs[0] && p[0] < xs[1] && p[1] > yT - 40 && p[1] < yB + 30) { t = clamp((yB - p[1]) / (yB - yT), 0, 1); on = true; }
    sp.t = t;
    const s = on ? Math.round(t * MAXA * reach / 100) + "°" : "rest";
    if (s !== state) { state = s; read.textContent = s; }
    B.wake();
  }
  lid.sil.classList.add("hi");
  set(null);
  draw();
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "dustextractor",
  means: "A dust extractor drum on casters: the pointer's height tips the hinged lid and motor dome open off the drum.",
  rules: [1, 3, 5, 8],
  range: [30, 100, 100],
  tour: [[200, 200], [200, 140], [200, 108], null],
  mount,
});

jointer.code:
/**
 * Jointer: a long base carrying a lower infeed table and an outfeed table with
 * the cutterhead gap between them, a tall fence standing along the back and
 * a pork-chop guard over the gap. The pointer's height over the jointer tilts
 * the fence in over the tables on a spring, and the guard swings aside with
 * it. At rest the fence leans in a little, bright.
 *
 * The pattern: one part following a continuous input (tilt).
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, rad, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const REST = 0.12, TZ = 22, MAXA = 45;
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.25);
  fit(C, [[0, -6, 0], [130, 32, 0], [0, 32, 0], [130, -6, 0], [30, -6, TZ + 34], [100, -6, TZ + 34], [80, 50, TZ]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b) => { const [a, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, a, i, z0, z1)); return s; };
  box(6, 4, 124, 26, 0, TZ - 8, 4, 1.6);
  box(0, 0, 61, 30, TZ - 8, TZ - 1.5, 3, 1.4);
  box(67, 0, 130, 30, TZ - 8, TZ, 3, 1.4);
  const guard = solid(g), fence = solid(g);
  const gOut = rrect(-5, -26, 9, 2, 6, 6), gIn = rrect(-3.6, -24.6, 7.6, 0.6, 4.6, 6);
  const fOut = rrect(28, 0, 102, 30, 4, 6), fIn = rrect(29.6, 1.6, 100.4, 28.4, 2.6, 6);
  const sp = spring(REST);
  let last = NaN;
  const lean = (ring, y, a) => ring.map((q) => { const dy = y + 1, dz = q.v; return P(q.u, -1 + dy * Math.cos(a) + dz * Math.sin(a), TZ - dy * Math.sin(a) + dz * Math.cos(a)); });
  const swing = (ring, z, b) => ring.map((q) => P(64 + q.u * Math.cos(b) - q.v * Math.sin(b), 30 + q.u * Math.sin(b) + q.v * Math.cos(b), z));
  function draw() {
    const v = sp.x;
    if (v === last) return;
    last = v;
    const k = v * reach / 100, a = rad(k * MAXA), b = rad(k * 80);
    guard.sil.setAttribute("d", poly(hull(swing(gOut, TZ + 0.5, b).concat(swing(gOut, TZ + 3, b)))));
    guard.cr.setAttribute("d", poly(swing(gIn, TZ + 3, b)));
    fence.sil.setAttribute("d", poly(hull(lean(fOut, -5, a).concat(lean(fOut, -1, a)))));
    fence.cr.setAttribute("d", poly(lean(fIn, -1, a)));
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const yT = P(65, -3, TZ + 30)[1], yB = P(65, 15, 0)[1], xs = [P(0, 32, 0)[0] - 10, P(130, -6, 0)[0] + 10];
  let state = "";
  function set(p) {
    let t = REST, on = false;
    if (p && p[0] > xs[0] && p[0] < xs[1] && p[1] > yT - 40 && p[1] < yB + 30) { t = clamp((yB - p[1]) / (yB - yT), 0, 1); on = true; }
    sp.t = t;
    const s = on ? Math.round(t * MAXA * reach / 100) + "°" : "rest";
    if (s !== state) { state = s; read.textContent = s; }
    B.wake();
  }
  fence.sil.classList.add("hi");
  set(null);
  draw();
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

