  means: "A burr coffee grinder: the hopper lifts off its dial collar and turns, and the dial's tick turns with it.",
  rules: [1, 4, 5, 6],
  range: [10, 18, 26],
  tour: [[200, 141], [214, 110], [186, 172], null],
  mount,
