fogmachine.code:
/**
 * Fog machine: a rounded box on two skids with a carry handle, and on its
 * front face a short nozzle. The pointer over the machine fires it: a cloud
 * of round puffs rolls out of the nozzle, each further out bigger and higher.
 * At rest a small puff hangs at the nozzle, bright. The slider is how far
 * the cloud rolls out.
 *
 * The pattern: one part answering (a push on the discrete clock); the hit is
 * on the machine's rest box, which never moves.
 */
const {
  Cam, clamp, facing, fit, hull, poly, prism, proj, rings, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 6, BT = 32, NZ = 18, NR = 5.5, N = 5, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = clamp(value, 36, 64);
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-30, -20, 0], [30, 20, 0], [30, -20, 0], [-30, 20, 0], [-10, 0, 46], [146, -8, 40], [120, 0, NZ + 46]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // skids, body, handle posts and bar
  for (const y of [-14, 10]) { const [r, i] = rings(-26, y, 26, y + 4, 1.8, 0.7); put(solid(g), prism(P, front, r, i, 0, BZ)); }
  const [br, bi] = rings(-28, -18, 28, 18, 7, 1.5);
  put(solid(g), prism(P, front, br, bi, BZ, BT));
  for (const x of [-16, 12]) { const [r, i] = rings(x, -2, x + 4, 2, 1.6, 0.6); put(solid(g), prism(P, front, r, i, BT, BT + 9)); }
  const [hr, hi] = rings(-17, -2.5, 17, 2.5, 2.4, 0.8);
  put(solid(g), prism(P, front, hr, hi, BT + 9, BT + 13));
  // a vent grille on the near side
  for (let k = 0; k < 4; k++) mk("path", { class: "nf lo", d: "M" + P(-18 + k * 6, 18, BZ + 7) + "L" + P(-18 + k * 6, 18, BT - 7) }, g);

  // the nozzle: a short horizontal can out of the front face, along +x
  const ringX = (x, r, cy, cz) => Array.from({ length: 28 }, (_, i) => { const a = (i / 28) * Math.PI * 2; return P(x, cy + r * Math.cos(a), cz + r * Math.sin(a)); });
  mk("path", { class: "sil", d: poly(hull(ringX(26, NR + 1.5, 0, NZ).concat(ringX(31, NR + 1.5, 0, NZ)))) }, g);
  mk("path", { class: "sil", d: poly(hull(ringX(30, NR, 0, NZ).concat(ringX(42, NR - 1, 0, NZ)))) }, g);
  mk("path", { class: "nf lo", d: poly(ringX(42, NR - 2.4, 0, NZ)) }, g);

  // the puffs, far to near
  const puffs = Array.from({ length: N }, () => mk("path", { class: "sil" }, g));
  puffs[0].classList.add("hi");
  function sphere(c, r) {
    const o = P(c[0], c[1], c[2]), e = P(c[0] + r * 0.7071, c[1] - r * 0.7071, c[2]), R = Math.hypot(e[0] - o[0], e[1] - o[1]);
    return poly(Array.from({ length: 40 }, (_, i) => { const a = (i / 40) * Math.PI * 2; return [o[0] + R * Math.cos(a), o[1] + R * Math.sin(a)]; }));
  }
  const tw = tween(REST);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    for (let j = 0; j < N; j++) {
      const f = (j + 1) / N, r = 4.5 + f * d * 0.3;
      const c = [46 + f * d + j * 2, (j % 2 ? 1 : -1) * f * 5, NZ + f * d * 0.32];
      puffs[j].setAttribute("d", sphere(c, r));
    }
  }

  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);

  // the hit: the machine and its cloud, as a rest box on screen
  const a0 = P(-30, 20, 0), a1 = P(30, -20, BT + 13), a2 = P(100, 0, NZ);
  function hit([sx, sy]) {
    return sx > a0[0] - 10 && sx < a2[0] + 20 && sy > a1[1] - 20 && sy < a0[1] + 30 ? 1 : -1;
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(tw, a < 0 ? REST : reach, performance.now(), 0);
    read.textContent = a < 0 ? "rest" : "fog " + Math.round(reach);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp(v, 36, 64); setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "fogmachine",
  means: "A fog machine: the pointer fires it, and a cloud of round puffs rolls out of the nozzle, growing as it goes.",
  rules: [1, 3, 5, 6],
  range: [36, 50, 64],
  tour: [[103, 127], [160, 190], [234, 220], null],
  mount,
});

movinghead.code:
/**
 * Moving head light: a square base with a turntable, a U-shaped yoke that
 * pans on it, and between the yoke's arms a round head with a wide lens that
 * tilts. The pointer over the light swings it: the yoke pans away across the
 * room and the head tilts up. At rest it faces us, lens bright, dipped a
 * little. The slider is how far the head tilts up.
 *
 * The pattern: one part answering (a pan and tilt on the discrete clock);
 * the hit is on the light's rest box, which never moves.
 */
const {
  Cam, circ, clamp, facing, fit, hull, lerp, poly, prism, proj, rad, rings, rrect, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BT = 14, YB = 18, AZ = 60, PZ = 44, PAN0 = 45, PAN1 = 5, T0 = -12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let tiltMax = clamp(value, 35, 80);
  const C = Cam(45, 0.5, 2.95);
  fit(C, [[-22, -22, 0], [22, 22, 0], [22, -22, 0], [-22, 22, 0], [-26, -26, AZ + 4], [26, 26, PZ], [0, 0, PZ + 22]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the base, its turntable
  const [br, bi] = rings(-22, -22, 22, 22, 7, 1.5);
  put(solid(g), prism(P, front, br, bi, 0, BT));
  mk("path", { class: "nf lo", d: "M" + P(22, -12, BT / 2) + "L" + P(22, 12, BT / 2) }, g);
  put(solid(g), prism(P, front, circ(15, 48), circ(13.6, 48), BT, YB));

  // the moving parts: yoke foot, two arms, the head between them
  const yg = mk("g", {}, g);
  const foot = solid(yg), armA = solid(yg), armB = solid(yg);
  const head = mk("g", {}, yg);
  const body = mk("path", { class: "sil" }, head), lens = mk("path", { class: "nf hi" }, head), lensIn = mk("path", { class: "nf lo" }, head);
  const turn = (ring, th) => ring.map((q) => {
    const c = Math.cos(th), s = Math.sin(th);
    return { u: q.u * -s + q.v * c, v: q.u * c + q.v * s, nu: q.nu * -s + q.nv * c, nv: q.nu * c + q.nv * s };
  });
  const footR = [rrect(-19, -7, 19, 7, 5, 4), rrect(-17.6, -5.6, 17.6, 5.6, 3.6, 4)];
  const armR = (s) => [rrect(s * 13 - 2.5, -7, s * 13 + 2.5, 7, 2.4, 4), rrect(s * 13 - 1.7, -6.2, s * 13 + 1.7, 6.2, 1.6, 4)];
  const ringsA = armR(1), ringsB = armR(-1);

  function draw(t) {
    const th = rad(lerp(PAN0, PAN1, t)), ti = rad(lerp(T0, tiltMax, t));
    put(foot, prism(P, front, turn(footR[0], th), turn(footR[1], th), YB, YB + 5));
    put(armA, prism(P, front, turn(ringsA[0], th), turn(ringsA[1], th), YB + 5, AZ));
    put(armB, prism(P, front, turn(ringsB[0], th), turn(ringsB[1], th), YB + 5, AZ));
    const sv = [-Math.sin(th), Math.cos(th), 0], w = [Math.cos(th), Math.sin(th), 0];
    const d = [w[0] * Math.cos(ti), w[1] * Math.cos(ti), Math.sin(ti)];
    const v = [sv[1] * d[2] - sv[2] * d[1], sv[2] * d[0] - sv[0] * d[2], sv[0] * d[1] - sv[1] * d[0]];
    const ring = (off, r) => Array.from({ length: 32 }, (_, i) => {
      const a = (i / 32) * Math.PI * 2, q = (j) => [0, 0, PZ][j] + d[j] * off + r * (Math.cos(a) * sv[j] + Math.sin(a) * v[j]);
      return P(q(0), q(1), q(2));
    });
    const back = ring(-12, 8.5), mid = ring(4, 10.5), lensR = ring(14, 10.5);
    body.setAttribute("d", poly(hull(back.concat(mid, lensR))));
    lens.setAttribute("d", poly(lensR));
    lensIn.setAttribute("d", poly(ring(14, 7)));
    // paint order: the far arm, the head, the near arm
    const sA = Math.cos(th) + -Math.sin(th);
    if (sA > 0) { yg.append(armB.g, head, armA.g); } else { yg.append(armA.g, head, armB.g); }
  }

  const tw = tween(0);
  let last = NaN;
  const B = register(stage, (_dt, now) => { const t = tval(tw, now); if (t !== last) { last = t; draw(t); } return !tdone(tw, now); });
  bag.add(B.unregister);

  const c0 = P(0, 0, 0), c1 = P(0, 0, AZ);
  function hit([sx, sy]) { return Math.abs(sx - c0[0]) < 95 && sy > c1[1] - 40 && sy < c0[1] + 35 ? 1 : -1; }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    act = a;
    tset(tw, a < 0 ? 0 : 1, performance.now(), 0);
    if (force) last = NaN;
    read.textContent = a < 0 ? "rest" : "tilt " + Math.round(tiltMax);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { tiltMax = clamp(v, 35, 80); setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "movinghead",
  means: "A moving head light: the pointer swings it, the yoke panning away on its base and the head tilting its lens up.",
  rules: [1, 3, 5, 6],
  range: [35, 60, 80],
  tour: [[200, 138], [150, 210], [260, 240], null],
  mount,
});

milkshakemixer.code:
/**
 * Milkshake mixer: a diner spindle mixer, a heavy base, a column at the back,
 * a rounded motor head reaching forward, the spindle hanging from it with its
 * agitator disc, and a tall steel cup pushed up around the spindle. The
 * pointer over the mixer tilts the cup off the spindle on its front bottom
 * edge, showing the spindle and disc. At rest the cup leans a little, bright.
 * The slider is how far the cup tilts.
 *
 * The pattern: one part tilts on a pivot; the hit is the rest pose's box.
 */
const {
  Cam, circ, clamp, fit, facing, hull, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 5, CX = 15, CY = 27, RB = 6.5, RT = 9, CH = 34, HZ0 = 52, HZ1 = 62, REST = 5;
const YP = CY + RB;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = value;
  const C = Cam(45, 0.5, 3.3);
  const ext = [[0, 0, 0], [30, 0, 0], [0, 46, 0], [30, 46, 0], [6, 0, HZ1], [24, 37, HZ1], [CX, 66, 22], [CX - RT, 62, 32], [CX + RT, 62, 32]];
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the base, the column at the back and the motor head reaching forward
  const [br, bi] = rings(0, 0, 30, 46, 7, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [cr, ci] = rings(10, 2, 20, 11, 4, 1.2);
  put(solid(g), prism(P, front, cr, ci, BZ, HZ0 + 2));
  const [hr, hi] = rings(5, 1, 25, 37, 8, 1.6);
  const head = solid(g);
  put(head, prism(P, front, hr, hi, HZ0, HZ1));
  mk("path", { class: "nf lo", d: seg(P(25, 18, HZ0 + 3), P(25, 30, HZ0 + 3)) }, head.g);

  // the spindle and its agitator disc
  const disc = circ(2.6, 20).map((q) => P(CX + q.u, CY + q.v, BZ + 20));
  const spin = solid(g);
  spin.sil.setAttribute("d", poly(hull(disc.concat(circ(2.6, 20).map((q) => P(CX + q.u, CY + q.v, BZ + 21.4))))));
  mk("path", { class: "nf", d: seg(P(CX, CY, HZ0), P(CX, CY, BZ + 21.4)) }, g);

  // the cup: a tapered steel tumbler, tilting on its front bottom edge
  const cup = solid(g);
  cup.sil.classList.add("hi");
  const ringPts = (r, z, t) => circ(r, 28).map((q) => {
    const dy = CY + q.v - YP, dz = z;
    return P(CX + q.u, YP + dy * Math.cos(t) + dz * Math.sin(t), BZ - dy * Math.sin(t) + dz * Math.cos(t));
  });
  let last = NaN;
  function drawCup(deg) {
    if (deg === last) return;
    last = deg;
    const t = (deg * Math.PI) / 180;
    cup.sil.setAttribute("d", poly(hull(ringPts(RB, 0, t).concat(ringPts(RT, CH, t)))));
    cup.cr.setAttribute("d", poly(ringPts(RT - 1, CH, t)));
  }

  const tilt = tween(REST);
  const B = register(stage, (_dt, now) => { drawCup(tval(tilt, now)); return !tdone(tilt, now); });
  bag.add(B.unregister);

  // the hit: the screen box of the mixer's rest and tilted poses, which never moves
  const sp = ext.map((p) => P(...p));
  const bx = [Math.min(...sp.map((p) => p[0])), Math.max(...sp.map((p) => p[0])), Math.min(...sp.map((p) => p[1])), Math.max(...sp.map((p) => p[1]))];
  const hit = ([x, y]) => x > bx[0] - 4 && x < bx[1] + 4 && y > bx[2] - 4 && y < bx[3] + 4;

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tilt, on ? clamp(maxT, 0, 60) : REST, performance.now(), 0);
    read.textContent = on ? "tilt" : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "milkshakemixer",
  means: "A diner spindle mixer: over it, the steel cup tilts off the spindle on its front edge, baring the agitator.",
  rules: [1, 4, 5, 8],
  range: [20, 40, 60],
  tour: [[181, 155], [236, 82], [258, 240], null],
  mount,
});

confetti.code:
/**
 * Confetti cannon: a squat base with a long barrel on a pivot. The pointer
 * aims it: the barrel tilts up toward the pointer's height and swings toward
 * its side, on a spring, and the confetti at the mouth spreads further the
 * higher it points. At rest the barrel leans low, bright. The slider is how
 * far the barrel can tilt.
 *
 * The pattern: a continuous aim on one part; the hit is the screen point,
 * read against a fixed frame, never the moving barrel.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PIV = [0, 0, 22], BACK = 14, LEN = 70, R0 = 8, R1 = 11, REST_E = 18, REST_A = -90;
const BITS = [[0, 0], [1, 1.2], [-1, 0.8], [0.6, -1], [-0.7, -1.3], [1.4, -0.2], [-1.3, 0.3]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[-22, -22, 0], [22, 22, 0], [0, -LEN, 30], [0, -20, PIV[2] + 62], [-30, -40, 50], [30, -40, 50]], 200, 200);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-20, -20, 20, 20, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 10));
  const [kr, ki] = rings(-9, -9, 9, 9, 4, 1.2);
  put(solid(g), prism(P, front, kr, ki, 10, PIV[2] - 4));
  const body = mk("path", { class: "sil hi" }, g), mouth = mk("path", { class: "nf" }, g), band = mk("path", { class: "nf lo" }, g);
  const bits = BITS.map(() => mk("ellipse", { class: "dot m", rx: 1.8, ry: 1.2 }, g));
  const el = spring(REST_E), az = spring(REST_A);
  let last = "";

  function basis(d) {
    let u = [d[1], -d[0], 0];
    const un = Math.hypot(...u) || 1; u = u.map((x) => x / un);
    const v = [u[1] * d[2] - u[2] * d[1], u[2] * d[0] - u[0] * d[2], u[0] * d[1] - u[1] * d[0]];
    return [u, v];
  }
  function ring(d, u, v, off, r, n = 28) {
    return Array.from({ length: n }, (_, i) => {
      const t = (i / n) * Math.PI * 2, q = (j) => PIV[j] + d[j] * off + r * (Math.cos(t) * u[j] + Math.sin(t) * v[j]);
      return P(q(0), q(1), q(2));
    });
  }
  function draw() {
    const key = el.x.toFixed(2) + "," + az.x.toFixed(2);
    if (key === last) return;
    last = key;
    const e = rad(el.x), a = rad(az.x);
    const d = [Math.cos(e) * Math.cos(a), Math.cos(e) * Math.sin(a), Math.sin(e)];
    const [u, v] = basis(d);
    const back = ring(d, u, v, -BACK, R0), tip = ring(d, u, v, LEN - BACK, R1);
    body.setAttribute("d", poly(hull(back.concat(tip))));
    mouth.setAttribute("d", poly(tip));
    band.setAttribute("d", poly(ring(d, u, v, 0, R0 + 1.5)));
    const spread = 6 + (el.x - REST_E) * 0.5;
    bits.forEach((b, k) => {
      const [p, q] = BITS[k], off = LEN - BACK + 5 + spread * (0.5 + 0.25 * ((k * 3) % 4));
      const s = (j) => PIV[j] + d[j] * off + (spread * 0.35) * (p * u[j] + q * v[j]);
      const pt = P(s(0), s(1), s(2));
      b.setAttribute("cx", pt[0]); b.setAttribute("cy", pt[1]);
    });
  }

  const B = register(stage, (dt) => {
    const m1 = stepS(el, dt), m2 = stepS(az, dt);
    draw();
    return m1 || m2;
  });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { el.t = REST_E; az.t = REST_A; read.textContent = "rest"; B.wake(); return; }
    const fy = clamp((250 - p[1]) / 190, 0, 1), fx = clamp((p[0] - 200) / 160, -1, 1);
    el.t = REST_E + amp * (0.45 + 0.55 * fy);
    az.t = REST_A + fx * 30;
    read.textContent = "tilt " + Math.round(el.t) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

hairline({
  name: "confetti",
  means: "A confetti cannon on a pivot: the barrel tilts up and swings toward the pointer, and the confetti at its mouth spreads further.",
  rules: [1, 3, 4, 5, 8],
  range: [24, 34, 44],
  tour: [[191,185], [226,151], [209,117], null],
  mount,
});

rotarycutter.code:
/**
 * Rotary cutter: a fabric rotary cutter standing on a cutting mat, a long
 * handle raked back from a round blade, the blade half covered by its guard.
 * The pointer over it swings the guard back off the blade and rolls the
 * cutter forward along the mat. At rest the guard is bright. The slider is
 * how far it rolls.
 */
const { Cam, fit, hull, poly, proj, rrect, seg, tween, tset, tval, tdone, unproj, disposer, mk, pointer, register } = HL;

const rz = (a) => ([x, y, z]) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a), z];
const pitch = (a) => ([x, y, z]) => [x * Math.cos(a) - z * Math.sin(a), y, x * Math.sin(a) + z * Math.cos(a)];
const tr = (dx, dy, dz) => ([x, y, z]) => [x + dx, y + dy, z + dz];
const chain = (...fs) => (p) => fs.reduce((q, f) => f(q), p);
const D = Math.PI / 180, BASE = -12 * D, R = 17, H = R + 1.5;
const arc = (r, a0, a1, n) => Array.from({ length: n + 1 }, (_, i) => { const a = (a0 + (a1 - a0) * i / n) * D; return [r * Math.cos(a), r * Math.sin(a)]; });

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let roll = value;
  const C = Cam(45, 0.5, 2.25);
  const W = rz(BASE);
  fit(C, [[-80, -30, 0], [70, 30, 0], [-80, 30, 0], [70, -30, 0], [-60, 0, 56], [40, 0, 56]].map(W), 200, 160);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const mat = mk("path", { class: "sil" }, g), matCr = mk("path", { class: "nf lo" }, g), cut = mk("path", { class: "nf dash" }, g);
  const mring = rrect(-80, -30, 70, 30, 6), mi = rrect(-78, -28, 68, 28, 4);
  mat.setAttribute("d", poly(hull(mring.map((q) => P(...W([q.u, q.v, -2]))).concat(mring.map((q) => P(...W([q.u, q.v, 0])))))));
  matCr.setAttribute("d", poly(mi.map((q) => P(...W([q.u, q.v, 0])))));
  const handle = mk("path", { class: "sil" }, g), hcr = mk("path", { class: "nf lo" }, g);
  const blade = mk("path", { class: "sil" }, g), hub = mk("path", { class: "nf lo" }, g);
  const guard = mk("path", { class: "sil hi" }, g), knob = mk("path", { class: "nf" }, g);
  const pose = tween(0);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    const x0 = -30 + roll * o, at = (p) => P(...W(tr(x0, 0, H)(p)));
    cut.setAttribute("d", o > 0.01 ? seg(P(...W([-30, 7, 0.1])), P(...W([x0, 7, 0.1]))) : "");
    // handle: a rounded bar raked back and up from the hub
    const hr = rrect(-68, -5.5, 2, 5.5, 5.5), Th = (q, z) => at(pitch(-38 * D)([q.u, q.v, z]));
    handle.setAttribute("d", poly(hull(hr.map((q) => Th(q, -5)).concat(hr.map((q) => Th(q, 5))))));
    hcr.setAttribute("d", poly(rrect(-65, -3.5, -14, 3.5, 3.5).map((q) => Th(q, 5))));
    const disk = (r, y, a0 = 0, a1 = 360, n = 40) => arc(r, a0, a1, n).map(([u, v]) => at([u, y, v]));
    blade.setAttribute("d", poly(hull(disk(R, 6).concat(disk(R, 7.2)))));
    hub.setAttribute("d", poly(disk(5, 7.2, 0, 360, 20)));
    // guard: a half cover over the blade, swung back round the hub
    const ga = 15 + 130 * o, gpts = arc(R + 2, ga, ga + 180, 24).concat(arc(4, ga + 180, ga, 8));
    guard.setAttribute("d", poly(hull(gpts.map(([u, v]) => at([u, 8, v])).concat(gpts.map(([u, v]) => at([u, 10, v]))))));
    knob.setAttribute("d", poly(hull(disk(3.5, 10, 0, 360, 16).concat(disk(3.5, 12.5, 0, 360, 16)))));
  }

  const B = register(stage, (_dt, now) => { draw(tval(pose, now)); return !tdone(pose, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(pose, a ? 1 : 0, performance.now(), 0);
    guard.classList.toggle("hi", !a);
    blade.classList.toggle("hi", a);
    read.textContent = a ? "cut " + Math.round(roll) : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0), [u, v] = rz(-BASE)([x, y, 0]);
    return u > -90 && u < 75 && Math.abs(v) < 40;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { roll = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "rotarycutter",
  means: "A rotary cutter on a cutting mat: the pointer over it swings the guard back off the round blade and rolls the cutter forward.",
  rules: [1, 3, 5, 8],
  range: [30, 50, 66],
  tour: [[154, 144], [190, 160], [120, 136], null],
  mount,
});

bobbinwinder.code:
/**
 * Bobbin winder: a small winder on a block base, a flanged bobbin on its
 * spindle and a stop arm on a post resting against the thread. The pointer
 * over it spins the bobbin, the thread builds up on it and pushes the stop
 * arm out round its post. At rest the bobbin is bright. The slider is how
 * far the arm swings out.
 *
 * The pattern: one part turning about a fixed axis, driven by a tween.
 */
const { Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, seg, tween, tset, tval, tdone, unproj, disposer, mk, pointer, put, register, solid, rrect } = HL;

const BX = 34, BY = 30, FR = 18, PX = 78, PY = 30, AL = 46, D = Math.PI / 180;
const disc = (x, y, r, n = 40) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[0, 0, 0], [100, 60, 0], [100, 0, 0], [0, 60, 0], [BX, BY, 46], [PX - 18, PY + 44, 30]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, 100, 60, 8, 2);
  put(solid(g), prism(P, front, br, bi, 0, 10));
  put(solid(g), prism(P, front, disc(BX, BY, 4, 16), disc(BX, BY, 3, 16), 10, 14));
  const low = solid(g), thread = solid(g), top = solid(g), spoke = mk("path", { class: "nf lo" }, g);
  for (const s of [low, thread, top]) s.sil.classList.add("hi");
  put(solid(g), prism(P, front, disc(PX, PY, 4, 16), disc(PX, PY, 3, 16), 10, 30));
  const arm = mk("path", { class: "sil" }, g), armCr = mk("path", { class: "nf lo" }, g);
  const pose = tween(0);
  let last = NaN;

  function draw(o) {
    if (o === last) return;
    last = o;
    const tr = 7 + 9 * o;
    put(low, prism(P, front, disc(BX, BY, FR), disc(BX, BY, FR - 2), 14, 17));
    put(thread, prism(P, front, disc(BX, BY, tr), disc(BX, BY, tr - 1), 17, 37));
    put(top, prism(P, front, disc(BX, BY, FR), disc(BX, BY, FR - 2), 37, 40));
    const sp = (o * 540 + 30) * D;
    spoke.setAttribute("d", seg(P(BX, BY, 40), P(BX + 13 * Math.cos(sp), BY + 13 * Math.sin(sp), 40)));
    // the stop arm: a bar from the post, its end on the thread
    const a = (180 - swing * o) * D, c = Math.cos(a), s = Math.sin(a);
    const T = (q, z) => P(PX + q.u * c - q.v * s, PY + q.u * s + q.v * c, z);
    const ar = rrect(-5, -4, AL - tr + 2, 4, 4, 4);
    arm.setAttribute("d", poly(hull(ar.map((q) => T(q, 24)).concat(ar.map((q) => T(q, 30))))));
    armCr.setAttribute("d", poly(rrect(-3, -2, AL - tr, 2, 2, 4).map((q) => T(q, 30))));
  }

  const B = register(stage, (_dt, now) => { draw(tval(pose, now)); return !tdone(pose, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(pose, a ? 1 : 0, performance.now(), 0);
    read.textContent = a ? "wind " + Math.round(swing) : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    const [u, v] = unproj(C, sx, sy, 40);
    return (x > -10 && x < 110 && y > -10 && y < 80) || Math.hypot(u - BX, v - BY) < FR + 4;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "bobbinwinder",
  means: "A bobbin winder: the pointer spins the bobbin, thread builds up on it and pushes the stop arm out round its post.",
  rules: [1, 3, 5, 8],
  range: [30, 60, 80],
  tour: [[174, 87], [210, 150], [150, 140], null],
  mount,
});

croquet.code:
/**
 * Croquet set: a mallet standing over its ball, a hoop on the lawn beyond. The
 * pointer draws the mallet back on its swing, further the further left it is,
 * and the part nearest the pointer is named and bright. At rest the ball is
 * bright and the mallet hangs just off true. The slider is how far it swings.
 *
 * The pattern: one part swinging on a pivot, driven by a spring.
 */
const { Cam, circ, clamp, fit, hull, poly, proj, spring, stepS, disposer, mk, pointer, register } = HL;

const REST = -10, PIV = [-10, 0, 74], HI = "ball";
const zcyl = (x, y, z0, z1, R, n = 24) => { const c = circ(R, n); return [c.map((p) => [x + p.u, y + p.v, z0]), c.map((p) => [x + p.u, y + p.v, z1])]; };
const xbar = (x0, x1, y, z, R, n = 28) => { const c = circ(R, n); return [c.map((p) => [x0, y + p.u, z + p.v]), c.map((p) => [x1, y + p.u, z + p.v])]; };
const ybar = (x, y0, y1, z, R, n = 20) => { const c = circ(R, n); return [c.map((p) => [x + p.u, y0, z + p.v]), c.map((p) => [x + p.u, y1, z + p.v])]; };
const ball = (x, y, R) => [0.1, 0.25, 0.4, 0.5, 0.6, 0.75, 0.9].map((f) => { const z = R + Math.cos(Math.PI * f) * -R, r = R * Math.sin(Math.PI * f); return circ(r, 32).map((p) => [x + p.u, y + p.v, z]); });
function PARTS() {
  return [
    { rings: zcyl(-10, 0, 12, 76, 1.8), name: "mallet", swing: true },
    { rings: xbar(-27, 7, 0, 6.5, 6.5), name: "mallet", swing: true, cr: 1 },
    { rings: ball(17, 0, 6.5), name: "ball", cr: 2 },
    { rings: zcyl(46, -12, 0, 22, 1.3), name: "hoop" },
    { rings: ybar(46, -12, 12, 22, 1.3), name: "hoop", cr: -1 },
    { rings: zcyl(46, 12, 0, 22, 1.3), name: "hoop" },
  ];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const parts = PARTS();
  const rot = (p, deg) => {
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a), dx = p[0] - PIV[0], dz = p[2] - PIV[2];
    return [PIV[0] + dx * c - dz * s, p[1], PIV[2] + dx * s + dz * c];
  };
  const ext = [];
  for (let d = 0; d >= -76; d -= 8) for (const pt of parts) for (const r of pt.rings) for (const p of r) ext.push(pt.swing ? rot(p, d) : p);
  const C1 = Cam(45, 0.5, 1); fit(C1, ext, 200, 166);
  const P1 = proj(C1), sp = ext.map((p) => P1(...p));
  const w = Math.max(...sp.map((p) => p[0])) - Math.min(...sp.map((p) => p[0])), h = Math.max(...sp.map((p) => p[1])) - Math.min(...sp.map((p) => p[1]));
  const C = Cam(45, 0.5, Math.min(372 / w, 292 / h)); fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  for (const pt of parts) {
    pt.grp = mk("g", {}, g);
    pt.sil = mk("path", { class: "sil" }, pt.grp);
    pt.crp = pt.cr === -1 ? null : mk("path", { class: "nf lo" }, pt.grp);
  }
  const ang = spring(REST);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    for (const pt of parts) {
      const pr = (p) => P(...(pt.swing ? rot(p, d) : p));
      pt.sil.setAttribute("d", poly(hull([].concat(...pt.rings).map(pr))));
      if (pt.crp) pt.crp.setAttribute("d", poly(pt.rings[pt.cr || 1].map(pr)));
    }
  }
  draw(REST);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(Math.round(ang.x * 100) / 100); return m; });
  bag.add(B.unregister);

  const mids = parts.map((pt) => { const all = [].concat(...pt.rings).map((p) => P(...(pt.swing ? rot(p, REST) : p))); return { pt, m: [all.reduce((s, p) => s + p[0], 0) / all.length, all.reduce((s, p) => s + p[1], 0) / all.length] }; });
  let cur = null;
  function choose(name, sx) {
    ang.t = name ? REST - 0.7 * reach * clamp(0.75 + (200 - sx) / 260, 0.35, 1) : REST;
    for (const pt of parts) pt.sil.classList.toggle("hi", pt.name === (name || HI));
    if (name !== cur) { cur = name; read.textContent = name || "rest"; }
    B.wake();
  }
  function hit([sx, sy]) {
    let best = null, bd = Infinity;
    for (const { pt, m } of mids) { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = pt.name; } }
    choose(bd < 110 ? best : null, sx);
  }
  choose(null, 200);
  bag.add(pointer(stage, { move: hit, leave: () => choose(null, 200) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "croquet",
  means: "A croquet mallet over its ball by a hoop: the mallet swings back on its handle, and the part under the pointer lights.",
  rules: [1, 3, 5, 8],
  range: [0, 70, 90],
  tour: [[208, 234], [258, 259], [312, 249], null],
  mount,
});

shuffleboard.code:
/**
 * Shuffleboard: a long court with its scoring triangle at the far end, a disc
 * resting at the near end and the cue's fork behind it. The pointer pushes the
 * cue forward and the disc slides up the court, further the further right the
 * pointer is; the part nearest it is named and bright. At rest the disc is
 * bright. The slider is how far the disc slides.
 *
 * The pattern: one part sliding along a track, driven by a spring.
 */
const { Cam, circ, clamp, fit, hull, open, poly, proj, rrect, spring, stepS, disposer, mk, pointer, register } = HL;

const HI = "disc", D0 = 6;
const box = (x0, y0, x1, y1, z0, z1, r = 2) => { const q = rrect(x0, y0, x1, y1, r, 4); return [q.map((p) => [p.u, p.v, z0]), q.map((p) => [p.u, p.v, z1])]; };
const zcyl = (x, y, z0, z1, R, n = 32) => { const c = circ(R, n); return [c.map((p) => [x + p.u, y + p.v, z0]), c.map((p) => [x + p.u, y + p.v, z1])]; };
const stick = (a, b, R, n = 16) => { const c = circ(R, n); return [c.map((p) => [a[0], a[1] + p.u, a[2] + p.v]), c.map((p) => [b[0], b[1] + p.u, b[2] + p.v])]; };
function PARTS() {
  return [
    { rings: box(-92, -16, 92, 16, 0, 2.5, 6), name: "court", marks: [[[44, 0], [86, -12], [86, 12], [44, 0]], [[58, -4], [58, 4]], [[72, -8], [72, 8]], [[-70, -16], [-70, 16]]] },
    { rings: stick([-58, 0, 6], [-104, 0, 36], 1.5), name: "cue", k: 0.45 },
    { rings: box(-60, -7, -55, 7, 2.5, 7, 1.6), name: "cue", k: 0.45 },
    { rings: zcyl(-47, 0, 2.5, 5.5, 7.5), name: "disc", k: 1, cr: 1 },
  ];
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const parts = PARTS();
  const mv = (p, pt, s) => [p[0] + (pt.k || 0) * s, p[1], p[2]];
  const ext = [];
  for (let s = 0; s <= 120; s += 10) for (const pt of parts) for (const r of pt.rings) for (const p of r) ext.push(mv(p, pt, s));
  const C1 = Cam(45, 0.5, 1); fit(C1, ext, 200, 166);
  const P1 = proj(C1), sp = ext.map((p) => P1(...p));
  const w = Math.max(...sp.map((p) => p[0])) - Math.min(...sp.map((p) => p[0])), h = Math.max(...sp.map((p) => p[1])) - Math.min(...sp.map((p) => p[1]));
  const C = Cam(45, 0.5, Math.min(372 / w, 292 / h)); fit(C, ext, 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  for (const pt of parts) {
    pt.grp = mk("g", {}, g);
    pt.sil = mk("path", { class: "sil" }, pt.grp);
    pt.crp = mk("path", { class: "nf lo" }, pt.grp);
    for (const m of pt.marks || []) mk("path", { class: "nf lo", d: open(m.map((q) => P(q[0], q[1], 2.5))) }, pt.grp);
  }
  const sl = spring(D0);
  let last = NaN;
  function draw(s) {
    if (s === last) return;
    last = s;
    for (const pt of parts) {
      const pr = (p) => P(...mv(p, pt, s));
      pt.sil.setAttribute("d", poly(hull([].concat(...pt.rings).map(pr))));
      pt.crp.setAttribute("d", poly(pt.rings[1].map(pr)));
    }
  }
  draw(D0);
  const B = register(stage, (dt) => { const m = stepS(sl, dt); draw(Math.round(sl.x * 100) / 100); return m; });
  bag.add(B.unregister);

  const mids = parts.map((pt) => { const all = [].concat(...pt.rings).map((p) => P(...mv(p, pt, D0))); return { pt, m: [all.reduce((s, p) => s + p[0], 0) / all.length, all.reduce((s, p) => s + p[1], 0) / all.length] }; });
  let cur = null;
  function choose(name, sx) {
    sl.t = name ? D0 + 1.3 * reach * clamp(0.75 + (sx - 200) / 260, 0.6, 1) : D0;
    for (const pt of parts) pt.sil.classList.toggle("hi", pt.name === (name || HI));
    if (name !== cur) { cur = name; read.textContent = name || "rest"; }
    B.wake();
  }
  function hit([sx, sy]) {
    let best = null, bd = Infinity;
    for (const { pt, m } of mids) { const d = Math.hypot(m[0] - sx, m[1] - sy); if (d < bd) { bd = d; best = pt.name; } }
    choose(bd < 110 ? best : null, sx);
  }
  choose(null, 200);
  bag.add(pointer(stage, { move: hit, leave: () => choose(null, 200) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "shuffleboard",
  means: "A shuffleboard court with a disc and its cue: the cue pushes and the disc slides up the court, and the part under the pointer lights.",
  rules: [1, 3, 5, 8],
  range: [0, 70, 90],
  tour: [[100, 145], [118, 154], [230, 215], null],
  mount,
});

buttonpress.code:
/**
 * Button badge press: a base plate with a die cup, a post at the back and a
 * long lever pivoting on the post. A ram hangs from the lever over the die.
 * The pointer pulls the handle down by how low it stands: the lever swings
 * down and drives the ram into the die. At rest the lever is raised and the
 * die cup's rim is bright. The slider is how far the lever swings.
 *
 * The pattern: one lever on a spring (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, ringAt, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 13, PY = 20, PZ = 62, L = 82, RX = 38, RAM = 38, REST = 35, KR = 5;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.25);
  const tip = (a) => [PX + L * Math.cos(rad(a)), PY, PZ + L * Math.sin(rad(a))];
  const t0 = tip(REST), t1 = tip(REST - 60);
  fit(C, [[0, 0, 0], [56, 40, 0], [56, 0, 0], [0, 40, 0], [t0[0], PY, t0[2] + KR], [t1[0] + KR, PY, t1[2] - KR], [PX, PY, PZ + 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [br, bi] = rings(0, 0, 56, 40, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const [cr, ci] = rings(PX - 6, PY - 7, PX + 6, PY + 7, 4, 1.4);
  put(solid(g), prism(P, front, cr, ci, 4, PZ + 4));
  const die = solid(g);
  put(die, prism(P, front, disc(RX, PY, 11), disc(RX, PY, 8.5), 4, 12));
  die.sil.classList.add("hi");
  const ram = solid(g), rod = mk("path", { class: "lo nf" }, g);
  const lever = mk("path", { class: "sil" }, g), lcr = mk("path", { class: "lo nf" }, g);
  const knob = mk("path", { class: "sil" }, g);
  const pin = mk("path", { class: "nf" }, g);

  const sp = spring(0);
  let last = NaN;
  function draw(f) {
    if (f === last) return;
    last = f;
    const a = rad(REST - swing * f), ca = Math.cos(a), sa = Math.sin(a);
    const at = (s, t, w) => P(PX + s * ca - t * sa, PY + w, PZ + s * sa + t * ca);
    const pts = [];
    for (const s of [-4, L]) for (const w of [-3.5, 3.5]) for (let i = 0; i < 12; i++) {
      const q = (i / 12) * Math.PI * 2;
      pts.push(at(s + 3 * Math.cos(q), 3 * Math.sin(q), w));
    }
    lever.setAttribute("d", poly(hull(pts)));
    lcr.setAttribute("d", open([at(2, 2.2, -1.5), at(L - 4, 2.2, -1.5)]));
    const kc = [PX + L * ca, PY, PZ + L * sa], kp = [];
    for (let i = 0; i <= 6; i++) {
      const t = (i / 6) * Math.PI - Math.PI / 2;
      kp.push(...ringAt(P, disc(kc[0], kc[1], KR * Math.cos(t) + 0.01, 20), kc[2] + KR * Math.sin(t)));
    }
    knob.setAttribute("d", poly(hull(kp)));
    const top = PZ + (RX - PX) * Math.tan(a);
    put(ram, prism(P, front, disc(RX, PY, 7.5), disc(RX, PY, 5.5), top - RAM, top - 6));
    rod.setAttribute("d", seg(P(RX, PY, top - 6), P(RX, PY, top)));
    pin.setAttribute("d", poly(hull(ringAt(P, disc(PX, PY, 2.4, 16), PZ + 3).concat(ringAt(P, disc(PX, PY, 2.4, 16), PZ + 6)))));
    const on = f > 0.02;
    die.sil.classList.toggle("hi", !on);
    lever.classList.toggle("hi", on);
    knob.classList.toggle("hi", on);
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    const y0 = P(...tip(REST))[1], y1 = P(...tip(REST - swing))[1];
    const f = p ? clamp((p[1] - y0) / (y1 - y0), 0, 1) : 0;
    sp.t = f;
    read.textContent = p ? Math.round(f * swing) + "°" : "rest";
    B.wake();
  }
  draw(0);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "buttonpress",
  means: "A badge button press: the pointer pulls the lever handle down, and the ram drives into the die cup.",
  rules: [1, 3, 5, 8],
  range: [25, 50, 60],
  tour: [[270, 100], [289, 202], [280, 150], null],
  mount,
});

garmentsteamer.code:
/**
 * Garment steamer: a water tank on the floor, a telescoping pole standing
 * from it and a steam head paddle hanging on the pole's top, joined to the
 * tank by a hose. The pointer raises the inner pole by how high it stands:
 * the head rides up and the hose pulls taut. At rest the pole is low and
 * the head is bright. The slider is how far the pole extends.
 *
 * The pattern: one sliding part on a spring.
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rings, ringAt, rrect, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TX = 24, TY = 20, TZ = 26, OUT = 52, IN0 = 68;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, 0, 0], [48, 40, 0], [48, 0, 0], [0, 40, 0], [TX, TY, IN0 + 8 + 40], [70, 20, 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  const [tr, ti] = rings(0, 0, 48, 40, 9, 2);
  put(solid(g), prism(P, front, tr, ti, 0, TZ));
  put(solid(g), prism(P, front, disc(TX, TY, 6), disc(TX, TY, 4.4), TZ, TZ + 3));
  put(solid(g), prism(P, front, disc(TX, TY, 2.6), disc(TX, TY, 1.6), TZ + 3, OUT));
  const inner = solid(g), hook = mk("path", { class: "nf" }, g), hose = mk("path", { class: "sil nf" }, g);
  const head = mk("path", { class: "sil hi" }, g), face = mk("path", { class: "lo nf" }, g);
  const plate = rrect(-11, -9, 11, 9, 5, 4), plin = rrect(-9, -7, 9, 7, 3.5, 4);

  const sp = spring(0);
  let last = NaN;
  function draw(f) {
    if (f === last) return;
    last = f;
    const top = IN0 + reach * f;
    put(inner, prism(P, front, disc(TX, TY, 1.8), disc(TX, TY, 1), OUT - 2, top));
    hook.setAttribute("d", open([P(TX, TY, top), P(TX, TY, top + 4), P(TX + 6, TY, top + 4), P(TX + 6, TY, top - 1)]));
    const hc = [TX + 8, TY, top - 13];
    const at = (q, x) => P(x, hc[1] + q.u, hc[2] + q.v);
    head.setAttribute("d", poly(hull(plate.map((q) => at(q, hc[0])).concat(plate.map((q) => at(q, hc[0] + 4))))));
    face.setAttribute("d", poly(plin.map((q) => at(q, hc[0] + 4))));
    const a = [48, 20, 9], b = [hc[0] + 2, hc[1], hc[2] - 9], m = [74, 20, 0], pts = [];
    for (let i = 0; i <= 24; i++) {
      const t = i / 24, u = 1 - t;
      pts.push(P(u * u * a[0] + 2 * u * t * m[0] + t * t * b[0], u * u * a[1] + 2 * u * t * m[1] + t * t * b[1], u * u * a[2] + 2 * u * t * m[2] + t * t * b[2]));
    }
    hose.setAttribute("d", open(pts));
  }

  const B = register(stage, (dt) => { const mv = stepS(sp, dt); draw(sp.x); return mv; });
  bag.add(B.unregister);

  function aim(p) {
    const y0 = P(TX + 8, TY, IN0 - 4)[1], y1 = P(TX + 8, TY, IN0 - 4 + reach)[1];
    const f = p ? clamp((p[1] - y0) / (y1 - y0), 0, 1) : 0;
    sp.t = f;
    read.textContent = p ? "+" + Math.round(f * reach) : "rest";
    B.wake();
  }
  draw(0);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; draw(sp.x); }, destroy: bag.dispose };
}

hairline({
  name: "garmentsteamer",
  means: "A garment steamer: the pointer raises the telescoping pole, and the steam head rides up on its hose.",
  rules: [1, 3, 5, 8],
  range: [20, 32, 40],
  tour: [[214, 120], [214, 69], [214, 47], null],
  mount,
});

golfballwasher.code:
/**
 * Golf ball washer: a tub on a post at the tee, a paddle plunger standing in
 * a slot through its lid with a ball held in the paddle, and a T handle on
 * top. The pointer's height pulls the handle: the plunger rides up out of the
 * tub on a spring and lifts the paddle and ball clear. At rest the plunger is
 * pushed down and the handle is bright.
 *
 * The pattern: one part following a continuous input (pull).
 */
const { Cam, circ, fit, facing, poly, prism, proj, rings, clamp, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const REST = 0.12, BZ = 30, TZ = 62, TRAVEL = 38;
const disc = (x, y, r, n = 20) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(10, 0.5, 2.5);
  fit(C, [[-18, -18, 0], [18, 18, 0], [18, -18, 0], [-18, 18, 0], [-30, 0, TZ + 70], [30, 0, TZ + 70]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r, b) => { const [a, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, a, i, z0, z1)); return s; };
  put(solid(g), prism(P, front, disc(0, 0, 20, 28), disc(0, 0, 18.4, 28), 0, 3));
  put(solid(g), prism(P, front, disc(0, 0, 3, 14), disc(0, 0, 2.2, 14), 3, BZ));
  box(solid(g), -22, -13, 22, 13, BZ, TZ, 6, 1.8);
  const slot = mk("path", { class: "lo nf" }, g);
  slot.setAttribute("d", poly([P(-17, -2, TZ), P(17, -2, TZ), P(17, 2, TZ), P(-17, 2, TZ)]));
  const paddle = solid(g), hole = mk("path", { class: "nf" }, g), ball = mk("path", { class: "nf sil" }, g);
  const rod = solid(g), bar = solid(g), capL = solid(g), capR = solid(g);
  const sp = spring(REST);
  let last = NaN;
  function draw() {
    const v = sp.x;
    if (v === last) return;
    last = v;
    const L = v * reach / 100 * TRAVEL, top = TZ + 4 + L;
    box(paddle, -16, -1.5, 16, 1.5, TZ, Math.max(TZ + 0.5, TZ - 6 + L), 1, 0.5);
    const bz = TZ - 12 + L;
    const o = P(0, 1.6, bz), rr = Math.hypot(...[0, 1].map((j) => P(6.5 / Math.SQRT2, 1.6 - 6.5 / Math.SQRT2, bz)[j] - o[j]));
    const show = bz + 6.5 > TZ;
    hole.setAttribute("d", show ? poly(Array.from({ length: 24 }, (_, i) => { const t = i / 24 * Math.PI * 2; return P(Math.cos(t) * 7.5, 1.6, Math.max(TZ, bz + Math.sin(t) * 7.5)); })) : "");
    ball.setAttribute("d", show ? poly(Array.from({ length: 28 }, (_, i) => { const t = i / 28 * Math.PI * 2; return [o[0] + Math.cos(t) * rr, Math.min(P(0, 1.6, TZ)[1], o[1] + Math.sin(t) * rr)]; })) : "");
    put(rod, prism(P, front, disc(0, 0, 2, 12), disc(0, 0, 1.4, 12), Math.max(TZ, TZ - 6 + L), top + 14));
    box(bar, -26, -3.5, 26, 3.5, top + 14, top + 21, 3.4, 1.2);
    box(capL, -30, -4.5, -24, 4.5, top + 12.5, top + 22.5, 3, 1);
    box(capR, 24, -4.5, 30, 4.5, top + 12.5, top + 22.5, 3, 1);
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const yT = P(0, 0, TZ + 50)[1], yB = P(0, 0, BZ)[1], xs = [P(-20, 20, 0)[0] - 30, P(20, -20, 0)[0] + 30];
  let state = "";
  function set(p) {
    let t = REST, on = false;
    if (p && p[0] > xs[0] && p[0] < xs[1] && p[1] > yT - 40 && p[1] < yB + 60) { t = clamp((yB - p[1]) / (yB - yT), 0, 1); on = true; }
    sp.t = t;
    const s = on ? "lift " + Math.round(t * reach / 100 * TRAVEL) : "rest";
    if (s !== state) { state = s; read.textContent = s; }
    B.wake();
  }
  bar.sil.classList.add("hi");
  set(null);
  draw();
  bag.add(pointer(stage, { move: set, leave: () => set(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; last = NaN; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "golfballwasher",
  means: "A golf ball washer on its post: the pointer's height pulls the T handle and the paddle plunger lifts the ball out of the tub.",
  rules: [1, 3, 5, 8],
  range: [30, 100, 100],
  tour: [[200, 180], [200, 109], [200, 60], null],
  mount,
});

foosball2.code:
/**
 * Table football: a cabinet with its pitch, two side rails, and four rods
 * across it, each carrying a line of players, a grip on the near end. The
 * pointer picks the rod under it: that rod spins and its players kick, and
 * the rods beside it follow less, spreading out from the pointer. At rest the
 * rods sit at uneven angles and one player is bright.
 *
 * The pattern: pick by the pitch's plane, which never moves; a spin per rod
 * on the discrete clock, staggered by distance.
 */
const { Cam, fit, facing, hull, poly, prism, proj, rings, seg, unproj, rad, tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid } = HL;

const XS = [-36, -12, 12, 36], RZ = 36, TOP = 18;
const YS = [[-14, 14], [-21, 0, 21], [-21, 0, 21], [-14, 14]];
const REST = [12, -18, 24, -10], FALL = [1, 0.45, 0.2, 0.1];
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let kick = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-58, -36, 0], [58, 36, 0], [58, -36, 0], [-58, 36, 0], [-58, -40, 42], [58, 60, RZ], [-58, 60, RZ]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (s, x0, y0, x1, y1, z0, z1, r, b) => { const [a, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, a, i, z0, z1)); return s; };
  box(solid(g), -58, -36, 58, 36, 0, TOP, 5, 2);
  const line = mk("path", { class: "lo nf" }, g);
  line.setAttribute("d", seg(P(0, -30, TOP), P(0, 30, TOP)));
  box(solid(g), -58, -36, 58, -31, TOP, 30, 2, 0.8);
  const rods = XS.map((x, i) => {
    const rod = mk("path", { class: "sil nf" }, g);
    rod.setAttribute("d", seg(P(x, -40, RZ), P(x, 36, RZ)));
    const men = YS[i].map(() => mk("path", { class: "sil" }, g));
    return { x, men, tw: tween(REST[i]) };
  });
  box(solid(g), -58, 31, 58, 36, TOP, 30, 2, 0.8);
  rods.forEach((r) => {
    const s = mk("path", { class: "sil nf" }, g);
    s.setAttribute("d", seg(P(r.x, 36, RZ), P(r.x, 48, RZ)));
    box(solid(g), r.x - 2.6, 46, r.x + 2.6, 60, RZ - 2.6, RZ + 2.6, 2.4, 0.8);
  });
  /** One player: a slab hung on the rod, turned by a degrees about it. */
  function man(x, y, a) {
    const d = [Math.sin(rad(a)), -Math.cos(rad(a))], e = [Math.cos(rad(a)), Math.sin(rad(a))], pts = [];
    for (const s of [-6, 16]) for (const t of [-2.2, 2.2]) for (const w of [-3.2, 3.2])
      pts.push(P(x + d[0] * s + e[0] * t, y + w, RZ + d[1] * s + e[1] * t));
    return poly(hull(pts));
  }
  let last = "", a = -1, hiK = -1;
  function draw(now) {
    const angs = rods.map((r) => tval(r.tw, now)), key = angs.map((v) => v.toFixed(2)).join();
    if (key === last) return;
    last = key;
    rods.forEach((r, i) => r.men.forEach((m, j) => m.setAttribute("d", man(r.x, YS[i][j], angs[i]))));
  }
  const B = register(stage, (dt, now) => { draw(now); return rods.some((r) => !tdone(r.tw, now)); });
  bag.add(B.unregister);
  function pick(k) {
    const now = performance.now();
    a = k;
    rods.forEach((r, i) => tset(r.tw, k < 0 ? REST[i] : kick * FALL[Math.abs(i - k)], now, k < 0 ? 0 : Math.abs(i - k) * 40));
    rods.forEach((r, i) => r.men.forEach((m, j) => m.classList.toggle("hi", k < 0 ? i === 1 && j === 1 : i === k)));
    read.textContent = k < 0 ? "rest" : `rod ${k + 1} · ${Math.round(kick)}°`;
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], TOP);
      let k = -1;
      if (Math.abs(x) < 66 && y > -50 && y < 66) { let bd = Infinity; XS.forEach((rx, i) => { if (Math.abs(rx - x) < bd) { bd = Math.abs(rx - x); k = i; } }); }
      if (k !== a) pick(k);
    },
    leave: () => { if (a !== -1) pick(-1); },
  }));
  bag.add(() => svg.replaceChildren());
  pick(-1);
  draw(performance.now());
  return { set: (v) => { kick = v; const k = a; a = -2; pick(k); }, destroy: bag.dispose };
}

hairline({
  name: "foosball2",
  means: "A table football table: the pointer picks a rod and it spins its players into a kick, the rods beside it following less.",
  rules: [1, 2, 3, 5, 8],
  range: [40, 80, 110],
  tour: [[167, 142], [200, 158], [266, 191], null],
  mount,
});

davit.code:
/**
 * Lifeboat davit: a gooseneck arm on its post at the deck's edge, a lifeboat
 * hanging from its falls. The pointer swings the arm outboard on a spring,
 * carrying the boat out over the side; at rest it stands stowed inboard, the
 * boat bright. The slider is how far the arm swings.
 */
const { Cam, fit, proj, facing, rings, rrect, ringAt, run, hull, poly, open, seg, clamp, spring, stepS, disposer, mk, solid, put, prism, register, pointer } = HL;

const L = 34, ZP = 48, ZB = 20, DB = 8, REST = Math.PI + 0.3, SWING = 2.3;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.45);
  const ext = [[-58, -38, 0], [10, 14, 0], [0, 0, ZP + 17]];
  for (let k = 0; k < 12; k++) { const a = (k / 12) * 6.283; ext.push([(L + 16) * Math.cos(a) * 0.9, (L + 16) * Math.sin(a), ZB]); }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [d0, d1] = rings(-58, -38, 10, 14, 5, 1.8);
  put(solid(g), prism(P, front, d0, d1, -4, 0));
  mk("path", { class: "dash nf", d: seg(P(-58, 14, 7), P(10, 14, 7)) }, g);
  const foot = rrect(-11, -3, 11, 3, 3, 4), top = rrect(-16, -5.5, 16, 5.5, 5.5, 6), inner = rrect(-14.6, -4.1, 14.6, 4.1, 4.1, 6);
  const post = mk("g", {}, g);
  put(solid(post), prism(P, front, rings(-4, -4, 4, 4, 2, 1)[0], null, 0, 3));
  put(solid(post), prism(P, front, rings(-2.2, -2.2, 2.2, 2.2, 1.1, 0.5)[0], null, 3, ZP));
  const arm = mk("path", { class: "nf sil", d: "" }, post);
  const boat = mk("g", {}, g);
  const hullS = solid(boat);
  const thwart = mk("path", { class: "lo nf", d: "" }, boat);
  const falls = mk("path", { class: "nf sil", d: "" }, boat);
  hullS.sil.classList.add("hi");
  const sp = spring(REST, { k: 90, c: 14 });
  let drawn = NaN, boatFirst = null;
  const xf = (ring, a, cx, cy) => { const c = Math.cos(a), s = Math.sin(a); return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c })); };
  function draw() {
    const a = sp.x;
    if (Math.abs(a - drawn) < 1e-4) return;
    drawn = a;
    const c = Math.cos(a), s = Math.sin(a), A = (r, z) => P(r * c, r * s, z);
    let d = "";
    for (const o of [0, 1.6]) {
      const pts = [];
      for (let i = 0; i <= 10; i++) { const b = (i / 10) * (Math.PI / 2); pts.push(A(L * (1 - Math.cos(b)), ZP - 2 + o + 14 * Math.sin(b))); }
      pts.push(A(L + 1.5, ZP + 10 + o));
      d += open(pts);
    }
    arm.setAttribute("d", d);
    const bx = L * c, by = L * s, ta = a + Math.PI / 2;
    const F = xf(foot, ta, bx, by), T = xf(top, ta, bx, by), I = xf(inner, ta, bx, by);
    hullS.sil.setAttribute("d", poly(hull(ringAt(P, F, ZB).concat(ringAt(P, T, ZB + DB)))));
    hullS.cr.setAttribute("d", open(ringAt(P, run(I, front), ZB + DB)));
    const e = (u, v, z) => { const tc = Math.cos(ta), ts = Math.sin(ta); return P(bx + u * tc - v * ts, by + u * ts + v * tc, z); };
    thwart.setAttribute("d", seg(e(-4, -4, ZB + DB - 0.5), e(-4, 4, ZB + DB - 0.5)) + seg(e(5, -4, ZB + DB - 0.5), e(5, 4, ZB + DB - 0.5)));
    const tip = A(L + 1.5, ZP + 10);
    falls.setAttribute("d", seg(tip, e(-11, 0, ZB + DB)) + seg(tip, e(11, 0, ZB + DB)));
    const bf = bx + by < 0;
    if (bf !== boatFirst) { boatFirst = bf; if (bf) post.before(boat); else post.after(boat); }
  }
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  const cx0 = P(0, 0, 0)[0];
  function set(on, x) {
    sp.t = on ? REST - clamp((x - cx0 + 120) / 200, 0.2, 1) * SWING * value : REST;
    read.textContent = on ? (sp.t < REST - 1.6 ? "out" : "swing") : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move: (p) => set(true, p[0]), leave: () => set(false) }));
  bag.add(() => svg.replaceChildren());
  set(false);
  return { set: (v) => { value = v; }, destroy: bag.dispose };
}

hairline({
  name: "davit",
  means: "A lifeboat davit: the pointer swings the gooseneck arm outboard, carrying the hanging lifeboat out over the ship's side.",
  rules: [1, 3, 5],
  range: [0.4, 1, 1.4],
  tour: [[162, 129], [250, 170], [320, 150], null],
  mount,
});

shadoof.code:
/**
 * Shadoof: a well sweep. A forked post holds a long pole on a pin; a stone
 * counterweight is lashed to the short end and a bucket hangs on a rope from
 * the long end, over a round well. The pointer is the hand on the rope: the
 * further toward the well it goes, the further the pole tips and lowers the
 * bucket, while the stone rises. At rest the bucket is up, bright.
 * The slider is how far the pole may swing.
 *
 * The pattern: a continuous aim (a spring on one angle), picked on the ground.
 */
const {
  Cam, circ, clamp, facing, fit, hull, lerp, poly, prism, proj, rad, rings, rrect, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = 0, PZ = 62, ARM = 76, SHORT = 44, ROPE = 12, WX = 72, WR = 17, WZ = 16, REST = -26;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-62, -24, 0], [100, 26, 0], [-60, 0, 100], [PX + ARM, 0, PZ + 36], [WX, 0, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // ground slab, then the well
  const [sr, si] = rings(-62, -24, 100, 26, 10, 2);
  put(solid(g), prism(P, front, sr, si, 0, 3));
  put(solid(g), prism(P, front, disc(WX, 0, WR), disc(WX, 0, WR - 3), 3, WZ));
  mk("path", { d: poly(disc(WX, 0, WR - 4, 32).map((q) => P(q.u, q.v, WZ))), class: "nf lo" }, g);

  const stone = mk("path", { class: "sil" }, g);
  const [br, bi] = rings(PX - 4, -11, PX + 4, -5, 2, 1);
  put(solid(g), prism(P, front, br, bi, 3, PZ + 6));
  const pole = mk("path", { class: "sil" }, g);
  const pin = mk("path", { class: "nf lo" }, g);
  const [fr, fi] = rings(PX - 4, 5, PX + 4, 11, 2, 1);
  put(solid(g), prism(P, front, fr, fi, 3, PZ + 6));
  const rope = mk("path", { class: "nf" }, g);
  const bucket = solid(g);
  bucket.sil.classList.add("hi");

  // a point s along the pole, y across it, c off its axis, at angle th
  const at = (th, s, y, c) => {
    const ct = Math.cos(th), st = Math.sin(th);
    return P(PX + s * ct + c * st, y, PZ - s * st + c * ct);
  };
  const pts = (th, s0, s1, r) => {
    const o = [];
    for (const s of [s0, s1]) for (let i = 0; i < 20; i++) { const f = (i / 20) * Math.PI * 2; o.push(at(th, s, r * Math.cos(f), r * Math.sin(f))); }
    return o;
  };
  const block = rrect(-9, -8, 9, 8, 3.5, 4);

  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const th = rad(deg);
    pole.setAttribute("d", poly(hull(pts(th, -SHORT - 4, ARM + 3, 2.4))));
    pin.setAttribute("d", seg(P(PX, -9, PZ), P(PX, 9, PZ)));
    const sp = [];
    for (const c of [-14, 2.5]) for (const q of block) sp.push(at(th, -SHORT + q.u, q.v, c));
    stone.setAttribute("d", poly(hull(sp)));
    const ex = PX + ARM * Math.cos(th), ez = PZ - ARM * Math.sin(th), bz = ez - ROPE - 9;
    rope.setAttribute("d", seg(P(ex, 0, ez), P(ex, 0, bz + 9)));
    put(bucket, prism(P, front, disc(ex, 0, 6.5, 24), disc(ex, 0, 5, 24), bz, bz + 9));
  }

  const a = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(a.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { a.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    if (x < -70 || x > 110 || Math.abs(y) > 60) return aim(null);
    const u = clamp((x + 50) / 130, 0, 1);
    a.t = lerp(REST, REST + amp, u);
    read.textContent = "dip " + Math.round(u * 9);
    B.wake();
  }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

