ballista.code:
/**
 * Ballista: a giant crossbow on a post. A long stock carries a winch at the
 * back and a frame at the front, two arms spring out of the frame and a
 * string runs from their tips round the nock of a bolt. The pointer is the
 * winch: the further back along the stock it goes, the further the string is
 * drawn and the arms bend back, the bolt sliding with it. At rest the bolt is
 * nocked, bright. The slider is how far the string may be drawn.
 *
 * The pattern: a continuous aim (a spring on one draw), picked on the ground.
 */
const {
  Cam, clamp, facing, fit, hull, lerp, poly, prism, proj, rad, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const SZ = 38, XF = 32, ARM = 50, PHI0 = 10, BOLT = 56, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-52, -64, 0], [44, 64, 0], [-52, 64, 0], [44, -64, 0], [XF + BOLT, 0, SZ + 10], [-40, 0, SZ + 16]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // a round rod from a to b, radius r, as a hull of two rings
  const rod = (a, b, r) => {
    const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], n = Math.hypot(...d);
    d[0] /= n; d[1] /= n; d[2] /= n;
    let u = [d[1], -d[0], 0];
    const un = Math.hypot(...u) || 1;
    u = un < 1e-3 ? [1, 0, 0] : [u[0] / un, u[1] / un, 0];
    const w = [d[1] * u[2] - d[2] * u[1], d[2] * u[0] - d[0] * u[2], d[0] * u[1] - d[1] * u[0]];
    const o = [];
    for (const p of [a, b]) for (let i = 0; i < 18; i++) {
      const f = (i / 18) * Math.PI * 2, c = Math.cos(f) * r, s = Math.sin(f) * r;
      o.push(P(p[0] + u[0] * c + w[0] * s, p[1] + u[1] * c + w[1] * s, p[2] + u[2] * c + w[2] * s));
    }
    return poly(hull(o));
  };

  const [br, bi] = rings(-44, -30, 36, 30, 10, 2);
  put(solid(g), prism(P, front, br, bi, 0, 4));
  const [pr, pi] = rings(-6, -5, 4, 5, 3, 1);
  put(solid(g), prism(P, front, pr, pi, 4, SZ - 3));
  const armB = mk("path", { class: "sil" }, g);
  const [sr, si] = rings(-52, -4.5, XF + 8, 4.5, 2, 1);
  put(solid(g), prism(P, front, sr, si, SZ - 3, SZ + 2));
  mk("path", { d: rod([-46, -12, SZ + 5], [-46, 12, SZ + 5], 4.5), class: "sil" }, g);
  const [fr, fi] = rings(XF - 5, -12, XF + 5, 12, 3, 1.2);
  put(solid(g), prism(P, front, fr, fi, SZ - 4, SZ + 11));
  const string = mk("path", { class: "nf" }, g);
  const bolt = mk("path", { class: "sil hi" }, g);
  const head = mk("path", { class: "sil hi" }, g);
  const armF = mk("path", { class: "sil" }, g);

  let last = NaN;
  function draw(pull) {
    if (pull === last) return;
    last = pull;
    const phi = rad(PHI0 + pull * 0.8), z = SZ + 6;
    const tip = (s) => [XF - ARM * Math.sin(phi), s * (12 + ARM * Math.cos(phi)), z];
    const tb = tip(-1), tf = tip(1), nx = XF - 6 - pull;
    armB.setAttribute("d", rod([XF, -12, z], tb, 2.6));
    armF.setAttribute("d", rod([XF, 12, z], tf, 2.6));
    const nock = P(nx, 0, SZ + 4);
    string.setAttribute("d", seg(P(...tb), nock) + seg(nock, P(...tf)));
    bolt.setAttribute("d", rod([nx, 0, SZ + 4], [nx + BOLT, 0, SZ + 4], 1.8));
    head.setAttribute("d", rod([nx + BOLT - 1, 0, SZ + 4], [nx + BOLT + 6, 0, SZ + 4], 3));
  }

  const a = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(a, dt); draw(a.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    if (!p) { a.t = REST; read.textContent = "rest"; B.wake(); return; }
    const [x, y] = unproj(C, p[0], p[1], 0);
    if (x < -80 || x > 90 || Math.abs(y) > 70) return aim(null);
    const u = clamp((40 - x) / 85, 0, 1);
    a.t = lerp(REST, amp, u);
    read.textContent = "draw " + Math.round(u * 9);
    B.wake();
  }
  draw(REST);
  read.textContent = "rest";
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; }, destroy: bag.dispose };
}

hairline({
  name: "ballista",
  means: "A giant crossbow: the pointer back along the stock winds the string, bending the arms back and drawing the bolt.",
  rules: [1, 3, 5, 8],
  range: [24, 40, 56],
  tour: [[237, 208], [191, 185], [153, 166], null],
  mount,
});

lifeboat.code:
/**
 * Lifeboat: an open double-ended lifeboat, two oars out in their rowlocks,
 * thwarts across the open stern and a domed canopy over the bow, hinged
 * amidships. The pointer over the boat swings the canopy up and back on its
 * hinge, wider the nearer the bow. At rest the canopy sits just ajar, bright.
 * The slider is how far the canopy can open.
 *
 * The pattern: one part swinging to the pointer, on a spring.
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, proj, rrect, ringAt, run, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid, rad,
} = HL;

const L = 92, W = 30, HZ = 20, HX = 40, REST = 12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.9);
  fit(C, [[-6, -24, 0], [L, W + 24, 0], [L, -4, 0], [-6, W + 24, 6], [HX, W / 2, 72], [10, W / 2, 62]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const oar = (y1) => {
    const a = P(26, W / 2 + (y1 > 0 ? 6 : -6), HZ + 1), b = P(14, y1, 4), c = P(10, y1 + (y1 > 0 ? 6 : -6), 2);
    mk("path", { d: seg(a, b), class: "nf sil" }, g);
    const bl = [P(15, y1 - 2.5, 4), P(9, y1 + (y1 > 0 ? 7 : -7) - 2.5, 1.5), P(9, y1 + (y1 > 0 ? 7 : -7) + 2.5, 1.5), P(15, y1 + 2.5, 4)];
    mk("path", { d: poly(bl), class: "sil" }, g);
    void c;
  };
  oar(-24);
  const foot = rrect(12, 9, L - 12, W - 9, 6, 6), top = rrect(0, 0, L, W, 15, 10), inner = rrect(2, 2, L - 2, W - 2, 13, 10);
  put(solid(g), { sil: poly(hull(ringAt(P, foot, 0).concat(ringAt(P, top, HZ)))), crease: open(ringAt(P, run(inner, front), HZ)) });
  for (const x of [10, 24]) mk("path", { d: seg(P(x, 2.5, HZ - 2), P(x, W - 2.5, HZ - 2)), class: "nf lo" }, g);
  mk("path", { d: seg(P(HX, 1, HZ + 0.5), P(HX, W - 1, HZ + 0.5)), class: "nf" }, g);
  const can = mk("path", { class: "sil hi" }, g), ridge = mk("path", { class: "nf lo" }, g), lip = mk("path", { class: "nf lo" }, g);
  oar(W + 18);

  const hw = (x) => (x > L - 15 ? Math.sqrt(Math.max(0, 225 - (x - (L - 15)) ** 2)) : 15) - 1;
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), ca = Math.cos(a), sa = Math.sin(a);
    const R = (x, y, z) => { const dx = x - HX, dz = z - HZ; return P(HX + dx * ca - dz * sa, y, HZ + dx * sa + dz * ca); };
    const pts = [], rid = [], end = [];
    for (let x = HX + 1; x <= L - 1; x += 3) {
      const w = hw(x);
      for (let i = 0; i <= 10; i++) { const t = (i / 10) * Math.PI, p = R(x, W / 2 + w * Math.cos(t), HZ + 0.8 * w * Math.sin(t)); pts.push(p); if (x === HX + 1) end.push(p); if (i === 5) rid.push(p); }
    }
    can.setAttribute("d", poly(hull(pts)));
    ridge.setAttribute("d", open(rid));
    lip.setAttribute("d", open(end));
  }

  const ang = spring(REST);
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  draw(REST);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, 0);
    const over = wx > -20 && wx < L + 20 && wy > -30 && wy < W + 30;
    ang.t = over ? REST + reach * clamp(0.4 + (0.6 * wx) / L, 0.4, 1) : REST;
    read.textContent = over ? Math.round(ang.t) + "°" : "rest";
    B.wake();
  }
  bag.add(pointer(stage, { move, leave: () => { ang.t = REST; read.textContent = "rest"; B.wake(); } }));
  read.textContent = "rest";
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "lifeboat",
  means: "An open lifeboat with oars out: the pointer over it swings the domed bow canopy up on its hinge, wider nearer the bow.",
  rules: [1, 3, 5, 8],
  range: [40, 95, 118],
  tour: [[205, 200], [276, 167], [305, 212], null],
  mount,
});

garbagetruck.code:
/**
 * Garbage truck: a front loader, cab up front and the tall refuse body
 * behind it, with two long lift arms pivoting on the body's nose and a
 * container held on their forks ahead of the cab. The pointer's place across
 * the frame swings the arms: the container climbs over the cab and turns
 * upside down above the hopper. At rest it hangs just lifted, bright. The
 * slider is how far the arms swing.
 *
 * The pattern: one hinged part (swing).
 */
const { Cam, clamp, facing, fillet, fit, hull, poly, prism, proj, rad, rings, ringAt, rrect, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const W = 50, PX = 86, PZ = 74, AL = 62, A0 = -38, REST = 6, MAXA = 135;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const end = (a) => [PX + AL * Math.cos(rad(A0 + a)), PZ + AL * Math.sin(rad(A0 + a))];
  const cp = (y, dx, dz, a) => { const [ex, ez] = end(a), c = Math.cos(rad(a)), s = Math.sin(rad(a)); return [ex + dx * c - dz * s, y, ez + dx * s + dz * c]; };
  const corners = (a) => { const o = []; for (const y of [4, W - 4]) for (const dx of [-2, 30]) for (const dz of [-30, 4]) o.push(cp(y, dx, dz, a)); return o; };
  const C = Cam(45, 0.5, 1.5);
  fit(C, [[0, 0, 0], [134, W, 0], [0, W, 0], [134, 0, 0]].concat(corners(0), corners(MAXA)), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(x + 11 * Math.cos(t), y, 11 + 11 * Math.sin(t))); }
    return pts;
  };
  const wheels = (y) => { for (const x of [22, 46, 114]) mk("path", { d: poly(wheel(x, y)) }, g); };
  wheels(4);
  const farArm = mk("path", { class: "nf" }, g);
  const [chr, chi] = rings(0, 6, 134, W - 6, 3, 1);
  put(solid(g), prism(P, front, chr, chi, 9, 19));
  const [br, bi] = rings(2, 0, 92, W, 8, 2);
  put(solid(g), prism(P, front, br, bi, 18, 70));
  mk("path", { d: poly(ringAt(P, rrect(58, 9, 84, W - 9, 4, 4), 70)), class: "nf lo" }, g);
  mk("path", { d: seg(P(20, W, 26), P(20, W, 64)), class: "nf lo" }, g);
  const foot = rrect(94, 2, 132, W - 2, 6, 6), top = rrect(96, 5, 118, W - 5, 5, 6);
  const cab = solid(g);
  cab.sil.setAttribute("d", poly(hull(ringAt(P, foot, 18).concat(ringAt(P, foot, 36), ringAt(P, top, 56)))));
  mk("path", { d: seg(P(129, W - 6, 38), P(117, W - 6, 53)), class: "nf lo" }, g);
  wheels(W - 4);
  const nearArm = mk("path", { class: "nf" }, g);
  const box = mk("path", { class: "sil hi" }, g), rim = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const [ex, ez] = end(a);
    const arm = (y) => seg(P(PX, y, PZ), P(ex, y, ez)) + seg(P(ex, y, ez), P(...cp(y, 0, -26, a)));
    farArm.setAttribute("d", arm(-3));
    nearArm.setAttribute("d", arm(W + 3));
    const h = hull(corners(a).map((p) => P(...p)));
    box.setAttribute("d", poly(fillet(h, h.map(() => 5), 3)));
    rim.setAttribute("d", seg(P(...cp(4, 2, 0, a)), P(...cp(W - 4, 2, 0, a))) + seg(P(...cp(W - 4, 2, 0, a)), P(...cp(W - 4, 28, 0, a))));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);
  function aim(a, r) { ang.t = a; read.textContent = r ? "rest" : Math.round(a) + "°"; B.wake(); }
  draw(REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(REST + clamp((sx - 120) / 170, 0, 1) * (max - REST)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = clamp(v, 40, MAXA); }, destroy: bag.dispose };
}

hairline({
  name: "garbagetruck",
  means: "A front-loading garbage truck: the pointer swings its lift arms, carrying the container over the cab to tip into the hopper.",
  rules: [1, 3, 5, 6],
  range: [70, 115, 135],
  tour: [[276, 250], [225, 205], [170, 160], null],
  mount,
});

piledriver.code:
/**
 * Pile driver: a tracked base with a cab and a tall mast, a pile standing
 * at its foot and a heavy hammer riding the mast. Over the rig the hammer
 * climbs the mast on the 700ms ease; leaving drops it back to its rest
 * above the pile, the hammer bright. The slider is how high it climbs.
 *
 * The pattern: one part answering a discrete choice (tween).
 */
const {
  Cam, fit, facing, prism, proj, rings, clamp, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 44, MAST = 132, HAM = 26;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-34, -20, 0], [44, 20, 0], [44, -20, 0], [-34, 20, 0], [22, 0, MAST], [-34, -20, 34]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(-34, -20, 20, -10, 4, 1.2, 0, 8);
  box(-34, 10, 20, 20, 4, 1.2, 0, 8);
  box(-30, -16, 18, 16, 5, 1.6, 8, 17);
  const brace = mk("path", { class: "lo nf" }, g);
  brace.setAttribute("d", "M" + P(-10, 0, 30).join(",") + "L" + P(18, 0, 92).join(","));
  box(-28, -14, -4, 12, 4, 1.4, 17, 34);
  box(16, -4, 24, 4, 2, 1, 0, MAST);
  box(28, -5, 38, 5, 2, 1, 0, 20);
  mk("path", { class: "dash", d: "M" + P(33, 0, 20).join(",") + "L" + P(33, 0, MAST - 4).join(",") }, g);
  const ham = solid(g);
  ham.sil.classList.add("hi");
  const [hr, hi] = rings(24, -9, 42, 9, 3, 1.4);
  const cap = mk("path", { class: "lo nf" }, g);

  const lift = tween(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    put(ham, prism(P, front, hr, hi, z, z + HAM));
    cap.setAttribute("d", "M" + P(24, 9, z + 6).join(",") + "L" + P(42, 9, z + 6).join(",") + "L" + P(42, -9, z + 6).join(","));
  }

  const B = register(stage, (dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);

  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 110 || sy < 10 || sy > 310) return leave();
    tset(lift, top, performance.now(), 0);
    read.textContent = "up " + Math.round(top);
    B.wake();
  }
  function leave() { tset(lift, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 76, MAST - HAM - 4); }, destroy: bag.dispose };
}

hairline({
  name: "piledriver",
  means: "A pile driver: over it the heavy hammer climbs the tall mast above the pile; the slider sets how high it climbs.",
  rules: [3, 5, 8],
