typewriter.code:
/**
 * Typewriter: a tapered body with a sloping bank of keys in front and, on
 * top, the carriage: a rail, the platen roller with its knobs, a sheet of
 * paper and the return lever. The pointer over the typewriter slides the
 * whole carriage along, as it travels while typing; leaving returns it. At
 * rest the platen is bright. The slider is how far the carriage travels.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, lerp, open, poly, prism, proj, rings, rrect, ringAt, run, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, place, pointer, put, register, solid,
} = HL;

const REST = -6, PX = 14, PZ = 28, R = 7, HALF = 46;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[0, 0, 0], [64, 80, 0], [0, 80, 0], [64, 0, 0], [2, 40 - 22 + REST, 62], [PX, 40 + 32 + HALF + 4, PZ - R], [30, 40 + REST - 56, 34]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // the body, narrower at its top, then the bank of keys before it
  put(solid(g), { sil: poly(hull(ringAt(P, rrect(0, 0, 50, 80, 8, 4), 0).concat(ringAt(P, rrect(4, 5, 42, 75, 6, 4), 20)))), crease: open(ringAt(P, run(rrect(5.5, 6.5, 40.5, 73.5, 4.5, 4), front), 20)) });
  put(solid(g), prism(P, front, ...rings(42, 4, 64, 76, 5, 1.6), 0, 9));
  for (const x of [47, 53, 59]) for (let y = 11; y <= 69; y += 7.2) place(mk("circle", { r: 1.7, class: "dot off" }, g), P(x, y + (x === 53 ? 2 : 0), 9));

  // the carriage, redrawn as it slides
  const carr = mk("g", {}, g);
  const rail = solid(carr), paper = mk("path", { class: "" }, carr), platen = solid(carr), cap = mk("path", { class: "nf lo" }, carr);
  const knobA = mk("path", { class: "nf" }, carr), knobB = mk("path", { class: "nf" }, carr), lever = mk("path", { class: "nf" }, carr);
  platen.sil.classList.add("hi");
  const circle = (r, y) => { const pts = []; for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(PX + r * Math.cos(t), y, PZ + r * Math.sin(t))); } return pts; };
  const cyl = (r, y0, y1) => poly(hull(circle(r, y0).concat(circle(r, y1))));
  const off = tween(REST);
  let last = NaN;
  function draw(s) {
    if (Math.abs(s - last) < 0.01) return;
    last = s;
    const cy = 40 + s;
    put(rail, prism(P, front, ...rings(6, cy - HALF + 2, 22, cy + HALF - 2, 3, 1), 20, 22));
    paper.setAttribute("d", poly(fillet([P(11, cy - 22, PZ + 4), P(11, cy + 22, PZ + 4), P(2, cy + 22, 62), P(2, cy - 22, 62)], [1, 1, 1, 1])));
    knobA.setAttribute("d", cyl(4.5, cy - HALF - 5, cy - HALF));
    put(platen, { sil: cyl(R, cy - HALF, cy + HALF), crease: poly(circle(R - 1.2, cy + HALF)) });
    knobB.setAttribute("d", cyl(4.5, cy + HALF, cy + HALF + 5));
    cap.setAttribute("d", poly(circle(3.4, cy + HALF + 5)));
    lever.setAttribute("d", open([P(PX + 2, cy - HALF + 4, PZ + 7), P(24, cy - HALF - 2, PZ + 8), P(32, cy - HALF - 10, PZ + 6)]));
  }
  const B = register(stage, (_dt, now) => { draw(tval(off, now)); return !tdone(off, now); });
  bag.add(B.unregister);

  let on = null;
  function setOn(v) {
    if (v === on) return;
    on = v;
    tset(off, on ? max : REST, performance.now(), 0);
    read.textContent = on ? "col " + Math.round(max) : "rest";
    B.wake();
  }
  setOn(false);
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    setOn(clamp(x, -40, 70) === x && clamp(y, -30, 110) === y);
  }
  bag.add(pointer(stage, { move, leave: () => setOn(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (on) { on = null; setOn(true); } }, destroy: bag.dispose };
}

hairline({
  name: "typewriter",
  means: "A typewriter: the pointer over it slides the carriage, platen, paper and lever, along the top; leaving returns it.",
  rules: [1, 3, 5, 8],
  range: [14, 24, 32],
  tour: [[148, 215], [203, 137], [251, 215], null],
  mount,
});

reachstacker.code:
/**
 * Reach stacker: a wheeled chassis with a counterweight and a cab, its long
 * boom laid low over the front, carrying a spreader that grips a container.
 * Over the machine the boom swings up on its pivot on the 700ms ease and
 * lifts the container high; leaving lowers it again, the spreader bright.
 * The slider is how far the boom rises.
 *
 * The pattern: one part answering a discrete choice (tween).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, rrect, clamp, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 6, PV = [-34, 0, 30], BL = 78;
const norm = (v) => { const n = Math.hypot(...v) || 1; return v.map((x) => x / n); };
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];

function beam(P, a, d, len, w, h, r, b) {
  d = norm(d);
  const e1 = Math.abs(d[2]) > 0.99 ? [1, 0, 0] : norm(cross([0, 0, 1], d)), e2 = cross(d, e1);
  const at = (ring, s) => ring.map((q) => { const p = [0, 1, 2].map((j) => a[j] + d[j] * s + e1[j] * q.u + e2[j] * q.v); return P(p[0], p[1], p[2]); });
  const R = rrect(-w / 2, -h / 2, w / 2, h / 2, r, 4), I = rrect(-w / 2 + b, -h / 2 + b, w / 2 - b, h / 2 - b, Math.max(0.3, r - b), 4);
  return { sil: poly(hull(at(R, 0).concat(at(R, len)))), crease: poly(at(I, len)) };
}
const tipOf = (a) => [PV[0] + BL * Math.cos(rad(a)), 0, PV[2] + BL * Math.sin(rad(a))];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value, on = false;
  const C = Cam(45, 0.5, 2.35);
  const pts = [[-46, -20, 0], [36, 20, 0], [-46, 20, 0], [36, -20, 0]];
  for (const a of [REST, 52]) { const t = tipOf(a); pts.push([t[0] + 12, 28, t[2] - 30], [t[0] - 12, -28, t[2] + 6], [t[0] + 12, -28, t[2] + 6], [t[0] - 12, 28, t[2] - 30]); }
  fit(C, pts, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const slab = (s, x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, o, i, z0, z1)); };
  const wheel = (x, y) => put(solid(g), beam(P, [x, y, 8], [0, y < 0 ? -1 : 1, 0], 6, 15, 15, 7.4, 1.2));
  wheel(-28, -12); wheel(14, -12);
  slab(solid(g), -44, -13, 32, 13, 4, 1.5, 9, 18);
  slab(solid(g), -46, -15, -30, 15, 4, 1.5, 18, 30);
  slab(solid(g), -6, -16, 14, -5, 3, 1.2, 18, 40);
  wheel(-28, 12); wheel(14, 12);
  const box = solid(g), arm = solid(g), spr = solid(g);
  spr.sil.classList.add("hi");

  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const t = tipOf(a);
    slab(box, t[0] - 11, -25, t[0] + 11, 25, 2, 1, t[2] - 30, t[2] - 6);
    put(arm, beam(P, PV, [Math.cos(rad(a)), 0, Math.sin(rad(a))], BL + 2, 9, 9, 3, 1));
    slab(spr, t[0] - 4, -28, t[0] + 4, 28, 2, 1, t[2] - 6, t[2] - 1);
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  const sp = pts.map((p) => P(...p)), X0 = Math.min(...sp.map((p) => p[0])), X1 = Math.max(...sp.map((p) => p[0]));
  const Y0 = Math.min(...sp.map((p) => p[1])), Y1 = Math.max(...sp.map((p) => p[1]));
  const say = () => { read.textContent = "boom " + Math.round(top) + "°"; };
  function move([sx, sy]) {
    if (sx < X0 || sx > X1 || sy < Y0 || sy > Y1) return leave();
    on = true;
    tset(ang, top, performance.now(), 0);
    say();
    B.wake();
  }
  function leave() { on = false; tset(ang, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { top = clamp(v, 26, 52); if (on) { tset(ang, top, performance.now(), 0); say(); B.wake(); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "reachstacker",
  means: "A reach stacker: over it the boom swings up on its pivot and lifts the gripped container high; the slider sets how far.",
  rules: [3, 5, 8],
  range: [26, 40, 52],
  tour: [[259, 205], [212, 280], [134, 138], null],
  mount,
});

straddlecarrier.code:
/**
 * Straddle carrier: four tall legs on bogies under two top girders, a cab on
 * the front corner, and a spreader hanging a container between the legs on
 * four cables. Over the machine the spreader hoists the container on the
 * 700ms ease; leaving lowers it near the ground, the spreader bright. The
 * slider is the hoist height.
 *
 * The pattern: one part answering a discrete choice (tween).
 */
const {
  Cam, fit, facing, poly, prism, proj, rings, clamp, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 6, TOPZ = 62, LX = 34, LY = 20;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-42, -24, 0], [42, 24, 0], [42, -24, 0], [-42, 24, 0], [-42, -24, TOPZ + 14], [42, 24, TOPZ + 6]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, s) => { const [o, i] = rings(x0, y0, x1, y1, r, b); s = s || solid(g); put(s, prism(P, front, o, i, z0, z1)); return s; };
  const leg = (x, y) => { box(x - 9, y - 3, x + 9, y + 3, 2.5, 0.8, 0, 7); box(x - 2.5, y - 2.5, x + 2.5, y + 2.5, 1, 0.6, 7, TOPZ); };
  leg(-LX, -LY);
  box(-40, -LY - 3, 40, -LY + 3, 2, 0.8, TOPZ, TOPZ + 6);
  box(-LX - 3, -LY, -LX + 3, LY, 2, 0.8, TOPZ, TOPZ + 5);
  leg(LX, -LY); leg(-LX, LY);
  const cables = mk("path", { class: "lo nf" }, g);
  const cg = mk("g", {}, g);
  const cont = solid(cg), ribs = mk("path", { class: "lo nf" }, cg), spread = solid(cg);
  spread.sil.classList.add("hi");
  leg(LX, LY);
  box(LX - 3, -LY, LX + 3, LY, 2, 0.8, TOPZ, TOPZ + 5);
  box(-40, LY - 3, 40, LY + 3, 2, 0.8, TOPZ, TOPZ + 6);
  box(LX - 6, LY - 8, LX + 6, LY + 4, 3, 1.2, TOPZ + 6, TOPZ + 16);

  const lift = tween(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    box(-28, -11, 28, 11, 1.5, 1, z, z + 22, cont);
    let d = "";
    for (let i = 1; i < 10; i++) { const x = -28 + i * 5.6; d += "M" + P(x, 11, z + 2).join(",") + "L" + P(x, 11, z + 20).join(","); }
    ribs.setAttribute("d", d);
    box(-30, -12, 30, 12, 2, 1, z + 22, z + 25, spread);
    let c = "";
    for (const x of [-22, 22]) for (const s of [-1, 1]) c += "M" + P(x, s * 10, z + 25).join(",") + "L" + P(x, s * (LY - 2), TOPZ).join(",");
    cables.setAttribute("d", c);
  }

  const B = register(stage, (dt, now) => { draw(tval(lift, now)); return !tdone(lift, now); });
  bag.add(B.unregister);

  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 160 || sy < 10 || sy > 310) return leave();
    tset(lift, top, performance.now(), 0);
    read.textContent = "hoist " + Math.round(top);
    B.wake();
  }
  function leave() { tset(lift, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 16, 32); }, destroy: bag.dispose };
}

hairline({
  name: "straddlecarrier",
  means: "A straddle carrier: over it the spreader hoists the container up between the tall legs; the slider sets the hoist height.",
  rules: [3, 5, 8],
  range: [16, 24, 32],
  tour: [[200, 172], [109, 215], [200, 127], null],
  mount,
});

stumpgrinder.code:
/**
 * Stump grinder: a squat chassis on two wheels with an engine box and a pair
 * of handlebars, and a long arm out front carrying the toothed cutting wheel
 * under its hood. Over the machine the arm swings the wheel sideways across
 * the cut on the 700ms ease; leaving swings it back, the wheel bright. The
 * slider is the swing angle.
 *
 * The pattern: one part answering a discrete choice (tween).
 */
const {
  Cam, fit, facing, hull, poly, prism, proj, rings, clamp, rad, tween, tset, tval, tdone,
  disposer, mk, pointer, put, register, solid,
} = HL;

const REST = 12, L = 44, PZ = 15, R = 14;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 2.15);
  const pts = [[-62, -16, 0], [-62, 16, 44], [-40, 16, 0]];
  for (const a of [REST, -60]) { const c = Math.cos(rad(a)), s = Math.sin(rad(a)); pts.push([L * c, L * s, PZ + R + 4], [L * c + 18 * c, L * s + 18 * s, 0], [L * c - 18 * c, L * s - 18 * s, 0]); }
  fit(C, pts, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  const wheel = (x, y) => { const w = []; for (let i = 0; i < 18; i++) { const t = (i / 18) * Math.PI * 2; w.push(P(x + 8 * Math.cos(t), y, 8 + 8 * Math.sin(t))); } mk("path", { d: poly(w) }, g); };
  wheel(-26, -15);
  const bars = mk("path", { class: "nf" }, g);
  bars.setAttribute("d", [-8, 8].map((y) => "M" + P(-40, y, 20).join(",") + "L" + P(-60, y * 1.3, 42).join(",")).join("") + "M" + P(-60, -10.4, 42).join(",") + "L" + P(-60, 10.4, 42).join(","));
  box(-42, -12, 2, 12, 3, 1.2, 8, 20);
  box(-36, -10, -10, 10, 3, 1.2, 20, 34);
  box(-4, -6, 6, 6, 3, 1, 20, 24);
  wheel(-26, 15);
  const arm = mk("path", {}, g);
  const disc = mk("path", { class: "sil hi" }, g), teeth = mk("path", { class: "lo nf" }, g);
  const hood = mk("path", {}, g);
  const hub = mk("circle", { class: "dot m", r: 2.2 }, g);

  const ang = tween(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    const q = (u, n, z) => P(u * c - n * s, u * s + n * c, z);
    const ab = [];
    for (const u of [0, L]) for (const n of [-3, 3]) for (const z of [PZ - 3, PZ + 3]) ab.push(q(u, n, z));
    arm.setAttribute("d", poly(hull(ab)));
    const dp = [], hp = [];
    let t = "";
    for (let i = 0; i < 24; i++) {
      const th = (i / 24) * Math.PI * 2, cu = Math.cos(th), sz = Math.sin(th);
      for (const n of [-2.5, 2.5]) dp.push(q(L + R * cu, n, PZ + R * sz));
      if (i % 2 === 0) t += "M" + q(L + R * cu, 3.2, PZ + R * sz).join(",") + "L" + q(L + (R - 3) * cu, 3.2, PZ + (R - 3) * sz).join(",");
      if (sz >= -0.01) for (const n of [-5, 5]) hp.push(q(L + (R + 3) * cu, n, PZ + (R + 3) * sz), q(L + 5 * cu, n, PZ + 5 * sz));
    }
    disc.setAttribute("d", poly(hull(dp)));
    teeth.setAttribute("d", t);
    hood.setAttribute("d", poly(hull(hp)));
    const [hx, hy] = q(L, 3, PZ);
    hub.setAttribute("cx", hx); hub.setAttribute("cy", hy);
  }

  const B = register(stage, (dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);

  function move([sx, sy]) {
    if (Math.abs(sx - 200) > 160 || sy < 10 || sy > 310) return leave();
    tset(ang, -top, performance.now(), 0);
    read.textContent = "swing " + Math.round(top) + "°";
    B.wake();
  }
  function leave() { tset(ang, REST, performance.now(), 0); read.textContent = "rest"; B.wake(); }
  leave();
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = clamp(v, 20, 60); }, destroy: bag.dispose };
}

hairline({
  name: "stumpgrinder",
  means: "A stump grinder: over it the arm swings the toothed cutting wheel sideways across the cut; the slider sets the swing angle.",
  rules: [3, 5, 8],
  range: [20, 40, 60],
  tour: [[247, 176], [286, 124], [84, 77], null],
  mount,
});

teleprompter.code:
/**
 * Teleprompter: a monitor lying face up under a sheet of glass hinged at its
 * far edge, with the camera hood behind. The pointer's depth over the frame
 * tilts the glass, on a spring, from leaning low to standing up. At rest
 * the glass leans low, bright. The slider is how far up it can tilt.
 */
const {
  Cam, fit, facing, fillet, poly, prism, proj, rings, clamp, lerp, rad, unproj,
  disposer, mk, pointer, put, register, solid, spring, stepS,
} = HL;

const W = 90, D = 70, MZ = 10, G = 74, X0 = 4, X1 = W - 4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-2, -30, 0], [W + 2, D + 2, 0], [W + 2, -30, 0], [-2, D + 2, 0], [X0, 0, MZ + G], [X1, G * 0.1, MZ + G], [X1, G, MZ + 10]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  let a, b;
  [a, b] = rings(W / 2 - 22, -30, W / 2 + 22, -6, 6, 1.6); put(solid(g), prism(P, front, a, b, 0, 4));
  [a, b] = rings(W / 2 - 18, -28, W / 2 + 18, -8, 5, 1.6); put(solid(g), prism(P, front, a, b, 4, 52));
  [a, b] = rings(W / 2 - 8, -6, W / 2 + 8, 2, 3, 1); put(solid(g), prism(P, front, a, b, 30, 42));
  [a, b] = rings(0, 0, W, D, 6, 1.8); put(solid(g), prism(P, front, a, b, 0, MZ));
  const scr = [[10, 10], [W - 10, 10], [W - 10, D - 10], [10, D - 10]].map(([x, y]) => P(x, y, MZ));
  mk("path", { d: poly(fillet(scr, [3, 3, 3, 3])), class: "nf lo" }, g);
  for (const x of [X0, X1]) {
    [a, b] = rings(x - 3, -3, x + 3, 3, 2, 0.8); put(solid(g), prism(P, front, a, b, MZ, MZ + 5));
  }
  const edge = mk("path", { class: "lo" }, g), glass = mk("path", { class: "sil hi" }, g), inner = mk("path", { class: "nf lo" }, g);
  const REST = 20, sp = spring(REST);
  let last = NaN;

  function plate(deg, dz, ins) {
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg)), q = (x, t) => P(x, t * c, MZ + 3 + dz + t * s);
    return fillet([q(X0 + ins, ins), q(X1 - ins, ins), q(X1 - ins, G - ins), q(X0 + ins, G - ins)], [3, 3, 3, 3]);
  }
  function draw(deg) {
    deg = Math.round(deg * 10) / 10;
    if (deg === last) return;
    last = deg;
    edge.setAttribute("d", poly(plate(deg, -2, 0)));
    glass.setAttribute("d", poly(plate(deg, 0, 0)));
    inner.setAttribute("d", poly(plate(deg, 0, 9)));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);
  draw(sp.x);

  function move([sx, sy]) {
    const [wx, wy] = unproj(C, sx, sy, MZ);
    if (wx < -50 || wx > W + 50 || wy < -60 || wy > D + 60) return leave();
    const f = clamp(1 - (wy + 20) / (D + 20), 0, 1);
    sp.t = lerp(REST, lerp(40, 84, reach), f);
    read.textContent = Math.round(sp.t) + "°";
    B.wake();
  }
  function leave() { sp.t = REST; read.textContent = "rest"; B.wake(); }
  read.textContent = "rest";
  bag.add(pointer(stage, { move, leave }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

