scrollsaw.code:
/**
 * Scroll saw: a long upper arm hinged on a post at the back of a low base,
 * its fine blade dropping through the table in front. The pointer over the
 * table lifts the arm on its hinge and draws the blade up out of the table,
 * the farther forward the higher. At rest the arm sits down, bright.
 * The slider is how far the arm lifts.
 */
const { Cam, clamp, facing, fit, hull, poly, prism, proj, rings, seg, unproj, spring, stepS, mk, pointer, put, register, solid, disposer } = HL;

const PX = -36, PZ = 58, R = 5, L = 84, TIP = 76, REST = 3, LIFT = 38;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-46, -24, 0], [64, 24, 0], [-46, -6, 118], [34, 6, 118], [80, 6, 60]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const rot = (deg) => {
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    return (dx, dz) => [PX + dx * c - dz * s, PZ + dx * s + dz * c];
  };
  function ext(el, prof, y0, y1) {
    const pts = [], f = [];
    for (const [x, z] of prof) { pts.push(P(x, y0, z), P(x, y1, z)); f.push(P(x, y1, z)); }
    el.setAttribute("d", poly(hull(pts)) + poly(f));
  }
  const box = (x0, y0, x1, y1, r, b, z0, z1) => { const [a, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, a, i, z0, z1)); };
  box(-46, -18, 26, 18, 5, 1.4, 0, 18);
  box(-44, -8, -28, 8, 4, 1.2, 18, PZ - 2);
  box(14, -24, 64, 24, 4, 1.4, 18, 22);
  const blade = mk("path", { class: "sil" }, g);
  const arm = mk("path", { class: "sil hi" }, g);
  const t = spring(REST);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const q = rot(v), o = [];
    for (let i = 0; i <= 10; i++) { const a = -Math.PI / 2 + (Math.PI * i) / 10; o.push(q(L + R * Math.cos(a), R * Math.sin(a))); }
    for (let i = 0; i <= 10; i++) { const a = Math.PI / 2 + (Math.PI * i) / 10; o.push(q(-8 + R * 1.4 * Math.cos(a), R * 1.4 * Math.sin(a))); }
    ext(arm, o, -5, 5);
    const [bx, bz] = q(TIP, -R), [cx, cz] = q(TIP, -(PZ - 22 + 1));
    blade.setAttribute("d", seg(P(bx, 0, bz), P(cx, 0, cz)) + seg(P(bx + 2, 0, bz - 2), P(bx - 2, 0, bz - 2)));
  }
  const B = register(stage, (dt) => { const m = stepS(t, dt); draw(t.x); return m; });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 22);
    if (x < -50 || x > 70 || y < -30 || y > 30) return -1;
    return clamp((x + 10) / 64, 0, 1);
  }
  let cur = -1;
  function set(v) {
    cur = v;
    t.t = v < 0 ? REST : REST + v * reach * LIFT;
    read.textContent = v < 0 ? "rest" : "arm " + Math.round(t.t) + "°";
    B.wake();
  }
  set(-1);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (cur >= 0) set(cur); }, destroy: bag.dispose };
}

hairline({
  name: "scrollsaw",
  means: "A scroll saw: the pointer over the table lifts the long upper arm on its hinge, drawing the fine blade up out of the table.",
  rules: [1, 3, 5, 6],
  range: [0.4, 1, 1],
  tour: [[205, 248], [256, 274], [230, 261], null],
  mount,
});

plungerouter.code:
/**
 * Plunge router: a round base, two posts standing on it, the motor riding
 * them on a collar with a knob at each end, its bit pointing down. The
 * pointer over the base plunges the motor down the posts and the bit through
 * the base, the nearer the front the deeper, on a spring. At rest it is
 * raised, the motor bright. The slider is how deep it plunges.
 */
const { Cam, circ, rings, clamp, facing, fit, prism, proj, seg, unproj, spring, stepS, mk, pointer, put, register, solid, disposer } = HL;

const BR = 34, PY = 24, PR = 2.6, TOP = 74, REST = 36, DEEP = 30, MR = 15, MH = 34;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));
function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.65);
  fit(C, [[-BR, -BR, 0], [BR, BR, 0], [BR, -BR, 0], [-BR, BR, 0], [0, 0, REST + MH + 10], [0, -PY, TOP], [0, PY, TOP]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, disc(0, 0, BR, 64), disc(0, 0, BR - 2, 64), 0, 4));
  const farLow = solid(g), farHigh = solid(g), farKnob = solid(g);
  const nearLow = solid(g), bit = mk("path", { class: "nf sil" }, g), collar = solid(g);
  const motor = solid(g), cap = solid(g), nearKnob = solid(g), nearHigh = solid(g);
  motor.sil.classList.add("hi");
  const t = spring(REST);
  let last = NaN;
  function draw(z) {
    if (z === last) return;
    last = z;
    const post = (s, y, z0, z1) => put(s, prism(P, front, disc(0, y, PR, 16), null, z0, z1));
    post(farLow, -PY, 4, z); post(farHigh, -PY, z + 5, TOP); post(nearLow, PY, 4, z); post(nearHigh, PY, z + 5, TOP);
    put(collar, prism(P, front, ...rings(-5.5, -PY - 9, 5.5, PY + 9, 5.5, 1.2), z, z + 5));
    put(farKnob, prism(P, front, disc(0, -PY - 9, 5, 20), disc(0, -PY - 9, 3.6, 20), z + 5, z + 14));
    put(nearKnob, prism(P, front, disc(0, PY + 9, 5, 20), disc(0, PY + 9, 3.6, 20), z + 5, z + 14));
    put(motor, prism(P, front, disc(0, 0, MR, 40), disc(0, 0, MR - 2, 40), z + 5, z + 5 + MH));
    put(cap, prism(P, front, disc(0, 0, 9, 28), disc(0, 0, 7.6, 28), z + 5 + MH, z + 10 + MH));
    bit.setAttribute("d", seg(P(0, 0, z), P(0, 0, Math.max(4.4, z - 16))));
  }
  const B = register(stage, (dt) => { const m = stepS(t, dt); draw(t.x); return m; });
  bag.add(B.unregister);
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 4);
    if (Math.hypot(x, y) > BR + 6) return -1;
    return clamp(0.35 + (x + y + BR) / (2 * BR) * 0.65, 0.35, 1);
  }
  let cur = -1;
  function set(v) {
    cur = v;
    t.t = v < 0 ? REST : REST - v * reach * DEEP;
    read.textContent = v < 0 ? "rest" : "depth " + Math.round(REST - t.t);
    B.wake();
  }
  set(-1);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (cur >= 0) set(cur); }, destroy: bag.dispose };
}

hairline({
  name: "plungerouter",
  means: "A plunge router: the pointer over the base plunges the motor down its two posts and drives the bit through the base.",
  rules: [1, 3, 5, 6],
  range: [0.3, 1, 1],
  tour: [[178, 232], [222, 236], [200, 259], null],
  mount,
});

pressurewasher.code:
/**
 * Pressure washer: the unit on two back wheels with its tall handle, a hose
 * from its outlet to the trigger gun, and the long lance, hung down along the
 * front at rest. The pointer's height is where the lance aims: it swings up
 * on the gun's pivot on a spring and the spray fans from its nozzle. At rest
 * it hangs, the lance bright. The slider is how far it can swing.
 */
const { Cam, clamp, facing, fit, hull, lerp, open, poly, prism, proj, rings, seg, spring, stepS, mk, pointer, put, register, solid, disposer } = HL;

const PX = 15, PZ = 56, WL = 60, REST = -62;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.4);
  fit(C, [[-26, -20, 0], [-26, 20, 0], [76, 0, 0], [72, 0, 92], [-20, 0, 78], [14, 16, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  function ext(el, prof, y0, y1) {
    const pts = [], f = [];
    for (const [x, z] of prof) { pts.push(P(x, y0, z), P(x, y1, z)); f.push(P(x, y1, z)); }
    el.setAttribute("d", poly(hull(pts)) + poly(f));
  }
  const wheel = (y0, y1) => { const pr = []; for (let i = 0; i < 28; i++) { const a = (i / 28) * Math.PI * 2; pr.push([-18 + 10 * Math.cos(a), 10 + 10 * Math.sin(a)]); } ext(mk("path", { class: "sil" }, g), pr, y0, y1); };
  wheel(-20, -15);
  put(solid(g), prism(P, front, ...rings(-20, -3, -16, 3, 1.5, 0.6), 44, 74));
  put(solid(g), prism(P, front, ...rings(-23, -12, -13, 12, 3, 1), 72, 77));
  put(solid(g), prism(P, front, ...rings(-16, -14, 12, 14, 7, 1.8), 6, 50));
  put(solid(g), prism(P, front, ...rings(-10, -10, 6, 10, 5, 1.4), 50, 56));
  wheel(15, 20);
  const hose = mk("path", { class: "nf" }, g);
  const spray = mk("path", { class: "dash nf" }, g);
  const grip = mk("path", { class: "sil" }, g), gun = mk("path", { class: "sil" }, g), lance = mk("path", { class: "sil hi" }, g);
  function capsule(el, ax, az, bx, bz, r, hw) {
    const a = Math.atan2(bz - az, bx - ax), prof = [];
    for (let i = 0; i <= 8; i++) { const t = a - Math.PI / 2 + (Math.PI * i) / 8; prof.push([bx + r * Math.cos(t), bz + r * Math.sin(t)]); }
    for (let i = 0; i <= 8; i++) { const t = a + Math.PI / 2 + (Math.PI * i) / 8; prof.push([ax + r * Math.cos(t), az + r * Math.sin(t)]); }
    ext(el, prof, -hw, hw);
  }
  const t = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = (deg * Math.PI) / 180, c = Math.cos(a), s = Math.sin(a);
    const at = (u, w) => [PX + u * c - w * s, PZ + u * s + w * c];
    const [g0x, g0z] = at(-12, 0), [g1x, g1z] = at(8, 0), [hx, hz] = at(-6, -14), [tx, tz] = at(WL, 0);
    capsule(grip, ...at(-6, 0), hx, hz, 2.6, 2.2);
    capsule(gun, g0x, g0z, g1x, g1z, 4.4, 3.4);
    capsule(lance, g1x, g1z, tx, tz, 2.2, 1.8);
    const hp = [];
    for (let i = 0; i <= 16; i++) { const u = i / 16, x = lerp(12, g0x, u), z = lerp(12, g0z, u) - 22 * Math.sin(Math.PI * u) * (1 - u * 0.4); hp.push(P(x, 8 * (1 - u), Math.max(1, z))); }
    hose.setAttribute("d", open(hp));
    const on = clamp((deg - REST) / 40, 0, 1);
    let d = "";
    if (on > 0.05) for (const k of [-1, 0, 1]) { const b = a + k * 0.16; d += seg(P(tx, 0, tz), P(tx + 22 * on * Math.cos(b), k * 4 * on, tz + 22 * on * Math.sin(b))); }
    spray.setAttribute("d", d);
  }
  const B = register(stage, (dt) => { const m = stepS(t, dt); draw(t.x); return m; });
  bag.add(B.unregister);
  const lo = P(40, 0, 0), hi = P(40, 0, 90), left = P(-26, 20, 0)[0], right = P(76, 0, 0)[0];
  function hit([sx, sy]) {
    if (sx < left - 10 || sx > right + 10 || sy < hi[1] - 20 || sy > P(14, 16, 0)[1] + 10) return -1;
    return clamp((lo[1] - sy) / (lo[1] - hi[1]), 0, 1);
  }
  let cur = -1;
  function set(v) {
    cur = v;
    t.t = v < 0 ? REST : REST + reach * lerp(30, 88, v);
    read.textContent = v < 0 ? "rest" : "aim " + Math.round(t.t) + "°";
    B.wake();
  }
  set(-1);
  bag.add(pointer(stage, { move: (p) => set(hit(p)), leave: () => set(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; if (cur >= 0) set(cur); }, destroy: bag.dispose };
}

hairline({
  name: "pressurewasher",
  means: "A pressure washer: the pointer's height swings the lance up on its trigger gun to aim, and the spray fans from the nozzle.",
  rules: [1, 3, 5, 6],
  range: [0.3, 1, 1],
  tour: [[250, 230], [276, 108], [265, 170], null],
  mount,
});

tiltrotor.code:
/**
 * Tiltrotor: a twin-rotor aircraft whose engine nacelles pivot at the
 * wingtips. At rest the nacelles lean forward, rotors almost upright for
 * cruise; the pointer over the aircraft tilts them up into hover, the rotor
 * discs turning flat overhead. The slider is how far they tilt.
 */
const {
  Cam, fit, hull, poly, proj, rings, prism, facing, rad, seg, tset, tval, tdone, tween, unproj,
  disposer, mk, pointer, register, solid, put,
} = HL;

const PX = 66, PZ = 26, WY = 64, RR = 32, A0 = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxA = value;
  const C = Cam(45, 0.5, 1.45);
  const ax = (a) => [Math.cos(rad(a)), Math.sin(rad(a))];
  const disc = (y, a, R, off) => {
    const [c, s] = ax(a), cx = PX + off * c, cz = PZ + off * s, out = [];
    for (let i = 0; i < 28; i++) { const t = (i / 28) * Math.PI * 2; out.push([cx - R * Math.sin(t) * s, y + R * Math.cos(t), cz + R * Math.sin(t) * c]); }
    return out;
  };
  const ext = [];
  for (const y of [-WY, WY]) for (const a of [0, 100]) ext.push(...disc(y, a, RR, 24));
  ext.push([0, 0, 0], [140, 0, 0], [6, 0, 44]);
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent) => { const s = solid(parent); const [rg, inn] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, rg, inn, z0, z1)); return s; };
  // one engine: nacelle body, rotor disc and three blades
  const engine = (y) => {
    const e = mk("g", {}, g);
    return { y, nac: mk("path", { class: "sil" }, e), cap: mk("path", { class: "nf lo" }, e), rot: mk("path", { class: "nf" }, e), bl: mk("path", { class: "nf lo" }, e) };
  };
  const far = engine(-WY);
  // tail: twin fins on a stabiliser, then fuselage, wing
  box(2, -6, 26, 6, 3, 1.2, 8, 30, g);
  const finA = box(4, -26, 18, -23, 1.5, 0.6, 26, 46, g);
  box(4, -26, 20, 26, 3, 1, 26, 29, g);
  box(0, -11, 142, 11, 10, 2, 6, 28, g);
  box(118, -9, 138, 9, 7, 1.6, 28, 32, g);
  box(56, -WY, 76, WY, 4, 1.4, 28, 31, g);
  box(4, 23, 18, 26, 1.5, 0.6, 26, 46, g);
  const near = engine(WY);
  void finA;
  const tw = tween(A0);
  let last = NaN;
  function drawEngine(E, a) {
    const [c, s] = ax(a), body = [];
    for (const off of [-12, 20]) body.push(...disc(E.y, a, 7, off).map((p) => P(...p)));
    E.nac.setAttribute("d", poly(hull(body)));
    E.cap.setAttribute("d", poly(disc(E.y, a, 5, 20).map((p) => P(...p))));
    const rim = disc(E.y, a, RR, 24);
    E.rot.setAttribute("d", poly(rim.map((p) => P(...p))));
    const hub = P(PX + 24 * c, E.y, PZ + 24 * s);
    let d = "";
    for (const i of [3, 12, 22]) d += seg(hub, P(...rim[i]));
    E.bl.setAttribute("d", d);
  }
  function draw(a) {
    if (a === last) return;
    last = a;
    drawEngine(far, a);
    drawEngine(near, a);
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? A0 + maxA : A0, performance.now(), 0);
    near.rot.classList.toggle("hi", true);
    far.rot.classList.toggle("hi", on);
    read.textContent = on ? "tilt " + Math.round(A0 + maxA) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 28);
    return (x > -4 && x < 146 && Math.abs(y) < 14) || (x > 40 && x < 96 && Math.abs(y) < WY + 12);
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { maxA = v; if (act) { tset(tw, A0 + v, performance.now(), 0); read.textContent = "tilt " + Math.round(A0 + v) + "°"; } B.wake(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "tiltrotor",
  means: "A tiltrotor aircraft: the pointer tilts both wingtip nacelles up from cruise into hover, the rotor discs turning flat.",
  rules: [1, 3, 5, 6],
  range: [40, 72, 82],
  tour: [[154, 199], [196, 172], [232, 160], null],
  mount,
});

lowloader.code:
/**
 * Low loader: a heavy-haul trailer with a raised gooseneck at the front, a
 * low deck and two loading ramps hinged at the tail. At rest the ramps stand
 * stowed upright, the near one bright; the pointer over the trailer lowers
 * them back onto the ground. The slider is how far they come down.
 */
const {
  Cam, fit, hull, poly, proj, rings, prism, facing, rrect, rad, clamp, tset, tval, tdone, tween, unproj,
  disposer, mk, pointer, register, solid, put,
} = HL;

const E = 166, L = 112, W = 56, DZ = 12, TZ = 18, RL = 46, RT = 3, UP = 78, LOW = -Math.asin(TZ / RL) * 180 / Math.PI;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxD = value;
  const C = Cam(45, 0.5, 1.62);
  // a ramp point: u along the ramp from the hinge, y across, w down through its thickness
  const rp = (u, y, w, th) => { const c = Math.cos(rad(th)), s = Math.sin(rad(th)); return [E + u * c + w * s, y, TZ + u * s - w * c]; };
  fit(C, [[E + RL, 0, 0], [E + RL, W, 0], [E, 0, TZ + RL], [-2, 0, 0], [-2, W, 0], [-2, 0, 40], [E - L, W, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, r, b, z0, z1, parent) => { const s = solid(parent); const [rg, inn] = rings(x0, y0, x1, y1, r, b); put(s, prism(P, front, rg, inn, z0, z1)); return s; };
  const wheel = (x, y0, y1) => {
    const pts = [];
    for (let i = 0; i < 20; i++) { const t = (i / 20) * Math.PI * 2; for (const y of [y0, y1]) pts.push(P(x + 8 * Math.cos(t), y, 8 + 8 * Math.sin(t))); }
    mk("path", { d: poly(hull(pts)), class: "sil" }, g);
  };
  const ramp = (y0, y1) => {
    const e = mk("g", {}, g);
    return { y0, y1, sil: mk("path", { class: "sil" }, e), cr: mk("path", { class: "nf lo" }, e), rib: mk("path", { class: "nf lo" }, e) };
  };
  // gooseneck at the far end, neck, far wheels, deck, near wheels, then the tail ramps
  box(6, 14, 16, W - 14, 3, 1, 22, 32, g);
  box(0, 2, E - L + 2, W - 2, 6, 1.8, 32, 40, g);
  box(E - L - 10, 4, E - L + 6, W - 4, 4, 1.4, DZ, 40, g);
  for (const x of [130, 150]) wheel(x, -2, 8);
  box(E - L, 0, E, W, 4, 1.6, DZ, TZ, g);
  for (const x of [130, 150]) wheel(x, W - 8, W + 2);
  const rA = ramp(4, 22), rB = ramp(34, 52);
  const ring = rrect(0, 0, RL, 1, 1.5, 3);
  function drawRamp(R, th) {
    const top = rrect(0, R.y0, RL, R.y1, 1.5, 3), inn = rrect(1.4, R.y0 + 1.4, RL - 1.4, R.y1 - 1.4, 1, 3);
    const pts = top.map((q) => P(...rp(q.u, q.v, 0, th))).concat(top.map((q) => P(...rp(q.u, q.v, RT, th))));
    R.sil.setAttribute("d", poly(hull(pts)));
    R.cr.setAttribute("d", poly(inn.map((q) => P(...rp(q.u, q.v, 0, th)))));
    let d = "";
    for (const u of [12, 24, 36]) d += "M" + P(...rp(u, R.y0 + 2, 0, th)).join(",") + "L" + P(...rp(u, R.y1 - 2, 0, th)).join(",");
    R.rib.setAttribute("d", d);
  }
  void ring;
  const tw = tween(UP);
  let last = NaN;
  function draw(th) {
    if (th === last) return;
    last = th;
    drawRamp(rA, th);
    drawRamp(rB, th);
  }
  const target = () => clamp(UP - maxD, LOW, UP);
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    tset(tw, on ? target() : UP, performance.now(), 0);
    rB.sil.classList.toggle("hi", true);
    rA.sil.classList.toggle("hi", on);
    read.textContent = on ? "ramp " + Math.round(UP - target()) + "°" : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TZ);
    return x > -2 && x < E + 12 && y > -2 && y < W + 2;
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { maxD = v; if (act) { tset(tw, target(), performance.now(), 0); read.textContent = "ramp " + Math.round(UP - target()) + "°"; } B.wake(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "lowloader",
  means: "A low loader trailer: the pointer lowers its two stowed tail ramps from upright down onto the ground for loading.",
  rules: [1, 3, 5, 6],
  range: [40, 98, 98],
  tour: [[180, 160], [203, 173], [224, 191], null],
  mount,
});

paraglider.code:
/**
 * Paraglider: an arched ram-air canopy of cells, its lines fanning down to a
 * pilot standing in the harness. The pointer over the glider swings the
 * canopy up from behind the pilot to overhead, as at launch. At rest the
 * canopy is half raised behind, bright. The slider is how far it swings up.
 *
 * The pattern: one part swinging about a pivot.
 */
const { Cam, fit, hull, poly, open, seg, proj, rad, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

const R = 74, HZ = 24, N = 10, SPAN = 58, LE = 13, TE = -15, REST = 58;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 2.0);
  // canopy samples before the swing, relative to the hang point
  const arc = (x, r) => { const o = []; for (let i = 0; i <= N; i++) { const f = rad(-SPAN + (2 * SPAN * i) / N); o.push([x, r * Math.sin(f), r * Math.cos(f)]); } return o; };
  const lead = arc(LE, R), trail = arc(TE, R), lip = arc(LE - 1, R - 4), att = arc(0, R - 3);
  const pitch = (p, d) => { const a = rad(d), c = Math.cos(a), s = Math.sin(a); return [p[0] * c - p[2] * s, p[1], HZ + p[0] * s + p[2] * c]; };
  const all = lead.concat(trail);
  const fp = all.map((p) => pitch(p, REST)).concat(all.map((p) => pitch(p, REST - 72)), [[0, -8, 0], [0, 8, 0], [10, 0, 0]]);
  fit(C, fp, 200, 164);
  const P = proj(C);
  const g = mk("g", {}, svg);
  mk("path", { d: open([P(-16, 0, 0), P(22, 0, 0)]), class: "dash nf" }, g);
  const lines = mk("path", { class: "nf lo" }, g);
  const can = mk("path", { class: "sil hi" }, g), ribs = mk("path", { class: "nf lo" }, g);
  // the pilot: harness body and helmet, standing at the hang point
  const blob = (z0, z1, r) => { const o = []; for (let j = 0; j < 12; j++) { const a = (j / 12) * Math.PI * 2; o.push(P(r * Math.cos(a), r * Math.sin(a), z0), P(r * Math.cos(a), r * Math.sin(a), z1)); } return poly(hull(o)); };
  mk("path", { d: blob(0, 19, 5), class: "sil" }, g);
  mk("path", { d: blob(21, 27, 3.6), class: "sil" }, g);
  mk("path", { d: seg(P(5, -5, HZ - 6), P(5, 5, HZ - 6)), class: "nf lo" }, g);
  const tw = tween(REST);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const Q = (p) => P(...pitch(p, d));
    const L = lead.map(Q), T = trail.map(Q);
    can.setAttribute("d", poly(L.concat(T.slice().reverse())));
    let r = open(lip.map(Q));
    for (let i = 1; i < N; i++) r += seg(L[i], T[i]);
    ribs.setAttribute("d", r);
    const h1 = P(2, -4, HZ - 4), h2 = P(2, 4, HZ - 4);
    let l = "";
    att.forEach((p, i) => { if (i % 2 === 0) l += seg(i < N / 2 ? h1 : h2, Q(p)); });
    lines.setAttribute("d", l);
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const rest = all.map((p) => P(...pitch(p, REST))).concat([P(0, 0, 0)]), xs = rest.map((q) => q[0]), ys = rest.map((q) => q[1]);
  const bx = [Math.min(...xs) - 10, Math.max(...xs) + 10, Math.min(...ys) - 10, Math.max(...ys) + 14];
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? REST - max : REST, performance.now(), 0);
    read.textContent = a ? "up " + Math.round(max) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3]), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "paraglider",
  means: "A paraglider canopy on its lines over the pilot: the pointer swings the arched wing up from behind to overhead.",
  rules: [1, 3, 5, 6],
  range: [40, 56, 72],
  tour: [[143, 95], [242, 111], [73, 196], null],
  mount,
});

dragster.code:
/**
 * Dragster: a long wedge of a car on fat rear slicks, tiny front wheels, a
 * rear wing up on struts and a drogue parachute packed at its tail. The
 * pointer over the car throws the chute: it streams back on its tether and
 * blooms open. At rest the chute is just out of its pack, bright. The slider
 * is how far it deploys.
 *
 * The pattern: one part sliding out and opening.
 */
const { Cam, fit, hull, poly, open, seg, proj, tween, tset, tval, tdone, disposer, mk, pointer, register } = HL;

const REST = 0.14, TAIL = [-2, 0, 18];
const chute = (d) => ({ x: -6 - 60 * d, r: 3 + 25 * d, z: 18 + 9 * d });

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.85);
  const car = [[-4, -24, 0], [130, 0, 0], [22, 24, 0], [0, -20, 44], [0, 20, 44], [130, 0, 11]];
  const big = chute(1);
  fit(C, car.concat([[big.x - big.r, 0, big.z + big.r], [big.x, -big.r, 0], [big.x, big.r, big.z + big.r]]), 200, 166);
  const P = proj(C), H = (pts) => poly(hull(pts.map((p) => P(...p))));
  const g = mk("g", {}, svg);
  mk("path", { d: open([P(-70, 0, 0), P(140, 0, 0)]), class: "dash nf" }, g);
  // the chute, its shroud lines and tether
  const dome = mk("path", { class: "sil hi" }, g), mouth = mk("path", { class: "nf lo" }, g), lines = mk("path", { class: "nf lo" }, g);
  const ringYZ = (x, r, z, n = 16) => { const o = []; for (let j = 0; j < n; j++) { const a = (j / n) * Math.PI * 2; o.push([x, r * Math.cos(a), z + r * Math.sin(a)]); } return o; };
  const wheel = (x, R, y0, y1, face) => { const a = ringYZ(0, 0, 0, 1); a.length = 0; for (let j = 0; j < 20; j++) { const t = (j / 20) * Math.PI * 2; a.push([x + R * Math.cos(t), y0, R + R * Math.sin(t)], [x + R * Math.cos(t), y1, R + R * Math.sin(t)]); }
    mk("path", { d: H(a), class: "sil" }, g);
    const f = []; for (let j = 0; j <= 20; j++) { const t = (j / 20) * Math.PI * 2; f.push(P(x + R * 0.62 * Math.cos(t), face, R + R * 0.62 * Math.sin(t))); }
    mk("path", { d: open(f), class: "nf lo" }, g); };
  wheel(22, 14, -24, -12, -12);
  wheel(118, 5, -10, -7, -7);
  // the body: a wedge from the engine bay to the needle nose
  mk("path", { d: H([[6, -9, 6], [40, -9, 6], [6, 9, 6], [40, 9, 6], [6, -9, 20], [6, 9, 20], [40, -8, 19], [40, 8, 19], [130, -3, 7], [130, 3, 7], [130, -2, 11], [130, 2, 11]]), class: "sil" }, g);
  mk("path", { d: poly([[9, -7, 19.4], [126, -1.6, 10.6], [126, 1.6, 10.6], [9, 7, 19.4]].map((p) => P(...p))), class: "nf lo" }, g);
  mk("path", { d: H([[44, -5, 17], [56, -5, 15], [44, 5, 17], [56, 5, 15], [46, -4, 27], [50, -4, 27], [46, 4, 27], [50, 4, 27]]), class: "sil" }, g);
  mk("path", { d: seg(P(6, -8, 19), P(4, -8, 42)) + seg(P(6, 8, 19), P(4, 8, 42)), class: "nf" }, g);
  mk("path", { d: H([[-2, -20, 41], [14, -20, 43], [-2, 20, 41], [14, 20, 43], [-2, -20, 44], [14, -20, 45], [-2, 20, 44], [14, 20, 45]]), class: "sil" }, g);
  mk("path", { d: seg(P(-1, -18, 44), P(-1, 18, 44)), class: "nf lo" }, g);
  wheel(118, 5, 7, 10, 10);
  wheel(22, 14, 12, 24, 24);
  const tw = tween(REST);
  let last = NaN;
  function draw(d) {
    if (d === last) return;
    last = d;
    const { x, r, z } = chute(d), cap = [];
    for (let i = 0; i <= 4; i++) { const f = (i / 4) * Math.PI / 2; cap.push(...ringYZ(x - r * 0.75 * Math.sin(f), r * Math.cos(f) + 0.3, z)); }
    dome.setAttribute("d", H(cap));
    const rim = ringYZ(x, r, z, 24);
    mouth.setAttribute("d", poly(rim.map((p) => P(...p))));
    const cf = [x + r * 1.5, 0, z], L = ringYZ(x, r, z, 8);
    lines.setAttribute("d", L.map((p) => seg(P(...p), P(...cf))).join("") + seg(P(...cf), P(...TAIL)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tw, now)); return !tdone(tw, now); });
  bag.add(B.unregister);
  const rest = car.map((p) => P(...p)), xs = rest.map((q) => q[0]), ys = rest.map((q) => q[1]);
  const bx = [Math.min(...xs) - 8, Math.max(...xs) + 8, Math.min(...ys) - 8, Math.max(...ys) + 8];
  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(tw, a ? max : REST, performance.now(), 0);
    read.textContent = a ? "chute " + Math.round(max * 100) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: ([sx, sy]) => setActive(sx > bx[0] && sx < bx[1] && sy > bx[2] && sy < bx[3]), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "dragster",
  means: "A dragster on its slicks under the rear wing: the pointer throws the drogue chute, which streams back on its tether and blooms open.",
  rules: [1, 3, 5, 6],
  range: [0.6, 0.8, 1],
  tour: [[268, 222], [203, 115], [340, 264], null],
  mount,
});

airboat.code:
/**
 * Airboat: a flat swamp hull with a raised driver's seat, and at its stern a
 * tall round fan cage with three rudder vanes behind it. The pointer's side of
 * the boat steers: the whole cage and its rudders swing round their post to
 * throw the wind that way, the propeller turning inside. At rest the cage
 * stands a little askew, its rim bright. The slider is how far it can swing.
 *
 * The pattern: one part turning to follow the pointer (spring).
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rings, circ, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const PX = -30, CZ = 30, CR = 19, REST = 0.22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxT = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 2.6);
  fit(C, [[-44, -24, 0], [40, 24, 0], [-44, 24, 52], [-44, -24, 52], [40, 0, 6]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [hr, hi] = rings(-38, -16, 38, 16, 10, 2);
  put(solid(g), prism(P, front, hr, hi, 0, 8));
  const [br, bi] = rings(18, -14, 38, 14, 9, 2);
  put(solid(g), prism(P, front, br, bi, 8, 10));
  const post = mk("path", { class: "nf" }, g);
  post.setAttribute("d", open([P(PX, 0, 8), P(PX, 0, CZ)]));
  const rudG = mk("g", {}, g);
  const rud = [0, 1, 2].map(() => mk("path", {}, rudG));
  const cageG = mk("g", {}, g);
  const back = mk("path", { class: "nf" }, cageG), rim = mk("path", { class: "nf hi" }, cageG);
  const spokes = mk("path", { class: "nf" }, cageG), prop = mk("path", { class: "nf" }, cageG);
  const [sr, si] = rings(-6, -7, 6, 7, 3, 1.5);
  const seatG = mk("g", {}, g);
  const leg = mk("path", { class: "nf" }, seatG);
  leg.setAttribute("d", open([P(-10, -5, 8), P(-10, -5, 24)]) + open([P(-10, 5, 8), P(-10, 5, 24)]));
  put(solid(seatG), prism(P, front, sr.map((q) => ({ ...q, u: q.u - 10 })), si.map((q) => ({ ...q, u: q.u - 10 })), 24, 27));
  const sb = mk("path", {}, seatG);
  sb.setAttribute("d", poly([P(-16, -7, 27), P(-16, 7, 27), P(-17, 7, 38), P(-17, -7, 38)]));

  const th = spring(REST);
  let last = NaN;
  function draw(a) {
    if (Math.abs(a - last) < 0.002) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const W = (ax, b, z) => P(PX + ax * c - b * s, ax * s + b * c, z);
    const ring = (ax, r) => circ(r, 28).map((q) => W(ax, q.u, CZ + q.v));
    back.setAttribute("d", poly(ring(-3, CR)));
    rim.setAttribute("d", poly(ring(2, CR)));
    let sp = "";
    for (let k = 0; k < 4; k++) { const t = k * Math.PI / 4; sp += open([W(2, CR * Math.cos(t), CZ + CR * Math.sin(t)), W(2, -CR * Math.cos(t), CZ - CR * Math.sin(t))]); }
    spokes.setAttribute("d", sp);
    const pa = a * 4 + 0.6, pc = Math.cos(pa) * (CR - 3), ps = Math.sin(pa) * (CR - 3);
    prop.setAttribute("d", poly([W(-1, pc, CZ + ps), W(-1, -ps * 0.12, CZ + pc * 0.12), W(-1, -pc, CZ - ps), W(-1, ps * 0.12, CZ - pc * 0.12)]));
    [-11, 0, 11].forEach((b, i) => {
      rud[i].setAttribute("d", poly([W(-7, b, CZ - 15), W(-19, b, CZ - 13), W(-19, b, CZ + 14), W(-7, b, CZ + 16)]));
    });
  }
  draw(REST);

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(th.x); return m; });
  bag.add(B.unregister);

  let lastP = null;
  function aim(p) {
    const w = p && unproj(C, p[0], p[1], 0);
    if (!w || Math.abs(w[0]) > 70 || Math.abs(w[1]) > 60) { th.t = REST; read.textContent = "rest"; }
    else {
      th.t = clamp(-w[1] / 30, -1, 1) * maxT;
      const d = Math.round((th.t * 180) / Math.PI);
      read.textContent = "rud " + (d > 0 ? "+" : "") + d;
    }
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => { lastP = p; aim(p); }, leave: () => { lastP = null; aim(null); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxT = (v * Math.PI) / 180; if (lastP) aim(lastP); }, destroy: bag.dispose };
}

