amphibian.code:
/**
 * Amphibious car: a boat hull below, a rounded car cabin with a windscreen
 * line above, and four wheels on swing arms at its sides. Bring the pointer
 * to it and the wheels fold up and out of the water, spreading from the wheel
 * nearest the pointer, turning flat as they lift. At rest the wheels stand
 * down, the rear pair half tucked, the front near wheel bright. The slider is
 * how far they fold.
 *
 * The pattern: parts folding with a stagger by distance (tween).
 */
const {
  Cam, clamp, fit, facing, open, poly, prism, proj, rings, tween, tset, tval, tdone, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const WR = 8, L = 9.85, B0 = 0.42;
const WH = [[20, -1], [-20, -1], [20, 1], [-20, 1]];
const RESTR = [0.05, 0.45, 0.05, 0.45];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let maxR = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 3.6);
  fit(C, [[-36, -34, 0], [36, 34, 0], [-36, 34, 30], [36, -34, 30], [36, 34, 0]], 200, 168);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const far = mk("g", {}, g), body = mk("g", {}, g), near = mk("g", {}, g);
  const wheels = WH.map(([x, s], i) => {
    const par = s < 0 ? far : near;
    const arm = mk("path", { class: "nf lo" }, par), disc = mk("path", { class: "sil" }, par), hub = mk("path", { class: "nf" }, par);
    return { x, s, arm, disc, hub, tw: tween(RESTR[i]), last: NaN };
  });
  const [hr, hi] = rings(-36, -13, 36, 13, 11, 2);
  put(solid(body), prism(P, front, hr, hi, 6, 15));
  const [cr, ci] = rings(-22, -11, 16, 11, 8, 2);
  put(solid(body), prism(P, front, cr, ci, 15, 26));
  const ws = mk("path", { class: "nf lo" }, body);
  ws.setAttribute("d", open([P(16, -10, 22), P(16, 10, 22)]) + open([P(-14, -11, 21), P(-14, 11, 21)]));

  let chosen = 0;
  function drawWheel(w, r, hiOn) {
    w.disc.classList.toggle("hi", hiOn);
    if (Math.abs(r - w.last) < 0.002) return;
    w.last = r;
    const b = B0 + r, hy = w.s * 12, hz = 18;
    const cy = hy + w.s * L * Math.sin(b), cz = hz - L * Math.cos(b);
    const ey = -w.s * Math.sin(r), ez = Math.cos(r);
    const pts = [];
    for (let k = 0; k < 24; k++) { const t = (k / 24) * Math.PI * 2, a = WR * Math.cos(t), e = WR * Math.sin(t); pts.push(P(w.x + a, cy + e * ey, cz + e * ez)); }
    w.disc.setAttribute("d", poly(pts));
    const hp = [];
    for (let k = 0; k < 12; k++) { const t = (k / 12) * Math.PI * 2, a = 3 * Math.cos(t), e = 3 * Math.sin(t); hp.push(P(w.x + a, cy + e * ey, cz + e * ez)); }
    w.hub.setAttribute("d", poly(hp));
    w.arm.setAttribute("d", open([P(w.x, hy, hz), P(w.x, cy, cz)]));
  }
  let active = false;
  function drawAll(now) {
    wheels.forEach((w, i) => drawWheel(w, tval(w.tw, now), active ? i === chosen : i === 2));
  }
  drawAll(0);

  const B = register(stage, (dt, now) => { drawAll(now); return wheels.some((w) => !tdone(w.tw, now)); });
  bag.add(B.unregister);

  let lastP = null;
  function aim(p) {
    const now = performance.now();
    const w = p && unproj(C, p[0], p[1], 0);
    active = !!w && Math.abs(w[0]) < 48 && Math.abs(w[1]) < 34;
    if (!active) {
      wheels.forEach((wh, i) => tset(wh.tw, RESTR[i], now, 0));
      read.textContent = "rest";
    } else {
      let best = 1e9;
      wheels.forEach((wh, i) => { const d = Math.hypot(w[0] - wh.x, w[1] - wh.s * 16); if (d < best) { best = d; chosen = i; } });
      const c = wheels[chosen];
      wheels.forEach((wh, i) => { const d = (Math.abs(wh.x - c.x) > 0 ? 1 : 0) + (wh.s !== c.s ? 1 : 0); tset(wh.tw, clamp(maxR, 0, 2), now, d * 45); });
      read.textContent = "up " + Math.round((maxR * 180) / Math.PI);
    }
    B.wake();
  }
  read.textContent = "rest";
  bag.add(pointer(stage, { move: (p) => { lastP = p; aim(p); }, leave: () => { lastP = null; aim(null); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { maxR = (v * Math.PI) / 180; if (lastP) aim(lastP); }, destroy: bag.dispose };
}

hairline({
  name: "amphibian",
  means: "An amphibious car afloat: bring the pointer near and its four wheels fold up and out of the water, spreading from the nearest.",
  rules: [2, 3, 5, 8],
  range: [40, 90, 100],
  tour: [[210, 199], [250, 160], [190, 107], null],
  mount,
});

utv.code:
/**
 * Side-by-side UTV: two seats under a tubular roll cage, a short hood up front
 * and a dump bed behind the cage, hinged at its tail. The pointer's place
 * across the frame tips the bed up on its hinge, its front rising over the
 * cage. At rest the bed is cracked up a few degrees, bright. The slider is
 * how far it tips.
 *
 * The pattern: one hinged part (swing).
 */
const { Cam, clamp, facing, fit, hull, open, poly, prism, proj, rad, rings, ringAt, rrect, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const L = 136, W = 60, Z0 = 14, ZB = 24, BL = 62, BH = 20, R = 14, REST = 6;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = value;
  const C = Cam(45, 0.5, 1.75);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [2 + BL * Math.cos(rad(55)), 0, ZB + BL * Math.sin(rad(55)) + BH * Math.cos(rad(55))], [0, W, ZB + BH], [100, 0, 70]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(x + R * Math.cos(t), y, R + R * Math.sin(t))); }
    return pts;
  };
  const hub = (x, y) => {
    const pts = [];
    for (let i = 0; i < 12; i++) { const t = (i / 12) * Math.PI * 2; pts.push(P(x + 5 * Math.cos(t), y, R + 5 * Math.sin(t))); }
    return pts;
  };
  for (const x of [26, 112]) mk("path", { d: poly(wheel(x, 6)) }, g);
  const [chr, chi] = rings(0, 8, L, W - 8, 4, 1.2);
  put(solid(g), prism(P, front, chr, chi, Z0, ZB - 1));
  const bed = mk("path", { class: "sil hi" }, g), rim = mk("path", { class: "nf lo" }, g);
  const seats = solid(g);
  put(seats, prism(P, front, ...rings(70, 10, 88, W - 10, 3, 1), ZB - 1, 36));
  for (const y of [12, W - 12]) mk("path", { d: seg(P(70, y, 36), P(66, y, 50)), class: "nf lo" }, g);
  const foot = rrect(104, 6, L, W - 6, 8, 6), top = rrect(106, 9, L - 6, W - 9, 6, 6);
  const hood = solid(g);
  hood.sil.setAttribute("d", poly(hull(ringAt(P, foot, ZB - 2).concat(ringAt(P, top, 36)))));
  mk("path", { d: open(ringAt(P, rrect(108, 12, L - 9, W - 12, 4, 4), 36)), class: "nf lo" }, g);
  for (const y of [6, W - 6]) mk("path", { d: open([P(66, y, ZB), P(70, y, 66), P(102, y, 66), P(108, y, 38)]), class: "nf" }, g);
  for (const x of [70, 102]) mk("path", { d: seg(P(x, 6, 66), P(x, W - 6, 66)), class: "nf" }, g);
  for (const x of [26, 112]) { mk("path", { d: poly(wheel(x, W - 6)) }, g); mk("path", { d: poly(hub(x, W - 6)), class: "nf lo" }, g); }
  const ang = spring(REST);
  let last = NaN;

  const bp = (y, d, zl, a) => P(2 + d * Math.cos(rad(a)) - zl * Math.sin(rad(a)), y, ZB + d * Math.sin(rad(a)) + zl * Math.cos(rad(a)));
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const y of [4, W - 4]) for (const d of [0, BL]) for (const zl of [0, BH]) pts.push(bp(y, d, zl, a));
    bed.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly([bp(8, 4, BH, a), bp(8, BL - 4, BH, a), bp(W - 8, BL - 4, BH, a), bp(W - 8, 4, BH, a)]));
  }
  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  function aim(a, r) { ang.t = a; read.textContent = r ? "rest" : Math.round(a) + "°"; B.wake(); }
  draw(REST);
  aim(REST, true);
  bag.add(pointer(stage, { move: ([sx]) => aim(REST + clamp((340 - sx) / 220, 0, 1) * (max - REST)), leave: () => aim(REST, true) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = v; }, destroy: bag.dispose };
}

hairline({
  name: "utv",
  means: "A side-by-side UTV with a dump bed hinged behind its roll cage: the pointer tips the bed up, its front rising over the cage.",
  rules: [1, 3, 5, 6],
  range: [24, 42, 55],
  tour: [[260, 250], [190, 160], [140, 140], null],
  mount,
