gullwing.code:
/**
 * Gullwing coupe: a low sports car whose two doors are hinged at the middle
 * of the roof. At rest the near door stands a little open, bright. The
 * pointer over the car swings both doors up like wings, on a spring; the
 * slider sets how far they lift.
 */
const {
  Cam, fit, facing, hull, poly, open, prism, proj, rings, ringAt, rrect, unproj, rad, clamp,
  spring, stepS, disposer, mk, pointer, put, register, solid,
} = HL;

const L = 96, W = 40, HZ = 32, HY = W / 2, D0 = 34, D1 = 62, REST = 22;
const PROF = [[HY, HZ], [HY + 11, HZ], [W - 3, 18], [W, 9]];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amax = value;
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [48, W + 6, 52], [48, -6, 52]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  function wheel(cx, y, par) {
    const pts = [];
    for (let i = 0; i < 24; i++) { const t = (i / 24) * Math.PI * 2; pts.push(P(cx + 9 * Math.cos(t), y, 9 + 9 * Math.sin(t))); }
    mk("path", { d: poly(pts), class: "sil" }, par);
    const hub = [];
    for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; hub.push(P(cx + 4 * Math.cos(t), y, 9 + 4 * Math.sin(t))); }
    mk("path", { d: poly(hub), class: "nf lo" }, par);
  }
  wheel(20, 2, g); wheel(76, 2, g);
  const farDoor = mk("g", {}, g);
  const fs = mk("path", { class: "sil" }, farDoor), fc = mk("path", { class: "nf lo" }, farDoor);
  // body: low wedge, then the cabin tapering to the roof
  const [br, bi] = rings(0, 0, L, W, 12, 2);
  put(solid(g), prism(P, front, br, bi, 5, 17));
  const foot = rrect(22, 2, 76, W - 2, 8, 6), top = rrect(D0 + 1, HY - 11, D1 - 3, HY + 11, 5, 6), inner = rrect(D0 + 3, HY - 9, D1 - 5, HY + 9, 3, 6);
  const cab = solid(g);
  put(cab, { sil: poly(hull(ringAt(P, foot, 17).concat(ringAt(P, top, HZ)))), crease: open(ringAt(P, inner, HZ)) });
  wheel(20, W - 2, g); wheel(76, W - 2, g);
  const nearDoor = mk("g", {}, g);
  const ns = mk("path", { class: "sil hi" }, nearDoor), nc = mk("path", { class: "nf lo" }, nearDoor);

  function doorPts(a, side) {
    const out = [];
    for (const [y, z] of PROF) {
      const dy = (y - HY) * side, dz = z - HZ;
      const ry = dy * Math.cos(a) - dz * Math.sin(a), rz = dy * Math.sin(a) + dz * Math.cos(a);
      out.push([HY + ry * side, HZ + rz]);
    }
    return out;
  }
  function drawDoor(a, side, s, c) {
    const pr = doorPts(a, side), A = pr.map(([y, z]) => P(D0, y, z)), B = pr.map(([y, z]) => P(D1, y, z));
    s.setAttribute("d", poly(hull(A.concat(B))));
    let d = "";
    for (let i = 1; i < pr.length - 1; i++) d += open([A[i], B[i]]) + " ";
    c.setAttribute("d", d + open(A) + " " + open(B));
  }

  const op = spring(REST);
  let last = NaN;
  function draw(v) {
    if (v === last) return;
    last = v;
    const a = rad(v);
    drawDoor(a, -1, fs, fc);
    drawDoor(a, 1, ns, nc);
  }
  const B = register(stage, (dt) => { const m = stepS(op, dt); draw(op.x); return m; });
  bag.add(B.unregister);

  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    const on = x > -10 && x < L + 10 && y > -30 && y < W + 30;
    op.t = on ? REST + (amax - REST) * clamp((x + 10) / (L * 0.6), 0.35, 1) : REST;
    read.textContent = on ? "door " + Math.round(op.t) + "°" : "rest";
    B.wake();
  }
  read.textContent = "rest";
  draw(REST);
  bag.add(pointer(stage, { move, leave: () => { op.t = REST; read.textContent = "rest"; B.wake(); } }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amax = v; B.wake(); }, destroy: bag.dispose };
}

hairline({
  name: "gullwing",
  means: "A gullwing coupe: the pointer over the car swings both roof-hinged doors up like wings; the slider sets how far.",
  rules: [1, 3, 5, 8],
  range: [50, 105, 125],
  tour: [[160, 190], [244, 234], [290, 240], null],
  mount,
});

kitesurf.code:
/**
 * Kitesurf rig: a board on the water, the control bar above it and two lines
 * running up to a curved arc kite. The pointer's side of the frame steers the
 * kite: it sweeps across the wind window and dips low at its edges, on a
 * spring. At rest it flies off to one side, its leading edge bright. The
 * slider is how far the kite may sweep.
 *
 * The pattern: one part swinging to follow the pointer.
 */
const {
  Cam, clamp, facing, fit, hull, open, poly, prism, proj, rings, seg, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const BZ = 26, LN = 105, R = 40, CH = 15, BASE = Math.PI * 1.25, REST = 0.45, MAXS = 1.25;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 1.8);
  function kite(sw) {
    const el = 1.0 - 0.45 * Math.abs(sw) / MAXS, ph = BASE + sw;
    const u = [Math.cos(el) * Math.cos(ph), Math.cos(el) * Math.sin(ph), Math.sin(el)], s = [-Math.sin(ph), Math.cos(ph), 0];
    const c = [u[1] * s[2] - u[2] * s[1], u[2] * s[0] - u[0] * s[2], u[0] * s[1] - u[1] * s[0]];
    const at = (psi, ch) => [0, 1, 2].map((k) => (k === 2 ? BZ : 0) + u[k] * LN + R * Math.sin(psi) * s[k] - R * (1 - Math.cos(psi)) * u[k] + ch * c[k]);
    return { at, s };
  }
  const ext = [];
  for (const sw of [-MAXS, -0.6, 0, 0.6, MAXS]) { const k = kite(sw); for (const p of [-1.3, 0, 1.3]) for (const h of [-CH, 0, CH]) ext.push(k.at(p, h)); }
  fit(C, ext.concat([[-26, -9, 0], [26, 9, 0]]), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const canopy = mk("path", { class: "sil" }, g), struts = mk("path", { class: "nf lo" }, g), le = mk("path", { class: "nf hi" }, g), lines = mk("path", { class: "nf lo" }, g);
  const [br, bi] = rings(-26, -9, 26, 9, 8, 1.4);
  put(solid(g), prism(P, front, br, bi, 0, 2));
  mk("path", { d: open([P(-6, -11, BZ), P(-6, 11, BZ)]), class: "sil" }, g);
  mk("path", { d: seg(P(-6, -5, 2), P(-6, -5, BZ)) , class: "dash nf" }, g);

  const sp = spring(REST);
  let last = NaN;
  function draw(sw) {
    if (sw === last) return;
    last = sw;
    const k = kite(sw), lead = [], trail = [];
    for (let i = 0; i <= 16; i++) { const psi = -1.3 + (2.6 * i) / 16; lead.push(P(...k.at(psi, 0))); trail.push(P(...k.at(psi * 0.96, CH * Math.cos(psi * 0.8)))); }
    canopy.setAttribute("d", poly(lead.concat(trail.reverse())));
    let d = "";
    for (const psi of [-0.78, -0.26, 0.26, 0.78]) d += seg(P(...k.at(psi, 0)), P(...k.at(psi * 0.96, CH * Math.cos(psi * 0.8))));
    struts.setAttribute("d", d);
    le.setAttribute("d", open(lead));
    const t0 = k.at(-1.3, CH * 0.3), t1 = k.at(1.3, CH * 0.3);
    lines.setAttribute("d", seg(P(-6, -10, BZ), P(...(k.s[1] > 0 ? t0 : t1))) + seg(P(-6, 10, BZ), P(...(k.s[1] > 0 ? t1 : t0))));
  }

  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setAim(p) {
    act = p;
    sp.t = p ? clamp((p[0] - 200) / 130, -1, 1) * reach : REST;
    read.textContent = p ? (sp.t < 0 ? "L " : "R ") + Math.round(Math.abs(sp.t) * 180 / Math.PI) + "°" : "rest";
    B.wake();
  }
  setAim(null);
  draw(sp.x);
  bag.add(pointer(stage, { move: setAim, leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = clamp((v * Math.PI) / 180, 0, MAXS); if (act) setAim(act); }, destroy: bag.dispose };
}

hairline({
  name: "kitesurf",
  means: "A kitesurf rig, board, bar and arc kite: the kite sweeps across the wind window toward the pointer's side, as far as the slider lets it.",
  rules: [1, 3, 5, 8],
  range: [20, 65, 70],
  tour: [[60, 120], [340, 120], [60, 120], null],
  mount,
});

junkship.code:
/**
 * Junk ship: a broad hull with a high stern, one mast and its battened lug
 * sail. The pointer over the ship hoists the sail: the yard climbs the mast
 * and the battens fan open one above another. At rest the sail is folded in
 * a low stack on the boom, the yard bright. The slider is how high it hoists.
 *
 * The pattern: one part rising and opening.
 */
const {
  Cam, clamp, fit, fillet, hull, open, poly, proj, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, register,
} = HL;

const L = 130, W = 17, D = 14, NB = 7, H = 112, MX = 10, GAP = 3, REST = 0.08, N = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let top = value;
  const C = Cam(45, 0.5, 1.6);
  const ZB = D + 9;
  fit(C, [[-L / 2, -W, 0], [L / 2, W, 0], [-L / 2, 0, D + 14], [MX, 0, ZB + H + 8], [-50, 0, ZB + H + 10]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const half = (t, w) => w * Math.pow(Math.sin(Math.PI * clamp(t, 0.04, 1)), 0.55);
  const deck = (t) => D + 13 * Math.pow(1 - t, 5) + 5 * Math.pow(t, 6);
  function outline(len, w, zf) {
    const pts = [];
    for (let s = -1; s <= 1; s += 2) for (let i = 0; i <= N; i++) {
      const t = s > 0 ? i / N : 1 - i / N;
      pts.push(P((t - 0.5) * len, s * half(t, w), zf(t)));
    }
    return pts;
  }
  mk("path", { d: poly(hull(outline(L * 0.8, W * 0.6, () => 0).concat(outline(L, W, deck)))), class: "sil" }, g);
  mk("path", { d: poly(outline(L - 6, W - 2.4, (t) => deck(t) - 0.6)), class: "nf lo" }, g);
  // the mast, a thin pole from the deck past the hoisted yard
  mk("path", { d: poly(hull([P(MX - 1.2, 0, D), P(MX + 1.2, 0, D), P(MX - 1.2, 0, ZB + H + 8), P(MX + 1.2, 0, ZB + H + 8)])), class: "sil" }, g);

  const sail = mk("path", { class: "sil" }, g), bat = mk("path", { class: "nf lo" }, g), yard = mk("path", { class: "nf hi" }, g);
  // each batten keeps its own reach: the sail fans out wide low, narrow high
  const xa = (i) => -54 + 22 * Math.pow(i / NB, 1.4), xb = (i) => MX + 16 - 6 * (i / NB);
  const hz = tween(REST);
  let last = NaN;
  function draw(f) {
    if (f === last) return;
    last = f;
    const lo = [], hi = [];
    let d = "";
    for (let i = 0; i <= NB; i++) {
      const z = ZB + i * (GAP + (H / NB - GAP) * f), tz = z + 2.2 * i * f;
      const a = P(xa(i), 0, tz), b = P(xb(i), 0, z);
      lo.push(a); hi.push(b);
      if (i > 0 && i < NB) d += seg(a, b);
    }
    const ring = lo.concat(hi.reverse());
    sail.setAttribute("d", poly(fillet(ring, ring.map(() => 1.5))));
    bat.setAttribute("d", d);
    yard.setAttribute("d", open([lo[NB], ring[NB + 1]]));
  }

  const B = register(stage, (_dt, now) => { draw(tval(hz, now)); return !tdone(hz, now); });
  bag.add(B.unregister);

  const box = [P(-L / 2, W, 0), P(L / 2, -W, 0), P(L / 2, W, 0), P(-L / 2, -W, 0), P(-54, 0, ZB + H + 12), P(MX + 16, 0, ZB + H + 12)];
  const bx0 = Math.min(...box.map((q) => q[0])), bx1 = Math.max(...box.map((q) => q[0]));
  const by0 = Math.min(...box.map((q) => q[1])), by1 = Math.max(...box.map((q) => q[1]));
  let act = null;
  function setAim(p) {
    const on = !!p && p[0] > bx0 && p[0] < bx1 && p[1] > by0 && p[1] < by1;
    act = on;
    tset(hz, on ? top : REST, performance.now(), 0);
    read.textContent = on ? "up " + Math.round(top * 100) : "rest";
    B.wake();
  }
  setAim(null);
  draw(REST);
  bag.add(pointer(stage, { move: setAim, leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { top = v; if (act) { tset(hz, top, performance.now(), 0); read.textContent = "up " + Math.round(top * 100); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "junkship",
  means: "A junk ship with one battened sail: the pointer over the ship hoists the yard and the folded sail fans open, as high as the slider sets.",
  rules: [1, 5, 6, 8],
  range: [0.4, 1, 1],
  tour: [[187, 191], [266, 266], [176, 130], null],
  mount,
});

coracle.code:
/**
 * Coracle: a round woven boat on a ring of water, a seat plank across its
 * bowl and one long paddle resting on the rim. The pointer stands on the
 * water and the paddle sweeps round its rim pivot to reach for it, on a
 * spring. At rest the paddle trails at a slant, its blade bright. The
 * slider is how far the paddle may sweep.
 *
 * The pattern: one part turning to face the pointer.
 */
const {
  Cam, circ, clamp, fit, fillet, hull, poly, proj, ringAt, seg, spring, stepS, unproj,
  disposer, mk, pointer, register,
} = HL;

const RB = 20, RT = 30, H = 14, QX = 22, QY = 22, QZ = H, PITCH = 0.42, REST = 1.25;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = (value * Math.PI) / 180;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-RT, -RT, 0], [QX + 75, QY + 75, -25], [QX + 75, -30, 0], [-30, QY + 75, 0], [0, 0, H + 6]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  mk("path", { d: poly(ringAt(P, circ(RT + 22, 48), 0)), class: "dash nf" }, g);
  const ring = (r, z) => ringAt(P, circ(r, 40), z);
  mk("path", { d: poly(hull(ring(RB, 0).concat(ring(RT, H)))), class: "sil" }, g);
  mk("path", { d: poly(ring(RT - 2.2, H - 0.4)), class: "nf lo" }, g);
  // the seat plank across the bowl, and a few woven ribs on the outside
  let d = seg(P(-RT + 3, -4, H - 3), P(RT - 3, -4, H - 3)) + seg(P(-RT + 3, 4, H - 3), P(RT - 3, 4, H - 3));
  for (const t of [0.45, 0.85, 1.25]) d += seg(P(RB * Math.cos(t), RB * Math.sin(t), 0.5), P(RT * Math.cos(t), RT * Math.sin(t), H - 0.8));
  mk("path", { d, class: "nf lo" }, g);

  const shaft = mk("path", { class: "sil" }, g), blade = mk("path", { class: "sil" }, g), grip = mk("path", { class: "nf lo" }, g);
  const yaw = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const ca = Math.cos(a), sa = Math.sin(a), cp = Math.cos(PITCH), sp = Math.sin(PITCH);
    const pt = (s, w) => P(QX + s * cp * ca - w * sa, QY + s * cp * sa + w * ca, QZ - s * sp);
    shaft.setAttribute("d", poly([pt(-32, -1.3), pt(40, -1.3), pt(40, 1.3), pt(-32, 1.3)]));
    blade.setAttribute("d", poly(fillet([pt(36, -2), pt(46, -8), pt(78, -8), pt(78, 8), pt(46, 8), pt(36, 2)], [1, 3, 4, 4, 3, 1])));
    grip.setAttribute("d", seg(pt(-32, -6), pt(-32, 6)) + seg(pt(50, 0), pt(74, 0)));
  }

  const B = register(stage, (dt) => { const m = stepS(yaw, dt); draw(yaw.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setAim(p) {
    if (!p) {
      yaw.t = REST; act = null;
      read.textContent = "rest";
    } else {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (Math.hypot(x - QX, y - QY) < 6) return;
      let dd = Math.atan2(y - QY, x - QX) - REST;
      dd = Math.atan2(Math.sin(dd), Math.cos(dd));
      yaw.t = REST + clamp(dd, -reach, reach);
      act = p;
      const deg = Math.round((((yaw.t * 180) / Math.PI) % 360 + 360) % 360);
      read.textContent = String(deg).padStart(3, "0") + "°";
    }
    blade.classList.add("hi");
    B.wake();
  }
  setAim(null);
  draw(yaw.x);
  bag.add(pointer(stage, { move: setAim, leave: () => setAim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = (v * Math.PI) / 180; if (act) setAim(act); }, destroy: bag.dispose };
}

hairline({
  name: "coracle",
  means: "A round woven coracle on the water: its long paddle sweeps round the rim to reach for the pointer, as far as the slider lets it.",
  rules: [1, 3, 5, 8],
  range: [20, 80, 120],
  tour: [[341, 154], [30, 97], [341, 154], null],
  mount,
});

velomobile.code:
/**
 * Velomobile: a recumbent bike's long egg shell on three small wheels, with
 * a bubble canopy over the cockpit. The pointer over the shell is a hand on
 * the hatch: the canopy swings up on its front hinge and shows the seat and
 * the pedal boom inside. At rest it is cracked open a little and bright.
 * The slider is how far the canopy opens.
 */
const {
  Cam, circ, clamp, fit, hull, poly, proj, seg, unproj, spring, stepS,
  disposer, mk, pointer, register,
} = HL;

const HL2 = 60, BY = 17, ZC = 24, BZ = 15, XH = 30, REST = 0.12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.8);
  fit(C, [[-HL2, -BY, 0], [HL2, BY, 0], [-HL2, 0, ZC + BZ], [HL2, 0, ZC], [-20, 0, 80], [XH, BY, 50]], 200, 165);
  const P = proj(C);
  const f = (x) => Math.pow(Math.max(0, 1 - (x / HL2) ** 2), 0.45);
  const topZ = (x, y) => { const k = f(x); return ZC + BZ * k * Math.sqrt(Math.max(0, 1 - (y / (BY * k + 1e-6)) ** 2)); };
  const g = mk("g", {}, svg);
  // wheels first: they sit under the shell
  const wheel = (x, y) => mk("path", { class: "sil", d: poly(circ(8, 24).map((q) => P(x + q.u, y, 8 + q.v))) }, g);
  wheel(-44, 0); wheel(34, -12); wheel(34, 12);
  // the shell: the hull of its cross sections
  const shell = [];
  for (let i = 0; i <= 24; i++) {
    const x = -HL2 + (i / 24) * 2 * HL2, k = f(x);
    for (let j = 0; j < 20; j++) { const t = (j / 20) * Math.PI * 2; shell.push(P(x, BY * k * Math.cos(t), ZC + BZ * k * Math.sin(t))); }
  }
  mk("path", { class: "sil", d: poly(hull(shell)) }, g);
  const belt = [];
  for (let i = 0; i <= 30; i++) { const x = -HL2 * 0.97 + (i / 30) * 1.94 * HL2; belt.push(P(x, BY * f(x) - 1.2, ZC)); }
  mk("path", { class: "nf lo", d: "M" + belt.map((p) => p.join(",")).join("L") }, g);
  // the cockpit opening, the seat and the pedal boom inside it
  const lip = circ(1, 40).map((q) => { const x = 3 + 25 * q.u, y = 11 * q.v; return [x, y, topZ(x, y)]; });
  mk("path", { class: "nf", d: poly(lip.map((p) => P(...p))) }, g);
  const sx = [], bk = [];
  for (const x of [-16, -6]) for (const y of [-7, 7]) { sx.push(P(x, y, ZC + 4)); sx.push(P(x, y, ZC + 7)); }
  for (const x of [-20, -16]) for (const y of [-7, 7]) { bk.push(P(x, y, ZC + 4)); bk.push(P(x, y, ZC + 18)); }
  mk("path", { class: "sil", d: poly(hull(bk)) }, g);
  mk("path", { class: "sil", d: poly(hull(sx)) }, g);
  mk("path", { class: "nf", d: seg(P(0, 0, ZC + 6), P(22, 0, ZC + 10)) + seg(P(22, -5, ZC + 7), P(22, 5, ZC + 13)) }, g);
  // the canopy: lip plus a raised inner ring, hinged on its front edge
  const dome = lip.concat(lip.map(([x, y, z]) => [3 + (x - 3) * 0.62, y * 0.62, z + 10]));
  const zh = topZ(XH - 2, 0);
  const can = mk("path", { class: "sil hi" }, g), canLip = mk("path", { class: "nf lo" }, g);
  const ang = spring(REST);
  let maxA = 1.25 * value, over = false, last = -1;

  function draw() {
    if (Math.abs(ang.x - last) < 1e-4) return;
    last = ang.x;
    const c = Math.cos(ang.x), s = Math.sin(ang.x);
    const rot = ([x, y, z]) => { const dx = x - XH, dz = z - zh; return P(XH + dx * c + dz * s, y, zh + dz * c - dx * s); };
    can.setAttribute("d", poly(hull(dome.map(rot))));
    canLip.setAttribute("d", poly(lip.map(rot)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    ang.t = over ? Math.max(REST, maxA) : REST;
    read.textContent = over ? `open ${Math.round((ang.t * 180) / Math.PI)}°` : "rest";
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], ZC);
      over = Math.abs(x) < HL2 + 15 && Math.abs(y) < BY + 22;
      retarget();
    },
    leave: () => { over = false; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { maxA = 1.25 * v; retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "velomobile",
  means: "A velomobile's egg shell on three wheels: point at it and the bubble canopy swings up on its hinge to show the seat.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[206, 140], [130, 120], [255, 165], null],
  mount,
});

landyacht.code:
/**
 * Land yacht: a long spine on three wheels, a cross beam at the back, a
 * tall mast and one triangular sail on a boom. The pointer on the ground is
 * where the wind comes from: the boom swings round the mast to set the sail
 * against it, on a spring. At rest the sail is sheeted a little to one side
 * and bright. The slider is how far the boom may swing.
 */
const {
  Cam, circ, clamp, fit, facing, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const MX = 14, MT = 104, BZ = 20, BL = 62, REST = 0.4;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-52, -38, 0], [50, 38, 0], [MX, 0, MT], [MX - BL, -BL, BZ], [MX - BL, BL, BZ]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const wheel = (x, y) => mk("path", { class: "sil", d: poly(circ(9, 24).map((q) => P(x + q.u, y, 9 + q.v))) }, g);
  wheel(-30, -36);
  const [cr, ci] = rings(-34, -38, -26, 38, 2.5, 0.8);
  put(solid(g), prism(P, front, cr, ci, 9, 14));
  const [sr, si] = rings(-52, -4, 50, 4, 3, 1);
  put(solid(g), prism(P, front, sr, si, 10, 16));
  const [er, ei] = rings(-26, -7, -8, 7, 4, 1);
  put(solid(g), prism(P, front, er, ei, 16, 22));
  wheel(46, 0);
  wheel(-30, 36);
  const mast = mk("path", { class: "nf sil" }, g);
  mast.setAttribute("d", seg(P(MX, 0, 16), P(MX, 0, MT)));
  const sail = mk("path", { class: "sil hi" }, g), bat = mk("path", { class: "nf lo" }, g), boom = mk("path", { class: "nf sil" }, g);
  const ang = spring(REST);
  let maxA = 1.35 * value, over = null, last = 99;

  function draw() {
    if (Math.abs(ang.x - last) < 1e-4) return;
    last = ang.x;
    const c = Math.cos(ang.x), s = Math.sin(ang.x);
    const at = (t, z) => P(MX - BL * t * c, -BL * t * s, z);
    const leech = [];
    for (let i = 0; i <= 10; i++) {
      const t = i / 10, z = BZ + (MT - BZ) * (1 - t), bl = 6 * Math.sin(t * Math.PI);
      leech.push(P(MX - BL * t * c + s * bl, -BL * t * s - c * bl, z));
    }
    sail.setAttribute("d", poly([P(MX, 0, BZ)].concat(leech.reverse())));
    const b = [];
    for (const t of [0.3, 0.55, 0.8]) {
      const z = BZ + (MT - BZ) * (1 - t);
      b.push(seg(P(MX, 0, z), at(t, z)));
    }
    bat.setAttribute("d", b.join(""));
    boom.setAttribute("d", seg(P(MX, 0, BZ), at(1.04, BZ)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(); return m; });
  bag.add(B.unregister);

  function retarget() {
    ang.t = over == null ? REST : clamp(over, -maxA, maxA);
    read.textContent = over == null ? "rest" : `boom ${Math.round((ang.t * 180) / Math.PI)}°`;
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      over = Math.hypot(x, y) > 140 ? null : Math.atan2(-y, MX + 20 - x);
      retarget();
    },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  retarget();
  return {
    set: (v) => { maxA = 1.35 * v; retarget(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "landyacht",
  means: "A land yacht on three wheels: the pointer is the wind, and the boom swings the sail round the mast to meet it.",
  rules: [1, 3, 5, 8],
  range: [0.4, 1, 1],
  tour: [[330, 180], [173, 221], [250, 255], null],
  mount,
});

canallock.code:
/**
 * Canal lock gates: a stone lock chamber, two walls on a floor slab, closed by
 * a pair of mitre gates, each with a long balance beam over its wall. The
 * pointer over the lock swings the gates open against the walls, the nearer
 * one first. At rest they stand almost shut, one a little ajar, its beam bright.
 * The slider is how far they swing open.
 */
const {
  Cam, fit, facing, poly, prism, proj, rad, rings, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X0 = -40, X1 = 40, CH = 20, WD = 13, WH = 8, GH = 19, L = 18.8, BL = 26, OPEN = 78;
const REST = [0.14, 0.03];

function place(ring, a, hx, hy) {
  const c = Math.cos(a), s = Math.sin(a);
  return ring.map((q) => ({ u: hx + q.u * c - q.v * s, v: hy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[X0, -CH - WD, -4], [X1, CH + WD, -4], [X1, -CH - WD, -4], [X0, CH + WD, -4], [-6, -CH - BL, GH + 4], [-6, CH + BL, GH + 4], [X0, -CH - WD, GH + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(X0 - 4, -CH - WD - 4, X1 + 4, CH + WD + 4, 3, 1.4);
  put(solid(g), prism(P, front, br, bi, -4, 0));
  const [fr, fi] = rings(X0, -CH - WD, X1, -CH, 2, 1.2);
  put(solid(g), prism(P, front, fr, fi, 0, WH));
  const water = mk("path", { class: "nf", d: poly([P(X0, -CH, 5), P(X1, -CH, 5), P(X1, CH, 5), P(X0, CH, 5)]) }, g);
  water.classList.add("dash");
  const [gr, gi] = rings(0, -1.6, L, 1.6, 1, 0.6);
  const [bmr, bmi] = rings(-BL, -1.2, L - 2, 1.2, 1, 0.5);
  const gates = [-1, 1].map((sd) => ({ sd, hy: sd * (CH - 1.6), gate: solid(g) }));
  const [nr, ni] = rings(X0, CH, X1, CH + WD, 2, 1.2);
  put(solid(g), prism(P, front, nr, ni, 0, WH));
  for (const gt of gates) { gt.beam = solid(g); }
  const tw = gates.map((_, i) => tween(REST[i]));
  const last = [NaN, NaN];

  function draw(i, f) {
    if (f === last[i]) return;
    last[i] = f;
    const gt = gates[i], a = rad(-gt.sd * OPEN * (1 - f));
    put(gt.gate, prism(P, front, place(gr, a, 0, gt.hy), place(gi, a, 0, gt.hy), 0, GH));
    put(gt.beam, prism(P, front, place(bmr, a, 0, gt.hy), place(bmi, a, 0, gt.hy), GH, GH + 3.5));
  }
  const B = register(stage, (_dt, now) => {
    let m = false;
    tw.forEach((t, i) => { draw(i, tval(t, now)); if (!tdone(t, now)) m = true; });
    return m;
  });
  bag.add(B.unregister);

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    act = a;
    const now = performance.now();
    tw.forEach((t, i) => tset(t, a < 0 ? REST[i] : reach, now, a < 0 ? 0 : Math.abs(i - a) * 60));
    const hi = a < 0 ? 1 : a;
    gates.forEach((gt, i) => gt.beam.sil.classList.toggle("hi", i === hi));
    read.textContent = a < 0 ? "rest" : `open ${a + 1}`;
    B.wake();
  }
  function move([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, WH);
    const inside = x > X0 - 12 && x < X1 + 12 && Math.abs(y) < CH + WD + 18;
    setActive(inside ? (y < 0 ? 0 : 1) : -1);
  }
  bag.add(pointer(stage, { move, leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  setActive(-1);
  return { set: (v) => { reach = v; if (act >= 0) { const a = act; act = -2; setActive(a); } }, destroy: bag.dispose };
}

hairline({
  name: "canallock",
  means: "A canal lock whose pair of mitre gates, each with a long balance beam, swing open against the walls under the pointer.",
  rules: [1, 2, 3, 4, 5],
  range: [0.3, 1, 1],
  tour: [[262, 148], [86, 179], [314, 190], null],
  mount,
});

barge.code:
/**
 * Barge: a long, low hull with a wheelhouse at the stern and three hatch
 * covers over the hold. The pointer picks a cover by where it is along the
 * barge: that cover swings open on its far hinge, the ones beside it lift a
 * little, staggered from it. At rest the middle cover stands ajar, bright.
 * The slider is how far a cover opens.
 */
const {
  Cam, clamp, facing, fit, fillet, hull, open, poly, prism, proj, rad, rings, seg, tdone, tset, tval, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 140, W = 40, HZ = 10, CZ = 15, X0 = 30, CW = 34, GAP = 2, N = 3, REST = [4, 38, 8], FAV = 1;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[0, 0, 0], [L, W, 0], [L, 0, 0], [0, W, 0], [8, 8, 32], [80, 4, CZ + W - 6], [80, -20, CZ + 20]], 200, 170);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the hull: a long low solid with a rubbing strake
  const hl = solid(g);
  const [hr, hi] = rings(0, 0, L, W, 12, 1.8);
  put(hl, prism(P, front, hr, hi, 0, HZ));
  mk("path", { class: "nf lo", d: seg(P(10, W, 4), P(L - 12, W, 4)) }, hl.g);
  // the wheelhouse at the stern, with a stack
  const wh = solid(g);
  const [wr, wi] = rings(5, 8, 22, W - 8, 3, 0.9);
  put(wh, prism(P, front, wr, wi, HZ, HZ + 18));
  mk("path", { class: "nf lo", d: seg(P(22, 12, HZ + 13), P(22, W - 12, HZ + 13)) }, wh.g);
  // the hold's coaming
  const co = solid(g);
  const [cr, ci] = rings(X0 - 2, 3, X0 + N * (CW + GAP), W - 3, 3, 1);
  put(co, prism(P, front, cr, ci, HZ, CZ));

  // the covers: plates hinged along the far edge (y = 4) at the coaming's top
  const covers = [];
  for (let k = 0; k < N; k++) covers.push({ x: X0 + k * (CW + GAP), s: solid(g), a: tween(REST[k]), last: NaN });
  function draw(c, deg) {
    if (deg === c.last) return;
    c.last = deg;
    const t = rad(deg), D = W - 8, cs = Math.cos(t), sn = Math.sin(t);
    const at = (u, v, h) => P(c.x + u, 4 + v * cs - h * sn, CZ + v * sn + h * cs);
    const pts = [];
    for (const u of [0, CW]) for (const v of [0, D]) for (const h of [0, 2]) pts.push(at(u, v, h));
    c.s.sil.setAttribute("d", poly(fillet(hull(pts), Array(hull(pts).length).fill(1.2))));
    c.s.cr.setAttribute("d", open([at(1, D - 1, 2), at(CW - 1, D - 1, 2)]) + seg(at(CW / 2 - 3, D - 5, 2), at(CW / 2 + 3, D - 5, 2)));
  }
  const B = register(stage, (_dt, now) => {
    let moving = false;
    covers.forEach((c) => { draw(c, tval(c.a, now)); if (!tdone(c.a, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // the hit: on the deck's plane, then the cover whose rest centre is nearest on screen x
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, CZ);
    if (x < X0 - 12 || x > L || y < -30 || y > W + 8) return -1;
    let best = -1, bd = Infinity;
    covers.forEach((c, k) => { const d = Math.abs(P(c.x + CW / 2, W / 2, CZ)[0] - sx); if (d < bd) { bd = d; best = k; } });
    return best;
  }
  let act = -2;
  function setActive(a, force) {
    if (a === act && !force) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    covers.forEach((c, k) => {
      const z = a < 0 ? REST[k] : clamp(amp * (1 - 0.42 * Math.abs(k - a)), 0, amp);
      tset(c.a, z, now, from < 0 ? 0 : Math.abs(k - from) * 45);
      c.s.sil.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : "hold " + (a + 1);
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = clamp(v, 50, 120); setActive(act, true); }, destroy: bag.dispose };
}

hairline({
  name: "barge",
  means: "A barge with three hatch covers over its hold: the cover under the pointer swings open on its hinge, its neighbours lift a little.",
  rules: [1, 2, 5, 6],
  range: [50, 100, 120],
  tour: [[168, 150], [218, 175], [270, 201], null],
  mount,
});

loftladder.code:
/**
 * Loft ladder: a hatch in the ceiling with its door hanging half open. The
 * pointer on the floor below calls the ladder down: the door swings to its
 * full angle and the ladder slides out of its end, one section for a far
 * pointer, all three when the pointer stands at the foot. At rest the door
 * hangs ajar, bright. The slider is the door's open angle.
 *
 * The pattern: one part swinging, a second sliding out of it.
 */
const {
  Cam, fit, open, poly, proj, rings, prism, facing, rrect, ringAt, unproj, rad, clamp,
  tween, tset, tval, tdone, disposer, mk, pointer, put, register, solid, seg,
} = HL;

const H = 70, DL = 40, DW = 24, REST = 34;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let ang = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-14, -14, 0], [70, 40, 0], [70, -14, 0], [-14, 40, 0], [-10, -8, H], [50, 32, H]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [fr, fi] = rings(-14, -14, 70, 40, 8, 2);
  put(solid(g), prism(P, front, fr, fi, -4, 0));
  // the hatch: its trim and its opening, in the ceiling line
  mk("path", { d: poly(ringAt(P, rrect(-8, -6, DL + 8, DW + 6, 4, 4), H)), class: "nf lo" }, g);
  mk("path", { d: poly(ringAt(P, rrect(0, 0, DL, DW, 1, 2), H)), class: "nf" }, g);
  const door = mk("path", { class: "sil" }, g), doorT = mk("path", { class: "nf lo" }, g);
  const rungs = mk("path", { class: "nf lo" }, g), rails = mk("path", { class: "nf sil" }, g);

  const a = tween(REST), e = tween(0);
  let last = "";
  function draw(A, E) {
    const key = A.toFixed(2) + "," + E.toFixed(2);
    if (key === last) return;
    last = key;
    const c = Math.cos(rad(A)), s = Math.sin(rad(A));
    const at = (t, y, dz = 0) => P(t * c, y, H - t * s + dz);
    door.setAttribute("d", poly([at(0, 1), at(0, DW - 1), at(DL, DW - 1), at(DL, 1)]));
    doorT.setAttribute("d", open([at(DL, 1), at(DL, 1, -1.6), at(DL, DW - 1, -1.6), at(DL, DW - 1)]));
    let rd = "", rr = "";
    const end = DL + E;
    for (const y of [5, DW - 5]) rr += open([at(DL * 0.35, y, 1), at(end, y, 1)]);
    for (let t = DL * 0.35 + 6; t < end - 1; t += 9) rd += seg(at(t, 5, 1), at(t, DW - 5, 1));
    rails.setAttribute("d", rr);
    rungs.setAttribute("d", rd);
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(a, now), tval(e, now));
    return !(tdone(a, now) && tdone(e, now));
  });
  bag.add(B.unregister);

  const foot = () => [H / Math.tan(rad(ang)), DW / 2];
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    if (x < -14 || x > 70 || y < -14 || y > 40) return -1;
    const [fx, fy] = foot(), d = Math.hypot(x - fx, y - fy);
    return d < 18 ? 3 : d < 34 ? 2 : 1;
  }

  let act = -2;
  function setActive(k) {
    if (k === act) return;
    act = k;
    const now = performance.now(), full = H / Math.sin(rad(ang)) - DL;
    tset(a, k < 0 ? REST : ang, now, 0);
    tset(e, k < 0 ? 0 : clamp(full * k / 3, 0, full), now, k < 0 ? 0 : 90);
    door.classList.toggle("hi", k < 0);
    rails.classList.toggle("hi", k >= 0);
    read.textContent = k < 0 ? "rest" : k + "/3";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { ang = v; last = ""; act = -2; setActive(-1); }, destroy: bag.dispose };
}

hairline({
  name: "loftladder",
  means: "A ceiling hatch with its door ajar: the pointer on the floor swings it open and slides the ladder down, section by section.",
  rules: [1, 3, 5, 8],
  range: [52, 60, 68],
  tour: [[113, 216], [284, 237], [220, 236], null],
  mount,
});

pergola.code:
/**
 * Louvred pergola: four posts carrying a frame, and a roof of slats that
 * turn on their long axes. The pointer over the roof opens the slats, the
 * one under it the furthest and the rest a little less, staggered from it.
 * At rest the roof is shut but for one slat standing ajar, bright. The
 * slider is how far the slats open.
 *
 * The pattern: a field of parts turning, spread from the pointer.
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, unproj, rad, clamp,
  tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid,
} = HL;

const L = 84, W = 56, H = 52, N = 8, PITCH = L / N, HW = 6.4, FAV = 5, REST = 8, AJAR = 50;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[-8, -8, 0], [L + 8, W + 8, 0], [L + 8, -8, 0], [-8, W + 8, 0], [0, 0, H + 8], [L, W, H + 8]], 200, 162);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [gr, gi] = rings(-8, -8, L + 8, W + 8, 8, 2);
  put(solid(g), prism(P, front, gr, gi, -3, 0));
  const box = (x0, y0, x1, y1, z0, z1) => { const [a, b] = rings(x0, y0, x1, y1, 1.2, 0.6); put(solid(g), prism(P, front, a, b, z0, z1)); };
  // posts, far to near
  for (const [x, y] of [[0, 0], [L, 0], [0, W], [L, W]]) box(x - 2, y - 2, x + 2, y + 2, 0, H - 3);
  // far beams
  box(-3, -3, L + 3, 1, H - 3, H + 3);
  box(-3, -3, 1, W + 3, H - 3, H + 3);

  const slats = [];
  for (let i = 0; i < N; i++) {
    const xc = PITCH * (i + 0.5), body = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g);
    slats.push({ i, xc, body, face, t: tween(i === FAV ? AJAR : REST), last: NaN });
  }
  // near beams, over the slats' ends
  box(-3, W - 1, L + 3, W + 3, H - 3, H + 3);
  box(L - 1, -3, L + 3, W + 3, H - 3, H + 3);

  function draw(s, A) {
    if (A === s.last) return;
    s.last = A;
    const c = Math.cos(rad(A)), sn = Math.sin(rad(A)), th = 1.3;
    const pt = (u, y, d) => P(s.xc + u * c + d * sn, y, H - u * sn + d * c);
    const top = [pt(-HW, 2, 0), pt(HW, 2, 0), pt(HW, W - 2, 0), pt(-HW, W - 2, 0)];
    const bot = [pt(-HW, 2, -th), pt(HW, 2, -th), pt(HW, W - 2, -th), pt(-HW, W - 2, -th)];
    s.body.setAttribute("d", poly(hull(top.concat(bot))));
    s.face.setAttribute("d", open([top[3], top[0], top[1]]));
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    for (const s of slats) { draw(s, tval(s.t, now)); if (!tdone(s.t, now)) moving = true; }
    return moving;
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, H);
    if (x < -6 || x > L + 6 || y < -10 || y > W + 10) return -1;
    return clamp(Math.floor(x / PITCH), 0, N - 1);
  }

  let act = -2;
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    slats.forEach((s, k) => {
      const d = Math.abs(k - a);
      const to = a < 0 ? (k === FAV ? AJAR : REST) : amp * Math.max(0.45, 1 - 0.14 * d);
      tset(s.t, to, now, from < 0 ? 0 : Math.abs(k - from) * 40);
      s.body.classList.toggle("hi", k === (a < 0 ? FAV : a));
    });
    read.textContent = a < 0 ? "rest" : a + 1 + "/" + N;
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; const a = act; act = -2; setActive(a); }, destroy: bag.dispose };
}

hairline({
  name: "pergola",
  means: "A pergola roofed with slats: the pointer over the roof turns them open, the one under it furthest, the rest staggered from it.",
  rules: [1, 2, 5, 8],
  range: [40, 70, 88],
  tour: [[191, 110], [151, 91], [250, 140], null],
  mount,
});

gateleg.code:
/**
 * Gateleg table: a narrow fixed top on four legs, with a drop leaf hinged
 * along its near side. The pointer over the table raises the leaf, and a
 * gate under it swings out on its pivot to carry the leaf's far edge. At
 * rest the leaf hangs part-way down, bright. The slider is how far the leaf
 * rises.
 *
 * The pattern: one part swinging up, a second swinging out to hold it.
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rings, seg, unproj, rad,
  tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid,
} = HL;

const CW = 34, D = 60, LW = 30, TH = 40, PX = CW - 7, PY = 12, G = 22, REST = 22;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amp = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-6, -6, 0], [CW + LW + 6, D + 6, 0], [CW + LW + 6, -6, 0], [-6, D + 6, 0], [0, 0, TH], [CW + LW, D, TH]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 1) => { const [a, b] = rings(x0, y0, x1, y1, r, 0.6); put(solid(par), prism(P, front, a, b, z0, z1)); };
  const [fr, fi] = rings(-6, -6, CW + LW + 6, D + 6, 8, 2);
  put(solid(g), prism(P, front, fr, fi, -3, 0));
  box(g, 2, 2, 5, 5, 0, TH - 3);
  box(g, CW - 5, 2, CW - 2, 5, 0, TH - 3);
  box(g, 2, D - 5, 5, D - 2, 0, TH - 3);
  box(g, PX - 1.2, PY - 1.2, PX + 1.2, PY + 1.2, 3, TH - 3);
  const gate = mk("g", {}, g), rails = mk("path", { class: "nf" }, gate), legG = mk("g", {}, gate);
  box(g, CW - 5, D - 5, CW - 2, D - 2, 0, TH - 3);
  box(g, 0, 0, CW, D, TH - 3, TH, 2);
  const leaf = mk("path", { class: "sil" }, g), face = mk("path", { class: "nf lo" }, g);

  const lift = tween(REST), swing = tween(0);
  let last = "";
  function draw(A, S) {
    const key = A.toFixed(2) + "," + S.toFixed(2);
    if (key === last) return;
    last = key;
    const dl = rad(90 - A), c = Math.cos(dl), s = Math.sin(dl);
    const pt = (u, y, d) => P(CW + u * c + d * s, y, TH - 3 - u * s + d * c);
    const top = [pt(0, 0, 3), pt(LW, 0, 3), pt(LW, D, 3), pt(0, D, 3)];
    const bot = [pt(0, 0, 0), pt(LW, 0, 0), pt(LW, D, 0), pt(0, D, 0)];
    const h = hull(top.concat(bot));
    leaf.setAttribute("d", poly(fillet(h, h.map(() => 1.5))));
    face.setAttribute("d", open([top[0], top[1], top[2]]));
    const ps = rad(S), lx = PX + G * Math.sin(ps), ly = PY + G * Math.cos(ps);
    rails.setAttribute("d", seg(P(PX, PY, TH - 7), P(lx, ly, TH - 7)) + seg(P(PX, PY, 6), P(lx, ly, 6)));
    legG.replaceChildren();
    box(legG, lx - 1.5, ly - 1.5, lx + 1.5, ly + 1.5, 0, TH - 3);
  }

  const B = register(stage, (_dt, now) => {
    draw(tval(lift, now), tval(swing, now));
    return !(tdone(lift, now) && tdone(swing, now));
  });
  bag.add(B.unregister);

  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, TH);
    return x > -8 && x < CW + LW + 8 && y > -10 && y < D + 10 ? 1 : -1;
  }

  let act = -2;
  function setActive(k) {
    if (k === act) return;
    act = k;
    const now = performance.now();
    tset(lift, k < 0 ? REST : amp, now, k < 0 ? 140 : 0);
    tset(swing, k < 0 ? 0 : 90 * amp / 90, now, k < 0 ? 0 : 160);
    leaf.classList.toggle("hi", true);
    read.textContent = k < 0 ? "rest" : Math.round(amp) + "°";
    B.wake();
  }
  setActive(-1);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amp = v; const k = act; act = -2; setActive(k); }, destroy: bag.dispose };
}

hairline({
  name: "gateleg",
  means: "A gateleg table: the pointer over it raises the drop leaf, and a gate leg swings out underneath to carry it.",
  rules: [1, 3, 5, 8],
  range: [55, 78, 90],
  tour: [[176, 107], [180, 93], [197, 134], null],
  mount,
});

weatherballoon.code:
/**
 * Weather balloon: a launch pad on the ground with a stake, a tether running
 * up through a small radiosonde box to a big round balloon with a tied neck.
 * The pointer swings the balloon on its tether: the further the pointer sits
 * to one side of the pad, the further the balloon leans over that way, the
 * sonde riding along the line. At rest it leans a little, the sonde bright.
 * The slider is how far the balloon may swing.
 */
const { Cam, circ, clamp, facing, fit, hull, open, poly, prism, proj, rings, run, seg, spring, stepS, disposer, mk, pointer, put, register, solid } = HL;

const R = 27, LEN = 82, AZ = 3, MAX = 0.62, A0 = -0.14, Q = Math.SQRT1_2;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.0);
  const tip = (a) => [Q * Math.sin(a) * (LEN + R), -Q * Math.sin(a) * (LEN + R), AZ + Math.cos(a) * (LEN + R)];
  fit(C, [[-24, -24, 0], [24, 24, 0], tip(MAX), tip(-MAX), [0, 0, AZ + LEN + R]].concat([MAX, -MAX, 0].map((a) => { const t = tip(a); return [t[0], t[1], t[2] + R]; })), 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-20, -20, 20, 20, 20, 1.6), 0, 3));
  put(solid(g), prism(P, front, ...rings(-1.6, -1.6, 1.6, 1.6, 1.6, 0.5), 3, AZ + 4));
  const line = mk("path", { class: "nf sil" }, g);
  const sonde = solid(g), bal = solid(g);
  const ax = P(0, 0, 0)[0];
  const sp = spring(A0);
  let lim = (MAX * value) / 1.4, last = NaN, over = null;
  const sph = [];
  for (let la = -90; la <= 90; la += 10) for (let lo = 0; lo < 360; lo += 10) {
    const p = (la * Math.PI) / 180, l = (lo * Math.PI) / 180;
    sph.push([R * Math.cos(p) * Math.cos(l), R * Math.cos(p) * Math.sin(l), R * Math.sin(p)]);
  }
  const eq = run(circ(R, 40), front);
  function draw() {
    const a = sp.x;
    if (Math.abs(a - last) < 1e-4) return;
    last = a;
    const d = [Q * Math.sin(a), -Q * Math.sin(a), Math.cos(a)];
    const c = [d[0] * (LEN + R), d[1] * (LEN + R), AZ + d[2] * (LEN + R)];
    const neck = [c[0] - d[0] * (R + 6), c[1] - d[1] * (R + 6), c[2] - d[2] * (R + 6)];
    const s = [neck[0] * 0.42, neck[1] * 0.42, AZ + (neck[2] - AZ) * 0.42];
    line.setAttribute("d", seg(P(0, 0, AZ + 4), P(...neck)));
    put(sonde, prism(P, front, ...rings(s[0] - 5, s[1] - 5, s[0] + 5, s[1] + 5, 1.8, 0.7), s[2] - 9, s[2]));
    bal.sil.setAttribute("d", poly(hull(sph.map((p) => P(c[0] + p[0], c[1] + p[1], c[2] + p[2])).concat([P(...neck)]))));
    bal.cr.setAttribute("d", open(eq.map((q) => P(c[0] + q.u, c[1] + q.v, c[2] - 2))));
  }
  bal.cr.setAttribute("class", "nf lo");
  const B = register(stage, (dt) => { const m = stepS(sp, dt); draw(); return m; });
  bag.add(B.unregister);
  function swing(t) {
    sp.t = t === null ? A0 : t * lim;
    bal.sil.classList.toggle("hi", t !== null);
    sonde.sil.classList.toggle("hi", t === null);
    read.textContent = t === null ? "rest" : Math.round((sp.t * 180) / Math.PI) + "°";
    B.wake();
  }
  bag.add(pointer(stage, {
    move: (p) => { over = clamp((p[0] - ax) / 110, -1, 1); swing(over); },
    leave: () => { over = null; swing(null); },
  }));
  bag.add(() => svg.replaceChildren());
  draw(); swing(null);
  return { set: (v) => { lim = (MAX * v) / 1.4; if (over !== null) swing(over); }, destroy: bag.dispose };
}

