pantograph.code:
/**
 * Pantograph: four flat arms pinned into a parallelogram, the long pair
 * hinged to a clamp at the far corner of the board. A stylus rides at the
 * middle joint and a pencil at the far end, drawing twice as large. The
 * pointer leads the pencil; the lattice opens and folds to follow. At rest
 * the pencil is the bright mark.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 56, RX = 66, RY = 46, ZA = 6;
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 3.2);
  fit(C, [[-8, -8, 0], [90, 70, 0], [90, -8, 0], [-8, 70, 0], [0, 0, 16], [RX, RY, 24]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  mk("path", { class: "lo", d: poly([[14, 4, 0], [92, 4, 0], [92, 72, 0], [14, 72, 0]].map((p) => P(...p))) }, g);
  const base = solid(g);
  put(base, prism(P, front, disc(0, 0, 8), disc(0, 0, 6.5), 0, 12));
  const bars = mk("path", { class: "sil" }, g), pins = mk("path", { class: "nf" }, g);
  const sty = mk("path", { class: "sil" }, g), pen = solid(g);
  pen.sil.classList.add("hi");
  const tx = tween(RX), ty = tween(RY);
  let lx = NaN, ly = NaN;
  const bar = (a, b, r) => { const pts = []; for (const [x, y] of [a, b]) for (const z of [ZA - r, ZA + r]) pts.push(...ringAt(P, disc(x, y, r, 12), z)); return poly(hull(pts)); };
  function draw(x, y) {
    if (x === lx && y === ly) return;
    lx = x; ly = y;
    const d = Math.hypot(x, y), a = Math.atan2(y, x), e = a + Math.acos(clamp(d / (2 * L), -1, 1));
    const B = [L * Math.cos(e), L * Math.sin(e)], O = [0, 0], Q = [x, y];
    const Cm = [B[0] / 2, B[1] / 2], D = [(B[0] + x) / 2, (B[1] + y) / 2], S = [x / 2, y / 2];
    bars.setAttribute("d", bar(O, B, 2) + bar(B, Q, 2) + bar(Cm, S, 1.6) + bar(D, S, 1.6));
    pins.setAttribute("d", [O, B, Cm, D].map(([u, v]) => poly(ringAt(P, disc(u, v, 1.6, 12), ZA + 2))).join(""));
    sty.setAttribute("d", poly(hull(ringAt(P, disc(S[0], S[1], 2.5, 16), ZA + 2).concat([P(S[0], S[1], 0)]))));
    put(pen, prism(P, front, disc(x, y, 2.6, 20), disc(x, y, 2, 20), 0, 22));
  }
  const Bk = register(stage, (_dt, now) => { draw(tval(tx, now), tval(ty, now)); return !(tdone(tx, now) && tdone(ty, now)); });
  bag.add(Bk.unregister);
  function aim(p) {
    let x = RX, y = RY;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      x = clamp(RX + (wx - RX) * amt, 30, 92); y = clamp(RY + (wy - RY) * amt, 0, 72);
      const d = Math.hypot(x, y), m = 2 * L - 6;
      if (d > m) { x *= m / d; y *= m / d; }
      if (d < 30) { x *= 30 / d; y *= 30 / d; }
    }
    const now = performance.now();
    tset(tx, x, now, 0); tset(ty, y, now, 0);
    read.textContent = p ? "×2" : "rest";
    Bk.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; }, destroy: bag.dispose };
}

hairline({
  name: "pantograph",
  means: "A pantograph's pinned lattice of arms: the pointer leads the pencil, and the arms open and fold to follow it.",
  rules: [1, 2, 4, 5],
  range: [0.3, 1, 1],
  tour: [[98, 210], [374, 201], [245, 171], null],
  mount,
});

planimeter.code:
/**
 * Planimeter: a polar planimeter on the desk, its weighted pole holding one
 * end of the pole arm, the measuring carriage at the hinge, and the tracer
 * arm reaching out to a lens. The pointer leads the lens across the paper;
 * both arms fold at the hinge to follow. At rest the lens is the bright mark.
 */
const {
  Cam, circ, clamp, facing, fit, hull, poly, prism, proj, ringAt, unproj, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L1 = 52, L2 = 52, RX = 72, RY = 44, ZA = 6;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let amt = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-12, -16, 0], [100, 84, 0], [100, -16, 0], [-12, 84, 0], [0, 0, 14]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const sheet = [[8, 18, 0], [100, 18, 0], [100, 84, 0], [8, 84, 0]].map((p) => P(...p));
  mk("path", { class: "lo", d: poly(sheet) }, g);
  const blob = [[30, 50], [44, 34], [66, 38], [74, 58], [56, 72], [36, 68]].map(([x, y]) => P(x, y, 0));
  mk("path", { class: "nf dash", d: poly(blob) }, g);
  const pole = solid(g);
  put(pole, prism(P, front, disc(0, 0, 7), disc(0, 0, 5.5), 0, 9));
  const arm1 = mk("path", { class: "sil" }, g), cart = solid(g), arm2 = mk("path", { class: "sil" }, g);
  const wheel = mk("path", { class: "nf" }, g), lens = mk("path", { class: "sil hi" }, g);
  const tx = tween(RX), ty = tween(RY);
  let lx = NaN, ly = NaN;
  const bar = (a, b, r) => { const pts = []; for (const [x, y] of [a, b]) for (const z of [ZA - r, ZA + r]) pts.push(...ringAt(P, disc(x, y, r, 12), z)); return poly(hull(pts)); };
  function draw(x, y) {
    if (x === lx && y === ly) return;
    lx = x; ly = y;
    const d = Math.hypot(x, y), a = Math.atan2(y, x), c = clamp((L1 * L1 + d * d - L2 * L2) / (2 * L1 * d), -1, 1);
    const e = a - Math.acos(c), ex = L1 * Math.cos(e), ey = L1 * Math.sin(e);
    arm1.setAttribute("d", bar([0, 0], [ex, ey], 1.6));
    put(cart, prism(P, front, disc(ex, ey, 6), disc(ex, ey, 4.5), 0.5, 10));
    arm2.setAttribute("d", bar([ex, ey], [x, y], 1.6));
    wheel.setAttribute("d", poly(hull(ringAt(P, disc(ex, ey, 3, 16), 10).concat(ringAt(P, disc(ex, ey, 3, 16), 12)))));
    lens.setAttribute("d", poly(hull(ringAt(P, disc(x, y, 6, 28), 0).concat(ringAt(P, disc(x, y, 6, 28), ZA + 2)))));
  }
  const B = register(stage, (_dt, now) => { draw(tval(tx, now), tval(ty, now)); return !(tdone(tx, now) && tdone(ty, now)); });
  bag.add(B.unregister);
  function aim(p) {
    let x = RX, y = RY;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      x = clamp(RX + (wx - RX) * amt, 24, 96); y = clamp(RY + (wy - RY) * amt, 22, 80);
      const d = Math.hypot(x, y), m = L1 + L2 - 4;
      if (d > m) { x *= m / d; y *= m / d; }
    }
    const now = performance.now();
    tset(tx, x, now, 0); tset(ty, y, now, 0);
    read.textContent = p ? Math.round(Math.hypot(x, y)) + "mm" : "rest";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { amt = v; }, destroy: bag.dispose };
}

hairline({
  name: "planimeter",
  means: "A polar planimeter: the pointer leads the tracer lens over the paper, and the two arms fold at the hinge to follow.",
  rules: [1, 2, 4, 5],
  range: [0.3, 1, 1],
  tour: [[119, 180], [298, 197], [208, 152], null],
  mount,
});

watercrane.code:
/**
 * Water crane: a railway water column on a square plinth, with a long arm
 * pivoting on its top and a leather hose hanging from the arm's end. The
 * pointer is where the tender's filler stands: the arm swings round the
 * column to face it, on a spring. At rest the arm points out front-right and
 * the hose is bright. The slider is how far the arm may swing.
 *
 * The pattern: a continuous aim (spotlights), the hit on a fixed plane at the
 * arm's height, paint order swapped when the hose passes behind the column.
 */
const {
  Cam, circ, clamp, fit, open, run, facing, hull, poly, prism, proj, rings, ringAt, unproj, spring, stepS, rad,
  disposer, mk, pointer, put, register, solid,
} = HL;

const L = 74, ZC = 74, AW = 4, AH = 6, RH = 4.2, ZH = 26, REST = rad(20), PL = 18;
const rot = (ring, th, cx, cy) => {
  const c = Math.cos(th), s = Math.sin(th);
  return ring.map((q) => ({ u: cx + q.u * c - q.v * s, v: cy + q.u * s + q.v * c, nu: q.nu * c - q.nv * s, nv: q.nu * s + q.nv * c }));
};
const disc = (x, y, r, n = 28) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = rad(value);
  const C = Cam(45, 0.5, 2.42);
  const ext = [];
  for (let i = 0; i < 16; i++) { const t = (i / 16) * Math.PI * 2; ext.push([(L + 6) * Math.cos(t), (L + 6) * Math.sin(t), ZC + AH + 4], [(L + 6) * Math.cos(t), (L + 6) * Math.sin(t), ZH - 4]); }
  ext.push([-PL, -PL, 0], [PL, PL, 0], [PL, -PL, 0], [-PL, PL, 0]);
  fit(C, ext, 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // plinth and its drain grate
  const [pr, pi] = rings(-PL, -PL, PL, PL, 4, 1.6);
  put(solid(g), prism(P, front, pr, pi, 0, 6));
  const [br, bi] = rings(-10, -10, 10, 10, 3, 1.2);
  put(solid(g), prism(P, front, br, bi, 6, 12));
  // hose (painted before or after the column), column, arm, pivot cap
  const hoseG = mk("g", {}, g);
  const hose = solid(hoseG), nozzle = mk("path", { class: "nf lo" }, hoseG);
  const colG = mk("g", {}, g);
  put(solid(colG), prism(P, front, circ(6, 28), circ(4.4, 28), 12, ZC));
  put(solid(colG), prism(P, front, circ(8, 28), circ(6.4, 28), 40, 44));
  const armG = mk("g", {}, g);
  const arm = solid(armG), cw = solid(armG), cap = solid(armG);
  const th = spring(REST);
  let last = NaN, behind = null;

  function draw(a) {
    if (a === last) return;
    last = a;
    const tx = L * Math.cos(a), ty = L * Math.sin(a);
    const [ar, ai] = rings(-10, -AW / 2, L + 3, AW / 2, 1.8, 0.7);
    put(arm, prism(P, front, rot(ar, a, 0, 0), rot(ai, a, 0, 0), ZC, ZC + AH));
    const [wr, wi] = rings(-20, -5, -8, 5, 2, 0.9);
    put(cw, prism(P, front, rot(wr, a, 0, 0), rot(wi, a, 0, 0), ZC + AH, ZC + AH + 7));
    put(cap, prism(P, front, circ(5, 24), circ(3.6, 24), ZC + AH, ZC + AH + 4));
    const top = disc(tx, ty, RH), bot = disc(tx + 3 * Math.cos(a), ty + 3 * Math.sin(a), RH);
    hose.sil.setAttribute("d", poly(hull(ringAt(P, top, ZC).concat(ringAt(P, disc(tx + 1.5 * Math.cos(a), ty + 1.5 * Math.sin(a), RH), (ZC + ZH) / 2), ringAt(P, bot, ZH)))));
    hose.cr.setAttribute("d", "");
    nozzle.setAttribute("d", open(ringAt(P, run(disc(tx + 3 * Math.cos(a), ty + 3 * Math.sin(a), RH), front), ZH + 5)));
    const b = tx + ty < 0;
    if (b !== behind) { behind = b; if (b) colG.before(hoseG); else colG.after(hoseG); }
  }

  const B = register(stage, (dt) => { const m = stepS(th, dt); draw(th.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function aim(p) {
    let t = REST;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], ZC);
      const d = Math.hypot(wx, wy);
      if (d > 12 && d < L * 1.9) {
        let diff = Math.atan2(wy, wx) - REST;
        diff = Math.atan2(Math.sin(diff), Math.cos(diff));
        t = REST + clamp(diff, -reach, reach);
      } else p = null;
    }
    th.t = t;
    const on = !!p;
    if (on !== act) { act = on; arm.sil.classList.toggle("hi", on); hose.sil.classList.toggle("hi", !on); }
    read.textContent = on ? "arm " + Math.round(((t * 180) / Math.PI + 360) % 360) + "°" : "rest";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = rad(v); }, destroy: bag.dispose };
}

hairline({
  name: "watercrane",
  means: "A railway water crane: the long arm on top of the column swings round to face the pointer, its hose swinging with it.",
  rules: [1, 3, 6, 8],
  range: [30, 110, 170],
  tour: [[80, 163], [80, 44], [354, 146], null],
  mount,
});

wagontippler.code:
/**
 * Wagon tippler: a rotary dumper, two big rings on rollers on a pit slab,
 * clamping an open hopper wagon on its rails between them. The pointer,
 * across the pit, is the side to dump on: the rings roll over on a spring
 * and the wagon turns with them. At rest the cradle leans a little and the
 * wagon is bright. The slider is how far the cradle may roll over.
 *
 * The pattern: a continuous aim (spotlights), on the ground plane.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, seg, unproj, spring, stepS, rad, fillet,
  disposer, mk, pointer, put, register, solid,
} = HL;

const W = 96, R = 42, ZC = R + 9, TH = 5, REST = rad(-12), N = 48;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = rad(value);
  const C = Cam(45, 0.5, 2.05);
  fit(C, [[-10, -R - 8, 0], [W + 10, R + 8, 0], [W + 10, -R - 8, 0], [-10, R + 8, 0], [0, 0, ZC + R], [W, 0, ZC + R]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-10, -R - 8, W + 10, R + 8, 5, 2);
  put(solid(g), prism(P, front, br, bi, 0, 6));
  for (const x of [0, W]) for (const y of [-20, 20]) {
    const [rr, ri] = rings(x - 4, y - 6, x + TH + 4, y + 6, 2.5, 1);
    put(solid(g), prism(P, front, rr, ri, 6, 13));
  }
  const ann = (x, a) => {
    const o = [], i = [];
    for (let k = 0; k < N; k++) { const t = (k / N) * Math.PI * 2; o.push(P(x, R * Math.cos(t), ZC + R * Math.sin(t))); }
    for (let k = N - 1; k >= 0; k--) { const t = (k / N) * Math.PI * 2; i.push(P(x, (R - 7) * Math.cos(t), ZC + (R - 7) * Math.sin(t))); }
    return poly(o) + " " + poly(i);
  };
  // far ring, then the cradle (rails and wagon), then the near ring
  mk("path", { d: ann(0) }, g);
  mk("path", { d: ann(TH), class: "sil" }, g);
  const rails = mk("path", { class: "nf lo" }, g), clamps = mk("path", { class: "nf" }, g);
  const wagon = mk("path", { class: "sil hi" }, g), rim = mk("path", { class: "nf lo" }, g);
  mk("path", { d: ann(W) }, g);
  mk("path", { d: ann(W + TH), class: "sil" }, g);
  const phi = spring(REST);
  let last = NaN;

  function draw(a) {
    if (a === last) return;
    last = a;
    const c = Math.cos(a), s = Math.sin(a);
    const Q = (x, y, z) => P(x, y * c - z * s, ZC + y * s + z * c);
    const sec = fillet([[-17, -22], [17, -22], [19, 14], [-19, 14]], [3, 3, 3, 3], 3);
    const pts = [];
    for (const x of [TH + 6, W - 6]) for (const [y, z] of sec) pts.push(Q(x, y, z));
    wagon.setAttribute("d", poly(hull(pts)));
    rim.setAttribute("d", poly(fillet([Q(TH + 7, -18, 13), Q(W - 7, -18, 13), Q(W - 7, 18, 13), Q(TH + 7, 18, 13)], [2, 2, 2, 2], 3)));
    rails.setAttribute("d", seg(Q(TH, -11, -27), Q(W, -11, -27)) + seg(Q(TH, 11, -27), Q(W, 11, -27)));
    clamps.setAttribute("d", seg(Q(TH + 2, -22, 18), Q(TH + 2, 22, 18)) + seg(Q(W - 2, -22, 18), Q(W - 2, 22, 18)));
  }

  const B = register(stage, (dt) => { const m = stepS(phi, dt); draw(phi.x); return m; });
  bag.add(B.unregister);

  function aim(p) {
    let t = REST, on = false;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      if (wx > -40 && wx < W + 40 && Math.abs(wy) < R * 2.2) { on = true; t = clamp(wy / (R * 0.9), -1, 1) * reach; }
    }
    phi.t = t;
    read.textContent = on ? "roll " + Math.round(Math.abs((t * 180) / Math.PI)) + "°" : "rest";
    B.wake();
  }
  draw(REST);
  aim(null);
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = rad(v); }, destroy: bag.dispose };
}

hairline({
  name: "wagontippler",
  means: "A rotary wagon tippler: the two big rings roll over toward the pointer's side, turning the clamped wagon upside down.",
  rules: [1, 3, 6, 8],
  range: [60, 130, 170],
  tour: [[200, 113], [113, 270], [287, 183], null],
  mount,
});

stampmill.code:
/**
 * Stamp mill: a long iron mortar box with one heavy stamp standing in it,
 * a shoe on a tall stem with a tappet collar. The pointer over the mill
 * lifts the stamp high out of the mortar, as the cam would; leaving lets it
 * settle back to a small rest lift. At rest the tappet collar is bright.
 * The slider is how high the stamp is lifted.
 */
const {
  Cam, circ, fit, facing, hull, poly, prism, proj, rings, ringAt, tset, tval, tdone, tween, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const MZ = 12, SR = 13, SH = 16, STEM = 3.5, SL = 70, CR = 7, CZ = 34, REST = 8;
const disc = (x, y, r, n = 32) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-34, -20, 0], [34, 20, 0], [34, -20, 0], [-34, 20, 0], [0, 0, MZ + 50 + SH + SL]], 200, 160);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  // mortar box, and its open feed slot on top
  const [mr, mi] = rings(-34, -20, 34, 20, 5, 2);
  put(solid(g), prism(P, front, mr, mi, 0, MZ));
  mk("path", { d: poly(ringAt(P, rings(-26, -15, 26, 15, 4, 1)[0], MZ)), class: "nf lo" }, g);
  // the stamp: shoe, stem, tappet collar
  const sg = mk("g", {}, g);
  const shoe = solid(sg), stem = solid(sg), coll = solid(sg);
  coll.sil.classList.add("hi");
  const z = tween(REST);
  let last = NaN;
  function draw(h) {
    if (h === last) return;
    last = h;
    const b = MZ + h;
    put(shoe, prism(P, front, disc(0, 0, SR), disc(0, 0, SR - 2), b, b + SH));
    put(stem, prism(P, front, disc(0, 0, STEM, 16), disc(0, 0, STEM - 1, 16), b + SH, b + SH + SL));
    put(coll, prism(P, front, disc(0, 0, CR, 24), disc(0, 0, CR - 1.6, 24), b + SH + CZ, b + SH + CZ + 6));
  }
  const B = register(stage, (_dt, now) => { draw(tval(z, now)); return !tdone(z, now); });
  bag.add(B.unregister);

  let act = null;
  function setActive(a) {
    if (a === act) return;
    act = a;
    tset(z, a ? lift : REST, performance.now(), 0);
    read.textContent = a ? "lift " + Math.round(lift) : "rest";
    B.wake();
  }
  function hit([sx, sy]) {
    const [x, y] = unproj(C, sx, sy, 0);
    const top = P(0, 0, MZ + REST + SH + SL)[1];
    return Math.abs(x) < 44 && Math.abs(y) < 30 || (Math.abs(sx - P(0, 0, 0)[0]) < 30 && sy > top - 10 && sy < P(0, 0, 0)[1]);
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return {
    set: (v) => { lift = v; if (act) { act = null; setActive(true); } },
    destroy: bag.dispose,
  };
}

hairline({
  name: "stampmill",
  means: "A stamp mill's heavy stamp in its mortar: the pointer lifts the shoe and stem high out of the box, as the cam would.",
  rules: [3, 5, 8],
  range: [20, 35, 50],
  tour: [[200, 202], [200, 129], [200, 93], null],
  mount,
});

railcrane.code:
/**
 * Railway crane: a breakdown crane on its flat wagon, standing on a short
 * length of track. The cab and its long luffed jib sit on a turntable; the
 * pointer on the ground swings them round to face it, hook hanging from the
 * jib's head. At rest the jib points along the wagon, bright. The slider is
 * how far the crane may slew either side.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rad, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CX = 50, CY = 18, REST = 22, H = 18;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.3);
  fit(C, [[-10, -40, 0], [110, 76, 0], [CX - 70, CY, 74], [CX + 70, CY, 74], [CX, CY - 70, 74], [CX, CY + 70, 74]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, z0, z1) => {
    const [r, i] = rings(x0, y0, x1, y1, 1.5, 0.8), s = solid(parent);
    put(s, prism(P, front, r, i, z0, z1));
    return s;
  };
  for (let x = -6; x <= 104; x += 12) box(g, x, 2, x + 5, 34, 0, 2);
  box(g, -10, 9, 110, 11, 2, 5);
  box(g, -10, 25, 110, 27, 2, 5);
  for (const x of [14, 30, 70, 86]) box(g, x - 6, 6, x + 6, 30, 5, 11);
  box(g, 0, 4, 100, 32, 11, 16);
  const top = mk("g", {}, g);

  const a = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    top.replaceChildren();
    const c = Math.cos(rad(deg)), s = Math.sin(rad(deg));
    const W = (u, v, z) => P(CX + u * c - v * s, CY + u * s + v * c, z);
    const blk = (u0, u1, v0, v1, z0, z1, zr = 0) => {
      const pts = [];
      for (const u of [u0, u1]) for (const v of [v0, v1]) for (const z of [z0, z1]) pts.push(W(u, v, z + (u - u0) * zr));
      return poly(hull(pts));
    };
    mk("path", { d: poly(hull([...Array(24)].map((_, k) => W(13 * Math.cos(k / 3.82), 13 * Math.sin(k / 3.82), H)).concat([...Array(24)].map((_, k) => W(13 * Math.cos(k / 3.82), 13 * Math.sin(k / 3.82), H - 2))))) }, top);
    mk("path", { d: blk(-20, -8, -11, 11, H, H + 14), class: "sil" }, top);
    mk("path", { d: blk(-10, 12, -11, 11, H, H + 22), class: "sil" }, top);
    mk("path", { d: blk(0, 12, -11, 11, H + 10, H + 22), class: "nf lo" }, top);
    const jib = mk("path", { d: blk(6, 74, -4, 4, H + 14, H + 20, 0.42), class: "sil hi" }, top);
    const tip = W(72, 0, H + 14 + 66 * 0.42), hook = W(72, 0, H + 6);
    mk("path", { d: seg(tip, hook), class: "nf" }, top);
    mk("path", { d: blk(70, 74, -2, 2, H + 1, H + 6), class: "sil" }, top);
    return jib;
  }
  draw(REST);

  const B = register(stage, (dt) => {
    const m = stepS(a, dt);
    draw(a.x);
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    let t = REST;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0), d = Math.hypot(x - CX, y - CY);
      if (d > 14 && d < 130) {
        let deg = (Math.atan2(y - CY, x - CX) * 180) / Math.PI - REST;
        deg = ((deg + 540) % 360) - 180;
        t = REST + clamp(deg, -reach, reach);
      }
    }
    a.t = t;
    read.textContent = t === REST ? "rest" : "slew " + Math.round(t - REST) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { reach = v; }, destroy: bag.dispose };
}

hairline({
  name: "railcrane",
  means: "A breakdown crane on its rail wagon: the cab and long jib slew round on the turntable to face the pointer.",
  rules: [1, 3, 5, 6],
  range: [40, 120, 160],
  tour: [[37, 236], [76, 184], [320, 226], null],
  mount,
});

coalingtower.code:
/**
 * Coaling tower: a tall concrete bunker on legs beside a length of track,
 * a hopper roof on top. On its track side a wide hinged apron hangs folded
 * against the wall. The pointer near the track lowers the apron out over
 * the rails, a chute for the coal. At rest the apron hangs almost shut,
 * bright. The slider is how far it swings out.
 */
const {
  Cam, clamp, fit, facing, hull, poly, prism, proj, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const TX = 26, HZ = 50, L = 50, REST = 10;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-4, -10, 0], [84, 50, 0], [0, 0, 92], [TX, 40, 92], [TX + L, 40, HZ]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (parent, x0, y0, x1, y1, z0, z1) => {
    const [r, i] = rings(x0, y0, x1, y1, 1.5, 0.8), s = solid(parent);
    put(s, prism(P, front, r, i, z0, z1));
    return s;
  };
  box(g, -4, -10, 84, 50, 0, 2);
  for (const [x, y] of [[2, 4], [2, 32], [20, 4], [20, 32]]) box(g, x, y, x + 4, y + 4, 2, 30);
  box(g, 0, 0, TX, 40, 30, 82);
  box(g, 4, 4, TX - 4, 36, 82, 92);
  for (let y = -6; y <= 46; y += 13) box(g, 34, y, 74, y + 4, 2, 4);
  box(g, 40, -10, 42, 50, 4, 7);
  box(g, 66, -10, 68, 50, 4, 7);
  const ap = mk("path", { class: "sil hi" }, g), lip = mk("path", { class: "nf lo" }, g);

  const a = spring(REST);
  let last = NaN;
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const t = (deg * Math.PI) / 180, s = Math.sin(t), c = Math.cos(t), pts = [];
    for (const y of [2, 38]) for (const [u, w] of [[0, 0], [L, 0], [0, 2.5], [L, 2.5]]) pts.push(P(TX + u * s + w * c, y, HZ - u * c + w * s));
    ap.setAttribute("d", poly(hull(pts)));
    const e = (u) => [P(TX + u * s + 2.5 * c, 2, HZ - u * c + 2.5 * s), P(TX + u * s + 2.5 * c, 38, HZ - u * c + 2.5 * s)];
    lip.setAttribute("d", poly([...e(L - 6), ...e(L).reverse()]));
  }
  draw(REST);

  const B = register(stage, (dt) => {
    const m = stepS(a, dt);
    draw(a.x);
    return m;
  });
  bag.add(B.unregister);

  function aim(p) {
    let k = 0;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (y > -20 && y < 60 && x > 10 && x < 100) k = clamp(1 - Math.abs(x - 54) / 46, 0, 1);
    }
    a.t = REST + Math.min(1, k * 1.5) * swing;
    read.textContent = k === 0 ? "rest" : "chute " + Math.round(a.t) + "°";
    B.wake();
  }
  aim(null);
  bag.add(pointer(stage, { move: aim, leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; }, destroy: bag.dispose };
}

hairline({
  name: "coalingtower",
  means: "A coaling tower beside the track: the pointer near the rails swings its wide apron down over them as a chute.",
  rules: [1, 3, 5, 6],
  range: [30, 88, 96],
  tour: [[233, 251], [190, 245], [280, 250], null],
  mount,
});

derrick.code:
/**
 * Derrick: a guy derrick, a tall mast held by four guy ropes to ground
 * anchors, and a long boom hinged at the mast foot with a topping lift from
 * the mast head and a hook on its rope. The pointer on the ground is where
 * the load should go: the boom slews round the mast to face it and luffs,
 * steep for a near spot, low for a far one. At rest the hook block is the
 * bright mark. The slider sets how far the boom swings from rest.
 *
 * The pattern: one part turning to face the pointer (aim).
 */
const {
  Cam, circ, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const MH = 78, FZ = 8, LEN = 86, REST_A = 70, REST_E = 38, ROPE = 22, GR = 52;
const disc = (x, y, r, n = 24) => circ(r, n).map((q) => ({ ...q, u: q.u + x, v: q.v + y }));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let K = value / 100;
  const C = Cam(45, 0.5, 1.75);
  const ext = [[0, 0, MH + 4]];
  for (let a = 0; a < 360; a += 45) { ext.push([GR * Math.cos(rad(a)), GR * Math.sin(rad(a)), 0]); for (const e of [20, 64]) { const h = LEN * Math.cos(rad(e)); ext.push([h * Math.cos(rad(a)), h * Math.sin(rad(a)), FZ + LEN * Math.sin(rad(e))]); } }
  fit(C, ext, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (par, x0, y0, x1, y1, z0, z1, r = 2, b = 0.8) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(par), prism(P, front, o, i, z0, z1)); };
  const guys = [45, 135, 225, 315].map((a) => [GR * Math.cos(rad(a)), GR * Math.sin(rad(a))]);
  const far = mk("g", {}, g), boomBack = mk("g", {}, g), mastG = mk("g", {}, g), boomFront = mk("g", {}, g), near = mk("g", {}, g);
  for (const [x, y] of guys) {
    const par = x + y > 0 ? near : far;
    mk("path", { d: open([P(0, 0, MH), P(x, y, 3)]), class: "nf lo" }, par);
    box(par, x - 4, y - 4, x + 4, y + 4, 0, 3, 2, 0.8);
  }
  box(mastG, -9, -9, 9, 9, 0, 5, 3, 1.2);
  put(solid(mastG), prism(P, front, disc(0, 0, 2.8), disc(0, 0, 2), 5, MH));
  put(solid(mastG), prism(P, front, disc(0, 0, 4.2), disc(0, 0, 3.2), MH - 2, MH + 2));

  const bg = mk("g", {}, boomFront);
  const lift = mk("path", { class: "nf lo" }, bg);
  const boom = mk("path", { class: "sil" }, bg), crease = mk("path", { class: "nf lo" }, bg);
  const rope = mk("path", { class: "dash nf" }, bg), hook = solid(bg);
  const sa = spring(REST_A), se = spring(REST_E);
  let last = "", side = 1;

  function draw() {
    const a = rad(sa.x), e = rad(se.x), key = sa.x.toFixed(2) + se.x.toFixed(2);
    if (key === last) return;
    last = key;
    const s1 = Math.cos(a) + Math.sin(a) >= 0 ? 1 : 0;
    if (s1 !== side) { side = s1; (s1 ? boomFront : boomBack).appendChild(bg); }
    const d = [Math.cos(e) * Math.cos(a), Math.cos(e) * Math.sin(a), Math.sin(e)];
    const s = [-Math.sin(a), Math.cos(a), 0], u = [-Math.sin(e) * Math.cos(a), -Math.sin(e) * Math.sin(a), Math.cos(e)];
    const at = (t, b, c, w) => P(t * d[0] + b * w * s[0] + c * w * u[0], t * d[1] + b * w * s[1] + c * w * u[1], FZ + t * d[2] + b * w * s[2] + c * w * u[2]);
    const pts = [];
    for (const t of [0, LEN]) for (const b of [-0.5, 0.5]) for (const c of [-0.5, 0.5]) pts.push(at(t, b, c, t ? 4 : 9));
    boom.setAttribute("d", poly(hull(pts)));
    crease.setAttribute("d", open([at(3, 0, 0.3, 8), at(LEN - 3, 0, 0.3, 4)]));
    const tip = [LEN * d[0], LEN * d[1], FZ + LEN * d[2] - 2];
    lift.setAttribute("d", open([P(0, 0, MH), P(...tip)]));
    const hz = Math.max(4, tip[2] - ROPE);
    rope.setAttribute("d", open([P(...tip), P(tip[0], tip[1], hz + 6)]));
    const [o, i] = rings(tip[0] - 3.5, tip[1] - 3.5, tip[0] + 3.5, tip[1] + 3.5, 1.5, 0.8);
    put(hook, prism(P, front, o, i, hz, hz + 6));
  }

  const B = register(stage, (dt) => { const m = [stepS(sa, dt), stepS(se, dt)].some(Boolean); draw(); return m; });
  bag.add(B.unregister);

  let on = null, tgt = null;
  function aim(p) {
    tgt = p;
    let ang = REST_A, el = REST_E;
    if (p) {
      const [wx, wy] = unproj(C, p[0], p[1], 0);
      let dA = (Math.atan2(wy, wx) * 180) / Math.PI - REST_A;
      dA = ((dA + 540) % 360) - 180;
      ang = REST_A + clamp(dA, -170, 170) * K;
      el = REST_E + (clamp(74 - Math.hypot(wx, wy) * 0.6, 20, 64) - REST_E) * K;
    }
    sa.t = ang; se.t = el;
    const act = !!p;
    if (act !== on) { on = act; boom.classList.toggle("hi", act); hook.sil.classList.toggle("hi", !act); }
    read.textContent = act ? String(Math.round(((ang % 360) + 360) % 360)).padStart(3, "0") + "°" : "rest";
    B.wake();
  }
  aim(null);
  draw();
  bag.add(pointer(stage, { move: (p) => aim(p), leave: () => aim(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { K = v / 100; aim(tgt); }, destroy: bag.dispose };
}

hairline({
  name: "derrick",
  means: "A guy derrick held by its guy ropes: the boom slews round the mast to face the pointer and luffs, steep for near, low for far.",
  rules: [1, 3, 5, 8],
  range: [30, 80, 100],
  tour: [[237, 255], [188, 181], [132, 246], null],
  mount,
});

treadwheel.code:
/**
 * Treadwheel: a medieval treadwheel crane, a great walking wheel on its axle
 * posts, its rope wound on the axle and led over a raking jib to a hanging
 * stone. The pointer across the figure walks the wheel: right turns it
 * forward and hoists the stone, left pays out and lowers it. At rest the
 * stone is the bright mark. The slider sets how far one sweep turns the wheel.
 *
 * The pattern: one part turning with the pointer (wind).
 */
const {
  Cam, clamp, fit, facing, hull, open, poly, prism, proj, rad, rings, spring, stepS,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CZ = 40, R = 34, W = 8, TIP = [86, 0, 96], FOOT = [36, 0, 3];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let K = value / 100;
  const C = Cam(45, 0.5, 2.0);
  fit(C, [[-R, -12, 0], [-R, 12, CZ + R], [R, 12, 0], [R, -12, CZ + R], TIP, [86, 0, 0], [40, 14, 0]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r = 2, b = 0.8) => { const [o, i] = rings(x0, y0, x1, y1, r, b); put(solid(g), prism(P, front, o, i, z0, z1)); };
  const W3 = (x, y, z) => P(x, y, z);
  box(-36, -13, 44, 13, 0, 3, 3, 1.2);
  box(-3, -13, 3, -9, 3, CZ + 2, 1.5, 0.6);
  const wheel = mk("g", {}, g);
  const rimB = mk("path", { class: "nf" }, wheel), spokesB = mk("path", { class: "nf" }, wheel);
  const slats = mk("path", { class: "nf lo" }, wheel), drum = mk("path", { class: "nf" }, wheel);
  // jib between the rims, then the near post and rim
  const jd = TIP.map((v, i) => v - FOOT[i]), jl = Math.hypot(...jd), dj = jd.map((v) => v / jl);
  const at = (t, b, c) => P(FOOT[0] + t * dj[0] - c * dj[2] * 5, b * 5, FOOT[2] + t * dj[2] + c * dj[0] * 5);
  const jp = [];
  for (const t of [0, jl]) for (const b of [-0.5, 0.5]) for (const c of [-0.5, 0.5]) jp.push(at(t, b, c));
  mk("path", { d: poly(hull(jp)), class: "sil" }, g);
  mk("path", { d: open([at(3, 0, 0.3), at(jl - 3, 0, 0.3)]), class: "nf lo" }, g);
  box(-3, 9, 3, 13, 3, CZ + 2, 1.5, 0.6);
  const rimF = mk("path", { class: "nf sil" }, g), spokesF = mk("path", { class: "nf" }, g);
  const rope = mk("path", { class: "nf lo" }, g), hang = mk("path", { class: "dash nf" }, g), stone = solid(g);
  const sr = spring(0);
  let last = "";
  const ring = (y, r, rot) => { const p = []; for (let i = 0; i < 48; i++) { const t = rot + (i / 48) * 2 * Math.PI; p.push(W3(r * Math.cos(t), y, CZ + r * Math.sin(t))); } return p; };
  const spokes = (y, rot) => { let d = ""; for (let k = 0; k < 6; k++) { const t = rot + (k * Math.PI) / 3; d += "M" + W3(4 * Math.cos(t), y, CZ + 4 * Math.sin(t)).join(",") + "L" + W3(R * Math.cos(t), y, CZ + R * Math.sin(t)).join(","); } return d; };

  function draw() {
    const rot = rad(sr.x), key = sr.x.toFixed(2);
    if (key === last) return;
    last = key;
    rimB.setAttribute("d", poly(ring(-W, R, 0)));
    spokesB.setAttribute("d", spokes(-W, rot));
    let d = "";
    for (let k = 0; k < 12; k++) { const t = rot + (k * Math.PI) / 6 + 0.26; d += "M" + W3(R * Math.cos(t), -W, CZ + R * Math.sin(t)).join(",") + "L" + W3(R * Math.cos(t), W, CZ + R * Math.sin(t)).join(","); }
    slats.setAttribute("d", d);
    drum.setAttribute("d", poly(ring(0, 5, rot)));
    rimF.setAttribute("d", poly(ring(W, R, 0)));
    spokesF.setAttribute("d", spokes(W, rot));
    const sz = clamp(26 + sr.x * 0.3, 6, 62);
    rope.setAttribute("d", open([W3(0, 0, CZ + 5), W3(TIP[0], 0, TIP[2])]));
    hang.setAttribute("d", open([W3(TIP[0], 0, TIP[2]), W3(TIP[0], 0, sz + 9)]));
    const [o, i] = rings(TIP[0] - 6, -6, TIP[0] + 6, 6, 2, 1);
    put(stone, prism(P, front, o, i, sz, sz + 9));
  }

  const B = register(stage, (dt) => { const m = stepS(sr, dt); draw(); return m; });
  bag.add(B.unregister);

  let on = null, tgt = null;
  function walk(p) {
    tgt = p;
    const act = !!p;
    sr.t = act ? clamp((p[0] - 200) / 110, -1, 1) * 140 * K : 0;
    if (act !== on) { on = act; rimF.classList.toggle("hi", act); stone.sil.classList.toggle("hi", !act); }
    read.textContent = act ? (sr.t >= 0 ? "+" : "−") + String(Math.abs(Math.round(sr.t))).padStart(3, "0") + "°" : "rest";
    B.wake();
  }
  walk(null);
  draw();
  bag.add(pointer(stage, { move: (p) => walk(p), leave: () => walk(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { K = v / 100; walk(tgt); }, destroy: bag.dispose };
}

hairline({
  name: "treadwheel",
  means: "A medieval treadwheel crane: the pointer walks the great wheel round, winding the rope over the jib to hoist or lower the stone.",
  rules: [1, 3, 5, 8],
  range: [30, 80, 100],
  tour: [[300, 160], [120, 160], [260, 200], null],
  mount,
});

salamander.code:
/**
 * Salamander grill: a kitchen salamander, a low base with a grill rack on it,
 * a post at the back and a heavy heating head that rides up and down the
 * post above the rack. The pointer over the grill lifts the head up the post
 * and slides the rack forward to serve. At rest the head hangs low over the
 * rack, bright. The slider is how high the head lifts.
 *
 * The pattern: one part slides on a guide; the hit is the rest pose's box.
 */
const {
  Cam, clamp, fit, facing, poly, prism, proj, rings, seg, tdone, tset, tval, tween,
  disposer, mk, pointer, put, register, solid,
} = HL;

const X1 = 60, Y1 = 40, BZ = 5, PZ = 64, HT = 11, REST_H = 17, TZ = 3, SLIDE = 0.35;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let lift = value;
  const C = Cam(45, 0.5, 2.55);
  const box = [[0, 0, 0], [X1, 0, 0], [0, Y1 + 12, 0], [X1, Y1 + 12, 0], [0, 0, PZ], [X1, Y1, PZ], [X1, 0, PZ], [0, Y1, PZ]];
  fit(C, box, 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);

  // the base, the post at the back
  const [br, bi] = rings(0, 0, X1, Y1, 5, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, BZ));
  const [pr, pi] = rings(21, 0, 39, 8, 3, 1);
  put(solid(g), prism(P, front, pr, pi, BZ, PZ));
  mk("path", { class: "nf lo", d: seg(P(30, 8, BZ + 8), P(30, 8, PZ - 6)) }, g);

  // the rack, which slides forward
  const tray = solid(g), bars = mk("path", { class: "nf lo" }, g);
  // the head, painted last: it hangs in front of the post and over the rack
  const head = solid(g), hd = mk("path", { class: "nf" }, g);
  head.sil.classList.add("hi");

  let lastT = NaN;
  function drawTray(d) {
    if (d === lastT) return;
    lastT = d;
    const [tr, ti] = rings(6, 11 + d, X1 - 6, Y1 - 2 + d, 3, 1.2);
    put(tray, prism(P, front, tr, ti, BZ, BZ + TZ));
    let b = "";
    for (let x = 12; x <= X1 - 12; x += 6) b += seg(P(x, 13 + d, BZ + TZ), P(x, Y1 - 4 + d, BZ + TZ));
    b += seg(P(14, Y1 + 1 + d, BZ + 1.5), P(X1 - 14, Y1 + 1 + d, BZ + 1.5));
    bars.setAttribute("d", b);
  }
  let lastH = NaN;
  function drawHead(h) {
    if (h === lastH) return;
    lastH = h;
    const [hr, hi] = rings(2, 4, X1 - 2, Y1 + 1, 5, 1.6);
    put(head, prism(P, front, hr, hi, h, h + HT));
    const z = h + HT / 2, y = Y1 + 3.5;
    let d = seg(P(14, y, z), P(X1 - 14, y, z)) + seg(P(14, Y1 + 1, z), P(14, y, z)) + seg(P(X1 - 14, Y1 + 1, z), P(X1 - 14, y, z));
    for (let x = 12; x <= X1 - 12; x += 6) d += seg(P(x, 12, h + HT), P(x, 20, h + HT));
    hd.setAttribute("d", d);
  }

  const hz = tween(REST_H), ty = tween(0);
  const B = register(stage, (_dt, now) => {
    drawTray(tval(ty, now));
    drawHead(tval(hz, now));
    return !tdone(hz, now) || !tdone(ty, now);
  });
  bag.add(B.unregister);

  // the hit: the screen box of the grill's rest pose, which never moves
  const sp = box.map((p) => P(...p));
  const bx = [Math.min(...sp.map((p) => p[0])), Math.max(...sp.map((p) => p[0])), Math.min(...sp.map((p) => p[1])), Math.max(...sp.map((p) => p[1]))];
  const hit = ([x, y]) => x > bx[0] - 4 && x < bx[1] + 4 && y > bx[2] - 4 && y < bx[3] + 4;

  let act = null;
  function setActive(on) {
    if (on === act) return;
    act = on;
    const now = performance.now(), L = clamp(lift, 0, 34);
    tset(hz, on ? REST_H + L : REST_H, now, 0);
    tset(ty, on ? L * SLIDE : 0, now, on ? 60 : 0);
    read.textContent = on ? "up " + Math.round(L) : "rest";
    B.wake();
  }
  setActive(false);
  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(false) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { lift = v; if (act) { act = null; setActive(true); } }, destroy: bag.dispose };
}

hairline({
  name: "salamander",
  means: "A kitchen salamander grill: over it, the heating head rides up its post and the rack slides forward to serve.",
  rules: [1, 4, 5, 8],
  range: [14, 26, 34],
  tour: [[207, 171], [178, 230], [240, 75], null],
  mount,
});

ropemaker.code:
/**
 * Rope maker: a hand-cranked wheel on a post, three hooks on its face and
 * three strands running from the hooks to a traveller post, where they meet
 * as one rope. The pointer cranks the wheel: sliding along the bench turns
 * it, and the strands twist round each other as the hooks go round. At rest
 * the crank handle is bright. The slider is how many turns the bench holds.
 *
 * The pattern: one part turning to follow the pointer (spring).
 */
const {
  Cam, fit, facing, hull, open, poly, prism, proj, rings, seg, spring, stepS, unproj,
  disposer, mk, pointer, put, register, solid,
} = HL;

const CY = 20, CZ = 52, R = 32, WX0 = 24, WX1 = 30, HK = 9, FX = 108, REST = 0.5;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let turns = value;
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[-2, -14, 0], [124, -14, 0], [124, 54, 0], [-2, 54, 0], [WX0, CY - R, CZ + R], [WX0, CY + R, CZ + R], [FX + 10, 20, 64]], 200, 166);
  const P = proj(C), front = facing(C);
  const disc = (x, r, n = 40, a0 = 0) => {
    const o = [];
    for (let i = 0; i < n; i++) { const a = a0 + (i / n) * Math.PI * 2; o.push(P(x, CY + r * Math.cos(a), CZ + r * Math.sin(a))); }
    return o;
  };
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-2, -14, 124, 54, 6, 2);
  put(solid(g), prism(P, front, br, bi, 0, 5));
  const [pr, pi] = rings(13, 14, 22, 26, 3, 1.2);
  put(solid(g), prism(P, front, pr, pi, 5, CZ + 4));

  // the wheel: a rim in the y-z plane, its inner edge and six spokes
  const wheel = solid(g);
  wheel.sil.setAttribute("d", poly(hull(disc(WX0, R).concat(disc(WX1, R)))));
  wheel.cr.setAttribute("d", poly(disc(WX1, R - 4)));
  const spokes = mk("path", { class: "nf" }, g);
  const hub = solid(g);
  hub.sil.setAttribute("d", poly(hull(disc(WX1, 6, 24).concat(disc(WX1 + 3, 6, 24)))));
  const hooks = mk("path", { class: "nf" }, g);
  const strands = mk("path", { class: "nf" }, g);
  const crank = solid(g), crankArm = mk("path", { class: "nf" }, g);
  const [tr, ti] = rings(FX, 12, FX + 10, 28, 3, 1.2);
  put(solid(g), prism(P, front, tr, ti, 5, 64));
  const rope = mk("path", { class: "nf" }, g);
  rope.setAttribute("d", open([P(FX, CY, CZ), P(FX + 0.5, CY, CZ)]));

  const ang = spring(REST);
  let last = NaN;
  function draw(th) {
    if (th === last) return;
    last = th;
    let d = "";
    for (let k = 0; k < 6; k++) {
      const a = th + (k * Math.PI) / 3, c = Math.cos(a), s = Math.sin(a);
      d += seg(P(WX1, CY + 6 * c, CZ + 6 * s), P(WX1, CY + (R - 4) * c, CZ + (R - 4) * s));
    }
    spokes.setAttribute("d", d);
    let hd = "", sd = "";
    for (let k = 0; k < 3; k++) {
      const a0 = th * 2 + (k * Math.PI * 2) / 3, hx = WX1 + 3;
      const hy = CY + HK * Math.cos(a0), hz = CZ + HK * Math.sin(a0);
      hd += open([P(hx, hy, hz), P(hx + 5, hy, hz), P(hx + 5, hy, hz + 2.5)]);
      const pts = [];
      for (let i = 0; i <= 48; i++) {
        const t = i / 48, x = hx + 5 + t * (FX - hx - 5), r = HK * (1 - t) ** 0.8, a = a0 + t * 5 * Math.PI - th * 2 * t;
        pts.push(P(x, CY + r * Math.cos(a), CZ + r * Math.sin(a)));
      }
      sd += open(pts);
    }
    hooks.setAttribute("d", hd);
    strands.setAttribute("d", sd);
    const ca = th + Math.PI / 6, cy = CY + (R - 6) * Math.cos(ca), cz = CZ + (R - 6) * Math.sin(ca);
    crankArm.setAttribute("d", open([P(WX1 + 3, CY, CZ), P(WX1 + 3, cy, cz)]));
    const pin = (x) => { const o = []; for (let i = 0; i < 16; i++) { const a = (i / 16) * Math.PI * 2; o.push(P(x, cy + 3 * Math.cos(a), cz + 3 * Math.sin(a))); } return o; };
    crank.sil.setAttribute("d", poly(hull(pin(WX1 + 3).concat(pin(WX1 + 18)))));
    crank.cr.setAttribute("d", poly(pin(WX1 + 18)));
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setAt(p) {
    let wx = null;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x > -20 && x < 140 && y > -40 && y < 80) wx = Math.max(0, Math.min(120, x));
    }
    act = wx;
    ang.t = wx === null ? REST : REST + (wx / 120) * turns * Math.PI * 2;
    crank.sil.classList.toggle("hi", true);
    wheel.sil.classList.toggle("hi", wx !== null);
    read.textContent = wx === null ? "rest" : Math.round((wx / 120) * turns * 360) + "°";
    B.wake();
  }
  setAt(null);
  bag.add(pointer(stage, { move: (p) => setAt(p), leave: () => setAt(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { turns = v; if (act !== null) { ang.t = REST + (act / 120) * turns * Math.PI * 2; B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "ropemaker",
  means: "A hand-cranked rope maker: sliding along the bench turns the wheel, and the three strands twist into rope.",
  rules: [1, 3, 5, 8],
  range: [0.25, 0.75, 1.5],
  tour: [[165, 170], [199, 219], [235, 262], null],
  mount,
});

linotype.code:
/**
 * Linotype: a typesetting machine on its plinth: the main frame, the keyboard
 * tray in front with its rows of keys, the metal pot at the side and, on top,
 * the slanted magazine with its matrix channels. The pointer swings the
 * magazine up on its front hinge, further the nearer the pointer comes to
 * the keyboard. At rest the magazine is bright. The slider is the swing.
 *
 * The pattern: one part tilting to follow the pointer (spring).
 */
const {
  Cam, fit, facing, fillet, hull, open, poly, prism, proj, rings, seg, spring, stepS, unproj, clamp,
  disposer, flatDot, mk, place, pointer, put, register, solid,
} = HL;

const HX = 34, HZ = 70, L = 50, T = 6, Y0 = 6, Y1 = 54, REST = 28, MAXA = 92;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let swing = value;
  const C = Cam(45, 0.5, 1.8);
  const corner = (a, s, t, y) => [HX - s * L * Math.cos(rad(a)) + t * T * Math.sin(rad(a)), y, HZ + s * L * Math.sin(rad(a)) + t * T * Math.cos(rad(a))];
  const ext = [];
  for (const a of [REST, MAXA]) for (const y of [Y0, Y1]) ext.push(corner(a, 1, 1, y), corner(a, 1, 0, y));
  fit(C, [[-4, -4, 0], [58, -4, 0], [58, 72, 0], [-4, 72, 0], ...ext], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const box = (x0, y0, x1, y1, z0, z1, r, b) => { const [o, i] = rings(x0, y0, x1, y1, r, b); const s = solid(g); put(s, prism(P, front, o, i, z0, z1)); return s; };
  box(-4, -4, 58, 72, 0, 6, 5, 2);
  box(4, 6, 30, 54, 6, HZ, 4, 1.6);
  // the keyboard tray and its keys
  box(30, 12, 50, 48, 30, 36, 3, 1.4);
  for (let r = 0; r < 3; r++) for (let c = 0; c < 6; c++) place(flatDot(g, C, 1.4, "dot off"), P(34 + r * 6, 16 + c * 6, 36));
  // the metal pot, round, at the side
  box(8, 56, 24, 70, 6, 40, 8, 1.6);
  box(6, 54, 26, 72, 40, 44, 9, 1.4);
  // the line of matrices waiting in the assembler, over the keyboard
  mk("path", { class: "nf lo", d: seg(P(32, 14, 48), P(32, 46, 48)) + seg(P(32, 14, 44), P(32, 46, 44)) }, g);

  const mag = solid(g), chans = mk("path", { class: "nf lo" }, g);
  mag.sil.classList.add("hi");
  const ang = spring(REST);
  let last = NaN;
  function draw(a) {
    if (a === last) return;
    last = a;
    const pts = [];
    for (const s of [0, 1]) for (const t of [0, 1]) for (const y of [Y0, Y1]) pts.push(P(...corner(a, s, t, y)));
    const h = hull(pts);
    mag.sil.setAttribute("d", poly(fillet(h, h.map(() => 3))));
    const top = [corner(a, 0.04, 1, Y0 + 2), corner(a, 0.96, 1, Y0 + 2), corner(a, 0.96, 1, Y1 - 2), corner(a, 0.04, 1, Y1 - 2)].map((q) => P(...q));
    mag.cr.setAttribute("d", poly(fillet(top, [2, 2, 2, 2])));
    let d = "";
    for (let j = 1; j < 10; j++) { const y = Y0 + 2 + (j * (Y1 - Y0 - 4)) / 10; d += seg(P(...corner(a, 0.12, 1, y)), P(...corner(a, 0.9, 1, y))); }
    chans.setAttribute("d", d);
  }

  const B = register(stage, (dt) => { const m = stepS(ang, dt); draw(ang.x); return m; });
  bag.add(B.unregister);

  let act = null;
  function setAt(p) {
    let f = null;
    if (p) {
      const [x, y] = unproj(C, p[0], p[1], 0);
      if (x > -30 && x < 90 && y > -30 && y < 100) f = clamp((x + 10) / 60, 0.25, 1);
    }
    act = f;
    ang.t = f === null ? REST : Math.min(MAXA, REST + f * swing);
    read.textContent = f === null ? "rest" : Math.round(ang.t) + "°";
    B.wake();
  }
  setAt(null);
  bag.add(pointer(stage, { move: (p) => setAt(p), leave: () => setAt(null) }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { swing = v; if (act !== null) { ang.t = Math.min(MAXA, REST + act * swing); B.wake(); } }, destroy: bag.dispose };
}

hairline({
  name: "linotype",
  means: "A linotype machine: the pointer swings its slanted matrix magazine up on the hinge, further the nearer it comes to the keys.",
  rules: [1, 3, 5, 8],
  range: [20, 45, 64],
  tour: [[209, 205], [228, 253], [196, 280], null],
  mount,
});

cottongin.code:
/**
 * Cotton gin: a wooden box on a base with a row of saw discs standing up
 * through slots in its top, a hinged hopper lid over them and a crank on its
 * near side. The pointer over the gin turns the crank and swings the lid
 * up on its far edge to bare the saws. At rest the lid is bright, just
 * ajar. The slider is how far the lid opens.
 *
 * The pattern: one part on a hinge (lid).
 */
const { Cam, fit, hull, poly, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid, unproj } = HL;

const W = 76, D = 52, H = 38, T = 4, REST = 10, NS = 7, SR = 13, CY = 26, CZ = H - 14, CR = 16;
const rad = (d) => (d * Math.PI) / 180;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = 40 + value * 0.5;
  const C = Cam(45, 0.5, 1.95);
  fit(C, [[-6, -6, 0], [W + 6, -6, 0], [-6, D + 6, 0], [W + 6, D + 6, 0], [0, -T, H + D + 2], [W, -T, H + D + 2], [W + 18, CY + CR + 4, CZ], [W + 18, CY, CZ + CR + 4]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const all = () => true;
  put(solid(g), prism(P, all, ...rings(-6, -6, W + 6, D + 6, 4, 2), 0, 5));
  put(solid(g), prism(P, all, ...rings(0, 0, W, D, 3, 1.5), 5, H));
  for (let i = 0; i < NS; i++) {
    const x = 10 + i * ((W - 20) / (NS - 1)), pts = [];
    for (let k = 0; k <= 22; k++) { const t = (k / 22) * Math.PI, r = k % 2 ? SR - 2.5 : SR; pts.push(P(x, CY + r * Math.cos(t), H - 5 + r * Math.sin(t))); }
    mk("path", { d: poly(pts), class: "" }, g);
  }
  const lg = mk("g", {}, g);
  const lid = mk("path", { class: "sil hi" }, lg), top = mk("path", { class: "nf lo" }, lg);
  const arm = mk("path", { class: "" }, g), knob = mk("path", { class: "" }, g);
  const ang = tween(REST);
  let last = NaN;
  const L = (x, u, t, a) => P(x, u * Math.cos(a) - t * Math.sin(a), H + u * Math.sin(a) + t * Math.cos(a));
  function draw(deg) {
    if (deg === last) return;
    last = deg;
    const a = rad(deg), pts = [];
    for (const x of [-2, W + 2]) for (const u of [0, D + 2]) for (const t of [0, T]) pts.push(L(x, u, t, a));
    lid.setAttribute("d", poly(hull(pts)));
    top.setAttribute("d", poly([L(1, 2, T, a), L(W - 1, 2, T, a), L(W - 1, D - 1, T, a), L(1, D - 1, T, a)]));
    const c = rad(deg * 3 + 200), hy = CY + CR * Math.cos(c), hz = CZ + CR * Math.sin(c), ap = [], kp = [];
    for (let i = 0; i < 12; i++) {
      const t = (i / 12) * 2 * Math.PI;
      for (const x of [W, W + 4]) ap.push(P(x, CY + 4.5 * Math.cos(t), CZ + 4.5 * Math.sin(t)), P(x, hy + 3 * Math.cos(t), hz + 3 * Math.sin(t)));
      for (const x of [W + 4, W + 18]) kp.push(P(x, hy + 2.6 * Math.cos(t), hz + 2.6 * Math.sin(t)));
    }
    arm.setAttribute("d", poly(hull(ap)));
    knob.setAttribute("d", poly(hull(kp)));
  }
  const B = register(stage, (_dt, now) => { draw(tval(ang, now)); return !tdone(ang, now); });
  bag.add(B.unregister);
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(ang, o ? max : REST, performance.now(), 0);
    read.textContent = o ? Math.round(max) + "°" : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: ([sx, sy]) => { const [x, y] = unproj(C, sx, sy, H); set(x > -30 && x < W + 30 && y > -30 && y < D + 30); },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = 40 + v * 0.5; if (on) { on = null; set(true); } }, destroy: bag.dispose };
}

hairline({
  name: "cottongin",
  means: "A cotton gin: the pointer turns the crank and swings the hopper lid up on its far edge to bare the row of saw discs.",
  rules: [1, 3, 4, 5, 6],
  range: [0, 50, 100],
  tour: [[200, 163], [183, 189], [240, 170], null],
  mount,
});

spinningjenny.code:
/**
 * Spinning jenny: a long frame with a row of upright spindles at one end, a
 * sliding carriage that clasps the threads, and a big drive wheel standing
 * at its far side. The pointer over the jenny draws the carriage out along
 * the frame, stretching the threads, while the wheel turns its spokes. At
 * rest the carriage is bright. The slider is how far the carriage runs.
 *
 * The pattern: one part on a rail (drawer).
 */
const { Cam, fit, hull, poly, prism, proj, rings, tdone, tset, tval, tween, disposer, mk, pointer, put, register, solid, unproj } = HL;

const LX = 130, D = 50, BZ = 5, NS = 8, SX = 10, SZ = 36, C0 = 34, WX = 92, WY = -12, WZ = 42, WR = 32;
const rad = (d) => (d * Math.PI) / 180;
const seg = (a, b) => "M" + a[0].toFixed(1) + " " + a[1].toFixed(1) + "L" + b[0].toFixed(1) + " " + b[1].toFixed(1);
const sy = (i) => 8 + i * ((D - 16) / (NS - 1));

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let max = 30 + value * 0.6;
  const C = Cam(45, 0.5, 1.7);
  fit(C, [[0, 0, 0], [LX, 0, 0], [0, D, 0], [LX, D, 0], [WX - WR, WY, WZ + WR], [WX + WR, WY, WZ + WR], [WX, WY, WZ + WR], [0, 0, SZ + 2]], 200, 166);
  const P = proj(C);
  const g = mk("g", {}, svg);
  const all = () => true;
  put(solid(g), prism(P, all, ...rings(WX - 3, WY - 3, WX + 3, WY + 3, 1.5, 0.8), 0, WZ));
  const ring = (r, y) => { const o = []; for (let i = 0; i < 40; i++) { const t = (i / 40) * 2 * Math.PI; o.push(P(WX + r * Math.cos(t), y, WZ + r * Math.sin(t))); } return o; };
  mk("path", { d: poly(hull(ring(WR, WY - 2).concat(ring(WR, WY + 2)))), class: "nf" }, g);
  mk("path", { d: poly(ring(WR - 3, WY + 2)), class: "nf lo" }, g);
  const spokes = mk("path", { class: "nf" }, g);
  mk("path", { d: poly(hull(ring(4, WY - 3).concat(ring(4, WY + 3)))), class: "" }, g);
  put(solid(g), prism(P, all, ...rings(0, 0, LX, D, 4, 2), 0, BZ));
  put(solid(g), prism(P, all, ...rings(4, 1, LX - 4, 5, 1.5, 0.7), BZ, BZ + 4));
  for (let i = 0; i < NS; i++) {
    const y = sy(i);
    put(solid(g), prism(P, all, ...rings(SX - 1.6, y - 1.6, SX + 1.6, y + 1.6, 1.5, 0.6), BZ, SZ));
  }
  const threads = mk("path", { class: "nf lo" }, g);
  put(solid(g), prism(P, all, ...rings(4, D - 5, LX - 4, D - 1, 1.5, 0.7), BZ, BZ + 4));
  const cg = mk("g", {}, g);
  const car = mk("path", { class: "sil hi" }, cg), carc = mk("path", { class: "nf lo" }, cg);
  const pos = tween(C0);
  let last = NaN;
  function draw(cx) {
    if (cx === last) return;
    last = cx;
    let s = "", k = "";
    for (let i = 0; i < NS; i++) s += seg(P(SX, sy(i), SZ), P(cx, sy(i), SZ - 6));
    threads.setAttribute("d", s);
    const ps = [];
    for (const x of [cx - 4, cx + 4]) for (const y of [-3, D + 3]) for (const z of [BZ + 4, SZ - 2]) ps.push(P(x, y, z));
    car.setAttribute("d", poly(hull(ps)));
    carc.setAttribute("d", seg(P(cx - 4, D + 3, SZ - 8), P(cx + 4, D + 3, SZ - 8)) + seg(P(cx + 4, -3, SZ - 8), P(cx + 4, D + 3, SZ - 8)));
    const a = rad((cx - C0) * 5 + 15);
    for (let i = 0; i < 6; i++) { const t = a + (i / 6) * 2 * Math.PI; k += seg(P(WX, WY + 2, WZ), P(WX + (WR - 3) * Math.cos(t), WY + 2, WZ + (WR - 3) * Math.sin(t))); }
    spokes.setAttribute("d", k);
  }
  const B = register(stage, (_dt, now) => { draw(tval(pos, now)); return !tdone(pos, now); });
  bag.add(B.unregister);
  let on = null;
  function set(o) {
    if (o === on) return;
    on = o;
    tset(pos, o ? C0 + max : C0, performance.now(), 0);
    read.textContent = o ? "+" + Math.round(max) : "rest";
    B.wake();
  }
  set(false);
  bag.add(pointer(stage, {
    move: ([px, py]) => { const [x, y] = unproj(C, px, py, BZ); set(x > -30 && x < LX + 30 && y > -40 && y < D + 30); },
    leave: () => set(false),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { max = 30 + v * 0.6; if (on) { on = null; set(true); } }, destroy: bag.dispose };
}

hairline({
  name: "spinningjenny",
  means: "A spinning jenny: the pointer draws the carriage out along the frame, stretching the threads off the spindles as the wheel turns.",
  rules: [1, 3, 4, 5, 6],
  range: [0, 50, 100],
  tour: [[159, 143], [305, 230], [88, 182], null],
  mount,
});

doughsheeter.code:
/**
 * Dough sheeter: a bakery sheeter, the roller housing standing in the middle
 * with a long belt table hinged to each side of it. The pointer over a side
 * folds that table up towards the housing and lays the other one flat, on one
 * spring per table. At rest the far table stands half folded, the near one
 * lies flat, and the roller gap on top of the housing is bright. The slider
 * is how far a table may fold.
 *
 * The pattern: a choice of side, picked on the plane of the flat tables,
 * which never moves; each table's angle is a spring.
 */
const {
  Cam, clamp, fit, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid, hull, rad,
} = HL;

const W0 = 2, W1 = 30, H = 12, Z = 24, L = 52, RA = [58, 6];

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.15);
  fit(C, [[0, -H - L, Z], [32, H + L, Z], [0, 0, 0], [32, 0, 0], [16, 0, Z + L]], 200, 166);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  const wingL = mk("g", {}, g), body = mk("g", {}, g), wingR = mk("g", {}, g);
  // the housing on its foot, with the roller gap across its top
  put(solid(body), prism(P, front, ...rings(-2, -H - 2, 34, H + 2, 3, 1.2), 0, 6));
  put(solid(body), prism(P, front, ...rings(0, -H, 32, H, 4, 1.4), 6, Z + 16));
  const gap = mk("path", { class: "nf sil", d: seg(P(3, -2, Z + 16), P(29, -2, Z + 16)) + seg(P(3, 2, Z + 16), P(29, 2, Z + 16)) }, body);
  mk("path", { class: "nf lo", d: seg(P(32, -H + 3, Z + 4), P(32, -H + 3, Z + 10)) }, body);
  function wing(grp, dir) {
    const s = { plate: mk("path", { class: "sil" }, grp), belt: mk("path", { class: "nf lo" }, grp), sp: spring(0), drawn: NaN };
    s.draw = (a) => {
      if (Math.abs(a - s.drawn) < 0.05) return;
      s.drawn = a;
      const c = Math.cos(rad(a)), n = Math.sin(rad(a));
      const at = (x, d, t) => P(x, dir * (H + d * c + t * n), Z + d * n - t * c);
      const pts = [];
      for (const x of [W0, W1]) for (const d of [0, L]) for (const t of [0, 3]) pts.push(at(x, d, t));
      s.plate.setAttribute("d", poly(hull(pts)));
      s.belt.setAttribute("d", seg(at(W0 + 2, 6, 0), at(W1 - 2, 6, 0)) + seg(at(W0 + 2, L - 6, 0), at(W1 - 2, L - 6, 0)) + seg(at(16, 10, 0), at(16, L - 10, 0)));
    };
    return s;
  }
  const ws = [wing(wingL, -1), wing(wingR, 1)];
  ws[0].sp = spring(RA[0]); ws[1].sp = spring(RA[1]);

  const Lp = register(stage, (dt) => {
    let m = false;
    for (const w of ws) { m = stepS(w.sp, dt) || m; w.draw(w.sp.x); }
    return m;
  });
  bag.add(Lp.unregister);

  function set(side) {
    const top = 30 + 58 * reach;
    ws[0].sp.t = side === null ? RA[0] : side === 0 ? top : 0;
    ws[1].sp.t = side === null ? RA[1] : side === 1 ? top : 0;
    gap.classList.toggle("hi", side === null);
    ws[0].plate.classList.toggle("hi", side === 0);
    ws[1].plate.classList.toggle("hi", side === 1);
    read.textContent = side === null ? "rest" : side === 0 ? "left" : "right";
    Lp.wake();
  }
  let cur = null;
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], Z);
      cur = x > -12 && x < 44 && Math.abs(y) < H + L + 6 && Math.abs(y) > 3 ? (y < 0 ? 0 : 1) : null;
      set(cur);
    },
    leave: () => { cur = null; set(null); },
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { reach = v; set(cur); }, destroy: bag.dispose };
}

hairline({
  name: "doughsheeter",
  means: "A bakery dough sheeter: the belt table on the side the pointer is over folds up beside the rollers, the other lays flat.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[124, 222], [276, 146], [110, 230], null],
  mount,
});

sausagefiller.code:
/**
 * Sausage stuffer: an upright canister on a foot plate, the stuffing tube
 * reaching out of its base, a gear box on its lid with a crank on its side and
 * the plunger's rack standing out of the top. The pointer turns the crank:
 * the further along the plate it goes, the further the crank turns and the
 * lower the rack sinks, on one spring. At rest the rack stands high and the
 * tube's mouth is bright. The slider is how far one pass may push.
 *
 * The pattern: a continuous aim on one value, read on the floor's plane,
 * which never moves.
 */
const {
  Cam, clamp, fit, poly, prism, proj, rings, rrect, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid, hull, rad,
} = HL;

const ZT = 56, ZH = 68, AX = 62, ARM = 27, T0 = 0.12;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.2);
  fit(C, [[-22, -22, 0], [22, 22, 0], [-22, 46, 0], [0, 0, 122], [24, 0, AX + ARM], [24, 0, AX - ARM]], 200, 166);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  put(solid(g), prism(P, front, ...rings(-22, -22, 22, 22, 6, 1.6), 0, 5));
  put(solid(g), prism(P, front, rrect(-15, -15, 15, 15, 15, 14), rrect(-13.4, -13.4, 13.4, 13.4, 13.4, 14), 5, ZT));
  put(solid(g), prism(P, front, ...rings(-11, -9, 11, 9, 3, 1.2), ZT, ZH));
  const rack = solid(g), cap = solid(g), arm = mk("path", { class: "sil" }, g), knob = mk("path", { class: "sil" }, g);
  mk("path", { class: "sil", d: poly(hull(ring(11, 15, 3.5, 0, AX))) }, g);
  // the stuffing tube, tapering out of the canister's foot towards the viewer
  const tubePts = ring(0, 14, 5, 1, 14).concat(ring(0, 44, 2.6, 1, 14));
  mk("path", { class: "sil", d: poly(hull(tubePts)) }, g);
  const mouth = mk("path", { class: "nf sil", d: poly(ring(0, 44, 2.6, 1, 14)) }, g);
  // a circle of radius r about an axis along x (k = 0) or along y (k = 1)
  function ring(a, b, r, k, z) {
    const p = [], q = (i) => [Math.cos(i * Math.PI / 12) * r, z + Math.sin(i * Math.PI / 12) * r];
    if (k) for (let i = 0; i < 24; i++) { const [c, s] = q(i); p.push(P(a + c, b, s)); }
    else for (const x of [a, b]) for (let i = 0; i < 24; i++) { const [c, s] = q(i); p.push(P(x, c, s)); }
    return p;
  }
  const sp = spring(T0);
  let drawn = NaN;
  function draw(t) {
    if (Math.abs(t - drawn) < 1e-3) return;
    drawn = t;
    const h = 118 - 46 * t, a = rad(40 + 320 * t);
    put(rack, prism(P, front, ...rings(-4, -4, 4, 4, 1.5, 0.8), ZH, h));
    put(cap, prism(P, front, ...rings(-8, -5, 8, 5, 2, 1), h, h + 4));
    const ey = ARM * Math.cos(a), ez = AX + ARM * Math.sin(a);
    const bar = [];
    for (const [y, z] of [[0, AX], [ey, ez]]) for (const d of [-2, 2]) for (const x of [14, 16]) bar.push(P(x, y + d * Math.sin(a), z - d * Math.cos(a)));
    arm.setAttribute("d", poly(hull(bar)));
    const kp = [];
    for (const x of [16, 26]) for (let i = 0; i < 16; i++) kp.push(P(x, ey + 2.6 * Math.cos(i * Math.PI / 8), ez + 2.6 * Math.sin(i * Math.PI / 8)));
    knob.setAttribute("d", poly(hull(kp)));
  }
  const L = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(L.unregister);

  function set(t) {
    const on = t !== null;
    sp.t = on ? T0 + (0.98 - T0) * t * reach : T0;
    mouth.classList.toggle("hi", !on);
    knob.classList.toggle("hi", on);
    read.textContent = on ? "push " + Math.round(sp.t * 100) : "rest";
    L.wake();
  }
  let cur = null;
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      cur = x > -40 && x < 50 && y > -40 && y < 60 ? clamp((50 - y) / 90, 0, 1) : null;
      set(cur);
    },
    leave: () => { cur = null; set(null); },
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { reach = v; set(cur); }, destroy: bag.dispose };
}

hairline({
  name: "sausagefiller",
  means: "A sausage stuffer: the pointer turns the crank on its gear box and the plunger's rack sinks into the canister.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[221, 272], [281, 242], [251, 257], null],
  mount,
});

softserve.code:
/**
 * Soft-serve machine: a tall cabinet with its freezing head standing out at
 * the front, the nozzle under it, a cone waiting on the drip tray and a long
 * draw lever on the head's face. The pointer pulls the lever: the nearer it
 * comes to the front, the further the lever swings down and the higher the
 * swirl rises in the cone, on one spring. At rest the lever stands up and the
 * nozzle is bright. The slider is how far the lever may be drawn.
 *
 * The pattern: a continuous aim on one value, read on the floor's plane,
 * which never moves.
 */
const {
  Cam, clamp, fit, poly, prism, proj, rings, seg, unproj, spring, stepS,
  disposer, mk, pointer, put, register, solid, hull, rad,
} = HL;

const CX = 40, CZ = 26, PZ = 62, LV = 34, T0 = 0.08;

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value;
  const C = Cam(45, 0.5, 2.45);
  fit(C, [[0, -20, 0], [50, 20, 0], [0, -20, 84], [46 + LV, 0, PZ], [46, 0, PZ + LV]], 200, 166);
  const P = proj(C), front = HL.facing(C);
  const g = mk("g", {}, svg);
  const circ = (x, y, r, z, n) => { const p = []; for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; p.push(P(x + r * Math.cos(a), y + r * Math.sin(a), z)); } return p; };
  put(solid(g), prism(P, front, ...rings(0, -20, 30, 20, 5, 1.6), 0, 84));
  mk("path", { class: "nf lo", d: seg(P(30, -14, 30), P(30, 14, 30)) }, g);
  put(solid(g), prism(P, front, ...rings(26, -14, 50, 14, 4, 1.2), 0, 4));
  put(solid(g), prism(P, front, ...rings(28, -9, 46, 9, 4, 1.2), PZ - 8, PZ + 6));
  const nozzle = mk("path", { class: "sil", d: poly(hull(circ(CX, 0, 3, PZ - 8, 16).concat(circ(CX, 0, 2, PZ - 14, 16)))) }, g);
  // the cone on the tray, its tip down in the holder
  mk("path", { class: "sil", d: poly(hull([P(CX, 0, 6)].concat(circ(CX, 0, 7, CZ, 24)))) }, g);
  mk("path", { class: "nf lo", d: seg(P(CX - 3, 4, 16), P(CX + 3, -1, 21)) + seg(P(CX - 4, -3, 18), P(CX + 2, 3, 12)) }, g);
  const tiers = [0, 1, 2, 3, 4].map(() => mk("path", { class: "sil" }, g));
  const lever = mk("path", { class: "sil" }, g), knob = mk("path", { class: "sil" }, g);
  const sp = spring(T0);
  let drawn = NaN;
  function draw(t) {
    if (Math.abs(t - drawn) < 1e-3) return;
    drawn = t;
    const H = 26 * t;
    tiers.forEach((el, i) => {
      const z = CZ + i * 5.2, r = 7.4 - i * 1.4, h = clamp(H - i * 5.2, 0, 5.2);
      el.setAttribute("d", h > 0.2 ? poly(hull(circ(CX, 0, r, z, 24).concat(circ(CX, 0, Math.max(r - 1.4 * h / 5.2, 1), z + h, 24)))) : "");
    });
    const a = rad(78 - 100 * t), c = Math.cos(a), s = Math.sin(a), bar = [], kp = [];
    for (const d of [0, LV]) for (const w of [-2.2, 2.2]) for (const y of [-2, 2]) bar.push(P(47 + d * c - w * s, y, PZ + d * s + w * c));
    lever.setAttribute("d", poly(hull(bar)));
    for (let i = 0; i < 3; i++) kp.push(...circ(47 + LV * c, 0, 4.5, PZ + LV * s - 3 + i * 3, 16));
    knob.setAttribute("d", poly(hull(kp)));
  }
  const L = register(stage, (dt) => { const m = stepS(sp, dt); draw(sp.x); return m; });
  bag.add(L.unregister);

  function set(t) {
    const on = t !== null;
    sp.t = on ? T0 + (1 - T0) * t * reach : T0;
    nozzle.classList.toggle("hi", !on);
    lever.classList.toggle("hi", on);
    knob.classList.toggle("hi", on);
    read.textContent = on ? "pull " + Math.round(sp.t * 100) : "rest";
    L.wake();
  }
  let cur = null;
  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      cur = x > -20 && x < 90 && y > -36 && y < 36 ? clamp((x + 10) / 70, 0, 1) : null;
      set(cur);
    },
    leave: () => { cur = null; set(null); },
  }));
  bag.add(() => svg.replaceChildren());
  set(null);
  return { set: (v) => { reach = v; set(cur); }, destroy: bag.dispose };
}

hairline({
  name: "softserve",
  means: "A soft-serve machine: the pointer draws the lever down on the freezing head and the swirl rises into the cone under the nozzle.",
  rules: [1, 3, 5, 8],
  range: [0.4, 0.8, 1],
  tour: [[131, 242], [176, 264], [221, 287], null],
  mount,
});
